INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-30 (M.S.) 30/12/2005', 'mektuplar-30-m-s-30-12-2005-mahzun-doga-1szcf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşlanmaya gidelim. 

Hadi gel.

Çocukluklar yetiştirelim çocukluğumuza.

Safi yerlerimiz sevinsin.

Hadi gel.

Kalışlar ekleyelim gelişlerine.

Uzunca zamanlarda duralım artık.

Safi yeller essin doğumladıklarımıza.

Yaşlanmaya gidelim.

Ölü doğurulmuş gençliğimiz.

Tamımız fazla görülmüş birbirimize.

Başladığımız yerden başlayalım.

Kurusundan ömrümüzün.

Hadi gel.

Yaşlanmaya götürelim yaşsız yerlerimizi.

Kalan dünyamız.

Saysak kısa sürer, 

biliyorsun.

Hesaplasak, zaman almaz.

Yaşasak çağlar geçer ikimizi.

Oysa.

Yaslasak iki ömrü birbirine, 

düşmesi zaman alır, 

biliyorsun.

Düşmesi asırlık savaş.

Biliyoruz.

Yaşlanmaya götürelim safi yerlerimizi.

Şom sesler tıkansın boğazlarına.

Kara kelimelerin yeri olmaz bu cennette.

Yaşlanmaya niyetlemişken yolumuzu.

Sersem sezgilerin yeri yok inanlarımızda.

Götürmeli bizi beyaz hisler.

Karanın izinde niyetimiz yok.

Hadi gel.

Kır boynunu bu gurbetin.

Yaşlanmaya götürelim vuslatlarımızı.

Bir dokunuşluk olsun en çok hasretin.

Teninde ıslanmaya gidelim.

Sesini sür dilime.

Bakışlarından dök gözlerime.

Yaşlanmaya gidelim.

Dizlerini yükle dizlerime.

Hadi koş gel.

Yaşlanmaya gidelim.', 'Yaşlanmaya gidelim.  Hadi gel. Çocukluklar yetiştirelim çocukluğumuza. Safi yerlerimiz sevinsin. Hadi gel. Kalışlar ekleyelim gelişlerine. U...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mektuplar-30-m-s-30-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok seviyorum desem yalan mı olur?', 'cok-seviyorum-desem-yalan-mi-olur-fazil-ozen-i89m9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erişilmez bir hayal mi karşımdaki kişi? 

Öylesine çok seviyorum, anlatamam ki

Her an beklediğim Leylamı bulmuşum sanki

Onu çok seviyorum desem, yalan mı olur? 

Göz göze geldiğimde başka bir alemdeyim

İçim hoş, gönlüm rahat, seher yeli gibiyim

Her haliyle her şeyiyle benim tek emelim

Onu çok seviyorum desem, yalan mı olur? 

Gözlerim yaşla dolu, boynum bükük olsa da

Benden kaçıp gitse de, ellerim boş kalsa da

Ve hatta yalnızlığım, ruhumu karartsa da

Onu çok seviyorum desem, yalan mı olur?', 'Erişilmez bir hayal mi karşımdaki kişi?  Öylesine çok seviyorum, anlatamam ki Her an beklediğim Leylamı bulmuşum sanki Onu çok seviyorum des...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Özen']::text[], 8.5, '{"poet":"Fazıl Özen","poet_slug":"fazil-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-seviyorum-desem-yalan-mi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Masal', 'bitmeyen-masal-sair-unifeb-xzhb3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sonu yazılmamış bir masalın

iki oyuncusuyuz biz

sen masalın güzel perisi 

ben ise yolunu kaybetmiş bir masal yolcusu

dedim ya masal perim

sonu olmayan bir yolda

bilincsiz yürümekteyiz bilinmezlere

ben masalın girişini yazdım

sen ise sonunu yaz bilinmezliğin

ister mutlu bitsin bu masal

ister ayrılıklarla sonuçlansın

tek bildiğim ve tek söyleyebildiğim

masalda olsa SENİ ÇOK SEVDİM..', 'sonu yazılmamış bir masalın iki oyuncusuyuz biz sen masalın güzel perisi  ben ise yolunu kaybetmiş bir masal yolcusu dedim ya masal perim so...', ARRAY['Türk Edebiyatı','Şiir','Şair Unifeb']::text[], 8.5, '{"poet":"Şair Unifeb","poet_slug":"sair-unifeb","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitmeyen-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '& - A n t o l o j i. C o m - &', 'a-n-t-o-l-o-j-i-c-o-m-gulsen-senderin-744su', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A  lfabetik dizinde binlerce şair,  şiir   

N  e de güzel topladın sayfalarına bizi

T  adına doyum olmaz, girildikçe girirlir

O  ku yaz konu işle, yorumla dizi dizi

L  eyla mecnun misali, demlersin  sevgimizi

O  lgun genç eski yeni, tüm şairler burada

J  ale parlaklığında, duygular bir arada

İ  mgelerle temalar, öykü, dize sırada.

C anan sıcaklığında müptela olduk sana

O kudukça okuya, bağlandıkça bağlana

M uhabbet pınarından ilham  katarak cana.', 'A  lfabetik dizinde binlerce şair,  şiir    N  e de güzel topladın sayfalarına bizi T  adına doyum olmaz, girildikçe girirlir O  ku yaz konu...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/a-n-t-o-l-o-j-i-c-o-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel diyordu', 'gel-diyordu-fazil-ozen-brma4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaktı beni sevdan kızgın bir kor gibi

Bahar günü yağan yağmur kadar ılık

Bakınca yüzüne yalvarıyor gibi

Ta derinden bir ses, sanki gel diyordu.

Yağmurlu bir günde ağlıyormuş gibi

Gözlerinde parlayan parıltımı, ışık! 

İçimde uyanan bir ürperti gibi

Ta derinden bir ses, sanki gel diyordu.

Düşlerimde olan leyla yokmuş gibi

Benimle olan tek şey derin bir yalnızlık

Eşini yitirmiş bülbülmüşüm gibi

Ta derinden bir ses, sanki gel diyordu.', 'Yaktı beni sevdan kızgın bir kor gibi Bahar günü yağan yağmur kadar ılık Bakınca yüzüne yalvarıyor gibi Ta derinden bir ses, sanki gel diyor...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Özen']::text[], 8.5, '{"poet":"Fazıl Özen","poet_slug":"fazil-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-diyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ataturke seslenis', 'ataturke-seslenis-ulya-erkman-hn3aj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bize emanet etmistin 

Bu vatani

Damarlarinda ki asil kan 

Demistin

Yete yukseltmege bayragini

Damarlarimizda ki asil kan

Simdi kayniyor Atam

Kurtarmak icin vatani 

Yobazlardan

 Seni dinliyoruz Atam

Yasatacagiz seni yeni bastan

Yasatacagiz butun ilkelerini

Izindeyiz zaten 

Coktan 

Defetmek icin vatan hainlerini

Mucadele zor olacak 

Benzemez asla seninkilere

Ilhamimiz sensin Atam

Kurtaracagiz vatani biz de

    Turk Gencligi

      Izindeyiz', 'Bize emanet etmistin  Bu vatani Damarlarinda ki asil kan  Demistin Yete yukseltmege bayragini Damarlarimizda ki asil kan Simdi kayniyor Atam...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ataturke-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntiharında Gözlerim', 'i-ntiharinda-gozlerim-birsen-ates-513zj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yine sarhoş dizelerim

yalpalıyor gecede

hafifledim biraz gölgemden

kalmasaydım çok geç

gelirdim yağmurlarla

düştüm kuyulara yine

karanlıktayım

intiharında gözlerim

ne dersin

çıkabilir miyim 

gölgelerden

31.12.05', 'yine sarhoş dizelerim yalpalıyor gecede hafifledim biraz gölgemden kalmasaydım çok geç gelirdim yağmurlarla düştüm kuyulara yine karanlıktay...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/intiharinda-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Sevdalarda Yaralanmış Yarınım', 'yanlis-sevdalarda-yaralanmis-yarinim-kamil-aydemir-19rx6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kırık bir dala konmuş serçeyim

hasret kokar sesim

sensiz de sendeyim

dudakların kıvrımına bak belkide ordayım

ya da yalçın dağlarının tepesinde

mutluluğun resmini çizmekteyim

razıyım kelebeğin ömrüne

beni sal yeter gönlüne

zulandaki düşlerini de düşürürsün

yalnızlığın ayazında sen de üşürsün

sokul sevgime

bir yıl daha tükendi

sevgime acılarını uzatarak

erik çiçeği gibi kış ortasında güneşe kanmış

yalancı gülüşlerde yanmış sol yanım

yanlış kapılarda sabahlamış

yanlış sevdalarda yaralanmış yarınım

sensiz de sendeyim

belki de uçurtmayım

gözlerinin göğünde

mutluluğum senin elinde

kalbimde gül mevsimi

seni büyütürüm her gülde

korkuların beni hüzünlere itiyor

bir yıl daha bitiyor

hasretimi katmerleşrirerek

bilir misin gecelerin sinsiliğini

geceler hep yaralarımı deşti

şu sevdalı yüreğime

günler bile uğrayıp geçti

bir kez olsun kapımı çalmadın

yaralı bir güvercin gibi düştüm ayakların altına

eğilip almadın

martıların arkasına aslı kalmam

senden bir şeyler söylesinler diye

        yıldızlara yalvarmam

sensizde sende olmam

her gün beyaz ve kırmızı gülü sensiz de sana vermem

sevdamdandır

sevdam sanki karlı dağlarda topal bir at

tıpkı damlalar gibi hasretin

geceleri içime daha berbat yağar

içimdek okyanuslar

inan ki bir gün beni boğar

her hasret sahibine ağır

ve her hasret sahibinde çoğalır

başkasını nasıl severim senin yerine

hiç bir aşk benzemez diğerine

her sevda sahibinde büyür

her renkte sen varsın

her güzellikte

ve ben sensizde sendeyim

ah yarınım

sen yalancı gülüşlerde yanmışsın

yanlış sevdalarda yaralanmışsın

bana kesme faturayı

bir yıl daha geçti

yüreğime seni sevmenin mutluluğunu bırakarak', 'kırık bir dala konmuş serçeyim hasret kokar sesim sensiz de sendeyim dudakların kıvrımına bak belkide ordayım ya da yalçın dağlarının tepesi...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/yanlis-sevdalarda-yaralanmis-yarinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VEFASIZ ve YOLCULUK', 'vefasiz-ve-yolculuk-serdal-konakci-bv7kk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorum sonu gelmez bir yolculuğa

Sonu gelmez bir sevdaya

Ne desem anlamsız bu dünya

Sevmişim seni ben vefasız

Gel bu yolculukta yoldaş ol bana 

Sonu gelmez bir sevdayla

İlerliyorum bu yalnız yolculukta 

Sensizim işte ben vefasız...

06.01.2004         23:45', 'Gidiyorum sonu gelmez bir yolculuğa Sonu gelmez bir sevdaya Ne desem anlamsız bu dünya Sevmişim seni ben vefasız Gel bu yolculukta yoldaş ol...', ARRAY['Türk Edebiyatı','Şiir','Serdal Konakcı']::text[], 8.5, '{"poet":"Serdal Konakcı","poet_slug":"serdal-konakci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vefasiz-ve-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilebilsen', 'bilebilsen-birsen-ates-5rttv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uçuyorum yine

kanadındayım martının

hiç olmadığım kadar

aşkla doluyum

düşlerimdesin yine

sevdim hayalini sesini 

beynimde sen

yüreğimde sen

ah bir bilebilsen

konuştukça 

renkler çoğalır içimde

bir büyü var

sende

biliyorum

dışarısı çok soğuk

içimi ısıtıyorsun

küçük bir sürpriz yap 

aniden gel

s e v i n d i r beni



31.12.05', 'uçuyorum yine kanadındayım martının hiç olmadığım kadar aşkla doluyum düşlerimdesin yine sevdim hayalini sesini  beynimde sen yüreğimde sen ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilebilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Suçlusu Oldum', 'dusunce-suclusu-oldum-yusuf-ter-vigqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşündüm yazdım çizdim

Karşımda düşman buldum

Düşünüyorum dedim

Düşünce suçlusu oldum

Haksızlığa  baş kaldırdım

Düşmanlarımı yıldırdım

Sanma silahla saldırdım

Düşünce suçlusu oldum

Doğru ilerledim yolda

Yolum bitti karakolda

Aydınlık var kitaplarda

Düşünce suçlusu oldum

Kalemini bırak derler

Yargısız infaz ederler

Belki de alır sürerler

Düşünce suçlusu oldum

Adliye koridorlarında

Başım dik bu yollarda

Vatanım senin uğruna

Düşünce suçlusu oldum

Özgürlüğü  savunduksa

Demokrasi bayrağımsa

Düşünce suçlusuna cezaysa

Düşünce suçlusu oldum

Kafa tasçısı yobazına bak

Linç etmek için insan yak

Utanmazsan madalya tak

Düşünce suçlusu oldum

Aydınlarımız  kol kolla

Karanlıkta bir ışık  ara

Devlet diye savun para

Düşünce suçlusu oldum 

Yusuf’um dar kalıplılar

Adam olmaz bu adamlar

Meydanları boş buldular 

Düşünce suçlusu oldum 

Yusuf Ter  16.12.05

Saat 19:18 İsviçre', 'Düşündüm yazdım çizdim Karşımda düşman buldum Düşünüyorum dedim Düşünce suçlusu oldum Haksızlığa  baş kaldırdım Düşmanlarımı yıldırdım Sanma...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dusunce-suclusu-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-ozan-turk-0g70f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk adımlarının değişinde yere

Kulak kabartıp

Kararlı adımlarına,

Başımı kaldırdım sonra

Yollar siyah ve toz toprak

Adımlarının iyice belirginleşmesine yakın,

Nice yoksul ümit birikmiş gökyüzünde

Baktım hayal meyal beyaz

Baktım

Yanyana örtülüyorlar yola...

Sabah...

Aklanmış yollar adımlarını bekliyor,

Temiz çarşafımız var sabah...

Yürüdük,

Konuştuk, koştuk sonra

Geldin.

Yalnızlıktık birbirimize

Sınır dışı bir kaç adım parladı içimizde

Ötesi bir karanlık...

gittik.

Şimdi geri kaçışlarımızdan

çamurlu bir beyaz...

Ne eskisi gibi sabun kokuyor yastık

Bahçemizden kalma iskelet bir sarmaşık...

Gidiyorsun şimdi...

Yollar yavaş yavaş

Edindi karanlığını

Temizlik vakti diyor havanın kokusu

Sabah diyeceğim sabah! 

Bu aklanmış yollar adımlarını beklerken yine

Asırlar sonra sana

Sabah diyeceğim kal gitme! 

Temiz çarşaflarım var sabah!', 'İlk adımlarının değişinde yere Kulak kabartıp Kararlı adımlarına, Başımı kaldırdım sonra Yollar siyah ve toz toprak Adımlarının iyice belirg...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sabah-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Günler', 'sensiz-gunler-naciye-bildim-nqiyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dar boğaz altında atıyor damarlarım,

Hani nerede diyorum,o büyük yangınlarım.

Şarkılarım,kaybolan şarkılarım

Sensiz gecelerde hep mırıldanırdım.

Kırgınım sevgilim sana kırgınım

Sensiz geçen günlere,çoktan dargınım.

Bitmiyorki dertlerim,dinmiyorki gözyaşlarım

Benimde olsa bir baharım,birde yazım

Gülümseyerek bakabileceğim yarınım.

Ben senelerdir neyi arzularım? 

Neyi özleyipte,neyi ararım? 

Aklım burda sonmuş bunu anlarım.

Sensizlikmi dedin,işte ozaman herşey durur

Zaman seni söylerken,sensizlik gönlümü vurur,

Islanırda mendiller,sanki gözlerimmi kurur.

felek bana hep ağlamayımı buyurur,

Ben ağlarkende,herkezi uyutur

İşim göklere kalmış,inle ey gökler sesimi duyur.', 'Dar boğaz altında atıyor damarlarım, Hani nerede diyorum,o büyük yangınlarım. Şarkılarım,kaybolan şarkılarım Sensiz gecelerde hep mırıldanır...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensiz-gunler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel', 'ecel-sair-ahrazi-07xk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sığarım sanma! Yanıltır seni,cüssen; 

Ecelin perdesi kimmiş,göreceksin; 

Vakit gelmişse eğer,cismini örtsen

Seni ihbar edecektir düşen aksin.

Doğumun sırrına bir bak,hatıran ne? 

İliğin aktığı yerden çıkılan kat,

Seni insan yaptı,hâmîni bir anne.

Hayatın rahmidir,anla,bu kainat! 

 * * *', 'Sığarım sanma! Yanıltır seni,cüssen;  Ecelin perdesi kimmiş,göreceksin;  Vakit gelmişse eğer,cismini örtsen Seni ihbar edecektir düşen aksin...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ecel-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıta', 'kita-naciye-bildim-4806b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlem hcresinde sensizlikle başbaşayım,

Bu kaçıncı sabah mı,akşam mı bilemediğim.

Gözlerimde taze bir tebessüm,yolun başındayım

Ha bitti,ha bitecek bir türlü çözemediğim.

Kıta

Ölüversem diyorum,kimselere söylemeden belli etmeden

O sonsuz uykuyla tanışsam mı diyorum,seni daha görmeden.

Yokluğuna alıştım,dönme nasıl olsa yeniden gideceksin

Sırt üstü kapansam toprağada,birazda sen özlesen.', 'Özlem hcresinde sensizlikle başbaşayım, Bu kaçıncı sabah mı,akşam mı bilemediğim. Gözlerimde taze bir tebessüm,yolun başındayım Ha bitti,ha ...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kita-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamdan Bir Sahne', 'yasamdan-bir-sahne-naciye-bildim-yuv3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamdan bir sahne bu

Kırık kadehlerin sonunu tamamlar hayatım.

her parçası bir yerde,

Ayrı ayrı rollerde.

Gözyaşı,sevinç

Keder,mutluluk

Acısı,tatlısı hep bir arada.

Yaşanacak şeyler yaşanmaz,

Yada yaşanması yasak şeyler yaşanır.

Kimi zaman gülünecek şeylere ağlarız,

Kimi zamanda,ağlanacak yere güleriz.

Bir tek ipsa boynumuzda

Helede ondokuzunda

Küçük avuntularla evleniriz.

YALNIZLIK parmağımızdaki yüzükse,

SEVGİ,boynumuzdaki zincir demekse

Yaşamın,yaşamamaktan farkı ne?', 'Yaşamdan bir sahne bu Kırık kadehlerin sonunu tamamlar hayatım. her parçası bir yerde, Ayrı ayrı rollerde. Gözyaşı,sevinç Keder,mutluluk Acı...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamdan-bir-sahne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlama', 'kutlama-orhan-kutlu-3i7sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asmalımescit''te bit pazarına düşmüş

etiketsiz, bezirganlarca satılır

iki bin beş

ne üstü kalmış ne altı.

eski halini ararda bulamaz

güzelim çınaraltı

gelen gideni aratır derler

göreceğiz

uğurlumu olacak

uğursuz mu iki bin altı

Dileğimiz

Yinede hayırlısı', 'Asmalımescit''te bit pazarına düşmüş etiketsiz, bezirganlarca satılır iki bin beş ne üstü kalmış ne altı. eski halini ararda bulamaz güzelim ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kutlama-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Yüreği!', 'ana-yuregi-nazife-abayli-cdjre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın için ağlarsın,

Üç gün beş gün sonra diner gözyaşların.

..................................................................

Beden bedenden ayrılır,ayrılığına ağlarsın,

Kavuşunca diner gözyaşların..

.....................................................................

Can candan ayrılır,ölümüne ağlarsın,

Bir yıl sonra,iki yıl sonra diner gözyaşların..

........................................................................

Her türlü acıya katlanırsında,

Yüreğinde açılan yarayı zamanla kapatırsında,

Ne,evlat için döktüğün gözyaşların diner,

Ne de  kapanır yaraların.....

......................................................................', 'Aşkın için ağlarsın, Üç gün beş gün sonra diner gözyaşların. .................................................................. Beden bedend...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ana-yuregi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhib''ler Kaptanıyım', 'muhib-ler-kaptaniyim-lokman-hamitoglu-jkod0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'MUHİB’LER KAPTANIYIM

Fırtınalı günlerde deli özlemlerim var

Mutluluğu nakşeden türlü hünerlerim var

Sazım kimi hasreti kimide vuslatı çalar

Mutluluk denizinde muhib’ler kaptanıyım....

Mehtaplı gecelerde zifir vakitlerim var

Fırtınalı sularda uslu martılarım var

Çıldıran poyrazlarda güneş ufkumda doğar

Mutluluk deryasında muhib’ler kaptanıyım....

Şair olmuş yamağım mecnun tayfalarım var

Aşktan aşka desenli Leyla yelkenlerim var

Ferhat dağı delerken şirin bana dert yanar

Mutluluk ummanında muhib’ler kaptanıyım...

Hiç çırak olmamışım ünsa’m aşka koşarken

Hiç bırak dememişim aşk yakamdan tutarken

Beddua etmemişim canan çekip giderken

Mutluluk sularında muhib’ler kaptanıyım...

                      Lokman HAMİTOĞLU', 'MUHİB’LER KAPTANIYIM Fırtınalı günlerde deli özlemlerim var Mutluluğu nakşeden türlü hünerlerim var Sazım kimi hasreti kimide vuslatı çalar ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/muhib-ler-kaptaniyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir''e Sitem', 'i-zmir-e-sitem-sadettin-deren-kw79k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen,İzmir şehri

Sen,beni yardan ayıran kent,

Evvelce ne güzeldi kokun

Ne güzeldi kızların,yaprağın,otun.

Sen,İzmir şehri,

Bu gün seni bir tuhaf buldum,

Bir eksiği var gibi caddelerinin.

Vitrinlerine yalnız bakamıyorum,

Kaldırımlarında tökezliyorum anlasana,

Sen,İzmir şehri

Beni yardan ayıran kent,

Seni sevmiyorum artık,

Seni sevmiyorum.', 'Sen,İzmir şehri Sen,beni yardan ayıran kent, Evvelce ne güzeldi kokun Ne güzeldi kızların,yaprağın,otun. Sen,İzmir şehri, Bu gün seni bir tu...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/izmir-e-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karda Kar Düşünceleri', 'karda-kar-dusunceleri-sadettin-deren-pghpl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kar iniyor şehrime ağır ağır

Bir kar ki düşler şarkılar üstüne

Ellerimi uzatıyorum ıpılık,

Ellerim ateş içindeler

O güzel türküyü söylüyorum yine ağlayık.

Kar iniyor işte şehrime ama hızlı

Cümle kuşlarda kaderimi seyrediyorum,

Bir el uzanmış tanrı aklığınca yeryüzüne,

Bir el uzanmış yücelerden.

Öpüyorum,bir daha öpüyorum,hep öpüyorum…

Kar iniyor şehrime lapa lapa,

Aklımda hep o bilmece,bildiğin.

Düşünüyorum bunca kirimizi pasımızı

Örtüveren cömertçe,birdenbire,

Bu apak düşünce kimin? 

Kar indi şehrime gördünüz

İşte buyrun gelin kar helvasına

Gelin koca ayaklarınızla basın,

Bu ulu ve bakire aklığıma,

Eskiden olduğu gibi yüreğimi parçalayın.

Karı eridi şehrimin artık,

Bütün caddeler sizin,gezin dolaşın.

Kaybolan aklığı arıyor ellerim.

Ellerim buz gibi,kanı çekilmiş,bembeyaz.

O türkü dudaklarımda,içli,derin.', 'Kar iniyor şehrime ağır ağır Bir kar ki düşler şarkılar üstüne Ellerimi uzatıyorum ıpılık, Ellerim ateş içindeler O güzel türküyü söylüyorum...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karda-kar-dusunceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-sadettin-deren-m3v9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen daha yepyeni

El değmemiş,gün görmemiş,

Sen daha

Bir aylık ya var ya yoksun.

Hoş geldin benim şiirim,

Günaydın mutlu sabahlara açılan geleceğim

Sen havam,suyum,ekmeğim

İyiye ve güzele ağrıyan tek sızım

Benim son şiirim

Sen benim ilk kızım.

Bu anandır yavrum

Ak sütü oluk oluk dudaklarında,

Sevgilerin en çoğuyla yanan.

İşte şunlar evlerimiz,yollarımız,

Şunlar insan kardeşlerin türlü türlü,

Bir de dünyamız var iyi kötü,

Sen de geldin aramıza ne iyi ettin,

Hoş geldin yavrum,hoş geldin.

Öyle güzel şeyler var ki öğreneceğin,

Örneğin yeşiller,allar,morlar

İnsan yürekleri,gizemin altın anahtarı,

SEVİ olsun ilk öğreneceğin istiyorum,

Adını SEVİ koyuyorum usulcana.

Sen daha yepyeni

El değmemiş,gün görmemiş,

Sen daha

Bir aylık ya var ya yoksun.', 'Sen daha yepyeni El değmemiş,gün görmemiş, Sen daha Bir aylık ya var ya yoksun. Hoş geldin benim şiirim, Günaydın mutlu sabahlara açılan gel...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kizima-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbet', 'nobet-sadettin-deren-0yvlt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Omzumda silâh, süngü takmışım

Ben sizler için ayaktayım.

Siz rahat döşeklerde uyuyun,

Benim için de güzel düşlere yatın,

Kara tasalardan uzak.

Yüreklerinize hiç korku girmesin,

Bıraktığım gibi güleç,iyimser,

Bıraktığım gibi elleriniz Tanrıya uzanmış,

Yitirdiğiniz sevdaları arayın yine,

Benim için de arayın.

Siz örneğin berberseniz çok konuşun,

Şık şık şık …makasınız işlesin,

Eğer fırıncıysanız bildiğim gibi,

Mis kokulu ekmeğinizi kardeşlerime dağıtın.

Kadınsanız,erkekseniz,

Yeni urbalarınızı giyin hep,

Ayakkabılarınızı benim için de boyatın,

Benim için de dolaşın caddeleri.

Omzumda silâh,süngü takmışım,

Ben sizler için ayaktayım.', 'Omzumda silâh, süngü takmışım Ben sizler için ayaktayım. Siz rahat döşeklerde uyuyun, Benim için de güzel düşlere yatın, Kara tasalardan uza...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nobet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geliyorum', 'sana-geliyorum-sadettin-deren-hr018', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilsem çalmazdım kapını inan

Sevda bir yaraymış kanayan

Şimdi bir selim coşmuş akan

Sana geliyorum,sana geliyorum.

Hayat kumardır derler hep kaybettim

Neyim var neyim yoksa hepsini verdim

Başımı alıp gideyim derken seni sevdim

Sana geliyorum,sana geliyorum.

Sana gelen yolları bir bir kesseler

Bir ateş çölünden geçeceksin deseler

Tutup alnıma sekiz el ateş etseler

Sana geliyorum,sana geliyorum.

Sarı siyah yeşil turuncu

Kader falım sende durdu

Biliyorsun abbas yolcu

Sana geliyorum,sana geliyorum.', 'Bilsem çalmazdım kapını inan Sevda bir yaraymış kanayan Şimdi bir selim coşmuş akan Sana geliyorum,sana geliyorum. Hayat kumardır derler hep...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-geliyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Yollar', 'sarhos-yollar-sadettin-deren-ct9bn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu yol İzmir’e gider,

Bu Ankara’ya.

Sen nerdesin söyle,

Benim yolum nerde.', 'Bu yol İzmir’e gider, Bu Ankara’ya. Sen nerdesin söyle, Benim yolum nerde....', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarhos-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıl Taşları', 'cakil-taslari-yavuz-bayram-caliskan-iq9qx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamansız mevsimlerde bastırdı sisler,

Bir hüznü baharına aldı yanlış günler,

Kaprisli gülücüklerin ürpertisi yalnızlığım,

Sığırcıkların baharını arıyorum.

Geleceğimi bilmek ister miyim? 

Zaman yırtılıyor, hatıralar en başa geçiyor,

Sisler içinde sadece kuşları duyuyorum,

Eskimiş şehirlerde yitik gençliğimi soluyorum,

Yaralayıcı hoyratlık kabalığını yapıyor,

Taş kemerli köprülerden akıp giden sular,

Karanlık sular değil beni ürperten,

Silemediğim geçmişim ve korkunç çaresizliğim,

İçimde sakladığım ışık zaman içinde sükunete akıp gidiyor,

Sevdiğimin boşluğu karanlıklara karışıyor,

Ayağıma batan çakıl taşları, ben öksüz sayılmam.

Sessiz ve sisli yıllar bir siz eksiktiniz,

Ne yana dönsem dalgalar gibi çarpıyorlar,

Yaralanıyorum, yaralanıyoruz, gökyüzü karanlık,

Ay matemini unutmak mümkün mü? 

Tek sığınağım ayağıma batan çakıl taşları,

Ne acıklı değil mi? Ben öksüz sayılmam.', 'Zamansız mevsimlerde bastırdı sisler, Bir hüznü baharına aldı yanlış günler, Kaprisli gülücüklerin ürpertisi yalnızlığım, Sığırcıkların baha...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cakil-taslari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-sadettin-deren-giiur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutsuz değilim güzelim

Beni anlıyor musun? 

“BELKİ” diyorum.

Böyle ağrılı sabahlara uyanıyorsam

Her tren çığlığında uzuyorsa tedirginliğim

Sakın yüreğimi ezilmiş sanma,

Bahar dallarında her gün yeniden uyanıyorum,

Sana yürüyor damarlarımdaki özsu.

Umutsuz değilim güzelim

Beni anlıyor musun? 

“BELKİ” diyorum.

Rüyalarımda hep seninle sevişiyorum

Yine seninle,anlıyorsun değil mi? 

Kirli bulutlar içimdeki denizleri taşırdı taşıracak,

Neresinden tutsam seni getiriyor yaşamak,

Hayat seninle güzel,gözyaşları seninle anlamlı,

Ellerin olmasa gerçek uçup gidiverecek sanki.

Umutsuz değilim güzelim

Beni anlıyor musun? 

“BELKİ” diyorum.', 'Umutsuz değilim güzelim Beni anlıyor musun?  “BELKİ” diyorum. Böyle ağrılı sabahlara uyanıyorsam Her tren çığlığında uzuyorsa tedirginliğim ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar Yangını 1', 'yalnizlar-yangini-1-sadettin-deren-vxbut', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En temiz yerinde sevda pınarının

En güzel yerinde çekip gittin,

Uluyan yalnızlığımla ben

Seni bekliyoruz.

Kapkara rüzgârlarını dinliyorum içerimde

Bulup bulup kaybettiğim gözlerinin.

Bilyorum yoldasın; geleceksin,

Hiç gelme dur,istemiyorum.

N’oldu o eski çocuk gülmelerimize,

Nerde gözyaşlarımızda birikmiş kahkahalar,

Uzaklardan sesleniyorum; duyuyor musun? 

Hiç duyma dur,istemiyorum.

Biliyorum şimdi kadınsı düşlerinde sen

En güzel yanımla beni seviyorsun.

Bütün kabalığımla,erkekliğimle beni; biliyorum,

Hiç sevme dur,istemiyorum.

Yüreğimde hep o sızı biliyorsun,

Gözlerimde ağlayan şarkılar

Mendilini çıkardın sanki; görüyorum,

Hiç silme gözyaşlarımı dur,istemiyorum.

En temiz yerinde sevda pınarının

En güzel yerinde çekip gittin.

Uluyan yalnızlığımla ben

Seni bekliyoruz.', 'En temiz yerinde sevda pınarının En güzel yerinde çekip gittin, Uluyan yalnızlığımla ben Seni bekliyoruz. Kapkara rüzgârlarını dinliyorum iç...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizlar-yangini-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar Yangını 2', 'yalnizlar-yangini-2-sadettin-deren-awzdt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine baykuşlar ötüyor akşamın alaca saçlarında

Ben seni bekliyorum gönlümce,sabırsız.

Geleceksin biliyorum,er-geç geleceksin,

Seni beklemek gelmenden güzel ve ulu,

Bekliyorum,bekleyeceğim.

Varsın beni deli sansın görenler

Gülüp geçsinler gözlerimdeki deli rüzgâra

Ayak seslerini duyacağım birazdan,

Şimdi o güzel gülüşünle çıkıp geleceksin,

Bekliyorum,bekleyeceğim.

Bu,sokak ortalarında beklemeler,

Ve kırık aynalardan sızan ışıktır beni yaşatan,

Gözlerinde en güzel rengi sevdanın,

Herhalde köşeyi dönüyorsundur diyorum,

Bekliyorum,bekleyeceğim.

Saatler ilerlesin,uçsun varsın,

Bütün ışıkları sönsün evlerin.

Ceylanım,en güzel umudum benim,

Çoğa varmaz gelirsin ürkekliğinle,

Bekliyorum,bekleyeceğim.

Yine baykuşlar ötüyor akşamın ağaran saçlarında

Ben seni bekliyorum gönlümce mahzun,

Geleceksin biliyorum,er-geç geleceksin,

Seni beklemek,gelmenden güzel ve ulu,

Bekliyorum,bekleyeceğim.', 'Yine baykuşlar ötüyor akşamın alaca saçlarında Ben seni bekliyorum gönlümce,sabırsız. Geleceksin biliyorum,er-geç geleceksin, Seni beklemek ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizlar-yangini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Limanı', 'gonul-limani-celal-topo-0bqph', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gemiler kalkacak bir gün

Bu gönül limanından kadınım

Gemiler ki; 

Karşılıksız sevgileri taşıyacak

Mendiller sallanacak ayrılıktan yana

Benim mendilim hüzünlü

Benim mendilim yaşlı olacak...

Senin mendilin beyaz

Senin mendilin kupkuru

Gözlerinse hafiften yeşile çalacak

Bir iskelede yalnız kalacağım

Aramızda koca koca dalgalar

İnsafsızca mesafeler

Bir ucunda sen bir ucunda ben

Günlerim yıllara bedel olacak kadınım

Gel de

Bekle bekleye bilirsen...

30 / 12 / 2005  Antalya', 'Gemiler kalkacak bir gün Bu gönül limanından kadınım Gemiler ki;  Karşılıksız sevgileri taşıyacak Mendiller sallanacak ayrılıktan yana Benim...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonul-limani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-sadettin-deren-36si2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah erkenden fabrika yollarında,

Soğuk sessizlikler büyüyor yüreğimde.

Bir yanım mosmor el ülkesinde hor görülmekten,

Bir yanım sizi arıyor garipsi türkülerde.

Fırından yeni çıkmış susamlı bayram ekmeklerinde,

Yurdumun kokusu burnumda tütüyor,

En çok…

Beni unutan dostlarım,ahbaplarım geçiyor,

Sabahçı kahveleri geçiyor gözümün önünden.

Simit satan küçük okul çocuklarını duyuyorum,

Ülkemin aydınları rahat döşeklerde uyurken.

Çift katlı otobüsleri beklerken duraklarda,

Yolsuz köylerim deli ediyor beni

En çok…

Kocaman gözler bıraktım geldim ardımda,

Sevgiyle pırıl pırıl yanan.

Bunca insan içinden sen ol istiyorum,

Yalnız sen ol beni arayan.

Esmer rüyalarda hep seni özlüyorum,

Seni söylüyorum,seni yazıyorum

En çok…', 'Her sabah erkenden fabrika yollarında, Soğuk sessizlikler büyüyor yüreğimde. Bir yanım mosmor el ülkesinde hor görülmekten, Bir yanım sizi a...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yara-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Devleti', 'ask-devleti-sadettin-deren-okymi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En büyük savaşı bu benim aşk devletimin

Meydanlarda senin askerlerin,tankların

Bütün güzelliğin,iyiliğin,sevginle meydan okuyorsun,

Çaresiz savaşacağız,yenilmeyi göze almışız.

Artık ölmek falan vız geliyor anlıyor musun? 

Bir aşk şarapneli götürmüş gözlerimi nasıl olsa,

Görüyorsun yüreğim paramparça yerlerde,

İstersen daha zorla kalelerimi,üzerime yürü…

İstersen daha zorla kalelerimi,üzerime yürü…

Belki son savaşım olacak ama ilk değil biliyorsun,

İşte en cengâver yiğitlerim,dörtnala atlarım,

Kolla kendini geliyoruz,haberin olsun,

Ya çekil aşk devletimin kapılarından

Ya gel gör nasıl susamışım mert bir savaşa.

Bütün damarlarım sana yürüyor dolu dizgin,

Benim sabrımı taşırma,vakit varken çek askerlerini topraklarımdan.

Benim sabrımı taşırma,vakit varken çek askerlerini topraklarımdan.

Bu savaş yürür giderse ikimiz de ezileceğiz kumandan,

Kim saracak yaralarımızı,kim silecek gözyaşlarımızı,

Uzat ellerini çaresizliğimin karanlığına uzat,

Al yüreğimi barış şarkılarıyla yıka

Ne sen beni öldürebilirsin,ne ben seni aslında,

Yenmek,yenilmek hüner değil zaten savaşlarda

En iyisi teslim olmak birbirimize sevda bayraklarında.', 'En büyük savaşı bu benim aşk devletimin Meydanlarda senin askerlerin,tankların Bütün güzelliğin,iyiliğin,sevginle meydan okuyorsun, Çaresiz ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-devleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksu', 'cocuksu-sadettin-deren-xp9d4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şeyi unutabilsem

Bütün dertleri,bütün sevdaları; 

Yeniden dönebilsem gerilere,

Çocuksu adımlarımla korkusuz,

Binebilsem kargıdan atıma.

Tutabilsem ellerinden arkadaşlarımın,

Mantar tabancamı patlatabilsem şenliklerde,

Yedi başlı devi yine seyredebilsem,

Peri kızlarının sıcaklığı yine beni sarsa,

Ah ne olur…

Her şeyi unutabilsem,

Yeniden dönebilsem gerilere…', 'Her şeyi unutabilsem Bütün dertleri,bütün sevdaları;  Yeniden dönebilsem gerilere, Çocuksu adımlarımla korkusuz, Binebilsem kargıdan atıma. ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuksu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy', 'duy-sadettin-deren-0bd72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle yukardan bakıp altındakilere,

Hor görüp diri-diri yutma.

Yatırıp yerden yere vurduklarına,

Bir gün muhtaç olacaksın unutma.

Kendine gel be hey sersem,

En üstte olmak önemli değil.

Gün gelir fırtınalar yürür üstüne,

Hep yukarı olmaz,biraz da eğil.

Üstteysen de alttaysan da sarıl,

Sarıl.sarılmak yaşamaktır inan.

Hiç üstte olur muydun acaba,

Olmasaydı sana alttan dayanan?', 'Öyle yukardan bakıp altındakilere, Hor görüp diri-diri yutma. Yatırıp yerden yere vurduklarına, Bir gün muhtaç olacaksın unutma. Kendine gel...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duy-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-sadettin-deren-3jwry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat dört sevgilim,

İzmir’in kahveleri bomboş,

Olgun başaklar kadar aziz

Bir sarı koku dolaşıyor etrafımda

Senin de bildiğin gibi

Seninleyim.

İşlerim bitmemiş varsın olsun

Anahtar sesini dinle,

Geliyorum.', 'Saat dört sevgilim, İzmir’in kahveleri bomboş, Olgun başaklar kadar aziz Bir sarı koku dolaşıyor etrafımda Senin de bildiğin gibi Seninleyim...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geliyorum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene Yakarı', 'gidene-yakari-sadettin-deren-0zej6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Heeyy…

Dur öyle koşup gitme,

Ben seni damarlarımda gezdirdim yıllarca,

Kanıma şerbet yaptım seni ben,

O nasıl gitmek öyle..

Nasıl yapayalnız bırakmak beni,

Heey dur biraz,

Dur benim deli-bozuk gençliğim.

Heeyy…heeyy…

Buraya bak,

Bunca kırdığımız cevizlere n’oldu,

N’oldu o korkusuz günlerimize.

O kahve köşeleri,

Bir vuruşta tuz-buz ettiğimiz şişeler,

Hani gitmez gibi görünen yüzün,

Hani…hani…

Heeyyy…

Buraya bak gençliğim,

O nasıl selâmsız-sabahsız gitmek,

Nasıl koşup-gitmek öyle,

Heeeyyy,heeeyyy…', 'Heeyy… Dur öyle koşup gitme, Ben seni damarlarımda gezdirdim yıllarca, Kanıma şerbet yaptım seni ben, O nasıl gitmek öyle.. Nasıl yapayalnız...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidene-yakari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstesem de İstemesem de', 'i-stesem-de-i-stemesem-de-sadettin-deren-jwqb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O simsiyah acılığı yine üstünde mi saçlarının? 

Kim bilir hangi rüzgârın elinde sereserpe,

Darmadağın,perişan,kırık ve güzel.

Artık soluğu yitmiş bir sonbahara girmişsindir,

Bilmem kaçıncı yüzyıldan beri saçların ellerimde,

Saçlarını düşünüyorum istesem de,istemesem de…

Belki elimi tutuyorsun ta… uzaklardan usulca,

Bilmem o taze erik çiçeği ellerin şimdi nerde? 

Sanki hemen koşup kapımı çalıverecek,

Sanki bilinmeyen ağrıların o zehir ikliminde,

Belki seni senden çalan birinde.

Ellerini düşünüyorum istesem de istemesem de…

Karanlık sokaklarda gözlerin hep yanımda inan,

Engin şarkılara ıpıslak oturmuş işte.

Aşka gülen…bana gülen…bana gülen…bana gülen…

Gözlerin olmasaydı sarhoş olmazdım biliyor musun? 

Her karanfilde bana koşan taptaze,

Gözlerini düşünüyorum istesem de,istemesem de? 

En olmadık türkülerde sana merhaba diyorum.

Şiir demiyorum artık seni söylemeyen şiire,

İpek böceklerinde duyuyorum sıcaklığını,

Seni yaşıyorum acı gitar çığlıklarında…

Ne kadar uzaklarda olsan,o kadar dizlerimin dibinde…

Seni düşünüyorum istesem de,istemesem de…', 'O simsiyah acılığı yine üstünde mi saçlarının?  Kim bilir hangi rüzgârın elinde sereserpe, Darmadağın,perişan,kırık ve güzel. Artık soluğu y...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istesem-de-istemesem-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Duyu', 'kara-duyu-sadettin-deren-94trm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben körüm işte

Senin gördüğünü göremem.

Ağaçlar,insanlar,evler

Sabahlar nasıl olur,gün nasıl biter

Ben daha hiç görmedim.

Acılı günleri sen sevmezsin,

Kör gözlerinde çirkin insanlar

İnan bana dostum,

Ne kadar güzeldir sen bilmezsin.

Ben sağırım işte

Senin duyduğunu duyamam.

Mermer dudaklar ülkesinin sırrı bu; 

Bir çocuk sesini,bir yaprak hışırtısını

Ben daha hiç duymadım.

Nasıldır kim bilir rengi bir sesin

Susuk ağızlardan bir kelime,

Bir tek ses duymak mi minörden

Ne kadar güzeldir sen bilmezsin,

Ben ölüyüm işte

Beni mermerlere gömülü sanıyorsunuz.

Yaşamak nedir,onu ben bilirim,

Ben bilirim  davul sesinin rengini,

Ne kadar güzeldir yaşamak sen bilmezsin.', 'Ben körüm işte Senin gördüğünü göremem. Ağaçlar,insanlar,evler Sabahlar nasıl olur,gün nasıl biter Ben daha hiç görmedim. Acılı günleri sen ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kara-duyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa', 'kisa-sadettin-deren-kjuj4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al şu beni benden

Sök al yüreğimi

Sök al yerinden

Olsun bitsin.', 'Al şu beni benden Sök al yüreğimi Sök al yerinden Olsun bitsin....', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kisa-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YirmiAltıncıBahar', 'yirmialtincibahar-yilmaz-helimergin-ltqqs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düş ve ayaz rengi fîgan kentini sardı,

Nice bilge sagunlar ziyâna merhem çaldı.

Çeri saçan eyvahlar meydanı kuşatırken; 

Virane hazanıma gül dolu bahar yağdı.

Şimâl yıldızı güldü artık hilâl sönmüyor,

Kutlu sesler haykırıp isyâna red çekiyor.

Masmavi boyanıyor onulmaz vaktin rengi,

Umutlar gün sayıyor hicrân sevda doluyor.

 	31.12.2005 08:53:00', 'Bir düş ve ayaz rengi fîgan kentini sardı, Nice bilge sagunlar ziyâna merhem çaldı. Çeri saçan eyvahlar meydanı kuşatırken;  Virane hazanıma...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Helimergin']::text[], 8.5, '{"poet":"Yılmaz Helimergin","poet_slug":"yilmaz-helimergin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yirmialtincibahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Gün', 'mutlu-gun-sadettin-deren-vpg1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mektup  aldım dostlar yetişin

Bir sümbüllü mektup aldım,

Çabuk bana kalemi-kağıdı verin.

Yardan mı kopmuş desem

Candan mı,

Bir zarf bir pul,yüreğimi tutup göndersem.', 'Bir mektup  aldım dostlar yetişin Bir sümbüllü mektup aldım, Çabuk bana kalemi-kağıdı verin. Yardan mı kopmuş desem Candan mı, Bir zarf bir ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mutlu-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenin Yakarısı', 'ogretmenin-yakarisi-sadettin-deren-1yv1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüce aydınlığında tertemiz ellerimiz

Sana yalvarıyoruz Tanrım; 

Işık verdiğin bu ufacık yüzleri kirletme

Bu elleri hep böyle temiz tut,

Tebeşirlerle büyüyen aklığı koru,

Çocuklarımızı iyi rüyalarla uyut.

Bilirsin neden yaşadığımızı,

Türkümüz neden bu kadar güzeldir bilirsin.

-Bir demet papatya,bir deste gül-

Üzerlerine serp iyilik tohumlarını,

Varsın yavrularımız saadetten delirsin.

Yüce aydınlığında tertemiz ellerimiz 

Sana yalvarıyoruz Tanrım.', 'Yüce aydınlığında tertemiz ellerimiz Sana yalvarıyoruz Tanrım;  Işık verdiğin bu ufacık yüzleri kirletme Bu elleri hep böyle temiz tut, Tebe...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ogretmenin-yakarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazdığım Şiirler Bitmedi', 'sana-yazdigim-siirler-bitmedi-sadettin-deren-k38y2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahlar hep aynı

Yarılanmış bardaklar var önümde

Bunu sana uzaklardan yazıyorum

Bunu sana yanıbaşından.

Sen benim gözbebeğim

İçerimdeki derin sızı,

Bilmem hâla öyle misin? 

Hâla ağlayık-küskün? 

Aramızda dağlar,kentler,

Ne kadar da uzaksın

Uzak...ve güzel...

Sen benim gözbebeğim,

İçerimdeki derin sızı.

Sabahlar hep aynı

Bir mavi alev büyüyor yüreğimde,

Sen çok uzaklarda,

Sen dizlerimin dibinde.', 'Sabahlar hep aynı Yarılanmış bardaklar var önümde Bunu sana uzaklardan yazıyorum Bunu sana yanıbaşından. Sen benim gözbebeğim İçerimdeki der...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-yazdigim-siirler-bitmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sadettin-deren-eqq0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanki yeniden doğuyorum her sabah gözlerinde

En insancıl güzellikleri öğreniyorum sende

Ha varmışsın,ha yokmuşsun değişmiyor

Senden söz etmeyen bir şey yok ki bende.

Ömrümün en güzel savaşını sende veriyorum

Ne yana yönelsem hep sana geliyorum

Çaresizlikler,işkenceler vız geliyor artık

Her gün seninle yanıyor,seninle sönüyorum.

Sensiz körüm,sağırım,çirkinim,

Bütün tasaların sahibi benim,

Gözlerini çoğaltıp tespih yapıyorum dualarıma,

Artık gelsen diyorum tatlı karanfilim.

Yedinci asırdan beri seni arıyorum,gelsene

Söylüyor sazım en güzel telinden,dinlesene

Bir senin sesin var beni mutluluğa çağıran

Karanlığın en zifirinde boğulmuşum,sevsene', 'Sanki yeniden doğuyorum her sabah gözlerinde En insancıl güzellikleri öğreniyorum sende Ha varmışsın,ha yokmuşsun değişmiyor Senden söz etme...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-721-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Şarkısı', 'yalnizlik-sarkisi-sadettin-deren-126ys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca yalnızlığımı bilsen

Yarın kapkara yollara çıkacağımı

Kalır mıydın? 

Ağır ağır inen bulutlar gibi yalnızlık

Bu otobüs,bu tren,bu...

Bu,yollarda kayıp giden acı karanlık

Kudurmuş canavarlar gibi geldi- durdu

Beni deli eden bu başbelası şey

Bir tutam sarı saçta yüreğime oturdu

Bunca yalnızlığımı bilsen

Yarın kapkara yollara çıkacağımı

Kalır mıydın?', 'Bunca yalnızlığımı bilsen Yarın kapkara yollara çıkacağımı Kalır mıydın?  Ağır ağır inen bulutlar gibi yalnızlık Bu otobüs,bu tren,bu... Bu,...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-sarkisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Cennet', 'yasak-cennet-sadettin-deren-vosff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fabrikaların harıl harıl,imreniyorum bazen Berlin,

Bunca karanlığı,aydınlığa değişiyorsun.

Ihlamurlar hep iyi çiçeklere yürüyor,

Bacalarından çıkan dumanı benimsemek geliyor içimden,

Şaşırmış,garipleşmiş kardeşlerim OLMASA.

İnsanlarını seviyorum,kendi hallerinde,çalışkan,

Günaydın diyor her gün ışıl ışıl yüzleri,

Oyunlar oynuyorum,çocuklara şarkılar öğretiyorum,

Sevecek gibiyim sanki maskaraları,

Yurdumda mahzun yüzlü yavrular OLMASA.

Pır pır ediyor yüreğimde beyaz güvercinlerin,

Güzel kadınların var Berlin anladık,

Bütün acılar çekilecek gibi geliyor,

Sanki karışıverecekmişim şu kalabalığa,

Sevdiğimin gözleri çakmak çakmak OLMASA.', 'Fabrikaların harıl harıl,imreniyorum bazen Berlin, Bunca karanlığı,aydınlığa değişiyorsun. Ihlamurlar hep iyi çiçeklere yürüyor, Bacalarında...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasak-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak ateşi', 'yak-atesi-hulya-serdar-s5ody', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anlamsızlığın yaşattıklarına bak

gözlerimde yitirdim seni

tek suçlusu benim değil mi? 

şimdi yak elindeki ateşi 

söndürmeden, rüzgara kaptırmadan

damarlarımdaki tüm kan

dolaşıyor beynimde sanki

yumruklarım duvarlarda kan izi

hazmedemiyorum seni

sensizliği değil ama

tek suçlusu benim değil mi? 

şimdi yak elindeki ateşi

söndürmeden yakmadan bedenini 

bunca yaşanmışlığın içinde

ruhumu kirletiyorum

unutmak adına seni

ve tek suçlusu benim değil mi', 'anlamsızlığın yaşattıklarına bak gözlerimde yitirdim seni tek suçlusu benim değil mi?  şimdi yak elindeki ateşi  söndürmeden, rüzgara kaptır...', ARRAY['Türk Edebiyatı','Şiir','Hülya Serdar']::text[], 8.5, '{"poet":"Hülya Serdar","poet_slug":"hulya-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yak-atesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk haz katar güzel olan ruhundaki güzelliklere', 'ask-haz-katar-guzel-olan-ruhundaki-guzelliklere-halil-colak-drbvp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hülyalı bakışların bir ok gibide  batarda sinelere

Ümit ve neşe dolar ruhumun sonsuz derinliklerıne

Lafla izah edilmez bir hüzün var buğulu gözlerinde 

Yaşama zevki verir hayranım gül olan gülüşlere

Aşk haz  katar güzel olan ruhundaki  güzelliklere 

Halil Çolak 31.12.2005 Ankara', 'Hülyalı bakışların bir ok gibide  batarda sinelere Ümit ve neşe dolar ruhumun sonsuz derinliklerıne Lafla izah edilmez bir hüzün var buğulu ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-haz-katar-guzel-olan-ruhundaki-guzelliklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü örnek oluyorsun bil bunu', 'kotu-ornek-oluyorsun-bil-bunu-mikdat-bal-erl0s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynaya bak kendini gör ukala

Kötü örnek oluyorsun bil bunu

İlim öğren medeniyet yakala

Kötü örnek oluyorsun bil bunu

Bütün bildiklerin kulaktan duyma

Gençlere anlatıp onlara kıyma

Bilmiyorum söyle, nefsine uyma

Kötü örnek oluyorsun bil bunu 

Bilmediğin şeye cevap verme sen

Bilmem söylemeyi ayıp görme sen

Kılığınla beyinlere grime sen

Kötü örnek oluyorsun bil bunu 

Okuduğun ya dergi ya gazette

Alim oldun satıyorsun bize de

Uzatırsın hiç kaçmadan özete

Kötü örnek oluyorsun bil bunu 

Beğenmezsin profesörü alimi

Cahillere satıyorsun çalımı

Bu tavırlar müslümanın hali mi

Kötü örnek oluyorsun bil bunu 

Mikdat der bu tipler karşıma çıkar

Konuşur konuşur canımı sıkar

Yarım hoca işte böyle din yıkar

Kötü örnek oluyorsun bil bunu', 'Aynaya bak kendini gör ukala Kötü örnek oluyorsun bil bunu İlim öğren medeniyet yakala Kötü örnek oluyorsun bil bunu Bütün bildiklerin kulak...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kotu-ornek-oluyorsun-bil-bunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al/evimdeyim', 'al-evimdeyim-orkun-isik-o5eik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Al/evim sem/ahtadır, cemrem biter kar anlık

Pervaneyi döndürdüm, kar yanar hece hece

Bal gülüm kem/ahtadır, vuslat yolu karanlık

Işıkları söndürdüm, seni yaktım bu gece…

Yangındır nefeslerim dönmüyor baharlara 

Yolcu/sudur bedenim koşuşuyor harlara 

Bir sor/sana h/Ali''mi  kitaplara darlara

Elif denen kapıda kale/Mim''dir bu gece…', 'Al/evim sem/ahtadır, cemrem biter kar anlık Pervaneyi döndürdüm, kar yanar hece hece Bal gülüm kem/ahtadır, vuslat yolu karanlık Işıkları sö...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/al-evimdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldu Gözlerim', 'vuruldu-gozlerim-mehmet-sait-akkus-lfn27', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gidişlerin bende bıraktığı

Ufak ufak içerimi yaktığı

Bir güneş gibi içime aktığı

Sevdalarına vuruldu gözlerim

Cemalindeki güzellik olmassa

Görününce bedenimi yakmassa

Yarım kalan şu aklımı almassa

Cemaline vuruldu gözlerim

Yetmiyormu bana bunca yaptığın

Aklımda kalanları dağıttığın

Başımdaki saçları ağarttığın

Umutlarına vuruldu gözlerim', 'Bu gidişlerin bende bıraktığı Ufak ufak içerimi yaktığı Bir güneş gibi içime aktığı Sevdalarına vuruldu gözlerim Cemalindeki güzellik olmass...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vuruldu-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Güzelliğin', 'o-guzelligin-mehmet-sait-akkus-j0tb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman yüzünü görsem

Elinden badeyi içsem

Sana iki laf söylesem

Sanki dilim tutuluyor

Oturup bakmak isterim

Bu canı yakmak isterim

Aniden akmak isterim

Sanki bedeb tutuluyor

Sanki dünyalar güzeli

Sana taparken ezeli

Senin gibi bir hazalı

Vururken tutuluyorum', 'Ne zaman yüzünü görsem Elinden badeyi içsem Sana iki laf söylesem Sanki dilim tutuluyor Oturup bakmak isterim Bu canı yakmak isterim Aniden ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-guzelligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buyrun noel sofrasına', 'buyrun-noel-sofrasina-nazan-i-zmirli-wcag2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '........boynu kırık..........

kolu bacağı bir yanda

...........hindi..................

sarmalanmış   soslara

porselen   tabaklarda,

boğuluyor    yaşları.

caka  satmaktı   oysa

kabaran    kanatlarda

amacı! ! ! 

birer  kör   bıçak   elde

kanayan    yüreğinde.

bir  parça da  sen  kap

hakkın    geçmesin 

ya da

bir  tutam  canım,

aklın  kalmasın

............afiye olsun................

............... dostlar...............

.............bir kadeh...............

...............kırmızı....................

...............şarap...................

.................iyi.......................

...............gider.....................

.............üzerine...................

..............buyrun................... 

........dostlar buyurun..........

halil ibrahim sofralarını.......

...........unutturan..................

...............noel..................

...........hindilerine..............

sohbetiniz bol,afiyetiniz şeker olsun......

31.12.2005-antalya', '........boynu kırık.......... kolu bacağı bir yanda ...........hindi.................. sarmalanmış   soslara porselen   tabaklarda, boğuluyo...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/buyrun-noel-sofrasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep kızı', 'zeynep-kizi-fahrettin-selcik-zazhr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Z E Y N E P   K I Z I

Z E Y N E P   K I Z I

Türkiye Bursa nere,Kanada Montreal nere

Kader yazdıktan sonra olur  elbette,

Soğuk ülkenin sıcak şehri Montreal,

Sana etmeyeceğiz hakkımızı helal,

İsmail kaptın en güzel kızımızı,

İçimize oturdu  hasret ve sızı,

Biliyorsun ki Firdevs in en büyük kızı,

 O ki Şentürk ve kahvecioğularının yıldızı.

Firdevs düşünmesin de neylesin,

Damat geldi ikinci evlat,teselli olsun,

Genç evlileri Allah mesut etsin,

Kuralı Mevlam koymuş,kim neylesin.

Fahrettin Selçik   31-12-2005

İsmail kaptın en güzel kızımızı,

İçimize oturdu  hasret ve sızı,

Biliyorsun ki Firdevs in en büyük kızı,

 O ki Şentürk ve kahvecioğularının yıldızı.

Firdevs düşünmesin de neylesin,

Damat geldi ikinci evlat,teselli olsun,

Genç evlileri Allah mesut etsin,

Kuralı Mevlam koymuş,kim neylesin.

Fahrettin Selçik   31-12-2005', 'Z E Y N E P   K I Z I Z E Y N E P   K I Z I Türkiye Bursa nere,Kanada Montreal nere Kader yazdıktan sonra olur  elbette, Soğuk ülkenin sıcak...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zeynep-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimin Sonsuzluğu', 'sevgimin-sonsuzlugu-savas-dincbas-aqef9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevginin evrenselliğini yaşıyorum

içimde dayanılmaz bir enerji

tüm bedenimi yırtacak gibi

kelimeler yetersiz

dünya dili ile

bu aşk değil

aşktan da öte

evrensel bir şey

yürek dolusu

sanki seni çok ötelerden

belki yüzyıllar öncesinden

belki başka bir boyuttan

tanıyor ve seviyorum...', 'sevginin evrenselliğini yaşıyorum içimde dayanılmaz bir enerji tüm bedenimi yırtacak gibi kelimeler yetersiz dünya dili ile bu aşk değil aşk...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgimin-sonsuzlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yAKA', 'yaka-fahrettin-selcik-qe6lx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Y  A  K  A

İzmir de ünlüdür, sahil Karşıyaka,

Bursa dan gelip Nesrinle mesken Tutmuşsun,

Fahrettin Selçik orada oturmuşluğun önemli vaka,

İnanıyorum,Sayende gelişmiştir bu Karşıyaka.

Baktım uğur var yaka da,oturdum kaldım,

Yetmiyormuş gibi birde Bornova yaka da mülk aldım,

Hem ormana sınır,hem de köy yerleşkeye yakın,

Usulsüz,ruhsatsız bir ev de burada yaptım.

Alerji ve yaştan, istemem artık deniz kenarı,

Yakaköy temizBornova da köykent,çamlık diyarı,

Yerden temiz havadan anlamaz İzmir hıyarı,

Bu köy taşlık ama  ağaçlık,oksijen anbarı.

Köyün yerleşme tarihi, asrı bulur,

Güneşi karşısından,alnından vurur,

Şimdilerde Büyük şehir sınırın da kalır,

Kanununda özel olarak orman köyü anılır.

Fahrettin Selçik  13-6-2005  Ulucak', 'Y  A  K  A İzmir de ünlüdür, sahil Karşıyaka, Bursa dan gelip Nesrinle mesken Tutmuşsun, Fahrettin Selçik orada oturmuşluğun önemli vaka, İn...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vesvese', 'vesvese-mustafa-caliskan-manisa-4aw5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İdrak susmuş,

Nefis kusmuş,

Kötülük coşmuş,

Perçemimden yakalamış beni

Bu bir ses,

Bu bir nefes, 

Vesveseden kafes,

Çığlık çığlığa kovuyorum seni.', 'İdrak susmuş, Nefis kusmuş, Kötülük coşmuş, Perçemimden yakalamış beni Bu bir ses, Bu bir nefes,  Vesveseden kafes, Çığlık çığlığa kovuyorum...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vesvese-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-hasan-kocamanoglu-ehsig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykuyu unuttuğunda

Gözde yaş kuruttuğunda

Kederi avuttuğunda

Beklerim seni bir tanem

…

Çaresiz ağladığında

Umudun kalmadığında

Tutanın olmadığında

Beklerim seni bir tanem

…

Gurbet aranı bölerse

Günün aylara dönerse

Yüzün sararıp sönerse

Beklerim seni bir tanem

…

Gönlün cefayı çekerse

Baharın yaza dönerse

Umut ışığın sönerse

Beklerim seni bir tanem

…

Km-050705', 'Uykuyu unuttuğunda Gözde yaş kuruttuğunda Kederi avuttuğunda Beklerim seni bir tanem … Çaresiz ağladığında Umudun kalmadığında Tutanın olmad...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-tanem-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Desti Gibi', 'kirik-desti-gibi-hasan-kocamanoglu-ogtev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüklenen manaları bilemedim

Emirlerini eda edemedim

Sırrınla kalbimi besleyemedim

Kırık desti gibi geldim efendim

…

Zekatla zengin fakirle yan yana

Oruç en güzel perhiz anlayana

Yolunda bir, bir şeyler yaptım ama

Kırık desti gibi geldim efendim

…

Namazla erdim yüce makamına

Lütfundan canlar buldum imanıma

Ezildim, izzet ve azametine

Kırık desti gibi geldim efendim

…

Sundun meccanen sonsuz nimetini

Bildirdin, anlamadım hikmetini

Umdum da celilinden, cemalini

Kırık desti gibi geldim efendim

…

Gücüm yetiremedim kul olmaya

Dalmışım dünyadan murad almaya

Günahkar kulu kapıdan kovmaya

Kırık desti gibi geldim efendim

…

KM-100705', 'Yüklenen manaları bilemedim Emirlerini eda edemedim Sırrınla kalbimi besleyemedim Kırık desti gibi geldim efendim … Zekatla zengin fakirle y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kirik-desti-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ağlarım Ben', 'aglarim-ben-hasan-kocamanoglu-mu0d1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürüm dağılmış otlar mı? 

Hazar kurumuş çağlar mı? 

Sevenim dostum yoklar mı? 

Sabah akşam ağlarım ben

…

Türkümün yüzü güldü mü? 

Dost, dost diyenler öldü mü? 

Zalim sefasın sürdü mü? 

Sabah akşam ağlarım ben

…

Dünya bu zulmü gördü mü? 

Ayılar basmış yurdumu

Dünya âlemler duydu mu? 

Sabah akşam ağlarım ben

…

Dumanlar gibi ağsam mı? 

Yağmurlar gibi yağsam mı? 

Feryadı figan salsam mı? 

Sabah akşam ağlarım ben

…

Kopuzla sazlar çalar mı? 

Düşeni kazlar anar mı? 

El, anan gibi yanar mı? 

Sabah akşam ağlarım ben

…

Bakma gözümde yaş mı var? 

Kara bağrımda taş mı var? 

Esarette gardaş mı var? 

Sabah akşam ağlarım ben

…

Km-270705', 'Sürüm dağılmış otlar mı?  Hazar kurumuş çağlar mı?  Sevenim dostum yoklar mı?  Sabah akşam ağlarım ben … Türkümün yüzü güldü mü?  Dost, dost...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aglarim-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabiha Rana''ya ithaf', 'sabiha-rana-ya-ithaf-mikdat-bal-52ugp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu gönlün vardır

Melekler öpsün gönlünü

Sevmeyene dünya dardır

Melekler öpsün gönlünü

Geçer aylar geçer yıllar

Ömür biter vade dolar

Ölmez asla seven kullar

Melekler öpsün gönlünü

Yeter bize insan isen

Tatlı, ballı lisan isen

Peri isen Çingan isen

Melekler öpsün gönlünü

Sevdin, sevdirdin kendini

Taktın bize kementini

Çok beğendim bu fendini

Melekler öpsün gönlünü

Devasın, ilacım dedim

Bil ki sana bacım dedim

Ben sana muhtacım dedim

Melekler öpsün gönlünü

Dünya geçer bir anlıktır

Tek aranan insanlıktır

Ne çingan ne Romanlıktır

Melekler öpsün gönlünü

Mikdat der şiirim sana

Çok yaşa, Sabiha Rana

Merhem olmuşsam yarana

melekler öpsün gönlünü', 'Sevgi dolu gönlün vardır Melekler öpsün gönlünü Sevmeyene dünya dardır Melekler öpsün gönlünü Geçer aylar geçer yıllar Ömür biter vade dolar...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sabiha-rana-ya-ithaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapanmak isterse biri turbanı', 'kapanmak-isterse-biri-turbani-mikdat-bal-hwiub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim dönüpte bakar koca karıya

Açık imiş kapalıymış bize ne

Eşin kapalı da evlatları ya? 

Açık ya kapalı o da bize ne

Kapanmak isterse biri turbanı

Sana ne, taksınlar, sen tak urganı

İstersen sonuna kadar urbanı

Çıkar öyle dolaş o da bize ne

Memleket sokaktan ibaret midir

Yaptığın insani bir gayret midiir

Bu bir özgürlük mü, esaret midir

Simge yapmış ise bu da size ne

Kimdi önce bunu yasaklayanlar

Sonra giyenleri pasaklayanlar

Kimdir bu kozları hep saklayanlar? 

Onlar huylanırmış, aman bize ne

Nasıl bir din ki bu yaşanmıyorsa

Bezden bir engelden aşılmıyorsa

Böyle bir baskıya şaşılmıyorsa

Müslümanız dersin o da bize ne', 'Kim dönüpte bakar koca karıya Açık imiş kapalıymış bize ne Eşin kapalı da evlatları ya?  Açık ya kapalı o da bize ne Kapanmak isterse biri t...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kapanmak-isterse-biri-turbani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Yüreğim Senin Olsun', 'al-yuregim-senin-olsun-hasan-kocamanoglu-qo8hz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kararın karakış sürer

Hasretin belimi büker

Kederin sevdamı dürer

Al yüreğim senin olsun

…

Çektim yârin özlemini

Saldım sevdanın demini

Tuttum yasla gündemini

Al yüreğim senin olsun

…

Yapraklar dökülür güzün

Özledim o güzel yüzün

Umuttu senin her sözün

Al yüreğim senin olsun

…

Çekerim aşkın çilesin

Kurdun kuşun da hilesin

Beklerim seni bilesin

Al yüreğim senin olsun

…

Tek çıktım yine akşama

Gözyaşı döktüm yarama

Çeker gidersem arama

Al yüreğim senin olsun

…

KM - 220605', 'Kararın karakış sürer Hasretin belimi büker Kederin sevdamı dürer Al yüreğim senin olsun … Çektim yârin özlemini Saldım sevdanın demini Tutt...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/al-yuregim-senin-olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet Işıkoğlu ve Mikdat Bal mesaj Trafiği', 'mehmet-isikoglu-ve-mikdat-bal-mesaj-trafigi-mikdat-bal-3qf23', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilimle cilala parlat cevheri 

Toplansın sevgiler yansıt ileri 

Yok olsun ortadan kalksın cehalet 

Kaplasın doğayı islam zaferi...........Işıkoğlu 

Ne güzel temenni ne güzel dilek 

Buna amin diyor, insan, cin melek 

Çekilmiyor gayri ateşten gömlek 

Kaplasın doğayı İslam zaferi.......Mikdat

Dilekler yetmiyor olmalı amel 

Safsata atılsın bulunsun temel 

Uzansın dünyaya imanlı bir el 

Kaplasın doğayı islam zaferi.......Işıkoğlu 

Amel de yetmiyor olmalı niyet 

Bak sana riyakar oldu cemiyet 

Muhlisler sevilir öyle der ayet 

Kaplasın doğayı İslam zaferi.......Mikdat Bal 

İhlas ile yaklaşılsa olaya 

Varılması kolay olur sılaya 

İslam bayrağını diker kalaya 

O zaman yaşanır islam zaferi.......Işıkoğlu

Ne büyük nimettir vucutta sıhhat 

Büyüğe küçüğe eyle nasıhat 

En büyük savaştır nefisle cihat 

O zaman yaşanır İslam zaferi.....Mikdat 

Gerektir insana düşünen beyin 

Tersine çalışıp olmasın hayin 

Eğmesek küffara dünyada boyun 

O zaman yaşanır islam zaferi.......Işıkoğlu

Beyinler tonlarca çalıştırılsa 

Dini bilgilerle buluşturulsa 

Evlatlarımız da alıştırılsa 

O zaman yaşanır İslam zaferi....Mikdat bal

Işıkoğlu der ki aklını kullan

Önünde rehber hazreti kur an 

Sırrı çözülürse ancak o zaman

Yaşanır dünyada islam zaferi......Mehmet Işıkoğlu

Bal der Kur''an ilmi her şeye şamil

Ne zaman olursak ilmiyle amil

Böylece oluruz insanı kamil

Yaşanır dünyada İslam zaferi......Mikdat Bal', 'Bilimle cilala parlat cevheri  Toplansın sevgiler yansıt ileri  Yok olsun ortadan kalksın cehalet  Kaplasın doğayı islam zaferi...........Iş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/mehmet-isikoglu-ve-mikdat-bal-mesaj-trafigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyy!', 'uyy-emin-nadir-eq1wv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat; gece bir buçuk.

Aklım yerinden uçuk.

Yaşı benden çok küçük.

Uyanıkım.

UYYY! YANIKIM.

Arar mı bu saatte? 

Gözlerim; yangın yeri,

Kirpiklerim ihanette.

Uykum var.

UYYY! KUM VAR.

Saat sabahın dördü

Ne aradı ne de sordu.

Gün ışıdı,sabah oldu.

Uykuluyum.

UYYY! KULUYUM.', 'Saat; gece bir buçuk. Aklım yerinden uçuk. Yaşı benden çok küçük. Uyanıkım. UYYY! YANIKIM. Arar mı bu saatte?  Gözlerim; yangın yeri, Kirpik...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uyy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altay''lının Kızı', 'altay-linin-kizi-hasan-kocamanoglu-rs38s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıldan, keçedendir çadırları

Sığdırırlar içine yurtları

Kubbesinde göğü, tepesinde ay’ı 

Diriliş destanıdır umutları

…

Geçmişten çıka gelir ak atlıları

Asya’yı yeniden sahiplenirler

Altay’ın dumanlıdır hep dağları

Birlikte yürür, yüreklenirler

…

Bu kutlu obada yaşanır töreler

Kültürlerinin köklerini süreler

Bu güne taşıdılar geçmişin izlerini

Yabanın tüm umutlarını düreler

…

Altaylının yahşi kızları,

At biner, kılıç kuşanırlar.

Gözü açık içer kımızları

Koca bir ömür sürer, beyle yaşlanırlar.

…

Altay’da ağaçların yaprağı sararmaz

Yaz kuşları susamaz

Gökyüzü belli etmeden ağlar

Yılkısı, kulunu yerinde duramaz.

…

Bu uğurlu yurtta, o kadar kolay mı? 

Yeşilliğe şahit özgür atlara söz geçirmek

Üzerinde adam gibi dimdik durmak

Altay Türkünü yorar mı? 

…

Km-280705', 'Kıldan, keçedendir çadırları Sığdırırlar içine yurtları Kubbesinde göğü, tepesinde ay’ı  Diriliş destanıdır umutları … Geçmişten çıka gelir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/altay-linin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amel Defteri', 'amel-defteri-hasan-kocamanoglu-sodvy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin başını alıp giderse,

Akrebin kuyruğunu kim yurt edinmez? 

Ağlayan bir karınca sesini duyursa,

Uzaktakilerin sesini kim işitmez? 

…

Gönlünü öyle bir ateşle alevlendir ki,

Matemiyle duyanların ciğerler yansın.

Haberin takdiriyle yedi gök titrer ki,

Denizlerin ve madenlerin gönlü aksın.

…

Kutlu kapıda kabul görürse hünerin,

Gözyaşlarının bile talihi güler.

Kerem sahibinden ihsan olursa günlerin,

Diken tarlası bile gül bahçesine döner.

…

Dünyada firavunların reisliği olmasaydı,

Cehennemler nerelerden beslenirdi? 

Dünyada hasım ve düşman olmasaydı,

Öfkesi ölen insanlar ne merhametlenirdi? 

…

Taç ve taht içinde büyük sultan olsan da

Bir gün bahtın, talihin sönüp gider.

Gökyüzünde güneş gibi, ay gibi olsan da

Ecel bir gün bu saltanatı viran eder.

…

Amel defteri olmayan bir kişi yoktur,

Defterine günahı ve sevabı yazılmasın.

Şu dünyada ölmeyecek bir kişi yoktur,

Boynuna berat veya berbat levhasın asmasın.

…

KM - 140605', 'Güneşin başını alıp giderse, Akrebin kuyruğunu kim yurt edinmez?  Ağlayan bir karınca sesini duyursa, Uzaktakilerin sesini kim işitmez?  … G...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/amel-defteri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Dostları', 'ankara-dostlari-hasan-kocamanoglu-o36ca', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ankara, dostları kendine çağırıyordu 

Türk edebiyatı mecrasını arıyordu

Beşevler’de ezilmiş bir kadın yatıyordu

Sabahın ilk ışıklarında rızk arıyordu

…

Aşti’den Kızılay’a metro taşıdı bizi

Geliyordu yerden yağmurun kokulu izi

Kürşad tipli Kemaloğlu karşılar geleni 

Sakarya’nın kızı Sevim de en çok güleni

…

“Gönlümün Güz Mevsimi”ni yazan A.Kadir’e

Güzel yazar, güzel söyler, değerdi takdire

Ahmet Turan kır saçlı, bir beyefendi gibi

Sevinç Atan Hanım sevk idarenin galibi 

…

Satoğlu durgundu, Tamburimiz çok suskundu

Akdemir’le İmdat Gümüş’ün gönlü dolgundu

Ulviye Hanım gün görmüş, asude olgundu

Gümülcine’li Nurten çilelerden yorgundu

…

Sevilay Şirin’di, Özlem dağlar gibi çetin 

Sevim’le Nur yan yana, Şerife çok metin

Arada bir, bir dalıp gidiyordu Nevin’im

En şeni, en şakrağı, Mustafa’ydı eminim

…

Yurdabak, okur sayılı rubailerini 

Dinleyenler dokur, gül yüzlü alkışlarını

Aslan Yürekli bir anadır Sabiha Rana

Kanlar kaynardı, gözü yaşlı Kaan Bayram’a

…

Hasko köşesinde, Elyasoğlu çok genç idi

Sahabeddin gözde, İmren, Atsız gibi idi

Unutmadım “İki karanfilin” annesini

Sanki derdi vardı, alamadı neşesini

…

Mesaj salmıştı, gelemeyen dostlarımız 

Seyre dalmıştı, adını unuttuklarımız

Varsın gönülden gönüle dostluklar kurulsun

Bir uçtan bir uca, vatana dostluk sunulsun

…

Ankara170705', 'Ankara, dostları kendine çağırıyordu  Türk edebiyatı mecrasını arıyordu Beşevler’de ezilmiş bir kadın yatıyordu Sabahın ilk ışıklarında rızk...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ankara-dostlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni', 'anla-beni-hasan-kocamanoglu-5h1jv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yol uzak varamıyorum

Ayakta duramıyorum

Hal hatır soramıyorum

Ne olursun anla beni

…

Önümü göremiyorum

Yönümü bulamıyorum

Günümü sunamıyorum

Ne olursun anla beni

…

Kapına gelemiyorum

Halimi seremiyorum

Borcumu veremiyorum

Ne olursun anla beni

…

Güllerini deremeden

Sevdiğime eremeden

Gideceğim göremeden

Ne olursun anla beni

…

KM-050705', 'Yol uzak varamıyorum Ayakta duramıyorum Hal hatır soramıyorum Ne olursun anla beni … Önümü göremiyorum Yönümü bulamıyorum Günümü sunamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anla-beni-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayan Bulur', 'arayan-bulur-hasan-kocamanoglu-7z9zn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayıp bilen gaibden iz mi görür? 

Hakk’ın eli olmadan kimler yürür? 

Kır, suretini de ruhun sevinsin

Ruhun âlemlerden ilham öğrensin

Gizleme gündüzün yüzünü elden

Gizleyerek yüzün çalma her telden

Nimeti boğaz yese yüz utanır

Kalpte sevgi olanı herkes tanır

Dostun cefası bire bin gibidir

Güzel vefası binde bir gibidir

Kör mesul değil, güzeli görmeden

Gecelerin saçlarını örmeden

Kendini yol erenlerinden sayma

Sarhoş olup da baş aşağı kayma

Umutsuzca yollara diken ekme

Bela çöllerinde çileler ekme

Hakk’a teslim ol da yüzün ak çıksın

Kir ve pasın temizlenerek aksın

Arayan bulur bela ve Mevla’sın

Doğru, temiz ve güzelsen evlasın

Km-130605', 'Ayıp bilen gaibden iz mi görür?  Hakk’ın eli olmadan kimler yürür?  Kır, suretini de ruhun sevinsin Ruhun âlemlerden ilham öğrensin Gizleme ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arayan-bulur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yıldız...', 'son-yildiz-bahtiyar-arslan-jm563', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yattım gölgelerin içine

kendi gölgemi aradım

binlerce yıldız öldü avuçlarıma...

annem usulca gülümsedi

kıskanmadı

saçındaki son yıldızı bıraktı saçlarıma...', 'yattım gölgelerin içine kendi gölgemi aradım binlerce yıldız öldü avuçlarıma... annem usulca gülümsedi kıskanmadı saçındaki son yıldızı bıra...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-yildiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-emre-saricicek-xlwh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerdesin bebeğim, nerelerdesin? 

Sır olup gittin kayıplardasın.

İnce narin çizgilerdesin

Yaşanmış tatlı düşlerimdesin.

Engin mavi göklerdesin.

Dalgalı karanlık denizlerdesin.

Susuz kurak çöllerdesin.

Akıp giden nehirlerdesin.

Mum ışığıyla dönecekmisin.? 

Tekrar bebeğim diyecekmisin?', 'Nerdesin bebeğim, nerelerdesin?  Sır olup gittin kayıplardasın. İnce narin çizgilerdesin Yaşanmış tatlı düşlerimdesin. Engin mavi göklerdesi...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bebegim-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutma', 'beni-unutma-numan-i-stanbul-mtmsr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidiyorum yar 

Artık dayanmıyor 

Kaldırmıyor bu yürek bu acıyı 

Tadamıyor sensiz sevdayı

Senin gittiğin gibi

Bende gidiyorum yar

Gitmek değil kaçmak

Deniliyor bunun adına

Ama ne ben sana

Nede bu yüreğe kaçmayı alıştırdım 

Çünkü sen kaçarken kalbimi

Ben kaçmaya çalışırken benliğimi kaybediyorum', 'Gidiyorum yar  Artık dayanmıyor  Kaldırmıyor bu yürek bu acıyı  Tadamıyor sensiz sevdayı Senin gittiğin gibi Bende gidiyorum yar Gitmek deği...', ARRAY['Türk Edebiyatı','Şiir','Numan İstanbul']::text[], 8.5, '{"poet":"Numan İstanbul","poet_slug":"numan-i-stanbul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-unutma-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma', 'bakma-mevlut-bicik-tqw7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Câmiye varıyorsun yüzler asık

Yüzlere bakıyorsun deriler kasık

Gönüllere bakıyorsun eşikler basık

Ne olursun yüzünle yüzüme bakma

Dert evime bir dert daha katma.

Namaza duruyorsun gönül bozuk

Duâ yapıldığında ise eller büzük

Bir hiç uğruna delinmiş  tüzük

Gurur ve kibirinle bana çatma

Arkamdan,aleyhimden tutup atma.

Hatme oturuyorsun gönül buruk

Vücûda bakıyorsun kol,kanat kırık

Muhabbet kanalının ortası yarık

Gönül evime soğuk suları dökme

Sırtımdan da hizmet libasını sökme

Sohbet dinliyorsun kalbler sönük

Kalb konuşana değil,içine dönük

Dinliyenler ise gerçekten donuk

Geçmişe nankörlük yapıp’da tepme

Beytül-mâle ihânetle sağa,sola sepme.

Benim sana söylediklerim elbette az

Birileri sana veriyor gerçekten gaz

Beni oralarda görmeyince alıyorsun haz

Bırak artık yakamı, elimi de tutma

Sûreta iyi görünüp’de içinden kin gütme.

Mevlüt Bicik

30.12.2005  saat  20.36

Esslingen', 'Câmiye varıyorsun yüzler asık Yüzlere bakıyorsun deriler kasık Gönüllere bakıyorsun eşikler basık Ne olursun yüzünle yüzüme bakma Dert evime...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bakma-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Benim Derdim', 'dert-benim-derdim-abdullah-odabas-pq0j4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günler geçer ömürden,                  		

Göreyim seni gönül,                     		

Nefs ile eyle cidal,                    		

Göreyim seni gönül,                     		

Tanı Hakkı kıl taat,                    		

Hakka eyle itaat,                       		

Gün bugün saat bu saat,                 		

Göreyim seni gönül,                     		

Hacil olma hesapta,                     		

Sualde hem kitapta,                     		

Kalmayasın azapta,                      		

Göreyim seni gönül,                     		

Ara bul has kulları,                    		

Müstakımdir yolları,                    		

Hoştur güzel halları,                   		

Göreyim seni gönül,                     		

Anlara eyle tazim,                      		

Emre itaat lazım,                       		

Nasihat sana sözüm,                     		

Göreyim seni gönül,                     		

Uğrulara kapılma,                       		

Pehlivan ol yıkılma,                    		

Uyuyup yolda kalma,                     		

Göreyim seni gönül,                     		

Fırsatı bil ganimet,                    		

Hayattır büyük nimet,                   		

Has kula vardır cennet,                 		

Göreyim seni gönül,                     		

Has kulların has işi,

Akar gözlerden yaşı,

Yumuşatır kara taşı,

Göreyim seni gönül,

Has kul olur has ümmet,

İşler farz ile sünnet,

Mükafat cemal görmek,

Göreyim seni gönül,

Mağruf işle nehyi at,

Amele ameller kat,

Önümüzde var sırat,

Göreyim seni gönül,

Teslimi ruh zor geçit,

Dertler olur binbir çeşit,

Koşar imdada mürşit,

Göreyim seni gönül,

Mürşide candan bağlan,

Aşkı mürşitle dağlan,

Murat alır çok ağlayan,

Göreyim seni gönül,

Seherlerde bülbül ol,

Yol almada düldül ol,

Ölürken ağlama gül,

Göreyim seni gönül,

Meleklere cevap ver,

Rabbim Allah Hak Resul,

Abdest al eyle gusül,

Göreyim seni gönül,

Meftuni ol kar akıl,

Halkayı tarika takıl,

Teeccütle evvabil kıl,

Göreyim seni gönül,', 'Günler geçer ömürden,                  		 Göreyim seni gönül,                     		 Nefs ile eyle cidal,                    		 Göreyim seni...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/dert-benim-derdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değirmen', 'degirmen-semsettin-veli-erbilli-tx12v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değirmen daşı kimin

Dolandım başı kimin

Kader meni kocaltı

Dedemin yaşı kimin

Değirmen daşı durmaz

Dolanır başı durmaz

O yar meni görende

Göz eder kaşı durmaz

Değirmen daşına bak

Duruptı başına bak

Senivçin çok ağladım

Gözümün yaşına bak

Değirmen daşın durut

Dolanmaz başın durut

Eğer meni seversen

Gözümün yaşın durut

Değirmen den içinde

Deni çok han içinde

Yar gelsin halim görsün

Gözlerim kan içinde

Değirmen daşıdandı

Dolansa başıdandı

Sevdanın bir hoşluğu

Yarın göz yaşıdandı

Değirmen kuyu budu

Harmanı suyu budu

Yar mennen her dem küser

Neyniyim huyu budu.', 'Değirmen daşı kimin Dolandım başı kimin Kader meni kocaltı Dedemin yaşı kimin Değirmen daşı durmaz Dolanır başı durmaz O yar meni görende Gö...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/degirmen-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikirlerin Mücadelesi', 'fikirlerin-mucadelesi-abdullah-odabas-vhzsx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarab verme müslümanlar başına,         	

Bir yerde olmasın ayrı fikirler,        	

Şeker yesen zehir olur canına,          	

Bir yerde olmasın ayrı fikirler,        	

Ayrı fikir ev ocağı yok eder,           		

Ne söylersen mutlak onlar ters gider,   	

Anne ağlar baba feryat zar eder,        	

Bir yerde olmasın ayrı fikirler,        	

Oğul, kızın gelin yahutda hanım,        	

Alimallah çıkarırlar dumanın,           	

Hergün binkez çıkar cesetten canın,     	

Bir yerde olmasın ayrı fikirler,        	

Yakar yıkar memleketi kavurur,          	

Şehirlerin külün göğe savurur,          	

Bir bakarsın hükümeti devirir,          	

Bir yerde olmasın ayrı fikirler,        	

Müslümana hiç yakışmaz zıt fikir,

Uy Kur''ana işler yolunda  tıkır,

Olmaz bir yerde isyan Malatya Diyarbakır,

Bir yerde olmasın ayrı fikirler,

Ağız açsak pervasızca neslimize çatarız,

Moskaflara memleketi bir akçeye satarız,

Hayran olduk biz batıya hala batarız,

Bir yerde olmasın ayrı fikirler,

Hep yabancı fikir bizi batırdı,

Edep, haya, namusu aldı götürdü,

Gençlik tamam yollarını yitirdi,

Bir yerde olmasın ayrı fikirler,

Meftuni sen kendi çevrene karış,

Bu hal ile gelmez Türklere barış,

Kervan gitti durma ardından yetiş,

Bir yerde olmasın ayrı fikirler,', 'Yarab verme müslümanlar başına,         	 Bir yerde olmasın ayrı fikirler,        	 Şeker yesen zehir olur canına,          	 Bir yerde olma...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/fikirlerin-mucadelesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neslime Saygı', 'neslime-saygi-abdullah-odabas-bs1mi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurban olam anam babam,                 	

Size nasıl dua kılam,                   		

Nurda yatsın nenem dedem,               	

Odabaş sülalesi,                       		

Amucemle aziz kardaş,                   		

Huri kılman size yoldaş,                		

Büyük küçük hep odabaş,                 	

Odabaş sülalesi,                       		

Odabaşlar hasleti,                     		

Sehavettir alameti,                     		

Bulasız siz hep cenneti,                		

Odabaş sülalesi,                       	

Dip dedemiz Abdurrahman,

Konuk sever yedirmiş nan

Görsünler cemalin ey Rahman,

Odabaş sülalesi,

Sahavette devam etmiş,

Biri gitmiş biri gelmiş,

Şu cihanda şöhret etmiş,

Odabaş sülalesi,

Neçare bizde son buldu,

Kuru bir nam elde kaldı,

Ne misafir konuk geldi,

Odabaş sülalesi,

Meftuniyem o demlerin,

Peder, kardeş, amucamın,

Bu duaya deyin amin,

Odabaş sülalesi,', 'Kurban olam anam babam,                 	 Size nasıl dua kılam,                   		 Nurda yatsın nenem dedem,               	 Odabaş sülale...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neslime-saygi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Keçim Olsa', 'bir-kecim-olsa-fatih-erdogan-iwjnd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir keçim olsun inatçımı inatçı.

Saçları kıvırcık,gözleri siyah bir keçi...

Onu öyle çok seveyim ki

Herkesin yanında öveyim,

Kurban gelsin kesmeyeyim

Keçimden hiç vaz geçmeyeyim.

Biraz param olsun ot alayım,

Seni kendi elimle besleyeyim.

Sadece benim olsun,

Yalnız benim...

Başkasına haram,bana yaren olsun

Güzel sözlerle inadını kıracak,

Bir keçem olsun', 'Bir keçim olsun inatçımı inatçı. Saçları kıvırcık,gözleri siyah bir keçi... Onu öyle çok seveyim ki Herkesin yanında öveyim, Kurban gelsin k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-kecim-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğrafım', 'fotografim-ethem-turan-im6qa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakmak istersen mektubumun yanında

Fotoğrafımı gönderiyorum sana

Bak nasılda yalnızım 

Kollarım açık beklemekteyim

Sensizliğin karamsarlaştırdığı

Gözlerime de sakın dikkatli bakma 

Yokluğuna ve seni görememeye alışamadılar

Karamsarlık derin izler bıraktı alnımda

Derin çizgiler oluşmaya başladı 

Her bir çizgide senin ismin saklı

Ellerimde nasıl  da açık 

Dua edercesine,

Rabbimden  seni istercesine

Dik duramadığıma da  bakma 

Hasret yükünün altında dizlerim ezilmekte

Uzun zamandır seni beklemekte 

Yorgun durmama da aldırma sakın 

Seni düşünerek geçti gecelerim 

Gülüşüme bak istediğin kadar 

Geriye bıraktığın  eserinde kalan 

Son tebessüme iyi bak 

Biliyor musun 

Senin  hatırandan geriye o kaldı 

Mutlu değilim sanma sakın 

Tam aksine delilercesine mutluyum 

Nedenini sormadan ben söyleyeyim

Ben bir deli kız sevdim', 'Bakmak istersen mektubumun yanında Fotoğrafımı gönderiyorum sana Bak nasılda yalnızım  Kollarım açık beklemekteyim Sensizliğin karamsarlaştı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/fotografim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-fatih-erdogan-gjifd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saf beyaz renginle masum gibisin

Gerçekte,can alan tipisin.

Sen,idamlık bir adamın

Darağacındaki ipisin.

Kar gibisin.08/10/2004', 'Saf beyaz renginle masum gibisin Gerçekte,can alan tipisin. Sen,idamlık bir adamın Darağacındaki ipisin. Kar gibisin.08/10/2004...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kar-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-suleyman-yavas-thp65', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman

Sevdiğimin yanında

Ellerimin arasından 

Kayıp giden balıktır

Zaman 

Hasretin girdabında

Bir ileri iki geri adımdır', 'Zaman Sevdiğimin yanında Ellerimin arasından  Kayıp giden balıktır Zaman  Hasretin girdabında Bir ileri iki geri adımdır...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-278-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Ayrılık', 'vakit-ayrilik-fatih-erdogan-bqvqq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık vakti şuan! 

Gözler nemli,yanaklar ıslak.

Gönül sevdiğine,toprak suya

Hasret kalacak.

Ne zor Allahım ayrılmak.

Toprak çatlamış susuzluktan,

Sanki yarılacak.

Gerçegin yerini hayaller alacak

yollar ırak ama koşsan varılacak.

kollar sevdiğine sanki tekrar sarılacak.', 'Ayrılık vakti şuan!  Gözler nemli,yanaklar ıslak. Gönül sevdiğine,toprak suya Hasret kalacak. Ne zor Allahım ayrılmak. Toprak çatlamış susuz...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vakit-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgördük', 'hosgorduk-ahmet-atmaca-c5u6k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'açılıp saçılmayı

şehvete kapılmayı

vede çalıp çırpmayı

biz herşeyi hoşgördük

herkez başına buyruk

biz bizi ele sorduk

nelere kafa yorduk

yozlaşmayı hoşgördük

ne dil kaldı ne töre 

hemde göz göre-göre

avrupa alsın diye

eyvallahı hoşgördük

bilmedik cinsiyeti cinsi ne

kulak verin şu gençliğin sesine

eroyinle esrar ile beynine 

hükmedenin hükmünü de hoş gördük

lut kavminden ne farkı var zamanın

vakti geçti dilenecek amanın

doğurupta sokaklara salmanın

utancını,ayıbını hoşgördük

şov dünyası rüyaları süslüyor

kimi kan ağlarken kimi gülüyor

kimi ise bunalımdan ölüyor

hayatlara zar atanı hoşgördük', 'açılıp saçılmayı şehvete kapılmayı vede çalıp çırpmayı biz herşeyi hoşgördük herkez başına buyruk biz bizi ele sorduk nelere kafa yorduk yoz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hosgorduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar', 'tekrar-ahmet-atmaca-hjqj4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar bu sırra eremezsin 

Yol bulupta geçemezsin 

Gül tutarsın deremezsin 

Solar elinde- elinde 

Yorgun düşer bakışların 

Bozulur kalp atışların 

Adım-adım kaçışların 

Sayar yerinde-yerinde 

Ne tufandır ne zelzele 

Gelmez malın mülkün göze 

Göz yaşların bir çift söze 

Akar derinden-derinde,', 'Yar bu sırra eremezsin  Yol bulupta geçemezsin  Gül tutarsın deremezsin  Solar elinde- elinde  Yorgun düşer bakışların  Bozulur kalp atışlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tekrar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Olsun', 'kutlu-olsun-sahin-kars-nt0t8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin bu mutlu gününde,

Yanında olmak isterim.

Armağanım sarı gülü,

Elimle vermek isterim.

Fısıldayıp kulağına 

Seni seviyorum deyip. 

İçindeki o sevinci,

Yüzünde görmek isterim.

Nazlım mutlu musun bugün

Kutlu olsun doğum günün.

Emelim arzum; sen benim

Ben senin olmak isterim.', 'Senin bu mutlu gününde, Yanında olmak isterim. Armağanım sarı gülü, Elimle vermek isterim. Fısıldayıp kulağına  Seni seviyorum deyip.  İçind...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kutlu-olsun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarıparçam', 'yariparcam-kamille-mukaddes-bpl15', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerime yağmurlar yağıyordu

O şehrin sokaklarında sele kavuşuyordum

Bir elini tutuyordum

Bir sen çiziyordum özlemlere,,

Saatler boyu yazıyordum,

Yine de kendimi anlatamıyordum..

Oysa bir bütünün yarısıydık biz,

Ayrı şehirlerde ayrı öykülerde,

Acılarımız da sevinçlerimiz de ayrıydı

Aynı olan BİZdik.

Kuşkusuz biz

Anlamıyordun...', 'Gecelerime yağmurlar yağıyordu O şehrin sokaklarında sele kavuşuyordum Bir elini tutuyordum Bir sen çiziyordum özlemlere,, Saatler boyu yazı...', ARRAY['Türk Edebiyatı','Şiir','Kamille Mukaddes']::text[], 8.5, '{"poet":"Kamille Mukaddes","poet_slug":"kamille-mukaddes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yariparcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik sone', 'yitik-sone-atif-okan-rznmy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen ve ben ikimiz yitik sayfalarıyız

rüzgarlı ruhumuzdan sözcükleri muhacir

iğreti ve mücerred hüzün ve neş''e denen

o boğumlu kitabın sen ve ben ikimiz

sen ve ben ikimiz neden bulamıyoruz

köprüleri meçhul nehirlere gerili

kalpleri mamur kılan ketum müstahdemleri

aah ''yaklaştıkça bulanan'' sen ve ben ikimiz

içte sevda aynasının sırrı döküldüğünden

mi? hayatı evla kılan o mana buharlaştı

giderek herbirimiz bir sırra döndüğünden

sen ve ben ikimiz sessizlik gibi bir acı

bulduk çıkardık kara dipsiz derinliğimizden

işte budur diyerek acıların miracı

                                     Atıf  OKAN

                                    30 ARALIK 2005

''Bazı ruhlar bu alemde asla mutmain olamayacaktır.onlar cennet ve cehennem arasında salınıp dururlar.mevsimsiz bahçeler gibi renksiz ve donukturlar.işte onlara; araf, rüzgarlı bir kaftan olarak biçilmiştir.''

                         HÜSEYİN  TORUN', 'sen ve ben ikimiz yitik sayfalarıyız rüzgarlı ruhumuzdan sözcükleri muhacir iğreti ve mücerred hüzün ve neş''e denen o boğumlu kitabın sen ve...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yitik-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öner Tarık''a', 'oner-tarik-a-suleyman-zaman-soydd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni unutmamış, candan kardeşim

                  Işık saçan insan, olur güneşim

                  Her zaman dostlara doğru gidişim

                  Beni anımsayan dosta merhaba

                  Öner Tarık kardeş; olmuş mihmanım

                  Güzel dosta feda olsun bu canım

                  Kurulsun dostlarca, her gün divanım

                  Divan kuran dosta, candan merhaba

                  İsterim  bu yılda, her gün gülesin

                  Seni bilen dosta, dostça gidesin

                  Ömrünce özünü hep şad edesin

                  Mutlu kılan dosta, candan merhaba

                  Bir güzel insansın, erdem seninle

                  Güzellik yansıttın, tüm benliğinle

                  Zamanım mutlandı, gül cemalinle

                  İyilik sunan dosta, candan merhaba

        

                 

                                                31.12.2005', 'Beni unutmamış, candan kardeşim                   Işık saçan insan, olur güneşim                   Her zaman dostlara doğru gidişim         ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oner-tarik-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinme ey canân', 'sinme-ey-can-n-ali-riza-unal-dnncx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sinme ey canan,nedendir bu kaçış,

Göresin bahtı payımda, sen varsın,

Dinme ey gözyaşı,sendedir yakış,

Ne,ah-ki payımda sen varsın,

 --  Eserin tamamı değildir   -', 'Sinme ey canan,nedendir bu kaçış, Göresin bahtı payımda, sen varsın, Dinme ey gözyaşı,sendedir yakış, Ne,ah-ki payımda sen varsın,  --  Eser...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sinme-ey-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Algı', 'yanlis-algi-suleyman-zaman-dqvy5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoksullaştı vay halkımız

Dönmez oldu  ki çarkımız

Eksiliyor bak artımız

Bunca yanlış sonucunda

Çıkartılar yasaları

Arttırdılar tasaları

Doldurdular kasaları

Sessizlikler sonucunda

Kazanıyor rantiyeci

Çalışanlar hep verici

Hırsıza olduk seyirci

Örgütsüzlük sonucunda

Uyan derim, yeter artık

Sömürenin yüzü yırtık

Ekmeğe tuz oldu katık

Bilinçsizlik sonucunda

Yeni dünyanın düzeni

Korur durur sömürgeni

Görmediniz ki ezeni

Yanlış algı sonucunda

Zamanım dostunuz sizin

Keder, sevinç, sevda bizim

Sorunlar çok artar sızım

Anlaksızlık sonucunda

          03.07.2001', 'Yoksullaştı vay halkımız Dönmez oldu  ki çarkımız Eksiliyor bak artımız Bunca yanlış sonucunda Çıkartılar yasaları Arttırdılar tasaları Dold...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanlis-algi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılsonu', 'yilsonu-taner-yusuf-bul-7gvq2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yılsonu değil bu kez gelen

başlayan da yeni değil

bu kez

sonyıl geliyor

sonu gelen umutlarımın

ümitsizliklerimin

beklemelerimin

ve senin 

son yılın bu giden

sessiz ağlamalar yok artık

kahreden anlamamazlıklarımın

ve kabullenmemişliğimin 

ve sessizleşmemişliğimin

ve kuduramamışlığımın öfkeden

son yılı

artık beklemek yok

ümit etmek

ummak keza

kızmak  bile

yok

bu yıl sonu değil artık

son yıl zira

hadi açalım son kez defterlerimizi

dökelim ortaya ne varsa kalan yaşanmışlıklardan

mutlu yada mutsuz her ne varsa gülelim

son yılımızda bari helalleşelelim

ankara

31 aralık

duran çam''a vekaleten', 'yılsonu değil bu kez gelen başlayan da yeni değil bu kez sonyıl geliyor sonu gelen umutlarımın ümitsizliklerimin beklemelerimin ve senin  so...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yilsonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islık Çalmaya Devam Ediyorum', 'islik-calmaya-devam-ediyorum-ufuk-bayraktar-kc18l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', ''''' umut dağın ardında şimdi, hüzün yanıbaşımızda... ''''

böyle yazıyordu bir sayfasında

o zaman ''ıslık'' vardı

sen vardın

___ben vardım

______biz vardık. 

o zaman daha bir üretkendik

yıkıntılardan çıkıyordu en büyük eserler

yürekler anka kuşu gibi 

küllerinden doğuyordu yeniden

yaşıyorduk.

düşünüyor

___konuşuyor

______''ıslık çalıyor''duk...

sabah rengine boyanıyor

kuşların sesine karışıyordu sesimiz. 

ayfer''den öğrendik o sabah

ıslık çalamayacağımızı artık. 

geceden toplantı yapmışlar

tutulmuş dillerimiz! 

sonra birer birer gittiler şehrin mevsimlik misafirleri

sen kaldın

___ben kaldım

______biz kalmadık ama! 

yarım kalmıştı herşey

bir ömre ne sığarsa işte... 

öyle ortada 

___öyle viran

biz bile bakamadık sonra halimize,

acıdık! 

acıdı canımız

acıydı varlığımız, 

öyle yalnızdık! 

derken sen de gittin

bir ben kaldım o uzun öğretim sürecinde. 

nedense bir sabah

ıslık çalmaya başladım yeniden

sesim sabah rengine boyandı

yıldızlar döküldü geceden. 

ilkay''a veriyordum sesimi; 

ben çalıyordum, o söylüyordu:

''''gökyüzüne çizilmiş resimlere benzerdik

rüzgarın peşine takılan bir nefes gibiydik

kırdı dallarımızı fırtınalar boranlar

kaldı bahar çiçekleri üzerinde sevdamız.''''

sesime ses veren çıkar diye

ıslık çalıyorum sabahın rengine. 

*************************************************************************

şiir tarlası grubu için yazılmıştır.

ıslık bilim-sanat dergisi; gaziantep üniversitesi bünyesinde yayın yapan bir dergiydi, 2000 yılında kapatıldı.', ''''' umut dağın ardında şimdi, hüzün yanıbaşımızda... '''' böyle yazıyordu bir sayfasında o zaman ''ıslık'' vardı sen vardın ___ben vardım ______b...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/islik-calmaya-devam-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-ebru-rabia-berkul-4kz3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güvercinin

Kanat çırpışlarındaki

Özgürlükte

Arıyorum mutluluğu

Sakin ve

Bir o kadar saf

Ağlara takılmayı

Düşünmeden

Gelip giden

Bir balığı seyrederken

Çoçukların yüzündeki

O çok özel

Gülümsemelerde

Ve

Sevgiliye duyulan

Hasret ve özlemlerle

Geçen günlerin

El_ele tutuşmalarla

Gelen hazda

Yakalıyorum mutluluğu.', 'Bir güvercinin Kanat çırpışlarındaki Özgürlükte Arıyorum mutluluğu Sakin ve Bir o kadar saf Ağlara takılmayı Düşünmeden Gelip giden Bir balı...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mutluluk-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharlar Bahane', 'baharlar-bahane-duygu-dinc-euetx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahardan esintiymiş adam

İlkbaharın habercisiymiş kadın

Ne ses, ne soluk varmış

Yaz, soğuğu sevmiyormuş,

Kış, güneşi…

Bir yaprak daha solmuş

Ama bu ne ilk, ne de sonmuş

Hep yapraklar solarmış

Bir yerlerde, birilerinin yüreği acırmış

Her rüzgarda bir çığlık varmış

Uzaklardan gelen…

Son günü gibi yaşarmış hayatını

Her istediğini yaparak,

İlk günü gibi de hevesle…

Gün gelmiş,

Tura gelmiş düşeş beklerken…

Hayat böyle geçip gidiyormuş

Ne bir gıcırdayan kapı

Ne bir çalan zil…

Yine uyumuş umutlar

Yine tavanarasına kaçmış mutluluk

Sevecekmiş, sevememiş

Sevilecekmiş

Ama zaten hiç sevilmemiş ki…

Bir takvim yaprağı daha gitmiş bugünden düne

Bir kum saati daha baş aşağı dönmüş

Kendi isteğiyle…

Ve bir masal daha başlamış…

Yazın da buluşabilirlermiş

Kışın da…

Ama onlar hep kışı seçer olmuş son zamanlarda

Yürek ağrısı saplanır kalırmış kadına

Adam hiç oralı olmazmış

Umursamadığından değil,

Çok fazlasını, defalarca yaşadığından…

Kadın mağrurmuş,

Adamsa inadına isyankar…

Başından beri hataymış

İlişkiyi ayakta tutan

“Belki birgün…” diye başlayan cümlelermiş…

Kadın aşıkmış

Adam, aşka inanmazmış

“Neden? ”varmış

Dayanılması güç her gerçeğin başında

Ve aslında cevap olan tüm cümleleri

Soruya dönüştürüp acı çekerlermiş

Severlermiş birbirlerini

Bağlılarmış da

Zaman bağları sıkılaştırsa da

Sorunları çözmüyormuş

Adamla kadın piyon,

Problemler büyük taşlarmış

Ve işin garibi

Hep aynı siyah karedelermiş…

Işıklar kapanmış

Mantıklı olan buymuş

Mantıksız olansa, mantıklı olanı yapmak…

Sevmek suçmuş,

Sevilmek şanssızlık…

Görmek zormuş,

Görmemek aptallık…

Bu kadar acı çekmektense

Ayrı istikamette gitsin gemilerimiz demişler

Kimse, kimsenin derdini dinlemez aslında

Ama adam kadını dinlemiş

Kadın dağlardan tepelere

Denizlerden göllere gelmiş

Alanı daraldıkça

Sevgisini sığdıramadığından sözetmiş

Boynunu eğmiş ve sürekli susmuş adam

Kadın haklıymış

Aslında adam da haklıymış ama

Söyleyecek sözü yokmuş…

Denizleri ikiye ayrılmış

Yan yana gemiler

Usulüne uygun bir vedayla ayrılmışlar

Her gözyaşı bir umut

Her umut bir gözyaşı olmuş kadının hayatında

Adamsa bir çentik daha atmış kaybetme çıtasına

Kadında onu bir kere daha görebilir miyim düşüncesi

Adamda son bir kez öpseydim pişmanlığı…

Kadın sonbahara doğru yol almış

Adam ilkbahara yaklaşırken…

Yeniden yeşermez mi koparılan güller

Ağlasam duyulmaz mı oralardan

Hep kaybetsem

Mutlak başarısızlığı kazanmış olmaz mıyım? 

Şarkımı ben yazsam

Yine yalnız mı söylerim? 

Uyusam, unutur muyum

Uyansam sevinir miyim yaşadığıma? 

Bir kerecik olsun papatyalara inansam

Günüm geceme eşit olsa bir güncük

Yalnız olmasam azcık

Bir hayal kursam

Bir kerecik olsun gerçek olsa

Çelişkilerim yön bulsa

Sorunlarım olmasa

Ve bir soru sorsam

“Bir tek ben miyim bunları yaşayan? ”

“Ağlama” dedi yağmur

“Ağla ağla, bitmez ki…”

Duygu DİNÇ

31.12.05

*Cevap aradığım tüm sorularıma ithafen…', 'Sonbahardan esintiymiş adam İlkbaharın habercisiymiş kadın Ne ses, ne soluk varmış Yaz, soğuğu sevmiyormuş, Kış, güneşi… Bir yaprak daha sol...', ARRAY['Türk Edebiyatı','Şiir','Duygu Dinç']::text[], 8.5, '{"poet":"Duygu Dinç","poet_slug":"duygu-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/baharlar-bahane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm', 'kustum-sair-hilaloglu-oxxep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollara küstüm sana ulaşmıyor diye.

Dillere gücendim seni anlatmıyor diye.

Kurudu göz pınarlarım ağlayamam ah! 

Irmaklarla konuşmam sana akmıyor diye.', 'Yollara küstüm sana ulaşmıyor diye. Dillere gücendim seni anlatmıyor diye. Kurudu göz pınarlarım ağlayamam ah!  Irmaklarla konuşmam sana akm...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kustum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Gecen Geceler', 'sensiz-gecen-geceler-ali-kalafat-xcdpo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cehennem geceleri yaşanır sen bu şehirden gidince

Düşmeden geçilmez sensiz gereksiz vakitlere

Mavi kelebek hikayelerine göz yumulmaz 

Uyku baglanmaz sensiz gecen gecelere

Sen bilemezsin sen yokken bu şehirde ışıklar yanmaz

Sabahlar olmaz sen gidince

Sensizlik kalleştir 

Kahpedir güven olmaz sensiz gecen gecelere 

Bense sensiz gecen her arsız gecelenin ecdadı nikah kıyar

Her birini  bir gece koynuma alır; atarım yatagımdan

Sensiz gecelerde ben bir makasla sabah ederim

Kefen biçerim siyah çarşaf kaputbezinden gecelere

Parmagıma simsiyah ipler dolar

Tutsak mutlulukların ardından koşarım

Esaret çemberime bir taş daha örer

Kendi kaderime bir satır daha koyarım

Uykusuzlugum hafif gelir agır giden adımlarıma

Fervasız yürürüm sabahı olmayan gecelerin ardından

Gücüm yetmez topraga vuran yagmur tanelerine

Islatmaz gözlerimi soguk ellerimi yıpratmaz 

Bir kalbimi ıslatır İşte birde yüregimi

Sensizlige bir adım uzaklaştın bir gece daha

Bu ilk defa olmasada 

SON OLMASI UMUDUYLA...', 'Cehennem geceleri yaşanır sen bu şehirden gidince Düşmeden geçilmez sensiz gereksiz vakitlere Mavi kelebek hikayelerine göz yumulmaz  Uyku b...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-gecen-geceler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Sana Haramdır', 'sevda-sana-haramdir-sair-hilaloglu-it3dp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmem ki bu gönlüm niye ram olmuş sana.

Çektiğim çileler neden gam olmuş sana.

Sebep oldu gözlerin aşıklar katliamına,

Bu yüzden ya sevda haram olmuş sana.

Zulmüne sınır yokmuş alemde ancak,

Değmesin keyfine bu meram olmuş sana.

Kervan yola düzüldü gidiyormuş öteye,

Benden sonra hayat serencam olmuş sana.

Peşinde koşturdun yıllarca acımadan

Sorsana acep Hilaloğlu geda m’olmuş sana.', 'Bilmem ki bu gönlüm niye ram olmuş sana. Çektiğim çileler neden gam olmuş sana. Sebep oldu gözlerin aşıklar katliamına, Bu yüzden ya sevda h...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-sana-haramdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkolizm - 2', 'askolizm-2-tarik-erkutlu-y4xf2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın

Şen şakrak

Kadınları 

Oldular

Leylak kokulu

İsimsiz 

Zira hepsi hüzünlü 

Maceramdılar  belli  belirsiz....', 'Aşkın Şen şakrak Kadınları  Oldular Leylak kokulu İsimsiz  Zira hepsi hüzünlü  Maceramdılar  belli  belirsiz.......', ARRAY['Türk Edebiyatı','Şiir','Tarık Erkutlu']::text[], 8.5, '{"poet":"Tarık Erkutlu","poet_slug":"tarik-erkutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askolizm-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan', 'unutulan-sair-hilaloglu-2z2ol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgili zaten yok, dostan hatırlamaz.

Düşman sırttan vurdu yaran hatırlamaz.

Perişanız aşkından gönül olmuş harabe,

Bir gitti dönmüyor, canan hatırlamaz.', 'Sevgili zaten yok, dostan hatırlamaz. Düşman sırttan vurdu yaran hatırlamaz. Perişanız aşkından gönül olmuş harabe, Bir gitti dönmüyor, cana...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutulan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ki Türk''üz', 'biz-ki-turk-uz-mehmet-ayhan-gunaydin-1oqak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİZ Kİ TÜRK’ÜZ

Emrediyor dinimiz,

Böyledir de töremiz.

Başkasına kıyamdır,

Allah’a dır secdemiz.

M. Ayhan Günaydın.

    30 Aralık 2005 

          Ankara', 'BİZ Kİ TÜRK’ÜZ Emrediyor dinimiz, Böyledir de töremiz. Başkasına kıyamdır, Allah’a dır secdemiz. M. Ayhan Günaydın.     30 Aralık 2005      ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biz-ki-turk-uz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-sair-hilaloglu-dwkve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kan damlasın yarenden şerha şerha olasın

İbrahim’in narında bağrı yanık Zeliha olasın

Yusuf misali bir aşka giriftar ettin beni

Dilerim Allah’tan sen dahi Züleyha olasın

Gökte ararken yerde buldum seni ben

Nefesiyle hayat veren Hazret-i İsa olasın

Dertlere durak oldu gönül ölüme gebe

Dur, gitme sevdiğim dilime Musa olasın

Ok misali bakışınla deldin ya gönlümü

Gamzen okuyla vurdun bari deva olasın

Hilaloğlu sevdi seni gönül vadilerinde

Suyum kesildi heyhat, ille sevda olasın', 'Kan damlasın yarenden şerha şerha olasın İbrahim’in narında bağrı yanık Zeliha olasın Yusuf misali bir aşka giriftar ettin beni Dilerim Alla...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beddua-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Olmalıydı', 'son-olmaliydi-sair-hilaloglu-oobg1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Bu son” demiştin ne oldu böyle gönül? 

Neden söz yemekte ustasın söyle gönül? 

Hani yeminlerin verdiğin sözler n’oldu? 

Bir daha tatmayacaktın aşkı öyle gönül.', '“Bu son” demiştin ne oldu böyle gönül?  Neden söz yemekte ustasın söyle gönül?  Hani yeminlerin verdiğin sözler n’oldu?  Bir daha tatmayacak...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-olmaliydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyom', 'bilmiyom-nihat-yucel-vhvwg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğun içimde bir sonsuz acı

Nasılım nerdeyim kimim bilmiyom

Şaşmışım bu gönül nasıl dayanır

Bu kadar acıyla nasıl ölmüyom

Aşkın çiçeklenen acı içimde

Acunu görüyom başka biçimde

Sevinç buldum her acının içinde

Acısız sevinçle mutlu olmuyom

Ben bir garip kulum dertle doluyum

Ben ki dört mevsimde çiçek dalıyım

Sevenlerin kurbanıyım kuluyum

Yıllar var ki bir seveni bulmuyom

Aşkın yüreğimi söküp gidiyor

İçime zehrini döküp gidiyor

Nihat günden güne çöküp gidiyor

Zerre zerre tükeniyom kalmıyom

                                           06/74

Nihat Yücel', 'Yokluğun içimde bir sonsuz acı Nasılım nerdeyim kimim bilmiyom Şaşmışım bu gönül nasıl dayanır Bu kadar acıyla nasıl ölmüyom Aşkın çiçeklene...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilmiyom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez mi?', 'degmez-mi-sair-hilaloglu-dlsir', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ne güzellik ya Rabb! İnsan böyle mi olur? 

Narına düşürdü beni, bu yangına değmez mi? 

Gözlerinin gamzesi, ne afetmiş Allahım,

Kirpiğiyle okladı kalbi, bu ölüme değmez mi? 

Gazellerden kopmuş sanki şiir misali gözleri,

Aşkın sarhoşu oldum, bu serencama değmez mi? 

Cemalin cezp etti, mest oldum endamınla,

Hayret ki ölmedim, bu hasrete değmez mi? 

Ah, güzel kız hasret gözyaşlarım dinmese de

Gönlüm yine senindir, bu esarete değmez mi? 

Nedense gönül yurdum sevdasız olmuyor

Gözyaşlarıma rağmen bu kefarete değmez mi? 

Hilaloğlu’m üzülmem ben yeter ki hatırla,

Seninle ağladığım bu hayata değmez mi?', 'Bu ne güzellik ya Rabb! İnsan böyle mi olur?  Narına düşürdü beni, bu yangına değmez mi?  Gözlerinin gamzesi, ne afetmiş Allahım, Kirpiğiyle...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/degmez-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Değilsin', 'asik-degilsin-hilal-sakar-t2a2n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen aşık değilsin,

Aşıklığın alameti değil bu olanlar.

Belki adı konmayan aldanışlar,

Ya da gerçekten kaçışlar.

Sen aşık değilsin,

Aşık adamın kanı deli olur.

Yorulmak nedir bilmez,

Gece gündüz hiç farketmez.

İsterse fatih olur,

Gelir alır baştan başa şehri.

Fetihten kaçmaz ki,

Bu işin ehli.

Romayı yakmaz belki ama,

Yakar tüm bilinmezlikleri.

Güven dolar gözleri,

Bırakır sevda izleri.

Sen aşık değilsin,

Aşık adamın baharları olur.

Kucakladığı,sevdiği baharları,

Kış aylarını yaşamaz hep baharda durur.

Gülleri olur ellerinde,

Kırmızı en az ateş kadar.

Seviyorum demesede,

Attığı her adım sevda adınadır.

Aşık adam güneşle doğar,

Karışır toprağa,suya.

Bakarsın yeryüzüdür,

Gökyüzü de olur sevdalıya.

Sen aşık değilsin,

Aşık olan rüyalara alır sevdiğini.

Galiba bırakmaz elini,

Anlaşılmaz akıllı mı,deli mi.

Her yol bağdata varmaz,

Bir yolu olur sevenin.

Başlar ve gider,

Başka yollara sapmaz.

Sevdiğinin ismini bilir seven,

Niye sever,ne kadar sever bilir.

Kapalı kapıları olmaz sevenin,

Hepsi aşkla açılmış dikilir.

Ölüm demez aşık adam,

Ölüm doğmaktır bilir.

Ölümle gerçek sevgiliye gidilir,

Ve bekler mahşer kapısında sevdiğini.

Mahşer kapısı; 

Sevdalıların kavuşma kapısı bilinir.

Beklenir saadet kahramanları,

Hepsinin yürektedir adları.

Sen aşık değilsin,

Aşıklık aramak,bulmaktır.

Sevdiğiyle bir olmaktır,

Onu cana koymaktır.

Kalpte iki kişi durmaz,

Ya vardır,ya yok arası olmaz.

Bir ileri,iki geri adım sayılmaz,

Aşık adamın gülleri hiç solmaz.

Belki yerine koyuşlar,

Belki unutma çabaları.

Söylerken dahi yürek yanar,

SEN AŞIK DEĞİLSİN...

yağmurmah 2005', 'Sen aşık değilsin, Aşıklığın alameti değil bu olanlar. Belki adı konmayan aldanışlar, Ya da gerçekten kaçışlar. Sen aşık değilsin, Aşık adam...', ARRAY['Türk Edebiyatı','Şiir','Hilal Şakar']::text[], 8.5, '{"poet":"Hilal Şakar","poet_slug":"hilal-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/asik-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katlime Ferman', 'katlime-ferman-sair-hilaloglu-yp8db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce küfrettin aşkıma sonra iman eyledin.

Hasretinle gönlümü yine perişan eyledin.

Yakıp yıktın ya hileyle gönül köşkümü

Sonra dönüp aşk ile onda iskan eyledin.

Vefasızca zulmetme sultanım sen bana,

“Vaciptir” diye katlime ferman eyledin.

Cellat olsa da kara gözlerin aşığına,

Bir bakışınla bazen hayat ihsan eyledin.

Ah, mahperi reva mıydı çektiğim senden,

Yaktığın haristanı niye gülistan eyledin? 

Merhamet et Hilaloğlu’na cevri kaldırıp

Senden ayrı yerleri yine vatan eyledin.', 'Önce küfrettin aşkıma sonra iman eyledin. Hasretinle gönlümü yine perişan eyledin. Yakıp yıktın ya hileyle gönül köşkümü Sonra dönüp aşk ile...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/katlime-ferman-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılın Kutlu Olsun', 'yeni-yilin-kutlu-olsun-yusuf-onder-bahceci-4hzym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni yılın kutlu olsun,

Kutlu olsun, mutlu olsun,

Bütün dertler benim olsun,

Sen yeterki üzülme.

Ben ne yıllar görmüşüm,

Senin için ölmüşüm,

Sararmışım solmuşum,

Sen yeterki üzülme.

Üzülme sen sevdiğim,

Seni sensiz seveceğim,

Belki birgün öleceğim,

Sen yeterki üzülme.

Mutlu yıllar olsun sana,

Yeni yılda sitem sana,

Benim Dünyam yeter bana,

Sen yeterki üzülme.', 'Yeni yılın kutlu olsun, Kutlu olsun, mutlu olsun, Bütün dertler benim olsun, Sen yeterki üzülme. Ben ne yıllar görmüşüm, Senin için ölmüşüm,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeni-yilin-kutlu-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terazi', 'terazi-nurten-koroglu-ps4h5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine kısmetimmiş

ayrılığın ağır kefesinde 

yer almak

çok mu zor

şu terazinin 

hizasını ayarlamak

sözde adilsin (!) 

tam ayara elin uzandığında

neden hep bana düşüyor 

hop oturup

 hop kalkmak.', 'Yine kısmetimmiş ayrılığın ağır kefesinde  yer almak çok mu zor şu terazinin  hizasını ayarlamak sözde adilsin (!)  tam ayara elin uzandığın...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/terazi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümüzce Birbirimizi Sevelim Delice', 'omrumuzce-birbirimizi-sevelim-delice-huseyin-erdogan-60ibs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'keşke sevdiğimle girebilseydim

yeni yepyeni umut dolu bir yıla

şiirim ne olurdu yanında olabilseydim

seninle dolaşabilseydim kol kola

sakın hiç üzülme sen benimlesin

inan ki her anımda gölgem gibisin

hayallerimde tutacağım o harika ellerini

seveceğim bir tek beni gören gözlerini

zaman geçip de gece yarısı olunca

saat tamı tamına sıfır sıfırı vurunca

ne olursun uzat bana o güzel ellerini

ellerimiz havada kaynasın birbirine

cerrahlar bile ayıramasın ömrümüzce

dile o anda benimle olan hayallerini

kokla yüreğimdeki sana açan  güllerimi

gönül bahçemdeki çiçeklerim yalnızca senin için

bir tek yaprağı bile solmayacak ölünceye değin

zaten sen de benim yaşadığım tek mevsimimsin

şiirim bil ki sen kainatın en çok sevilen kadınısın

sen benim yüreğimdeki rengarenk baharımsın 

sevdiğim şiirim hasretim yeni yılımız kutlu olsun

ömrümüzce birbirimizi sevelim delice ne olursun

                                                     31.12.2005

                                                  Hüseyin Erdoğan', 'keşke sevdiğimle girebilseydim yeni yepyeni umut dolu bir yıla şiirim ne olurdu yanında olabilseydim seninle dolaşabilseydim kol kola sakın ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/omrumuzce-birbirimizi-sevelim-delice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorsun', 'agliyorsun-ufuk-bayraktar-cw5lt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne olduysa

oldu bitti her şey.

senin oldu bittiye getirdiğin gibi de değil; 

acıtarak! 

ağlıyorsun şimdi bir küskün akşama.

geri dönmüyor yol verdiklerin,

üzülüyorsun.

toprağa da gömsen özlemlerini

filizlenip bir zaman sonra

gözüne değiyor acıların,

aşk böyle bir şey işte...', 'ne olduysa oldu bitti her şey. senin oldu bittiye getirdiğin gibi de değil;  acıtarak!  ağlıyorsun şimdi bir küskün akşama. geri dönmüyor yo...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/agliyorsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-hikmet-aksu-qa40i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kümelenmeyin bulutlar, kümelenmeyin

Üstüme karanlık çökmesin artık.

İçimdeki ruhlar debelenmeyin,

Koskoca yıldızlar böbürlenmeyin,

Ey dertler, kederler kibirlenmeyin,

Gönlüm başka sitem çekmesin artık.

İstemem boşalmış mey kadehime, 

Saki başka içki dökmesin artık.

Değse de sakinin eli elime

Dokunsa da sazlar gönül telime,

Konmasa da bülbül hiçbir dalıma,

Garip gönlüm boyun bükmesin artık.

Durulsun coşkun sel, dinip, durulsun,

Varıp üzerime gelmesin artık.

Ters dönen feleğin çarkı kırılsın,

İsterse çathlasın toprak yarılsın,

Kenetlensin can, canana sarılsın,

Ayrılık ömrümü sökmesin artık.

Dost Kalemlerden:

Bir ses duydu göğnüm,ta derinden 

Sendedir ululuk,çağrışın bir başkadır, 

Bir haz buldu öz-üm,yel-i serinden 

Bendedir zâr-u zan,sevişin aşkadır, 

Lûtuf sendedir açına,her daim öğünüm, 

Evişim hazdan öte,vuslatın bir başkadır, 

Devranım canadır,akıl firar can evinde, 

Seyran etti bu cuş,coşuşum aşkadır..........Aliyy-ül Razân', 'Kümelenmeyin bulutlar, kümelenmeyin Üstüme karanlık çökmesin artık. İçimdeki ruhlar debelenmeyin, Koskoca yıldızlar böbürlenmeyin, Ey dertle...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aksu']::text[], 8.5, '{"poet":"Hikmet Aksu","poet_slug":"hikmet-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/artik-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Yüreğinin Devri**', 'yureginin-devri-burcu-alpaslan-guvenli-ko2cw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En güzel şiiri istemekti

günlerdir hatam….

Sevdadan mı ıslandı gözlerim,

sebebi nedir bu gün neşemin? 

Ellerine eldiven diye giydirdiğin düşlerinle

döndürdüğün yüreğinin

içi dışı kaç devirdir bilir misin? 

İzlerini takip ettin mi gözlerimin? 

ne yana eğilse gölgeleri

dinlendirmek için seni

yaratıldı yeşillerim…

Gözlerimin arasına aldığım resimlerin

saklandı

yaptığın evin çatısında

bak; 

______salkım saçak kanatlarında

……..31/12/2005 İstanbul (Düşhane’ m)', 'En güzel şiiri istemekti günlerdir hatam…. Sevdadan mı ıslandı gözlerim, sebebi nedir bu gün neşemin?  Ellerine eldiven diye giydirdiğin düş...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yureginin-devri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyalıyım', 'dunyaliyim-kamil-at-13a21', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cahil ulusum var diye insana kıyar

Irkçılık faşizm bunca bahane duyar

Kendi kardeşini memleketi soyar

Cahil uluscu olsun ben dünyalıyım.

Körler beylerine körce sınır çizmiş

Memleket sevdalısı yoksulu ezmiş

Hakkını isteyenleri kurşuna dizmiş

Cahil uluscu olsun ben dünyalıyım.

Ben görmedim bahsediyor nurdan

Fakirleri insanı ezer ecelide burdan

Onlara uyanlar insan öldürür ardan

Cahil uluscu olsun ben dünyalıyım.

İnsanlık aynıdır kimmiş olağan üstü

Cahiller başkayız diye kanlar kustu

Fikirleri gram etmez bilinmez dostu

Cahil uluscu olsun ben dünyalıyım.

Övünmem ben amerika ya başkası

Dünya aynıdır banane uzay aşması

Kamil bitti insanın dosta yaklaşması

Cahil uluscu olsun ben dünyalıyım.', 'Cahil ulusum var diye insana kıyar Irkçılık faşizm bunca bahane duyar Kendi kardeşini memleketi soyar Cahil uluscu olsun ben dünyalıyım. Kör...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunyaliyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş ey sevgili', 'yetis-ey-sevgili-ali-riza-unal-rg74q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine açtı ol perdeden günahı,

Döktü bir bir amel ile mübahı,

Unuttum görünce hayrı sevabı,

Gel ey canân öz od-um yanıyor.

Yitirdim bu bende mal-u evladı,

Bitirdin mezhebi,imanı  evradı,

Lütfu ayan ettin,galu bela ervahı,

Yetiş ey sevgili-tutuştu özüm yanıyor…', 'Yine açtı ol perdeden günahı, Döktü bir bir amel ile mübahı, Unuttum görünce hayrı sevabı, Gel ey canân öz od-um yanıyor. Yitirdim bu bende ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yetis-ey-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yalnızlık', 'adi-yalnizlik-birsen-ekiz-jimli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birden kapının sesi duyulur

Giden kim? 

Yorgundur, yaralıdır bedenin

Kendi geç kalmışlıklarına kızarsın

Onun erken kaçışlarına kızdığın gibi

Eyvahların da avutmaz ki seni

Onsuz öksüz kalan sesinden anlarsın

Tebessümündeki sahipsizliğinden anlarsın

Artık yalnızsındır

Beklemekten vazgeçersin

Işığı olmayan boşluğun yutar seni

Ağladığını bir tek sen duyarsın

Çırılçıplak bir gerçeğe uyanırsın

Rüyalarındaki bıçak izinden 

Azalan hayallerinden anlarsın

Kimsenin vakti yoktur seni dinlemeye

Anlatmaktan vazgeçersin

Artık yalnızsındır

Söylediklerini değil, söyleyemediklerini ezberlersin

Yaşadıklarını değil, yaşayamadıklarını hatırlarsın

Sen hayatını ona emanet etmek isterken

Onun giderken sana emanet ettiği menekşenin

Hüzne çalan renginden anlarsın

Issız evinin yoksunluk kokan ışığından anlarsın

Artık yalnızsındır

Dönüp bakmaktan vazgeçersin

Tutsak yolculuklarda fısıldayan yüzleri yitirirsin

Tren istasyonlarında geçen tesellisiz zamandan anlarsın

Çocukluk sevinçlerini denizin dalgınlığında unutursun

Maviye sevdalı martıların serseriliğinden anlarsın

Kurallarını hiç öğrenemediğin bu dünyada 

Bir başınasındır

Sormaktan vazgeçersin

Artık yalnızsındır

Birden kapının sesi duyulur

Giden kim? 

Giden sözlerindir, nefesindir

Giden yarınındır, hayallerindir

Geride kalanın adı yalnızlık.', 'Birden kapının sesi duyulur Giden kim?  Yorgundur, yaralıdır bedenin Kendi geç kalmışlıklarına kızarsın Onun erken kaçışlarına kızdığın gibi...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ekiz']::text[], 8.5, '{"poet":"Birsen Ekiz","poet_slug":"birsen-ekiz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/adi-yalnizlik-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yandım Kıyamam', 'sana-yandim-kiyamam-yusuf-onder-bahceci-6o6cc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni yanında bil sevdiğim,

Yanında bil, cânında bil,

Gözlerinde yaşlar varsa sil,

Sana yandım kıyamam.

Hep ağlayan ben olayım,

Senin yolunda Mecnun olayım,

Senin aşkınla yanıp kül olayım,

Sana yandım kıyamam.

Bu aşk ile yanmışım ben,

Hem yanmışım, ölmüşüm ben,

Benim sevgim tâ yüreğimden,

Sana yandım kıyamam.

Acep Mecnun''da Leyla''yı böylemi sevmiş,

Eğer sevmişse söyleyin cânımı vermiş,

Mecnun''mu daha çok Önder''mi sevmiş,

Sana yandım kıyamam.....', 'Beni yanında bil sevdiğim, Yanında bil, cânında bil, Gözlerinde yaşlar varsa sil, Sana yandım kıyamam. Hep ağlayan ben olayım, Senin yolunda...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-yandim-kiyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 12', 'd-siir-ve-sarki-sozleri-12-huseyin-avdic-b4tf9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.Vuruldum/(Trajikomik)

Bir kadın gördüm vuruldum.

Peşinden koştum yoruldum.

Kapısını çaldım kovuldum.

Ah, ben bu aşkta mahvoldum! 

*   *   *

Şimdi ne yapsam etsem? 

Kimin peşinden gitsem? 

Derdime kim derman olur? 

Bana bir aşk sunan olur? 

*   *   *

Ya Rab! Yol göster bana.

Onu çıkar karşıma.

Bir aşk koy şansıma.

Onu çıkar karşıma.

Not: TSM olarak bestelendi.

Berlin, Ocak 2004', '.Vuruldum/(Trajikomik) Bir kadın gördüm vuruldum. Peşinden koştum yoruldum. Kapısını çaldım kovuldum. Ah, ben bu aşkta mahvoldum!  *   *   *...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılınız Kutlu Olsun', 'yeni-yiliniz-kutlu-olsun-necati-keceli-8qil7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Takvimde kalmadı bitti yapraklar

     Yeni yılınız kutlu olsun dostlar

     Coşkuyla dolacak cadde, sokaklar

     Yeni yılınız kutlu olsun dostlar

     Mutluluk getirsin şehire, köye

     Şarkılar söyleyin hep doya doya

     Yeni yıla girin, güle, oynaya

     Yeni yılınız kutlu olsun dostlar

     Yoksula, fakire kapıyı açıp

     Türlü meyve suyu, içkiden içip

     Dost, akrabanızla kuş gibi uçup

     Yeni yılınız kutlu olsun dostlar

     Umutla beklesin yetimler dullar

     Onlara da çıksın paralar pullar

     Barış kardeşliği getirsin yıllar

     Yeni yılınız kutlu olsun dostlar

     Aranızda olmasın demirden perde

     Şarhoşken vurmayın kimseye darbe

     Sevgiyi arayın her gün her yerde

     Yeni yılınız kutlu olsun dostlar

     Necati diyor ki, demeyin aman

     Yeni yıla kaldı şurda az zaman

     Sevdiğiniz olsun yürekte her an

     Yeni yılınız kutlu olsun dostlar

      Tüm insanların  YENİ YILINI  KUTLARIM

     Necati KEÇELİ

     ADANA 31.12.2005', 'Takvimde kalmadı bitti yapraklar      Yeni yılınız kutlu olsun dostlar      Coşkuyla dolacak cadde, sokaklar      Yeni yılınız kutlu olsun d...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yeni-yiliniz-kutlu-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Te$ekküre Dâvet', 'te-ekkure-d-vet-huseyin-avdic-0urd9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Te$ekküre Dâvet

Yeni Yil''a kadar koca bir yil daha ya$atildiniz.

Medenî olmazsiniz, ya$amin $ükrünü yapmazsaniz.

Berlin, Aralik 2005.', 'Te$ekküre Dâvet Yeni Yil''a kadar koca bir yil daha ya$atildiniz. Medenî olmazsiniz, ya$amin $ükrünü yapmazsaniz. Berlin, Aralik 2005....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/te-ekkure-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Aşk1', 'i-stanbul-a-ask1-fatih-erdogan-mme6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dar,karanlık sokakta ışık.

Karanlığı delen bir çığlık,

Ardından karanlığa karışıp giden hıçkırık.

İstanbul,zordur sevene ayrılık.

Sanadır bunca hasret,bitmeyen çığlık.

Anla beni İstanbul,ağla benimle.

Ömrü bitiren,bedeni çürüten ayrılık.

Ya da tut ellerimi,dola kollarını boynuma

Hadi başını yasla omzuma.

Benim sevdiğim gibi:

Yani ölümüne sev sende beni.

Eğer,ayrı düşersek İstanbul

Dalgalarınla hırçınca kıyılarını döv

Unutma beni İstanbul! 

Gökyüzüne,boğaza bak.

Mazide beni gör.

Hasretim,büyük sevdam İstanbul.29/11/2004', 'Dar,karanlık sokakta ışık. Karanlığı delen bir çığlık, Ardından karanlığa karışıp giden hıçkırık. İstanbul,zordur sevene ayrılık. Sanadır bu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-a-ask1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** SeVdAm *', 'sevdam-i-brahim-dikmen-2-soxmy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım,

Sana nasıl kavuşacağım,

Ne zaman kollarımla saracağım seni.

Ellerin,ellerimde nezaman kenetlenecek

Güz yağmurları gibi,nezaman düşeceksin,

Nezaman yağacaksın gözlerime.

Nezaman kor olacak birbirine hasret dudaklarımız.

Hangi hazan sonrası yanacak bedenlerimiz.

Bilemiyorum ki! 

Sende bilmiyorsun değilmi? 

Sürgün olmuş bir aşkın,iki yakasında gibiyiz

Sen,yağmurları bekliyorsun ıslanmak için,

Bense,fırtınalar kopsun istiyorum hoyratça.

Beynimi kemirip duruyor söylediklerin

Sahi,gerçekten seviyormusun beni,

Gerçekten kalbindemiyim,ölecek kadar.

O zaman, 

Nedendir beklemelerin,neden bu suskunluğun,

Haydi,kır artık yüreğindeki prangaları,

Bırak girsin içeri,AŞKIM ve SEVDAM.

31/12/2005', 'Canım, Sana nasıl kavuşacağım, Ne zaman kollarımla saracağım seni. Ellerin,ellerimde nezaman kenetlenecek Güz yağmurları gibi,nezaman düşece...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdam-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizci Aşkı', 'denizci-aski-hikmet-aksu-mfdrk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklar aralı, soluk kesilmiş,

Gözler bakar! Görmez, dolanır durur.

Gemi fora etmiş yelkenlerini

Bir  mendil sahilde sallanır durur.

Ufukta dumandan incecik bir iz,

Çevresi gurupta allanı verir.

Kayalar üstünde masmavi deniz,

Bir yudum hasretle sanki yutulur.

Martılar uçuşur, düdük sesleri,

Kalpler atmakta ki kapı vurulur.

Yok eder beklenti yorgun hisleri,

Gözler serap görür, saçlar yolunur.

Ey! Beyaz  köpükler, yeşil yosunlar! 

Söyleyin, sizle dost nasıl olunur? 

Ayşe karşısında levent beklerken; 

O da karşısında bir nine bulur.', 'Dudaklar aralı, soluk kesilmiş, Gözler bakar! Görmez, dolanır durur. Gemi fora etmiş yelkenlerini Bir  mendil sahilde sallanır durur. Ufukta...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aksu']::text[], 8.5, '{"poet":"Hikmet Aksu","poet_slug":"hikmet-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/denizci-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemli', 'onemli-salih-ozalasan-lhp9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmiş geleceğin aynası derler

Oysa aynaya nasıl bakıldığı önemli

Bir yıl dört mevsim derler

Oysa mevsimlerin nasıl yaşandığı önemli

İlkbahar yaz aşk ayı derler

Oysa sevgide yürek çok önemli

Sonbahar kış hazandır derler

Oysa dört mevsim birlikte önemli

Yeni bir yıl eskisi gidiyor geçmişe

Acı tatlı anılarıyla yoğrulmuş iç içe

Eskisinde bulamadıklarımız uhde

Yenisini karşılıyoruz sevinçle

Dilerim yeni yıl yenilikler

Eskisinde olmayan güzellikler

Sağlık sıhhat mutlu birliktelikler

Verecekse olsun eskisinden önemli

Mutlu değilsek tarifsiz mutluluk

Sevgisizsek yürek dolusu sevgi

Sağlık esenlik daima doğruluk

Yaşatsın ki olsun eskisinden önemli

Sevdiklerimiz yüreklerimizde yaşasın

Sevenler yüreklerinde yaşatsın bizleri

Gözümüz asla ardımızda kalmasın

Yılları yaşamasını bilmek her şeyden önemli

Y.Tarihi 31-12-2005 Saat 13.30

Salih ÖZALAŞAN', 'Geçmiş geleceğin aynası derler Oysa aynaya nasıl bakıldığı önemli Bir yıl dört mevsim derler Oysa mevsimlerin nasıl yaşandığı önemli İlkbaha...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/onemli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Oğuzuz Türkmen''iz', 'biz-oguzuz-turkmen-iz-semsettin-veli-erbilli-yunhc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oğuzlara dayanan derin soylu adım var

Tarihim şen şerefli her günde bir yadım var

Savaşları hep zafer bugüne bin dadım var

Savaşta yelinmeyen Türkmen''iz biz Türkmen''iz

Atalarmızdan aldık mavidir bayrağımız

Gücde güçlü sözde bir bizim yeni çağımız

Onların sayasından yakındır ırağımız

Savaşta yelinmeyen Türkmen''iz biz Türkmen''iz

Şehitliği isteriz zillete duşmanındır

Irak yurdu yurdumuz başı dik Türkmenindir

Tarihini yenilen görülen pışmanındır

Savaşta yelinmeyen Türkmen''iz biz Türkmen''iz

Milletin kırılmayan sert olan dayağıyız

Onlar büyük baştılar bizlerde ayağıyız

Tarih boyu yaşatan bu yolun yüz ağıyız

Savaşta yelinmeyen Türkmen''iz biz Türkmen''iz

Tarihmizin uğrunda gururla baş koyarız

Bizlere yan bakanın gözlerini oyarız

Biz oğuzız Türkmen''iz yiğitlikte soy eriz

Savaşta yelinmeyen Türkmen''iz biz Türkmen''iz', 'Oğuzlara dayanan derin soylu adım var Tarihim şen şerefli her günde bir yadım var Savaşları hep zafer bugüne bin dadım var Savaşta yelinmeye...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-oguzuz-turkmen-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-seyfet-bozcali-ecxcm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi bir gül gibidir,bakım ister her zaman.

Hangi gönüle girerse,ümit saçar o zaman...

Sevgi bir su gibidir,hayat verir her yana,

Sevgi bir kişiye değil,gerek bütün Cihana...

Sevgi bir güneş gibidir,ısıtır sarar insanı.

Hayat verir yeryüzüne,hazırlar imkanları...

Sevgi bir ay gibidir,doğunca güler yüzlü,

Aydınlatır gönülleri,kalpleri koymaz pürüzlü...

Sevgi ümit kaynağıdır,kazandırır her şeyi.

Sevgisiz yaşamaktansa,yaşamamak daha iyi...', 'Sevgi bir gül gibidir,bakım ister her zaman. Hangi gönüle girerse,ümit saçar o zaman... Sevgi bir su gibidir,hayat verir her yana, Sevgi bir...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-235-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılınız Kutlu Olsun', 'yeni-yiliniz-kutlu-olsun-nurten-altinok-eymlb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                      



Merhaba,

Keşke hepinizin ismini buraya yazabilseydim tek tek.

Göndermiş olduğunuz yılbaşı kutlama iletilerinize tüm yüreğimle teşekkür ediyorum.

Hepiniz sağolun, hatırladığınız ve saydığınız için.

Hepiniz sağ olun düşündüğünüz ve aklınızdan geçirdiğiniz için

Hatırlayan ve hatırlamayan, kutlayan ve kutlamayan ve sen bu iletiyi okuyan gönüldostu:

Yeni yıl, ne istiyorsanız onu getirsin sizlere...

2006. şiiri yazacağınız bir yıl olsun...

Herşeyden önemlisi sağlıkla gelsin, huzurla gelsin..

Dünyamızda ve Türkiye''mizde savaşsız, doğal felaketsiz, açlığın ve acının sona ereceği bir yıl olsun 2006

Allah dileyene dilediğini versin...

Nice sağlıklı yıllara...

Sevdiklerimizle...



 

Olmadı şikayetim 

Varlığa, yokluğa

Olmadı şikayetim

Açlığa, tokluğa

Gurbeti sıla belledim

Yıldızlar yarattım gökyüzünde her bir bakışa

Umutlar, dar zamanlarda

Elleriniz ellerimde varoldukça

Şükürler olsun Tanrım

İnsan yaratıldığıma

Şükürler olsun Tanrım

Yarattığın herşeye saygı duyduğuma

Baktığımı görmeyi sağladığına

İşittiğimi duymaya

Dar zamanlarımdaki HUZUR''una şükürker olsun

SANA ŞÜKRETMEMİ SAĞLA

Bana ve tüm dünyaya

Her yeni gelene umutla sarıldık

Dünyada mekan

Ahirette iman

Her yeni geleni

Güzel dileklerle karşıladık

SEN İNSANLIĞIMIZDAN UTANDIRMA....

Nice Yıllara

Sevgiyle

Barışla

Sağlıkla

2006 hayırlara vesile olsun...

NURTEN ALTINOK', 'Hoşgeldiniz                         Merhaba, Keşke hepinizin ismini buraya yazabilseydim tek tek. Göndermiş olduğunuz yılbaşı kutlama iletil...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yeni-yiliniz-kutlu-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Yerde', 'orta-yerde-ali-aldemir-ls0s6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir elimde mavzer

Ah bir elimde sevdan

Bu diyardan çekip gitmek var ya; 

Her yol çıkmaz sokak gözlerinde

Ne zor, ne müşkülmüş meğer

Yüreğimdeyken vurgunların

Yarı parçan bir kırık gülle

Orta yerde kalması yüreğin', 'Bir elimde mavzer Ah bir elimde sevdan Bu diyardan çekip gitmek var ya;  Her yol çıkmaz sokak gözlerinde Ne zor, ne müşkülmüş meğer Yüreğimd...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/orta-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Hırsızı', 'gonul-hirsizi-mehmet-sait-akkus-31q9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aklımı benden alan

Bu bedeni eden talan

Senden başka herşey yalan

Oy benim gönül hırsızım

Günlerdir uyuyamadım

Yüreğimden atamadım

Senden asla opamadım

Oy benim gönül hırsızım

Senin ismini anınca

Ateş bacayı sarınca

Ta yüreğimden yakınca

Oybenim gönül hırsızım

Oy benim gönül hırsızım

İçimdeki ince sızım

Ağlıyorum gönül sazım

vay benim gönül hırsızım', 'Bu aklımı benden alan Bu bedeni eden talan Senden başka herşey yalan Oy benim gönül hırsızım Günlerdir uyuyamadım Yüreğimden atamadım Senden...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-hirsizi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzatmalara Kaldık', 'uzatmalara-kaldik-mehmet-sait-akkus-4d1gv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baksana ömür yavaşça geçiyor

Farkına varmadan geçen zamanın

Tanıdıklar birer birer göçüyor

Faydası yok arkadaş ağlamanın

Şöyle oturup aynaya bakınca

Kimbilir neler geçiyor içimizden

Gidenleri birer birer anınca

Hüzün,ve yaşlar akar gözümüzden

Ne yapalım kaderde varsa olmak

Oturup üzülmek boşuna olur

Boşunadır,vaktidir artık dolmak

Gideni bekletmek boşuna olur', 'Baksana ömür yavaşça geçiyor Farkına varmadan geçen zamanın Tanıdıklar birer birer göçüyor Faydası yok arkadaş ağlamanın Şöyle oturup aynaya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzatmalara-kaldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Duygu Bir Arada', 'i-ki-duygu-bir-arada-hikmet-aksu-it3e8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek kolay iş değil

Yürek,sabır; aşk gerek

Üzmek kolay,

Daha kolay kalp kırmak,

Kalp değil de taş gerek.

Bir yudum muhabettir

Loş ışıklar altına sığınış,

Silinir kafalardan günün sitresi,

Daha yakın vücutlar, 

Daha sakin duygular...

İştenlikle,''canım demek'' ne güzel,

ne güzel ele ele tutuşabilmek.

Hayat sevilir her konumda; 

Boş vermek değil,inanmak gerek.

Işıklar aniden söner.

Kadehler devrilir masalara,

Susar müzik,kesilir muhabbet,

Ne kalır sabaha? 

Zerih olmuşsa akşamlar...

Her şeyi sevmektir sevgi,

Mutluluk gün ışığı gibi.

Yayılır her yana...

Bir tekin sevdasına,

Bir çoğu sevmek gerek.

O zaman renklenir solgun hülyalar,

Güller gerçek; mor,beyaz,al...

Saksılarda çiçekler nazlı,

Açmış perdeleri sevgili

Ardına kadar.

Sözler şarkı gibi ruhlara damlar.

Sevda haykırıştır,naradır

Fısıltı değil, acemi

işitmek değil, özde 

Duymak,hissetmek gerek.

Kadehler doğrulur masalarda,

Tambur hüzünlü, daha hüzünlü keman.

Kahkahalar yükselir,kafalar duman.

Ne çabuk tükenir koskoca gece,

Ne de çabuk gelir sabahlar

Çirkinler bile güzeldir,

Olanaksız, kusursuz olabilmek.

Ne anlamı olurdu gülün dikensiz; 

Sevginin çilesiz  olamayacağını

Unutmamak gerek.

Dikenle gülü, 

Güzelle çirkini,

Kötü ile iyiyi,

İnsanı sevmek gerek, 

İnsanca sevmek gerek.', 'Sevmek kolay iş değil Yürek,sabır; aşk gerek Üzmek kolay, Daha kolay kalp kırmak, Kalp değil de taş gerek. Bir yudum muhabettir Loş ışıklar ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Aksu']::text[], 8.5, '{"poet":"Hikmet Aksu","poet_slug":"hikmet-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/iki-duygu-bir-arada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzken Mutluluk', 'mutsuzken-mutluluk-serkan-asilbas-ztcoc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala çok zor sensizliği yaşamak,

Sevmeyeceğine dair etkisini artıran umutsuzluk,

Benliğimi bütünüyle sarıyor.

Kimseye söyleyemiyorum seni hala sevdiğimi,

Karanlıktan başka.

Karanlık sırdaşım olmuştu çünkü.

Hayatında biri olabilirdi biliyorum.

Ellerini başkası tutabilir,

Gözlerine başkası bakabilir,

Dudaklarını bir başkası öpebilirdi.

Kahroldum bunları düşününce,

Gözlerim yaşarıyor ağlayamıyorum.

Tutuluyorum sadece.

Of of,

Aynı yer ve zamanda olsak bile,

Sana bir nefes kadar yakın,

Ve güneş kadar uzağım.

Seni görmek daha çok acı veriyor artık,

Hiç bir şey olmamış gibi davranıyorum.

Sadece arkadaş gibi oluyorum.

Kimse farketmesin diye,

Sana güneş gözlüklerimin arkasından bakıyorum.

Ela gözlerini sonsuza dek kaybettiğimi biliyorum.

Mutsuzken mutluluğu yaşıyorum', 'Hala çok zor sensizliği yaşamak, Sevmeyeceğine dair etkisini artıran umutsuzluk, Benliğimi bütünüyle sarıyor. Kimseye söyleyemiyorum seni ha...', ARRAY['Türk Edebiyatı','Şiir','Serkan Asılbaş']::text[], 8.5, '{"poet":"Serkan Asılbaş","poet_slug":"serkan-asilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mutsuzken-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürçü lisan ettikse af ola!', 'surcu-lisan-ettikse-af-ola-nazan-i-zmirli-hcsho', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sürçü lisan ettikse af ola........

Didiştik durduk, pişmanlıklar olsada, aklımız geride kalsada,dönüpte yakalayamayacağımız..... eski yılla..........Bize küsüp, güzel  anılarımızı 

bizden almaz inşallah...............................

Eskisi   olmayanın   yenisi   olur   mu   dostlar.! 

Güzeliyle çirkiniyle,acısıyla  tatlısıyla, doğrusu yanlışıyla,  anılar  tecrübedir bizleri   yeniliklere  taşıyan. 

Duygular işte durulup sonra kabaran...kalemleri grafik  çizgileri gibi yazdıran.

Yılbaşı neyimize desekte; bir sonun   bir başı, dönüp duruyor işte. Bizde iste isteme bu düzen içersinde, birer ilmeğiz, gidip geliyoruz  cambazlarlar gibi

ipin üzerinde................

Bazen düğüm, bazen   kör  düğüm  oluyoruz.....................bazen  bir  dilek 

ipi gibi  sulara  karışıp..................belki de  bir   dağın   zirvesinde  erişilmiş hazzın   içinde............  kaybolmak istiyoruz......................

Düzen içinde  düzensizlikler  yıpratıyor  sayfalarımızı, koparıyor bağlarımızı

yinede  umutlarımızı   yitirmiyoruz.  Yaşama   sevincimizi     öldürmüyor.......

her  yeni  gün  için  GÜLÜMSÜYORUZ............................................................

''bana kalpten gülümsemeyi öğreten,kalbimdeki en güzel  varlığa sonsuz teşekkürler...........................''

Bir   imtihansa   bu  yaşam,  bir  öğrenci   bir   öğretmen   rolünde   yaşamı  paylaşarak   sunan   oyuncular   olmalıyız.

Günü, saati, dakikayı,  saniye   ve  nefes    alabilecek  bir  saliseyi hissedebiliyorsak,   yaşayabiliyorsak    hakkıyla....................yarınlar

bizim  neden olmasın.................bizler    varoldukça............................

Şu an  ayrılmak  çok  zor, yalnızlığımı  paylaşan  kalem  olmuş   tuşlardan....

Ne kedar kalabalıklar içinde yalnız kalsakta zaman zaman, bizlerle hayat

bulan   dostlarımız   var,  kalabalıklarımız  var, hatırladığımızda  mutlu olan

kutlamalarımızı,sunduğumuz çiçeklerimizi sabırsızlıkla sevgiyle alan alan.....

Kutlu olsun yeni  yılları..........diyelim..............

Bu şehirde; Kış günü  baharı yaşatan  nergisleri kucak  kucak gönderiyorum sizlere............................

Dileklerinize yıldızlar yağsın........................... 

Sağlıkla  nice yeni yıllara sevdiklerinizle..................

SAYGILARIMLA

31.12.2005-antalya', 'Sürçü lisan ettikse af ola........ Didiştik durduk, pişmanlıklar olsada, aklımız geride kalsada,dönüpte yakalayamayacağımız..... eski yılla....', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/surcu-lisan-ettikse-af-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Aşk', 'gercek-ask-cenk-aksal-pk96l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadının kalbi

Mezar gibidir...

Erkeğin kalbi..

Beş yıldızlı,

Otel gibidir...mi? 

31/12/2005

Zehra Yüce', 'Kadının kalbi Mezar gibidir... Erkeğin kalbi.. Beş yıldızlı, Otel gibidir...mi?  31/12/2005 Zehra Yüce...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gercek-ask-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Korkusu', 'allah-korkusu-timur-i-likan-uonab', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbinde olmalı hep ALLAH korkusu

Ondan korkmayanı sarar gaflet uykusu

(31 Aralık 2005/ İstanbul)', 'Kalbinde olmalı hep ALLAH korkusu Ondan korkmayanı sarar gaflet uykusu (31 Aralık 2005/ İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/allah-korkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-ali-aydogan-ed859', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir duyduklarım Yasadıklarım 

kaldım gülüşünde yarım yarim

sevdim seni bir mavi düş gibi

hayal oldum düş oldum 

Ey hayat şimdi neredesin

nerenin bilinmezindesin

soguk burası üşüyorum 

gözyaslarımda kaldı gülüşlerim

sende saklı kaldı hayallerim

gözlerinde kaldı düşlerim 

gel düş yollarıma gel yollarıma

beni sensiz seni bensiz bırakma

kırdım seni biliyorum

ömrüm senin diliyorum istiyorum

seni kırmak istemezdim 

senden özür diliyorum Hayat', 'Nedir duyduklarım Yasadıklarım  kaldım gülüşünde yarım yarim sevdim seni bir mavi düş gibi hayal oldum düş oldum  Ey hayat şimdi neredesin n...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-276-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Güzelsin Bayrağım', 'sen-guzelsin-bayragim-seyfet-bozcali-u4zn8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baharda gül,gülde bülbül güzeldir.

Toprakta çim,çimde çimen güzeldir.

Vadide sis,dağda orman güzeldir.

Tüm bunlardan sen güzelsin bayrağım...

Kalpte sevgi,sevgide kalp güzeldir.

Tende iman,imanda can güzeldir.

İbadetle geçen zaman güzeldir.

Tüm bunlardan sen güzelsin bayrağım...

Derede su,suda canlı güzeldir.

Şehitte kan,kanda şehit güzeldir.

Vatan için vereiel can güzeldir.

Tüm bunlardan sen güzelsin bayrağım.

Bedende baş,başta akıl güzeldir.

Bilgide yol,yolda bilgi güzeldir.

Ömürde can canda canlı güzeldir.

Tüm bunlardan sen güzelsin BAYRAĞIM...', 'Baharda gül,gülde bülbül güzeldir. Toprakta çim,çimde çimen güzeldir. Vadide sis,dağda orman güzeldir. Tüm bunlardan sen güzelsin bayrağım.....', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-guzelsin-bayragim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yangınları', 'gul-yanginlari-i-hsan-kurt-bwqeg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El konulmuş sevgiler, sevgiliye sitemkâr

Kırılmış bir yüreğin tamburunda gezinir.

Duyulanlar acı, çalınan ise nevâkâr

Savrulan küller, gül yangınlarında bilinir.

Gözyaşı dökülmüş hüzün canlanır sesimde..

Bir poyrazın taraklarında saçlar çözülür,

Kirpiklere cemre düşer beşinci mevsimde.

O ne aşktır, yangındır ki sinsice süzülür

Sırların beni ifşâ ettiği hevesimde.

Mahcupluğun burcunda gül avlayan bulunmaz..

Çağlayanlar soluğudur, yüreğimden gelir.

Kışların hazanına yaprak bile bulunmaz.

Ne zaman kapı çalınacak, kim bilebilir? 

Çareyi gül yangınları yer, çare bulunmaz.

Güllerin kül ettiği hazan bahçelerinde..', 'El konulmuş sevgiler, sevgiliye sitemkâr Kırılmış bir yüreğin tamburunda gezinir. Duyulanlar acı, çalınan ise nevâkâr Savrulan küller, gül y...', ARRAY['Türk Edebiyatı','Şiir','İhsan Kurt']::text[], 8.5, '{"poet":"İhsan Kurt","poet_slug":"i-hsan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gul-yanginlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onüçüncü Renk', 'onucuncu-renk-bahaettin-kabahasanoglu-0pygu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onüçüncü  Renk

seni kimse görmedi mi 

bugüne kadar

ne güzellik

bu ne çalım

seni can yakan

sanki kırlara düşmüş

onüçüncü renk

yağmur kokan

rüzgar kokan

menekşe kokan

seni kimse görmedi mi

bugüne kadar

tebessümün

ve sohbetin

kalbime akan

hayallerimi süsleyen

ufku delen yar

rüyalarıma hoş geldin 

sonsuza kadar', 'Onüçüncü  Renk seni kimse görmedi mi  bugüne kadar ne güzellik bu ne çalım seni can yakan sanki kırlara düşmüş onüçüncü renk yağmur kokan rü...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Kabahasanoğlu']::text[], 8.5, '{"poet":"Bahaettin Kabahasanoğlu","poet_slug":"bahaettin-kabahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onucuncu-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-bahaettin-kabahasanoglu-d0ic1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen yoktun

sen yoktun

kimse yoktu

kalbim bomboştu

içim bir hoş

gönlüm bir hoştu

sen yoktun

bugün yoktu

yarın yoktu

içimdeki çocuk sarhoştu

sen yoktun

yol yoktu

yolcu yoktu

bir gün sen çıktın karşıma

o gün

o gün çok hoştu', 'sen yoktun sen yoktun kimse yoktu kalbim bomboştu içim bir hoş gönlüm bir hoştu sen yoktun bugün yoktu yarın yoktu içimdeki çocuk sarhoştu s...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Kabahasanoğlu']::text[], 8.5, '{"poet":"Bahaettin Kabahasanoğlu","poet_slug":"bahaettin-kabahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yoktun-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah İçin Yaşa', 'allah-i-cin-yasa-timur-i-likan-e1srd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sâdece ve sâdece hep ALLAH için yaşa

Uyma nefsine,  olma şeytan elinde maşa

(31 Aralık 2005/ İstanbul)', 'Sâdece ve sâdece hep ALLAH için yaşa Uyma nefsine,  olma şeytan elinde maşa (31 Aralık 2005/ İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/allah-icin-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Aşk2', 'i-stanbul-a-ask2-fatih-erdogan-vzquw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerçek aşkların başladığı,

Büyük sevdaların yaşadığı şehir.

Yüreğimdeki korun alevlendiği,

Sevdamın,sevdaların başladığı yer.

Aşkımın yaşadığı sehir:İSTANBUL

Ben sana aşığım,güzel şehir

Mevlam ne güzel yaratmış

Atam şahane donatmış

Yapıların eşsiz sanatmış.

Aşığım sana güzel şehir

Yolarına düştüğüm,

Duygulanıp,coştuğum şehir:

Güzel İstanbul.01/12/2004', 'Gerçek aşkların başladığı, Büyük sevdaların yaşadığı şehir. Yüreğimdeki korun alevlendiği, Sevdamın,sevdaların başladığı yer. Aşkımın yaşadı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-a-ask2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Değil', 'belli-degil-seyfet-bozcali-mmo71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık önümüzü göremez olduk,

Yokuş belli değil,düz belli değil.

Hayat akışında kontrölsüz kaldık,

Bakar lakin gören  göz belli değil...

Kesmiş bıyığını uzatmış saçı,

Takmış küpesini,giymiş sitreci,

Bacı desem duyarmı ki utancı,

Oğlan belli değil,kız belli değil...

Erkek kadın konserlere koşarlar,

Müziğin sesiğle ağlar,coşarlar,

Çılgın gibi sanatçıya koşarlar,

Hasta belli değil,sağ belli değil...

Sevgiden,saygıdan haberi olmaz,

Gününü gün eder,hak hukuk bilmez,

Yaban atı gibi kontrole girmez,

Kontrolü sağlayan yer belli değil...

Seyfet der ömrünü verme hebaya,

Hürmet gösterelim ana-babaya,

Bu ortamda çok muhtacız duaya,

Çünkü gidilecek yer belli değil...', 'Artık önümüzü göremez olduk, Yokuş belli değil,düz belli değil. Hayat akışında kontrölsüz kaldık, Bakar lakin gören  göz belli değil... Kesm...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/belli-degil-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın', 'sen-vardin-bahaettin-kabahasanoglu-ebmab', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen vardın	

bazı şiirlerimde sen vardın

bir sözcük bir mısra kadar

bazı şiirlerime sığmazdın

şiirden büyüktün

dünya kadar

bazı şiirlerimde  sen vardın

şiirin bir yerinde ağlardın

sular seller kadar

sulu gözün biriydim ben de

sayfalara yağmur yağardı

yüreğime kar

üşürdü ellerim ayaklarım

uzaklığın kadar

bazı şiirlerimde sen vardın

düşünürdüm düşünmediğin kadar

ateş basardı soğuk gecelerde

rüyalardan yol bulurdum

meleklerden kanat

süzülürdüm karanlığın köründe

seni arardım

inadına inat

ne bulunmaz hint kumaşıydın

işim zor

yolum uzun

çin’e maçin’e kadar', 'sen vardın	 bazı şiirlerimde sen vardın bir sözcük bir mısra kadar bazı şiirlerime sığmazdın şiirden büyüktün dünya kadar bazı şiirlerimde  ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Kabahasanoğlu']::text[], 8.5, '{"poet":"Bahaettin Kabahasanoğlu","poet_slug":"bahaettin-kabahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-vardin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı', 'yilbasi-mevlut-bicik-t5h7u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Íşte bugün ikibinbeş senesinin son günü

Dünyânın her tarafında bir hareketlilik var

Hesâp gününden korkanlar düşünür dünü

Özünü unutmuş olanlar, olmuş kabukla yar.

Ramazan’da,kurban’da huzur bulamıyanlar

Zannettiler ki! yılbaşın’da buluruz huzur

Îmân-ü Íslâm ile gönül bağını kuramıyanlar

Pişirirler Hindi’yi, yanıbaşında ise şişeler durur.

Senenin son gününde bu meş’um gecesinde

Yenilir hindiler, habira içilir, çekilir kafalar

Isyânlar okunuyor,amellerin her bir hecesinde

Bu manzaraya şâhit olan  mü’min üzülür,afalar.

Kesilmiştir yine milyonlarca masum çamlar

Kimseler görmez,duymaz ve de yazmamıştır

Patlatılır bombalar,saat 12 yi gösterdiği anlar

Ínsanlık dünyâ târihinde bu kadar azmamıştır.

Aman Yâ Rab ne korkunç inkılâp olmuş gönüllerde

Nice müslümânım diyenler oluveriyor bir gecede gavur

Yazılanlar kağıt’da, söylenenler ise kalmış dillerde

Hânemizden,gönlümüzden bu gecenin mel’anetini savur.

Mevlüt Bicik

31.12.2005  saat 15.18

Esslingen', 'Íşte bugün ikibinbeş senesinin son günü Dünyânın her tarafında bir hareketlilik var Hesâp gününden korkanlar düşünür dünü Özünü unutmuş olan...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yilbasi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Hayatıma', 'hosgeldin-hayatima-volkan-yoruc-suo1x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoşgeldin hayatıma

Buyur geç kuytu anılarıma

Sakınma 

Aç gözlerini bak çekinmeden bakışlarıma

Anlat

Yaşamakta olduğun tüm hayatınla

Hoşgeldin hayatıma

Suskun kalma

Bu renkler senin için 

Unutma

Ben durulmam dinleyenim olduktan sonra

Sakın olaki bıkma

Hoşgeldin hayatıma

Ve hoşbulduk yanıma oturduktan sonra', 'Hoşgeldin hayatıma Buyur geç kuytu anılarıma Sakınma  Aç gözlerini bak çekinmeden bakışlarıma Anlat Yaşamakta olduğun tüm hayatınla Hoşgeldi...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hosgeldin-hayatima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl mı bıraktı bizde şu gurbet', 'akil-mi-birakti-bizde-su-gurbet-mikdat-bal-f2w6g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akıl mı bıraktı bizde şu gurbet

Kafa ayrı, gövde ayrı kol ayrı

Muhtevası zehir dolu bu şerbet

Suyu ayrı, şeker ayrı, bal ayrı

Memlekette yeşil bahçeler, bağlar

Parçalı bulutlu, dumanlı dağlar

Çaylar şırıl şırıl denize çağlar

Oyuk ayrı, oluk ayrı, yol ayrı

Hastalanıp fıttıranlar çoğunluk

Cadde, sokak, trafik, çevre yoğunluk

Bir biri üstünde cansız yığınlık

Hayvan ayrı, insan ayrı, kul ayrı

İrtibat yok, iltifat yok, ilgi yok

Anadan babadan yârden bilgi yok

Soranlara derim evet bil ki yok

Durum ayrı, tavır ayrı, hal ayrı

Arzularım her yazını  kışını

Hayalimde kaşkarların düşünü

Anam silsin gözlerinin yaşını

Dostluk ayrı, komşu ayrı el ayrı 

Mikdat’ım ben içim yara dış yara

Gerçek yara, hayal yara, düş yara

Zaman yara, bahar yara kış yara

Bayrak ayrı, vatan ayrı il ayrı', 'Akıl mı bıraktı bizde şu gurbet Kafa ayrı, gövde ayrı kol ayrı Muhtevası zehir dolu bu şerbet Suyu ayrı, şeker ayrı, bal ayrı Memlekette yeş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/akil-mi-birakti-bizde-su-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Aşk3', 'i-stanbul-a-ask3-fatih-erdogan-vftmb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul''u özledim,

Martılara simit atmayı

Vapurla boğazı geçmeyi...

Bir bardak çay içmeliyim Emirgan''da

Simit yemeliyim Çamlıca''da

Eski  nağmelerin kollarında seyretmeliyim boğazı

Tarihin arasından geçerek varmalıyım Sultanahmet''e

Yalvarmalıyım Rabbim''e 

Allahım öyle bir yapı ki nurdan 

Ayrılmayayım burdan

Tarihi koklamalıyım,

Yenicaminin güvercinlerini yemlemeliyim

Karacaahmet''te huzura erip

Sana burada kavuşmalıyım İstanbul.', 'İstanbul''u özledim, Martılara simit atmayı Vapurla boğazı geçmeyi... Bir bardak çay içmeliyim Emirgan''da Simit yemeliyim Çamlıca''da Eski  na...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-a-ask3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'XXX Yılın Tüm Yükü Sırtımda', 'xxx-yilin-tum-yuku-sirtimda-zeki-ergin-i45wb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gün 2005 yılının son günü

yılın tüm yükü sırtımda

acımasızlığıyla eziliyorum

suskunluk yakışır mıydı

haykırmalıydıım haksızlıklara

ancak neresinden başlamalıyım

ver elini 2006 

sevecenliğimi sakladım sana

umudumu yeşert

dert sıkıntı

öfke yumağı olan 

dünyaya bir gülümse

_erenköy 31aralık2005', 'bu gün 2005 yılının son günü yılın tüm yükü sırtımda acımasızlığıyla eziliyorum suskunluk yakışır mıydı haykırmalıydıım haksızlıklara ancak ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yilin-tum-yuku-sirtimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HiKaYeLeRiM PErDE 1', 'hikayelerim-perde-1-aykut-karaman-kr58h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karartılar var... Sislerin arasında, uzakta... Birbirlerinden ayıramıyorum aslında. Bir hareketlilik, planlanan bir şey. Hiç durmuyorlar... İnce bir siluleti aralarında belirliyorum. Kendime hedef seçer gibi. Eğer onu izlemeyi başarabilirsem, ufak ufak farkları ayırmam ve hepsini takip etmem belki mümkün olabilir. Bu tıpkı, karanlıkta, hiçbir şey göremezken yaşadığınız panik gibi. Önce ne olduğunu tanımlayamadığınız bir parça görünür olur. Ortamın karanlığından daha koyu bir ton. Sanki bir sihir gibi o farklı ton şekillenmeye başlar. Karanlığın içinde daha karanlık olanı görebiliyor olmak gariptir başlarda. Ama ilk şaşkınlıktan çıkıp düşünmeye başladığınızda aslında daha koyunun olmadığını anlarsınız. Koyu yoktur, açık vardır. Koyunun görünmesinin sebebi açıktır. Tıpkı şu anda hareketlerini sonsuz bir dikkatle takip ettiğim ince karartının görünebiliyor olmasını sağlayan sis perdesi gibi... Hiç sonlanmayacak bir oyunu izler gibiyim. Alkış yok, uğultu yok. İfadesiz bakan bir sürü göz ve düzenli alınıp verilen nefesler... Zaman zaman kulağı rahatsız eden bir hırıltı, kurumuş boğazların, zorlanan beden kölelerinin ifadesi. Acaba benim gibi düşünmekteler mi? Onlar da, kendilerine bir hedef seçtiler mi? Gittikçe anlamsızlaşan bu hareketliliği izlerken, olan biteni anlamak için bir çaba gösteriyorlar mı? .. Mesela sen; iki yanımdaki, buğulanmış gözlerin sahibi, senin hedefin kim? .. Beni duyduğuna dair bir belirti göstermedi. Ve sanırım ben de ona bir şey sorduğuma dair bir belirti göstermedim. Boynumu o yöne çeviremedim. Yerimden kalkıp yanına gitmiş olmalıydım ama yapmadım. Sesim çıkmış olmalıydı ama dudaklarım kıpırdamadı. Sol yandan on üçüncü kişi benim. Diz çökmüş durumdayım. Ellerimi dizlerimin hemen üstüne yerleştirmişim. Başım dik ve karşıya bakıyor. Ağzım kapalı, nefes alış verişim düzenli ve gözlerim... Buğulu. Sisin içindeki ince siluletin hareketlerini izliyorum... Biraz önce ortadan kaybolmuştu. Belki de ben kaybetmiştim. Ne kadar kolay; yolunda gitmeyen bir şeyler olduğunda başkasını suçlayıveriyoruz. Tepki basit, düşünce sığ... “O Yaptı...” Ben izliyordum ama bir anda ortadan kayboldu. Sen de gördün değil mi? Nasıl da hızlıydı... Derinlere kaçtı ve yok oldu. Yoksa ben kaybetmezdim değil mi? Eğer o kadar hızlı olmasaydı asla kaybetmezdim... Yerinden kalktı, uzaklardaki, diğerlerinden ayıramadığım –ya da bir farkını göremediğim- diğer siluletin yanına gitti. Ona bir şeyler söyledi ve geri geldi. Diğeri pek bir tepki vermedi. Cevabı basitti, iletti. İnce karartı yerine döndü... Ne kadar zaman geçtiğimi bilmiyorum... Uzun? Kısa? Fikrim yok. Acıyı hissediyorum zaman zaman bedenimde. Kızgınlığı tadıyorum beynimin en derinlerinde. Nefret ediyorum o zaman sisten ve içindeki karartılardan. Ama bir keresi farklıydı. Yedi sıra arkamdaydı. Yerinden yavaşça kalktı. Sakin adımlarla yaklaştı. Sıcak nefesini ensemde hissettim.Sesi kulaklarımda çınladı. Dokunuşu yumuşaktı, bir parçamdı, tenine karışmıştım. Beni aldı, geriye götürdü, yedi sıra arkaya... Gözleri buğulu, nefes alışverişi düzenliydi... Ve ben de on üçüncü sıradayım aslında. İnce siluleti yine buldum... Yalnız değil. Bu sıralar hiç yalnız kalmıyor zaten. Mutlaka yanında diğer karartılar oluyor. Acaba benim ince siluletim ünlü bir kişi mi? .. Kibirle seviniyorum. Tabi ki ünlü; o benim siluletim... Hem bu benim açımdan da güzel bir şey. Karartım hiç yalnız kalmıyor ve ben onu her seferinde diğer karartılardan  ayırabiliyorum. Demek ki, başlangıçtaki düşüncem doğruydu. Kısa bir süre sonra tüm karartıların farkını anlayabileceğim. Ve böylece tüm hareketi takip etmem mümkün olabilecek. O zaman sisin içindeki siluletlerin planlarını çözeceğim...

Omzumda bir ağırlık hissettim. Bir el. Hafifçe sarsıyor beni. Bir dost uyarısı hissi uyandırıyor bende. Sanki beni anlıyor gibi. Ne düşündüğümü biliyor ve o da sisin içinde bir hedefin peşinde. Kim olduğuna bakmak istiyorum. Beni yalnızlığımdan kurtaran bu dost kim, görmek istiyorum. Oysa arkamı dönebilsem anlayacağım ki, kimse yok. Herkes diz çökmüş ve bir an bile hareket etmeden perdeye bakmakta. Bilinçli veya bilinçsiz. Anlıyor veya anlamıyor. Ama bakıyor. Nefes alış verişleri düzenli. Zaman zaman hırıltılar... Ben on üçüncü sıradayım, gözlerim donuk, omzumda bir kızarıklık var. Acımıyor.

İnce silulet olduğu yere çökmüş... Başını iki elinin arasına almış; Üzgün gibi, belki de pişman.. Ya da suçlu. Ağlıyor gibi hayal ediyorum onu. Süregelen, takip etmekte zorlandığım hareketliliğin içinde kaybolmuş ve yorgun. Ne yapacağın bilemez bir halde. Anlam veremiyor. Bir başka karartı geliyor onun yanına. Diğer karartılardan farkı yok gözümde. İnce değil. Kalın da değil. Ayrılacak hiç bir özelliğini bulamıyorum diğerlerinden. Sadece benim hedefimin yanında duran herhangi bir başka karartı o.', 'Karartılar var... Sislerin arasında, uzakta... Birbirlerinden ayıramıyorum aslında. Bir hareketlilik, planlanan bir şey. Hiç durmuyorlar... ...', ARRAY['Türk Edebiyatı','Şiir','Aykut Karaman']::text[], 8.5, '{"poet":"Aykut Karaman","poet_slug":"aykut-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hikayelerim-perde-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HiKaYeLeRiM PErDE 2', 'hikayelerim-perde-2-aykut-karaman-ihxsc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Konuşuyorlar... Ne dediklerini duymam mümkün değil ama bu bir tartışma değil. Anlayabiliyorum. Dost bir karartı bu... İnce silulet çöktüğü yerden kalkıyor. Dost karartı onu sarmalıyor. Arkamda bir yerlerden acı bir çığlık duyuyorum. Bir nefes okşuyor kulağımı, yanaklarım ıslanıyor başkasının gözyaşlarıyla. Bir damla kan damlıyor gökyüzünden. Sırada bir düzensizlik var. Yerimi sayamıyorum. Eminim ki on üç değil. O nereye kayıyor acaba? Arkama dönüyorum, devamlı değişen yerime aldırmadan saymaya başlıyorum. Yedi sıra geriye... Olamaz! Boş... Bu işte kesinlikle bir yanlışlık olmalı. Yedi sıra gerimdeydi biliyorum. Tekrar saymalıyım ama sıram hala değişiyor ve bu durum saymayı çok güçleştiriyor... Üstelik değişimler sadece yatay düzlemde değil... Zaman zaman dikey yönde de hareketlenmeler yaşanıyor. Yükselirken, bloklar halinde  bir sürü topluluk görüyorum. Hepsinin bir perdesi var ve izliyorlar. Diz çökmüşler, ellerini dizlerinin üzerinde birleştirmişler, başları dik, bakışları sabit. Binlerce olmalı bu gruplar. Sonunu göremiyorum. Ortam sakinleşiyor sanki. Bir kez daha denemeliyim. İki.. Üç.. Dört.. Tamam.. Onu buldum ama geride değil; Sağımda, bana yaklaşmış. Hatta en önde galiba. Yanına gitmek için yerimden kalkıyorum, sıra değişimlerinde o kadar karıştı ki her şey... –Bunu bir iki kez daha yaşandığını hatırlıyorum ama bu kadar etkilenmemiştim. Hatta benim sıram hep aynı kalmıştı.- Hızlı adımlarla sıranın en başına doğru yürüyorum. Yaklaştıkça durumunu daha iyi görüyorum. Birinci sırada. Gözleri buğulu, diz çökmüş, başı dik ve perdeye bakıyor. Yanına oturuyorum onun, yerim en baştan ikinci. Aslında hiç yürümedim. Sıraları saymış olmalıydım ama hiç saymadım. O da hareket etmedi. Diz çökmüş durumdayız, perdeye bakıyoruz. O birinci sırada ben ikinci sıradayım. Nefes almıyor! , köleler isyan ediyor...

Sıra kayıyor... İnce silulet, tek başına. Oturduğu yerden kalkıyor. Çevreyi inceliyor sanki bir şeyler arıyor gibi. Sise yaklaştığımı görüyorum. Artık karartımı daha net seçebiliyorum. Sonunda hedefime ulaşacağım işte! Onu o kadar iyi izledim ki, her hattın seçebilecek hale geldim. Artık diğer karartıları da daha dikkatli incelemem mümkün olabilecek ve böylece çözüme bir adım daha yaklaşacağım. Sis perdesi kalkacak ve dönen dolaplar ortaya çıkacak. İnce karartı eline bir şey alıyor ve onu kafasına götürüyor... Uzun bir sessizlik, gözlerimi ayırmadan izliyorum Ve bir patlama. Silulet sarsılıyor.

Elimi kaldırıyorum elini yakalamak için. Bulunduğum durumdan dolayı kireçlenmiş olan dizlerim hareketi istediğim çabuklukta yapmama izin vermiyor. Kalbim sıkışıyor. Yapma diye bağırmak isterken, ciğerlerime yayılan bir yanma engel oluyor bana.

Karartı diz çöküyor... Elleri dizlerinin üzerinde. Boşluğa bakıyor. Gözleri buğulu.

Sıranın en başındayım. Diz çökmüş durumdayım. Ellerim dizlerimin üzerine kavuşmuş. Perdeye bakıyorum. İfadesiz suratım ve buğulu gözlerim var. Beynim sancıyor. Nefes alamıyorum,

İşte, anladım! ! ! 

Sıra kayıyor...', 'Konuşuyorlar... Ne dediklerini duymam mümkün değil ama bu bir tartışma değil. Anlayabiliyorum. Dost bir karartı bu... İnce silulet çöktüğü y...', ARRAY['Türk Edebiyatı','Şiir','Aykut Karaman']::text[], 8.5, '{"poet":"Aykut Karaman","poet_slug":"aykut-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hikayelerim-perde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yer Olmalı', 'bir-yer-olmali-tulay-eker-kgilv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yer olmalı

Yağmurlarından ıslatmayan

Güneşi saçlarından yakalayan

Bir yer olmalı 

Gecenin karanlığından sıyrılıp

Yolları kısaltan

Bir yer olmalı

Dudağımın sol kenarındaki ölüm tebessümünü

Yankısı ile sarmalayan

Bir yer olmalı

Batmayı görmüşken doğmayı da seyrettiren

Bir yer...', 'Bir yer olmalı Yağmurlarından ıslatmayan Güneşi saçlarından yakalayan Bir yer olmalı  Gecenin karanlığından sıyrılıp Yolları kısaltan Bir ye...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-yer-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti', 'gitti-erol-duran-jurmb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzüme Baktı, 

Baktı sadece

Hiç konuşmadık

Bir damla yaş aktı içime

Gözlerim buğulandı

Kabahatli bendim.

Çekip gitti...', 'Yüzüme Baktı,  Baktı sadece Hiç konuşmadık Bir damla yaş aktı içime Gözlerim buğulandı Kabahatli bendim. Çekip gitti......', ARRAY['Türk Edebiyatı','Şiir','Erol Duran']::text[], 8.5, '{"poet":"Erol Duran","poet_slug":"erol-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gitti-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecavüz Davası', 'tecavuz-davasi-cemal-simsek-m3yk6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerinde kelepçe,iki jandarma arasında

Birlikte girdiler mahkeme salonuna

Hakim gelince herkes ayağa kalktı,

Tecavüz davası başladı.

Kimlik tesbitinden sonra,

Hakim sordu zanlı ya,

Dün gece yarısından sonra,

Tecavüzde bulunurken mağdur''a

Suç üstü yapmışlar,yakalanmışsın

Ne diyorsun bu konuya.

Zanlı çevirdi başını, arkaya baktı

Göz göze geldiler tecavüz ettiği adamla

Suçumu kabul ediyorum hakim bey

Çoktan razıyım verilecek cezaya.

Gençti, yakışıklıydı, kibardı

Her bakışın da içim yanardı.

Aşık olmuştum tüm benliğimle

Gece rüyalarımda, gündüz hayalimde 

O gece uyku girmedi gözlerime

Onun olmak istiyordum bütün gece

Arzu mu şehvet mi ne dersen de

Şeytana uydum bir kere

.

Aşk, sevmek, istemek suç ise

Çoktan razıyım verilecek cezaya

Pişmanmısın diye sorarsan

Cevabım tek kelimedir.

Asla....

Hakim döndü mağdur''a,

Aşıkmış,sevdalıymış sana

Bu yüzden gece girmiş koynuna

Pişmanlık duymuyor asla...

Bende seviyordum aslında

Derin bir uykudaydım gece yarısında

Üstüme bir ağırlık çöktü,

Belki yüz kilodan da fazla.

Eziliyordum altında

Ne aşk kalıyordu ne sevda

Ben vazgeçtim bu dava dan

Hatta evlenebilirim onunla

Bir şartım var hakim bey

Üstüme çıkmayacaksa..

Sanığın mağdurla evlenmesine,

Mahkeme heyetinin davetine,

Temyiz yolu açık olmak üzere,

Karar verildi davanın düşmesine.

Sanık sevinçle fırladı havaya

Açtı kollarını koştu mağdur''a

Öyle bir atladıki boynuna

Mağdur kalmıştı yine alt''ta...', 'Ellerinde kelepçe,iki jandarma arasında Birlikte girdiler mahkeme salonuna Hakim gelince herkes ayağa kalktı, Tecavüz davası başladı. Kimlik...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/tecavuz-davasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmazıma', 'unutulmazima-cilgin-romantik-72rgm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni unutmak

Gidişin kadar kolay olsaydı

Bir damla yaş akmazdı gözlerimden

Yüreğim kan ağlamazdı

Sensiz geçen gecelerde

Şarkılar susmazdı umarsızca

Yokluğunu yazmazdı kalemim

Ve çaresiz bir çırpınışın

Sessiz çığlıkları yükselmezdi mısralardan

Her şey eskisi gibi olurdu

Sen olmazdın şarkıların sözlerinde

Geceler beni anlardı

Boğulmazdım karanlıklara

İstediğim gibi bir sevgilim olurdu şiirlerde

Beni severdi

Hem de deli gibi

O kadar kolay olsaydı 

Seni unutmak

Bir kere bile bakmazdım ardıma

Gittiğin günü yırtıp atmazdım takvimlerden

Adını anmazdım 

Mecnun olmazdım aşk çölünde

Seni unutmak kolay olsaydı

Sensiz de yaşardım bu hayatı', 'Seni unutmak Gidişin kadar kolay olsaydı Bir damla yaş akmazdı gözlerimden Yüreğim kan ağlamazdı Sensiz geçen gecelerde Şarkılar susmazdı um...', ARRAY['Türk Edebiyatı','Şiir','Çılgın Romantik']::text[], 8.5, '{"poet":"Çılgın Romantik","poet_slug":"cilgin-romantik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutulmazima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Oluyor.', 'neler-oluyor-cemal-simsek-l2fzo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mahalle ayni mahalle

Sokak ayni sokak

Sola bakmazdım önceleri

Kapınızın önünden geçerken.

Gece ayni gece

Pencere ayni pencere,

Pencerenize bakmazdım önce

Her ışık yanışın da.

Akşamları duymazdım hiç,

Evinizden gelen müzik sesini.

Hiç bu kadar uzamamıştı

Bu mevsimin geceleri.

Ben yine ayni ben,

Neler oluyor bana.

Tekrar aşık mı oluyorum

Bu yaştan sonra', 'Mahalle ayni mahalle Sokak ayni sokak Sola bakmazdım önceleri Kapınızın önünden geçerken. Gece ayni gece Pencere ayni pencere, Pencerenize b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neler-oluyor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakin', 'sakin-gulsen-gonenc-g3eop', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanan gemileri görmüyorsun da

Kokusunu da mı almıyorsun? 

Hiç büyümemiş çocuklarımla

Bu adanın ''sakin''iyim.', 'Yanan gemileri görmüyorsun da Kokusunu da mı almıyorsun?  Hiç büyümemiş çocuklarımla Bu adanın ''sakin''iyim....', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sakin-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Nokta', 'kor-nokta-gulsen-gonenc-xwxd2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Noktalar var görmeyen,

Gözler var noktaları görmeyen,

Bir mücadele, bir haykırış; 

Görmeyenlerle görülmeyenler arasında.

Hep istedim ama hiç beklemedim.

İşte o an, bu an.

Gözümüz aydın!', 'Noktalar var görmeyen, Gözler var noktaları görmeyen, Bir mücadele, bir haykırış;  Görmeyenlerle görülmeyenler arasında. Hep istedim ama hiç...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kor-nokta-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-gulsen-gonenc-7lbuv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özgürlüğü uzaktan gördüğü ama bilmediği diyarlarda

boş boş uçmak sanan serçe,

konmak istiyor serçe parmağa; 

Gördüklerim yanıltıcıymış, uçmak zormuş, diyor.

Uzaktan göremediği birşey var aslında:

O serçe parmağı gagalarken kangren olan yara.

Serçe parmak yok artık, serçe.

Başka parmak hiç olmadı zaten.', 'Özgürlüğü uzaktan gördüğü ama bilmediği diyarlarda boş boş uçmak sanan serçe, konmak istiyor serçe parmağa;  Gördüklerim yanıltıcıymış, uçma...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serce-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''yı Dinliyorum', 'ankara-yi-dinliyorum-selim-gul-4ozge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ankara’yı dinliyorum Orhan Veli’ye inat

Ne rüzgâr esiyor hafiften

Ne de gözlerim kapalı

Denizin sesi de İstanbul’a has

Bütün renkler Ankara’da mat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Çankaya sırtlarından çan sesleri geliyor

Cinnah’ın dibinde yalnız kalmış minare

Tunalı Hilmi’de şuh kahkahalar

Kuğulu Park’ta insanlar rahat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ülkemin kalp sesleri geliyor kulağıma

Uzun derin bir inilti dağılıyor etrafa

Askerler rap rap meclisin bahçesinde

İrademin boynunda yağlı bir halat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Vekiller misket oynuyor milletin kaderiyle

Memurlar öğle paydosunda simit dişlerken

Amirler kebap yiyor künefenin önünden

Açlıktan garibin midesi kat kat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Hacettepe’de oturmuş ağlıyor kızlar

İffet çığlıkları dolduruyor gökleri

Rengarenk örtülerle çiçekler açmış başlar

Pencereden bakıyor merhametsiz bir surat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Köprülerin altında baldırı çıplak çocuklar

Bir poşetin içinden bali çekiyor

Çingeneler Çinçin’ de göbek atıyor

Çiftliğe hapsolmuş türlü türlü hayvanat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Acı bir fren sesi geliyor Dö Gol yolundan

Sanki çığlığı kızın, kulağımı yırtıyor

Ambulans bağırarak trafiği yarıyor

Sona eriyor yine taze bir hayat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Gençlik Parkı’nın bankları gıcırdıyor

Lunaparkta eğlence var meraklısına

Sevgililer kayıklarda ilan-ı aşk ediyor

Çocukların sevgilisi cansız dönen at

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Kızılay’ı sel götürmüş, bir insan seli

Kimi işe gidiyor, kimi saf saf geziyor

Sakarya çay ocağında biri, bir çay istiyor

Esnafın bugün de işleri kesat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Banliyö treni Sincan yolunu tutmuş

Samanpazarı’nda gelinlik kızlar alışveriş yapıyor

Bentderesi her zamanki namus pazarı

Haydi güneş! Bugün de biç namusa bir fiyat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Hacı Bayram Camisi yalnızlığını yaşıyor

Bakanlıklar, Bahçeli, Emek şen şakrak

Altındağ, Mamak, Kayaş fukara ağırlıyor

Ömrümü yutuyor canavar  saat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ankara’yı dinliyorum Orhan Veli’ye inat

Ne rüzgâr esiyor hafiften

Ne de gözlerim kapalı

Burada hayatım bölündü lif lif

Bütün renkler Ankara’da mat

Ankara’yı dinliyorum Orhan Veli’ye inat

21 Ekim 1997 Ankara', 'Ankara’yı dinliyorum Orhan Veli’ye inat Ne rüzgâr esiyor hafiften Ne de gözlerim kapalı Denizin sesi de İstanbul’a has Bütün renkler Ankara’...', ARRAY['Türk Edebiyatı','Şiir','Selim Gül']::text[], 8.5, '{"poet":"Selim Gül","poet_slug":"selim-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ankara-yi-dinliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
