INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Ben Ne De Sen', 'ne-ben-ne-de-sen-i-brahim-halil-demir-8g08j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dolaştık el ele sevdanın gurbetinde,

Ne ben hayır gördüm,ne de sen.

Oturduk sevdanın sofrasında,

Ne ben doyasıya yedim ne de sen.

Bakıştık sevdalı gözlerle birbirimize,

Ne ben anlayabildim seni ne de sen

Çekmişti kader sevda sürmesini gözlerimize,

Ne ben bakmasını bildim ne de sen,

İçtik suyu avuç avuç aşk pınarından,

Ne benim hararetim dindi ne de senin.

Kırbaçladılar bizi habire durmadan,

Ne sen şahlanabildin ne de ben.

Delik deşik oldu yüreğimiz  sevda savaşında,

Ne ben şehit olabildim ne de sen.

Aldık sevda sancağını elimize,

Ne ben gazi olabildim ne de sen.

Uzandık sevdanın kuş tüyü döşeğine,

Ne ben uyuyabildim ne de sen.

Doğuverdi sevda güneşi üzerimize,

Ne ben ısınabildim ne de sen.

03/01/2006', 'Dolaştık el ele sevdanın gurbetinde, Ne ben hayır gördüm,ne de sen. Oturduk sevdanın sofrasında, Ne ben doyasıya yedim ne de sen. Bakıştık s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-ben-ne-de-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askere Annesinden Mektup', 'askere-annesinden-mektup-fethi-kucuk-eopqx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğul; bak işte büyüdünde asker oldun

binbir acılarla büyüttüğüm,ninnilerle uyuttuğum sen,

şimdi asker ocağındasın oysa

oysaki sana daha ne kazaklar örecektim üşümeyesin diye

seni bekleyecektim eve geç gelmelerinde

oysaki oğlum 20 yıl doyamamıştım sana sarılacaktım doya doya

Ah oğul ah

Aman kendine dikkat et oğlum sakın üşütüpte hasta olma

kendini ezdirme aman oğlum sakın

biliyorsunki orası ana kucağı değil oğul asker ocağı

ben seni gözümden sakındım ömrümce 

şimdi oralarda kıyamam sana evladım canım yavrum

bekle sabret sayılı gün çabuk biter

Oğul, oğul

Binlerce şehit yatar bastığın o kutsal topraklarda

binlerce gözyaşı aktı ne kanlar döküldü oğul

sende askersin oğul,hak aşkına vatan aşkına de

sık dişini.Başını dik gözünü pek tut,silahın namusun görevin şereftir oğlum.Olaki caymayasın sözünden

çünkü sen MUSTAFA KEMAL torunusun oğul

Oğul can Oğul

işte sana son gurbet,işte sana bir nasihat

düşerse birgün düşman karşısında siperin

korkma...söyle askerin mert olduğunu,düşmanın namert olduğunu ve de bu vatanın emanet olduğunu

3-5 nöbetine ver oğlum kalbinin heyecanlı atışını

ve haysiyetini koy kepinin üstüne her selam verdikçe yerine gelen

biliyorum korkmaz ve dönmezsin sözünden

çünkü sen babanın oğlusun 

şunu unutma oğul,vatan sağolsun', 'Oğul; bak işte büyüdünde asker oldun binbir acılarla büyüttüğüm,ninnilerle uyuttuğum sen, şimdi asker ocağındasın oysa oysaki sana daha ne k...', ARRAY['Türk Edebiyatı','Şiir','Fethi Küçük']::text[], 8.5, '{"poet":"Fethi Küçük","poet_slug":"fethi-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askere-annesinden-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telefonun Başındayım', 'telefonun-basindayim-yusuf-onder-bahceci-12chb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Telefonun başındayım,

Çalmıyor ki bir türlü,

Sanki çok zormu söyle,

Bir numara çevirmek.

Telefon her çaldığında,

Bu sefer o diyorum,

Baktım ki sen değil,

Boynu bükük kalıyorum.

Birgün arayacak biliyorum,

Allah''ım sabır sabır diyorum,

Rüyalarda görüyorum,

Sevdiğimi sevdiğimi.', 'Telefonun başındayım, Çalmıyor ki bir türlü, Sanki çok zormu söyle, Bir numara çevirmek. Telefon her çaldığında, Bu sefer o diyorum, Baktım ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/telefonun-basindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürce', 'ozgurce-yalin-sinan-uy1mr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazmaktı içimdekileri dağıtmak için

Ve okumaktı insanları

İnce kalın fark etmeyen

Akıcı berrak bir şekilde

Bir roman bir şiir gibi

Kül tablasına esir kalmadan

Sönmeden gözlerimin ateş saçan feri

Bırakmaktı içimdeki

Tüm kötü bildiklerimi

Akşamları gündüzleri karıştırmadan

Kirli iğrenç ne varsa

Sonsuz derinlikte bir tabuta hapsetmek

Zozan yaylasından alıp

Temiz havayı ciğerlerime

Botan çayına girip tenimin kirliliğini

Alıp ağır bedenimden sıyırmak

Zan altında tutulmadan

Kelepçe vurulmadan düşüncelerime

Vs.. demeden haykırabilmek

İçimdeki tüm düşüncelerimi özgürce', 'Yazmaktı içimdekileri dağıtmak için Ve okumaktı insanları İnce kalın fark etmeyen Akıcı berrak bir şekilde Bir roman bir şiir gibi Kül tabla...', ARRAY['Türk Edebiyatı','Şiir','Yalin Sinan']::text[], 8.5, '{"poet":"Yalin Sinan","poet_slug":"yalin-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozgurce-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-yusuf-onder-bahceci-jlxqy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gurbet elde akşam olur hüzün çöker gönlüme,

Yuvasız kuşlar gibi buralarda kaldım ağlarım,

Gurbet elden haber saldım gözü yaşlı anama,

Ağlama yavrum sen dedi bu dokunur kanıma,

Gurbetin iyisi hiç olurmu sandın,

Gurbet elde sevdin öylece kaldın,

Sen bu gurbeti oyunmu sandın,

Saçlarına aklar doldu gel artık.

Gel Allah''ı seversen no''lur bekletme beni,

Şurda kaç gün ömrüm kaldı gidenler hani,

Seninle gidenler döndüler sen nerde hani,

Yaşıtların tek tek gitti ne olursun gel artık.', 'Gurbet elde akşam olur hüzün çöker gönlüme, Yuvasız kuşlar gibi buralarda kaldım ağlarım, Gurbet elden haber saldım gözü yaşlı anama, Ağlama...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-artik-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Komik Hikaye', 'bir-komik-hikaye-yalin-sinan-opzhi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah aynı saatte kalkıyorum

7:30 dedin mi yüzümü yıkıyorum

Dişlerimi fırçalıyorum üstümü değişiyorum

Yavaş yavaş  yürüyorum durağa doğru

İlk önce çöpçü Kenan amcayı görüyorum

Her zaman ki gibi sessiz

selamıma kafasını kaldırıp gülümsüyor.

Bir kaç adım sonra bu seferde gülten teyze

Her günkü temizliği yapıyor balkonda

Kolay gelsin diye bağırıyorum dalmış

Bir an afallıyor sağol evlat diyip işine koyu lor..

Omuzsuma bir el dokunuyor irkiliyorum

Donup baktığımda sensin  yine her zamanki gibi

Ürkütmeden rahat duramasın ki

Aylardır böyle ama her seferinde heyecan

Her seferinde karışıklık, yüreğimde irkilmeyle,

Yine havadan sudan askın anlamında konuşuyoruz

Her sabah kahrolası yol ayrımına kadar.

Yine hazırlanıyorum hoşça kal kendine iyi bak demeye

Bugün bir farklılık görüyorum elimi uzatınca

“Ne o benden kurtulmak mı istiyorsun”

“ne o sevgilin mi bekliyor görmesen mı beni yanında”

Gülümsüyorum ya neye güldüğümü bilmiyorsun

Sen bu yoldan gidiyorsun ben ise durağa doğru.

“Neyse boş ver  yürüyelim anlatırım yolda

Artık işyerim değişti sana yakın bir yere geliyorum”

(Acaba ne kadar yakın.Sonradan öğrendim bayağı yakın

Bir kat aşağı kadar yakın) 

Durağa nasıl vardığımı hatırlamıyorum bir an

Otobüsün gelişini gördüm sonra bir de hücum  edenlere

Bugün otobüs o kadar değişik geldi ki

Yol o kadar kısa geldi ki ne konuşabildim

Nede bir şey sorabildim ya boş ver dedim...

iniyorum dediğimi hatırlıyordum

“dur bende bu durakta ineceğim “

Senden kurtuluş yok mu? (Gülümseyerek söyledim) 

Yürümeye koyulduk yavaş yavaş ses seda yok ikimizde de

Buyur dedim işyerim burda bir çayımı iç bari

Gulumsedı merak etme bundan sonra bol bol cayını ıcecegım

Cok masraflısın dıye seslı dusunmusum

Gulumsemeler kahkahalara karıstı

O gunden sonra hergun cıkıslarda bereber yuruduk

Yagan yagmurlarda bereber ıslandık

Gozyaslarımızı  bereber zemınlere damlattık

Bırgun ıste geldı yıne yol ayrımı.

Son cesaretımı topladım  yıne bır sabah gıderken ıse

Bu sefer ben omuzuna dokundum benımle evlenırmısın? 

Dıye haykırmısım ben bıle sasırdım

Gulten teyse ogul nıhayet yanı dedı hele sukur dedın

Kenan amca ılk defa konustu afferın ogul kacır ma kızı

(ben babası vermeze kacırmayı dusunuyordum oysa) 

Bu sefer ırkılme sırası sende dedım buyur cevap ver bakıyım.

Gulumsedı herzamankı tatlıgında eee dedı

Evet mı yanı! Haykırırım evet  demesen

tum mahaleyı Ayagı kaldırım dedım....

Iyıkı kaldırmadın dedı herkez bızı seyredıyor

 Herkez bızı mi seyredıyormuş işleri yok mu? ....

Başka ne işleri olsun ne guzel film işte dıyınce..

Ask ınsanın gozunu kor eder Gül dıye cevap verdım.

“Pekı  Evet ama..bugun ıstemeye geleceksınız”

O gun zaman oyle durgundukı aksamı zor ettım..

Sımdı mesudum ya ıkı tanede velet var..

Sırıtırlar hep,cekıstırıler saclarımı.........', 'Her sabah aynı saatte kalkıyorum 7:30 dedin mi yüzümü yıkıyorum Dişlerimi fırçalıyorum üstümü değişiyorum Yavaş yavaş  yürüyorum durağa doğr...', ARRAY['Türk Edebiyatı','Şiir','Yalin Sinan']::text[], 8.5, '{"poet":"Yalin Sinan","poet_slug":"yalin-sinan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/bir-komik-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perican', 'perican-sair-hilaloglu-t803i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolunda feda olmak varsa kaderde,

Al bu canım senindir tasarruf et Perican.

Elimdeyse ellerin aldırmam kedere, derde,

Al bu gönlüm senindir tasarruf et Perican.', 'Yolunda feda olmak varsa kaderde, Al bu canım senindir tasarruf et Perican. Elimdeyse ellerin aldırmam kedere, derde, Al bu gönlüm senindir ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/perican-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olan Oldu', 'olan-oldu-sair-hilaloglu-9mr5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zincire vurulma makamındayım yar

Gel de gör bendeni ah neler oldu

Bak hasrete giriftar ettiğin gönlüm

Mecnun’a eş tutuldu, aşka yar oldu

Ateş mi kesilir yurdundan geçen sular

Yakar mı dilimi çekilen hu, hular

Görmezem gayrısını gelmesin ahular

Sende kıldı tecessüm berkarar oldu

Artık olan oldu gam çekmek niye

Sensiz hazan her dakika her saniye

Görmeden yandım da hayal-i periye

Hilaloğlum yolunda hep berdar oldu', 'Zincire vurulma makamındayım yar Gel de gör bendeni ah neler oldu Bak hasrete giriftar ettiğin gönlüm Mecnun’a eş tutuldu, aşka yar oldu Ate...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilaloğlu']::text[], 8.5, '{"poet":"Şair Hilaloğlu","poet_slug":"sair-hilaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olan-oldu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Allah''ı Seversen', 'gel-allah-i-seversen-yusuf-onder-bahceci-e6cbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlama sen sevdiğim,

Sevip gönül verdiğim,

Şu kalbimi bir bilsen,

Gel Allah''ı seversen.

Şu kalbimi bir görsen,

Gözümde yaşları silsen,

Ölmüşüm ben bir gülsen,

Gel Allah''ı seversen.

Seni sevdim arıyorum,

Uçan kuştan soruyorum,

Rüya gördüm yoruyorum,

Gel Allah''ı seversen.

Benim derdim hayli derin,

Elem, keder hep kaderim,

Söyle nasıl nasıl edim,

Gel Allah''ı seversen.....', 'Ağlama sen sevdiğim, Sevip gönül verdiğim, Şu kalbimi bir bilsen, Gel Allah''ı seversen. Şu kalbimi bir görsen, Gözümde yaşları silsen, Ölmüş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-allah-i-seversen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamıyorum Sensiz', 'olamiyorum-sensiz-turgut-onal-v9ibl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni yalnız bırakıp gittin bu gece

Odamda ışık bile yakmadım

Yıldızlar ağladı yalnızlığıma

Penceremi açıp bakmadım

Avuçlarımdan kaçırdığım kuş gibiydin

Sen gittin sıcaklığın kaldı yüreğimde

Kirpiğim kirpiğime değmeden sabahı ettim

Islak bir mendil kaldı ellerimde

Hüznümü anlatmak için bu şiiri yazdım

Belkide yazmamalıydım.....bilemiyorum

Gece saat üç... ve... hâlâ yoksun

Umudumu yitirip gidemiyorum

Sensizlik bu gece çok koydu bana

Müebbete hüküm giymiş makûmum sanki

Resmine baktıkça içim sızladı

Olamıyorum sensiz.....inanki...', 'Beni yalnız bırakıp gittin bu gece Odamda ışık bile yakmadım Yıldızlar ağladı yalnızlığıma Penceremi açıp bakmadım Avuçlarımdan kaçırdığım k...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olamiyorum-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Öğrendim', 'senden-ogrendim-arjin-murad-fmpti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'baharlar yazlar yaptım kendime...

birde yaslar..

gelişini ve gitmelerinin tümünü anlatabilmek için..

şimdiye kadar gecikti bahar,yaz....umut...

belki de ben aramadım bekledim sadece..

gözlerim :

gözlerinden kaçarken yara bere içinde kalmalarım...

gözlerim :

unutmaktan sakındığım herşey-im-e bakamdığım..

-özleyeyim diye-

gözlerin : 

hayatın çirkefliğinden kurtardığım herşey-im-in depo yeri..

yüreğin..

bir kelime kifayetsiz kalacaksa...

yetersiz kalacaksa anlamlar...

yüreğinin karşılamakta kalmalı sevgili...

yüreğinde ki sevgindir belkide hayatı-ım-n anlamı...

gel korkma sen..

kuytuluktan vazgeçtim gel...

senı en aydınlık yerımde tasıyayım gel..

ama unutma kuytularımı onlarıda sevindireceksen gel..

''''ne olursan ol'''' gel demiyorum sana

benım olacaksan BEN olacaksan gel..

beni sen yapacaksan gel..

senle YAZ da gelsin...

yaz...gelsin..

sen bana yazdıkca...

sen bana AKtıkca bende aklayayım yaşamı..

sen yazınca YAZ olsun bir ömür...

hayatıma keşkeleri çoğaltıyorsun uzun zamandır..

keşke diyorum...

keşke....ve susuyorum...hemde hiç susmadan...

gel...hiç gitmemiş gibi...

gel...hiç gitmeyecekmiş gibi....

gel...

''''ne olursan ol'''' değil...

gelıyorsan yüreğini de al yanına..

yüreğindeki AK....korkAK....çıplAK...sevgini de getir...

''''ne olursan ol''''değil...

gel...hepsi..bu...

                                                              Hayatıma AKan a....', 'baharlar yazlar yaptım kendime... birde yaslar.. gelişini ve gitmelerinin tümünü anlatabilmek için.. şimdiye kadar gecikti bahar,yaz....umut...', ARRAY['Türk Edebiyatı','Şiir','Arjin Murad']::text[], 8.5, '{"poet":"Arjin Murad","poet_slug":"arjin-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/senden-ogrendim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yıldız kayıyor', 'bir-yildiz-kayiyor-nurseven-atmaca-j6m64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlızlığa mahküm ettin ya beni

Yıldızlar ağlar 

Gözler ağlar 

Sevdam ağlar 

Yorgun bu beden

Yorgun bu yürek

Esir düşmüş gecelere 

Gecenin sessizliğine inat

Cırcır böcekleri çığlıklarda 

Kırık bir sandalye sesi 

Birde senin yokluğun

Kenarı yırtık soluk resmin 

Parmak uçlarımda sevişiyor 

Acıtıyor yüreğimi,

Demi vuruyor kahpece 

Sessiz kara zifir geceler 

Bir hüzün çöküyor yüreğime 

Çatılardan düşen damlalar 

Avuçlarıma üşüyor 

Gözyaşlarım sarıyor seni 

Yüreğimin tekne kıyısında kalan 

Son umut kırıntısı

Soluyor 

Silinmiş film misali

Sevişiyor geceler acılarımla 

Dans ediyor hoyratça zaman

Bir yıldız kayıyor 

Yıkılıyor koca çınar 

Azrail dolaşıyor 

Adım adım başucumda', 'Yanlızlığa mahküm ettin ya beni Yıldızlar ağlar  Gözler ağlar  Sevdam ağlar  Yorgun bu beden Yorgun bu yürek Esir düşmüş gecelere  Gecenin s...', ARRAY['Türk Edebiyatı','Şiir','Nurseven Atmaca']::text[], 8.5, '{"poet":"Nurseven Atmaca","poet_slug":"nurseven-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-yildiz-kayiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürürken Dinlediğim', 'yururken-dinledigim-engin-kahraman-mlwvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskisi gibi aldırmıyorsun, başladığı gibi bitiyor gün/

ürkek  kısraklar gibi koşarak karanlığın içinden.

Sen hala düşler topluyorsun adresleri şüpheli ömrünün/

ıssız ve hazan vurmuş bahçesinden. 

Aynı üslupla yazılmış şiirlerin verdiği bıkkınlık/

gibi, akşamı esmerliğiyle tanıyorsun artık. 

Ne kaldı geriye coşkulu şiirler’den bize? 

Gece uzak tellerde açılmış bir yırtık...

Bak! yaşlı kadınların çıkını gibi karanlık/

gizliyor her şeyi, için için büyüyor.

 “Düz gitmek iyidir” diyor. [ bir  iç ses ]

Kendisi her zaman kestirmeden yürüyor.

Öcünü al kır yollarının, avlu önlerinin/

Yak desem Neron hırsıyla bütün şehirleri.

Aynı karanlık toplamayacak mı yine/ 

dimağları kurutulmuş bütün köleleri.

Mevsimler değişiyor ama eskimiyor günlerin/

üzerindeki esvap, canlı ve parlak, bin yıllık...

Bozkırlar gibi kavrulup duruyor teninde/

Gözünü her kapayışında ürperen aydınlık.', 'Eskisi gibi aldırmıyorsun, başladığı gibi bitiyor gün/ ürkek  kısraklar gibi koşarak karanlığın içinden. Sen hala düşler topluyorsun adresle...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yururken-dinledigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-nurseven-atmaca-85bgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerim yetmiyor seni görmeye

İçimde coşan ne bilemiyorum

Alışamadım sensizliğe

Bir güneş oldun

Bir de bora

Sonra deli rüzgar

Estin gittin

Ne acıymış ayrılık

Yürüyor acılarım gökyüzüne 

Delik deşik sevdalarım

Yıldızların altında ufalanıyor

Nehir gibi gözyaşlarım

Gece arsız korkuyorum

Tutamıyorum ellerini

Üşüyorum

Çok üşüyorum

Soğuk bir odada

Sobanın başında

Hayaller kuruyorum

Arkada bıraktığın bir yalnız beni

Ateşe dumana anlatıyorum

Dalga dalga oluyor hayallerim

İçime işleyen ayaza

Bir asır gibi tarihler yazıyorum

Seninle var olan bu nefes

Sensiz dolmuyor ciğerlerime

Düşlerim yetmiyor seni görmeye

Yapraklarına çığ düşmüş laleler gibi 

Üşüyorum

Buz gibi oluyor bedenim 

Gidiyorum

Parmaklarımın ucunda sen', 'Düşlerim yetmiyor seni görmeye İçimde coşan ne bilemiyorum Alışamadım sensizliğe Bir güneş oldun Bir de bora Sonra deli rüzgar Estin gittin ...', ARRAY['Türk Edebiyatı','Şiir','Nurseven Atmaca']::text[], 8.5, '{"poet":"Nurseven Atmaca","poet_slug":"nurseven-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gidiyorum-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsanevi bir ask hikayesi', 'efsanevi-bir-ask-hikayesi-ulya-erkman-pn0km', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ressam ile sairi

idiler

Veriyorlardi birbirlerine

Kendileri hakkinda bilgiler

E mail de tanismislardi

Birbirlerine yazilar yazarak

Okyanuslarla ayrilmislardi

Imkansizdi onlar icin kavusmak

Bir hayli yas  farki  vardi 

Aralarinda

Yinede devam ediyorlardi

Yazismalarina

Yazismalar gittikce 

Manalandi

Sevgileri satirlar arasina 

Saklandi

Gittikce alevlendi bu 

Sevgi

Gozleri gormuyordu artik

Hic kimseleri

Oylesine bir asktiki bu

Hemde deniz asiri

Nasil olurdu boyle bir ask

Hissetmeden bir hayli yas farki? 

Ruhlariydi onlari baglayan

Yas neymiski? 

Seviyorlardi birbirlerini

 Hemde deliler gibi

Ciziyordu  ressam firsat buldukca

Resmini

Fotograflardan, bilhassa

Tutamadigi ellerini

Sairi ise bakiyordu resimlerine

Sevgiyle

Ekliyordu sevgisini ozlemle

Siirlerine

Mahserde de beraber olacagiz

Diyorlardi

Askimiz o ana kadar yasayacak

 Inaniyorlardi

Tanimasam onlari belki bende 

Inanmazdim

Belki de durup durup bu siiri 

Yazmazdim

Ama bir siir degil bu

Bir hakikat hikayesi

Gorulmemis isitilmemis bence

Buyuk bir ask efsanesi', 'Ressam ile sairi idiler Veriyorlardi birbirlerine Kendileri hakkinda bilgiler E mail de tanismislardi Birbirlerine yazilar yazarak Okyanusla...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/efsanevi-bir-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ellerden Giderim', 'bu-ellerden-giderim-yusuf-onder-bahceci-hknp4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlama sen sevdiğim,

Sevip gönül verdiğim,

Seni sevdim demezsen,

Bu ellerden giderim

Yıllar oldu bekliyorum,

Seni sevdim diyorum,

Sende beni sevmezsen,

Bu ellerden giderim.

Seni sevdim yaralıyım,

Derdi dağlar sıralıyım,

Sorma şimdi nereliyim,

Bu ellerden giderim.

Benim derdim yâr derdi,

Herkesin var bir derdi,

Bu derdi Allah verdi,

Bu ellerden giderim....', 'Ağlama sen sevdiğim, Sevip gönül verdiğim, Seni sevdim demezsen, Bu ellerden giderim Yıllar oldu bekliyorum, Seni sevdim diyorum, Sende beni...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-ellerden-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Ağlarken', 'yuregim-aglarken-turgut-onal-j8ice', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdimi anlattım kara geceye

Yıldızlar yas tuttu, ağladı güller

Sen benim derdimi nerden bilirsin

Yüreğim ağlarken gözlerim güler

Hasrete alışmak ne kadar zormuş

Kim kapımı çalmış, kim hatır sormuş

Anladım bu sevda beni çok yormuş

Yüreğim ağlarken gözlerim güler

Çöllerde dolaşan Mecnun'' a  döndüm

Aşkımı gizledim kalbime gömdüm

Seni bilmem ama ben her gün öldüm

Yüreğim ağlarken gözlerim güler

Seni sevdiğime pişman değilim

Biricik varlığım, aşkım, sevgilim

İsmini ne zaman söylese dilim

Yüreğim ağlarken gözlerim güler', 'Derdimi anlattım kara geceye Yıldızlar yas tuttu, ağladı güller Sen benim derdimi nerden bilirsin Yüreğim ağlarken gözlerim güler Hasrete al...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregim-aglarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Merhamet', 'ask-ve-merhamet-ramazan-saglam-3st6y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadıköy rıhtımında yüzlerce martı uçar

Mehtabın ışığında yüreğime aşk saçar

Hızla çarpar dalgalar yüreğimin koyuna

Aşkı toplar martılar atar deniz suyuna

Gecenin güzel yüzü martı mehtap ve yıldız

Denizin sesi bir de balıkta gümüş yaldız

Seyreyle sabaha dek ömrüne ömür katsın

Sen uyuma yinede bırak bu şehir yatsın

Yakomozlar altında sandalcı keyfi gıcır

Çekerken oltasını gelen balığa acır

Merhamet! Ey merhamet! Balıkta mı keramet

Seni görmek ne güzel aşka yeter merhamet.', 'Kadıköy rıhtımında yüzlerce martı uçar Mehtabın ışığında yüreğime aşk saçar Hızla çarpar dalgalar yüreğimin koyuna Aşkı toplar martılar atar...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Sağlam']::text[], 8.5, '{"poet":"Ramazan Sağlam","poet_slug":"ramazan-saglam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-merhamet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-turgut-onal-ouex0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep aynı yalanı dinledim ömrümce

Kendi yalnızlığımın gurbetindeyim

Günler sıyrılıp soyunuyor avuçlarımda

Ben geçen yılların nöbetindeyim

Dalgalar milyonkere dövüyor sahili

Güneç milyon kere doğup batıyor

Yüreğimi sevdanın ateşi değil

Senin yalanların kanatıyor

Sevgiye, şefkate ihtiyacım vardı

Vefanın sıcaklığından yoksun büyüdüm

Güneşe döndüm yüzümü gitmek istedim

Yazık ki bütün yollar kördüğüm', 'Hep aynı yalanı dinledim ömrümce Kendi yalnızlığımın gurbetindeyim Günler sıyrılıp soyunuyor avuçlarımda Ben geçen yılların nöbetindeyim Dal...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kordugum-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocalar Konuşuyor', 'hocalar-konusuyor-alper-kuruk-bdrhy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HOCALAR  KONUŞUYOR

                             (İSTANBUL HUKUK FAKÜLTESİ  ÜÇÜNCÜ SINIFTA YAZILMIŞTIR.) 

                           CEZA HUKUKU KÜRSÜSÜNDEN:

                            Prof.DR.NACİ ŞENSOY (MERHUM) 

                           “  Tehirinde mazarrat melhuz bulunan ahvâl müstesna

Tekrar edelim bir daha...

-Gülmek ve konuşmak yok! atarım dışarı ha! -

Yegân yegân tesbit eylediğimiz

İşbu hâdiseler muvacehesinde

Halli iktiza eden mesele...

-Gülen,konuşan olsun hele

Haşlarım,atarım dışarı ha! - “

                             CEZA USULÜ HUKUKU KÜRSÜSÜNDEN:

                              Prof.Dr.NURULLAH KUNTER (şimdi EMEKLİ) 

                             “ Patagonya Usul Kanunu

  Cart-curt kaideler koyuyor

 Falan filan,filan falan oluyor..”

İDARE HUKUKU KÜRSÜSÜNDEN:

Asistan Dr.İSMET GİRİTLİ (Halen Prof. Dr.EMEKLİ)  	

“Tabir caizse af buyurun

Kalleşçe sizi buraya topluyor

Yine de yoklama âdem-i ifa oluyor...”

DEVLETLER HUKUKU KÜRSÜSÜNDEN:

Prof.Dr. CHARLES CROZAT  & MÜTERCİMİ Asistan Dr. Bayan..

Hoca der:Mes étudiants! 

Tercümesi:Talebeleğim

Yanınızda biğeğ coğğafya hağitanız olsun.

(Dikkat! alkış var burada...) 

Göğünüz kuzeydeki kutup buzlu pasta

Nasıl paylaşıldı.(Zıkkımlansınlar...) 

İCRA VE İFLAS HUKUKU KÜRSÜSÜNDEN:

Prof.Dr.İLHAN POSTACIOĞLU (MERHUM) 

“Arkadaşlar davacının hakk-ı hıyarı var.

Gülecek ne var sanki? 

Netice-i talep,semere-i ihtilâf

E...benim bu tâbirler hoşuma gider.

Hem sizin kompozisyonunuz sıkıcı

Okurken zorluk çekiyorum,eğer

Havalandırsaydınız biraz şöyle yıllanmış şaraplar gibi

Mest olmamak elden gelir miydi? 

......Bunlar teferruat

Ben bile aklımda tutamam

Size de imtihanda sormam.

Temiz temiz dökerim

Sizi de kendimi de yormam.

Haydi bakalım bunu kim söyleyecek

Aferin...Numaran kaç senin? ”

MALİYE HUKUKU KÜRSÜSÜNDEN:

Prof.Dr.ORHAN DİKMEN (ŞİMDİ emekli) 

“İlk çocuk pahalı olur,sonrakiler ucuz

Asgarî geçim indirimi için insanın

Doğrusu Kraliçe Süreya’yı acıyası geliyor

Vermeliydi Allah on bir değil dokuz...

Adam Smith beş kuruşluk simidin ona çıktığını görseydi

Adamcağız yeni nazariyeler peşinde koşardı Türkiye için...”



MEDENİ HUKUK KÜRSÜSÜNDEN:

Doç Dr. İSMET GÜLÜMSER SUNGURBEY

(Şimdi Prof. Ve EMEKLİ) 

“Alkışla inletiyorsunuz öğreneği

Duyan “görmük” zannedecek

Cık cık tarlasına düştük	

Altı kaval üstü şeşhâne diyecek.

Bu yasa bu yasadan esi almış

(Tabii ben de Ataç’tan...) 

“GUGUK”çıkıyor artık “sınavlara”az kalmış...”

MEDENİ HUKUK KÜRSÜSÜNDEN:

Ordinaryüs Prof.Dr.HIFZI VELDET VELİDEDEOĞLU (MERHUM) 

“Bir tanıdık gelmiş bana fikrimi sordu

Şöyle şöyle oldu dedi

Hallediverdim işini, adamcağız

Dua ede ede gitti

“Hay Allah senden razı olsun...”

Meğer içi yanıkmış zavallının...”

Ne hoş ki rahat rahat

İstediğime diyebilirim üstad.

Ne doktoramı veriyorum 

Ne de yazdığım doktora tezi...

Hem iğreti adım da var

Eskiler ona der:”nam-ı müstear”

SİVRİ UÇ...

Batarsa da kan çıkmaz

Hanefi abdestini bozmaz.

Bu da sana arkadaş:

“Bu taşındır diyerek AMME’yi diksem başına

İDARE otursa gelip gelip karşına

Çarpışsan sınav sınav

Olsan Başını Vermeyen Şehit

Eder seni boyun sıra kitaplar istiap...

N olurdu şu bilgi olsaydı hap

Bir sabah,bir öğle,bir akşam alsaydık

Hepimiz âlim olsaydık.

Ey giriş kapısı ardına dek açık

Çıkış kapısı hafif aralık okul

Yıllardan beri kurulduğun yetmezse eğer

Yine yıllarca gönül tahtına kurul.

Ey talebe arkadaş isteme benden dua

Evde karın ve boy boy çocukların diploma bekler

Allah’a açılmış temiz eller...

                                                 ALPER  KÜRÜK', 'HOCALAR  KONUŞUYOR                              (İSTANBUL HUKUK FAKÜLTESİ  ÜÇÜNCÜ SINIFTA YAZILMIŞTIR.)                             CEZA HUK...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/hocalar-konusuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Götür Beni', 'al-gotur-beni-turgut-onal-0ojng', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Al götür beni

Al götür buralardan

Pembe güllerin açtığı yere.

Yalansız, dolansız

Riyasız

Kuşkulardan uzak

Sevginin çiçek çiçek açtığı

Gönüllerin sevda ile uçtuğu

Bir yerlere

Al götür beni

Al götür buralardan

İki gözüm çıksın yalanım varsa

Kuşlar bile ürker oldu insanlardan

Sevgi...masal kitaplarında kaldı sadece

Güneş ısıtmıyor içimizi artık

Gök bulanık,

Su bulanık,

Gönüller yanık sevgisizlikten.

Gözpınarlarında bile

Yaş kalmamış duygusuzluktan.

Al götür beni

Al götür buralardan.

Eğer varsa pembe düşlerde yaşatılan ülke

İnsanları makineleşmemiş,

İnsanları güleç,

İnsanları sevecen

Al götür beni.

Kanat takıp uçarım

Yedi iklim dört mevsim yorulmadan.

Yeter ki; 

Al götür beni

Al götür beni

Al götür beni buralardan.

Al götür beni birtanem, al götür

Kıskançlıktan, riyadan uzak yerlere

Al götür beni birtanem, al götür

Sevgi ırmaklarının aktığı yere.', 'Al götür beni Al götür buralardan Pembe güllerin açtığı yere. Yalansız, dolansız Riyasız Kuşkulardan uzak Sevginin çiçek çiçek açtığı Gönüll...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/al-gotur-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Yâr', 'gitme-y-r-ahmet-turan-altunsu-cmhq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gitme! ..

gitme hüzün çiçeğimi besleyen rüzgâr...

ağlayan şafaklarımın gri / siyah bulutlarıdır

vedaya muhalif bedbîn yüreğimde çırpınan...

“gidişinden” yaralı salkım saçak / kırık kanatlarıdır...

gitme! râzıyım zulmüne, poyraz olsan ne yazar? ..

gitme yâr! ..

gitme! .. yorgun omuzlarımdaki yük sen ol! 

sen ol aşkın dayanılmaz hazzındaki sır...

dokun parmak uçlarınla ıslak dudaklarıma...

dokun ve gör nasıl bir arzu taşır:

hisseden sen, bilen sen, şahidi bir tek sen ol! ..

gitme ah yâr! ..

ağyarına bile râzıyım telvesindeki, gözlerinin...

her katresinde biraz daha, biraz daha zehirlensem

sende ben, bende sen olmak değil midir ki? ..

ve alıp o telveleri, göl yeşilimle mühürlensem:

bendesi olmaz mıyım bendeki gözlerinin? ..

gitme ay yüzlü bahar, gitme telve gözlü yâr,

gitme, sar kollarını hasretime inat, sar! ..

__________________03.01.2006 / Güdül / Ankara

____________________Ahmet Turan Altunsu', 'gitme! .. gitme hüzün çiçeğimi besleyen rüzgâr... ağlayan şafaklarımın gri / siyah bulutlarıdır vedaya muhalif bedbîn yüreğimde çırpınan... ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gitme-yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sal öyle gitsin', 'sal-oyle-gitsin-nizami-sunguroglu-1zty2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kement atma yüreğimin bağına

Sevda çöllerine sal öyle gitsin

Beni koydun şu gurbette ateşe

Sıla rüzgarını kat öyle gitsin

Gurbette gönlümün sevdası yetim

Açma yüreğimi yıllarım ketum

Daldı bak gözlerim buğulu resmim

Uyanma rüyadan dal öyle gitsin

Yıllar katmer, katmer mevsimler hazan

Sılada kimsem yok nameler yazam

Gurbette kaynayan dert dolu kazan

Gam doldu yüreğim tart öyle gitsin

Göz yaşım akarken yüreğim gamlı

Hasretim vatana gurbetim harlı

Soğutmaz buzlar olsa da karlı

Al şu yüreğimi,al öyle gitsin..

03/01/2006

Nizami Sunguroğlu

Hollanda', 'Kement atma yüreğimin bağına Sevda çöllerine sal öyle gitsin Beni koydun şu gurbette ateşe Sıla rüzgarını kat öyle gitsin Gurbette gönlümün ...', ARRAY['Türk Edebiyatı','Şiir','Nizami Sunguroğlu']::text[], 8.5, '{"poet":"Nizami Sunguroğlu","poet_slug":"nizami-sunguroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sal-oyle-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun', 'biliyormusun-yusuf-onder-bahceci-mhypa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşığım ben gözlerine,

Kalbi çalan sözlerine,

Uyku girmez gözlerime,

Biliyormusun.

Seni sevdim uzakara,

Beni alsan kollarına,

Gel deyince yollarıma,

Geliyormusun.

Ben derdimi biliyorum,

Seni sevdim seviyorum,

Hayal edip gülüyorum

Gülüyormusun.

Seni sevdim derbederim,

Kendimi heder ederim,

Sen kendini yoklasana,

Neylersin.....', 'Aşığım ben gözlerine, Kalbi çalan sözlerine, Uyku girmez gözlerime, Biliyormusun. Seni sevdim uzakara, Beni alsan kollarına, Gel deyince yol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biliyormusun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunmaz', 'bulunmaz-mehmet-fatin-baki-z5hgo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle câhilsin ki Mehmet,  zâtınâ mekteb bulunmaz.

Şems’e istid’a’ yazarsan kâmil-ül-âm şeb bulunmaz.

Hazret-i Peryamberin sünnetlerinden saptığında

İlm-i-fıkh dersinde dün zikrettiğin mezheb bulunmaz.

Câmi dergâhında mazbût din-i islâm dersi versen

Mescidin bâbında yatmış bunca rind-meşreb bulunmaz.

Elli yıldır genç okuttun tıfl’a yol gösterdin ammâ

Hâla ümmîsin Fatin sen,  zâtınâ mekteb bulunmaz.

Şems = güneş

İstid’a’ = yalvararak birşey isteme

Kâmil-ül-âm = bütün yıl boyunca 

Şeb = gece

İlm-i fıkh = şerâit ilmi, hadis, tefsir,

Mazbût = doğru, sağlam bir şekilde 

Bâbında = kapısında 

Rind-meşreb = derviş kılıklı kalender

Tıfl = küçük çocuk

Ümmî = anadan doğma cahil 

Fâilâtün     fâilâtün     fâilâtün     fâilâtün

/ .   /    /   / .   /    /   / .   /    /   / .   /    /', 'Öyle câhilsin ki Mehmet,  zâtınâ mekteb bulunmaz. Şems’e istid’a’ yazarsan kâmil-ül-âm şeb bulunmaz. Hazret-i Peryamberin sünnetlerinden sap...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulunmaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Değil Bunun Adı', 'kader-degil-bunun-adi-yusuf-onder-bahceci-rfg0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdim gelmedin,

Bana güller vermedin,

Cânım, gülüm demedin,

Sevdiğimi bil yeter.

Ben aşığım vefakârım,

Seni sevdim cefakârım,

Sana yandım isyankârım,

Kader değil bunun adı.

Gözlerinden bilirim ben,

Beni seven o güzeli,

O da beni sevmiş belli,

Kader değil bunun adı.

Hep kafa kafaya verdiler,

Seni benden vazgeçirdiler,

Hatır, gönül yıktı bilmediler,

Kader değil bunun adı....', 'Seni sevdim gelmedin, Bana güller vermedin, Cânım, gülüm demedin, Sevdiğimi bil yeter. Ben aşığım vefakârım, Seni sevdim cefakârım, Sana yan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kader-degil-bunun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleme Bâri', 'soyleme-b-ri-mehmet-fatin-baki-0ygof', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyamazsan vezin âhengini câri 

Okuyup şi’rimi gör falsodan âri

Demesen doğruyu bir kez bile olsa

Alenen Hakka yalan söyleme bâri.

Câri = akıcı, yürüyen 

Falso = yanlış, hatâ

Âri = hür,, hatasız 

Alenen = apaçık 

Bâri = hiç olmazsa

Feilâtün      feilâtün      feilâtün 

.  .   /   /    .  .   /   /    .  .   /   /', 'Duyamazsan vezin âhengini câri  Okuyup şi’rimi gör falsodan âri Demesen doğruyu bir kez bile olsa Alenen Hakka yalan söyleme bâri. Câri = ak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soyleme-bari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ervâh', 'erv-h-mehmet-fatin-baki-dxiil', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim uyandırdı şehit ruhları dün Bosnada? Eyvah! 

Ne bilen var ne de ben söyleyebildim. Bilir Allah.

Ki eğer Bosnalı kardeşleri görmekse kaderde

Uyanır yardım için toprağa düşmüş yatan ervah.

Ervah = ruhlar

Feilâtün       feilâtün       feilâtün      feilâtün

.  .   /   /     .  .   /   /     .  .   /   /     .  .   /   /', 'Kim uyandırdı şehit ruhları dün Bosnada? Eyvah!  Ne bilen var ne de ben söyleyebildim. Bilir Allah. Ki eğer Bosnalı kardeşleri görmekse kade...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ervah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende', 'bende-mehmet-fatin-baki-nvi3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anadadan doğma bebekler gibi ben de

Ararım kabre  kadar  kendimi bende

Ne zaman benlik için şeytana uysam 

Yapıyor  benciliğim hep beni  bende.

Ömürüm bitse dahî köhne bedende

Yine nefs eyleyecek bendeni  bende.

Yalınız küflü kemik kalsa kefende 

Bu kemik  sağlayacak nâşımı bende 

Arasam hür köşe ben kendi içimde 

Beni nefsim yapacak  kendine bende.

Kabr = mezar

Ben de = ben dahi

Bende = özümde, içimde

Bende = köle

Feilâtün    feilâtün    feilâtün  

.  .   /   /  .  .   /   /  .  .   /   /', 'Anadadan doğma bebekler gibi ben de Ararım kabre  kadar  kendimi bende Ne zaman benlik için şeytana uysam  Yapıyor  benciliğim hep beni  ben...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bende-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müşkile', 'muskile-mehmet-fatin-baki-89vcs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufacık fark bile mevcutsa eşitlik darasında

Çıkarır müşkile zenginle fakir şahs arasında. 

Bu meşakkat çoğalırken, kızışan kavga da bitmez

Nice suçsuzlar ölürler bu cemiyyet yarasında.

Seneler  böylece  gelmişken eğer böyle giderse 

Çabucak çâre bulunmaz  beşerin yüz karasında.

Müşkile = zorluk 

Meşakkat = sıkıntı 

Feilâtün   feilâtün   feilâtün   feilâtün

.  .   /   / .  .   /   / .  .   /   / .  .   /   /', 'Ufacık fark bile mevcutsa eşitlik darasında Çıkarır müşkile zenginle fakir şahs arasında.  Bu meşakkat çoğalırken, kızışan kavga da bitmez N...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muskile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozpembe Dünyamız', 'tozpembe-dunyamiz-hasan-can-wubpq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha benden kopalı ne kadar oldu ki,

Daha dün gözlerin gözlerimdeydi,

Yüreğimde bir çocuktun küçük ellerinle,

Daha sonbahar bile gelmemişti.

Çocuk aşkıyla başladı sevdamız,

Tozpembe gördük dünyayı,

Herşey ne kadar güzeldi,

Belkide gerçekten tozpembeydi dünya.

Şimdi bana unut diyebilecek kadar büyüdün,

Olsun bakalım, birgün elbet bende büyürüm,

O tozpembe zamanlardan kurtulurum.

O zaman dünyanın rengi ne olur bilemem,

Belkide ben hiç değişemem...

Hayli zamandır yoktun,

Bugün duydum sesini,

Biraz buruktu sözlerin,

Birazda titrek nefesin.

Bir an o eski dünyamız geldi aklıma,

Hani tozpembe olan dünya,

Belki yeniden diye geçti kafamdan,

Ama anladım ki dünyalarımız çoktan değişmiş.

Evet, tek sorumlu benim yıkılan dünyamız adına,

Sorumsuzluğumun enkazını toplamaya çalışsamda,

Herşeyi yerine koymaya uğraşsamda, boşuna,

Söyleyemesende çoktan boşvermişsin sevdama.

Hayat öyle hızlı kayıp gitmişki avuçlarımızdan,

Farkında bile değiliz değişen zamanın, hayatın...

Şimdi ben her sayfama bir sevda şiiri ekliyorum,

Eski, yeni ne varsa, her hatırayı kalbimde biriktiriyorum,

O tozpembe hayaller çoktan akıp gitmiş gözlerimizden,

Bekliyorum, ama hiçbir şey geri gelmez onuda biliyorum.', 'Daha benden kopalı ne kadar oldu ki, Daha dün gözlerin gözlerimdeydi, Yüreğimde bir çocuktun küçük ellerinle, Daha sonbahar bile gelmemişti....', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tozpembe-dunyamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Defterimde İhanete Yer Yok', 'benim-defterimde-i-hanete-yer-yok-munevver-senol-hwujj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim defterimde ihanete yer yok.

Bir babamın ölümüne neden olanları                                       

Birde bana ihanet edenleri.

Asla ve asla affetmiyeceğim.

Kadınlar menfaati için aldatır diyorlar.

Ama yanılıyorlar.

Kanı bozuk olanlara, lafım yok.

AMMAA,  ben erkek olupta aşkından ölen.

Sonunda menfaatine yenik düşüp, ALDATAN.

Erkeğim diye geçinenleride gördüm.

Bir babamın ölümüne neden olanları,

Birde bana ihanet edenleri...

Asla ve asla affetmiyeceğim

Benim defterimde

        17.3.1995', 'Benim defterimde ihanete yer yok. Bir babamın ölümüne neden olanları                                        Birde bana ihanet edenleri. Asla...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-defterimde-ihanete-yer-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara yazım…..Derin sızım….', 'kara-yazim-derin-sizim-huseyin-ozcan-fkfaz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'asi, deli dolu bir ateş parçasıydın,			

elimde tutmaya çalıştığım……			

önce ellerimi yaktın……			

yüreğime almaya çalıştım seni			

orada da  sönmeyen yangınlar çıkardın….			

hayallerime almaya çalıştım seni,			

dar geldi sığmadın ….taştın.			

azad edeyim gitsin dedim,			

bir baktım ki ; 			

yürek mahkum,akıl mahkum,dil mahkum......', 'asi, deli dolu bir ateş parçasıydın,			 elimde tutmaya çalıştığım……			 önce ellerimi yaktın……			 yüreğime almaya çalıştım seni			 orada da  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kara-yazim-derin-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler(108) ''Mudurnu Konakları...''', 'maniler-108-mudurnu-konaklari-abdullah-atay-ai6po', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mudurnu konakları

Ağırlar  konukları

Mevlam artık görüver

Yüreği yanıkları....

Yarimin adı Neşe

Benzer doğan güneşe

Bir bakışı mest eder

Gülüşü de pürneşe...

Evin yanı medrese

Yarim gidiyor derse

Bin ömür ona feda

O da beni severse...

Bir zamanlar seninle

Ne güzeldik el ele

Gittiğin günden beri 

Her günüm kahır çile...

Al kuşağı sırmalı

Kömür gözler sürmeli

Yari gördüğüm yerde

Sarım sarım sarmalı...

Haber geldi can dosttan

Yarim giymiş al fistan

Aşksız gönül çöl olur

Seven gönül gülistan...

Ben yarime vurgunum

Onsuz geçmez bir günüm

O yar benden gidince

Hüzünlere sürgünüm...

Yarsız garip bir kulum

Lal olur ağzım dilim

Sevdiğimi görünce

Güller açar her dalım...', 'Mudurnu konakları Ağırlar  konukları Mevlam artık görüver Yüreği yanıkları.... Yarimin adı Neşe Benzer doğan güneşe Bir bakışı mest eder Gül...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-108-mudurnu-konaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarsın', 'yanarsin-huseyin-ozcan-1mm9b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'olmayacak bir sevdaya,			

böyle olmayacak hayaller kurarsan,			

sonra,gerçek bir tokat gibi patlar			

yüzünde en şiddetiyle……			

ve hüzün en kızıl haliyle girer içine,			

zapdet. zaptedebilirsen gözyaşlarını,			

gel söz geçir,geçirebilirsen  yüreğine,			

hadi, terketsin seni şimdi hüzün.

			

git hayallerini at en derin denizlere,			

savur sevdanı en acımasız rüzgarlara,			

en derin çukuru aç toprakta			

göm içine içindeki tüm arzularını			

sonra al başını………

geriye  bakmadan çek git..	

			

hatta yemin et.kuran üstüne,			

ekmek üstüne,hatta en sevdiğine,			

bir daha asla haram sevdaların			

peşinden koşmayacağım diye…….			

ve önce kendine dürüst ol,			

kendine verdiğin sözü tut….

.			

sonra al başını aklına da			

böyle olmayacak sevdalara dalıp,			

olmayacak hayaller peşinden koşma…….			

işte böyle sonun hüsran olur..			

cehennem gibi ateşlerde yanarsın…', 'olmayacak bir sevdaya,			 böyle olmayacak hayaller kurarsan,			 sonra,gerçek bir tokat gibi patlar			 yüzünde en şiddetiyle……			 ve hüzün en...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yanarsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yıl Daha Geçti', 'bir-yil-daha-gecti-mehmet-can-nx1cl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha geçti

Sensiz..

Senin geçen  bir yılın..

Bensiz..

Et ve tırnak gibiyiz demiştin.

Ayrıldık işte..

Yıl 2006.

Sen bensiz bende sensiz.', 'Bir yıl daha geçti Sensiz.. Senin geçen  bir yılın.. Bensiz.. Et ve tırnak gibiyiz demiştin. Ayrıldık işte.. Yıl 2006. Sen bensiz bende sens...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-yil-daha-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Kadar', 'senin-kadar-mehmet-can-ju3z2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi sevmedim  senin kadar..

Hiç kimseye bağlanmadım

Sana bağlandığım kadar..

Gideli iki yıl oldu..

Ömrümde elbette çok ağladım..

Ama hiç biri canımı yakmadı fazla..

Sana ağladığım kadar..', 'Hiç kimseyi sevmedim  senin kadar.. Hiç kimseye bağlanmadım Sana bağlandığım kadar.. Gideli iki yıl oldu.. Ömrümde elbette çok ağladım.. Ama...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senin-kadar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka Sevgili Bilmem', 'senden-baska-sevgili-bilmem-huseyin-ozan-ozturk-9dq9y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden başka sevgili tanımam,bilmem gayri.

Sensiz yaşayamam,sensizde ölmem gayri.

Varlığın öylesine dolmuş ki benliğime,

Yanına çağırsan da; gerek yok,gelmem gayri.', 'Senden başka sevgili tanımam,bilmem gayri. Sensiz yaşayamam,sensizde ölmem gayri. Varlığın öylesine dolmuş ki benliğime, Yanına çağırsan da;...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senden-baska-sevgili-bilmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şarkı', 'her-sarki-mehmet-can-x0yo6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şarkıda sen varsın..

Dinlediğim de..

Nereye baksam 

Ne yapsam..

Ya önümdesin..

Ya yanımdasın..

Kapatsam gözlerimi..

İçimdesin..

Kavgalı anlarımız neden aklıma gelmez..

Kırdığın sözleri neden hatırlamam..

Yeter artık değimli? 

Gülümseyen bakışlarını çek üzerimden..

Terk eden sendin..

Git artık..

Çık ruyalarımdan

Çık hülyalarımdan…

Ama çık dediysem de

Terk etme yine beni..

Böyle de güzelsin..

Git dediğimde bilki

Gel diyorum sana..

Hadi..', 'Her şarkıda sen varsın.. Dinlediğim de.. Nereye baksam  Ne yapsam.. Ya önümdesin.. Ya yanımdasın.. Kapatsam gözlerimi.. İçimdesin.. Kavgalı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur?', 'ne-olur-mustafa-ali-kucukcopur-9l9gv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç olmazsa görünsen düşümde

Ne olur,kıvılcım alevlense düşün de.

Seslensen canımdaki en sevimli cana

Sende katılsan artık bu serancama.', 'Hiç olmazsa görünsen düşümde Ne olur,kıvılcım alevlense düşün de. Seslensen canımdaki en sevimli cana Sende katılsan artık bu serancama....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ali Küçükçopur']::text[], 8.5, '{"poet":"Mustafa Ali Küçükçopur","poet_slug":"mustafa-ali-kucukcopur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-olur-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Buldum Sonunda', 'seni-buldum-sonunda-huseyin-ozan-ozturk-irz4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalı bir denizdim ve duruldum sonunda.

Koştum aşk yollarında ve yoruldum sonunda.

Gönlüme yoldaş olsun diyerek gece gündüz; 

Elliüç yıl aradım seni buldum sonunda...', 'Dalgalı bir denizdim ve duruldum sonunda. Koştum aşk yollarında ve yoruldum sonunda. Gönlüme yoldaş olsun diyerek gece gündüz;  Elliüç yıl a...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-buldum-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sonraki Limana (120)', 'bir-sonraki-limana-120-i-brahim-arslan-8amii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Limanına sığındım

Ne limanı bu, bilmeden...

Gelip geçen bir yolcu değilim,

Hep hayallerimin peşinden gittim ben,

En son hiç kuş uçmayan tepesinden,

Gemi uğramayan,denizi olmayan

Yolumun sonuna vardım..

Hayatın bu limanına sığındım...

Bir tarafım harabeye dönmüş,

Öyle ki sanki Sodom-Gomore

Bir tarafımda yine hayat var

Bir tarafımda nefes almayanlar

Bir tarafımda milyon insan var...

Milyon kere yemin,neredeyim

Hangi limanı bu hayatın bilmiyorum

Bildiğim tek şey,

Gelmek istediğim yerde değilim...

Bir tarafımda umut tacirleri

Bir tarafımda mübarek insanlar

Sudan yeni çıkmış balık gibiyim...

Bildiğim bir şey varsa,

Bu dünya benim dünya değil...

Bu benim hayallerimdeki liman mı? 

Gemi uğramayan,denizi olmayan

Bilmeden hayatın hangi limanına sığındım..

Nerede ve nasıl bir sonraki liman...

2005', 'Limanına sığındım Ne limanı bu, bilmeden... Gelip geçen bir yolcu değilim, Hep hayallerimin peşinden gittim ben, En son hiç kuş uçmayan tepe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sonraki-limana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esaretim (121)', 'esaretim-121-i-brahim-arslan-eb8tb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'esaretim

beni sensizliğe sürgün

ettiğin gün başladı,

ben o gün bugündür

yaşamıyorum

gülüm...

sen sensizliği

öyle kolay mı sandın? 

unutacak mı sandın

bu yürek seni

vazgeçer mi sandın...

sen benim güneşim olduğunu,

bilmiyor musun? 

sen mutlu ol! diyedir

kadere boyun eğişim

sırf bu yüzden! 

yaşar gibi görünüyorum

insanlar arasında...', 'esaretim beni sensizliğe sürgün ettiğin gün başladı, ben o gün bugündür yaşamıyorum gülüm... sen sensizliği öyle kolay mı sandın?  unutacak ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esaretim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Başkasına Yar Olsanda', 'sevdim-baskasina-yar-olsanda-huseyin-ozan-ozturk-9oaap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kış olsanda sevdim,bahar olsanda...

Dost olsanda sevdim.ağyar olsanda..

Aşkımı bilememzsin Sevgili Güzçiçeğim; 

Sevdim birkez,başkasına yar olsanda...', 'Kış olsanda sevdim,bahar olsanda... Dost olsanda sevdim.ağyar olsanda.. Aşkımı bilememzsin Sevgili Güzçiçeğim;  Sevdim birkez,başkasına yar ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdim-baskasina-yar-olsanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Gecelerim', 'sensiz-gecelerim-huseyin-ozan-ozturk-uw3ye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz gecelerimin sırrına erebilsen.

Çektiğim acıları bir kerre görebilsen,

Mum gibi yanardın da,erirdin damla damla.

Alev alev yanan şu, gönlüme girebilsen.', 'Sensiz gecelerimin sırrına erebilsen. Çektiğim acıları bir kerre görebilsen, Mum gibi yanardın da,erirdin damla damla. Alev alev yanan şu, g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-gecelerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah! (122)', 'eyvah-122-i-brahim-arslan-c93lx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eyvah

bahar ayları geçmişte

farkedememişim bunca zaman...

saçlarıma beyaz,ömrüme kış gelmişte

inkar etmişim bunca zaman...

kuşlar ölüm şarkısını söylüyormuş

bedenim göç hazırlığı yapıyormuşta

çöktüğümü gözlerim görmüyormuş,

görmemeye inat etmişim bunca zaman...

eyvah

hazırlıkta yapmadım

yaman bir ayrılık varmış bu diyardan

sona gelmişim adım adım

durmadan gidiyormuşum bunca zaman...

artık neyi yalanlıyorsun

hala duymuyormusun,ölümün ayak seslerini

o sana sen ona yaklaşıyorsun..

Azrail''in eli ensemdeymiş bunca zaman...

eyvah

ne baharlar geçmişte

seyretmişim bunca zaman

kuşlar ölüm şarkısını söylüyormuş

ninni zannetmişim bunca zaman...

      2004', 'eyvah bahar ayları geçmişte farkedememişim bunca zaman... saçlarıma beyaz,ömrüme kış gelmişte inkar etmişim bunca zaman... kuşlar ölüm şarkı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eyvah-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayınca', 'olmayinca-seyfet-bozcali-z1dkv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıkık bahçelerde bülbül ötermi? 

Onu dillendiren gül olmayınca.

Dermansız yaralar şifa buurmu? 

Hakkı hakim kılan kul olmayınca...

İmansız sinede merhamet olmaz.

Yaratanı bilen kula kul olmaz.

Hak yolunda giden asla yorulmaz,

O''na köstek olan şer olmayınca...

İnsan olan hiç kötülük yapar mı? 

Mevla''yı zikreden kalp pas tutar mı? 

Çekirdekten koca ağaç biter mi? 

İlahi tecelli var olmayınca...

Sabah doğan güneş akşam batıyor.

Arı bin bir çiçekten bal yapıyor.

Baykuş neden viranede ötüyor? 

Anlamı kalmazdı sır olmayınca...

Seyfet der ömrümüz dünyada anlık,

Son nefeste fayda vermez pişmanlık,

Binek tabut olur,evse mezarlık,

Kurtuluş zor,amelin olmayınca...

                 ''Vakit geçmeden namaza,ölüm gelmeden tövbeye acele edin.''

                                                                      Hadis-i şerif

25.2.1992', 'Yıkık bahçelerde bülbül ötermi?  Onu dillendiren gül olmayınca. Dermansız yaralar şifa buurmu?  Hakkı hakim kılan kul olmayınca... İmansız s...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olmayinca-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Halepçe', 'ah-halepce-i-sa-tekin-3qa7t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah Dilan

Ah Zilan

Beynimden vurulmuşum Halepçe''de

Yüreğim dört parça

Dilan sağda yatıyor

Zilan solda

Yer gök zehir kusuyor

Gökten alevler yağdırıyor Baas uçakları

Kuşlar uçmuyor

İnsanlarım ölüyor

Bebeler katlediliyor

Ah Zilan

Ah Dilan

Halepçe yanıyor

Ey Amed

Kara Amed

Acıların yurdu

Surları kara Amed

Kara haber tez duyulur

Ah Zilan 

Ah Dilan

Ciğerim yanıyor

Yüreğim kanıyor

Halepçe yanıyor

Zilan''lar, Dilan''lar yanıyor

İsimsiz bebeler ölüyor

Ah Zilan 

Ah Dilan

Yine bize ferman

Yine bize katliam

Ve Dünya sağır

Ve biz sahipsiz

Ve tüm Cihan sessiz

Sen Ağla kara Amed sen ağla

Dilan için ağla 

Zilan için ağla

Halepçe için ağla

Ağla ki...

Kara surların bu vahşete

Gözyaşı döksün

Döksün sel olsun

Hiç durmadan

Dicle''ye aksın

Ta Halepçe''ye kadar

Alsın götürsün

Tüm matemleri

Tüm acıları

Sulasın göz yaşlarımız

Ülkemin tüm topraklarını

Ah Zilan

Ah Dilan

Acıların yurdu

Direncin Abidesi

Gözü yaşlı kara Amed

Ağla Dilan için

Ağla Zilan için

Bugün bizlere ferman

Bugün bizlere katliam

Gübreledik kanımızla

Tüm topraklarımızı

Demledik içimize tüm acıları

Yüreğim yanıyor

Ateş topu sanki her yer

Gökyüzünden zehir kusuyor Baasçılar

Can pazarındayız

Ah Dilan 

Ah Zilan

Dicle yaslı

Fırat Hırçın

Ay karanlık

Dağlarda duman

Kızıla boyandı her yan

Ah Halepçe Ah

Nagazaki Hiroşima sanki

Ağla Amed

Ağla Ülkem

Bugün bize ferman 

Bugün bize katliam

Herkes suskun ve tepkisiz

Dünya sağır ve kör

Ağla Amed

Dilan için ağla

Zilan için ağla 

Acımız sonsuz

Öfkemiz büyük

Ah Halepçe ah...

Seslenen yürektir Kitabımdan', 'Ah Dilan Ah Zilan Beynimden vurulmuşum Halepçe''de Yüreğim dört parça Dilan sağda yatıyor Zilan solda Yer gök zehir kusuyor Gökten alevler ya...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/ah-halepce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Yeri (123)', 'cehennem-yeri-123-i-brahim-arslan-f4det', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cehennem yeri

Gönlüm bir cehennem yeri

Girme gönlüme kavrulursun

Yanarsın benim gibi..

Gece çöktüğünde,

Yalnızlıktan ağlarsın benim gibi...

Bu nasıl ateş ki hiç sönmez

Yakar yüreğimi,yüreğini

Hiçbir yangını küçümseme...

Beni bu yangınla birbaşıma

Bırakmalısın...

Koş,benden uzaklara koş,haydi! 

Asiyim ben

Yanmayı hakettim böyle

Yenilmeyi,yalnızlığı hakettim

Bin güneş doğuyor bedenimde şimdi

Bin cehennem var bende,cehennem gibi..

Yanmışım

Bunca zaman yanılmışım

İnsan yaratılmışım

Belli ki insan kalamamışım...

Asiyim ben

Kendimi arayan biriyim ben

Cehennem gibi yanmayı da bilirim,ben

Cehennemi yakmayı da...

Beni bu yangınla bir başıma bırak

Ancak bu yangınla sönerim ben...

                      2004', 'Cehennem yeri Gönlüm bir cehennem yeri Girme gönlüme kavrulursun Yanarsın benim gibi.. Gece çöktüğünde, Yalnızlıktan ağlarsın benim gibi... ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cehennem-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mertliğin Sesi', 'mertligin-sesi-altay-taskin-5sjsp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece düşlerimizde, gündüz hakikatle gözümüzle hepsini

Ömrümüz bitinceye kadar hissedeceğiz hayatın sevincini, kederini

Yaşarken anlasın hep insanlık hatırlatsın mertliğin ezelini,

Bir ok hızıyla yırtsın namertlerin sesini, kırsın belini,

Düşürsün hiç yere can yakmak isteyenlerin maskesini

Göğsü kabarsın toprağın, selamlasın çiçekler gelip geçeni,

Toprak donatsın çiçeklerle ebedi mertin mabedini

Gelecek nesillerin yaşatması için bu insanlık eserini...', 'Gece düşlerimizde, gündüz hakikatle gözümüzle hepsini Ömrümüz bitinceye kadar hissedeceğiz hayatın sevincini, kederini Yaşarken anlasın hep ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mertligin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi Yak (beyit)', 'oylesi-yak-beyit-abdulkadir-karaca-gmdvx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Veryansın etme bana,yar bırak canım yansın

Öylesi yak ömrümü, yanmayanlar utansın

(aralık 2005)', 'Veryansın etme bana,yar bırak canım yansın Öylesi yak ömrümü, yanmayanlar utansın (aralık 2005)...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/oylesi-yak-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Çığlık', 'sessiz-ciglik-yasemin-kurt-xqwos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu son feryadım aşkım,

Seni geçmişe gömüyorum.

Sessizce gelen aşkını sessizce kalbime hapsedip,

Senin dünyandan çekiliyorum.

Artık sevdam acı versede bana yapmalıyım,

Sonum iyi değil yoksa deliriyorum.

Kaçmak çözüm değil biliyorum.

Sessizce ağlıyor ve çekip gidiyorum.

Sen her zaman kalbimin efendisi kalacaksın,

Beni bilmediğin gibi tanımayacaksın.

Sen başka ellerde gerçeği ararken,

Ben ezilen kırçiçekleri misali gideceğim.

Arkadaşlarım nasihat ederdi de dinlemezdim.

Şimdi hepsi haklı çıktı hepsi.

Platonik gerçekle aşka olmaz demişlerdi.

Acı yaren olur acı çekersin,

Dinlemeden sevdim içimden gizlice seni.

Her gelişini bekledim umutsuzca,

Acıyan kalbimin feryadlarını bile duymak istemedim.

İşte sessizce ben gidiyorum.

Sevgi güzel ama karşılıklı olunca,

Sen bilmesende yinede pişman değilim.

Birgün ellerin olsan bile,

Seni ölesiye hep seveceğim.

Bu son sessiz çığlığım aşkım,

Seni severken gidiyorum.

Bilmediğin sevgim yanımda kalacak hep,

Seni son kez çığlık çığlığa seviyorum.', 'Bu son feryadım aşkım, Seni geçmişe gömüyorum. Sessizce gelen aşkını sessizce kalbime hapsedip, Senin dünyandan çekiliyorum. Artık sevdam ac...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kurt']::text[], 8.5, '{"poet":"Yasemin Kurt","poet_slug":"yasemin-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sessiz-ciglik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim (124)', 'sevdigim-124-i-brahim-arslan-colkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğim gecelere benziyor

Hep sır içinde sır

Yatıyor yüreğimin bir yerinde,

Belki bin asır...

Bu bendeki sevda nasıl bir sevda,

Bu sevdayı yürek nasıl taşır...

Sanki yok benden başka,böyle büyük seven

Böyle yanan ve bu yangını küçümseyen...

Yazanlar yanlış yazmış büyük aşkları,

Onlar,sevgimden haberi olmayanlar

O aşkların kalmamış, şimdi külleri

Benim kalbimse hala bir yangın yeri...

Sevdiğim gecelere benziyor

Hep sır içinde sır

Yaşıyor yüreğimin bir yerinde,

Belki bin asır...

Yaşayan bu acıyı nasıl taşır

Nasıl tadar hergün ölmeyi,

Her öldüğünde yine nasıl dirilir

Gel bana sor,elbet bilen bilir...

Ve unutmaz bu yürek hiçbir an seni,

Yaşatır kendi bedeninde bu can seni...

Gün gelir bu sevdada tarihe karışır..

Ve karışmalı...

Sevdiğim gecelere benziyor

Hep sır içinde sır

Yanıyor yüreğimin her bir yeri,

Belki bin asır...

                                   24.6.2004', 'Sevdiğim gecelere benziyor Hep sır içinde sır Yatıyor yüreğimin bir yerinde, Belki bin asır... Bu bendeki sevda nasıl bir sevda, Bu sevdayı ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdigim-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Bebek', 'hos-geldin-bebek-mehmet-dogan-8-a8wbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çığlık çığlığa giriverdin aramıza

Sevinecek mi

Sitem mi edeceğim bilemiyorum

Mademki dönüşü yok bu yolun

Hoş geldin hanemize

Sefalar getiresin yuvamıza

Sana sıcacık kucağım ninnilerim masallarım...

Nasihattan gayrı yok mirasım

Umut sensin 

Evren senin

İşte önünde yolun

Koşuşmaya boğuşmaya mahkümsun

Hazırlan

Sevgileri  sevimsizlikleri

Dostlukları kahpelikleri

Umutları yıkımları göğüsleyeceğin

Bir yığın ikilem bir sürü denklem var

Kim bilir kollarında beyninde prangalar taşıyacak

Mahpuslarda sürgünlerde itilip kakılacaksın

Darbelerde 

Postalların dipçiklerin altında ezilecek 

İşkencelerin içinde  yoğrulacaksın

Belki panzerler tanklar kıstıracak bir köşede

Anandan emdiğim aksütü burnundan getirecekler

İnsan olmanın özgür düşüncenin

Özgür düşünebilmenin büyük bedelleri var

Ne sınavlardan ne sıratlardan geçeceksin

Nükleer yağmurlar...

Kan barut kokusu ülkende ülkelerde...

Herkeste can ve namus korkusu

Bir genç bir asker ikisi de vatan yavrusu

Dağ başlarında yol ortasında 

Birer birer düşüyor olacak

Ağıtlar duyacaksın

Bir yavuklunun 

Bir ananın acı feryatları doldurunca kulaklarını

İçin yanmaz yüreğin burkulmaz mı çocuğum

İnsanın insanlığı pervasızca bitirdiğini görünce

İnsan oldığundan utanacaksın

Kine nefrete gerek yok 

İyi kötü insan bu

Ben buyum diyebildin mi

Zalimden diktatörden daha güçlüsün

Güçlü olmaya mecbur ve mahkümsun

Yorulacak çok yorulacaksın bu yolda 

İnanıyorum güveniyorum sana

Okuyacaksın...

Konuşacak tartışacak danışacaksın

Doğruyu güzeli kendin bulacaksın

Ak güvercinlerin barışa uçuştuğu

İnsanların kardeşçe el ele tutuştuğu

Cenneti sen kuracaksın...

     23.08.1979', 'Çığlık çığlığa giriverdin aramıza Sevinecek mi Sitem mi edeceğim bilemiyorum Mademki dönüşü yok bu yolun Hoş geldin hanemize Sefalar getires...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hos-geldin-bebek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan âyetler', 'yasayan-yetler-sair-ahrazi-fzm2v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana el açtı hayat,hep sana yalvardı mekân

Senin aşkınla yağıp besledi ırmakları su.

Evvelin yok.Sana eş olmadı hiçbir tabakan

Sen yarattın göğü,eşyâyı ve bâkî ulusu.

Güneşin âteşi,solgun hava,topraktaki nem

Seni göstermede her ân; ‘’Yaşatır Râb! ’’ diyerek.

Ne hayatmış ne zarâfet ne de canmış hazinem; 

Seni bilmekmiş efendim,bana yalnız bu gerek! 

* * *', 'Sana el açtı hayat,hep sana yalvardı mekân Senin aşkınla yağıp besledi ırmakları su. Evvelin yok.Sana eş olmadı hiçbir tabakan Sen yarattın ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasayan-ayetler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimoza', 'mimoza-zekiye-comakli-ruf72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiler ölmez derler

Akar damarda sıcak

Dudağın kıvrımında

Gözlerde yaşayarak

Yemyeşil sabahlarda 

Sohbet koyulaşmalı

Gümüşten ipliklerle

Sevdalar dokunmalı

Yüreğime göklerden 

Avuç avuç kor yağsa

Sevmak asla suç değil

Anlasana mimoza

Sevdaların üstüne 

Çökmesin karanlıklar

O güzel duygulara 

Yağmasın mor yağmurlar

Sevda kutsal olmalı

Ta..yürekten vurmalı

Üzerine yalnızca

Beyaz yağmur yağmalı

Yüreğime göklerden

Avuş Avuç kor yağsa

Sevmak asla suç değil

Anlasana Mimoza

Ruhumuzda işkence

 olmasın hiç bir gece

Masmavi bulutlardan

Sevgi yağsın sessizce

Gül renkli şafaklarda

Kalpler karşı karşıya

Bir mum gibi eriyip

Tükensem çerağında

Yüreğime göklerden 

Avuç avuç kor yağsa

Sevmek asla suç değil

Anlasana mimoza', 'Sevgiler ölmez derler Akar damarda sıcak Dudağın kıvrımında Gözlerde yaşayarak Yemyeşil sabahlarda  Sohbet koyulaşmalı Gümüşten ipliklerle S...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Çomaklı']::text[], 8.5, '{"poet":"Zekiye Çomaklı","poet_slug":"zekiye-comakli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mimoza-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Ben (125)', 'senle-ben-125-i-brahim-arslan-8hl0z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski ve yeni ne varsa senden

Sildim yüreğimden aşkının izlerini

Anladım hep kaybediyorum seni,

İki ayrı bedeniz senle ben...

Sen ölümden kaçar gibi

Ben ölüme koşar gibi...

Eski ve yeni ne varsa senden 

Ve senden başka ne varsa hayatımda

Seninle birlikte sildim herşeyi

Geçtim bütün sevdiklerimden...

Şimdi iki ayrı deniziz senle ben..

Sen akdeniz gibi,

Ben karadeniz gibi...

Eski ve yeni ne varsa senden

Senden sonra hayat bir kafes gibi

Artık hayat bir nefes gibi

Yaşıyorum sen olmadan

Ve yaşıyorum şimdi nefes almadan...

Sen cennette yaşar gibi

Ben cehennem de yanar gibi

Hep ayrıyız senle ben...', 'Eski ve yeni ne varsa senden Sildim yüreğimden aşkının izlerini Anladım hep kaybediyorum seni, İki ayrı bedeniz senle ben... Sen ölümden kaç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senle-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhran', 'buhran-charles-bukowski-2dhoq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çok fazla 

çok az 

ya da çok geç 

çok şişman 

çok zayıf 

ya da çok kötü 

kahkaha 

ya da gözyaşı 

ya da kusursuz 

kayıtsızlık 

nefret edenler 

sevenler 

ellerindeki şarap şişelerini sallayarak 

önlerine çıkanları süngüleyip 

kadınların ırzına geçen ordular 

ya da ucuz bir pansiyon odasında 

Marilyn Monroe''nun fotoğrafıyla yaşayan bir ihtiyar 

o denli büyük ki dünyadaki yalnızlık 

onu saatin kollarının ağır hareketlerinde 

bile görebilirsiniz. 

o denli büyük ki dünyadaki yalnızlık 

onu Vegas''ta, Baltimore''da ya da Münih''te 

yanıp sönen neon ışıklarında görebilirsiniz. 

insanlar yorgun, 

hayat tarafından cezalandırılmış, 

ya sevgiyle ya da sevgisizlikle 

sakatlanmış. 

yeni hükümetlere ihtiyacımız yok 

yeni devrimlere ihtiyacımız yok 

yeni kadınlara ihtiyacımız yok 

yeni yollara ihtiyacımız yok 

şevkate ihtiyacımız var. 

müşfik davranmıyoruz 

birbirimize. 

müşfik davranmıyoruz. 

korkuyoruz. 

nefretin gücü simgelediğini 

sanıyoruz. 

cezalandırmanın 

sevgi olduğunu. 

daha az sahte bir eğitim bize gereken 

daha az kural 

daha az polis 

ve daha iyi öğretmenler. 

bir odada 

bir başına acı çeken 

öpülmemiş 

dokunulmamış 

bir başına bitki sulayan 

olsa da çalmayacak 

bir telefondan yoksun 

insanın dehşetini unutuyoruz. 

müşfik davranmıyoruz birbirimize 

müşfik davranmıyoruz birbirimize 

müşfik davranmıyoruz birbirimize 

boncuklar sallanır, bulutlar örter 

köpekler gül bahçesine işer 

bir çocuğun kafasını koparır cani 

dondurma külahından bir ısırık alır gibi 

okyanus bir gelip 

bir giderken 

anlamsız bir ayın esaretinde. 

müşfik davranmıyor insanlar birbirine.', 'çok fazla  çok az  ya da çok geç  çok şişman  çok zayıf  ya da çok kötü  kahkaha  ya da gözyaşı  ya da kusursuz  kayıtsızlık  nefret edenler...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/buhran-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyguları Giyinmek', 'duygulari-giyinmek-zekiye-comakli-gxama', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mümkün olsaydı diyorum 

duyguları giyinmek

Terziye verip duygularımı 

Diktirseydim

Kocaman cepleri olsa

Artanları doldursaydım

Yol boyu yalın ayak

Duygularımı giyinip yürüseydim

Yıldızların aydınlığında

Kaleme tutsak olmadan

Dolaşsaydım

Acıları kara

Ümitleri pembe

Özlemleri mavi giyinseydim

Vefasızlığı gri anlatıp

Arzuya kırmızı

Maziye sarı ile dönseydim

Ati için beyaz giyinip 

Geceleriçıkarmasaydım

Arkası gelmese bu masalın

Uykum kaçmasa gece yarıları

Dünyanın tortularından ayırıp

Masalla gerçeği bir potada eritsem 

ve düşlerimin yakamozlarıyla

Duygularımı giyinebilsem', 'Mümkün olsaydı diyorum  duyguları giyinmek Terziye verip duygularımı  Diktirseydim Kocaman cepleri olsa Artanları doldursaydım Yol boyu yalı...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Çomaklı']::text[], 8.5, '{"poet":"Zekiye Çomaklı","poet_slug":"zekiye-comakli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duygulari-giyinmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışlarında Mecnun İlahı Anlar', 'bakislarinda-mecnun-i-lahi-anlar-bahadir-kursun-dp0vh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir musiki tadında girdin dünyama 

en yoksun anlarında kalbimin imandan

çaldın ilahilerin en güzelini gönül makamında

nerde kaldı sazendeler,nerde meyler

mehtapsız gecelerimde nerde soframın şeytanları

karanlık odalarda nerde parlak bakışların

şehvetinle mest olur azgın nevsim

seni arar kadehlerde gözbebeklerim

sensiz yatağım kucaklamaz bedenimi

uykular kabullenmez sensiz geceleri

karanlık sarmışken ketum bedenimi

acze düşer senin ışığında geceler

varlığın yakar kara çalıları

bastığın yerde kan revan güller biter

uzansa ruhum avuçlarından ilaha

dökülür tüm günahlarım kirpiklerimden o anda

çekilirken sisler karanlık sularımdan

bir demet yakamoz düşer mehtap bakışlarından

yokluğunda kasırgalar kopar denizlerimde

korku sarar mahzenimin duvarlarını

yangınlara müptela olur ömrüm

bir yağmur tanesinde ararım sıcaklığını

aseletinde saklıdır bir mucize

ölümsüzlük nehrinde yıkanmış sanki ellerin

ak pak teninde açar en güzel kardelenler

bakışlarında mecnun ilahı anlar

zamanın tutsağıyken her ruh alemde

ben yalnız sana tutkunum zamandan da ötede

yalnız sana secde eder bu baş her alemde

yalnız sanadır bana dair olan her alem de', 'bir musiki tadında girdin dünyama  en yoksun anlarında kalbimin imandan çaldın ilahilerin en güzelini gönül makamında nerde kaldı sazendeler...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Kurşun']::text[], 8.5, '{"poet":"Bahadır Kurşun","poet_slug":"bahadir-kursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bakislarinda-mecnun-ilahi-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para Sesi,Kadın sesi,Su sesi', 'para-sesi-kadin-sesi-su-sesi-seyfet-bozcali-2nqd5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tüm tarih boyunca etkili olmuş,

Para sesi,kadın sesi.su sesi.

Ülkeler arası hep sorun olmuş,

Para sesi,kadın sesi,su sesi...

Birisi ülkenin ekonomisi,

Diğeri toplumun aşkı,sevgisi.

Öteki milletin yaşam öyküsü,

Para sesi,kadın sesi,su sesi...

Kadın uğrunadır tüm cinayetler,

Bunca kurulan,yok olan yuvalar.

Yazılan şiirler,aşklar,sevgiler,

Para sesi,kadın sesi,su sesi...

Su içi başlamış sınır savaşı,

Onunla var olur ekmeyi,aşı.

Onunla eş değer yaşam savaşı,

Para sesi,kadın sesi, su sesi...

Öğretmen Seyfet der bu üç seste hoş.

Hayırlı olursa hayat  daha hoş.

Bize derler hayat boyu durma koş,

Para sesi,kadın sesi,su sesi...

           ''Üç ses vardıd ki; Allah  onları çok sever.

             Zikredenin sesi.Kur-an okuyanın sesi,

             Seher vakti istiğfar edenin sesi.''

                                        Hadis-i şerif', 'Tüm tarih boyunca etkili olmuş, Para sesi,kadın sesi.su sesi. Ülkeler arası hep sorun olmuş, Para sesi,kadın sesi,su sesi... Birisi ülkenin ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/para-sesi-kadin-sesi-su-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum (126)', 'gidiyorum-126-i-brahim-arslan-gz5wd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sorma beni,arama beni

Gittiğim yeri bende bilmiyorum..

Arkama bakmadım bile giderken,

Önümü görmüyordum..

Ayaklarım çıplaktı, umrumda da değildi

Yolumun sonu var mıydı,bilmiyordum

Seni bulmaktan hangi güç alırdı beni,

Seni bulmadan döner miydim bu sokaktan...

Sorma beni sevdiğim,

Seni terk-ediyorum işte,

Şimdi senden başkasına gidiyorum,

Şaşırma O''ndan geldim O''na gidiyorum...

Yalnız değildim O vardı yanımda,

Biliyordum

Belki bu yüzden korkmuyordum

Başıma yağan yıldızlardan...

Sahte sevgin al senin olsun,

Ben şimdi ölmeye değil,ölmemeye gidiyorum

Kavuşuyorum,sadece bir adım kaldı

Onuda atıyorum...

               28.04.2004', 'Sorma beni,arama beni Gittiğim yeri bende bilmiyorum.. Arkama bakmadım bile giderken, Önümü görmüyordum.. Ayaklarım çıplaktı, umrumda da değ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidiyorum-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni istemiyorum', 'seni-istemiyorum-yasemin-kurt-j64a5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sordum dün nerdesin diye seni tanıdıklarıma,

Yine başka güzelde geziyor dediler.

İçim burkuldu,ağıt yaktım kalbimden,

Duydun mu inleyen nağmalerde sesimi? 

Acıtmadı mı hiç içini? 

Acıtsa ne olur ki sen bilmezsin sevilmenin kıymetini.

Sana artık hiçbirşey için söz veremem.

Senle sonum yok biliyorum.

Oyun oynayan sen,oynanan ben,

Seven ben,seviyorum diye nice güzeli aldatan sen.

Yokluğun içimi ezip geçsede,

Boyun eğmiyeceğim artık bu aşka ben.

Seni sevsemde,

Müsadem yok senin beni çiğnemene.

Sen birşeyi unuttun bende.

Severken birden silip geçeceğimi.

Şimdi yolunu gözlerim gözlese bile,

Kalbim ne kin dolu ne de matem,

Gitmek çare değil artık,

Ödül oldu kalbim için.

Dün arkadaşlara rastladım.

Sen pişmanmışsın bu aşk için.

Belki dönerim diye pencereden dışarı bakıp,

Seviyor,gelecek dermişsin.

Seviyorum inkar  edecek değilim bebeğim.

Ama bende sabır bitti,

Sana geri dönmeyeceğim.

Sen başka dünyalara şimdi istediğin kadar git,

Ben bil ki o eve geri gelmeyeceğim.

Ve seni her zaman sevsemde,

Seni istemiyeceğim.', 'Sordum dün nerdesin diye seni tanıdıklarıma, Yine başka güzelde geziyor dediler. İçim burkuldu,ağıt yaktım kalbimden, Duydun mu inleyen nağm...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kurt']::text[], 8.5, '{"poet":"Yasemin Kurt","poet_slug":"yasemin-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılan Baht', 'kirilan-baht-altay-taskin-zt76g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göçtü bir taze baht yine

Karanlıklarda çürümüş yaprak

Büyük bir örümcek ağı gözesiz

Dayanmıyor uzaklar hıza

Girmiş lacivertliğin girdabına

Dünya boşalmış gibi

Kaktüslerin dikenleri irilmiş

Ayrılığın acısını taşırken

Yaydan çıkan zehirli ok

Gidiyor yerde sürünerek

Hedef belirsiz bozuk

Dertler gömülmüş gibi

Acıların sessizliği yırtmış kabını

Yağmur damlalarıyla biten mantar

Kıyıların bitmiş derin soluğu

Biçimden seçilmiş son karar

Kılıcın keskin yüzünde kan

Sessizlik kesilmiş gibi', 'Göçtü bir taze baht yine Karanlıklarda çürümüş yaprak Büyük bir örümcek ağı gözesiz Dayanmıyor uzaklar hıza Girmiş lacivertliğin girdabına D...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirilan-baht-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söğüt, Ben ve Mezar Taşım!', 'sogut-ben-ve-mezar-tasim-emel-hicyilmaz-7ker8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarda asılı olan resmi ben çizdim! 

   Ellerimle şekil verdim dünyama! 

   Orada yaşıyorum; 

   Arkası; 

   Yeşilin binbir tonu ağaçlarla süslü! 

   Önü ise; 

   Kocaman bir göle bakıyor! 

   Tahta merdivenlerle iniyorum göl kıyısına! 

   Biraz yosun kokusu değiyor burnuma! 

   Ahşap evimin balkonunda sallanır bir sandalye var, gün batımını orada izliyorum akşamları! 

   Adeta yaşadığımı, soluk aldığımı hissediyorum! 

   Gün doğarken ise hep kabuslar görüyorum şöminenin başındaki yatağımda! 

   Çığlık çığlığa uyandığımda; 

   Güneşin doğuşunu santimetrekarelerle kaçırıyorum! 

   Öğlene doğru sıcak basıyor! 

   Buram buram ter döküyorum! 

   Ormanda mini bir gezinti hoş olur diye düşünüyorum! 

   Kuşların cıvıltılarıyla patika yolları adım adım tavaf ediyorum! 

   Sincaplar koşturuyor etrafımda! 

   Tavşanlar kaçışıyor oradan oraya! 

   Patikam devam ediyor bu sırada! 

   Etraf binbir güzelliklerle ve rengarenk çiçeklerle dolu! 

   Yüreğim huzurlu ve mutlu! 

   Herşey istediğim gibi,

   Tek şey dışında! 

   Güneşin doğuşunu kabuslarım kovalıyor! 

   Bir türlü yakalayamıyorum! 

   Saatler kurup başucuma koyuyorum; 

   Nafile! 

   Ya geri kalıyor  ya da ileri gidiyor kadranım! 

   Yakalayacağım! 

   Güneşin doğuşunu birgün izleyeceğim! 

   Hava kararmaya başlıyor yavaş yavaş! 

   Huzurla ilerlerken bu kez de gün batımını kaçırıyorum! 

   Bir akşam da izlemeyivereyim, yarın akşam izlerim diye düşünüp, dalıyorum biraz daha derinlere! 

   Kuşlar ötmez oluyor,

   Sincaplar, tavşanlar, karıncalar bile yuvalarında sevdikleriyle sohbetleşiyor! 

   Gecenin hüznü ağaçları sarıyor önce! 

   Sonra da; 

   Baykuşların ışıltılı gözlerinden başka birşey göremez oluyorum! 

   Üşüyorum! 

   Gökyüzünde dolunay var

   Ve onu izlerken; 

   Hergün aşındırdığım patika sınırını aştığımı farketmeden yeni bir patika açıyorum önüme! 

   Soğuk yavaş yavaş tenimi dondurmaya başlıyor! 

   Direniyorum soğuğa ve ayaza! 

   Ulaşmalıyım güneşin doğuşuna! 

   Dağlar beyaz taçlarını takıyor! 

   Bağırsam duyacaklar gibi! 

   Uzansam dokunurmuşum gibi! 

   Parmak uçlarım ıslak şimdi! 

   Yapraklara değiyorum; 

   Hepsi nemli! 

   Bir gariplik var bu gece! 

   Daha önce gitmemiştim hiç bu kadar ileriye! 

   Ahşap evim uzaklarda kilometrelerce! 

   Korkuyorum! 

   Kabuslarım canlanıyor gözümün önünde! 

   Arkama bakıyorum, karanlık; 

   Önüme bakıyorum, sonsuzluk! 

   Duramam! 

   Geri dönüş imkansız! 

   Tek çarem donmamak için soğuktan; 

   Tüm kudretimle bir adım daha atmak! 

   Gün doğacak, korkular bitecek biliyorum! 

   Uyumazsam; 

   Kabus görmeyeceğime inanıyorum! 

   Kabusumu yaşıyorum! 

   Hatırlamaya başlıyorum; 

   Bu sabah çığlık çığlığa uyandığımda da buralarda bir yerlerde olduğumu görüyordum galiba! 

   Herşey tanıdık gelmeye başlıyor sonra da! 

   Çok garip! 

   Her adımda kabusuma yaklaşıyor gibiyim! 

   Çözmeye çalışıyorum bu işi! 

   Ama hala yarısı yok! 

   Güneşin doğuşunu neden hep kaçırdığım kısmında kocaman bir soru işareti var! 

   Sabırla,

   Azimle 

   Ve inatla ilerliyorum! 

   Az kaldı! 

   Ha gayret diyorum! 

   Bitti bitecek! 

   Dayanmalıyım! 

   Dur bir dakika! 

   O da ne? ! 

   Tan yerindeki kızıllık! 

   Aman Tanrım! 

   İşte! 

   İşte oldu! 

   Gün ağrıyor! 

   Güneşin doğuşunu göreceğim galiba! 

   Hafiften hareketlenmeler mi var ne? ! 

   Evet! 

   Anne kırlangıç yavrularını besliyor gibi! 

   Evet evet! 

   Tavşanlar da uyanıyor! 

   Ağaçlar da belirginleşti! 

   Karıncaları bile seçmeye başladım galiba! 

   Birazdan güneş doğacak! 

   Ve ben ilk kez  yakalayacağım! 

   Evet! 

   Oldu bu iş! 

   Zorlu bir yolculuktu! 

   Kabul! 

   Ama göreceğim güneşin doğuşunu! 

   Fakat,

   Bu da ne! 

   Bir patika belirdi şimdi! 

   ''Beni takip et! '' der gibi! 

    Dur bakalım,

    Burdan devam edelim! 

    Evet oldu işte güzel bir patikaymış! 

    Çok da belirgin! 

    Benden önce bir sürü fani yürümüş gibi! 

    Neyse! 

    Güneşin doğuşunu kaçırmayayım! 

    İlerde koca gövdeli birşey var! 

    Ne acaba? 

    Ağaç! 

    Biraz daha yaklaşırsam tamamdır! 

    Yanında da bir taş var! 

    Allah Allah? ! 

    Evet oldu işte! 

    Bu; 

    Bu ağaç; 

    Söğüt ağacı! 

    Benim en sevdiğim ağaç! 

    Yaprakları, dalları ne kadar da güzel! 

    Sabahın serin maviliğinde savruluyorlar ordan oraya! 

    Fakat! 

    Ahenkli melodileri bana bir cenaze marşını çağrıştırıyor! 

    Dalların arasından güneşin ilk ışıkları parıldıyor! 

    Evet! 

    Yaşasın! 

    Yakaladım işte! 

    Yakaladım seni! 

    Doğuyorsun 

    Ve ben izliyorum! 

    Müthiş bir duyguymuş bu! 

    Güneşin doğuşunu ilk kez izliyorum ben! 

    O mavilik,

    Sakinlik,

    Cıvıltılar,

    Renkler,

    Dalların musikisi! 

    Herşey bu kadar mı güzel olur Rabbim! 

    Doğdu işte! 

    Doğdu! 

    Çok şükür güneşin doğuşunu izleyebildim! 

    Artık kabus görmeyeceğim! 

    Şimdi ahşap evime, mütevazi yatağıma dönüp uyuyacağım! 

    Zorlu bir yolculuk oldu! 

    Dönmeden önce söğüt ağacının altındaki taşa bakacağım, merak ettim! 

    Üzerinde birşey yazıyor! 

    Mezar mı o? ! ! ! ! 

    Kim acaba? ! ! ! ! ! 

    Kabuslarım geldi hatırıma yine! 

    Ben o mezarda yatanı tanıyorum galiba! 

    Evet evet! 

    Çığlık çığlığa uyanışımın,

    Güneşin doğuşunu hep kaçırışımın nedeni bu mezardı! ! ! ! ? ? ? ? 

    Şimdi hatırladım! 

    Ama kimdi? ? ? ? 

    Kimdi bu? ? ? ? 

    Neden çığlık atıyordum? ? ? ? ! ! ! ! ! ! ! 

    Neden güneşin doğuşunu kaçırıyordum? ? ? ? ! ! ! ! ! ! ! 

    Şimdi adını okuyacağım! 

    Yoksa bu iş sonuçlanmaz! 

............................................

    Aman Tanrım! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

    ''Emel Hiçyılmaz! ''

          ? --?', 'Duvarda asılı olan resmi ben çizdim!     Ellerimle şekil verdim dünyama!     Orada yaşıyorum;     Arkası;     Yeşilin binbir tonu ağaçlarla ...', ARRAY['Türk Edebiyatı','Şiir','Emel Hiçyılmaz']::text[], 8.5, '{"poet":"Emel Hiçyılmaz","poet_slug":"emel-hicyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":172,"source_url":"https://www.antoloji.com/sogut-ben-ve-mezar-tasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskün Türkü', 'kuskun-turku-zekiye-comakli-7f72y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz limanda fener

Dalga kıranlar küskün

Sevgi kırıntıları 

Kuytu mekanlar küskün

Sevdalı gökyüzünün 

Lacivert yüzü küskün

Sesini renge veren

Ressam fırçası küskün

Denizin tirşesinde 

kaybolan ışık küskün

Küskün aşkın türküsü

Türkünün dili küskün', 'Sensiz limanda fener Dalga kıranlar küskün Sevgi kırıntıları  Kuytu mekanlar küskün Sevdalı gökyüzünün  Lacivert yüzü küskün Sesini renge ve...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Çomaklı']::text[], 8.5, '{"poet":"Zekiye Çomaklı","poet_slug":"zekiye-comakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kuskun-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlam Saklamış', 'mevlam-saklamis-seyfet-bozcali-o7c6e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevlam ömrümüzde ecel saklamış.

Koskoca gövdede bir kalp saklamış.

Dünyayı donatmış türlü nimetle,

Mümiin kalbinde şükür saklamış...

Örnek için karıncayı yaratmış,

Arının balında sırrı saklamış.

Çekirdekten dev ormanlar türetmiş,

Onların içinde çok can saklamış...

İnsanı Melekten üstün yaratmış,

Onların içinden Resül''ler çıkmış.

İnsana düşünen akılı vermiş,

Evliya beyninde zikri saklamış...

Peygamberler gönülleri fethetmiş,

Hep hakkı söylemiş,uyarmış durmuş,

Namazda,duada miraç var demiş.

Hafızın kalbinde Kur-an saklamış...

Çürütüp tohumu vermiş mahsülü,

Tüm canlılar onda bulmuş rızkını,

İman etmeyenler çeker kahrını,

Müminin gönlünde CENNET SAKLAMIŞ.

                      ''Her dinin bir ahlakı vardır.İslamın ahlakıda hayadır.''

                                                                           Hadis

12.11.1990', 'Mevlam ömrümüzde ecel saklamış. Koskoca gövdede bir kalp saklamış. Dünyayı donatmış türlü nimetle, Mümiin kalbinde şükür saklamış... Örnek i...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mevlam-saklamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktur Ege Gibisi', 'yoktur-ege-gibisi-ege-saydam-b7y10', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzüm tatlıdır tatlı,

Karpuz iri iri,

Ayva,incir bal gibi,

Kiraz yemeli.

Olmaz domatessiz kahvaltı,

Yanında da zeytin.

Bol bol nar yemeli,

Yoktur Ege gibisi.', 'Üzüm tatlıdır tatlı, Karpuz iri iri, Ayva,incir bal gibi, Kiraz yemeli. Olmaz domatessiz kahvaltı, Yanında da zeytin. Bol bol nar yemeli, Yo...', ARRAY['Türk Edebiyatı','Şiir','Ege Saydam']::text[], 8.5, '{"poet":"Ege Saydam","poet_slug":"ege-saydam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoktur-ege-gibisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanuni''ye Sunulan Donlar', 'kanuni-ye-sunulan-donlar-ekrem-sama-itdh7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akdeniz iç deniz sayılırdı o günler,

Neler yaşandı bu denizde hem kaç sefer...

Binbeşyüzaltmış''tı, bakın şimdi şu harbe; 

Bu sefer sahne bir ada ismi de Cerbe.

Birleşik haçlılar, kocaman bir donanma,

Sayı ikiyüzden az derlerse inanma.

Miktarca ölçüsü kaçmıştı endazenin,

İntikamı için, şu meşhur Preveze''nin

Osmanlı sayıca sadece yüz kadardı,

Donanmada ünlü denizciler de vardı.

Gazi Turgut Reis ve Paşamız Piyale,

Ne olaylar oldu, sığmaz akla hayale.

Düşman kendisinden emin küstah ve mağrur,

Osmanlıyı silmek için el oğuşturur.

Bir yığın prens markiz, asil ve asilzade,

Bir gemi dolusu, belki daha ziyade.

Takıp takıştırmış hepsi tüm ziynetini,

Görüp kutlayacak, Türk''ün hezimetini.

Olayı şiirle detaylı anlatamam,

Bir hücumla oldu, haçlının işi tamam.

Esir düşmek oldu, asillerin sonları,

Hünkara sunuldu haçlıların Donları (*) 

(İstanbul:03.01.2006) 

------

(*)    Meşhur esirlerin isimleri:

Don Alvaro de Sandi, Don Sanchez de Levia, Don Beranger de Requesens, Don Juan de Cardona, Don Giovanni de Cardona, Don Gaston vs.', 'Akdeniz iç deniz sayılırdı o günler, Neler yaşandı bu denizde hem kaç sefer... Binbeşyüzaltmış''tı, bakın şimdi şu harbe;  Bu sefer sahne bir...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kanuni-ye-sunulan-donlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur gitme....', 'dur-gitme-ercan-akbay-u5b69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dur gitme

    ardında ağlayan iki göz

    bir kırık kalp kalmasın.

    Dur gitme

    bir nakış gibi işlenen umutlarım

    kopmuş bir tesbih gibi dağılmasın.

    Dur gitme

    bu şehrin bütün sokakları daralıp

    ışıkları bir bir kararmasın.

    Dur gitme

    yine meyhanelerin kapıları

    sarhoş akşamlara açılmasın.

    Dur gitme

    gözlerime bak.......gör seni sevdiğimi

    sonra pişman olup,gönlün benim gibi yanmasın.....

                                              İst.1987', 'Dur gitme     ardında ağlayan iki göz     bir kırık kalp kalmasın.     Dur gitme     bir nakış gibi işlenen umutlarım     kopmuş bir tesbih ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dur-gitme-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryakin Oldum', 'tiryakin-oldum-zekiye-comakli-0dqbj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensin tadı kumsalda

İnan sütlü  kahvenin

Gelde çekme bir yudum 

Tiryakin oldum senin

Can katıyor sulara

Deniz telvesi tenin 

Sen taşırdın cezvemi

Tiryakin oldum senin

Yeke senin elinde

Gönül senin dümenin

Alamam gözlerimi

Tiryakin oldum senin

Yol açık fora fincan

Hep seyirde yelkenin

Yıllardır liman liman 

Tiyarkin oldum senin

Günün şavkına inat 

Işıl ışıl gözlerin 

Bir yerinde gecenin

Tirkayin oldum senin', 'Sensin tadı kumsalda İnan sütlü  kahvenin Gelde çekme bir yudum  Tiryakin oldum senin Can katıyor sulara Deniz telvesi tenin  Sen taşırdın c...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Çomaklı']::text[], 8.5, '{"poet":"Zekiye Çomaklı","poet_slug":"zekiye-comakli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tiryakin-oldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-seyfet-bozcali-txsug', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşa geçmiş ise bunca yıllarım,

Faydası olmayan varı neyleyim,

Ateş  olmuş ise geçen yollarım,

Yüce dağ başında karı neyleyim...

Faydası yok ise can toprağıma,

Boşa akıp giden seli neyleyim.

Şakıyıp durmazsa gönül bağımda,

Bülbülsüz rengarenk gülü neyleyim...

Dost odur ki kara günde dost olsun,

İnsan o ki sevgisiyle yol olsun,

Eş o dur ki dar günümde yar olsun,

Geniş günde düşman bile yar olur...

Sevgi o dur bu gönlüme taht kursun,

İbadetsiz geçen günü neyleyim.

İki metre kare bir mekan için,

Bunca saltanatı malı neyleyim...

Seyfet der dünyalık,dünyanın malı,

İyi bilinmeli karı zararı,

En güzel karımız Hakkın kararı

O karardan özgesini neyleyim...

        ''Şan,şerf ve üstünlük mal ile değil; 

          İlim ve ırfan ile ölçülür.''

                             Hadis-i  şerif

12.5.1993', 'Boşa geçmiş ise bunca yıllarım, Faydası olmayan varı neyleyim, Ateş  olmuş ise geçen yollarım, Yüce dağ başında karı neyleyim... Faydası yok...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neyleyim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-umit-paksoy-5hggm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonra

karla karışık yağmurlar çizdim

balkon duvarlarına

sonra bir uçak gördüm

insanların yalnızlığını

yıldızların yalnızlığını düşündüm

ve yelkovan akrebe

bir kaç kere değdi geçti

	

-anlayacağınız hocam

ödev mödev yapamadım-

Aslında akrep ve yelkovan

iki ayrı zamanın

aşıkları

üzülüyorum onlar için

görmüyor musunuz?', 'Sonra karla karışık yağmurlar çizdim balkon duvarlarına sonra bir uçak gördüm insanların yalnızlığını yıldızların yalnızlığını düşündüm ve y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonra-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Erirken', 'karlar-erirken-zekiye-comakli-d65mt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağı çevreleyen nur ağı gibi

Seherde ışıyan kırağı gibi

Büyüyen bir alev yumağı gibi

Gönlümü sarmıştın karlar erirken

Kah acı kah atlı demelerden geçtik

Sevda gömleğini beraber biçtik

Gömleğe sarılıp şarabı içtik

Gönlümü sarmıştın karlar erirken

Yıllarca gönlümü mekan eyledin

Bir deli poyraza nasıl meylettin

Açtığın yarayı srmadan gittin

 Gönlümü sarmıştın karlar erirken', 'Ağı çevreleyen nur ağı gibi Seherde ışıyan kırağı gibi Büyüyen bir alev yumağı gibi Gönlümü sarmıştın karlar erirken Kah acı kah atlı demele...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Çomaklı']::text[], 8.5, '{"poet":"Zekiye Çomaklı","poet_slug":"zekiye-comakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karlar-erirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukların yüzlerinde gördüğüm', 'cocuklarin-yuzlerinde-gordugum-umit-paksoy-5x652', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir bu

çocukların yüzlerinde gördüğüm

çocukluğum mu yoksa 

üstüme yıkılıp kalan

kimin çocukları bunlar 

tenha parklarda gördüğüm

niye bakarım 

usanmadan

Öyleyse ben çocukken

yeryüzündeki tüm şiirlerden

ve çocukları seyretme işinden 

kim sorumluydu

öyleyse

kimden sormalıyım çocukluğumu

hangi şairden

Kimin çocukları bunlar

pencereme gökkuşağını kim koydu.', 'Nedir bu çocukların yüzlerinde gördüğüm çocukluğum mu yoksa  üstüme yıkılıp kalan kimin çocukları bunlar  tenha parklarda gördüğüm niye baka...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklarin-yuzlerinde-gordugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül, gülüm ağlama', 'gul-gulum-aglama-mikdat-bal-rbyc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O güzel gözlere yaşlar yakışmaz

Gül, gülüm ağlama gel bülbülüm gel

Seven gözler öyle yaşlı bakışmaz

Bil, gülüm ağlama gel bülbülüm gel

Çiçeğim, bir tanem beyaz gülüm gel

Bıraksın kederler, dertli başını

Sırma saçlarını hilal kaşını

Gülmek sana layık, gözün yaşını

Sil,gülüm ağlama, gel bülbülüm gel

Çiçeğim, bir tanem beyaz gülüm gel

Şu yeşil ağaçlar, şu uçan kuşlar

Şahidimiz olsun, şu dağlar taşlar

Gözlerindan akan o kanlı yaşlar

Sel, gülüm ağlama gel bülbülüm gel

Çiçeğim, bir tanem beyaz gülüm gel', 'O güzel gözlere yaşlar yakışmaz Gül, gülüm ağlama gel bülbülüm gel Seven gözler öyle yaşlı bakışmaz Bil, gülüm ağlama gel bülbülüm gel Çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gul-gulum-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Sokağındayım Yine...', 'dusler-sokagindayim-yine-sibel-uygun-mwoii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşler sokağında gezindim yine dün gece. 

Yokluğunun akşamlarında sığındığım karanlıklardan herhangi birisiydi. 

Gözyaşlarım yıldız yıldız caddelere süzülürken,

Kimseler farkına bile varamadı ağladığımın...

Evet...

Aşk mavi sevdalarda yüklüdür. 

Mavidir sevdanın rengi...

Yaşanmış, yaşanan, yaşanmadan son bulan...

Tüm kırık dökük mavi sevdalar...

Gururlara yenik düşmüş kayıp aşklar...

Anılar eşliğinde yüreklerden sökülüp,

Sessizce gökyüzünün boşluğuna,

Dalgaların derinliklerine bırakılıverilen sevdalar...

İşte bundandır hep denizin ve gökyüzünün o mavi berrak rengi...

Çünkü sadece mavidir sevdanın rengi', 'Düşler sokağında gezindim yine dün gece.  Yokluğunun akşamlarında sığındığım karanlıklardan herhangi birisiydi.  Gözyaşlarım yıldız yıldız c...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dusler-sokagindayim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orman Yakar Gibi', 'orman-yakar-gibi-sefik-koman-xjz88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belleğimde anılar var gömülü

Anılarda ordular var gönüllü

Sorular var, sorunun en müşkülü

O ordular, neden dağıtıldılar? 

Yürekleri çiçek açmış çocuklar,

Üveyikler gibi köye uçtular.

Köylere hem ışık hem güç oldular.

O ordular, nasıl dağıtıldılar? 

Kurmayları vardı bulunamayan

Siteler kurdular, kurulamayan

Hedefler koydular, varılamayan

Kuranlar, kurduranlar, neden sustular? 

Enstitüler olsaydı böyle olmazdı

Bu yurt, kurda, kuşa muhtaç kalmazdı

Dağlarda laleler, güller solmazdı

Neden aşımıza zehir kattılar? 

Tonguç Baba, Yücel Amca, diye bağırdık

Aydın olanları köye çağırdık

İmam hatiplerden daha ağırdık

Enstitüler kazan kaldırmadılar…

Bu günün suçlusu bizler değiliz.

Bizler Mustafa Kemal askerleriyiz.

İmam hatiplere kaldı yerimiz,

Orman yakar gibi bizi yaktılar…

                         Şefik Koman', 'Belleğimde anılar var gömülü Anılarda ordular var gönüllü Sorular var, sorunun en müşkülü O ordular, neden dağıtıldılar?  Yürekleri çiçek aç...', ARRAY['Türk Edebiyatı','Şiir','Şefik Koman']::text[], 8.5, '{"poet":"Şefik Koman","poet_slug":"sefik-koman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/orman-yakar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yer takviminde bir gün', 'yer-takviminde-bir-gun-umit-paksoy-jdznt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yer takviminde bir gün

telefonlar meşgul

     -başladığım yere

      geri dönüyorum öyleyse-

yer takviminde bir gün

ışıklar kırmızı

Bu takvimde bir gün, sıcak

bütün kalelerim zapt ediliyor 

bütün otobüslerim kaçmış', 'Yer takviminde bir gün telefonlar meşgul      -başladığım yere       geri dönüyorum öyleyse- yer takviminde bir gün ışıklar kırmızı Bu takvi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yer-takviminde-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devre 69', 'devre-69-yusuf-ziyaeddin-sivaslioglu-dukb5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gencecik çocuklardık

Çıkmamıştı bıyıklarımız

Eylül altmışdört''te

Devre arkadaşlığına başladık

Çengelköy Kuleli''de

Harbiyeli olmak hedefimiz

Hayallerimizi süslerdi

Sarı Kordon ve Meçimiz

Üç yıllık bir çalışma

Eğitimle karışık öğretim

Hatırası kaldı bizlerde

İstanbul''daki günlerin

İzmir''de indik tirenden

Gar titredi sesimizden

Silah arkadaşı olmak için

Silahlara sarıldık yürekten

İzmir dönüşü Ankara

Öğretim sığdırılmış iki yıla

Hafta sonlarının keyfi

Saklıdır Kızılay turlarında

Gırgır, şamata, şakalar

Oluştu bitmeyen hatıralar

Altmışdokuz Ağustosunda

Hazırlanmıştı Diplomalar

Kimimiz Piyade, kimimiz Tankçı

Topçu, İstihkam, Muhabere derken

Devre dediğimiz kervan

Oluştu Altıyüz on Gençten

Yıl ikibin, Devre

Tamamlamış otuzbir yılı

Çıkarırken üniformaları

Tüketmişiz nice yılları

Şimdi Emekli Subaylarız

Geçen yılları özlemle anarız

Devre gecelerinde güler

Cenazelerde ağlarız.

(İstanbul, 3 Ocak 2006)', 'Gencecik çocuklardık Çıkmamıştı bıyıklarımız Eylül altmışdört''te Devre arkadaşlığına başladık Çengelköy Kuleli''de Harbiyeli olmak hedefimiz ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/devre-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi boşluktasın', 'simdi-bosluktasin-umit-paksoy-agasl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Bir

2

Şimdi boşluktasın

sırt üstü uzanınca

iki gökyüzü

kayar gider altından farklı yönlerde

Eski dilde uçmak, iki zamanlı ritim

ya da iki zamanlı bir rivayet

3

Dün gece

bir elektrik direğini geçtikten sonra

üçe kadar saydım', '1 Bir 2 Şimdi boşluktasın sırt üstü uzanınca iki gökyüzü kayar gider altından farklı yönlerde Eski dilde uçmak, iki zamanlı ritim ya da iki ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-bosluktasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi sesime düşman olmadan', 'kendi-sesime-dusman-olmadan-umit-paksoy-o7znb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendi sesime düşman olmadan

işlemeli annem bu şehri beyaz bir gömleğime

benim etimden kesilmeden bu şehrin bir parçası 

ben bu şehre dair notlar almalıyım bir kenara

Trafik lambalarına sarılarak ağlamak istiyorum

çoğu zaman.', 'Kendi sesime düşman olmadan işlemeli annem bu şehri beyaz bir gömleğime benim etimden kesilmeden bu şehrin bir parçası  ben bu şehre dair no...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kendi-sesime-dusman-olmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba 11', 'merhaba-11-tulay-i-cen-oq9w7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can merhaba.

Merhaba güzel insan seni inan çok özledim. Seninle  konuşmayı  tartışmayı  inan  çok özledim, ne yazık bana ses vermiyorsun, artık sen yoksun. Sen yoksun diyorum inanıyorumki beden olarak  yoksun ama ruhun benimle beraber. Ne olurdu yanımda olsaydın, bana yol gösterseydin inanki sana cok ihtiyacım var.Kafam okadar karışıkki bir türlü toplıyamıyorum.

Can yaşadıklarımı yaşamak zorundamıyım, zamanın akışını  değiştirebilirmiyim, hayır  eminimki bunu yapamam.

Can  herzaman dediğim gibi hayat cok zor olduğu kadarda çekilmez, bu hayatı sana kavuşana kadar çekmek zorundayım.

Bazı şeyleri artık kabullenmeye başladım.Ne diyeceksin birincisi artık senin dönmeyeceğini hayatın  seninle yaşadığım gibi olmayacağını  kabullendim.Artık sen yoksun  sekiz senedir gelirsindiye bekledim ama boşunaymış demekki beklentiler boşmuş.

Seni  sevmek seni istemek artık bana yetmiyor ama ben yinede  seni sevmeye devam ediceğim.

İnan bana seni hep sevdim sevmiye devam ediceğim..

Seni seviyorum kafam karışık olsa bile ben seni  hep sevmiye devam ediceğim ne olur anla beni.

Seni seven,sensizliğe mahkum, seni beklemeye devam eden ben.

SENİ SEVİYORUM.

Denizin ortasındayım,

bir sağa bir sola sallanıyorum,

Limanı  bulmak için.

Karanlıkta yanaşmaya çalıştım

rıhtıma...,

Sığınılacak limandın sen benim gönlümde.

Dalgalar savurdu 

beni senin,

güçlü kollarına.

Beni tek sen,

koruyabilrsin.

Al beni kollarına,..

Alabora olmuş gemi gibiyim.

21/03/2000', 'Can merhaba. Merhaba güzel insan seni inan çok özledim. Seninle  konuşmayı  tartışmayı  inan  çok özledim, ne yazık bana ses vermiyorsun, ar...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/merhaba-11-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıktır', 'yaziktir-seyfet-bozcali-10w2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelin boşa geçirmeyin ömürü,

Zamana yazıktır cana yazıktır.

Kutsal Vatan için birlik olalım,

Devlet''e yazıktır mala yazıktır.

Üç beş kanı bozuk hayel peşinde,

Ülkesini parçalama düşünde.

Kandırılmış henüz çok genç yaşında,

Oğula yazıktır,kıza yazıktır...

Toprak için Vatan için can veren,

Bayrak için,bayraklara kan veren.

Şehit düşüp topraklara can veren,

Şehide yazıktır kana yazıktır...

Düşüncede ön yargılı olmayın,

Komşu devletleri dosttur sanmayın,

Bizler içten sizler dıştan vurmayın,

Vatana yazıktır yurda yazıktır...

İndirmeyin bayrağımı semadan,

Ezanlar okunsun minarelerden,

Medet ummayalım Avrupalıdan,

İmana yazıktır dine yazıktır...

Zalimlerin oyununa gelmeyin,

Senlik benlik kavgasına dalmayın,

İnsanları bir çok kampa bölmeyin,

Gençliğe yazıktır,cana yazıktır...

Seyfet der rabbinin ipine sarıl,

Onunla meşgul ol,ihlasla yorul,

Aziz vatan için tek bir yumruk ol,

Atana yazıktır yurda yazıktır...

                           ''Küçüklerimize acımayan ve büyüklerimizesaygılı

                             olmayan bizden deyildir.''

                                                                Hadis

1512.1989', 'Gelin boşa geçirmeyin ömürü, Zamana yazıktır cana yazıktır. Kutsal Vatan için birlik olalım, Devlet''e yazıktır mala yazıktır. Üç beş kanı bo...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yaziktir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BeN BiR ÇaM AğACıYıM', 'ben-bir-cam-agaciyim-mine-ozdemirtas-k6pb2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir çam ağacıyım yolun tam ortasında

ölümsüzüm  /  beni vursunlar

mazeretim yok.

yanımdan o kadar hızlı aktı ki sular 

üstüne tünediğim kayalar bile aşındılar.

yuvarlanan taş 

yosun tutmaz 

diyenler

dediklerini

diye dursunlar

takamadıksa

kulağımıza

rüzgarları

küpe diye

ve eskiyemediyse 

köklerimizde

yıllar

kime ne? / bunun ormana, ne zararı var? 

ne çıkar

bir artı sel daha

yüklenecekse yarınlar? 

ne çıkar

susuz kalacaksa

özsuyu taşıyan damar

ne çıkar 

şu kalın gövdeye

kazınacaksa

ayrılıklar.

eğer bir gün tükenirse sevdalılar

ogün

en fazla

keserler başımızı

parça parça doğrarlar

böylece

çoğalır  sayımız

yayılırız

bir şaire

kalem olur sol yanımız

kağıt olsak

ne çıkar

ama / hele bir dur

unutma,

kış gelip bastırsa da kar

çığ düşüp kapansa da yollar

bende hep yeşil kalır

sararmaz dallar

ben bir çam ağacıyım yolunun tam ortasında

yaslanmayacaksan bana / beni vursunlar.

03/01/2006', 'Ben bir çam ağacıyım yolun tam ortasında ölümsüzüm  /  beni vursunlar mazeretim yok. yanımdan o kadar hızlı aktı ki sular  üstüne tünediğim ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ben-bir-cam-agaciyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 34 (değilsem de)', 'lirik-34-degilsem-de-fevzi-cebe-uol49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doğru tarif etmek gerek

varsa eğer kuralları da

niçin yaşadım, birisi için mi

kimin 

akışlarım ve damlayışlarım oldu

uçuşlarım ve kayboluşlarım

bir balık veya  kartal değilsem de

12.12.2004 – 20:45', 'doğru tarif etmek gerek varsa eğer kuralları da niçin yaşadım, birisi için mi kimin  akışlarım ve damlayışlarım oldu uçuşlarım ve kayboluşla...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lirik-34-degilsem-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-nuray-acar-dgnv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Serseriyim düpedüz o bildiğiniz tanımda

Üstüm başım olmasa da düşüncelerim aynen öyle

Duraksamayın dedim ya serserice yaşıyorum

Gece olmuş gün tüketmiş kendimi 

Umurumda mı olur ki 

Evde aş bitmiş yok yok aşk ta gitmiş

Dedim ya serseriyim düpedüz o bildiğiniz tanımda

Böylesi bir ruhtan sakın ola beklentiye büyük hedeflere

Uzak düşüncelere kapılmayın sel gibi süpürürüm sizi

Ne sizden geriye sağlam bir parça ne de benden size 

Yekpare bir düşünce dizisi kalmamıştır.

Serseri bir ruh bu istediği noktada durup istediğinde soluksuz ilerler

Onun doğrularına çoğu zaman siz insanoğlunun aklı ermez

Siyahların altında gün ışığında güneş ile iddialaşır

Ter içinde kalan bedenine inat buz keser 

Denizde susuzluktan ölüm orucuna girdiği de ne çoktur

Dedim ya serseridir bu ruh sizin değil kendi rüzgarında 

Savrulur durur yönü de olmaz ya dikine ya dibine alır gider 

Bir başına saatsiz zamanlarda dumansız ateşlerde ve 

Serseri bir gezegende yörüngesizdir.

Tanımını da koyamazsın ki izin olmaz buna

Bakarsın sol yanında bitivermiş daha cümlenin ortasına gelmeden

Buharlaşmış ne sağına geçmiştir ne eski yönündedir

Dedim ya serseridir bu ruh kim bilir nerde kiminledir

Uzun vadeli borç gibi değil spekülatörlerin favorisi olmalıdır

Hızır’dır o, dar zamanda kötü anlarda ve acının tam ortasında

Bitiverir ve serseridir teşekkürlerinizi de kabul etmez

Hediye falan da boş onu ikna edecek

Kendinden daha katmerli bir ruhun serseri serzenişidir.', 'Serseriyim düpedüz o bildiğiniz tanımda Üstüm başım olmasa da düşüncelerim aynen öyle Duraksamayın dedim ya serserice yaşıyorum Gece olmuş g...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/serseri-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki ters bir yüz yaşamak', 'i-ki-ters-bir-yuz-yasamak-umit-paksoy-rv5we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki ters bir yüz yaşamak

Sen bu odaya girip her

çıt deyişinde

duvar saatim

çıt deyince parçalanan duvar saatleri gibi

parçalanıyor, aklım almıyor

Sonra

soru işareti şeklinde bir aspirin

usulca kanıma karışıyor

	

ama bunu anlayabiliyorum', 'İki ters bir yüz yaşamak Sen bu odaya girip her çıt deyişinde duvar saatim çıt deyince parçalanan duvar saatleri gibi parçalanıyor, aklım al...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iki-ters-bir-yuz-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye....', 'sevgiliye-taner-nisanci-h0vg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVGİLİYE ……….

Esen rüzgarla dağılsın saçların,

Tebessüm eksik olmasın yüzünden.

Ela göz üstünde kalem kaşların,

Çatılmasın.Bal damlasın sözünden

Leblerin ateşi yaksın sinemi,

Çevirme ela gözünü gözümden.

Kuşatıp sar daim gönül hanemi,

Ayrılmasın.Aşk damlasın özünden

Mecnun eyleyip sal ıssız çöllere,

Leyla belledim gelirim izinden.

Hal bilmez elinde düşüp dillere,

Açılmasın.Kor damlasın közünden

Can evime gelip çökse ecelim,

Son nefesi vermek isterim dizinde.

Sureti hayalin ile mecalim,

Saçılmasın.Nur damlasın cüzünden. 

                                          03/01/2006', 'SEVGİLİYE ………. Esen rüzgarla dağılsın saçların, Tebessüm eksik olmasın yüzünden. Ela göz üstünde kalem kaşların, Çatılmasın.Bal damlasın söz...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgiliye-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkakca özlediğim birini', 'korkakca-ozledigim-birini-umit-paksoy-edh8k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkakça özlediğim birini

birden bire

uzak bir şehirde

-anlamsız bir yerde, bilmem niye-

gördüğümde

konuşacak tek kelime bulamadım

Belki bunu

terkedilmiş çocuklar bilir

bir çizgi roman karesinde

terkedilmiş çocuklar', 'Korkakça özlediğim birini birden bire uzak bir şehirde -anlamsız bir yerde, bilmem niye- gördüğümde konuşacak tek kelime bulamadım Belki bun...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korkakca-ozledigim-birini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanlı Bayrağım', 'sanli-bayragim-seyfet-bozcali-9c793', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SensinTürkiye''min şerefi şanı,

Ey şanlı bayrağım can sana kurban.

Bu yüce vatanın güzel nişanı,

Damarımda akan,kan sana kurban...

Allah bu milleti sensiz etmesin,

Sensiz olan hiç bir ocak tütmesin,

Gönlümüzden sevgin eksik olmasın,

Tüm varım servetim, ben sana kurban...

Tarihin,geçmişin destanla dolu,

Hor bakan melunun kırılsın kolu.

Gölgene dar gelir bu anadolu,

Çoşup akan,nehir göl sana kurban...

Edirne''den Van''a Kars''tan İzmir''e,

Sevdanla kısalır yol birden bire.

Boğazlardan geçip tüm haşmetinle,

Dünyaya yaydığın şan sana kurban...

Şehidim kalbimde,renginde kanım,

Yoluna fedadır,canım cananım,

Ölürsem örtsünler,senle her yanım,

Seyfet der benliğim,ben sana kurban...', 'SensinTürkiye''min şerefi şanı, Ey şanlı bayrağım can sana kurban. Bu yüce vatanın güzel nişanı, Damarımda akan,kan sana kurban... Allah bu m...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanli-bayragim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-mevlut-bicik-980r7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hidâyet’den nasîbi olanlar seni bulur

Elbette sever seni,devamlı seninle olur

Sana muârız olanların kalbi,gönlü solur

Seni bulmak,seni bilmek lütuf’dur efendim.

Seni sevmek,seninle olmak şeref’dir efendim.

Senin sevginle muhakkak hizmetlere koşulur

Gelirse kalblere feyiz elbette canla coşulur

Bî-samîmi ve sâdık olanlar haliyle boşolur

Senin sevgine lâyık olmak nimet’dir efendim.

Samîmi ve sâdık olmak  devlet’dir efendim.

Senki! Mürebbisisin  bî-çâre  gönüllerin

Tercümânısın duâ’larda bî-kelâm dillerin

Kokususun bedenlerde kesîrullevn güllerin

Feyzınla,nurunla güller yeşersin  efendim.

Himmetinle bî-hayât gönüllere deşarzsın efendim.

Muhtâcız her zaman sana,senin himmetine

Vesîle-i necâtsın sen şu Dünyanın milletine

Elbette şefâatin hak’dır Muhammedin ümmetine

Nemrudî ateş içerisinden kap bizleri efendim.

Gönül bahçenin hizmetcisi yap bizleri efendim.

Mevlüt Bicik

03.01.2006   saat 20.20

Esslingen', 'Hidâyet’den nasîbi olanlar seni bulur Elbette sever seni,devamlı seninle olur Sana muârız olanların kalbi,gönlü solur Seni bulmak,seni bilme...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/efendim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç saat önce', 'uc-saat-once-umit-paksoy-utkqv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Televizyon seyreden çocukların yüzlerindeki bilgelik bulaşmıştır zengin aile kızlarının mentollü sigara tadındaki dudaklarına. O dudaklar ki televizyon programı gibi umut vadederken, yaşama isteğini incitir kelebeklerin. Biliyorum dayanılır gibi değil. Biliyorum filmlerdeki iyi adamlara güvenilmez ve çiçek açmaz mentollü sigaralar. Fakat bütün bunlar bir intihar mektubuna atılacak imzaya haklılık verir mi? Ölümümün gerçekliğinin bir anlamı olmadığı gibi...

Kim deliyse ölümsüzdür!', 'Televizyon seyreden çocukların yüzlerindeki bilgelik bulaşmıştır zengin aile kızlarının mentollü sigara tadındaki dudaklarına. O dudaklar ki...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/uc-saat-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maske...', 'maske-ali-orhan-gunaydin-fe6wg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar sahte gülücüklerle bezenmiş, maskelerini takmışlar...

Komşum aç-susuzmuş,

Dayım hasta yatıyormuş,

Annemse için için ağlıyormuş,

Bana ne! 

Benim insanlığımı almışlar...', 'İnsanlar sahte gülücüklerle bezenmiş, maskelerini takmışlar... Komşum aç-susuzmuş, Dayım hasta yatıyormuş, Annemse için için ağlıyormuş, Ban...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/maske-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler ve aşk ateşi', 'golgeler-ve-ask-atesi-umit-paksoy-yn3xs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gri gökyüzünün, o bulutsuz dünyanın askeri

kulübenden çık

Arka bahçesinde ceset olmayan birisin sen

irtifa kaybında atılacak ilk cisim

bir insan

belki de hatırlanacak biri

Bu yüzden kirleniyorsun

bu yüzden yalınayak koşan bir çocuk sevindiriyor seni

gölgelerin olmadığı yerleri seviyorsun.

Bulutsuz dünyanın askeri

söyle

bir adamın ve bir kadının

bir lokanta camından yansıdığını görünce

adım atmanın

ya da bisiklete binmenin

olabilir bir yanı kalır mı? 

Gölgesiz bir yaşamak mümkün mü sence? ..', 'Gri gökyüzünün, o bulutsuz dünyanın askeri kulübenden çık Arka bahçesinde ceset olmayan birisin sen irtifa kaybında atılacak ilk cisim bir i...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/golgeler-ve-ask-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4 Ocak 1998, Pazar', '4-ocak-1998-pazar-umit-paksoy-04kh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ormanda birbiri ardına dizilmiş, birbirinin resmini çizen yedi cüce ressamdan biriyle uzaktan akraba oluşumuzun en kısa hikayesi, onun bir yel değirmeninin 12. katında dünyaya gelmesi, gözlerini açar açmaz karşısında şimdilerde ortak dostumuz olan emekli mareşali görmesi ve mareşalin onun kulağına ezan okuyup, ismini söylemesinden sonra benim cüce dostumu, dünyaya getiren ana rahminin biraz üzgün de olsa tıpkı geldiği gibi gökyüzünde birkaç daire çizdikten sonra, solgun mavilikler içinde kaybolması ile başlar. Günlerden pazardır. 4 Ocak 1998, Pazar...', 'Ormanda birbiri ardına dizilmiş, birbirinin resmini çizen yedi cüce ressamdan biriyle uzaktan akraba oluşumuzun en kısa hikayesi, onun bir y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/4-ocak-1998-pazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden istenileni biliyorum.', 'benden-istenileni-biliyorum-umit-paksoy-w86cv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrin karanlık bir haritasından

başka bir karanlık yaratıyorum kendime

balkonu güneş gören bir apartman dairesi geliyor aklıma

boşluk, sürekli bir ışık ve yalnız bir bekleyiş

kulaklarımı, kalp kapakçıklarımı zorluyor beklemek

bekledikçe anlıyorum

Gizli ve yağmurlu bir gün

ellerimden ve çizilmiş bir gökkuşağı düşer üstüne

ben bazı şiirleri hatırlayamadığım için şiir yazarım

Kaybettiklerine hiç üzülmeyen bir adam

bundan günler sonra

cüzdanında taşıdığı o fotoğrafa en sonunda bakmış

günlük güleçlik bir sonbahar

gökkuşağını ve kendini aynı karede

böyle donuk görünce

ne anladığını

düşünmüş bütün bir kış boyu

Her şey dört mevsim artık

günlerin kaydı olmaz.', 'Şehrin karanlık bir haritasından başka bir karanlık yaratıyorum kendime balkonu güneş gören bir apartman dairesi geliyor aklıma boşluk, süre...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benden-istenileni-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Devam', 'yasamaya-devam-ali-orhan-gunaydin-ap8n1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşe kalka yaşıyoruz şu dünyada emanet,

Tükenmesin ümidin,dayan ya sabır; sabret.

Geçecektir kötü günler,bitecek bir gün elbet,

Yeter ki sen; 

Doğru yaşamaya devam  et...

02/01/2005', 'Düşe kalka yaşıyoruz şu dünyada emanet, Tükenmesin ümidin,dayan ya sabır; sabret. Geçecektir kötü günler,bitecek bir gün elbet, Yeter ki sen...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamaya-devam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratıklar aşkına', 'yaratiklar-askina-umit-paksoy-s6k12', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaratıklar aşkına

resim, büyü ve kışın eldiven takmayan herkes

Ben ve kötü ben

kediyle oynarken onu ve

onun aslında başka olduğunu

düşünmek istemeyiz.

Resim dersleri bize böyle öğretir

yanan sobanın yanında yatan şey

ve ben küçükken hatırlamam bir kedimiz daha varmış

mutluyken kaçan tek şey odur hayatımdan

Hatırlamam

ben ve kedinin fotoğrafı var sadece

o da öyle bir yere düşmüş ki

çıkmaz

O gün bakılmıştır ve

resim defterlerinden fallara

hindi çıktıysa gülünmüş

kızak ve yeni bir eldiven için

Bu sokakta yaşamak, bu çıtırtı, seni sevmek

bu sokakta yaşlanır ama ölmez kimse

resim defterlerinden

soba, kestane, uzun koşular

ve eşyalara sarılan çocuklar çıkar

sen çıkmazsın

Sayfaları ister istemez yırtan ben

başka şeyler düşünmeye çalışırım...', 'Yaratıklar aşkına resim, büyü ve kışın eldiven takmayan herkes Ben ve kötü ben kediyle oynarken onu ve onun aslında başka olduğunu düşünmek ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yaratiklar-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın?', 'yarin-ali-orhan-gunaydin-recgf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünden önce yoktum.

Dün doğdum.

Bugün varım.

Yarın? 

 05/02/1996', 'Dünden önce yoktum. Dün doğdum. Bugün varım. Yarın?   05/02/1996...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yarin-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolla Bana Sevgini', 'yolla-bana-sevgini-i-rfan-kayagil-eedx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolla bana sevgini

Bulur elbet dengini

Saçlarının rengini

Özlüyorum Sevgilim

Sulardaki şırıltı

Gözlerinde pırıltı

Kulağımda fısıltı

Özlüyorum sevgilim

Yolla bana resmini

Unutamam ismini

Ben başka birisini

Sevemem ki sevgilim

Teninin Kokusunu

Öptüğüm dokusunu

Gözlerinin rengini

Özlüyorum Sevgilim', 'Yolla bana sevgini Bulur elbet dengini Saçlarının rengini Özlüyorum Sevgilim Sulardaki şırıltı Gözlerinde pırıltı Kulağımda fısıltı Özlüyoru...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolla-bana-sevgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-ali-orhan-gunaydin-tfrvs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mecnun Leyla''ya,

Ferhat Şirin''e,

Kerem Aslı''ya,

Bense sana bağlanmışım.

Leyla Mecnun''u,

Şirin Ferhat''ı,

Aslı ise Kerem''i anlamış,

Sen beni Anlamadın...

12/04/1993', 'Mecnun Leyla''ya, Ferhat Şirin''e, Kerem Aslı''ya, Bense sana bağlanmışım. Leyla Mecnun''u, Şirin Ferhat''ı, Aslı ise Kerem''i anlamış, Sen beni A...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlamadin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca ve göllerin oluşumu', 'karinca-ve-gollerin-olusumu-umit-paksoy-5iajd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçi ve döndüğü yönü düşünür

gece uykusu kaçmışsa

İlk uçakla gidenin bir kırmızı bir de siyah gömleği vardı

eski kayıtlar

barda oturan o eski adam

bir yerlerde tozlanan bir şeyler

aynıdır

birine inanmak yeter

Hikayeleri yoktur aslında', 'İçi ve döndüğü yönü düşünür gece uykusu kaçmışsa İlk uçakla gidenin bir kırmızı bir de siyah gömleği vardı eski kayıtlar barda oturan o eski...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karinca-ve-gollerin-olusumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülmek için', 'uzulmek-icin-umit-paksoy-r5k2r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

kafein, parasetamol, suskun hayaller

kıyıda bekleyen yalnızlık

geçen zamanın hüznü

2

Kar kokusu ve belki

siyah beyaz hatırlanacak bir gece yarısı

boğulmak nedir bilmek için dokundum

kadın derisinden bir kadına

3

Meğer karafatmalar girsin imiş rüyalarıma

öyleyse bozulmuş eşyalara öfkelenir gibi seviyormuşuz seversek

yani ruhum soyunmak için bekliyormuş bir alacakaranlığa

4

Üzülmek için', '1 kafein, parasetamol, suskun hayaller kıyıda bekleyen yalnızlık geçen zamanın hüznü 2 Kar kokusu ve belki siyah beyaz hatırlanacak bir gece...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzulmek-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı yokuş', 'ayni-yokus-umit-paksoy-l4yel', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lastik ayakkabı

naylon gömlek

nuşanbadan pantolon

sonra aynı  merdiven

aynı yokuş

aynı caddelere saçılmış insanların arasından

Bir kalp atışına ayarlıymış yüzüm

plastik kovaların arasında en plastik benmişim

işim gücüm buymuş benim

her sabah süper kahramanların gizli dünyalarından uyanan

kraliyet ailesinden bir deliymişim mesela

çocukluğumdan kalma bir yüz gibi

her hatırladığımda yeniden yaratıyormuşum kendimi

Bu yüzden kaybetmişim

bir kaybeden yaratmışım kendimden.

Yürüyorum...

Neden anlaşılır gibi değil

şarkıların anlamı.', 'Lastik ayakkabı naylon gömlek nuşanbadan pantolon sonra aynı  merdiven aynı yokuş aynı caddelere saçılmış insanların arasından Bir kalp atış...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayni-yokus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 3', 'mektup-3-salim-calik-63asg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MEKTUP  3

     özlemin kötü huylu bir ur gibi oturdu yüreğime.  şimdi ellerinin değdiği yerleri seviyorum. saatleri sayıyorum geleceğini bilmenin ve beklemenin telaşıyla.  saatin akrebi beklemekle geçen zamanları zehirliyor senin geleceğin ana kadar.  şimdi severek baktığın, konuştuğun, sularını bardakla sunduğun çiçeklere bakıyorum heyecanla.  hepsinde senden bir iz bulacağımı umarak dolaşıyorum tek tek.  selamlıyorum senin gibi. ve senin gibi suluyorum mutlu olacağını bilerek...

     şimdi geriye sarıp anılarımı seninle karşılaşmamızı, bahçelerde gizli gizli buluşmalarımızı canlandırıyorum. çocuktuk...çocuk yalınlığımızla çıktığımız yolda büyüttük birbirimizi ve kızımızı. kızımız da bizi.  ve öğrendiklerimize kendimizden kattıklarımızla öğretmeye başladık sevdayı...yaşamı.

     çok özlemler yaşadık.  ve zerresi yıllara bedel birliktelikler. 

özlemin kötü huylu bir ur gibi oturdu yüreğime.  şimdi gözlerini düşünerek bakıyorum yollara. senin beni beklediğin gibi bekliyorum seni.  “gözleri yatırıp uzaklara” susuz bir toprak gibi bekliyorum seni...senin gözlerinle bakıyorum gelinlik bir kız gibi çiçeklenmiş doğaya.  tüm beyazları toplayarak ağartıyorum yokluğunun karasını.  sarı ve kırmızılarla  “seni seviyorum”  yazıyorum evimiz karşısındaki dağlara.  ve bu mevsimde söylenebilecek en güzel şiirlerden birini söylüyorum senin için, senin geleceğin yollara.

	“dağlarına bahar gelmiş memleketimin”

     seni her düşünüşümde birbirimize öğrettiklerimizi gözden geçiriyorum. herkesin gözü önünde ve yaşımızın üzerinde bir bilgelikle yaşamımızdan damıttığımız yıllarımızı düşünüyorum. rastlantıyla bulduğum elbiseme yapışmış bir tel saçını aylarca sakladığım Menemen günlerimi.  aramızdaki yüzlerce kilometreyi santime indirgeyen mektuplarımızı, telefonlarımızı ve düşlerimizi düşündüm. beklenilmeyeni gerçekleştirmemizin gönenciyle bağırdım. “nelere nelere baskın gelmez ki seni düşünmenin tadı! ” 

     çıkıp geleceksin. biliyorum.  ve geleceğini bilmenin coşkusuyla gülüşlerinden yapraklar yapıyorum yolunun üzerindeki çıplak ağaçlara.  kıyıda köşede kalmış acılarla savaşmak için sana ilk kez “seni seviyorum” dediğim günü kuşanıyorum.  ve heyecandan patlamaya hazır yüreğimi sürüyorum en kötü olasılıkların orta yerine.  biliyorum.  çıkıp geleceksin...doğanın verdiği yaratıcılıkla avuçlarında daha da büyüttüğün sevdayla...sevdamızla...

	özlemin kötü huylu bir ur gibi oturdu yüreğime.

		DESTAN  2

bir şelale gibi döküp saçlarını omuzlarına

çağıran sağanaklarınla ıslatırsın beni

coşkun dalgaların kıyılarımda

arzuyla bakan gözlerin yangınlara salar beni

çağırta çağırta kendini

				24.01.1998  Menemen', 'MEKTUP  3      özlemin kötü huylu bir ur gibi oturdu yüreğime.  şimdi ellerinin değdiği yerleri seviyorum. saatleri sayıyorum geleceğini bil...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektup-3-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oradan geçen bir çocuk', 'oradan-gecen-bir-cocuk-umit-paksoy-imyw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırak beni

kaçır

şeytanlar çıksın içimden

sen katil ol, ben maktul

sen katil ol, ben kanatları yolunmuş, rezil

sen katil ol, ben ağlanacak haline bile ağlıyor

Bir an için

oradan geçen bir çocuğun

o fotoğrafı gördüğünü düşünürsek

o fotoğrafla zamanın

bir daha yaşanmayacak bir mevsime

bir daha tekrarı olmayacak bir oradan geçişe

çerçevelendiğini de

hesaba katmalıyız

Bir sehpa,

çerçevelenmiş bir ilkbahar,

oradan geçen bir çocuk...', 'Bırak beni kaçır şeytanlar çıksın içimden sen katil ol, ben maktul sen katil ol, ben kanatları yolunmuş, rezil sen katil ol, ben ağlanacak h...', ARRAY['Türk Edebiyatı','Şiir','Ümit Paksoy']::text[], 8.5, '{"poet":"Ümit Paksoy","poet_slug":"umit-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oradan-gecen-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 4', 'mektup-4-salim-calik-9u6lp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MEKTUP  4

     darbeler ve muhtıralar çocuklarıyız biz. ne olduğunu, neler yaşandığını kavrayamasak da anamızın, babamızın, komşularımızın tedirgin adımlarından, ürkek bakışlarından, yabancıların, hatta manavın, bakkalın yanındaki suskunluklarından anlıyorduk iyi şeyler yaşanmadığını.

     darbeler ve muhtıralar çocuklarıyız biz. kuşkunun, kaygının insanı boğan yalnızlıklarını paylaştık abilerimizin ve ablalarımızın.... ve onlardan öğrendik güveni, onuru, sevdayı...

      ''asmayalım da besleyelim mi? '', ''kana kan intikam intikam''  çığlıkları arasında insanlıktan çıkanlara baktıkça daha bir gururlandık bize insanlığımızı öğretenlerle ve insanlığımızla. daha bir büyüdük, ve idam sehpaları kuranlara inat daha bir sevdik Deniz''i,  daha bir sevdik Yusuf''u, daha bir sevdik Hüseyin''i, daha bir sevdik.... ve öykündük yaşamlarına.

	

     darbeler ve muhtıralar çocuklarıyız biz. sevdalarımız memleketimize benziyor bu yüzden. tüm güzellikleriyle göz alıcı bir ''anka'' gibi dirildikçe yeniden yeniden yakıldığımız ateşleri beslediler. işte bu yüzden çatık kaşlarımız, bu yüzden yüzyıllara dayanır en yeni türkümüzün yaşı. 

     kardeşliği yaşayabilmek için tüm dünya halklarıyla; uzatarak yollarımızı yürüdük el ele. yürüdükçe yollara barikat, yürüdükçe kurşun, yürüdükçe panzer, yürüdükçe olağanüstü hal ve yürüdükçe....yürüdükçe özgürlük, inadına sevda ve inadına başkaldırı...

	

     darbeler ve muhtıralar çocuklarıyız biz. açık cezaevine dönüştürülen ülkemizde her karşılaşmamız bir görüş günüydü. her tutsaklık, her ayrılık her ölüm bin isyan. sıkılı yumruklarımızla beslediğimiz, düşüncelerimizle yoğurduğumuz binlerce isyan. 

     yaşayarak gördük ki, zaman en iyi yargıcı tarihin.

şimdi bir yanda bizi biz yapan mirasıyla yolumuzu aydınlatanlar

     şimdi bir yanda her aydınlığı karartarak ülkemizi batıranlar

     ve görüyoruz ki sevgilim; yer değiştiriyor herkes. 

akarsu yatağını bulup, ulaşıyor Deniz''ine. 

ve kalem kıranlar, parmak kaldıranlar milyonlarca kez öldüler halkın bilincinde. ve dupduru yalın sevdalarıyla koşmaya devam ediyor emperyalizme karşı yürekler. 

     darbeler ve muhtıralar çocuklarıyız biz. büyüdük ülkemizi doyasıya gezemeden. büyüdük özlemeye yazgılı bir yaşamı taşıyarak bedenimizde. sevgiliyi özler gibi özleyerek sevdik bu ülkeyi, ölümüne sevdik ülkemizi... yaşadığımız tüm acılara rağmen en güzel günlerimizin yaşamadıklarımız, yaşayamadıklarımız olduğu bilinciyle sevdik bu ülkede yaşadığımız her anı...

     ve topraklarımızda filiz veren kahramanlarımızdan biliyoruz; 

     ''..elbet ki sevgilim elbet / elini kolunu sallayarak.../ dolaşacaktır bu memlekette hürriyet''

                                Sürüyor Yollara Vurgunluğum

     işçilerin, memurların, köylülerin ve öğrencilerin eylem adımlarıyla, ''başka bir dünya mümkün'' sloganlarıyla dönüyorum sana.  biliyorum beni bekliyor olacaksın buğulu gözlerinle. biliyorum, tüm umutları ve direngenlikleri toplayıp düşüncelerinde beni bekliyor olacaksın... 

     alanlardan topladığım eylem gülleriyle dönüyorum sana. çocuğumuza, tüm çocuklara dağıtılmak üzere toplanmış barış çiçekleriyle dönüyorum. ırkın, rengin, dilin, dinin, coğrafyanın ayırmadığı, ayıramadığı kardeşlik türküleriyle...

     giderken sol göğsümde götürdüğüm sevdamızı yolların bilgeliği ve bizden öncekilerin bıraktığı deneyimlerle daha da büyütmüş olarak getiriyorum sana...ve bizden sonrakilere yollar boyu yeni deneyimler bırakarak dönüyorum sana...', 'MEKTUP  4      darbeler ve muhtıralar çocuklarıyız biz. ne olduğunu, neler yaşandığını kavrayamasak da anamızın, babamızın, komşularımızın t...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mektup-4-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Resmi Çiz Bana', 'kalp-resmi-ciz-bana-ramazan-ates-qowtw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ağaç olsaydım, 

Yol kenarında.

Gölgemde konaklar mıydın? 

Meyveler dolsaydım,

Dal arasında,

Alıpda eline tadar mıydın? 

Salıncak kurup,

Dalına öyle,

Zevk içinde sallanır mıydın? 

Elinde bir bıçak,

Ucuda sivri,

Gövdeme bir kalp resmi yapar mıydın? 

Sana açsam serin olan gölgemi,

Uzatıp ayaklarını, kapatıp da gözlerini,

Biraz olsun beni hayal eder miydin? 

Sen uyurken yaslanıpda gövdeme,

Öyle sıkı sarardım ki kendime,

Beni düşünde görür müydün? 

Koskocaman yarık açıp gövdemde,

Seni çekip almak için içime,

Söyle,  içime girer miydin? 

Ben bir ağaç iken yollarda,

Seni aldım, seni sardım koynumda.

Durur muydun? Bir bedenin içinde? 

Yaşar mıydın? Sımsıcacık içimde? 

Ramazan Ates/Esncehde-3.1.2006', 'Bir ağaç olsaydım,  Yol kenarında. Gölgemde konaklar mıydın?  Meyveler dolsaydım, Dal arasında, Alıpda eline tadar mıydın?  Salıncak kurup, ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalp-resmi-ciz-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsedin Diye...', 'gulumsedin-diye-metin-yalti-ub279', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O hep şiirleri sana yazardı,

Sohbetinde sözü senden açardı,

Olur da gelmezsen keyfi kaçardı,

Gülümsedin diye gizler kayboldu. 

Seviyorum dedin, aklım karıştı,

Gecem gündüz oldu, uykular şaştı.

Vermiştin bir resim, o muskalaştı.

Gülümsedin diye sisler kayboldu.

Seni sevmek bende tek amaç oldu.

Seviyorum dedin, gönlüm şen oldu.

Dudağımdan adın silinmez oldu.

Gülümsedin diye kinler kayboldu.

Bu gönül seninle bil ki şad oldu.

Bu aşkı sürdürmek artık farz oldu.

Gideceğin için gözüm yaş doldu.

Gülümsedin diye gamlar kayboldu.

Bu gün gördüm onu saçı ak olmuş,

Avurtları çökmüş bir haller olmuş,

Karşılıksız aşkın sürgünü olmuş,

Gülümseyemedi hazlar kayboldu.

Hiç insafın yokmuş ey zalim senin,

Aklını başından aldın Metin’in.

Dilerim bir aşka sürgün gidesin,

Gülümseyemedim, yıllar kayboldu.

 3/4/06', 'O hep şiirleri sana yazardı, Sohbetinde sözü senden açardı, Olur da gelmezsen keyfi kaçardı, Gülümsedin diye gizler kayboldu.  Seviyorum ded...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulumsedin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlüme...(Eşime)', 'guzel-gozlume-esime-ali-orhan-gunaydin-xhi6m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aynı yerdeyken bile seni özlerken,

Nasıl? hasret çekerim ben! 

O güzel gözlerin bana bakarken,

Nasıl? çok özlemem seni,ben!', 'Aynı yerdeyken bile seni özlerken, Nasıl? hasret çekerim ben!  O güzel gözlerin bana bakarken, Nasıl? çok özlemem seni,ben!...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzel-gozlume-esime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağla', 'cagla-salim-calik-z6he7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağla

camın buğusunda yol

yolda damla çoğul çağla

damlada sen

gidiyoruz işte teni yaka yaka

sende ben elimde kalan yanımla

(ölüm getiren baskınları kanıksadık

her gece

gecede soluğu kurşun kusan namluların

ve okunmayacak bir anı

camın buğusuna yazılanlar

''insanlaşma adaylığımızı vetoluyorlar'') 

gidiyoruz küçüle küçüle

sende fırtına bende toz duman

yolda damla çoğul çağla

akıyor kanla karışık akıyor zaman', 'Çağla camın buğusunda yol yolda damla çoğul çağla damlada sen gidiyoruz işte teni yaka yaka sende ben elimde kalan yanımla (ölüm getiren bas...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cagla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömürsün Sende Ölüm', 'omursun-sende-olum-ali-orhan-gunaydin-7olv5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömürsün valla ölüm sende,

Gelmeden önce haber verilmez mi? 

Şu kısa süren ömürde,

Son isteğin nedir? denmez mi? 

                   03/01/2006', 'Ömürsün valla ölüm sende, Gelmeden önce haber verilmez mi?  Şu kısa süren ömürde, Son isteğin nedir? denmez mi?                     03/01/20...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/omursun-sende-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeN-BeN', 'sen-ben-nail-oruc-bo66p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapattım  ışıklarını bir bir odalarımın

Bir bulut çöktüğünde odama

Gözlerinin karasından

Diziliverdi bir tespih gibi 

Yüreğimin sana ait kareleri:

Sen-ben, sen-ben, sen-ben…

Sonra gözlerin bir sıradağ oldu duvarda,

Kirpiklerinse  birer parmaklık.

Tam da bırakmışken kendimi eteklerine

Bir karesine takılıp kalmışım:

Erimiş tırnaklarım parmaklarımda

Umutsa gözlerimde 

Bakakalmışım  arkandan, giderken  bensizliğe

Sen-ben, …-ben, …-ben, …- ben…', 'Kapattım  ışıklarını bir bir odalarımın Bir bulut çöktüğünde odama Gözlerinin karasından Diziliverdi bir tespih gibi  Yüreğimin sana ait kar...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ben-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulaktan Kulağa Oyunu (Fısıltı)', 'kulaktan-kulaga-oyunu-fisilti-metin-soydeveli-tkzs2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kulaktan kulağa oyunu gibiydi sevdamız! 

''Seni seviyorum'' dedim. Yanımdakine

Sana iletmesi için

Seni ''seviyormuş'', demiş yanındakine

O da obürüne,  seni ''seviyor muymuş? '' demiş

Obürü de diğerine, '' seni seviyormuymuş neymiş''

Diğeri de sana, ''seni sevmiyormuş'' deyip,

Kestirip atmış

İnanma! .. inanmaA! .. İNANMAAA! ..

Gel yaklaş, yaklaş yanıbaşıma

Duy ilk ağızdan haykırışımı! .. 

''Seni seviyorum... Seni seviyorumm...''

''Seni seviyorummm...''SENİ SEVİYORUMMM...''', 'Kulaktan kulağa oyunu gibiydi sevdamız!  ''Seni seviyorum'' dedim. Yanımdakine Sana iletmesi için Seni ''seviyormuş'', demiş yanındakine O da ob...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kulaktan-kulaga-oyunu-fisilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderme', 'gonderme-salim-calik-bcu05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönderme

uzaktasın

benden uzakta

hem kapı kolunda hem alanlarda

çiçeklerde

      sularda

           yatakta

herşey

bana karşı

sana gönderme yapıyor bugün

                             Şubat 1996', 'Gönderme uzaktasın benden uzakta hem kapı kolunda hem alanlarda çiçeklerde       sularda            yatakta herşey bana karşı sana gönderme ...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gonderme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ı Beyazlar Yaşar', 'ask-i-beyazlar-yasar-ahmet-sali-vpv8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz yerlileri

Muhabbeti ayırdık kendimize

Beyazlara terkettiğimiz mevzilerde

Sürerken yenilgilerimizin izini...

Bıraktık Aşk''ı onlara

Light yapsınlar deyü nasırlaşmış

Kalplerini! ...

Güçlerini sınarken acımasızca 

Kanayan vicdanlarına -MERHEM OLSUN DİYE-

Aşk öykünmeleri ürettiler

İhtişamlı mekanlarda...

-HALBUKİ KAHRAMANLARI DA YERLİYDİ! -

Koskocaman kalbe tek bir aşkı sığdıracak kadar 

Minicikti; 

Öyküleri! ...

Platonik ve gerçek dışıydı

Hayata yamanamayacak kadar 

da banal...

Ne yaşayacak kadar

Cesurdular! 

Ne de bizlere açıklayacak kadar

Bilgili! ...

Bize yakışıyordu; muhibbileşmek 

Ve koskoca kalbe sığdırmak

Sevgileri...

Kimilerini çocuklarımızla 

Paylaştık

Kimilerini, analarımız ve

Bacılarımızla

Bazıları da 

Kadınlarımıza özeldi! ...

-VE AĞACI VE MAHLUKATI SEVECEK KADAR BÜYÜTTÜK KALBİMİZİ-

Arabesk''te takıldık kimi

-HÜZNÜ UCUZA MALEDECEK KADAR KURNAZDIK YA! -

Sevemedik ASLA; 

Platonik Aşk''ı 

Katı atık bırakılmış gibi 

Kirletiyordu KALBİMİZİ! ...

Sevdalarda koştururken benliğimizi? ! 

Öğrendik adam gibi işlemeyi; 

Günahı bile...

Koskocamandı ya kalbimiz

ANCAK; 

Aşk; kalakaldı size....

Sevdalıyız biz hayata ve

ötesine...

Bazen kederlidir

Sevgimiz..

Bazen tutkulu ve bazen

ERKEKÇE! ..

-BİR SUDA İKİ DEFA YIKANILMAZ ÇÜNKİ-', 'Biz yerlileri Muhabbeti ayırdık kendimize Beyazlara terkettiğimiz mevzilerde Sürerken yenilgilerimizin izini... Bıraktık Aşk''ı onlara Light ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Salı']::text[], 8.5, '{"poet":"Ahmet Salı","poet_slug":"ahmet-sali","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ask-i-beyazlar-yasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-metin-soydeveli-pp3ng', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül avare

Gönül uçarı

Aşk bir şahin pençesi

Ölünecekse ölünecek; 

Yok aşkın kaçağı

Gönül engin

Gönül zengin

Dünya güzeli olmasa da, 

Sevdi birkere

Var mı dünya üzerinde dengin', 'Gönül avare Gönül uçarı Aşk bir şahin pençesi Ölünecekse ölünecek;  Yok aşkın kaçağı Gönül engin Gönül zengin Dünya güzeli olmasa da,  Sevdi...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonul-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni affet', 'beni-affet-ulvi-guvenc-6qzg9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olurdu sanki yanına gelebilseydim

Elerini tutup gözlerinin içine bakabilseydim

Seni seviyorum diyebilseydim

Şaşırmış gibi yapıp biraz kızarsaydın

Önce yere doğru bakıp sonra kafanı kaldırsaydın

Bende seni seviyorum deseydin

Sarılsaydık hemen bir birimize hiç ayrılmayacakmış gibi

Kulağına ‘ben sana mecburum bilemezsin’ diyebilseydim

Gülümseseydin sözlerimin büyüsüne kapılıp

Tam o an öpebilseydim seni soluksuz kalana dek

Etraftan görenler ayıplasaydı bizi

Biz umursamasaydık kimseyi,düşünmeseydik hiçbir şeyi

Olmadı işte yapamadım hiçbirini

Ben bir korkaktım sense çok güzeldin

İşte beni bu yüzden affet!', 'Ne olurdu sanki yanına gelebilseydim Elerini tutup gözlerinin içine bakabilseydim Seni seviyorum diyebilseydim Şaşırmış gibi yapıp biraz kız...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Güvenç']::text[], 8.5, '{"poet":"Ulvi Güvenç","poet_slug":"ulvi-guvenc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-affet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara', 'nice-yillara-hulusi-kilic-mow7b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulmayandan unutmayanlara

Sevgi,umut dolu selamlar olsun bugün! 

Alın canlarım,alındoslarım; 

Önce zihninize,sonra bedeninize yayın.

Sonra kaldırın; dik tutun başınızı,

Yürüyün engellerin üstüne,

Aşın bir bir,durmaksızın

Ve yürüyün birlikte güneşe doğru...

Hep birlikte ulaşın umut dolu yarınlara,

Daha da güzeline; mutluluğa,eşitliğe...

Barış içerisinde,

Daha nice yıllara!', 'Unutulmayandan unutmayanlara Sevgi,umut dolu selamlar olsun bugün!  Alın canlarım,alındoslarım;  Önce zihninize,sonra bedeninize yayın. Sonr...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nice-yillara-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut İstersen', 'unut-i-stersen-esat-korkmaz-vsjdw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi son sözünü söyle 

içinden geçeni de

Sonra da 

unut geceden kalan her şeyi

anı da unut gece bitende

bitti bitecek zaten 

tan ağaracak 

git

Ben kimi sarmak istesem 

sen gibi 

ne düşler biter kollarımda 

gel geç mi yaşamalı dersin

öyle ya

hangi Tutsak kaldı ki müebbet 

ardına bakmadan git

gidelim

ardına kayarsa gözucun

İşte o an onmaz yaram

sana tutkulu kalır ellerim.. 

Yüreğime sızar yerin 

dolmaz boşluğun

neylerim o an Sensiz

02.01.06', 'Hadi son sözünü söyle  içinden geçeni de Sonra da  unut geceden kalan her şeyi anı da unut gece bitende bitti bitecek zaten  tan ağaracak  g...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unut-istersen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf Karesi', 'fotograf-karesi-mahmut-ozkoca-f0yw6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ümit dolu gözlerle 

Bakıyorum denize

Bir sahil kahvesinde

Işık gelsin gözlerinize

Sohbetler gülüşmeler öpüşmeler

Çocukların içi gibi hayaller

Oynaşıyor birbiriyle köpekler kediler

Cıvıl cıvıl insanlar el  eleler.

Dünyanın tüm güzelliklerinin önünde

Poz veriyoruz güzelce, o anı

Ölümsüzleştiriyoruz fotoğraf karesinde

Ama biz ansızın ölüyoruz...

Ne karamsarlık ne keder benimkisi

Doğduğumdan beri taşıyorum bu hissi

Mutluluğun en güzelini yaşıyorum

Hayata, çocuk gözüyle bakıyorum', 'ümit dolu gözlerle  Bakıyorum denize Bir sahil kahvesinde Işık gelsin gözlerinize Sohbetler gülüşmeler öpüşmeler Çocukların içi gibi hayalle...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Özkoca']::text[], 8.5, '{"poet":"Mahmut Özkoca","poet_slug":"mahmut-ozkoca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fotograf-karesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Çerçeve', 'bos-cerceve-mahmut-ozkoca-upbix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben...  daima......ağlıyorum.

Güneşin kurşuni kızıllığı

Dalgasız denizin sarhoşluğu

İle yapayalnız sahilde

Kaleler  yapan oğlumu özlüyorum... Seni de.

Ben...

Yalnızlığın bu kadar zor

Kaçınılmaz olduğunu bilemezdim

Senden ayrılmadan önce

İçimde sönmek bilmiyor kor

				... Ya sende.

15 TEMMUZ...

Karanlık boyu denize bakıyorum

Ağlar çekiliyor usul usul

Üzerimden kara yıldızlar geçiyor

Yaklaş diyorum yanıma sokul

Şarkımızı aylar söylüyor

				... Usul usul.

Biliyorsun...

An-lar geçiyor dünya dönüyor

Kalbimde bir şiirsin bir resim

Hayatımızı anlatıyor yakıyor

Dudağından düşmüyor ismim

				... Senin de.

Anlamalıydık! 

Hüzünle umut kol kola beraber

Hem yaşıyor hem yaşamıyoruz bu şehirde

Hem el ele gönül gönüle beraber

Sabahyıldızı ile birlikte

                                       ... Hasret biter.

Bak! 

Şimdi kaybettiğim resim gibisin

Tuvale sulu boya ile boca edilmişiz

Fırçasız susuz çalış üzerimde sesin

Duyulur, resim çizgilerinde sensiz.

Anlıyorum neden! 

Bu şehrin ışıkları ansızın söner

Habersiz çekip giden kedi gibi 

Uslanmaz gönül sana döner

Ayrılamadığım şiirlerim resimlerim gibi.

Elimde değil! 

Katıksız sevgim karışır yaşantıma

Odessa’ya demir atarsın çiçeksin

Gölgen de artık uğramaz limanıma

Sen hiç koklayamadığım çiçeksin.

16 TEMMUZ...

Bir kadın ellerini uzatıyor rüyama

Saçları sen gözleri sen gülüşü, o...

Gülüşünü hiç katamadım hayatıma

Bir rüya bir hayaldi sen ve o.

Tutuklu yargılandı aşkım, o

Sivri çatılı kahpe şehirde

Sararan otlar çiçek açar mı, o

Kahpe şehrin gökyüzünde.

17 Temmuz...

Taammüden yaşamaktan bıktım 

Seni sensiz yaşamak istemiyorum

Duvarda boş çerçevedeki resim

İçinde seninle her şeyinle bensizim! 

17 Temmuz öğleden sonra...

Yavaşça yaklaşıyorum

Umarsız kaygısız yaşantımın

İp uçlarını veriyor şarkılar

Sessizce çığlık atıyorsun

Avazım çıktığı kadar susuyorum

		         ... Sen de.

18 Temmuz... 

Son gün

Böyle geçiyor

Sensiz...

Ve yalnızlık

Seremonisi gibi geliyor her şey

			... Sen de.

19 Temmuz

Çıkıyorum...

Uçsuz bucaksız buğday

Tarlaları önümde

Sararmış başaklar önümde

			... Sen de.

Unutma

Senin de gözlerin

Islanacak bulutlarla

Öylece ağlayacaksın

Güneşin kurşuni kızıllığında

20 Temmuz

Özgürüm...

Dalgasız denizin sarhoşluğu

İle sahilde kaleler

Yapan oğlumun önünde

   ben...

	...daima...

		...ağlıyorum...', 'Ben...  daima......ağlıyorum. Güneşin kurşuni kızıllığı Dalgasız denizin sarhoşluğu İle yapayalnız sahilde Kaleler  yapan oğlumu özlüyorum.....', ARRAY['Türk Edebiyatı','Şiir','Mahmut Özkoca']::text[], 8.5, '{"poet":"Mahmut Özkoca","poet_slug":"mahmut-ozkoca","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/bos-cerceve-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiiri ters yönden bakar bu cahil -- O tanır kendini', 'siiri-ters-yonden-bakar-bu-cahil-o-tanir-kendini-mikdat-bal-3a1v3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmediği halde burnunu nasıl,

Ustanın işine  sokar bu cahil

Ne kafiye bilir ne tarz ne usul

Şiiri ters yönden bakar bu cahil

Düşünmeden atar konuşur ergen

Yazdığı her şeyde hata ederken

Bana göre böyle olmalı derken

Kurulmuş düzeni yıkar bu cahil

Kalkar yanlış bulur benim dilime

Ne tekniğe bakar ne de bilime

Nerden öğrenmişse üç beş kelime

Adamın canını sıkar bu cahil

Cahil kafasını bilime yaslar

Herkese laf atar bilgiçlik taslar

Haddini aşarak herkese toslar

Her taşın altından çıkar bu cahil

Mikdat der bilgi mi? ,..  onda ne gezer

Dili sivri, sözle insanı üzer

Elinde kalemi yazar da çizer

Şiirleri bozar sakar bu cahil', 'Bilmediği halde burnunu nasıl, Ustanın işine  sokar bu cahil Ne kafiye bilir ne tarz ne usul Şiiri ters yönden bakar bu cahil Düşünmeden ata...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siiri-ters-yonden-bakar-bu-cahil-o-tanir-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Bekleyiş', 'sessiz-bekleyis-sadettin-deren-20d9j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben artık sersemin biri oldum,

Biliyorum gelmeyeceksin

Ama bekliyorum.

Evde yoksun,söylediler,

Perdelerde bir kıpırtı arıyorum.

Telefon etmezsin artık belli bir şey

Ama ya ederse diyorum.

Ben artık sersemin biri oldum,

Seni arıyorum ceplerimde.

Boynumda kolların geziniyor sanki,

Kapının anahtarlarını paspasın altından alamıyorum,

Yeni ayakkabıların boyandı gelirsin diye

Her gün taze ekmek alıyorum, seversin ya,

Çayın sımsıcak bak.

Ben artık sersemin biri oldum,

Aldım seni başköşeye oturttum.

Ayaklarını ovalıyorum yorulmuşsundur,

Ojelerin eskimiş,yeniliyorum,

Güzel bacaklarını üst-üste koyup,

Veriyorum eline bir sigara..

Seni seyrediyorum.', 'Ben artık sersemin biri oldum, Biliyorum gelmeyeceksin Ama bekliyorum. Evde yoksun,söylediler, Perdelerde bir kıpırtı arıyorum. Telefon etme...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sessiz-bekleyis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümüzdeki Ateş', 'gonlumuzdeki-ates-hulusi-kilic-128dw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep mektup,hep mektup...

Değişen,gelişen hiç bir şey yok,

Her gün havanda su dövüyoruz

Mektuplarla bu iş yürümez be gülüm! 

Ne senin yazdıklarınla,

Ne de benim yazdıklarımla...

Her ikimizin mektuplarını toplasak bile

Ancak üç gün soba tutuşturulur

Ve ancak üç gün ısınırız.

Öyle olduktan sonra; 

Kaç gün yanık tutar bu mektuplar

Gönlümüzdeki ateşi? 

Kaç gün ısıtır bizi bu sevgi?', 'Hep mektup,hep mektup... Değişen,gelişen hiç bir şey yok, Her gün havanda su dövüyoruz Mektuplarla bu iş yürümez be gülüm!  Ne senin yazdıkl...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonlumuzdeki-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı Emri', 'tanri-emri-sadettin-deren-1d02m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toparlanın ey kullarım

Kendinize gelin,silkinin şöyle.

Kokuşmuşluğunuzu görün artık.

Hep kötüye kullandınız verdiklerimi,

Devam edemezsiniz edepsizce böyle.

Kocaman süngerimi aldım elime

Siliyorum bütün yaptıklarınızı,

Yok sayıyorum hatalarınızı,

Yediğiniz bokları siliyorum duyun

Yeniden başlatıyorum hayatı,

Haydi göreyim sizi, buyurun.', 'Toparlanın ey kullarım Kendinize gelin,silkinin şöyle. Kokuşmuşluğunuzu görün artık. Hep kötüye kullandınız verdiklerimi, Devam edemezsiniz ...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tanri-emri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-ahmet-sefer-kocer-2fq8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlüm bu gün uslanmıyor

Kara gözlüm gelmez diye

Kuş yuvada seslenmiyor

Kara gözlüm gelmez diye

Arap atım yorulmuyor

Kudurmuş gem vurulmuyor

Buralarda durulmuyor

Kara gözlüm gelmez diye

Gülleri küsmüş kokmuyor

Çaylar kurumuş akmıyor

Gözüm kapandı bakmıyor

Kara gözlüm gelmez diye

Pınarlar boşa çağlıyor

Ağaçlar kara bağlıyor

Yollar ah çekip ağlıyor

Kara gözlüm gelmez diye', 'Gönlüm bu gün uslanmıyor Kara gözlüm gelmez diye Kuş yuvada seslenmiyor Kara gözlüm gelmez diye Arap atım yorulmuyor Kudurmuş gem vurulmuyor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sefer Kocer']::text[], 8.5, '{"poet":"Ahmet Sefer Kocer","poet_slug":"ahmet-sefer-kocer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-gozlum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahırlı Akşamlar', 'kahirli-aksamlar-metin-soydeveli-jk607', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam hüznü çökünce omuzlarıma

Lanet ederdim kahrına, kahrolası akşamların

Korkuturdu beni karanlık, gayyaya düşerdim her akşam

Sabah olmayacak, seni, gözlerini,

Bir daha göremeyeceğim sanırdım

Titrek mum ışıklarında sabahlardım

Uyuyup bir daha uyanamamak kaygısıyla

Her sabah gözlerini seyrederdim doğada

Gün alması gözlerim

Gözlerinde dünyayı görmeyen gözlerimle

Gecelerden birinde karanlığa kapadım gözlerimi

Hayal dünyamın ışıklarıyla aydınlattım gecemi

Hayallerimle derin uykulara dalmışım

Olanlar olmuş; sabahı, gözlerini görememişim 

Bu acıyla irkildim; uyandım! 

Mumlar erimiş, sönmüş, her taraf kapkaranlık! 

Yırttım gecenin karanlığını çığlıklarımla! 

Fırladım çıktım gecenin karanlık sokaklarına

Bu karanlık sokaklarda biri, belki benim gibi 

Sordu:'' işin ne gecenin üçünde buralarda''

Kapandım ayaklarına, ellerini öptüm, öptüm...

Meğer sabaha iki saat varmış! Ben rüya görmüşüm', 'Akşam hüznü çökünce omuzlarıma Lanet ederdim kahrına, kahrolası akşamların Korkuturdu beni karanlık, gayyaya düşerdim her akşam Sabah olmaya...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kahirli-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-hulusi-kilic-r17c1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar günüydü,her hangi bir gün...

Ne yağmur vardı,ne de ıslatacağı

Elleri koynunda kimsesiz çocuklar...

Islanacak toprak da yoktu gerçi,

Ama yeşerecek bir filiz vardı.

Yağmasa da yağmur,olmasa da toprak:

Gün doğmadan daha,ne umutlar doğacak!', 'Bir bahar günüydü,her hangi bir gün... Ne yağmur vardı,ne de ıslatacağı Elleri koynunda kimsesiz çocuklar... Islanacak toprak da yoktu gerçi...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umut-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Âvaresi Oldum', 'askin-varesi-oldum-bahaettin-karakoc-gh02u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akılgından bir dal kestim

Sopa yapmak değil kastım

Ben anadan doğma mestim,

Sen gitsen gizin kalıyor.

Yol oldum yoluna ulak

Ne aşım, ne işim dölek

Ne yapar yanmışsa bulak? 

İçimde sızın kalıyor.

Avârelik işim oldu,

Gülümsedim hışım oldu,

Hüzün kan-kardeşim oldu

Her şeyde izin kalıyor.

Sevdiğini ah bir bilsem

Umursamam yüzyıl yelsem

Oturup resmini silsem,

Ortada ağzın kalıyor.

İstihâreye yatarken

Çok derin kulaç atarken

Her yıldız bir bir batarken

Senin yıldızın kalıyor.

Döküldüm yârim döküldüm

Çok kırıldım, çok büküldüm

Sapa dağlara çekildim

Ayrık denizin kalıyor.

Doruklara duman çöker

Gökyüzü gözyaşı döker

Kolumu ayrılık büker,

Elde hep hüzün kalıyor.

Bahaeddin KARAKOÇ (Ihlamurlar Çiçek Açtığı Zaman / Ayışığınsa Serenatlar – Sıla Kitapları / İstanbul -2001)', 'Akılgından bir dal kestim Sopa yapmak değil kastım Ben anadan doğma mestim, Sen gitsen gizin kalıyor. Yol oldum yoluna ulak Ne aşım, ne işim...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/askin-avaresi-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İstiyor Bu Hayat Bizden?', 'ne-i-stiyor-bu-hayat-bizden-i-hsan-kurt-qwsxx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamaksa yaşıyoruz

Cahit gibi her günü dert edinerek

Ölmekse öleceğiz bir gün

Düşünüyorum ki şunu ölmeden

Ne istiyor bu hayat bizden? 

(Gül Şafağı Hüzünleri''nden)', 'Yaşamaksa yaşıyoruz Cahit gibi her günü dert edinerek Ölmekse öleceğiz bir gün Düşünüyorum ki şunu ölmeden Ne istiyor bu hayat bizden?  (Gül...', ARRAY['Türk Edebiyatı','Şiir','İhsan Kurt']::text[], 8.5, '{"poet":"İhsan Kurt","poet_slug":"i-hsan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ne-istiyor-bu-hayat-bizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-hulusi-kilic-g6bfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kaç günlük görüşme,arkası ayrılık...

Bu birlikteliğimiz de bitiyor,

Yine ayrılık,yine acı var.

Bir gün yine döneceğim; 

Oldukça bizde bu sevgi,

Yüreğimizde bu sancılar...', 'Bir kaç günlük görüşme,arkası ayrılık... Bu birlikteliğimiz de bitiyor, Yine ayrılık,yine acı var. Bir gün yine döneceğim;  Oldukça bizde bu...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/donus-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Deyipde Geçme', 'kus-deyipde-gecme-ramazan-ates-sveap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuş olsaydım, bir çınarın dalında,

Vara, yoğa öten, cik cik,

Durup da dinler miydin birazcık? 

Uçup konsam, ben omzuna yumşacık,

Ürkek ürkek gözlerine bakarak,

Tutup beni okşar mıydın birazcık? 

Tüylerim, pamuk gibi yumuşak,

Ellerinle beni tutup yüzüne,

Sevgi ile sürer miydin birazcık? 

Gözlerim ışıl ışıl sıcacık,

Bal dudağın sevgi ile yaklaşıp,

Beni öyle öper miydin birazcık? 

Heyecandan kalbim hemen duracak,

İsterdim ki gül sinende azıcık

Beni öyle tutar mısın birazcık? 

Seni öyle arzu ile gezerek,

Güzelliğin gözlerimle süzerek,

Sever miydin sende beni birazcık? 

Ramazan Ateş/Enschede-3.1.2006', 'Kuş olsaydım, bir çınarın dalında, Vara, yoğa öten, cik cik, Durup da dinler miydin birazcık?  Uçup konsam, ben omzuna yumşacık, Ürkek ürkek...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kus-deyipde-gecme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muzdarip', 'muzdarip-ugur-aydin-2-43z88', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi bekletmekten.. kimi beklenmekten 

muzdariptir..

oysa  senle ben bekletilen amma 

beklenmeyenlerdeniz....

öyle değilmi kaybolan gençliğim...', 'Kimi bekletmekten.. kimi beklenmekten  muzdariptir.. oysa  senle ben bekletilen amma  beklenmeyenlerdeniz.... öyle değilmi kaybolan gençliği...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/muzdarip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok(sun)  luk mu?', 'yok-sun-luk-mu-bilge-karamehmet-z1op9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokuluğun işten gelirdi her akşam,

Başımı cama yaslar beklerdim seni...

Sokağı aydınlatan her ışığı sen sanardım,

Nefesimden buharlanan

cama yazardım ismini...

Sular varınca pencere dibine, gelir derdim..

Penceremdeki ismin 

ağlardı her bekleyişimde

Yokluğun hiç bitmeyen işten gelirdi her yaz akşamı,

Gelince konuşamazdım

Tüm kelimelerin korkardı 

senin yorgunluğundan

Yutkunurlar geri dönerlerdi her seferinde...

Bilmezdin...

Sana ne kadar özlem duyduklarını,

Güzel sözlerine hasret bile olamadım,

Tanışmak istedim hep ama

Dedim ya..

Bir türlü kısmet olmadı....', 'Yokuluğun işten gelirdi her akşam, Başımı cama yaslar beklerdim seni... Sokağı aydınlatan her ışığı sen sanardım, Nefesimden buharlanan cama...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yok-sun-luk-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-nesibe-yildirim-74uum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimi açtım zümrütü ankanın kanatlarındayım, 

Yıldızlara, baktım pırıltıları yüzüme değdi, 

Gökkuşağı renklerini önüme sundu,

Güneşi gördüm gamzesi yanağıma kondu

Derken yer kırmızı, gök kırmızı.

Bir yere indim, dağlar taşlar

Yürüdüm dev adımlarla,

Nehirler önüme durdu,

Dağlar, eteklerini aşağı sundu

Dallar yollarına yemişlerini koydu

Vardım yolun sonuna, mahşer yeriydi sanki.

Sen ortalığa düşmüş beni arıyordun,

Birden ellerimi tuttun 

Yüreğimdeki sevgi gönlüme kondu  

                                                     01.03.2006', 'Gözlerimi açtım zümrütü ankanın kanatlarındayım,  Yıldızlara, baktım pırıltıları yüzüme değdi,  Gökkuşağı renklerini önüme sundu, Güneşi gör...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Yıldırım']::text[], 8.5, '{"poet":"Nesibe Yıldırım","poet_slug":"nesibe-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruya-225-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-hulusi-kilic-c411v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi bir kış gecesinin koynundayım

Hem de bitimsiz,uzun,adamakıllı...

Dışarıda durmaksızın yağan yağmur,

Dağları yıkarcasına esen fırtına var.

Üstelik mum ışığı da küskün yaşama...

Radyoda tanımadığım şarkılar,

Duvarda bilmediğim resimler...

Anlayacağın paylaştığımız hiç birşey,

Seni anımsamam için hiç bir neden yok.', 'Şimdi bir kış gecesinin koynundayım Hem de bitimsiz,uzun,adamakıllı... Dışarıda durmaksızın yağan yağmur, Dağları yıkarcasına esen fırtına v...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yabanci-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin çiçeği', 'kalbimin-cicegi-nesibe-yildirim-81zaq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kibrit yaktım

Gözlerim yanan bir kıvılcımdı

Sus ağlama dedim, sustu

Gözlerinde bir acı belirdi 

Hüzünlüydü nedendi bilmem 

İçim acıyla burkuldu 

Sordum sualim cevapsız 

Nedenini oda bilmiyordu 

Gülümsedim derdine inatlaşırcasına

O da gülmüştü, yinede ağlıyordu 

İçimde bir yangın, bir acı vardı

Boğazıma hıçkırıklar düğümlendi sanki

Kulağımı tırmalarcasına bir feryat

Bir zil sesiydi beni uyandıran

Acıydı beni yıkan, yüreğimi dağlayan

Devrildim yaşlı yorgun bir ağaç gibi

Kara bir haberdi onun ölümü

Boğazımda bir düğüm gözlerim yanıyordu

İnanmamış feryat etmiştim nafile

Biliyordum ilahi takdirdi hepsi gerçekti

Anlamıştım şimdi neden ağladığını

Sebebi ölümün yakınlığının hissi

Sarmıştı benliğimin kalbimdeki eşsiz yeri

Bütün bu sevda, bir ömrün, bir arkadaşlığın bedeli

Onu düşündüğüm bir akşamdı yine 

Uykularıma kamcı gibi gözleri

Aklımdan bir türlü gitmedi,

Kalbimin bir çiçeğiydi o gözyaşımla suladığım.

                                                    25.07.1997', 'Bir kibrit yaktım Gözlerim yanan bir kıvılcımdı Sus ağlama dedim, sustu Gözlerinde bir acı belirdi  Hüzünlüydü nedendi bilmem  İçim acıyla b...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Yıldırım']::text[], 8.5, '{"poet":"Nesibe Yıldırım","poet_slug":"nesibe-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalbimin-cicegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz - Senli', 'sensiz-senli-metin-soydeveli-7zcdh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O, yalnız bizim dediğin yerde

Şimdi ben

Yalnız dolaşıyorum

İçimde acı burukluklarla.

Burkulan, acı çeken yalnız ben değilim,

Ağaca çizdiğimiz kalp ağlamakta.

Kara  kara düşüncede kuşlar

Ötmeyi unuttular şimdi.

Derenin şarkı söyleyen şırıltıları

Şimdi ağlamaya bıraktı yerini.

Mehtap bildiğin gibi değil şimdi

Sabahlara dek kıvranıyor acılar içinde! 

Derenin hırçın, ağlayan göz yaşlarında,

Bitgin, çaresiz kendini yitiriyor çam dallarında.

Seninle hoştu, haz vericiydi bunlar

Ağaca çizdiğimiz kalbin

Göz yaşları mutluluktan,

Kuşların ötmeyişi aşkımıza hürmettendi.

Dere o zama da ağlıyordu belki! 

Ama, derenin ağlayan şırıltıları aşkımzın şarkısıydı

Mehtap desen, çılgın bir rakkase.

Raksını çılgınca alkışlamak geliyordu içimizden.

Çam dallarında kendini yitirişi bile ne hoştu

Yarınlara doğabilmek için.', 'O, yalnız bizim dediğin yerde Şimdi ben Yalnız dolaşıyorum İçimde acı burukluklarla. Burkulan, acı çeken yalnız ben değilim, Ağaca çizdiğimi...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-senli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdıraptan kurtuluş', 'izdiraptan-kurtulus-nesibe-yildirim-y2zri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deryalara ağladım 

Göz yaşlarım, dinmedi 

Yüreğimdeki, dar kapı

Bir türlü açılıp gitmedi

Acılarım karabasan oldu 

Düşlerim yandı kavruldu, külleri bitmedi

Hasret gemisi gemisi ufukta kaybolup sessizleşti

Yeminlere sığındım hatıralarım silindi.

Duygularımı hazine misali derinlere gömdüm

Feryat figan ettim haykırdığım bilinmedi

Tüm alemi seyre daldım umutlarım tükendi 

Yaralı ceylan tabiri, düşlerim ok ucunda yere serildi

Gözlerimi geceye hapsettim 

Yüreğim bir çocuk misali şenlendi

Dünyada güzel olan her şeyi sevmeye çalıştım

Yoluma çıkan bir demet çiçek aklım başıma getirdi

                                                                   28.03.1997', 'Deryalara ağladım  Göz yaşlarım, dinmedi  Yüreğimdeki, dar kapı Bir türlü açılıp gitmedi Acılarım karabasan oldu  Düşlerim yandı kavruldu, k...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Yıldırım']::text[], 8.5, '{"poet":"Nesibe Yıldırım","poet_slug":"nesibe-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/izdiraptan-kurtulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-nesibe-yildirim-ynoi7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük yüreklere sığdıramadık sevgileri

Güzel sözcükler açamadı kilitleri 

Kırılan kalpler bir daha birleşemedi

Alın götürün beni kuşlar yaralı kanatlarınızla

  

Çığlık, çığlık sonsuzluğa dek sürecek sanki

İnsanlar duyarsız her şeye gülüp geçti

Yaşam alevi yandıkça  yandı tükendi

Alın götürün beni kuşlar yaralı kanatlarınızla

Akan kanlar damlayarak birikti

Küçük bir çocuğun hançerlendi düşleri

Günler aylar geçti bu vahşet bitmedi

Alın götürün beni kuşlar yaralı kanatlarınızla

Yalanlar yeminlerle sakız gibi çiğnendi

Gözlerimi açtım bu vahşeti görünce yüreğim titredi

Yağmur yağdı yeryüzündeki kanı temizleyemedi

Alın götürün beni kuşlar yaralı kanatlarınızla

 

 (Bosna anısına)    27.11.1995', 'Küçük yüreklere sığdıramadık sevgileri Güzel sözcükler açamadı kilitleri  Kırılan kalpler bir daha birleşemedi Alın götürün beni kuşlar yara...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Yıldırım']::text[], 8.5, '{"poet":"Nesibe Yıldırım","poet_slug":"nesibe-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kuslar-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluklarımın Kadını', 'mutluluklarimin-kadini-ahmet-agir-7tdcq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen mutluluklarımın kadını

Seninle yaşadım baharları

Sen benim karanlık gecelerime

Güneş gibi doğan aydınlığım

Sen bana tekrar gülmeyi öğrettin

Sen benim acılarımı dindirdin

Gökkuşağım oldun yeniden

Seninle bildim renklerin güzelliğini', 'Sen mutluluklarımın kadını Seninle yaşadım baharları Sen benim karanlık gecelerime Güneş gibi doğan aydınlığım Sen bana tekrar gülmeyi öğret...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağır']::text[], 8.5, '{"poet":"Ahmet Ağır","poet_slug":"ahmet-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutluluklarimin-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-ahmet-agir-utdto', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatım; sürgünler ülkesi,

Köşe bucak savrulmuşum ben.

Yüreğim; yangın yeri,

Cayır cayır yanan ormanlar misali.

Aşklarım, ya aşklarım,

Hazan mevsimi, bir kuru yaprak…', 'Hayatım; sürgünler ülkesi, Köşe bucak savrulmuşum ben. Yüreğim; yangın yeri, Cayır cayır yanan ormanlar misali. Aşklarım, ya aşklarım, Hazan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağır']::text[], 8.5, '{"poet":"Ahmet Ağır","poet_slug":"ahmet-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hazan-mevsimi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokun', 'dokun-hakan-kartal-dc4iy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geceye sapladığım fotoğraftan, 

ayırdım parmakuçlarını 

kirpiklerinden akıttığın kokumu 

yıkadım çığlığınla 

dokun kadın 

dokun,üryan dudağıma 

yolculuksun içimde, 

göğsüme vakitsiz astığım 

kızıla kesen al çarşafın, 

gemzeler üşüten dişiliği 

nefesinle ezdiğin saatler bitmesin 

dokun kadın 

boşal deniz gözlerime 

büyüsün sevişmemiz 

Hakan Kartal 

18 Aralık 2005 / İstanbul', 'geceye sapladığım fotoğraftan,  ayırdım parmakuçlarını  kirpiklerinden akıttığın kokumu  yıkadım çığlığınla  dokun kadın  dokun,üryan dudağı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kartal']::text[], 8.5, '{"poet":"Hakan Kartal","poet_slug":"hakan-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dokun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-riza-cinar-9yr2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Net cevaplarıyla en çok babamı sevdim zıt düşünceleriyle doğru kararlarıyla acemi bağırmalarıyla bu dünyada en çok babamı sevdim sevdim sevdim dedim vurdun kırdın dedim senin ekmeğini ben çok yedim allah razı olsun babam kalbimim tahtı senin dünyanı kemeri senin benim aklım biraz serin hatalarımı affet babam', 'Net cevaplarıyla en çok babamı sevdim zıt düşünceleriyle doğru kararlarıyla acemi bağırmalarıyla bu dünyada en çok babamı sevdim sevdim sevd...', ARRAY['Türk Edebiyatı','Şiir','Rıza Çınar']::text[], 8.5, '{"poet":"Rıza Çınar","poet_slug":"riza-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/babama-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bensin', 'sen-bensin-ahmet-agir-zpv0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni özlüyorum her zamankinden beter

Çığlıklarım sessizliklere gömülür

Hep sen derim, sen der bu beden

Sen akarsın vücudumda sıcak sıcak

Seni taşırım içimde en ücra köşelerinde

Seni tanımlarım her dilde

Çiçeklere kuşlara böceklere

Seni nasıl sevdiğimi anlatırım

Sen hayatsın bir sudaki kadar güzel

Sen yaşamsın en mutlu bedenlerde

Sen özlemsin en hasret dolu gurbetlerde

Sen bensin bu beden de...', 'Seni özlüyorum her zamankinden beter Çığlıklarım sessizliklere gömülür Hep sen derim, sen der bu beden Sen akarsın vücudumda sıcak sıcak Sen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağır']::text[], 8.5, '{"poet":"Ahmet Ağır","poet_slug":"ahmet-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bensin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-34 (M.S.) 03/01/2006', 'mektuplar-34-m-s-03-01-2006-mahzun-doga-r90xo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üstümüz ilk yaşam. 

Kurumaktan kıl payı kurtulmuş bir hayat.

Tekeline alınmışız açık ve tok bir yolun.

Raylarımız birleşmeye bilenmiş.

Son istasyondayız; 

tenin.

Ne güzelsin. 

Zamanın Son Harikası.

Dilinde ne güzel bir ismim.

Adaletin bulunan yarısı.

Ne çok yakışıyor sana sana yakışmak.

Bana ne çok yakışıyor sana yakışmak.

Uzun bir yer üstü gömütlüğün ardından.

Ne çok yakışıyor bize değerin.

Mahşerimiz hazır.

Ölmek hazır artık sevgimli.

Bize de yırtılabilir yer.

Tufanlar kopabilir artık.

Kainat birleşebilir.

Karnına sığabiliriz artık.

Rahminde hayatla buluşmak.

Sütünden bir parça ekmek yemek.

Kucağında hayata alışmak.

Ne çok yakışıyor sana cennetli olmak.

Kollarında ayağa durmak.

Şefkatinde yürümek.

Emeğinde koşmak.

Ne çok yakışıyor sana sende yaşam bulmak.

Dalında durmak güzel.

Bir damla suyundan içmek.

Renginde mavi bir yaprak olmak.

Meyvelerinin tadında olmak.

Seni içimlemek ne güzel ey mavi balçık.

Yeryüzümün tek sermayesi.

ilk emanetim.

seni sevinmek ne huzurlu bir sevinç.

Ölmek hazır bize artık sevgilim.

Yıllar birleşti.

Yollar birleşmeye hazır.

Sende yaşamaya hazırız ikimiz.

Emeğinde bir lokma su olmak ne güzel.', 'Üstümüz ilk yaşam.  Kurumaktan kıl payı kurtulmuş bir hayat. Tekeline alınmışız açık ve tok bir yolun. Raylarımız birleşmeye bilenmiş. Son i...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mektuplar-34-m-s-03-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen beni hiç sevmedin', 'sen-beni-hic-sevmedin-abdulvahap-ates-ogcqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen beni hiç sevmedin

nedir çektiğim senden

her anımı kapladın

ruhumun ortasına

varlığını sapladın

hacmin arttı içimde

ele yar bırakmadın

karanlık doldu içim

bir mum bile yakmadın

senle ortada kaldım

bir sevimlik takmadın

onurluca sevmemi

dönüpte ayıpladın

sevgimin can evine

bir ok gibi saplandın

taktir edecek yerde

sabrımı eleştirdin

ben tuttum seni serde

sen aleme bildirdin

bir var bir de endama

sevgimi değiştirdin

kalbimi sundum sana

sen bana kin besledin

olmadı olmayacak

sen beni hiç sevmedin', 'sen beni hiç sevmedin nedir çektiğim senden her anımı kapladın ruhumun ortasına varlığını sapladın hacmin arttı içimde ele yar bırakmadın ka...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-beni-hic-sevmedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeklerimi Sulamayı Unutma', 'ciceklerimi-sulamayi-unutma-melih-coskun-0pncz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Silahının kabzasına 

Gülen çocuk resimleri çizen 

Zoraki bir kontrgerillayım ben dağlarında. 

Nişan almayı bilmez ellerim 

Kalem tutmayı bildiği kadar 

Anne bak 

Senin için gül büyüttüm koynumda 

Koklama sakın

Dokunma

Güzel annem/ Ağlama...

Dicle''m; 

Sen gözyaşıydın dağlarımın 

Taptaze kurşun yarası döşümde, 

Kızaran yanağı gelinlik kızın 

Oğlanın sert bakışının ardında sakladığı 

Ölümüne sevdası, 

Saymadım 

Toprak olan kaçıncı ana yüreğidir adım 

Kaç mektubum var hiç yollanmamış

Hasretimin çetelesini tuttuğum defterin arasında 

Silahının kabzasını

Gökkuşağının yedi rengine boyayan  

Zoraki bir kontrgerillayım ben dağlarında 

Bir parka verdiler adımı

Güleç yüzlü çocukların oynadığı

Bak güzel annem 

Senin için gül büyüttüm koynumda

Çiçeklerimi sulamayı unutma... 

2005', 'Silahının kabzasına  Gülen çocuk resimleri çizen  Zoraki bir kontrgerillayım ben dağlarında.  Nişan almayı bilmez ellerim  Kalem tutmayı bil...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ciceklerimi-sulamayi-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aci Çekiyorum', 'aci-cekiyorum-mustafa-aslan-2-luepr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözüm hiç geçmiyor,

Sevdama kiymet verilmiyor,

Hep yalniz kaliyorum,

Hep ben agliyorum,

Sevmek buysa eger ben yokum arkadas.

Sevdim hep aci çektim,

Sözümü birtürlü geçiremedim,

Ben dedimse ankara,

O dedi istanbul.

Dogruyu söylesem yalan gibi geliyor,

Inanmiyor,

Kiskaniyorum desem,

Beni kiskançliktan kudurtuyor,

Hiç beni dinlemiyor.

Benden birseyler sakliyor,

Belki gerçekleri,

Belkide yalanlari.

Belkide benden sevgisini sakliyor,

Belkide Göstermek istemiyor.

Simdi aci çekiyorum,

Neden mi? 

Çünkü seviyorum,

Severken,

Mutlu olmak yerine,

Hep aci çekiyorum,

Mutlu olmak istesemde,

Olamiyorum.

Onu birakmak istesemde,

Baglanmisim birakamiyorum.

Tarih Ve Saati: 29/05/2005	15:12', 'Sözüm hiç geçmiyor, Sevdama kiymet verilmiyor, Hep yalniz kaliyorum, Hep ben agliyorum, Sevmek buysa eger ben yokum arkadas. Sevdim hep aci ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aci-cekiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acilar Denizi', 'acilar-denizi-mustafa-aslan-2-kpgcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daldim hergün acilar denizine,

Yüzme bilmiyorum, kurtaran yokmu,

Boguluyorum acilar denizinde,

Kalbimin yarasini yakti tuzlu su.

Kurtaran yok, neden bilmem,

Acilar içindede olsamda artik ölmem,

Insanlara karsi bu günden sonra gülmem,

Aglar dururum acilar denizinin kenarinda.

Acilar denizi okadar mahsum görünüyorki,

Içinde yüzmek istiyor insane,

Içine girdikten sonra yüzemezsin,

Bedenin kapilir acilar denizene sürüklenirsin.

Bana simdi sarhos diyorlar,

Ama gerçekten derdimi bilmiyorlar,

Ben sarhos degilim,

Ben sadece ask sarhosu olmusum.

Hergün acilar denizinin sahilinde oturur,

Yalvaririm acilar denizine,

Çek git, rahat birak beni, su halime bak,

Artik çek git hayatimdan, 

Sayende sevdiklerim çekip gitti,

Can dostlarim sahte çikti,

Sevdiklerim beni biraktilar.

Çek git, su halime bak,

Çek git, hayatimdan,

Çek git, baska sahillere,

Çek git, basima gelenlere bak,

Çek git, ACILAR DENIZI, çek git. 

Tarih Ve Saati: 31/10/2004		11:40', 'Daldim hergün acilar denizine, Yüzme bilmiyorum, kurtaran yokmu, Boguluyorum acilar denizinde, Kalbimin yarasini yakti tuzlu su. Kurtaran yo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/acilar-denizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aciya Alisilmaz', 'aciya-alisilmaz-mustafa-aslan-2-mjxvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdigimde hiç sevilmedim,

Ben aglarken,

Onlar güldü.

Yaman sevdalara kosarken,

Yolda kaldim,

Bir dost çikipta el uzatmadi,

Bir batakliga düstümya,

Gelen giden hep vurdu,

Alismalisin dediler,

Alismak istedim,

Felek vurmus,

Insan oglu vursa ne yazar.

Acilar pes pese geldi,

Beni aldi seller gibi,

Götürdü bilinmez diyarlara,

Herkez ayni sözü söyledi,

Alismalisin aciya,

Alismalisin yasadiklarina,

Alismalisin felegin tokatina,

Alismalisin kader yazina.

Benim sadece bir sözüm oldu,

Herseye alisilir,

Yillardir aci çektigim halde,

Aciya alisamadim,

Bilinki dostlarin,

Ne yaparsaniz yapin,

Aciya alisilmaz.

Tarih Ve Saati: 23/05/2005	22:18', 'Sevdigimde hiç sevilmedim, Ben aglarken, Onlar güldü. Yaman sevdalara kosarken, Yolda kaldim, Bir dost çikipta el uzatmadi, Bir batakliga dü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aciya-alisilmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte o zaman', 'i-ste-o-zaman-sinan-oktay-38ge1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni istiyorum! ! ! 

    Karanlığın karanlığı,

    Aydınlığın aydınlığı,

istediği kadar.

  Aydınlansın sevdamın evi

yüreğimde sevdanla.

 İşte o zaman,

 Gündüzüm sen karakış içersinde

baharım sen,

  rüzgarları beni sarhoş eden.', 'Seni istiyorum! ! !      Karanlığın karanlığı,     Aydınlığın aydınlığı, istediği kadar.   Aydınlansın sevdamın evi yüreğimde sevdanla.  İşt...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-o-zaman-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aciya Dönüs', 'aciya-donus-mustafa-aslan-2-v346q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir derin nefes, bir de karanlik,

Yeter bana...Bu yalan dünyada,

Gökten yagmur degil tas yagsa,

Gözlerim damla yas olsa,

Yüregim hasretinle alev gibi yansa, 

Unutma ki seni hergün sevecegim.

Hergün seni ariyorum,

Sensiz, dünyam çok sessiz,

Yasayamiyorum,

Hep seninle olmak istiyorum

ÇÜNKÜ SENİ ÇOK SEVİYORUM

Yürüyorum,

Ne kaldirimlar biter,

Ne basibos geceler.

Ne göz yasim diner,

Ne de gözyasimi kimse siler,

Ne kalbim kanar,

Ne de sevenler beni yakar.

Ansizin gözlerinde durdum,

Donup bakakaldim gözlerine,

Bir uçurumdan düser gibi oldum,

Kistan, bahara döndü gönlüm,

Üsüyen ruhum, isindi aniden,

Ansizin gözlerinde durdum ve sonra,

Yanlizligima sordum, sen var miydin gerçekten,

Yoksa hayallerimle mi savasiyordum,

Ve kendime sordum gerçek olan neydi,

Senin gözlerinmiydi? 

Tekrara hersey aciya döndü,

Elimde bir sigara,

Bir o yanar, bir de ben.

Düsmüsüm dört duvar arasina,

Bir o susar, bir de ben.

Tarih Ve Saati: 11/12/2004		13:01', 'Bir derin nefes, bir de karanlik, Yeter bana...Bu yalan dünyada, Gökten yagmur degil tas yagsa, Gözlerim damla yas olsa, Yüregim hasretinle ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aciya-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açmadan Soluyor', 'acmadan-soluyor-mustafa-aslan-2-7ow9j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açmadan soluyor güllerimiz,

Açmadan soluyor sevdamiz,

Ayirmak istiyor yalan insanlar,

Engelliyorlar sevdamizi.

Birakmiyorlar rahat sevelim,

Birbirimizi rahat görelim.

Gitmezki basimdan kara sevda,

Bilmemki derdimi kime satam.

Kaderimiz yanlis mi çizilmis,

Yoksa sevmek mi haram.

Anlayamiyorum artik dünyayi,

Batsin böyle yasam.

Son kez bakmak istiyordum gözlerine,

Sözlerimi eklemek istiyorum sözlerine.

Hep karsi çiktilar sevgime,

Sevgime ve sevenlerime.

Sevmek veya sevilmek,

Haram mis bana.

Aç kollarini,

Kosuyorum sana.

Birakma ellerimi,

Kurban olurum sana.

Açmadan soluyor,

Güllerimiz,

Sevdamiz,

Sevgimiz.

Hep ayrilik gül gibi açiyor,

Güllerimiz ise açmadan soluyor,

Ayni benim hayatim gibi.

Tarih Ve Saati: 26/12/2004		14:53', 'Açmadan soluyor güllerimiz, Açmadan soluyor sevdamiz, Ayirmak istiyor yalan insanlar, Engelliyorlar sevdamizi. Birakmiyorlar rahat sevelim, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/acmadan-soluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açtim Sana', 'actim-sana-mustafa-aslan-2-oia33', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgimi açtim sana,

Uzat artik,

N’olur ellerini bana.

Sensiz bir hayat,

Ölüm gibi geliyor bana.

Insanlardan uzak,

Sessiz,

Ve çaresizim.

Derdimi açtim sana.

Dinle artik,

N’olur hak ver bana.

Tarih Ve Saati: 29/05/2003	01:24', 'Sevgimi açtim sana, Uzat artik, N’olur ellerini bana. Sensiz bir hayat, Ölüm gibi geliyor bana. Insanlardan uzak, Sessiz, Ve çaresizim. Derd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/actim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmamış Bebeğe', 'dogmamis-bebege-selim-gul-ixa89', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üstad Abdurrahim Karakoç ve Prof.Dr. Seyit Mehmet Şen''e saygılarımla

Dünyaya gelmeden önce bir düşün

Eski dünya değil artık bu dünya bebek.

Bahar yaz geçti bu devir güzün

Bekle kışta geçsin öyle gel bebek.

Bahçeler ham meyvenin tasallutu altında

Gönüller kör şehvetin kurbanlığı yolunda

Sistemler soyanın sömürenin yanında

Adilce düzenimiz kurulsunda öyle gel.

Alem siyonistlerin kulu kölesi bugün

Sözler kalemşörlerin iyi silahı bugün

Soygunculuk yaşamanın kuralı bugün

Sabret her şey aslına rücu etsin öyle gel.

Kula köle nesiller hürriyet haram oldu

Bir kısım gözü dönmüş arza hükümran oldu

Vatandaşı üç buçuk soysuz yargılar oldu

Yasayı yargıçlara teslim edelimde gel

Terör esiyor bugün gündemin nevri döndü

Umutlar tükeniyor garibin mumu söndü

Namus ehlini yendi namussuzların fendi

Tasadan kurtuluşu sağlayalım öyle gel.

Enaniyet sarıyor ruhunu elalemin

Makam mevki araç değil amacıdır cümlenin

Ağlarken masum halkım yeri yoktur gülmenin

Masanın mahkumları gebersinde öyle gel.

Vatan, millet, şeref, şan edebiyatta kaldı

Para girdi gönüle haya sokakta kaldı

Üç beş kuruş aya çıktı kanaat yaya kaldı

Kasaların kilidini kıralımda öyle gel.

Bu fani dünyanın sonu yok sananların

Bir avuç toprak için mazlum ağlatanların.

Geberince gömsen toprak kokutanların

Arsa hastalığına derman bulalımda gel.

Keçiler kırıtmadan teke peşine gitmez.

Keçiye köle olmuş tekeden hayır gelmez

Akılları uçkurundan yukarı çıkmaz

Nisadan insanları ayıralım öyle gel.

Güloğluyum her daim sabrı telkin ederim

Selameti gördüm mü o yol üzre giderim

Orası bugünlerde buradan hayırlı derim.

Hele bekle ben sana gel diyeyim öyle gel.

Haziran 1997 Ankara', 'Üstad Abdurrahim Karakoç ve Prof.Dr. Seyit Mehmet Şen''e saygılarımla Dünyaya gelmeden önce bir düşün Eski dünya değil artık bu dünya bebek. ...', ARRAY['Türk Edebiyatı','Şiir','Selim Gül']::text[], 8.5, '{"poet":"Selim Gül","poet_slug":"selim-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/dogmamis-bebege-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine senin için dirilirim.', 'yine-senin-icin-dirilirim-muzaffer-alcinkaya-p9pe2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatta vereceğim son nefesim

Çölde esen rüzgar gibi ısıtmalı yüreğini

Dalına tutunan son yaprak gibi 

Ruhum sonbaharda kopsada

İlkbaharda yeniden yeşeren

Yaprak olurum yüreğinde

Yine sende can bulurum..

Yine senin için dirilirim. 

(03.01.2006)', 'Hayatta vereceğim son nefesim Çölde esen rüzgar gibi ısıtmalı yüreğini Dalına tutunan son yaprak gibi  Ruhum sonbaharda kopsada İlkbaharda y...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Alçınkaya']::text[], 8.5, '{"poet":"Muzaffer Alçınkaya","poet_slug":"muzaffer-alcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yine-senin-icin-dirilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adina Siirler Yazdim', 'adina-siirler-yazdim-mustafa-aslan-2-9l3yy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adina siirler yazdim,

Seni nasil sevdigimi anlattim,

Dinleyen olmasada,

Bilki askim ben yalniz sana yandim.

Adina siirler yazdim,

Her satirda senin için agladim,

Gören olmasada,

Bilki ben senin için agladim.

Adina siirler yazdim,

Bir gün de olsa senden ayri kaldim,

Derdime derman olmasalar da,

Bilki seni görmeye geldim.

Adina siirler yazdim,

Kalbime ismini,

Beynime resmini,

Yüregime sevgini,

Gönlüme de seni çizdim.

Bilen olmasa da,

Bilki seni seviyorum.

Adina siirler yazdim,

Yazdim da, derdimi bosalttim,

Insanlar dinlemese de,

Agaç oldu dert arkadasim,

Agaç beni anlamasa da,

Bilki gönlümün gülüsün,

Ömrümün günüsün,

Günümün de günesisin.

Sen benim için tek sin,

Sen sadece benim sin

Adina siirler yazdim,

Yazdim da, sana sevgimi böyle anlattim.

Tarih Ve Saati: 01/01/2005		22:56', 'Adina siirler yazdim, Seni nasil sevdigimi anlattim, Dinleyen olmasada, Bilki askim ben yalniz sana yandim. Adina siirler yazdim, Her satird...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adina-siirler-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırnaklarım', 'tirnaklarim-suheyl-turkoglu-nvie8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzuyorlar,

Hiç durmadılar.

Kestikçe tepelerinden,

Arsızlaştılar.

Sardılar

Elimi, ayağımı,

Yaşlandıkça

Zorlaştı kesmak,

Onlar büyüdükçe,

Hayatımı zorlaştırdılar.

Fayda aradım

Büyümelerinde,

Sulamadan,

Gübresiz,

Mikrop yuvası olup

Zarar veren,

Tırnaklarım,

Sizi nereye sığdırırım,

Bilemiyorum.', 'Uzuyorlar, Hiç durmadılar. Kestikçe tepelerinden, Arsızlaştılar. Sardılar Elimi, ayağımı, Yaşlandıkça Zorlaştı kesmak, Onlar büyüdükçe, Haya...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tirnaklarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Annem', 'affet-annem-mustafa-aslan-2-ntov5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için gizli gizli aglar,

Sensiz kalirim diye korkarim.

Degerini bilemedim,

Ben sana hayirli evlat olamadim,

Sen benim iyiligimi isterken,

Ben senin kalbini kirdim.

Bana gerçekleri söylediginde,

Kirildim,

Gerçekleri kabullenemedim.

Biliyorum annem,

Benim gidisim gidis degil,

Birgün yolda kalirim,

Ozaman anlarim,

Senin degerini.

Affet annem,

Sana yardimim olmadi,

Yari aç, yari tok gezdin,

Benim için agladin,

Ben orali bile olmadim.

Hatirlarmisin annem,

Okulu birakacagimi söyledigimde karsi çikmistin.

Ben seni dinlememistim,

Okula kayit dosyasini yirtmistim,

Sen sinirlenip,

Kafani duvardan duvara vurmustun,

Hasta halinle benim için aglamistin.

Ben unutamadim anne,

Aklima geldikçe çildirdim,

Hep agladim,

Ben kendimi affedemedin,

Sen,

Affet annem.

Tarih Ve Saati: 15/08/2005      04:47', 'Senin için gizli gizli aglar, Sensiz kalirim diye korkarim. Degerini bilemedim, Ben sana hayirli evlat olamadim, Sen benim iyiligimi isterke...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/affet-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmem Seni', 'affetmem-seni-mustafa-aslan-2-oel0s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece kokunu sürdüm,

Sessizce saçlarindan öptüm,

Yazdigin mesajlari okudum,

Issizlik kapiyi çaldi, açmaya korktum.

Nasilsa ayrilik bu askin sonu,

Kader ikimize çizmis bu yolu,

Yagmur damlalari arkadasim oldu,

Martilar sirdasim yoldasim oldu,

Dalgalar duygularim gibi isyan ediyordu.

Seninle bu aski yasamadik say,

Birlikte gülüp de aglamadik say,

Böylesi unutmak daha da kolay.

istemem söyleme bir tek kelime,

Degmesin artik hiç elin elime,

Sar yeni askini benim yerime,

Sen de eller gibi adimi unutmayi dene..

Böyle tek basima birakip gitme dedim,

Beni yalniz koyma sakin terk etme dedim,

Yalniz koyup beni bir yere gitme,

Seni ben kendime hep yar bilmistim,

Bu dünyaya senin için gelmistim.

Yasasam ne farki var, ya da ölmüsüm.

Eline uzanip tutmak istedim,

Dudagindan birkez öpmek istedim,

Gittigin yerlere gelmek istedim.

inan ki affetmem affetmem seni,

istiyorsan çek git hadi serbestsin,

Bensiz diliyorum bir gün görmezsin,

Öldügümde mezarima bile gelmezsin.

Gidersen affetmem, affetmem seni,

inan ki affetmem, affetmem seni,

Ölsem de affetmem, affetmem seni...

Tarih Ve Saati: 11/12/2004		00:54', 'Bu gece kokunu sürdüm, Sessizce saçlarindan öptüm, Yazdigin mesajlari okudum, Issizlik kapiyi çaldi, açmaya korktum. Nasilsa ayrilik bu aski...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/affetmem-seni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affettim Seni', 'affettim-seni-mustafa-aslan-2-ef81u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana çok çektirdin,

Ama birakamam seni,

N''olursa olsun,

Affettim seni.

Benden uzaklasiyorsun,

Sen vatan ellerde,

Ben gurbet bataginda,

Biliyorum sende olamazsin bensiz,

Gel iste affettim seni.

Hala agliyorum,

Susmaz oldu gözüm.

Yüregim kaniyor,

Susmaz oldu özüm.

Yalniz kaldim,

Aci çektiriyor sözüm.

Gel artik,

Affettim seni.

Senin yerini kimse dolduramaz,

Bu yalniz yürek varya,

Inanmazsin sensiz olamaz.

Gel artik birtanem,

Affettim seni.

Tarih Ve Saati: 19/07/2005     14:34', 'Bana çok çektirdin, Ama birakamam seni, N''olursa olsun, Affettim seni. Benden uzaklasiyorsun, Sen vatan ellerde, Ben gurbet bataginda, Biliy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/affettim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agaç Ve Ben', 'agac-ve-ben-mustafa-aslan-2-15m5z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Agaca sordum sevdigin varmidir diye? 

Bana cevabi çok güæel oldu; 

Benim sevgililerim dallarim,

Ayak altimda duran çimenlerdir dedi.

Ayni soruyu agaçta bana sordu.

Ben birtürlü bir cevap bulamiyordum.

Belkide dogruyu söylemekten korkuyordum.

Çünkü alay etmesinden korkuyordum,

Ama dayanamayip gerçegi söyledim.

Dedim sevgilim çok oldu,

Ama senin dallarin kadar bana bagli olmadilar.

Baska bir soru sordum konuyu degistirmek için! 

Sordum; Sen hiç sarki söylermisin? 

Cevap olarak hemen; 

Rüzgarla benim yapraklarim birlestimi,

Güzel bir ses çikar ve o ses benim en sevdigim sarkidir.

Ve o sarkiya dallarim ve bende dans ederek eslik ederiz.

Ayni soruyu tekrar bana sordu.

Ya sen hiç sarki söylermisin? 

Cevap olarak sunu söyledim.

Ben sarkiyi yalniz kaldigimda,

Ayrildigimda veya terk edildigimde,

Bagirarak söylerim.

Anlayacagin benim söyleme nedenim baska,

Derdimi sarkilarla paylasiyorum.

AGAÇ SASIRARAK: Ben senden dahada mutluymusum,

Sen dünyayi gezdigin halde umutsuzsun.

Mutluluk nedir unutmussun.

Arkadaslar anlayacaginiz,

Ben bir agaç kadar mutlu, umutlu, ümitli olamadim.

Kisaca bir agaç kadar olamadim.

Tarih Ve Saati: 09/07/2004	00:23', 'Agaca sordum sevdigin varmidir diye?  Bana cevabi çok güæel oldu;  Benim sevgililerim dallarim, Ayak altimda duran çimenlerdir dedi. Ayni so...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/agac-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agla Yüregin Bosalsin', 'agla-yuregin-bosalsin-mustafa-aslan-2-69r28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Agla yüregin bosalsin,

Agla yagmurlar eslik etsin.

Akan göz yaslarin,

Sürükler seni kiyilara vurur seni.

Unutma adi konmus ayriligin,

Çok acimasizmis.

Bunu çok iyi biliyorum.

Esen rüzgarlar,

Bir siir olsun dudaklarinda,

Ismini an sarkilarda.

Biliyorum,

Tozlandi hayalin,

Bir mutlu yuva kurup,

Çoluk cocua karismak.

Hepsi bir hayaldi,

Simdi toz pempe hayal oldu.

Bosver diyecem kafana takma,

Kendini yalan sevgilere satma,

Sevgine yalan sözleri katma,

Umutlarla yasa,

Dert gelmez basa.

Tarih Ve Saati: 10/07/2005       15:23', 'Agla yüregin bosalsin, Agla yagmurlar eslik etsin. Akan göz yaslarin, Sürükler seni kiyilara vurur seni. Unutma adi konmus ayriligin, Çok ac...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agla-yuregin-bosalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik Hali', 'caresizlik-hali-bilge-karamehmet-gh1bq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine günlerdir hüzün..

Türk Dili''ndeki durumlara

yeni bir durum ekledim

bu gece...

''çaresizlik hali''...

Yönelme halimi,rafa kaldırdım

epey önce.....', 'Yine günlerdir hüzün.. Türk Dili''ndeki durumlara yeni bir durum ekledim bu gece... ''çaresizlik hali''... Yönelme halimi,rafa kaldırdım epey ö...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/caresizlik-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamak', 'aglamak-mustafa-aslan-2-w5yek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aglamak nedir bilirmisiniz,

Aglamak ayriliktir,

Aglamak sevmektir,

Aglamak kaderdir,

Aglamak bazende mutluluk,

Bazende gülmektir.

Ben hergün agliyorum,

Ne için,

Neden,

Kimin için,

Ne için,

Ben bile bilmiyorum.

Yoksa mutluluk mu beni aglatan,

Aglatipta yüregimi kanatan.

Sanmiyorum,

Mutluluk nedir bilmiyorumki.

Hayat bir sinav gibi,

Mutlaka kazanmaliyim diyorum,

Her yanlista bir dogru gidiyor,

Mutlaka kazanmaliyim.

Ben sanmistimki,

Yanimda olacak,

Evimin kenarinda beni bekleyecek,

Mutlulukla karsilayacak,

Yanagima bir öpücük verecek.

Simdi yavas yavas anliyorumki,

Sinavi kaybetmisim,

Agliyorum,

Ve nedeni ögreniyorum,

Ben terk edilmistim.

Hayat diplomasini alamadim,

Sevilmeyi hakketmemisim.

Ben onun için agliyormusum,

Aglamak buymus desene.

Tarih Ve Saati: 26/12/2004		15:01', 'Aglamak nedir bilirmisiniz, Aglamak ayriliktir, Aglamak sevmektir, Aglamak kaderdir, Aglamak bazende mutluluk, Bazende gülmektir. Ben hergün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/aglamak-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pera''da bir Dilek', 'pera-da-bir-dilek-bilge-karamehmet-zrd59', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hafif sesi gelir yağmurun gece..

Tüm yorgunluğumu aldı götürdü

bu gece...

Burnumda sıcak hayta kokusu,

Yağmur yağarsa,

rüzgar diner bi gece....', 'Hafif sesi gelir yağmurun gece.. Tüm yorgunluğumu aldı götürdü bu gece... Burnumda sıcak hayta kokusu, Yağmur yağarsa, rüzgar diner bi gece....', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/pera-da-bir-dilek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agladim Sabaha Kadar', 'agladim-sabaha-kadar-mustafa-aslan-2-pfd4r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine bir ayrilik sözü,

Çaresizlik,

Adim atmis yüregime,

Kimseye dinletemiyorum kendimi,

Hep aci çekiyorum,

Hep agliyorum,

Sen yanimda yoksun,

Ne yaptigimi,

Nasil yasadigimi bilmiyorsun,

Bilmezsin neler çekiyorum geceleri,

Ben yine herzamanki gibi,

Agladim sabaha kadar.

Seni benden almak isterler neden? 

Seven yürek çokmu zalimdir.

Koparmak isterler açan güllerimi neden? 

Sevda güllleri çokmu acimasiz.

Yikmak isterler hayellerimi neden? 

Çokmu görürler mutlulugu bize.

Bu hayat böylemi bitecek söyle neden? 

Bu hayat çokmu kalles.

Aglarim sabaha kadar neden? 

Bu sevgi böyle bitmez.

Yikamasinlar sevgimizi,

Sen karsi çik bunlara,

Söz anlar,

Beni dinlemezler,

Sen yardimci ol bana,

Söyle nasil seviyoruz birbirimizi,

Bu hayat bizsiz yasanmaz.

Askim ben yine agladim sabaha kadar,

Uyumadim,

Sabahlari yasadim,

Geceleri öldüm, hep siir yazdim,

Siirlerle anlastim,

Ama derdimi dinlemez oldu siirler,

Agir geldi tasiyamaz sayfalar,

Mürekkebi yetmez kalemimin biter,

Uyurum en fazla 10 dakika,

Hemen uyanirim acilar içinde,

Terlemisim,

Kabuslar hep ayni,

Seni benden aliyorlar,

Ben ne yapiyorum,

Hiç birsey,

Yapacak birseyim yok,

Çaresizim,

Agladim sabaha kadar! ! ! ...

Tarih Ve Saati: 01/08/2005	03:29', 'Yine bir ayrilik sözü, Çaresizlik, Adim atmis yüregime, Kimseye dinletemiyorum kendimi, Hep aci çekiyorum, Hep agliyorum, Sen yanimda yoksun...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/agladim-sabaha-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglama Dersin', 'aglama-dersin-mustafa-aslan-2-9muj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aglama dersin simdi sen bana,

Soruyorum sana,

Sevdigini yavas yavas kaybediyorsun,

Aglamadan durabilirsin,

Sen ona gönlünü vermissin,

Onsuz olabilirmisin.

Bir kez sözünü dinlemesede.

Onu sevmekten vazgeçermisin.

Tarih Ve Saati: 16/07/2005      14:04', 'Aglama dersin simdi sen bana, Soruyorum sana, Sevdigini yavas yavas kaybediyorsun, Aglamadan durabilirsin, Sen ona gönlünü vermissin, Onsuz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglama-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamayacagim', 'aglamayacagim-mustafa-aslan-2-yuf91', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artik aglamayacagim,

Bende sizler gibi gülecegim,

Artik hayat umrumda degil,

Sevdiklerim zaten beni sevmiyorlar.

Aglamaktan biktim, usandim

Gözlerimden kan gelmesinden yildim,

Yüregimin aglamasina dayanamaz oldum,

Simdi bende aglamayacagim.

Birgün gelir, elbet bende gülerim,

Birgün gelir, elbet sende seversin,

Birgün gelir, elbet sende aglarsin,

Birgün gelir, elbet sende aglamaktan bikarsin,

Birgün gelir, elbet sende benim gibi olursun,

Bende aglamayacagim dersin.

Bak bir yildizlara, nasilda parliyorlar

Eskiden bende onlar gibiydim,

Sevdikten sonra hayatim degisti,

Aglamaktan tükeniyordu ömrüm.

Biraktilar ben aci çekeyim,

Bu sevdamin yolunda,

Ama artik bende biktim,

Artik AGLAMAYACAGIM

Seni sevdimde hayatima anlam geldi.

Tarih Ve Saati: 31/10/2004	11:46', 'Artik aglamayacagim, Bende sizler gibi gülecegim, Artik hayat umrumda degil, Sevdiklerim zaten beni sevmiyorlar. Aglamaktan biktim, usandim ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglamayacagim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-i-smail-hakki-i-zmir-wectk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bİr derdim var

Dertler arasında 

Kaybolmuş bir dert

Bir sevgim var

sevdalar içinde

Kaybolmuş sevda

Bir büyüğüm var

Aşktan büyük

Aşkımız var', 'Bİr derdim var Dertler arasında  Kaybolmuş bir dert Bir sevgim var sevdalar içinde Kaybolmuş sevda Bir büyüğüm var Aşktan büyük Aşkımız var...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı İzmir']::text[], 8.5, '{"poet":"İsmail Hakkı İzmir","poet_slug":"i-smail-hakki-i-zmir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenik Yıl', 'yenik-yil-gultekin-mustafa-ot8fz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kopyala yapıştır günler hep

takvime eziyet

oysa ne bakire umutlarla başlamıştık

bakire bir yıla bakire bir takvimle

bir yıl geçmiş 

bir yıl ömrümüzün ırzına geçmiştir

hep boşa geçmiştir

en başarılısı da olsa her özgeçmiş

olursa aksini iddia eden

hep neticeye dikkat çekmişimdir

vurup kapıyı çıkıcam tam bir ocakta

takvimi tınlamadan

lakin kapıya eziyet koluna günah

yeni bir yıllar

sadece sizlere kutlu olsun', 'kopyala yapıştır günler hep takvime eziyet oysa ne bakire umutlarla başlamıştık bakire bir yıla bakire bir takvimle bir yıl geçmiş  bir yıl ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yenik-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kaldırım Kurgusu', 'bir-kaldirim-kurgusu-gultekin-mustafa-4n4t7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine bir dönüşteydi eve

hava karanlık ve ayaz

bedeni otobüsten indirdim 

ruhu bagajdan

benim için yapılan kaldırıma 

kumanda omurilikte

attım kendimi

zira o herkesten daha iyi biliyor

evimin yolunu

genç bir kız belirdi önümde 

sarı siyah bir gölge gibi

beni fark etti tedirginleşti

kaldırım uzun 

hava karanlık ve ayaz

adımlarımız düzene girdi

aradaki mesafe uygun

o yürüyor ben yürüyordum

hava karanlık ve ayazdı

saat gecenin çok geçi

ben karanlık gölgem cilalıydı

o canını düşünüyor ya elbet

ya da ırzını

ben öyküyü düşünüyorum

hem de ırzını

yavaşlayınca geçip gideyim diye kendisini

ben de yavaşladım korumak için mesafeyi

kaldırım uzun

hava karanlık ve ayaz

saat gecenin çok geçi

ben karanlık gölgem cilalıydı

tek bir dükkan

tek bir insan yoktu

cesaretimi topladım birden

hızlandırdım adımlarımı

hava karanlık ve ayaz

daha sessiz daha hızlıydım

saat gecenin çok geçi

sokak lambasının altında gölgem belirdi

gölgemi gördü

heyecanlandı

kaldırım uzun

arkasına baktı bende ona baktım

çantasını önüne aldı

tek bir dükkan

tek bir insan yoktu

tedirginliğini sezdirmemeye çalıştı

etrafı detaylı süzdüm

yaklaştım, yaklaştım

yanına kadar geldim

hava karanlık ve ayaz

geçip gideceğimi zannetti

hızlı bir hamle yaptım

sol elimi hızla savurup ağzını kapadım

sağ elimle sol elini sıkıca kavradım

hava karanlık ve ayaz

sağ eliyle düşmemek için

paltoma tutundu

kaldırımın kenarına doğru götürdüm 

çırpınan bedenini

yasladım çimenlerin arasına

hava karanlık ve ayaz

çimenlerse ıslak

debelenmesine aldırmadım

alacağımı aldım

onun için de farklı bir tattı eminim

acaba bu öyküyü okusaydı güler miydi

ben de öyle düşünmüştüm der miydi

yoksa beni sapıklıkla mı suçlardı

düşünmekle sapıklık olmuyor mu

söyleyince mi suçlanıyoruz

her insanda var bu duygu

kandırma kendini derdim o zaman

neyse ki alt geçidin lambalarını tamir etmişlerdi de

arkamda beliren gölgelerden 

korkmama gerek kalmadı', 'yine bir dönüşteydi eve hava karanlık ve ayaz bedeni otobüsten indirdim  ruhu bagajdan benim için yapılan kaldırıma  kumanda omurilikte attı...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/bir-kaldirim-kurgusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim?', 'kim-bilge-karamehmet-jxufx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İmrenirim bir baba

kızının elinden tuttuğu vakit...

Papucum delindi baba,

kar yağdı tenime..

paran ısıtmaz tenimi, 

yüreğinle sar yeter..

Karnım acıktı babam,

doyurmaz köşedeki bakkal...

Elin saçıma değdiği an

Günün gecemi katleder....', 'İmrenirim bir baba kızının elinden tuttuğu vakit... Papucum delindi baba, kar yağdı tenime.. paran ısıtmaz tenimi,  yüreğinle sar yeter.. Ka...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kim-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamak Için', 'aglamak-icin-mustafa-aslan-2-9hgii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aglamak için,

Sadece aynaya bakmam yeterli,

Baktigim an,

Çirkin bir surat,

Acilarla genç yasta yaslanmis,

Derileri büzüsmüs bir el,

Kisaca yalnizligi görüyorum,

Iste o an basliyorum aglamaya.

Aglamak için,

Sadece seni düsünmem yeterli,

Düsündügüm an,

Yasanmis günler,

Mutlu ve mutsuz anilar,

En önemliside,

Bana bakisin,

Bunlar aklima geldiginde,

Iste o an basliyorum aglamaya.

Aglamak için,

Sadece yasadiklarimi yasamam yeterli,

Yasadigim an,

Geçmiste kalan maziler,

Yalnizlik,

Hergün göz yasi,

Gizli gizli aglamalar,

Dostsuz ve yolsuz,

Mutsuz ve umutsuz,

Sevgiden mahrum,

Sevda atesi,

Sevmek,

Severken bile terk edilmek,

Bunlari tekrar yasadigimda,

Iste o an basliyorum aglamaya.

Tarih Ve Saati: 16/05/2005	12:08', 'Aglamak için, Sadece aynaya bakmam yeterli, Baktigim an, Çirkin bir surat, Acilarla genç yasta yaslanmis, Derileri büzüsmüs bir el, Kisaca y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aglamak-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamazsam Uyuyamam', 'aglamazsam-uyuyamam-mustafa-aslan-2-his46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok seyim var sizlere anlatacak

Varmi kulak veripte dinleyecek

Sonuna kadar beni izleyecek

Varmi benimle anlattiklarimi yasayacak

Sigarasiz sabah olmuyor

Gözlerim yas yerine 

Kan agliyor

Nedendir bunu kimse bilmiyor

Aglarim her gece

Sevilmedigim için

Aglarim her gece

Annemi kaybetme korkusu oldugu için

Yillardir ask ugruna

Ömrümü kaybettim

Ben simdi her gece

Aglamazsam uyuyamam

Kaybettim geçen yillarimi

Bulamadim hayatin anlamini

Sevilmedim yalandi sevdiklerim

Özledim, özlemimle agladim

Artik yalnizim

Gözyaslarini kendime dost bildim

Simdi her gece

Içimi çekerek aglamazsam

UYUYAMAM! 

Tarih Ve Saati: 22/10/2004	23:37', 'Çok seyim var sizlere anlatacak Varmi kulak veripte dinleyecek Sonuna kadar beni izleyecek Varmi benimle anlattiklarimi yasayacak Sigarasiz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aglamazsam-uyuyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglatma Beni Yeter', 'aglatma-beni-yeter-mustafa-aslan-2-qeglm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aglatma beni yeter,

Bu göz yaslari en sonunda biter,

Sevgi dedigin sey nedir ki? 

Kisa zamanda nefrete döner,

Ben senden nefret edemem deme,

Gam yükünü sende yeme.

Aglatma beni yeter,

Bana verdigin acilar,

Benimle ayni yol üstünde gider,

Her salise karsima çikar,

Sen bilemezsin beni çok sikar,

Tüm hayallerimi yikar.

Aglatma beni yeter,

Yeter,

Yeter,

Benim bu sevgim varya,

Nefretten,

Ölümden beter.

Tarih Ve Saati: 19/07/2005     01:09', 'Aglatma beni yeter, Bu göz yaslari en sonunda biter, Sevgi dedigin sey nedir ki?  Kisa zamanda nefrete döner, Ben senden nefret edemem deme,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aglatma-beni-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglayacaksin', 'aglayacaksin-mustafa-aslan-2-x1xh6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni birakip gittin,

Aglamaya mahkum ettin,

Acilari bana biraktin,

Gülüp geçtin.

Ben aglarken,

Sen güldün.

Beni mezara gömdün,

Yasadiklarimi hep gördün,

Hep dalga geçtin,

Ben aci çekerken,

Sen beni izledin,

Ben yorgun düserken,

Sen kosmaya basladin,

Kaçtin benden,

Uzaklara,

Seni bulamayim diye,

Saklandin,

Yaban ellere,

Bana çok çektirdin,

Seni hep sevdim,

Daima da sevecegim,

Ama bilki,

Bana yasattiklarin,

Bana çektirdiklerin,

Yorgun düstügümde bana vurusun,

Ben seni severken,

Benden nefret edisin,

Aklina geldikçe,

Duramayacaksin,

Aci çekeceksin,

Artik ben gülerken,

Sen kana kana,

AGLAYACAKSIN! 

Tarih Ve Saati: 16/05/2005	14:43', 'Beni birakip gittin, Aglamaya mahkum ettin, Acilari bana biraktin, Gülüp geçtin. Ben aglarken, Sen güldün. Beni mezara gömdün, Yasadiklarimi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aglayacaksin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-suheyl-turkoglu-eps91', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudaklarına

Bakıp iç çekmek,

Sevdayı öpmek,

Çok mu güzelim.

Aşkıma ateş,

Yandı gönlümde,

Bana merhametin,

Yok mu güzelim.

İçime işledi,

Sevda yelleri,

Aşkına mahkum,

Oldum güzelim.', 'Dudaklarına Bakıp iç çekmek, Sevdayı öpmek, Çok mu güzelim. Aşkıma ateş, Yandı gönlümde, Bana merhametin, Yok mu güzelim. İçime işledi, Sevd...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzelim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglayan Rüzgar', 'aglayan-ruzgar-mustafa-aslan-2-cj6nh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar bana benzer,

Elden ele eser,

Bazen firtina olur,

Bazen serinletici hava,

Bazen barajlar yikar,

Bazen agaçlarla konusur,

Eserken sarki söyler,

Büyük bir ugultuyla gelen rüzgar,

Acilarini bildiriyor,

Herkezin bilmesini istiyor,

Sadece aci çeken insanlar degilmis.

Ben çok iyi anladimki,

Rüzgar benim can dostum.

Her gelen rüzgarla bende agliyorum,

Bazen mutlu oluyorum,

Bazen mutsuzlukla bogusuyorum.

Bazen insanlara gülerken,

Bazen saldiriyorum,

Birde bakiyorumki,

Ben agliyorum,

Rüzgar agliyor.

Rüzgar aglarken, ben,

Ben aglarken, rüzgar,

Birbirimize eslik ediyoruz.

Agla rüzgar agla,

Artik dayanamiyorum,

Bende aglayacagim.

Tarih Ve Saati: 23/05/2005	22:24', 'Rüzgar bana benzer, Elden ele eser, Bazen firtina olur, Bazen serinletici hava, Bazen barajlar yikar, Bazen agaçlarla konusur, Eserken sarki...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aglayan-ruzgar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agliyor Artik Gözlerim Sensiz', 'agliyor-artik-gozlerim-sensiz-mustafa-aslan-2-p2tls', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Agliyor artik gözlerim sensiz,

Gülmek bilmiyor yüzüm.

Sensizlik çok zor geliyor bana,

Ne olur beni anlasana.

Kahrolsun böyle yasam,

Kalktim yürüdüm,

Bir kere degil,

Bin kere öldüm.

Her baktigim yerde seni gördüm,

Seni ben kalbime gömdüm.

Agliyorum, gözümde bir damla kan,

Birakti gitti beni, kalbimde yatan.

Seviyordum onu delicesine,

Artik sensiz anlamsizim.

Içim yanar, dayanamiyorum içim sizim sizim,

Artik simdi sensiz,

Gecelerimle basbasa,

Dünya çok sessiz.

Agliyor gözlerim artik sensiz,

Simdi sen ne yapiyorsun acaba, bensiz.

Ölü veya diri, fark etmiyor artik,

Ben ne de olsa yasayan bir ölü oldum.

Tarih Ve Saati: 11/07/2004	07:35', 'Agliyor artik gözlerim sensiz, Gülmek bilmiyor yüzüm. Sensizlik çok zor geliyor bana, Ne olur beni anlasana. Kahrolsun böyle yasam, Kalktim ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agliyor-artik-gozlerim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglayan Umutlar', 'aglayan-umutlar-mustafa-aslan-2-dsj1h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artik aglar, susmaz umutlarimiz,

Gülmekten uzak durur,

Mutlulugu unutur,

Bizim garip umutlarimiz.

Tükenir ve hep biter,

Aci çeker,

Cani yanar,

Ama vazgeçmez bu umutlar.

Seni alsalarda,

Umutlar tükenir,

Ama tükendikçe yeni umutlar dogar,

Sikilir hep aglamaktan,

Mutluluk diler allahtan,

Susmaz hiç,

Aglayan umutlar.

Umutlar aglasada,

Ümitler güler,

Her seferinde,

Seninde gönlünü çeler,

Zaman bitmez,

Kiyamet kopmazsa,

Bilki bu umutlar bitmez.

Bu aglayan umutlar,

Senin için agliyorlar,

Sensizligin acisi çekselerde,

Hiç yilmiyorlar,

Böyle bir günde,

Hep seni ariyorlar,

Inaniyorlar ki,

Seni bulacak,

Ve birdaha kaybetmeyecekler.

Tarih Ve Saati: 05/03/2005	20:11', 'Artik aglar, susmaz umutlarimiz, Gülmekten uzak durur, Mutlulugu unutur, Bizim garip umutlarimiz. Tükenir ve hep biter, Aci çeker, Cani yana...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/aglayan-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım Ben Seni', 'anlayamadim-ben-seni-durdane-demirkoparan-ncf4y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen nasıl sevdin sevdiğim

Nasıl seviyorsun

Ben anlamıyorum

Göremiyorum gözlerinde bir ışık

Göremiyorum küçücük bir sevda

Benim içim yanıyor

Sana ne oluyor

Gözyaşlarım döndü sele

Ben ağlıyorum

Bütün gece, bütün gün

Sen nasılsın

Biliyor musun yandığımı

İçini titretiyor mu acım

Görüyor musun sevdiğimi

Ve içimde çakan şimşekler

Yüreğimde kopan fırtınalar

Sızlatıyor mu yüreğini

Yakıyor mu seninde içini

Bu sevda beni öldürüyor

Seviyorum diyorum

Duyuyor musun

Yoksa kapattın mı sevdamın haykırışlarına

Yüreğin gibi kulaklarını da

Ve ben bitiyorum bu sevdadan

İçten içe eriyorum 

Kimse bilmez neler yaşıyorum

Her gün yeni bir umutla uyanmaktan

Her gün, bir gün anlayacak 

Ve bir gün dönecek diye beklemekten

Karar ver artık

Ya erkek gibi mertçe

Yada nankör gibi 

Karar ver

Ya sev ölümüne

Yada çek git vur yeniden

Haksızın haklıya yaptığı zulüm gibi

Vur beni

O yere göğe sığdıramadığım

Sen, canım dediğim canımdan üstün saydığım

Saçının teline kıyamadığım

Ya sahip ol sevdamıza

Yada vur beni yeniden

Vur alıştım senden gelen acıya

Yüreğim katmer katmer acı doldu

Ben ki ömürlük sevdim seni

Dayanırım katlanırım

Severim yine seni

Sen beni anlarsın 

Sevdiğimi bilirsin

Bende bileyim

Ya git adam gibi

Yada anlat kendini bileyim sevdiğini

Anlayayım seni

Canım, canımdan üstün saydığım…', 'Sen nasıl sevdin sevdiğim Nasıl seviyorsun Ben anlamıyorum Göremiyorum gözlerinde bir ışık Göremiyorum küçücük bir sevda Benim içim yanıyor ...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/anlayamadim-ben-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ah', 'ah-ah-mustafa-aslan-2-0j6zm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah ah diye diye geldim bu yasima,

Seve seve yasadim hayatimi,

Ama hayatimda hiç sevilmedim.

Hep aldandim insanlara,

Hep terk ettiler beni,

Bir baskasi için.

Tarih Ve Saati: 09/11/2003	13:34', 'Ah ah diye diye geldim bu yasima, Seve seve yasadim hayatimi, Ama hayatimda hiç sevilmedim. Hep aldandim insanlara, Hep terk ettiler beni, B...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ah-ah-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agliyorum', 'agliyorum-mustafa-aslan-2-eeweu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Agliyorum hergün zaman geçmek bilmez,

Aglayan gözlerim neden hiç gülmez,

Anlatamaz oldum derdimi,

Sevemez oldum yasadigim günleri.

Aglamaktan biktim, kurtaran yok,

Bir kere olsun benimle gülen yok,

Dalga geçip aglatanlar çok,

Neden benimde bir sevdigim yok.

Düsüncelerim boguluyor,

Sevgim yokoluyor,

Derdim gün geçtikçe cogaliyor,

Annem beni kurtaran olmuyor.

Felek vurdu kalbime,

Aldi koydu beni gurbet ellere,

Korkarmiyim artik ölümden,

Bilemezler korkarim gülmekten.

Zaman gelir, güller solar,

Zaman gelir, hayat biter,

Zaman gelir, uçuruma iter,

Zaman gelir, ve habersiz gider.

Gençligimi yasayamadim,

Sevdalara doyamadim,

Vuruldum artik yarali kalbimden,

Hergün kan akar gözlerimden.

Tarih Ve Saati: 16/10/2004	19:18', 'Agliyorum hergün zaman geçmek bilmez, Aglayan gözlerim neden hiç gülmez, Anlatamaz oldum derdimi, Sevemez oldum yasadigim günleri. Aglamakta...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agliyorum-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agliyorum 2', 'agliyorum-2-mustafa-aslan-2-etodp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun zaman geçmisti,

Aglamiyordum,

Seni tanidiktan sonra,

Seninle bir hayata basladiktan sonra,

Ilk defa güldüm,

Ilk defa allahimdan bizi ayirmamasini istedim,

Olmadi,

Olamadi,

Ama yinede ayirmasin ölesen kadar.

Simdi agliyorum,

Sensizligin göz yaslari akiyor,

Kalbim bile kan agliyor,

Çok korkuyordum seni kaybetmekten,

Simdi seni kaybettim,

Ama tamamen degil,

Ben seni kalbime gömdüm,

Her yere baktigimda seni görüyorum,

Sen olmasan bile,

Hayalin yeter.

Aglamaktan biktim artik,

Bende gülmek istiyorum,

Agliyorum susmak bilmez gözlerim.

Seni kiskandim,

Çünkü seni seviyordum.

Açik saçik giyinme dedim,

Çünkü baska gözler baksin istemiyordum.

Günahmi seni sevmek,

Günahmi bana gülmek,

Diliyelim allahimiz bizi hiç ayirmasin,

Vücutlarimiz ayrilsa bile,

Ruhlarimiz beraber kalsin.

Dünya simdi zindan oldu bana,

Ne sen bensiz,

Ne ben sensiz,

Yasarmi acaba su sevgimiz.

Tairh Ve Saati: 02/03/2005	21:36', 'Uzun zaman geçmisti, Aglamiyordum, Seni tanidiktan sonra, Seninle bir hayata basladiktan sonra, Ilk defa güldüm, Ilk defa allahimdan bizi ay...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/agliyorum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'palavra', 'palavra-mustafa-aslan-2-nc7aa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'N''olurdu sevmeseydim,

Senin su halini görmeseydim,

Ariyor seni sevdam hergün,

Askindan ölürüm elbet birgün.

Bir gün olur huzurun kaçar,

Insan dedigin NAMUS için yasar,

Sevdan bedenimi asar,

Denizler askimdan tasar.

Bir kiz ile adim atmak isterdim hayata,

Degismezdim onu dünyaya,

Kahr ederim su mutsuzluga,

Kafami vururum duvarlara.

Ask atesinde sende yanarsin,

Neden su insanlara kanarsin,

Düsünürsen geçmisi sende aglarsin,

Verdigim gül, gül gibi sende solarsin.

Özledim o tatli mahsum yüzünü,

Isterim mutlu mutlu gülüsünü,

Unutamam bensiz gidisini,

Haykiririm kalbine sevdanin sesini.

Hiç dogru degilsin güzelim,

Gel el ele mutluluga gidelim,

Su nalet sehri terk edelim,

Ölene dek birbirimizi sevelim.

Tarih Ve Saati: 29/05/2005    00:11', 'N''olurdu sevmeseydim, Senin su halini görmeseydim, Ariyor seni sevdam hergün, Askindan ölürüm elbet birgün. Bir gün olur huzurun kaçar, Insa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/palavra-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /1', 'palavra-1-mustafa-aslan-2-pgmjc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben dogdum ama yasamiyorum,

Bir kiz sevdim,

Yok yere küstüm,

Bazen onu kirdim,

Bazen sözlerine aldandim,

Ama ondan ayrilamadim,

Ben dogdum ama yasamiyordum,

Belkide onun sayesinde yasama döndüm.

Onunla güldüm,

Onun için agladim,

Yillarca mutlulugu aradim,

Mutlulugu onda buldum,

Ben onu sevdim,

Sevmez olaydim,

Onsuz olamiyorum.

Ben kendimi onda kaybettim,

Hala bulamadim.

Tarih Ve Saati: 13/08/2005     02:00', 'Ben dogdum ama yasamiyorum, Bir kiz sevdim, Yok yere küstüm, Bazen onu kirdim, Bazen sözlerine aldandim, Ama ondan ayrilamadim, Ben dogdum a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/palavra--1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /2', 'palavra-2-mustafa-aslan-2-yyxy0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle basladim yasama,

Seninle basladim sevmeye,

Seninle basladim gülmeye,

Seninle basladim gerçekleri ögrenmeye,

Senin basladim, 

Seninle bitiririm bu sevdayi.

Kiz dinle beni,

Bu siirimde sana,

Seninle degistim,

Seninle ögrendim sevmeyi,

Sevipte, sevilmeyi.

Birak bu sevda yasasin,

Birakta DeRTLi-SaiR mutlu olsun,

DeRTLi-SaiR yalniz seni sever,

Yalniz seninle cennet bahçelerinde gezer.

Bilesinki DeRTLi-SaiR hep aglar,

Yalniz seninle güler.

Tarih Ve Saati: 13/08/2005     02:18', 'Seninle basladim yasama, Seninle basladim sevmeye, Seninle basladim gülmeye, Seninle basladim gerçekleri ögrenmeye, Senin basladim,  Seninle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/palavra--2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak etmiyor', 'hak-etmiyor-husamettin-guven-e1692', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'temizdeyip nikah attim

namus deyip senle yattim

sever diye cocuk yaptim

temizligi hak etmiyor

el aleme laf soz oldun

cocuklara rezil oldun

mutluluga mahrum kaldin

mutlulugu hak etmiyor

bak cocuklar senin arar

annem diye sana yanar

sen onlari hep yaralar 

cocuklari hak etmiyor

kafa tasi gozu sismis

tek hayali ozgurlukmus

o yuvayi gozden silmis

ozgurlugu hak etmiyor

hiyikliyor ucacakmis

daglarada kacacakmis

yavrulari atacakmis

yavrulari hak etmiyor', 'temizdeyip nikah attim namus deyip senle yattim sever diye cocuk yaptim temizligi hak etmiyor el aleme laf soz oldun cocuklara rezil oldun m...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hak-etmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gibi', 'sen-gibi-durdane-demirkoparan-lxeqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sigara daha yakıyorum

Sensiz yaşadığım uzun günlerin akşamında

Çekiyorum içime ağır ağır

Sanki sen gibi 

Acımı hafifletir sanıyorum

Kuru bir dumanı

Biliyorum her gün biraz daha yaklaştırıyor beni sona

Zaten bile bile yapıyorum

İçindeki zehire sen diyorum

Olacaksa senden olsun

Sen bitir beni yavaş yavaş

Hep yaptığın gibi

Kuralı bozmuyorum

Zaten ya sevinçten ya kederden içerim

Ama hep içecek bir neden bulurum

Bilirim ki senden artık vefa yok

Bilirim hayır yok

Gelmezsin 

Terk eylemişsin bu kalbi

Bu aşkı

Ama sigaram o beni bırakmaz sen gibi

İhtiyacım olduğunda yanımdadır hep

Pardon

Unutmuşum

Sigaram da param olduğu sürece yanımda..

Yinede vazgeçemiyorum

Ne senden ne de sigaramdan…', 'Bir sigara daha yakıyorum Sensiz yaşadığım uzun günlerin akşamında Çekiyorum içime ağır ağır Sanki sen gibi  Acımı hafifletir sanıyorum Kuru...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-gibi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mirac-durmus-9ahxh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralı bir yürek bu

Sana aşık olan

Senin yokluğunda kanayan

Bir yürek bu...

Sensizlikte karanlığa mahkum olan

Gün ışığına hasret kalan

Uğrunda harcanan

Bir yürek bu...

Sensizlikte sızlayan bir yürek bu

Adını boşluğa haykıran

Sonsuzlukta kaybolan

Bir yürek bu...

Sana hasret bir yürek bu

Kadere inat Sana tapan

Yokluğunla savaşan

Seni,sensizlikte de yaşatan

Bir yürek... Bu...', 'Yaralı bir yürek bu Sana aşık olan Senin yokluğunda kanayan Bir yürek bu... Sensizlikte karanlığa mahkum olan Gün ışığına hasret kalan Uğrun...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-317-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O o', 'o-o-serkan-cekirge-5h9vc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen diye uyandım gün doğumlarında.

burası neresi! sen kimsin diyerek.

saçları,dudakları,elleri sadece sana benzeyen.

herkes için güzel.lakin sen olmayan.', 'sen diye uyandım gün doğumlarında. burası neresi! sen kimsin diyerek. saçları,dudakları,elleri sadece sana benzeyen. herkes için güzel.lakin...', ARRAY['Türk Edebiyatı','Şiir','Serkan Çekirge']::text[], 8.5, '{"poet":"Serkan Çekirge","poet_slug":"serkan-cekirge","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/o-o-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmadan guluse bak', 'utanmadan-guluse-bak-husamettin-guven-bjw0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kirdiklari kirk i gecmis

yuzunede maske takmis

sevenleri rezil yapmis

utanmiyor guluse bak

yuzu bile kizarmiyor

dert ve keder getirmiyor

tavri beni cildirtiyor

utanmiyor guluse bak

duygu somurusu yapar

aglayarak icler yakar

sikilmadan nutuk atar

utanmiyor guluse bak

zehir artik sana hayat

gec bunlari kulahima anlat

sen git derdini halana anlat

utanmiyor guluse bak', 'kirdiklari kirk i gecmis yuzunede maske takmis sevenleri rezil yapmis utanmiyor guluse bak yuzu bile kizarmiyor dert ve keder getirmiyor tav...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/utanmadan-guluse-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalınan düşler', 'calinan-dusler-sinan-oktay-eoui1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Huzur vermezler bana geceleri karafatmalar

gelirler penceremden kapımdan üzerime

çalmak için düşlerimi teker, teker,

O yüzden sıkı sarılırım düşlerime geceleri.

Yoklar gündüzleri ortada 

Çaldıkları düşleri yerler saklandıkları yerlerde.', 'Huzur vermezler bana geceleri karafatmalar gelirler penceremden kapımdan üzerime çalmak için düşlerimi teker, teker, O yüzden sıkı sarılırım...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/calinan-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-fatma-guven-u0w8y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Can diyerek yüreğime bastığım; 

Birgün çıkmaz sokaklara,

Yanılıp-yakılırda saparsa ayakların,

İpini boynuna geçirirse zaafların,

Kapılıp gidersen sevda hayallerine,

Bilki; saman alevidir tuttuğun.

Çıkışı olmayan labirenttir kaçışın.

Dur acele etme! 

Bu sana son çağırışım,', 'Can diyerek yüreğime bastığım;  Birgün çıkmaz sokaklara, Yanılıp-yakılırda saparsa ayakların, İpini boynuna geçirirse zaafların, Kapılıp gid...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/can-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /5', 'palavra-5-mustafa-aslan-2-po2fj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kiz,

Isik olur sabahlari aydinlatirsin.

Kiz,

Siyaz olur karartirsin geceleri.

Kiz,

Bir söz söylersin, costurursun gönülleri.

Kiz,

Aglarsin, yakarsin yürekleri.

Kiz,

Sen seversin seni seveni.

Kiz,

Inan çok mutluyum,

Dünyanin belkide en varlikli hazinesi sensin.

Kiz,

Benim için herseye degersin.

Kiz,

Okursan bu siiri hak ver bana,

Sakin kiyma bu sevdaya.

Bilirsin seni nasil sevdigimi.

Tarih Ve Saati: 13/08/2005      03:25', 'Kiz, Isik olur sabahlari aydinlatirsin. Kiz, Siyaz olur karartirsin geceleri. Kiz, Bir söz söylersin, costurursun gönülleri. Kiz, Aglarsin, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/palavra--5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /3', 'palavra-3-mustafa-aslan-2-5bfz3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana beni sevdigini söylersin,

Acaba dogrumu dersin.

Bilirim sende sevmek istersin,

Ama dogru seçimdemisin.

Kiz sus sen konusma,

Gözlerin anlatir bana herseyi.

Kiz sus aglama,

Hayat degmez göz yasina.

Ben seni gülüsünle sevdim,

Sen gülerken ben sevindim.

Seni benden almak istediler,

Ben ise savasmaya erindim.

Bilesin bu sevda kolay bitmez,

Biterse bu zavalli DeRTLi-SaiR gülmez,

Baska birini sevmez.

Tarih Ve Saati: 13/08/2005     02:34', 'Bana beni sevdigini söylersin, Acaba dogrumu dersin. Bilirim sende sevmek istersin, Ama dogru seçimdemisin. Kiz sus sen konusma, Gözlerin an...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/palavra--3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /4', 'palavra-4-mustafa-aslan-2-muro3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ve Ben,

Gündüz ile Gece.

Sen ve Ben,

Ay ile Günes.

Sen ve Ben,

Tas ile Toprak.

Sen ve Ben,

Yatak ile Yorgan.

Sen ve Ben,

Gömlek ile Kiravat.

Sen ve Ben,

Saç ile Toka.

Sen ve Ben,

Agaç ile Çimen.

Sen ve Ben,

Siir ile SaiR.

Sen ve Ben,

Yalniz ikimiz ve Sevgimiz.

Kiz duyuyormusun,

Sen ve Ben,

Bir sarki,

Bir roman,

Bir siir,

Bir renksiz filimiz.

Kafamda üç hece,

Ve üç kelime.

Düsüncelerim durdu,

Gelmez akla baska bir kelime.

Sen ve Ben! ...

Seni Seviyorum Kiz! ...

Sen ve Ben,

Yalniz ikimiz ve Sevgimiz.

Tarih Ve Saati: 13/08/2005     02:56', 'Sen ve Ben, Gündüz ile Gece. Sen ve Ben, Ay ile Günes. Sen ve Ben, Tas ile Toprak. Sen ve Ben, Yatak ile Yorgan. Sen ve Ben, Gömlek ile Kira...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/palavra--4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /6', 'palavra-6-mustafa-aslan-2-jfpdl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak kiz bu sevdaya nasil basladik,

Nasil gidiyor.

Bilmeni isterim en güzel duygular bizimdi.

Bizim askimiz zorluklarla dolu.

Biz ayni,

Ama ayri düsündügünü sanan saskinlardaniz.

Biz birgün sever,

Birgün kavga ederiz,

Ama olsun,

Biz evlilige kendimizi hazir ederiz.

Biz hep severiz,

Belkide hiç vazgeçmeyiz.

Biz hep gülmeli,

Hep birbirimizi dinlemeliyiz.

Kiz,

En güzel günler benim,

Yillar ise senin olsun.

Bu sevdaya birkere basladikya,

Birakta mezarda son bulsun.

Tarih Ve Saati: 13/08/2005      03:50', 'Bak kiz bu sevdaya nasil basladik, Nasil gidiyor. Bilmeni isterim en güzel duygular bizimdi. Bizim askimiz zorluklarla dolu. Biz ayni, Ama a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/palavra--6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /7', 'palavra-7-mustafa-aslan-2-ozxgk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben geceleri siir yazar,

Sabahlari gezerim,

Bana karsi yanlisi olani ezerim,

Bana kimse yaklasmasin derim,

Çünkü ben onu severim.

Hergün onun yolunu gözlerim,

Sevgi dolu ona karsi sözlerim.

Her yanlisimda ve dogrumda,

Her gerçegimde ve yalanimda,

Yüregimde ve özümde,

Kisaca herseyimde akkadin.

Kiz,

Yalnizlik nedir bilirmisin? 

Ben yalnizligi sende unuttum.

Özlemek nedir bilirmisin? 

Ilk defa seni özledim.

Ayrilik nedir bilirmisin? 

Bunu sende tatmak istemem.

Basladigimiz gündeki gibi mutlu kalsak,

Biliyorum bu zamanda sevmek yasak.

Ama gel dinle beni.

Ne olur,

Seninle zor olani basarsak.

Yasaklari çigneyip,

Mutluluga,

Sevdamiza ilk adimi atsak.

Kiz ayriligi hiç yasamasak.

Tarih Ve Saati: 13/08/2005     04:48', 'Ben geceleri siir yazar, Sabahlari gezerim, Bana karsi yanlisi olani ezerim, Bana kimse yaklasmasin derim, Çünkü ben onu severim. Hergün onu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/palavra--7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /8', 'palavra-8-mustafa-aslan-2-23s6t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni çok seviyorum,

Anladimki sensiz bir hiçim,

Seni sevmemek elimde degil.

Sen hep ol yanimda.

Tek derdim sen ol.

Bende sana verecek sevgi bol.

Sevgiye susuzsan gel bana,

Gidereyim susuzlugunu.

Yakip bütün askimi,

Seninle beraber kalbime gömdüm.

Hep orada kalacaksin.

Zaman zaman yasadim,

Zaman zaman sensiz kaldim,

Sensiz öldüm.

Ama ben artik gerçeklere döndüm.

Kiz,

Simdi yanimdasin,

Acaba hep yanimda kalacakmisin.

Tarih Ve Saati: 13/08/2005     05:06', 'Seni çok seviyorum, Anladimki sensiz bir hiçim, Seni sevmemek elimde degil. Sen hep ol yanimda. Tek derdim sen ol. Bende sana verecek sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/palavra--8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  /9', 'palavra-9-mustafa-aslan-2-v848f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne acilar çektim bir bilsen,

Neler geldi basima,

Anlatmaya kalksam,

Buna yürek dayanmaz,

Buna bir ömür yetmez.

Kiz,

Seninle yavas yavas unutuyorum geçmisi,

Imkanim olsa görmek isterdim gelecegi,

Neler oluyor,

Daha neler olacak.

Acimi çekiyorum,

Yoksa mutlumuyum,

Derdimin dermanini ariyorum,

Acaba gelecekte,

Derdimin dermanini sende bulurmuyum.

Bosver at gitsin,

Bu benim beynim varya,

Doldu tasiyor,

Artik geçmisi silsin,

Kader pesimi biraksin,

Bilsinki bu yürek onu seviyor.

Tarih Ve Saati: 13/08/2005     05:43', 'Ne acilar çektim bir bilsen, Neler geldi basima, Anlatmaya kalksam, Buna yürek dayanmaz, Buna bir ömür yetmez. Kiz, Seninle yavas yavas unut...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/palavra--9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  10', 'palavra-10-mustafa-aslan-2-3jg9g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman geçmiyor aglarim,

Kaç gündür senden uzagim.

Ayni ülke, ayni sehir içinde,

Sana yakin, ama manevi sekilde uzak.

Herkez sanki askimiza kuruyor tuzak.

Korkuyoruz birbirimize yaklasmaya,

Bizi beraber görür ayirirlar diye.

Bu kadar acimasiz olmak ne diye.

Çaresisiz,

Korkular içindeyiz.

Bilseler keske biz birbirimizi severiz,

Beraber aglar, beraber güleriz.

Kiz,

Sen inanma söylenenlere,

Bizi kimse ayiramaz, örnek olalim sevenlere.

Savasalim, ayiripta gülenlere.

Tarih Ve Saati: 14/08/2005      01:33', 'Zaman geçmiyor aglarim, Kaç gündür senden uzagim. Ayni ülke, ayni sehir içinde, Sana yakin, ama manevi sekilde uzak. Herkez sanki askimiza k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/palavra--10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  11', 'palavra-11-mustafa-aslan-2-lt3o2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canimi iste benden,

Hemen vereyim.

Ama ayrilik isteme.

Ben yoluna köleyim.

Ne para ister,

Nede mutlu bir hayat,

Bu gönül yalniz seni ister.

Kim derdiki biz bir olacagiz,

Yasadiklarimizidan pisman olacagiz,

Geçen yillarimiza aglayacagiz.

Kiz,

Saniyeler dakikaya,

Dakikalar saatlere,

Saatler günlere,

Günler haftalara,

Haftalar aylara,

Aylar ise yillara düsman oldu,

Onlarin savasinin acisi hep bizi buldu.

Bu siirde senin için akan gözyaslarimla son buldu.

Tarih Ve Saati: 14/08/2005     01:56', 'Canimi iste benden, Hemen vereyim. Ama ayrilik isteme. Ben yoluna köleyim. Ne para ister, Nede mutlu bir hayat, Bu gönül yalniz seni ister. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/palavra--11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  12', 'palavra-12-mustafa-aslan-2-rdt89', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben aglarsam aglar,

Gülersem gülersin.

Ben seni seviyorum,

Bilirim sende beni seversin.

Ben siir yazarim,

Sen sarki söylersin.

Ben seni görmek istesem,

Hemen camin önünde beni beklersin.

Ben ayrilmaktan korkuyorum desem,

Sen hep susmami istersin.

Ben sana soru sorsam,

Hep cevaplari gizlersin.

Ben yillarca sevgi yükünü tasidim,

Sira sende, artik sende bizdensin.

Ben hep zorluklarla savastim,

Sende savasacaksin, bunu bilmelisin.

Kiz,

Sevda yükümü sende biraktim,

Geçmisimi,

Geçmisini,

Bir ateste yaktim.

Sensiz bosa geçen yillarimi,

Bir kalemde siirlere sattim.

Tarih Ve Saati: 14/08/2005      02:23', 'Ben aglarsam aglar, Gülersem gülersin. Ben seni seviyorum, Bilirim sende beni seversin. Ben siir yazarim, Sen sarki söylersin. Ben seni görm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/palavra--12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  13', 'palavra-13-mustafa-aslan-2-03qy9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen her güzelden güzelsin,

Tatlidanda tatlisin.

Sen her insandan farklisin,

Sen siirlerimin tadisin.

Gözlerin parlar,

Yildizlardan parlak.

Yüzün hep güler,

Yüzünde gül bahçesini tasirsin.

Sen yalanlarimdaki gerçeksin,

Gönlümün tek sahibisin.

Kiz,

Yanaklarin al,

Dudaklarin bal.

Yüzün ak,

Döde bana bak,

Bakta bir bakista yüregimi yak.

Gözlerinin içinde yanan,

Sanki azgin bir ates.

Baktigin yeri yakiyor,

Küle çeviriyor.

Beni yaktigin gibi.

Tarih Ve Saati: 14/08/2005     02:54', 'Sen her güzelden güzelsin, Tatlidanda tatlisin. Sen her insandan farklisin, Sen siirlerimin tadisin. Gözlerin parlar, Yildizlardan parlak. Y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/palavra--13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  14', 'palavra-14-mustafa-aslan-2-5fc6w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben mutlu olmani istiyorum,

Mutlu olman için,

Elimden geleni yapiyorum.

Bazen sana akil veriyor,

Bazende yanlisini düzeltmeye çalisiyorum.

Günlerce sana seni anlatiyorum,

Ama her sözümde ayiplaniyorum.

Ben seni seviyorum,

Seninle hep gülüyor,

Aglamiyorum.

Seni kiskaniyor,

Askindan ölüyorum.

Bu sevdayi bitirme,

Mezarda bitsin istiyorum.

Kiz,

Sen aglarken agladim,

Sana hergün daha çok baglandim,

Günler geçtikçe yaslandim,

Yorgun düsüp, gizlice kendime agladim,

Ayrilmayalim diye,

Küsmeyelim diye,

Sana zaman zaman yagladim.

Belkide sana hala yaranamadim.

Bilmeni isterim,

Ben seninle yasamaya basladim.

Tarih Ve Saati: 14/08/2005     03:19', 'Ben mutlu olmani istiyorum, Mutlu olman için, Elimden geleni yapiyorum. Bazen sana akil veriyor, Bazende yanlisini düzeltmeye çalisiyorum. G...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/palavra--14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  15', 'palavra-15-mustafa-aslan-2-uvuof', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neredesin simdi,

Sessiz,

Hersey çok sessiz,

Bir okadarda çaresiz.

Hasret kokar geceleri,

Uyku tutmaz.

Geceleri sessiz ve sensiz,

Sen gidersen hasretlik uzar içimde,

Siir gibi sen varsin dilimde,

Ilk konustugumuz yer hala gözümde.

Sensin her söyledigim sözümde.

Kiz,

Sen dinlermisin söylediklerimi,

Aglarsam silermisin gözlerimi,

Yanima gelip dindirirmisin hasretimi,

Ben taniyamadim,

Tanitirmisin bana kendimi.

Mustafa kimmis unuttum,

Ruhuma mustafa yerine,

DeRTLi-SaiR''i koydum.

Tarih Ve Saati: 14/08/2005     04:24', 'Neredesin simdi, Sessiz, Hersey çok sessiz, Bir okadarda çaresiz. Hasret kokar geceleri, Uyku tutmaz. Geceleri sessiz ve sensiz, Sen giderse...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/palavra--15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  16', 'palavra-16-mustafa-aslan-2-ogt0y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizlige alisamadi bu yürek,

Sensiz olamadi bu gönül.

Hasretini çekerken,

Söyle susarmi aglayan gözler.

Senin gibi bir sevgilim var,

Düsmana ne gerek var.

Söyle yasamakmi bu benimki,

Yasamak buysa,

Ölsem daha iyi.

Senden ayri kalmak,

Sesini duymak,

Ama görememek,

Görsem bile dokunamamak.

Öpememek,

Saramamak.

Söyle sen buna yasamakmi diyorsun.

Kiz,

Çaresizlik içindeyim,

Nasil yasayacagim anlamadim.

Sensizlige iki aydan sonra bile alisamadim,

Bu aylar içinde zaten yasayamadim.

Ben bu aska bas koydum,

Ama geri alamadim.

Herkezden iki adim önde,

Dört adim arkada yürüyorum,

Ama nedense,

Çikis yolumu bulamiyorum.

Dönüp dolasip ayni yola çikiyorum.

Tarih Ve Saati: 15/08/2005      01:21', 'Sensizlige alisamadi bu yürek, Sensiz olamadi bu gönül. Hasretini çekerken, Söyle susarmi aglayan gözler. Senin gibi bir sevgilim var, Düsma...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/palavra--16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  17', 'palavra-17-mustafa-aslan-2-na3vn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak yine sensiz,

Sensiz ve çaresiz.

Gidisin öldürdü,

Gelisin beni yasatti.

Gidisinle gelisin esit,

Ikiye böldün beni,

Varliginla yoklugunun arasinda kaldim.

Senin için yandi bu yürek,

Senin için sönecek.

Kendime güvencimi kaybettim,

Elbet geri dönecek.

Bu gönül sende yasadi,

Sende ölecek.

Kiz,

Korkuyorum,

Neden? 

Bende artik bilmiyorum.

Seni özlüyor,

Senin hasretinle yasiyorum.

Bu yürek kaniyor,

Artik dayanirmi bilmem,

Seni son kez göremesem,

Ben rahat ölemem.

Tarih Ve Saati: 15/08/2005      02:01', 'Bak yine sensiz, Sensiz ve çaresiz. Gidisin öldürdü, Gelisin beni yasatti. Gidisinle gelisin esit, Ikiye böldün beni, Varliginla yoklugunun ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/palavra--17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  20', 'palavra-20-mustafa-aslan-2-1yk95', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah uyandigimda,

On dakikalik uykumdan,

Hemen seni ararim,

Günesin dogusunu izler,

Günesi sana benzetirim.

Benim ruhumu isitan,

Günesim sensin.

Her gece siirimi yazarken sana,

Göz yaslari arasinda yazarim,

Bazen yagan yagmura bakar,

Derim,

Bulutlar,

Benim derdime sizde aglayin.

Hasretime hasret,

Özlemime özlem,

Göz yasima yas katin.

Kiz,

Seni bekler,

Seni yasarim.

Ben seni birakamam,

Ben buna nasil inanirim.

DeRTLi-SaiR yalniz seni sever,

Bunu bilir, bunu kalbimde tasirim.

Tarih Ve Saati: 15/08/2005      03:43', 'Her sabah uyandigimda, On dakikalik uykumdan, Hemen seni ararim, Günesin dogusunu izler, Günesi sana benzetirim. Benim ruhumu isitan, Günesi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/palavra--20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  19', 'palavra-19-mustafa-aslan-2-h6fr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalan,

Yalanmis yalan,

Anladim hersey,

Herkez yalan.

Bizim askimiza el uzatanin,

Elleri kirilsin.

Bizim askimiza dil uzatanin,

Hayati kaysin.

Bizim askimiza yalan diyen,

Insanlar utansin.

Hersey,

Herkez yalan,

Gerçek olan askimiz,

Askim buna inan.

Kiz,

Sende özler,

Sende gizli gizli aglarsin.

Ayriliktan korkar,

Gerçeklerden kaçarsin.

Kim düsürdü askimizi dilden dile,

Bosver korkma,

Geç yanlarindan gururunla güle güle.

Tarih Ve Saati: 15/08/2005      03:18', 'Yalan, Yalanmis yalan, Anladim hersey, Herkez yalan. Bizim askimiza el uzatanin, Elleri kirilsin. Bizim askimiza dil uzatanin, Hayati kaysin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/palavra--19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra ? ? ?  18', 'palavra-18-mustafa-aslan-2-0br6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni yazdim kalbime,

Ismini çizdim gönlüme.

Seni haykirdim gecelere,

Gecenin sessizligine.

Alisamadim sensizlige,

Isyan ettim hasretine.

Kafayi taktim kaderimin isine,

Kulak vermiyor kimse benim sesime,

Dertler geliyor topluca üstüme,

Derman bulun artik su dertlerime.

Bir gece daha,

Ve yeni bir dert.

Yeni bir dertle,

Yeni bir siir.

Kiz,

Ismini yaziyorum,

Her gittigim yere.

Alisamaz bu yürek,

Sensizlige,

Sensizligin sessizligine.

Tarih Ve Saati: 15/08/2005      02:45', 'Seni yazdim kalbime, Ismini çizdim gönlüme. Seni haykirdim gecelere, Gecenin sessizligine. Alisamadim sensizlige, Isyan ettim hasretine. Kaf...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/palavra--18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Ve?', 'mustafa-ve-mustafa-aslan-2-4dd9p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'M’ utluluk nedir sende ögrendim,

U’ mutlarimi yitirmistim, sen oldun umudum,

S’ on durak derken, ilk duragim sen oldun,

T’ utunacak dalim yokken, benim için agaç oldun,

A’ sigim simdi sana deliler gibi,

F’ erhatla Sirinin aski gibi,

A’ nladim hem çok iyi anladimki, sensiz anlamsizim.

V’ eda günü gelse ne dersin? 

E’ lveda mi? Yoksa? Seni seviyorum sözcügümü? 

? '' Kim oldugunu unuttum, Sen hiç olmadin''ki.

Tarih Ve Saati: 11/04/2005	21:38', 'M’ utluluk nedir sende ögrendim, U’ mutlarimi yitirmistim, sen oldun umudum, S’ on durak derken, ilk duragim sen oldun, T’ utunacak dalim yo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mustafa-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanlarin Kusu', 'yalanlarin-kusu-mustafa-aslan-2-6m403', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen sevdali güllerin,

En güzeli.

Sen kuslarin,

En özgür uçani.

Sen sevgimin,

Tek sultani.

Sen yalanlarin kusu,

Bense bir yabanci.

Seni sevmek çok güzel,

Seninle olmak çok özel.

Bana bakipta göklerde uçusun,

Ansizin kapimi çalisin,

Bana gülüsün,

Bir anda yere konusun,

Ve benim olusun,

Okadar çok önemliki,

Seninle olmanin sevinci var içimde.

Sen yalanlarin kusu.

Hazirmisin,

Benimle olmaya,

Eski özgürlügünü unutmaya.

Sen yalanlarin kusu.

Hazirmisin,

Mutlu bir yuva kurup,

Benimle ömür boyu yasamaya.

Sen yalanlarin kusu.

Hazirmisin,

Özgürlügünü birakip,

Mutlu olmaya.

Tarih Ve Saati: 25/05/2005     02:32', 'Sen sevdali güllerin, En güzeli. Sen kuslarin, En özgür uçani. Sen sevgimin, Tek sultani. Sen yalanlarin kusu, Bense bir yabanci. Seni sevme...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalanlarin-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram oldu yasamak', 'haram-oldu-yasamak-husamettin-guven-oa664', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seviyorum desemde

neselenip gulsemde

unutamam olsemde

haram oldu  yasamak

rezil ettin sevenleri

lekeledin bak her yeri

terk etmissin sevenleri

haram oldu yasamak

nasil sana kanayim

hangi tavrina inanayim

rezil etdinben oleyim

haram oldu yasamak', 'seviyorum desemde neselenip gulsemde unutamam olsemde haram oldu  yasamak rezil ettin sevenleri lekeledin bak her yeri terk etmissin sevenle...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haram-oldu-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlığımı Bastırdım', 'acligimi-bastirdim-i-rfan-kaban-um479', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırdım yüreğinden  bir parça

Katık yapıp yanına kafamdaki en inatçı sorunu

Yedim bir öğünde hepsini

Midem berbat,midem ağzıma geliyor

Ağzımda yüreğinin ekşi tadı

Ağzımda kafamdaki sorunun en berbat tarafı

Açlığımı bastırdım

Berbatım…', 'Kırdım yüreğinden  bir parça Katık yapıp yanına kafamdaki en inatçı sorunu Yedim bir öğünde hepsini Midem berbat,midem ağzıma geliyor Ağzımd...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/acligimi-bastirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıta-1', 'kita-1-naciye-bildim-1ll5o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gitmek istersen uzaklara,

Kara saplı bir bıçak gibi

Kes,parçala bağrımı.

Beni öldür öyle git...

Elinde valizin,düşersen yollara

Kapımı  erken çalan ecel gibi

Canımı al öyle git', 'Bir gün gitmek istersen uzaklara, Kara saplı bir bıçak gibi Kes,parçala bağrımı. Beni öldür öyle git... Elinde valizin,düşersen yollara Kapı...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kita-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minicik', 'minicik-nevin-kalafatoglu-qonnp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kedicik

minicik

kartopucuk

ışık yumağı bir pisicik

ismi piknik

ay annesi

lin çizgisi

nurhanesi

bir tanesin

2006/ modalı piknik için /ist

antalya', 'kedicik minicik kartopucuk ışık yumağı bir pisicik ismi piknik ay annesi lin çizgisi nurhanesi bir tanesin 2006/ modalı piknik için /ist ant...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/minicik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıta-2', 'kita-2-naciye-bildim-7w2hj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi bir yaz sabahının hazin öyküsünü anlatıyorum,

Yeni açmış güller gibi,bir avuç su bir rüzgar bekliyorum.

Şimdi bir yaz sabahını öyküsünü anlatıyorum,

Gözlerim uzun yollarda,ölümü beklercesine seni bekliyorum.', 'Şimdi bir yaz sabahının hazin öyküsünü anlatıyorum, Yeni açmış güller gibi,bir avuç su bir rüzgar bekliyorum. Şimdi bir yaz sabahını öyküsün...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kita-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takıldı Gözlerim Düşlerine', 'takildi-gozlerim-duslerine-birsen-ates-zu9i4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir yerlerde

karşılaşsak seninle 

alakasız bir kış akşamında

sözüm var kendime

sarılıp öpeceğim seni

o yüzden gelmiyorum

biliyorum

bırakmayacağımı 

sinmiş kokun üzerime

sana 

sarılamadan daha

takıldı gözlerim 

gözlerine

düşlerindeyim

her gece

orada ara hep beni

hiç

gelmesem de

    

04.01.06', 'bir yerlerde karşılaşsak seninle  alakasız bir kış akşamında sözüm var kendime sarılıp öpeceğim seni o yüzden gelmiyorum biliyorum bırakmaya...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/takildi-gozlerim-duslerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Öğretmenim', 'sevgili-ogretmenim-refika-dogan-u21yh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '" En çok konuşması gerekirken “ bir şey konuşamayan “ lar konumuna düşürülen öğretmenlerimize..." r.d

sevgili öğretmenim; 

okul bir bahçe, sizse bahçıvan... 

bizler diktiğiniz fidanlarız; 

bakıp besledikçe engin bilginizle, 

dar gelecek o bahçe 

sığmayacak minik fidanlarınız; 

büyüyecek

büyüyecek selvi dal gibi... 

dal-budak saracak dört bir yana kökler! 

köklerden yeni fidanlar sizin,

hep sizin eseriniz olacak! 

sevgili öğretmenim, 

siz bir hecesiniz; 

beşikten mezara,

anamla başlayıp 

sizinle noktalanan süreç... 

ve sonra

dağarcığımda toplanan azık 

verdiğiniz şeyler! 

yaşam boyu ayakta tutacak, 

beni, ben olmaya çağrıştıracak,

insana, insan olabilmesini amaçlayacak 

değerler halkası... 

sevgili öğretmenim, 

siz coşkun bir sel gibisiniz; 

yatağından çağlayarak 

bilinmeyene uzanan 

uzantı... 

geçtiği yerde 

yosun tutmuş artıkları silip süpüren 

ab-ı hayat suyu... 

siz 

özgür bir düşüncesiniz usumda; 

karanlıkları yırtan 

aydınlığın umudu... 

insan onurunun ezel-i bekçisi... 

bağnazlığın, sığlığın 

düşmanı,

yılmaz demokrasi savaşçısı... 

sevgili öğretmenim,

siz bir duygusunuz içimde; 

kabardıkça, kabaran, 

yudumsadıkça ılık ılık, 

hayat buluyor damarımdaki kan! 

parlayan bir güneşsiniz; 

sıcak ve aydınlık ışığınızla, 

-kısır döngü içinde buzullaşmış medeniyetileri eriterek-

sarsılmaz inancıyla; 

usumdaki gerçeğe dönüştürecek 

birer çağdaş çizgi... 

biliniz ki; andım olacak 

tuttuğunuz meş’aleyi devir alırken, 

özgürlük ve demokrasinin onurlu savaşında; 

barışçı 

sosyal adaletçi 

erdemli 

ekin dolu 

İnsan olabilmenin bilincine erebilmiş insanlarla 

hayat bulacak 

bir dünya için savaşmak! 

Çocuksu ve berrak sevgilerin masumiyetiyle 

selamlıyorum! 

Refika Doğan -1988 -Ankara', '" En çok konuşması gerekirken “ bir şey konuşamayan “ lar konumuna düşürülen öğretmenlerimize..." r.d sevgili öğretmenim;  okul bir bahçe, s...', ARRAY['Türk Edebiyatı','Şiir','Refika Doğan']::text[], 8.5, '{"poet":"Refika Doğan","poet_slug":"refika-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/sevgili-ogretmenim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi bir elbise çıkmaz kardeşim kumaş fasonsa', 'i-yi-bir-elbise-cikmaz-kardesim-kumas-fasonsa-halil-colak-4efkt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençlik elden gider boşa geçer zaman

Bitti ömür sermayesi az kaldı geriye kalan

Şimdiki dostlukların çoğu kardeşim yalan

Bitiyor ömür  anlamaya  kalmıyor zaman

Kesilince menfaatler uğramaz sana da kimse

İnsanlık tezgahında dokunan kumaşta buysa

İyi bir elbise çıkmaz kardeşim kumaş fasonsa 

Halil Çolak 4.1.2006 Ankara', 'Gençlik elden gider boşa geçer zaman Bitti ömür sermayesi az kaldı geriye kalan Şimdiki dostlukların çoğu kardeşim yalan Bitiyor ömür  anlam...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iyi-bir-elbise-cikmaz-kardesim-kumas-fasonsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap veremez sessiz sedasız yol alır omuzlarda', 'cevap-veremez-sessiz-sedasiz-yol-alir-omuzlarda-halil-colak-070lt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalmamış muhabbet ne evlatta ne yarda

Kimseyi Allah bırakmasın derdiyle  darda

Bülbül figan eder olsa da altın kafeste

İnler durur yavrum aheste aheste

Zaman geçer dünyada ömür biter bir anda

Nice yolcular uğramış geçmişlerde bu handa 

Son yolculuk başladığı cemaatin helalaştığı zamanda 

Cevap veremez sessiz sedasız yol alır omuzlarda

Halil Çolak 4.1.2006 Ankara', 'Kalmamış muhabbet ne evlatta ne yarda Kimseyi Allah bırakmasın derdiyle  darda Bülbül figan eder olsa da altın kafeste İnler durur yavrum ah...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cevap-veremez-sessiz-sedasiz-yol-alir-omuzlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sene', 'bu-sene-cemal-simsek-xheor', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıl geride kaldı,hasret kaldım sevgiye 

Cevapsız kaldı aşkım,gönlüm döndü deliye 

Umutla bakıyorum,gelecek günlerime 

Taş kalpli yüreklere,SEVGİ DOLSUN BU SENE. 

..................................................................', 'Bir yıl geride kaldı,hasret kaldım sevgiye  Cevapsız kaldı aşkım,gönlüm döndü deliye  Umutla bakıyorum,gelecek günlerime  Taş kalpli yürekle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-sene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-mehmet-sait-akkus-vsv2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen sevilecek

Sen özlenecek

Sen beklenecek

Sen tapılacak

Kadınsın benim için

Sen gönlüme eş

Sen doğan güneş

Sen aşkından sarhoş

Sen aya kardeş

Olacak kadar güzelsin kadınım

Sen yıllara

Sen yarınlara

Sen Gönüllere

Akacak kadınsın benim için

Seni unutmak

Seni anlatmak

Seniyazmak

Seni kazımak

Lazım akıllara kadınım', 'Sen sevilecek Sen özlenecek Sen beklenecek Sen tapılacak Kadınsın benim için Sen gönlüme eş Sen doğan güneş Sen aşkından sarhoş Sen aya kard...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kadinim-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki İste', 'yeterki-i-ste-mehmet-sait-akkus-dxj8s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İste kolum çizeyim

Kanımla adın yazılsın

Bıçakla tenim keseyim

Bende adın silinmesin

Unutulacak değilsin

Bir kenara yazıyorum

Sen benim için en öncesin

Senin için ölüyorum

Yeterki iste amadeyim

Senin için yanıyorken

Bir vilsen ne haldeyim

Hergün yeniden ölürken', 'İste kolum çizeyim Kanımla adın yazılsın Bıçakla tenim keseyim Bende adın silinmesin Unutulacak değilsin Bir kenara yazıyorum Sen benim için...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeterki-iste-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaydırak', 'kaydirak-elazigli-mustafa-kaya-u7wy3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 've büyüdük 

yorgun bir sarıyla 

göğe vururdu seslerimiz 

Fırat kenarında.... 

kaydırak oynardık 

hırçın Fırat üzerinde 

çimerdik 

taş ısınmış olurdu 

sudan çıkınca uzanmaya.. 

çalılardan korkmazdık 

güller açtırırdık 

böğürtlenler hardalımızdı 

sakız kanatırdık 

işlemeli bayırlarda.. 

toprağa yayılırdık

hikayeler…komik sözler

anlatırdık

uç uç böcekleri gelirdi

çekirgeler de,

sinekler hep vardı

bir yanımızda 

ağustos böcekleri

bir yanımızda Fırat akardı…

Mustafa kaya

03.01.2006 /  üsküdar', 've büyüdük  yorgun bir sarıyla  göğe vururdu seslerimiz  Fırat kenarında....  kaydırak oynardık  hırçın Fırat üzerinde  çimerdik  taş ısınmı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaydirak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Şekli', 'i-ntihar-sekli-makbule-baydaroglu-q4u72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bileklerimdeki kesikler,

Derin değil kalbimdeki kadar.

Asfalttaki kan izlerim,

Çıkmıyor yıkanmakla.

Mideme sokulan hortumlar,

Arıtmıyor beynimi.

Karar veremediğim bir sonla,

Harcıyorum kendimi.', 'Bileklerimdeki kesikler, Derin değil kalbimdeki kadar. Asfalttaki kan izlerim, Çıkmıyor yıkanmakla. Mideme sokulan hortumlar, Arıtmıyor beyn...', ARRAY['Türk Edebiyatı','Şiir','Makbule Baydaroğlu']::text[], 8.5, '{"poet":"Makbule Baydaroğlu","poet_slug":"makbule-baydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/intihar-sekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünce', 'olunce-makbule-baydaroglu-rcxj1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölünce,

Unuttuğumu sanma

Konuşamadığımı bil.', 'Ölünce, Unuttuğumu sanma Konuşamadığımı bil....', ARRAY['Türk Edebiyatı','Şiir','Makbule Baydaroğlu']::text[], 8.5, '{"poet":"Makbule Baydaroğlu","poet_slug":"makbule-baydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/olunce-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-makbule-baydaroglu-tm68z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen giderken benden,

Bir bedevinin

Asla kaybolmadığı

Yollarına inat

Miladı dolmuş bir aşkın

Çarmıha gerilme vaktinde unutulan

İkindi kızıllığını götürüyorsun.', 'Sen giderken benden, Bir bedevinin Asla kaybolmadığı Yollarına inat Miladı dolmuş bir aşkın Çarmıha gerilme vaktinde unutulan İkindi kızıllı...', ARRAY['Türk Edebiyatı','Şiir','Makbule Baydaroğlu']::text[], 8.5, '{"poet":"Makbule Baydaroğlu","poet_slug":"makbule-baydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/giderken-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-osman-demircan-iaw21', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir  resim  çizdim; 

Bütün  çıplaklığıyla  kendi  resmimi.

Dudağımda  gözyaşı  izleri

Silip  süpürdü  bütün  evetleri.

Soylu  büyük  bir  çizgiyi

Alnıma  kazıdım.

Alnımda  sakladım  bütün  gizi.

Kuşkuyla  tedirgin  gözlerimin  çerçevesinde

Uyumuş  da  büyümüş  acılar  gördüm.

Yüzümün  kıvrımlarında

Hiç  olmamışlığın  gölgesini  vurdum.

Zamanın  düğümlerine  vurabildiysem  kendimi

Çizebildiysem  resmimi

Dostuma  vermek, düşmanıma  göstermek  için

Altına  da  beyaz  bir  güvercin  yaptım.

Bir  resim  çizdim; 

Bütün  çıplaklığıyla  kendi  resmimi.

Var  mı  cesareti  olan? 

Kalemi  size  verdim.

Çizin  resminizi.', 'Bir  resim  çizdim;  Bütün  çıplaklığıyla  kendi  resmimi. Dudağımda  gözyaşı  izleri Silip  süpürdü  bütün  evetleri. Soylu  büyük  bir  çi...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/resim-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela', 'ela-makbule-baydaroglu-fmkm6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimdeki el dedin,

Tut sana rüya, tut bana rüya.

Sihrine mağlup oldum.

Kapkara oldu dünya.

Gözümdeki göz dedin,

Tut sana bela, tut bana bela.

Gayri bize bir mum gerek; 

Ben karanlık,sen ela.', 'Elimdeki el dedin, Tut sana rüya, tut bana rüya. Sihrine mağlup oldum. Kapkara oldu dünya. Gözümdeki göz dedin, Tut sana bela, tut bana bela...', ARRAY['Türk Edebiyatı','Şiir','Makbule Baydaroğlu']::text[], 8.5, '{"poet":"Makbule Baydaroğlu","poet_slug":"makbule-baydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ela-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Sevinci', 'yasama-sevinci-osman-demircan-5drul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir  bahar  akşamında

Kar  suları  beslerken  yayla  çimenlerini

İçin  için  kaynamak  istiyorum.

Serin  sular  gibi  çağlamak  istiyorum.

Kanat  açarak  yaşama  sevincine

Ressamların  ve  şairlerin  duygu  denizinde

Rüzgarları  arkama  alarak

Bir  martı  gibi  uçmak  istiyorum.

Doya  doya  yaşamak  istiyorum.', 'Bir  bahar  akşamında Kar  suları  beslerken  yayla  çimenlerini İçin  için  kaynamak  istiyorum. Serin  sular  gibi  çağlamak  istiyorum. K...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasama-sevinci-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuval Gönüller', 'tuval-gonuller-savas-dincbas-0qi07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sesler fırçamız

kelimeler renkler

duygularımız yaratıcı

gönüller tuval

duygularınızı

çizerken tuvale

siyahı atın

boya kutunuzdan

rengarenk

gönüller yaratın

sevgiyi resmeden

yaşayan ve yaşatan

tüm evreni

bu tablolarla donatın...', 'sesler fırçamız kelimeler renkler duygularımız yaratıcı gönüller tuval duygularınızı çizerken tuvale siyahı atın boya kutunuzdan rengarenk g...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tuval-gonuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve Niyetine', 'kahve-niyetine-salih-erdem-3l6oa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağacım yetirdim ruhun tözünde

Meyvemi kavurdum aşkın özünde

Gönüldür değirmen çeker sazında

Kınamı koklayın hatırım kalır

Ocağı fikrimde sürüp közüne

Bilirsin bahane maksat sözüme

Ağırdan dolarım suyun gözüne

Vuslatı bekleyin hatırım kalır

Bir taşım bengidir suyum kaynasın

Fincana köpüksüz canan koymasın

Damakta nihanım kimse doymasın

Sırrımı saklayın hatırım kalır

Dökülme zamanı bitecek hasret

Fincana dolarım birazcık sabret

Dudaktan gönlüne akıp nihayet

Tadımı katlayın hatırım kalır

Su ile başlanır usulü aslım

Önce ya da sonra tatlıdır faslım

Bu güzel meseli öğrensin neslim

Gençleri kutlayın hatırım kalır

İnsandan insana damak farklıdır

Kiminin şekeri yandan çarklıdır

Şanımda Türk adı aslım şarklıdır 

Soyumu yoklayın hatırım kalır

Kervanım düzüldü Yemen ilinde

Her anım bir tören halkın dilinde

Gelinlik kızların usta elinde

Düğünü bekleyin hatırım kalır

Kültürel mirasım asırlık serden

Küpümü kırdılar saçıldım sırdan

Adımı kaldırın düştüğü yerden

Üstümü paklayın hatırım kalır

Sohbetin sonunda sadete gelip

Fincanım sükûtu hayale dalıp

Bilinmez sırrını telveme salıp

Falıma yükleyin hatırım kalır 

Erdemoğlu zaman ömrü öğütür

Göz dikip tahtıma ferman dağıtır

Canıma buz düşer tenim soğutur 

Adımı aklayın hatırım kalır

22.12.2005 02.45

22.12.2005 22.40 Salih ERDEM - AYDIN

Sözün özü; 

Şiirdi bahanem sohbetin için

Dileği şahanem dostluğu seçin

Dimağa çalarım iş bu kelâmı

Gerisi teranem usuldan geçin', 'Ağacım yetirdim ruhun tözünde Meyvemi kavurdum aşkın özünde Gönüldür değirmen çeker sazında Kınamı koklayın hatırım kalır Ocağı fikrimde sür...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kahve-niyetine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiddet Dolu Bir Gün', 'siddet-dolu-bir-gun-gulsen-gonenc-1bucj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiddet dolu bir gündü.

Önce serçe öttü; 

ayrılık bir karadelik dedi.

Serçenin kafasını kopardım,

ağzımla.

Sonra sert bir rüzgar yüzümü tokatladı.

Saçlarıma asılı çiçekler soldu,

ansızın.

Estim, estim, rüzgarı bile ezdim geçtim.

Şiddet dolu bir gündü.', 'Şiddet dolu bir gündü. Önce serçe öttü;  ayrılık bir karadelik dedi. Serçenin kafasını kopardım, ağzımla. Sonra sert bir rüzgar yüzümü tokat...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siddet-dolu-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabb/im', 'rabb-im-orkun-isik-yhyne', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rabbimizin kulağının zarıdır, 

Avuçlarımızı açtığımız semamız. 

Bizi duysun diye açılmamış mı avuçlarımız, 

Boş dönmeyen dualarımız… 

İçimizle dünya arasında ki dışımız, 

Mihengimiz oluyordu, utanç duvarımız. 

İmgeleşiyordu dışımız içimiz de 

Zira; bizi biz yapmaktaydı vicdanımız…', 'Rabbimizin kulağının zarıdır,  Avuçlarımızı açtığımız semamız.  Bizi duysun diye açılmamış mı avuçlarımız,  Boş dönmeyen dualarımız…  İçimiz...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/rabb-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum benim', 'erzurum-benim-halil-colak-x1vbh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemini çekiyorum ey beyaz  belde

Senden ayrılmış ayrılalı da derbederim

Özledim eksi otuz olan ayazın senin

O güzel vatanım olan Erzurum’um benim

Bir zamanlar adımlardım

 Kar yağarken caddelerin senin

Daha çok artıyor sana olan muhabbetim benim

Hayalimden  gitmiyor çağlayarak 

Türkü söyleyerek akan giden arasın senin

Beyaz gelinlik giymiş evliyalar diyarı Erzurum benim

Halil Çolak 4.1.2006 Ankara', 'Özlemini çekiyorum ey beyaz  belde Senden ayrılmış ayrılalı da derbederim Özledim eksi otuz olan ayazın senin O güzel vatanım olan Erzurum’u...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/erzurum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güvercin', 'beyaz-guvercin-osman-demircan-m2aoy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bak  beyaz  güvercinim! 

Ben  seni  savaşçı  ruhumla  severim.

Ve  içimdeki  şiddet  arttıkça,

Senin  varlığına  ters  düşerim.

Bak  gör  içimdeki  şiddetin  izlerini! 

Bakışımla  seni  üzerim.

Sen  bir  bahar  kadar  hoşsun...

Bense  bir  kış  kadar  sert  geçerim.', 'Bak  beyaz  güvercinim!  Ben  seni  savaşçı  ruhumla  severim. Ve  içimdeki  şiddet  arttıkça, Senin  varlığına  ters  düşerim. Bak  gör  iç...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyaz-guvercin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar', 'acilar-murat-polat-2-qjjyi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçen konu “acıydı” çekilen

Nasıl katlanmalı? 

Yahut nasıl onunla yaşamalı

Ve...acıları nasıl çevirmeli mutluluğa.

Dedim ki...ben hep acı çektim

Dedim ki...tanışamadım mutlulukla henüz! 

Dedim ki...istiyorum, bekliyorum

Bekleyeceğim, arayacağım

Henüz pes etmedim...

Nasıl düşülürse, kalkmayı da belledim

Sorunum...hep ayakta,

Hep dimdik ve uzun soluklu

Yaşayamamak...şöyle ağız tadıyla.', 'Geçen konu “acıydı” çekilen Nasıl katlanmalı?  Yahut nasıl onunla yaşamalı Ve...acıları nasıl çevirmeli mutluluğa. Dedim ki...ben hep acı çe...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/acilar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yandım Sana Yandım', 'sana-yandim-sana-yandim-yusuf-onder-bahceci-yzoeh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdim hâlim harap,

Aşk çölünde oldum turap,

Sen gözümde vaha, serap,

Sana yandım, sana yandım.

Söyle yıllar nasıl geçecek,

Sensiz ömür nasıl bitecek,

Hiçbir zaman gelmeyecek,

Sana yandım, sana yandım.

Kader değil bunun adı,

Gözümde koydular muradı,

Dünya onlara da kalmadı,

Sana yandım, sana yandım.

Birgün hesap sorarım ben,

Rüya gördüm yorarım ben,

Uçan kuştan sorarım ben,

Sana yandım, sana yandım....', 'Seni sevdim hâlim harap, Aşk çölünde oldum turap, Sen gözümde vaha, serap, Sana yandım, sana yandım. Söyle yıllar nasıl geçecek, Sensiz ömür...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-yandim-sana-yandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırım Taşları', 'kaldirim-taslari-serdar-ahmet-guzel-b1ij9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaldırımlar eskidi bu şehirde

Yağmur yağdı, kar ve rüzgâr

Yıprattı bu şehrin kaldırımlarını

İnsanlar gezdi, aymazca

Kimi tükürdü, kimi tekmeledi

Bu akşam baktım bu şehrin kaldırımlarına

Bana benziyordu, örselenmişti.

03.12.2006 saat:23.04', 'Kaldırımlar eskidi bu şehirde Yağmur yağdı, kar ve rüzgâr Yıprattı bu şehrin kaldırımlarını İnsanlar gezdi, aymazca Kimi tükürdü, kimi tekme...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kaldirim-taslari-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirim Bir Tek Sensin Çare', 'siirim-bir-tek-sensin-care-huseyin-erdogan-49dgq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gün bile tebessüm etmesen bana

biterim tükenirim,nefes alamam buralarda

darmadağın olurum aklar düşer saçıma

zindan olur her yer vallahi gök yıkılır başıma

eğer bu dünyada kavuşamadan ölürsem sana

taparcasına sevdi sevildi yazdır mezar taşıma

şiirim ben yine de razıyım uzaktan da olsa

seninle birbirimizi çılgınca severek yaşamaya

bekle bekle beni bir gün geleceğim seni almaya

o güzel yüreğindeki sevgi okyanusuna dalmaya

yılın dört mevsimi seni soluyacağım doya doya 

her gece semaya bakıyorum seni varsın Ay''da

inan ki sen olursun canım bana ayna her anımda

ben de yalnızca seni görürüm baktığım her yerde

şiirim bir tek sensin çare bendeki her türlü derde

                                                             04.01.2006

                                                         Hüseyin Erdoğan', 'bir gün bile tebessüm etmesen bana biterim tükenirim,nefes alamam buralarda darmadağın olurum aklar düşer saçıma zindan olur her yer vallahi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siirim-bir-tek-sensin-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara sende', 'ankara-sende-halil-colak-ahisg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün mutlu olamadım güzel Ankara sende

Suçlu sen misin ben miyim  anlamadım bende

Gam bende elem bende insanlar eğlenir sende

İlk baharında bile kış yeniden başlıyor bende

En sıcak  gününde  de sinem donuyor sende

Aşkın muhabbetin kalmadı güzelim bu tende

Bütün insanlar iki yüzlü olarak dolaşıyor sende

Alışamadım vurgun yemişe döndüm  bende

Halil Çolak 4.1.2006 Ankara', 'Bir gün mutlu olamadım güzel Ankara sende Suçlu sen misin ben miyim  anlamadım bende Gam bende elem bende insanlar eğlenir sende İlk baharın...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ankara-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Film bitti', 'film-bitti-emin-nadir-1apmj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen; 

Mazideki sevgili.

Kurguladığımız kadardı rolümüz,

Film bitti.

Bizler,

Şimdi...

Ateşli aşk sahnelerini,

Yalnızlığımızın salonlarında

İzleyip; 

Sansürlediğimiz.

Filmin kahramanları...', 'Sen;  Mazideki sevgili. Kurguladığımız kadardı rolümüz, Film bitti. Bizler, Şimdi... Ateşli aşk sahnelerini, Yalnızlığımızın salonlarında İz...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/film-bitti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmesem', 'gormesem-bahri-capgulas-htcrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üstüme yorganı çeksem; 

Olan biteni görmesem; 

Acı çekenleri görmesem; 

Ve acıyı kendimde hiç hissetmesem.

Bendeki de elbet yürek

Mazlumu elbet hissedecek

Kurşun gelse delse geçse öteye

Ancak bu kadar etkilenecek.

Görmüyor mu hiç kimse bunları

Bak insanlar açlık ve sefalet içinde

İhtiyarlar ellerinde tablaları maişet peşinde.

Peki bu gidiş bu Türkiye nereye böyle

Kafa kalmadı artık düşüne düşüne

Ha! düşünce suç artık boşuna düşünme

Bak köşe yazarları,kitap yazarları sevkediliyor mahkemeye

Ne demeye türkiyenin halini düşünmeye.

Namertler çıktı çıkalı piyasaya

Açlık,sefalet,mazlumluk hep kapıda

Apoyla oy topladılar ekonomide topa tutuldular

Çocuklarımızın çocuklarını bile borçlandırdılar.

Amerika her şeyimize karışır oldu

IMF hesapmemurluğumuza soyundu

Büyüklerimiz zenginlere çalışır oldu

Ölüm fakir fukara için tek çare görünür oldu.

				28.01.2002', 'Üstüme yorganı çeksem;  Olan biteni görmesem;  Acı çekenleri görmesem;  Ve acıyı kendimde hiç hissetmesem. Bendeki de elbet yürek Mazlumu el...', ARRAY['Türk Edebiyatı','Şiir','Bahri Çapgulaş']::text[], 8.5, '{"poet":"Bahri Çapgulaş","poet_slug":"bahri-capgulas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gormesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldumu?', 'oldumu-murat-polat-2-afhpp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben neyse alışkınımda

Böylesi bir terke! 

Senin kolayca itişin yok mu

Yok mu bu umut dolu yolu…

Ben hep hazırım arkadan vurulmaya da

Sen daha da hazırlıksız,

Ve…Sessiz vurdun! Şaşkınım…

Ben gerçek ve hazırdım, doluydum

Sen inanmadın ya bana…

Beni kendime bile kandırttın

Helal olsun sana…', 'Ben neyse alışkınımda Böylesi bir terke!  Senin kolayca itişin yok mu Yok mu bu umut dolu yolu… Ben hep hazırım arkadan vurulmaya da Sen dah...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oldumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmam', 'uslanmam-murat-polat-2-i8wgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uslanırmı bu uslanmaz huylarım

Huylarım mı beni yaramaz yapan? 

Ben dahil herkes ikisini ayırmada

Bir yarışta, bir telaşta.

Onlara soran varmı? 

Başka biri olmak...

Değişmek biraz...

Dönmek normale! 

Ne soran var

Nede değişen.

Eldekiler olmamalı hesapta

Yaşam bu hiç hesaba uymaz

Diretenler hep sonunda

Şimdi sessiz ve çıplak yatmakta.', 'Uslanırmı bu uslanmaz huylarım Huylarım mı beni yaramaz yapan?  Ben dahil herkes ikisini ayırmada Bir yarışta, bir telaşta. Onlara soran var...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uslanmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zerrin''e', 'zerrin-e-murat-polat-2-cy2jl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk aklıma gelen…Bilemezsin

Ne pop star yarışması,

Ne kaçak elektrik davası.

Sen de ne var biliyor musun? 

O kahrolası hüzün…

O kaçamadığım,

O yapış yapış

O insafsız hüzün…', 'İlk aklıma gelen…Bilemezsin Ne pop star yarışması, Ne kaçak elektrik davası. Sen de ne var biliyor musun?  O kahrolası hüzün… O kaçamadığım,...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zerrin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim....&..ben', 'kalbim-ben-nazan-i-zmirli-y5lok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.............bana.............

.........ödül olan..........

..............sen..............

sana 

sunabileceğim

en güzel

armağan

.......... seninle...............

......... dopdolu..............

...........kalbim...............

...............ve...................

..............ben.................

04.01.2006-antalya-', '.............bana............. .........ödül olan.......... ..............sen.............. sana  sunabileceğim en güzel armağan .......... ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalbim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-nizamettin-ozel-7758q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni her zaman

Ve her yerde terket.

Sadece ama sadece,

Gözlerine bakmama müsade et.

Rüyalarına gireyim,

Benim olsun gecelerin.

Kabuslarla uyanınca sen,

Sırtımda iz bıraksın pençelerin.

Arasanda bulamazsın,

Benim gibi seven yürekten.

Haydi düş gönlüme, düş; 

Bir şelale gibi yüksekten...', 'Beni her zaman Ve her yerde terket. Sadece ama sadece, Gözlerine bakmama müsade et. Rüyalarına gireyim, Benim olsun gecelerin. Kabuslarla uy...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Geliyorsa', 'nasil-geliyorsa-murat-polat-2-rs01q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ce her insan,sevdiği şeyi yapmalı

Yada ona yönelmeli, vakit geçirmeden

Bir flütse bu buğulu...dertli, öyle içten,inceden

Çalmalı, üflemeli, solumalı onu...nefes nefese.

Bir gitarsa yoksa...vurmalı tellerine

Parmakları kanamalı, tırnakları kırılmalı...işte öyle

Birisini sevmekse, belki deliler gibi

Şööyle sarılmalı, ses gelmeli! 

Hani diyo ya “ayı” gibi, ama belini kırmadan...

Öpmeli onu, koklamalı doya doya.nefes nefese...

Yada ölmekse tek becereceği

Yani inandığı, geride kalan...

Öyleyse adam gibi ölmeli...öylece...

Öylece...sessiz...ses-siz...son nefesinde.', 'Ben ce her insan,sevdiği şeyi yapmalı Yada ona yönelmeli, vakit geçirmeden Bir flütse bu buğulu...dertli, öyle içten,inceden Çalmalı, üfleme...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nasil-geliyorsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimselere Diyememki...', 'kimselere-diyememki-yusuf-onder-bahceci-6p9su', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanmaki gözlerim ağlar,

Yürekte özlerim ağlar,

Derdim vardır sıradağlar,

Kimselere diyememki.

Yıllar oldu gelmediki,

Seni sevdim demediki,

Bir yüzüme gülmediki,

Kimselere diyememki.

Belkide hiç gelmeyecek,

Onu sevdim bilmeyecek,

Kader belki gülmeyecek,

Kimselere diyememki.

Ona güller verecektim,

Seni sevdim diyecektim,

Onun için ölecektim,

Kimselere diyememki....', 'Sanmaki gözlerim ağlar, Yürekte özlerim ağlar, Derdim vardır sıradağlar, Kimselere diyememki. Yıllar oldu gelmediki, Seni sevdim demediki, B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimselere-diyememki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yazı Varya', 'bu-yazi-varya-murat-polat-2-b35mz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak kimine turada geldiği olur

Bu yazı var ya bu yazı

Tamam turacılar şöyle bir dursun

Yazıcılar hele bir yazılsın…

Tamam…Basit…De ki anladım

Kimi güler bu hayatta

Kimide kaybeder

Ama bu yazı ya

Bir bildiği vardır bu yazanın…!', 'Bak kimine turada geldiği olur Bu yazı var ya bu yazı Tamam turacılar şöyle bir dursun Yazıcılar hele bir yazılsın… Tamam…Basit…De ki anladı...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-yazi-varya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacılar Destanı', 'hacilar-destani-abdullah-odabas-g2e69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memleketimin gülleri,                   		

Hakikat bağı bülbülleri,                		

Marifet konuşur dilleri,                	

Hacı kardeş dostlarım,                  	

İrfan dolu mektubunuz,                  		

Sedre şifa can tazeler,                 		

Bu mahsun-i şad ettiniz,                		

Hacı kardeş dostlarım,                  		

O masada ben de olsam,                  	

Sohbetlerden lezzet alsam,                	

O kahvede çırak olsam,                  		

Hacı kardeş dostlarım,                  		

Masanızda çay olaydım,                  	

Sohbete ortak olaydım,                  		

O sırra vakıf olaydım,                  		

Hacı kardeş dostlarım,                  	

Masanızı süpüreydim,

Hizmete layık olaydım,

Aranızda oturaydım,

Hacı kardeş dostlarım,

Baka idim gül yüzlere,

Kulak vereydim sözlere,

Kurban olam ben sizlere,

Hacı kardeş dostlarım,

Memleketim şirin yurdum,

Dostlarımı orda koydum,

Erzurumda garip kaldım,

Hacı kardeş dostlarım,

Meftuniyem vatanımın,

Gabristanda yatanımın,

Anne baba kardeşimin,

Okur Fatiha dostlarım,', 'Memleketimin gülleri,                   		 Hakikat bağı bülbülleri,                		 Marifet konuşur dilleri,                	 Hacı kardeş ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hacilar-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe', 'dilekce-abdullah-odabas-0riqv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senelerdir ahını  çektiğim Tayyar Baba,     

Bir görüşte toz duman berhava etti bizi,       	

Ehli kamil, ehli irfan o muhterem,             	

Bir görüşte toz duman berhava etti bizi,       	

Arif olan bir nazarda tanıyor kemterleri,      	

Saç sakal yok sonradan azanları,               	

Altmışında uyanmamış Hayberi gezenleri, 

Bir görüşte toz duman berhava etti bizi,       	

Ne olaydı görse idim hub cemalin efendim,

Elli üçten bu tarafa ahu zarın çekerdim,

Hoş tesadüf Erzurum da görüştüm,

Bir görüşte toz duman berhava etti bizi,

Bize kısmet değil imiş ariflere yar olmak,

Bu acize yan bakışlar Abdulbakiye sarılmak,

Pus edem destii şerifin olmasın hiç darılmak,

Bir görüşte toz duman berhava etti bizi,

Meftuniyem nalayıkam sizlere dervişlere,

Ehli kamil lutfeder el atar düşmüşlere,

Kurban olam can veren dosta erişmişlere,

Bir görüşte toz duman berhava etti bizi,', 'Senelerdir ahını  çektiğim Tayyar Baba,      Bir görüşte toz duman berhava etti bizi,       	 Ehli kamil, ehli irfan o muhterem,            ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dilekce-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evcioğluna Destan', 'evciogluna-destan-abdullah-odabas-syjn9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Sami EVCİOĞLU''na) 

Mektubunuz can tazeler,                 		

Selam sefa size kardeş,                 	

Gönlümü şad fetheyledi,                 		

Selam sefa size kardeş,                 	

Hep bir şaha köle gurban,               		

Mevlam bize kıldı ihsan,                	

Saf gönüle dolar irfan,                 	

Selam sefa size kardeş,                 		

Kalem alet dil tercüman,

Kalb hazineyi kenzi rahman,

Nazargahı arşu rahman,

Selam sefa size kardeş,

Mürşid kamil üstadımız,

Dünya ukba iftiharımız,

Kurban ona hep varımız,

Selam sefa size kardeş,

Meftuniyi görün mazur,

Çok kusuru diler özür,

İlyas mısın yoksa hızır,

Selam sefa size kardeş,', '(Sami EVCİOĞLU''na)  Mektubunuz can tazeler,                 		 Selam sefa size kardeş,                 	 Gönlümü şad fetheyledi,            ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/evciogluna-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizdiğin Kaderim! …', 'cizdigin-kaderim-muammer-celik-p94jz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'varlığımla dolu yanın çürümüş 

küskün yanın bensiz üşümüş! ... 

Şiirimdir benim kaderim 

ve 

ben kaderimi yazarım...

Yüreğime köz basıyorum 

ateşim aşkım 

sevda dumanında dolanıyor başım… 

Bin yıl öncesinden 

bir tek seni sevdim 

Şimdi sevgimi yıldızlara verdim 

gözlerim 

ahhh 

o yeşil gözlerimmmm... 

Yoruldu yollarını gözlemekten,

kapandı dünyana benim gözlerim... 

Tutuldu dillerim 

çatıldı çenelerim 

çıkmaz oldu sözlerimmm

Ve ben hala seni özlerim... 

Yıldızların değil 

gözlerinin şehadetini isterim 

bu yetmez artık

yanında yüreğinin kefaletini

gönlünün feryadını

ihanetinin kefaretini de isterim...

Öptüğün alnım var ya; 

işte tam oramdan vuruldum 

canlı mefta oldum 

zemzemin’le yundum 

ve sevgisizliğin mezarına sensizce kondum... 

Yakınımdan geçtiğin gecede yıldız yoktu 

avucunda tuttugun halde mehtabı 

güneşin işi bile çok zordu 

gülmediğini desen de

içindeki ben artık şiir yazmıyordu... 

Penceremi aralayan rüzgarın 

fırtına ve kasırga gibi esiyor

soğuğu nefesimi kesiyor

bıçakla kestiğin yerlere

buz bastım, yine de dinmiyor

bıçak yarası kapanır derler

ama dil yarası kavuşmak bilmiyor…

söyle eyy sevgili, 

nefesi kesilmiş 

nasibi hepten kesilmiş 

helvası yenmiş merhuma bu AĞIT niçin? ... 

Yalnızlığa, sensizliğe ittiğin 

bu adam; 

yürek atışını 

kendi avuçlarında öldürdü, SIRF senin için! ... 

Tükendi kısmetim, kaldırıldı kaşığım 

ben sana degil, artık yokluğuna aşığım! 

ve

Çizdiğin Kaderim, Şimdi Benim Şiirim! …

BirDeli

02.01.2006', 'varlığımla dolu yanın çürümüş  küskün yanın bensiz üşümüş! ...  Şiirimdir benim kaderim  ve  ben kaderimi yazarım... Yüreğime köz basıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/cizdigin-kaderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Veda', 'sessiz-veda-ufuk-coban-2wlf6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gitmek istiyorsan git uzaklara,

Bırakma birşey uçup giden kokuna.

Hayalleri sil gözlerinden öyle git,

Beni aldığın sessiz limanlara.

Hayal kurduğum tek sendin,

Sen bizi bir kalemde sildin.

Hatalar engel mi sevmeye,

Bir sessiz vedayla gittin.

Düşleri yıkmak istiyorsan sen bilirsin,

Bilmedin senin için nelerden vazgeçtim.

Ellerimde kokun, gözlerimde hayalin,

Ben senden bir türlü vazgeçemedim.

Herşeyi uğruna silmek istedim,

Sen bizi karanlıklara gömdün,

Acımasız düşüncelere girdin,

Bir sessiz vedayla gittin.

04/01/2006 10:30', 'Gitmek istiyorsan git uzaklara, Bırakma birşey uçup giden kokuna. Hayalleri sil gözlerinden öyle git, Beni aldığın sessiz limanlara. Hayal k...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-veda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir adım at oğlum gel bana doğru', 'bir-adim-at-oglum-gel-bana-dogru-mikdat-bal-zqzvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yoruldum tutmuyor titrer dizlerim

Bir adım at oğlum gel bana doğru

Sana yol göstersin benim izlerim

Evladım yolunu bul bana doğru

Gençsin kuvvetlisin haline şükret

Bu halin hoş değil zararı farket

Kendine tuttuğun o yolu terket

Hadi yavrum yürü yol bana doğru

Bir fayda etmiyor ilaçlar zıkkım

Tahliller umutsuz öyle der hekim

Bizden sonra sensin dünyaya hakim

Beklenen bir umut ol bana doğru

Biliyorum bir çok sorunların var

Unutturmak için ürünlerin var

Hayat bu gün değil, yarınların var

Hadi kendine dön, gül bana doğru', 'Yoruldum tutmuyor titrer dizlerim Bir adım at oğlum gel bana doğru Sana yol göstersin benim izlerim Evladım yolunu bul bana doğru Gençsin ku...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-adim-at-oglum-gel-bana-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit İkindiydi', 'vakit-i-kindiydi-latif-oz-pgiik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit ikindiydi..

Gözlerinin ısrarında gördüm

Bana koşan duygularını

Bense gölgen gibiydim; 

Ne koşup tutabildiğin,

Ne kopartıp atabildiğin

Vakit ikindiydi..

Hava ayaza kesmiş

Duyguların yüreğinde; 

Derinliklere çekilmiş

Buz gibiydi ellerin

Vakit ikindiydi..

Günahtan kaçışta ısrarın vardı

Ve ona koşuşun

Sırlı alemler ülkesi

Pencerenden içeri

Vakit ikindiydi..

Duruşun net değildi aksimde

Kavi halef

Mücella ayine

Rüyamda hayalin

Vakit ikindiydi..

Ve sonrası..', 'Vakit ikindiydi.. Gözlerinin ısrarında gördüm Bana koşan duygularını Bense gölgen gibiydim;  Ne koşup tutabildiğin, Ne kopartıp atabildiğin ...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vakit-ikindiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-yusuf-onder-bahceci-o1p46', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vefasız,

Şimşekler çakar gözlerinden,

Oklar saplanır kalbime,

Kara, çatık kaşlarından,

En kolay yerimden vurursun beni,

Derinden, kalbimden,

Nasıl unuturum seni,

Unutmak gayem değil ki....', 'Vefasız, Şimşekler çakar gözlerinden, Oklar saplanır kalbime, Kara, çatık kaşlarından, En kolay yerimden vurursun beni, Derinden, kalbimden,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vefasiz-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Öyle Sevmişim Ben', 'seni-oyle-sevmisim-ben-yusuf-onder-bahceci-yzblr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Serin esen yeller gibi,

Bendi yıkan seller gibi,

Koku veren güller gibi,

Seni öyle sevmişim ben.

Çok sevmişim bilmemişim,

Yıllar yılı gülmemişim,

Nasıl hata etmişim,

Seni öyle sevmişim ben.

Bana deme sitem sözler,

Kalbim hâla seni özler,

Hani o verilen sözler,

Seni öyle sevmişim ben.

Güzellerde olur nazlar,

Dertli çalar bütün sazlar,

Arşa çıkar tüm niyazlar,

Seni öyle sevmişim ben....', 'Serin esen yeller gibi, Bendi yıkan seller gibi, Koku veren güller gibi, Seni öyle sevmişim ben. Çok sevmişim bilmemişim, Yıllar yılı gülmem...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-oyle-sevmisim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-nizamettin-ozel-p55hv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benliğimi isyan feryatları

Ve hasret ateşi kavurmakta.

Tek tek toplayıp bulutları,

Hırçın bir rüzgar gibi savurmakta.

Derin uykulara yatmışım,

Beyni kemiren derin düşüncelere.

Bedenimi yataklar uzatmışım,

Teslim ederek ruhumu gecelere.

Dalga dalga hayal perdesi,

Kelpetenle sökülen duygular.

Bu çatık kaşlı adam kimin nesi; 

Gece gündüz beni sorgular...', 'Benliğimi isyan feryatları Ve hasret ateşi kavurmakta. Tek tek toplayıp bulutları, Hırçın bir rüzgar gibi savurmakta. Derin uykulara yatmışı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sorgu-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah ezanı', 'sabah-ezani-nevzat-ozkan-eu0w0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'erken uyandım

kulağımda güzel bir melodi

dört bir yanda okunuyor

sabah ezanı

ortalık karanlık

içimde karamsarlık

sokaklarda gölgeler

çocuklar servis bekler

içimde bir huzur bir ürperti

içten okunan sabah ezanı

bu sabah da rahatlatıyor beni', 'erken uyandım kulağımda güzel bir melodi dört bir yanda okunuyor sabah ezanı ortalık karanlık içimde karamsarlık sokaklarda gölgeler çocukla...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sabah-ezani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gösteri', 'gosteri-nizamettin-ozel-rqcaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atalarımız doğru söylemiş; 

Tavuğun ya derisi, ya gerisi.

Bunların yaptığı; 

Bir lokma et için,

Yarım saat çatal bıçak gösterisi...', 'Atalarımız doğru söylemiş;  Tavuğun ya derisi, ya gerisi. Bunların yaptığı;  Bir lokma et için, Yarım saat çatal bıçak gösterisi......', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gosteri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmayan Hayat', 'yasanmayan-hayat-figen-aydogmus-awgv9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun

İner gözlerine ağırlık

Yaşanmış bir günün sessizliğidir uyku

Kafayı koyar yünden yastığa

Çeker yorganı tepesine kadar

Çizgi koyar gibi geceyle gündüz arasına

İri vücudu birden yumru olur ufacık

Sıskalaşır bedeni çeker dizlerini göğüslerine

Dalması gerek uyku dediği güzelliğe

Dalar günün verdiği işkenceye

Koyunlar atlar binlerce

Sayılar sırasını şaşırır

Kapalı gözlerine izin vermez düşünce

Uykusuz başlar yine sabahtan işkence

Bu kaçıncı gece eziyet veren

Yaşamakla ölmek arası gidip gelen

Hayallerine saldıran hangi mahluk

Kaç kez daha saldıracak çıplak elleriyle

Yaşamak zor olduğunu kimler biliyor

Uykusuz gecelere idam verilmiyor

Yamalı pantolana boyalı tırnağa

Peki neden iğrenç deniliyor

F.A. 3.1.2006', 'Yorgun İner gözlerine ağırlık Yaşanmış bir günün sessizliğidir uyku Kafayı koyar yünden yastığa Çeker yorganı tepesine kadar Çizgi koyar gib...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasanmayan-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bir Bardak Şarapta IX', 'su-bir-bardak-sarapta-ix-i-brahim-balci-04jvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ahit sandığının önündeki Kral mı,yoksa

Rakkase mi, dansederken çağıran ten türküsünü

Şu bir bardak şarapta,bedenin gördü ruhum

Sen ki ey esmer hatun, Rabb’la güreşte Davud’sun

Bedenin tekmil silah, dellendirir ki seni

Verdiğin hazlar günah, dillendiren bu beni

Şu bir bardak şarapta, sukunet buldu ruhum

Sen ki ey Josephine, aç kalmış uterus''sun

Ölüm, salt çürüyüp yitmesi mi bedenin

Beden dururken yerinde unutulanın nicedir hali

Şu bir bardak şarapta katakomp gördü ruhum

Sen ki ey ölüm  nefesli, kadim bir Lazarus’sun', 'Ahit sandığının önündeki Kral mı,yoksa Rakkase mi, dansederken çağıran ten türküsünü Şu bir bardak şarapta,bedenin gördü ruhum Sen ki ey esm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-bir-bardak-sarapta-ix-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Kadın', 'ah-kadin-figen-aydogmus-zxlt0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessizlikten önce

Sahnenin ortasında çığlık

Bir avucunda yalnızlık

Diğerinde utandığı ar

Bağışla diyor gözleri karanlığa uzanarak

Yalvarışları

Geleceğe umutsuzca akıttığı gözyaşı

Pavoretti''nin iniş çıkışlarını

Picasso''nun Müzisyenleri sahne arkasında çalmakta

Ah kadın

Sahnenin tam ortasında yalnızsın

Seyirciler sessiz

İşte istediğin sessizlik çırılçıplak

Ve işte sen

Ki son oyunun

Son perdesindesin

Sapla elindeki hançeri artık kalbine

Seni izleyenlerde yıkılsın

F.A. 10.01.2003', 'Sessizlikten önce Sahnenin ortasında çığlık Bir avucunda yalnızlık Diğerinde utandığı ar Bağışla diyor gözleri karanlığa uzanarak Yalvarışla...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ah-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmez Dertlerimi', 'kimse-bilmez-dertlerimi-yusuf-onder-bahceci-zi459', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şiirler onun için,

Sevdiğimi bilmez niçin,

Yanıyorum için için,

Kimse bilmez dertlerimi.

Şimdi seni getirseler,

İşte sevdiğin deseler,

Güzel sözler söyleseler,

Kimse bilmez dertlerimi.

Bugün değil dünden oldum,

Ağlıyorum senden oldum,

Hasretinle deli oldum,

Kimse bilmez dertlerimi.

Sende beni özlermisin,

Bende sevdim dermisin,

Bunu eller ne bilsin,

Kimse bilmez dertlerimi....', 'Bu şiirler onun için, Sevdiğimi bilmez niçin, Yanıyorum için için, Kimse bilmez dertlerimi. Şimdi seni getirseler, İşte sevdiğin deseler, Gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimse-bilmez-dertlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervaneler Karanlıkta Ölür/ F''ye.../ Denememe yazısı', 'pervaneler-karanlikta-olur-f-ye-denememe-yazisi-emine-tansu-pxjsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '/Her sevi gerekçesiz kelimeler doğurur, 

her doğan, sevi’ye seviyesizce mahkum olur/ 

Günlerdir içimde safra, yüzümde çıban bu işaretler. Neyin nesi bilmiyorum. Yıldızlar kadar sürecek mi savaşım? Yoksa içerde mi alacağım soluğu yine? Zindanlara nöbet olmaktan, histeri travması geçirmiş alışkanlıklardan, çöp kutularını karıştırıp durmaktan  sıkıldım. Kendi sokağında yırtık güz aydınları taşıyan kollarım! Nerede kaybettim ben aramadığımı? .. 

Vaveyla... Her baktığımda daha çok özlüyorum adından kovuluşumu... Koparsam, yüzümdeki soğuk izi siler mi? Tiz bir tebessüm, ıslak bir sis serpilir mi günceme? Tesadüfün deliğinden geçirdiğim her iğne suratımda devşirdi pençesini. Dikişli gözlerimi aralayabildim. Etime mıhladığım “ben”cil düğmeleri kavlattım, başımdan kaynar sular döktüm köklerime. Aşağı da karanlıktı yukarısı kadar... Gördüm...

Çirkin kahkahama saplanmış boğuk hüzün! Süngülerini vur yüzüme ya da çatlasın zehrin. Genzimde yanık kozalak kokusuyla yaşamasını da bilirim ben. Çivi çividen alır hıncını; kol kırılır, yen içinde bir yere taşınır lüzumluca. Bu kuyuyu iğneyle çıkardım ben, karanlık çektirmem çıkrığıma... 

İşte o gün –ya da o günden sonra artık- sapsarı bir uzlete düştüm. Saçlarıma esir bir cinayetin ürpertisi, dağlara gömüldüm. Topuğumla ezdim hatırlı hatıraları, kum birikti enseme oluklardan akan sudan, bahanelerden... Yine kendime öldürmüştüm seni. Ateş gibiydi gözlerim, etrafımda yabanıl sarmaşık gazelleri, gariptim... Ben sensizliğe geldim. Nazardan beterdi... Yirmi beş gün boyu, yirmi beş yıldır biriktirdiğim korkuları ambalajlamakla bitti. Kapı aralığından bir kasımpatı geçti. Sen sandım... Döndüm, yokluğun çoğalmıştı... Kaç yüz değiştirdim aynada, kaç turnusol değdirdim suskunluğuma, kaç ışık hızından öteydim, bilme! Duymamak için eğri gidişini, kulaklarımı bir midye kabuğunun içine kilitledim. Mahurda cızırtılı taş plak dönerken, esefle dinledim. Şaşırdım, bunaldım, bilmedin... Müjgan da terke meyilliydi artık gözlerimi... Biliyorum, aramızda zardan duvarlar vardı, tahtadan totemler... Gülünce, gülmezdi iç cebinde gezdirdiğim çocuk, benizsiz kalırdı rıhtımda yakamozlar. Parmaklarımdan nilüferler sızıyor diyorum ben, taşıma suyla yanıyorum ireminde, anlamıyorsun. Böldüm diyorum omzumdan yukarısını, kestim sırnaşık dilimi. Kaldırdım aramızı ikimizden, yuttum hikayemi. Tadı felaketti! 

/Gözlerini yumduğunda memleketin kokmazdım, 

Bundandı bütün sınırlardan dökülmem ıslak kaldırımlara/

Baktığımda anladım. Gemi kopmuş bir tay ağzında kalmış helva ekmek saatleri, kadran suç üstü yakalanmış incir yaprağında dahi. Üstsüz başsız kalmışız üstelik uluorta, aşk önlüğümüze yama! Yer ile yeksan kış ortasında, yanına gidebilmek yanından... tipik bir heyula...

Baktığımda anladım. Siyahtım... Lanetinden bile kilometrelerce uzaktım. Gözünde aç bir tevazu. Kıpırdarsam, vurulacaktım...

Baktığımda anladım. Yüzümde gezinen kelebek rüzgarı değildi, karanlığın değildi üzerimde yanan. Dudaklarımı ısırmam adına nispetti... 

/Görmüyor musun? Unuttum! / 

Terazime kefe oldum, seni doldurdum içine. Hayat bir kıvılcım demiştim. “Doğmadan önce ve öldükten sonraki karanlıkların arasına sıkışmış bir kıvılcım”. Ateş böcekleri ışıkta ölür, pervaneler karanlıkta, anlamadın... Işığıma senin karanlığını örttüm artık, gül tohumlarını söktüm. Baş harfini söylememek için delirdim günlerce. Ayyuka çıktım herkesin ağzından, indim en yüksek sese, argındım. Kente ölü cümleler doğurdum cam kenarlarında; soğuktu, yalnızdım, asayişti üstelik... Kıstım sesimi kulaklarında ve bir gölge boyu uzadım... 

Ben,

giderken de seni götürdüm yanımda,

sıkıca sarındım bakırdan mahmurluğuna tan yerinin.

Sürmedim tünel karanlıklarını,

topal bir ışkındım toprağında yalnızca.

Bulutlardan çırpmıyorum kalbimi hiçbir alkışa,

ya da hiçbir damlaya koşasım gelmiyor artık...

Gözaltımda mosmor “düşünce” ipuçları,

dost bırakmıyor yarınlık...

Ölürsem,

Yanağındaki çukura gömülmek istiyorum,

Vaziyetimdir! 

Mevsimi geldi, kiremitlerde acemi bir zemheri jurnali.

Artık mecalsiz göçüyorum,

Kanatlarımda keçeleşmiş bir uyku ağırlığı, kurşuni

“Aşıp aşıp giden yollar benimdir...”

Git dedin,

kaldım...

Ben bir balabandım, yaralandım

Dağlarda erguvan sesi, çamlarda cır cır böcekleri...

Şah damarım! 

Sana ışık dedim, sömür ağzımdaki utangaçlığı. 

Pervaneler karanlıkta ölür dedim sana,

Anlamadın

Git dedin,

Saatlerce öldüm koynunda...', '/Her sevi gerekçesiz kelimeler doğurur,  her doğan, sevi’ye seviyesizce mahkum olur/  Günlerdir içimde safra, yüzümde çıban bu işaretler. Ne...', ARRAY['Türk Edebiyatı','Şiir','Emine Tansu']::text[], 8.5, '{"poet":"Emine Tansu","poet_slug":"emine-tansu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/pervaneler-karanlikta-olur-f-ye-denememe-yazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim Gaziantepli bestekar-şair Erol Güngör şiiri', 'ogretmenim-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-5lks4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akla dolan bilgileri

            Kalbi saran sevgileri

            Geleceğe sezgileri

            Sizden aldık öğretmenim..

            Çalışmayı, öğrenmeyi

            Başarılar göstermeyi

            Hep doğruyu söylemeyi

            Sizden aldık öğretmenim..

            Her sorunun cevabını

            Eğitimin sevâbını

            Olgunluğun hesabını

            Sizden aldık öğretmenim..

            Anne gibi sevdik sizi

            Baba gibi bildik sizi

            Kalbimizde bulduk sizi

            Son söz sizin, öğretmenim..', 'Akla dolan bilgileri             Kalbi saran sevgileri             Geleceğe sezgileri             Sizden aldık öğretmenim..             Çalı...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogretmenim-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-omer-sirakaya-m96di', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bayram geldi durmam daha.

Ben köyüme gidiyorum.

Size hoşça kalın deyip. 

Ben köyüme gidiyorum.

İbadetim etmek için.

Kurbanımı kesmek için 

Dost ahbabı görmek için

Ben köyüme gidiyorum

Arkama dönüp bakmadan.

Bolu dağında durmadan.

Taşova, Erba,Niksar dan.

Reşadiye''ye  gidiyorum

Bin üç yüzlü rakımlara.

Kekik kokan yaylalara.

Boşa akan pınarlara.

Su içmeye gidiyorum.

Babamın yanna varmaya. 

Bir fatiha okumaya.

Mezar taşın okşamaya.

Ziyarete gidiyorum

Soba yakıp demlen çayı.

Gelir şimdi emmi dayı.

Özlemişim komşuları.

El öpmeye gidiyorum.

Nebişeyh''li Ahmet olsun.

Taşlıcalı Dursun gelsin

Hamza bize et közlesin

Muhabbete gidiyorum.

Yurdumun en güzel yeri.

Ömer için özel yeri.

Genci Bozkurt, kızı Huri.

Hasanşeyh''e gidiyorum.', 'Bayram geldi durmam daha. Ben köyüme gidiyorum. Size hoşça kalın deyip.  Ben köyüme gidiyorum. İbadetim etmek için. Kurbanımı kesmek için  D...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sırakaya']::text[], 8.5, '{"poet":"Ömer Sırakaya","poet_slug":"omer-sirakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gidiyorum-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yekamın*', 'yekamin-fethi-aslan-nev22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşuna mı sevdik,

boşuna mı öptük ölümü gözlerinden

kavganın tam orta yerinde.

Daha açmamışken paptyalar,

doğamamışken Güneş tepelerden,

Baharı bekelerken

Mitralyözlerin  çığlıkları  arasında

yatıp gözlerinin siperine

boşuna mı haykırdım yasaklı sevdamızı.

Bir yaramaz çocuk kurnazlığında

bir o kadar da haşarı.

şimdi yasaklı dillerde yazıyorum duvarlara

yasaklı sevdamızı,

yekamın*.

---

*Birtanem', 'Boşuna mı sevdik, boşuna mı öptük ölümü gözlerinden kavganın tam orta yerinde. Daha açmamışken paptyalar, doğamamışken Güneş tepelerden, Bah...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yekamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-sahin-erturk-ox3gt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gururumu ezdirmem

Senden sevgi dilenmem

Artık senle olamam

Gidiyorum hoşçakal

Bana göre ben haklı

Sana göre sen haklı

Bulamadık orta yol

Gidiyorum hoşçakal

Sözler artık boşuna

Gitmiyorsun hoşuma

Herkes kendi yoluna

Gidiyorum hoşçakal

Katlanamam nazına

Alma beni ağzına

Senden uzak Fatsa ya

Gidiyorum hoşçakal

(04.01.2006)', 'Gururumu ezdirmem Senden sevgi dilenmem Artık senle olamam Gidiyorum hoşçakal Bana göre ben haklı Sana göre sen haklı Bulamadık orta yol Gid...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hoscakal-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu İnsan Göremedim', 'mutlu-i-nsan-goremedim-yusuf-onder-bahceci-3rq6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezdim dağları, taşları,

Ellerde hep gözyaşları,

Mahsun, garip bakışları,

Mutlu insan göremedim.

Gezdim diyardan diyara,

Selam saldım nazlı yâre,

Kalbimizde gizli yara,

Mutlu insan göremedim.

Belki birkaç sahte gülüş,

Seni sevdim hep serzeniş,

Bu nasıl iş, bu nasıl iş,

Mutlu insan göremedim.

Mutluluk ne söyle bana,

Seni sevdim inansana,

Kalbim kırık şimdi sana,

Mutlu insan göremedim', 'Gezdim dağları, taşları, Ellerde hep gözyaşları, Mahsun, garip bakışları, Mutlu insan göremedim. Gezdim diyardan diyara, Selam saldım nazlı ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlu-insan-goremedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıyorum.', 'kiziyorum-muhsin-yener-9gk9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin geldi aklıma.

Az önce de saçların...

Sadece onlar mı?

Aklıma gelmeyen kalmadı bugün.

Sen ve seni hatırlatan her şeye...

Kızıyorum yağmurlara,

Seni bana hatırlatıyor diye.

Öyle ya, sadece yağmurlar mı suçluydu?

Hiç mi suçu yoktu saçlarının,

Bana inat rüzgâra savurttuğun...?', 'Gözlerin geldi aklıma. Az önce de saçların... Sadece onlar mı? Aklıma gelmeyen kalmadı bugün. Sen ve seni hatırlatan her şeye... Kızıyorum y...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kiziyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin gibi... :)) .. :)) . :)) .istiyorum..', 'senin-gibi-istiyorum-nazan-i-zmirli-42nct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...........................gülmek

senin gibi......................

..........................gülmek

seni yaşar gibi.............

..........................gülmek

seni anlatır gibi............

...........................gülmek

ama! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

sensiz............... 

başaramıyorum

ki! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

04.01.2006-antalya', '...........................gülmek senin gibi...................... ..........................gülmek seni yaşar gibi............. ..............', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-gibi---istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görebilesin beni..', 'gorebilesin-beni-taskin-erdinc-gwnuj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim kapalı dilemedim seni,

Kapandığında gözlerimiz,

Gideceğimiz yer aynı aslında,

Ama bulmak zor beni bilirsin,

İhtiyaç duyulan açıkken görmen beni,

Açıkken gözler sevmen beni,

İtirazın neye olsa sarılıp öpmen beni,

İstersen benden dilememi,

Kapamadan o gözlerini,

Dileki Allah''dan görebilesin beni......', 'Gözlerim kapalı dilemedim seni, Kapandığında gözlerimiz, Gideceğimiz yer aynı aslında, Ama bulmak zor beni bilirsin, İhtiyaç duyulan açıkken...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Erdinç']::text[], 8.5, '{"poet":"Taşkın Erdinç","poet_slug":"taskin-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gorebilesin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenisi Olmaz..', 'yenisi-olmaz-taskin-erdinc-q4ihy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl bakarsan öyle görür gözlerin,

İstemedikçe yıldız yoktur gök te,

İstemedikçe deniz yoktur çölde,

Tuttukça elin kanlanır oysa,

Görmediğin diken çokdur gülde,

Nasıl dilersen, öyle olur yarının,

İstemedikçe, güneş yoktur günde,

Dilemedikçe, yarın yoktur dünde,

Anı çoktur, sen diledikce..

Yenisi olmaz, eskiyi bekledikçe...', 'Nasıl bakarsan öyle görür gözlerin, İstemedikçe yıldız yoktur gök te, İstemedikçe deniz yoktur çölde, Tuttukça elin kanlanır oysa, Görmediği...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Erdinç']::text[], 8.5, '{"poet":"Taşkın Erdinç","poet_slug":"taskin-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yenisi-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-zati-erbas-yoiwg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzak bir şehirsin

tuzak

bir

yalnızlık denizinin

ikiye

böldüğü

bıçağın

kemiğe dayandığı gibi

tut

ellerimi', 'uzak bir şehirsin tuzak bir yalnızlık denizinin ikiye böldüğü bıçağın kemiğe dayandığı gibi tut ellerimi...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzak-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Benden Ne İstersin', 'daha-benden-ne-i-stersin-yusuf-onder-bahceci-aehbl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevdim cân bilirim,

Bir gülüşe cân veririm,

Cân veririm, kan veririm,

Daha benden ne istersin.

İşte böyle severim,

Bitmez benim kederim,

Sen gelmezsen neylerim,

Daha benden ne istersin.

Seni sevdim seveceğim,

Senin için öleceğim,

İste cânım vereceğim,

Daha benden ne istersin.

Seni sevdim seviyorum,

Seni sevdim diyorum,

Yavaş yavaş ölüyorum,

Daha benden ne istersin...', 'Seni sevdim cân bilirim, Bir gülüşe cân veririm, Cân veririm, kan veririm, Daha benden ne istersin. İşte böyle severim, Bitmez benim kederim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daha-benden-ne-istersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Varsa..', 'umut-varsa-taskin-erdinc-88uw1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokağı varmı umutların, yoksa çıkmazmı sokakları,

Sokaklarda tükenen umutlar var, umduğuna giden yolda,

Bense bekleyen her çıkmaz sokakta, çıkmaz umutlarla,

Dökülen umutlar sokaklarca, telaşla beklenir toplanmayı,

Bense çöp gibi toplarım, bulmak istercesine umutlarını, 

Sen umutlarını kaybettikçe, ben biriktiririm sokaklarca umutları,

Sokaklar umutları saklar, ben karıştırmışım umutlarımı,

Ben de bir umutsam sence, bir çıkmaz sokakda dökülmüş,

Ben bulurum seni çıkmazında sokakların, çıkmazında umutların,

Sen girdiğinde çıkmaz umutlarınla, çıkmaz sokağıma,

Ben belki de sarılırım, umutlarla çıkmazında sokağının..', 'Sokağı varmı umutların, yoksa çıkmazmı sokakları, Sokaklarda tükenen umutlar var, umduğuna giden yolda, Bense bekleyen her çıkmaz sokakta, ç...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Erdinç']::text[], 8.5, '{"poet":"Taşkın Erdinç","poet_slug":"taskin-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umut-varsa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaydan çıkmış bir okum sevginle bekle!', 'yaydan-cikmis-bir-okum-sevginle-bekle-kamil-soylemez-0aeyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaçıncı iz düşümü adımların 

Bundan öncesi geçenlerin 

Takılıp teközlyip,dikilenin 

Kaçının yarası kabukla saklandı 

Sevrken göz yaşlarını yanağı 

Hangisinde çığlık kaldı.... 

Yaslanıp serinlediği görgeden 

Sesizce bedenine çalarken 

Kimdi bizden önce giden 

Fatih gibi fetihleri yaşayıp bitiren 

Kimin özlemi sevgiliden özel 

Saklamışken yürek telinde 

Hangi makamın sedası boşlukta 

Taş pilaklardan havda kaldı 

Sislimidir tarih gerçekten 

Saklanıp bize sinsice gülen 

Kaç cariye katledilip denize atıldı 

Kaç oğlan sesizce boğuldu 

Senin boğulduğun kadar çokmuydu 

Sömürülüp katledilenin kaçıncı yılıydı 

Tarihe inat ayaktalığın neyin anlamı 

Boylu boyunca boğazmıydı senin olan 

Benim ağlayışımın ardında kalan 

Hangi pranga beni sessizce bağlayan 

Ya özlemin yüzü soğukken 

Tutuşmak neydi sevdiğim 

Bu kadar uzaktan benim pimimi çeken sevdan 

Hangi usulcakları nazardan saklamalı 

Ben allahım bana bağışla derken 

Çıkarttım tüm dünyalıkları 

Şimdi dervişim aşkın ve sevdandan 

Yürüyorum benden öncekilerin izinde 

Yunusun bana seni gerek seni felsefesiyle 

Ne olursun bekle dur deme 

Yaydan çıkmış bir okum sevginle bekle!', 'Kaçıncı iz düşümü adımların  Bundan öncesi geçenlerin  Takılıp teközlyip,dikilenin  Kaçının yarası kabukla saklandı  Sevrken göz yaşlarını y...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yaydan-cikmis-bir-okum-sevginle-bekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Zamanı....', 'gitme-zamani-omer-golge-eir27', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık gitme zamanıdır,gün batımında

İmkansız bir aşktan kaçarcasına

En kızgın anında müsademenin

Yüreği namluya takarcasına

Bu şehri silerek gözbebeğimden

Bütün geçmişimden koparcasına

Gamzelerin olmuş firar sebebim

Gülüşlerin yokluğumun yarası

Gözlerine bakıp bakıp yandığım

Fena deryasına dalarcasına

Artık gitme zamanıdır gün batımında

Mümkünsüz düşlerden kalkarcasına

Saçların, rüzgarın ipekten eli

Benim olmayanı okşarcasına

Bir masal fısıldar İstanbul şimdi

Yıkılmış bir ömrü anarcasına

Her sokak başında nefesin durur

Bir şehir ağlıyor kanarcasına

Anladım yetmiyor bu deli yürek

İmkansız olanı başarmak için

Sevdalar bu yüzden kısa ömürlü

Yoklukla yoğrulmuş masalcasına', 'Artık gitme zamanıdır,gün batımında İmkansız bir aşktan kaçarcasına En kızgın anında müsademenin Yüreği namluya takarcasına Bu şehri silerek...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gitme-zamani-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel ruh-i ravanım,seyrana gelsin', 'gel-ruh-i-ravanim-seyrana-gelsin-ali-riza-unal-nm1dv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine meşk ister bu can canâna,

Aç zülfü nigârın,cevlanâ gelsin,

Sen ile demdedir bu vucut iklimi,

Gel ruh-i meramım,seyrana gelsin,

Nedendir harareti aşk,ten ile kan-a,

Gel-ki bu taç-ı taht hayrana gelsin,

Ezelden hasletim var,leyli-i mihmana,

Gel ruh-i revanım seyrana gelsin..', 'Yine meşk ister bu can canâna, Aç zülfü nigârın,cevlanâ gelsin, Sen ile demdedir bu vucut iklimi, Gel ruh-i meramım,seyrana gelsin, Nedendir...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-ruh-i-ravanim-seyrana-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sana İntihar Ediyorum...!', 'sana-i-ntihar-ediyorum-dilek-egri-1z1qm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana her gidişim bir intihar girişimi./.günahkar..asi..

giydiğim elbisenin iç cebinde../.utangaçlığım gizli..

yüreğimin saati durur sana gelişimde.

ne seni geçer ne beni..

utanmaz bir zaman başlar..

akrep''le yelkovan üstüste..! 

gölge oyunları sarar soğuk duvarları..

sen bedenini giydirirsin bana

birkaç beden büyüktür aşkın..

ama ben inatla büyürüm aşkına...! 

sonkezmiş gibi, 

bir daha sana ölememenin korkusuyla

aşk-ı şahadet getiririm dudaklarının arasında...

utanmaz saatler diner..

vurgun saatler başlar

vurur kaçar..! 

ve nefesim kesilir..

tüm  kahramanlığıyla buselerin beni..

hayata döndürür.! 

pardon..? 

döndürür mü

öldürür..! 

ben gözlerinde çekerim ipimi...! 

şaşırmazsın deliliğime

bilirsin sevgilim; 

/..gömleğinin kolları darağacı olsa

...yine geçiririm boynumu kollarının arasına.../

uyanırım 

rüya biter..

ben seni sevmek için

inadına yaşarım...

04/01/2006', 'sana her gidişim bir intihar girişimi./.günahkar..asi.. giydiğim elbisenin iç cebinde../.utangaçlığım gizli.. yüreğimin saati durur sana gel...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sana-intihar-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarında özgürlüğüm', 'avuclarinda-ozgurlugum-cetin-hacifettahoglu-acz8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimsenin bilmediği yer avuçların

Öfkeni alıp sıkarsın

Sıkarsında acırım

Parmaklarında özgürlüğüm

Aralasan hapis olurum

Açtığında kurtulurum

Kollarına akarım 

Akarımda omuzlarına yük olurum

Silkelersin omuzlarını

Düşerim

Düşerimde

Ayakalarına pranga olurum

Koşmak istersin 

Adım adım çürürüm

Çürütürsün yüreğinde

Çürürümde

Sende kalıp yok olurum', 'Kimsenin bilmediği yer avuçların Öfkeni alıp sıkarsın Sıkarsında acırım Parmaklarında özgürlüğüm Aralasan hapis olurum Açtığında kurtulurum ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avuclarinda-ozgurlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Böyle Özlemedi', 'kimse-boyle-ozlemedi-serkan-er-8scpp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat

sensiz geçen her gün için

yüzüme bir çizgi daha ekliyor.

Ve gün gelip

aynada kırış kırış olmuş suratıma baktığımda

hayatın yüzüme kazıdığı her çizgide

sana olan özlemimin kalıntılarını göreceğim.

- - - - - - - - - - - - -

Ben seni

yüzümün kıvrımlarında saklayıp

gözyaşlarımın oluklarında gizleyeceğim.

O an gelene kadar 

ben hep seni özleyeceğim.

O an geldiğinde

ellerimin titrekliği bitecek

senin için atan yüreğim tükenecek

son nefesim bedenimi terkettiğinde

sana olan özlemlerim dinecek...', 'Hayat sensiz geçen her gün için yüzüme bir çizgi daha ekliyor. Ve gün gelip aynada kırış kırış olmuş suratıma baktığımda hayatın yüzüme kazı...', ARRAY['Türk Edebiyatı','Şiir','Serkan Er']::text[], 8.5, '{"poet":"Serkan Er","poet_slug":"serkan-er","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kimse-boyle-ozlemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter! ..', 'yeter-mehmet-ali-demircan-qdja4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık zor gelmez cana, 

Meleklerim bana YETER. 

Çare, gönül ağrısına, 

Kalpten dualarım YETER.

Bilgilerin kaynağıdır, 

Her derdimin dermanıdır, 

Kitapların temelidir, 

Kuran-î Azim-im YETER.

Peygamberler peygamberi, 

İki cihanın serveri, 

Alemin nurlu güneşi, 

Canım *Muhammed*’im YETER.

Her incelik var içinde, 

*Rabb*’imden armağan bize, 

Alem’ in dini kendine, 

Hak dini İslam’ım YETER. 

*Yaradan*''ı tanımaksa, 

Bir kez içten bak aynaya, 

İşte gerçek tam orada,

Kendini gör, sana YETER.

Çok din vardır şu alemde,

Her kes bir başka beyhude,

İstemem başka ilahe,

Bana tek *Allah*’ım YETER.

Bilmek istersen *Rab*’ ini, 

Görmek istersen kudreti, 

O muhteşem gözlerini, 

Çevir aleme o YETER.

Ne sağı ara ne solu,

Hak kelamını al oku,

O içinde olan ruhu,

Sal ortaya sana YETER.

MAD.', 'Yalnızlık zor gelmez cana,  Meleklerim bana YETER.  Çare, gönül ağrısına,  Kalpten dualarım YETER. Bilgilerin kaynağıdır,  Her derdimin derm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yeter-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma Hiç Bir Gönüle Giremezsin!', 'kusura-bakma-hic-bir-gonule-giremezsin-i-brahim-halil-demir-hxfdm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakmasını bilmiyorsan,göremezsin.

Sevmeyi beceremiyorsan,sevilemezsin.

Açık tutmamışsan yirmidört saat gönül kapını,

Kusura bakma! Hiçbir gönüle giremezsin.

Sadece Allah rızası için vermemişsen,alamazsın.

Sevda gergefinde aşkı binbir şevkle motif motif dukumamışsan,

Demek ki sevda yolunda henüz yolcu olamamışsın.

Sevgi suyunu içmemişsen,sevgi fidanlarını dikemezsin.

Sevda yüreğini yakmamışsa,sevdalanmışın halini anlayamazsın.

Bu uğurda kapı kapı dolaşmamışsan,başkasının yorgunluğunu bilemezsin.

Zemheri ayında sevdanın harareti  seni ısıtamamışsa,

Hakkın yok bu konuda konuşmaya zira yalancı çıkar,rüsvay olursun.

Sevda yayından aşkın oku  isabet etmemişse yüreğine,kan kaybından ölmezsin,

Bu yolda didelerinden yaş dökülmemişse,içten gülemezsin.

İspat etmek için samimiyetini, sevda uçurumlarının en ulusuna çıkmamışsan,

Kusura bakma! Hiç kimseyi kandıramaz ve de inandıramazsın

04/01/2006', 'Bakmasını bilmiyorsan,göremezsin. Sevmeyi beceremiyorsan,sevilemezsin. Açık tutmamışsan yirmidört saat gönül kapını, Kusura bakma! Hiçbir gö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kusura-bakma-hic-bir-gonule-giremezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Ağlarsa', 'gonul-aglarsa-kerem-kayar-jkrzg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece uzaktan seslenirse dün 

Geçmişten gönlüne gelirse bir ün 

İçinde bir yankı yaparsa üzgün 

Gönlümün sesidir, sen duyabilsen 

Geçtiğin yollara yağmur yağarsa 

Dallarda parlayan inciler varsa 

Eline O''nlardan biri damlarsa 

Gözümün yaşıdır, sen silebilsen 

Bir gece bahçende bülbül ağlarsa 

Gönlünde bir yeri ateş dağlarsa 

Ve, O''rda dinmeyen bir sızı varsa 

Kalbimin ağıdır, sen bilebilsen 

Bir şarkı sevgine kanan birinin 

Yıllardır bu yüzden yanan birinin 

Adını ömrünce anan birinin 

Bitmeyen yasıdır, Sen bunu bilsen...', 'Bir gece uzaktan seslenirse dün  Geçmişten gönlüne gelirse bir ün  İçinde bir yankı yaparsa üzgün  Gönlümün sesidir, sen duyabilsen  Geçtiği...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-aglarsa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu Hâlim''dir', 'arzu-h-lim-dir-mevlut-bicik-9xar0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meerbeck’de hizmet aşkıyla tutuşup yanarken

Esslingen’e tayin olundum zamansız ve erken.

Başım gözüm üstüne dedim,tereddüt etmeden gittim

Koştum hizmete gece,gündüz sağlık açısından bittim.

Íhvan,ehavat,cemaatle hiç durmadan koştum

Kalbî birlik,rûhî âhenkle her geçengün coştum.

Yıllarca hizmet hayatımda büyüklerimi hiç üzmedim

Beğendirmek için kendimi,sahte raporlar düzmedim.

Her olumsuz hadiseyle hep kendim üzüldüm

Hizmetin mes’ûliyetiyle dâima ezildim,büzüldüm.

Talebeliğimde,Hocalığımda yıllarca sıkıntı çektim

Bıkmadan! hizmet fidanlarını, gönülcüğüme ektim.

Fakat günün birinde bozulunca sağlığım

Hiç bir zaman kopmadı,büyüklere bağlılığım.

Hizmete devam da bulamayınca sıhhat

Ístifamı verdim.dedim n’olur ya Rab affet.

Derken Esslingen’e yeni bir Hoca verildi

Henüz daha ilk geldigin de yaylar gerildi.

Hiç bir zaman yıldızlarımız birbirine uymadı

Bölge idarecimiz sagolsun hiç bunları duymadı.

Ístemedim daha fazla,  işin teferruâtına inmek

Yaralarım,ağrılarım,sancılarım bilmeyince dinmek.

Tam dört küsür senedir, çektim rûhî iskence

Dayanamayıp sabredemeyip canıma tak edince.

Cesaretimi toplayarak yazdım bir mektup zât-i âlinize

Sümenaltı edilmeden,kaybolmadan tiz geçmiş elinize.

Okudunuz mektubum, demediniz boşver önemsizdir

Nasıl olsa bu hoca hizmet dışıdır görevsizdir.

Ílgilendiniz,kısa zaman zarfında iki hoca gönderdiniz

Eskiden de bilirim! Gerçekten siz şahsiyetli bir önderdiniz. 

Elçiler tarafından alındı elbette ifadem

Bir nebze de olsa rahatladım.Gitti içimden mâtem.

Adam yerine koyulup dinlenmek ne kadar hoşmuş

Bir defa daha anladımki! Hâric-i hizmet olan hayat boşmuş.

Şartlar müsâit olduğunda hizmete hazırım

Emir ve tâlimatlarınıza her zaman nâzırım. 

Bunca meşğuliyetinizin arasında rahatsız ettiğim için sizi

Kusuruma bakmayın.öfkelenmeyiniz mâzür görünüz bizi.

Hizmetlerimizde muvaffakiyetiniz için ederim Rabbime niyâz

Geçmişi unutup,açmaya çalışıyorum bir sahife bembeyaz.

Seviyorum,seviniyorum derdim hakkında gerçekten bilgilendiniz

Hürmetlerimle teşekkür ediyorum bu kardeşinizle ilgilendiniz.

Mevlüt Bicik

02.01.2006   saat 18.13

Esslingen', 'Meerbeck’de hizmet aşkıyla tutuşup yanarken Esslingen’e tayin olundum zamansız ve erken. Başım gözüm üstüne dedim,tereddüt etmeden gittim Ko...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/arzu-halim-dir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-huseyin-ozcan-bb4em', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ey hislerimin tercümanı, içimdeki ferahlık,			

ey hayat yolumdaki en güzel tesadüf üm,			

ey kederli gecelerimin  ay ışığı,			

ey yüzüne baktığımda içimde doğan güneşim,			

ey yüreğimi ısıtan  en alazlı ateşim.			

ey gülümseyince güller açanım,			

ey konuştuğunda ışık saçanım.			

yoluna kurban olayım senin,

canına canımı  vereyim.

sevgili dostum,can yoldaşım,

neredeydin…..nerelerde eylendin.

velhasıl canım,cananım  sen geldin,

geldin, girdin  içime baharlar  serdin,

keder ummanlarındayken çaresiz,

sevinç verdin,neşe verdin,can verdin….

ey güzel dost…..ey güzel insan…..

sen ne iyi ettin de geldin……..

hoşgeldin......', 'ey hislerimin tercümanı, içimdeki ferahlık,			 ey hayat yolumdaki en güzel tesadüf üm,			 ey kederli gecelerimin  ay ışığı,			 ey yüzüne bak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hosgeldin-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyısındayız Hayatın', 'kiyisindayiz-hayatin-mustafa-caliskan-manisa-ggtrm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heves, süs, püs; pis

Kokuyor sanki nefis.

Günah ruhta ur, habis.

Bak şurada son kavis. 

Cürümde olmasın galeyan

Sanki Kıyısındayız hayatın

İdeoloji dediğin de nedir? 

Emin ol kalır tek Ekber-i Bir

Bazen ince, bazen kalın fikir

Yaşamın içerisinde şöyle bir

Esip geçiyor akım, cereyan

Sanki Kıyısındayız hayatın

Derken tükenir de hayatın

Ömrün, gençliğin, baharın 

Kalır, yalnızca ah u fizarın

Silkin, de şöyle; ben varım

Hayal-i Dünya olur hezeyan

Sanki Kıyısındayız hayatın

Azrail denilen yüce sefir 

Ölüm için gelir misafir

Kucağını açacak  bak kabir

Vuslata mani tul-i emeldir

Olmasın son nefeste feveran

Sanki Kıyısındayız hayatın

Kesinlikle böyledir usul 

Gelmeden en son fasıl 

Öz ol, benliğinden sıyrıl

Hakk’a olmak için vasıl 

Aşk ile sarsın bizi heyecan

Sanki Kıyısındayız hayatın', 'Heves, süs, püs; pis Kokuyor sanki nefis. Günah ruhta ur, habis. Bak şurada son kavis.  Cürümde olmasın galeyan Sanki Kıyısındayız hayatın İ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kiyisindayiz-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat nedir ki?', 'hayat-nedir-ki-selma-sengoren-f4bji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir umut mu beklenen geceler

Karanlığın gözyaşları mı gizlenen

Yaşamak mı

Unutmak mı

Yoksa

Hergün ölmek mi? 

Bir kelimenin ucunda gözyaşlarımız

Hayat nedir ki? 

Güne başlarken, 

Umutla tomurcuklanıp yeşeren bir sevinç

Gün biterken, 

Kök salmış bir hüzün.

Ümitlerin,

Ümitsizliğe dönüşmesi mi? 

Bir lokma ekmek için,

Zamanla yarışıp

Acıların derinleşmesi mi? 

Bir türlü çözemedik.

Daha çok küçüksün bebeğim

Yıllar sonra

Sen de soracaksın benim gibi

Hayat nedir ki?', 'Bir umut mu beklenen geceler Karanlığın gözyaşları mı gizlenen Yaşamak mı Unutmak mı Yoksa Hergün ölmek mi?  Bir kelimenin ucunda gözyaşları...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayat-nedir-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba '' ma....', 'baba-ma-huseyin-ozcan-06b0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen yanımdayken,			

aklıma kötü şeyler gelmiyordu hiç.			

ve hiç korkmazdım			

yalnız yatmaktan geceleri.			

			

varlığın yalnız bedenimin değil,			

ruhumunda nöbetçisiydi sanki.			

korkulu rüyalarda görmezdim,			

hissederdim  o sıcak buseni yanaklarımda.			

			

o zaman dönerdim yatağımda,			

o zaman farkederdim			

bir tarafımın uyuştuğunu.			

ve o güzel ellerin hep saçlarımda.			

sen yanımdayken baba''cığım,

hiç korkmazdım yarınlardan,

endişelenmezdim hiç.

şimşekler korkutmazdı beni,

yağmurun asfalt sokaklardaki sesi

ninni gibi gelirdi……

oysa şimdi; 

uyku tutmuyor artık geceleri,

gökgürültüsü uyandırıyor kan ter içinde,

şimşekler amansız korkutuyor.

senin ellerini arıyorum saçlarımı okşayan,

sıcak buseni arıyorum yanaklarımda,

zifiri karanlık gecelerde seni özlüyorum.

alışamadım bir türlü yokluğuna,			

alıştırmadan terkettin bizi.			

senden sonra,			

hiç kimsenin nasihatı senin gibi değil,			

hiç kimsede senin merhametini bulamıyorum.			

bu gün senin günün dü baba''cığım.			

ama sen yoksun………			

ben seni istiyorum…….', 'sen yanımdayken,			 aklıma kötü şeyler gelmiyordu hiç.			 ve hiç korkmazdım			 yalnız yatmaktan geceleri.			 			 varlığın yalnız bedenimin d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/baba-ma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-sezgin-ozpinar-b420l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlu gecelerde,

Islanırım senin için,

Gök gürlediğinde,

Yanımda sen yoksun,

Yalnızım...

Ağladığım gecelerde,

Sokaklara çıkardım,

Seni aramak için,

Yanımda sen yoksun,

Yalnızım...

Sonbahar geldiğinde,

Yapraklar döküldüğünde,

Seni sevdiğimi anladım,

Yanımda sen yoksun,

Yalnızım...', 'Yağmurlu gecelerde, Islanırım senin için, Gök gürlediğinde, Yanımda sen yoksun, Yalnızım... Ağladığım gecelerde, Sokaklara çıkardım, Seni ar...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Özpınar']::text[], 8.5, '{"poet":"Sezgin Özpınar","poet_slug":"sezgin-ozpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizim-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat''oldu...', 'sanat-oldu-ali-baksi-3lae1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kayıp yıllardan gelip,umudun bittigi yerde yenileri yeşertmekti yaşam belkide,tebeşir kokan okul sıralarındaki cocukluğum  geldi aklıma,hocam bir kaktüs cizmişti biz gülmüştük,hocamın beş kardeşinden sonra sanat denilen şey aklımda noktalardan öte virgüller oluşmuştu,babamın her cümlesinde sevgi sanattan gelir derdi,o eski cınar adamı,gezmişti tüm yurdu,yudum yudum anlatışında,sevdim hikayeleri resimleri bakan dünya gözlerini,hep demişti bu gün kendin için ne ögrendin? ? bu gün öğrenmeliydim babam için, geçmişte yaşanmış tarihim içim,yaşadığım güzel dünyanın yüzleri için ögrenmeliydim iliklerimdeki yaşamım için,ögreniyorum her gün kendim için birilerini mutlu etmek degil benimkisi,mutlu olmak için bir cok sebeblerim oldugu için seviyorum,bu dünya insanlarını,kötü de olsa iyide olsa yaşanacak bir ömür bizimki isteyene yüregimiz ortada,bazen kimi şarkılar bazen kimi sözçükler,yaşanmış bir bedeli var bizlere anlatılan,umulmadık bir zamanlarda öyle durgunlaşıyorumki,iliklerimde eski bir aşk sesleniyor bana dogru,kaybedilenler arkamda kendi gerçegimi aramak zorda olsa bakıyorum gelip giden yaşamlara,istedigim el ele sınırı olmayan bir dünya,istedigim cıkarların arada kalmadıgı samimi bir dünya,belki cok istiyorum ama,kimsenin inançını kimsenin lisanını degil benim ki,aşk ı istiyorum durulmuş dalgalarda bir yudum suyla bir dilim ekmekle ne kadar mutlu oldugumu görmelerini istiyorum,binemedigim zaman denilen duragımda,umarsızca sevginin sadakatlerini umuyorum tüm insanlara,sevmek gibi geliyor her dokundugum her konuştugum,sevmek tatında geliyor yüregime baktıgım yüzler baktıgım aynalar,caresizlik umuyor sanki dünya insanlarına,bazen zor diyoruz bezen alay gerçekten hep kaçıyoruz,öyle zamansız geçen yıllarda boş ve avere geçen günlerde durgunlugum dalgalardan öte bulutsu gelir bana,umulmadık mavilerde seviyorum sebebsiz bile olsa, bir cok sebebim olmalı yaşama...', 'kayıp yıllardan gelip,umudun bittigi yerde yenileri yeşertmekti yaşam belkide,tebeşir kokan okul sıralarındaki cocukluğum  geldi aklıma,hoca...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sanat-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye', 'diye-osman-yagar-kgftm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar yılı boş hayelle haşlandım

Belki birgün bana dönersin diye

Bekliye bekliye artık yaşlandım

Korkum rüzgar vurup sönersin diye

Bülbül güle bak gül kime sevdalı

Kimse görmez sende olan endamı

Saran olmaz benim yürek yaramı

Yep yerde bekledim inersin diye

Nasıl feryat etmem yüreğim harda

Himmet edip benim yaramı sarda 

Ne haldeyim hele bir aleme sorda

Sevdan Osman ile anarsın diye', 'Yıllar yılı boş hayelle haşlandım Belki birgün bana dönersin diye Bekliye bekliye artık yaşlandım Korkum rüzgar vurup sönersin diye Bülbül g...', ARRAY['Türk Edebiyatı','Şiir','Osman Yağar']::text[], 8.5, '{"poet":"Osman Yağar","poet_slug":"osman-yagar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diye-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor', 'doktor-ali-kalafat-g0ly1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne oldu Doktor söylesene

Yaşayacakmıyım bileyim 

Ne kadardır kalan ömrüm 

Bir saat de, bir gün de,  üç ay de

Ama ne olur söyle Doktor

Haber verdiniz degil mi Doktor 

GELECEK DEGİL Mİ 

Bir kez olsun gelecek degil mi 

Üşüyorum Doktor 

Bir battaniye daha örtsünler üstüme

Üçüncü battaniye mi Doktor

Örtün olsun 

Hatta bir daha örtsünler 

İçimi bu battaniyeler ısıtmıyor Doktor

Susadım Doktor 

Söyleyin bir bardak su versinler

Yüregimin ateşini söndürür sanıyorum

Soguk olsun Doktor 

Soguk 

Belkide  O nun ateşini söndürür 

O mu dedim Doktor

O kim mi

Bak gömleğimin sol üst cebinde 

Kalbime en yakın bir resim var

O resim O nun resmi Doktor

Güzel mi Doktor söylesene güzel mi

Belki çok güzel degil 

Ama O benim sebebim

O benim SİYAH KELEBEGİM Doktor

Bana da çevir Doktor bende son

Son bir kez daha bakayım 

Yaşarken dünya gözüyle bir melek göreyim

Yaklaştır Doktor

Takatim yok elimi kaldırmaya 

Yaklaştır da iyice yakından bakayım

Gözleri çok güzel degil mi Doktor

Yıldızlar var sanki içinde 

Saçları da güzel degil mi 

Baksana nasılda rüzgara kapılmış

Deniz yosunlarını andırıyor

İyi de O kim mi

Hala neden soruyorsun Doktor 

Anlamadın mı O kim

Anlatmaya benim 

Dinlemeye senin ömrün yetmez Doktor

Ama sen yine de söyle

Ne kadar kaldı sürem 

Yetişecek degil mi beni görmeye 

Onu tekrar görebilecegim degil mi

Elini tutup saçını okşabilecegim degil mi

Zaman ver biraz zaman

Biraz daha yaşamalıyım Doktor

En azından O gelen kadar

Eger olmayabilir diyorsan

Hiç bekletme beni bu acıyla 

Resmini cebime koy

Sonra çek kalbime neşteri

Çek gözüme çek dilime Doktor 

Onu görmeyen gözü

Onu sevmeyen kalbi 

Onu söylemeyen dili ne yapayım

Böyle konuşmayayım mı Doktor

Kandırma beni

Bende biliyorum Doktor

Biliyorum zamanın daraldıgını

Haber vermiştiniz

Yetişebilecek degil mi Doktor

Çok konuşmayayım mı Doktor

Kusura bakma 

Bunca zaman hiç kimseye derdimi acamadım ki

Sadece şimdi konuşabildim

O na O nu sevdigimi bile söyleyemedim Doktor

Sıkıldım Doktor

Bir son sigara  yakıp versen elime

Ama o elime degil 

Neden mi Doktor

O elimi ilk O tuttu Doktor

O tuttu elimi 

Ondan sonra tutmadı elim Doktor

Hayır felçli degil dedim ya 

İLK O TUTTU ONDAN SONRA TUTMADI ELİM DOKTOR

Gelmedi mi hala doktor

Kapıya tekrar bakın ne olur

Dünya gözümle bir kez daha göreyim

Yanıma gelip elimi tutsun

Bir kez olsun CANIM desin SEVDİGİM desin Doktor

Kaldırsınlar şu serumu Doktor

Dayanamıyorum 

Kalbime ondan başka birşey girmesin Doktor

Gözlerim görmüyor 

Resmi tekrar yerine koydun degil mi Doktor

Eger gelmez ise yalnız gitmeyeyim 

Bari bir resmi yanımda olsun

Eger yetişemez ise Doktor

Ne olur ONU ÇOK SEVDİGİMİ SÖYLEYİN

Susmalımıyım aglamayayım mı 

Peki Siz sevdiniz mi hiç Doktor

Kavuşamadıgınız oldumu mesela

Hiç aşk yaranıza pansuman yaptırdınız mı 

Hiç Sevgiyle yanan kalbinizi ameliyata aldınız mı Doktor

Çok soru sordum kızıyorsun biliyorum doktor

Ama kızma 

Son bir şey sorup gidiyorum

PEKİ SİZ NEDEN AGLIYORSUNUZ....:(', 'Ne oldu Doktor söylesene Yaşayacakmıyım bileyim  Ne kadardır kalan ömrüm  Bir saat de, bir gün de,  üç ay de Ama ne olur söyle Doktor Haber ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/doktor-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makber', 'makber-ali-gencay-pr6wk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yazmadım alnıma bu kaderi

Tut elimi çocuk gibi, al götür beni

Unutmalıyım kim nerde ne demiş

Kim çalmış en sevdiğim hayalleri

Yanağımda buruşuk yastık izleri

Koynumda sensizlik, aşk zikirleri

Ansız, anmasız basar karabasan

Yakar ciğerimi, tıkar nefeslerimi

Sen ay yüzlü, toprak tenli sevgili

Aşk gömülü, yüreğindir makberi

Ardımdan ağlarlar belki kalanlar

Bilmezler sensin ruhumun cenneti', 'Ben yazmadım alnıma bu kaderi Tut elimi çocuk gibi, al götür beni Unutmalıyım kim nerde ne demiş Kim çalmış en sevdiğim hayalleri Yanağımda ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/makber-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-osman-yagar-o5rbm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Niye çıktın niye karşıma

Bütün derdi saldın başıma

Zehir kattın tatlı aşıma

Kanım karıştı gözüm yaşına

		Varmı bilmem gerçek seveni

		Seven varmı dostum diyeni

		Ömrüm canım senin diyeni

		Dersin artık bırak peşimi

Osman YAĞAR der bak yoruldum 

Varmak istedim hep kovuldum

Canan diye diye kavruldum

Terk edilen yine ben oldum', 'Niye çıktın niye karşıma Bütün derdi saldın başıma Zehir kattın tatlı aşıma Kanım karıştı gözüm yaşına 		Varmı bilmem gerçek seveni 		Seven ...', ARRAY['Türk Edebiyatı','Şiir','Osman Yağar']::text[], 8.5, '{"poet":"Osman Yağar","poet_slug":"osman-yagar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoruldum-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam ve ben', 'sevdam-ve-ben-osman-yagar-b0cj0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canan diye diye canın vermezsin

Kalkıp neden peşi sıra gitmezsin

Halden hale düştüm neden görmezsin

Ömrüm bitti acep neden gelmezsin

		Olmaz oldu hiçbir şeyim dünyada

		Görmez oldum onu artık rüyamda

		Öldüm ama gözüm kaldı arkada

		Kabre girdim,girsin artık sevdamda', 'Canan diye diye canın vermezsin Kalkıp neden peşi sıra gitmezsin Halden hale düştüm neden görmezsin Ömrüm bitti acep neden gelmezsin 		Olmaz...', ARRAY['Türk Edebiyatı','Şiir','Osman Yağar']::text[], 8.5, '{"poet":"Osman Yağar","poet_slug":"osman-yagar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdam-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep''im', 'zeynep-im-yusuf-ter-qlanz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömürden güller derledim

Güllerle yarış gülüm 

Çiçekleri sana verdim

Sevdalarla barış gülüm

Yeni yılda dostla barışsan

Türkülerle şiirle tanışsan

Boynuma taktığım başsan 

Sevdalarla barış gülüm

Zeynep’im hayal olmadan

Yusuf  Ummana dalmadan

Kuyuları derin kazmadan

Sevdalarla barış gülüm

Yusuf Ter 30.12.05

Saat 15:37 İsviçre 

Not:''sadece şiire yakışan ve kafiyeleri tutan isimleri kullandım. Bu kullandığım isimlerle şiirimin kafiyesi

dışında hiç bir alakam yoktur''

Yusuf Ter', 'Ömürden güller derledim Güllerle yarış gülüm  Çiçekleri sana verdim Sevdalarla barış gülüm Yeni yılda dostla barışsan Türkülerle şiirle tanı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zeynep-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynamıyorum Hayat..', 'oynamiyorum-hayat-ali-orhan-gunaydin-clz7i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oynamıyorum  bir daha senle hayat,

Küsüm işte,

Bu kadarda olmaz, kırılmaz insanın ümidi her işte,

Ver! misketlerimi,

Al! bende ki istediğini..

Küstüm,

Görürsün.

Bir daha istesende,

Senle oynamam ki ...

                     04/01/2006', 'Oynamıyorum  bir daha senle hayat, Küsüm işte, Bu kadarda olmaz, kırılmaz insanın ümidi her işte, Ver! misketlerimi, Al! bende ki istediğini...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oynamiyorum-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudumsun', 'umudumsun-i-lknur-er-7sgy4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurumuş çatlamış topraklarım

Bir damla su ol serpil içime

Açayım sana

Bırak yapraklarım kalmasın içimde

Bırak çıksın hazinelerim kuytularımdan

Bırakma beni sonsuzluğa

Kururum

Nariğim kolay incinirim

Bir kez bükersem boynumu

Kaldırmaya gücün yetmez bir daha

Umudumsun 

Tükeniyorsun bende

Gel çare ol karanlıklarıma', 'Kurumuş çatlamış topraklarım Bir damla su ol serpil içime Açayım sana Bırak yapraklarım kalmasın içimde Bırak çıksın hazinelerim kuytularımd...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umudumsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evcilik', 'evcilik-cengiz-kapusuz-j84uh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varya çocukken 

Hani bir oyun oynardık.

Sen anne olurdun,

Bende baba.

Oysa ki, ikimizde çocuktuk

Ne fark ederdi senin anne,

Benimde baba olmam.

Ama cok güzeldi o rüyaya dalman.

Çöpten Çatallar,

Gazoz kapağından tabak,

Çamurdan ekmek,

Ottan yemek,

Öyle oluyormuş evcilik demek.', 'Varya çocukken  Hani bir oyun oynardık. Sen anne olurdun, Bende baba. Oysa ki, ikimizde çocuktuk Ne fark ederdi senin anne, Benimde baba olm...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/evcilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delice Sevmek', 'delice-sevmek-cengiz-kapusuz-rrieb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek seni ama delicesine.

Yasamak, hayatı paylasmak.

Bu zor yolda gülmek ya da aglamak,

Senin yanında, senin ile ölürcesine

Melekler ağlıyor bu halime.

Sen ise ne ağlıyor, ne gülüyorsun.

Çünkü bu halimi sende biliyorsun.

Gülercesine boşvermişcesine! ! ! ! !', 'Sevmek seni ama delicesine. Yasamak, hayatı paylasmak. Bu zor yolda gülmek ya da aglamak, Senin yanında, senin ile ölürcesine Melekler ağlıy...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/delice-sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Tahtası', 'akil-tahtasi-erkan-arslan-edfcy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir şairin dilindeyken hikaye bulur.

Şair ne dert dinler ne dert dilenmez.

Bu günün döndüğü an şiirlik bir zamandır.

Şiir yüreklerden dökülür serviliklerle...

Mahzenini doldurur,zamanlık ve mekanlık.

Çiğ da nesi gibidir,ben yaşarım dünyayı.

Her açan gül,herdoğan gün,hep ben varım çiçek.

Efendim! Başımda taşırım bütün dünyayı...

Hangi halimle başbaşa kalsam halim benim.

Ben varsam vardır dünya,içinde uyanmalar.

Hangi yüze baksam,hangi suratta ben varım.

Hey yer yüzü! En güzel elbisen bendemidir...

Cevheri işler toprak,fidede cevher verir.

hey miskin kendini devasa gören cüce.

İşlenen cevher olur,o cevher benim delir.

Yazdın mı akıl tahtasına bütün dünyayı...

                                      Mart  1998', 'Şiir şairin dilindeyken hikaye bulur. Şair ne dert dinler ne dert dilenmez. Bu günün döndüğü an şiirlik bir zamandır. Şiir yüreklerden dökül...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akil-tahtasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Ne Haber', 'senden-ne-haber-yusuf-onder-bahceci-htk2c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sözümde duruyorum,

Seni sevdim soruyorum,

Rüya gördüm yoruyorum,

Acep senden ne haber.

Sen sözünde dururmusun,

Beni arar bulurmusun,

Kötüler Allah''ından bulsun,

Acep senden ne haber.

Senden haber bekliyorum,

Hiç uğraşma gitmiyorum,

Ömrüm heder ediyorum,

Acep senden ne haber.

Sitem etme no''lur bana,

Darılırım sonra sana,

Yaman sevdim anlasana,

Acep senden ne haber....', 'Ben sözümde duruyorum, Seni sevdim soruyorum, Rüya gördüm yoruyorum, Acep senden ne haber. Sen sözünde dururmusun, Beni arar bulurmusun, Köt...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-ne-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana..', 'ana-melih-baki-khobl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''kavgada çocuklarını yitirmiş tüm analara''

Tabuta kapanmış.! 

Fedakar ana..

Sil gözyaşlarını bak etrafına,

Yaşam durmuş

Saygı sana...

Bak şu bereketli toprağa,

Düşen yağmura,

Bu gün verdiğin tohum,

Umuttur yarınlara...

Binlerce nar çiçeğini

Kır çiçeğini

Gömdük toprağa..

Hepimiz,

Umutluyuz,bekliyoruz..! 

Toprak gebedir bahara...

Tabuta kapanmış

Gözü yaşlı ana

Sil gözyaşlarını 

Bak etrafına...

Cenaze değil o...

Tabut değil  o...

Umuttur tohumdur..

Gömülecek toprağa

1976 Nisan İstanbul

Melih Baki

(Ağla yüreğim Dağlar da Ağlar şiir kitab.Karahan yay.2005.Adana)', '''kavgada çocuklarını yitirmiş tüm analara'' Tabuta kapanmış.!  Fedakar ana.. Sil gözyaşlarını bak etrafına, Yaşam durmuş Saygı sana... Bak şu...', ARRAY['Türk Edebiyatı','Şiir','Melih Baki']::text[], 8.5, '{"poet":"Melih Baki","poet_slug":"melih-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ana-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç çocuk', 'utangac-cocuk-baki-sulopasa-ahcuq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşamla beraber...

Karanlık basar; geceye uzanır...

Siyahın sessiz örtüsü.

Ortalıkta bir masumiyet; 

Kadınlar şimdi daha güzel! 

Utangaç çocuğa cesaret geldi; 

İçki içip, tur aracak,

Kızlara sarkıp, pas atacak,

Olmazsa...

İçini dökecek arkadaşına.

Asıl bir daha! utangaç çocuk.

Sandığın kadar güzel değil; 

O Kız, naza çekmez! 

Ortalıkta bir masumiyet...

Kadınlar şimdi daha güzel!', 'Akşamla beraber... Karanlık basar; geceye uzanır... Siyahın sessiz örtüsü. Ortalıkta bir masumiyet;  Kadınlar şimdi daha güzel!  Utangaç çoc...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/utangac-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurmu', 'olurmu-omer-arslan-ic0nm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rabbimin huzuruna gelmeyince

	İnsanların yüzünde nur olur mu 

	Yunus gibin de  çile çekmeyince

	Odun taşıyan herkes pir olur mu

	

	Her nefeste adını anmayınca

	Hak şerbetini içip kanmayınca

	Allah ın ateşiyle yanmayınca  

	Her yanan İbrahim’le bir oluru 			

	

	Silki kalbinden tutsaklık pasını

	Duy kulağınla Mevla nın sesini

	Kopar kır şeytanın kelepçesini

	İpini koparan herkes hür olur mu

	Allah için göz yaşını  dökmezsen

	Hayrı hasenatı kalbe ekmezsen

	Hakkı ararken kendin yitmezsen

	İnsanlar İsa gibi sır olur mu

	

	Boşa arama yüreğinde yaran

	Geçmez ki  mahşerde altınla paran

	Bin bir kolla sarsa da seni saran

	Hiç Muhammet gibi yar olur mu', 'Rabbimin huzuruna gelmeyince 	İnsanların yüzünde nur olur mu  	Yunus gibin de  çile çekmeyince 	Odun taşıyan herkes pir olur mu 	 	Her nefes...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olurmu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-i-smail-arslan-8o87l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kısarak baktığım güneşte 

Güneşi sarmak isteyen bulutta gördüm

Gökyüzünde,göç eden kuş katarlarında

Uzaklara kanat çırpan turnada gördüm

Sonsuz hayallerin karanlık boşluğunda

Kör kuyunun ulaşılmaz derinliğinde 

Büyük uçurumun hemen yanıbaşında

Bulanıkça akan azgın sularda gördüm.

Dolaştım şehrin büyük kalabalığında

Ayaklar dolaştı,her attığım adımda

Kan olmazki benim meçhul yaralarımda

Sokakta,caddede,kaldırımlarda gördüm

Bu hayatın çıkılmayan bataklığında

Ne bir düşünce kaldı,ne fikir aklımda

Karanlığa gözümü dikip baktığımda

Yıldızları,güneşi,maviliği gördüm

Ceylan bakışlı,abanoz saçlıyı gördüm.', 'Gözlerimi kısarak baktığım güneşte  Güneşi sarmak isteyen bulutta gördüm Gökyüzünde,göç eden kuş katarlarında Uzaklara kanat çırpan turnada ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gordum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayan-ı faş eder cuş-um,avaz eyleme beni', 'ayan-i-fas-eder-cus-um-avaz-eyleme-beni-ali-riza-unal-ubb2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasletim ey canân,sana meylim sendendir,

Şimdi hasretim sana,bu ayrılık nedendir,

İtirafım var ayan,hata, günâh bendendir,

Bu visâle düçâr,nâlan eyleme beni.

Şaşı eden bu kesretin,nuş-u demdendir,

Nerde halvetim sana,bu gayrılık nedendir,

Aklı bi çareyim,bu mecnunluk bendendir

Ayan-ı faş eder cuş-um, avaz eyleme beni …', 'Hasletim ey canân,sana meylim sendendir, Şimdi hasretim sana,bu ayrılık nedendir, İtirafım var ayan,hata, günâh bendendir, Bu visâle düçâr,n...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayan-i-fas-eder-cus-um-avaz-eyleme-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıtma Beni Yaşam', 'acitma-beni-yasam-zeliha-bicer-yx83x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acıtma beni yaşam

Koparma beni dalımdan

Öyle hafif 

Öyle savunmasızım ki

Bu gece

Kayar ayağım buzdan

Esen rüzgar 

Koparır beni dalımdan

Esme be rüzgar

Bu gece esme

Efkarlıyım martılarım

Hüzün yüklü bulutlarım

Ağlamak isterim

Ağlayamam

Yüreğimin yükü var

Aklımın doğrusu

Yürüdüğüm yolun taşları

Açtığım kapımın anahtarı

Hep sen

Sen işte

Gelişlerin sevinç

Gidişlerin yaş

Dayan şimdi işte

Dayan gidişlere..', 'Acıtma beni yaşam Koparma beni dalımdan Öyle hafif  Öyle savunmasızım ki Bu gece Kayar ayağım buzdan Esen rüzgar  Koparır beni dalımdan Esme...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acitma-beni-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmamak', 'unutulmamak-mehmet-ayhan-gunaydin-d1qhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UNUTULMAMAK

Teker teker göçüyor insanlar.

Unutuldular, unutuluyorlar,

Unutulacaklar…

Hayırla yad ediliyor, sade

Şu gök kubbe de,

Hoş bir seda bırakanlar.

Şairlik kim, ben kim? 

Haddim değil, değilim.

Tuttum. 

Bir şeyler karaladım.

Oturdum. 

Yazdım.

Bel ki bir gün.

Olur da çıkar bir gün.

Okuyup da sevecek,

Olsa da tek kişi için.

Hayırla yad edilmek,

Bel ki, rahmet dilenmek.

Tek korkum unutulmak,

Unutulmamak için.

M. Ayhan Günaydın.

      2 Ocak 2005

          Ankara', 'UNUTULMAMAK Teker teker göçüyor insanlar. Unutuldular, unutuluyorlar, Unutulacaklar… Hayırla yad ediliyor, sade Şu gök kubbe de, Hoş bir sed...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutulmamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B ü l b ü l', 'b-u-l-b-u-l-gulsen-senderin-o6oa3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbülün çilesi bu, dillerde öyküsü var

Göğsünü kanatırken  onca diken onca gül

Israrlı bu feryadın, her seher türküsü var

O gül ki kokusunda, aşkla demlenir gönül.

Yalnız senin kalbinde yanmaz bu harlı sevda

Gizemli gecelerden, kavuşur güne dünya

Gül goncasında umut, bin bir emel ve hülya

O gül ki kokusunda, aşkla demlenir gönül.

Altın kafesin olsa, gününü gün etmeye

Yüreğin yine kanar, gül dalında ötmeye 

Gönlünde bir tek efkâr, aşkını fethetmeye 

O gül ki kokusunda, aşkla demlenir  gönül.

Gülşen kızıllığında, feryadın neden bülbül

Bahar şarkısı söyle, şenlenerek eğlen gül

Dikeni kanatsa da,aşka hep devadır gül

O gül ki kokusunda, aşkla demlenir gönül.', 'Bülbülün çilesi bu, dillerde öyküsü var Göğsünü kanatırken  onca diken onca gül Israrlı bu feryadın, her seher türküsü var O gül ki kokusund...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/b-u-l-b-u-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan Sevgiliye', 'gardiyan-sevgiliye-mehmet-cengiz-1z91j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hey gardiyan 

bırak beni çıkayım

kanatlanıp uçayım

sevdiğime kavuşayım

özgürlüğü bende soluyayım

bırak beni de çıkayım

kırçiçeklerinden, papatyalardan

melegimin saçına taç yapayım

biliyorum be gardiyan

elinde olsa bırakırsın

sen de bendeki yürekten taşırsın

beni düşündükçe ağlar, ağlarsın

bırakmasanda bende CANSIN

Mehmet Cengiz

(mayıs 2005)', 'hey gardiyan  bırak beni çıkayım kanatlanıp uçayım sevdiğime kavuşayım özgürlüğü bende soluyayım bırak beni de çıkayım kırçiçeklerinden, pap...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gardiyan-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar-Yollar', 'yillar-yollar-ahmet-bektas-hzvy0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzanır sonsuza gider,

Yıllar soldurur,ayırır yollar.

Gün gelir elbet biter,

Yıllar ve yollar.', 'Uzanır sonsuza gider, Yıllar soldurur,ayırır yollar. Gün gelir elbet biter, Yıllar ve yollar....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yillar-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-hulya-kandemir-bomxa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlık, hasret bir de sen…

Uzaklarda unutulmayı bekleyen anılar gibisiniz.	

Hatırlandıkça canımı acıtıyor varlığınızı hissetmek

Ama yine de silinmiyor aklımdan

Yalnız gecelerde hasretle seni sevmek! 

Çaresizlik, umutsuzluk bir de ben…

Nereye gideceği belli olmayan yolcular gibiyiz.

İmkânsız görünse de adresi bilmek,

Silinmiyor aklımdan

Çaresizlik içinde, umutsuzca seni sevmek', 'Yalnızlık, hasret bir de sen… Uzaklarda unutulmayı bekleyen anılar gibisiniz.	 Hatırlandıkça canımı acıtıyor varlığınızı hissetmek Ama yine ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-ben-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettik', 'kaybettik-ertan-akbayrak-6mav4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mahur bakışlıydı,parıldayan gözleri vardı...

Uzaklaştı hep, ben gözlerine daldıkça...

Aldandı büyük şehrin sıcağına...

Zerre bırakmadı,avuç avuç çaldı yüreğimden...

Zamansızdı gidişi,belkide veda...

En güzelini yaşadı belki; 

Zamansız gidişlerin...

İmkanı yoktu belkide, bir daha geri dönmenin...

Korkularını yenemedi büyük şehir...

Ağladı...sabahladı...dayanamadı...

YÂR...! diye uyandı kâbuslardan kaç kez...? 

Bulamadı yanında,olmayan yastığına sarıldı...

Erteledi hep yarınları ve baharları...

Tutamadı elinden sevdanın...

Tanıyamadı aynalarda kendini...

İstanbul ona dar geldi...

Kaybetti YÂRİ...yarınını kaybetti...', 'Mahur bakışlıydı,parıldayan gözleri vardı... Uzaklaştı hep, ben gözlerine daldıkça... Aldandı büyük şehrin sıcağına... Zerre bırakmadı,avuç ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Akbayrak']::text[], 8.5, '{"poet":"Ertan Akbayrak","poet_slug":"ertan-akbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaybettik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-hulya-kandemir-bilrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanım ateşten rüzgâr, diğer yanım huzura köle

Yarınlara umutla bakabilmeyi düşlerken

Geleceği karanlık sokaklarda aramak

Ve dönüp dolaşıp aynı çıkmaza saplanarak

Yabancı yollarda kaybolmak

Başka dünyalarda yürürken, kendini unutmak

Unutmak yaşamaya dair her şeyi.

İnsan olmayı ve hayaller kurmayı belkide…

Sevdayı ellere verdik 

Her istediğimizde yanımızda olacağını sanarak

Oysa hiç düşünmedik

Onu ömür boyu bulamayan fakirleri', 'Bir yanım ateşten rüzgâr, diğer yanım huzura köle Yarınlara umutla bakabilmeyi düşlerken Geleceği karanlık sokaklarda aramak Ve dönüp dolaşı...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmak-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-hulya-kandemir-gm9ki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Git daha fazla sevdirmeden

Gönlümdeki ateşi alevlendirmeden

Canımdan öte can olmadan git.

Hayatı seninle düşlemeden,

Bir ömrü yoluna sermeden git.

Dertler bir iken bin olmadan

Sevdan ile yaralarım sarmadan git.

Çıktıkça yorulduğum bitmeyen yokuşum,

Acın ile ölmeden git.', 'Git daha fazla sevdirmeden Gönlümdeki ateşi alevlendirmeden Canımdan öte can olmadan git. Hayatı seninle düşlemeden, Bir ömrü yoluna sermede...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/git-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlerin Bittiği Yer', 'sozlerin-bittigi-yer-hulya-kandemir-tq480', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sözlerin bittiği yerdeyim

Ne sesler var ne de ışıklar

Tükenmiş burada hayatlar

Başka bir âlemdeyim. 

Bu gece söndürmeyin ışıkları

Aydınlatsın lambalar kör karanlıkları

Sözlerin bittiği yer aldı tüm umutları

Düşlerin görülmediği yerdeyim.', 'Sözlerin bittiği yerdeyim Ne sesler var ne de ışıklar Tükenmiş burada hayatlar Başka bir âlemdeyim.  Bu gece söndürmeyin ışıkları Aydınlatsı...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sozlerin-bittigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıl Dönümü', 'yil-donumu-hulya-kandemir-q4hcy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel daha fazla bekletmeden.

İçimde yanan ateşini söndürmeden gel.

Sensizliğin yıl dönümünü yaşarken

Sensiz geçen zamana küsmeden gel.

Uzayan yolları adımlarken

Dünlerimi unutamadan yarınlara bakarken

Bitmeyen hüzünleri bir bir sayarken

Hayata gülmeyi unutmadan gel.', 'Gel daha fazla bekletmeden. İçimde yanan ateşini söndürmeden gel. Sensizliğin yıl dönümünü yaşarken Sensiz geçen zamana küsmeden gel. Uzayan...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yil-donumu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayri Kabili Rücu Yahut Yar Yar Yar', 'gayri-kabili-rucu-yahut-yar-yar-yar-mehme-arslan-e5xes', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dönüşü yok artık bu yolun

tıpkı plastiğin 

doğada dönüşümü olmadığı gibi

seni bana hatırlatan kelime

aramızdakileri anlatıyor artık

yarimdin

aramıza yarlar girdi

yarım kaldım şimdi

04/01/2006', 'dönüşü yok artık bu yolun tıpkı plastiğin  doğada dönüşümü olmadığı gibi seni bana hatırlatan kelime aramızdakileri anlatıyor artık yarimdin...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gayri-kabili-rucu-yahut-yar-yar-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-murat-onat-yoat3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne hastanın gözlediği tabibim

Ne ıssız çöllerde yeşil bir vaha

Melanetlerle dolu bu kalbim

Kötüyüm, bildiğinizden çok daha

Ne denizcinin kayıp karasıyım

Ne bir çocuğun eşsiz mutluluğu

Yalnız nefsimin maskarasıyım

Kaybettim o saf, kutsal duruluğu

Ben küsufların korkunç karanlığı

Ben yalnızlık, sefalet girdabı

Ben esir ruhların cinnet çığlığı

Ben şeytanın şatafatlı mihrabı

1995', 'Ne hastanın gözlediği tabibim Ne ıssız çöllerde yeşil bir vaha Melanetlerle dolu bu kalbim Kötüyüm, bildiğinizden çok daha Ne denizcinin kay...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-230-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Öldür Beni Sen Ey Sevgili', 'sen-oldur-beni-sen-ey-sevgili-kamil-soylemez-q3ui8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ay yüzlü,beyaz tenli sevgili

Sen yakıp,tutuşturdun yüreğimi

Sen şaşırttın sen, aşkın ile feleğimi

Şimdi geceyim,her yanım zemheri

Sen ay yüzlü,beyaz tenli sevgili

Sen aşkın,yüreğimde bilki hançeri

Sen çekip,çıkartmasan sen ah sen

Bilki tez elden,yok edeceğim kendimi

Sen ay yüzlü,beyaz tenli sevgili

Sen tut,tuta ellerimden getir beni

Sen kuş edip,cennetine uçurt beni

Sen yücelt,sen yüreğinde, yüreğimi

Sen ay yüzlü,beyaz tenli sevgili

Sen güldür sen,şu garip yüreği zengini

Sen gonca et,sen gül et günlerimi

Sen öldür sen, gelmeyeceksen beni', 'Sen ay yüzlü,beyaz tenli sevgili Sen yakıp,tutuşturdun yüreğimi Sen şaşırttın sen, aşkın ile feleğimi Şimdi geceyim,her yanım zemheri Sen ay...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-oldur-beni-sen-ey-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerin Buluştuğu Yer', 'duslerin-bulustugu-yer-hulya-kandemir-5mu8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düş bahçesindeyim

Burada çiçekler alev kırmızı

Her bir çiçek gönlümün hırsızı

Bitmeyen alevler yanar düş bahçesinde

Hepsi düşlerin çıkmazı…

Bir düş bahçesindeyim.

Gökyüzü alabildiğine mavi,

Özgürce uçan uçurtmalarla dolu…

Burada belli değil 

Ne gecenin ne de gündüzün sonu…

Bir düş bahçesindeyim

Her sabahı yağmurlu

Bir düş bahçesindeyim

Nerede olduğu bilinmez,

Ne başı belli ne de sonu…', 'Bir düş bahçesindeyim Burada çiçekler alev kırmızı Her bir çiçek gönlümün hırsızı Bitmeyen alevler yanar düş bahçesinde Hepsi düşlerin çıkma...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duslerin-bulustugu-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınadaki Gemi', 'firtinadaki-gemi-hulya-kandemir-ov847', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınadan çıkmış gemiler gibisin

Ardında bıraktıkların alabora olmuş

Sen, verdiğin mücadele ile kazanmışsın

Enginliklerde yüzmeyi…

Ellerinden aldın hayatta kalmak isteyenlerin canını

Ve bir avuç gözyaşı verdin her birine

Avunsunlar diye…', 'Fırtınadan çıkmış gemiler gibisin Ardında bıraktıkların alabora olmuş Sen, verdiğin mücadele ile kazanmışsın Enginliklerde yüzmeyi… Ellerind...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/firtinadaki-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hulya-kandemir-ad2fi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerdesin sessizliğimi ayağa kaldıran fırtına,

Nerdesin kulaklarımı sağır edecek çığlık! 

Görmek istiyorum mum ışığındaki pencereden koca dünyayı

Bakmak istiyorum loş sokakların belirsiz ayak izlerine

Ruhumun dinginliğini bir köşeye fırlatmak

Ve haykırmak istiyorum kahpe dünyaya

Ne gerek vardı seninle yaşamaya!', 'Nerdesin sessizliğimi ayağa kaldıran fırtına, Nerdesin kulaklarımı sağır edecek çığlık!  Görmek istiyorum mum ışığındaki pencereden koca dün...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/isyan-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Silintili Bulanık Geçmiş Yaşamlar', 'unutulan-silintili-bulanik-gecmis-yasamlar-hakki-hakan-kaya-laxjq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ölüm 

beni 

ve beni tanıyanları da aldığında 

sanki 

hiç var olmamış gibi olacağım... 

silinip 

üstüne 

yeniden yazılan 

yazılar gibi', 'ölüm  beni  ve beni tanıyanları da aldığında  sanki  hiç var olmamış gibi olacağım...  silinip  üstüne  yeniden yazılan  yazılar gibi...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutulan-silintili-bulanik-gecmis-yasamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-hulya-kandemir-giur1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'El salla bebeğim gökyüzüne

Tatlı gülüşün ulaşsın her bir maviliğe

Karanlıktan ürkme bebeğim,

Yüzünü dön güneşe…

Umut ek toprağa bebeğim,

Filizlensin yüreğindeki sevgiler.

Tutsak etme düşüncelerini,

İçinde büyüttüğün çiçekleri ezdirme bebeğim.

Dürüst ol, yürü hep doğruluğa

Zorluklardan yılma bebeğim.

Korkmak değiştirmez gerçekleri

Bildiğin yoldan dönme bebeğim.

Zannetme ağlamak küçük düşürür adamı.

Her bir acı büyütür insanı.

Dününü bilmeyen, göremez yarını.

Hüzün ve mutluluk kardeştir bebeğim.', 'El salla bebeğim gökyüzüne Tatlı gülüşün ulaşsın her bir maviliğe Karanlıktan ürkme bebeğim, Yüzünü dön güneşe… Umut ek toprağa bebeğim, Fil...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bebegim-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sitem', 'sitem-hulya-kandemir-md2ea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bende kalmadı benimle yitirdiklerin

Her birini sensiz yağan yağmurlara verdim.

Bende kalmadı eski ben; 

Sensizlikte yitip gittim.

Şimdi sensiz geçen zamanı tadıyorum.

Biraz limoni biraz da acı…

Bazen dalıp gidiyorum uzaklara, 

Sebebim başımın tacı.', 'Bende kalmadı benimle yitirdiklerin Her birini sensiz yağan yağmurlara verdim. Bende kalmadı eski ben;  Sensizlikte yitip gittim. Şimdi sens...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sitem-750-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kaç Para Eder', 'ask-kac-para-eder-kamil-soylemez-9huae', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşık olmak........

Çokmu kötü diye sorma

Aşık olmayan hamlara

Yanmayı ne bilsin ki

Mevlayı görmeyen......

Yüreği yanmayan insanlara', 'Aşık olmak........ Çokmu kötü diye sorma Aşık olmayan hamlara Yanmayı ne bilsin ki Mevlayı görmeyen...... Yüreği yanmayan insanlara...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-kac-para-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Ya', 'sen-gittin-ya-mehmet-cengiz-zus0z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir tufan yaşadı ki gönlüm

Nuh kıskandı....

Sen gittin ya

Sevda şiiri yazmaz oldu kalemim

Gurbet oldu sanki vatanım

Sen gittin ya

Sanki...

sanki,Turan''ın son kalesindeki sancak düştü

Vatanım...

Ah...Vatanım gurbet, yüreğim mülteci oldu

Sen gittin ya...

Arkadaş oldum rüzgarlara yellere

Bazen ölümü...

Ölümü hissetsemde ensemde

Yinede yılmadım, büyüttüm sevdamı içimde

Sen gittin ya...

Giderken,

Bir beni alamadın benden

Oğuz soyuyum, Türkün oğluyum ben,

Nesl_i Asım''ım dönmek yok! 

Aşkın, yüreğimde çelikten bir demet

Azalmak, kısalmak, tükenmek yok

tükenmek yok.

Mehmet  cengiz

  (mayıs 2005)', 'Öyle bir tufan yaşadı ki gönlüm Nuh kıskandı.... Sen gittin ya Sevda şiiri yazmaz oldu kalemim Gurbet oldu sanki vatanım Sen gittin ya Sanki...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-gittin-ya-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlayan', 'caglayan-belgin-turan-6wztv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağlayan

O gözlerden süzülen birkaç damla yaş değil,

Usanmadı sevmekten ki bu yürek taş değil,

İçim de durulmayan O sanki bir çağlayan,

Nazlı yarim olmadan gönlüm inan hoş değil.

 Belgin TURAN		19.11.2005

''Güzden Önce Aşktan Sonra'' adlı şiir kitabımdan alınmıştır.

Gündüz Kitabevi Yayınları

Demet 7. Sokak No:7/b

Yenimahalle/Ankara', 'Çağlayan O gözlerden süzülen birkaç damla yaş değil, Usanmadı sevmekten ki bu yürek taş değil, İçim de durulmayan O sanki bir çağlayan, Nazl...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/caglayan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynuma Sar...', 'boynuma-sar-i-brahim-ethem-bingul-7481i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir varmış, bir yokmuş

Diye başlar masallar

Hep güzel kavuşmalarla sonlanırlar

Dinleyin bakın bir bilseniz

Ayrılığın soğuk elleri yürek yakan fırtınalar...

Acılı bir tebessüm şimdi gülüşlerim

Çizginin sonuna düştü düşlerim

Hasret çölünde kaybolan mecnunum

Nefesin olmadan soluk almaz yüreğim...

Gelemedi, bari gel dese yâr

Çağırmadan gidemem, sözüm var

Şu dağlar, bayırlar feryadıma dar

Yeter, vuslat müjdesini yâr boynuma sar...

www.iebingul.com', 'Bir varmış, bir yokmuş Diye başlar masallar Hep güzel kavuşmalarla sonlanırlar Dinleyin bakın bir bilseniz Ayrılığın soğuk elleri yürek yaka...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/boynuma-sar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delirmez misin?', 'delirmez-misin-veysel-alkan-ah280', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç aydınlık değildir, şimdi geceler.

Işığın yeterli mi,karalmazmısın? 

Kafanı yormadı mı bunca çileler? 

Anladın ya hatanı,daralmazmısın? 

Delice yaşadıksa bu büyük aşkı.

Hatırası kalmıştır,ezilmezmisin? 

Çaldığında radyoda sevdiğim şarkı.

Dinlerken ağlayıpta,üzülmezmisin? 

Yastığın boştur şimdi,odalar renksiz.

Sıcaklığım kaldı mı,üşümezmisin? 

Yatağında yorganın,yüreğin bensiz.

Taşırken yanlızlığı,delirmezmisin?', 'Hiç aydınlık değildir, şimdi geceler. Işığın yeterli mi,karalmazmısın?  Kafanı yormadı mı bunca çileler?  Anladın ya hatanı,daralmazmısın?  ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/delirmez-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil yolculari', 'kandil-yolculari-ayla-efe-21s2q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KANDIL YOLCULARI

Gündüz güneş donuk kalır

Gece yıldızlar sönük kalır

Onların nuru âlemi alır

Secdedeyken kandil yolcuları.

Sabahları zikir işleri

Onların hep hayırdır basları

On sekiz âlemin düşleri

Olmaktır kandil yolcuları

Yönleri hep hakka doğru

Kimi aradı kimi sordu

Huzuru sadece sende buldu

Nur oldu kandil yolcuları

Çok versen sevinmezler

Az verirsen yerinmezler

Yüzünü kimseye çevirmezler

Senden başkasına kandil yolcuları.

Ben derim yane yane

Sadece sendedir çare

Yolunda giden yanar nara

Aydınlıktır kandil yolcuları.', 'KANDIL YOLCULARI Gündüz güneş donuk kalır Gece yıldızlar sönük kalır Onların nuru âlemi alır Secdedeyken kandil yolcuları. Sabahları zikir i...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kandil-yolculari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen gün', 'beklenen-gun-vahan-i-saoglu-5wn33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BEKLENEN GÜN

Beklenen günlerin geçmeyen saniyelerini sayıyordu.

Tarifsiz bir heyecan diyarından gelen hızlı kalp atışları misafiriydi yüreğinde bugün.

Lezzetli melodilerin göz kararı bekleyişlerine inat olacaktı gözyaşları, biliyordu.

Ne soğuğun uyutası okşaması, ne de etraftakilerin acır bakışları etkileyecekti.

Az sonra bitecekti her şey, hiçbir şey engel olamayacaktı.

Bitmeyen bekleyişlerin çıkmaz sokağında yankılandı ayak sesleri,

Alkışların süslediği bir arenanın yalnız matadoruydu bakışları,

Yağmurlarını tüketen bulutların onurluca arkasını dönüp gitmesini görüyordu gökyüzünde,

Umutsuzluğun yollarını çok eskitmişti beklerken,

Şimdi ise beklediği, bir kilit kadar yakındı, 

Yıllara inattı bu bekleyişin adı, karanlığa yapılan nispet.

Her sigaranın tükenmesinden sonra daha iyi anlaşılıyordu pakettekilerin sonsuzluğu.

Bitmeliydi artık bu bekleyiş, dayanamayacaktı bu ağır yüklü yolcu,

Beklenen anın gelmesinden daha uzun sürmüştü bu kör bekleyiş.

Yoksa gelmeyecek miydi, hayır bu olamazdı.

Söz vermişti, unutmazdı, unutamazdı.

Ağır çekilmiş bir sahnenin kımıldamayan figüranlarıydı akrep ile yelkovan.

İlerlemiyorlardı...

Cevapsız mektupların sahibi hala gelmemişti, bekletilmeyi sevmiyordu...

Zil sesini duymuş bahçeye çıkan çocukların koşuşlarını hissediyordu yüreğinde.

Hadi artık diye yalvarası geliyordu ama kime yalvaracağını bilmiyordu.

Bu gelişin dönüşü olmayacaktı, onu ya alacak ya da alıp gidecekti.

Hayatının kadını geldiğinde güzel görünmeliydi,

Derin alın çukurlarını kamufle etmeye çalışan mesaisi bitmiş işçiler gibiydi parmaklar.

Bırakıp gidemeyeceği nadir bekleyişiydi, 

Dağınık saçların beyazları çoğalıyordu,

Bitmeyecekti bu bekleyiş.

Ufuk çizgisine asla ulaşamayacaktı...

Umutların yorgunluktan yığılmak üzere olduğu vakit açıldı kapı...

Gözler kilitlendi o aşkın giriş tüneline,

Hayallerin, umutların sahibiydi gelen,

Ölüm sessizliğinin canlı şahidiydi,

Ağlıyordu rüyalarının masum prensesi,

Karşı koymayacaktı gözlerinin hapsindeki isyancı gözyaşlarına,

Olmadı...

Ağladı...

Sonsuz bekleyişin bitişini müjdeleyen ses duyuldu...

Baba oldunuz efendim...

Dünyalar güzeli bir kızınız oldu...', 'BEKLENEN GÜN Beklenen günlerin geçmeyen saniyelerini sayıyordu. Tarifsiz bir heyecan diyarından gelen hızlı kalp atışları misafiriydi yüreği...', ARRAY['Türk Edebiyatı','Şiir','Vahan İsaoğlu']::text[], 8.5, '{"poet":"Vahan İsaoğlu","poet_slug":"vahan-i-saoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/beklenen-gun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-gulnare-leman-zpd6f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerde benim güzel baht ım? 

Kalbimi her zaman yaktın.

Acılara yelken açtım....

Aşkım gönlüme hakim

Zalim...

Affet beni güzel annem,

Hiç mutlu olmadım ki,ben

Dilime gelmedi yalan,

Hayat veren,hayat satan

Zalim...

Kolay olmadı yaşamım,

Her an namusla yaşadım.

Sıldırımlı dağlar aştım,

Son da kaderle barıştım

Zalim...', 'Nerde benim güzel baht ım?  Kalbimi her zaman yaktın. Acılara yelken açtım.... Aşkım gönlüme hakim Zalim... Affet beni güzel annem, Hiç mutl...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zalim-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun-2', 'sen-yoktun-2-sacide-yaylaz-badix', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu geceyi yine uykusuz geçirmişti,yorgundu bitkindi,omuzlarında yılların yorgunluğu vardı sanki ama umutlarını hiç tüketmemişti yıllardır.

İşte yine sabah olmuştu,yavaşça doğruldu yatağından kalktı,

Artık havalar soğumaya başlamıştı sıkıca giyindi şömine ye benzeyen yerdeki ocağı yaktı,önce kendime güzel bir çay demleyeyim dedi içinden dışarıya çıktı,tulumbadan su çekti yüzünü yıkadı o anda duvarda asılı duran oltalarını gördü.

Durdu baktı evet bugün bir değişiklik yapayım dedi,çay yapmaktan vazgeçti içeriye girip ocağın ateşini toparladı bir yere,sonra dışarıya çıkıp olta takımını aldı kapısını kapatıp yürüdü sahile doğru.

Ufak bir kayığı vardı,onu uzaktan görünce üzüldü hayat ona, oda kayığına vefasızlık yaptığını düşündü,öyle ya uzun süredir onunla ilgilenmemişti,

Oysa ne günleri geçmişti o kayığın içinde gözlerinin önünden film şeridi gibi geçmeye başladı geçmişi.

Aradan kaç yıl geçmişti oysa,daha dün gibiydi Yosun gözlüsünü bir balıktan döndüğü gün tanımıştı

Sahilde durmuş kıyıya yaklaşan balıkçıları seyrediyorlardı arkadaşlarıyla o anda tek onu görmüştüm dedi kendi kendine tek o vardı sanki sahilde ama o beni görmedi bile diye düşündü, sonra ki günlerde buna benzer geçmeye başlamıştı,ama bir gün işte o gün sahile yanaştığımda elimdeki deniz kabuklarını ona uzattım hiç unutmam o anı diye düşünmeye başladı tekrar,o anda yosun rengi gözlerini gördüm ne kadar süre öylece bakakaldığımı bilememiştim tek hatırladığım ellerinin titrediği,

benimde ellerim titriyordu anlayamamıştım,

Ama sonra ki günler denizden dönüşümde sahile yaklaşırken hep onu arar olmuştu gözlerim,o hep oradaydı, sanki beni bekler gibi,

Anlamıştım onu sevmeye başlamıştım hiç konuşamıyorduk sade gözlerimiz,

gözlerimiz konuşuyordu.

Ama bir gün 

-yarın beni de götürür müsünüz balığa giderken dedi,

ne diyeceğimi bilememiştim donup kalmıştım,

-yarın beni de alır mısın giderken

-benimle birliktemi gelmek istiyorsun o an sanki ben değildim konuşan

,-evet

-tamam gel diyebilmiştim,

nasıl dediğimi bile bilemiyorum sesim sanki benden çıkmıyordu,

o gece hiç uyumamıştım.

onunla olabileceğimi,onun yanımda olacağını düşünmekten bütün gece hiç uyumadan sabahı etmiştim.

Hemen sahile koştum birde baktım ki orada beni bekliyordu.

Kayığa bindik ipleri çözdüm hiç konuşmuyorduk sanki konuşsak bu büyü bozulacakmış gibi iki suskun sahilden uzaklaşmaya başladık.

Çok garip bir yakınlıktı bizimki her şeyi gözlerimiz söylüyordu,gözler konuşuyordu sadece,

İşte böyle bu suskunluk içinde akşamı etmiştik geriye döndük,ertesi gün,sonrası günler hep böyle geçmeye başlamıştı ve bir gün işte o gün ilk kez o konuştu

-seni seviyorum

ne diyeceğimi bilememiştim şaşkındım ama bir o kadar da mutluydum

ellerimle bir anda onun ellerini tuttum konuşamıyordum

-seni seviyorum duydun mu dedi

işte şimdi uykuda olmadığımı anlamıştım rüya değil di gerçekti duyduklarım

-bende seni seviyorum yosun gözlüm dediğimi hatırlıyorum

geriye nasıl döndük hiç hatırlamıyorum.

İşte o günden sonra deniz bir başka güzeldi benim için başka bir anlamı vardı balık tutmamın

Her gün sevgimizi sunduk denize,tek denizdi sevgimizi paylaşan.

Günler su gibi akıp gidiyordu,deniz kabuklarından yüzükler, bilezikler yapmıştım,o bana sanki denizin bir armağanıydı.

İşte yine yüzüne hüzün çöktü bir anda.

Ama şimdi yok,nerde ne yapıyor diye düşündü yıllar geçti ama ben onu burada bekliyorum diye geçirdi içinden.

Gitmişti yosun gözlü sevdiği,yosun gözlüm yok dedi yavaşça.

Yine yılların yorgun bekleyişi omuzlarına çökmüştü işte..

Aradı gözlerim 

Şaşkın ürkek, 

Açan güllerde,

Esen yellerde, 

Ama sen yoktun.

Şimşekler çakıyordu,

Gök gürlüyordu,

Yağıyordu yağmur,

Ama sen yoktun.

Yalnızdım,gariptim

Çaresiz,

Bende ağlıyordum

Ama sen yoktun.

Bir bilinmezdeydim ama sen yoktun.', 'Bu geceyi yine uykusuz geçirmişti,yorgundu bitkindi,omuzlarında yılların yorgunluğu vardı sanki ama umutlarını hiç tüketmemişti yıllardır. İ...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sen-yoktun-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada Yanacaksın', 'orada-yanacaksin-huseyin-sonmez-pzupz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aradığın herşeyi burada bulacaksın

Burada sevecek,burada solacaksın

Buradan götürüp odunu ateşi

Yalnızca orada yanacaksın.', 'Aradığın herşeyi burada bulacaksın Burada sevecek,burada solacaksın Buradan götürüp odunu ateşi Yalnızca orada yanacaksın....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/orada-yanacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Ters yollara Saptınki', 'niye-ters-yollara-saptinki-eyup-selahattin-dalkiran-3tvdi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim ağlarken

Bu ellerden giderim

Efsanevi bir aşk ile.

Gidiyorum işte

Zifiri karanlıkları sırtlayarak.

Çok Korkuyorum

Hudutsuz hüzünler ile

Sensizlikler durağına.

Biliyorsun''ki 

Çok derinlerdeydi yaşanacak aşkımız

Yasaklara inat yaşayacaktı

her hangi bir zamanda

Sahibini kaybeden

Bir tarih yaprağı gibi.

Aşk değilmiydi bizi

akla erdiren.

Keşke senin ve benim adım

Aşka ölüm diye yazılsaydı

Kaderimiz içinde.

Niye ters yollara saptın ki

Sevda ilmiklerinden geçerken

bizim dileklerimiz.

Yalanmış

Sen ve ben gibi

Sihrimiz kaçmasın diye

Fincanlarımızı ters yüz ederdik

Falcı kadının sözlerine karşı.

Niye ters yollara saptın ki

Bensiz ben olmadan senle.', 'Yüreğim ağlarken Bu ellerden giderim Efsanevi bir aşk ile. Gidiyorum işte Zifiri karanlıkları sırtlayarak. Çok Korkuyorum Hudutsuz hüzünler ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/niye-ters-yollara-saptinki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmadım', 'seni-unutmadim-huseyin-sonmez-69dyd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tövbesini bozan,

Yeminini unutup 

Azan,

Dininden dönen,

Geçmişini silen,

Meyhaneyi dost bilen,

Kadehleriyle sabahlayan

Bir sarhoşum...

Dilim tutuldu,

Mecnûn oldum.

Adımı unuttum,

Evimi unuttum,

Yolumu unuttum,

Yaşımı unuttum,

Umutlarımı unuttum,

Vefayı unuttum,

Sadakati unuttum.

Yalnızca,

Seni

Unutmadım...', 'Tövbesini bozan, Yeminini unutup  Azan, Dininden dönen, Geçmişini silen, Meyhaneyi dost bilen, Kadehleriyle sabahlayan Bir sarhoşum... Dilim...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-unutmadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-fethi-kucuk-sxmjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binbir acılarla beni büyüttün

Emeğin ödenmez bilesin annne

Göz yaşlarınla beni uyuttun,

Emeğin ödenmez bilesin anne

Sevda gemi oldu sen ise kaptan

Kendini adadın yavruna hepten

Sçına ak düştü binbir sebepten

Emeğin ödenmez bilesin anne

Dokuz ay karnında taşıdın durdun

Acını feryadınla yoğurdun

Başımızdan kötülüğü savardın

Emeğin ödenmez bilesin anne

Sen anneydin annelerin yücesi

Sen idin sevdaların ecesi

Ağzımdan düşmez oldu hecesi

Emeğin ödenmez bilesin annne', 'Binbir acılarla beni büyüttün Emeğin ödenmez bilesin annne Göz yaşlarınla beni uyuttun, Emeğin ödenmez bilesin anne Sevda gemi oldu sen ise ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Küçük']::text[], 8.5, '{"poet":"Fethi Küçük","poet_slug":"fethi-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller desin sen bir Türksün', 'eller-desin-sen-bir-turksun-mikdat-bal-5sb41', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne Laz ne Kürt, ne Çerkezim

Ne sağ, ne sol ne merkezim

Herkes benim ben herkesim

Eller desin sen bir  Türksün

Tüm şer güçler bizden ürksün

Güney kuzey batı doğu

Yok milletin azı çoğu

Bize ait varı yoğu

Eller desin sen bir  Türksün

Tüm şer güçler bizden ürksün

Bayrağımız yurdumuz bir

Askerimiz ordumuz bir

Türkümüz bir Kürdümüz bir

Eller desin sen bir  Türksün

Tüm şer güçler bizden ürksün

Gönlümüzde vatan yatar

Kalplerimiz hep bir atar

Sevgi taşır katar Katar

Eller desin sen bir  Türksün

Tüm şer güçler bizden ürksün

Mutlulukla dolsun yürek

Çalışmalı kazma kürek

Bize bu yurt her an gerek

Eller desin sen bir  Türksün

Tüm şer güçler bizden ürksün', 'Ne Laz ne Kürt, ne Çerkezim Ne sağ, ne sol ne merkezim Herkes benim ben herkesim Eller desin sen bir  Türksün Tüm şer güçler bizden ürksün G...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eller-desin-sen-bir-turksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-huseyin-sonmez-c2xr3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimde tarak,

Saatlerce seninle konuşarak

Saçlarımı taradım.

Yıllar geçtikçe hep

Kendimi aradım

Sende.

Bir değişiklik vardı bende,

Çekinmeden söyledin.

Eski,uzun,siyah saçlarım

Parlak yüzüm

İçin için parlayan gözlerim

Neredeydi? 

Beyaz saçlarım,

Kırışık yüzüm,

Feneri sönmüş ışık gibi gözüm

Hepsi değişmişti. 

Yıllarca herşeyi olduğu gibi

Gösterdin bana.

Ne diyebilirdim ki sana

Hiç kaçmadın doğruluktan

Doğruyu söylemekten sükût etmedin

İki yerden kaçamayacağım

Biliyorum:

Bir mizandan bir de senden

Şayet kurtulursam kirden 

Bu rezil bedenden

Sana doyasıya bakmak isterim.

Ağlayarak değil gülerek

Tek dostum olduğunu bilerek

Şimdi kavgalıyım

Seninle.

Eskisi gibi konuşmuyorsun benimle

Suratın asık ve kırışık

Acı ve kedere alışık

Gibisin.

Ne zaman fırtınalar kopsa içimde

Sen başka başka biçimde

Bana bakıyorsun.

Biliyorum,biliyorum.

Suç bende...

Şu cılız,aciz

Şu rezil

Bedende...', 'Elimde tarak, Saatlerce seninle konuşarak Saçlarımı taradım. Yıllar geçtikçe hep Kendimi aradım Sende. Bir değişiklik vardı bende, Çekinmede...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/aynalar-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyor Yüreğim İstanbulun Ortasında', 'usuyor-yuregim-i-stanbulun-ortasinda-eyup-selahattin-dalkiran-bn1sr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senli şiir

Benlik şarkısıdır.

ortaya attığımız aşk ile

İstanbul denen Güzel şehirde

portakal gibi kokmaya başladı.

Portakalın Çiçeği olabilirmiyiz? 

Bülbülün  güle sevdası gibi

Aşk bahçem

uyandır beni 

Düşlerin olayım diye.

İstanbul denen güzel Şehirde.

Bu yüreğin dileği

Seni beklemek olsun

İstanbul denen Güzel sehirde

Yeni doğan güne karşı.

Günahlarım kendinden bile kaçıyor

Üşüyor yüreğim İstanbulun ortasında

Sen yoksun diye

Yolda üşüyenler gibi.

Biliyormusun? 

Kalbimdeki aşkını gezdiğimiz

Üsküdarın Meydanında bulunan

Çeşmeye bıraktım belki gelip 

Aşkımı tekrar oradan alır bir bardak

Akan Sebil sudan içerek beni anar

ve hatırlarsın diye.

Ya Çamlıca tepesindeki elele 

tutuşup sıcak sevgi dolu ağaçlarının

gölgesi altında seni öperken

Kızaran yanaklarımızdamı ordaki

Güzel ağaçlarla yandı.

Sen oralarda gezip beni ararsın diye

Çamlıca tepesinde seni arıyorum dolaşarak.

Bakıyorum

Sarıyere,Eminönüne,Sirkeciye,

Beşiktaşa,Yıldız yokuşuna,Ortaköye,

Yedi tepeyi tarıyor gözlerim en ince 

ayrıntısına kadar Seni belki görürüm diye.

Bir şeylerin içine bıraktım kendimi

döneceksin diye.

Yüreğim yoruldu

sensiz azapların yolunda.

Yollarımız ayrılınca

Ayın gölgesimi,düştü üzerimize

Yada kara kedimi geçti aramızdan

Rüyalarımız,umutlarımız,sevdalarımız

Sen ve ben gibi dağıldı

İstanbulda denen güzel şehirde.

Gel sevgilim gel

yüreğim yoruldu artık

Seni aramaktan

Gel seni bekliyorum kız kulesinin

Önündeki beton merdivenli 

Üstünde halı serilmiş çay bahçesine

Seni bekliyorum Padişahlar,evliyalar cennetinde.', 'Senli şiir Benlik şarkısıdır. ortaya attığımız aşk ile İstanbul denen Güzel şehirde portakal gibi kokmaya başladı. Portakalın Çiçeği olabili...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/usuyor-yuregim-istanbulun-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-selim-gul-ijqdq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köyden mektup geldi emmimoğlundan

Geçim sıkıntısından millet oyy deyi yazmış

Tarlalar çıktı elden, sıra davarda

Böyle giderse ahval, vayy deyi yazmış.

Komşu köyler eşkıyayı salar üstüme

Çifte tüfek yetmez gayrı dostuma

İllede bir vurgun ister postuna

Çayır çimen barut kokar, bey deyi yazmış.

Ekmek bile lüküs olmuş ceplere

Bir yılda bir kilo et girmez evlere

Kışlar soğuk, perişanız, düştük dillere

Odun buldun, gizli yere koy deyi yazmış.

İtin oğlu mahsulümü tarumar etti

Nafakamı dirhem dirhem soydu piç etti

Dayanamadı Hasan kalktı göç etti

Köyde kaldı üç beş kişi, say deyi yazmış.

Yıllar yılı bu sülükler emdiler bizi

Tatlı tatlı sözler ile yoldular tüyümüzü

Bu sefer Selim gardaş değiştik yolumuzu

Biz Hoca’ya verdik bu kez rey deyi yazmış.

9 Kasım 96 Ankara', 'Köyden mektup geldi emmimoğlundan Geçim sıkıntısından millet oyy deyi yazmış Tarlalar çıktı elden, sıra davarda Böyle giderse ahval, vayy de...', ARRAY['Türk Edebiyatı','Şiir','Selim Gül']::text[], 8.5, '{"poet":"Selim Gül","poet_slug":"selim-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektup-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Söyle', 'selam-soyle-dursun-elmas-kx3vw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '................Ömer Sırakaya''nın ''gidiyorum''şiirine

Demek köye gidiyorsun

Güle güle devam eyle.

Vardığında herkeslere

Bizden köye selam söyle.

Kimselere diyemiyom,

Bu yıl kurban kesemiyom,

Ben bayrama gidemiyom,

Sırdaşlara selam söyle.

Amasya''dan Taşova''ya

Erbaa''da biraz mola,

Hal hatır sor Yenihan''a,

Yoldaşlara selam söyle.

Yol boyunca yayalara,

Çal Dağı''nda kayalara,

Başı duman yaylalara,

El salla da selam söyle.

Acı poyraz çok esse de,

Tipi aman vermese de,

İç suyundan buz kesse de

Kana doya selam söyle.

Git öğretmenler evine

Merhaba de hepisine,

Emmimoğlu İsmail''e,

Arzet hâlim selam söyle.

Bizim başkan ''Kel Salih''e,

Sizin köyden ''Dom Ali''ye'',

Hani bizim şu  Bedir''e,

Şiir okut,selam söyle.

İşler nasıl Veysel Önder,

Ne yapıyor Dursun Özer? 

Gardaşınız sizi özler,

Tüm dostlara selam söyle.

Can dostumdur Nuru Dayı,

Halil ondan olmaz ayrı,

Taşkafa ver İslam''lılı

Hepisine selam söyle.

Var ya hani,şu ''Kabaklar'',

Selam söyle dağlar kadar,

Osman sana çay ısmarlar

Canlarıma selam söyle.

Köyün özler dertli gönül,

Gardaşlığım ''Koca Hail'',

Selam sana reis Cemil,

Sevenlere selam söyle.

Karadağlı,yazma yeter,

Sabah erken horoz öter,

Bacasında tezek tüter,

Var köyüme selam söyle.', '................Ömer Sırakaya''nın ''gidiyorum''şiirine Demek köye gidiyorsun Güle güle devam eyle. Vardığında herkeslere Bizden köye selam söy...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/selam-soyle-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Bana', 'don-bana-huseyin-sonmez-j861a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne anlatsam ne söylesem

Sevdiğimi bilebilsen

Gittiğin şu uzak ilden

Dönüp bana gelebilsen.

Kurumuş bir yaprak gibi

Çorak,susuz toprak gibi

Verimsiz bir insan oldum

Dönüp bana gelebilsen.

Feryatlarla doldu ahım

Hasret kaldı sana ruhum

Kalmadı içimde sulhum

Dönüp bana gelebilsen.

Çile doldum öbek öbek

Hep dolandım hasretine

Yandı kavruldu şu yürek

Dönüp bana gelebilsen.

Bu canımı sana versem 

Sevdiğimi görebilsen

Yıllar oldu hiç gülmedim

Dönüp bana gelebilsen.

Vakit bitti geç kalmadan

Kapım açık hiç çalmadan

Kendini üzüp yormadan

Dönüp bana gelebilsen.', 'Ne anlatsam ne söylesem Sevdiğimi bilebilsen Gittiğin şu uzak ilden Dönüp bana gelebilsen. Kurumuş bir yaprak gibi Çorak,susuz toprak gibi V...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/don-bana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A t a m', 'a-t-a-m-necati-keceli-yegcg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Atam'' bize emanet bu vatanda 

    Bak neler türedi geçen zamanda 

    Doğuda, batıda, koca cihanda

    Parçalanır vatan nerdesin Atam

    Bu vatan anaydı, babaydı, yardı 

    Hani ülkede, harf devrimi vardı 

    Şimdi sokakları Kürtçeler sardı 

    Parçalanır vatan nerdesin Atam

    Tekke ve zaviye''lik kalktı ama 

    İnsanlar, muskacıya gitti şama 

    Kanunlar bozuldu, yapıldı yama 

    Parçalanır vatan nerdesin Atam 

    Dini siyasete, alet ettiler

    Oy için ülkeyi tarumar ettiler

    Meclise sarık türbanla gittiler 

    Parçalanır vatan nerdesin Atam

    Senin heykelini bile yıktılar

    Soyguna, talana sahip çıktılar

    Yaşlısı genci terörden bıktılar

    Parçalanır vatan nerdesin Atam

    Necati KEÇELİ

    İZMİR', '''Atam'' bize emanet bu vatanda      Bak neler türedi geçen zamanda      Doğuda, batıda, koca cihanda     Parçalanır vatan nerdesin Atam     B...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/a-t-a-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 16', 'd-siir-ve-sarki-sozleri-16-huseyin-avdic-7oh6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim Bu Leyla

Kim bu Leyla, kim bu Leyla? 

Aklımı başımdan alan,

Beni kalbimden vuran,

Ruhumu bensiz kılan,

Kimdir bu Leyla? 

*   *   *

Kim bu Leyla, kim bu Leyla? 

Beni Mecnûn eyleyen,

Beni bende yok eden,

Beni kendinde mahveden,

Kimdir bu Leyla? 

Not: Bestelendi.

Berlin, Şubat 2005.', 'Kim Bu Leyla Kim bu Leyla, kim bu Leyla?  Aklımı başımdan alan, Beni kalbimden vuran, Ruhumu bensiz kılan, Kimdir bu Leyla?  *   *   * Kim b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmet Gibi', 'rahmet-gibi-huseyin-sonmez-2r9u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mehtap suda görününce

Meltem orda harelendi

Gözyaşlarım rahmet gibi

Gecenin bir saatinde.

Öbek öbek çile doldu

İplik iplik  hep dolandı

Tane tane düştü yere

Rahmet gibi gözyaşlarım.

Hasret oldu ateş afet

Bu yalnızlık çile mihnet

Gözyaşlarım oldu rahmet 

Gecenin bir saatinde.

Gecenin bir saatinde 

Zebun etti çaresizlik

Tane tane düştü yere

Rahmet gibi gözyaşlarım.', 'Mehtap suda görününce Meltem orda harelendi Gözyaşlarım rahmet gibi Gecenin bir saatinde. Öbek öbek çile doldu İplik iplik  hep dolandı Tane...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rahmet-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Ruhlu Bir Adamım', 'sair-ruhlu-bir-adamim-vecdi-murat-soydan-rglg1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül yorgunu bir adamım işte,

Şiirlerimi yüreğimde yaşatıyorum. 

Saatlerce oturup şiirler yazıyorum.

Şiirlerimde sevgi var, 

Aşk var, hasret var.

Gidenlere ağıtlar,

Kalanlara şükürler var.

Dizelerde,

Söylenmeyenleri dile getirmek var.

Saatlerce göz yaşı döküp,

Ardından, göz yaşı silmek var.

Yer yer hüzün,

Kırıntı da olsa,

Mutluluk var.

Şiirlerim…

Kaç dakikada okunuyor acaba? 

Sordum çevreme.

Bir solukta dediler.

Kaç yılda yazılıyor.

Bunu ben biliyorum sadece.

Bir ömür boyunca yazılıyormuş.

Bu yük, bu bedene ağır gelir oldu.

Taşımam artık dedikçe,.

Söz dinlemez oluyor,

Haykırıyor bu yürek.

Coştukça coşuyor işte.

Elimde değil,

Yazıyorum.

Garip bir hamalım,

Ama, şair ruhlu bir adamım.

Şu dizeler de olmasaydı,

Ne anlamı kalırdı hayatın.

Dimdik ayaktayım işte.

Eğilmem namerde,

Eğilmeyecektir  başım.

Kırılmadı, kırılmayacak kalemim.

Suskun şair dedirtmem kendime,

Şimdi susmak zamanı değil, 

Ölesiye dek yazmak zamanıdır.

Vecdi Murat SOYDAN

04/01/2006-Mihalıççık -ESKİŞEHİR', 'Gönül yorgunu bir adamım işte, Şiirlerimi yüreğimde yaşatıyorum.  Saatlerce oturup şiirler yazıyorum. Şiirlerimde sevgi var,  Aşk var, hasre...', ARRAY['Türk Edebiyatı','Şiir','Vecdi Murat Soydan']::text[], 8.5, '{"poet":"Vecdi Murat Soydan","poet_slug":"vecdi-murat-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sair-ruhlu-bir-adamim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Oralar Karanlıkmı Gündüzmü', 'senin-oralar-karanlikmi-gunduzmu-eyup-selahattin-dalkiran-0ytuv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramak,bulmak

Bır tutku oldu benim için

Her bahar denerim

Damlalar halinde

Yalnızlığa dem vurarak

biraz sen biraz ben diyerek

Terleyen alevlerin arasında

Senin oralar karanlıkmı,gündüzmü

Aşk gibi? .

Kendimi aradım

Her mevsimin içinde

Bazen gençliğimi astığım oldu

Yaz günlerinin sıcağında.

Benim gibi günler geçsede,

biliyorum çok geç

gönüllerimiz yaralı

Yuh olsun

Yaşıyor ve seviyoruz

yine birbirimizi

Kar esintileri gibi

Yuh olsun yalnızlığımıza yuh.', 'Aramak,bulmak Bır tutku oldu benim için Her bahar denerim Damlalar halinde Yalnızlığa dem vurarak biraz sen biraz ben diyerek Terleyen alevl...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-oralar-karanlikmi-gunduzmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilim', 'sen-degilim-emre-yildirim-uihlb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al bu yüreği,

Vur kelepçeyi

Çıt çıkarırsam namerdim

Çünki ben sen değilim...', 'Al bu yüreği, Vur kelepçeyi Çıt çıkarırsam namerdim Çünki ben sen değilim......', ARRAY['Türk Edebiyatı','Şiir','Emre Yıldırım']::text[], 8.5, '{"poet":"Emre Yıldırım","poet_slug":"emre-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öperdim Gözlerinden', 'operdim-gozlerinden-mustafa-alpaydin-k50v9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan hasretim bugün fazladır dünden

Ah çekerek ağlarım ayrılığın elinden

Şimdi yanımda olsan bal akardı dilinden

Sarılırdım boynuna öperdim gözlerinden.

Canlanır hatıralar silinmez hayalimden

Gönül seni arzular adın düşmez dilimden

Sevdayı bilmeyenler anlayamaz halimden

Sarılırdım boynuna öperdim gözlerinden.

Resmine baktığım an yaş gelir gözlerimden

Aşk sarhoşu olurum geçerim ben kendimden

Hüzün kaplar gönlümü inilerim derdimden

Sarılırdım boynuna öperdim gözlerinden.', 'Sana olan hasretim bugün fazladır dünden Ah çekerek ağlarım ayrılığın elinden Şimdi yanımda olsan bal akardı dilinden Sarılırdım boynuna öpe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/operdim-gozlerinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Bir Kuş Uçmak Bilmez', 'gonlum-bir-kus-ucmak-bilmez-nihat-yucel-d1jlc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kişi ne çekerse bil ki

Çekiyor kendi elinden

Vaz geçmişim bu dünyanın

Bülbülünden hem gülünden

Kara günüm geçmek bilmez

Gönlüm bir kuş uçmak bilmez

Alışmamış içmek bilmez

Bir doluyu dost elinden

Bir sancıyım dinsem bile

Aşk yolundan dönsem bile

Bir alevim sönsem bile

Ateş çıkacak külümden

Bu dünyaya geldik niçin

Sevgiyi yaşamak için

Sevgiler büyüyünce kin

Yıkılacak temelinden

Dostlarım bu kadar sözüm

Alev alev yanar özüm

Dünyayı görmüyor gözüm

Göz yaşlarımın selinden

Acı çektim şimdiye dek

Bu acıyla ölsem gerek

Nasıl dayanıyor yürek

Bıkmışım tahammülünden

                          Mayıs/74

Nihat Yücel', 'Kişi ne çekerse bil ki Çekiyor kendi elinden Vaz geçmişim bu dünyanın Bülbülünden hem gülünden Kara günüm geçmek bilmez Gönlüm bir kuş uçmak...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonlum-bir-kus-ucmak-bilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bembeyaz Bir Hikaye...', 'bembeyaz-bir-hikaye-hasan-can-rq55m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokaktan eve üç kilometre yol,

Soğuk bir kıştı, üşüyordu heryerim,

Soğuğa aldırmayan sadece ellerimdi,

Parmaklarım buz tutmuş olsa bile aldırmıyordu soğuğa.

Kocaman bir kıştı, sokaktaydım,

Eve hayli yol vardı, üşüyordum,

Ellerimde olmasa donacaktım,

Ocaktı, kar gittikçe büyüyordu,

Saçlarımda kardan bir şapka vardı.

İnsanlar büyük bir uğraş içindeydi,

Çoluk çocuk üşümesin diye,

Akın etmişlerdi köyün merkezine,

Yakacak odun, kömür,

Herkes ne koparsa kardı satıcılardan,

Efendisi olmuştu kar köyün,

Bembeyaz bir efendi...

Sarmıştı tüm asiliğiyle dörtbir yanı.

Ocaktı, bir adam tren istasyonunda,

Evsiz barksız bir adam,

İki büklüm bir bankta,

Onun heryeri üşüyordu,

Elleri bile...

Titriyordu, ama banamısın demiyordu,

Yaşıyordu, donmadan, içinde bir ateş yanıyor gibi...

Saç, sakal eşit uzunlukta,

Yağan karları üzerinden atıp,

Tekrar iki büklüm, titreye titreye,

İçinde yanan ateş onu koruyordu.

Ocaktı, eve az kalmıştı,

Saçlarımda kardan bir şapka,

Titriyordum, ellerim yine aynı,

Çocuklar evlerin camlarından,

Minik gözleriyle beni süzüyorlardı,

Bembeyaz bir serüven eve az kalmıştı.

Bir bank görmüştüm yolumun üstünde,

Tren istasyonundaki adam gelmişti aklıma,

Birazda yorgundum, oturdum bankın üzerine,

Tuhaf bir istekle uzandım olduğum yerde,

Kar yine aynı şiddetle devam ediyordu,

Hava kararmak üzereydi, eve az kalmıştı,

Yorgundum, gözlerim yorgundu,

Ellerimde üşümeye başlamıştı.

Ve sabaha karşı,

Güneşin aydınlatan yüzünde,

İki bankta, iki donuk ceset bulundu,

Biri tren istasyonunda,

Biri ise, eve az kalmıştı...

Ocaktı, herşey kapkaraydı,

Bembeyaz bir hikayenin bitişiydi...', 'Sokaktan eve üç kilometre yol, Soğuk bir kıştı, üşüyordu heryerim, Soğuğa aldırmayan sadece ellerimdi, Parmaklarım buz tutmuş olsa bile aldı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bembeyaz-bir-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-nihat-yucel-vhssy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutarak sevgi bağından

Kurtulup benlik ağından

Kanatlanıp kaf dağından

Geçelim dostlar geçelim

Görüp yarin gül yüzünü

İşitip şeker sözünü

Bir kadehte gök yüzünü

İçelim dostlar içelim

Uyanarak bir rüyadan

Eğlenmeden kâm almadan

Sıra ile bu dünyadan

Göçelim dostlar göçelim

Ozan olan söyler sözü

Kim belecek halimizi

En son kendi örtümüzü

Biçelim dostlar biçelim

                             06/69

Nihat Yücel', 'Tutarak sevgi bağından Kurtulup benlik ağından Kanatlanıp kaf dağından Geçelim dostlar geçelim Görüp yarin gül yüzünü İşitip şeker sözünü Bi...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dostlar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar', 'nar-ali-arslan-3z3u6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kabuğunu çatlatan nar 

rengini saçar bir yüreğin,

bin kristal birden ışıldar;

sevincin huzmeleridir, 

yansır yaşama.

Suda şimdi gölgelerin serinliği 

var.

Bir kavuşmaca telaşı başlar kavşağa bir adım kala.

Dönüm noktalarının ucunda birikir heyecan,

sancısı dibe vurunca,

köpüğüne dolaşır, 

şaşkın şelale;

bir baş dönmesinde hızla düşer yatağına.

Haydi, 

açın bütün kapaklarını aklın;

içinden fışkıracak dolu şey var.

Kabuğunu çatlatan nar,

suyuna doygun zarından  açar;

tadından almasına mahir her dudakta;

aşkla ıslanınca.', 'Kabuğunu çatlatan nar  rengini saçar bir yüreğin, bin kristal birden ışıldar; sevincin huzmeleridir,  yansır yaşama. Suda şimdi gölgelerin s...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/n-a-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ben miyim?', 'bu-ben-miyim-emre-yildirim-v4z3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız kalmak istiyorum bu gece,

Senden uzak,

Yıldızlardan uzak,

Kendimden uzak.

Yalnızlığımla başbaşa oturup

İçmek istiyorum sabah dek.

Sonra...

Sonrası meçhul be gülüm,

Kalırmıyım göçermiyim bilinmez.

Belki,

Hüzünle dolu bir sonbahar mevsiminde,

Ağaçtan düşerken,

Rüzgarın sürükleyip götürdüğü bir yaprak misali,

Nereye gittiğimi bilmeden

İçmeden sarhoş olmuş aşık gibi

Oradan oraya savrulur dururum.

Belki,

Köşe başında bir kaldırımın üstünde,

Cansız bedenim bulunur.

Bir elimde sigara izmariti,

Bir elimde

Beraber çektirdiğimiz resim....

Şimdi sen söyle,bu ben miyim?', 'Yalnız kalmak istiyorum bu gece, Senden uzak, Yıldızlardan uzak, Kendimden uzak. Yalnızlığımla başbaşa oturup İçmek istiyorum sabah dek. Son...', ARRAY['Türk Edebiyatı','Şiir','Emre Yıldırım']::text[], 8.5, '{"poet":"Emre Yıldırım","poet_slug":"emre-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-ben-miyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşın adı aşk olunca', 'savasin-adi-ask-olunca-mustafa-komuscuoglu-90u5i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya denen şu düşte

Ömür herdem sürgünde

Et tırnaktan ayrılır mı dersin? 

Damla denizden ayrıldı işte

Görmez misin bir sır var bu işte

Bilmez misin ömrün hep bitişte

Duymazmısın alem hep zikredişte

Zerreden,kürreye o herşeyin içinde

Kiminde yaş olup gözden aktı

Kiminde silah olup canları yaktı

Aşk denen şey bir büyük savaştı

Bu savaşın galibi hiç olmadı

Karşı cephede sevilen olunca

Kurşun sıkılabilirmi düşmana

Can nasıl kıysın ki cananına

Kazananı yok,savaşı aşk olunca...', 'Dünya denen şu düşte Ömür herdem sürgünde Et tırnaktan ayrılır mı dersin?  Damla denizden ayrıldı işte Görmez misin bir sır var bu işte Bilm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/savasin-adi-ask-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tıbben olmasa bile...', 'tibben-olmasa-bile-mustafa-komuscuoglu-2921e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanı eritiyoruz çayımızda yudum yudum

Hakikilerini ararken gönül gönül sevdanın

Kendi öz yurdumuzdan kovulduk

Ne bir teselli aradık,ne de bir teselli bulduk

Gönlümüzün tüm yasını,gözyaşlarıyla yunduk

Hergün yavaş yavaş,dirhem dirhem öldük

Ama kimselere ölüyoruz demedik,diyemedik

Beden yaşıyordu deil mi? Yaşıyorduk bizde öyleyse

Ama başkalarının dilince,söylediğince

Varsın tabiplerin kağıtlarında yazmasın ölü diye

Zaten o kağıtlarda yazar mı ki insan; aşık diye

Biz vermişiz çoktan dilekçemizi ilgili mercihlere

Tıbben olmasa bile,kalben ölüyüz diye...', 'Zamanı eritiyoruz çayımızda yudum yudum Hakikilerini ararken gönül gönül sevdanın Kendi öz yurdumuzdan kovulduk Ne bir teselli aradık,ne de ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tibben-olmasa-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yas Tutan Memeler', 'yas-tutan-memeler-yasar-pullu-44bm9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dağlar boşuna emzirdi bizi

eyvaah ölmeden yenildik

bilmeden geçtik yolları

bıçak geçti yara derin

üzerimiz

çamur taş ve toprak

ustura dil damar kesik

kadınların sevdaya benzediği

çığlıkların arşa yükseldiği

bir eski zamandı

gölgelerin ölümünü bilmeden sevdik

Bilmedik tarihimizi

kaç bin fidan yitirdik

mezarları göklere serili

ayları uzattık 32, günlere

acıyı paraya dönüştürelim diye

kare ekranlara sığdı metafizik

ormanlar üşüdü yüreğimizde

obamızı özledik

boşa ezberledik hasreti

daldık

toprağa çakılı damarlarımız

kökümüze dargın kırıldık

küf kokulu sokakları kentlerin

tüketti gözlerimizdeki alevi

çürük bir kan

piç bir sürgün

yüzümüze küfretti

bu dağlar boşuna emzirdi bizi

Bilmeden karasını gözlerimizin

sürdük ellerimize 

çok renkli çiçekleri

mühürlü kapılardan geçtik

kırıp kilitlerini

usul usul doğarken güneş

Aslı ile Kerem i dinlemiştik

yoz aşklara yenildik

bu dağlar boşuna emzirdi bizi

onmaz bir yaradır şimdi

yastadır memeleri', 'Bu dağlar boşuna emzirdi bizi eyvaah ölmeden yenildik bilmeden geçtik yolları bıçak geçti yara derin üzerimiz çamur taş ve toprak ustura dil...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yas-tutan-memeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-suleyman-yavas-hkatx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim

Saçlarında biçimlendim

Gecelere savruldum

Mehtaba dokundum

Yıldızlar kadar öldüm

Sevdim

Gözlerinde eridim

Dalgalarla boğuştum

Kumsala vurdum

Kumlar kadar öldüm

Sevdim

HİÇ ÖLMEDİM', 'Sevdim Saçlarında biçimlendim Gecelere savruldum Mehtaba dokundum Yıldızlar kadar öldüm Sevdim Gözlerinde eridim Dalgalarla boğuştum Kumsala...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdim-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Bir Başkası Yok', 'rubai-bir-baskasi-yok-nihat-yucel-xhf1i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varsın ya yetersin bana bir başkası yok

Bak gönlümü yakmış gibidir attığın ok

Yalnız yaşarım kimseye etmem mihnet

Çok gördüler ah bir bana dünyayı da çok

                                                   Mayıs/69

Nihat Yücel', 'Varsın ya yetersin bana bir başkası yok Bak gönlümü yakmış gibidir attığın ok Yalnız yaşarım kimseye etmem mihnet Çok gördüler ah bir bana d...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rubai-bir-baskasi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tastamam', 'tastamam-yasar-pullu-xo73e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Babasına benzer bir oğlan

sığmaz asfalt yollara

ın cin top oynar yarasında

suç gizlenmiş akşama

yüreğini sıksa kaldırımlarda

boyunca akacak kan

cehennem giyinir kanatır gözlerini

gömer ölümü kefensiz

deme verir kendini

Babasına benzer bir oğlan

uslanmaz kan damarlarında

kuşanır öfkesini

vurur dağlara

boğar baygın gülmeleri kirli sularda

öyle hazırlanmış

öyle tastamam', 'Babasına benzer bir oğlan sığmaz asfalt yollara ın cin top oynar yarasında suç gizlenmiş akşama yüreğini sıksa kaldırımlarda boyunca akacak ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tastamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '@@@Labirent -@@@', 'labirent-nazan-i-zmirli-1kst8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'günün    yorgunluğu

....................kıvrılmış     kalbime; 

akşam sisi çökmüş

...........................duman duman.

adımlarım

bedenim 

beynim

farklı 

yerlerde

ruhum

geziniyor

şehrin

yitik 

köşelerinde. 

sokaklar

kıvrım kıvrım

beynimin 

içi gibi

dizelerde.

dönüp dönüp

çıkamadığım

aralara 

uzanan

daralan

anılar...

buram buram

kokardı

çocukluğumda

közde kestane

her sokak 

köşesinde

sac  üzerinde 

döne döne....

kokular

savrulmuş

boğuluyor

yakılıyor

keşmekeşlik

kale içinde

kestane  olsam

canım 

acıyor...

köz  olsam 

kalbim

dayanmıyor.

kızgın sacda 

dansediyor

labirent 

gibi 

bedenim

beynim

yüreğim

keşke 

közde

kestane 

kokusunu 

alabilseydim

ve de

labirentlerde

kaybolabilseydim.....

04.01.2006-antalya', 'günün    yorgunluğu ....................kıvrılmış     kalbime;  akşam sisi çökmüş ...........................duman duman. adımlarım bedenim ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/labirent-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Eve Dönüşleri', 'kasim-eve-donusleri-gultekin-mustafa-gpspk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'serkan’ın yerine akşamcılar uğrar

elimde kitaplar

ben eve dönerim

kasımın gündüzleri de 

akşam gibi olmaya başladı

aklımda çağrışımlar

arada bir pazar kıyağını görüyoruz havanın 

hepsi bu

bir de çağrışımlar

az para, az moral, az köfte harcı ruh haliyle

yekpare bir selamünaleykümden ibaret 

eve girişim

o da sırf babam istiyor diye

bu adamın bundan başka derdi yok

varsa da benim haberim yok

aklımda çağrışımlar', 'serkan’ın yerine akşamcılar uğrar elimde kitaplar ben eve dönerim kasımın gündüzleri de  akşam gibi olmaya başladı aklımda çağrışımlar arada...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kasim-eve-donusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim aşk', 'zalim-ask-baykal-kaanalp-2pmpe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çektiğim acılar

size yalan gelir bilirim

anlatamam derdimi

susarım konuşmaz dilim

çekerim ağırlığını

zalim aşkın

taşıyamasamda gündüze

acımı gece yaşarım

geceler aldatmaz beni

hiç yalnız bırakmaz

hiç sorgulamaz beni

o yüzden severim geceleri', 'çektiğim acılar size yalan gelir bilirim anlatamam derdimi susarım konuşmaz dilim çekerim ağırlığını zalim aşkın taşıyamasamda gündüze acımı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zalim-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla gözlerim ağla.', 'agla-gozlerim-agla-ali-riza-unal-rwpd4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağla gözlerim ağla,ağla gözlerim ağla,

Her hasretin son var,ağla gözlerim ağla,

Bu çileye bel bağla,Ağla gözlerim ağla, 

ağla gözlerim ağla..ağla gözlerim ağla,

ağla gözlerim ağla,ağla gözlerim ağla,

sen vefaya el bağla,ağla gözlerim ağla,

her cefanın sonu var,ağla gözlerim ağla

ağla gözlerim ağla,ağla gözlerim ağla.

--- Beste beste ve güftedir,   ---', 'Ağla gözlerim ağla,ağla gözlerim ağla, Her hasretin son var,ağla gözlerim ağla, Bu çileye bel bağla,Ağla gözlerim ağla,  ağla gözlerim ağla....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/agla-gozlerim-agla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama''sı Saklı...', 'ama-si-sakli-zulfikar-yapar-kaleli-lbozm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül fincanında saklarım seni,

Sırılsıklam terlemezsen yanarım.

Öperim, okşarım, koklarım seni,

Gerçek Biri birlemezsen yanarım.

Emen diye diker oklarım seni,

Oktan evvel fırlamazsan yanarım.

Kalbur ile eler, paklarım seni,

Cılız iken gürlemezsen yanarım.

Azarlar, döverim, haklarım seni,

Dört dolanıp, turlamazsan yanarım.

Haset pazarında aklarım seni,

Hor bakanı horlamazsan yanarım.

Evet candan özge saklarım seni,

Sebepleri zorlamazsan yanarım.

Halini sorarım, yoklarım seni,

Çıban başı körlemezsen yanarım.', 'Gönül fincanında saklarım seni, Sırılsıklam terlemezsen yanarım. Öperim, okşarım, koklarım seni, Gerçek Biri birlemezsen yanarım. Emen diye ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ama-si-sakli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzele Şiir', 'guzele-siir-gultekin-mustafa-5sp7k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk bir rastlantı şaşkınlığı 

varoluş hengamesinde

ve demiş olduğun gibi

bütün hipotezlerin gerçekleşmesi

bir rastlantıya bağlı

aşk bir mengene sıkıştırması 

tam göğsümün üstünde

bir hayli acı vermede canıma

koşa koşa kışa giren 

bu aceleci sonbahar mevsiminde

bana yakınlaşman 

yürek sarhoşluğuma sebep

her yakınlaşman; bir ayrıntı, fotoğraf karesi

her yakınlaşman; 

ayrıntılardan tüme varan 

varoluşçu bir yaşama heyecanı

bir adım yakınımda ama

uzak yüzün bana

yüzündeki yerleşik hüzün

hüznü uzaklaştıran ani gülüşün

sahneyi her hatırlayışımda heyecanlanmam bundan

sanırım ki sahnede sen de varsın

ve rolüm gereği ben aniden

sana aşık olacağım', 'aşk bir rastlantı şaşkınlığı  varoluş hengamesinde ve demiş olduğun gibi bütün hipotezlerin gerçekleşmesi bir rastlantıya bağlı aşk bir meng...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzele-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Buzlu Saman Alevli Yolla Geliyorum', 'sana-buzlu-saman-alevli-yolla-geliyorum-eyup-selahattin-dalkiran-jt8r0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilemedinmi 

Sendeki bende

Bir gün bir punduna

Getirirsem seni

Kırmızıdan,yeşile dönen

Günleri hatırlatacağım sana

Tek tesellim Kendimi

şiir dörtlükleri arasında

boğulmadan tutmam.

yaşanmaz bu hayat

Hüznüm ellerimde kaldıkça.

Biliyorum  dokunamam 

Camdan olan kalbine

Çabuçak kırılıverir,

Bıçak sırtındaki 

Bir şiir gibi dağılır oracıkta

Peki ne yapmalıyım sana

kırılmasın diye kalbin

Yeter artık

Tedbirini al

Ben geliyorum

Sana buzlu,saman alevli yoldan

Nasılsa ölüm var

ölecekde değilsin

ince ince.

Tedbirini al

Geliyorum şiirlerimin 

o ince yolunda

anılarımızla,acılarımızla

Yaşaklara inat.

Bana verdiğin

Uçurumlar içindeki özgürlükleremi

Güvendinde kendine güvenin

Tedbirini al

esaretim bitmek üzere

sana,yağmura karşı ayaza bulaşmış 

kar tanecikleri ile', 'Bilemedinmi  Sendeki bende Bir gün bir punduna Getirirsem seni Kırmızıdan,yeşile dönen Günleri hatırlatacağım sana Tek tesellim Kendimi şiir...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sana-buzlu-saman-alevli-yolla-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Affeder', 'seven-affeder-i-smail-kocamaz-yrjnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri erkek, kadın öteki

Biri gül, diğeri dikeni,

Olsalar da kedi köpek gibi,

Seven affeder seveni.

Biri  gidelim dese Anya''ya

Diğeri isterse gitmek Konya''ya

Yol konulur mutlak ortaya,

Seven affederse seveni.

Ana, baba, küçük, büyük,

Sevenlere vermez güçlük,

Bağ, bahçe olur güllük,

Seven affederse seveni', 'Biri erkek, kadın öteki Biri gül, diğeri dikeni, Olsalar da kedi köpek gibi, Seven affeder seveni. Biri  gidelim dese Anya''ya Diğeri isterse...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seven-affeder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaca oğlan anısına', 'karaca-oglan-anisina-ali-riza-unal-0h4tj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elvan olmuş ruhi revanım,nur-u yare,

Şu eyvandan salınan,döndürdü zare,

Hayran olmuş gönül,nar-ı bi çare,

Bu seyrena zar eden yar değilmi.

Tükendi varım  perdeye,bin pare,

Bu hicrana sebeb ar değilmi,

Dinleme yad-eli ne derse desin,

Bu firaka sebeb el değilmi.', 'Elvan olmuş ruhi revanım,nur-u yare, Şu eyvandan salınan,döndürdü zare, Hayran olmuş gönül,nar-ı bi çare, Bu seyrena zar eden yar değilmi. T...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karaca-oglan-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Olduk', 'kayip-olduk-sahin-kars-n8gsy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yanı yemyeşil şu Avrupa''nın,

Ova burda orman burda düz burda.

Dönüşüne heveslendik dünyanın,

Gelip kuyruğundan tuttuk biz burda.

Bulutlara yükseliyor yapılar,

Girek dedik, açılmışken kapılar.

Bu diyarın türlü türlü hapı var,

Beğenip beğenip yuttuk biz burda.

Medeniyetinden hicap getirdik,

İnsanlığı itibarı yitirdik.

Deste deste dövizleri yatırdık,

Defteri kalemi sattık biz burda.

Hayal deryasında temel atarız,

Para ile, sevgi alır satarız.

Otuz kişi bir çarşafta yatarız,

Hayâ sözü dudaklarda haz burda.

Boy gösterir ince ince ağrılar,

Çöplüklerde oğul verir arılar.

Unutuldu sıladaki yavrular,

Ne ararsın kefen burda bez burda.

Kader çektik hep maçadan kupadan,

Omuzumuz kurtulmadı sopadan.

Bize niye bakarsınız tepeden? 

N''eylerdiniz olsaydınız siz burda? 

Şahin''in içinde hep aynı sızı,

Yaz bahar zay oldu getirdik güzü.

Kar yağdı araya kapattı izi,

Velhasılı kayıp olduk biz burda.', 'Her yanı yemyeşil şu Avrupa''nın, Ova burda orman burda düz burda. Dönüşüne heveslendik dünyanın, Gelip kuyruğundan tuttuk biz burda. Bulutla...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kayip-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Çizgi', 'i-nce-cizgi-ramazan-ates-myowl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çizgi var aramızda,

Sen bir yanda, ben bir yanda.

Ya beni al senden yana,

Ya gel gülüm, sen, bu yana.

Çok incecik bir çizgide,

Hemi yakın, hemi uzak.

Sanki birşey var içinde,

Belki sevdamıza tutak.

Kaldıralım o çizgiyi,

Tut bir yandan, ben bir yandan.

Yaşayalım biz sevgiyi,

Mutlulukla, içten, candan.

Çizgi mizgi çizilmesin,

Hür olsun artık sevdalar.

Sevenler hiç üzülmesin,

Güzel görünsün rüyalar.

Ramazan Ateş/Enschede-4.1.2006', 'Bir çizgi var aramızda, Sen bir yanda, ben bir yanda. Ya beni al senden yana, Ya gel gülüm, sen, bu yana. Çok incecik bir çizgide, Hemi yakı...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ince-cizgi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlere sığındım....', 'siirlere-sigindim-ercan-akbay-cuvso', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözyaşının tuzlu olduğunu

    Dudaklarım yastıklara değince anladım

    Oda karanlıktı,sen yoktun

    Adını andım

    Sonra bir yağmur başladı

    Gecenin orta yerinde

    Özlemlerle ıslandım

    Şiirlere sığındım

    Gözyaşının tuzlu olduğunu

    Sen gidince anladım......

                     HAYAT DERGİSİ   8.11.1986   Sayı.46', 'Gözyaşının tuzlu olduğunu     Dudaklarım yastıklara değince anladım     Oda karanlıktı,sen yoktun     Adını andım     Sonra bir yağmur başla...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siirlere-sigindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yordular Beni', 'yordular-beni-ramazan-ates-wp2t6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pin pon topu vardır hani,

Ben öyleyim, aynen öyle.

Elden ele, yerden yere.

Canı sıkılan vuruyor,

Kimi tutup savuruyor,

Elden ele, yerden yere.

Taşa değmiş, kuma değmiş,

Eline alan atıvermiş,

Elden ele, yerden yere.

Sende acımadan bana,

Tutup da fırlattın aha,

Elden ele, yerden yere.

Tut benide koy bir yere,

Yeter gülüm atma yine,

Elden ele, yerden yere.

Yeter artık yetti bana,

Yıllardır atıla atıla,

Elden ele, yerden yere.

Ramazan Ateş/Enschede-4.1.2006', 'Pin pon topu vardır hani, Ben öyleyim, aynen öyle. Elden ele, yerden yere. Canı sıkılan vuruyor, Kimi tutup savuruyor, Elden ele, yerden yer...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yordular-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlışlarla Geçti Ömrüm', 'yanlislarla-gecti-omrum-hasan-gorgu-slpbf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir başka görünür dünya

Gençliğinin baharında

Her söylenilen şey gerçek 

Her yapılan güzel gelir

Arkadaş dostluk başkadır

Varı yoğu paylaşmaktır 

Elde avuçta ne varsa

Bir bir etrafa saçmaktır

Bedeni ve ruhu soymak

Yerine sevgiyi koymak

Bir başkadır aşık olmak

Mutluluktur aşka doymak

Heyhat zaman çabuk geçer

Gerçekler rüyayı biçer

Felek bu kral çıplak der

Kendine bir kurban seçer

Ne zaman ki yalnız kalır

Dertlerinle konuşursan

İşte o an anlarsın ki

Her şey yalan her şey talan

Yalanlara kandı gönlüm

Yanlışlarla geçti ömrüm

Tam doğruyu buldum derken

Bedeni toprağa gömdüm', 'Bir başka görünür dünya Gençliğinin baharında Her söylenilen şey gerçek  Her yapılan güzel gelir Arkadaş dostluk başkadır Varı yoğu paylaşma...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanlislarla-gecti-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Yağıyor Yüreğime', 'gozlerin-yagiyor-yuregime-selahattin-yetgin-ysibs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılarla örülmüş bir duvardı senden önce yüreğim

Hüznün mevsimlerinde ayrılığı söyledi hep şiirlerim

Bitti yaşadığım kırlangıç fırtınası, yağmur gecelerim

Şimdi, uzak kentlerden yağıyor içime çakıltaşı gözlerin

Yarını yitirmekten korktuğum anlarda, sesinin, yüreğime dokunuşlarının vuruşlarıyla mutlanırım. Dünyanın bütün iğrenç seslerini keserek, bir dağın zirvesine çıkarak nefesim kısılana kadar bağırmaktır seni sevdiğimi söylemek. Saçlarıma tutunan bir sevdayla, şimdi yüreğim yıllara kafa tutar. 

Çığlığı susturulmuş ormanlar gibi içim, bedenimdeki tüm zincirlerle, elimde kan kızılı bir şarap testisi seni yudumlamak istiyorum yıkılana kadar. İçimdeki kaktüs kırığı acılarla, bedenimdeki yanmış yıkılmış imparatorluklarla, ellerimin tersiyle siliyorum bütün gökyüzünü ve senin gözlerini asıyorum, bütün renkler mavi olana kadar.

Parmaklarımızın ucundaki çoğul ağlamalarla, bizi titreten sevdayla aşk gömülü bir makberdir dinlediğimiz senfoni. Yüreğimizdeki direnmelerin acı turunçları boy atarken gecelerde, bir kardelen ağlar uzak kentlerin karları altında. Bilmelisin ki, benim de başım döner kalabalıklarda. Geceleri gri bir gökyüzüne bakmayı ne çok özlediğimi, yüzüme çarpacak gibi oluveren yıldızları seyretmeyi, o sobelendiğim çocukluğumdaki oyunlara dönmeyi ne çok istiyorum bir bilsen.

Yaraya tuz basan kahır gecelerinde ‘Ayazda kalmış bir kuş gibi’ titreyen yüreğimle, sevda hep yolumu gözlemiştir benim. Yüzündeki gülücükler eksildiğinde, lokmaları çiğnerken açlığa direndiğinde ve yüreğine asla söz geçiremediğinde, ekinler yanar geniş tarlalarında. Kimin ördüğü bilinmez, kimin yüklediği anlaşılmaz bu acılar duvarıyla nice fırtınalara göğüs gereceğiz anlayacağın. Bu yüreğimizdeki yontularla, ufkumuzdaki isimsiz sevdalarla ve her gün umduğumuz günaydınlarla dönecek bu dünya. 

Ruhundan sağıp, göğsünde emzirdiğin şiirlerle sevişmek gibidir hüzün. Dur durak bilmeksizin, avuçlarındaki doğurgan tazelikle cılız bakar gün batımı, sabrın geceye direnir, belki de toprak ağlar gözlerinde filizlenen çiçeklerle.

Gözlerindeki yakamozların iksirleriyle, sen de acılarımı silmek istiyorsun yüreğimden. Bir masal atına bindirerek, dolaştıracaksın beni bilinmez ülkelerde. Nicedir dinlediğim hüzünlü ağıtları silip ruhumdan, aşk şarkılarının hiç kesilmediği o mutluluk ormanlarına sürükleyeceksin sevginle. Titreyen ellerime şiir gözlerinle değecek, yaralı gönlüme sargı olacaksın aniden. Nura çevireceksin aşka ibadetimi, nan gibi aklımı işgallere duracaksın, kıyameti bekler gibi.

Düşlerin hiç solmadığı, gözyaşının akmadığı ve bir gece bitmeden diğerinin özlenmediği bir çocuk yanım var benim de. Gökteki uçurtmalara ıslak gözlerle bakan her çocuğun hüznüyle, koyu bir yeşillik altında sermayesine kaşık sallayan çocukluğumla ne tufanlar geçti benim de içimden. Nice karlar eridi, nice kardelenler tohuma durdu dağlarımda. Yapabilseydim eğer, sığlaştırırdım tüm okyanusları, yüreğimin uçsuz bucaksız tüm ovalarına gözlerini anımsatan çiçekler ekerdim. Yeryüzündeki bütün nehirlere çakıl taşları atardım, yüreğindeki şarkılar beni bulana kadar.

Her kelebek kanadında umudu taşırken, bilseydi kısa bir ömrünün olduğunu rengarenk bir renge bürünür müydü, sorarım kimi kendime. Gözlerinin derinliklerindeki tuvale, yüreğimdeki fırçalarla dokunup, kimi bir kelebeğin, kimi de bir kartalın kanadında gözlerine sarılıp uyumak, işte o an dünyayı yeniden yaratıp ayrılıkların hiç olmadığı bir atlasta sobelenmeye razı olurdum. Güldükçe aralanan dudaklarınla, ağladıkça nemlenen kirpiklerinle ve beni düşündükçe ağrıyan o sol yanınla, ölümsüzlük iksirlerini kaynatırdım aşkın o büyük kazanında.

Hazan kovmuşsa baharı, yeni mevsimlere açık tutmalısın kapını. Her dalın tomurcuğa tutkun olduğu, her arının bal için çiçek çiçek dolaştığı, her atın özgürlüğe topuk salladığı bu çelişkiler yumağında, demirci örsü döverken, ayrılanlar kadere söverken, her taş suskunluğuna ağlarken, sevda demire suyu, taşa ölümsüzlüğü, kadere de dönülmezliği vermiştir. Her şafakta doğan güneş dağları aşmadan, acı olgunlaşıp yüreklere düşmeden, soğuktan üşümüş ellerimi ruhunda ısıtmadan, bu yüreğime saplanan süngülerden kaçmak istemiyorum.

Tenime ter olacaksa nefesin, yıldızlarını gönder ülkeme. Koynumdaki fısıltıyla güller ol toprağımda. Denizlerimin mavi düşü, nehirlerimin çakıl taşı ol istersen. Asırlardır kartallarla sevişmelere duran dağlar, aslında mavi olduğu için tutkundur gökyüzüne. Karacaların su içtiği nurlu denizlerde, engelleri aşamayan, karanlıkta tütsülerle ağlayan ve bir balıkçı meyhanesinde kadeh üstüne kadeh deviren sevdalılarla dönmekte anlayacağın bu küre. Hiddetle kırılan kadehlerde tan ağarınca görünür gerçeğin dibi. 

Pervane böceğinin ışığa küstüğü anlarda, gölgelenir ansızın duvarlar. Aşkı cebimizde rengi kaybolmuş bir zar gibi gezdirirken, hep yek umarız yaşamdan. Kimimiz yek atıp, kimimiz düşeş atarken hiç yaşlanmayacak bir ruhla şarkılara ağlarız. Emdiğimiz süt ak, uykumuz sak ve gecelerimiz hain tuzaktır kardelen. Masallardaki tüm düşleri özleriz de, birini yaşamaya gücümüz yetmez. Sen, yüksekte bir kayanın altında denize sevdalı, yüreğimde yalınayak gezinen, küreksiz denizlere çıkan, rüzgarı asla hesap etmeyen, gönlüme zamansız düşmüş bir kardelensin. ‘Senin yurdun dağlardır, hep yüksektesin, elimden tutamazsın kardelen! ’…

Dedim ya, düşlerin asla sorgulanmadığı, yasakların hiç olmadığı, saatlerin hiç tik-taklara durmadığı  bir yer var ruhumda. Her bahar yeniden doğar, her sonbaharda  gazel olurum ben. Her bekleyişin benden yılları çaldığı anlarda, incinir içimde en sabırlı bekleyişler. Gecemin rengi karadır ve binlerce çocuk ağlar ruhumda. Gönlümüzdeki bakir sabahlar adına, içimizde hiç eskimeyecek, hiç eksilmeyecek şarkılar adına, dağlarında otağ kurdum işte. Yağmur duasına durarak ellerimi açtım sana. Sana soyunmak, zeytin gözlerinin kulelerinde ufku gözlemektir. Ölümsüzlüğü ve çözümsüzlüğü  kutsal kılan her sevda gibi, şimdi seni soluyorum bu ozan göğsümde.', 'Acılarla örülmüş bir duvardı senden önce yüreğim Hüznün mevsimlerinde ayrılığı söyledi hep şiirlerim Bitti yaşadığım kırlangıç fırtınası, ya...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-yagiyor-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Biraz Gam Var', 'yuregimde-biraz-gam-var-zeliha-bicer-g02wj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimde biraz gam var

Biraz hüzün,

Biraz sen. 

Yemyeşil kesilirim birden

Gözün gözüme değdiği zaman.

Yüreğimde bulutlar yüklü,

Zamansız yağan

Yağmur damlaları var. 

Yolları düşünsem biran

Gidişin gelir aklıma

Buz kesilirim o zaman.

Martılarım geliyor rıhtımda yürürken,

Çığlıklarında kanatlarında sevgim.

Çırpındıkça onlar karşımda

Serinliğim olur.

Sevgim birikir yine 

Dereden geçer ırmak olur 

_Gelişlerin de_

_Gidişlerin de_ 

Olsun yar...

Sen benlesin..

Beni seviyorsun ya! 

Bu yeter! 

Bu yeter! 

Yüreğime....', 'Yüreğimde biraz gam var Biraz hüzün, Biraz sen.  Yemyeşil kesilirim birden Gözün gözüme değdiği zaman. Yüreğimde bulutlar yüklü, Zamansız ya...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuregimde-biraz-gam-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba 12', 'merhaba-12-tulay-i-cen-yuxng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba can.,

Can merhaba her zaman yazdığım ve söylediğim gibi seni özledim.Özledim.

Bu günde akşam oldu  ben yine sensiz  ve karanlıktayım.Biliyormusun  karanlıklar artık beni  korkutmuyor, şunuda  öğrendimki korkunun  hiç bir şeye faydası yok, korksakta  olacak olayların  önüne gecemeyiz, neler yazıyorum yine.yazdığım şeyleri ben bile mantıksız buluyorum.

Can biliyormusun.Bazı şeyleri yazmak  istediğim halde  yazamıyorum.Duygularım körelmiş gibi kendimi  boşlukta hissediyorum.

Bu yazıyı yazarken  seninle geçmişe döndüm ama  düşüncelerim karmakarışık, gözümden öyle çok şey geciyorki hiç biri birbiriyle  bağlantılı değil, seninle konuşmakta  güçlük çekiyorum.

Seninle sanki konuşacak  konu kalmamış gibi.Aklımdan geçenler karmakarışık..Kendimi hiç iyi hisetmiyorum  ama bildiğim tek şey var seni özlüyorum ve seni hala cok ama cok seviyorum.

Gecenin karanlığından,

gelen bir ışık gibisin.

Şuan benimlesin.

sana  söyliyecek,

sözler dökülmüyor.

sanki 

Zincirle bağlanmış gibi

Dilim.

Kırmalı zincirleri

anlatmak tek, tek.

Seni ve beni.

Seni seviyorum. 

Seni özlüyorum.

05/11/1995', 'Merhaba can., Can merhaba her zaman yazdığım ve söylediğim gibi seni özledim.Özledim. Bu günde akşam oldu  ben yine sensiz  ve karanlıktayım...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merhaba-12-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Bismillah', 'haydi-bismillah-ahmet-sali-6gq54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hükmetmiştir sokaklara soğuk - fakat-

Engelleyemez baharın kokusunu...

Tedirginlik damgalı odalarda; 

Duyulur Tv''lerden savaş haberleri 

Aklı olanlar; 

Akılalmaz görüntülere yorarlar kafalarını.

Düşünene ibrettir; 

Ruhumu şeytana satanlarla 

Köle ruhluların sözde didişmesi! ...

Gözyaşlarını silebilmek nimet olurken

Kolları kopan çocuğa

-Halbuki en tabii hakkıydı-

Düşünceler kanamaya başlar 

Düğümlenir boğaz''lar 

İnsanca utancın hıncıyla! ...

En ciddi darbeyi alır 

Şeytan ruhlu''yla, köle ruhlu 

Danışıklı dövüşün arenasında! 

Mermi yağmurundan yavrularını koruyan 

Annenin; 

Kameraya yakalanan endişeli 

Bakışlarıy''la...

Bir esenliğin esintisi beklenir olur

Çocuğa kol,

Anaya güven gerektir artık ve 

Bir deccal kadavrasını biçen 

Öfkenin sesi! ...

-HAYDİ BİSMİLLAH-', 'Hükmetmiştir sokaklara soğuk - fakat- Engelleyemez baharın kokusunu... Tedirginlik damgalı odalarda;  Duyulur Tv''lerden savaş haberleri  Akl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Salı']::text[], 8.5, '{"poet":"Ahmet Salı","poet_slug":"ahmet-sali","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/haydi-bismillah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üniversite yolu', 'universite-yolu-abdulhamit-aydin-5m0hh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıktan aydınlığa

                                       Umutsuzluktan umuda

                                       Bir yola çıktım.

		

                                                                                       Bu yol; 

                                                                          Uzun ama çetrefilli bir yer

                                                                        Aşması zor ama aşılmaz değil

               Sanki; 

Heybetli ve sarp bir dağ

Attıkça kulaç atılan bir deniz

Dolandıkça sonu gelmeyen labirent

                                                                                     Korkma! 

                                                                           Bu dağın ardı güzellik

                                                                           Bu denizin sonu güzellik

                                             	                           Bu dolambacın sonu güzellik

          Güven! 

Yapacağının en iyisini yap

Yapmadıysan kendini bitirme

Yaptıysan da bitti yeter deme

                                                                                     Bir daha de! 	  	

                                                                              Olacak tesellisi ver

                                                                        Daha iyi yapacak gazı ver

                                                                     Koca dünyasın, aldırma takma

       Uygula ve başar                 

Uzun maratondasın, pes etme! 

Uzun buz pistindesin, kayıp düşme! 

Uzun bir mağaradasın, bırakıp gitme! 

                                     Karanlıktan aydınlığa

                                     Umutsuzluktan umuda

                                     Bir yola çıktım.', 'Karanlıktan aydınlığa                                        Umutsuzluktan umuda                                        Bir yola çıktım. 		 ...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Aydın']::text[], 8.5, '{"poet":"Abdülhamit Aydın","poet_slug":"abdulhamit-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/universite-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür...', 'sukur-ali-orhan-gunaydin-dvh9s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sağol be dostum,

Nasılsın? diye sormuşsun.

Şükür,

Nefes alabiliyorum ya,

Daha ne olsun? 

      04/01/2006', 'Sağol be dostum, Nasılsın? diye sormuşsun. Şükür, Nefes alabiliyorum ya, Daha ne olsun?        04/01/2006...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sukur-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün delillerin üzerinde', 'butun-delillerin-uzerinde-guler-atas-g3y6k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün 

Eminönü vapuru......

               Martılar karabataklar...

Kirli maviden  - Turkuaz yeşile

                            Bütün boğaz.

Çay ikram ettik sana ellerimizle.

Yoktun ama bakıyordun..

Görmüyordun....

Ama oradaydın.

Çeliştim kendimle.

İçimin caddelerinde koşan kim....

Sokakları denizde biten bu şehir.

Yakar artık kızkulesi’ni...

                Galata ‘yı–Emirgan ‘ı

Yakar kibritçi kız hikayesiyle

İçimin sokaklarını..

O sokaklar ki öykünü anlatıyor hala....

Ulaştığı sahillerde deniz kuşlarına.

Çocukları seni bekliyor....

Büyütmek için barikatları.

Gel...............

bana değilse de.....

Terk edecek kadar sevdiğin....

Bu şehre.

Bugün KARAKÖY vapuru seni taşıdı....

Haydarpaşa garına.

Oğlunu bulmuş ana gibiydi yollar.

Ve bu gün.

Bir gemide kundaklandı duygularım...

Bütün  delillerin  üzerinde

Parmak izlerin..

Bu şehir mutlu ben üzgün

                                             04 /01 /2006', 'Bu gün  Eminönü vapuru......                Martılar karabataklar... Kirli maviden  - Turkuaz yeşile                             Bütün boğaz...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/butun-delillerin-uzerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
