INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güvercin', 'beyaz-guvercin-altay-taskin-xjefx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uçma kuşum bensiz

beraber uçalım uzaklara

paylaşalım barışı ufuklarda

unutursan beni

kalırsın nefessiz

barış kalır anız tarlasında

al beni de yanına

barışı kanatlandıralım

zeytin dallarında...', 'uçma kuşum bensiz beraber uçalım uzaklara paylaşalım barışı ufuklarda unutursan beni kalırsın nefessiz barış kalır anız tarlasında al beni d...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beyaz-guvercin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılırken Sevdan, Oldum Kefil', 'satilirken-sevdan-oldum-kefil-i-brahim-halil-demir-lod2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın pazarlarında satılırken sevdan,oldum kefil,

Kırdın kolum kanadım,bitirdin servetim,ettin sefil.

Çektin çekebildiğin kadar sevda yayını,sapladın okun,

Arifler meclisinde kamil iken, unutturdun  bildiklerimi oldum cahil.

Sevda savaşlarında seven mağlup sevilen ise olur hep galip,

Seven, sevilen uğruna, Ferhat misali, su getirmeli dağlar delip.

Tutsunlar kollarımdan atsınlar beni sevdaların en girdabına,

İstemem sormasın dostlar, yapmacıktan halimi gidip gelip.

Sevilen daim ışıktır sevenin sevdalı gözlerinde,

Çok anlamlar yüklüdür onun için sevilenin sözlerinde.

Seven çok yorulur,zira çok nazlanır çok da şımarık olurlar,

Sevgilerinin gizlendiklerini bilirler sevenlerin yüreklerinde.

Sevilenin gözleri daima seven için ceylanı anımsatır,

Seke seke yürüyüşü dünyaya küstürür,yürekleri hoplatır.

Ona hiçbir zarar dokunmasın,üzülmesin diye,

Seven, her şeyini seve seve bir tatlı tebessümü için sattırır.

06/01/2006', 'Aşkın pazarlarında satılırken sevdan,oldum kefil, Kırdın kolum kanadım,bitirdin servetim,ettin sefil. Çektin çekebildiğin kadar sevda yayını...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/satilirken-sevdan-oldum-kefil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zülfe divane', 'zulfe-divane-ali-riza-unal-t5m90', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimdedir güneşi solduran,o yüzün mahı,

kim bilir  bağra dökülen,zülfü siyahı,

bir nakışki görenin, tükenir  ahı

açtırma  hicabı sin-i,zülfe divane,', 'kimdedir güneşi solduran,o yüzün mahı, kim bilir  bağra dökülen,zülfü siyahı, bir nakışki görenin, tükenir  ahı açtırma  hicabı sin-i,zülfe ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zulfe-divane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan Seni Seviyorum', 'i-nan-seni-seviyorum-yusuf-onder-bahceci-rbto0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi şiir yazıyorum,

Ayrı düştük kızıyorum,

Herşey hayır diyorum,

İnan seni seviyorum.

Beni sevdin biliyorum,

Sana sitem etmiyorum,

Yalan söze kızıyorum,

İnan seni seviyorum.

Sevdan ile yanmışım,

Yanan kalbi görmüşüm,

Senin için ölmüşüm,

İnan seni seviyorum.

Seni sevdim seveceğim,

Sana cânım diyeceğim,

Senin için öleceğim,

İnan seni seviyorum.', 'Şimdi şiir yazıyorum, Ayrı düştük kızıyorum, Herşey hayır diyorum, İnan seni seviyorum. Beni sevdin biliyorum, Sana sitem etmiyorum, Yalan s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inan-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Alırdım Ellerinden', 'seni-alirdim-ellerinden-yusuf-onder-bahceci-6dxaw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elim, kolum bağlı, bağlı,

Seni benden onlar ayırdı,

Eğer şimdiki aklım olsaydı,

Seni alırdım ellerinden.

Şimdi elimden bir şey gelmiyor,

Sen evlisin Önder bunu biliyor,

Benim yüzüm birgün olsun gülmüyor,

Seni alırdım ellerinden.

Seni gerçek seven bendim ben,

Yok desen bile tutardım ellerinden,

Bize büyümü yaptılar bilemedim ben,

Seni alırdım ellerinden.....', 'Elim, kolum bağlı, bağlı, Seni benden onlar ayırdı, Eğer şimdiki aklım olsaydı, Seni alırdım ellerinden. Şimdi elimden bir şey gelmiyor, Sen...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-alirdim-ellerinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-i-lyas-genc-8oiqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sana yazdığım son şiirim,

Son bedduam, son günahım olsun…

Gözlerin uzaklarda beni arayıp dursun..

Yüreğinde acımı doyasıya yaşayasın..

Elveda diyemiyorum sana, 

Mevsimsiz çiçekler yüreğinde açsın.

Kör olsun talihin, gülmesin şansın..

Benim gibi seveni bir daha bulamayasın…

Bütün aşklar yıldızlar kadar uzağında olsun,

Seni gören sana acısın, aşklardan uzak dursun

Göz yaşların yağmurlarla birleşip sele karışsın..

Kalbin iflas etsin.. amaçsız yaşayasın,

Gülmelerin yalan bakışların haram olsun..

Sevda tuzaklarında yargısız infazda kalasın

Tutkulu aşkların kölesi olasın…

Dilerim Mevla’m dan acılar içinde acı yaşayıp.

Bütün kayıplarını en mutlu olduğun anda bulup,

Sonra tekrar kaybedip yeni acılar yaşayasın..

Akşam ağarmadan sacların ağarsın.

Adımı her caddenin adı sanıp

Deliler gibi sağ sola dolanasın.

Beni yaktığın gibi sende yanasın

Ömrün boyunca yuva kuramayıp 

Anne olamayasın..

Tuttuğun dokunduğun ne varsa

Beni hatırlatsın… Beni arasın…

Sende benim gibi hayata doymadan

Hayatından bıkasın….

Bıkasın ki..! hayal ettiğin ne varsa yaşam adına

Bu şiir gibi..son öpüşmemiz gibi.. yarım kalsın…….

yasak.tutku', 'Bu sana yazdığım son şiirim, Son bedduam, son günahım olsun… Gözlerin uzaklarda beni arayıp dursun.. Yüreğinde acımı doyasıya yaşayasın.. El...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beddua-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Diyene Kadar', 'sevdim-diyene-kadar-yusuf-onder-bahceci-br32a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakın yanlış anlama,

Şimdi şiir yazarım,

Yazar yazar bozarım,

Sevdim diyene kadar.

Şiir yazdım dağlarda,

Gezdim viran bağlarda,

Seni sordum Samsun''da,

Sevdim diyene kadar.

Denize baktım durdum,

Kalbimi yaktın durdun,

Ellere seni sordum,

Sevdim diyene kadar.

Sensiz mutsuz geceler,

Dilim adın heceler,

Bu nasıl bilmeceler,

Sevdim diyene kadar....', 'Sakın yanlış anlama, Şimdi şiir yazarım, Yazar yazar bozarım, Sevdim diyene kadar. Şiir yazdım dağlarda, Gezdim viran bağlarda, Seni sordum ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdim-diyene-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aralıktan', 'araliktan-kadir-ucvet-9l8xh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aralıktan; 

küçük gözler bulurdum

kendime,

bakacak..

ufacık sözler satardım

iyimserliğimde

salın(a) cak.

Dün: güzel ama

hazin seslerdi.

Bugün: 

O’nu arıyan..', 'Aralıktan;  küçük gözler bulurdum kendime, bakacak.. ufacık sözler satardım iyimserliğimde salın(a) cak. Dün: güzel ama hazin seslerdi. Bugü...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/araliktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Fırtınası', 'gonul-firtinasi-i-lyas-genc-up2f2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımda hep yanlış yaptım,

Yanlış insanları yanlış zamanda sevdim.

Oysa seni tam zamanında sevmiştim

Sen on sekize yeni girmiş, bende

Yirmi dört yaşımı bitirmiştim..

Seninle alakalı tüm geleceğimin

Planını kurmuş, 

Dualarımla Allah’ıma sığınmıştım…

Sanıyorum yine yanıldım

Yine yanlış yaptım….

Biliyorum..! Bu mektupta diğerleri gibi

Yanlış insanların elinden,

Yanlış adreslere dolaşacak

Yetmiş milyon okuyacakta 

Sana okumak nasıp olmayacak..

Olsun…! Yazdığım mektuplar bana

Yazamadıklarım sana kalsın..

Ben annemi hiç tanımadım 

Çoğu zaman yıldızları anne diye çağırdım

Annemin kucağında uyumak hiç nasıp olmadı

Senin kucağında uyuduklarım bana

Bundan sonraki bütün uykularım sana kalsın…

Öfkeme yenilip sana beddualar ettim

Ama sana ettiğim beddualara 

Amin demeye dilim varmadı. 

Ettiğim beddualar bana, 

Yapamadığım bütün dualarımda sana kalsın..

Sen kışın ortasında baharı yaşarken

Benim saclarıma da her mevsim karlar yağsın…..

Sen gözlerinin rengini gökyüzündeki maviden al 

Benim yeşil gözlerim de çamurlara bulansın..

Gece sefaları bana,diğer tüm çiçekler sana kalsın.

Dilden dile dolaşan ağıtlarım sana

Defterimin arasında ağlayan dizelerimde bana kalsın

Bu dünyada ve diğer dünyada 

Cennetti yaşamak sana,

Cehennemlere yanmak ta bana kalsın…

Ne kadar acı çeksem de ağlayamam

Çünkü sen benim gözyaşımdasın

Allah’ıma yalvarırım ki..! 

Sana gelen bütün belalar senden önce beni bulsun

Senden başka yar seversem, darağacında sallanmak,

Şu değeri beş para etmez boynumun borcu olsun…….! 

yasak.tutku', 'Hayatımda hep yanlış yaptım, Yanlış insanları yanlış zamanda sevdim. Oysa seni tam zamanında sevmiştim Sen on sekize yeni girmiş, bende Yirm...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gonul-firtinasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş (004 – Ürettiğin din)', 'yuruyus-004-urettigin-din-mehmet-coban-uj5cp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönülden yaptığını

Emrimle karıştırma

Biri benim senden istediğim

Diğeri senin bana verdiğin

Senden istediğimi vermezsen

Dinin gider elden

Kendi istediğini vermezsen

Kaybetmezsin dininden

Gönlünden coşan değil din

Sen onu fazladan verdin

Böylece hem kendini

Hem beni sevindirdin

Ama karıştırırsan 

Emrimle istediğini

Fark etmezsin şirke girdiğini

Farzı ben emrederim

Sen yaparsın

Nafileyi sen istersin

Sen yaparsın

Karıştırırsan farzla nafileyi

Boşa yaparsın bütün amelleri

Amellerin hepsi güzel olsa da

Farz nafile karışınca 

Din kalmaz ortada

Üstün görme nafileyi farzdan

Üstün görürsen nafileyi farzdan

Koyarsan nafileyi farzın yerine

Şirk gelir, inancının yerine

Gördüm ki, farzlarım yok hayatında

Nafile olanlar kavgan olmuş hayatında

Farzlarım yok olmuşsa hayatında

Nafileler olmuşsa hep din kavganda

İnandığın ve yaşadığın din benim değildir

İnandığın din, kendi ürettiğinden başkası değildir! ..

06.01.2006-İzmir', 'Gönülden yaptığını Emrimle karıştırma Biri benim senden istediğim Diğeri senin bana verdiğin Senden istediğimi vermezsen Dinin gider elden K...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yuruyus-004-urettigin-din-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşım Gençmiş Bilmemişim', 'yasim-gencmis-bilmemisim-yusuf-onder-bahceci-bh4xk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdim seni gözlerinden,

Uçup gittin ellerimden,

Ölürüm ben kederimden,

Yaşım gençmiş bilmemişim.

Keşke sevdim deseyidim,

Sana yandım deseyidim,

Güzel sözler söyleseydim,

Yaşım gençmiş bilmemişim.

Sevdan beni öldürdü,

Sanma yüzüm güldürdü,

Ömür boyu süründürdü,

Yaşım gençmiş bilmemişim.

Şimdi seni arıyorum,

Ben rüyada görüyorum,

Seni sevdim özlüyorum,

Yaşım gençmiş bilmemişim....', 'Sevdim seni gözlerinden, Uçup gittin ellerimden, Ölürüm ben kederimden, Yaşım gençmiş bilmemişim. Keşke sevdim deseyidim, Sana yandım deseyi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasim-gencmis-bilmemisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Var?', 'kim-var-murat-polat-2-i3mqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden başka kim var içimde? 

“Ses ver” dediğimde...kendime

Bir ölü kadar sessiz,

Bir buz kadar soğuk...

Benden başka kim var içimde? 

“Çık dışarı” dediğimde,

Çıkmak istemez yerinden.

Bir sağır gibi duyarsız

Bir dilsiz kadar sessiz...

Benden başka herkes içimde

Bir gürültü, bir karmaşa sorma

Savaş alanı sanki her yer kan revan.

Sanki herkes herkese düşman...', 'Benden başka kim var içimde?  “Ses ver” dediğimde...kendime Bir ölü kadar sessiz, Bir buz kadar soğuk... Benden başka kim var içimde?  “Çık ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Değilim', 'i-yi-degilim-murat-polat-2-vm2bz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alışmışım her halde sana

Kendimi çok yalnız hissediyorum.

Ne kadarda çabuk bitiyor

Ne çabuk gidiyor huzurum.

Ben mi tüketiyorum acaba 

Yoksa hep tükenmiş mi geliyor? 

Hep zirveyi zorluyor

Küçük tepelerde zevk almıyorum.

Alışmışım herhalde sana

Kendimi çok mutsuz hissediyorum

Ne çabuk bozulup dağılıyorum

Ne kadarda hızlı.

Ben mi bilmiyorum acaba

Yoksa hep yenilenip mi geliyor

Hep olmazı zorluyor

Olanı görmüyor bu gönlüm.

Belki de alıştım yalnızlığa

Kendimi hapsediyorum.

Her çıkışta dışarı

Bocalıyor kayıyorum.

Ben mi zorluyorum acaba 

Yoksa hep zorumu geliyor

Neden bu uğraş, bu telaş

Nereye koşuyorum?', 'Alışmışım her halde sana Kendimi çok yalnız hissediyorum. Ne kadarda çabuk bitiyor Ne çabuk gidiyor huzurum. Ben mi tüketiyorum acaba  Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iyi-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa', 'yoksa-murat-polat-2-a95m8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allah’ım, Allah’ım, Allah’ım

Diye inleyen ben değilmiyim? 

Kurtar beni, kurtar beni...

Diye inleyen ben değilmiyim? 

Bu nasıl bir hastalık? 

Ben mi onu meşhur ediyorum

Yoksa o mu beni rezil...', 'Allah’ım, Allah’ım, Allah’ım Diye inleyen ben değilmiyim?  Kurtar beni, kurtar beni... Diye inleyen ben değilmiyim?  Bu nasıl bir hastalık? ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yoksa-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-nadire-gulcicek-ryvw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen geçip giderken,

Nasıl da dokunmuşsun saçlarıma…

Gri,beyaz karışımı tel-tel izlerin var! 

Dokunduğun yüreğim bezgin,suskun,yaralı,

İzlerin var, yaralı kalp atışlarımda…

İşte o zaman,

Tutamıyorum  avuçlarımda…

Akıp gidiyorsun hoyratça! 

İçinde masum umutlarım, sevdalarım,

Hayallerime akıyor, çocukluğum,gençliğim,

Bedenim sızlayıp,ıslanıyor,

Yağmurlaşan gözlerimde…

Bir yaprak düşüyor dalından, 

Suya bir yansımayla…

Su üşüyor, göz düşüyor,

Yüzleşiveriyor  yüzüm  dar zamanla…

Zaman  zaferde, sen özlemine yenik,

Kaybolmuşluklar içinde bir sevgili…

06-01-2006 (Nadire aktaş)', 'Sen geçip giderken, Nasıl da dokunmuşsun saçlarıma… Gri,beyaz karışımı tel-tel izlerin var!  Dokunduğun yüreğim bezgin,suskun,yaralı, İzleri...', ARRAY['Türk Edebiyatı','Şiir','Nadire Gülçiçek']::text[], 8.5, '{"poet":"Nadire Gülçiçek","poet_slug":"nadire-gulcicek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zaman-280-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahlımı Arıyorsunuz?', 'gunahlimi-ariyorsunuz-kamil-at-slp9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halkları ezenler

Halktan çalanlar

İnsanlığı üzenler 

Çalarak bulanlar.

Savaşları isteyenler

Doğrular pis diyenler

Yiğide hapis diyenler

İki ayaklı yılanlar.

Düşünceye saygı 

duymayanlar

Gerçekleri beynine 

koymayanlar

Hergün 

yoksullara kıyanlar

Günahlı, 

günahsız kalanlar.

İşte onlar

Günah içinde yüzüyor...', 'Halkları ezenler Halktan çalanlar İnsanlığı üzenler  Çalarak bulanlar. Savaşları isteyenler Doğrular pis diyenler Yiğide hapis diyenler İki ...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunahlimi-ariyorsunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hel hel ettim hamaradan mağradan', 'hel-hel-ettim-hamaradan-magradan-asik-veli-2-pkvxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hel hel ettim hamaradan mağradan                

Dediler bir Suna gitti bu yola

Elim ile evlerini göçürdüm

Telli Suna gitti derler bu yola

Başına bağlamış hindi balası

Belasını rakibinden bulası

Akbaba tekkesi Elburs* kalesi

Dediler bir Suna gitti bu yola

Başına bağlamış hindi dediler

Aşıklar lebinden emdi dediler

Vardı Başkışlaya kondu dediler

Dediler bir Suna gitti bu yola

Gitmiyor yavrunun hayali sözü

Yarim sürmelemiş eladır gözü

Kalaycık geçidi Hocabey özü

Dediler bir Suna gitti bu yola

VELİM eydir yetemedim ilkinden

Göremedim püskülünden börkünden

Kündelenden Köklü yoldan Sorgundan 

Telli Suna gitti derler bu yola.', 'Hel hel ettim hamaradan mağradan                 Dediler bir Suna gitti bu yola Elim ile evlerini göçürdüm Telli Suna gitti derler bu yola B...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veli 2']::text[], 8.5, '{"poet":"Aşık Veli 2","poet_slug":"asik-veli-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hel-hel-ettim-hamaradan-magradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olmalıyım', 'ben-olmaliyim-saadet-un-l8jdq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'soldurmayın rengimi

esen neşemi

bir mutluluk şarkısı da 

ben çalmalıyım

sevda olmalıyım 

aşk olmalıyım

kendimden muhteşem bir kadın

yaratmalıyım

üşüyen bu bedenin

titreyen kalbin

güneşi ben olmalıyım

ısıtmalıyım

toprakta bir tohum

tohumdan fidan

bir yiğidin türküsü de 

ben olmalıyım

sevilen ben olmalıyım

sevilmeliyim', 'soldurmayın rengimi esen neşemi bir mutluluk şarkısı da  ben çalmalıyım sevda olmalıyım  aşk olmalıyım kendimden muhteşem bir kadın yaratmal...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-olmaliyim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün...', 'bugun-arzu-gulucudur-wwf72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarının anlamı yok bugün

Bugün içinde saklı gün

Günün şifresi sen ve ben

Ben sen olmadan,yok olmaz bu beden

Sen ben olmadan,var olmaz ki geçen....', 'Yarının anlamı yok bugün Bugün içinde saklı gün Günün şifresi sen ve ben Ben sen olmadan,yok olmaz bu beden Sen ben olmadan,var olmaz ki geç...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bugun-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimize', 'hepimize-mehmet-ayhan-gunaydin-btk4v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HEPİMİZE

Olursa bir korkun yalnız ölümden olsun.

O da; 

Verilecek son nefesi,

Gönlünden geçtiğince verememekten olsun.

Hepinizin Kurban bayramı kutlu olsun.

M. Ayhan Günaydın.

    6 Ocak 2005

        Ankara', 'HEPİMİZE Olursa bir korkun yalnız ölümden olsun. O da;  Verilecek son nefesi, Gönlünden geçtiğince verememekten olsun. Hepinizin Kurban bayr...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hepimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozuk Niyet', 'bozuk-niyet-ozan-naroglu-jhj8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kötü niyetli siir ya bu; oldu iste

büyük acilarim kücüklerini kiskandi! 

kücük acilarim iyi niyetli,küsüklügünden utanip; büyüklerinin allahina,kitabina...

sövüp saydi

evimin odalari birbirine uymuyor''odabasi''

icimdeki sonbahar kislarin kapisinda can cekisiyor

ama

ölmüyor...

ve simdiki zamana öykünen cümlelerim

di´li gec(mis)  zamanima agliyor.

eyyy salya sümük (gel) ecek! 

sinirindayim su anin! ! ! 

hani istesem diyorum,yani istesem,

........ker giderim.', 'Kötü niyetli siir ya bu; oldu iste büyük acilarim kücüklerini kiskandi!  kücük acilarim iyi niyetli,küsüklügünden utanip; büyüklerinin allah...', ARRAY['Türk Edebiyatı','Şiir','Ozan Naroglu']::text[], 8.5, '{"poet":"Ozan Naroglu","poet_slug":"ozan-naroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bozuk-niyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinde Taşlar Ve Savaşlar', 'filistinde-taslar-ve-savaslar-seyfet-bozcali-nm9ac', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dinmedi ortadoğu da savaşlar.

Yıllarca raflara kalktı barışlar,

Devlet olmak Filistin''de tüm düşler, 

Özgürlük uğruna atılan taşlar...

Amerikan desteği,  yahudi zulmü,

Altmış yıldır hep seyrettik bu filmi,

Toprağından sürülmek insanlıkmı, 

Hep sel oldu aktı göz yaşı kanlı...

Sokak ortasında kollar kırıldı,

Baba kucağında oğullar öldü,

Dünya ekranlardan seyirci kaldı,

Vatan özlemiyle ezildi başlar.

Gözü dönmüş İsrail askerleri,

Yaktı,yıktı şehirleri köyleri,

Tanklarla ezdiler genç cesetleri,

Betono gömüldü kurulan düşler.

İnsan hakkı savunanlar yok oldu,

Zulümle Filistin baş başa kaldı,

Hitlerin yerini Şaron''lar aldı,

Topa,tanka karşı çaresiz taşlar...

Hangi yürek dayanır bu acıya,

Dur diyen yok yıllar süren sancıya,

Sokakta perişan ana bacıya,

Sahip çıkmak için atılan taşlar...', 'Dinmedi ortadoğu da savaşlar. Yıllarca raflara kalktı barışlar, Devlet olmak Filistin''de tüm düşler,  Özgürlük uğruna atılan taşlar... Ameri...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/filistinde-taslar-ve-savaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El vurup yâremi incitme tabip', 'el-vurup-y-remi-incitme-tabip-asik-veli-2-r9ln0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El vurup yâremi incitme tabip  

Bende hayat bulmaz hicraneler var

Destin vurup tamir eylersin amma

Tamir kabul etmez viraneler var

Yareler döşenmiş figana başlar

Görelim ki kadir mevlam ne işler

Şu adüler bize deli demişler

Daha bizden önce divaneler var

Dert için ağlayan tabibe gelir

Arayanlar elbet dermanın bulur

VELİM derki kimde ne var kim bilir

Çekti gülizar etti elde neler var', 'El vurup yâremi incitme tabip   Bende hayat bulmaz hicraneler var Destin vurup tamir eylersin amma Tamir kabul etmez viraneler var Yareler d...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veli 2']::text[], 8.5, '{"poet":"Aşık Veli 2","poet_slug":"asik-veli-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/el-vurup-yaremi-incitme-tabip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum Hayal Kırıklığımda', 'seni-ariyorum-hayal-kirikligimda-multe-ci-han-d64ka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni gördü gözlerim

 Kapalı kapılar ardından

 Uzakta

 Sensizliğin köşe başında

 Seni ararken hayal kırıklığımda

 Ufukta umutların bittiği yerdeyim

 Herşeyden soğuk...

 Seni arıyorum yine

 Hasretim ellerine

 Hasretim o güzel yüzüne.

 Hala hissediyorum seni başucumda

 Hayalin hala benimle

 Ruhun bedenimde

 Eminim ki rüyalarında hala ben varım

 Yoksa ben böyle olamazdım

 Eğer karşılığı olmasaydı

 Ben böyle olamazdım

 Bir gün aynaya baktığımda

 Göremezsem seni

 Göremezsem hayalini

 O zaman bırakırım seni sevmeyi

 Hayallerimde seninle olup

 Sonsuzlukta yürümeyi', 'Seni gördü gözlerim  Kapalı kapılar ardından  Uzakta  Sensizliğin köşe başında  Seni ararken hayal kırıklığımda  Ufukta umutların bittiği ye...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-ariyorum-hayal-kirikligimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazımın yüzüncü doğum günü', 'nazimin-yuzuncu-dogum-gunu-abdullah-oral-28uqp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NAZIM''IN 100. DOĞUM GÜNÜ

                 Vay be vay anasını be

Vay benim ellerimde serpilip gelişen hayat

Vay benim 

        Aydınlık düşlerime

                   Saplanan hançer

Vay benim puslu yollarında

       Düşüp kalktığım yurdum.

Düşmüşüz iki kollu uçurumun

                   İki sarkık yanına.

Yüzlerini ayaklar altına almış

                   İnsanlar yürüyor

                   Kendi göğünden uzak uçurumlara.

Zulmün pençesine düşmüş özgürlüğüm

Can telef etmekte

        Sanayi yollarında

Nazım Hikmet

Vatan hainliğine devam ediyor hala. 

           II

Bugün 

Yüzüncü yaşına ayak basıyor Nazım

Sakın demeyin ha

Ölümden sonra yaş mı sayılır.

Sayılır lan sayılır

Adam gibi yaşayana ölüm mü olur.

Onlar 

Tek duvaklı gelinin 

Gerdeğine girer gibi 

Girdiler toprağın koynuna 

Hücre hücre sararak yurdu.

Ölümsüzlüğe kulaç atarak 

Aştılar ölüm denizini.

Onlardan bir çığlık kalır

Sokaklarda yansıması dinmeyen

Ölümsüzleşirken sevda 

Ölümsüzleşir isyan.

Yıllar öncesinin yansıması

Çınlıyor kulakları da

Amerikanın yarı sömürgesiyiz

                       Diyor Nazım

                    III

Ustaya hırlaşıyor

Kan buğusunda dişlerini ısıtanlar

Salyalı dudaklardan 

Dehşeti dökülmekte yaşamın.

Çok şükür, çok şükür

Ölsem de gam yemem gayri

Sonunda kurtulduk yarı sömürgecilikten

Şimdi

Tam sömürgesiyiz Amerikanın.

Emek işkenceye mahkum

Umut  dar ağacında

Yargısız  katledilmekte hayat

Şimdilerde

Deli dolu akıyor koyağında  sular

Başlarını çarpa çarpa taşlara

Nazım Hikmet

Vatan hainliğine devam ediyor hala.

Bir dolar bir buçuk milyon

Efendilikten kurtardık köylüyü

Kölesi yaptık yoksulluğun

İzavura lar bize ağlıyor şimdi

                  IV

Bütün kirlenmelere

Kapattıkça kapılarımızı

Alıcılarımızdan girdiler

                  Odamızın sıcaklığına.

Önce kültürlerimizi yozlaştırdılar

Sonra çaldılar duygularımızı

Gün geçtik çe

Kendi maymununu yarattı sermaye.

Haber dediler

Pisliklerini döktüler eteklerinden

Kim kiminle yatmış 

Kimin şeyi kimin neresinde

Piç ettiler yaşamı.

Piç ettiler serpilip gelişen hayatı

Şimdi 

Medya maymunlarının

  Salyalı dudaklarından 

           Hortumlananm kanı dökülmekte 

                             Emekçi halkımın.     

İki bacak arasına asılmış sevda.

Yoksulluğun-

Bekareti satılmakta otel odalarında.

Şose boylarında aç kadın 

Doyurabilmek için bebesini

Sarkık memelerini okşatmakta

Yüzünü yitiren insana.

             v

Fabrika kapılarında

Makina lar dan değersiz 

Kendi mezarına kazmakta emekçi.

Kul edilmiş insanlık kula

Nazım Hikmet vatan hainliğine

                             Devam ediyor hala.

Vay be- vay anasını be

Tükürmeli böyle yaşama

Nereden nereye geldik böyle.

Vay benim

Çürümüş damaklarımda

Kırılıp dökülen dişlerim 

Henüz çiğnenmeden çalınmış lokmam.

Vay benim omuzdan düşen kolum

Vay benim bir defa bükülüp

                Bir daha doğrulmayan belim.

Nereye böyle  ayaklarım 

Niçin susarsın dillerim 

Neden görmezsin gözlerim

Baksana, duysana, görsene 

Nazım Hikmet vatan hainliğine 

                Devam ediyor hala.

            VI

Nasırlanmış

Çatlak derisinden

Kanımı sızdıran

Ellerim

Bırak yazma gayrı

Yarına kalsın güzel sözler

Sevdalar aşklar

Tutkularım aydınlık özlemim.

Sakın ha Abidin

Sakın çizme

Mutluluğun resmini.

Hele bir sürelim maviye yelkenleri

Hele bir varalım gelecek o günlere

Sakın ha Abidin..

Bir umudum kalsın yarına

Bak gül yanaklı bebesini emziren

                                          Anneler

                                           Zehir içiriyor bebesine.

Sarı balık yitirdi rengini

Sakın ha Abidin...

Bu kahır öldürsün beni...

Çizersen

Çürütürler mutluluğu

Kırılır direncim 

Gelecek nesle kalsın

                          Mutluluğun resmi.

                  VII

..

Biraz daha bekle be Abidin

Hele bir hanımeli açsın

Tanyaların çığlıkları açsın balkonlarımızda.

Güneşe başkaldırsın

Utancını kasketin altına saklayanlar

Gözden kaçan gerçeğin

Dile düşen adıdır isyan.

Hasret yangını

Dudaklarımdan

Özgürlük türküsü dökülsün hele bir.

Hele bir

Yürek diretilsin

Diş bilensin

Yarınsız kalışlara.

Kırılsın bilekte zincir

Yıkılsın hücreler

Sevdam ulaşsın bulutlara

Baksana Abidin...

Nazım usta

Vatan hainliğine

Devam ediyor hala

         Vııı

Özgür bir dünya düşlerken

Hortumlandı damarımda kan.

Emek yenik düştü

Kasalarını vatan sayanlara

Afrikalılar gibi yaşıyoruz da

Avrupalaştık diyoruz.

Kendi kabuğuna çekilmiş

                          Cevahir yürekliler.

Sarhoş ağızlara yenik düşmüş

Direniş türkülerim.

Barlar pavyonlar

Devrimci tüketiyor

Kafatasçı üretiyor

Salyalı dudaklarda sarhoş naralar.

Umut ayaklar altında

Emek katlolmakta fabrikalarda

Nazım Hikmet vatan hainliğine 

                       Devam ediyor hala...

                      IX                              

Yüz yıllık 

Bir direniş türküsü Nazım

Bazen şiir olur

Bazen türkü

Bazen kaygısıdır kan içicilerin.

O şimdi

Başı göklerde bir çınar.

Çalamamışlar güneşini.

Rüzgarlara bırakmış şiirlerini.

Onun türküsü gelir uzaklardan

                             Rüzgarın kanatlarıyla.

Dağlar türkü söylüyor

Nehirler ağlıyor

Kalemim-

Pis yüreğine

              Dalıp dalıp çıkıyor.

Kahpeliğin ırkçılığın

              Ve satılmışlığın

Yüreğimde sevdası Nazım''ın 

Ellerimde isyanı.

Yıllanmış bir çınarbaşı yıldızlarda

Yüzüncü yaşında.

Vatan hainliğine devam ediyor

Nazım Hikmet RAN hala.......

                                                                     OCAK 2002', 'NAZIM''IN 100. DOĞUM GÜNÜ                  Vay be vay anasını be Vay benim ellerimde serpilip gelişen hayat Vay benim          Aydınlık düşle...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":207,"source_url":"https://www.antoloji.com/nazimin-yuzuncu-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-mazlum-unlu-d5ifk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilin yanında işte

İstediğin gibi

Gez, toz, eğlen 

Zaman gelecek hatırlayacaksın

Çay içerken,

Türkü dinlerken,

Şımarırken bir başkasına

Gülerken biri gözünü kapattığında

İşte o zaman karşına çıkacak

Ortaköy,taksim,gülhane 

İstanbul sana soracak 

mazlum nerde? 

Her şey canlanacak 

Hepsi dillenecek

Hesabı onlar soracak

Elbet aklına gelecek 

Umudum bu değil 

Bu olması gereken 

Olur ya 

Bir gün aklına düşersem

Beni özlediğini hissedersen

Beni görmek istersen

Hiç düşünmeden gel

Ya def ol git derim

Ya da gel yanıma 

yapacağın sadece gelmek

*Bu yazıları okuyacak mısın bilmiyorum.Bakalım  bu yazılar ile  ne zaman yüzleşeceksin.Gün geçtikçe unutuyorum seni.Ben unuttuğum zaman,sen hatırlayacaksın.', 'Sevgilin yanında işte İstediğin gibi Gez, toz, eğlen  Zaman gelecek hatırlayacaksın Çay içerken, Türkü dinlerken, Şımarırken bir başkasına G...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/pismanlik-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emperyalist Savaşlarda Yiten Dünya Çocullarına', 'emperyalist-savaslarda-yiten-dunya-cocullarina-abdullah-oral-vu17x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emperyalist Savaşlarda Yiten Dünya çoculları

Ben açlıkla doyurulmuş bir çocuğum 

Nişangahında kahpeliğin

Dünyanın her yerinde

Ölüm adlanır solgun gülüşlerime 

Bazen başımda kartallar bekler

Öldüğümde leşimi yemek için 

Bazen babamın kollarında vurulurum 

Filistin sokaklarında 

Bazen de paletler geçer

Masum gülüşlerimden 

Afganistan’da bombalar yaparken üstüme

Vietnam’da hala süngüsündeyim düşmanın

Hiroşima dün gibi aklımda

        II                  

Nedense bütün masallarda 

Devler hep yemektedir çocukları

Kanıma sulanır silahların ağızları

                           Göz yaşlarımı delip geçerken mermiler

Neden? bu öfkeniz beyler 

Neden bu durmayan kan 

Neden? Beyler Neden? 

Ben ölmekteyim

Bu anlamsız öfkeden 

Ne istedim ki sizden

Bir lokma ekmek 

Bir sıcacık gülüşten başka 

Ne istedim ki sizden

Bırakın yaşamak istiyorum

Yaşıtlarım gibi oynayayım koşayım

Onlarca bombanın ağırlığını

Nasıl taşırım çocuk omuzlarımda 

Çağı utandırıyorsunuz beyler 

              III

Nasıl duyurabilirim bilmiyorum

O sağır kulaklarınıza 

İçime sığmayan düşleri 

Ekmeğimi bala banmak

Annemin göksünde yatmak istiyorum

Babamın elinden tutup 

Gezmek istiyorum 

Çocukların öldürülmediği bir dünyada

Dilim farklı diye

Rengim farklı diye 

Nasıl söylenir bilmem 

Ben ölmek istemiyorum

Az sonra  yine bombalar yağacak üstümüze

Yine barut kokularını silecek

Baygın et kokuları

Yine çağın ihanetiyle yüzleşeceğim

                    

İki iri zeytin tanesi gibi 

Anlıma fırlayan gözlerimi sunacağım

Amerikan köpeklerine

               IV

Az sonra her şey yitirecek rengini

Delik deşik olacak 

Güzel olan her şeyin yüreği 

Yatağım yanacak beşiğim kırılacak 

Yüz bin çocuk olacağım

Yüz bin kız yüz bin erkek 

Körpe yüreğimizi sunacağız  çağın celladına

Yaralı bir geyiğin üstüne 

Sırtlanların üşüşmesine benziyor her şey

Leş kargalarının sırasını beklemesine 

Lağım farelerin etimi didiklemesine 

Bugün ıraktayım 

Yarın belli değil 

Hangi ülkede katledileceğim 

Ölürsem paylaşılacak etim 

Yaşarsam pazarlanacak bedenim

Tutsağı olacağım bu kanlı savaşın

Yada ağzı salyalı bir itin 

           V

Çocuk diye kandıramazsınız beni 

Ben yaşıma basmadan büyüdüm

Biliyorum az sonra gelecekler 

Ağızlarında diz boyu salya 

Elleri kanlı bıçaklı 

Emperyalistler 

Çok severlermiş taze çocuk etini

Gelecekler 

       Ve ırzına geçecekler bebekliğimin

Ama ben son olmayacağım 

Dün Filistin deydim

Bugün ıraktayım

Yarın belli değil işte 

Hangi ülkede 

Hangi yurtta vatansız öleceğim..

          VI

Siz hala susacak mısınız 

Anneler babalar

Katliama seyircimi kalacaksınız. 

Haydi gayrı sessiz çığlığımın sesi olun 

Ellerimin bedeni 

Umudumun yansıması 

Öfkemi tutun avuçlarınızda 

Yürek verin sesime 

Ölmesin sizinde çocuklarınız 

                     Yanmasın yüreğiniz 

Yarın sizin çocuklarınız olacak 

Emperyalist namluların ucunda 

Haydi gayri ağabeylerim ablalarım 

Umut yarına geç kalmasın

Bir daha hiroşimalar olmasın 

                                                                        Şubat 2003', 'Emperyalist Savaşlarda Yiten Dünya çoculları Ben açlıkla doyurulmuş bir çocuğum  Nişangahında kahpeliğin Dünyanın her yerinde Ölüm adlanır s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/emperyalist-savaslarda-yiten-dunya-cocullarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tok İnsan Acın Halinden Ne Anlar', 'tok-i-nsan-acin-halinden-ne-anlar-seyfet-bozcali-hlwdx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giyim kuşamına bakıp aldanma,

İnsanın halinden insan ne anlar,

Yaşamı boyunca bencil davranan,

Tok insan açın halinden ne anlar...

Hiç çile çekmeyen çileyi bilmez,

Gününü gün eder kimseyi görmez,

Eğlenceden bardan asla yorulmaz,

Tok insan açın halinden ne anlar...

Servetlere konar, emeksiz yaşar,

Gayri meşru yoldan evlenir boşar,

İnsanlıktan ırak kulvarda koşan,

Tok insan açın halinden ne anlar...

Fakirliğin ''F'' harfini görmemiş,

askari ücretle ev geçindirmemiş,

Ucuz ekmek için kuyruk görmemiş,

Tok insan açın halinden ne anlar...

Hayat felsefesi yalan ve dolan,

Geçmiş tüm yaşamı hiyleli pilan,

Kul hakkının ne olduğunu bilmeyen,

Tok insan açın halinden ne anlar...

Ayrık otu gibi biter her yerde,

Çare olmak istemez hiç bir derde,

Ahtapot gibidir aklı miydede,

Tok insan açın halinden ne anlar...

Yokluğun pençesine düşmemiş,

Yetimi, öksüzü hiç sevindirmemiş,

Hayır işlememiş, hayır görmemiş,

Tok insan açın halinden ne anlar...

Artık yaka sarmaz olmuş enseyi,

Haramlardan yana açar keseyi,

Çuval gibi sarkmış önde göbeyi,

Tok insan açın halinden ne anlar...

İnsan anlasaydı insan halini,

Reva görürmüydü bunca zulümü,

Yaparmıydı düşünseydi ölümü,

Tok insan açın halinden ne anlar...

Helalı, haramı ayırt etmeyen,

Şeytanı nefsine düşman olmayan,

Seyfet derki insanları sevmeyen,

Tok insan acın halinden ne anlar', 'Giyim kuşamına bakıp aldanma, İnsanın halinden insan ne anlar, Yaşamı boyunca bencil davranan, Tok insan açın halinden ne anlar... Hiç çile ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tok-insan-acin-halinden-ne-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahariye', 'bahariye-ozer-genc-pmwlv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan harmanını nasıl yüklenir? 

İçinden kırmızı tramvay geçen cadde

Mendil satan küçük kızlar

Dilenciler simitçiler,emekliler, yalnızlar

Tek tük İstanbul beyefendileri

Bedenini göstermekten başka hüneri olmayan buralı kızlar

Ucuz parfüm kokuları kendinden önce gelen

Ve baş bağlamaktan başka 

Tesellisi olmayan varoşlu kızlar

Ergen kollarının yasakları

Gözlerinden fırlamış

Rantiyeler,

Gözleriyle direnmeye çalışan 

Orta yaşlı kadınlar

Cadde''deki hizmetçiliklerini unutmaya çalışırken

Uzak evlerine dönmek zorunda olan 

Telaşlı kadınlar

Mevsimsiz kızarmış solaryum gülleri

Boğa heykeli süvarileri

Duvarlara yaslanıp çalan

Sokak müzisyenleri

İçlerinde sekiz on yaşlarında bir esmer çocuk var

Mızıkayla bildik bir şarkıyı çalar durur

Herkes vitrinlere bakar 

Ben ona bakarım

Yüreğimi dağlar boşvermiş yaz akşamlarında

Giyim dükkanlarından yayılan yadırgı ezgiler

Arada bir kızlarımla buluştuğum bankanın köşesi

O  eski tramvay Kadıköy''den değil de

Sanki çıngırdamayla 

Çocukluğumdan gelir

Uzay-zamanın iplerine asılmış

Karşıdaki sokaktan kızlarım gelir

Sanki iki genç kız değil de

Beyaz  basmadan uzun gecelikleriyle

Güllü adları gibi gül yüzleriyle

Çocuklukları gelir

Onlarla geçiridiğim doktorlu

Beş parasız, eczaneli,ilaçlı kışlarım gelir

Omzuma alıp oynadığım yazlarım gelir...

Bak yine beton ve eksoz günbatımını örttü 

Sen yarın Bahariye''ye gel

Dişlerinle inci gelsin

Saçlarınla mercan gelsin

Baştanbaşa caddeye yeni bir heyecan gelsin

Gurbetten dönüşlerde Türkçe gibi gel

İlk kavuşma akşamında tene dokunuşlar gibi gel

Deniz gibi çiçek gibi kuşlar gibi gel

Serçe gibi, martı gibi,kırlangıç gibi gel

Mayıs sabahlarında yeni bir başlangıç gibi gel

Gel ki  renkli fırçalar gezinsin

Bu gri manzaranın üstünde

Birkaç neşeli, ezgi katılsın 

Bu hüzün bestesine

Kadın eli değsin dağınık benliğime

Bak dün akşam buralarda

Pasaklı sevdalılar dolaşmış

Aşk ıslatmış sokakları yağmur yerine', 'İnsan harmanını nasıl yüklenir?  İçinden kırmızı tramvay geçen cadde Mendil satan küçük kızlar Dilenciler simitçiler,emekliler, yalnızlar Te...', ARRAY['Türk Edebiyatı','Şiir','Özer Genç']::text[], 8.5, '{"poet":"Özer Genç","poet_slug":"ozer-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bahariye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünüversite sınavında kızıma/Yarına koşu', 'unuversite-sinavinda-kizima-yarina-kosu-abdullah-oral-jl1nm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kitaplar.la dost olanlar 

   Yaşama dost kalırlar.

                                                                                                                                        Ünüversite sınavında kızıma

               YARINA KOŞU

                  Saat 9:45

Şimdi şu anda

Kendi geleceklerine

İlk adımı atıyor çocuklarımız

Düzenin engelli barikatları

Aşılması zor dikenli teller

Kimileri aşacak engelleri

Kimi düşecek daha ilk adımda

Kara duvarların

Aydınlık yüzleri düşerken 

                   Kiminin gözlerine

Kimisi  elleri kolları bağlı 

                   Nişangahında düzenin

                        Vurulup düşecekler

                              Karanlığın ortasına

Şimdi şu anda

Kahrolsun şuan yok

Yarının basamaklarına

Tırmanıyor çocuklarımız

Ellerinde bir kalem bir kağıt

                   Tutunacak bir dal aramakta geleceğe

Beklemekteyim

Tellere takılan kızımın 

Barikatları aşmasını

Ağır hantal bedenim

Kollarımı uzatamayacak kadar yorgun 

Ve ellerim ihanet içinde

Kaşımıyor kendi yarasını

                             

                               Saat 10:30

Göğüs kafesime sığmayan

Bir yürek depişmekte

                     Sol tarafımda

Çıldırdı

Zamanın gerisinde gitmenin

                    Utancıyla

Başımda haziran güneşi 

Dumanı titriyor

Dudaklarımda ıslanan sigaramın

Sam yeli vurmuş yanağıma

Gözlerim güneş yanığı

Çerçevesine tutunmuş bakışlar

Camlarına asılı kaldı okulun

Yelkovan on birin üstüne düşmek üzere

Yüreğimde ağrısı bekleyişin

Çocuklar hala ter dökmekte 

                           Gelecek için

Şimdi şuanda

Neresinde acaba kızım 

Aşılması zor barikatın

Yüzünü yitirmiş 

Sorular kuşatmış zamanı

Soğuk terler içinde

Çelişkilerle savaşmakta bakışlar

Her yanlış adım

Tabanlara,da patlayan

Serseri bir mayın gibi 

Zaman

Dibi delik bir kovada

Suyun kendi kendini

 Tüketişi misali akıp gidiyor

                                  Saat 11:52

Çocuklarımız

Suyu tutabildiler mi avuçlarında

Yada

Kaç damlasını yudumladılar umudun

Islandı mı dudaklar gelecek adına

Tırnaklarım dişlerimle oynaşıyor

Dişlerim dudaklarımı yontmakta

Saniyeler yelkovanı kovaladıkça

Akrep, ağır hantal  adımlarla

Devam ediyor yoluna

Ağırlaştıkça dizlerim

Yavaşça sırtımı verdim toprağa

Güneşi emzirmekteyim gözlerime

Birazcık gökyüzü 

           Birazcık mavi

Ufkumda kül rengi bulutlar

Nasılda aranırmış yaz yağmuru

Gölgesine sığınacak dal olmayınca

Üç saatlik maraton bitmek üzere

Kaçıncı saati koşuldu yolun 

Kaçıncı dakikada düşenler oldu

Kopanlar yarıştan

Sıkışıp kaldı gözlerim

Okulun kapılarına

Acı duymuyorum ama

Güneşin sarı sıcağı

Yanaklarımda alevlenen

Esen yelden duyuyorum

                   O türküyü hala

Ruhi Su söylüyor

Vatanı olmayanların

Dizelerdeki yurtsuz sürgünlüğü

                            Dudaklarıma asılı kalan

                                 Saat 12:35

Aralandı kapılar

Gözüktü 

Yarına koşmaktan yorgun

                Deniz gözlüm

Kamaşan gözlerini yumrukluyor

Dizlerinde yurtsuzluk ağrıları

Önce uzak dağların 

               Havasını çekti içine

Sonra 

Koşarak geldi yanıma

Sarıldım

Yüreğimdeki nehirlerin ıssızlığına

Alnındaki kader çizgilerini 

Bastım göksüm,ün üstüne

Bütün özlemlerin sarhoşluğuyla

Başladık yürümeye

Halkımızın ortak türküsünü

                           Paylaşarak......

   Söz ibrahim karaca.müzik Grup yorum

Bu kente ayrılık düştüğü zaman

Uykusunda bir kuş ölür ecelsiz

Alıp,ta başını gitmek istersin

Karanlık sokaklar kör sağır dilsiz

                                               Kızımı üniversite

                                               Sınavında beklerken

                                                                               16 Haziran', 'Kitaplar.la dost olanlar     Yaşama dost kalırlar.                                                                                          ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/unuversite-sinavinda-kizima-yarina-kosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tsunami (26.12.2004)', 'tsunami-26-12-2004-seyfet-bozcali-9c61v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tsunami afeti yaktı yuttu yok etti,

Bir çok ahlaksızlığın izlerini yok etti,

Kendini eğlenceye şatafata atanlar,

Bir gün de dalgalarla, depremlerle giderler...

Nerde kaldı dünyanın en güzel sahilleri,

Şimdi mezarlık oldu o turistlik yerleri,

Seni yoktan var eden yaratanı anmassın? 

Kanaatkar olmassan hiç bir şeye doymassın...

İlahi kuvvet ile her şey yerli yerinde,

Sevmeli mevlasını dualar dudağında,

Kaderinde ne varsa o olur etme merak,

Topraktan yaratıldık sonumuz kara toprak...

(27.12.2004)', 'Tsunami afeti yaktı yuttu yok etti, Bir çok ahlaksızlığın izlerini yok etti, Kendini eğlenceye şatafata atanlar, Bir gün de dalgalarla, depr...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tsunami-26-12-2004-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordu', 'zordu-multe-ci-han-dkt3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle başladım fırtınalarda yüzmeye

Kesilmesi nefesimin

Vücuduma krampların girmesi

O zaman başladı

Ayda yeni büyüyen çiçeği

Dünyadan görmek gibiydi

ZORDU

Yağmurlarda ıslanmış ruhum 

Uçar kaçarken bedenimden

Hayal etmeyi düşünmek kadar zor

Aslında ben seni değil

Seni sevmeyi istiyordum

Bir ışık gibi hızlı olmak hayatımda

Kaçmak uzaklara

Dudağımdan çıkan ses

O ince, tiz ve nefret dolu olan

Kıskandığım kulağından

Gizlemeye çalıştığım

Kapalı kapılar ardından izleken seni 

Seni hayal edip günlerimi geçirmek gibi

Hep uzağında olmak istiyordum

Senden uzakta kalbinin sahibi

Hep uzağında olmak istiyordum

Aşkının tek neferi', 'Seninle başladım fırtınalarda yüzmeye Kesilmesi nefesimin Vücuduma krampların girmesi O zaman başladı Ayda yeni büyüyen çiçeği Dünyadan görm...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zordu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyde Sevgi', 'her-seyde-sevgi-seyfet-bozcali-w6ry6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakka ve hakikate itaatta var sevgi,

Sabır, şükür, tevekkül, bağlılıkta var sevgi.

Vakar, haya, tevazu, adalette var sevgi,

Severnlerle büyüyen sevgi selidir sevgi...

İnanan, inanmayan insana yoldur sevgi,

Haksızlığa engeldir, mazluma koldur sevgi.

Toplandıkça büyüyen koca bir seldir sevgi,

Ufukta ışın gibi aydın bir yoldur sevgi...

Seyfet der gönüllere, açılan yoldur sevgi,

Dokundukça kokuyan, bir demet güldür sevgi.

İnsanları bağlayan kopmaz bir bağdır sevgi,

Demokrası, özgürlük, birlik yoludur sevgi...', 'Hakka ve hakikate itaatta var sevgi, Sabır, şükür, tevekkül, bağlılıkta var sevgi. Vakar, haya, tevazu, adalette var sevgi, Severnlerle büyü...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-seyde-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Aşkın Mayın Tarlası **', 'askin-mayin-tarlasi-seyhmus-sevilmez-r3uro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın mayın tarlasına

Kaderce sevmeye hazır yürekler gömülmüş..

Basılmaya amade 

Patlamaya hazır aşklar, 

Kime niyet, kime kısmet dercesine

Sahibini bekler.

Korkarak adımlarını atma sakın,

Kendi mayınını bulmayana dek 

Basmazmış insan..

Doğum çizgisinden ölüm çizgisine koşarken

Kirli çamura da batma..

Sevgi barutunu yitirmiş 

Puflayan küflü mayınlar da var 

Aman dikkat! 

Neme lazım kaybetmeyesin yüreğini..

Denk gelirse gerçek aşkın, bahtına

Etraf tozpembe duman olur, oturursun tahtına

Ya denk gelmese

İşte o zaman,

İşte o zaman yeraltından dikili isimsiz mezar taşları yeşerir.

Sıralı boş mezarlara bakarsın,

Hangi taşa ismim yazılacak diye

Ölmeden ağıtlar yakarsın.

Aşkın gerçek iki yüzüdür acı ve sevinç.

Kader, şansına fırlatır aşkı, yazı tura niyetine..

Alın yazısının son noktasını koymak için

Saplamışsa kalemi alnına,

Artık iş işten geçmiştir.

Ya aşkı yaşıyorsundur.

Ya da aşkla ölüyorsundur.

06.01.2006/Batman', 'Aşkın mayın tarlasına Kaderce sevmeye hazır yürekler gömülmüş.. Basılmaya amade  Patlamaya hazır aşklar,  Kime niyet, kime kısmet dercesine ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/askin-mayin-tarlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım aynura', 'kizim-aynura-abdullah-oral-888xn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KIZIM AYNUR’A

Seninle karşılaştığım

O ilk günü hatırlıyorum da

Hüzünlü sevinç taşıyordun

Tarifi imkansız acılarıma

Sen otuz günlük bebek 

Ben sevda sularında vurulmuş

              Yaralı bir martı

Önce öpüp kokladım

Gözlerinde umudu

Sonra kırık kanadıma 

merhem diye sardım seni

Toprağa düşen bir umudun

Zemheride  çiçeğe durmasıydın

Yani örgütlenmesi baharın 

                       Kardelenim

Seninle ağırdı yüzü dağların

Bahar düştü kapımıza

Yanaklarından kokladım kır çiçeklerini

Büyümeyi öğrendim seninle

Duyar gibiyim hala

O minicik ellerinin sıcaklığını

Hani tutarda ellerimden 

Emeklemeden yürümeyi öğretirdin bana

Zaman yok

Geç kalmayalım diye yarına

Ben bir türlü Öğrenemedim yürümeyi

Sen yürüdük çe büyüdün

Saklı sevdalar büyüttün

O minicik yüreğinde

Şimdi tepeden tırnağa

Çiçeğe durmuş bahar gibisin

Beyaz gelinlik içinde

Gayrı zamanımız yok 

Geri dönüp bakmaya

Ayaklanmış içindeki hapis duygular

Haydi mutluluk seni bekliyor

Koş yüreğinin götürdüğü yere

Hatırlıyorum da

Nasıl unuta bilirim

Hala ellerimde saklı

Sıcaklığı bebekliğinin…

                                                    

                                         

                                                    18 MAYIS 2003

                                               Kızım Aynur un Evlendiği gün', 'KIZIM AYNUR’A Seninle karşılaştığım O ilk günü hatırlıyorum da Hüzünlü sevinç taşıyordun Tarifi imkansız acılarıma Sen otuz günlük bebek  Be...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kizim-aynura-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümü Kör Eden Sensin', 'gozumu-kor-eden-sensin-yusuf-ter-r0051', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gözlerimi  kör eden sensin

Dünyaya bakamıyorum göresin

Gözlerim arıyor gülüm nerdesin 

Gel götür beni de elimden canım

Beklerim seni uçan kuşlar gibisin

Dizlerime derman tenime bedensin

Geceme ay gündüzleri güneşimsin

Kanadım olacaktın canımdın sen

Senden başkası yok içimde bilesin

Gözüm olacaktın sözünü veresin

Beni üzüp küsüp terk etmedesin

Yedi bitirdi bu der beni neylersin 

Yusuf Ter 04.01.06

Saat 23:15 İsviçre', 'Bu gözlerimi  kör eden sensin Dünyaya bakamıyorum göresin Gözlerim arıyor gülüm nerdesin  Gel götür beni de elimden canım Beklerim seni uçan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozumu-kor-eden-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Vatan''ın', 'bizim-vatan-in-seyfet-bozcali-as1mc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç taraftan kucaklamıştır deniz,

Muhteşem bir ülke gelip görseniz.

Göreni büyüler gezip bilseniz,

Dünyada eşi yok bizim vatanın...

Nüfus bakımından büyük marmara,

Sanayisi olmuş dertlere çare,

İşçici, memuru bağrında çıra,

Dünyada eşi yok bizim vatanın...

Efeler diyarı ege bam başka,

Sevgisiz kalanı getirir aşka,

Sahilleri limanları revanşta,

Dünyada eşi yok bizim vatanın...

Turistler meskeni, şirin akdeniz,

Göreni büyüler tabiat, deniz,

Cennet gibi gönüllere verir haz,

Cihanda eşi yok bizim vatanın...

Karadeniz dağlık ormanı sıktır,

Her taraf yem yeşil yayla çaylıktır,

Önemli besini hamsi, balıktır,

Dünyada eşi yok bizim vatanın...

Tahıl ambarımız iç anadolu,

Bütün bölgelere uzatmış kolu,

Bağrında kocaman tarlalar dolu,

Dünyada eşi yok bizim vatanın...

Doğuanadolu yüksekte sisi,

Heykel gibi dim dik dağı vadisi,

Yaylalarda bekler bizi ve sizi,

Cihanda eşi yok bizim vatanın...

Birde gelin bizim güneydoğuya,

Dev barajlarıyla kanacak suya,

Seyfet der muhtacız sevgi, saygıya,

Dünyada eşi yok bizim vatanın...

''Vatan sevgisi imandandır'' 

Hadis-i Şerif', 'Üç taraftan kucaklamıştır deniz, Muhteşem bir ülke gelip görseniz. Göreni büyüler gezip bilseniz, Dünyada eşi yok bizim vatanın... Nüfus bak...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bizim-vatan-in-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-multe-ci-han-3mua6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcak bir gülümsemeye hasret bu kalp

Sıcak bir buseye

Karanlık bir patikada bekliyorum seni

Ellerim ellerine hasret

Ne zaman bir araba görsem uzaklarda

Umutlanıyorum...

Son bulmamış hikayemsin benim

Son sayfası olmayan romanım

Bırakıp da kaçamadığım prensesimsin masallarımda

Herkesten gizlediğim  ikinci hayatım

Bir an pes ediyorum

Bir neşter elimde

Duygularıma uzanan ellerin gibi

Koparıp atmak geliyor içimden

Koparıp atmak geliyor seni

Ne kadar zordur bilemezsin

Sonu olmayan bir film çekiyorum sensizliğimde

Ne kadar zordur bilemezsin

Bile bile uçuruma gidiyorum sensizliğimde

GİDİYORUM

Dudağımda senden kalma sözler

Gözlerimde siluetin

Yine o eski gülücükler aklımda

O güzel gözlerin hala gözlerimin ucunda

Gidiyorum

Hiçbir zaman unutamayacağım anılarımla', 'Sıcak bir gülümsemeye hasret bu kalp Sıcak bir buseye Karanlık bir patikada bekliyorum seni Ellerim ellerine hasret Ne zaman bir araba görse...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gidiyorum-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç mi özlemedin edna kulunu', 'hic-mi-ozlemedin-edna-kulunu-i-smail-pekinoglu-46he0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç mi özlemedin edna kulunu

dağları delip de geldin bir zaman

Karlar mı kapattı sıla yolunu

bahar seli gibi aktın bir zaman

saçına bağlardın gülü sümbülü

al yeşil fistana sarı püskülü

kara göz üstüne sırma kakülü

döktün viran ettin gezdin bir zaman

garip kaldın şimdi gurbet ellerde

al mendilimi yar sakla sinende

böyle ayrılığı yazmaz kalemde

tez gelirim deyi gittin bir zaman', 'Hiç mi özlemedin edna kulunu dağları delip de geldin bir zaman Karlar mı kapattı sıla yolunu bahar seli gibi aktın bir zaman saçına bağlardı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-mi-ozlemedin-edna-kulunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-abdullah-oral-lr28q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'OĞUL 

 Ne getirir gelen günler bilinmez 

Dağa yakma çoban ateşi oğul 

Senden geçinene inan dost denmez 

Dost bilip te yeme taşını oğul

Gün gelir olur ya olacak elbet 

Kefenim olacak beyaz bir tülbent 

Sanma duyar gayrı sesimi bu kent 

Düşürme gözünden yaşını oğul 

 Sakın durma boşa umut selinde 

  İnan kurtuluşun senin elinde 

Herkes düşman olur kötü gününde

 Bilmelisin kendi işini oğul

Kimseler kırmadan gülünü dermez 

Zor gününde kötü dost kol kanat germez 

Sana senden başka kinse elvermez 

Eğme hal bilmeze başını oğul

  Onurunu yazdır kimlik kartına

Riyakar dostunu alma sırtına 

Korkma savuramaz seni fırtına 

Açık tut rüzgara döşünü oğul 

 Vurguni‘yim korku gelmesin dile 

Özü bozulursa kurt düşer güle 

Sakın aç itlerle girme bir yola 

Bırakmazlar senin leşini oğul 

     oğlum sinan''a', 'OĞUL   Ne getirir gelen günler bilinmez  Dağa yakma çoban ateşi oğul  Senden geçinene inan dost denmez  Dost bilip te yeme taşını oğul Gün g...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ogul-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilimde vird oldu sözümde hece', 'dilimde-vird-oldu-sozumde-hece-i-smail-pekinoglu-x8y93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilimde vird oldu sözümde hece

çağırırım hemi gündüz hem gece

bülbüller çığrışır gülün dilince

Ondan özge demem dahi yar diye

her seher buluşur canlar semada

yare can ''çin öter bülbülü şeyda

bulunmaz arama yadlarda fayda

ondan özge demem dahi var diye

Hazel''i seherde düşmüşüm yola

gözlerime kanlı yaşlar hep dola

pazarda özümü satsam ki nola

onda özge demem dahi kâr diye', 'Dilimde vird oldu sözümde hece çağırırım hemi gündüz hem gece bülbüller çığrışır gülün dilince Ondan özge demem dahi yar diye her seher bulu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilimde-vird-oldu-sozumde-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Gül Dikmektir', 'sevmek-gul-dikmektir-erhan-tigli-315d8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek gül dikmektir

sevdiğinin bahçesine

kendi bahçesine dikercesine özene bezene

atmaktır kini nefreti çöpe

gülün dikeninden yakınmamaktır

Ve yaşamaktır sevdiğinin adresinde 

kendi evindeymişçesine sere serpe

Oturduğu yeri gülle donatmaktır.', 'Sevmek gül dikmektir sevdiğinin bahçesine kendi bahçesine dikercesine özene bezene atmaktır kini nefreti çöpe gülün dikeninden yakınmamaktır...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-gul-dikmektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlendin sende (sibel)', 'evlendin-sende-sibel-hasan-cangir-gafjb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her akşam gün batınca 

Hayallerimi ertelerim yarına 

Beklemek acı vermez ruhuma 

Yanarım gelmeyecek korkusuyla 

Ne haldeydim, ne haldeyim 

Sensizim viraneyim 

Uzağıma gittin ama 

Ben hayalinle evliyim 

Geçtiğin yollara adını yazdım 

Görmedim deme sakın 

Sen bana uzaksın ama 

Ben sana senden de yakın 

Ağlama yüreğim dönecek elbet 

Bu böyle sürüp gitmeyecek 

Sen haykır aşkını seviyorum de 

Herkesi kıskandır', 'Her akşam gün batınca  Hayallerimi ertelerim yarına  Beklemek acı vermez ruhuma  Yanarım gelmeyecek korkusuyla  Ne haldeydim, ne haldeyim  S...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlendin-sende-sibel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Söylediler Yalan Dediler', 'yalan-soylediler-yalan-dediler-yusuf-onder-bahceci-cgb9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakıp bakıp ağlıyorum resmine,

Hasret kaldım gülüşüne, sesine,

Neden inandın sen eller sözüne,

Sana yalan söylediler, yalan dediler.

Aşkınla dağları dolandım durdum,

Dağlarda ceylandın sana vuruldum,

Evvel deli idim şimdi duruldum,

Sana yalan söylediler, yalan dediler.

Gizli gizli ağlıyorum sevdiğim,

Hep içime atıyorum sevdiğim,

Elden birşey gelmiyorki sevdiğim,

Sana yalan söylediler, yalan dediler.

Seni sevdim sana dua, dileklerim,

Bir ömür boyuda olsa yine beklerim,

Bu sene olmazsa yine de Allah Kerim,

Sana yalan söylediler, yalan dediler....', 'Bakıp bakıp ağlıyorum resmine, Hasret kaldım gülüşüne, sesine, Neden inandın sen eller sözüne, Sana yalan söylediler, yalan dediler. Aşkınla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-soylediler-yalan-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen artık evlisin(sibel)', 'sen-artik-evlisin-sibel-hasan-cangir-e7k98', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haberini verdiler bana evleniyor diye 

İnan senden çok mutlu oldum bilemezsin 

Kurtuldun işte benden benim sevgimden 

Bundan sonra artık beni sevmezsin 

Git güle güle yolun açık olsun 

Dilerim en kötü gününde mutlu olursun 

Bende bulamadıklarını onda bulursun 

Bundan sonra artık beni tanımazsın 

Yanından geçersem tanımamazlıktan gel 

Sesimi duyarsan duymamazlıktan gel 

Tenimi hissdersen bilmemezlikten gel 

Bundan sonra artık beni tanmazsın 

Sen artık evlisin benimse boynum bükük 

Benle geçen günlerini bir bir unuttum 

Senden bana bir resmin birde hayalin kaldı 

Onlarıda seninle birlikte maziye savurdum', 'Haberini verdiler bana evleniyor diye  İnan senden çok mutlu oldum bilemezsin  Kurtuldun işte benden benim sevgimden  Bundan sonra artık ben...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-artik-evlisin-sibel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrik Yaşam', 'esrik-yasam-erhan-tigli-00i9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni esrik görüp de

sanmayın ki

gece gündüz içiyorum

gökyüzünün mavisiyle

yeryüzünün yeşilinden

özlemime kumaş biçiyorum

kuşlarla kelebeklerle arılarla

güzelliklere çiçek çiçek uçuyorum

sevdamın coşkulu ırmağıyla

mutluluğa doludizgin

akıyor akıyor akıyorum

umudumun yelkenine sımsıkı sarılıyorum.', 'Beni esrik görüp de sanmayın ki gece gündüz içiyorum gökyüzünün mavisiyle yeryüzünün yeşilinden özlemime kumaş biçiyorum kuşlarla kelebekler...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/esrik-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sibel ama evlisin(sibele)', 'sibel-ama-evlisin-sibele-hasan-cangir-723bv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'evime girdin çıktın 

tam üç yıl beraber olduk 

herşeyi tamamen paylamıştık 

hiç yalanını yakalamadım 

hiç üzdüğünü de görmedim 

tam evlenmek istedim 

nedense zamana ihtiyacım var dedin 

beklerim demiştim 

o günden sonra bir daha seni göremedim 

duydumki evliymişsin 

nasıl da kahroldum 

nasıl da maffoldum 

nasıl da aşık olmuşum 

nasıl da sana konduramadım 

ama evliymişsin 

benden sana olsun bu şarkı 

ne güzel de söylemiş 

yılzdız tilbe ablamız 

ama evlisin 

benim değilsin 

yıllar önce nerdeysin 

çok geciktin sevgilim', 'evime girdin çıktın  tam üç yıl beraber olduk  herşeyi tamamen paylamıştık  hiç yalanını yakalamadım  hiç üzdüğünü de görmedim  tam evlenmek...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sibel-ama-evlisin-sibele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mim Dersi', 'mim-dersi-numan-eksioglu-yiovt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuklara mimi anlatıyorum

İşte bulunmaz fırsat

Müdür bey yaklaşıyor 

Müdür beye şüphelice bir bakış

Tedirgin hareketler

Ürkütmeye eli kolu sallayış

Yerlerde taş arayış

Ağaca doğru hamle

Gözler hep müdür beyde

Aceleyle tırmanış 

Müdür bey yukarıya

Şaşkın şaşkın bakarken

İzleyen çocuklardan

Dakikalarca alkış', 'Çocuklara mimi anlatıyorum İşte bulunmaz fırsat Müdür bey yaklaşıyor  Müdür beye şüphelice bir bakış Tedirgin hareketler Ürkütmeye eli kolu ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mim-dersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyin', 'beyin-numan-eksioglu-h396a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyin var 

Beyindir 

Beyin var 

Bireyindir', 'Beyin var  Beyindir  Beyin var  Bireyindir...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beyin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-numan-eksioglu-yzdik', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbim ayna

Bakıp görme suretini istersen

Olabilir mi

Değil

Tarak tarak örmelersen fikrini

Çiçek suret senindir 

Kalbim çocuk

Sıkıverme yanağını istersen

Sıkamaz mısın

Çevril

Coşkunluğun insanlığın sevdiğim

Çocukluğa özendiğin süredir', 'Kalbim ayna Bakıp görme suretini istersen Olabilir mi Değil Tarak tarak örmelersen fikrini Çiçek suret senindir  Kalbim çocuk Sıkıverme yana...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbim-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmıydı Yalanmıydı', 'yalanmiydi-yalanmiydi-yusuf-onder-bahceci-01aji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seven kalbim seni özler,

Seni özler, yolu gözler,

Hani o verilen sözler,

Yalanmıydı yalanmıydı.

Ben sözümde duruyorum,

Seni sevdim seviyorum,

Sen nasılsın bilmiyorum,

Yalanmıydı yalanmıydı.

Uğraşma hiç boşuna,

Yalan sözle kandırdılar,

Seni benden ayıranlar,

Yalanmıydı yalanmıydı.

Güldüğüme bakma sen,

İçim kan ağlar bilsen,

Benim sevdiğim derken,

Yalanmıydı yalanmıydı.....', 'Seven kalbim seni özler, Seni özler, yolu gözler, Hani o verilen sözler, Yalanmıydı yalanmıydı. Ben sözümde duruyorum, Seni sevdim seviyorum...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanmiydi-yalanmiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-numan-eksioglu-xdbou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaramaz haylaz bulut

Resim oluşuyordu

Beni de yasaklasın

Gülünçleşsinler diye

Tasarladığı plan

Az daha tutuyordu', 'Yaramaz haylaz bulut Resim oluşuyordu Beni de yasaklasın Gülünçleşsinler diye Tasarladığı plan Az daha tutuyordu...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasak-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Tükenmez Dilek', 'yurek-tukenmez-dilek-numan-eksioglu-ui6n3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevinçleri genleştirmek istiyor

Üzüncü büzüştürmek

Bölüştürmek sevgiyi

Ve herkese birer pay

Çiçek düşsün istiyor

Yürek tükenmez dilek

Kahkahayı yerleştirmek istiyor

Kederi savuşturmak

Çoğaltırmak umudu

Ve herkese birer pay

Gerçek düşsün istiyor

Yürek tükenmez dilek', 'Sevinçleri genleştirmek istiyor Üzüncü büzüştürmek Bölüştürmek sevgiyi Ve herkese birer pay Çiçek düşsün istiyor Yürek tükenmez dilek Kahkah...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yurek-tukenmez-dilek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürekli Soru', 'surekli-soru-numan-eksioglu-z3a34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimden fışkırırsın görmezsin

Ben yürek örgücüsü çırpınışım bu yönde

Sen durup hislerine kördüğümler işlersin

Benini herkeslemek bu yalnız istediğim

Sen inatla benini herkes diye süslersin

Rüzgarı ters üfleyip rüzgarı durdururum

Güneşin önündeki bulutları deflerim

Kayıkların kurtulup dökülünce küflerin

Teşekkürü ters yönlere seslersin

Ben seni çok önceden benimsedim

Bu şiir de bu nedenle yazıldı

Sürekli soracağım

Karanfil sever misin', 'Gözlerimden fışkırırsın görmezsin Ben yürek örgücüsü çırpınışım bu yönde Sen durup hislerine kördüğümler işlersin Benini herkeslemek bu yaln...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/surekli-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşme', 'cesme-suleyman-yavas-d87a6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıkmadan usanmadan

Şırıl şırıl akan çeşme

Sesine hiç kızmam kızamam

Sen ki kaç kere kandırdın beni

Hemde hiç yüze vurmadan', 'Bıkmadan usanmadan Şırıl şırıl akan çeşme Sesine hiç kızmam kızamam Sen ki kaç kere kandırdın beni Hemde hiç yüze vurmadan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cesme-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekçe', 'cicekce-numan-eksioglu-x9298', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Der ki çiçek

Ben de ne

Ben seni açmalıyım', 'Der ki çiçek Ben de ne Ben seni açmalıyım...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/cicekce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücüme gidiyor', 'gucume-gidiyor-tevfik-karinca-z1nq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En derin inzivalarını yaşıyorum

Hani o, ağzından düşürmediğin yalnızlığın

Ve içinden çıkamadığım nice yanılgıların

Yıllardır gizlice, gözden uzak, ve kulak kirişte

Besledik sevda adına birbirimizi

Yazık büyütememişiz

Yenildik, sahipsiziz şimdi

Bahaneler mazeretler gırla

Dürüstçe diyebilsek 

Söylenmesi gerekenleri

Kahpece kandırıyoruz

Kendimizi

Gücüme gidiyor ister istemez

Vasiyetimsin sanki

Sabıka gibi peşimde yaşam

Vazgeç

Sürüklenme gelme ardımdan

Sen gülleri seversin

Dikenleri batırma eline

Kardeşinmişim gibi sevişme benimle

Vazgeçtim

Pişmanım 

Sevmedim de

Sensiz olmaz diyorsun

Filmi başa sarıyorsun ya

Gücüme gidiyor ister istemez

Fazla mı abarttık dersin sevdamızı

Yalnızlığa susmuşken

Aykırıklıklara durmuşken

Bırakmak mı zor gelen

Yaşamayı düşünüyoruz ya

Can çekişirken

Gücüme gidiyor ister istemez

Ödünç aldığımız emaneti

Hayra yorduğumuz kehaneti

Gösteremediğimiz cesareti

Korkakça, korkarak

Seni seviyorum diyorum ya

Gücüme gidiyor ister istemez', 'En derin inzivalarını yaşıyorum Hani o, ağzından düşürmediğin yalnızlığın Ve içinden çıkamadığım nice yanılgıların Yıllardır gizlice, gözden...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gucume-gidiyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-seyfet-bozcali-9i6ug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan odur hep doğruyu görmeli,

Doğru düşünerek karar vermeli,

Adım adım doğru yola varmalı,

Sen nerdesin ben nerdeyim arkadaş...

Yapılan şeyleri hor görme sakın,

İbadet edersem bu benim hakkım,

Kötü siz söyleten, içtiğin zıkkım,

Sen yoluna ben yoluma arkadaş....

Namazı kılana yobaz diyorsun,

Geçmişi anana bağnaz diyorsun,

Vatan, Bayrak nedir? Bilmem diyorsun,

Bilgisizsen ben nedeyim arkadaş...

Maddiyatı sevip, ona taparsın,

Para için çok yuvalar yıkarsın,

Gerçeyi anlatsam, karşı çıkarsın,

Sen yoluna ben yoluma arkadaş,

Kazancını düşüncesiz harcarsın,

Teselliyi şişelerde bulursun,

Haram desem, gericisin diyorsun,

Mantıksızsan ben nedeyim arkadaş...

Seyfet der bu yolun yolcularıyız,

Bu güzel vatanın bekçileriyiz,

Bu yurt için çalışırsak hepimiz,

Amacımız aynı olur ARKADAŞ...', 'İnsan odur hep doğruyu görmeli, Doğru düşünerek karar vermeli, Adım adım doğru yola varmalı, Sen nerdesin ben nerdeyim arkadaş... Yapılan şe...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arkadas-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-suleyman-yavas-zogtz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen 

Kokulu bir baharın 

Aşık olunan kızı

Bir annenin yavrusuna

Şevkatli bakışı

Sen

Küçük bir çocuğun elinde

Yeni oyuncak

Üşümüş bir kedinin

Yanında yanan ocak

Sen 

Kupkuru ayazdan

Açan gün

Aşığın 

Aşkına yaptığı düğün

Sen

Yaşamın

En güzel anı

Yoktan varın

Varlığı', 'Sen  Kokulu bir baharın  Aşık olunan kızı Bir annenin yavrusuna Şevkatli bakışı Sen Küçük bir çocuğun elinde Yeni oyuncak Üşümüş bir kedinin...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-727-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heykelin Güler Şimdi', 'heykelin-guler-simdi-numan-eksioglu-zb5mj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buğdayı yorgunsam da bedenime serpip dur

Hemen köklendiririm

Öpülesi düşleri tasarla tasarla kur

Ben gerçeklendiririm

Mumu söndür romantizm sırası değil şimdi

Yaralı karıncanın ayağına ilaç sür

Sevgiye bir kaşık bal

Kuşlardan bak örnek al

Ben kanatlandırırım

Kitapların tozluluk nedenini bul şimdi 

Yeteneğin hangi yönde bildin mi

Bilmedinse biliver

Başka bir iş yapıyor isen eğer

Hobi olarak başla yeteğin yolunda

Ben yüreklendiririm

Sen başlayıver şimdi

Göreceksin bulacaktır gülmeyi

Aşkın yeteğinde

Ekmeğin de aşın da

Bir adım kadar durup kulaklasan sözümü

Gülücüklendiririm

Heykelin güler şimdi', 'Buğdayı yorgunsam da bedenime serpip dur Hemen köklendiririm Öpülesi düşleri tasarla tasarla kur Ben gerçeklendiririm Mumu söndür romantizm ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/heykelin-guler-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yön', 'yeni-yon-sadettin-deren-e4gep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adımımı atıyorum ya

Yürüyorum ya ellerim cebimde

Bütün yollar sana doğru', 'Adımımı atıyorum ya Yürüyorum ya ellerim cebimde Bütün yollar sana doğru...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yeni-yon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Düştünmü Aşka', 'sen-hic-dustunmu-aska-i-lknur-er-j91q2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hiç düştünmü aşka

Damarlarından kanın çekildimi

Bir bakışına durdumu kalbinin tiktakları

Kendinden geçtiğin oldumu

Benden önce sen dedin mi hiç

___________________ Öldünmü Onsuz

Sen hiç düştünmü aşka

Kanatlandımı yüreğindeki kuş

Çarptımı sevgilinin kalbine

Tuttunmu hiç ellerini

Tutuldumu ellerin sımsıkı

___________________ Hayat bu dedinmi

Sen hiç düştünmü aşka

Ona giderken

Koştumu yüreğin senden önce

Yollar uzadıkça uzadımı

Onun yanında aktımı zaman

___________________ Zaman dursa dedinmi

Sen hiç düştünmü aşka

Ben düştüm

___________________ Bir daha çıkamadım…', 'Sen hiç düştünmü aşka Damarlarından kanın çekildimi Bir bakışına durdumu kalbinin tiktakları Kendinden geçtiğin oldumu Benden önce sen dedin...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-hic-dustunmu-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut', 'tut-suleyman-yavas-jz1j4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Put

Gözü perdelilerin İlahı put

Dut

İpek böceğinin sırdaşı dut

Yut

Az da olsa helalinden yut

Tut

Bir gün öleceğini aklında tut', 'Put Gözü perdelilerin İlahı put Dut İpek böceğinin sırdaşı dut Yut Az da olsa helalinden yut Tut Bir gün öleceğini aklında tut...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tut-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü', 'turku-numan-eksioglu-hg2g5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhi Su''ya

O türküye başladı

Çiçeklerde bir telaş

Birden esen rüzgarla

Sapları eğilerek

Yere değdiklerinde

Epeyce yatıştılar', 'Ruhi Su''ya O türküye başladı Çiçeklerde bir telaş Birden esen rüzgarla Sapları eğilerek Yere değdiklerinde Epeyce yatıştılar...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/turku-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten', 'zaten-sadettin-deren-tr5uz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarhoş olmak geçiyor içimden,

Sarhoşken zaten gülüşünde.

Yürümek sana akan sularda hep,

Yürürken zaten sen ciğerimde.

Ellerine ihtiyacım var ölümüne,

Ellerin zaten hep cebimde.

Gözlerinde uyanmayı düşlüyorum,

Gözlerin zaten hep gözlerimde.

Seni bir bardak suda yudumlamak,

Sen zaten köpük-köpük yüzerken bende.

Yüreğini öpesim geliyor kaç kereler,

Yüreğin zaten atarken yüreğimde.

Yağmurlarda sırılsıklam olmak niye,

Yağmur zaten kudurmuş içerimde.

Gel artık güzelim gel,

Gel zaten duruyorsun can-evimde.', 'Sarhoş olmak geçiyor içimden, Sarhoşken zaten gülüşünde. Yürümek sana akan sularda hep, Yürürken zaten sen ciğerimde. Ellerine ihtiyacım var...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaten-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilkar', 'bilkar-mehmet-akif-gulhan-hluj2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Has oğlum geldi

Uğramadan geçmez derdin ya bana

Yine geldim

Bilecik,Künçeğiz arası 

Bir cenaze konvoyu

İstanbul’un güleç kızı

Saf''a durduk namazını kıldık

Yiğit Abazalar köyünde

Seni toprağa verdik

Gülümse bize oralardan

Yine ne olur

Mehmet Akif Gülhan  06.01.2006

Ablacığım cennet mekanın olsun', 'Has oğlum geldi Uğramadan geçmez derdin ya bana Yine geldim Bilecik,Künçeğiz arası  Bir cenaze konvoyu İstanbul’un güleç kızı Saf''a durduk n...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Sonunda Yâr Gitti', 'en-sonunda-y-r-gitti-yusuf-onder-bahceci-w20c3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün akrabalarım bir oldu,

Olan hep bana oldu,

Her biri birşey dedi,

En sonunda yâr gitti.

Biri seni sevmiyor dedi,

Biri sana gelmiyor dedi,

Türlü türlü yalan söyledi,

En sonunda yâr gitti.

Belki tehdit ettiler,

Belki çek git dediler,

Bilmemki ne dediler,

En sonunda yâr gitti.

Sen inandın onlara,

İnandın o yalanlara,

Çaresizdim planlara,

En sonunda yâr gitti....', 'Bütün akrabalarım bir oldu, Olan hep bana oldu, Her biri birşey dedi, En sonunda yâr gitti. Biri seni sevmiyor dedi, Biri sana gelmiyor dedi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/en-sonunda-yar-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyı O Dondurur', 'aciyi-o-dondurur-numan-eksioglu-309tz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anıl Tosun''a

Kirpiklerin uzanıp saçlarını tarasın

Yumuşak saçlarından 

Yorgan olsun üstüne döşek olsun altına

Onunla gülüşük dur

İçindeki şarkılar onu umutlandırsın

Gıdısına sevgi sür

Yüreğinin onsuz bölgelerinin

Kulağını çekip dur

Ne yapsan hak etmiştir

Hak etmiştir doğrudur

Diyarların göz yaşı tek böyle gıdıklanır

Sarıl ona güzelim

Sarıl acıyı dondur', 'Anıl Tosun''a Kirpiklerin uzanıp saçlarını tarasın Yumuşak saçlarından  Yorgan olsun üstüne döşek olsun altına Onunla gülüşük dur İçindeki şa...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aciyi-o-dondurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkış', 'alkis-numan-eksioglu-h52zi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nazım Hikmet Ran''a

Yüzünü bana dön ve 

Sıkıca sarıl bana

Şöyle kalbin kalbimin

Tam üzerine gelsin

Her atışta çarpsınlar birbirine

O böyle alkışlanır', 'Nazım Hikmet Ran''a Yüzünü bana dön ve  Sıkıca sarıl bana Şöyle kalbin kalbimin Tam üzerine gelsin Her atışta çarpsınlar birbirine O böyle al...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/alkis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek', 'emek-numan-eksioglu-vx4ym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ensar Yazıcı''ya

Karanlığı kürekledi içinden 

Gölge bile bırakmadı bir parça

Aşk düşleyeni bulur

Höykürüş parça parça

Onca acıyla tutup 

Irağı size çekti

Bir kerecik bunalıp 

Bir ağaçtan bir yapracık koparsa

İş gününe güleçtir hep varlığı

O ve aşk bir tek parça', 'Ensar Yazıcı''ya Karanlığı kürekledi içinden  Gölge bile bırakmadı bir parça Aşk düşleyeni bulur Höykürüş parça parça Onca acıyla tutup  Irağ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/emek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taklit', 'taklit-numan-eksioglu-2x1ig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünce Suçlusuna

Çiçeklerin arasında dikilip

Çiçek taklidi yapsan

Çok zor yakalanırdın', 'Düşünce Suçlusuna Çiçeklerin arasında dikilip Çiçek taklidi yapsan Çok zor yakalanırdın...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/taklit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 18', 'd-siir-ve-sarki-sozleri-18-huseyin-avdic-h5wrb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derman Ol Derdime

Derman olmak dertlere,

İnan mutluluk verir.

Gel, derman ol sen de,

Derdime, aşk derdime.

*   *   *

Bir kez bulmuşken seni,

Sakın ha gelmem deme.

Çok arattın kendini,

Şimdi beni reddetme.

*   *   *

Yıllarca çok aradım,

Senin gibi birini.

Şimdi bulmuşken seni,

N''olur, reddetme beni! 

Not: Henüz tam bestelenmedi.

Berlin, Mart 2005.', 'Derman Ol Derdime Derman olmak dertlere, İnan mutluluk verir. Gel, derman ol sen de, Derdime, aşk derdime. *   *   * Bir kez bulmuşken seni,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Türbe', 'sessiz-turbe-mehmet-akif-gulhan-5m1u0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin kabrin 

Kalbimde sessiz türbe             

Sana geldim rahmetli

Seni görmeye

Yakışmadı sana 

Yeşil saltanat arabası

Yakışmadı belediyenin

Ucuz sandukası

Seni gönderirken 

Ebediyete; ağlayamadık

Attık üstüne toprağı

Bunu vazife sandık

Yokluğun kor gibi

Şimdi geldi akıl başa

Şimdi yüz sürüyoruz

Yattığın soğuk taşa

O şimdi; bir rahmetli 

Kabrinde yatan

O muydu giderken

Fırtınalar kopan

O; yalan dünyaya

Sessiz,sakin geldi

Taşa yazılı ismin 

Bize pek garip geldi.

O naçiz vücudun 

Toprak olmuş

O mübarek kabrin

Çiçekleri solmuş

O; dünyada

Eşsiz bir çiçek miydi

Belki de hoş bir 

Sada bıraktı gitti

O; belki bir garipti

Kadere boyun eğdi

Bir avuç toprak

Ona da yetti.

Şimdi kim senin

Ardından ağlayan

Şimdi kim mübarek taşına

Fatiha okuyan

Şimdi kim seni hatırlayan

Her şey bitti.

Bütün iyilikleri

Unutuldu gitti.

Mehmet Akif Gülhan 06.01.2006', 'Senin kabrin  Kalbimde sessiz türbe              Sana geldim rahmetli Seni görmeye Yakışmadı sana  Yeşil saltanat arabası Yakışmadı belediye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sessiz-turbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-numan-eksioglu-osewu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hitler''si Yazarlara 

Mürekkebi bebeklerin kanından 

Ucu çekili tırnak

Sapı sökülmüş kemik

Eklemleri tanklarla çiğnenirken 

Kenetlenmiş ellerden

Tulumbası mahzende

İşkenceyle alınmış 

Bir yürekten oluşan 

Bir garip şeydir kalem

Sizin elinizdeyken', 'Hitler''si Yazarlara  Mürekkebi bebeklerin kanından  Ucu çekili tırnak Sapı sökülmüş kemik Eklemleri tanklarla çiğnenirken  Kenetlenmiş eller...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kalem-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeçenek', 'secenek-numan-eksioglu-3udt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İbrahim Dedenin Kendi Kendine Söylenişi

Tanrım 

Ya beni al 

Ya Şevket''i al

Ama ben sana ne yaptım

Sen yine Şevket''i al', 'İbrahim Dedenin Kendi Kendine Söylenişi Tanrım  Ya beni al  Ya Şevket''i al Ama ben sana ne yaptım Sen yine Şevket''i al...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/secenek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet', 'adalet-numan-eksioglu-fyb6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karga

Adalet sembolü heykelinin

Kefesine kondu

Terazi paslı mıydı

Sabit mi yapılmıştı

Kefe kımıldamadı', 'Karga Adalet sembolü heykelinin Kefesine kondu Terazi paslı mıydı Sabit mi yapılmıştı Kefe kımıldamadı...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adalet-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuştukça', 'konustukca-numan-eksioglu-dikt1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok Yetkili Ağıza

Konuşma

Konuştukça 

Sevgi siz eki alıyor

Saygı sız', 'Çok Yetkili Ağıza Konuşma Konuştukça  Sevgi siz eki alıyor Saygı sız...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/konustukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzum', 'arzum-suleyman-yavas-b16m1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Estirmek sana 

Sevdamın rüzgarlarını

Sana vermek

Aşkımın bütün hayatını

Mateminde 

Duymak kışını

Sevincinde

Görmek baharını

Arzdan arşa değen

Bir arzumdur benim', 'Estirmek sana  Sevdamın rüzgarlarını Sana vermek Aşkımın bütün hayatını Mateminde  Duymak kışını Sevincinde Görmek baharını Arzdan arşa değe...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arzum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünüm', 'gorunum-numan-eksioglu-mt52s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin yarı vahtıdı 

Özüm uyanık iyidim

Köpek mırılladı

Kapı cırılladı

Dedim hele mırıllasın

Dedim hele cırıllasın

Hele görüm neyliyir

Karaltıdır içeriye süzüldü

O an benim üreciğim büzüldü

Dedim dur bir süzülsün

Dedim dur dur büzülsün

Hele görüm neyliyir

Adam sıska yapılıydı

Elinde silah yoğ idi

Elin sandığa daldırdı

Karımın altınları

Benim paralarımı

Torbasına doldurdu

Dedim hele daldırsın

Dedim hele doldursun

Dur bir görüm neyliyir

Rahat rahat dolanırdı

Bütün evimi soyurdu

Dedim dur dolansın görüm 

Dedim dur bir soysun görüm

Hele görüm neyliyir

Adam torbayı kaldırdı

Ih dedi sırtına vurdu 

Dersin ceylan süzüldü

Dedim hele bir dur görüm

Hele hele neyliyir', 'Gecenin yarı vahtıdı  Özüm uyanık iyidim Köpek mırılladı Kapı cırılladı Dedim hele mırıllasın Dedim hele cırıllasın Hele görüm neyliyir Kara...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gorunum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yürek Eğittin Mi', 'hic-yurek-egittin-mi-numan-eksioglu-0arjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orantısız bölümler doluşmuş bedenlere

Hele hele şu kalpler

Beyinler orantısız

İnsan aşkı aldatmış 

Issıza yöneliyor

Hiç yürek eğittin mi

Adım yola kapalı

Yasa kasaya açık

Eşitsiz eşitlikler

Şiir pek bilinmiyor

Hiç yürek eğittin mi

Çiçek öğütülüyor

Sevgi eritiliyor

Beni sende bıraktım

Almaya niyetim yok

Böyle hep ters olmuyor

Hİç yürek eğittin mi', 'Orantısız bölümler doluşmuş bedenlere Hele hele şu kalpler Beyinler orantısız İnsan aşkı aldatmış  Issıza yöneliyor Hiç yürek eğittin mi Adı...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hic-yurek-egittin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bileceksin', 'nerden-bileceksin-yusuf-onder-bahceci-0c8qf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vallahi yazamam ben bu şiirleri,

O beni sevipte düşünmeseydi,

Kalpten kalbe bir yol varmış gidermiş,

Sevenler kendini heder edermiş,

Her sevenin arasına biri girermiş,

O beni sevmese onu düşünemem,

O istediği kadar unut desin unutamam,

Seven kalbi oyun, eğlenceyle avutamam,

Ölene dek böyle şiir yazar ağlarım,

Hiç bir şeyden zevk almam bizarım,

Nerde bir oyun görsem kızar bozarım,

İşte böyle geçer aylar, yıllarım,

Senden ayrı tam otuz yıl sayarım,

Dile kolay bunun gündüzü, gecesi,

Dile kolay bunun hecesi, bilmecesi,

Çok sevdiğim seni elimden almasınlar, 

Böyle boynu bükük bırakmasınlar diye,

Geceler boyu uyumayıp,

Bir o yana bir bu yana dönüp,

Allah''ıma yalvarır, yakarır dualar ederdim,

Söylesene sen bunu nereden bileceksin....', 'Vallahi yazamam ben bu şiirleri, O beni sevipte düşünmeseydi, Kalpten kalbe bir yol varmış gidermiş, Sevenler kendini heder edermiş, Her sev...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerden-bileceksin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayılış', 'ayilis-numan-eksioglu-bz3p0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kürsüye çıktığında 

Öndekinin tikindeki azgınlık 

Dikkatini çekiyor

Onun yanındakinin

Parmakları masaya sinirlice vuruyor

Bir kaçını kıravat boğar gibi oluyor

Bir kaçı yutkunuyor

Bir çoğunun gözleri çok büyüyor

Epeyce bir bölümün 

Aceleden bir işleri çıkıyor

Kendi grubundan da epyce çıkanlar var

Başkan süresini anımsatırken sesi titriyor

Anlam veremeyerek konusuna dönüyor

Birine içerlenmiş

Senin gördüğün yılan

Gidip derisini değiştirir diyor sadece

Koro halinde 

Bana hakaret edemezsin deniyor

O zaman ayılıyor', 'Kürsüye çıktığında  Öndekinin tikindeki azgınlık  Dikkatini çekiyor Onun yanındakinin Parmakları masaya sinirlice vuruyor Bir kaçını kıravat...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürkek Kanatlarımsın', 'urkek-kanatlarimsin-i-lknur-er-d2sgr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ürkek kanatlarımsın

Soğuk kış günlerinde

Varlığınla içimi ısıtan

Ve

Her an gitmeye hazır 

Kalbimin Efendisi

06.01.06 16:34', 'Ürkek kanatlarımsın Soğuk kış günlerinde Varlığınla içimi ısıtan Ve Her an gitmeye hazır  Kalbimin Efendisi 06.01.06 16:34...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/urkek-kanatlarimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-savas-dincbas-n3ips', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşamak seninle

..........sevmek seninle

güzelliği içmek

..........kanmak seninle

mutluluk tablosu

...........çizmek seninle

fırçadaki boyalar

...........kurumadan gel

besteler seninle

..............güfte seninle

yazılan en güzel

................eser seninle

mutluluk şarkısı

.........söylemek seninle

sazımdaki notalar

...........dökülmeden gel

bir ömür boyunca

..............sensiz,seninle

yaşadım yalnız ben

...............hep hayalinle

bir kez olsun diz dize

...............olmak seninle

yüce mevlam beni

............çağırmadan gel...', 'yaşamak seninle ..........sevmek seninle güzelliği içmek ..........kanmak seninle mutluluk tablosu ...........çizmek seninle fırçadaki boyal...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seninle-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Seven Sevenler', 'gercek-seven-sevenler-yusuf-onder-bahceci-z48lk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hepmi yalan oluyor,

Gerçek seven sevenler,

Seni sevdim demiyor,

Gerçek seven, sevenler.

Ne vardı söyleseydin,

Seni sevdim deseydin,

Sana yandım deseydin,

Gerçek seven, sevenler.

Gözlerinden daha çok,

Sözler seni bağlarmış,

Seven pekçok ağlarmış,

Gerçek seven, sevenler.

İşte böyle diyorum,

Sana sabır diliyorum,

Gözlerinden anlıyorum,

Gerçek seven, sevenler....', 'Hepmi yalan oluyor, Gerçek seven sevenler, Seni sevdim demiyor, Gerçek seven, sevenler. Ne vardı söyleseydin, Seni sevdim deseydin, Sana yan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gercek-seven-sevenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında yokum ben', 'aslinda-yokum-ben-i-smail-pekinoglu-gukkv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aslında yokum ben

bulutlarla çizilen bir imgeyim

                                    yalnızca.

Ne rüzgarın akışına bırakabilirim

                                              kendimi

ne de dalgalarına deryanın..

Aslında yokum ben,

sahte yakamozlarla örtülü

              bir düşüm belkide.

savurup dururum boşluğu,

       hiçlik deryasında

                  daracık bir gemide...', 'Aslında yokum ben bulutlarla çizilen bir imgeyim                                     yalnızca. Ne rüzgarın akışına bırakabilirim            ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aslinda-yokum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-numan-eksioglu-banjs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öğretmen Evren yürek

Kabul etsek-etmesek

Benimsesek-yok desek

İnsan eğitimsizse

Solgundur Evren çiçek

Bilgisizlik ilkelliğin adıdır

Bilim sanat ön sıra

Öğretmen ardı sıra

İnsanlar sıra sıra

Gelişime damgalar vurmalıdır

Öğretmenin dediği

Kavramada ön noktadır gözlerin

Gözlerini kapama

Aç duygularını

Nolursun üretiver

Yöresel olsun olsun

Evrensel aşksı olsun 

Nolursun hazır durma

Uzatıver bebelere elini

Dokunuver gamzesine ışısın 

Seçiliversin birden

Baharda tomurcukşık

Kara kışta soğukşık

Sevgi en güzel şıklık

Sevgi en güzel lezzet

Dostluk biraniden net

Sonrası otur seyret

Bebeklerce bakınıp

Her yanı kardeş seyret

Sonra sıra 

Kardeş orkestrasında

Kardeş korosundadır

Haydi koro

Herkesi şarkı dinlet

Ve orkestra

Bas ve net

İnansak-inanmasak

Duyumsasak-pööh desek

Savaş hayvan gelenek

Barış insan görenek

Öğretmenim dediği

Herkes sonsuz uzaydır

Herkes sonsuz yetenek

Herkes yeteneğince

Bal versin yeterki tek

Dünya sorunsuz petek', 'Öğretmen Evren yürek Kabul etsek-etmesek Benimsesek-yok desek İnsan eğitimsizse Solgundur Evren çiçek Bilgisizlik ilkelliğin adıdır Bilim sa...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ogretmen-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir ne zaman', 'kimbilir-ne-zaman-osman-taspinar-aadrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep okutmak isterdi de şu garip babam

Almadı nedense bir türlü bu man kafam

Benimle okuyanlar bitirdiler tamam

Yetişiriz belki biz de kimbilir ne zaman? 

Kalem''im mala oldu.Kravatsa çekiç

Gülmedi talih bize nedense hiç

Hayat çok zor,yaşamaksa daha güç

Kurtuluruz belki biz de kimbilir ne zaman.

Oluruz sanma ne matamatikçi,ne de biyolog 

Hocalarla kuramadık nedense bir diyalog

Ömrümüz tükenirken olsa da soluk soluk

Gideriz belki biz de kimbilir ne zaman? 

Hoyrat vurur felek bize sillesini

Dilerim kurtarır Rabbim cümlesini

Cümlesini değil,unutttuk kelimesini

Veririz belki biz de kimbilir ne zaman? 

Her yanı iki ders,her yanı bir beş

Atamadık yıllardır bir düşeş

Hayat bitip gider ne sevda ne bir eş

Severiz belki biz de kimbilir ne zaman? 

Boş vermektense karaladık bir şeyler 

Okusun da düşünsün diye hocalar

Her kime vardıysak iş yok diye kovalar

Buluruz belki biz de kimbilir ne zaman?', 'Hep okutmak isterdi de şu garip babam Almadı nedense bir türlü bu man kafam Benimle okuyanlar bitirdiler tamam Yetişiriz belki biz de kimbil...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimbilir-ne-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavra Canan', 'kavra-canan-numan-eksioglu-mshp2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldan aktan bol değil

Bolluk yalnız karadan

Kavra diye sürekli

Can mı vermeli candan

Sonsuzlukta hiçbirşey eksik değil

Doğamızda tek canlı artık değil

Hele insan insandan

Ne eksik ne de artık

Tüm eksikliklerimiz

AZ insanlığımızdan', 'Aldan aktan bol değil Bolluk yalnız karadan Kavra diye sürekli Can mı vermeli candan Sonsuzlukta hiçbirşey eksik değil Doğamızda tek canlı a...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kavra-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dürüstlük Olmalıdır', 'durustluk-olmalidir-seyfet-bozcali-j1nox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu vatanı yükseltmek ilkemiz olmalıdır.

İyi, güzel ahlakta üstünlük olmalıdır.

Dürüst,doğru sözlülük, ülkümüz olmalıdır.

Kardeşlik bağı için, dürüstlük olmalıdır...

Sevgi, barış, kardeşlik arzumuz olmalıdır.

Vatan, bayrak sevgisi hep sonsuz olmalıdır.

Güven, inanç, itikat iözümüz olmalıdır.

İnsan sevgisi için dürüstlük olmalıdır.

Din, dil, ırk, cins mevzusu ayrımsız olmalıdır.

Tüm vatan toprağında kardeşlik olmalıdır.

Gönderdeki bayrağa sevgimiz olmalıdır.

Yaşantımız boyunca dürüstlük olmalıdır...', 'Bu vatanı yükseltmek ilkemiz olmalıdır. İyi, güzel ahlakta üstünlük olmalıdır. Dürüst,doğru sözlülük, ülkümüz olmalıdır. Kardeşlik bağı için...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/durustluk-olmalidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ol...', 'sen-ol-ozen-oksuz-yomm4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giden sen ol...

Ben sırt dönemem bunca emeğe

İlk susan sen ol...

Ben dayanamam bu kadar sessizliğe

Git biran önce söndür ışıkları...

Bir gül verir gibi...

Sakince bırak git acıları

Öldüren sen ol...

Yüreğime çek tetiği ıskalamadan

Ne yaptığını bile anlamadan

Cesaretli sen ol...

Usulca bırak geçmişi ellerime

Düşünme,aldırma sözlerime

Gitmeden en güzel şiirini oku

Son defa bakarak gözlerime', 'Giden sen ol... Ben sırt dönemem bunca emeğe İlk susan sen ol... Ben dayanamam bu kadar sessizliğe Git biran önce söndür ışıkları... Bir gül...', ARRAY['Türk Edebiyatı','Şiir','Özen Öksüz']::text[], 8.5, '{"poet":"Özen Öksüz","poet_slug":"ozen-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-ol-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Plaj', 'i-ki-plaj-numan-eksioglu-jaa4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki plaj

Ortada tel örgü duruyordu

Hamfendi elindeki sebze artıklarını

Ücretsiz yana doğru

Fırlatmaya doğruldu

Beri yandan birisi hamfendiye

-Tıpkı önceki gibi-

Yuuh yuuh der gibi oldu

Hamfendi bozularak

-Tıpkı önceki gibi-

Ücretli yana döndü', 'İki plaj Ortada tel örgü duruyordu Hamfendi elindeki sebze artıklarını Ücretsiz yana doğru Fırlatmaya doğruldu Beri yandan birisi hamfendiye...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-plaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elektrikçilere', 'elektrikcilere-numan-eksioglu-6u0wo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çaydamlığımdaki su kaynadı

Sıcak su ister misiniz?', 'Çaydamlığımdaki su kaynadı Sıcak su ister misiniz?...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/elektrikcilere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Politikacı Dileği', 'politikaci-dilegi-numan-eksioglu-ryf8m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oyunuzu

Buyunuzu

