INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömlek-i Şerif (2)', 'gomlek-i-serif-2-mehmet-akif-tiryaki-fq774', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gömleği Resul-ü Ekrem giydi,

Osmanlı zamanında padişaha geçti,

Daha sonra saraydan bir hanıma verildi.

Saraylı Hanım da gömleği yerine emanet etti.

Emanetçi Ali Haydar Efendi''ydi.

Efendi Baba emri bil marufta kolera olmuştu,

Gayrimüslim bir doktora tedavi oldu

Doktoru karantinaya aldılar salmadılar,

Efendi Baba browning tabancasını aldı pencereden dışardakilere 

Doktoru bırakın dedi,

Doktor endişelendi sonra azat oldu.

Saraylı hanım bunu duydu bekledi, Baba iyileşti,

O zamanlar Efendi Baba Kumrulu''da oturuyordu.

Daha sonra İsmet Efendi Tekkesi''ne şeyh oldu.

Oraya kutsal emaneti başının üstünde götürdü.

Kadir geceleri ziyaretle meşgul oldu,

Arkasından emaneti torunu Hümeyra''ya bıraktı,

Vefatından sonrada işi damadı ele aldı.

Yatsı namazından sonra ceviz sandığından çıkarılıyordu,

Kat kat bohça, salat-ı ümmiye ile açılıyordu.

Sonra huşu ile ziyaret olunuyordu.

Ziyaret sonucu selevat ile katlanıp, sandığına koyuluyordu

Birdahaki ziyarete kadar sandık yok oluyordu.

Ziyaret esnasında edep harici davranışa girilmedi,

Aşırı gayretkarlık gösterilmedi.

Birdahaki ziyarete kadar kendinden söz edilmedi.

Server-i Enbiya(s.a.s)   Efendimiz''in gömleği beyaz pamuklu idi,

Ön kısmında ayetler, dualar vardı.

Birde vefkler ebcet hesabıyla yazılmıştı.

Göğüs kısmının iki yanı renkli idi.

Arka tarafı ise yazısızdı.

Efendi Baba bu yazıların daha sonra 

Aşıklar tarafından yazıldığını söylerdi,

Bu gömleklere eskiden savaşta giyilen

Dualı gömlek derlerdi.

Bu gömleğin yıkanmayışının sebebi,

Suyunun her derde şifa olması ebedi,

İnşeallah size de görmek nasip olur emi.', 'Bu gömleği Resul-ü Ekrem giydi, Osmanlı zamanında padişaha geçti, Daha sonra saraydan bir hanıma verildi. Saraylı Hanım da gömleği yerine em...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gomlek-i-serif-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher''e Özel', 'seher-e-ozel-murat-yazici-fve8z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir parçam sende kalıyor giderken

Hayalinle tek başınayım sen yokken

Senden gelecek güzel sözü bekler durur

Aşkınla, sevginle harman olmuş bu beden

Seni bütün varlığımla sevdiğimi söyledim

Sensiz tek bir anı istemeyen ben

Bendeki kalbin tek sahibi SEN:

Ne olurdu beni sevdiğini söylesen.', 'Bir parçam sende kalıyor giderken Hayalinle tek başınayım sen yokken Senden gelecek güzel sözü bekler durur Aşkınla, sevginle harman olmuş b...', ARRAY['Türk Edebiyatı','Şiir','Murat Yazıcı']::text[], 8.5, '{"poet":"Murat Yazıcı","poet_slug":"murat-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seher-e-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-mehmet-faruk-habiboglu-xic4i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşluk vaktinde nedir düşündüğüm

Bu, düşler sokağına adanmış şiir

Hani gözlerindeki tenha kediciğim

Kuytularında seni saklar bu şehir

Bir telaşa dûçar yorgun yüreğim 

Harflerde gizlenen sen misin, kimdir

Yahut ben de bu ülkenin zencisiyim

Sofrada payımıza bir çanak zehir..

Kediciğim ben senin ellerinde öleceğim

Senin için ama.. Unutma kediciğim..', 'Kuşluk vaktinde nedir düşündüğüm Bu, düşler sokağına adanmış şiir Hani gözlerindeki tenha kediciğim Kuytularında seni saklar bu şehir Bir te...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hani-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokoluştaki Çaresizlik', 'yokolustaki-caresizlik-figen-aydogmus-ilxpv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanıyor 

Ortasında durduğum hayallerim

Başımdan ayak uçlarıma kadar iniyor sızılar

İliklerimden geçerken kırılan umutlar

Ümit bekliyor çaresiz olan gözlerim

Yalancı bir hayatın damarlarında akmayan kan gibiyim

Yoluna setler diziliyor

Yağmur gibi akmak isterken gözümdeki yaşlar

Çaresizim

Bir teselli gül yüzlü pamuk tenli 

Sevdiğim

Sana bütünleri verdim nerdesin

Parçalanan mutluluğu birleştirdim

Nerdesin

Beklemekle oldurmuyor hayat gülümsemeleri

Karanlık ışık olmadan anlamsız kalıyor

Sarhoşum diyorum sevdiklerime 

Onlar da beni anlamıyor

Ah dostlarım, sevdiğim ah,

Bilinmezmi gözüne bakınca çekilen acı

Anlamak istemez misiniz beni 

Boş verdiniz sizde hayatın içindeki sevmeyi

Ama ben

Ben yokoluştayım

Tutun artık elimi

Güzel günlerin Dostları

Sevgilim 

F.A. 07.01.2006', 'Yanıyor  Ortasında durduğum hayallerim Başımdan ayak uçlarıma kadar iniyor sızılar İliklerimden geçerken kırılan umutlar Ümit bekliyor çares...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yokolustaki-caresizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapanca Gölü''nün Dibinde', 'sapanca-golu-nun-dibinde-mehmet-akif-tiryaki-nkamq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sapanca gölünün dibinde,

Kaynayan sular vardır en derininde.

Göl balığı lezzetine doyulmaz,

Gölde dalga sesi duyulmaz.

Büyük bir havuzdur Sapanca Gölü bize,

Temiz bırakmalıyız diğerlerimize,

Tatlı su gölün buharı çevreye yayılır,

Ilık bir buhar etrafa dağılır.

Ilık buhar dağa çıkar dinlenir,

Ormanın oksijeni göl kenarına gelir.

Bir türlü buluşamazlar orta bir yerde,

Sapanca havası şifadır her derde.

Kırılan kemiklerin en iyi ilacı oksijendir,

Oksijen Sapanca''da imal edilendir.

Yağmur çoktur, fırtınası nadir,

Soğucak yaylası her derde çaredir.', 'Sapanca gölünün dibinde, Kaynayan sular vardır en derininde. Göl balığı lezzetine doyulmaz, Gölde dalga sesi duyulmaz. Büyük bir havuzdur Sa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sapanca-golu-nun-dibinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ünlem! ...(A.D. Dosyasından)', 'unlem-a-d-dosyasindan-naime-erlacin-pgn9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anlamlı bir adı yok! 

''sabahı idam eden kadın'' diyorlar ona

uyandırılmayan tüm sabahları

uyanılmayan...

ağlıyordunuz siz 

çılgın şiirler söylüyordunuz 

siyahi bir güneşe doğru

kara büyünüzden kalmıştı 

is kokan çığlıklar

bir ihtimal 

lav kusan dağın eteklerinde

''geceyi katleden adam''a terk edilmişti rüyalar

‘yangına giden’ ‘ateşten gelen’i süzdü böyle

geceye hesabını veremedi gün

iri birer ünlemdi gözlerdeki bakışlar

ağlıyorduk biz...

(7 Ocak 2006)', 'anlamlı bir adı yok!  ''sabahı idam eden kadın'' diyorlar ona uyandırılmayan tüm sabahları uyanılmayan... ağlıyordunuz siz  çılgın şiirler söy...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unlem-a-d-dosyasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenime', 'ogretmenime-ferit-agca-i2b2h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Minicik ellerimle dokundum,

Koskaca yüreğine.

Büyüdükçe büyüyen su dalgası,

Öğrenmeye dair.

Bir zamanlar oyun oynadığım

Kelime yığınları,

Seninle anlam kazanan.

Parmaklarla öğrettiğin 

Sayılar karmaşasından öğrendim,

Hayatı formülize etmesini.

Şimdi  dokunabildim,

Hatırımdaki resmine,

Tebeşir kokan ellerine,

Ve gizli ağlamalarına,

Seni sakladım geleceğe.', 'Minicik ellerimle dokundum, Koskaca yüreğine. Büyüdükçe büyüyen su dalgası, Öğrenmeye dair. Bir zamanlar oyun oynadığım Kelime yığınları, Se...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ogretmenime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Kaotik Tortu...', 'kaotik-tortu-naime-erlacin-4fz3o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'inkâr edildi 

geçmişe nakşolmuş sırlar

inkâr edildik hepimiz

serdengeçti bir dolu ânın şimdi

mağrur suskunluğudur son hükümdar

“öteki”liğini haykırır duygu seli 

vurdumduymaz bir nankörlüğün 

zarfını mühürler çığlık çığlığa 

hayata dair kesin ikrarın

adlarımızı aradık 

bulanık sularda

susmadı hiç isimsiz kalabalık

uzaklar sonsuza ağıt

acıyla çözüldü şifresi isyanın

ruhun şir’i pençesidir 

tekilliğine ağlayan kaotik özne 

ve sorar sahipsizlik 

hangi duruştan kaldı bu tortu

eskitemediğimiz hangi yüzünden zamanın? 

(7 Ocak 2006)', 'inkâr edildi  geçmişe nakşolmuş sırlar inkâr edildik hepimiz serdengeçti bir dolu ânın şimdi mağrur suskunluğudur son hükümdar “öteki”liğini...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaotik-tortu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal varsa gerçek de vardır', 'hayal-varsa-gercek-de-vardir-muhsin-yener-ao63i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayal varsa gerçek de vardır,

demiştin ya...

Bir çocuğun avuçlarında sakladığı

ekmek sıcaklığı gibi inandım sana.

Çünkü hiçbir şehir

önce düşlenmeden kurulmadı.

Hiçbir türkü

bir yüreğin içi yanmadan söylenmedi.

Hayal dediğin

bir işçinin nasırlı ellerinde büyür bazen,

bazen mapus damında

göğe bakarken çoğalır.

Ve insan

önce içinden geçirir dünyayı değiştirmeyi,

sonra bir sabah

elleriyle kurar yeniden.

Hayali kurulmayan gerçek

olur mu hiç?

Tohuma düşmeden filiz olur mu umut?

Geceyi düşlemeyen

sabaha inanabilir mi?

Ben biliyorum;

en güzel gerçekler

bir insanın içindeki

inatçı hayallerden doğar.', 'Hayal varsa gerçek de vardır, demiştin ya... Bir çocuğun avuçlarında sakladığı ekmek sıcaklığı gibi inandım sana. Çünkü hiçbir şehir önce dü...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-hic-affetmeyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapanca Tiryakisi', 'sapanca-tiryakisi-mehmet-akif-tiryaki-5em86', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tiryakisiyim Sapanca''nın 

Bir de senin, 

Tiryakisiyim oksijenin. 

Ağaç kokusunu özlemişim, 

Bir de ıslak serinliğini Kartepe''nin. 

Tepelerine insanlar yuva kurmuş Sapanca''nın, 

Önünde büyük bir havuz aşiyanın. 

Yeşilin bulunmayan bir türü varsa o buradadır, 

Sabah gün ağarırken sizi kuşlar uyandırır. 

Bir başkadır tabiatı Sapanca''nın, 

Serttir mizacı yaşayan insanının. 

Misafirperverdir, dosttur onlar size, 

Biraz kaba olsalar da gönüllerini verirler bize. 

Benden selam olsun hepinize. 

Sapanca Dağları''nı duman bürümüş, 

İkbâliye, İlmiye, Memnuniye beyaz şal örtünmüş, 

Lacivert taçlı gelin parfüm sürünmüş, 

Buram buram aşk kokar tepelerde, 

Demli çaylar içilir, sahildeki çay bahçesinde 

İşte böyledir Sapanca 

Tiryaki''nin penceresinde.', 'Tiryakisiyim Sapanca''nın  Bir de senin,  Tiryakisiyim oksijenin.  Ağaç kokusunu özlemişim,  Bir de ıslak serinliğini Kartepe''nin.  Tepelerin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sapanca-tiryakisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair-2', 'sana-dair-2-ferit-agca-emba4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oksitlenmiş düşüncem,

Geceler boyu kıvranan,

Yatağın sağından soluna.

Hâlâ göğüslerinden besleniyorum.

Ve hâlâ duyuyorum,

Gecede birleştiren,

Ağır krem kokunu.

Biliyorum aynı kaldırımdayız.

Oynak kaldırım taşlarından

Sular sıçratıyoruz hâlâ.

Ve hâlâ uyuma taklidindesin

Küfretmenin karmaşasında,

Kalbinle aklın arasındasın.

Oksitlenmiş düşüncem,

Geceler boyu kıvranan,

Bir duvardan diğerine.

Ve ben,

Hâlâ gözlerini yazıyorum,

Susamış şiirlerin satırına.', 'Oksitlenmiş düşüncem, Geceler boyu kıvranan, Yatağın sağından soluna. Hâlâ göğüslerinden besleniyorum. Ve hâlâ duyuyorum, Gecede birleştiren...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-dair-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nemli Bir Öpücük', 'nemli-bir-opucuk-mehmet-akif-tiryaki-cvi3c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sapanca gölü uyumuş kalmış, 

Kış gününde hayale dalmış, 

Tepeler beyazlanmış, 

Sapanca''da bir yavaş dans başlamış. 

Hava karardığında melekler, 

Sapanca Gölü''ne inecekler, 

Müzik ahenk demekse eğer ortam sesli, 

Tabiat bu dansa hevesli. 

Devam edecek sabaha kadar bu vals, 

Sabah başka bir senaryo, başka bir dans. 

Sürer günlerce Sapanca''da bu türbülans. 

Nemli bir öpücük duyarsınız çehrenizde, 

Kapılırsınız bu büyüye isteseniz de...istemeseniz de..', 'Sapanca gölü uyumuş kalmış,  Kış gününde hayale dalmış,  Tepeler beyazlanmış,  Sapanca''da bir yavaş dans başlamış.  Hava karardığında melekl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nemli-bir-opucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şey var aramızda', 'bir-sey-var-aramizda-muhsin-yener-2oz0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şey var aramızda

adı konmamış bir kavga gibi

susunca büyüyen,

konuşunca dağılan...

Senin gözlerinde ışıldıyor

geceyi yaran bir işçi lambası gibi,

benim dilimin ucunda

yarım kalmış bir türkü.

Bir şey var aramızda,

ellerimizi birbirine çağıran

ama yolları susturan.

Sen bakınca

şehirlerin bütün yalnızlığı

omzuma çöküyor.

Ve ben

hangi sözcüğü seçsem

bir yanım sürgün kalıyor sana.

Çünkü aşk dediğin

biraz memleket hasreti,

biraz devrim sabrı,

biraz da

bir insanın gözlerinde

yeniden doğmaya inanmasıdır.', 'Bir şey var aramızda adı konmamış bir kavga gibi susunca büyüyen, konuşunca dağılan... Senin gözlerinde ışıldıyor geceyi yaran bir işçi lamb...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mutluluklar-dilerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardayım', 'uzaklardayim-i-smail-baharsen-0r5jc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ararsa gözlerin dalmasın mateme..

ben şimdi çok uzaklardayım..

hasretin sisli gölgesinde..

kaybolan bir ufuktayım..

yüreğim saklı zincirle..

karanlık şafaklardayım..

bitmeyen kasvetimle..

ışıksız karanlıktayım..

firar etmemi düşünme..

bitmeyen zorlardayım..

ölüm var ellerimde..

hayatla pusudayım..

korku girdi düşlerime..

ürkek uykulardayım..

nöbetim senin sevgine..

bir kurşun ucundayım..

başıboş gecelerce..

kahpe mayınlardayım..

bilinmeyenlerimle..

sırda saklıyım..

ölüm gözlüm..

şimdi uzaklardayım..', 'ararsa gözlerin dalmasın mateme.. ben şimdi çok uzaklardayım.. hasretin sisli gölgesinde.. kaybolan bir ufuktayım.. yüreğim saklı zincirle.....', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uzaklardayim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naz', 'naz-selma-sengoren-gb17k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaçma güzel

Etme naz

Gözler buğulu,

Dudaklar kiraz

Savurur saçların

Sümbülüne dokunur zülfün

Açılan gamzene gözlerim oldu meftun

Gülüşündedir endam

Bakışındadır vurgun sevdam

Götür beni sonsuzluğa

Düşlerime konuk ol,

Hayalimde kalıver biraz

Kaçma güzel

Etme naz

Gözler buğulu,

Dudaklar kiraz

Nefesinle dol

Ateş ol

Dumanınla tüt de,

Gönlümün köşkünü yakıver biraz

Kelimelerim ol konuş

Çiçeklerini dök ruhuma,

Kokunla beni sar, sar biraz

Kaçma güzel

Etme naz

Gözler buğulu,

Dudaklar kiraz

Ay yüzlüm, bal sözlüm

Gel bende ''ben'' ol,

Leylaklara ömrümü seriver de,

Öksüz bedenimi yaşat, yaşat biraz.', 'Kaçma güzel Etme naz Gözler buğulu, Dudaklar kiraz Savurur saçların Sümbülüne dokunur zülfün Açılan gamzene gözlerim oldu meftun Gülüşündedi...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/naz-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yARIM', 'yarim-mehmet-faruk-habiboglu-uzp3d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siyaha yer açın beyaza elveda

Sular duruldu sırlar uslandı

Kesif bulutlar var havada

Hüzün artık yüreğime yaslandı

Cinnet meclisidir aklın durağı

Sorunun ötesi cevabın berisi

Apansız devrildi rindan otağı

Yalnız hüzün! Boş gerisi..', 'Siyaha yer açın beyaza elveda Sular duruldu sırlar uslandı Kesif bulutlar var havada Hüzün artık yüreğime yaslandı Cinnet meclisidir aklın d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Kumu', 'cam-kumu-aydin-erkurt-7dxi1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şen nakaratlı kahkahalar kalır,

Cam kılığındaki zamandan,

Diktiğimiz kumdan kale gölgesine.

Uykularda büyür, yaşlanır, hazırlanırız; 

Yok sayıp kısalttığımız gecenin rengine.

Gün; güneştir hâlbuki

Doğumunu, batımını çekeriz

Albümlerimize.

Pencerelerimiz var,

Yaşlı-genç insan yavruları

Sığmıyor, karanlığın arka bahçesine.

Son soluğu duymazsak,

Toprak atmazsak bir de üzerine,

Şahitlenmez.

Katlanır, belki gönül,

Cam kumu, geri dönülmeze.

(ARALIK-2005)', 'Şen nakaratlı kahkahalar kalır, Cam kılığındaki zamandan, Diktiğimiz kumdan kale gölgesine. Uykularda büyür, yaşlanır, hazırlanırız;  Yok sa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Erkurt']::text[], 8.5, '{"poet":"Aydın Erkurt","poet_slug":"aydin-erkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cam-kumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-adnan-durdagi-77d4o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşmüşsün sevdaya yanmışsın belli

Kapılmış hayale kanmışsın belli

Aşkın şerbetine banmışsın belli

Sevda seni sarmış sende sevdayı

Görünen köylere kılavuz olmaz

Sevgi bir çiçektir açınca solmaz

Aşk bir dipsiz kuyu doldursan dolmaz

Sevda seni sarmış sende sevdayı

Bu yol uzun bir yol gitmekle bitmez

İçerden yanmışsın dumanın tütmez

Çaresiz kalımışsın derman kar etmez

Sevda seni sarmış sende sevdayı

Kurulmuş kainat sevda üstüne

Dağları delmişler gönül dostuna

Melekler bürünmüş sevgi postuna

Sevda seni sarmış sende sevdayı

Yetimi Adnan der sevmiş gönülden

Aşkın mahkum etmiş ne gelir elden

Ağlatmış aşığı söyletmiş dilden

Sevda seni sarmış sende sevdayı', 'Düşmüşsün sevdaya yanmışsın belli Kapılmış hayale kanmışsın belli Aşkın şerbetine banmışsın belli Sevda seni sarmış sende sevdayı Görünen kö...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu nasıl edep', 'bu-nasil-edep-ali-riza-unal-r240n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o aşk ilâhi ise,edebi bilmez,

bir sevdaki ölür  dirilmez,

meyittir musallada selâ verilmez,

yatar bir çukurda kabri bilinmez

nicedir edep, ya edep yahu,', 'o aşk ilâhi ise,edebi bilmez, bir sevdaki ölür  dirilmez, meyittir musallada selâ verilmez, yatar bir çukurda kabri bilinmez nicedir edep, y...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-nasil-edep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Susar Tekmil Kuşlar', 've-susar-tekmil-kuslar-zek-i-budak-y4416', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelir de sineden uçar gider sevgili

Üstüne titreyerek yeşerttiğin dal kurur

Silinse dahi gözden gül cemâlin hayâli

O bitmesi imkânsız aşkın sancısı durur

Boşuna tesellîye çalışır seni herkes

Dinecek yerde heyhat büyür içinde heves

Seni çağırır durur gecelerden gelen ses

Ve susar tekmil kuşlar, sadece bir gong vurur

(Yok Dönmene İhtimal - 2003)', 'Gün gelir de sineden uçar gider sevgili Üstüne titreyerek yeşerttiğin dal kurur Silinse dahi gözden gül cemâlin hayâli O bitmesi imkânsız aş...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ve-susar-tekmil-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-erhan-tigli-wksen', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyü çocuğum büyü

	Çek yalanın üstünden

	Aldatıcı kara örtüyü

	Büyü çocuğum büyü

	Kur güzelliğe köprüyü

	Çözülsün karanlık büyü

	Yaşa gönlünce

	Yaşamak adlı  öyküyü

	Büyü çocuğum büyü

	Uyandır bilinçsiz uykuyu

	Yır at kuşkuyu

	Göm mezara korkuyu

	Çekmesin derinliğine seni

	Karamsarlık adlı kör kuyu

	Büyü çocuğum büyü

	Korkma dokuz köyden kovulmaktan

	Unutma onuncu köyü.

					Erhan Tığlı', 'Büyü çocuğum büyü 	Çek yalanın üstünden 	Aldatıcı kara örtüyü 	Büyü çocuğum büyü 	Kur güzelliğe köprüyü 	Çözülsün karanlık büyü 	Yaşa gönlün...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buyu-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş..', 'bekleyis-i-smail-baharsen-pk3so', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bekle demiştin giderken..

ellerin elimde değildi neden

çokmu zordu son bir bakış..

ve sen gittin bense yaralı..

yılları kovaladı bu hasret..

depreşti duygularım..

geçen zamanla..

her doğum gününü

her yılbaşını sensiz kutladım..

acılarımla içtim sevgini..

bitmedi içimdeki bu bekleyiş..

kar aldım sensiz koynuma..

yalnızlıktan farkı yoktu..

yalnızlığın senden...

bir adım atsan bitecekti..

gönlümdeki bu sesleniş..

lanet olsunki bana...

seni sevmişim...

herşey bitti ömrümde..

tek bitmeyen sensin..

yılların suçu yok biliyorum..

Ahmet Selçuk tan okudum

gelmeyen sensin...', 'bekle demiştin giderken.. ellerin elimde değildi neden çokmu zordu son bir bakış.. ve sen gittin bense yaralı.. yılları kovaladı bu hasret.....', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bekleyis-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsizlik', 'umitsizlik-zek-i-budak-9nc3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerin uçuşması bir şey değildir belki

Zaman denen rüzgârla bilinmez bir mekâna

Velâkin ağacımız kökünden kurumada

Yok gelecek bahardan gün görmek tesellîsi

Ey Tanrı ''nın sonsuza yol alan cengâveri

Dur ve sor edindiğin bu dinmez cinnet neden

Neden hiç acımadan en yağız ümitleri

Dizmişiz kurşunlara, şafağı beklemeden

(Telecam / Lüleburgaz - 24.08.1982)', 'Günlerin uçuşması bir şey değildir belki Zaman denen rüzgârla bilinmez bir mekâna Velâkin ağacımız kökünden kurumada Yok gelecek bahardan gü...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umitsizlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim Bilemedim', 'bilemedim-bilemedim-yusuf-onder-bahceci-k411m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu Dünya çoktan kokmuş,

Aşkın Kanunu hiç yokmuş,

Dünya hepten yokuşmuş,

Bilemedim bilemedim.

Gerçek seven alamazmış,

Alıpta hiç saramazmış,

Sevenler hep ayrılırmış,

Bilemedim bilemedim.

Bunu çok geç anladım,

Senden ayrı hep ağladım,

Bu ellerde yalnız kaldım,

Bilemedim bilemedim.

Şimdi gelse ne olurki,

Derdim nasıl son bulurki,

Yalnız kaldım tek başıma,

Bilemedim bilemedim....', 'Bu Dünya çoktan kokmuş, Aşkın Kanunu hiç yokmuş, Dünya hepten yokuşmuş, Bilemedim bilemedim. Gerçek seven alamazmış, Alıpta hiç saramazmış, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilemedim-bilemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Patlak Kazablanka Bahçesi**', 'patlak-kazablanka-bahcesi-burcu-alpaslan-guvenli-zkd4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kağıtlara teslim oldu

__hayallerim

Yazıp çizdiklerim

ekleyip çıkardıklarım

Tutturabilmek

umutları________

____sakınmalı insan 

hayatın dengesiz bakışlarından….

bir tuhaf çelişkidir

___ hayat

kendine dolanan….

suç bulamazsın! ! 

O’ da garip

____kime ne anlatsın! ! 

Sen; 

Unutma…yeter

Yaratılışındandır; 

düşündüklerini 

gerçek yapabilme gücün

Ne zaman of çeksen

Düşhane’ nde

senin için

inadına beyaz bir kazablanka daha patlar! ! ! 

07/01/2006(İstanbul - Düşhane’ m)', 'Kağıtlara teslim oldu __hayallerim Yazıp çizdiklerim ekleyip çıkardıklarım Tutturabilmek umutları________ ____sakınmalı insan  hayatın denge...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/patlak-kazablanka-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Bahara Benzer', 'omur-bahara-benzer-i-smail-baharsen-33wc1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ömür bahara benzer,çiçekli..

taze dalında yakut asılı..

gözyaşına benzer,yanakta

iz bırakan kıpkırmızı..

ömür bahara benzer,nisanda

çiğ damlası gül tende..

yağmura benzer,yalandan

ıslatıpta geçen üstünden..

ömür bahara benzer,güneşli..

asalak bulutlarda kaybolan..

yalana benzer,kuyruklu..

bittiğinin farkına varmadan..', 'ömür bahara benzer,çiçekli.. taze dalında yakut asılı.. gözyaşına benzer,yanakta iz bırakan kıpkırmızı.. ömür bahara benzer,nisanda çiğ daml...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omur-bahara-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelek Var Yenden Güzel', 'yelek-var-yenden-guzel-zek-i-budak-20oat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende olsaydı eğer, kapında ne arardım

Sürmediğim baharı isteme benden güzel

Şalvarı beğenmez de yen deyip tutturursun

Yen de güzeldir ama yelek var yenden güzel

Hak kusurumu bırak kul kusurumu bildir

Hoş olan suret değil güler yüz tatlı dildir

Yeğleme ayrılığı gönül razı değildir

Tırnağı cansız sanıp koparma tenden güzel

Eğleyemez başka yâr, sevdanda iken beni

Gönül verdimse güle, korkutmaz diken beni

Cismin değildir asla, işvendir çeken beni

Maksat güzel sevmekse güzel var senden güzel

(Kartal / İstanbul - 23 Mart 1980)', 'Bende olsaydı eğer, kapında ne arardım Sürmediğim baharı isteme benden güzel Şalvarı beğenmez de yen deyip tutturursun Yen de güzeldir ama y...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yelek-var-yenden-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Doğurgan', 'yasam-dogurgan-h-hikmet-esen-5feev', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelecek,

Geçmişin köprüsünde.

Altından,

Coşkun sular gibi

Akarken,

Zaman; 

Anılar yürekte gizli,

Tükenen,

Sadece an.

Oysa her an,

Gül fidelerinde patlayan,

Tomurcuklar gibidir.

Yaşam,

Doğurgan...', 'Gelecek, Geçmişin köprüsünde. Altından, Coşkun sular gibi Akarken, Zaman;  Anılar yürekte gizli, Tükenen, Sadece an. Oysa her an, Gül fidele...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasam-dogurgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzmin Dert', 'muzmin-dert-zek-i-budak-6w5vk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unuttum sanma sakın içimdesin halâ sen

Varlığınla müzmin dert, hâtıranla belâ sen

Bilmesem bile şimdi hangi iklimlerdesin

Unuttum sanma sakın içimdesin halâ sen

Koynunda bir yorgun baş mes''ut ve râm uyusun

Başka murat isteme günahınla mutlusun

Ölmeyince işlevi sona erer mi us''un

Unuttum sanma sakın içimdesin halâ sen

Varlığınla müzmin dert, hâtıranla belâ sen

(Yok Dönmene İhtimâl - 2003)', 'Unuttum sanma sakın içimdesin halâ sen Varlığınla müzmin dert, hâtıranla belâ sen Bilmesem bile şimdi hangi iklimlerdesin Unuttum sanma sakı...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muzmin-dert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocama', 'hocama-ulya-erkman-lpjmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kitap geciverdi dun elime 

Kapaktaki resme baktim huzunle

Hatiralar canlaniverdi sanki birden

Okuyor gibiydim onun da gozlerinden

O hocamdi ben ise genc talebesi

Belli olurdu her haliyle sevgisi

Ben on sekiz yasinda o ise kirkinda 

Yazilmamisti beraberlik alnimiza

Gocup gitmisti sonra sair ruhu

Bulmustu nihayet olum huzuru

''Seni unutmadim'' der gibi yillar sonra

Siir kitabiyla cikiverdi karsima

Huzunle baktim resme dalarcasina

Rahmet okudum sonra sair ruhuna

Hurmetle andim hatirasini

Kalbime gomdum sair askini

             Nur Icinde yat

 Ahmet Hamdi Tanpinar', 'Bir kitap geciverdi dun elime  Kapaktaki resme baktim huzunle Hatiralar canlaniverdi sanki birden Okuyor gibiydim onun da gozlerinden O hoca...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hocama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Sana Demli Çaylar', 'helal-sana-demli-caylar-mehmet-akif-tiryaki-dkgpk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Defter beyaz,

Kağıt beyaz,

Kalem siyah yazıyorsa eğer,

Hayat her şeye rağmen yaşamaya değer.

Bir de cebimizde varsa simitle çay parası,

Gel keyfim gel,

Köşebaşı kahvesinde

Sabah kahvaltısı

İlk çay ve sıcak simit halkası

Bir şehir yaşantısı

Bir sabah manzarası.

Üstüne içilen ikincisi avantası.

Helal sana demli çaylar

Arap çocuğu.

Gene kaptın kısmeti,

Bitti kahvaltı hasreti.

Başladı hayatta kalma mahareti

Hem dürüst olacaksın,

Hem de helal kazanacaksın.

Kalmayacak kimsede hakkın,

Ne de sen yedireceksin hakkını.

Bıraktım sigara merakımı,

''Helal sana demli çaylar'' derdi baba,

Vermedim paramı asla rakı, şaraba.

Buna yaşamak denirse yaşıyorum herkese merhaba,

Hayat geçiyor oflaya puflaya.', 'Defter beyaz, Kağıt beyaz, Kalem siyah yazıyorsa eğer, Hayat her şeye rağmen yaşamaya değer. Bir de cebimizde varsa simitle çay parası, Gel ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/helal-sana-demli-caylar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Dertli Olmazdım', 'boyle-dertli-olmazdim-yusuf-onder-bahceci-7gu94', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen beni sevmeseydin,

Bana gönül vermeseydin,

Bende seni sevmezdim,

Böyle dertli olmazdım.

Sen bana gülmeseydin,

Seni sevdim demeseydin,

Seni sevdim gelmeseydin,

Böyle dertli olmazdım.

Bana güller vermeseydin,

Güzel sözler demeseydin,

Beni sevip görmeseydin,

Böyle dertli olmazdım.

Şimdi ağlıyorum buralarda,

Soruyorum uçan kuşlara,

Deseydin ki boşuna uğraşma,

Böyle dertli olmazdım.', 'Sen beni sevmeseydin, Bana gönül vermeseydin, Bende seni sevmezdim, Böyle dertli olmazdım. Sen bana gülmeseydin, Seni sevdim demeseydin, Sen...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boyle-dertli-olmazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tembellik', 'tembellik-mehmet-akif-tiryaki-b62z5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dur demeli artık bu gidişe,

Çekilmeliyiz kabuğumuz geç bile kaldık,

Zevke, eğlenceyede daldıkça daldık.

Seyrediyorsam tv kime ne? 

Hanım da zaten örüyor evde tentene,

Girilirmi kilitli olan meskene

Değermi ticaret bunca riskine

Yakışırmı hergün çalışmak miskine

Beş gün işe gitmek nemize yetmez,

Bir gün daha tatil olsa kimse reddetmez.

Tembel olduk artık hey hat acı bize,

Ne yaparsak yapalım iflah etmez kendimize.', 'Dur demeli artık bu gidişe, Çekilmeliyiz kabuğumuz geç bile kaldık, Zevke, eğlenceyede daldıkça daldık. Seyrediyorsam tv kime ne?  Hanım da ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tembellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınımsı', 'aydinimsi-emin-nadir-jrh76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendini halktan koparmış,

Aydın geçinen aydınımsı.

''Bu millet sanattan anlamıyor kardeşim''

Demişsin.

Anlattın mı? 

Köy meydanlarında sergilemeyi

Düşündün mü resimlerini? 

Bir bardak ayran eşliğinde.......

Galerileri,kokteyl bardaklarını

Bırakıp.

''Bu millet okumuyor.'' muş.

Okuttun mu? 

Halkın anlayacağı dilden 

Yazdın mı şiirlerini? 

Bir kelimeniz; 

Bir ansiklopedi bilgisi.

Bar köşelerinin loş ışıklar şairleri...

Balıkçıların ellerindeki

Ağızdan ağıza dolaşan şarap şisesi

Daha paylaşımcı,

Daha aydınlık sizden.

Çıkın artık şu,

Billur kadehlerinizden', 'Kendini halktan koparmış, Aydın geçinen aydınımsı. ''Bu millet sanattan anlamıyor kardeşim'' Demişsin. Anlattın mı?  Köy meydanlarında sergile...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aydinimsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum De Gitsin', 'seviyorum-de-gitsin-yusuf-onder-bahceci-se0d3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vallahi sen seviyorsun,

Ama niye demiyorsun,

Allah sana akıl versin,

Seviyorum de gitsin.

Yıllar olmuş demiyorsun,

Ömür bitmiş bilmiyorsun,

Hayal edip gülüyorsun,

Seviyorum de gitsin.

O da seni seviyor,

Hep yolunu bekliyor,

Hayal edip ağlıyor,

Seviyorum de gitsin.

Ne kadarda zormuş böyle,

Sen gözünü yumda söyle,

Ondan sonra gönül eyle,

Seviyorum de gitsin...', 'Vallahi sen seviyorsun, Ama niye demiyorsun, Allah sana akıl versin, Seviyorum de gitsin. Yıllar olmuş demiyorsun, Ömür bitmiş bilmiyorsun, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-de-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Olsun', 'gecmis-olsun-mehmet-akif-tiryaki-4r1ma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer para parayı çekerse,

İnsanlar sokaklarda kurban keserse,

Kuş gribi beyaz et tüketimini etkilerse,

Tinerciler sokaklarda her önüne gelenden para isterse,

Polisler dolandırıcılarla el ele verirse,

Zatürreden çocuklar ölürse,

İstanbul''da verem salgını başgösterirse,

Üç gün içinde bir dükkana iki defa hırsız girerse,

Serseri kurşunlar insanlara isabet ederse,

Gazeteciler falcılara sorarak haber verirse,

Gayrimenkul fiyatları zirveye giderse,

İnsanlar emlakçılığı meslek seçerse,

Sümerbank indirime giderse,

Takım elbise onsekiz milyon ederse,

Görevimiz tehlike filmi vizyona girerse,

Hamit Karzai Türkiye''ye gelirse,

Hande Yener müzikleri dinlenirse,

Amerika Irak''a girerse,

Tek bir şey söylemek istiyorum,

Ve size ''geçmiş olsun'' diyorum..', 'Eğer para parayı çekerse, İnsanlar sokaklarda kurban keserse, Kuş gribi beyaz et tüketimini etkilerse, Tinerciler sokaklarda her önüne gelen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecmis-olsun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süngü, Gece, Ay ışığı', 'sungu-gece-ay-isigi-kenan-taskin-acntn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir, iki, üç demeden atladılar

Soğuk zemperi esmekteydi, sağ baştaki çavuş

Gözlerini dikmiş haykırmakta ve ufukta sancılı bin ana doğurmaktaytı.

Ahmet onbaşı elinde kınalı çakmağı bir tüfeğini temizlemekte birde doğan yeni bebeğe bakmaktaydı.

Bulutlar çok karaydı, topların barut kısımına değmesin diye anneler yavrularını sarar gibi onları sarmaktaydılar.

Bir tek ürkeklik yoktu Kürt Ali Laz Memet hepsi buradaydı.

Bir emirle yer gök inleyecek ve gözlerindeki gizli prangalar çözülecekti.

Sabaha doğru Conkbayırı ateş sesleriyle inledi sesler sesleri çığlıklar çığlıkları kovaladı ve yeni doğan bebek de dahil hiçbiri geriye bakmadılar anneler tanımadan veriyorlardı. topları erkeklerin ellerine,

Yerden yatan kandı

Ama önlerinde her geçen zaman azim ve doğan bebeğe

Bırakılacak özgür bir vatandı

Ufukta süngü gece ve ayışığı vardı 

Ordular....

Süngü gece

Ayışığı ise

Vatandı...

Yerde akan kandı...', 'Bir, iki, üç demeden atladılar Soğuk zemperi esmekteydi, sağ baştaki çavuş Gözlerini dikmiş haykırmakta ve ufukta sancılı bin ana doğurmakta...', ARRAY['Türk Edebiyatı','Şiir','Kenan Taşkın']::text[], 8.5, '{"poet":"Kenan Taşkın","poet_slug":"kenan-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sungu-gece-ay-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkindi', 'i-kindi-tuba-deniz-kuslar-en014', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'odanın en dibindeki ahşaba vuran güneş

bütün ikindi huzuru

ya da ipi çekmek boğazıma

aynı şey

öğledensonra haberlerinin

dar serin yıllanmış ve ıslak sokaklara taştığı

yılgınlık

oysa karanlığın

ya da nadasa bırakılan toprağın

gölge gibi uzayan hastalığı

hani diyorum

biri çıkıp söylemeli müzminleşen

çirkefin izbe yeraltı şarapçılarının

fahişelerin ya da mavi gökyüzünün sebebini

18:34  23.08.05', 'odanın en dibindeki ahşaba vuran güneş bütün ikindi huzuru ya da ipi çekmek boğazıma aynı şey öğledensonra haberlerinin dar serin yıllanmış ...', ARRAY['Türk Edebiyatı','Şiir','Tuba Deniz Kuşlar']::text[], 8.5, '{"poet":"Tuba Deniz Kuşlar","poet_slug":"tuba-deniz-kuslar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ikindi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Derde Çaremi Olur', 'bu-derde-caremi-olur-yusuf-onder-bahceci-tyzul', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bu dertlere salan,

Kendi gidip adı kalan,

Talan oldu ömrüm talan,

Söyle gülemi ağlayayım,

Yoksa garip bülbülemi.

Gitti gelmez güzel günler,

Gönül sevdiğini özler,

Bahçelerde solan güller,

Onu bana hatırlatır,

Gençliğimi hatırlatır.

Kendi gitti resmi kaldı,

O resimde şimdi soldu,

Saymadım ki kaç yıl oldu,

Saysam sanki ne olur,

Bu derde çaremi olur....', 'Beni bu dertlere salan, Kendi gidip adı kalan, Talan oldu ömrüm talan, Söyle gülemi ağlayayım, Yoksa garip bülbülemi. Gitti gelmez güzel gün...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-derde-caremi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olmaya Geldim', 'i-nsan-olmaya-geldim-suleyman-zaman-17oas', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğdum bir bedenden, dünyaya geldim

Bu cimi bedende, ulvi can buldum

Birleştim, göründüm, tüm birlik oldum

Mekanda bir insan olmaya geldim

Ayakla  yürüdüm, elimle tuttum

Gözlerimle gördüm, dilimle tattım

Anlam katmak için, çok sanat yaptım

Yaşamda bir insan olmaya geldim

Dokundum derimle, şeyi tanıdım

Ben doğmadan önce, nerde varıdım

Aşka yönlendiren, tinsel harıdım

Özümle bir insan, olmaya geldim

Beynimle kavradım, tüm nesneleri

Aklımla çözümler, oldum şeyleri

Deryaya bağladım, tüm nehirleri

Bütünde bir insan, olmaya geldim

Buldum tekerleği, yolu kısalttım

Demirle, çelikle, aletler yaptım

Nice buluşlarla,  Ay’a ulaştım

Teknikte  bir insan olmaya geldim

En küçük maddeyi,  çözümler oldum

Çözdüm genetiği,  şifremi buldum

Evrensel yasaya, bilimle vardım

Bilimde bir insan olmaya geldim

Evrende karşıtlık, ilkesi gördüm

Varolan her şeyde, kaosa erdim

Çatışkı içinde, çatışkı sezdim

Doğada bir insan olmaya geldim

İnsandım ağladım, zamanla güldüm

Bazen nefret ettim, bazen de sevdim

Çok gönül kazandım, çok gönül kırdım

Duyguda bir insan olmaya geldim

Bayramlar var ettim, barış sağlasın

Uçağı ürettim, hızlı yol alsın

Herkes sağlıcakla, gönençle kalsın

Kültürde bir insan olmaya geldim.

Zamanım yaşamda görür insanı

Gelip geçicidir, bu dünya hanı

Doymak bilmeyenler, akıttı kanı

Toplumda bir insan olmaya geldim

		07.01.2006', 'Doğdum bir bedenden, dünyaya geldim Bu cimi bedende, ulvi can buldum Birleştim, göründüm, tüm birlik oldum Mekanda bir insan olmaya geldim A...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/insan-olmaya-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ört Ü s t ü n ü', 'ort-u-s-t-u-n-u-birsen-ates-63tca', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her şiirimde

diyorum ki kendime

ölümü yazma! 

elimde değil dökülüyor

dudaklarımdan soğuk ismi.

üşüyor kalemim

eyy ölümden uzak kelimelerim

ört üstünü 

soğuk ölümlü dizelerimin...

her susku

ölüm soğukluğunda biraz

pençesinde

kıvrandırıyor yalnızlığın. 

nereden takıldın ki

yine dilime.

sensizliği tanımak istediğim

sevdiğimin gözlerinde

07.01.06', 'her şiirimde diyorum ki kendime ölümü yazma!  elimde değil dökülüyor dudaklarımdan soğuk ismi. üşüyor kalemim eyy ölümden uzak kelimelerim ö...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ort-u-s-t-u-n-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidim Tükendi Gücüm Kalmadı', 'umidim-tukendi-gucum-kalmadi-yusuf-onder-bahceci-8ozbx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiği halde sevdim demedi,

Güldüğü halde öldüm bilmedi,

Sevdasıyla yandım nasıl demedi,

Ümidim tükendi, gücüm kalmadı.

Böylesi bir sevda düşman başına,

Herhalde acı çekmem gider hoşuna,

Her şey dedi ama sevdim demedi,

Ümidim tükendi, gücüm kalmadı.

Sevdasıyla yanmışım ben görmüyor,

Onu seven kalbim derdi ile inliyor,

Kaç yıl oldu bilmem birgün gelmiyor,

Ümidim tükendi, gücüm kalmadı.

Varın gidin ona söyleyin, deyin,

O seni çok sevmiş, seviyor deyin,

Ayrılalı yıllar olmuş gülmüyor deyin,

Ümidim tükendi, gücüm kalmadı....', 'Sevdiği halde sevdim demedi, Güldüğü halde öldüm bilmedi, Sevdasıyla yandım nasıl demedi, Ümidim tükendi, gücüm kalmadı. Böylesi bir sevda d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umidim-tukendi-gucum-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın tam sevgin ölümsüz olsun', 'askin-tam-sevgin-olumsuz-olsun-ayhan-zenbilci-fjmvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaktaysa sevgilin gökyüzüne bak 

Görebilirsen orda sevdiğin... 

En parlak yıldız… İşte o özlediğin 

Şimdi yanımda olsa dediğin… 

Yüreğinin sesi 

Sahilde dalgaların hışırtısı olsun 

Semadaki parlak yıldız sevgilin olsun 

Bırakın azıcık hasret de olsun. 

Yanında sevgilin bilinmez kıymet 

Gidince kopar kızılca kıyamet 

Bırak sevgilin uzak ta olsun 

Aşkın tam sevgin ölümsüz olsun 

Başlarken aşklar sanki hiç bitmez 

Zaman yer bitirir bütün sevgiyi 

Aşk, aşk diye haykıran diller 

Birden dikenli tel oluverirler 

Uzakta sevgilin yanarsın 

Gelince yanına kaçacak yer ararsın 

Bırak sevgilin uzakta olsun 

Aşkın tam sevgin ölümsüz olsun', 'Uzaktaysa sevgilin gökyüzüne bak  Görebilirsen orda sevdiğin...  En parlak yıldız… İşte o özlediğin  Şimdi yanımda olsa dediğin…  Yüreğinin ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Zenbilci']::text[], 8.5, '{"poet":"Ayhan Zenbilci","poet_slug":"ayhan-zenbilci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-tam-sevgin-olumsuz-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Özlem, Adı Hasret', 'adi-ozlem-adi-hasret-ugur-kilic-h81w6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir duygu doğar benliğime,

Sen gelirsin aklıma,

Uyku girmez gözüme,

Bunun adı özlem,

Bunun adı hasret sevdiğim.

Yürürüm koca kentin caddelerinde,

Bir sıcaklık eksiktir ellerimde,

Bakamam sağa sola başım önümde,

Bunun adı özlem,

Bunun adı hasret sevdiğim.

Gözlerim yolda kaldı gel artık yeter,

Sensizlik gülüm ölümden beter,

Tat vermiyor gezdiğim yerler,

Bunun adı özlem,

Bunun adı hasret sevdiğim,

Yatağım soğuk uzanamamki,

Sana sarılmadan uyuyamamki,

Gecem bitmez inadına sanki,

Bunun adı özlem,

Bunun adı hasret sevdiğim.

Geldiğinde mutluluktan uçacağım,

Gönlümde huzuru bulacağım,

Bilsen sana nasıl sarılacağım,

Bunun adı özlem,

Bunun adı hasret,

Bunun adı sevgi birtanem.......', 'Bir duygu doğar benliğime, Sen gelirsin aklıma, Uyku girmez gözüme, Bunun adı özlem, Bunun adı hasret sevdiğim. Yürürüm koca kentin caddeler...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/adi-ozlem-adi-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuzdur İnsan Ülkemde', 'ucuzdur-i-nsan-ulkemde-suna-aras-hg46f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatı gözlerine sakladım, gittin

Üşüyen sokaklar geçti göğsümden

Ayırdın bir yanımı çok ince dilimlere

Bir tarafım sevda moruydu zaten.

Yasaksın

Yüreğim günaha geriniyor

Kara yaşa döküldüm, işaretlendim

Kaynak sular ateşlendi alnımın çatısına

Yüz derime adı yasak acılar bırakıldı

Azap tanrılarına kurban edildim.

Düşlerim korkutan giz

Avucuna sığmaz atışı yüreğimin

Silkinip atıyor gövdemi senden

Kürt düşü kadar yasağım

Dişlerini dil ucuma kitledin.

Gel ki gözlerin sürdürsün beni

Sıcaklığın yanım olsun sımsıcak

Kaçak yanlarıma yataklık etsin

Pahalı tutuyor kendini postum

Peşime düşenler hayıflanıyor

Ülkemiz de hayat ucuzladı ya.', 'Hayatı gözlerine sakladım, gittin Üşüyen sokaklar geçti göğsümden Ayırdın bir yanımı çok ince dilimlere Bir tarafım sevda moruydu zaten. Yas...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ucuzdur-insan-ulkemde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elinden geleni yap', 'elinden-geleni-yap-mikdat-bal-glaus', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elinden geleni yap  da gerisi

Allah’a kalmıştır kafanı yorma

Sana bir şey kalkıp derse birisi

Dinle ama buna kafanı yorma

Çözüm önermezse bir daha sorma

Herkeste ağız var konuşur olan

Kimse hesap etmez doğru, ya yalan

Yürüyen gazette, bedava ilan

Çoğu dedikodu üstüne varma

İki yüzlülere hiç bir şey sorma

Ona sorulmadan girer araya

Tuz ile biberi eker yaraya

Nerde kavga varsa koşar oraya

Böylesi yüzsüzün yanında durma

O alçağın teki ismini sorma

Bir de ikide bir kalkar naz eder

Her söze her lafa itiraz eder

Kendini unutur ele va’z eder

Görmedim hayatta böyle bir yarma

Sahtekardan asla fikrini sorma

Mikdat der bu tipler her yerde vardır

Hoş görüleri kıt kalpleri dardır

Dedem derdi bunlar aslen “himardır”

Onlar anlamaz ki kırbacı vurma

Salıver peşinden kafanı yorma', 'Elinden geleni yap  da gerisi Allah’a kalmıştır kafanı yorma Sana bir şey kalkıp derse birisi Dinle ama buna kafanı yorma Çözüm önermezse bi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/elinden-geleni-yap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-sadullah-seyit-subhi-nebiogullari-uolo6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessizce ağlamak erkeklerin işidir

Sen niye ağlarsın be güzel

Ağrıların sızılarınmı var

Yanık yüreciğin közmü oldu için

Ağla güzel ağla

Yanmışlara yitiklere

Erkeklerede ağla terk edilmişlere

Ama sessizce ağla farketmesinler

Yararlanmasınlar zayıflığından.

                                 13 07 2002', 'Sessizce ağlamak erkeklerin işidir Sen niye ağlarsın be güzel Ağrıların sızılarınmı var Yanık yüreciğin közmü oldu için Ağla güzel ağla Yanm...', ARRAY['Türk Edebiyatı','Şiir','Sadullah Seyit Subhi Nebioğulları']::text[], 8.5, '{"poet":"Sadullah Seyit Subhi Nebioğulları","poet_slug":"sadullah-seyit-subhi-nebiogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ogut-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Olmalı', 'acik-olmali-kamil-at-kqcee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açıklar gizli olanları sevmez biline

Gün gelir, olanları alacak eline

Herkes sarılacaktır artan külüne

Gizlice yazılarımda saklanmam.

Herşey sonunda yerini bulacak

Şimdi boşa ötenler kayıp olacak

Tek şeydir, insanlığımız kalacak

Gizli yazıp halklardan aklanmam.

Çok önemli yazıda çiçek olmak

Ebedi kokusu dünyada kalmak

Okunma sonrasında neşe almak

Yazımda boş yere koklanmam.

Gördüğünü tüm halka bir demeli

Engeller çok umut kesmemeli

Kamil At, sonsuz rotasını izlemeli

Yoksa akıla sonsuz eklenmem...', 'Açıklar gizli olanları sevmez biline Gün gelir, olanları alacak eline Herkes sarılacaktır artan külüne Gizlice yazılarımda saklanmam. Herşey...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acik-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirin Olmayan Çocuk', 'sirin-olmayan-cocuk-omer-yildiz-jp5vk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşları aynı,

Ağlaması aynı, 

Gülmesi aynı… 

Aynı,

Bütün çocuklar aynı...

Sevgiyi; 

Kelimeler icat edilmeden

Henüz daha konuşulmadan,

Ateş bulunmadan,

Taş,

Tekerlek olup yuvarlanmadan

Ana kucağında

Öğrenen 

Çocuk da,

Kucağımızdaki çocuk da aynı …

Aynı

Bütün çocuklar aynı....

Şirin olmayan 

Çocuk 

Şirin olmayan

Bir yavru  var mı? ...', 'Gözyaşları aynı, Ağlaması aynı,  Gülmesi aynı…  Aynı, Bütün çocuklar aynı... Sevgiyi;  Kelimeler icat edilmeden Henüz daha konuşulmadan, Ate...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sirin-olmayan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 19', 'd-siir-ve-sarki-sozleri-19-huseyin-avdic-xo580', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Garibim/(Acıklı)

''Bir garibim şu dünyada.''

Başım almış giderim ben,

Bağlanacak kimsem yoktur,

Bir başına kalmışım ben.

*   *   *

Ne kadar sürer bu gidiş? 

Bilir bilmez giderim ben.

Rabbim imdadıma yetiş! 

Pek çaresiz kalmışım ben.

*   *   *

Ne anam kaldı ne babam.

Ne çocuğum ne akrabam.

Rabbim bana sabırlar ver,

Sen''sin benim tek dayancım.

Of, of! 

Not 1: İlk mısra, ismini bilmediğim

       bir şaire aittir.

Not 2: T.Sanat ve Halk Müziği karışımı 

       olarak bestelendi.

Berlin, Nisan 2005.', 'Bir Garibim/(Acıklı) ''Bir garibim şu dünyada.'' Başım almış giderim ben, Bağlanacak kimsem yoktur, Bir başına kalmışım ben. *   *   * Ne kada...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-sahin-kars-q4fo8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ona çok da, bana az geldi niye,

Hem istenir hem de olur hediye? 

Bitirirler seni hep yiye yiye.

Derler Almanya''dan hediye geldi,

hediyesiz hala ne diye geldi? 

Bütün emeğini versen az gelir,

Arkan sıra türlü türlü söz gelir.

Mevsim döner bahar geçer yaz gelir,

Derler Almanya''dan hediye geldi,

Hediyesiz dayı ne diye geldi? 

Dünya tamahına kanabilirsen,

Bunca yükseklerden inebilirsen.

Hasta, yarım belki dönebilirsen,

Derler Almaya''dan hediye geldi,

Hediyesiz emmi ne diye geldi? 

Babam  borçlu anam hastadır derler.

Acındırır, acındırır soyarlar.

Birde seni şey yerine koyarlar.

Derler Almaya''dan hediye geldi.

Hediyesiz teyze ne diye geldi? 

Duyup gücenmesin yârin almancı,

Tatlı bir tebessüm kârın almancı,

Sayılsa hatırın bari almancı,

Derler Almaya''dan hediye geldi.

Hediyesi yok da ne diye geldi? 

Şahin senin seyirine çıkarlar,

Elin boşsa türlü kulak takarlar,

Açar belki tabutuna bakarlar,

Derler Almaya''dan hediye geldi.

Hediyesi yoksa ne diye geldi?', 'Ona çok da, bana az geldi niye, Hem istenir hem de olur hediye?  Bitirirler seni hep yiye yiye. Derler Almanya''dan hediye geldi, hediyesiz h...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hediye-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 32 (''balık'')', 'lirik-32-balik-fevzi-cebe-ytsfw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazen...herşey çok zor

...sözcüklerin türeşimi olmasa

çıkış olmaz 

yanılsamalara bile

çıkış yok

saydam akvaryumdan

''balık'' derken 

farkında mıyız...

kendimizi tarif ettiğimizden

24.11.2004 - 23:12', 'bazen...herşey çok zor ...sözcüklerin türeşimi olmasa çıkış olmaz  yanılsamalara bile çıkış yok saydam akvaryumdan ''balık'' derken  farkında ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lirik-32-balik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne gördün? ? ? ? anlat.! ! ! ! !', 'ne-gordun-anlat-nazan-i-zmirli-r0kii', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geçmişin

yaşanmışlığına

imza   atan

parmaklarımı

kapattım

beni  bana

kısa  kesik  çizgilerle 

anlatan  yüzüme......

siyah beyaz fotoğraflar

sararmış

güz  yaprakları  gibi

savrulmuş,  yıpranmış

sonbahar  nemi

üzerlerinde...

bir avuç içi

kadar mı

küçülür 

bir  ömür,

yok  mu 

olur

tüm 

yaşananlar

indirdim

eski  ellerimi,

açtım  yorgun  gözlerimi

derin  bir  nefes  aldım

kalbimdeki  son  ışıkla

baktım; 

terkedilmiş 

hayat çizgilerime........

o da ne? ? ? ? ? 

uzun bir ömür.......

ak saçlı bir nine.........

oturuyor zirvelerde.........

üşüyen  yeni elleri...............

ak saçlı  bir...............................

dervişin..........................................

umut vadeden.....................................

sıcacık..............................ellerinde.....

09.12.2006-antalya', 'geçmişin yaşanmışlığına imza   atan parmaklarımı kapattım beni  bana kısa  kesik  çizgilerle  anlatan  yüzüme...... siyah beyaz fotoğraflar ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-gordun-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çürütme', 'curutme-asima-azra-uyoky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın tüm hukuku yanmak olsaydı

çakmaklar ateşe tapmaz mıydı? 

Yağmurun buluta tutkunluğunda

toprak kavrulmaktan bıkmaz mıydı? 

çürütmeler/1', 'Aşkın tüm hukuku yanmak olsaydı çakmaklar ateşe tapmaz mıydı?  Yağmurun buluta tutkunluğunda toprak kavrulmaktan bıkmaz mıydı?  çürütmeler/1...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/curutme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal/ansız sone', 'kal-ansiz-sone-atif-okan-1q3fk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her giden çokça kalabalık gittiğinden

kaygılı solgun bir kalmak mıhlar geriye

taş kesmiş firavun gibi gönlümün kızıl denizinde

kalan kalansız vakit kalan ziyade akşam

geçir günün ışık atlarını su unutkandır Musa''m

giden gitti dökülen yapraklarla bir-bir

kalan çıplak ağaçta bir dal/gın bakış

huysuz rüzgarlarla dövdü bağrını güm-güm

baharlar beklemekten yorgun düştüm

yorgun, daha ölemeyecek kadar yorgun

giden sevgililer nereden bilecekler? 

kalmak iç-içe geçmiş alevden bir merhaledir

ki başı sonuna mıhlı bu sonsuz yolun

menzili yanılarak geçilecektir

                                Atıf  OKAN', 'her giden çokça kalabalık gittiğinden kaygılı solgun bir kalmak mıhlar geriye taş kesmiş firavun gibi gönlümün kızıl denizinde kalan kalansı...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kal-ansiz-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pek çok arzuladım varayım dedim', 'pek-cok-arzuladim-varayim-dedim-asik-veli-2-egs16', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pek çok arzuladım varayım dedim                                                                 Varamadım gül yüzlü yar küstün mü?                

Haki payına yüzler süreyim dedim                        

Süremedim gül yüzlü yar küstün mü?                 

On beş yıl yaklaştı olmadı çare                            

Erenler terkim kılmadı zara                                  

Fazlı gibi kendi kendim hançere                           

Vuramadım gül yüzlü yar küstün mü?                  

Sıra ister Beytullah’m yolları                                 

Onun yolu zordur yokuş belleri                              

Al yanakta al kırmızı gülleri                                   

Deremedim gül yüzlü yar küstün mü?                    

Aşık oldum Ehl-i Beyt’in nuruna                             

Amasya’da yatan gerçek pirime                               

Elim bağlı belim bağlı darına                                   

Duramadım gül yüzlü yar küstün mü?                     

Eşiğine süremedim yüzleri

Gözüme tütüyordur ayak izleri

Dili şeker ezer şirin sözleri

Eremedim gül yüzlü yar küstün mü? 

VELİM eydir işim ah-ı zar idi                                  

Beni bu sevdaya salan yar idi                                    

Danışmaya çok müşkülüm var idi                             

Soramadım gül yüzlü yar küstün mü?', 'Pek çok arzuladım varayım dedim                                                                 Varamadım gül yüzlü yar küstün mü?          ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veli 2']::text[], 8.5, '{"poet":"Aşık Veli 2","poet_slug":"asik-veli-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pek-cok-arzuladim-varayim-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar 1', 'yollar-1-nevzat-ozkan-flczr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'otogarda,

anonslar arasında

bilmem bu kaçıncı gidiş

bu kaçıncı uğurlama.

yaş kemale erdi ama

yollar,

yolculuklar bitmedi daha.', 'otogarda, anonslar arasında bilmem bu kaçıncı gidiş bu kaçıncı uğurlama. yaş kemale erdi ama yollar, yolculuklar bitmedi daha....', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yollar-1-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehir Kurtulurken', 'bir-sehir-kurtulurken-memet-karabalik-e8axj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutsak ucundan bir şeylerin

Bir yerlere götürse bizi ırmaklar

Ben köprüdeyken Murat taşsa

Batsam uzun uzun serinliğine

Duymasam mehterin savaş çığlığını

O Geçe''den el etse barış

Bir ben olmasam gören

Bir alem şahitlik etse

Hep birden vurmasa çocuklar yere

Çocuklar asker asker büyümese

Vuruşa vuruşa kurtulur oysa

Seksendört yıl önce savaşmasa dedem

Tutsak ninem doğurmazdı babamı

Tutsak ucundan güzel şeylerin

Tutsak olmasak savaşlara

14 Nisan 2003*

* 14 Nisan (Ağrı''nın Tutak İlçesinin kurtuluş yıldönümü)', 'Tutsak ucundan bir şeylerin Bir yerlere götürse bizi ırmaklar Ben köprüdeyken Murat taşsa Batsam uzun uzun serinliğine Duymasam mehterin sav...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sehir-kurtulurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzeninde Yer Arıyorum', 'mahzeninde-yer-ariyorum-seyfettin-bilal-ozluk-uq3fz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnzivaya çekilmiş yüreğim

Şimdi rotasını mı kaybetti? 

Ne gittiğim limanı biliyor

Ne de demir alacağı gemiyi.

O yürekteki ne aşklara kimbilir neye gebe

Mahzeninde bana da yer açar mı? 

Yoksa yaydan çıkan ok gibi

Hedefe doğru emin adımlarla yol mu alıyor? 

Yoksa rüzgara kapılıp karavana mı olur

Bir denklem gibi çözülmez mi? 

Basit gelen bir yaşamda

Izdırapların içinden sıyrılıp huzur bulur mu? 

Bir kere ok yaydan çıktı

Rotam belli oldu doğru limandayım

Fırtına bile durdurmaz beni

Sen mahzeninde bana yer açtığın sürece...', 'İnzivaya çekilmiş yüreğim Şimdi rotasını mı kaybetti?  Ne gittiğim limanı biliyor Ne de demir alacağı gemiyi. O yürekteki ne aşklara kimbili...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahzeninde-yer-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Yalanlar', 'sen-ve-yalanlar-i-lhan-altin-qpgkl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonunda vazgeçtin benden…

Ben yalanlarınla bana bıraktığın yıkıntılarda,

Sen başka diyarda, başkalarının rüyalarında,

Benim bir figüran bile olmayı beceremediğim, 

Yapamadığım yalan dünyalarda yaşıyorken

Hani bana sorardınya

	“Beni nekadar çok seviyorsun” diye

Sonunda anlamıştık, biz birbirimizi denizler kadar çok seviyorduk…

Bak sevgilim denizlerde buharlaşıyormuş içinde binlerce umutlarla! 

Yoksa ne işin var onun kollarında, ve o dudaklarındaki iz de ne…

Şimdi anladın yüreğimin nekadar büyük olduğunu,

Ayaklar altına alsanda yaşayacağını ve direneceğini…

Beni sana getiren yollar da yalnız değilmi? 

Sevdaya az kala bir çay tadında değilmi hayat? 

Hasret getiren, beni senden götüren yollarda,

Akıp giden zaman değilmi yaşamak? 

Belki o yıldızdı beni sana getiren,

Karanlığı aydınlatırcasına sıcak, inatçı

Sonu yine karanlık olsada

	“Bakın nasıl aydınlattım” 

		diye gülümseyen edasıyla yüreğime saplanan ateş topu,

Herkez ikide bir “sıcak suyumu tez getirin” diyen solistin,

Söylemeye çalıştığı parçaları dinleyip,

		Espirilere anlamsız gülücükler savururken…

Senin gözlerinde ben vardım, birde sessizlik,

Bişeyler anlatırken sen, ben sadece seni izliyordum,

					Sana aşık olmuştum…

Oysa ne güzeldi Cunda sokaklarında kolkola, sımsıcak

Senle köprüler yapmak uzak diyarlara,

		Ve el ele atlamak köprülerden ne güzeldi sevgilim…

Seni yosunlardan kurtarmak, kahramanın olmak çok güzeldi.

Kimseler çıkaramazdı o anahtarı 

Eğer kardeşim olmasaydı denizden

Kalbimin anahtarınıda sen, 

		Şimdi daha derinlere atsanda…

Hani tellerin arkasına hapsedilmiş, 

Bence sevimli, aslında pekte sevimli görünmeyen,

 			O kocaman keçi bile imreniyordu bize,

						Nasılda eğleniyorduk…

Yüreğime seni çekerken ben, seni severken delice,

Ne güzeldi Cunda Adası, 

Yüreğimin sarp kayalıklarında 

		Sevdaya yürümek yalın ayak…

Biz ne köprülerden atlamıştık,

		Kimsenin atlamaya cesaret edemeyeceği…

Burda ay hep dolunay, akşamları bira ve üç dört leblebi,

Sıcacık hatıralar aklımda…

Hani  kolayca tutatbildiğim sweetinin yakası,

Bir öpücük, içimi ısıtan, yüreğimi yakan,

“Ölümlerden ölüm beğen oğlum” dedirten kendi kendime…

						O ıslak dudakların

Gece, kapanan ışıklar, düşünen, uykusuz ben

Üstümdeki parfüm kokun, rüyalarıma gelmeye başlayan sen,

Korkuyordum çok korkuyordum…

Ama sen korkma sevgilim kimse ateşlere atmayacak seni,

Bıraktığım gibi dönmesende bana,

Sözler tutulmasda, yalanlar seni öldürmez sevgilim…

Beni kendine saklamasanda, çok sevmesende, 

Ayaklarının altında ezilsede yüreğim,

Birbaşıma, günden güne yaşayan bir ölüye dönüşsemde,

Ayrılmış olsakta, beraber ölmesekte, herşey yalan olsada…

Benimle atlayamasamda daha yüksek köprülerden,

Seni kimse ateşlere atmaz, korkma! 

Çektiğim acıların hesabını kimseler sormaz senden…

Sıcak nefesini yüzümde hissediyorum geceleri,

Donuk, soğuk bakışların delip geçiyor içimi,

Sen elini uzatıyorsun, tutuyorum ve birden yok oluyorsun,

Her gece seni gördüğümde gideceğini biliyorum,

Rüyada olduğunu bilmek ne kötü, gideceğini bilmek

İnsan yinede avunuyor bilsede ayrılıkları,

Sonra buz gibi duvar, ve acımasız karanlık, sessizlik,sensizlik,

Sayamadığım gözyaşları terkedilmiş zamanlara akar gider

Yorgun bedenim, ebedi uykuya gün sayan yüreğim,

 sen ve yalanlar…', 'Sonunda vazgeçtin benden… Ben yalanlarınla bana bıraktığın yıkıntılarda, Sen başka diyarda, başkalarının rüyalarında, Benim bir figüran bile...', ARRAY['Türk Edebiyatı','Şiir','İlhan Altın']::text[], 8.5, '{"poet":"İlhan Altın","poet_slug":"i-lhan-altin","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/sen-ve-yalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin yeniden doğuşu', 'gunesin-yeniden-dogusu-bilal-bavli-mjn7y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyan sevdiğim, ben geldim! 

ne komşuları uyandırdım 

ne de kapıdaki saksıyı devirdim

gittiğim halden pek farksız değil

                                       şimdiki halim

hala biraz kararsız

hala biraz çaresizim.

Sen! düşlerini uçurtma yapıp

boşluğa bıraktığın vakit

ben güneşin kucağında seni izliyordum

Gülümsüyordun.

güneş gibiydin

ben seni böyle daha bir sevmiştim.

bir tebessümün bulutların dağılmasına yetiyordu

güneşi görmekti tek isteğin

ben güneşin ta içindeydim...

haydi sevdiğim! 

bir kez daha geç kalmayalım

ertelenecek hiç bir şey kalmadı

vakit dar, üstelik,

güneş batmak üzere! ...', 'Uyan sevdiğim, ben geldim!  ne komşuları uyandırdım  ne de kapıdaki saksıyı devirdim gittiğim halden pek farksız değil                      ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gunesin-yeniden-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekler Oldum', 'bekler-oldum-yavuz-dogan-2jqfi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Sen hiç bilmesen bile… -

Öyle çok kırıldım ki habersiz gidişine 

Döktüğün gözyaşını kan diye bekler oldum. 

Umudunu takarak yıldızların peşine 

Gördüğün düşü gerçek san diye bekler oldum. 

Tam karşına asarak siyah beyaz resmimi 

Düşmanın bil istedim gülümseyen cismimi. 

Ve bir Ocak gecesi vazgeçtiğin ismimi 

En son nefesin bilip an diye bekler oldum. 

Dumanında hapsolmuş alev almaz közdün ya 

Senden başka herkese kör eylenmiş gözdün ya 

Belki dönersin diye hep tuttuğum sözdün ya 

Sözüme başka yari can diye bekler oldum.

Karanfiller boynunu bükerken kucağında 

Baykuşlar yuva kursun evinde ocağında 

Ben buz tutup üşürken Ağustos sıcağında 

Sen Zemheri’de kavrul, yan diye bekler oldum. 

Omzunda taşıyorken yaşadığın günahı 

Bin kere tövbe etsen geri almam bir ahı 

Pişman olup karşımda diz çöktüğün sabahı 

Kararttığın geceme tan diye bekler oldum.', '- Sen hiç bilmesen bile… - Öyle çok kırıldım ki habersiz gidişine  Döktüğün gözyaşını kan diye bekler oldum.  Umudunu takarak yıldızların pe...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekler-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet Etmek Olmaz', 'sikayet-etmek-olmaz-memet-karabalik-25hi7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şikayet etmek olmaz

Baltaya sapını kendi vermiştir ağaç

Bir ülke hep birden ağıt yakarsa

Bil ki gece deprem olmuştur

Sabaha uyanmayan çocuklar vardır

Kirişler altında nice umut kalmıştır

Şikayet etmek olmaz

Kendi yaptığı temele gömülmüştür birileri

Enkazlardan ağıtlar yükselirken

Halaya duran binler vardır

Çağlayan sallanmamıştır

Bingöl ıraktır ya göze

Korteş kavgası vardır sol yanda

1 Mayıs 2003 (Bingöl Depremi)', 'Şikayet etmek olmaz Baltaya sapını kendi vermiştir ağaç Bir ülke hep birden ağıt yakarsa Bil ki gece deprem olmuştur Sabaha uyanmayan çocukl...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sikayet-etmek-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklın Yolu', 'aklin-yolu-memet-karabalik-dyezw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aklın yolu birden çok

su yolunu buldu mu gider

sevdiysen

gecenin ve günün amansızlığında

çocuklar kadar şensindir', 'aklın yolu birden çok su yolunu buldu mu gider sevdiysen gecenin ve günün amansızlığında çocuklar kadar şensindir...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aklin-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini Aç', 'ellerini-ac-memet-karabalik-f3awr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ellerini aç kabaran göğe

gemiler demir almadan yetiş

çıkar sevdiklerini içinden

yüreğine hapset

geri dönemeyeceğini bilsen de

vatanın uğrunda öl

anan kurtulsun diye

azatlık dilenmesin diye baban

sen kavuşamasan da

senden sonrakiler kavuşsun yarin gülüşüne

ellerini aç

çocuklar aşkına', 'ellerini aç kabaran göğe gemiler demir almadan yetiş çıkar sevdiklerini içinden yüreğine hapset geri dönemeyeceğini bilsen de vatanın uğrund...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellerini-ac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldum sanma', 'vuruldum-sanma-ali-riza-unal-z6dyw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sessizce gidişe,darıldım sanma,

senden başkaşına,sarıldım sanma,

öldürürse beni derdi gam öldürür,

hançere kurşuna.vuruldum sanma,

şevkimdir sevdan, yoruldum sanma,

Aklı divaneyim, arıldım sanma,

Söndürüse ateşi,nurun söndürür,

Çehrene nazına,vuruldum sanma.', 'sessizce gidişe,darıldım sanma, senden başkaşına,sarıldım sanma, öldürürse beni derdi gam öldürür, hançere kurşuna.vuruldum sanma, şevkimdir...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vuruldum-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dostum Benim (129)', 'ey-dostum-benim-129-i-brahim-arslan-srdqb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey dostum benim,özüne yabancı

Gittiğim yolun sonu yok benim,

Çıkılmaz denilen tepeleri çıktım

Gördüm tenekeden insanları...

Ve yaşayanları,yaşamayanları...

En güzel günleri başkalarına bıraktım..

Kalsın istedim

Hala olsun istedim...

Meşakkatli yolun yolcuları,

Yoruldum...

Her gün çileyle yoğruldum...

Soramadım kendime nereye diye? 

Biliyordum nereye gittiğimi

Bilmediğimi,

Öleceğim güne kadar yürüyüş bu,

Bazen yürümeden yol aldığım da oldu...

Gittiğim yolun sonu yok benim

Ey dostum benim,sözüne bile yabancı...

Ey dostum benim,gözüne bile yabancı..

Kul olamamanın utancını

Nasıl taşıdım bunca yıl

Üzerimde kefenden başka giysi mi var

Nihayetinde ölüm yok mu? 

Yaşasan yüzyıl

Bilemedin binyıl,

Ey dostum benim...

                                 15.02.2005', 'Ey dostum benim,özüne yabancı Gittiğim yolun sonu yok benim, Çıkılmaz denilen tepeleri çıktım Gördüm tenekeden insanları... Ve yaşayanları,y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ey-dostum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* D e r y a l a r B e n i m *', 'd-e-r-y-a-l-a-r-b-e-n-i-m-i-brahim-dikmen-2-wiw3o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben

denizlerin

hırçın yelkenlisiyim

ne limanım var

sığınacak

nede

koyum var

demir atacak

Ben

denizlerin

özgür yelkenlisiyim

ne rıhtımım var

yaslanacak

nede

döşüm var

sıcağına yaslanacak

Ben

denizlerin 

efendisiyim

bütün mavilikler benim

uçsuz bucaksız

deryalar benim

Sen,kollarını

Sen,yüreğini

açmasanda

Sen

göğsünde yatırmasanda

denizler benim

ben denizlerin sevdalısıyım.

07/01/2006', 'Ben denizlerin hırçın yelkenlisiyim ne limanım var sığınacak nede koyum var demir atacak Ben denizlerin özgür yelkenlisiyim ne rıhtımım var ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/d-e-r-y-a-l-a-r-b-e-n-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emi', 'emi-sadik-softa-0i8nw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dizilir ahların hepsi bir aha,

Uykularım direk olur sabaha,

Vuslata erdir de beni bir daha,

Kollarından sakın bırakma emi.

Yüreğimi ezdi sanki biçecek,

Sessizce kalbime ektiğim çiçek,

Zanneder misin ki gönlüm geçecek,

Vallahi vazgeçmez unutma emi.

Kavuşmayı umuduma yükledim,

Zamanı durdurdum seni bekledim,

Derman kesildikçe hep emekledim,

Yolunu bekledim unutma emi,

Aramızda esen bahar yelinin,

Basar bamteline gönül telinin,

Beni alıp giden yürek selinin,

Engeli, bendisin unutma emi.

Çankırı-19.06.2004', 'Dizilir ahların hepsi bir aha, Uykularım direk olur sabaha, Vuslata erdir de beni bir daha, Kollarından sakın bırakma emi. Yüreğimi ezdi san...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/emi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten Kaybettim Aşkta (130)', 'zaten-kaybettim-askta-130-i-brahim-arslan-mtipw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'son defa gözlerimin içine bakta git...

yakta git yüreğimi,

bir enkaz gibi beni

bırakta git...

gözlerimin içinde

sana sitem yok mu? 

orada kendine

ve yüzsüzlüğüne,

bakta git...

git haydi

bir saniye daha 

durma buralarda..

arkana bakmadan,

aşktan kaçta git...

ben zaten hep

kaybettim aşkta

git...

sanma ağlarım

siyah saçlarına

siyah gözlerine

ben ağlarım sadece

sana yazdığım şiirlere

ve senin gibi

kalp-size gönül verdiğime...

son defa gözlerimin

içine bakta git

yakta git yüreğimi,

bir enkaz gibi beni

bırakta git...

gözlerimin içinde

sana sitem yok mu?

2006', 'son defa gözlerimin içine bakta git... yakta git yüreğimi, bir enkaz gibi beni bırakta git... gözlerimin içinde sana sitem yok mu?  orada ke...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zaten-kaybettim-askta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Mektup', 'yuce-mektup-mustafa-ulusoy-ofhjk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahvalimi yazıyorum sevdiğim,

Bir gelsen de görsen halim perişan,

Yürümekle bitmez yolum perişan,

Çiçeklerim açmaz gülüm perişan,

Baharların eski tadı olmuyor,

Sen olmazsan benim yüzüm gülmüyor.

Ahvalimi yazıyorum sevdiğim,

Görmeyeli yüreğime dert oldun,

Hasretinle hüzün keder gam doldum,

Yaprak gibi yel önünde savruldum,

Fırtınalar sensiz sükun bulmuyor,

Sen olmazsan benim yüzüm gülmüyor.

Ahvalimi yazıyorum sevdiğim,

Sensiz hayat acı elem işkence,

Seni söyler dilimdeki her hece,

Aklımdasın sen sevdiğim sen her gece,

Yürek seni mekanından silmiyor,

Sen olmazsan benim yüzüm gülmüyor.

Ahvalimi yazıyorum sevdiğim,

Sen gideli dünya bana dar oldu,

Yürek yandı alev alev nar oldu,

Bu hasretlik yüreğime yar oldu,

Yüreğimde senin yerin dolmuyor,

Sen olmazsan benim yüzüm gülmüyor.

Ahvalimi yazıyorum sevdiğim,

Derdi yazdım yazmak ile bitmedi,

Anlatmaya kalemlerim yetmedi,

Belki ağlar diye elim gitmedi,

Dertlerimi onca kağıt almıyor,

Sen olmazsan benim yüzüm gülmüyor.', 'Ahvalimi yazıyorum sevdiğim, Bir gelsen de görsen halim perişan, Yürümekle bitmez yolum perişan, Çiçeklerim açmaz gülüm perişan, Baharların ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ulusoy']::text[], 8.5, '{"poet":"Mustafa Ulusoy","poet_slug":"mustafa-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuce-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoldayken', 'yoldayken-mustafa-ulusoy-94bxz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir garip yolcuyum hasrete giden,

Hayalini aldım yanıma biraz,

Sensiz gurbet elde bilmem ki ne idem,

Hayalini aldım biraz yanıma.

Kendimi yollarda eğlerim belki,

Derdinden yüreği dağlarım belki,

Düşünüp sessizce ağlarım belki,

Hayalini aldım biraz yanıma.

Hasretin menzili hiç gelmez diye,

Bu garip dertlidir hiç gülmez diye,

Orada ne olur ne olmaz diye,

Hayalini aldım biraz yanıma.', 'Bir garip yolcuyum hasrete giden, Hayalini aldım yanıma biraz, Sensiz gurbet elde bilmem ki ne idem, Hayalini aldım biraz yanıma. Kendimi yo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ulusoy']::text[], 8.5, '{"poet":"Mustafa Ulusoy","poet_slug":"mustafa-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoldayken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsama 2', 'animsama-2-rahim-recep-akdora-59nrs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çok uzaklara gittim yine

eski bir aşkın kurumayan yarası kanadı

gençtim, korkusuz,

nice rüyalarım eşleşiyordu nice rüyalarla 

çaldın beni

o güzel bakışlarınla

gömdün kalbinin en derin köşesine

hırslıydın fırtına gibi

hiçbir engel, engel olamazdı isteklerine

dikilirdin hemen karşıma

aşk ışıkları dolduğunda gözlerine

bana geldiğinde ateş fışkırıyordu gözlerin yine

bir kuş gibi uçtun arabamın koltuğuna

“sür” dedin, “sür şu karşıki ormana”

deli bir rüzgardı eteklerini savuran 

ellerin rüzgara hiddetinden eteklerindeydi,

gözlerin gözlerimde

sırtımıza

buz gibi

kurşun gibi 

yağmur damlaları çarpıyordu ara da bir

Yürüyorduk orman içine

bizi gizleyecek kuytu bir yere

gözlerimizden özlem fışkırıyordu

utanıyordu deli rüzgar rüzgarlığından

ağaç yapraklarına çarpan yağmur 

tempo tutuyordu cesaretimize 

bastığımız yer çamur

aşk evimiz olmuştu koca meşenin altı

kurutuyordu yağmur ıslaklığını gözlerimizin ateşi

ateşimizden ateş çalıyordu rüzgar

susmuş bize bakıyordu 

meşenin alt dalında kuşlar

bize bakıyordu az ötede putlaşmış bir ceylan

bir boy yakınımızda bir tutam menekşe 

bükmüşlerdi boyunlarını utançlarından

rüzgara inat temposuna devam ediyordu yağmurla yapraklar

toprak döşeğimiz, yorganımızdı yaprakların yeşili

o yaşta deli yapıyor insanı yasak aşklar

anımsadıkça yüzüm kızarıyor şimdi

utanıyorum rüzgarlardan

utanıyorum yağan yağmurlardan

nerede ceylan görsem kaçırıyorum gözlerimi

ama asla güzelliğini unutamıyorum

asla bitiremiyorum sana olan sevgimi

[email protected]', 'çok uzaklara gittim yine eski bir aşkın kurumayan yarası kanadı gençtim, korkusuz, nice rüyalarım eşleşiyordu nice rüyalarla  çaldın beni o ...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/animsama-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen (131)', 'bazen-131-i-brahim-arslan-4h7zk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen kabus gördüğün gece olurum

Bazen dilindeki en son hece,bazen

Sen olurum sensizliğimde ve bazen

Kahrolurum seni hatırladım diye..

Bazen üzerinde yürüğün toprak

Bazen üzerine yağan yağmur,bazen

Yüzüm güler sana ve bazende kızarım

Kendime,seni unutamadım diye...

İlkbahar olurum bazen ve bazende

Kış kadar soğuk olurum,göç olurum

Senden uzaklara gitmek için,neden? 

Yinede beraberimde sen olursun...

Bazen soluğun kadar yakın olurum

Bazen deli eder beni yokluğun ve

Bazen de gözyaşı olursun,sen ve sen

Sonu gelmeyen tozlu yollar olursun...

Binkere ölürsün hayalimde bazen

Bazen gülüşün canlanır her yanımda,

Katil olurum... bazen ben vurulurum

İşte sen tetiği çeken el olursun...

Bazen yollar sana bağlanır ve bazen

Gözlerin gözlerimin içine bakar

Bazen veda ettiğin sahne canlanır

Bazen o son sözlerin içimi yakar,

İlkbahar gibi ihtiyaçsın sen bazen

Bazen de gerçek olmayan bir rüyasın...

Ey sevgili bıraktığın dağda kar var..

Artık buraya güneş batıdan doğar....', 'Bazen kabus gördüğün gece olurum Bazen dilindeki en son hece,bazen Sen olurum sensizliğimde ve bazen Kahrolurum seni hatırladım diye.. Bazen...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bazen-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gönüle Bir Damladır Öğretmen', 'her-gonule-bir-damladir-ogretmen-seyfet-bozcali-i18fy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilgi kaynağından bilgiler sunan,

Her gönüle bir damladır öğretmen.

Baba şefkatiyle nasihat veren,

Her gönüle bir damladır öğretmen...

Çorak kalmış zihinleri yeşerten,

Somurtkan yüzlerde umut belirten,

Bilmeyene hak,hukuku bildiren,

Her gönüle bir damladır öğretmen...

O küçücük fidanlara yön veren,

Bilgi sunan,kültür sunan,can veren,

Yaşamı boyunca taze kan veren,

Her gönüle bir damladır öğretmen...

Bulunduğu çevreye ışık saçan,

Cehalete karşı mertçe savaşan,

Haklıyı savunan,hak yolu seçen,

Her gönüle bir damladır öğretmen...

Küçücük kalplere sevgiyi koyan,

Bilgi kaynağını cömertçe sunan,

Tarihleri yazan,sorunlar çözen,

Her gönüle bir damladır öğretmen...

Vatan için nefer gibi çalışan,

Önüne çıkan tüm engeli aşan,

Bilimle uğraşan,bilgiyle taşan,

Her gönüle bir damladır öğretmen...', 'Bilgi kaynağından bilgiler sunan, Her gönüle bir damladır öğretmen. Baba şefkatiyle nasihat veren, Her gönüle bir damladır öğretmen... Çorak...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/her-gonule-bir-damladir-ogretmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirafname', 'i-tirafname-alev-polat-0fjsn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

Üç bilinmeyenli bir denklem bizimki; 

ne ben beni ifade edebilirim

ne sen sensin artık

ne de aşk diye bir şey var...

bitesi bir sigara dalı

yitesi bir duman tüm bunlar...

Bense; 

boşa çınlayan bir çan gibiyim

böyle aşksız, böyle habersiz...

Ben susmayı öğretirim yüreğime de

Bak, dinle beni...

İtirazım yok sensizliğe

ama

itiraf ediyorum yine de:

‘‘bir bar loşluğunda sev

güneş ayıplar beni’’   

II.

kaygandır senin tenin

niye ki kabuklu benim susuşlarım

dolduruyor küçük loş odaları

sözcüklerin, akışkan.

Konuşmasak

Sıkışmasak kelimelere...

ürküp kaçarsın bilirim

benzin döker, bakarsın

bilirim yaralı ceylan cemalin...

haklısın sen, konuşuyorum işte:

‘lütfen sigaranı yakıp gitme...’

III.

Yorgunum,

her sabah uyandım ömrümde.

Dargınım gündüzlere.

          ‘keşke biraz daha uyusam’

bak yine keşke dedim! 

Varsın olsun,

kızgınlığım 

inadına isyanım

buhar oldu 

uçtu...

‘Keşke’lerden yol yaparım 

şimdi kendime 

Ev yaparım, yer içerim.

Hem ben 

5 yaşın masumluğunda 

Hep aynı yokuşta düştüm

Hep aynı yeri kanadı dizimin...', 'I. Üç bilinmeyenli bir denklem bizimki;  ne ben beni ifade edebilirim ne sen sensin artık ne de aşk diye bir şey var... bitesi bir sigara da...', ARRAY['Türk Edebiyatı','Şiir','Alev Polat']::text[], 8.5, '{"poet":"Alev Polat","poet_slug":"alev-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/itirafname-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorsun (132)', 'diyorsun-132-i-brahim-arslan-234wj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dur diyorsun dur,dur da

uçurumun kenarına gelinceye kadar 

neredeydi senin o dur diyen sesin...

kur diyorsun kur,kurda

nerede bir yuva kuracak para

ve sonra istersen mutlu hayal kur...

nur diyorsun nur,nurda

nur topu gibi bu çocuk

nasıl doyar,nasıl büyür

para yoksa bizde azizim,

o çocukta hiç durur mu nur...

sur diyorsun sur,sur da

biliyoruz çok bizde  kusurda

bilmediğimiz o melek

ne zaman üfürür sur''a...

vur diyorsun vur, vurda

vurmakla tükense

al ötekini berikine vur...

2006', 'dur diyorsun dur,dur da uçurumun kenarına gelinceye kadar  neredeydi senin o dur diyen sesin... kur diyorsun kur,kurda nerede bir yuva kurac...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/diyorsun-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-alev-polat-fmb0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirler yazıyorum sana

İçinden gani gani sen fışkıran cümleler kuruyorum 

eriyor ya sesler arasında Sesim 

kısılıyorum ya

Ondan yazıyorum sana

Yüreğimi çıkarıp göğsümde durduğu yerden

Yapıştırıyorum imza yerine

Erimesin artık sesim diye', 'Şiirler yazıyorum sana İçinden gani gani sen fışkıran cümleler kuruyorum  eriyor ya sesler arasında Sesim  kısılıyorum ya Ondan yazıyorum sa...', ARRAY['Türk Edebiyatı','Şiir','Alev Polat']::text[], 8.5, '{"poet":"Alev Polat","poet_slug":"alev-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ses-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Bir Boşluktan Sana Bakmak', 'sonsuz-bir-bosluktan-sana-bakmak-omer-i-skenderoglu-bca61', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonsuz bir boşluktan sana bakmak

Düşerken aşağılara seni seyretmek

Sen olmak, seni özlemek, 

Yalnızlığa ihanet adını her dem bulutlarda aramak

Sen yokken bile isyanlarda sessizlikte ve karanlıkta 

Sana ait bir düşünce ile uyanıp, 

Uzaktaki kıvılcımı seyretmek.

Pervane böcekleri gibi gitmek içine doğru

Yani ateşe, yanacağını bile bile. 

Diyorum ya işte seni sevmek 

Sensizkende senle olabilmek.', 'Sonsuz bir boşluktan sana bakmak Düşerken aşağılara seni seyretmek Sen olmak, seni özlemek,  Yalnızlığa ihanet adını her dem bulutlarda aram...', ARRAY['Türk Edebiyatı','Şiir','Ömer İskenderoğlu']::text[], 8.5, '{"poet":"Ömer İskenderoğlu","poet_slug":"omer-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonsuz-bir-bosluktan-sana-bakmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor işler', 'zor-isler-baki-sulopasa-xudjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çölde fırtına; 

Rüzgarın dansı kumlarla,

zor işler.

Turuncu kelebeğin,

cilveli raksı aşkıyla; 

Olağan işler.

Ya insanın aşkı, insanla...

Yasakla, dayakla! 

Zor işler, zor valla!', 'Çölde fırtına;  Rüzgarın dansı kumlarla, zor işler. Turuncu kelebeğin, cilveli raksı aşkıyla;  Olağan işler. Ya insanın aşkı, insanla... Yas...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zor-isler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykudayım Sanki', 'uykudayim-sanki-alev-polat-nqhj8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykudayım sanki:

Issız bir adaya düşmüşüm ve etrafta

Bedenler varmış

bakınca parlayan

Dokununca dağılan.

Serapmış meğer bu bedenler 

Issızmış ada, derinmiş çığırtkanmış sessizlik

Bir ağaç bulmuşum çekmişim dizlerimi karnıma

Oturmuşum

Ama zaman bir türlü geçmek bilmiyormuş

Sırıtkanmış her saniyesinin siması

Oysa bitmeliymiş bu ömür

Bitememiş.', 'Uykudayım sanki: Issız bir adaya düşmüşüm ve etrafta Bedenler varmış bakınca parlayan Dokununca dağılan. Serapmış meğer bu bedenler  Issızmı...', ARRAY['Türk Edebiyatı','Şiir','Alev Polat']::text[], 8.5, '{"poet":"Alev Polat","poet_slug":"alev-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uykudayim-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkınız ne', 'farkiniz-ne-seyfet-bozcali-dxnrx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırk  yıllık eyriğe doğru diğenlerden farkınız ne.

Hakkı terk edip batıla,koşanlardan farkınız ne.

Yaşanan bu sonuçlardan,köşe başında açlardan,

Bir çok karanlık güçlerden,olanlardan farkınız ne.

Hani nerde tahtı tacı? Nerde darbeci,cuntacı? 

Yalandan bakıcı,falcı,olanlardan farkınız ne.

Gerçeyi görmez gözlerden,doğru olmayan sözlerden,

Utanmayan o yüzlerden,olanlardan farkınız ne.

Seyfet basma sırra kadem,Çoğalmış batılı tutan,

Manayı maddeye satan,melunlardan farkınız ne.', 'Kırk  yıllık eyriğe doğru diğenlerden farkınız ne. Hakkı terk edip batıla,koşanlardan farkınız ne. Yaşanan bu sonuçlardan,köşe başında açlar...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/farkiniz-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-haldun-uras-o5mvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüme giriyor gecenin ışıkları.

Kimine yol gösterir,

Kimine yarenlik ederler belli ki.

Sabah olur, gün ışıldarken,

Nereye kaybolurlar birer birer bilmem ki? 

Geceler uzundur, hele ki kış geceleri.

Birde düşüncelere dalarsan.

Gözlerinden uyku akar, uyuyamazsan...

Beyninde düşünceler kümelenip te,

Kovamazsan.

İşte o zaman gecelerle dost olmalısın.

Ta ki sabah olana,

Işıklar bir bir sönene kadar.

Geceler cilveli, gündüzler acımasız.

Bu bir aşk mıdır yoksa kavgamı? 

Kimbilir? ….

Bizi bekleyen başka şeyler var.

Yeni sevgiler, bir tutam iyilik,

Belki küçük bir çaba ile,

Düzeltilecek bir sürü yanlışlar var.

Kimileri için yeni bir gün,

Yeni umutlar demektir.

Gündüzler bazen kurtuluş,

Bazen de esarettir insana.

Gecelerle dost olmalı,

Gündüzlere ise söz geçirmelisin.

Hesabını gece yapmalı,

Borcunu gündüz ödemelisin.', 'Gözüme giriyor gecenin ışıkları. Kimine yol gösterir, Kimine yarenlik ederler belli ki. Sabah olur, gün ışıldarken, Nereye kaybolurlar birer...', ARRAY['Türk Edebiyatı','Şiir','Haldun Uras']::text[], 8.5, '{"poet":"Haldun Uras","poet_slug":"haldun-uras","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/geceler-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuştuğun Kadar Konuştun (133)', 'konustugun-kadar-konustun-133-i-brahim-arslan-91mp3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Konuş ve hiç susma,

Sonuna kadar hakkını iste

Alıncaya kadar kuruş kuruş...

Ve sonra sus,hiç konuşma...

İkiyse dört iste

Hatta ikiye sekiz al

İşte böyle böyle başlar

Cemiyetlerde kokuşma...

Pis pis sırıt

Alacağın kadarından fazlasını alınca

Elbet kalpten olur

Sonunda tokuşma...

Paralının yanında ol

Yolun bu olsun

Parasızla dostluğu boz

Sadece hayatla bozuşma

Başını önüne eğ şimdi

Dünya hayatıda neymiş

Asıl öldükten sonra  var

Bir büyük duruşma...

Elin ayağın yeter

Burada ifade vermeye

Konuştuğun kadar dünyada

Konuştun.Artık hiç  konuşma...

                                          27.02.05', 'Konuş ve hiç susma, Sonuna kadar hakkını iste Alıncaya kadar kuruş kuruş... Ve sonra sus,hiç konuşma... İkiyse dört iste Hatta ikiye sekiz a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/konustugun-kadar-konustun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AlIp götürür seni benden', 'alip-goturur-seni-benden-kamuran-gunduzalp-zdb9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur tanesi okşarcasına akar gider tenimden 

dokunuşlarını yıkar seni benden götürürken 

yağmur sonrası bir ebemkuşağı doğar 

ben yeşili seçerim. 

mutluluk getirir derdi nenem yeşilin altından geçersen 

gelip geçen mutluluklarımın anası mıydı bilmem 

yeşiline sarılırken umutlarım 

açar ellerimi Tanrı''ya seni dilerim.. 

Ummadığın anda şimsekler çakar, 

kime isyanıdır bilmem gökyüzünün 

ama korkarım halà çocuksu tavırlarla 

sana sığınır gönlüm korunmak için 

işte o zaman bir yıldırım daha... 

Çiseleyen yağmur sonrası 

aşk şarkısı olup dökülürsün dudaklardan 

yavaş yavaş silinirken ismin buğulanan camlardan 

sımsıcacık duygulara bürünmüşken sıcaklığınla 

bir şimsek çakar aniden 

alır götürür seni benden 

çırılcıplak duygularım titrer sensizlikten... 

07/01/06 

Kàmuran GÜNDÜZALP', 'Yağmur tanesi okşarcasına akar gider tenimden  dokunuşlarını yıkar seni benden götürürken  yağmur sonrası bir ebemkuşağı doğar  ben yeşili s...', ARRAY['Türk Edebiyatı','Şiir','Kamuran Gündüzalp']::text[], 8.5, '{"poet":"Kamuran Gündüzalp","poet_slug":"kamuran-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alip-goturur-seni-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kangren Oldu Gidiyor', 'kangren-oldu-gidiyor-seyfet-bozcali-z9ess', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Repçiler,popçular türedi yutta,

Benlikler kangren oldu gidiyor.

Bir çok anlamsız kelime lugatta,

Sözümüz kangren oldu gidiyor.

Helalı bırakır harama bakar,

Akrep,yılan gibi zehirin döker.

Allah''tan korkmadan yuvalar yıkar,

Gözümüz kangren oldu gidiyor.

Saçlar kimyasal boyayla boyanmış,

Kedi gibi sivri tırnak uzatmış.

Dayak yemiş gibi yüzün morartmış,

Yüzümüz kangren oldu gidiyor.

Verem kanser derken eyidis,firengi,

Gün be  gün soluyor hastanın rengi.

Çağdaşlık uğruna kaybettik cengi,

Özümüz kangren oldu gidiyor...', 'Repçiler,popçular türedi yutta, Benlikler kangren oldu gidiyor. Bir çok anlamsız kelime lugatta, Sözümüz kangren oldu gidiyor. Helalı bırakı...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kangren-oldu-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deniz Kenarında', 'bir-deniz-kenarinda-hasan-can-dgwra', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir deniz kenarındaydım,

Durgundum, bakışlarım yorgun,

Beynimde düşünceler,

Gözlerimde mavi sular,

Kafamın üstünde uçuşan martılar vardı.

Bir deniz kenarında yalnızdım,

Kimsesiz bakıyordum mavi sulara,

Eğilip bir avuç su vurdum yüzüme,

Ruhum açıldı, gözlerimin buğusu silindi.

Akla zarar bir fırtına başladı birden,

Dalgalar delirdi aniden,

Sular bir yağmur gibi yüzüme vuruyordu,

Sonra fırtına yavaş yavaş duruldu.

Gökyüzünden kara bulutlar silindi,

Yeniden bir mavilik oluştu gözlerimde.

Bir deniz kenarında unutulmuştum,

Aşırıydı kederim kimsesizdim,

Uzaktı herkes, uzaktaydı,

Eş, dost olsada aramazdı.

Bir deniz kenarındaydım,

Bakarken mavi sulara ağlamışım,

Farkında bile olmadan,

Oturdum bir bankın üzerine,

Öylece devam etti kederim...', 'Bir deniz kenarındaydım, Durgundum, bakışlarım yorgun, Beynimde düşünceler, Gözlerimde mavi sular, Kafamın üstünde uçuşan martılar vardı. Bi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-deniz-kenarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dededen Öğütler…', 'dededen-ogutler-haldun-uras-xk662', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hoş geldin bebeğim.

Bize dünyayı verdin.

Yumuşacık teninle,

Masum gözlerinle,

Ufacık bedeninle,

Çok mutluyuz seninle.

Ne kadar da masumsun.

Masum ve savunmasız.

Ama hiç merak etme biz,

Sana herşeyi öğretiriz.

Hele bir ayağa kalk.

Kalk da bir etrafına bak.

Bak da gör nereye geldin.

Geldin de iyi halt ettin.

Önce kavgayı öğrenmelisin.

Bunun adı kendini savunmaktır.

Kaidesi bir vurana, iki vurmaktır.

Baktın ki ucunda cezası vardır.

Çaresi bir yalan uydurmaktır.

Yalan vicdanını rahatsız ederse,

Benimkisi beyaz yalandır de.

Unutma bu erkeklerin dünyası,

Ne olursa olsun öyle kalmalı.

Etrafa entel görünmek için,

Aman feministlerle iyi geçin.

Çevreciyim de, izlenimi iyidir.

Ama gereğini yapma zorlu iştir.

Herkes doğruyu söylerim der,

Der de işine geldiği yoldan gider.

İnsanlar önce sağlık derler.

Ama parayı çok severler.

Herkesin bir bedeli vardır,

Mühim olan onu bulmaktır.

Unutma paran olursa eğer

Çoğu sonunda sana baş eğer.

Bak baban beni dinledi,

Yükseldi de yükseldi.

Bilmiyorum ne oldu? 

Artık görünmez oldu.

Gözlerimiz yollarda,

Yüreklerimiz buruk.

Senelerdir bekliyoruz.

Yaşıyoruz yalnız ve huzursuz.

Ne gelen var ne giden.

Bu vefasızlık neden? 

Bir yanlışımız mı oldu? 

Olduysa nerede oldu? 

İşte sevgili çocuğum.

Bu sırrı çözmek sana kaldı.

Bu kadar ipucundan sonra.

Gerisi kolay olmalı.', 'Hoş geldin bebeğim. Bize dünyayı verdin. Yumuşacık teninle, Masum gözlerinle, Ufacık bedeninle, Çok mutluyuz seninle. Ne kadar da masumsun. ...', ARRAY['Türk Edebiyatı','Şiir','Haldun Uras']::text[], 8.5, '{"poet":"Haldun Uras","poet_slug":"haldun-uras","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/dededen-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Biçareler', 'bu-bicareler-seyfet-bozcali-exdf9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu fani dünyayı,ebedi sanır,

Şatafata mal,servete aldanır,

Günahta,sevapta hep yaya kalır,

Öteyi düşünmez bu biçareler...

Bir kaç ahmak birbiriğlr yarışır,

İçer,içer birbirine karışır,

Kadınları kucaklarda dolaşır,

Ar,haya ne bilmez bu biçareler...

Sosyetelik için başa güreşir,

Çağdaşlık der atlet,kilot dolaşır,

İnsanlara zülmetmekle uğraşır,

Günah,sevap bilmez bu biçareler...

Nefsani istekler ön pilandadır,

Onlar için yaşam bu dünyadadır,

Tövbe,istiğfarı son nefestedir,

Ahreti düşünmez bu biçareler...

Daracık kabrine konduğu zaman,

Nasıl geldiğini bilmez dünyadan,

Kabir azabını tattığı zaman,

Pişmanlık duyarlar bu biçareler...

Seyfet der ot gibi yaşayıp ölen,

Dünya hayatınıebedi sanan,

Şeytanı laneye kanıp aldanan,

Zavallı sürüsü bu biçareler...', 'Bu fani dünyayı,ebedi sanır, Şatafata mal,servete aldanır, Günahta,sevapta hep yaya kalır, Öteyi düşünmez bu biçareler... Bir kaç ahmak birb...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-bicareler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya (134)', 'dunya-134-i-brahim-arslan-xct4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya yalan dünya

Dünya hain dünya,

Bugün üzerinde öldüm

Dün üzerinde geziyordum ya...

İyilere fani dünya

Kötülere baki dünya

Bugün gerçekleri gördüm

Dün bulanık  görüyordum ya...

Dünya ağlatan dünya

Dünya karaları bağlatan dünya 

Bugün altında inledim

Dün üstünde gülüyordum ya,

Zalimlere mesken dünya

Sevenlere mezar dünya

Bugün son kez nefes aldım,

Dün yaşıyordum ya..

Dünya ferahlatan dünya

Dünya korkutan dünya

Dün bana mekandın

Bugün mezarsın ya,

Dün sevdalındım

Bugün belalımsın ya...', 'Dünya yalan dünya Dünya hain dünya, Bugün üzerinde öldüm Dün üzerinde geziyordum ya... İyilere fani dünya Kötülere baki dünya Bugün gerçekle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dunya-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Biraz..', 'biraz-osman-kilic-kvt8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel hadi yürüyelim dağlarımda şöyle bir

Şöyle bir salınalım eteğinde doğamın

Bir yıldızı titretelim bağrımızda gel hadi

Günün gözü göremeyiz,duyamayız da belki

Belki dilek tutamayız güneşler sönsün için

Dağılalım yaylalarda yalınayak gel hadi

Gel biraz yürüyelim...

Gel hadi ağlaşalım kara bahtımız için

Akalım ovalara kara bulutlar gibi

Bir sönüp bir çakalım,bir coşalım bir durup

Gizli destanını dinleyelim gözyaşlarının

Kaçarak insanlardan kara kediler gibi

Fırlayalım bir anda efsunundan hayatın

Gel biraz ağlaşalım...

Gel hadi savuşalım yasak vakit buradan

Mayınları patlatarak sınırında cinnetin

Kol bacak uçuşurken havada tepetaklak

Salyamızda boğalım utangaç yanımızı

Kanımızın sıcağını dindirsin bu infilak

Kanımızın sıcağına konduralım bu anı

Gel biraz sevişelim...

                             02.05', 'Gel hadi yürüyelim dağlarımda şöyle bir Şöyle bir salınalım eteğinde doğamın Bir yıldızı titretelim bağrımızda gel hadi Günün gözü göremeyiz...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/biraz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlara Kaldı mı Bizede Kalsın', 'onlara-kaldi-mi-bizede-kalsin-seyfet-bozcali-ri1ux', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya malı için herkes yarışta,

Toprak için birçok ülke savaşta,

Deden,atan şehit düştü genç yaşta,

Onlara kaldımı bizede kalsın... 

Çok devlet kuruldu,çoğu yok oldu,

Zülüm eden fravunlar çok oldu,

O büyük servetle karun yok oldu,

Onlara kaldımı bizede kalsın...

Şatafatlı hayat söndü yok oldu,

Şaddal''a bir sinek musallat oldu,

Kafaya furulan tokmakla öldü,

Onlara kaldımı bizede kalsın...

Nice Padişahlar,krallar göçtü,

Kimi sevgi saçtı,kimi kan içti,

Allah''ın sevgili kulları göçtü,

Onlara kaldı mı bizede kalsın...

İki Cihan O''nun için var oldu,

Cehalet dönemi Onla son buldu,

Bize rehberimiz Kur-an''ı verdi,

Resül''e kaldı mı bizede kalsın...

Bin yıl yaşamıştı Hazreti Adem,

Nerede adelet sağlayan deden,

Ebubekir,Ömer,Ali ve Osman,

Onlara kaldı mı bizede kalsın...', 'Dünya malı için herkes yarışta, Toprak için birçok ülke savaşta, Deden,atan şehit düştü genç yaşta, Onlara kaldımı bizede kalsın...  Çok dev...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/onlara-kaldi-mi-bizede-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-seyfet-bozcali-u1r9q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ecel bizi bulur ise,

Bu gövdede can çaresiz.

Ruh gövdeyi terk ederse,

Damarlarda kan çaresiz...

Helal,haram bilmeğenin,

Namazını kılmayanın,

Hak yolunda gitmeğenin,

Göysünde iman çaresiz...

İnsan boşa koşmuş ise,

Ömrü boşa geçmiş ise,

İhtiyarlık gelmiş ise,

Dizlerde takat çaresiz...

Sevgi nedir bilmemişse,

Hakka gönül vermemişse,

İhlas ile ölmemişse,

Toprakta o can çaresiz...

Hayır,haseneti yoksa,

İnsanlara zulmü çoksa,

Amel defteri soldaysa,

Mahşerde o kul çaresiz...

Seyfet der gel al bu sözü,

Doğru yaşa sünnet,farzı,

Koymuşsa secdeye yüzü,

Kalmaz o mümin çaresiz...', 'Ecel bizi bulur ise, Bu gövdede can çaresiz. Ruh gövdeyi terk ederse, Damarlarda kan çaresiz... Helal,haram bilmeğenin, Namazını kılmayanın,...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/caresiz-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul'' da Rapsodi', 'i-stanbul-da-rapsodi-aylin-ayla-selcukoglu-rwha1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaygan bir esinti korkularimi senle ürkütür

Aglar karalar, elvedalar ve küsmeleri nefesin öldürür

Derken yari aralik gözlerimle,bilmedigim Istanbul’u senle süslerim

Açlik çeken gözlerimi Yeditepe’den kaçirip Kanlica’ya gizlerim

Islak persembelerden kalanlar,Istanbul’un koynunda süzülür

Masrapalar mutluluktan tokusurken bensizlikten Istanbul büzülür

Eskiden kalma müvezziler yitmis ki ulasmaz rehin sözlerim

Kalin siltelere dolali sonbahar sarhosluklari,soygun yeri gözlerim

Uskumrunun çigliklari âfâkin yankisini söndürür

Bogaziçi köprüsünden baktigim ziynet mavilik:basimi döndürür

Yuvarlanir uzun yolculuklarda yoksulluga terk edilmis ellerim

Yeminler sandallara dizilir; yaninda yasmagi yitmis, kirilmis testilerim

Tövbeler pencerelerden sabah saatlerinde Istanbul’a bürünür

Saçaklari tüketmeden süregiden umutlar yarinlara sürünür

Belenir nasirli yürekler pembeye,sebep: sirmalardan parlak hayallerim

Sürükler hiçlerimi heplere; Istanbul tokalasirken benle,diner zelzelelerim…

22.05.2005 Pazar 00.46-00.57', 'Kaygan bir esinti korkularimi senle ürkütür Aglar karalar, elvedalar ve küsmeleri nefesin öldürür Derken yari aralik gözlerimle,bilmedigim I...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-da-rapsodi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satırlarının Hatırına', 'satirlarinin-hatirina-aylin-ayla-selcukoglu-yig1p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benden kaçarsın, kendinedir yolculuğun

Toplanıp gelişim olur bu hal kendime

Göz yordamıyla dokunamadığım için sana,yoksun

İş yüreğime kalır; konuşur da güler de senimle senle

Bi çay içerim yanında tütün yok,ocak taşı sözler vurgun

Hamlamışım,yabancılaşmışım istemeden bedenime

Okuduğum her satırın hatırına,ideme kazınmışsın,sonsuzsun

İkrahım yok lâkin,ne senime ne de benime...

17.08.2005    11.08', 'Sen benden kaçarsın, kendinedir yolculuğun Toplanıp gelişim olur bu hal kendime Göz yordamıyla dokunamadığım için sana,yoksun İş yüreğime ka...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/satirlarinin-hatirina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Anarşik Hissiyat...', 'anarsik-hissiyat-osman-kilic-1b7tv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aferin sana çocuk söz dinliyorsun

Seni bana bakmıyorken yakaladım

Teşekkürler sana çocuk...

Güzel duramaz senden en renkli çiçek bile

Bu karanlık bu ıslak kaldırımın dibinde

Gelip gözlerine yakından baksam

Okşasam saçlarını

Tutsak bir kuşa dönüşüverecek yüzün biliyorum

Şimdi yapamam bunu üzgünüm

Fakat randevun tamam ilk güneşimin çentiğinde

Sen burada bekle

.......................ben gitmeliyim

Yitmeliyim bu kalabalığın sakinliğinde..

Ben kalabalığı izliyorum

Kalabalık beni izliyor mu ki? 

Bana mı bakıyor şu kocakarı? 

Şaşkınlığını söküp alarak yüzünden kaçıyorum

Omuzumla sarsarak bir habis ihtiyarı

Binbir küfür peşimde bir işhanının

..................................................kapısını açıyorum

Işıklı mağazaların göz alan döşemeleri

İstemezler adımımın köy kokan balçığını

Bir bakışta anlıyorum...

Tüm utangaçlığım mesaneme baskıda şimdi

Tuvalet! Tuvalet! Neredesin? 

Üç kere susam dedim mi bırak

Kollarımı çörekotunda tut

Elma-armut? 

Yok yok şu tarafta olacaktın

Az biraz su gerek bana-bir garip umut

Bir avuç sudan belki kaçıverecek

Ruhumun kötü kişisi umut kemirgeni; 

O acımasız haydut...

Ah şu aynanın cinsel organı olan surat

Dölleyemez kederimi akıttığın çirkinlik

Umudum bitene dek

..............................alaycı kalabalığında! ! 

Ah içinde kadın-erkek

................................herkesin orospu olduğu ayna

En hiddetli yüzünde bir o kadar sakinlik

Var diyerek

...............severek beğenerek

Sürünerek sırında koynuna varacağım

Ey dışımda yaşlılıktan eğilip bükülerek

Efkarımdan korlanıp yüzüme öksürerek

Dönenip duran dünya

Biliyorum hoşuna gitmediğimi

Lakin katlanacaksın yine bir süre buna

Dökülmesin diye erkenden,ortalığa sırların

Sürüneceğim var daha...

Hey tarihçi! ! Gel biraz daha küfür doldurayım hokkana

Biraz daha acı

Biraz daha keder

Sonra benim tarihimi yazarsın

Tarihçi! Al şunları da ve yıkıl:

İbrişim kelle ve pişmiş

Genç Osman karakit ve michael...

Hey! ! Düşlerime saldıran keçi ayaklı şeytan! 

Çek elini yoksa polis çağırırım! ! ! 

              08.05', 'Aferin sana çocuk söz dinliyorsun Seni bana bakmıyorken yakaladım Teşekkürler sana çocuk... Güzel duramaz senden en renkli çiçek bile Bu kar...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/anarsik-hissiyat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük bi kız', 'kucuk-bi-kiz-demet-demirel-broh8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elini yüzüne dayamıştın o eski resimde

Sırtında kırmızı hırkan 

Kimbilir hangi uzak hayallerin 

gerçekleşebilirliğini tartışıyordun yüreğinde 

gözlerinde gizemli 

yüzünde sevimli ifadenle 

küçük bi kız çocuğuydun sen! 

söyle bana, 

ne zaman büyüttün yaşlarını? 

Sen kalbinin üstüne düştün 

yaramaz çocuklar gibi koşarken 

Yara bantları yapışmadı yarana 

kalbinin kanlı ıslaklığından 

Seni de mi kanattılar ben gibi 

eli sapanlı çocuklar 

Tekrar tekrar kopardılar mı 

kabuklarını yaralarının 

küçük bi kız çocuğuydun sen 

ne vakit büyüdün? 

Gözüne bulut mu kaçtı,ne var? 

Neden yağmur yağıyor yüzüne? 

Kimler bozdu bekaretini yüreğinin? 

Şimdi kimin yalnızlığını taşıyorsun zihninde? 

Gördün, tanıdın, öğrendin 

artık sen de biliyorsun 

acı sadece dil yakmıyor 

siyah-beyaz bir fotoğraftır hayat 

renkli renkli gülünmüyor 

sil artık gözyaşlarını 

küçük bi kız işte böyle büyüyor.', 'Elini yüzüne dayamıştın o eski resimde Sırtında kırmızı hırkan  Kimbilir hangi uzak hayallerin  gerçekleşebilirliğini tartışıyordun yüreğind...', ARRAY['Türk Edebiyatı','Şiir','Demet Demirel']::text[], 8.5, '{"poet":"Demet Demirel","poet_slug":"demet-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kucuk-bi-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noktala-ma!', 'noktala-ma-demet-demirel-ql3s7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şimdi,al kalemi eline

ve

dansa kaldır tüm kelimeleri

cümleler kur onlarla

beni anlatan

ki

okunabileyim 

kırmızı kalemle altını çiz

en beğendiğin cümlelerin

sakın ayırma onları öğelerine

ki

bölünmeyeyim

noktalı virgüller

bir demet gül oldu, bak

en kurulmadık cümleler

çeyizim - senin için

sen de bilinmeyen kelimelerle

bir duvak yap bana

anlamlarını iyi aç

ki

görünebileyim

''iki paragraf arası düğün mü olurmuş? ''

deme

hem,herkes hazır

tüm harfler davetli

sen de gel

ki

sevineyim

kaç vakittir suskun şiir

birer birer ayrılıyor harfler

aklımın düğün salonu''ndan

nicedir bekliyorum seni

gel

me

din

ki

güleyim

artık sessizce ilerliyorum

olur a, ararsan bir gün beni

yazdıklarının üzerinde yürümekteyim

cümle sonlarını bekliyorum

kendimi aşağı atmak için

İlk noktada duracağım

bağlaçlarla bağla cümleleri

ki

düşmeyeyim.', 'şimdi,al kalemi eline ve dansa kaldır tüm kelimeleri cümleler kur onlarla beni anlatan ki okunabileyim  kırmızı kalemle altını çiz en beğend...', ARRAY['Türk Edebiyatı','Şiir','Demet Demirel']::text[], 8.5, '{"poet":"Demet Demirel","poet_slug":"demet-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/noktala-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Guruldayan Mide Baladı', 'guruldayan-mide-baladi-mucahit-gulbas-1wla1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni düşlemek isterdim sevgilim

Kordon’un şahi karanlığında

Gerdeğe girmek seninle..

Ellerinden tutmak isterdim

Guruldayan mideme hediye.

OOLMASA DA ZARAR YOK

Gam,kasavet,dert..

Bütün bunlara ne hacet

Sen yanımda olduğunda

                Tüm dünya yalan..

Gerçekten de yalan be güzelim

Gözleri de elleri de mavi değil körfezin

Ama olsaydı şimdi bir sandviç salamlı

                  Immm…

Ne güzel geleceksin baldan tatlı

Ve şimdi diyeceksin işte biliyorum

Sevecek,koynuma gireceksin

Ekmek gibi doyuracaksın beni….

ETMEE…GİTT..

Vazgeç bu sevdadan

Gardaş olduyduk ya 

Gelme “bacım”

DAHA EN AZ  ÜÇ GÜN DAHA AÇIM.

Mücahit Gülbaş    1989/İzmir', 'Seni düşlemek isterdim sevgilim Kordon’un şahi karanlığında Gerdeğe girmek seninle.. Ellerinden tutmak isterdim Guruldayan mideme hediye. OO...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guruldayan-mide-baladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ney’dik Biz Aynı Dudakta ve Üflendik Ayrılığa …', 'ney-dik-biz-ayni-dudakta-ve-uflendik-ayriliga-muammer-celik-4k4im', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Verirlerse vesikamızı, 

vardığımızda  menzile,

şairden sayılıp okunacağız

dize dize, destansı şiirler bizim...

vesikamız; 

giydiğimiz kefenimizdir

menzilimiz;

geldiğimiz efendimizdir bizim...

mezuniyet; 

hesaptan sonrasıdır 

özgürlük; 

ölümden öte olandır bizim...

çektiğimiz çiledir aşkımız, 

çile dediğimiz dünyada’dır

çilemizin bir ucu yâr’dadır bizim...

sevgimiz cân’adır,

gelişten varış’a  yolda,

cân’ımız  cânân’dadır bizim....

BirDeli

07.01.2006', 'Verirlerse vesikamızı,  vardığımızda  menzile, şairden sayılıp okunacağız dize dize, destansı şiirler bizim... vesikamız;  giydiğimiz kefeni...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ney-dik-biz-ayni-dudakta-ve-uflendik-ayriliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Sekiz El Ateş Edilirken', 'kirk-sekiz-el-ates-edilirken-aylin-ayla-selcukoglu-qjlbj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerimdeki çocuk yüreğim

Titredi sebepsiz yokluğuna

Budandı,filizlenen en açık yeşillerim

Ardına düştüm derin pusuna

Yarı mor,yarı lacivert akar kanım

Ateş renginden dönerken

Katlediyor toy umudumu,”SEN” li hatıralarım

Can’ım boğazlanıp yine de solurken 

Lebinden şakıdığın baldan sözlerin

Hepsini birer birer süpürmekteyim

Hala bana ait,bendeki gözlerin

Lâkin onu da yanımda götürmekteyim

Serimde patlatılır her renk balonlarım

Kırk sekiz el ateş edilirken

Tek yokluğunla sökülür yamalarım

Şimdi elde ettiğim ben,”SEN” hiçliğe savrulurken.

22.04.2005 Cuma  17.04', 'Ellerimdeki çocuk yüreğim Titredi sebepsiz yokluğuna Budandı,filizlenen en açık yeşillerim Ardına düştüm derin pusuna Yarı mor,yarı lacivert...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirk-sekiz-el-ates-edilirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Yoluna Girmez', 'hakkin-yoluna-girmez-seyfet-bozcali-874cx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep gaflet içindedir,bunu almıyor akıl,

Ne kadar uyarsanda,Hakkın yoluna girmez.

Çektikleri zahmettir,işlediği günahtır,

Bunlar nasıl Ümmettir,Kur-an yoluna girmez...

Söyleneni anlamaz,ayet,hadis dinlemez,

Abdest,namazdan kaçar,islam yoluna girmez.

Müminle alay eder nefsini ihya eder,

Dünyayı baki sanar,hakkın yoluna girmez...

Şeytanı rehber etmiş,kötü yollarda yürür.

Ayrı lisan öğrenmiş halkın dilinden bilmez,

Uçurum eşiğinde,önünü düzlük sanır,

Hep hayeller peşinde, kabrin yolunu bilmez...

Çok konuşur övünür,kendini üstün görür,

Kibir O''na ne yaptı Şeytanın halin görmez.

Hadise kulak tıkar,Farzları yersiz bulur,

Hep hayvan gibi yaşar,Rabbin emrine girmez...

Seyfet der ki İslam''ın önemi bilinseydi,

İnsan kendi aklıyla ateş yoluna girmez.

Nimetini düşünür,bulurdu yaratanı,

Hep şükürle yaşayıp,şirkin yoluna girmez...', 'Hep gaflet içindedir,bunu almıyor akıl, Ne kadar uyarsanda,Hakkın yoluna girmez. Çektikleri zahmettir,işlediği günahtır, Bunlar nasıl Ümmett...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hakkin-yoluna-girmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Battığı Ufukta', 'umudun-battigi-ufukta-murat-bahadir-uyem8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umdun Battığı ufukta



Kaybolan yarınlar 

Yarım kalan sevdamız 

Kimin umrunda 

Umudun battığı ufuktayız 

Hasret dayanmış kapıya 

Biz hala masallardayız 

Aynalarda küsmüş bize 

Sanki kaybolmaktayız... 

Murat Bahadır', 'Umdun Battığı ufukta Kaybolan yarınlar  Yarım kalan sevdamız  Kimin umrunda  Umudun battığı ufuktayız  Hasret dayanmış kapıya  Biz hala masa...', ARRAY['Türk Edebiyatı','Şiir','Murat Bahadır']::text[], 8.5, '{"poet":"Murat Bahadır","poet_slug":"murat-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umudun-battigi-ufukta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Senden, Bir Benden', 'bir-senden-bir-benden-aylin-ayla-selcukoglu-dcuj0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen düşmeden gözlerimden

Ben gözlerimi kaybettim

Sen yağmadan yüreğime

Ben ayazımı eskittim

Sen kurmadan hayallerimi

Ben toplandım mazinden

Sen vermeden minik ellerimi

Ben vazgeçtim,en dönülmez “SEN”imden! 

22.04.2005  Cuma  15.17', 'Sen düşmeden gözlerimden Ben gözlerimi kaybettim Sen yağmadan yüreğime Ben ayazımı eskittim Sen kurmadan hayallerimi Ben toplandım mazinden ...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-senden-bir-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim,Nerdesin.', 'ozledim-nerdesin-yasemin-kurt-mh71u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava soğuk,içim üşüyor 

Nerdesin? 

Ocakta birkaç odun parçası,

Gökyüzünde ay ve yıldızlar.

Bürünmüşüm yırtılmış çarşafıma,

Aklım üşüyor.

Nerdesin? 

Bilmez misin eskidende karanlığı sevmezdim ben.

Bıraktığın karanlık bir ev.

Şimdi her köşe sensizlikle bezeli,

Aklım soruyor.

Nerdesin? 

Uzatsam gecenin koyu karanlığına ellerimi.

Boş kalacağını bilsemde çekmem geri.

Soğuk yatak,soğuk kalp,

Soruyorlar,

Nerdesin? 

Yüreğin rahat mı gittiğin yerde? 

Hatırlar msın arkada bıraktığın biçare

Ne halde? 

Sormaz mısın hiç kendine.

Nerede diye.

Ben hergün soruyorum,

Nerdesin demek beni öldürsede.

Bu can çıkacak birgün bu bedenden.

Soracağım haykırarak gökyüzüne.

Nerdesin?', 'Hava soğuk,içim üşüyor  Nerdesin?  Ocakta birkaç odun parçası, Gökyüzünde ay ve yıldızlar. Bürünmüşüm yırtılmış çarşafıma, Aklım üşüyor. Ner...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kurt']::text[], 8.5, '{"poet":"Yasemin Kurt","poet_slug":"yasemin-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozledim-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lü''süz', 'lu-suz-cuneyt-temir-ipcqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lü’süz 1

Ucuzladı, kafası kırılansıca sermaye sözlerim.

Eskiden böyle miydi! 

İki laf ettim mi üçüncüsüne hâcet yoktu.

Oldu mu şimdi! 

Fahişeye bile para vermezken,

Bu kadar laf ile yalnız yatmak.

Olmadı.

Sabahın zıkkımına kadar tenimde,

Dilimde, aklımda, içimde üç hece,

Seviş seviş seviş....', 'Lü’süz 1 Ucuzladı, kafası kırılansıca sermaye sözlerim. Eskiden böyle miydi!  İki laf ettim mi üçüncüsüne hâcet yoktu. Oldu mu şimdi!  Fahiş...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Temir']::text[], 8.5, '{"poet":"Cüneyt Temir","poet_slug":"cuneyt-temir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/lu-suz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümden Sızarken Sabahlar', 'omrumden-sizarken-sabahlar-aylin-ayla-selcukoglu-mow80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ebrimden sağdığım mayasız yağmurlar

Zihnime üşüşürken ıslanan kuraklık

Ağlarıma takılır yaraladığım taze lazanyalar

Sabrımla örtüşürken mahirâne,çıraklık

Taba rengi düşler,gerçeğimi yağmalar

Kifayetsiz sürtüşürken benle,sana kaplanmışlık

Masamda gümüşî şamdana takılı beyaz mumlar

Yine zatıma sunulan günlerce bakıştığım yalnızlık

Etekleri uçuşurken martıların,yıkanır yarınlar

Payıma düşer bugünler,hazmedebildiğim kadarlık

Bandırır sendeki hürriyetime kadife sarımlar

Ötelerden beridir,susadığım garip sırdaşlık

Bilinirliği  kanıtlanır ömrümden sızarken sabahlar

İremler dolandırır,tercih ettiğim sana yaşamışlık

Gamzelerimde alkışlanırken yakınsak rüyalar

Cennetler akıtır,dönüşteki saf meyilime eder yârânlık.

18.05.2005   Çarşamba    11.05.-11.40', 'Ebrimden sağdığım mayasız yağmurlar Zihnime üşüşürken ıslanan kuraklık Ağlarıma takılır yaraladığım taze lazanyalar Sabrımla örtüşürken mahi...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omrumden-sizarken-sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lü''süz 2', 'lu-suz-2-cuneyt-temir-le47u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarım çocuk masalı, yarım piç benim.

Arada sırada oynarken bir çiklet ile adım çıkıyor.

Suçu üstlenir piç yanım,

Galeyana geldik der masal dağım.

Şimdi tutup kendimi, yani ufak tefekli halimi,

Koysam bacak arana...

Hangisi ufak ufak ezerken seni,

Hangisi altından kaçırır bu teni....', 'Yarım çocuk masalı, yarım piç benim. Arada sırada oynarken bir çiklet ile adım çıkıyor. Suçu üstlenir piç yanım, Galeyana geldik der masal d...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Temir']::text[], 8.5, '{"poet":"Cüneyt Temir","poet_slug":"cuneyt-temir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lu-suz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Soy', 'cabuk-soy-cuneyt-temir-5hs0i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlığı çektim pencereye,

Sokul şimdi hızlı hızlı yanıma.

Soy etimden kemiğime ne varsa,

Buruşturup katla yatağın başucuna.

Allah yarattı kul insaf da deme sakın.

Gözlerini dik boynuma.

Çabuk soy çabuk geç,

Adisyon fişleri önümüze konup,

Hesabı denkleştirmeden soy.

Geceliğini çıkar, gecenin üstüne örtelim.

Kapatalım lambaları; tasarruf bahanesiyle içimi deş.

Çabuk soy, bekareti gecikti doğurganlığın.

Sarhoş geç direksiyon başına,

Ve gelirken ihlal et bütün kuralları.

Camı taşlarlar,

Kapı zembereğine dayanan siren sesleri.

Çabuk soy diyorum insafın nerde? 

Şimdi alırlarsa beni köynek,  mintan; 

Parmaklıkları öperim senin yerine.

Sen dokunmazsan onlar dokunacaklar,

Ellerimi kanatıp seni söyletecekler.

Bir sigara verirler yakarım sonra...

Bülbül ol derler ben sen olurum.

Yine kanatırlar...

Çabuk soy diyorum hevesin nerde? 

Vakit bir fren sesi,

Bitiş anımız bir post bıyıklı.

İte kaka yol alırım birazdan.

Karga tulumba mı sokayım senide koynuma.

Üşüdüm diyorum sana, laftan anlamaz mısın? 

Müebbet hapis göz kırpıyor,

Kimse gelmez ziyaretime. 

Dinine yandığım sigara karaborsa olur diyorum.

Sana diyorum yalvartma yeter çabuk soy.

Baba adımı soruyorlar, fişleneceğim bütün kayıtlarda

İnsafa gel, soymazsan bile beni yattığın koğuşa koy.

                                                                        03,01,2006 02:49 pazartesi-salı', 'Karanlığı çektim pencereye, Sokul şimdi hızlı hızlı yanıma. Soy etimden kemiğime ne varsa, Buruşturup katla yatağın başucuna. Allah yarattı ...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Temir']::text[], 8.5, '{"poet":"Cüneyt Temir","poet_slug":"cuneyt-temir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/cabuk-soy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Sesleniş', 'en-guzel-seslenis-aylin-ayla-selcukoglu-8aflx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'El bağlayıp dalmışsınız beraber akaçlanan hayat pınarına

Sessiz servetiniz olmuş,başınıza sokunduğunuz bir iki ak papatya

İmgelemiş sizi,beslendiğiniz nezaket fışkıran lebiniz,dönüp sırtını hazana

Nemlenen buğulu gözleriniz,birbirinizin suretinde akmış mavi zamana

Vezni olmuşsunuz birlik melodisinin,her biriniz ayrı gayrısız uzanıp yarına

Ellemiş güllemişsiniz kara toprağın bağrını,çoraklığını sıyırıp inadına

Öğütmüşsünüz paçalarınızı sıvayıp göz yaşlarınızı,iki güle bir ağlaya

Nargilenin hazzına varmışsınız karıştığınız her bir halka dumanla

Damıtmışsınız bugünden süzülen yarınların en mavisini, yuya yıkaya

Eğirler devşirmişsiniz her nevi çiçeğin evinine bulana boyana

Rapsodiniz isyanla yaşlansa da,hançer işlemesin birbirini tümleyen ne ona sana,ne bakaya.

24.06.2005 Cuma   21.01', 'El bağlayıp dalmışsınız beraber akaçlanan hayat pınarına Sessiz servetiniz olmuş,başınıza sokunduğunuz bir iki ak papatya İmgelemiş sizi,bes...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-guzel-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeamete Uğrarken', 'seamete-ugrarken-aylin-ayla-selcukoglu-t1dy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahipsiz gülüşler böler uykularımı

Koklarım uçuklarken güneşimi,ayımı

Sermeyeceğim yine de sana,bende kalanımı

Deşeceğim sensizliği,tüketerek zamanımı

Şeamete uğrarken bırakmadım minkarımı

Bezedim kararsızlığa mahkûm,kimsesiz bağrımı

Arıyor solan sebebim,senimi yani ifakatımı

Yine beraber haykırıyoruz bak,lâl nakaratımı

Yakardın gelsen,hayata soğutan hatamı

Kışa bağladın bu gidişinle,kır çiçekli baharımı

Senden öğrendim uzaklardan bir nefesle sulamayı,goncamı

Erişirsen; tek senle,yalnız senle süslerim âfâkımı! 

27.05.2005  Cuma   09.14-09.57', 'Sahipsiz gülüşler böler uykularımı Koklarım uçuklarken güneşimi,ayımı Sermeyeceğim yine de sana,bende kalanımı Deşeceğim sensizliği,tüketere...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seamete-ugrarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Yamalıkları', 'aksam-yamaliklari-cuneyt-temir-uui5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dikenli akşam üstleri.

Güneşin sırtına inen bir hançer,

Yaralı ışıkları taşıyan bir sedye; 

Akşam üstleri.

Çam kırıkları ile dolu bahçe duvarlarına

Bebek elleri dokunurken,

Bir yaprağın ömrünü uyuz bir kurtçuğa 

Teslim eden,

Deli çağında babasından sakladığı sigarayı,

Duvar diplerinde askıya alan üniformalının,

Tütsü dudaklar arasında, peşmerge ateşi taşıyan

Casusun acı bakışını

Ve kokuşmuş bedenler altında,

20 yıl sonrasının hayalini satın alan yosmaların,

gözlerini çalan.

Dikenli akşam üstleri...

Bulutların ardında bir ülke hayal ederken,

Sabunsu kokulara muhtaç kalan esirin,

Her sardığı simit de yüreği çıtırdayan,

Serseri bıçaklar arasında simitçinin.

Heybeye yürekli koca bir delikanlının,

Son bir kez baktığı; 

Akşam üstleri.

Benim hep gördüğüm,

Her gece içime bir yılan sokup,

Sabah kelebek uçurduğum  yatağımdan.

Hep gördüğüm...

Güneşin sırtına yediği hançerden başka bir şey değil,

Cesedini kıyıya sürükleyen akşam üstleri...', 'Dikenli akşam üstleri. Güneşin sırtına inen bir hançer, Yaralı ışıkları taşıyan bir sedye;  Akşam üstleri. Çam kırıkları ile dolu bahçe duva...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Temir']::text[], 8.5, '{"poet":"Cüneyt Temir","poet_slug":"cuneyt-temir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aksam-yamaliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismarlarım Gülmelerimi', 'ismarlarim-gulmelerimi-aylin-ayla-selcukoglu-apg0o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Harçlık diye arka cebime

Koyuyorum,dumanlara sarılı göz bebeklerimi

Hîbe ediyorum zamanı kendime

Siliyorum çocuksu ayrık küsmelerimi

Koyuluyorken günler,çağlayan benime

Yetmez olur ısmarlarım gülmelerimi 

Kodlanırken usumda yarınlar,yalın bir tepkime

Çağırırım beni kan tutarken,boşalan katrelerimi

24.05.2005   08.10-08.25', 'Harçlık diye arka cebime Koyuyorum,dumanlara sarılı göz bebeklerimi Hîbe ediyorum zamanı kendime Siliyorum çocuksu ayrık küsmelerimi Koyuluy...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ismarlarim-gulmelerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5 A'' ya Sesleniş', '5-a-ya-seslenis-aylin-ayla-selcukoglu-kwoj7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benliğimle yeniden barıştırdınız beni

Eksilmeyen sevginiz kahretti bendeki

Şaşıfelek çıkmazlarını

Aslında gitmiyorum,sizde var olacağım

Yağmur ıslatmayacak sissiz yanaklarımı

Ardımdan laf gelmeyecek,eminim

Sözlerim çınlayacak daima kulaklarınızda

Etrafınıza farkınızı göstereceksiniz inşallah

Sakın unutmayın defteri nasıl kullanacağınızı da emi

Layıkıyla büyük adamlar olup çıkın karşıma

Eşkıya cehaletin,sökün etiketini küçük bedenlerinizle

Nakışlayın,parlak düşüncelerinizle okulu,beni bezediğiniz gibi

İsyana yer yok,şükredin zorlansanız dahi

Şüphe duymayasınız,siz hep bende var olacaksınız

Sabahları selamlaşmayacağız artık

Okula kolumda sizlerle ulaşmayacağım da hatta

Nefesim kesilince anlatmaktan,su yetiştiren siz olmayacaksınız bana

Sizinle gurur duyuyorum demeyeceğim vücuden ama

Ufacık çırpınışlarınızı dahi hissedeceğim uzaklardan

Zevkli geçen her anımızı hatırlatacak şu resimler

Saf,yalın sevginiz,hayata daha bir bağladı beni

Evveli,unutulası eskiyi  unuttum her göz darbenizde

Vicdanım rahat değil,geride bıraktığım için

Gaddar çıkar dünyasında,bıraktığım için sizi

İstendik davranışlarınızla pes dedirtin cümle aleme

Miras bıraktığım sevgi-saygıyı yaşayıp yaşatın hep

Linç edin size gelecek tüm kötülükleri,dininizle,dilinizle

Eyvallah gidiyorum,attığım sevda tohumları o dünyayı sığdıramadığım minik yüreklerinizde

2001 Hatırası', 'Benliğimle yeniden barıştırdınız beni Eksilmeyen sevginiz kahretti bendeki Şaşıfelek çıkmazlarını Aslında gitmiyorum,sizde var olacağım Yağm...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/5-a-ya-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dost!', 'ey-dost-aylin-ayla-selcukoglu-hdi1f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızılca şafak ağarır gövdemde

Kâbuslar yıkılır çehrende

Yağmur yağmaya utanır derken

Eser ılık nefesin yüreğime

Sarılırım sarmaşık şiirlerime

Geceye küs değilim artık

En az senin kadar sevmekteyim onu da

Yamacımda sen,gözlerimde…

Saatler dur durak bilmez

Senle büyüyen hayallerim gibi

Ey dost! ihtiyacım olduğu anda yanımdasın

Sen ki, se mübarek bir insansın

Yalan yok bendeki sende

Kahreder yalan sevişler, bize

Çıkar kokmaz,rengi beyaz

Seni seviyorum ey dost,dünya dursa da dönse de! 

20.04.2002  Cumartesi      10.16', 'Kızılca şafak ağarır gövdemde Kâbuslar yıkılır çehrende Yağmur yağmaya utanır derken Eser ılık nefesin yüreğime Sarılırım sarmaşık şiirlerim...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-dost-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarışınlığının Sınırı Yok', 'sarisinliginin-siniri-yok-cuneyt-temir-qr75j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarışınlığının sınırı yok,

Onu görünce biz böyle derdik.

Karşı kaldırımı O''na ayırmıştık,

Yitik kuşlar, düşen bozuk para ve ucuz el kitapları

O''nun kaldırımının malıydı..

Hiç bir zaman dakik değildi, olmadı da

Bu yüzden saat takmaya başladık.

Yel değirmenleri gibi dönerken saniyeler, tutuşturuyorduk beynimizi.

Elimizde aforoz belgeleri, ağzımızda tütün tadı,

Hep Onu çaldık meyhane saatlerinde..

Gülümseyince yıkardık dükkan camlarını,

Suretimizden eksik etmiyorduk, aşkımızı ve serseriliği..

Polis tutanaklarına böyle imza attık...

''Sarışındı ama sınırı yoktu''

sarışınlığı başa belaydı.

Bir şarjör mermi saydırırdı bir bakışı,

Bir kere süzsün bizi; 

Ansiklopedi ciltleri kadar derin olurduk.

Ama ''adam''sız'' değildik ya yüzüne karşı.

Oysa her gece yazdığım şiirler üzerinde sevişiyorduk.

saçak altlarında kesiyordum soluğunu.

''Adam''sız'' olmamak koydu bize.

Kırılgan kaburgalarım arasında yumuşak teni,

Yorgan ve elektrik düğmesi arasında kaldı...

.

Her gün güneşi vurduktan sonra naaşı için içirdik.

Sarışına içerdik,

Tadı buna benziyor mu diye hayal kurup,

Rakı kadehi kırılınca, O ağladı diye üzülürdük.

En deli bendeydi tarifsizliği, kimseye sezdirmedim.

Köstebek yuvalarına kum doldurur gibiydi içimde oynayışı.

Acı bir susuzluktu...

Acıtmayacak gibi değildi; 

Teneke masanın etrafında dönen fırıldak duyguları dinlemek.

Keyif sakimiz içkiydi, mezemiz sarışın.

Ve süre gelmesi gereken gibi geldi yalnızlık.

Ortada kaldık.

En büyük günahı hemen yazdık, tebeşir elimizde:

Sarışındı ama... yoktu...', 'Sarışınlığının sınırı yok, Onu görünce biz böyle derdik. Karşı kaldırımı O''na ayırmıştık, Yitik kuşlar, düşen bozuk para ve ucuz el kitaplar...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Temir']::text[], 8.5, '{"poet":"Cüneyt Temir","poet_slug":"cuneyt-temir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sarisinliginin-siniri-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Diğer Yanı', 'yuregimin-diger-yani-aylin-ayla-selcukoglu-aqfjc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarım,usludur,habersiz

Kanmaz haram nimetlerin cümlesine

Kayıtsız resmi dolanır

Düşlediği,sensiz oluşturduğu gökyüzünde

Açtı yüreğini sana umarsız

Belki duymadın,ya ki anlatamadım

Diz üstü çöküyorsun karşımda neden? 

Beni kaçırıp senden saklayamadım

İznim yok girmene yüreğimin

O mahrem uç köşesine

Milletvekili gibidir,dokunulmaz

Yazacam korkusuz,dilim saklı durmaz

Kârım yok düne oranla

Bekliyorum,şükür yaradana

Tuâle bezedim mâh yüzünü,kapkara

Niye girdin ki,dolanmaktasın kanımda

Senden kalan bir çok anı

Unutturmuş bana,uğruna tükettiğim zamanı

Yarı mutlu,yarı acı sevdalı

Dediğim; sana hasret 

YÜREĞİMİN DİĞER YANI! 

09.05.2002  Perşembe 22.53', 'Yarım,usludur,habersiz Kanmaz haram nimetlerin cümlesine Kayıtsız resmi dolanır Düşlediği,sensiz oluşturduğu gökyüzünde Açtı yüreğini sana u...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregimin-diger-yani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lila Umutlar', 'lila-umutlar-aylin-ayla-selcukoglu-e19do', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara utançları sindirdim

Dokunulmamış gonca gölgesinde

Sevimsiz anlar buhar oldu

Yüreğime sadece lila umutlar hâkim

Gözüm dalıyor kabir sonsuzluğuna

Askerim bu yolda,ölümüne fedâi

Yasaklı dövüşler çıkmazda kaldı

Yüreğime sadece lila umutlar hâkim

Hayata,yaşanası hayata mesajım

Beyaz güller var artık vazomda

Yine dîdelerim değil,gülüm kırmızı

Yüreğime sadece lila umutlar hâkim

Dönmeyeceklerimin gelişini bekleme artık

Eksilen umudumdu evvel,şimdi kinim

Mekik dokur ellerim,kelimelere nakışlar seni

Yüreğime sadece lila umutlar hâkim

Kalabalıktan gelir sesin,bilmem nerdesin

Aksıran,üşütmüş gözlerin

Tutamadığın,ulaşmak istediğin ellerim

Yüreğime sadece lila umutlar hâkim

Kasılma bakalım,kal,otur öylece

Bugünü yaşadım nasılsa demeden

Yarınların en güzelini düşlerken

Yüreğime sadece lila umutlar hâkim

Gitmeli artık,karışmalı buluta

Sabaha sabırsızım,kıvranırdım geceleri

Soluğum bile hafifledi şu an ellerimde

Yüreğime sadece lila umutlar hâkim

11.04.2002 Perşembe  10.10-10.23', 'Kara utançları sindirdim Dokunulmamış gonca gölgesinde Sevimsiz anlar buhar oldu Yüreğime sadece lila umutlar hâkim Gözüm dalıyor kabir sons...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/lila-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim'' e', 'annecigim-e-aylin-ayla-selcukoglu-iy9ht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdime ortağım hatta

Olmazsa olmazım anam, canım, kanım

Sanki bende, benden öte beni

Teskine imkan yok dediğim, yetimleyin

Usulca uçurur gövdemdeki ruhumdan

Mavi kelebeğiyim onun, canıma kastımı söker

Anam, değil değil, çıkmazlardan dönüşüm

Naçiz, nazara inat cennet kapım

Anlamaktan dahası yaşayan beni

Melaikem, kanatsız Ayla’sının gözbebeği, sevdiğim! ! ! 

25.01.2002  CUMA   23.28', 'Derdime ortağım hatta Olmazsa olmazım anam, canım, kanım Sanki bende, benden öte beni Teskine imkan yok dediğim, yetimleyin Usulca uçurur gö...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/annecigim-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengim', 'rengim-aylin-ayla-selcukoglu-j621r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ilkin beyazdim

Uzunca yasadim bozulmadan

Dokunmuyorlardi

Anlamazdim ya ki

Benlerimden,kahverengi benlerimden bile bihaberdim

Zamanla yeserdim

Göge uzanan uzun dallarda

Pembeydi gülüslerim

Sicacik nakislarim yagmur kokardi

Sandigim kocaman,içi de dolu

Düzdürmüsüm,anamla,bacimla

Tüm renkleri

Masmavi denize asiktim

Su çekerdi beni alabildigine

Daglar benim için vardi sanki

Alip basimi gitsem de

Bagira bagira,hiçkira hiçkira

Aglamayi ögrensem diye

Yolculuklari severdim

Kavustururdu beni yesile

Umuda tasirdi gri martlar

Tarifsiz gelirdi sevgiler

Sarardi gezen yüregim

Dalimdan düsen son yaprak gibi

Mavi çocuk yandi

Gri küllerle savruldu

Ardina kara yürek daglandi

Geceler karayagiz

Kan kirmizi didelerim

Didemde sancim büyüdü

Yüregim oyuna aç

Kuzgun ötermis

Kiremit rengi hangi,kimler

Kemiklerim dahi sevmez artik

Uyanir uyanmaz gördügüm

Islak,siyahi nazli bebegi

Menekse kokacak yarin

Oyalarla sigindim

Koyu yesile çalan limana durgun

Demir attim…

Alem bahari bilmez

Ya yazi,ya kisi yasar

Bir ben kaldim saydam bahari yasayan

Basi sonu belli

Yasayacaksan gözünü karartacak

Mühürleyeceksin renkleri

Güne aydin,geceye iyi demek için

Ama agartacaksin ufkunu

Kizil goncayi sunabileceksin

Hak ettigin beyaz dönüste…

14.02.2002-Persembe-23.59/00.14', 'Ilkin beyazdim Uzunca yasadim bozulmadan Dokunmuyorlardi Anlamazdim ya ki Benlerimden,kahverengi benlerimden bile bihaberdim Zamanla yeserdi...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/rengim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısacık..', 'kisacik-elif-betul-ozturk-lnc9w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önce bir sevgiydi,

Sonra kin oldu.

Bir destandı ama,

Sonra mazi oldu.

Güzel bir yazdı,

Sonra sonbahar oldu.

Öyle bir sevdaydı ki,

Yandı bitti kül oldu...', 'Önce bir sevgiydi, Sonra kin oldu. Bir destandı ama, Sonra mazi oldu. Güzel bir yazdı, Sonra sonbahar oldu. Öyle bir sevdaydı ki, Yandı bitt...', ARRAY['Türk Edebiyatı','Şiir','Elif Betül Öztürk']::text[], 8.5, '{"poet":"Elif Betül Öztürk","poet_slug":"elif-betul-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kisacik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol/Gidiş', 'yol-gidis-nermin-altindag-y9xbn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm çelik, ben çomak

Ölüm tren, ben fren

Ölüm ayna, ben kavak

Ölüm ayna, son durak...

''Aynalıkavak''ta son tango...''  Çobanyıldızına...

... not düşmediğim bir tarihte/ KADIRGA', 'Ölüm çelik, ben çomak Ölüm tren, ben fren Ölüm ayna, ben kavak Ölüm ayna, son durak... ''Aynalıkavak''ta son tango...''  Çobanyıldızına... ... ...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yol-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın,anlama', 'anlamadin-anlama-mehmet-akif-gulhan-dkvbe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saeede mane saşe

Heira o haa hakare 

Semine toa galire

Teaiçe hakemeri

Taoşimane jaide

Anlamadın değil mi? 

Boş ver

Bende anlatmak istemedim

Zaten anlamazsın

Anlatsam dinlemezsin

Dinlesen kabullenmezsin

Kabullensen hesaba uymaz

Boş ver anlamadın,anlama

Mehmet Akif Gülhan 07.01.2006 Saat 20.08

Şiirin baştaki 5 mısrasının hiç bir anlamı yoktur.', 'Saeede mane saşe Heira o haa hakare  Semine toa galire Teaiçe hakemeri Taoşimane jaide Anlamadın değil mi?  Boş ver Bende anlatmak istemedim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anlamadin-anlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavga', 'kavga-mucahit-gulbas-v8c7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hiç “efes’in çatısında viski içtinmi

Yatına binip te 4 kadınla aşk-meşk ettin mi…

Gökleri delen otellerde tepsi üstünde”karı”oynattın mı *

Sen hiç villa gördünmü

Kuş tüyü yataklarda dilberlerle uyudun mu

Bindin mi bıçkın gibi siyah bir arabaya

Ayağını yerden kestinmi…

Hiç pirzola biftek yemekten

Rakı içmekten şiştin mi..

“Amerika’ya gidip sağlık taramasından geçtin mi.

Hey sen! 

Aval aval vitrinlere bakan

“Amerikan’ pantolonu için babasına yalvaran..

Marmarise,Bodruma gidip,

”Bebek’ten,”alsancak’tan  geçtin mi? 

Geçmedin değil mi..

Geçmiş isen de görmedin biliyorum

Eğer görseydin yada görmesini bilseydin

Anlardın.

Yeryüzünde neyin kavgası olduğunu..

* Yukarıda kullanılan “karı’ sözcüğü herhangi bir aşağılama içermemektedir.Şiirde kullanılan halk ağzına destek sağlamak için kullanılmıştır/anlayışınıza sığınırım

M.Gülbaş    İzmir /1989', 'Sen hiç “efes’in çatısında viski içtinmi Yatına binip te 4 kadınla aşk-meşk ettin mi… Gökleri delen otellerde tepsi üstünde”karı”oynattın mı...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kavga-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öç', 'oc-husam-hasret-2sdgg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acığa durdu zaman sıyırdı kılıcını

Bağırıp öfkesiyle döktü temiz kanları

Hıncıyla darmadağın etti suçsuz canları

Kimler kanlısı idi, kimden aldı öcünü

* Acığa durdu: Karşı durdu', 'Acığa durdu zaman sıyırdı kılıcını Bağırıp öfkesiyle döktü temiz kanları Hıncıyla darmadağın etti suçsuz canları Kimler kanlısı idi, kimden ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oc-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi sokakta seni görsem', 'hangi-sokakta-seni-gorsem-seyit-ahmet-duzen-porwv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi sokakta seni görsem,

O sakaga benziyorsun...

Bu kent kadar yabanciysan bana.

Suc sehrindir üstlenmem

Gece tek tanigimdir önce sen bilmelisin

Yollardan korkmam ardıma düşüp gelmelisin

Hangi sokakta seni görsem,

O sakağı asiyorum gözlerimle,

Daragacinda havalaniyor güvercinler

Ellerimle siliyorum cesmelerin gözyasini

Analar beni ayıplar, bebeler taslar

Seni vurursam bu şehirde

Beni yasatmazlar...', 'Hangi sokakta seni görsem, O sakaga benziyorsun... Bu kent kadar yabanciysan bana. Suc sehrindir üstlenmem Gece tek tanigimdir önce sen bilm...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hangi-sokakta-seni-gorsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne çok şey var anlatılacak', 'ne-cok-sey-var-anlatilacak-ramazan-kayak-36po0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlatılacak ne çok şey var aslında 

Öylesine duygu yüklü 

Sıcacık sevdalar la dolu 

Çiçek, çiçek

Yağmur, yağmur

Tutkulardan yarınlardan

Yokluk içinde yaşanan 

Yangınlardan

Ne çok şey var anlatılacak 

Yumruklarda sıkılı öfke 

Gülüşlerdeki tutku

Baharlarda ki sevda 

Kırmızı güller diyarından

Habersiz geçen çocukluktan 

Okullara uğramadan geçen 

Yitik sevdaların peşinden 

Kayıp olan bir gençlikten 

Dağlardaki özgürlükten 

Talan edilmiş yürekten 

Kör kuyulardaki geçmişten 

Haramilerle dolu gelecekten 

Anlatacak ne çok şey var

Deli gibi sevdalara tutulmak

Kırmızı karanfilleri kucaklarcasına sevmek

Kömür madenlerinde sesizliği paylaşmak

Su damlacıklarıyla 

Hayat yolunda yürümeyi bıkmadan

Yapayalnız olsan da kendinle

Ne çok şey var anlatılacak 

Ölümle yaşam özerine 

Özverili sevdalar özerine 

Tutsak yüreğimiz özerine 

Oysa hepsi dudağımda kaldı

Şu gönlüme yangın düştü düşeli', 'Anlatılacak ne çok şey var aslında  Öylesine duygu yüklü  Sıcacık sevdalar la dolu  Çiçek, çiçek Yağmur, yağmur Tutkulardan yarınlardan Yokl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ne-cok-sey-var-anlatilacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğa', 'mutluluga-husam-hasret-pjecq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlar şadlık için öttüğü zaman

Sevinç kanadıyla uç mutluluğa

Ayrılık çilesi bittiği zaman

Kavuşmak kapısın aç mutluluğa

Gönlümüz sevgiyi doğru buldukça

Şadlık çilemizi içten yoldukça

Sevişip kavuşmak mümkün oldukça

Benimle yaşamı seç mutluluğa

Sevgi dünyasının kapısından gir

Orda olanları gör ki kimlerdir

Bakarken hecele şiirimi bir bir

Sonra anlamını saç mutluluğa

Gözün aydın olsun söyle aşkına

Her uzak güzellik geldi yakına

Acıyı, kederi son defa kına

Her nesneyi bırak geç mutluluğa', 'Kuşlar şadlık için öttüğü zaman Sevinç kanadıyla uç mutluluğa Ayrılık çilesi bittiği zaman Kavuşmak kapısın aç mutluluğa Gönlümüz sevgiyi do...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutluluga-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar sensiz gelir', 'i-lkbahar-sensiz-gelir-ramazan-kayak-cn796', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey ömrümün anlamı olan 

Ben hala sendeyim seninleyim

Biliyordun 

Güller açardı yüzünde 

Sen güldüğünde

Masmavi olurdu denizler 

Sen baktığında 

Fırtınalar kopardı gönlümde 

Sen ağladığında 

Sevgi doldurmuştun ömrüme 

Sen sevdikçe 

Şimdi gönül evim viran olmuş 

Sen gittiğinde 

Talan olmuş tüm dünyam 

Yoksun diye

İlkbahar sensiz gelir

Şu yoksul gönlüme 

Yağmurlar yağdığında bu şehre 

Sen gelirsin aklıma 

Güzelliğinle 

Sen gelirsin aklıma sesiz gidişinle 

Kırılgan bıraktın ömrümü 

Kalbimde sabır halkaları kopmakta 

Sensizlik bedenimde harami olmuş 

Sensiz geçen günlerimde 

Mezarına her geldiğimde 

Bende ölürüm sensiz 

Ölürüm, ölürüm 

Her bahar sensiz gelirken ömrüme', 'Ey ömrümün anlamı olan  Ben hala sendeyim seninleyim Biliyordun  Güller açardı yüzünde  Sen güldüğünde Masmavi olurdu denizler  Sen baktığın...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ilkbahar-sensiz-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garibin', 'garibin-husam-hasret-dww22', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl olsa gurbette

Şansı olmaz garibin

Yaşadıkça hasrette

Yüzü gülmez garibin

Yuvadan umut keser

Yüreğini gam basar

Başında yeller eser

Sesi gelmez garibin

Uzandıkça hayali

Koynunda kalır eli

Yurda dönmek emeli

Hiçte ölmez garibin

Gece kapılır düşe

Gündüzü geçer boşa

Vatandan başka köşe

Ahın almaz garibin', 'Nasıl olsa gurbette Şansı olmaz garibin Yaşadıkça hasrette Yüzü gülmez garibin Yuvadan umut keser Yüreğini gam basar Başında yeller eser Ses...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/garibin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-husam-hasret-dvd6e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk günden benim için gam kahra battın anne

Dediğin her ninniye göz yaşı kattın anne

Ev eşiğimi, çoluk çocuğumu görmeden

Ne yazık bu hasretle toprakta yattın anne

Sen gideli esmiyor başta hoş hava anne

Ne de bu dertlerime vardır bir deva anne

Elinle her bir köşe süslenip düzenirdi

Sensiz darmadağındır bu ev, bu yuva anne

Sen gideli bir ahım ikiye döndü anne

Kırılan dallarıma gam kuşu kondu anne

Varlığın benim için yanan bir mum gibiydi

Sensiz karanlıktayım, çünkü o söndü anne', 'İlk günden benim için gam kahra battın anne Dediğin her ninniye göz yaşı kattın anne Ev eşiğimi, çoluk çocuğumu görmeden Ne yazık bu hasretl...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anne-188-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-husam-hasret-zycms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğru ol karışma her terse işe

Haram lokma alma ağıza, dişe

Kırılsa sağalmaz gönül bir şişe

Gücün yeterse de zulmetme oğul

Sakın zalim olma, zulüme dalma

Zulmetme mazlumun ahını alma

Şerrinden uzak dur, kapısın çalma

Ziyanlı başına baş çatma oğul

Zulmün dostu değil, düşmanı çoktur

Ona atılan ok haktaki oktur

Bu günü var ise yarını yoktur

Kirli denizine taş atma oğul', 'Doğru ol karışma her terse işe Haram lokma alma ağıza, dişe Kırılsa sağalmaz gönül bir şişe Gücün yeterse de zulmetme oğul Sakın zalim olma,...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogul-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-husam-hasret-k90e0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizlik bir öyküdür yokluğu anlatacak

Yıllar boyu sevişip bir an kavuşmayana

Bir söz veya bir tümce hatıra diye ancak

Sessizce dinletecek susup konuşmayana', 'Sensizlik bir öyküdür yokluğu anlatacak Yıllar boyu sevişip bir an kavuşmayana Bir söz veya bir tümce hatıra diye ancak Sessizce dinletecek ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensizlik-231-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şadlık', 'sadlik-husam-hasret-m24js', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şadlık bir melek ise

Boyunu görmemişim

Geline bezek ise

Toyunu görmemişim

Dertlere derman ise

Visale ferman ise

Vergili harman ise

Köyünü görmemişim

Görüşü belli ise

Kalbe teselli ise

Akılı deli ise

Huyunu görmemişim', 'Şadlık bir melek ise Boyunu görmemişim Geline bezek ise Toyunu görmemişim Dertlere derman ise Visale ferman ise Vergili harman ise Köyünü gö...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sadlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-husam-hasret-mx3f7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin bahtıma bir ak perde açtı

O günden uyku bile gözümden kaçtı

Sevginin hoşluğunu dünyama saçtı

Gel bana, gel yanıma ey bala ceylan

Kaşına, kirpiğine, gözüne hayran

Gözlerin aşkıma bir dünya yarattı

Beni bu gam içinden şadlığa attı

Sevgime doyulmayan bir sevgi kattı

Gel bana, gel yanıma ey bala ceylan

Kaşına, kirpiğine, gözüne hayran

Gözlerin gözlerime neşeyle baktı

Gönlünden yar gönlüme bir sevgi aktı

Beni o günden bile aşka bıraktı

Gel bana, gel yanıma ey bala ceylan

Kaşına, kirpiğine, gözüne hayran', 'Gözlerin bahtıma bir ak perde açtı O günden uyku bile gözümden kaçtı Sevginin hoşluğunu dünyama saçtı Gel bana, gel yanıma ey bala ceylan Ka...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerin-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bize', 'gel-bize-husam-hasret-e9hcf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şadlığı hem de sevinci al bize

Gel bize gel, gel bize gel, gel bize

Gecikme yar, gör ki ne bir gamdayız

Bir az olsun, bir az düşün dal bize

Olan nedir olmayan ne, düz söyle

Her ne dedi yalan dedi fal bize

Dinç almadık bu üç günlük hayatta

Dost olmadı, düşman oldu mal bize

Kimse yoktur derdimizi diyelim

Onun için hep diyorlar lal bize

Sen olmazsan, kimse bulmaz çaremiz

Yazık olur, yakışmaz bu hal bize', 'Şadlığı hem de sevinci al bize Gel bize gel, gel bize gel, gel bize Gecikme yar, gör ki ne bir gamdayız Bir az olsun, bir az düşün dal bize ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Aşkım', 'sana-olan-askim-husam-hasret-141vw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllarca aşkını besleyip durdum

Onun için bir ev, bir yuva kurdum

Her zaman kendimi bir aşık gördüm

Sana olan aşkım gerçektir gerçek

Gönülde yeniden her gün aşkı ek

Bağımızda açsın al pembe çiçek

Bizim olsun gülüm bu güzel dünya

Çevremizi sarsın bir yeşil hülya

Seninle hayatın hoş tadı olur

Seninle sevginin muradı olur

Seninle her şeyin bir adı olur

Sana olan aşkım derindir derin

Seven gönüldedir her zaman yerin

Sevgi dünyamıza es serin serin

Bizim olsun gülüm bu güzel dünya

Çevremizi sarsın bir yeşil hülya', 'Yıllarca aşkını besleyip durdum Onun için bir ev, bir yuva kurdum Her zaman kendimi bir aşık gördüm Sana olan aşkım gerçektir gerçek Gönülde...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-olan-askim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki', 'ki-husam-hasret-gw4m5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl bu yaşamı benimserim yar

Sen yoksun içinde, sen uzaksın ki

Yaşamak var ise yaşamınla var

Sevgi için evvel, son duraksın ki

Yalnızlık kaderi başıma çattı

Beni sensizlikten boşluğa attı

Hayal deryasında vapurum battı

Kurtaran o liman, o topraksın ki

Yıllar özlediğim konu sendedir

Çıplak sevgimizin donu sendedir

Her bir şeyin ilki, sonu sendedir

Şadlığa, çileye bir kaynaksın ki', 'Nasıl bu yaşamı benimserim yar Sen yoksun içinde, sen uzaksın ki Yaşamak var ise yaşamınla var Sevgi için evvel, son duraksın ki Yalnızlık k...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ki-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Burda yürek Çaresiz..', 'burda-yurek-caresiz-murat-dogan-zbusl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirin mükemmelliğine diler tutulmuşta

Sözler kalmış çaresiz.. 

Özlem düşmüşte gönüldeki sevgiye 

Yürek kalmış çaresiz..

Aşk acısına kapılmışta deli yürek

Gözler kalmış çaresiz..

Ölüm  kapıyı çalmışta

Can; son nefesinde kalmış çaresiz..', 'Şiirin mükemmelliğine diler tutulmuşta Sözler kalmış çaresiz..  Özlem düşmüşte gönüldeki sevgiye  Yürek kalmış çaresiz.. Aşk acısına kapılmı...', ARRAY['Türk Edebiyatı','Şiir','Murat Doğan']::text[], 8.5, '{"poet":"Murat Doğan","poet_slug":"murat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/burda-yurek-caresiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahanemiz Var', 'sahanemiz-var-ali-balliktas-p94zr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey vaiz sen bizi bilmek istersen,

Şah-ı Merdan gibi şahanemiz var.

Bizimle bir olup kalmak istersen,

Buyur gir içeri meyhanemiz var.

Sormayız orada senden künyeyi.

Doldurur içeriz aşkla badeyi.

Hayyamız günlerce üfleriz ney''i,

Bizi sarhoş eden sakiyemiz var.

Bütün erenleri ulu biliriz.

bilen bilir biz ölmeden ölürüz.

Hallac-ı Mansurdan ilham alırız,

Enel-Hak babında efsanemiz var.

Biz ki dersimizi evvelden aldık.

Yunusla deryanın dibine daldık.

Ferhat''ız boşamı dağları deldik,

Çünkü Şirin gibi cananemiz var.

MAZLUMİ böylece döndük taşkına.

Bendolduk Mecnun gibi şaşkına.

Gör ki derbederiz Leyla aşkına,

Çölden çöle gezen divanemiz var.', 'Ey vaiz sen bizi bilmek istersen, Şah-ı Merdan gibi şahanemiz var. Bizimle bir olup kalmak istersen, Buyur gir içeri meyhanemiz var. Sormayı...', ARRAY['Türk Edebiyatı','Şiir','Ali Ballıktaş']::text[], 8.5, '{"poet":"Ali Ballıktaş","poet_slug":"ali-balliktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sahanemiz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gençlik', 'bu-genclik-seyfet-bozcali-p04o5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmişine daim sahip çıkarsa,

Zaman gelir öze döner bu gençlik.

Atasını arar gurur duyarsa,

O zaman gücünü bulur bu gençlik...

İçkiden Kumardan uzak durursa,

Bu yaşlarda zararını bilirse,

Helalı,haramı tam öğrenirse,

O zaman özüne döner bu gençlik...

Senlik benlikkavgasına düşerse,

Alet olup sokaklara taşarsa,

Vatanı,Bayrağı umursamazsa,

Hazimet içinde kalır bu gençlik...

Çağdaşlığı kıyfette görürse,

Konserlerde gününü gün ederse,

Ülke için kafasını yormazsa,

Devletlere köle olur bu gençlik...

İbadet aşkıyla görev yaparsa,

Hep hak için hakkı üstün tutarsa,

Yönetimi adeletle yaparsa,

Toplumlara baş taç olur bu gençlik...

Seyfet der bu gençlik özümüz bizim,

Kulağımız gören gözümüz bizim,

Şiirde,şarkıda sözümüz bizim,

Rabbimin bir lutfu bize bu gençlik...', 'Geçmişine daim sahip çıkarsa, Zaman gelir öze döner bu gençlik. Atasını arar gurur duyarsa, O zaman gücünü bulur bu gençlik... İçkiden Kumar...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umrumda Değil', 'umrumda-degil-ali-balliktas-k69si', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya batacakmış umrumda değil,

Yarim ile yarsız olduktan sonra.

Cennetteki huri neyime benim,

O yar benden ayrı kaldıktan sonra.

Aşkımız sevdamız tükenip bitti.

Umut vapurumu deryalar yuttu.

Bağım veran oldu Baykuşlar öttü,

Zamansız güllerim solduktan sonra.

Hüküm versem hüküm salsam nolacak.

Dünyada ebedi kalsam nolacak.

Aleme MAZLUMİ olsam nolacak,

O yar defterinden sildikten sonra..', 'Dünya batacakmış umrumda değil, Yarim ile yarsız olduktan sonra. Cennetteki huri neyime benim, O yar benden ayrı kaldıktan sonra. Aşkımız se...', ARRAY['Türk Edebiyatı','Şiir','Ali Ballıktaş']::text[], 8.5, '{"poet":"Ali Ballıktaş","poet_slug":"ali-balliktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umrumda-degil-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-erdogan-ergin-9gd3f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bizler el sallarız gidenlerin ardından

gidenler mutlu mudur biz yokken

hiç gelir miyiz hatırlarına

mendilerrimize dokunurlar mı

ve düşünürler mi

sevgili ne yapar ayrıyken

gidenler mutlu mudur? 

oysa durmak zor burada

gitmek kolay

çıkıvermek birden insanların hayatından

bakmadan arkana

gitmek öylece

dönmeden

düşünmeden

kırmadığını sanıp kalpleri

hadi git o zaman

al yanına şiirlerini

sepetini doldur bir kişinin aşkıyla

hadi git

bakma arkana

arkanda duran dostluklara

sitemdir

sitem etmekte keyfiyetimdir

senin çekip gittiğin gibi

*** Çok değerli bir dostumun arkasından yazmıştım. Geri döndü ama şiiri kaldı. Paylaşayım istedim.', 'bizler el sallarız gidenlerin ardından gidenler mutlu mudur biz yokken hiç gelir miyiz hatırlarına mendilerrimize dokunurlar mı ve düşünürle...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sitem-218-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döner Bu Devir', 'doner-bu-devir-seyfet-bozcali-3itk5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durmaz gidiyorsun,yol yarılandı,

Aman bir duruver ardına bir bak.

Kaydeder herşeyi zamanın bandı,

En sonunda kaplar üzerin toprak.

Azığında ne var? yokla çantanı,

Duyarsan yürekten anla,duy beni.

İster deli,ister Mecnun say beni,

Yeterki gereksiz işleri bırak.

Kimseye hor bakma,güvenip mala,

Vicdan delinirse tutar mı yama,

Mazlum ağlıyorken gülüp,oynama,

Sanma ömrün sonu o kadar uzak.

Azıp,sapanlara yarar bu devir,

Belirli bir zaman döner bu devir,

Bir gün olur biter,söner bu devir,

Sanma bu gök yüzü hep mavimtırak.

Gür gelen suların kesilir bir gün,

Bir mum gibi erir son bulur ömrün,

Geçmişte ne yaptın bırazcık düşün,

Bütün ömrün geçmiş hayırdan ırak...', 'Durmaz gidiyorsun,yol yarılandı, Aman bir duruver ardına bir bak. Kaydeder herşeyi zamanın bandı, En sonunda kaplar üzerin toprak. Azığında ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/doner-bu-devir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Sureti: Kazimmi', '12-bir-adam-muzesi-sureti-kazimmi-ahmet-yozgat-bnwxe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Köylük yerde Kazimmi derdik biz ona.

boyu ince ve yaralı bir iğde dalı misali uzun

ama kaderi yedi cüceden biriydi sanki.

kahküller döşenirdi bin bir özenle

erken çizilmiş alnına köy bebelerinin.

bir mavi ve aynalı bavulu vardı tahtadan

ve sahtiyan kösüresi yarı kör usturasının

eli gibi, kolu gibi, hatta yüreği gibi

sanki kendinden bir parçaydı.

sofrada baş yemeği tekti Kazimmimizin

tek ve yağda pişmiş yumurtaydı.

kazimmi derdi saçlı, saçsız herkes ona

berberlik olan mesleğinde ustalığı ortaydı.

B/...

kazimmi derdik biz göbeller de ona.

gahi öne düşerdi utangaç saçlarımız

gahi sol yana onun yaba gibi ellerinin altında.

“Karga kekili” modeli biz çocuklar içindi

Büyükler içinse hep üç numaraydı yerel moda.

kazimmi derdi kimi komik anıları da ona.

Kazimmi “Dön kıçını pis karı...” diye başladımıydı

Hepimiz yutkunur ve susardık

Saç örgüsü bulutlara türkü yakan dudağı

İş üstünde bile işlerdi durmadan onun.

tarihini yazardı haki asker kışlalarının.

Bir çavuş arkadaşından söz ederdi

“Allah’ına kadar Adanalı…”

Bir de parolayı anımsayamayan geceleyin

Omzu dört yıldızlı uyurgezer komutanından.

Yetmezdi ve “Anlat hele Kazimmi.” derdik biz ona

bir şıklatırdı konunun girizgahı olarak

cephede mavzer sanıp perma marka makasını.

bir de kışlasındaymış gibi o an Sarıkamış’ın

selam ve hazrol dururdu çakı gibi asker anılarına.

ulu yaşına rağmen gencecik yürekliydi Kazimmi

ve gönlü hala gezde, gözde, arpacıktaydı.

Haftalık saç kesimi nöbetinde gelirdi bize.

Tekdüze yaşamında sevdiği bir işi, 

bir tıpkı kendisine benzeyen karısı

Ve bir de yağda pişmiş yumurtaydı.

Rus Zaza’sıydı bıçkısının unutulan adresi

usturası markasız, kaba ve su verilmemiş çelikti.

Delikti kulağı köyde pişen her aş hususunda

Kimin ocağında  kavrulmuş un hellesi pişti

Hangi horanta yağsız yedi o akşam sütlaşı

Veya kim kime ne dedi, hepsini bilirdi.

kazimmi derdi her traşlı baş ona

rus zaza’sı dinine ve imanına kadar kör

nankördü ona göre bütün kafası keller

traşını sormayın canlar

Oldukça acıcaydı.

Daha bu gün gibi belleğimizde 

Saçlarımızın kesekli tarlalardan

Arpa kökleri gibi yolunuşunun dayanılmaz acısı

Ve tıraş boyu akıttığımız istem dışı gözyaşı.

C/...

kazimmi derdi her kirli traşlı yüz ona 

Odaların ortalığındaki hayali tarlalara kıl ekerdi

Yanağına kırmızı pamuk herkesin.

kazimmi derdik biz ve tüm bıyıklar ona.

boyu ince ve uzun ama kısmeti kısacıktı.

kim ki kestirecekti accık ucundan

ya da söktürecekti dipteki çürük azısını

veya ilk tıraşını olacaktı

mutlaka ona uğrayacaktı.

bıyığın palası ondan sorulurdu.

Kelebeği, börtüsü böceği ondan.

o boşaltırdı bir ustura darbesiyle ortasını

iki yandan sarkık ortasyalı Camoka’yı.

Dudak üstünün bir parmak basımı Hitler biçimi

ya da üst dudağın su içimi...

kazimmi derdi burun altları bile ona

yalnızca traştandı geçimi.

D/...

Kazimmi düştü karlı bir günde toprağa.

makas düştü, düştü zaza ve kör ustura...

ak karlara kızıl kan düştü.

buhurlandı pınarlar tuzlu gözyaşı düştü.

direndi kırçıl sakalları komşuların.

O an öksüz kalan kahküller ağlamada.

her harmanda alırdı hakkını.

kendi de düştü toprağa 

o yıl alamadığı yarım kalan hakkı da...

kazimmi derdi mevsimler ve harman yerleri ona.

gözü yaşlı, un çuvalı boş

ve şaşkın ve yapayalnız iki oğul ile

kocamış bir kadın bıraktı arkada...

***

Kazimmi şiirinin meraklısına dipnot: 

Kazimmi  çocukluğumdan anımsadığım upuzun bir berberdi. Adı Kazım Atak’tı. Lakabı Pancar’ın Kazim’dı. Pancar yakıştırması renginin kırmızılığından mı yoksa anasının adının Pancar oluşundan mı geliyordu bilmiyorum. Ama küçük kardeşi de Pancar’ın Bekir adında biriydi. Yoksul bir ailenin büyük temsilcisiydi. Arazide bir karış bile toprakları yoktu sanırım. Hayatı boyunca köyünün berberliğini yapmıştı. Bu arada diş çekimi de onun ilgi alanı içindeydi. Çocukluğumda derin bir yer tutan anamın diş çekimini de o yapmıştı. Uyuşturma gibi bir şeyi bildiği yoktu rahmetlinin. Anam acılar içinde dakikalarca inlemişti. Ama Kazimmi aldırmamış ve kanırta kanırta çekmişti çürük azıyı. Ne deyim ellerine sağlık Kazimmi. Komik ve hoşsohbet biriydi. Onun anılarından süzülerek darbımesel olmuş “Dön kıçını pis karı ve sahurun ilk gününde karıyı kaşağıladım.” sözleri köyünde hala anımsanmakta. Hatta yerel bir deyim olarak kullanılmaktadır. Sanırım yetmişli yılların birinde, bir karlı kış günü göçtü berberimiz. Şimdi ardından bir Fatiha bekliyordur sanırım.', 'A/... Sahici adı her ne ise unuttum Köylük yerde Kazimmi derdik biz ona. boyu ince ve yaralı bir iğde dalı misali uzun ama kaderi yedi cüced...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-sureti-kazimmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum seni', 'bekliyorum-seni-mazlum-unlu-7c4lk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekliyorum seni işte 

Ne zaman geleceksin umurunda mı? 

Ben hayalimdekine aşık oldum 

-sana değil-

Acaba gelecek mi

Bazı insanlar vardır ki

Sevgisini çabuk bulur

Bazıları vardır ki

Onlara hasretle bakar 

Ve 

Bekler

Nasıl bir acıdır bu

İsyan etmez misin hiç

Hangi adalete sığar bu

Ben söyleyeyim canım kardeşim

İlahi adalete tabi ki

Allah insanları öyle yaratmış

Kimin aşığını Alaskaya 

Kimini ise Afrika ya

Bazen de hemen komşusu yapar 

Anladın mı şimdi

Yani birisi var seni bekleyen 

Belki zamanı gelmedi daha 

Bekle sabret 

Alaskadan afrikadan gelmek  kolay değil elbette

Belki de komşundan şeker alacaksın

Ama nerden bilecektin şeker almaya giderken

Nikah şekeri dağıtacağını

Arayış da ol bekle sabırlı ol

Zamanı geldiğinde gönül kapını aç

Çünkü hayalindeki çoktan gelmiş olacak', 'Bekliyorum seni işte  Ne zaman geleceksin umurunda mı?  Ben hayalimdekine aşık oldum  -sana değil- Acaba gelecek mi Bazı insanlar vardır ki ...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bekliyorum-seni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstük', 'kustuk-tuncay-ulak-georn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üzülmüş bir çift göz bırak arkanda,

Biri sensizliğe biri terk edilişine ağlasın.

Büzülmüş iki dudak bırak çocuk misali,

Biri yalnızlığına biri kuruluğuna yansın.

Umursamadığın duygularım yorganın olsun,

Hissetmediğin ellerim yastık.

Ve şunu bilki duyarsız sevgilim,

Ben, dudaklarım ve gözlerim,

Hep birden sana küstük.', 'Üzülmüş bir çift göz bırak arkanda, Biri sensizliğe biri terk edilişine ağlasın. Büzülmüş iki dudak bırak çocuk misali, Biri yalnızlığına bi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Ulak']::text[], 8.5, '{"poet":"Tuncay Ulak","poet_slug":"tuncay-ulak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kustuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoğaldı', 'cogaldi-seyfet-bozcali-yqd5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yirminci asırın sonu gelmeden,

Bataklık büyüdü,pislik çoğaldı,

Demir perdeleri aralanınca,

Nataşalar geldi,zina çoğaldı...

Sokaklarda pazarlıklar yapıldı,

Yaşam için taze canlar satıldı.

Kurtlar sofrasına meze yapıldı,

Pazarlar büyüdü fuhuş,çoğaldı...

Bütün atamalar siyasi oldu.

Adamı olanlar yerini buldu.

KİT''ler bunlar için arpalık oldu.

Arpalıktan yiyen atlar çoğaldı...

Feminist düşünce gittikçe arttı,

Karı,koca hakkı raflara kalktı.

Toplum birbirine kem gözle baktı,

Nefisler kudurdu,piçler çoğaldı...

Arsızlıkta Avrupa''yı solladık,

Genç kızlarımızı övdük balladık,

Çağdaşlık uğruna soyduk yolladık,

Sahillerde çıplak insan çoğaldı...

Seyfet der bu nesle güven verelim,

Önderlik edelim,örnek olalım,

Gelin insanlığa sahip çıkalım,

Doğruluk hız kesti,yalan çoğaldı.

  14.06.1991', 'Yirminci asırın sonu gelmeden, Bataklık büyüdü,pislik çoğaldı, Demir perdeleri aralanınca, Nataşalar geldi,zina çoğaldı... Sokaklarda pazarl...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cogaldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine sen', 'yine-sen-mazlum-unlu-y8fgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neler oldu bir anda 

Tam da kalbimin pasını silmişken

Tam da kalbimin derinliğine inmişken

İçimde ki çocuk uyanmışken

Hayatı anlamışken

Ama olmuyor ki

Görmeden,dokunmadan onu hissetmeden

Sevginin anlamı olmuyor ki

Ya unutuyorsun yada vazgeçiyorsun

Ama teşekkür ederim

Çocuğum büyüdü 

-sövmeye bile başladı-

Sayende sevgiyi öğrendim 

İhaneti aldatılmayı 

Ben bunları zaten biliyordum

Neden tekrar yaşatarak öğrettin ki

Allah'' tan dilediğim odur ki

Sen de yaşayasın 

Acı çekesin

Ama seni öyle sevdim ki

Bunları da dilemedim 

Sadece sen 

Hep sen………', 'Neler oldu bir anda  Tam da kalbimin pasını silmişken Tam da kalbimin derinliğine inmişken İçimde ki çocuk uyanmışken Hayatı anlamışken Ama ...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yine-sen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzet', 'farzet-i-lknur-han-im4xn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ardına bakmadan gitmek kolaysa,

Sen beni ben seni sevmedik farzet.

Dünleri bir anda silmek kolaysa,

Gözlerin gözlerimi görmedi farzet.

Farzet başka yerlerde yabancıyız biz.

Kalmasın ne senden ne benden bir iz.

Rüzgarda savrulan yaprak misali,

Ayrı ayrı yönlere yürür gideriz.

Farzet hayalinde ben hiç olmadım.

Yüzümü gördüğünde bakakalmadın.

Damla damla yüreğine sanki dolmadım.

Ellerin ellerimi tutmadı farzet.

Albümden resimleri alıp atarsın.

Sakladığın mektupları belki yakarsın.

Ben giderken sen ardımdan bakarsın.

Gurbete düşmüş yabancı farzet.

Farzet bu odada ben yaşamadım,

Gününe gecene ortak olmadım,

Gönül yaralarını ben hiç sarmadım,

Geçerken uğramış birisi farzet.

Zaman derman olur belki sızıma,

Ne kahreder ne kızarım alın yazıma,

Alışırım bakarsın sensiz olmaya,

Ben diye birisi doğmadı farzet.

                                                          2004', 'Ardına bakmadan gitmek kolaysa, Sen beni ben seni sevmedik farzet. Dünleri bir anda silmek kolaysa, Gözlerin gözlerimi görmedi farzet. Farze...', ARRAY['Türk Edebiyatı','Şiir','İlknur Han']::text[], 8.5, '{"poet":"İlknur Han","poet_slug":"i-lknur-han","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/farzet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendin ol', 'kendin-ol-mazlum-unlu-330o5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben şimdi rahatım

Sıkıntım yok 

Derdim sadece sen

Çağlayan akarsuydum

Duruldum yoruldum 

Kafam boş

Hayat boş

Ama öyle değil 

Gerçek bu değil

Yüzleş kendinle

Ne kadar güçlüsün 

Gör bakalım

Belki başkasına sığınacaksın

Belkide başkası olacaksın sonra

Belkiide sen olmaya kendin olacaksın

Tek başına olacaksın aynı benim gibi

İşte o zaman

Kendini keşfedeceksin 

Yapabileceklerini göreceksin

İşte o zaman anlayacaksın

Kendi içinde bir krallık yapmışsın

Ve kralı da sen olmuşsun

Sen sen ol 

Her zaman

Kendin ol', 'Ben şimdi rahatım Sıkıntım yok  Derdim sadece sen Çağlayan akarsuydum Duruldum yoruldum  Kafam boş Hayat boş Ama öyle değil  Gerçek bu değil...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendin-ol-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-İçim kan ağlıyor bugün', 'i-cim-kan-agliyor-bugun-sair-ahrazi-in4dt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içim kan ağlıyor bugün

gitmek istiyorum çok uzaklara

fânusunda kaybolan bir ışığın

nasıl kalırsa ardında buğusu

öyle kalsın istiyorum bakışlarda

son kasveti boşluktaki hüznümün.

içim kan ağlıyor bugün

ölüm daha belirgin duruyor hayattan

ve nüksediyor eski bir hastalık gibi

hâtıramda senden ayrı geçmiş yılların aksi

duymamak istiyorum kendimi yarın! 

korkusu derlerdi ölümün.Hâyır! 

hissiymiş ağlatan insanı

ölmek için ayrılmış bir günün.

içim kan ağlıyor bugün

sen yoksun

kalbimdeki sevinç yok.

biliyorum:bir adım uzaklaşayım desem

isteği yok gelmeye ömrümün

içim kan ağlıyor bugün

 * * *', 'içim kan ağlıyor bugün gitmek istiyorum çok uzaklara fânusunda kaybolan bir ışığın nasıl kalırsa ardında buğusu öyle kalsın istiyorum bakışl...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icim-kan-agliyor-bugun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetimdir OĞUL...', 'vasiyetimdir-ogul-ercan-eyvaz-xk3m7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bu beden toprak olup 

Yanınızdan gittiğimde

Evimizin direği yıkıldı demeyesin

Gözüm üstünde olacak OĞUL.

Sana keselerle altın bırakamadım ama

Bir vasiyetim var, bunu iyi dinleyesin

Anneni, kardeşlerini, ondan önce vatanı milleti

Sevmektir OĞUL.

Paylaş, sadece maddiyatla değil

Manevi yönden de olsa, 

Sakın ama sakın, cimri davranmayasın.

Paylaşmak, insanlıktır OĞUL.

Varlığımda yırtık giydim, hiç giyemedim de

Aç dolaşmadık, muhtaç olmadık kimselere

Eğer sen varlığında el açar başın öne eğilirse

O zaman sana hakkımı helal etmem OĞUL

Bedenin çalışsın bırakma paslanmaya

Damlasın terlerin alnından aşına

Bunları iyi dinle vasiyetimdir sana 

Kemiklerimi sakın sızlatmayasın OĞUL

Dualarını, şükürlerini Allah’ıma eksik etmeyesin

Bunları iyi dinle vasiyetimdir

Kapına gelen her kim olursa yüz üstü bırakma

Para veremesen de karnını doyur OĞUL

Kanınla besleme kinleri kin gütme

Hırçın başakları ekme bedenin tarlasına

Fırtınalarınla onları biçmeye çalışma

Bunlardan sen sakınasın OĞUL.

Allah işini rast getirsin.

Allah’ıma emanetsiniz sonuna kadar 

OĞUL…', 'Bir gün bu beden toprak olup  Yanınızdan gittiğimde Evimizin direği yıkıldı demeyesin Gözüm üstünde olacak OĞUL. Sana keselerle altın bıraka...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/vasiyetimdir-ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik beraberlik', 'birlik-beraberlik-mazlum-unlu-1hz5z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşün bir defa Mustafa Kemali

Onun yaptıklarını 

Ya da onun bir sözüyle ölüme atılanları

Asker olmasaydı paşam ne yapardı 

Gene başarılı olabilir miydi? 

Cesareti, ileri görüşlülüğü 

Bütün liderlik vasıfları

Arkasında  kimse yokken işe yarar mıydı

Elbette hayır! 

İşte bizim işçilerimizde böyle

Paşanın askeriydi bizim işçimiz

Canını verdi asgari ücret için

Emekçi dostlarım

Kirli ellerini, yüzünü

Pasaklı giysilerini

Utanma sakın ha! 

Elin, yüzün yıkanır 

Elbisen temizlenir

 Ama ortaya çıkardığın şaheser

Senin var olduğunu, unutulmayacağını

Baki kalacağının en büyük göstergesidir 

Utanma sakın

Sen olmazsa biz olmayız

Biz olmazsak kimse olmaz', 'Düşün bir defa Mustafa Kemali Onun yaptıklarını  Ya da onun bir sözüyle ölüme atılanları Asker olmasaydı paşam ne yapardı  Gene başarılı ola...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/birlik-beraberlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazdığım', 'sana-yazdigim-suleyman-yavas-xchul', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece renk saçlarını savurunca geceye

Yıldızlar hayran bakar gökyüzünden yerlere

Güzelim gözlerinle süzersen gökyüzünü

İnan ki güneş şaşırır tersini düzünü

Mehtaplı yüzün melekleri kıskandıran nur

Bu güzellik en hisli şiirle zor dokunur

Arzdan arşa güzelliklerin sendedir özü

Yüzüne baksın merak eden yusuf bir yüzü

Nurunla kendinden geçer bütün güzellikler

Sana benzemek için dua eder melekler

Yüreğimde hiç dinmeyen aşkının sesi var

Baktığım her yerde sanki nurundan bir iz var

Sensizliği yaşarken kolay uğruna ölmek

Yeter ki mümkün olsun seni ukbadan görmek

Ruhuma yazılmış aşkın ölsem de silinmez

Benim gördüğüm seni annen bile göremez', 'Gece renk saçlarını savurunca geceye Yıldızlar hayran bakar gökyüzünden yerlere Güzelim gözlerinle süzersen gökyüzünü İnan ki güneş şaşırır ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-yazdigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözü Yaşlı Adam', 'gozu-yasli-adam-huseyin-sonmez-mxdg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben her sabah geçerim

Köprünün altından.

Akasyanın altında

Gözü yaşlı adam

Soğuk,sıcak demeden

Uzanmış yatıyor.

Yüreğime burukluk

Acıma acı katıyor.

Tutmak istesem de

Elini tutamam.

Acılarla bütünleşmiş yüreğine

Sevinç,umut katamam.

Eski bir palto,

Yırtık bir ayakkabı,

Bütün serveti.

Unutmuş sevgiyi,aşkı,hasreti.

Ağlama gözü yaşlı adam ağlama,

Anlamsız ifadelerle bakma yüzüme

Ruhundaki acıyı bana ver,

Ben taşıyayım.

Bu dünyadaki bütün sıkıntılar

Benim olsun,

Ben onlarla yaşayayım.', 'Ben her sabah geçerim Köprünün altından. Akasyanın altında Gözü yaşlı adam Soğuk,sıcak demeden Uzanmış yatıyor. Yüreğime burukluk Acıma acı ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozu-yasli-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damlalar', 'damlalar-suleyman-yavas-40d4h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Damlalar

Gökten yere inen damlalar

Arıya bal yılana zehir veren damlalar

Tohumu dipten yüzeye iten damlalar

Dirilmenin sırrını öğreten damlalar', 'Damlalar Gökten yere inen damlalar Arıya bal yılana zehir veren damlalar Tohumu dipten yüzeye iten damlalar Dirilmenin sırrını öğreten damla...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/damlalar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmak Akıl', 'ahmak-akil-huseyin-sonmez-t7noi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ahşap kaldırımlarda

Yürürken ahmak akıl,

Gökyüzündeki yıldızlara 

Bir takıl.

Denizde kabarırken

Sevgi yumağı,

Taşlar arasında bir çakıl,

Dünyada rengi bakır.

Bakırdan değersiz mi ki akıl? 

Ahşap kaldırımlarda 

Yürürken ahmak akıl

Ayağın kaymasın

Gökyüzündeki yıldızlara

Bir takıl.

Uçsun enginde

Dolaşsın düşlediklerin

Senin olsun beklediklerin

Gözünle söylediklerin,

Kalbinle duyduğun

Her şey.

Ben senin olmayacağım,

Sen kendinle dolaşacaksın

Enginde

Belki ahşap kaldırımlarda

Belki

Yapayalnız,

Belki 

Çaresiz...', 'Ahşap kaldırımlarda Yürürken ahmak akıl, Gökyüzündeki yıldızlara  Bir takıl. Denizde kabarırken Sevgi yumağı, Taşlar arasında bir çakıl, Dün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ahmak-akil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su ve Sus', 'su-ve-sus-riza-aslan1-g4tii', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağustos böceklerini

görüyorum

saz çalıyor gün boyu

kirli elleriyle

karıncalar görüyorum

ekmek taşıyorlar

incecik  belleriyle

ekmeğe koşuyorlar gün boyu

nasırlı elleriyle

ağustos böceklerini görüyorum

cazlarda

sazlarda

ekmeği emekle katık eden

karıncalar görüyorum

tarlalarda bahçelerde

bağlarda

anlaşılan

su, ağustos böceklerine yazılmış

sus,karıncaların belleklerine kazınmış...', 'ağustos böceklerini görüyorum saz çalıyor gün boyu kirli elleriyle karıncalar görüyorum ekmek taşıyorlar incecik  belleriyle ekmeğe koşuyorl...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan1']::text[], 8.5, '{"poet":"Rıza Aslan1","poet_slug":"riza-aslan1","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/su-ve-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden çıktın karşıma', 'nerden-ciktin-karsima-mikdat-bal-37ygf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımda sen hiç yoktun, ismini de bilmezdim

Nerden çıktın karşıma, aklımı aldın gittin

Bilseydim böyle zordur, bu yollardan gelmezdim

Nerden çıktın karşıma, kalbimi çaldın gittin

Memnun musun halinden, ey kalbimin hırsızı

Nasıl bir hastalık bu sevdanın en arsızı

Dayanılmaz bir acı öldürüyor her sızı

Nerden çıktın karşıma, dertlere saldın gittin

Nasıl bir yaratıksın, cin misin peri misin

Gönlüm hicran kalbimin tuzu biberi misin

Sen başımın belası ölüm haberi misin

Nerden çıktın karşıma, belalım oldun gittin

Hazan rüzgarı gibi bahar estin kışıma

Elli yaşımdan sonra ne getirdin başıma

Büyümü sihir miydi yâr ne kattın aşıma

Nerden çıktın karşıma hayalim oldun gittin', 'Aklımda sen hiç yoktun, ismini de bilmezdim Nerden çıktın karşıma, aklımı aldın gittin Bilseydim böyle zordur, bu yollardan gelmezdim Nerden...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerden-ciktin-karsima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada Kimse Var Mı?', 'orada-kimse-var-mi-huseyin-sonmez-phmup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce büyük bir gürültü

Sonra her yerde toz duman,

Gece saatin üç olduğu zaman

Birer birer kayboluyorlar,

Yıllarca emek çekerek yaptıkları,

Deli gibi severek taptıkları

Her şey kayboluyor.

Geride kalan acı,gözyaşı

Toprağın altında sırdaşı,

Kiminin sevdiği,kiminin arkadaşı

Her şey kayboluyor.

Orada kimse var mı? 

Sesimi duyuyor musunuz? 

Yoksa beni benimle bırakıp,

Gidiyor  musunuz? 

(17 Ağustos 1999)', 'Önce büyük bir gürültü Sonra her yerde toz duman, Gece saatin üç olduğu zaman Birer birer kayboluyorlar, Yıllarca emek çekerek yaptıkları, D...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/orada-kimse-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olacak Olur', 'olacak-olur-ayse-birgul-yilmaz-99mu9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevreken ayrılmak en zor olanı

Hayatın bazen zor anları vardır

Yeminler tövbeler aşkın yalanı

Unutmak bezen de yılları alır.

Bakarsın ardında kalan yollara

Sitemler edersin geçen yıllara

O yalan sevgiden her ne kalmışsa

Sarılır ağlarsın umutlarınca.

Gidende kalanda bir gün unutur

Bir yanında sabır bir yende gurur

Her şeyin bir vakti zamanı vardır

Varsa kaderinde olacak olur.', 'Sevreken ayrılmak en zor olanı Hayatın bazen zor anları vardır Yeminler tövbeler aşkın yalanı Unutmak bezen de yılları alır. Bakarsın ardınd...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olacak-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişe Bakış', 'gecmise-bakis-huseyin-sonmez-tlm6v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmişimi unutup 

Önümü göremedim.

İlmik olmuş aklımla,

Geleceği,

Bir türlü çözemedim.

Çaresizlik girdabında

Dolaşırken yapayalnız,

Ne yapacağımı

Bilemedim.

Ne seni övdüm,

Ne de yerdim.

Eskiye dönüp baksam,

O meşaleyi bir yaksam

Engelleri aşıp

Sonsuz bir hızla koşsam

Kimse beni tutamayacak.

Biliyorum

Her şey eskide.

Yeni eskisiz olmaz

Görmezsem onu,

Bu meşale yanmaz.

Yemin ettim

Onu göreceğim.

Vatanım,

Seni kimse sevmese bile

Yalnız ben seveceğim.', 'Geçmişimi unutup  Önümü göremedim. İlmik olmuş aklımla, Geleceği, Bir türlü çözemedim. Çaresizlik girdabında Dolaşırken yapayalnız, Ne yapac...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gecmise-bakis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamıda Çaldılar...', 'ruyamida-caldilar-dilan-tan-4pnix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün çarpıştım hayalinle kabusumda, 

ağlayarak uyandım bu son uykumda, 

neden saklandın  şarkımın nakaratında,

sonbaharda yapraklar gibi solmaya geldim....

deli gözlerim kör olmustu yarına, 

varamadım koymadılar yar yanına, 

rüyamıda çaldılar can düşmanıma, 

son nefeste şifa bulmaya geldim...', 'dün çarpıştım hayalinle kabusumda,  ağlayarak uyandım bu son uykumda,  neden saklandın  şarkımın nakaratında, sonbaharda yapraklar gibi solm...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruyamida-caldilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kadar Güzelsin', 'guzel-kadar-guzelsin-ayse-birgul-yilmaz-mj0aq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel kadar güzelsin dayanılmaz değilsin

Farklı olabilirsin inanılmaz değilsin

Gelgitler yaşıyorsun duyguların karışık

Ben sabır yürekliyim ulaşılmaz değilsin

Kırıklar içindesin onarılmaz değilsin

Sevgiden yaralısın kazanılmaz değilsin

3 Ocak 06', 'Güzel kadar güzelsin dayanılmaz değilsin Farklı olabilirsin inanılmaz değilsin Gelgitler yaşıyorsun duyguların karışık Ben sabır yürekliyim ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/guzel-kadar-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-huseyin-sonmez-1oq69', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buz dağıyım bir ummanın içinde,

Eriyip giderim türlü biçimde

Bir bilinmez,bir sonsuzun peşinde.

Sürüklenir,bir ses olur giderim.

Gün doğar,güneş batar giderim

Zulümle doğmuşum,ben bir kederim

Böyleymiş alın yazımla kaderim

Sürüklenir,bir ses olur giderim.

Durduramaz hiçbir kimse yazımı 

Dindiremez hiçbir kimse sızımı

Her damlam derya ile buluşur,

Umman olup,sürüklenip giderim.', 'Buz dağıyım bir ummanın içinde, Eriyip giderim türlü biçimde Bir bilinmez,bir sonsuzun peşinde. Sürüklenir,bir ses olur giderim. Gün doğar,g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giderim-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Gözlü kız', 'siyah-gozlu-kiz-i-lyas-genc-5gs6c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah bir tren..ağır ağır yol alıyor

Bir çift siyah göz..sevdiğine gidiyor

Herkes el sallıyor..kız yalnız

Yol uzuyor gittikçe..kız susuyor

Yollar yorgun,ray yorgun

Siyah gözlerin sahibi genç kız üzgün

Cama doğru eğilir vücudu hal kalmamıştır 

Bıkmıştır kıraç toprakları seyretmekten

Nereye baksa özlem

Ah şu yol bitsede sevgilimi görsem! 

Diye düşünür….

Gözlerini gökyüzüne çevirir

Siyah bulutlar beyaz bulutları kovalar,

Ortalık kararır bir yağmur başlar 

Gök gürültüsü ve şimşekler

Uzak bir yere yıldırım düşer

Rüzgar trenle yarışır,tren aldırmaz, 

Tren yoluna devam eder…..

Tünele girer tren her taraf zindan

Zaten eskiden buyana korkardı karanlıktan..

Çantada taşıdığı resmi çıkarır öpüp öpüp koklar

Aklına sevgilisinin kendisine yazdiği şiirler 

Ve adına hitaben söylediği şarkılar gelir 

Hafiften mırıldanır birer birer.

Ne çok seviyorum bir daha kesinlikle ayrılmam der 

İki damla yaş dudaklarına kadar süzülür

Kendi kendine ne uzun bir tünel der

Gözlerini karanlıklara diker uykuya dalar

Tünel biter gökyüzü susar, yağmur susar 

Rüzgar ara verir ıhtırasına bir süre esmez..

tren yoluna devam eder.

Aydınlık olur her taraf

Kız uyanır gökyüzüne bakar

Bu sefer beyaz bulutlar siyahları kovalar

Bir an gözleri gökyüzünde kalır

Düşünür, beyaz bulutlara şiir yazar

Ne kadar çok sevdiğini, özlediğini anlatır

Yine çantasında taşıdığı resmi çıkartır öper öper

Buğulanmış cama bir omuz resmi çizer

Başını çizdiği resme dayanır 

Bazen resme bakar bazen de resmi öper

Gözlerine ağırlık çöker

Tekrar Uykuya dalar

Tren yoluna devam eder

Bir zaman sonra bir gürültü kopar

Çığlıklar, ağlamalar,feryatlar, gökyüzüne ulaşır

Bulutlar dağılır ne siyah kalır nede bayaz

Yollar can pazari,raylar ölüm tuzakları

Tren raydan çıkar..

Vagonlar devrilir, insanlar yere serılır

Siyah gözlü kız bir daha uyanmaz 

omuz resmi çizip başını yasladığı cam dağılır

Kızdan geriye arada bir öpüp kokladığı resim

Ve bulutlara anlattığı sevdasinin hasreti kalır...', 'Siyah bir tren..ağır ağır yol alıyor Bir çift siyah göz..sevdiğine gidiyor Herkes el sallıyor..kız yalnız Yol uzuyor gittikçe..kız susuyor Y...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/siyah-gozlu-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Saklambaç', 'saklambac-huseyin-sonmez-08hiu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerini kapat,saklambaç oynayalım

Beni bulamayacağın yere saklanacağım.

Bulamadım diye üzülüp ağlamak yok,

Bu oyunu sonsuza dek oynayacağım.', 'Gözlerini kapat,saklambaç oynayalım Beni bulamayacağın yere saklanacağım. Bulamadım diye üzülüp ağlamak yok, Bu oyunu sonsuza dek oynayacağı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saklambac-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Senden Alıyorsa Aşkdır', 'seni-senden-aliyorsa-askdir-ramazan-ates-ab4jr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gönül gönüle aktığı zaman,

Yüreğin hızlıca çarptığı zaman,

Dillerin lal olup sustuğu zaman,

İşte ona aşk diyorlar be dostum.

Nefesin tutulup başın dönerse,

Dizlerin titreyip, kalbin çarparsa,

Gözlerin her yerde onu ararsa,

İşte ona aşk diyorlar be dostum.

Bir şey söylesen de anlamaz kimse.

Yüzün solmuş, rengin kaçmış derlerse,

Her yerde gördüğün yalnız biriyse,

İşte ona aşk diyorlar be dostum.

İçinde kıpırtı, yemeği kestin,

Yatağa gücenip, uykuya küstün,

İçini kavuran ateşe düştün,

İşte ona aşk diyorlar be dostum.

Dünya bir yana, o bir yana dersin,

Her saat her zaman onu istersin,

Hayalinde o, hep onu düşlersin,

İşte ona aşk diyorlar be dostum.

Bir yere otursan dalar gidersen,

Adını duyunca merak edersen,

Onun için ateşlere girersen,

İşte ona aşk diyorlar be dostum.

Sevdiği renkleri sende seversin,

Gezdiği yerlerde zevkle gezersin,

Onsuz kalmaktansa ölmek istersin,

İşte ona aşk diyorlar be dostum.

Ramazan Ateş/Enschede-7.1.2006', 'Bir gönül gönüle aktığı zaman, Yüreğin hızlıca çarptığı zaman, Dillerin lal olup sustuğu zaman, İşte ona aşk diyorlar be dostum. Nefesin tut...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-senden-aliyorsa-askdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma Beni Senden Çalmaya Geldim...', 'korkma-beni-senden-calmaya-geldim-dilan-tan-rtqdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yar yokluğu olmaz mı acı,yoktur ilacı

ölümüne vardım yokluğun çok acı

unutmam yıllar gecsede o gittiğin  anı, 

gidersen yüreğinde can vermeye geldim...

gözleri andım her gözün ferinde, 

sözlere kandım her sesin ahenginde, 

özlem gecenin soğuk nefesinde, 

gittiğin gecelerde unutmaya geldim…

kış geldi son güneşimin üzerinde, 

bahar korktu kaçtı çiçekler hüzünde, 

hazan bende esir yüreğim gizlice, 

emanetsin hazan dur ağlama güneşi almaya geldim…

umut cağımı kaybettim geride, 

gömdüm gece herseyi en derinde, 

yar gözlerin mutlumu başka bir yürekte, 

korkma beni senden çalmaya geldim...

yar dediğin ay ışığı gecede, 

bulamadım gözlerimde başka nerede, 

koymuştum yüreğimde bas köseye, 

nerde? 

isterse azat edeyim ölsemde… demeye geldim', 'yar yokluğu olmaz mı acı,yoktur ilacı ölümüne vardım yokluğun çok acı unutmam yıllar gecsede o gittiğin  anı,  gidersen yüreğinde can vermey...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korkma-beni-senden-calmaya-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada Kalır', 'dunyada-kalir-huseyin-sonmez-1pk2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mum alevi içinde

Siyah bir nokta,

Aydınlık buradan

Doğar,yayılır.

Bir teknede

Zevk ve kahır

Yoğrulur.

Yürekler yanar,

Kavrulur.

Bedenin her zerresi

Kimi zaman gelir

Bir kül gibi

Savrulur.

İnsanoğlu,

Geriye alınacak

Bir güzelliğe

Hep aldanır.

Güzel yüz,

Güzel kaş,

Güzel göz,

Servi boy,

Hepsi hepsi

Sadece

Bu dünyada 

Kalır.', 'Mum alevi içinde Siyah bir nokta, Aydınlık buradan Doğar,yayılır. Bir teknede Zevk ve kahır Yoğrulur. Yürekler yanar, Kavrulur. Bedenin her ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dunyada-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar...', 'daglar-dilan-tan-z8lhl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ağlarım nerde gözyaslarım dağlar, 

karlarım erir neden ben susarım dağlar, 

güneslerim doğar titrerim, 

ayaz gecelerde terlerim,

bırak omuzunda ağlayayım,

sakla doruklarında acımı, 

paylas heybetinle caresizliğimi dağlar,', 'ağlarım nerde gözyaslarım dağlar,  karlarım erir neden ben susarım dağlar,  güneslerim doğar titrerim,  ayaz gecelerde terlerim, bırak omuzu...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/daglar-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık...', 'gel-artik-dilan-tan-mt7k1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zamanı unutmuş deli gibiyim, 

yarını gören veli gibiyim, 

ben sensiz yasayan ölü gibiyim, 

dünde bıraktım hayatı gel artık...

umut söner gecenin buz hüznünde, 

söyle yarim neden yas var gözünde,

ağlıyorsun dur  gitme... 

ağladım adının her hecesinde, 

ölüm gittiğin her adımda içimde...

ölüyorsun dur gitme...

dünde bıraktım hayatı gel artık...

...', 'zamanı unutmuş deli gibiyim,  yarını gören veli gibiyim,  ben sensiz yasayan ölü gibiyim,  dünde bıraktım hayatı gel artık... umut söner gec...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-artik-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peki ya sen', 'peki-ya-sen-muhsin-yener-8jrd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çünkü insan

en çok sevdiğini düşünür soğuk gecelerde.

Ve en çok

adı dudaklarında kalan birini özler.

Ve ben 

Bir ekmek sıcaklığında,

bir çayın buğusunda,

hep seni yaşayacağım.

Peki ya sen?..

Bir vakit gece yarısı

ansızın aklına düşer miyim?

Bir yağmur camına vururken

benim adımı duyar mısın?

Yoksa

ben burada seni yaşarken,

sen oralarda

beni yavaş yavaş unutur musun?..

Muhsin yener', 'Çünkü insan en çok sevdiğini düşünür soğuk gecelerde. Ve en çok adı dudaklarında kalan birini özler. Ve ben  Bir ekmek sıcaklığında, bir çay...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/peki-ya-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Sureti: Çakırgız', '12-bir-adam-muzesi-sureti-cakirgiz-ahmet-yozgat-wsonj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Çakırgız derdik biz ve pınar başları ona.

Kışın bile yalın ayaklarıyla yalardı karı.

Parmak aralarında kıvrılarak çıkar

Ve kurtçuk kurtçuk olurdu ilkbahar çamurları.

Sonbahar akşamları kaybolan sarıkızını arardı 

Azalan aydınlığında sokakların.

Mor yamalı peşini sokardı her daim

Üç eteğinin Antep işi kınalı kuşağına.

Yaşına erişilmezdi asırların harmanında

Gezerdi onunla ardını bırakmayan geçmişi.

Gözleri bulutsuz gökyüzü gibi mavi

Lenger yüzü kalaysız bakır gibi kırmızıydı

Eşini hiç sormayın, deli dolu biriydi.

Ama yine de vurgunuydu karısının

“Çakır” dedimiydi bir daha çıkardı ağzından

Vaz geçmesi ne mümkün Anşa’sından

Bir de alt dudağına yapışık Bafra artığı cigarasından.

Anlaşılan tam ortasından vurmuştu Çakırgız 

Delidolu kocasının doludizgin yüreğini.

O işte buydu:

Masmavi gözleriyle akardı esrik gönüllere.

Çakırgız sayın ki bir bengisuydu...

B/...

Çakırgız derdik biz ve bulgur imeceleri ona.

Yitirdiği umutlarını arardı belki boş harmanlarda.

Belki de bereketsiz geleceğini karatoprakta.

Nasırlı ellerini bağlardı birer dirgen ucu gibi

Asla eğilmeyen doksan derece bükük beline.

Eline yaralı ve sevdakeş türküler yakardı.

Yüreğine Yemen işi allı kına...

Ama kendimi içerdi bilmem

Çorak yüzüyle delidolu kocası mı yoksa.

Hep cıgara cıgara kokardı.

Çakırgız derdi geçmiş asırlar ona

O yalnız Çalap’tan korkardı.

Bir gümüş çiğ düşmüş sabahleyindi

Çaldı yüreğinin kapısını Çalap, Çakırgız’ın

O gece bütün köylüler gördü gökyüzünde

Kayıp gittiğini masmavi bir yıldızın...

***

Çakırgız şiirinin meraklısına dipnot: 

İlk çocukluk anılarımda kalan yaşlı bir nineydi Çakırgız. Adı Ayşe ya da Anşa idi. Çakır Anşa olarak da biliniyordu köyünde. Çakırlığı gözlerinin mavi rengindendi sanırım. Kocasının adı Kadir’di. Namı diğer Deladir. Deladir emmi karısına düşkün bir adamdı herhalde. Bu yüzden evinden pek ayrı kalamazdı, diye anlatılır söz açıldığında. Şimdilerde de, o yörede uzun gurbet hayatı çekemeyen kişilere “Deladir gibi” yakıştırması yapılıyor. Çakırgız’ın bir oğlu vardı bildiğim kadarıyla. Kızı var mıydı, bilmiyorum. Çakırgız’ın oğluna Deladir’in Osman abi  diyorduk biz köy çocukları. O da babası gibi komik bir adamdı. Çakırgız’ın fotoğrafı doksan derece  bükülmüş beli ile kalmış belleğimde. Bir de yaz kış yalın olan ayaklarını anımsıyorum. Çakırgız yetmişli yılların birinde göçtü bu dünyadan. Şimdi ardından bir Fatiha bekliyordur sanırım.', 'A/... Sahici adı her ne ise unuttum Çakırgız derdik biz ve pınar başları ona. Kışın bile yalın ayaklarıyla yalardı karı. Parmak aralarında k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-sureti-cakirgiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün olur', 'gun-olur-muhsin-yener-xc1js', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün olur...

Olmaman gereken bir yerde bulursun kendini.

Gün olur...

Etmemen gereken bir laf çıkar dudaklarından.

Gün olur...

Vermemen gereken bir sözü,

Hiç düşünmeden verirsin.

Gün olur...

Aklına ihtiyacın olmadığını sanır,

Yönünü duygularına çevirirsin.

Ve gün olur...

Duygularının sesini dinlerken,

Duygusuz insanların

Sofrasında bir meze,

Dillerinde bir hikâye olursun.

İşte o gün,

Kendine dönüp sorarsın:

Madem gün bugündür,

Madem yaşanacak olan

Tam da şu andır...

Sen beni,

Benim seni sevdiğimden

Daha çok sevebilir misin?

Muhsin Yener', 'Gün olur... Olmaman gereken bir yerde bulursun kendini. Gün olur... Etmemen gereken bir laf çıkar dudaklarından. Gün olur... Vermemen gereke...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gun-olur-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Portresi: Omşemmi', '12-bir-adam-muzesi-portresi-omsemmi-ahmet-yozgat-z3aes', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Omşemmi derdik köylük yerin ahalisi biz ona.

Ama “Omşemmi” derken üşürdük

İliğimize kadar temmuzun alazında.

İnansanız da inanmasanızda

Ona vız gelir, tırıs giderdi ayaz

Mevsim ha yaz, ha kış olmuş, aldırmazdı

Ayakları yalın, yüreği yalbırdak gezerdi

Kütür kütür buz kesen köy sokaklarında.

Buzlarla el sıkışmıştı zemheri gözesinde

Kutuplarla sarmaş dolaş ahbaptı sanırım.

Tanrım! O ne iri cüsseydi.

Bir üfürseydi bulut bulut örülen dağlara

Ağustosta bile dişli karlara bir hal olurdu.

Ulur gibi dururdu zemheri buzgöbeği göğsünde.

Üstünde döşü yırtık öksüz ama çiçekli mintanı

Altında çemrik paçalarıyla

Kasığına kadar “karamandul suvari” vurulmuş

Zile işi şeytan kadifesinden şalvarı aha bugünkü gibi

Kahverengi gözlerimin önünde.

Dibi delinmiş, yetim yaşamı,

Soğuktan kan kızılı usturalara doğranmış yanakları

Ve dinine yandığım yoksulluğuna rağmen

yüreğindeki kanı Omşemmi’nin bereketli bereketli akardı 

Omşemmi derdi bildik bilmedik herkes ona

Bir yanı işaret parmağı gibi ayaktaydı

Bir Hitit kenti gibi yıkıktı onun öteki yanı.

B/...

Omşemmi derdik biz ve keçe kepenekler ona.

Girmemişti hiçbir zaman zifafa ilikleriyle

Gömleğinin üst dört düğmesi

Yaz kış açıktılar sonuna kadar.

Mintanının aralığından kırçıl kılları döşünün

Ayrık  otları gibi uç atardı şemsikamerleyin güneşe

Ve şaşkın gözbebeklerime çocukluğumun.

Omşemmi derdik biz ve tarla kesekleri ona.

Topraklarla el sıkışmıştı bir savaş ardından

Çoraklarla kanlı bıçaklı ahbaptı sanırım.

Tanrım! 

Neden obruk yaylaları gibi yarılmıştı yanağı.

Dururdu karakışın dudaklarında üfür üfür

Şakaklarında buzdan cembelle gibi şeytansidiği

Ağzından her daim köpeköldüren bir izmarit 

Yani kederli Bafra cıgarası sarkardı.

Omşemmi derdi bilcümle yeryüzü ona

O biz çocuklara yaslı yaslı bakardı...

C/...

Omşemmi derdik biz ve kruvaze kasketler ona.

Hafif kaykık dururdu yara izi taşıyan sağ kaşı

Ve bir başka savaşta rengi ölmüş zavallı şapkası

Ve bir de Muş tütününden dolanan cıgarası

Uç uca eklenirdi bulutların altında.

Reci’yle el sıkışmıştı

Tekel ile ahbaptı sanırım.

Tanrım! O ne tiryakilikti? 

Sayın ki zırdelilikti.

Dururdu kuyruğu kısa şubatın buzlu kırığında

Bir kuzeyli vandal gibi ellerine duman hohlardı.

Vız gelirdi zemheri Omşemmimize

Vız gelirdi karakış.

O yalnız yüreklerin soğuğundan korkardı...

Omşemmi derdi tekel idaresi bile ona

Kulağının ardına çifte “Bafra” sokardı.

Ç/...

Omşemmi derdik biz ona

Ve bir gün...

Çok gerilerde kalmışken yoksul yaz

Hava dinine kadar ayaz mı ayaz

Salkım saçak buzken kasım güneşi

Minareden su sal’ası verildi.

“Eyvah devrildi Omşemmi! ”

Upuzun ve sakin toprağın yar gibi yatağına.

Öksüz kalan kalpağına oğlu sahip çıktı.

Kızı da yamalı yün abasına.

Umur görmüş karısına hiçbir şey...

Yoktu ki başkaca terekesi

Hey gidi delikanlım Omşemmim hey! 

Omşemmi derdi topraklar sana

Maraba geldin nankör feleğe ve ırgat gittin

Ne ağa olabildin ne de küçük bir bey

Hey ulan hey...

***

Omşemmi şiirinin meraklısına dipnot:

Cebirler, Omşemmi’nin sülalesinin adıydı. Bu ad onlara yoksulluklarından verilmişti sanırım. Omşemmi’nin asıl adı ise Omar’dı. Yani Ömer’in galatı. Çalışkan bir çiftçiydi. Öküz koşardı. Yaz kış toprakla uğraşır, yarıçıplak dolaşırdı. Hiç “Üşüdüm,” dediğini duymadım. Yoksulluğuna rağmen “Şunum yok, bunum yok,” dediği de gelmedi kulağıma. Ama sık sık sigaraya gereksinim duydu gibime geliyor. Çünkü onun sigara tüketişi leblebi yemek gibi bir şeydi anımsadığım kadarıyla. Günde birkaç paket... Yanlış değilse üç oğlan babasıydı Omşemmi. Oğulları Fransa’da oturuyor ve çalışıyorlar şimdilerde. Omşemmi, oğullarının kazandığı para ile yaşamına giren zenginliğe bakıp hayıflanır: “Anam kalksa da şimdiki halimizi görse,” dermiş, işittiğime göre son demlerinde. Omşemmi seksenli yılların birinde usulca göçtü dar-ı  dünyadan. Ardından bir Fatiha bekliyordur sanırım.', 'A/... Sahici adı her ne ise unuttum Omşemmi derdik köylük yerin ahalisi biz ona. Ama “Omşemmi” derken üşürdük İliğimize kadar temmuzun alazı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-portresi-omsemmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz kesmiş dünya', 'buz-kesmis-dunya-ahmet-sali-mjyhl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırakılmış hüzün

Bir soğuğun ortasına

Eritsin buzları diye..

Bırakılmış muhabbet 

Bir hüznün ortasına

Yeşertmeyi başarsın diye..

Bırakılmış sevgi

Bir yeşilliğin ortasına 

Gülleri açsın mutluluğun diye..

Kopartmışlar gülleri 

Boğulmuş sevgi

Mutluluğun selinde..

Karartmışlar yeşili,

Küllenmiş muhabbet 

Derin bir yokluk içinde...

Yoketmeye kalkmışlar hüznü

BUZ KESMİŞ dünya...', 'Bırakılmış hüzün Bir soğuğun ortasına Eritsin buzları diye.. Bırakılmış muhabbet  Bir hüznün ortasına Yeşertmeyi başarsın diye.. Bırakılmış ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Salı']::text[], 8.5, '{"poet":"Ahmet Salı","poet_slug":"ahmet-sali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/buz-kesmis-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12Bir Adam Müzesi Sureti: Tevgenişte', '12bir-adam-muzesi-sureti-tevgeniste-ahmet-yozgat-czpmo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Tevgenişte derdik köyde hepimiz ona.

Adı neydi? Tevgenişte ne demekti? 

Hala bir bilmece gibi belleğimde.

Kaderi gibi yanık ve mısır koçanı yüzü

Rengini yitirmiş kasketinin altında

Kahverengi bir Kafkaslı fotoğrafı gibi dururdu.

Öylesine eski, öylesine soluk ve sakin

Öylesine razı ve teslim alınyazısına...

Ne oğluna, ne kızına ne de karısına

“Höt! ” bile demedi Tevgenişte.

Ha vardı bir gölge misali ya da yoktu

Bu bir yanı inadına kalabalık dünyada.

Sayın ki yeşillenerek yaşamadı Tevgenişte.

Bir göründü soluk bir yıldız gibi, 

Bir Yunus Emre garibi gibi kayboldu

Kısacık, ıssız ve soluk bir rüyada...

B/...

Tevgenişte derdi sigara bulutları ona.

Anasının göğsüne yatan bebe misali

dayardı Tekel’den dolanan Bafra cıgarasını

Her daim çatlak ve suskun dudaklarına.

Arada bir de çamurdan evcikler yapardı.

Galiba Tevgenişte çamura yüreğini katardı.

Tevgenişte derdi Kazan muhacirleri ona.

Uzak bir diyara aitti göçebe ceddi.

O gözleri tarihin doksan üçüne çekik

Ve yapayalnız bir muhacir Tatar’dı.

Atardı abasını yıldızlık mavilikler altına

Zavallı ve yapayalnız Tevgenişte

Issız ve ıtır kokusuz bir odada

Rüyalarında bile tek başına yatardı.

Tevgenişte derdi geceler bile ona

Bir tutam şekerine iki tutam tuz katardı.

C/...

Tevgenişte derdi hüzünlü gurbetler ona.

Tek başına bu darıdünyada

Özlem ile arkadaş, hasret ile ahbaptı.

Tarlaların bulanık bereketini kavrardı

Günboyu, nasırlı ve yanık elleriyle.

Soyunur akşamları gurbet ile yatardı.

Tevgenişte derdik biz ona

O içine akıttığı acısına pekmez katardı...

Tevgenişte derdi puhu kuşları bile ona

Çünkü o yapayalnız bir Tatardı.

Ç/...

Tevgenişte derdi gri alın yazıları ona

Nedense eylemedi onu felek

Sonu iyi gelen kullarından.

Orta karar yaşamından gün görmedi.

Eşinden ve çocuklarından hakeza...

Gülmüşse bazen. Eskaza

Alel acele af dilerdi kaderden

Ve gözlerine sinmiş yaşlı ve yerli kederden.

Tevgenişte derdi boynu bükük takvimler ona.

Kırıldı kaleminin yassı ucu bir güz günü.

Düğünü gibi sükûnetle yani usulca.

Ne el sallandı ardından, ne bir oyalı mendil

Ne de döküldü tek damla gözyaşı

Ne sulbû ne de bir arkadaşı...

Geldiği gibi üryan gitti Tevgenişte

Sayın ki bitti başladığı yerden 

Yeşilçam’da üçüncü sınıf ve siyah beyaz bir film.

Sahici adı her ne ise unuttum

Tevellütü ne idi ömürler skalasında

Ya da kaç idi yaşı? ...

Devlet sırrı gibi gark oldu toprağa

Ama dağlar gibi her daim dumanlıydı

o yalnız ve solgun Tatar’ın başı...

***

Tevgenişte şiirinin meraklısına dipnot: 

İlk anımsadığım şey öldüğünde on kasım olduğuydu. Adı Tevfik’ti. Köy ağalarından birinin nazlı kızını aldığı için tüm köylünün eniştesi olmuştu. Bu yüzden herkes ona Tevgenişte yani Tevfik enişte diyordu. Doksan üç harbinde Tataristan’dan Anadoluya göç etmiş bir ailenin büyük oğluydu. Babası derin bir imamdı: Hamdi hoca... Tevgenişte seksenli yılların ilk yarısında toprağa düştü. Şimdi ardından bir Fatiha bekliyordur sanırım.', 'A/... Sahici adı her ne ise unuttum Tevgenişte derdik köyde hepimiz ona. Adı neydi? Tevgenişte ne demekti?  Hala bir bilmece gibi belleğimde...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/12bir-adam-muzesi-sureti-tevgeniste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12Bir Adam Müzesi Sureti: Hocemmi', '12bir-adam-muzesi-sureti-hocemmi-ahmet-yozgat-x3eg3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Hocemmi derdik biz ve ciltli kitablar ona.

Gırtlağına kadar seferberlik harb’içinde

Ve nankör çakır dikenleriyle boyboyaydı.

Beynine ekip Evamil dizelerini

Ikhzar üflerdi mescit duvarlarına.

Baş köşeydi köy odasında her daim yeri.

Siyeri Nebi’lere dalardı tevekkel ikindilerde.

Boş yürek tuvallerine Uğru Abbas çizerdi

Hocemmi, bedeni çorak toprağa yapışık olsa da

Ruhu ta diyar-ı teberlerde gezerdi.

Hocemmi derdi tüm ezoterik tarihçe ona.

Konuşanda dünyalık söyler

Düşünende kozmik kozmik sezerdi.

B/...

Hocemmi derdik biz ve Necid çölü kumları ona.

Kalın ciltleri yığıp odasının orta yerine

Çekip kınından sahtiyen kaplı Tarih-i Siyeri

Sürerdi dudaklarını doludizgin diyarı küfre.

Sonra Hikaye-i Kesikbaşı yuvarlar

Ve Hikaye-i Güvercin uçururdu havaya.

Sonra Hikaye-i Geyik kovalardı çöllerde.

Ve ururdu yankı yankı duvarlara

Hikaye-i Merdi Meydan narasını.

Hayber kal’asını alan orduda bir nefer

Tebuk seriyyesine sefer olurdu.

Önü bizden yana üfürüktü Hocemminin

Cebeli Uhut’a dayardı arkasını.

Hocemmi derdi simyayı kadim ona.

Koşum koşum küheylan atları

Tarlada marabaları ve ırgatları vardı.

Amma severdi o

Bir yamalı dervişan hırkasını.

C/...

Hocemmi derdik biz ve kutlu cengaverler ona.

Özlemle kınalardı dilini Zülfikar’ın

Rivayet ve hikayet eylerdi eskileri

Ceng-i Mute’ye uğrayıp bir solukta

Sonra uzanırdı toprak tuğlalı Kan Kalesi’ne

Muhammed Hanefi’yle arkadaş

Güvercindi Ceferi Tayyar’ın kanadında

Şu yanında Uğru Abbas risalesi

Diğer yanında içmek için seherinde sabahların

Hazırdı Arabi Muhuddin’in Fusûsu Hikem kasesi

Hocemmi derdi Endülüs ve Granada ona

Uymak üzre sünneti resule

minnacık bir yama taşırdı elbisesi...

Ç/...

Hocemmi derdik biz ve Bağdatlılar ona.

Ne zaman diz yıksak yaşlı rahlesinin eteklerine

Dalardık Tarıkı Ziyad gibi Endülüs’e 

Ve binip eğri develere uğrardık cengi Sıffin’e.

Kükrerdi esadullah misali Hocemmi

“İmana gel ya kafir! ”

Ve iman tazelerdi bir bir bilcümle karî.

Bin bir şükür ve tefekkürle kapardı

Kufi bir besmele hattıyla açtığı

Sahtiyan kapağını kadim kitabın Hocemmi.

Sonra aralardı sufiliğin gnostik penceresini

İbni Arab’ın Füsus deryasına dalardı.

Salardı perisperisini

Vahdeti vücut felsefesine

Bir damla Hallaç doldurup kasesine.

Hocemmi derdi sülus kitaplar bile ona.

Yaşadı, cümleden saygı gördü

Öldü “El Fatiha! ” yazdırdı esamesine...', 'A/... Sahici adı her ne ise unuttum Hocemmi derdik biz ve ciltli kitablar ona. Gırtlağına kadar seferberlik harb’içinde Ve nankör çakır dike...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/12bir-adam-muzesi-sureti-hocemmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım Çoktandır Seni', 'ararim-coktandir-seni-yavuz-agir-ny17y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlara sorarım acep tanırmı seni

Acılar bir bir yoklar üzermi  seni

Hiç merak etmezmisin a canım beni

Barim köydeki çınara sor beni beni

 Çiçeğe sorarım acep bilirmi seni

 Umut çemberine dolarım seni

 Aşkın şarabını mahsende sakladım

 Koy kadehine iç beni beni...', 'Dağlara sorarım acep tanırmı seni Acılar bir bir yoklar üzermi  seni Hiç merak etmezmisin a canım beni Barim köydeki çınara sor beni beni  Ç...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ararim-coktandir-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12Bir Adam Müzesi Sureti: Gövşanacı', '12bir-adam-muzesi-sureti-govsanaci-ahmet-yozgat-9rs20', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Gövşenacı derdik biz ona.

Bir çökelekli dürümünü kilimden bozma çantasında

Bir de uslanmaz anılarını taşırdı.

Yekinmeden daha güneş dağların arkasından

O yekinirdi kırk yamalı pazen yatağından.

Besmele ile tutardı yolunu umudunun.

Selamını emanet edip komşularına.

Biz ise ona

Demediğimizi bırakmaz uzaktan

Yakından çalışkanlığına türküler yakardık.

Gövşenacı derdi elmalar ve erikler ona.

Çiftetelli oynatırdık bıyıkların altına

Biraz müstehzi müstehzi bakardık.

B/...

Gövşenacı derdik biz ona.

Yırtık göz kapağıyla bir kimmeryalı gibi ürkütücü

Sevecendi bal akan dudağıyla.

Mavi mavi delerdi lazerli bakışları

Rüyalarını ve yüzünü toprağının.

Yapayalnız tırmansa da dağlara

Yanı başındaydı onun sıcacık hayalleri

Her yerde ve her daim.

Kaybetti küçük bir çanta gibi yanında taşıdığı 

Güzel çirkin arası kadınını bir pazartesi.

Kaybetti Leyla’sını.

Ama asla Gövşenacı

Yitirmedi o yeşil ve varlıklı hülyasını...', 'A/... Sahici adı her ne ise unuttum Gövşenacı derdik biz ona. Bir çökelekli dürümünü kilimden bozma çantasında Bir de uslanmaz anılarını taş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/12bir-adam-muzesi-sureti-govsanaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12Bir Adam Müzesi Sureti: Hatınaba', '12bir-adam-muzesi-sureti-hatinaba-ahmet-yozgat-unoxj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Hatınaba derdik biz ona.

Herkesin Hatınaba’sıydı.

Elleri ince ve uzun

Zülüfleri kıvrıktı yay gibi.

Evdeşiyle kırıktı sanırım.

Gündüzleri herkesle hemhal

Geceleri yalnızdı hatınaba ay gibi.

Gelinler ondan sorardı geciken günlerini.

Tay gibi kızlar ona danışırdı

Sonbahara söz kesilen düğünlerini.

B/…

Hatınaba derdik biz ona.

Kız, kısrak, kadın, erkek

Yani bilcümle kişi

“Hatınaba” derdi Hatınaba’ya.

O çıktı mı yaylaya

Sökün ederdi ne varsa dertten yana.

Bir tabip gibi şikayet dinler.

Bir hekim gibi ilaç yazardı.

Ve inanmayacaksınız ama

Onun yazdığı yarımyamalak reçeteyi

Ne doktor çızardı, ne de cerrah bozardı.

Hatınaba’ydı o

Buldu herkese çaresini

Ama kendine bulamadı.

Öldü ince bir hastalıktan

Ardınca herkes ağladı...', 'A/... Sahici adı her ne ise unuttum Hatınaba derdik biz ona. Herkesin Hatınaba’sıydı. Elleri ince ve uzun Zülüfleri kıvrıktı yay gibi. Evdeş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/12bir-adam-muzesi-sureti-hatinaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Sureti: Akfabi', '12-bir-adam-muzesi-sureti-akfabi-ahmet-yozgat-xotrb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/...

Sahici adı her ne ise unuttum

Akfabi derdik biz ona.

Latince’yi ilk belleyendi Akfabi.

Kozayı ilk yırtan yani.

Sayın ki müderristi medresede.

O bilse de bilmese de

Her bir mesele zatına danışılırdı.

Akfabi derdi herkes ona.

Bize göre bilgisi tamdı onun

Yani maşallah akîl bir adamdı.

2/...

Akfabi derdik biz ona

Gençliği doludizgin küheylandı...

İçkide saki, kumarda erkete

Herkese “mim tuttururdu” iskambilde.

Gecesi haramîydi onun doludizgin

Gündüzü ise hazinede talandı.

Yarış atları gibi koşardı düğünden düğüne.

Güldüğüne gelinler yanardı

Ağladığına amcası...

Babası bir cinayet vurgunuydu.

Akfabi

Galiba bir tek onun yorgunuydu.

3/...

Akfabi derdik biz ona.

Gençliği onun

Ne kadar küheylan gibi doludizginse

Erişkinliği o kadar durgun suydu.

O, ele avuca sığmaz

Yani kuş uçurtmaz

Ve yüreğinden kervan geçirtmez adam

Tam orta yerinde anaforun

Vuruldu bir prangaya.

Eli çekildi,

Ayağı döküldü çılgın halayın ortasında

Sayın ki bir kalyon oturdu karaya.

Akfabi derdi Roma’ya gidn yollar ona.

Memuriyet bile dizdi tespihine hayatın

Yılları saya saya gına içinde.

4/...

Sahici adı her ne ise unuttum

Akfabi derdi çılgın geçen takvimler ona.

Amca olduğunda Akfabi

Yani saçlarına kırağı

Kalbine ölüm izi düşende...

Serdi pişmanlık seccadesini

Kederli kaderinin üstüne.

Ne geçmişe mil çekti

Ne geleceğe çiçek...

Karlı bir kış zemherisinde

Soğuk tandırlara harlı bir haber düştü.

Oğlu, kızı, dostu, düşmanı

Çember çember çevrildi çevresi

Başucuna pervaneler üşüştü.

En çok azrail’den korkardı

En az ona direndi.

“Yaşa be Akfabi! ” derdi hayat ona

Yalnızca ölüme yenik düştü.', '1/... Sahici adı her ne ise unuttum Akfabi derdik biz ona. Latince’yi ilk belleyendi Akfabi. Kozayı ilk yırtan yani. Sayın ki müderristi med...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-sureti-akfabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Fotoğrafı: Ziyamabi', '12-bir-adam-muzesi-fotografi-ziyamabi-ahmet-yozgat-euoht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Ziyamabi derdik biz ona.

güneş çıkmadan daha bal kokan kovanından

o sıyrılmış olurdu kınından kılıç gibi.

Doldururdu tandır yanığı yufkasının arasına

Hançer kesmez tam yağlı koyun yoğurdunu.

aklını belki yediği yoğurtlara borçluydu

belki de babasından devraldığı zengin genine.

engine uçururdu rüya kuşunu çünkü Ziyamabi.

bazen yağmurlu bulutlarda yüzerdi.

bazı konardı turkuvaz denizlere.

bizlere beşi beş kuruştan akıl satardı.

Ziyamabi bir kişi gibi görünürde

Görünmezde Berlin’den Kurtalan’a

Upuzun ve kalabalık bir katardı

Farkında olmasa da kendi

“Kepenek altında aslan yatardı.” 

B/...

Ziyamabi derdik biz ona.

İnadına ve ta yürekten severdik.

ne mümkün onsuz olmak

ve imkânsızdı o yoksa hayal kurmak.

Ziyamabi bir derviş gibi uzak bu dünyaya

Kasketi kaykık bir berduş gibi yakındı.

Koyun gözü şiir yazardı hayatının enine

Uzununa patates burunlu resim yapardı.

Hatta bir ara sanırım

mızrabına yandı bağlamanın.

yani sanatın binbir gecesine abandı

kulaçladı kendini gurbet denizinin derinliklerinde

Ellerinde mor bir kınası Bozok yaylalarının

Sürmeli bozlağı dudaklarında

Ziya’nın atı gibi dolandı

Ziyamabi bedenini hor kullandı

ve hep zorladı beynini.

Kendinin Macellan’ı olamadı...', 'A/... Sahici adı her ne ise unuttum Ziyamabi derdik biz ona. güneş çıkmadan daha bal kokan kovanından o sıyrılmış olurdu kınından kılıç gibi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-fotografi-ziyamabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Anası: Havseme', '12-bir-adam-muzesi-anasi-havseme-ahmet-yozgat-vp3a1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/...

Sahici adı her ne ise unuttum,

Havseme derdik biz ona. 

*** 

Bir kimsesiz yetim kız,

Havseme bir öksüzdü çocukluğunda.

Belikleri aylarca çatılıydı, bakıcısızlıktan.

Haktan gayrı kimesnesi... 

Esnemesi uykusuzluktan değil, annesizliktendi.. 

Sırtındaki keten gömleği yamalı ve bi tekti

Belindeki “bıldırdan” kalma, çiçekleri solmuş etekti...

Gözlerinin gök–alası bulutlara yansırdı öksüz kızın.

Alabora olurdu, mazlumlar dolu mavnalar düşlerinde.

Sadece alnının burcuna, sevenleri yitik martılar konardı

Ve hüzünlü kirpiklerinin en uzununa anka kuşları. 

Masallarda, çöllerde yalınayak, 

Başı kabak köy hikayelerinde,

Yalın yalbırdak koşan yok olan umudunun ardınca,

Kadınca bir devinimdi onunkisi de işte, 

Her işte tek başına ve sadece oydu sofra başında,

Yedi ya da dokuz yaşında henüz,

Yani daha havseme olmadığı yıllarda

Ak düştü kumral saçlarına 

Ve garibimin turkuvaz umuduna, 

Acımasız ayaz...

2/...

Sahici adı her ne ise… Boş verin be ağalar

Zaten Havseme de yaşlı bir ağaya gelin gitti.

Bitti yeşil rüyaları, pembe hayalleri evrildi

Devrildi bir alaca akşam üstünün hüzünlü külrengine.

Daha birinci yılında bir oğlan doğurdu.

Sonra bir bir daha havseme...

Sabahını dürüp ömrünün

İkindide başladı kalanına.

Ve kahırlı bir akşamın alacası düştü

Yaşlı ve yaslı döşeğine.

Menencitten saldı erini dönülmez yola.

Darı dünyada yapayalnız kaldı.

Yeni hayaller ördü havseme çaresiz

Küçük ve çalkanan yeni marmara’sına daldı...', '1/... Sahici adı her ne ise unuttum, Havseme derdik biz ona.  ***  Bir kimsesiz yetim kız, Havseme bir öksüzdü çocukluğunda. Belikleri aylar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-anasi-havseme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Denizcisi: Alreyiz', '12-bir-adam-muzesi-denizcisi-alreyiz-ahmet-yozgat-449l1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Alreyiz derdik biz ona.

İnadına denizciydi, inadına balıkçı.

Kaçı devirmişti tevellütü kendi de bilmiyordu.

Tütün içiyordu boyuna

Sonuna kadar çilingir...

Bakışları kendinden çok uzaktı.

Sarkıktı sararmış bıyıkları

Ta... Toprağı süpürüyordu.

Alreyiz diyordu martılar ona

Çıkanda hamsi avına

Denizden balık kürüyordu..

Kısmeti salt bereket alreyiz

Dırahoması uskumru hamsisi çeyiz...

B/...

“Alreyiz” derdik biz ona.

O bize “yegen...”

Suret dörtgendi onda

Yürek ise kaplardı bütün geometriyi.

Avcunun içi gibi bilirdi tüm marmara’yı

Boydan boya ege’yi.

Uskumruyu ve levreği

Yani bilcümle derya kuzularını

Gözlerinden tanırdı.

Sertti volkanda granit kadar

Ama çukurovada pamuk kadar yumuşacıktı.

Ne zaman bir pot kırsa potundan utanırdı.

Alreyiz diyordu ya hamsiler ona

O diğergam biriydi, her şeye katlanırdı...

C/...

Sahici adı her ne ise unuttum.

Zaten o da öz adı gibi kayıptı.

Ne geçmişi arı duruydu

Ne de geleceği apak.

Hamsi buğulama yaparak

Devirirdi tüm akşamları...

Devletle işi olmazdı, resmiyetle hakeza

Eskaza bir “kafakağıdı” gerekse

Herkese açılan kapılar ona kapanırdı.

Çünkü yoktu ki kaydı “kuydu”...

Yurdu uzak bir noktaydı haritada

Memleketi dalgalı derya...

Ç/...

Alreyiz derdik biz ona.

En sona onun teknesi peyda olurdu

Gözlerimize yansıyan ummandan.

Dayardı gürgenden küpeşteye

Bir camgöze ısırılmış elini.

Gözlerini diken eder batırırdı

Nöbete çıktığımız iskeleye.

Sonra “Meraba yegenler” derdi.

İlk önce bize verirdi kısmetinin zekatını

Sonra alışkın martılara...

Alreyiz derdi denizler ona.

Biz de öyle derdik.

Günlerden birgün bekledik bekledik

Ama ne yazık ki katarda göremedik...

D/...

Gerçek adı neydi onun

Bir bilen yoktu.

Alreyiz derdik biz ona.

Denizler öyle derdi, martılar öyle...

Bir av dönüşünde

Balıkçılar mahzun, tayfalar yaslı

Miçolar som acıya kesmişti.

Sormuştuk biz

Seferden dönen en yaşlı denizciye

“Alreyiz nerde? ” Diye.

“Deniz aldı” demişti.

Sayın ki cümlemizin yüreğini delmişti...', 'A/... Sahici adı her ne ise unuttum Alreyiz derdik biz ona. İnadına denizciydi, inadına balıkçı. Kaçı devirmişti tevellütü kendi de bilmiyor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-denizcisi-alreyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-serhat-caliskan-uahet', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine yazmıştım,engüzel şiirleri

O''gözler bana hiç aşık olmadı

Saçlarında söndürdüm,koskoca güneşi

O''güneşki birdaha yüzüme parlamadı

Yoksulluğun sınırında son çırpınışım

 Bu ilk kavgam değil kahpe kaderle

Katil eder insanı hain gülüşler

Bu ilk vedam değil,mutlu günlere

Yaklaş biraz ayyüzlüm öyle uzaktan  bakma

Yabancısı değilim gözlerinin

Tanışıyoruz insanlıktan

Kim olduğumu  sorma

Bu baskılar altında öğrenemezsin', 'Gözlerine yazmıştım,engüzel şiirleri O''gözler bana hiç aşık olmadı Saçlarında söndürdüm,koskoca güneşi O''güneşki birdaha yüzüme parlamadı Yo...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerin-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Emekçisi: Demircemmi Hamparsı', '12-bir-adam-muzesi-emekcisi-demircemmi-hamparsi-ahmet-yozgat-tfsrc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Demircemmi derdik biz ona.

Kalın ve kıllı bilekleriydi

Çocuksu gözbebeklerimize ısmarlanan.

Her daim  açık göğsünden

İlkbaharleyin fışkıran neydi? 

Çimen mi? Çiçek mi? 

Yoksa gözlerimize batan diken miydi? 

Omzu öyle geniş

Sayın ki bir ucu mağrip’te

Diğer ucu maşrıp’ta.

Sanki bizim demircemmi

Masallardan fırlayan bir devdi.

Demircemmi derdi çocuklar ona

O hepimizi severdi...

B/...

Demircemmi derdi körükler ona.

Kıvılcımlar ekerdi karanlık geceye karşı

Gündüz çiçek çiçek açılsın diye.

Hayalleri pembe şerare

Balyozu som demirdendi.

İpek ipek burulurdu elinde her şey.

Daldırınca ham demiri ateşe

Ne ateş kalırdı, ne demir.

Hey gidi hey! ..

Onun dövdüğü sadece ömürdendi.

Sahici adını unuttum ama

Dünyası demircemminin

Kor ateş ve marsık kömürdendi...

C/...

Sahici adı neydi bilmem

Ama

Dükkânı dumana keserdi günboyu.

Körüğü nefes nefese.

Elinde kocaman bir çekiçle

Durmadan dan, dan, dan! ..

Daha güneş doğmadan

Başlardı onda canlılık.

Delikanlılık ise babadan kalıktı.

Yüreği tenhaydı demircemminin

Amma dükkanı kalabalıktı...

Sahici adı her ne ise unuttum

Demircemmi derdi müşteriler ona

Tüm derdi bir parça dünyalıktı...

Ç/...

Demircemmi derdi çekiçler ona.

Onun el emeğiydi

Havalinin tekmil demir aksamı.

Saban demirini o burunlardı.

Boyutlara geçit veren menteşeler onundu.

Çekiç, kerpeten, keser...

İster kazma olsun istenen

İster balta ve nacak

Hatta kap–kacak...

Dedik ya bilcümle metal eşya

Yeniden şekle girerdi.

Demircemmi ne eder, ederdi.

Onun usta ellerinde herbir şey yenilenirdi...

D/...

Sahici adı her ne ise unuttum

Bütün dünya demircemmi derdi ona.

Yana yana ve bütün ömrünce

Cehennemi bir ocağın başındaydı.

Demircemmi öldüğünde

Asırlık bir çınarla emsal

Yani yüz yaşındaydı.

Ateşlerle yana yana yaşadı

Yattı metallerle yanyana

Çünkü mezarı onun

Şehrin alt ucundaki hurdalıktaydı.', 'A/... Sahici adı her ne ise unuttum Demircemmi derdik biz ona. Kalın ve kıllı bilekleriydi Çocuksu gözbebeklerimize ısmarlanan. Her daim  aç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-emekcisi-demircemmi-hamparsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Sureti: Bekrçavış', '12-bir-adam-muzesi-sureti-bekrcavis-ahmet-yozgat-66nvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Bekrçavış derdik biz ona.

Seferberlikten kalan tek adamımızdı.

Dündeki zulme dirnen yanımızdı.

Daha on beşindeyken bekrçavış

Demişti hökümet “Haydi sefere! ..”

Ayakta delik çarık, sırtta yamalı mintan

Sürülmüştü garip bekr cepheye...

B/...

Bekrçavış

Sahici adını bırakmış bir savaşta

Daha onaltı yaşta

Bıraktığı bir adı olsa hadi neyse...

Bekrçavış sarıkamış’a gömmüş

Bir kolunu da.

Umutlarını yemen’de bırakmış.

Hayalleri ise kalmış ta... Galiçya’da.

Bekrçavış derdik biz ona.

Ya da gazemmi

Ömrü acılarla kolkolaydı onun

Hüzünlere gebe idi her demi...

C/...

Yedi yıl dile kolay! ..

Nerde bir olay veya bir vak’a

Gazemmi’nin müfrezesi orada.

Yastığı taş, yatağı yağız yer

Gökyüzü olmuştu yorganı.

Yıldızları saya saya

Kurşun sıkmıştı düşmana.

Yanıbaşında vurulan Süleyman’a

Ağıt yakamadan daha

Bir kurşun halil çavuşa

Bir kurşun emirber Ramazan’a.

Bekrçavış derdi hatıralar ona

Anlatırdı günlerce anlatırdı yana yana...

Ç/...

Ve günlerden bir gün

“Terhis olmuştu ordusu” Bekrçavış’ın.

Alınmıştı elinden

Yedi yıl koyun koyuna yattığı

Patır patır patlattığı

Can yoldaşı mavzeri.

“Çok zor oldu” derdi ayrılmak ondan.

Koymamıştı bu kadar yemen’de kalan hayali

Ayrılırken sarıkamış’ta sol kolundan.

Yüreği kabarmıştı

Çöküp bir filistin taşının üstüne

Sessizce ağlamıştı...

Bekrçavış derdi gözyaşları ona.

Ve o hala huş kal’ası gibi ağlardı.

Mavzeri patlardı gözlerinin zaman tünelinde

Yüreği kor ateş tandırlarda yanardı...', 'A/... Sahici adı her ne ise unuttum Bekrçavış derdik biz ona. Seferberlikten kalan tek adamımızdı. Dündeki zulme dirnen yanımızdı. Daha on b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-sureti-bekrcavis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Sürücüsü: Arabacali', '12-bir-adam-muzesi-surucusu-arabacali-ahmet-yozgat-1bx31', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A/.

Sahici adı her ne ise unuttum

Arabacali derdik biz ona.

Şirin mi şirin kasabamızın

Kıyıcığından bir köydendi.

Kendine bakmazdı atına baktığı kadar.

Arabaccali ne zaman yatar? 

Ne zaman dinlenirdi? 

Şaşardık bilcümle ahali.

Çünkü o sabahın köründen

Gecenin koynuna kadar

Habire çul taşırdı. Çuval taşırdı...

B/.

Arabacali derdi atlar ona.

İki atından biri doru birisi demirkırdı.

Vururdu inadına yükü arabasına

Tepeleme yığardı.

Ne zaman sarsa atlar bir rampaya

Direnir, gerinir ve ıkınırdı.

Sanmayın ki arabacali

Acımazdı atlarına.

Yoo! Gözünden bile sakınırdı...

C/...

Sahici adı her ne ise...

Arabacali kışın kömür taşırdı

Yazın kum çakıl...

Ne zaman yaşlı bir nine

Ya da engelli biri...

Kasardı dizginleri.

Arabanın kasasında her daim

Bir minder bulundururdu.

Altına atardı misafirinin.

Arabacalinin yüreği umman

Hoşgörüsü sarışın ışık misali safrandı.

Ç/...

Arabacali derdik biz ona

Atlar arabacali derdi

Arabalar arabacali...

Eli açıktı onun, gönlü açık

Yani yüreği harman yeri

Ama kaderi karışık birazcık

O sisli kış günü yükleyip kömürü

Kamçıyı şaklatan arabacali

Dönünce köşeyi

Kocaman tekerlekli bir kamyon

Bastı acımasızca.

Atlar savruldu.

Araba bir yığın tahta.

Bakın ki şu bahta

Arabacali eksi soğukta ateşlere kavruldu...', 'A/. Sahici adı her ne ise unuttum Arabacali derdik biz ona. Şirin mi şirin kasabamızın Kıyıcığından bir köydendi. Kendine bakmazdı atına bak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-surucusu-arabacali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sararmasın Yüreğindeki Yaprak', 'sararmasin-yuregindeki-yaprak-gulseren-onay-5boms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yemyeşil saçlarını 

Sarartıp 

Dökünce ağaçlar 

Daldaki son yaprak sen ol, 

Bekle… 

Yazgın benzemesin 

Denize ulaşamadan 

Kuruyan nehirlere. 

Sevgimin uçsuz bucaksız 

Çöllerinde, 

Susuz bir bedevi gibi 

Umuda aç ellerini, 

Bekle….. 

Ateşi sönse de 

Umudun, 

Son kıvılcımını 

Saklayarak bekle beni…. 

Sıcaklığım 

Rüzgarla yalayacak 

Yüzünü önce, 

Alevleyecek 

Umudunun korunu. 

Ay olup doğacağım 

Karanlığa tutkun gecelerine…. 

Yitirmiş de olsan 

Umutlarını, 

Yine 

Sana geleceğim 

Beni bekle……. 

07/01/2006/ANTALYA', 'Yemyeşil saçlarını  Sarartıp  Dökünce ağaçlar  Daldaki son yaprak sen ol,  Bekle…  Yazgın benzemesin  Denize ulaşamadan  Kuruyan nehirlere. ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sararmasin-yuregindeki-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12Bir Adam Müzesi Ekmekçisi: Fırıncömer', '12bir-adam-muzesi-ekmekcisi-firincomer-ahmet-yozgat-enq6u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Fırıncömer derdik biz ona.

Avuçlarına hep ekmek ekmek hohlardı.

Sabahın köründe

Besmeleyle açardı taş fırınını.

Çam odunu yakardı.

Önce hamur hamur

Sonra ekmek ekmek kokardı.

Fırıncömer derdik biz ona.

Göze, nazara inanınrdı.

Dükkanın şafağına mavi boncuk takardı...

B/...

Biz Fırıncömer derdik ona

Ekmekler fırıncömer

Çıraklıktan yetişmeydi

Yani işi zeminden kavramıştı.

İri bilekleri kocaman elleriyle Fırıncömer

Sanki ateşten fırlamıştı.

Yanakları somun ekmek gibiydi

Öylesine şişkin ve tombuldu.

Fırıncömer esirgemezdi ustalığını.

Hep çırak yetiştirirdi.

Onun fırını fırın değil sayın ki bir okuldu...

C/...

Fırıncömer derdi ekmekler ona.

On yıl mı desem? Ya da otuz mu? 

Fırıncömer hep ocağın başında.

Dilinde bozlak, elinde kürek, 

Çıtır ve gevrek olurdu pişirdiği ekmekler.

Cömert bir adamdı.

Kediler ve köpekler onun artığıyla doyardı.

Asla çalmazdı belediye gramajından

Pişirdikleri hep aynı ayardı...

Ç/...

Sahici adı her ne ise unuttum

Ama o bizi unutmadı.

Hiç bir gün gönlünü ateşsiz

Kasabayı somunsuz bırakmadı.

Bir ağustos günüydü ölüverdi fırıncömer.

Hemen işbaşı yaptı çıraklar.

Devam ettirdiler işi.

Fırıncömerin gidişi pek duyulmadı.

Fırıncömer derdi simitler ona.

Adı unutuldu da onun

Ekmeğinin tadı unutulmadı.', 'A/... Sahici adı her ne ise unuttum Fırıncömer derdik biz ona. Avuçlarına hep ekmek ekmek hohlardı. Sabahın köründe Besmeleyle açardı taş fı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/12bir-adam-muzesi-ekmekcisi-firincomer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Çobanı: Mikayla', '12-bir-adam-muzesi-cobani-mikayla-ahmet-yozgat-7ft2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Çobanmikayla derdik biz ona.

İnekler ve camızlar onu tanırdı

Hiç unutmazdı tosunlar.

Ne zaman “ho–ho” dese

Toplanırdı kocaman sığır sürüsü.

Onun tek süsü

Şapkasına taktığı koyun gözüydü.

Çeketi omzundan düşmezdi her daim.

Gömlek yakası çözük olurdu.

Dururdu çeşme başında

Notasız karakoyun çalardı.

Onun kavalını dinleyen her şey

Derin derin düşüncelere dalardı...

B/...

Çobanmikayla derdik biz ona.

Mikayla herkese “ede” derdi.

Yaz aylarında sığır

Sonbaharda koyun güderdi.

Azığı hep imansız çökelek olurdu.

Kurdu, kuşu kokusundan tanırdı.

Hangi ot hangi hastalığa iyi gelir

Hangi çiçek hangi derde devadır

Yalnızca ondan sorulurdu.

Çobanmikayla derdik biz ona.

Her nebatın onun eli altında

Kurutulmuş bir destesi bulunurdu...

C/...

Çobanmikayla derdi buzağılar ona.

Yalnızdı dağlar kadar

Yalnızca hayvanlarıyla dosttu.

Anlardı her mahlukun derdinden

Tek tek konuşurdu onlarla.

Koyunlarla kurtların ezeli düşmanlığı

Onun da sonu oldu.

Arsız bir songüz günü

Sürüye daldı hain bir canavar.

Çobanmikayla davrandı.

Ama geç kaldı.

Kurt beş koyunla birlikte onu da aldı.

Çobanmikayla derlerdi kuzular ona.

Kendi gitti kaderi gibi kederle

Koyaklarda yanık mı yanık

Bir kaval sesi kaldı...', 'A/... Sahici adı her ne ise unuttum Çobanmikayla derdik biz ona. İnekler ve camızlar onu tanırdı Hiç unutmazdı tosunlar. Ne zaman “ho–ho” de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-cobani-mikayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Bir Adam Müzesi Çerçisi: Gencilismayil', '12-bir-adam-muzesi-cercisi-gencilismayil-ahmet-yozgat-j5feq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A/...

Sahici adı her ne ise unuttum

Çerçigencilismayıl derdik biz ona.

Ondan öğrendik biz okumayı.

Ondan belledik bilcümle menkıbeyi.

Çerti kolunda, heybesi omzunda

Ne zaman çıksa alt yoldan.

Bütün sümüklü göbeller

Koşuşurduk iki koldan.

Kimimiz aşık kerem ile aslı kız

Kimimiz karacoğlan alırdık.

Hazreti ali hayberde cengetmede

Keloğlan kaf dağında oyundaydı...

Çerçigencilismayıl derdik biz ona

Kitabın envayi çeşiti ondaydı.

B/...

Çerçigencilismayıl derdi kızlar ona.

Gözleri yoldaydı gelinlerin.

Nineler onu beklerdi.

Yazmalar için incik

Boncuklar nazar için...

İğnenin en sağlamı ve en sivrisi

İncesi, kalını, çatallısı...

Örtüler için sırmalı dantel satardı.

Çerçismayıl sattığı herbir şeye

Sevgi katardı, sevda katardı.

Çerçismayıl derdi boncuklar ona.

Veresiye defteri bulundurmazdı.

Unutmazdı hiçbir şeyi.

Bütün hesapları aklında tutardı...', 'A/... Sahici adı her ne ise unuttum Çerçigencilismayıl derdik biz ona. Ondan öğrendik biz okumayı. Ondan belledik bilcümle menkıbeyi. Çerti ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/12-bir-adam-muzesi-cercisi-gencilismayil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Psiko-yorum', 'psiko-yorum-ahmet-sali-t6q8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zerresine kadar işlerken ruhuma

Geceden...Dost olur mu? 

Gidişler seçerken verir argümanlarımı

Ezilmiş sigara izmaritlerim,,

Delice dönüşleri eşliğinde 

Pusulamın

Sorgularım benliğimi

Sorular asılırken beynime-TIPKI-

Vidalı bir çengel gibi...

Ne çok duyguyu açıklar 

Korku ve özgürlük..

-Havaya sıkılan kurşun gibi-

Döver tanımlarım boşluğu

Sözcüklerin ruhu aşamazken

Vicdanımdaki uçurumu...

Aradıkça özgürlüğü

Sıklaşır korku nöbetlerim ve

Tutuklarım ben-liğimi

Gerçekle yalan arasında

Adamlığım takar kelepçelerini..

Şükretmek kar ım olur

Arttıkça huzursuzluğum

-YA  rahatsız olmasaydım-

Örer ömrünün taşlarını

Seçimimdir kaygılarım..', 'Zerresine kadar işlerken ruhuma Geceden...Dost olur mu?  Gidişler seçerken verir argümanlarımı Ezilmiş sigara izmaritlerim,, Delice dönüşler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Salı']::text[], 8.5, '{"poet":"Ahmet Salı","poet_slug":"ahmet-sali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/psiko-yorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-ali-orhan-gunaydin-7kxxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah! Geçmiyor bir türlü şu başımdaki ağrım,

İnsafı yok ki,birgün bile,

Kafam  bi rahatlasın.

O iyilikten anlamaz,

Ona  ancak, sıkı bir beddua lazım.

Dilerim Allah''tan bir günde,

Başağrımın başını ağrıtsın...

        07/01/2006', 'Ah! Geçmiyor bir türlü şu başımdaki ağrım, İnsafı yok ki,birgün bile, Kafam  bi rahatlasın. O iyilikten anlamaz, Ona  ancak, sıkı bir beddua...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beddua-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman İyi Düşün', 'aman-i-yi-dusun-ramazan-ates-15nj2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir soru sormuştum, dün gece sana,

Bir kuru öksürük, cevap mı bana? 

Bir daha düşünsen, düşün bir daha,

Bir kuru öksürük, cevap mı bana? 

Güzelden öteye sende bir hal var,

Sevgisin, gönülsün, bambaşka bir yar,

Güzel demek yetmiyor, yetmez sana,

Bir kuru öksürük, cevap mı bana? 

Ben seninle engel demez aşarım,

Seninle sevgiyi, mutluluğu yaşarım,

Bir şeyler söyle, boş gözlerle bakma,

Bir kuru öksürük, cevap mı bana? 

Sevdiğim ben senden,  seni istedim,

Bu canımı yollarına sereyim,

Evet de ki, senle yuva kurayım,

Bir kuru öksürük, cevap mı bana? 

Gel artık evet de, birtanem bana.

Ramazan Ateş/Enschede-7.1.2006', 'Bir soru sormuştum, dün gece sana, Bir kuru öksürük, cevap mı bana?  Bir daha düşünsen, düşün bir daha, Bir kuru öksürük, cevap mı bana?  Gü...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aman-iyi-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baştan Savma Yapma (Düz Yazı)', 'bastan-savma-yapma-duz-yazi-ali-kilic-kakiz-lyh5s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapıya gelen muhtaç birine, mutlaka bir şey vermeliyiz. Eğer biz bir şey veremiyorsak,verebilecek olan birine onu götürmek gerekir. Böyle bir şahsın, bir kez istemesi,müstehabtır. İkinci defa talepde bulunması uygun değildir. Üçüncü kez gelirse, uyarmak gerekir, bu davranışı doğru değildir.

Peygamberimize s.a.v. bir adam geldi, dardayım ihtiyacımı gör ya Muhammed dedi, bir şeyler istedi. Resûlullah s.a.v. talebini karşıladı adam döndü gitti.

Adam ertesi gün tekrar geldi. Yine bir şeyler istedi. Allah’ın Resûlü adama bir şeyler vermedi, evinde neyin var dedi? 

Adam: Ya Resûlullah, bir su kırbacım, bir de çul (Bir parçasını üstüme bir parçasını altıma seriyorum)    var diye halini arz eyledi. Peygamberimiz ona, su kırbacın kalsın,çulu getir dedi. İstenilen çul getirildi. Fahri kâinat efendimiz, açık artırma ile çulu satışa sundu, bir dirhem verdi birisi,sonra artıran yok mu diyerek,diğer birisi iki dirhem verdi. Çul onun oldu.

Peygamberimiz s.a.v.:

Bir dirhemi al, sende kalsın. Geri kalan dirhemle de, git çarşıda bir balta al gel buyurdular. Adam bir balta satın alıp geldi. Baltaya sap taktılar adama verdiler.

Daha sonra Resûlullah s.a.v.,şimdi şu dağa çık, orada baltayla odun kes çarşıya getir sat, on gün sonra bana gel buyurdular. Adam bütün gayretiyle işe koyuldu söyleneni yaptı sonra da Resûlü Ekreme uğradı, selam verdiler.

Ya Resûlullah Anam babam sana feda olsun,meğer iş varmışta nasıl yapılacağını bilmiyormuşum dedi ve gitti.

Öğretmek gerekir, baştan savma yapmamak lazım.

Brüksel / 2000', 'Kapıya gelen muhtaç birine, mutlaka bir şey vermeliyiz. Eğer biz bir şey veremiyorsak,verebilecek olan birine onu götürmek gerekir. Böyle bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bastan-savma-yapma-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul (Üstad Mansur İlhan Yakar; Şiir Paylaşımı)', 'i-stanbul-ustad-mansur-i-lhan-yakar-siir-paylasimi-i-brahim-necati-gunay-zr0pk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair''in memleketi şiir yurdu burası. 

Yetmiş iki milletin perde perde arası. 

Bir tadımlık sevdanın bin ömürlük yarası. 

_____Göçtü nice derbeder, aşkı ile şan kaldı. 

_____Hepsinden mutlak haber,İstanbul nişan kaldı. 

Daha tarih bilmezken kehanetlik yaşını. 

Kimse altın saymazken toprağını taşını. 

Kız kulesi ağlıyor, suya vermiş başını. 

_____İçinde öldü sevda aşka bir yalan kaldı. 

_____Damla damla firakın sebebi yılan kaldı. 

Tarihinin rahminde her an yeni sevda bul. 

Mecnun’unu vurmuşlar, Leylâları kalmış dul. 

Aşkı rüzgar sevgili yeditepe İstanbul. 

_____Esen esti başından her biri cüce kaldı. 

_____Nihayet kutlu rüzgar bağrında yüce kaldı. 

Bir gecelik sevdaya gözü yaşlı gelindin. 

Yere düştü duvağın sende taşa serildin. 

İstanbul sen eskiden böyle mağrur değildin. 

_____Rahmetinden baharsın arkanda gazel kaldı. 

_____Fatih Sultan yolunu gözleyen güzel kaldı. 

Vuslatın destan oldu eski çağ mezar düştü. 

Fatih’in haşyetiyle şanından Sezar düştü. 

Yiğidim Ulubatlı Hasana nazar düştü. 

_____Ondan sana İstanbul tebessüm eda kaldı. 

_____Meşhedine bürünmüş onurlu veda kaldı. 

Şimdi benim, mukaddes dedem kokan şehrimsin. 

Geçmişimden kılavuz geleceğe fehmimsin. 

Mabedinden hakikat,nur akıtan nehrimsin. 

_____Türbe türbe iskele baştaşı kürek kaldı. 

_____Sırrı iman hürriyet vasiyet yürek kaldı. 

Söyle Karacaahmet ben nasıl bir evladım. 

İmkansız anlatamam dile sığmaz feryadım. 

Minareli şerefim gökkubbeli ecdadım. 

_____Kandilde yağ tükendi ateşte habil kaldı. 

_____Güneşte yandı fitil gölgede kabil kaldı. 

Şair’in vatanında cemresin duman duman. 

Havasında suyunda toprağında aranan. 

En mutlu şiirimsin Sultanahmet haykıran. 

_____Suya düştü mısralar, ne eski hasım kaldı. 

_____Seni siğaya çeken bir molla kasım kaldı. 

Gölgesi düşmez iken sancağına ejderin. 

Şimdi ben güneşinde yanıyorum kederin. 

Gelmez mi makberinden evladına haberin! 

_____Kapıma senden gelen ne kutlu posta kaldı. 

_____Babaannem ağlıyor tesbihi yasta kaldı. 

Medeniyet büyüten en kutlu beşiksin sen. 

Fırtınalı kapıya sabırlı eşiksin sen. 

Her mevzide İstanbul hep delik deşiksin sen. 

_____Parmak şahit tetiğe bastıkça izi kaldı. 

_____Şehit düştün İstanbul mavzerin gazi kaldı. 

Kaldırdın mı üstünden, rüzgar tutan abanı. 

Kime eser bu yeller kim kucaklar yabanı. 

Sen misafir bilirdin receb ile şabanı. 

_____Heder oldu ramazan sahur''a uyku kaldı. 

_____Mağfiretlik geceye şişeli kuytu kaldı. 

Altın saklı İstanbul toprağında taşında. 

Bu hazine hudutsuz berekettir aşında. 

Nebi Halil İbrahim dua okur başında. 

_____Ondandır tükenmeyen dile destan aş kaldı. 

_____Şimdi ağla İstanbul, iki göz bir yaş kaldı. 

Adı serhat İstanbul, şimdi durmuş ve dursun! 

Durmuş''un rüyasından bu ibretlik kabusun. 

Mahkemesi kurulmuş fetih kızı namusun. 

_____Ayak geçti ırzına kabahat başa kaldı. 

_____Uykuların vebali mezarda taşa kaldı. 

İstanbul öksüz şimdi boynu bükük bir yetim. 

Uzletinde ağlıyor yıkık dökük servetim. 

Mısraları tutuşmuş şiirlik memleketim. 

_____Ne kaside, ne gazel; ne rafta şiir kaldı. 

_____Şiirler roman oldu romancı şair kaldı. 

İstanbul''um, sevdiğim çatık kaşlı edalım. 

Yollarına gül döktüm kokladın mı vefalım. 

Türkü türkü gururum nağme nağme sevdalım. 

_____Beste düştü tellere güftesi dilde kaldı. 

_____Mansur döndü bülbül''e gözyaşı gülde kaldı. 

Mansur İlhan Yakar

Çok Değerli Üstad''ın Bir Şiirini Sizlerle Paylaşmak İstedim.

Saygılarımla.', 'Şair''in memleketi şiir yurdu burası.  Yetmiş iki milletin perde perde arası.  Bir tadımlık sevdanın bin ömürlük yarası.  _____Göçtü nice der...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/istanbul-ustad-mansur-ilhan-yakar-siir-paylasimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-elazigli-mustafa-kaya-poq49', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar

yıllar,

ıssız bir yalnızlık,

acı bir rüzgar

uzak kıyılarda

yıkılan dalgalar

ateşe verilen ırmaklar,

buruşuk deniz,

okuyup geçtiğim kitaplar,

infilak eden mutluluğum,

kendime sakladığım sırlar,

ve bir sarmaşık gibi

sarılıp durduğum aşklar

düştüğüm uçurumlar

yasaklandığım akşamlar

saçlarımı koparan acılar

güz vurmuş yapraklar

uyumayan sular

ve tenha bir yer

ak saçlı kar.

yıllar…yıllar olalı

dönülmez 

iki büklüm kaldım

kırık söğüt dalı gibi

biri ben,

biri yıllar….

Mustafa kaya

08.01.2006 / fatih', 'Yıllar yıllar, ıssız bir yalnızlık, acı bir rüzgar uzak kıyılarda yıkılan dalgalar ateşe verilen ırmaklar, buruşuk deniz, okuyup geçtiğim ki...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yillar-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhal', 'muhal-mehmet-rizaoglu-omfk3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzanmışım musallaya boylu boyunca,

Midem dolandı,kafatasımı yutunca', 'Uzanmışım musallaya boylu boyunca, Midem dolandı,kafatasımı yutunca...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/muhal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanatçı...', 'sanatci-ercan-akbay-71hvz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne şiirden medet um

       ne bestenden ün ara

       bak zil çalıyor mide kasların

       açlık karanfil olmuş yakana...

       ne dosta güven

       ne meçhul okuyucuna

       bak gittikçe büyüyor yalnızlığın

       bir kısır döngüde duyguların

       hep böyle gelmiş böyle gidiyor

       kimin yaşarken kadri biliniyor.

       hadi boşver içlenmeye

       çek bir fırt daha kadehinden

       yine bir şeyler karalayıver

       ister açlıktan söz et

       ister parasızlıktan

       istersen aşksızlıktan.

       bakarsın zaman duruverir ansızın

       çarpmaz olur sevgiye vuran yüreğin

       sen bilmezsin,akar yine zamanın seli

       bir çakıl taşı gibi bir kıyıda

       anılır senin de adın

       anlaşılır senin de duyguların.

                                                                       3.11.1991

       iş işten geçmiş ola

       göz yaşını damlatana selam ola...........7.1...2006  bitti.

    

                                                                        H.A.DEDE NİN ANISINA.', 'ne şiirden medet um        ne bestenden ün ara        bak zil çalıyor mide kasların        açlık karanfil olmuş yakana...        ne dosta gü...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sanatci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz kaçmıyor / yanılgı kırılmaları...', 'deniz-kacmiyor-yanilgi-kirilmalari-zafer-zengin-etnika-uduj5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

körpe kuzusuna yanan anaların safları belirlemesi

dört iklim, üç yüz atmış beş gün zemheri ayazında

hala hazırladığı sabah kahvaltılarına, suşi yiyen

penguen tuhaf tuhaf  bakarken, elini kesmesine dair; 

saflarında ve safında kayıp

yenilgilerine ağlar komutanlar

analar sonra

manevralardan anlamazlar

bir ses beklerler öğlene doğru

sonra geceye kaçan

sonra ertesi güne kalan…

yolun sonu üstüne binlerce öykü dinlemiş

yüzü yerine bıyığı sakalı yeni terlemiş çocuğun

çaresizlik üzerine yazdığı mektuplara dair; 

anamı ağlatmayın “

rüzgarın biçtiği dağın ucunda

elini kaleme bağlamış

titreyen eliyle bir genç adam

ölümün geri getirmediklerine dair; 

sonra ağlar analar

yasların ucunu bağlar

göğsünün orta yerine

gordion düğümü bağlar

ağlarsa analar ağlar

gerisi yenilmiş komutanlar…

gerçeğin olmadığını gören, bir aşk varmış, bir de yalan diyen

yüzüne saçlarını döküp, sevdaya hasret kalan çocuğun,

yitirdiği güzelliklere dair küslüğü; 

yaşanacak yer

yalnızlığın bağrı

ağır giden zamanın ayıbı

dudağında unuttuğu nazı

birde kendine sakladığı yazı

bağırsaydı, seni çok özledim diyecek olan

deniz kızının mırıldanırken düşünmesine dair; 

sonra git

deniz kaçmıyor

tek başına bir evle

paylaşılmıyor yalnızlık

ucunu açtı kalemin

etine batırdı ve yazdı

sonra gel

denize ne kaldı…

29 12 2005

.', '. körpe kuzusuna yanan anaların safları belirlemesi dört iklim, üç yüz atmış beş gün zemheri ayazında hala hazırladığı sabah kahvaltılarına,...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/deniz-kacmiyor-yanilgi-kirilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki çocuk', 'i-cimdeki-cocuk-guzin-osmancik-a2htl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine o çocuk canlandı içimde

Yine kovalambaç, saklambaç

Nasıl duygulardı onlar

Tutuksuz, özgür ve uçuk

Hiç bir şey düşünmezdik

Oynamaktan yemekten başka

Bir de derdim uyku olmasa

Nasıl temizdi kaygısız gamsız

Büyüdük yazık zamansız

Ne aşk vardı ne sevda 

Bez bebeğim, mandolinim.

Hiç susmadı içimde 

O çaldığım melodim.', 'Yine o çocuk canlandı içimde Yine kovalambaç, saklambaç Nasıl duygulardı onlar Tutuksuz, özgür ve uçuk Hiç bir şey düşünmezdik Oynamaktan ye...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimdeki-cocuk-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-huseyin-ozcan-gi7ey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerini kırmızıya boyadım ayrılığın,

saçlarını beyaz yaptım.......

nerdesin ey zalim yar,

her gece uykularıma  girer,

gözlerime dolar, taşar,

yaş olur akar  hasretin.......

takvimin her yaprağında

ayrılık yazıyor,

anladım ki artık gelmeyeceksin.....', 'gözlerini kırmızıya boyadım ayrılığın, saçlarını beyaz yaptım....... nerdesin ey zalim yar, her gece uykularıma  girer, gözlerime dolar, taş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anladim-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '& - Yakarış - &', 'yakaris-gulsen-senderin-ofi6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadere mi yüklesem, bu müphem hezeyanı

Sardırdı gama derde,  çaresi yok besbelli

Ayırarak canandan, leyla eyledi canı

Nafile yakarışlar,  bulamaz bir teselli.

Hançer ıstırap vermez, kanayan şu kalbime

Sevmek de suç sayıldı,  varamadım dengime

Kutsal o armağanla,  bağlandım ben sevgime

Nafile yakarışlar, bulamaz bir teselli.

Boşuna mı bu gönül taşıyor hışım hışım 

Ne ettimse dinmedi  kanlı akan göz yaşım

Hıçkırarak her gece düşer yastığa başım

Nafile yakarışlar,  bulamaz bir teselli.

Kadir Mevlam kavuştur gönülden sevenleri

Böyle kutsal bir aşka  ömrünü verenleri

Düşlemekten yoruldum vuslata erenleri

Nafile yakarışlar bulamaz bir teselli.', 'Kadere mi yüklesem, bu müphem hezeyanı Sardırdı gama derde,  çaresi yok besbelli Ayırarak canandan, leyla eyledi canı Nafile yakarışlar,  bu...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yakaris-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle ol hep', 'benimle-ol-hep-guzin-osmancik-x8xl8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benimle ol hep

Hiç görmediğim İlahım

Bırakma beni

Zaten doğuşum

Ecelim de sensin

Ne farkeder

Erken ya da geç

Gelse  de ölüm

Şükrümde sensin

Hüznümde sen

Neşemde

Seninle güzel hayat 

Seninle  var  olmak yaşamak

Sana varmak

Bütün gün ismini anmak

Ol dediğinde olan benim

Öl dediğinde ölenim

Ben sana aitim

    sonram', 'Benimle ol hep Hiç görmediğim İlahım Bırakma beni Zaten doğuşum Ecelim de sensin Ne farkeder Erken ya da geç Gelse  de ölüm Şükrümde sensin ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benimle-ol-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
