INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TaşLamA', 'taslama-asima-azra-h57vx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcacık odalarda yaşıyorsan sen

adaleti irdeleme istersen! 

Üşümüyorsan saçaklardaki kuşa

razı ol göğünü karartan kışa

ve kızma kafana attığım taşa! 



çürütmeler/2', 'Sıcacık odalarda yaşıyorsan sen adaleti irdeleme istersen!  Üşümüyorsan saçaklardaki kuşa razı ol göğünü karartan kışa ve kızma kafana attığ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/taslama-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Maviye Çalıyor Düşlerim', 'geceyi-maviye-caliyor-duslerim-suna-doganay-bn85k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derinlere dalıyorum,

Saatte yüz kilometre.

Geçiyor hızla hayaller,

Süzülerek  buğulu camların ardından.

Yalnız bir yıldız gülümsüyor tepelerden.

Maviye boyuyorum zifiri karanlıkta,

Kararan gök kubbenin yüzünü.

Kar yağıyor düşlerin ikileminde,

Çamların cılız kollarına. 

Direniyor körpe bir ağaç,

Kalpsiz sokakların eteğine.

Yaşlı bir adam,

Donmak üzere..

Kabına sığmıyor yüreğim.

Resimler çiziyor renk renk,

Giderek yayılan havai fişekleri.

Çocuk sesleri, atlıkarınca..

Uyuşuk hayalperest saatler..

Geçip gidiyor sığ bir denizin,

Saygısız köpükleri üzerinde yüzerek.

Alışıyor gözlerim,

Karanlığın geleceksiz kıpırtılarına...

Derinlere dalıyorum....

Aylar, yıllar giriyor düşlerime.

Bazen ileri, bazen geri.

Çocukluğumun bayramları,

Kırmızı tafta elbisem,

Ve odun taşıyan minik eller..

Bir dağ köyü, öğrencilerim...

Sonra yakalanıyor umutlar.

Bir çiğ damlası düşüyor,

Yalnız yaşayan kır çiçeğinin yapraklarına.

Kekik kokusu...

Toprak kokusu...

Fidan dağıtıyor demet demet

Yeşilsever, masum, çocuksu...

Toprak yüzü görmeyen ellere...

Erken adımlar düşüyor,

Denizin engin ruhlu sularına...

Derinlere dalıyorum...

Kar yağıyor kaldırım taşlarına.

Kırmızı kumaşa tosluyor,

Dev boynuzlu bir boğa.

Fırlatınca matadoru havalara,

Kaldırım taşları sökülüyor,

Yol boyunca....

Ne güzel şeydir,

Gülümseyerek bakabilmek,

Gökkuşağının yedi rengine.

Başım mı dönüyor ne,

Dalarken gökyüzünün maviliğine.

Tutuklanıyor gecenin güneşi,

Paslı saatlerden kelepçelerle.

Sonra yıldızlardan bir perde,

Gülümsüyor gökyüzünün,

Karanlık ateşine,

Parıltılı bir mecburiyetle...

''Dur'' diyor düşlerim gecelere.

Parkta, sokakta yatmıyor çocuklar.

Geceyi maviye boyuyorum.

Deniz şeffaf, deniz saydam, cam gibi.

Bahçemde nesli tükenmeyen,

Ağaçlar yükseliyor boy boy.

Büyüdükçe büyüyor yağmur ormanları.

Bir ressam geceyi boyuyor tuvalinde,

Karanlığa mavi çalıyor..', 'Derinlere dalıyorum, Saatte yüz kilometre. Geçiyor hızla hayaller, Süzülerek  buğulu camların ardından. Yalnız bir yıldız gülümsüyor tepeler...', ARRAY['Türk Edebiyatı','Şiir','Suna Doğanay']::text[], 8.5, '{"poet":"Suna Doğanay","poet_slug":"suna-doganay","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/geceyi-maviye-caliyor-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Söyleyemedim..!', 'soyleyemedim-umut-gul-fgnyq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırmak istedim içimdeki gizi 

Duymalıydı tüm evren,

Bilmeliydi ağaçlar kuşlar, böcekler

Katılmalıydı sevincime tüm dostlar

Dilimin ucuna kadar geldi 

Susuverdim birden …

Söyleyemedim….

Seni sevdiğimi..! 

……………….

Yine kalacaktı sırrım yüreğimde

Vermeseydi ele  gözlerim beni

…

“ama saklayamadım

sende  çok anlayışlıydın üstelik

bakınca  anlayıverdin gözlerimden”

….

Gizleyemedim..! 

31.12.2005', 'Haykırmak istedim içimdeki gizi  Duymalıydı tüm evren, Bilmeliydi ağaçlar kuşlar, böcekler Katılmalıydı sevincime tüm dostlar Dilimin ucuna ...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyleyemedim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin Yar Yar', 'ne-dersin-yar-yar-ali-balliktas-jav1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El ele tutuşup kıldan köprüyü,

Geçelim birlikte ne dersin? yar yar.

Dokunmadan bize feleğin yayı,

Kaçalım birlikte ne dersin? yar yar.

Aşkımız demlensin alsın demini.

Biz bize yakalım gönül şem''ini.

Ayrılmamak için sevda yemini,

İçelim birlikte ne dersin? yar yar.

Avcılar her zaman gezerken cana.

Düşürürler bizi tek tek kapana.

Ayrılmadan Keklik gibi yan yana,

Uçalım birlikte ne dersin? yar yar.

Ümür sayılıdır düşün bir kere.

MAZLUMİ bizede gelecek sıra.

Yaşlanıp baş başa dönülmez yere,

Göcelim birlikte ne dersin? yar yar..', 'El ele tutuşup kıldan köprüyü, Geçelim birlikte ne dersin? yar yar. Dokunmadan bize feleğin yayı, Kaçalım birlikte ne dersin? yar yar. Aşkım...', ARRAY['Türk Edebiyatı','Şiir','Ali Ballıktaş']::text[], 8.5, '{"poet":"Ali Ballıktaş","poet_slug":"ali-balliktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-dersin-yar-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenlerdeniz.', 'erenlerdeniz-ali-balliktas-jp76j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönmeyiz bu yoldan gül yüzlü Şah-a,

El pençe bağlanıp duranlardanız.

Bundan güzel varlık ne olsun daha,

Tanrı''yı ademde görenlerdeniz.

Can ile Canana demişiz yar yar.

Bundandır görmüşüz daim itibar.

Saklımız gizlimiz yoktur aşikar,

Varımız meydana serenlerdeniz.

Kar da gözümüz yok, varlığımız kar.

Dostu kaybetmekse en büyük zarar.

Hakkın divanında olmuşuz berdar,

Hakikat sırrına erenlerdeniz.

MAZLUMİ bendedir bir tek ikrarla.

Dar ile divanda durayım yarla.

Bu yol çetin yoldur, lakin kırklarla,

Yol alıp erkana girenlerdeniz.', 'Dönmeyiz bu yoldan gül yüzlü Şah-a, El pençe bağlanıp duranlardanız. Bundan güzel varlık ne olsun daha, Tanrı''yı ademde görenlerdeniz. Can i...', ARRAY['Türk Edebiyatı','Şiir','Ali Ballıktaş']::text[], 8.5, '{"poet":"Ali Ballıktaş","poet_slug":"ali-balliktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erenlerdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-mehmet-rizaoglu-vkugj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün ömrüm uykuda geçti,gecelerim uykusuz,

Nasip olur mu derin bir uyku,sonsuz ve korkusuz.', 'Bütün ömrüm uykuda geçti,gecelerim uykusuz, Nasip olur mu derin bir uyku,sonsuz ve korkusuz....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/uyku-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-mehmet-rizaoglu-fvpki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alevden hayal biçtim, has şiir beklemeyin,

Meçhulden gelen hiçtim, hiç''e hiç eklemeyin', 'Alevden hayal biçtim, has şiir beklemeyin, Meçhulden gelen hiçtim, hiç''e hiç eklemeyin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sair-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç olmadan gel', 'gec-olmadan-gel-metin-kaya-i-lhan-d5wr3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılların üzerine asırları bindirmeden

Geleceksen bekliyorum, geç olmadan gel...

Saçlarımın aklarına, arkadaşlar eklemeden

Geleceksen bekliyorum, geç olmadan gel...

..

Yanıpta kor olmuş gönül bağıma

Sayende doymadığım gençlik çağıma

Karları yağdırmadan hasret dağıma

Geleceksen bekliyorum, geç olmadan gel...

..

Geleceğim karanlık, geçmişim hüzün

Rüyalarıma rehberlik eder o melek yüzün

Beklediğim tek şey yemyeşil gözün

Geleceksen bekliyorum, geç olmadan gel...

..

Almadan son nefesimi, sensiz dünyada

Ellerini tutar, saçlarını okşarım yalnız rüyada

Buluşmadan sevgilim öbür dünyada

Geleceksen bekliyorum, geç olmadan gel...', 'Yılların üzerine asırları bindirmeden Geleceksen bekliyorum, geç olmadan gel... Saçlarımın aklarına, arkadaşlar eklemeden Geleceksen bekliyo...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gec-olmadan-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Sana', 'hasretim-sana-metin-kaya-i-lhan-hu462', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'özenle sakladığım mektupların şimdi önümde

cımbızla ayıklıyorum

tek tek,

elinin değdiği harfleri sanki...

özlemim dağlar gibi yürüyor üstüme

ben bir çaresiz

ben bir umutsuz aşık

ben 	

bitmiş tükenmiş bir çınar gibi

özleminin baskısı altında inlerken

cımbızlıyorum harfleri yine..

senden bir ışık görmek

senden bir koku almak için...

ellerinin değdiği kağıtlarda 

ellerini ararım

boşuna...

gözlerimi okşayan gözlerini ararım

boşuna...

her defasında getirdiğim

en sevdiğin güllere bakarım 

senin yerine..

koklarım beraber kokladığımız gün gibi..

sanki yanımdasın bir tanem

kollarında ağladığım gün gibi...

şimdi yine

yine ellerimde güller, kalbimde hasretin var

gözlerimde hüzün yaşları

hücum ederken yanaklarıma...

sana sesleniyorum...

yanına geleceğim günü özlemle bekliyorum..

al bu gülleri 

ilk verdiğim güller gibi taptaze koru,

benim, aşkını sonsuza dek koruyacağım gibi...

akan yaşlarımla toprağını ıslattım affet...

kalbimden, beynimden, ruhumdan çıkmayan sevginle

ben yaşamaya çalışırken,

senin burada yatmana katlanamıyorum...

yarın, tekrar geleceğim...

her zaman geldiğim güllerinle...

hasret rüzgarlarından bir ses 

fısıldıyor kulağıma sanki

zaman yakındır gülüm, yakındır zaman

kavuşacağız seninle...', 'özenle sakladığım mektupların şimdi önümde cımbızla ayıklıyorum tek tek, elinin değdiği harfleri sanki... özlemim dağlar gibi yürüyor üstüme...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hasretim-sana-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '= Şirin anneciğim=', 'sirin-annecigim-fadime-dizdar-g1gax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşil gözlerinle,ışıklar saçtın,

Karanlık yolumu,sen aydınlattın.

Allah sevgisini,canından kattın

Benim nazlı,şirin annecığim.

Mahşer gününde,olmam ki şaşkın,

Başıma Nurdan bir taç bıraktın,

Cennet de bekliyor,o yüce tahttın,

Benim nazlı,şirin anacığım.

Bu dilim yetmez,seni anlatmaya,

Kalemler yetmez,sevgini yazmaya,

Nasıl kıyarlar,sevgi dolu anaya.

Benim nazlı,şirein anacığım.

   **********************

Kardan aktır tenin ne hoş cemalin

Yüreğimde mevcut yerindir anam! ..

Gitmiyor gözümden her türlü halin

Herşeyin güzeldir şirindir anam! 

Yeşil gözlerinle ışıklar saçtın

Karanlık yolumu sen Nura açtın,

Dinmeyen derdime bir tek ilaçtın

Hak aşkı bir sende derindir anam! 

                            Fadime Dizdar', 'Yeşil gözlerinle,ışıklar saçtın, Karanlık yolumu,sen aydınlattın. Allah sevgisini,canından kattın Benim nazlı,şirin annecığim. Mahşer gününd...', ARRAY['Türk Edebiyatı','Şiir','Fadime Dizdar']::text[], 8.5, '{"poet":"Fadime Dizdar","poet_slug":"fadime-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sirin-annecigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mehmet-rizaoglu-zntbr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin için yaratıldı âlemlerin âlemi,

Senin için tüketsem; Okyanusla mürekkep,

Ormanlarla kalemi!', 'Senin için yaratıldı âlemlerin âlemi, Senin için tüketsem; Okyanusla mürekkep, Ormanlarla kalemi!...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/senin-icin-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli', 'gizli-metin-kaya-i-lhan-fi7y5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde yanan köz gibisin..

Dumanın ruhumda gizli gizlidir…

Gözümden akan yaşlar gibisin

Her damlası yağmurlarda gizli gizlidir…

Benliğimde kör bıçaklar gibisin

Yaraların içimde gizli gizlidir

Yangınlarıma yağmur taneleri gibisin

Damlalarında acılarım gizli gizlidir…

Yürüdüğüm yollarda taşlar gibisin

Ayaklarımda acıların gizli gizlidir…

Kanayan yaralarıma tuz basarmış gibisin

Kanımın her damlasında sevdan gizli gizlidir..

Her damla gözyaşımda volkan gibisin

Lavların yüreğimde gizli gizlidir…

Geçtiğin her noktayı yakar gibisin

İzlerin hayatımda gizli gizlidir…

Çöldeki yollarıma çıkmaz sokak gibisin

Görünmez engellerin gizli gizlidir…

Sen çözemediğim labirentler gibisin

Cevabın yüreğimde gizli gizlidir…', 'İçimde yanan köz gibisin.. Dumanın ruhumda gizli gizlidir… Gözümden akan yaşlar gibisin Her damlası yağmurlarda gizli gizlidir… Benliğimde k...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gizli-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi Sensin', 'sebebi-sensin-metin-kaya-i-lhan-qe18q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutlardan süzülen hasret damlalarına

Set çekmek elde değil, sebebi sensin...

Ruhumu yakıp yıkan özlem yangınlarına

Set çekmek elde değil, sebebi sensin...

..

Saçlarıma kar yağdıran kadere isyanıma

Çıkmazlara doğru giden dert yollarıma

Uykularımı bölen sevgi kabuslarıma

Set çekmek elde değil, sebebi sensin...

..

Ruhumu kuru dal eden aşk yağmurlarına

Bağrımı yakıp viran eden gözyaşlarına

Gözlerimin dünyaya boş bakışlarına

Set çekmek elde değil, sebebi sensin...

..', 'Bulutlardan süzülen hasret damlalarına Set çekmek elde değil, sebebi sensin... Ruhumu yakıp yıkan özlem yangınlarına Set çekmek elde değil, ...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sebebi-sensin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık...', 'yazik-metin-kaya-i-lhan-ey7ng', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakıyorum gökyüzüne

çimenlerin üstünden

başım yerde,

dizinde değil.. ne yazık 

sevgin bana bir ömür 

aşkın içimde kor olmuş kömür

hayalin gözümde 

yüreğim hasretinle dolu

başım dizinde değil.. ne yazık

söyleşirken olmayan geleceğimizden

haberimiz yoktu ki

bu hasret günlerimizden

sen artık yoksun, kokunda yok, 

gözlerin yok içinde kaybolacağım

ellerin yok artık yanımda

öpüp koklayacağım…

bakıyorum gökyüzüne

çimenlerin üstünden

başım yerde,

dizinde değil.. ne yazık 

sevgin bana bir ömür 

aşkın içimde kor olmuş kömür

hayalin gözümde 

yüreğim hasretinle dolu

başım dizinde değil.. ne yazık

söyleşirken olmayan geleceğimizden

haberimiz yoktu ki

bu hasret günlerimizden

sen artık yoksun, kokunda yok, 

gözlerin yok içinde kaybolacağım

ellerin yok artık yanımda

öpüp koklayacağım

tenin dahi yok

okşayıp, ruhumun içinde kaybolacağım

özlemin bir kasırga gibi sarsıyor beni

özlememek mümkün mü canım

bedenimi benden alan buseni...

başım dizinde değil.. ne yazık

toprak oluyor çimelerin üstünde saçlarım

kokunu duyamamak, gözüne bakamamak

sesinde kaybolamamak beni acılarım

şiirler yazamıyorum, sen yanımda olmayınca

yaşamıyorum ki başımı dizlerine yaslamayınca

artık

hasret denilen işkence 

aşkıma azık

başım dizinde değil.. ne yazık..', 'bakıyorum gökyüzüne çimenlerin üstünden başım yerde, dizinde değil.. ne yazık  sevgin bana bir ömür  aşkın içimde kor olmuş kömür hayalin gö...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yazik-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankârım ben...', 'i-syank-rim-ben-metin-kaya-i-lhan-oacqr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni senden almaya gücüm yetmiyor

Sabahsız gecelere isyankârım ben...

Sensizliğin verdiği acı bitmiyor

Sabahsız gecelere isyankârım ben..

..

Ağlamak bana bir meslek oldu

Sevginle yanan ruhum şimdi çöl oldu

Saçıma düşen aklar madalyam oldu

Sabahsız gecelere isyankârım ben...

..

Akşam mı olmuş yoksa güneş mi doğmuş? 

Zamanım  zindanlarda bir köşe olmuş

Karanlıklar yalnızca bana arkadaş olmuş... 

Sabahsız gecelere isyankârım ben...', 'Seni senden almaya gücüm yetmiyor Sabahsız gecelere isyankârım ben... Sensizliğin verdiği acı bitmiyor Sabahsız gecelere isyankârım ben.. .....', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isyankarim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekemedim', 'cekemedim-metin-kaya-i-lhan-hiuho', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi bir rüzgar esti geçti

Saçlarımı uçuşturup; başımın üzerinden

Benliğimin taa içine kadar...

Unuttuğum kokular saçıldı

Burnumun girişinden; ruhumun eskilerine...

Öylesine estiki bu deli rüzgar

Can verdi sevgilimin küllerine...

Her şeyi unuttum derken 

Hayat verdi yeniden mutsuzluğumun geçmişine...

Bırakmalı insan bir yerde artık

Adam gibi, heybetli bir çizgi çekmeli

Geçmişin puslu anılarına...

Yelkenleri fora etmeli geleceğine

Estirmeli kasırgaları, mutluluk kokan yelkenlerin içine...

Bir deli rüzgar esti geçti kulaklarımdan

Bir zamanlar tatlı sesler uçuşan kanallardan...

Canlandı ölü anılar...

Bırakamadım; 

Heybetli bir çizgi çekemedim...

Görünce; rüzgarın alıp götürdüğü cansız yaprağı...

Aklıma düştü salınıp gidişin,

Bir deli rüzgarın savurduğu yaprak misali...

Başbaşa kaldım işte..rüzgar uzaklaşınca yanımdan

Sımsıcak fakat içimi soğutan anılarımla...

Çekemedim heybetli bir çizgi işte...

Bir kuru yaprağın bana hatırlattığı

Seninle dolu anılarıma...

Çekemedim...', 'Şimdi bir rüzgar esti geçti Saçlarımı uçuşturup; başımın üzerinden Benliğimin taa içine kadar... Unuttuğum kokular saçıldı Burnumun girişind...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cekemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Uğruna', 'sevdan-ugruna-hatice-guler-fcyht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğini seninle bozuyorum

Karanlıklardan çıkıp gelen hayalinle

Seni hasretten coşan gözlerimle sarıyorum

Sensizliğe hiç mecalim kalmadı

Sevdan uğruna her  şeyi terk etmek istiyorum

Ne varsa bana değerli,bana yakın

Ne varsa bana muhtaç,benim olan

Arkamda bırakıp sana koşmak,koşmak...

Senin için,bir ömrü, sonsuz bir geleceği

Sevdan uğruna yüklenip sana gelmek istiyorum

Sevdiğim...........', 'Gecenin sessizliğini seninle bozuyorum Karanlıklardan çıkıp gelen hayalinle Seni hasretten coşan gözlerimle sarıyorum Sensizliğe hiç mecalim...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdan-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Ver', 'hak-ver-mustafa-aslan-2-sgle1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hak ver anana,

Sakin uyma seytana.

Ana hissi hep dogrudur,

Dinlemezsen bu yolun sonudur.

Ana derse yaptigin yanlistir,

Dogruyu yapman, anayi gururlandirir.

Ana yalan söylemez,

Sen dinlemezsen anani, bu dünya böyle dönmez.

Anana hak ver,

9 aylik yüktün,

Simdi 20 yasina girmissin,

Ne fark eder.

Ana yüregi iste,

Dayanmaz yüregi,

Artik sende hak ver.

Tarih Ve Saati: 11/08/2005    04:26', 'Hak ver anana, Sakin uyma seytana. Ana hissi hep dogrudur, Dinlemezsen bu yolun sonudur. Ana derse yaptigin yanlistir, Dogruyu yapman, anayi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hak-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben senin neyini sevdim?', 'ben-senin-neyini-sevdim-metin-kaya-i-lhan-pqc79', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin elini sevdim, elini

Güller gibi yumuşak

Güller gibi kokulu elini sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin yanakların sevdim, yanaklarını

Nar gibi kıpkırmızı

Nar gibi yenilesi yanaklarını sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin tenini sevdim, tenini

Bir pamuk gibi bembeyaz,

Bir pamuk gibi yumuşacık tenini sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin gözünü sevdim, gözünü,

Dipsiz kuyular gibi sonsuz bakan,

Dipsiz kuyular gibi esrarengiz gözünü sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin kalbini sevdim, kalbini...

Sünger gibi emici

Sünger gibi sabırlı kalbini sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin ruhunu sevdim, ruhunu

Bir melek gibi günahsız

Bir melek gibi seven ruhunu sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben senin benim olmanı sevdim, benim olmanı,

Bulutlar kadar hür

Bulutlar kadar cesaret dolu olmanı sevdim...

Ben senin neyini sevdim; bilirmisin bir tanem? 

Ben sendeki beni sevdim, beni

Toprak gibi merhametli

Toprak gibi saklayıcı sendeki beni sevdim...

Ben seni sevdim işte

Ruhumdaki yangınlara köpük olmanı sevdim..

Ben; 

Benim olmanı sevdim....', 'Ben senin neyini sevdim; bilirmisin bir tanem?  Ben senin elini sevdim, elini Güller gibi yumuşak Güller gibi kokulu elini sevdim... Ben sen...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ben-senin-neyini-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Kursun Siksan Geçmezya Geceden', 'hani-kursun-siksan-gecmezya-geceden-mustafa-aslan-2-dk50q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani kursun siksan geçmezya geceden,

Kursunu siktin ama geceye degil bana.

Hançeri soktun yoktan hayatima,

Derdin ne diye, simdi sorma bana.

Gecelerce seni düsündüm,

Kendi kendime güldüm,

Çok üzüldüm,

Ama yaralidir gönlüm.

Konus birkez bana,

Sevdigimi anlatayim sana,

Uçurumlardan düstümde,

Elimden tutan olmadi.

Zaman zaman agladim,

Zaman zaman sizladim,

Kimseye degil ben kendime yaptim,

Ben sadece sana degil herkeze kandim.

Korkusuzca yürüdüm sevdalara,

Korkarak geri döndüm,

Her sevdigimde dahada söndüm,

Ben kendi kendimi mezara gömdüm.

Hayal bile edemez oldum,

Sensiz olmaktan ben soldum.

Çikisi olmayan bir yoldun,

Çikmazlara düstüm kurtar beni.

Tarih Ve Saati: 17/11/2004	19:54', 'Hani kursun siksan geçmezya geceden, Kursunu siktin ama geceye degil bana. Hançeri soktun yoktan hayatima, Derdin ne diye, simdi sorma bana....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hani-kursun-siksan-gecmezya-geceden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Beraberdik', 'hani-beraberdik-mustafa-aslan-2-1s4ji', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz birbirimizi seviyorduk,

Ama ask demek nedir bilmiyorduk,

Ask, mecnunun aski gibi olmaliki,

Ona ask denilsin.

Hani beraberdik,

Hani hep beraber kalacaktik,

Askini alip gittin,

Bende birsey birakmadin.

Uzaktan bir gülücük attin,

Beni o gülüsünle felege sattin.

Biz hani beraberdik.

Dedigin dogru, ozaman beraberdik,

Simdi ayri dünyalarin insanlariyiz.

Bakta gör içimdeki sevdayi,

Sevdami nefrete döndürdün.

Içimdeki kine yenik düsürdün,

Beni insanlara güldürdün.

Farketmez seni artik sevmiyorum,

Yalanci insani zaten sevemem.

Beraberdik, simdi ayriyiz,

Seviyorduk, simdi sevdamiz oldu nefretimiz.

Tarih Ve Saati: 17/11/2004	21:21', 'Biz birbirimizi seviyorduk, Ama ask demek nedir bilmiyorduk, Ask, mecnunun aski gibi olmaliki, Ona ask denilsin. Hani beraberdik, Hani hep b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hani-beraberdik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-mustafa-aslan-2-58xxf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmek haram,

Yalniz bana degil,

Herkeze haram olsun.

Benden baskasi sevmesin seni,

Benden baskasi çekmesin derdini,

Bensizligi istiyorsan,

Sende olursun elbet,

Yalnizligin gülleri.

Tarih Ve Saati: 16/08/2002	00:17', 'Seni sevmek haram, Yalniz bana degil, Herkeze haram olsun. Benden baskasi sevmesin seni, Benden baskasi çekmesin derdini, Bensizligi istiyor...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/haram-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkim Degilmis', 'hakkim-degilmis-mustafa-aslan-2-iozd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkez ben asigim,

Aski yasiyorum der,

Ama ask artik kitaplarda kaldi.

Herkez seviyorum, seviliyorum der,

Ama severler, sevmek kolaydir,

Sevilmek ise hakketmektir.

Demekki ben hakketmedim.

Tarih Ve Saati: 02/11/2003	04:35', 'Herkez ben asigim, Aski yasiyorum der, Ama ask artik kitaplarda kaldi. Herkez seviyorum, seviliyorum der, Ama severler, sevmek kolaydir, Sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hakkim-degilmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Koynumda Resmin', 'hala-koynumda-resmin-mustafa-aslan-2-rnexp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala koynumda resmin,

Gözümde gözlerin,

Gönlümde hala sözlerin,

Kalbimde kaldi özlerim.

Çekip gittin bir sey söylemeden,

Hiç bunun sonunu düsünmeden,

Çekip gittin gönlümden,

Sildim gözlerimden kanli yaslari.

Nerdesin, nezaman döneeksin,

Bir gün sende seveceksin,

Benim çektigimi çekeceksin,

Ozaman beni özleyeceksin,

Belkide ogün geri döneceksin.

Birakma dedimde neoldu,

Habersizce hayallerimden kayboldu,

Geldik sona, hayatin sonumu bu,

Akan kanmidir, yoksa bir damla su''mu.

Sevmek dedikleri, yoksa bumu.

Hala sakliyorum koynumda resmini,

Resminle beraber olan sevgimi.

Bekliyorum, gelecesin biliyorum,

Hala seni seviyorum

Tarih Ve Saati: 17/11/2004	21:00', 'Hala koynumda resmin, Gözümde gözlerin, Gönlümde hala sözlerin, Kalbimde kaldi özlerim. Çekip gittin bir sey söylemeden, Hiç bunun sonunu dü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hala-koynumda-resmin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mustafa-aslan-2-9ko30', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suya hasretken,

Damla damla su döktüler yerlere.

Sana hasretken,

Hasretinle beni yerle bir ettiler.

Kendime hasretken,

Beni derin gecelerde eskilttiler.

Tarih Ve Saati: 04/05/2005     00:09', 'Suya hasretken, Damla damla su döktüler yerlere. Sana hasretken, Hasretinle beni yerle bir ettiler. Kendime hasretken, Beni derin gecelerde ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasret-320-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatira Defteri', 'hatira-defteri-mustafa-aslan-2-utlde', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açtim sayfalarini hatira defterimin

Yasadim yine geçen yillarimi

Yorgun düstüm en bastan

Sonuna gelemdim hatira defterimin

Zorda olsa yasadim

Birer birer yazdim hatira defterime

Agladim ilk sayfayi okurken

Hayatimda sevdigimi yazarken

Herzaman sever, yorgun düser

Gözlerim bikar, gönlüm yikar

Hayat bakar, kader satar

Simdi yorulmus, yerime oturmusum

Baktim son sayfasinda

Kararmis dünyam, sarsilmis

Son sayfada gül yapragi vardi

O bile yasadiklarimin içinde sararmis

Simdi eski halimden eser yok

Gönlüm yorulmus

Sevecek hal kalmamis bende

Tarih Ve Saati: 21/10/2004	22:54', 'Açtim sayfalarini hatira defterimin Yasadim yine geçen yillarimi Yorgun düstüm en bastan Sonuna gelemdim hatira defterimin Zorda olsa yasadi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatira-defteri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hataliyim', 'hataliyim-mustafa-aslan-2-9tm1g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni zorla degistirmek istediysem hataliyim,

Seni kendime benzetmek istediysem hataliyim,

Seni sen olarak kabul etmediysem hataliyim,

Sensiz kaldimsa ben hataliyim,

Seni sen oldugun için sevmediysem hataliyim,

Seni baskasina yar edersem hataliyim,

Sensiz bir hayat yasarsam bilmelisin hataliyim,

Bu dünya bana karsi hep benmi hataliyim,

Yalniz kaldim yine ben hataliyim.

Bak askim beni iyi dinle,

Sensiz olduguma sakin sevinme,

Degisiyorum senin için iste sevin zaman geldi,

Eger sana laik biri degilsem ben hataliyim,

Kendimi sana sevdiremezsem ben hataliyim,

Zaman eger bana karsiysa ben hataliyim,

Bunu bilki askim ben sensiz olursam ben hep hataliyim,

Askim bak dinle bu söylediklerimi,

Ben hep hataliyim,

Yeterki sen yanimda kal,

Ben hep hatali olmaya raziyim.

Seni seviyorum ve sensiz olamam.

Yasadigimiz günleri ölsemde unutmam.

Tarih Ve Saati: 01/08/2005	01:37', 'Seni zorla degistirmek istediysem hataliyim, Seni kendime benzetmek istediysem hataliyim, Seni sen olarak kabul etmediysem hataliyim, Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hataliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatirlarmisin', 'hatirlarmisin-mustafa-aslan-2-08iys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatirlarmisin,

Ilk tanistigimiz o günü,

Nasilda mahsum bakiyorduk birbirimize.

Hatirlarmisin,

O ilk oynadigimiz oyunu,

Yalandan hep yenilirdim,

Senin gülüsünü izlemek için.

Hatirlarmisin,

O sana ilk sarildigim günü,

Nasilda titriyorduk,

Sen bana sormustun,

Çok mu soguk? 

Hayir o ilk sarilmanin heycaniydi,

o heycan hala var bende.

Hatirlarmisin,

Ilk seni öptügüm günü,

Nasilda korkarak öpüyordum,

Dudaklarin yüregimi yakar diye.

Hatirlarmisin,

Seni seviyorum dedigim ilk günü,

Nasilda korkuyordum,

Ayni sözü duyamam diye.

Hatirlarmisin,

Beni nasil bir anda yiktigini,

Sana söz söyledim diye,

Bana bakarak,

Sanki haykirircasina,

Sanane diyisini.

Bence bunlari iyi hatirlarsin,

Benim için unutulmaz günlerdi,

Simdi herkez bilecek,

Bu sir varya,

Bütün gönülleri titretecek.

En sonunda varya,

DeRTLi-SaiR bile ölecek.

Tarih Ve Saati: 19/07/2005	01:24', 'Hatirlarmisin, Ilk tanistigimiz o günü, Nasilda mahsum bakiyorduk birbirimize. Hatirlarmisin, O ilk oynadigimiz oyunu, Yalandan hep yenilird...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hatirlarmisin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-mustafa-aslan-2-2hook', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykudan uyandim,

Bir gece,

Apansiz,

Gözlerim,

Ates atesti.

Seni düsünüyorum,

Ellerim soguk,

Yazmak için uzaniyorum,

Kagit islak,

Elini koy,

Kalbimin üstüne,

Bir ritm duyacaksin,

Kalbim var ya,

Kirik.

Sen,

Sadece bana baktin,

Buz tutmustun,

Sanki,

Duvardin,

Tastin.

Üsüyordum,

Titriyordum,

Ama,

Ellerimi, 

Hiç tutmadin.

İlk o zaman anladim,

Sevmeyi hiç bilmedigini,

Kendinden,

Baska birini,

Ve

Hemen,

Senden,

Kaçtim.

Hayat halen beter,

Hayat halen gider,

Hayat cekilmiyor,

Ustune bastigim kader,

Ben ne yaptim kader sana,

Düsman ettin beni bana,

Hasretle ask hep yan yana,

Gönül verip suna buna

Hep sonunda bos çikacak.

Karanlikti odam,

Duvarlar renksiz,

Pencere kapali,

Nefes almak çok zor simdi,

Kültablasi hala yerinde,

Üzerimde sen,

Karanlikta,

Rüzgara karsi yürürken,

Gece açiyor kapisini,

Yüregime.

sarkilar mirildaniyorum,

Kendi kendime.

Yine yeni bir sevda,

Yine ben,

Kötüyüm su saatlerde,

Bir haftadir, 

Aklimdan çikmayan sen,

Simdi iyice yakin,

Benimle karanliga.

Belirsizlik var,

Sevdamda,

Hatta,

Her seyde! 

Tarih Ve Saati: 11/12/2004		15:20', 'Uykudan uyandim, Bir gece, Apansiz, Gözlerim, Ates atesti. Seni düsünüyorum, Ellerim soguk, Yazmak için uzaniyorum, Kagit islak, Elini koy, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/hayat-281-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Aci Dolu', 'hayat-aci-dolu-mustafa-aslan-2-pxw7m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Inanmazsin gülmek haramdir,

Sevmek dersen,

Kalbimdeki yaramdir.

Kalbimizdeki yarayi,

Sevdamiz saniyoruz,

Oysa çok yaniliyoruz.

Kalbimizdeki yara,

Dert doluymus.

Kimse bilemedi,

Veya bilmek istemediki,

Hayat aci dolu.

Tarih Ve Saati: 29/05/2005     00:17', 'Inanmazsin gülmek haramdir, Sevmek dersen, Kalbimdeki yaramdir. Kalbimizdeki yarayi, Sevdamiz saniyoruz, Oysa çok yaniliyoruz. Kalbimizdeki ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-aci-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Adami', 'hayat-adami-mustafa-aslan-2-icnnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben oldum bir hayat adami,

Gezdim gece gündüz sokaklarda,

Hiç sansim olmadi askta,

Belkide benim yasam seklim baska.

Artik gülmez kader yüzüme,

Inanmaz kimse sözüme,

Aciyi kattilar özüme,

Kimse bakmaz artik gözüme.

Aglar dururum sormam neden,

Ne istedi felek benden.

Kötü yollara düsmem,

Geceleri sevda atesi varken üsümem.

Bir kere söyle bana beni sevdigini,

Istersen artik çek git,

Seni seviyorum sözün,

Aklimdan çikmayacaktir.

Karsinda beni bul,

Sevdam ile sende otur.

Bogazim dügüm dügüm olmus,

Belkide benim kaderim buymus.

Korkma yürü bana dogru,

Düsmene izin vermem,

Olmusum hayat adami,

Zamana birakirim kendimi.

Hayat adami nedir,

Yasadini söyleyemeyen kisidir,

Herzaman sevipte, aldatilan,

Yarali olan kisidir.

Tarih Ve Saati: 17/11/2004	20:01', 'Ben oldum bir hayat adami, Gezdim gece gündüz sokaklarda, Hiç sansim olmadi askta, Belkide benim yasam seklim baska. Artik gülmez kader yüzü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-adami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Vurmus Damgasini', 'hayat-vurmus-damgasini-mustafa-aslan-2-5s80d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaderim beni hiç güldürmüyor

Hergün beni aglatiyor

Damgasini vurmus kalbime

Sokmus beni sahte günlere

Yasam sevincim kalmamis

Gülmekte neymis yasamamis

Aglamak, cesme gibi aglarmis

Ruhumda bu yüzden yorulmus

Bir gün güldürmedi kaderim beni

Dogmus dogali aglatiyor

Bilmem benden daha ne ister

Bir canim kaldi alsada kurtulsam

Son sözümü söyleyemedim

Birkerede olsa sevilmedim

Yasamak nedir, nasildir bilemedim

Hayatin damgasini kalbimden silemedim

Damgayi vurdu bana

Yarali olarak koydu yollara

Hayat vurma yeter

Bilemezsin kalbim benden beter

Kirma yeter 

Yoksa

Oda beni birakip gider

Vurdun damgani anladik

Mutlulugu yasakladin boyun eydim

Güldürmedin, zaten gülemiyordum

Aglamakla geçti yillarim

Artik istedigin kadar vur hayat damgani

Tarih Ve Saati: 13/10/2004	18:52', 'Kaderim beni hiç güldürmüyor Hergün beni aglatiyor Damgasini vurmus kalbime Sokmus beni sahte günlere Yasam sevincim kalmamis Gülmekte neymi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-vurmus-damgasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kadini', 'hayat-kadini-mustafa-aslan-2-k7y73', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ON ALTI yasinda 

Çikmisti ask pazarina 

Çok sey ögrenmisti. 

Kötülükler çoktu 

Ama gerçek oyunda buydu. 

Sonunda o da bir insan 

Her sey hizla geçsin ister 

Ask da, hatta keder de. 

Arar dün geceki gözyaslarini? 

Arar geçen yillarini

Arar geçen günlerini

Elbet zamanla 

Daha kolay gidilir 

Ask pazarina 

Ve daha hizli geçer orada yillar 

Fakat duygulari 

Korkuyla soguklasir

Insanlar serefsiz olunca 

O çekermis hayatin kahrini 

         

Iyi ögretilirse pazarlik 

Askin pazarinda

Nefsini paraya dönüstürmek 

Hiç de kolay degildir 

Simdilik bu kadar yetistirebiliyor

Ne de olsa yaslaniyor insan 

Yillar geçiyor

Hep 16 sinde kalamazya

Birde sizler düsünün

Tarih Ve Saati: 24/10/2004	13:48', 'ON ALTI yasinda  Çikmisti ask pazarina  Çok sey ögrenmisti.  Kötülükler çoktu  Ama gerçek oyunda buydu.  Sonunda o da bir insan  Her sey hiz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-kadini-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatim', 'hayatim-mustafa-aslan-2-wlu35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatmak istiyorum derdimi,

Acaba dinleyen olacak mi? 

Bu siir de yazdiklarimi,

Kimse ciddi olupta,

Okuyacak mi? 

Yaziyorum bu siirde kisa bir hayatimi,

Hep acilarla dolu olan,

Hep iskence içinde,

Yasadigim hayatimi anlatiyorum.

Çocuk yasimda geldim,

Gurbet denen batakliga,

Kendime bir yol çizmek istedim,

Hiç bir yol bulamadim,

Hergün agladim,

Özlem çekiyordum,

Hergün kavga vardi evde,

Babam hergün evden kovardi,

Annem hep acilarla yasadi,

Kimin için mi? 

Bizim için,

Ben ve iki abim için,

Daha çocuk yastaydik,

Hayatin anlamini bilemiyorduk,

Kendimizi derslerimize vermistik,

Taki ben ilk defa asik oldugum güne kadar,

Birini sevmistim,

Oda beni seviyordu,

Ama kader aglarini örmüstü,

Sevdigimi ecel aldi elimden,

Küçüktüm,

Daha 14 veya 15 yasindaydim,

Sevdigimin ölümünden sonra kendimi siirlere verdim.

Belki ondan osnra çok sevmisimdir,

Ama hiç birinde sevilmedim,

Sevgiyi disarida ariyordum,

Yillardir da aradim,

Ama hiç bulamadim,

Hergün gizlice agladim,

Hayatima isyan ettim,

Dertlerimi kimseyle paylasamadim,

Anlattiklarim kisiler tarafindan dinlenilmedi,

Dinlenildiyse bile alay ettiler,

Bende derdimi siirlerle anlatmaya basladim.

Erkek adam aglar mi? 

Aglarmis,

Hemde kana kana,

Içini çeke çeke.

Ailem dagilmisti,

Ve sonunda olan oldu,

Artik olgunlasmistik,

Ben ve abilerim kendi ayaklarimizin üstünde durabiliyorduk,

Ve annem artik dayanamiyordu,

Hergün aglamaktan,

Hergün bizim ezildigimiz görmekten bikmisti,

Ve en sonunda babamdan ayrildik,

Çok olay geçti aramizdan,

Ama biz yilmadik,

Dayandik,

Babasizliga zaten çocuk yasta alismistim,

Babam gurbet ellerde,

Bizse türkiyede geçim savasindaydik,

Annem yemedi yedirdi,

Giymedi giydirdi,

Tek istedigi okuyup adam olmamizdi,

Ama nerde bizde o yürek,

Biz kim adam olmak kim,

Hay yiyip Harman savurduk,

Anneme belkide hiç destek olmadim,

Hep kendimi düsündüm.

Simdi hala babasizligi yasiyorum.

Bazen onun arkasindan söz sayiyorum,

Bazende onun için kana kana agliyorum,

Babasizligi iyi bilirim,

En bastata sevgisini.

Hep bir yolda gidecegim dedimya,

Bu yol askin yoluydu,

Beni seveni bulmak istiyordum,

Ama bulamiyordum,

Okulu biraktim 2003/2004 yilinda,

Annem yikilmisti,

Oysa ben çalisip kendi ayaklarimin üstünde durmak istiyordum,

Ama oda olmadi,

Çalistim,

Ama ha var ha yok,

Para heresy degilmis,

Sevgiden mahrum büyüdüm,

Sadece anne sevgisi,

Diger sevgilerden mahrumdum.

Dayanamadim,

Adam olmak için okula tekrar basladim,

Ilk 3 ay çok iyi geçti,

Ama ondan sonra,

Tekrar hastaligima yenik düstüm.

Bir taraftanda iyiydi aslinda,

Birine asik olmustum okulda,

Okadar sicak,

Okadar can yakin biriki,

Onu benim olmadan kiskanmaya baslamistim,

Yaninda erkek gördümmü deliriyordum,

Tanismistik,

Konusup, dertlesiyorduk,

Çok iyi anlasiyorduk,

Ama ona onu sevdigimi anlatamiyordum.

Bekliyordum sadece.

Ramazan bayrami geldi,

Bende ona numarami vermistim,

Bana mesaj atarak,

Bayramimi kutlamisti,

Bende onun,

Ve onun için yazdigim siiri göndermistim,

Çok hosuna gitmisti,

Bir an dayanamadim,

Ve onu sevdigimi yazmaya basladim,

Ama cesaret edemedim göndermeye,

Ama arkadasim yanlislikla gönder tusuna basti,

Ben gitmesin diye telefonu bile kapattim,

Ama gitmisti,

Okumus ve sasirmisti,

Belkide sevinmisti.

Bir ay böyle bekledim,

Ondan bir cevap bekliyordum.

Ara sira bulusup konusuyorduk,

Bazen telefonla konusurduk,

Bazende gecelerce mesaj yazardik,

Içimde bir korku vardi,

Sevmemeye yemin etmistim,

Ve onun için yeminimi bozmustum,

Ya buda beni sevmezsen,

Ya beni sevipte, birakip giderse,

Ben ne yapardim,

Bilemiyorum.

Ama bekleyisimden sonra,

Evet cevabini aldim,

Ve bir anda sanki dünyanin en mutlu kisisi bendim.

Ikimizin düsünceleri çok degisikti,

Ama ikimizde birbirimizi üzmemek için elimizden geleni yapiyorduk,

Belki oluyordu,

Belki de olmuyordu,

Bilemiyorum.

Ama yinede mutluyduk,

Ayni okulda oldugumuz için,

Birbirimize çok yakindik,

Bu hosumuza gidiyordu,

Ama dedi kodulardan korkuyorduk.

Ama artik hiçbirsey farketmiyor,

Biz beraberiz,

Ve beraberligimizi nerdeyse herkez biliyor.

Bazen onu kirdigim oluyor,

Aslinda bazen degil,

Haftanin 4 gününü kesin onu kirarak geçiriyordum,

Bazi yönlerden hakliydim,

Bazi yönlerdende haksizdim, çok abartiyordum,

Ama elinde degilki,

Onu kimseyle paylasmak istemiyordum,

Sadece ben bakayim, kimse bakmasin,

Sadece ben yaninda oturayim, baskasi yaklasmasin,

Bilmiyorum belki gerçekten sevmeyi abartiyorum,

Ama elimde degil,

Onu ölümüne seviyorum.

Ona olan sevgim gün geçtikçe artti.

Yarin Pazar,

8 mayis 2005,

Yarin bizim beraberligimizin 5. ayi,

Daha çok güzel günler geçecek bence.

Ailem karsi çikiyordu bu iliskiye,

O yüzden aileme güvenim kalmamisti,

Baskalariyla geçinip,

Baskalariyla arkadaslik yapiyordum,

Taki beni arkamdan vurduklari güne kadar,

Iste o gün anladim,

Tek güvenebilecegim kisiler,

Ailemmis ve tek sevdigim.

Simdi çok mutluyum,

Hem ailemle,

Hem sevdigimle,

Sevildigimi hissedebiliyorum.

Iste bu benim çok kisa özetlenmis bir hayatim,

Belkide size uzun gelecek,

Okumayacaksini,

Sadece basini ve sonunu kontrol edeceksiniz,

Ama farkertmez.

O sizin bileceginiz bir sey.

Benden bukadar,

Inanmazsiniz,

Bu siiri yazarken okadar çok agladimki,

Bir anda heresy gözümde bastan canlandi.

Bir seyi simdi iyi bilinki,

Artik çok mutluyum.

Ve bu siir askimi ölümsüzlestirecek.

Tarih Ve Saati: 07/05/2005	19:16', 'Anlatmak istiyorum derdimi, Acaba dinleyen olacak mi?  Bu siir de yazdiklarimi, Kimse ciddi olupta, Okuyacak mi?  Yaziyorum bu siirde kisa b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":190,"source_url":"https://www.antoloji.com/hayatim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatimin Anlami', 'hayatimin-anlami-mustafa-aslan-2-3r4nx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatimin anlami sensin,

Sen sevdamin kendisisin,

Öyle sevmisimki seni,

Kimse bu asktan yildiramaz beni.

Güldügün de yüzünde güller açiyor,

Sevgini kalbime saçiyor,

Agladiginda yüregim aciyor,

Seninle beraber benim gözlerimde sanciyor.

Sana baktigimda gözlerin parliyor,

Her bakisinda ask yatiyor,

Sözlerin mutluluk,

Bakislarin bana umut veriyor,

Biliyorum kalbim yalniz seni seviyor.

Elini tuttugumda uçar gibi oluyorum,

Senin askinla bende yaniyorum,

Beni öptügünde heycandan titriyorum,

Tenindeki kokuyla kendimden geçiyorum,

Simdi çok iyi anladimki,

Seni ben deliler gibi seviyorum.

Ya sen? 

Tarih Ve Saati: 13/01/2005		13:31', 'Hayatimin anlami sensin, Sen sevdamin kendisisin, Öyle sevmisimki seni, Kimse bu asktan yildiramaz beni. Güldügün de yüzünde güller açiyor, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayatimin-anlami-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatimin Anlami Oldu', 'hayatimin-anlami-oldu-mustafa-aslan-2-ubg88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimde yanan bir ates var. 

Gözyaslarinla söndüremezsin. 

Içimde bir sevda var. 

Istesende öldüremezsin. 

Beni bir kere aglattinya. 

Ölsende güldüremezsin.

Sevdanin adina kandim, 

Bende sevdalandim. 

Gülüsüne kandim, 

Kendimi insandan saydim. 

Gözlerine kandim, 

Bakisinla beni kandirdin. 

Sana kandim da ne oldu, 

Hiç degilse hayatimin bir anlami oldu.

Tarih Ve Saati: 16/08/2005     05:45', 'Kalbimde yanan bir ates var.  Gözyaslarinla söndüremezsin.  Içimde bir sevda var.  Istesende öldüremezsin.  Beni bir kere aglattinya.  Ölsen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayatimin-anlami-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Mi Aci Çekecegiz', 'hep-mi-aci-cekecegiz-mustafa-aslan-2-p9ti7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep mi aci çekecegiz,

Inslanlardan uzak,

Kendi kendimize yanacagiz,

Giden gelmez,

Gelense görünmeden gitmez,

Acilari yasatir bastan.

Neden hersey arka arkaya geliyor,

Birgünlük mutlulgumuzu yikiyor,

Hiç kimse mi vijdan azabi çekmiyor,

Neden hep yalnizlik bize hakim oluyor.

Bazen uzaklardayin,

Düsünüyorum,

Daha ne olabilirki! 

Acilar bizede hakim olmus,

Yönetemiyoruz hayatimizi.

Hergün göz yasi,

Bilemiyorum,

Hani sen ve ben yenilmezdik,

Hani hep beraberdik,

Kusura bakma,

Hersey üst üste geldi,

Sende her konuda aci çekmeye basladin.

Çok korkuyorum,

Sende bana benzeyeceksin diye,

Hergün göz yasi,

Hergün aci ve keder,

Bunlari sende mi yasayacaktin.

Birak sen yasama bunlari,

Sen sadece gül,

Sen gülki,

Senden kuvvet alip,

Senin yerinede o acilari ben çekeyim,

Sen sadece gül,

Sen gülki,

Benim gibi güllerin solmasin.

Tarih Ve Saati: 17/03/2005	18:14', 'Hep mi aci çekecegiz, Inslanlardan uzak, Kendi kendimize yanacagiz, Giden gelmez, Gelense görünmeden gitmez, Acilari yasatir bastan. Neden h...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hep-mi-aci-cekecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayellerim', 'hayellerim-mustafa-aslan-2-4uxwr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'H'' ayret ettim böyle bir aska

A'' klimdan çikmiyorsun bakisin baska

Y'' animdan geçip bana sasma

E'' limden askimi alma

L'' ale gibi benide soldurma

L'' anet ettirme bana

E'' sir etme beni sana 

R'' üyami çevirme kabusa

I'' nandirma senin yalanlarina

M'' utluyken neolur benden kaçma

Tarih Ve Saati: 09/07/2004	17:55', 'H'' ayret ettim böyle bir aska A'' klimdan çikmiyorsun bakisin baska Y'' animdan geçip bana sasma E'' limden askimi alma L'' ale gibi benide sold...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayellerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatin Gözyaslari', 'hayatin-gozyaslari-mustafa-aslan-2-qn08u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatin gözleri olmus bir damla kan

Hayatin kendisi bizi aglatan

Derdimize dert katan

Kalbimizde yatan

Ama bizi herseferinde satan 

Hayatin gözyaslari olmus yalan

Varmidir artik geri kalan

Hayatla bir olup, derdine derman bulan

Yorgun düstüm artik aglamaktan

Yorgun düstüm artik yasamaktan

Yorgun düstüm artik kahrolmaktan

Yorgun düstüm artik kan kusmaktan

Yorgun düstüm derdime derman aramaktan

Yorgun düstüm hayatin gözyaslarini tutmaktan

Zor hemde zor

Benide yor hayat benide yor

Derdimin dermani ol

Kalbimin atesi ol

Yüregimin yarasi ol

Ol ki hayat gözyaslarini dökmeyeyim

Artik biktim aglamaktan

Her adimimda yorulmaktan

Nefes nefese kalmaktan

Nezaman güleceksin bana kader

Agir geliyor, tasiyamiyorum yeter

Bilki bu gözyaslarim elbet biter

Ozaman gözlerim seni siler

Hayat gözyaslari ise sonsuzluga gider

Tarih ve Saati: 05/10/2004	20:17', 'Hayatin gözleri olmus bir damla kan Hayatin kendisi bizi aglatan Derdimize dert katan Kalbimizde yatan Ama bizi herseferinde satan  Hayatin ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayatin-gozyaslari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Yalan', 'hepsi-yalan-mustafa-aslan-2-gd7gu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum derler ya,

Sakin inanma.

Sensiz yasamak haram derler ya,

Sen sen ol sakin kanma.

Insan ogluna güven olmaz ya,

Dogrudur, hepsi yalan.

Zaman kör kursun gibidir,

Hayatini deler geçer,

Milyonlarca insan arasindan seni seçer,

Bilesinki acilar seni dünyadan biçer.

Söylenenler gerçek mi acaba,

Gün gelipte ölüm dösegine yattigin zaman,

Gerçekleri iste o gün görürsün,

Herkeze anlatmak istersin,

Ama gücün yetmez,

Sana herseyin yalan oldugunu söyler,

Ama sen duymazsin,

Inanki dostum,

Söylenenlerin,

Yasananlarin,

Sevenlerin,

Hepsi yalan.

Ask desen sanki ölmüs,

Kefensiz mezara gömülmüs,

Kahrolan asklar varya,

Inan dostum hepsi yalan,

Seni senden alir da,

Insanliktan uzak tutar,

Herseyi anlatan sadece 2 kelime,

HEPSi YALAN! 

Tarih Ve Saati: 19/03/2005	21:09', 'Seviyorum derler ya, Sakin inanma. Sensiz yasamak haram derler ya, Sen sen ol sakin kanma. Insan ogluna güven olmaz ya, Dogrudur, hepsi yala...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hepsi-yalan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsini', 'hepsini-mustafa-aslan-2-d9nob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir insana inanman için,

Onu sevmen gerekir.

Onu sevmen için,

Güvenmen gerekir.

Ona güvenmen için,

Ona asik olman gerekir.

Asik olman için,

Hepsini yapman gerekir.

Zor olan buya.

Tarih Ve Saati: 05/11/2003	05:24', 'Bir insana inanman için, Onu sevmen gerekir. Onu sevmen için, Güvenmen gerekir. Ona güvenmen için, Ona asik olman gerekir. Asik olman için, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hepsini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gece Yatagimda Uykusuz', 'her-gece-yatagimda-uykusuz-mustafa-aslan-2-q2s0y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece yatagimda uykusuz,

Seni bekliyorum,

Belki gelirsin,

Görürüm diye,

Belki gelir bana seslenirsin,

Sesini duyarim diye.

Gecelerim uykusuz geçer,

Hep seni düsünürüm,

Düsünürken,

Bazen güler,

Bazen aglarim.

Mutlulugu sende buldum,

Yasadiklarimiza gülerim.

Hayatimi sende kaybettim,

Yasadiklarimiza aglarim.

Sen güldün mü,

Gecelerim senlenir.

Sen küstün mü,

Geceler darilir bana,

Susar konusmaz bana.

Her gece yatagimda uykusuz,

Seninle yasadiklarim,

Aci ve tatli,

Çirkin ve güzel,

Mutlu ve mutsuz günlerimi düsünürüm.

Tarih Ve Saati: 15/05/2005	18:34', 'Her gece yatagimda uykusuz, Seni bekliyorum, Belki gelirsin, Görürüm diye, Belki gelir bana seslenirsin, Sesini duyarim diye. Gecelerim uyku...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-gece-yatagimda-uykusuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Saat Basinda', 'her-saat-basinda-mustafa-aslan-2-tk0ix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canim hatirliyormusun,

Parmagina taktigim yüzügü,

Ve benim yüzügümü,

Bende manevi anlami çok,

Seni tamamen hatirlamak için,

Öperim yüzügümü,

Her saat basinda,

Sen yokken yanimda.

Birtanem,

Sende öp benim için,

Hatirla her saat basinda beni.

Sen benim en son eserimsin,

Seni ben kesfettim,

Görmeyen gözler kör,

Seni birtek benmi gördüm,

Gördüm,

Zamanla güzelliginden,

Bende kör oldum,

Seni gören gözler kör olmus,

O yüzden sen sevgisizdin.

Ben seni bulduktan sonra kör oldum,

Her saat basinda yüzügümü öpüp kalbime koydum.

Sende öp, kalbine koy,

Hatirla beni,

Her Saat Basinda.

Tarih Ve Saati: 18-11-2005	04:19', 'Canim hatirliyormusun, Parmagina taktigim yüzügü, Ve benim yüzügümü, Bende manevi anlami çok, Seni tamamen hatirlamak için, Öperim yüzügümü,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-saat-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hergün Yalniz', 'hergun-yalniz-mustafa-aslan-2-k1ras', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnizim hergün yalniz,

Kaderimle basbasa,

Yalniz seni seviyorum,

Neden ben diye sorma,

Neden sen bende bilmiyorum.

Yalniz seni özlüyorum,

Neden bende bilmiyorum.

Tarih Ve Saati: 08/12/2003	01:40', 'Yalnizim hergün yalniz, Kaderimle basbasa, Yalniz seni seviyorum, Neden ben diye sorma, Neden sen bende bilmiyorum. Yalniz seni özlüyorum, N...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hergun-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkez Der', 'herkez-der-mustafa-aslan-2-lvnja', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkez der,

Yasamak güzel,

Ben neden yasayamiyorum.

Herkez der,

Ask güzel,

Ben neden aski tadamiyorum.

Herkez der,

Gülmek güzel,

Ben neden hep agliyorum.

Herkez der,

Sevmek zor,

Ben neden hep zoru seçiyorum.

Seni sevmek zorsa,

Suçsa,

Günahsa,

Varsin ne olursa olsun,

Artik bende seni seviyorum.

Tarih Ve Saati: 19/08/2002	23:23', 'Herkez der, Yasamak güzel, Ben neden yasayamiyorum. Herkez der, Ask güzel, Ben neden aski tadamiyorum. Herkez der, Gülmek güzel, Ben neden h...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/herkez-der-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkez Neden Düsman', 'herkez-neden-dusman-mustafa-aslan-2-40yqp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki bir bizmi sevdik bu dünyada,

Bir bizmi yasadik mutlulugu,

Herkez bir anda bize karsi,

Ayirmak isterler,

Yikmak,

Yok etmek,

Sevgiyi nefrete döndermek,

Herseyi yasanmaz hale getirmek,

Bizi neden mahvetmek isterler.

Kime ne zararimiz var,

Kendi halimizde,

Aci,

Hüzün dolu,

Yalnizlik,

Mutluluk,

Hayeller,

Güzel günler,

Umutlar,

Bunlarla yasarken bizden ne isterler.

Bu sevgiye herkez neden düsman,

Birakmazlar,

Hep aglatirlar neden.

Sanki bir bizmiyiz mutlulugu arayan,

Ararken bütün acilara dayanan,

Birakin gitsin,

Birakin yasasin,

Birakin ölmesin bu sevda.

Tarih Ve Saati: 01/08/2005	01:48', 'Sanki bir bizmi sevdik bu dünyada, Bir bizmi yasadik mutlulugu, Herkez bir anda bize karsi, Ayirmak isterler, Yikmak, Yok etmek, Sevgiyi nef...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/herkez-neden-dusman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sevmedin', 'hic-sevmedin-mustafa-aslan-2-mv8f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen beni hiç,

Hiç ama hiç sevmedim.

Oysa ben hayatimi sana vermeye hazirdim,

Sen benim kalbimde olacaksin.

Son askim kalacaksin,

Ama unutma,

Birgün gelecek,

Sende yalnilikla bogusacaksin,

Hergün aciyla kivranacaksin,

Sende aglayacaksin.

Ve iste o gün,

Bendeki günleri arayacaksin.

Daha çok arayacaksin.

Tarih Ve Saati: 09/03/2003	01:10', 'Sen beni hiç, Hiç ama hiç sevmedim. Oysa ben hayatimi sana vermeye hazirdim, Sen benim kalbimde olacaksin. Son askim kalacaksin, Ama unutma,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-sevmedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Içimdeki Yangin', 'icimdeki-yangin-mustafa-aslan-2-ul17a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alev alev yaniyor,

Tutusmus sönmüyor,

Sensizligi yasiyor,

Ama küle dönüsmüyor.

Sadece yaniyor kalbim,

Tutusuyor yüregim,

Sensizligi seviyor gönlüm,

Yaniyor,

Sönmek bilmiyor,

iÇimdeki yangin.

Derdimin dermani sensin,

Yaramin melhemi sensin,

Atesimi söndürecek su sensin,

Sen benim herseyimsin.

Seni sensiz yasiyorum,

Hergün birazdaha yoruluyorum,

Ama sevmekten vazgeçmiyor,

Benim bu deli gönlüm,

Gönlüm vazgeçse,

Ruhum vazgeçmez senden.

Seni yazdim,

Silinmez yaziyla kalbime.

Seni çizdim,

Sensiz dünyama.

Nereye,

Kime,

Baksam karsimda sen varsin.

Çok korkuyorum,

Seni sevdigimi,

Senin için ölecegimi,

Baska bir sevgili bulunca,

Beni unutursun diye,

Ölümden degil,

Senden uzak durmaktan,

ÇOK KORKUYORUM,

Söndür içimdeki yangini.

Tarih Ve Saati: 05/12/2004		12:41', 'Alev alev yaniyor, Tutusmus sönmüyor, Sensizligi yasiyor, Ama küle dönüsmüyor. Sadece yaniyor kalbim, Tutusuyor yüregim, Sensizligi seviyor ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/icimdeki-yangin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hosgeldin', 'hosgeldin-mustafa-aslan-2-fcfyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun zaman boyunca ayri,

Ve sevginden mahrumdum,

Simdi yine beraberiz,

Hosgeldin,

Yeniden gönlüme.

Sensizlige son,

Mutluluga yeni bir adim.

Hosgeldin,

Umutlar.

Hosgeldin,

Askim,

Hosgeldin.

Tarih Ve Saati: 11/08/2005     03:39', 'Uzun zaman boyunca ayri, Ve sevginden mahrumdum, Simdi yine beraberiz, Hosgeldin, Yeniden gönlüme. Sensizlige son, Mutluluga yeni bir adim. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hosgeldin-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yagmuru', 'huzun-yagmuru-mustafa-aslan-2-wezc9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yagar yagmur durmaz birgün,

Seni sevdigim günden beri,

Anlar bulutlar beni,

Bu benim hüznümün yagmuru.

Çileler içinde yasamim geçti,

Içinde var hayatin hilesi,

Vardir kaderimin cilvesi,

Yag yagmur durma, göster sevgimi.

Ben aglarim susmam,

Isimdeki kinimi kusmam.

Hüzün yagmuru akar,

Birgün sevdalar sizide yakar.

Akar damla damla yaslar gözümden,

Yemin ettim dönmem sözümden.

Ya sen Ya hiç dedim,

Artik kimseyi sevemezdim.

Bir yanda felegin sillesi,

Bir yanda sevdamin atesi,

Bir yanda sen varsin,

Diger yanimda mezarim.

Sevdam sönerse kendimi gömerim,

Sen sönersen ruhumu gömerim.

Artik dayanmaz gözlerim kurur oldu,

Hüzün yagmurlarida durdu.

Kalbimde güvendim seni sevdi,

Beynime güvendim mezarima bakti.

Agladikça günlerim gitti,

Ve bu hüzün yagmuru böylece bitti.

Tarih Ve Saati: 17/11/2004	20:11', 'Yagar yagmur durmaz birgün, Seni sevdigim günden beri, Anlar bulutlar beni, Bu benim hüznümün yagmuru. Çileler içinde yasamim geçti, Içinde ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/huzun-yagmuru-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihanet, Kin Ve Nefret', 'ihanet-kin-ve-nefret-mustafa-aslan-2-aofup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni çok sevmistim,

Hemde canimdan çok,

Sen ise askima iHANET ettin,

Simdi mutlumusun bakalim,

Simdi umutlumusun söyle,

Söyle ama bana degil yüreyine söyle,

Içimde bir duygu kaldi,

Oda sana duydugum KiN dir,

Neden neden ben diye sormuyorum,

Çünkü kalpsizleri seçiyorum,

Ve o kalpsizleren artik NEFRET ediyorum,

Ama en büyük nefretim sensin,

Artik sende bensiz ölürsün,

Belki birgün sende beni seversin,

Ama bilki o gün yüzüne bakmam,

Yanliz duydugum duygulari belli ederim,

Bu duygular anca sana yakisir.

iHANET ettin bana,

Duydugum duygu KiN sana,

Artik sen benim  NEFRETiMSiN.

SAKIN UNUTMA! ! ! 

Tarih Ve Saati: 02/04/2003	23:38', 'Seni çok sevmistim, Hemde canimdan çok, Sen ise askima iHANET ettin, Simdi mutlumusun bakalim, Simdi umutlumusun söyle, Söyle ama bana degil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ihanet-kin-ve-nefret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ikimizede Yeter', 'ikimizede-yeter-mustafa-aslan-2-lpihs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ve Ben,

Benim askim ikimizede yeter,

Sen beni biraz sev yeter,

Sen sevilmeyi ögren yeter,

Benim askim ikimizede yeter.

Tarih Ve Saati: 08/05/2002	10:13', 'Sen ve Ben, Benim askim ikimizede yeter, Sen beni biraz sev yeter, Sen sevilmeyi ögren yeter, Benim askim ikimizede yeter. Tarih Ve Saati: 0...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikimizede-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Içimde Bir Sanci Var', 'icimde-bir-sanci-var-mustafa-aslan-2-1z2yv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben artik çok degistim,

Degisirken,

Hayatin ne oldugunu gördüm,

Görürken,

Kör olmak istedim,

Isterken yalniz kaldim,

Kör olmakta neymis,

Kimseyi göremez oldum,

Önünde yürüyen cisimler sanki bir hayel.

Içimde bir sanci var,

Sizlar durur.

Içimde bir özlem var,

Gün geçtikçe büyür.

Içimde bir sevda,

Gün geçtikce degisir.

Içimde bir sair var,

Gün geçtikçe yok olur.

Artik ben kendimi tanimaya basladim,

Kimin beni sevdigini,

Kimin nefret ettigini iyi anladim,

Kendimi baslarda eve sakladim,

Uzak durdum,

Ama kimseye yaranamadim,

Simdi geldim dis dünyaya,

Neden herkez bukadar sahte,

Bukadar bencil,

Bukadar insanfiz.

Içimde bir sanci var,

Ama bu sanci siirlere bir sigmiyor.

Tarih Ve Saati: 30/07/2005	20:56', 'Ben artik çok degistim, Degisirken, Hayatin ne oldugunu gördüm, Görürken, Kör olmak istedim, Isterken yalniz kaldim, Kör olmakta neymis, Kim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icimde-bir-sanci-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ask Masali 2', 'bir-ask-masali-2-mustafa-aslan-2-3qb11', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'B'' ir dünyam vardi yasam doluydu

I '' nanmazsin dünyam bir anda batti

R'' abbime isyanlar çogaldi

A'' sk nedir bilen yok

S'' asiriyorum aci çeken çok

K'' ahrolsun böyle yasam 

M'' utsuzluk kapimi çalmis

A'' çan açmis kaçan kaçmis

S'' onunda kaderim damgayi basmis

A'' glar gözlerim kan aglar

L'' imandan kalkan gemi benimle batar

I '' sirir kalbimi yabani insanlar

Tarih Ve Saati: 09/09/2004	03:43', 'B'' ir dünyam vardi yasam doluydu I '' nanmazsin dünyam bir anda batti R'' abbime isyanlar çogaldi A'' sk nedir bilen yok S'' asiriyorum aci çeke...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ask-masali-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilk Kez Gülüyorum', 'ilk-kez-guluyorum-mustafa-aslan-2-dpcuu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ilk kez gülüyorum,

Ilk kez yalniz degilim,

Ilk kez biri var yanimda,

Ilk kez yasama sevinci var içimde.

Bugün sana sarildigimda,

Kalbim iki kez daha hizli atti,

Bir yandan üsüyor,

Bir yandanda düsencelerimi dinliyordum.

Üsürken titriyor,

Ama seni kaybetme düsüncesi bana sok veriyordu.

Senin tenindeki sicaklik,

Beni isitmisti.

Bakislarin, gülüsün,

Birazdaha umutlandiriyordu beni.

Seninle ömrümü yasamak,

Seninle beraber yaslanmak,

Ve seninle beraber ölmek isterdim.

Ilk sarkiyi mirildadiginda,

Içimde sanki bir firtina koptu.

Hissederek, yasayarak,

Söylüyordun.

Sarkimiz kan ve gül olsun,

Ben kan,

Sen gül,

Sen beni birakirsan,

Sen kana,

Ben seni birakirsan,

Bende gül gibi solayim.

Yalnizligin sarkisini unutalim,

Sadece askimizi yasiyalim.

Tarih Ve Saati: 08/12/2004	17:43', 'Ilk kez gülüyorum, Ilk kez yalniz degilim, Ilk kez biri var yanimda, Ilk kez yasama sevinci var içimde. Bugün sana sarildigimda, Kalbim iki ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ilk-kez-guluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ikiye Böldün Beni', 'ikiye-boldun-beni-mustafa-aslan-2-g8shm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ikiye böldün beni,

Bir yanda gururum,

Diger yandanda duygularim.

Sana yenik düsüyorum,

Her gece su kenarinda üsüyorum,

Artik yetti diyorum,

Ama duygularima yenik düsüyorum.

Gururum kirilmis,

Yaramaz ise artik.

Gururum çek git diyor,

Duygularim savas diyor,

Terk etme,

Umutlarinla yasa diyor,

Gururum yikiliyor,

Duygularim yeniyor,

Neden bu oluyor,

Ruhum hiç anlamiyor.

Seviyorum delicesine,

Agliyorum ölürcesine,

Gururumu siliyorum saniyesine,

Duygularimi dinliyorum severcesine,

Bazen agliyorum gülercesine.

Ikiye böldün beni,

Dogrum nedir bilemiyorum,

Gururummu? 

Yoksa duygularimmi? 

Sen söyle hayatimin anlami.

Tarih Ve Saati: 21-12-2005     21:31', 'Ikiye böldün beni, Bir yanda gururum, Diger yandanda duygularim. Sana yenik düsüyorum, Her gece su kenarinda üsüyorum, Artik yetti diyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ikiye-boldun-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inanirmisin', 'inanirmisin-mustafa-aslan-2-ma1cg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek bir dilegim vardi,

Oda mutlu, umutlu olmakti.

Tek bir cümlem vardi,

Oda seni seviyorum.

Tek bir askim,

Oda artik siirlerim.

Tek bir ben vardim,

Simdi bende bir yalan oldum.

Buna inanirmisin? 

Tarih Ve Saati: 28/10/2003	01:08', 'Tek bir dilegim vardi, Oda mutlu, umutlu olmakti. Tek bir cümlem vardi, Oda seni seviyorum. Tek bir askim, Oda artik siirlerim. Tek bir ben ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/inanirmisin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inanma', 'inanma-mustafa-aslan-2-xr4jt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum diyen dile,

Yalandir inanma,

Seninle istemiyorsa,

Palavralar ustura.

Bunlara inanma,

Hepsi birer numara.

Yalan söylemez deme,

Gam yükünü yeme,

Yalan doludur yüreklerimiz,

Sen sen ol,

Kimseye inanma.

Seni sevse terk etmez,

Baskasiyla zaten gülemez,

Seni seviyorsa baskasini sevemez,

Sensiz bir as yiyemez.

Dünya yalan dolu,

Inanma arkadas,

Dünyanin kendisi yalan,

Dünyaya sakin kanma.

Senin tek bir dostun var,

Oda içinde yasayan sevdandir.

Senin bir dert arkadasin var,

Oda sevdanla yasayan sensin.

Tarih Ve Saati: 10/07/2005	15:14', 'Seni seviyorum diyen dile, Yalandir inanma, Seninle istemiyorsa, Palavralar ustura. Bunlara inanma, Hepsi birer numara. Yalan söylemez deme,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/inanma-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inanmak', 'inanmak-mustafa-aslan-2-wkddl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artik çok iyi anladim,

Sensizlige alismaliyim,

Hergün yalniz kalip,

Hatiralarla canlanmaliyim,

Hasretinle yanarken,

Içimdeki atesi söndürmeliyim.

Inanmak,

Sensizlige,

Sessizlige,

Özleme,

Hasrete,

Kedere,

Hüzüne,

Umutlara,

Umutsuzluga,

Mutlu olmaya,

Mutsuzluga alismaya,

Aglamaya,

Gülmeye,

Artik inanmak zorundamiyim.

Inanmak,

Sensiz yaslanmaya.

Inanmak,

Aski seninle yasadigima.

Inanmak,

Sensiz ölecegime.

Inanmak,

Inanmak,

Inanmak istemiyorum.

Tarih Ve Saati: 16/05/2005	12:00', 'Artik çok iyi anladim, Sensizlige alismaliyim, Hergün yalniz kalip, Hatiralarla canlanmaliyim, Hasretinle yanarken, Içimdeki atesi söndürmel...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/inanmak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Insan Yerine Hiç Koyulmadim', 'insan-yerine-hic-koyulmadim-mustafa-aslan-2-zo4ht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Insan yerine hiç koyulmadim,

Hep aldatildim.

Insan yerine hiç koyulmadim,

Hep ezildim, hep kovuldum.

Insan yerine hiç koyulmadim,

Sözlerimi kimseye dinletemedim.

Birgün gelir elbet insane olurum,

Birgün gelir elbet adam yerine koyulurum,

Kendime güvencim kalmadi,

Yalnizlik beni kanatlari altina aldi,

Rüzgar eserken,

Hayallerimi de benden aldi.

Insan yerine hiç koyulmadim,

Hep kullanildim,

Kirildim,

Ve bir kenara atildim,

Sözümü dinleyen olmadi,

Yalnizlik benim soyadim oldu,

Karma karisik dünyam,

Karanlikta boguldu.

Ben adam miyim,

Bence degilim,

Sesimi hiç duyuramadim,

Kör kursun gibi sagdan sola,

Namlusuz tüfek gibi karanlik bir dünyaya,

Ben acilara mahkum oldum.

Hiç insan yerine koyulmadim.

Tarih Ve Saati: 03/04/2005	18:09', 'Insan yerine hiç koyulmadim, Hep aldatildim. Insan yerine hiç koyulmadim, Hep ezildim, hep kovuldum. Insan yerine hiç koyulmadim, Sözlerimi ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/insan-yerine-hic-koyulmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Insanlar Nekadar Insafsiz Olabiliyorlarmis', 'insanlar-nekadar-insafsiz-olabiliyorlarmis-mustafa-aslan-2-4lhdx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdik diye,

Düsman oldular bize,

Aski yasattik diye,

Gömdüler topraga diri diri.

Acimadilar.

Öldürmek istediler sevdigimizi,

Korkma birtanem,

Öldüremezler,

Dünya fani,

Burda öldürseler,

Öbür dünyada yine beraberiz,

Sevgimizi öldüremezler,

Kiyamazlar,

Nekadar insafsizlar,

Hiç mi sevmediler,

Hiç mi aski tatmadilar.

Birak birtanem,

Askimiz bu dünyada öldürseler bile,

Vijdan azabi çekecekler,

Bu sevdanin bitisi,

Kiyametin baslangici olacaktir.

Tarih Ve Saati: 16/05/2005	14:38', 'Sevdik diye, Düsman oldular bize, Aski yasattik diye, Gömdüler topraga diri diri. Acimadilar. Öldürmek istediler sevdigimizi, Korkma birtane...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/insanlar-nekadar-insafsiz-olabiliyorlarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismin Kadar Güzelmisin', 'ismin-kadar-guzelmisin-mustafa-aslan-2-cz25t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ismin kadar güzelmisin, 

Güller kadar özelmisin, 

Sana gül desem gülermisin, 

Sana bir gül versem beni severmisin, 

Yoksa çekip gidermisin. 

Ismin kadar güzelmisin, 

Sana birsey desem beni dinlermisin, 

Ayriligi tattim, 

Sende istermisin, 

Hayatin gözyaslarini gördüm, 

Sende görürmüsün. 

Ismin kadar güzelmisin, 

Sana beni bekle dersem, 

Beni beklerimisin, 

Yoksa ismimi silip, 

Beni redmi edersin. 

Ama ne yazikki, 

Hayati sevemezsin.

Tarih Ve Saati: 03/08/2005	02:36', 'Ismin kadar güzelmisin,  Güller kadar özelmisin,  Sana gül desem gülermisin,  Sana bir gül versem beni severmisin,  Yoksa çekip gidermisin. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ismin-kadar-guzelmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iste Gidiyorum', 'iste-gidiyorum-mustafa-aslan-2-xoi1g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iste gidiyorum,

Önümde sira daglar,

Hepsi birbirinden yüksek,

Hepsi birbirinden aci dolu,

Yolumu kesmisler,

Umutlarima ulasamiyorum,

Her çiktigim dagda,

Daha yüksegi var karsimda,

Korkuyorum bir an,

Agliyorum,

Aglamakla kendimi avutuyorum,

Tekrar yollara düsüyorum,

Yoruluyorum,

Durup, bir nefes aliyorum,

Bir yudum suya hasret,

Sevgiye özlem çekiyorum,

Tekrar göz yasimi silip,

Yolculugama devam ediyorum,

Ama yolun sonu neresi? 

Ben bile bilemiyorum.

Sadece umutlarimi ariyorum.

Tarih Ve Saati: 15/04/2005	22:25', 'iste gidiyorum, Önümde sira daglar, Hepsi birbirinden yüksek, Hepsi birbirinden aci dolu, Yolumu kesmisler, Umutlarima ulasamiyorum, Her çik...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iste-gidiyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istemedi', 'istemedi-mustafa-aslan-2-q02gh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyayi sevdim, dert Verdi,

Doslarimi sevdim, hep kazzik yedim,

Kendimi sevdim, ama deger vermedim,

Ölümü sevmeyi denedim,

Inanmazsiniz ölüm bile beni istemedi.

Tarih Ve Saati: 13/10/2003	23:37', 'Dünyayi sevdim, dert Verdi, Doslarimi sevdim, hep kazzik yedim, Kendimi sevdim, ama deger vermedim, Ölümü sevmeyi denedim, Inanmazsiniz ölüm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/istemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istemem Ben Artik Ayrilik', 'istemem-ben-artik-ayrilik-mustafa-aslan-2-fwc88', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak yine ben söylüyorum,

Bir yaz mevsimi ben ölüyorum,

Bu ayrilik sözü varya,

Bu yürek senin için kanarya,

Açi çekerken gözlerim hep aglarya,

Olmaz gitmez bu böyle,

Yine bir ayrilik sözcügü,

Ve yine bir kabus,

Uyumaz,

Geceleri aglar bu yürek,

Seni özlerken,

Hasretini çekerken,

Dayanmaz bu yürek,

Istemem artik ben ayrilik.

Kör olsamda görmesem,

Sagir olsamda duymasan,

Sakat kalsamda dünyayi hissetmesem,

Sevsem ama severken sevilsem,

Severken bile aglasam,

Ama bu ayrilikta ben olmasam,

Ne olur? 

Hayat çok zor gülmez yüzüm,

Sensiz geçen zaman geçmez gülüm,

Sensiz geçecekse günüm,

Bitsin artik istemem bu ömrüm,

Istemem artik ben ayrilik.

Tarih Ve Saati: 01/08/2005	04:37', 'Bak yine ben söylüyorum, Bir yaz mevsimi ben ölüyorum, Bu ayrilik sözü varya, Bu yürek senin için kanarya, Açi çekerken gözlerim hep aglarya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/istemem-ben-artik-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isyan Ediyorum', 'isyan-ediyorum-mustafa-aslan-2-474to', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün yine yeni seyler duydum,

Duyar duymaz yikildim,

Yine ayrilik,

Bak yine karsi çikanlar,

Birakmiyorlar,

Sevdami bir gün yeneceler,

Sabr dedigin sey tükenecek,

Bu ömür belkide sensiz bitecek,

Bu hayat sensiz neye yarar,

Isyan ediyorum,

Isyan,

Bizi ayirmaya çalisanlara isyan.

Beddua etsem olmaz,

Herkezin kendi düsüncesi,

Biliyorum karsi çikanlardan biri annen,

Senin mutlulugunu istiyor,

Ama sana neden seçme hakkini tanimiyor,

Baksana beni hiç tanimiyor,

Ama beni yinede kötülemesini biliyor,

Seni benden almak için,

Öz yavrusunu tehdit ediyor,

Olmaz böyle,

Olmaz.

Isyan ediyorum,

Ama neye yarar,

Keske su amalar olmasaydi,

Hersey basladigi gibi bitseydi,

Sen benim olarak basladin,

Benim olarak mezarda bitseydin,

Simdi beraber kalacagimiz bile süpheli,

Ama yinede hayata gülmeli,

Seni benden alsalar bile hayata devam etmeli,

Bak yine bir ama,

Ama olmuyor sensiz olmuyor,

Seni benden aldiklari gün,

Belki dünyadan bir can daha eksilecek,

Bu seven kalp kendini mezara gömecek.

Neden ben? 

Neden biz? 

Hatalarin bedelini biz ödüyoruz.

Neden? 

Nedenini bilsek ben bu hallere gelmezdim.

Hala beraberiz,

Ama nereye kadar gidecek acaba,

Seni baskasina yar etmem.

Ben isyan ediyorum,

Ama allahima degil,

Sizlere.

Tarih Ve Saati: 01/08/2005	05:02', 'Dün yine yeni seyler duydum, Duyar duymaz yikildim, Yine ayrilik, Bak yine karsi çikanlar, Birakmiyorlar, Sevdami bir gün yeneceler, Sabr de...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/isyan-ediyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isyan Ettim', 'isyan-ettim-mustafa-aslan-2-3zb0d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Isyan ettim hayatima, 

Boyun egdim kaderime, 

Yüregimi verdim sevdigime, 

Gülümsedim sevenlere, 

Agladim aglayan kalplerle, 

Bilmem bana ne oldu, 

Yarim kaldim Yasantimda.

Içimde mutluluk dogmadan öldü, 

Seven kalbim kan dolan bir göldü, 

Sana bakan iki çift gözdü, 

Biri seni gördü digeri ise zaten kördü. 

Isyan ettim insanlarimiza, 

Neden böyle kahpeyiz diye. 

Isyan ettim arkadaslarima, 

Nerdeydiniz dar günümde diye. 

Isyan ettim sevdiklerime, 

Neden böyle sahtesiniz diye. 

Isyan ettim kendime, 

Neden her seferinde bunlara kaniyorum diye. 

Bir tek isyanim kaldi oda allaha, 

Onuda ölsemde yapmam.

Tarih Ve Saati: 16/08/2005      02:57', 'Isyan ettim hayatima,  Boyun egdim kaderime,  Yüregimi verdim sevdigime,  Gülümsedim sevenlere,  Agladim aglayan kalplerle,  Bilmem bana ne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/isyan-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isyanim Gecelere', 'isyanim-gecelere-mustafa-aslan-2-qrf4l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Isyanim gecelere,

Sessiz,

Ve sensiz gecelere.

Isyanim gecelere,

Sisli,

Ve yagmurlu gecelere.

Isyanim gecelere,

Soguk,

Ve ürpertici gecelere.

Isyanim gecelere,

Sonsuz,

Ve soluksuz gecelere.

Isyanim gecelere mi? 

Hayir,

Gecelerde aci çeken bana,

Isyanim kendime,

Geceler mahana.

Tarih Ve Saati: 15/05/2005	18:30', 'Isyanim gecelere, Sessiz, Ve sensiz gecelere. Isyanim gecelere, Sisli, Ve yagmurlu gecelere. Isyanim gecelere, Soguk, Ve ürpertici gecelere....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isyanim-gecelere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iyi Düsündüm', 'iyi-dusundum-mustafa-aslan-2-6454w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün çok iyi düsündüm,

Düsündüm ve çok iyi karar verdim.

Karar verdim ve seni unuttum.

Anladimki sen kendini düsünen,

Bencilin birisisin.

Onun için seni beynimden,

Ve Kalbimden sildim,

Anlayacagin sana laik olan,

Tek seyi yaptim.

Tarih Ve Saati: 15/11/2003	01:47', 'Bugün çok iyi düsündüm, Düsündüm ve çok iyi karar verdim. Karar verdim ve seni unuttum. Anladimki sen kendini düsünen, Bencilin birisisin. O...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iyi-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdirap', 'izdirap-mustafa-aslan-2-vr0gv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Izdirap çekeceksin beni öldürdünya,

Sende aglayacaksin beni gömdünya.

Artik hayatin bir hiç oldu,

Seninde kaderinin sonu buydu.

Bakma bana utaniyorum senden,

Gülme bana bakarak affetmem.

Sevdami gömerim kalbime,

Seni ekledim simdi nefretime.

Kos bana yillarca,

Benim sana kostugum gibi.

Ama ulasama bana,

Benim sana ulasamadigim gibi.

Kos çikmaz sokaklardasin,

Kaçis yolun yok çikmazdasin.

Beni nasil kalbine hapsedip biraktinsa,

Simdi sira sende,

Izdirap çekme zamani sevdigim.

Göz yaslarimda bogulmustum,

Hayellerimi yikip gidiyordum.

Ama biliyorsun mecburdum,

Ben çektim izdirabimi.

Gözlerin kurusun aglamaktan,

Kalbin kanasin her kursun yarasinda.

Beynin dursun beni düsünmekten,

Çek izdirap, gülme sirasi bende.

Ama kalbim istemiyor bunlari.

Seni hala seviyorum nedense.

Tarih Ve Saati: 17/11/2004	20:18', 'Izdirap çekeceksin beni öldürdünya, Sende aglayacaksin beni gömdünya. Artik hayatin bir hiç oldu, Seninde kaderinin sonu buydu. Bakma bana u...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/izdirap-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamak Bulusmalar', 'kacamak-bulusmalar-mustafa-aslan-2-rppfd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaçamak bulusmalar,

Artik son bulsun.

Bana bakip gülümseme,

Saat geldi gideceksin biliyorum.

Ama belli etme ayriliga dayamiyorum,

Yarin yine bulussakta,

Sensiz geçen saatlere agliyorum.

Senin yaninda mutluyum,

Sen gittinmi yalnizlikla bogusuyorum,

Kendimle savasiyorum.

Tarih Ve Saati: 11/08/2005     04:48', 'Kaçamak bulusmalar, Artik son bulsun. Bana bakip gülümseme, Saat geldi gideceksin biliyorum. Ama belli etme ayriliga dayamiyorum, Yarin yine...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kacamak-bulusmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçkere', 'kackere-mustafa-aslan-2-55mex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçkere gerçekten sever insan,

Kaçkere severde sevilir.

Hiç kimse umrumda degil,

Ister sevsinler,

Ister sevmesinler.

Ben isterdimki,

Sen sevmeyi bileydin.

Sen sevilmeye alismissin,

Ama sevmek nadir bilmeyenlerdensin.

Tarih Ve Saati: 10/08/2002	23:14', 'Kaçkere gerçekten sever insan, Kaçkere severde sevilir. Hiç kimse umrumda degil, Ister sevsinler, Ister sevmesinler. Ben isterdimki, Sen sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kackere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma Sevgimden', 'kacma-sevgimden-mustafa-aslan-2-2pn0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni bekliyorum nerde kaldin,

Yoksa benimi kandirdin,

Korkuyorsun sevgimden,

Neolur yeter kaçma sevgimden.

Her satirimda seni yaziyorum,

Hergün beynime resmini çiziyorum,

Sensiz günlerimde,

Nedense bir ben agliyorum.

Ver artik ellerini ellerime,

Bak gözlerinle gözlerime,

Çevapsiz kalma sözlerime,

Sen sadece kendin ol.

Tam zamaninda karsima  çiktin,

Tam ölmeyi düsünürken,

Tamamen yalniz kalmisken,

Tamamen yorulmusken,

Sen çiktin karsima,

Sana kapildimda,

Simdi hayatin anlamini anladim,

Hayatimin anlami senmissin.

Sen benim zaman kusumsun.

Neolur yeter kaçma sevgimden.

Tarih Ve Saati: 05/12/2004	12:48', 'Seni bekliyorum nerde kaldin, Yoksa benimi kandirdin, Korkuyorsun sevgimden, Neolur yeter kaçma sevgimden. Her satirimda seni yaziyorum, Her...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kacma-sevgimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Önünde Savruldum', 'kaderin-onunde-savruldum-mustafa-aslan-2-eg9a5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ilk defa sevdigimde kaybolmustum,

Unutulmaz hayallerimde,

Aglamak nedir bilmezdim,

Hep gülerdim, 

Hep sevilirdim,

Hayatin anlamini bilmezdim,

Sevmek sözünü duymamistim,

Göz yaslarini saçma bulurdum.

Seni sevdimde çok degistim,

Gülerken, simdi agliyorum,

Sevilirken, simdi taninmiyorum,

Hayati bilmezken, simdi iyi tanidim,

Sevmek sözünü duymamistim, 

Sende buldum sevmeyi,

Simdi göz yaslarini çok anlamli buluyorum.

Kaderin önünde savruldum,

Bir yaprak misali.

Gülen kaderim düsman oldu bana,

Aciyi katti felek hayatima.

Birakinda sevmenin tadini alayim,

Nasil birseymis bakayim,

Sevmek acimi verir, yoksa huzurmu,

Sevmek güzelmidir, yoksa sevilmekmi,

Hala çözemedim.

Tarih Ve Saati: 17/11/2004	20:36', 'Ilk defa sevdigimde kaybolmustum, Unutulmaz hayallerimde, Aglamak nedir bilmezdim, Hep gülerdim,  Hep sevilirdim, Hayatin anlamini bilmezdim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaderin-onunde-savruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadersiz Kamil', 'kadersiz-kamil-mustafa-aslan-2-xi5rs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'K'' aderim yanlis çizilmis

A'' yriligin yüzünden

D'' aha nasil yasamayi düsünürüm

E'' ger sen yoksan yanimda

R'' ahatim bozuldu senden sonra

S'' ana olan askimi anlamadin

I'' nanmak istemedinmi yoksa

Z'' aten kadersizim hayattan yana

K'' adersizim bu yalan dünyada

A'' nladim simdi yalanmis

M'' alesed askim bile yalanmis

I'' nandim simdi senin yalan askina

L'' akin sen beni anlamadin

Tarih Ve Saati: 19/12/2003	17:10', 'K'' aderim yanlis çizilmis A'' yriligin yüzünden D'' aha nasil yasamayi düsünürüm E'' ger sen yoksan yanimda R'' ahatim bozuldu senden sonra S'' a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kadersiz-kamil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadinim Ol Istemistim', 'kadinim-ol-istemistim-mustafa-aslan-2-0u69e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadinim ol istemistim,

Çok seymi istedim senden,

Can çikmaz artik bedenden,

Eyer aciyi çekmezsen.

Kadinim ol istemistim,

Biliyorsun seni çok sevmistim,

Karsilik olarak sen beni istememistin,

Belkide kimseyi sevememistin.

Kadinim ol istemistim,

Yanmis,

Kanamis,

Aglamis,

Solmus,

Gözler ve Sözler.

Sevilmeyi haketmeyiz bizler,

Nedenmi kaderimiz bizleri izler.

Kuslar özgürdür derler, kus olmak isterdim,

Sevilmek güzeldir derler, sevilmek isterdim.

Simdi gidiyorsun arkana dönüp bakmadan,

Arkandan bakarken sana gitme,

Beni birakma,

Gitme, kal, gitme

Sana arkandan gitme diyemedim,

Haykiramadim seni deli gibi sevdigimi.

Kadinim ol istemistim,

Mutlu bir yuva düslemistim,

Düslerim kabus oldu,

Gidiyorsun bilmedigim yerlere.

Gitme,

Baskasini sevme,

Sakin sevilme,

Öylece gülme,

Agla ama belli etme,

Seviyorum diyemedim sana.

Sadece kadinim olmani istemistim.

Tarih Ve Saati: 17/11/2004	20:28', 'Kadinim ol istemistim, Çok seymi istedim senden, Can çikmaz artik bedenden, Eyer aciyi çekmezsen. Kadinim ol istemistim, Biliyorsun seni çok...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kadinim-ol-istemistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahretsin Neden Seni Seviyorum', 'kahretsin-neden-seni-seviyorum-mustafa-aslan-2-pzdsc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahretsin neden seni seviyorum,

Kalpsiz birine can veriyorum,

Duy bu sözüm sana,

Kalpsiz oldugunu duysana.

Yuvamdan ayri kaldim senin için,

Sense kalbimi kirdin bir oyun için,

Neden söyle dahami yüksek göründün simdi,

Artik bilmiyorum neden seni seçtim,

Seni severken mutlu olurum sanmistim.

Yanilmisim meger simdi daha mutsuzum,

Kaderimle tekrar bulusmusum,

Bilki kapsizde olsan seni seviyorum,

Bu yolda ölümü göze aliyorum.

Ama sakin unutma hala özlüyorum,

Seni degil Kalbini özlüyorum,

Nerde hani kalbin nerde,

Nasil simdi sen mutlumusun.

Beni mutsuz yaptinya,

Mutlumusun söyle simdi.

KAHRETSiN  neden seni sevdim,

Sevmek bana suçmu,

Her sevdigimde ölmemmi gerekiyor.

Her ayrilikta karanlik olamasimi gerekiyor,

Ama simdi anladim sen degmezsin,

Sen yanliz bir kalpsizsin,

Kahretsin senin gibi bir kula.

Artik yasamak sana haram,

Git git gidisini kimse görmesin,

KAHRETSiN NEDEN SENi SEViYORUM,

Nedenini Bana Deyil Kalbime Sorun! ! ! 

Tarih Ve Saati: 03/04/2003	00:17', 'Kahretsin neden seni seviyorum, Kalpsiz birine can veriyorum, Duy bu sözüm sana, Kalpsiz oldugunu duysana. Yuvamdan ayri kaldim senin için, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kahretsin-neden-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolsun Böyle Yasam', 'kahrolsun-boyle-yasam-mustafa-aslan-2-3oxyn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'K'' ahrolsun gitsin, bitsin böyle yasam

A'' nlarmisin beni güzel pasam

H'' ayellerimdeki sevda

R'' üyalarimdaki özlem

O'' lmaz olsun böyle yasam

L'' akin ölürsem, yanasma bana

S'' uskun olsamda konusma bana

U''  nut beni, karismam sana

N'' ede olsa benimki sahte yasam

B'' iktim, usandim artik

Ö'' ldüm, yikildim artik

Y'' alan sözlerden

L'' imandan kalkan gemilerden

E'' ridim, bittim, tükendim ben

Y'' illardir bekledigim sevgi

A'' radigimi bulamadigim

S''  asirip sok oldugum

A'' anlamadigim bir yasam

M'' utsuzum ben kahrolsun böyle yasam be pasam

Tarih Ve Saati: 10/07/2004	12:00', 'K'' ahrolsun gitsin, bitsin böyle yasam A'' nlarmisin beni güzel pasam H'' ayellerimdeki sevda R'' üyalarimdaki özlem O'' lmaz olsun böyle yasam ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahrolsun-boyle-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Ellerinde', 'kalbim-ellerinde-mustafa-aslan-2-g23tz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'K'' orkuyorum artik sevmekten

A'' skimla alay edilmesinden

L'' aleler, güller gibi solmaktan

B'' ilmez kimse benim derdimi

I'' nanmaz kimse kara sevdama

M''  ahsum bakislara kanmaktan

E'' zilmistim günden güne

L'' anet etmistim hayatima

L'' imandan kalkti artik gemiler

E'' zilmekten bikmis sonsuzluga giderken

R'' abbimden dilerim hergün mutluluk

I'' nanmazsin gelir bana umutsuzluk

N'' eden ben diye sormam kimseye

D'' amgasini vurmus kader

E'' lden ne gelir vurmus birkere keder

Tarih Ve Saati: 26/09/2004	12:07', 'K'' orkuyorum artik sevmekten A'' skimla alay edilmesinden L'' aleler, güller gibi solmaktan B'' ilmez kimse benim derdimi I'' nanmaz kimse kara ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbim-ellerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Hosçakal', 'kalbim-hoscakal-mustafa-aslan-2-vil6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbim hosçakal,

Seni birakiyorum yaban ellere,

Kalbim hosçakal,

Eller benden daha iyi bakar sana.

Hep aci çektirdim kalbime,

Hasret biraktim sevgiye.

Hergün sokaklarda kalbimi görürüm,

Elden ele savrulmus,

Yipranmis,

Daldan dala konar olmus.

Kalbim artik hosçakal,

Seni sevdigime birakiyorum,

Ona sadik kal,

Ne sen onu,

Nede o seni üzsün,

Ben gidiyorum.

Uzaklara,

Kimsenin bilmedigi yerlere,

Acilardan,

Dertlerden uzak,

Yalniz,

Yapa Yalniz,

Sensiz veya senli dünyalara.

Kalbim mutlu olursun bu kiside,

Seni kendinden çok sever,

Beni sana unutturur,

Mutluluga kavusturur.

Sakin ha,

Birakip gitmeyesin.

O seni sevecektir,

Benim seni sevdigimden çok sevecektir,

Kalbim Hosçakal.

Tarih Ve Saati: 30/04/2005	17:24', 'Kalbim hosçakal, Seni birakiyorum yaban ellere, Kalbim hosçakal, Eller benden daha iyi bakar sana. Hep aci çektirdim kalbime, Hasret birakti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kalbim-hoscakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimi Çaldin', 'kalbimi-caldin-mustafa-aslan-2-y9npr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni birakmam, kaçamazsin,

Sen kalbimi çaldin,

Ömür boyu hapis yedin,

Kalbimin kilidini kiramazsin.

Kalbime hapsediyorum seni,

Birakmam, öldürsende beni.

Zorlama iste suçlusun,

Cezani çekmelisin.

Birak dedin bana birakmadim,

Istemiyorum dedin, ben bekledim.

Defol dedin, aldiris etmedim,

Seni sadece kalbime hapsettim.

Suçu bende arama,

Kalbimi sen çaldin,

Beni benden aldin,

Baskalarina satamadin,

Bende sana kaldim.

Bosver ugrasma, zordyr çikmak kalbimden,

Bosuna konusma dönmem sözümden.

Dert yanma, çikarmam özümden,

Bakislarini çek gözümden.

Alay eder gibi bakiyorsun,

Beni sen yakiyorsun.

Simdi gitmekmi istiyorsun,

Zorla sevdirmem kendimi,

Açarim kalbimin kafesini,

Istersen çek git umrumda degil,

Sende oldun bir bencil,

Kalbimi çaldin ömür boyu hapis verdim,

Düsüncesiz,

Bencil,

Hiçmi akillanmadin,

Idam vermedigime dua et.

Tarih Ve Saati: 17/11/2004	20:45', 'Seni birakmam, kaçamazsin, Sen kalbimi çaldin, Ömür boyu hapis yedin, Kalbimin kilidini kiramazsin. Kalbime hapsediyorum seni, Birakmam, öld...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kalbimi-caldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldirimlar', 'kaldirimlar-mustafa-aslan-2-0u3z8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaldirimlar benim yeni mekanim,

Gizli sokak aralarinda kaldirimlar,

Dertlenirim,

Hemen oraya kosarim,

Hep orada gizli aglarim,

Kimse görmez,

Içimdeki sevdami,

Íçimdeki yarami.

Kaldirimlarda uyuklarim,

Uykumu ayakta alirim,

Bazen yorgunluktan yikilir,

Bazen acilarla savasirim,

Sensizligi çekerken,

Ben kendime isyan ederim.

Hatirlarmisin,

Seni evinin önünde,

Kaldirimda beklerdim,

Pencereden birkere baksin,

Onu göreyim,

Bugünlük bana yeter diye,

Simdi hersey okadar çok degistiki,

Artik beni anlamiyorsun,

Yalniz kendini düsünüyorsun,

Aslinda haklisin,

Insan ogluna güven olmaz,

En iyi arkadasin,

Sadece kendindir.

Baskasina güven olmaz.

Ayri olamaztik biz,

Bunu iyi biliyorsun,

Bu sevdayi böyle bitmez,

Tekrar askimiza baglanmamiz lazim.

Son kezde olsa,

Birbirimize anlam vermemiz lazim.

Tarih Ve Saati: 15/05/2005	18:19', 'Kaldirimlar benim yeni mekanim, Gizli sokak aralarinda kaldirimlar, Dertlenirim, Hemen oraya kosarim, Hep orada gizli aglarim, Kimse görmez,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kaldirimlar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmamis Insanlik', 'kalmamis-insanlik-mustafa-aslan-2-qp7g2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haram yiyip haram satmayi,

Günahlara günah katmayi,

Yalan atip yalan tutmayi,

Insan insana ögretmis.

Kalmamis insanlik.

Irza geçip zina yapmayi,

5 kurusa alip 10 kurusa satmayi,

Hep yari yolda kalmayi,

Insan insana ögretmis.

Kalmamis insanlik.

Hergün gülüp aglatmayi,

Yarali kalpleri kanatmayi,

Sevipte insanligi unutmayi,

Insan insana ögretmis.

Kalmamis insanlik.

Allaha isyan etmeyi,

Haram asi yemeyi,

Yalani sevmeyi,

Canli mezara gömmeyi,

Insan insana ögretmis.

Kalmamis insanlik.

Tarih Ve Saati: 20/05/2005     12:14', 'Haram yiyip haram satmayi, Günahlara günah katmayi, Yalan atip yalan tutmayi, Insan insana ögretmis. Kalmamis insanlik. Irza geçip zina yapm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalmamis-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsizler', 'kalpsizler-mustafa-aslan-2-e3rek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalpsizler içinde boguluyorum,

Beni kim kurtaracak,

Bilemiyorum.

Yillardir mutlu olamiyorum,

Beni kurtaran olursa,

Belki ben o gün mutlu olurum.

Eger kimse kurtarmak istemezse,

Bu fani dünyada durmam,

Bir anda yok olurum.

Tarih Ve Saati: 08/06/2002	19:29', 'Kalpsizler içinde boguluyorum, Beni kim kurtaracak, Bilemiyorum. Yillardir mutlu olamiyorum, Beni kurtaran olursa, Belki ben o gün mutlu olu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalpsizler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsizler 2', 'kalpsizler-2-mustafa-aslan-2-bnz47', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalpsizler arasinda kalmisim,

Dört duvar arasi gibi,

Boguluyorum aralarinda,

Kurtaran yok.

Sonunda bir dost eli uzandi,

Beni çekti aralarindan,

Beni çok degistirdi,

Sevmek nedir ögretti,

Artik kimseyi sevmiyorum,

Sadece sevilmeyi bekliyorum.

Zaman çok degismis,

Belliki daha çok beklerim.

Ne seven,

Nede sevilen kalmis,

Bu fani dünyada,

Tarih Ve Saati: 29/07/2002	00:26', 'Kalpsizler arasinda kalmisim, Dört duvar arasi gibi, Boguluyorum aralarinda, Kurtaran yok. Sonunda bir dost eli uzandi, Beni çekti aralarind...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalpsizler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanli Günler', 'kanli-gunler-mustafa-aslan-2-lf02b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkez düsman olmus birbirine

Çeken vurur ileriyi düsünmeden

Kiyarlar bir ananin yavrusuna

KIyarlar bir ananin emeklerine

Arkada birakirlar aglayan bir ana bir baba

Kendi hayatini söndürdügünü bilmeden

Kanli günler geçer insanlar arasinda

Bir hiç ugruna vuranlarla, vurulanlar

Bir an olsun vicdan azabi çekmezmisiniz

Bir yuvanin yikilisini izlemek

BIr deyil bin yuvanin yikilisini

Bir can vermis allah sen neden aliyorsun

Korkun yokmu allahtan

Verdigi cani almaktan

Gözü yasli ana birakmaktan

Hayatinin son bulmasindan

Kan akar kalplerden

Bir kurusa alirsin kursunu

Bir kursunla alirsin insan canini

Arkanda birakirsin kanli günleri

Tarih Ve Saati: 20/08/2004	16:26', 'Herkez düsman olmus birbirine Çeken vurur ileriyi düsünmeden Kiyarlar bir ananin yavrusuna KIyarlar bir ananin emeklerine Arkada birakirlar ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kanli-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapilar', 'kapilar-mustafa-aslan-2-588rc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapilar kapandi yüzüme,

Kapilar kapandi sözüme,

Bu kapilar,

Senin kalbinin kapilari,

Senin cennetinin kapilari,

Içeri girmek zordur,

Ama birde girdinmi.

Bunun çikisi yoktur.

Tarih Ve Saati: 26/02/2002	16:20', 'Kapilar kapandi yüzüme, Kapilar kapandi sözüme, Bu kapilar, Senin kalbinin kapilari, Senin cennetinin kapilari, Içeri girmek zordur, Ama bir...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kapilar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Toprak', 'kara-toprak-mustafa-aslan-2-oe8cc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birakipta gittin,

Beni sevmedigini söyledin,

Beni askina mahkum ettin,

Sonra rest çekip gittin.

Derdimi anlatamam insanlara,

Konusurum kara topraga,

Beni anlayan olmadi,

Bir kara toprak benim için agladi.

Al beni yanina,

Al beni içine,

Kara toprak.

Birakma beni dünyada,

Sahte,

Yüzsüz,

Yalanci insanlar arasinda.

Beni anladigini biliyorum kara toprak,

Ben oldum deredeki yaprak,

Içine almiyorsan,

Al beni yanina kara toprak.

Derdimin dermani sende,

Sen hiç güler yüz görmedin,

Aynen bende.

Herkez aglar basinda,

Benim aglayanim bile olmadi.

Kara toprak sendemi yoksa,

Sendemi istemiyorsun beni.

Sendemi ögrendin insanlardan bencilligi,

Beklemezdim senden kara toprak.

Tarih Ve Saati: 17/11/2004	20:51', 'Birakipta gittin, Beni sevmedigini söyledin, Beni askina mahkum ettin, Sonra rest çekip gittin. Derdimi anlatamam insanlara, Konusurum kara ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kara-toprak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-sultan-duran-psbzt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz pınarlarına kurban olduğum

Yanaklarına buseler kondurduğum

Canım, bir tanem, biricik yavrum

Sıkışmış gibisin o bedende

Sanki sığmıyorsun kabına

Geleceğe başarılarla dolu bir kucak

Kaygılardan uzak, mutluluklarla

Koşmaktır niyetin bilirim

Bir of çeksen rahatlayacaksın

Ama belki erken diye düşünüyorsun

Aslında erken de...

Benim güzel kızım, ruhu güzelim

Sen doğrularından eminsin

Ben ise başaracağından...', 'Göz pınarlarına kurban olduğum Yanaklarına buseler kondurduğum Canım, bir tanem, biricik yavrum Sıkışmış gibisin o bedende Sanki sığmıyorsun...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kizima-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Kalbimin Anilari', 'kanayan-kalbimin-anilari-mustafa-aslan-2-ivojf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'K'' anadi kalbim ölümü düsündüm

A'' nladim hayatin gerçek anlamini

N'' eden kimse sormadi bana

A'' glayan dostlarima

Y'' alan gibi gelir hersey sana

A'' nlasana seni seviyorum

N'' iye mi?  Bende bilmiyorum

K'' ime sorsam seni

A'' glatir o kisi beni

L'' imandan kalkti gemi

B'' enide alsin yanina yada seni

i '' grendim kendi kendimden

M'' utluluk istemedim kimseden

i '' nandim hep yalan sözlere

N'' ede olsa yalan bu dünya yalan

A'' nlatirmisin bana yasami

N'' için bu dünyada yasadigimi

I '' slanan vücudum üsür oldu

L'' anet edilen insanlar kanla doldu

A'' glatipta gülen çok

R'' üyalarimdaki perilerden hayir yok

I '' rmaktan at beni senin kalbine

Tarih Ve Saati: 10/07/2004	10:40', 'K'' anadi kalbim ölümü düsündüm A'' nladim hayatin gerçek anlamini N'' eden kimse sormadi bana A'' glayan dostlarima Y'' alan gibi gelir hersey s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kanayan-kalbimin-anilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadir Benim Bahtim', 'karadir-benim-bahtim-mustafa-aslan-2-6llkj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karadir benim bahtim,

Çinlar gecelerce feryadim.

Sevilmenin tadini alamadim,

Neden her sevdigimde ben agladim.

Ben hep insanlara kandim,

Sevda atesiyle hergün yandim,

Elbet bende sevilirim sandim,

Oysa karaymis benim bahtim,

Ben yine aldandim.

Renksiz bir dünyam var,

Simsiyah göz gözü görmüyor,

Karadir benim bahtim,

Hayatimin anlami olmuyor.

Gülemiyorum, asik bir surat,

Göremiyorum, kör bir çift göz,

Bana söyledigin iki söz,

Hayir derken bana verdigin umut.

Anlamsiz bir arkadaslik,

Artik bizde yaslandik,

Ruhumuz ölmüs,

Günesimiz sönmüs,

Kalplerimiz ikiye bölünmüs,

Kaderimiz demekki buymus.

KARADIR BENiM BAHTIM,

SEVDiMDE SEViLiRiM SANDIM.

Tarih Ve Saati: 18/11/2004		13:20', 'Karadir benim bahtim, Çinlar gecelerce feryadim. Sevilmenin tadini alamadim, Neden her sevdigimde ben agladim. Ben hep insanlara kandim, Sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karadir-benim-bahtim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlüm', 'karagozlum-mustafa-aslan-2-ul50n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'K'' ara gözlüm seni seviyorum

A'' nlamini bende bilmiyorum

R'' engim soldu kefeni giydim

A'' gardi saçlarim bu yasta

G'' ünesim batmis dogmak bilmiyor

Ö'' zledim seni bekle geliyorum

Z'' annetmeki çok uzaktasin gelemem

L'' anet olsun dünyaya

Ü'' zülme sen KARAGÖZLÜM

M'' erak etme gelecegim en sonunda

Tarih Ve Saati: 08/12/2003	14:23', 'K'' ara gözlüm seni seviyorum A'' nlamini bende bilmiyorum R'' engim soldu kefeni giydim A'' gardi saçlarim bu yasta G'' ünesim batmis dogmak bil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karagozlum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboldu Yillarim', 'kayboldu-yillarim-mustafa-aslan-2-7o5e7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadersiz gelmisim yalan dünyaya

Sansim hiç olmadi sevmekten yana

Agladim hergün kana kana

Arkadasim neolur bir yol göster bana

Birgün gelir sende benim gibi seversin

Sende geçen günlerini özlersin

Hayattan elbet sende bezersin

Belkide mutsuzluguna sende gülersin

Kayboldu yillarim, aglayan olmadi

Kayboldu yillarim, yardim eden olmadi

Kayboldu yillarim, neden diye soran olmadi

Kayboldu yillarim, elimden tutan olmadi

Kaybolan yillarim

Geri gelecekmi

Herkez birakip gitti beni

Biraktilar sevipte, ayrilik görenleri

Son kez baktim arkama

Göremedim bir türlü seni

Hala bakiyorum

Artik! 

KAYBOLDU YILLARIM

Tarih Ve Saati: 21/10/2004	17:40', 'Kadersiz gelmisim yalan dünyaya Sansim hiç olmadi sevmekten yana Agladim hergün kana kana Arkadasim neolur bir yol göster bana Birgün gelir ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kayboldu-yillarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim Biliyorum', 'kaybettim-biliyorum-mustafa-aslan-2-bcm91', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni tamamen kaybettim biliyorum,

Sensizlik ölüm,

Bunuda biliyorum.

Sende bunlara kanip,

Beni sensiz biraktin.

Evet simdi sensizim.

N’olmus,

Kafaya bile takmiyorum.

Sen önemli bir seyi unuttun,

Benim bildiklerim degil,

Düsündüklerim önemlidir.

Tarih Ve Saati: 06/09/2002	15:45', 'Seni tamamen kaybettim biliyorum, Sensizlik ölüm, Bunuda biliyorum. Sende bunlara kanip, Beni sensiz biraktin. Evet simdi sensizim. N’olmus,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybettim-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayip Sehir', 'kayip-sehir-mustafa-aslan-2-txxu7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kayip bir sehirdeyim,

Seni ariyorum,

En sonunda seni buldum,

Ama simdide kendimi kaybettim.

Kayip sehirde boguluyorum,

Ben sensiz yokoluyorum,

Feryad ediyorum,

Neolur duysana.

Korkmuyorum artik,

Kayip sehirde bir sen,

Birde ben varim,

Diger insanlar yok gözümde.

Seni sevdigimi haykiriyorum,

Neolur duysana.

Bak bi gözlerime,

Bak neler görüyorsun.

Baksanda biliyorum,

Gözlerimde yalniz seni görürsün.

Kayip sehirde bir sevda günesi,

Sevenler el ele geziyor,

Hepsi birbirine benziyor,

Seni sevdimde,

Kayip sehrin,

Mecnunu ben oldum.

Tarih Ve Saati: 30/11/2004		16:23', 'Kayip bir sehirdeyim, Seni ariyorum, En sonunda seni buldum, Ama simdide kendimi kaybettim. Kayip sehirde boguluyorum, Ben sensiz yokoluyoru...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayip-sehir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaz Mezarimi Be Mezarci', 'kaz-mezarimi-be-mezarci-mustafa-aslan-2-tuwva', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaz mezarimi be mezarci,

Içimde yanan bir sanci,

Uzaklara götür beni sandalci,

Insanlarin hepsimi yalanci.

Mezarimi kazin sira bende,

Gireyim mezarima sevgimle.

Gönlümü verdimde ellere,

Ne oldu söyle be mezarci.

Soluyorum bir gül gibi,

Batiyorum bir gün gibi,

Seviyorum adam gibi,

Ölüyorum bir deli gibi.

Attigim adimlari sayiyordum,

Son bir adim daha,

Ozaman mezarima düsücegim,

Birakta sevdam atayim son adimimi.

Günler gelir sende seversin,

Kaderine sende boyun eyersin,

Uzaklara bensiz gidersin,

Benim gibi sende,

Kaz be mezarci dersin.

Tarih Ve Saati: 18/11/2004		13:27', 'Kaz mezarimi be mezarci, Içimde yanan bir sanci, Uzaklara götür beni sandalci, Insanlarin hepsimi yalanci. Mezarimi kazin sira bende, Gireyi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kaz-mezarimi-be-mezarci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler gördüm neler', 'neler-gordum-neler-mikdat-bal-rb5m2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neler gördüm neler saysam bitmez ki

Kör, sağır ve dilsiz doğanı gördüm

Her şeyi anlatsam hoşa gitmez ki

Sarımsak, pırasa,  soğanı gördüm

İstismar  yapılır  hem  de  bilerek

Yüzüne dostunum deyip gülerek

Kitap  bastıralım  diye gelerek

Ozanı şairi sağanı gördüm

Hainin eline fırsat geçince

Kanını  hortumla emip içince

Bir çoğu zulmeder  taraf seçince

Gazap olup taş taş yağanı gördüm

Herkes çetesini kurduğu zaman

Geçitin başına durduğu zaman

Bir nokta menfaat gördüğü zaman

İğne deliğine sığanı gördüm

Herkes haklı imiş insanlar tuhaf

Bu sözüm kimseye değildir ithaf

Kalmadı adalet kalmadı insaf

Garibi meydanda boğanı gördüm

Mikdat der bu gözler çok şeyler gördü

İnsanlar her çeşit boyaya girdi

Bir kaç tane ise şairin derdi

Dertleri üst üste yığanı gördüm', 'Neler gördüm neler saysam bitmez ki Kör, sağır ve dilsiz doğanı gördüm Her şeyi anlatsam hoşa gitmez ki Sarımsak, pırasa,  soğanı gördüm İst...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neler-gordum-neler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Battığı Gözlerin', 'gunesin-battigi-gozlerin-yusuf-pekol-trgw9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutlarımı

Güneşin battığı gözlerinde

Aramaya çıkmış

Yorgun fakat umutlu

Bir hayalperestim...

Limana demir atmışsa gemileri ömrümün

Ya sen gelmişsin gittiğin yerden

Ya da benim gitme vaktim gelmiştir

Fırtınalı ömür limanından

Dingin ölüm limanına...', 'Umutlarımı Güneşin battığı gözlerinde Aramaya çıkmış Yorgun fakat umutlu Bir hayalperestim... Limana demir atmışsa gemileri ömrümün Ya sen g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunesin-battigi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar mısın?', 'aglar-misin-cihan-basak-3ifs1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzünü döküp sinene

Beni düşünüp ağlar mısın? 

Öyle mahçup elin yüzünde

benim için ağlar mısın? 

Gözyaşların dudağına varmadan

Beni sessizce anar mısın? 

Bir elin hep yüzünde

Beni düşünüp anlar mısın? 

Yüzünü döküp gönlüne 

Benim için ağlar mısın? 

Yüreğinin tam ortasına alıp beni

Hiç çıkarmadan saklar mısın? 

Ağlaya ağlaya durmadan

Bana bir nehir gibi akar mısın? 

26 Kasım 1999', 'Yüzünü döküp sinene Beni düşünüp ağlar mısın?  Öyle mahçup elin yüzünde benim için ağlar mısın?  Gözyaşların dudağına varmadan Beni sessizce...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglar-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyürüm Zamanla', 'buyurum-zamanla-birsen-ates-r3uxu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'anlayamazsın 

içimde kopanları 

parça parça dökülüyor

geceye sessizce

ayazındayım hala

yüreğimi üşüten sözlerinin

ben sende hiç olamadım ki

eğreti oturduğum yüreğin de

bekledim bir kıyıda sessizce 

üzerime giydirdiğin

k a b uğ u m u 

soydum kanadı

bırak kaybolayım

sensizliğimin çıkmaz sokaklarında

büyürüm  z a m a n l a 

08.01.06', 'anlayamazsın  içimde kopanları  parça parça dökülüyor geceye sessizce ayazındayım hala yüreğimi üşüten sözlerinin ben sende hiç olamadım ki ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buyurum-zamanla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sence', 'sence-ethem-turan-3wu9m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazmayı çare edinsem de nafile 

Akan kan geri gelmez 

Çıkan can da öyle

Kırılan gönül tamir olur mu  sence 

Parçalanan umutlar gelir mi geriye

Aynı sıcaklık olur mu tenimde 

Yaşarken ölünür mü 

Ölünür mü sence

Yada kahrolarak yaşanır mı 

Doyar mı insan ömrüne 

Gülebilir mi kaderine 

Mutluyum diye  bilir mi 

Diyebilir mi sence 

Ne aman sız hastalıklara yakalanmış insanlar gülse de

Gülemiyorum işte istesem de

Yıkılmış duvar dikilir mi yerine 

Dikilir mi sence

Harap olmuşum uğraşlar nafile 

Eskisi gibi olmak ta istemiyorum belki de

Yaşamak istemiyorum belki seninle 

Yaşamak istemiyorum aynı şeyleri 

Bir daha yıkılmaya cesaretim yok  belki

Bir daha vurulmaya da 

Ağlayacaksam  bir kez doyasıya

Hiç düşünmeden hazırım  son kez  olmasına 

Ardına bakmadan   yürüyeceksem 

Gönül  rahatlığıyla 

Sahte ruhunla değil 

Seni bulmalıyım  benliğinle karşımda

Öleceksem bu uğurda 

Değmeli  yaşama vedaya 

Değmeli sevene ihanet etmeye 

 Değmeli gözü açık gitmemeye

Değmeli değil mi sence', 'Yazmayı çare edinsem de nafile  Akan kan geri gelmez  Çıkan can da öyle Kırılan gönül tamir olur mu  sence  Parçalanan umutlar gelir mi geri...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sence-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim?', 'ben-kimim-kamil-at-1iofo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben yarattığım kendi şiirimdeyim

İnsanlığın görmediği imdeyim

Ömrüm ezgilerde yine gümdeyim

Şiirde görmediniz delimisiniz.

Yollar kıvrım kıvrım uzanır gider

Değer verdim insan ise öder

Beni kendine benzeten halteder

Bilinmez bahçenin gülümüsünüz.

Öyle gider sanma sonsuz kalır

Birgün haklı hakkını zalimden alır

İnsan olmayan biter, olan yükselir

Kötünün elini kaldıran elimisiniz.

Kamil At bulmuş doğru yolunu

Hayatta dertle bilmez eğri yolunu

Yoksul kavgasını bilir hem de çulunu

Gözüme batan hain çalımısınız.', 'Ben yarattığım kendi şiirimdeyim İnsanlığın görmediği imdeyim Ömrüm ezgilerde yine gümdeyim Şiirde görmediniz delimisiniz. Yollar kıvrım kıv...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-kimim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenmemesi Gerekenin Şiiri', 'soylenmemesi-gerekenin-siiri-nurullah-genc-os2zb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'reddini doldurursa avucuma kan gibi 

kırmızı bir çığlıkla yırtılır dudaklarım: 

‘ söylememeliydim biliyorum! ...’ 

kırılsa da baharı bekleyen pencereler 

akrebin gözlerinden geçse de dehlizlerim 

eski bir mezarlığa gömülmeden izlerim 

‘söylememeliydim biliyorum! ...’ 

simsiyah bulutların arasından ansızın 

çatlayan yüreğime koydu susuzluğunu 

ver Allah’ım bana ver O’nun sonsuzluğunu 

hüzünlü bakışları şafağımda tebessüm 

gündüzümde ışığı, gecemde hilali var 

evimin tenhasında büyüyen melali var 

kum fırtınasında mı, selde mi yürüyorum 

‘ söylememeliydim biliyorum! ...’ 

gemilerde aradım yüzünün görkemini 

martılarla yoruldum, tayfalarla vuruldum 

kalbimi morga koydum bir liman köşesindenefesini aradım dalgaların sesinde 

tutundum hayatımın çürüyen yıllarına 

bakıp bakıp ağladım boş kalan yollarına 

beni anlamaz diye kabuslar görüyorum 

‘ söylememeliydim biliyorum! ...’ 

ciğerimde bir köz gibi taşıdım yokluğunu 

ver Allah’ım, bana ver suya küskün kuğunu 

mor lekeler bıraktı solgun yanaklarıma 

kartal kanı bulaştı rüyalarıma bile 

fırtınalar diner mi ulaşmadan sahile 

hayalin bozkırında kurtkapanıydı ömrüm 

nasıl da bir başıma kopardım dikenleri 

nasıl da acımasız köprülerde yürüdüm 

uzaktan gülümseyip deniz fenerlerine 

sonunda mahkum gibi kapandım ellerine 

kirpiklerimden sızan hicranı siliyorum 

‘ söylememeliydim biliyorum! ...’ 

ısrarlı denizlerin dibinde volkandır aşk 

kesif bir muammayı öğretir balıklara 

balıklar derde düşen aşığı avuturlar 

aşık ölünce kuşlar uçmayı unuturlar 

güneşle buluşmayı göze alan, derinde 

yağmur yüklü bir ömür paylaşır göklerinde 

eleğimsağma renkler düşürünce şehrayin 

başlamalı yeniden içimizde bir ayin 

belki de döndü talih, çözüldü bilmeceler 

tükenecek siyaha baş koyduğum geceler 

umarım, kaybettiğim devranı buluyorum 

‘ söylememeliydim biliyorum! ...’ 

ah, Allah’ım gösterme bana soğukluğunu 

nicedir bekliyorum dağlar ardında O’nu 

nefesimde rüzgarın gölgesidir dağılan 

kanımda gözlerinin hasretidir boğulan 

bir zamanlar benzerdik muhabbet kuşlarına 

dalardım o gizemli, mahmur bakışlarına 

gittiği gün sokaklar içinde kaldım, sefil 

öldü kafeste bülbül; soldu nergis karanfil 

bedevi kahramanlar yurdundan geliyorum 

‘ söylememeliydim biliyorum! ...’ 

melekler en çaresiz anımda buldu beni 

gaflet şarabı içtim, aşikar kıldı beni 

baykuşlar dahi mutlu bu habersiz dönüşten 

hangi yokuş daha yar olabilir inişten doruktaki saraydan koyar mı beni mahrum 

‘ söylememeliydim biliyorum! ...’ 

bu son yürüyüşümdür yarına kalmaz umut 

Allah’ım, bir gül gibi O’nu baharımda tut 

esrarlı bir evimiz olsaydı fildişinden 

beyaz bir gölge gibi yürüseydim peşinden 

desturun var mı diye dururken eşiğinde 

bizim olan bir kalbi bulsaydım beşiğinde 

bu nehir yine sarhoş akar mıydı ülkemden 

bir deprem ortasında sarsılır mıydı beden 

korkarım ki, dergahtan yine kovuluyorum 

‘ söylememeliydim biliyorum! ...’ 

biliyorum, yalnızlık ekecekler bahçeme 

biliyorum,yağmurda yürüyecek kötürüm 

biliyorum, mülteci türküler duyacağım 

biliyorum, gülerse, O’nunla ben de hürüm 

acı hatırasından bile kam alıyorum 

‘ söylememeliydim biliyorum! ...’ 

unutulan kalplerin tahtında rüyadır aşk 

gözlerime bakarsa, görür ki, deryadır aşk 

ah, ölüm habercisi beyaz parıltılarım 

ah, Azrail çağıran çizgileri yüzümün 

ah, paslanan kılıcın dudağında sönen mum 

ah, yolcuyu hüsranla buluşturan uçurum 

kim bilir kelebeğin kanadından bakanı 

kim bilir baldıranda misk ü amber kokanı 

sanki aynı hüzzamla yüz yüze kalıyorum 

‘ söylememeliydim biliyorum! ...’ 

haddim değil güneşi götürmek kainata 

gökle buluşmamızı çok görür haramiler 

anlamazlar ki, bin kez gelsem bile hayata 

bu can gökte yaşayıp, gökte ölmeyi diler 

ah, gönül toprağıma yaprak döken serviler 

efkarıyla bir garip derbeder oluyorum 

‘ söylememeliydim biliyorum! ...’ 

ben Raymalı Ağa’yım, sözümle kırılır yay 

o, bir anda ruhumu altüst eden Begimay 

lacivert bir macera değildir aradığım 

şahmaranın kolları sarınca çiçekleri 

kiralık duygulardan kefen biçer cüceler 

baharda yağmur olur yüreğim, güzün sarı 

yakamozlar içinde, kışın kar tanesidir 

derinden baktığında eritir aynaları 

sanmayın perdelerin ardından gülüyorum 

‘ söylememeliydim biliyorum! ...’ 

bana misket oynamak yakışır hüzünlerle 

bana binlerce yılın ıstırabıdır gelen 

bana dönmez yüzünü efsaneler güzeli 

hayal kırıklığıdır avucuma dökülen 

sabahın sitemiyle büyürken kaygılarım 

akşamın dayanılmaz yükünü çekiyorum 

‘ söylememeliydim biliyorum! ...’ 

reddiyle, çaresizlik yıkılırsa başıma 

nasıl mihman olurum o gün mezar taşıma 

sırlıdır her kapının arkasında inkisar 

boynu bükük kükremez, mahkum olsa da arslan 

her iklimde farklıdır yılanın tutkuları 

uçan bir ecza gibi olmamalı intizar 

kızıla boyanırsa yaprakları kaktüsün 

yanılgıya dönüşür parlaklığı her süsün 

duy sesimi ey yitik hazinem, ağlıyorum 

‘ söylememeliydim biliyorum! ...’ 

ah, bir tutunabilsem burçlarına güneşin 

sessiz yürüyebilsem zifiri gecelerde 

ah, küçük bir vatanım olsa kalbinde senin 

kundağında vuslatı yudumlasak evrenin 

bitmeyen bir şarkıya kenetlense gönlümüz 

birbirine karışsa ölümümüz, ömrümüz 

ipek avuçlarında uyanmak diliyorum 

‘ söylememeliydim biliyorum! ...’ 

kırabilsek sevdayı çalan oyuncakları 

sırtımda hamal gibi taşırım çocukları 

neden mahrum edelim karanlığı ışıktan 

neden solsun bir çölün kumlarında şakayık 

al bu zalim kuşkuyu efsanevi aşıktan 

sana tahtım da layık, bil ki, bahtım da layık 

titrek bir suskunluğun nidasıydı tarihim 

senin olsun otağım, varım yoğum, talihim 

giderken götürdüğün kalbimi arıyorum 

‘ söylememeliydim biliyorum! ...’ 

susmalı ayrılığın uğursuz puhuları yıkılmalı hayatı küçümseyen köprüler 

dönmeli, sahralara sürdüğümüz tebessüm 

ah, idam fermanıyla yargılanan tanyeri 

ah, bir gülün içimde kımıldayan elleri 

yarama merhem diye hüznünü sarıyorum 

‘ söylememeliydim biliyorum! ...’ 

kader umudumuzu taşımadan ırağa 

yürümeliyiz artık bizim olan durağa', 'reddini doldurursa avucuma kan gibi  kırmızı bir çığlıkla yırtılır dudaklarım:  ‘ söylememeliydim biliyorum! ...’  kırılsa da baharı bekleye...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":147,"source_url":"https://www.antoloji.com/soylenmemesi-gerekenin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-naciye-bildim-9zhlv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüm kör olupta,düşsem yollara

Kokunu duyupta gelirim anam.

Çok uzak diyerlera gitsemde,

Acını duyupta gelirim anam.

Şimdi bu gurbette yazım kış oldu,

Gönlüm ne beklerdi,şimdi ne buldu.

Bin umut vardı bende,bir bir soldu

Gurbete düştümde,boynumu büktü.

Uzun uzun yolları,

Bir yudumda içerim.

Sıra sıra dağları,

Bir adımda geçerim.

Yeterki affet beni

Yeterki özle beni.

Vatanımla seni düşününce,derinden dokunur

Bir gün ölürsem anam,bilirim toprağım kurur.

İçimde sinenin kokusu,karşımda resmin durur,

Bağrıma bastıkça anam,gurbet hançer gibi vurur.', 'Gözüm kör olupta,düşsem yollara Kokunu duyupta gelirim anam. Çok uzak diyerlera gitsemde, Acını duyupta gelirim anam. Şimdi bu gurbette yazı...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anam-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılara Sığınış', 'anilara-siginis-alper-kuruk-b8n5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kütür kütür eriğini yediğim ağaçların

Kütür kütür dallarını kırdı yel,

Benim olan yaşadığım anılar 

Siz de mi el, siz de mi el? 

Sığındım yaşanmış anıların sıcaklığına

Yarının bilmediğim yellerine karşı

Şimdi içimde bir durgunluk

Bir sessizlik var içimde.

Belki yarın başımda

Yine bir kavak yeli eser

Yine duyarım eriklerin 

Dişlerimi kamaştırdığını

Ve yeni aşkların başıma 

Görürüm türlü dertler açtığını..', 'Kütür kütür eriğini yediğim ağaçların Kütür kütür dallarını kırdı yel, Benim olan yaşadığım anılar  Siz de mi el, siz de mi el?  Sığındım ya...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anilara-siginis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Biber', 'aci-biber-alper-kuruk-xc0jv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatı hiçe saydım

Boşa saydım hayatı,

Aşk hayatın tadıymış 

Bunu önce anlasaydım.

Ayrılık aşkın zehri

Aşkın biberiymiş ayrılık,

Felek,hiç yanmazdım 

Biber sürmene ağzıma

Eğer çocukcasına 

Aşk için ağlasaydım.

Bense güldüm...

Ayrılığı bilmeyişime gülmüşüm demek...

Ben gençtim Felek

Sen çocuk yerine koydun beni

Biber sürdün ağzıma.

Kendimden geçtim

Her şeyden geçtim ben

Tek aşktan geçemedim.

Dilim yanık

Dilim parça parça o biberden

Zehri geçmese de dilimden

Aşkım tek

Yekvücuduz aşk içinde o ve ben.', 'Hayatı hiçe saydım Boşa saydım hayatı, Aşk hayatın tadıymış  Bunu önce anlasaydım. Ayrılık aşkın zehri Aşkın biberiymiş ayrılık, Felek,hiç y...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aci-biber-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanardağ', 'yanardag-alper-kuruk-oc48g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğsüne bakıyorum

Doğrusu bakarken de 

Çok korkuyorum...

Göğsünün sağında FUJİ-YAMA

Solunda VEZÜV...

Dedim ya korkuyorum...

Vezüv, o kadar dolgun

O kadar sabırsız ki

Belli altında kalbin var

Kızgın lâvı bitmek,tükenmek bilmiyor.

O Vezüv, o Fuji-Yama kaç şehri alt-üst ettiler

Ama seninkiler

Lâv kusmadan da

Nice kâlpler erittiler...

Biliyorum hep bunları da

Bakarken korkuyorum göğüslerine

Anlıyorum içimde beliren sıcaklıktan

Benim kâlbim de yanacak

O lâvlar yorganım olacak...', 'Göğsüne bakıyorum Doğrusu bakarken de  Çok korkuyorum... Göğsünün sağında FUJİ-YAMA Solunda VEZÜV... Dedim ya korkuyorum... Vezüv, o kadar d...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yanardag-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı', 'postaci-alper-kuruk-i2xpn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yine postacı göründü

Zaten tüm hasretlikler bizim mahallede.

Elinde mektup dulu

Kapıları çalar postacı

Sevinç dağıtır evlere.

Postacı kapıları

İnsanlardan iyi tanır.

Hem bütün kapıları sever

Sever ama benimkinin önünden geçerken

Biraz utanır

Çünkü eli değmedi ona

Kapım ona yabancı.

Bir gidişi var ki postacının

Ah! bilseniz ne acı...

Niçin ben böyleyim ya Râb? 

Çocuklaşacağım gelir postacıyı görünce

Bir daha mektupsuz gelince

Desem ayıp olur mu bilmem 

Ey postacı,postacı bir mektup satar mısın?', 'İşte yine postacı göründü Zaten tüm hasretlikler bizim mahallede. Elinde mektup dulu Kapıları çalar postacı Sevinç dağıtır evlere. Postacı k...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/postaci-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Çarşı', 'kapali-carsi-alper-kuruk-xioez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçim dolu dert,

İçim dolu umut

Dertten umuttan pazar kurulu içimde

Ne ararsan bulursun

Tek arayan olsun...

Kıskanıyorum seni KAPALI ÇARŞI

Senin aydınlığa açılan 

O kadar çok kapıların var

Benimse içim her yanından kapalı

Açılacak bir dostu bile yok.

Senin malların kapış kapış gider

Bende dert çok,umut çok

Kuru umut neye yarar? 

Herkes derdi neylesin? 

Herkes dertliden kaçar.

Senin o geniş kapılarından

Aydınlıkla birlikte giren insanların

Karanlık kâlplilerinden biri de benim.

İçim dolu dert,

İçim dolu umut

Neyleyim,böyle geçinip giderim...', 'İçim dolu dert, İçim dolu umut Dertten umuttan pazar kurulu içimde Ne ararsan bulursun Tek arayan olsun... Kıskanıyorum seni KAPALI ÇARŞI Se...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kapali-carsi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Kelime', 'ates-kelime-alper-kuruk-6n32x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dökülürken dudakları yakan

Hasretten başka bir kelime

Bilirseniz söyleyin Allah aşkına.

Hasretti dudaklarımdan dökülen

Hasretti en kızdığım kelime

Beni de yakan o oldu zaten.

Ben vefayı yârda görmedim

Ayrılıkta gördüm ama...

Ben ayrılığı sevmedim

O beni sevdi.

Kurudu,büzüştü dudaklarım

Üzerinde hasretin zehri sıvalı

Korkuyorum yapıştırmaktan

Hasreti bilmeyen dudaklara.

Bende bu kader oldukça

Bilirim ayrılık yakamı koymaz,

Varsın ben dudağa doymayayım

Onlar hayatı anlasın...

Böyle sızlanacağım ben ömrüm sonuna dek

''Yansın bu dudaklarım hasretle yansın... ''', 'Dökülürken dudakları yakan Hasretten başka bir kelime Bilirseniz söyleyin Allah aşkına. Hasretti dudaklarımdan dökülen Hasretti en kızdığım ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ates-kelime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakılan Gönül', 'birakilan-gonul-alper-kuruk-i31xw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadından bir öpücük 

Sigaradan bir yudum

Dudağımdan içime

Sızan bir zehir duydum.

Bir tatlı sarhoşluk

Sardı boyumca beni,

Bir kadın yokluğuymuş

Hayatımdakı boşluk.

Zevk zevki doğurdu

Aşk da üstüne biber,

Dudakları bir kordu

Sigara ateşine benzer.

Bir an geldi ki o da 

Sigara gibi benden

Kül kül uzaklaştı

İzmaritçesine attım ağzımdan

Ben onu terkettim 

O beni bıraktı.

Dudağımın izi 

Benden ona yadigâr

Kendi artık yok ama 

İçim dolusu zehri var...', 'Kadından bir öpücük  Sigaradan bir yudum Dudağımdan içime Sızan bir zehir duydum. Bir tatlı sarhoşluk Sardı boyumca beni, Bir kadın yokluğuy...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/birakilan-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Sevgili İçin', 'hepsi-sevgili-i-cin-alper-kuruk-sc1lp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dili lâl

Gözü kör,

Yese bal 

Ağzı tatsız

Gönlü yârsız olanın.

Sevgili olmayınca 

Dil güzelikten kime bahseder? 

Kimi görür gözü? 

Gördüğnden ne zevk alır? 

Ağzının tadını anlar 

Hayatın zevki dudaklar 

Bal emen arı gibi

Sevgilinin dudaklarından

Öptükçe her seferinde

Bir başka çeşit kalır

O öpüşlerin tadı damakta...

Düşünce karadan geçti

Düşünce şimdi akta.', 'Dili lâl Gözü kör, Yese bal  Ağzı tatsız Gönlü yârsız olanın. Sevgili olmayınca  Dil güzelikten kime bahseder?  Kimi görür gözü?  Gördüğnden...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hepsi-sevgili-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ön Ve Son Hesap', 'on-ve-son-hesap-alper-kuruk-v190f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim için 

Güneş bir daha doğmamacasına batacak

Yere battığım zaman ben.

Güneş başkalarını ısıtacak,

Başkaları teneffüs edecek bu havayı,

Herkes fâniler için her şeyden

Faydalanacak bir zaman

Tıpkı benim gibi.

Payıma şimdi düşen bir toprak...

Yağmur başkalarını ıslatacak

Benim de toprağımı.

Biliyorum,toprak ana

Verdiğini alacaksın benden

En son zerresine kadar

Ki dünyada ilk hesap bu önceden.

Evet, bir de ötekini düşünüyorum...

Düşünüyorum da iyilikten yana

Her şeyi yapmak istiyorum.

Ama olmuyor ki öyle hep...

İnsanlığımı unutuyorum bazan

Ve uyuveriyorum şeytana...', 'Benim için  Güneş bir daha doğmamacasına batacak Yere battığım zaman ben. Güneş başkalarını ısıtacak, Başkaları teneffüs edecek bu havayı, H...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/on-ve-son-hesap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Değişmişsin Sen', 'cok-degismissin-sen-alper-kuruk-4hyac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen eskiden böyle değildin

Şimdi çok değişmişsin.

Soyadın başkaydı eskiden

Ayrılınca ilk işin benden

Soyadını değiştirmek olmuş.

İsmindeki bu değişiklik 

Senin sen olduğunu bana

İnandırmakta zorluk çektirdi.

Göğüslerin dimdikti eskiden

Şimdi solmuş.

Yüzün pürüzsüzdü

Herkes kıskanırdı seni

Artık kırışıklar dolmuş.

Şimdi ikileşmişsin

Başkalarına eşmişsin.

Gözlerin değişmemiş tek

O şeytanlık hâlâ gözlerinde.

Allah üstümde tek

Ben yerde yalnız

Elimden geçti çok kız...

Keşke bakmasaydım gözlerine

Gözlerindeki o şeytanı

İçime aktaran sen oldun.

Kandırdığım genç kızların

Utanıyorum bakamıyorum yüzlerine.', 'Sen eskiden böyle değildin Şimdi çok değişmişsin. Soyadın başkaydı eskiden Ayrılınca ilk işin benden Soyadını değiştirmek olmuş. İsmindeki b...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cok-degismissin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Sen', 'neredesin-sen-arif-altunbas-nkj4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam olur hüzün çöker özüme 

Ay ışığı vurur durur yüzüme

Melek gibi görünürsün gözüme 

Neredesin neredesin Sen

Yıldız gibi doğarsın sen içimde 

Gamlarımı boğarsın sen içimde 

Göz yaşımı sağarsın sen içimde 

Neredesin Neredesin Sen

Dağlarından sular olup akayım 

Şahin gibi yükseklerden bakayım 

Saçlarına gonca güller takayım 

Neredesin neredesin Sen

İstanbul,28.12.2005', 'Akşam olur hüzün çöker özüme  Ay ışığı vurur durur yüzüme Melek gibi görünürsün gözüme  Neredesin neredesin Sen Yıldız gibi doğarsın sen içi...', ARRAY['Türk Edebiyatı','Şiir','Arif Altunbaş']::text[], 8.5, '{"poet":"Arif Altunbaş","poet_slug":"arif-altunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neredesin-sen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-h-hikmet-esen-p8imm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tomurcuk

Patladı, patlayacak.

Gecikmiş baharın

Goncasında

Güneş''e gebe

Özlemler.

Çatlayan topraktan

Süzülen su

Bir erik fidesine

Ya da gülün dikenine

Koşacak nefes nefese 

Can vermeye.

Batacak koynuna

Aydınlığın

Akşamlar. 

Sökecek şafak, 

Güneş

Eli kulağında

Çıktı çıkacak 

Tepelerin ardından.

Tomurcuk

Can derdinde

Patladı 

Patlayacak...', 'Tomurcuk Patladı, patlayacak. Gecikmiş baharın Goncasında Güneş''e gebe Özlemler. Çatlayan topraktan Süzülen su Bir erik fidesine Ya da gülün...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tomurcuk-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Perdelik Oyun', 'tek-perdelik-oyun-h-hikmet-esen-rkh9a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gaz lambası ışığınIN

Yanık kokusunda 

Bulabilmek hazzı

Ve seçebilmek

Gölgeleri fütursuzca.

Parmaklarla

Tavşan gölgesi yapabilmek

Duvarlara

İz bırakmayan

Anılara karışan

Gölgeler ki tadı 

Çocukluğumdan kalan. 

Güneş''i iple çekmek sanki 

Ağaran tan''la

Gün''e merhaba.

Gaz lambası ışığından

Gün''e giden gölgeler.

Oyun biter

Yaşam mı, gölgeler mi

Gerçek boyut bilinmez.

Elbette çocuk da gitti gider

Sahne biter

Perde iner.', 'Gaz lambası ışığınIN Yanık kokusunda  Bulabilmek hazzı Ve seçebilmek Gölgeleri fütursuzca. Parmaklarla Tavşan gölgesi yapabilmek Duvarlara İ...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tek-perdelik-oyun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Feryadı', 'gozlerin-feryadi-i-brahim-duskun-6w9sr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerin feryadı bakışlar 

neleri anlatmazki

anlayabilince insan

umursamaz çağlar gördün çocuk

tanığı bakışların

feryadı gözlerin olan

bahar hala uzak değil mi

zemheri aylar şimdi

titriyorsun

anla diyorsun

umuyorsun

gel diyorsun

bekliyorsun

gözlerin feryadı bu 

neleri anlatmazki

öyle kala kalınca bakışlar', 'gözlerin feryadı bakışlar  neleri anlatmazki anlayabilince insan umursamaz çağlar gördün çocuk tanığı bakışların feryadı gözlerin olan bahar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-feryadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Bal', 'aci-bal-sadettin-deren-hudjh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir haber gelmesin istiyorum

Hiçbir satır senden

Zehrin ciğerimde gidişi

Döne-burkula  öyle güzel ki…', 'Hiçbir haber gelmesin istiyorum Hiçbir satır senden Zehrin ciğerimde gidişi Döne-burkula  öyle güzel ki…...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aci-bal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gidiş, gidiş değil gafletle ihanetle bu cennet vatan yıkılır bence', 'bu-gidis-gidis-degil-gafletle-ihanetle-bu-cennet-vatan-yikilir-bence-halil-colak-nkigh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delisiyim, divanesiyim, sevginin muhabbetiyim de bende 

 Kendimi de bilemedim bulamadım ey güzelim Ankara sende 

Coşkun sellere benzerdim engel tanımazdım hak olan yerde

Dillere kilit vuruluyor, hakkı söyleyen yeriliyor Ankara  sende 

Çağlar geçer, ömür biter hakkı söyleyenler, bu gidişle azalır sende

Hakkı savunmaktır,hakkı tanıtmaktır boynumun Borcu olan bende

Binlerce yıllık bir milletin başkentisin birazcık  kendine gel sende 

Sar milletin yaralarını artık vatan severler kaygı duymasın bende

Nasıl haykırmıştı o cihana hükmeden şahin bakışlı koca Yavuz sende

Bu cihan bir hükümdara çok bir hükümdara az haklıda dedem bence

Haykır artık Türkün güçünü kudretini göster,Ulu Atatürk söyledi sende

Bu gidiş, gidiş değil gafletle ihanetle bu cennet vatan yıkılır bence

 Halil Çolak 8.1.2006 Ankara', 'Delisiyim, divanesiyim, sevginin muhabbetiyim de bende   Kendimi de bilemedim bulamadım ey güzelim Ankara sende  Coşkun sellere benzerdim en...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gidis-gidis-degil-gafletle-ihanetle-bu-cennet-vatan-yikilir-bence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Evinde Bayram', 'huzur-evinde-bayram-enver-herguler-8492k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünkü endişelerim, tümü çıktı ya beyhude.

Biliyorum sabırsız oldum, değil ki elimde

Ne yapsam, yavrularım hep gözüm önünde

Şükürler ola yanında şimdi, hem de hepsi de 

Gelinler sıralanmış, kucaklayıp el öpmede

Torunlarım, daha önce taht kurmuşlar dizimde

Süt ve şefkatimle büyüttüğüm yavrularım,

Beni aşan boylarıyla sırım gibi hepsi de.

Yeniden depreşen o güzelim eşsiz anılar

Hasret gideren sohbet, sevgi hal hatır sormalar

Yankı yapar arada bir atılan kahkahalar

Ya hele bana sunulan o ender armağanlar! 

MUTLUYUM

Böyle geçti bir bayram günü neşe içinde

MUTLUYUM.

Böyle geçti bir bayram günü huzur evinde.

Mutluluğumu kıskanan,

Dur durak tanımayan yelkovan

Nasıl da karşı koydu

Zamanı durdurmak istediğimde.

Lâkin teselliyi buldum yazarak

Otuz şubatı günlük defterimde.....

Canım sıkıldıkça günlüğüme bakarım

Ziyâdesiyle depreşir bayram anılarım

Dört duvar arasında dolanır durur 

Meraktayım ne haldeler şimdi acaba? 

Benim cevher yavrularım.', 'Dünkü endişelerim, tümü çıktı ya beyhude. Biliyorum sabırsız oldum, değil ki elimde Ne yapsam, yavrularım hep gözüm önünde Şükürler ola yanı...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/huzur-evinde-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Be Dünya', 'ah-be-dunya-necati-keceli-wmtsd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah be dünya senin neyini sevem

    Geldim gidiyorum el oldun bana

    Altın yükü değil şu topal devem

    Çok çalıştım ama pul oldun bana

    Hayallim, umudum acıdır aşım

    Yol yarıyı geçti tükenir yaşım

    Pamuk tarlasına döndüde başım

    Başımdan dökülen kıl oldun bana

    Sardı etrafımı kalınca surlar

    Kuruyup gidiyor gözde pınarlar

    İçime yağarda yağmurlar, karlar

    Hayırsız, vefasız kul oldun bana

    Üstümdemi kaldı o nankör gözün

    Mevsiminde yokmu baharın yazın

    Hep bağrımı yaktı içimde közün

    Kuruyup yandığım çöl oldun bana

    Ağustos ayında gelir üşüme

    Mutluluk girmiyor hayal düşüme

    Bu yılların izi kaldı döşüme

    Transit geçtiğim yol oldun bana

    Ecel yolu bekler kalkmış atağa

    Hatırım sormadan attı yatağa

    Çok sevdiğim girdi kara toprağa

    Günlerce döktüğüm sel oldun bana

    Necati KEÇELİ

    İZMİR', 'Ah be dünya senin neyini sevem     Geldim gidiyorum el oldun bana     Altın yükü değil şu topal devem     Çok çalıştım ama pul oldun bana   ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ah-be-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Evi Bahçesi', 'huzur-evi-bahcesi-enver-herguler-qmvea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Burada da bahar olurmuş

Hem de her renk çiçekleriyle,

Cıvıl cıvıl kuşları da dahil.

Dışardaki ayni güneş burayı da ısıtıyor

Etrafında hayat dolu nice insanlar ancak

Yorgunluktan olacak ki

Hareketleri gayet yavaş.

Kimsem yok sananlar

Pek de yanılırlar.

Kader ortağımdır dertlerimi paylaştığım

Zümrüt yeşili yapraklar.

Beraberce bekliyoruz

Bahardan sonra yaz gelir ya

Doğrusu ürkütür bizi

Yazdan sonrası....', 'Burada da bahar olurmuş Hem de her renk çiçekleriyle, Cıvıl cıvıl kuşları da dahil. Dışardaki ayni güneş burayı da ısıtıyor Etrafında hayat ...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzur-evi-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**-Gidiyorum-**', 'gidiyorum-i-lker-unlu-s6a7b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün tüm anlaşılmamış değerlerimi görüp de gidiyorum... 

Büyük bir yıkılmışlıkla, değerimi görerek gidiyorum... 

Acıdan kahrolsam da sensiz gecelerde, 

Boş yastığına bıraktığın kokun, 

Islansa da geceleri... 

Sensizlik bir karabasan gibi ulusa da karşımda, 

Bana verilen değerle yüzleşip gidiyorum... 

Saklı kalan tüm izleri bir bir yakıp, 

Düşüncesizliğini de bu sevdaya katıp, 

Yokluğuna da yine bir dal gül takıp, 

Kalbimi eze, eze gidiyorum... 

Ve ben gidiyorum... 

Sana bundan sonra kimsenin ben gibi dokunmayacağını, 

Böyle içten konuşmayacağını, 

Artık adına hiç şiir yazılmayacağını, 

Bile, bile gidiyorum... 

Her güzde bir sitemle ansam da adını, 

Farklı tenlerde aradığım kadını, 

Adına kendini paralamış adamı, 

Kalbimde yalnızlığa itip de gidiyorum... 

Artık ne bir sitem ne bir kelam kalacak, 

Artık bu iki kalp hiç öyle atmayacak... 

İşte bu hüzünlü fedakârlıklar ardında, 

Toprağına bağlı, güneşe hasret, karlar altında, 

Boynu bükük bir papatya gibi, 

Yalnızlığa itilmiş bir sevda kalacak... 

Ve ben gidiyorum... 

Her güzde bir sitemle anacağım adını, 

Farklı bir tende aramayacağım kadını, 

Adına kendini paralamış adamı, 

Kalbimde yalnızlığa itip de gidiyorum...', 'Bugün tüm anlaşılmamış değerlerimi görüp de gidiyorum...  Büyük bir yıkılmışlıkla, değerimi görerek gidiyorum...  Acıdan kahrolsam da sensiz...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gidiyorum-198-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Çiçeği', 'mum-cicegi-alper-kuruk-gzt33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanmak,hep yanmak

Kerem gibi Aslı için

Yunus gibi Allah için.

Aşıklara karıştım ben de...

Ama ben yanmaktan

Dem vurmayacağım.

Bana bir söz ver de

Aşkından içime bir fide

Mum Çiçeği fidesi dikeyim.

Yedi sene sırf yeşil yaprak açayım

Çiçeğimi saklayayım içimde

Senin için.

Sabrımı verir Allah

Sen yalnız söz ver

Ve dur sözünde.

Sabırla açan mum çiçeğinden

Elimle bir taç yapayım

Ben onu başına takayım

Tek sen beni peşine tak...', 'Yanmak,hep yanmak Kerem gibi Aslı için Yunus gibi Allah için. Aşıklara karıştım ben de... Ama ben yanmaktan Dem vurmayacağım. Bana bir söz v...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mum-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuşlar XL', 'kopuslar-xl-erol-dal-5l8an', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Azabı hak etmiş bir kulum. 

Budur işte benim sonum

Ki; 

Uykuya hasret ruhum.

Uyuştu bedenim

Duymuyorum; 

Soyundum artık

Donmuyorum…

Sonsuzluklar mekanındayım,

Susuzlara sunduğun şarap

Baldan; 

İçmiyorum…

Sondan başladım biliyorsun

Umursuzluğum bundan.

Terk ettiğim vahşetin izleri; 

Derin kaldı alnımdan.

Beni ateş paklar arkadaşım.

Aslında çabalamadan yanmalıyım.

Toz dumana karışırken,

Atılırken dağlar etrafa

Ben toprakta; 

Yeniden doğmalıyım…

                                      Mekan/2006', 'Azabı hak etmiş bir kulum.  Budur işte benim sonum Ki;  Uykuya hasret ruhum. Uyuştu bedenim Duymuyorum;  Soyundum artık Donmuyorum… Sonsuzlu...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kopuslar-xl-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Hamuru', 'ask-hamuru-asude-gediz-midgq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın

asalettir hamuru 

zoru başarmaktır huyu

acı  yer, sızı içer

kırdınsa  onu 

gömer

kolay kolay ele gelmez

bu da 

onun 

onuru.....', 'Aşkın asalettir hamuru  zoru başarmaktır huyu acı  yer, sızı içer kırdınsa  onu  gömer kolay kolay ele gelmez bu da  onun  onuru........', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-hamuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosunlu Gözler', 'yosunlu-gozler-alper-kuruk-uu34b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok mu ağladın böyle

Yosun tutmuş gözlerin? 

Gerçek âşıksın belli hâlinden.

Ağlamak lâzım ara-sıra

Yeşertmek için gözlerde

Yeni aşk filizlerini.

İşte 

Ateşin cavcavlı zamanında

Kavrulurken filizler

Bazı kere

Bir ayrılık samı eser

Gözleri kurutur

O an kâlplerdeki sıcaklık

Ölü soğukluğuna bürünür âniden.

Dinmez göz yaşı artık

Yosun bağlar gözler seninki gibi...

Şimdi bakacak olsam gözlerine

Kayıyor,tutunamıyor gözlerim

Benzemiyor gözlerin eskisine.', 'Çok mu ağladın böyle Yosun tutmuş gözlerin?  Gerçek âşıksın belli hâlinden. Ağlamak lâzım ara-sıra Yeşertmek için gözlerde Yeni aşk filizler...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yosunlu-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin her zaman sıcak mı bakar..', 'gozlerin-her-zaman-sicak-mi-bakar-ercan-akbay-2mx1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin her zaman,sıcak mı bakar

   Yoksa gözlerime,bir davet mi var

   Ellerin her zaman,sıcak mı tutar

   Yoksa ellerime,bir davet mi var.

   Ömrüme son düşen,cemre misin sen

   Kalbime bal süzen,petek misin sen

   Kadere dur diyen,peri misin sen

   Dudağın her zaman,böyle mi yakar.

   Gözlerin her zaman,sıcak mı bakar

   Yoksa hislerime,bir davet mi var

   Kolların her zaman,sıcak mı sarar

   Yoksa bu aşkıma,bir davet mi var.

   Ömrüme son düşen,cemre misin sen

   Kalbime bal süzen,petek misin sen

   Kadere dur diyen,peri misin sen

   Dudağın her zaman,böyle mi yakar....', 'Gözlerin her zaman,sıcak mı bakar    Yoksa gözlerime,bir davet mi var    Ellerin her zaman,sıcak mı tutar    Yoksa ellerime,bir davet mi var...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-her-zaman-sicak-mi-bakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmam Nikahı', 'i-mam-nikahi-cahit-etikan-voz5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günahı imamın,

Nikahı damadın boynuna.

Gelin kendinden emin.

Mum söndüde,kim kimin girdiyse koynuna.

Kerametine helal,haram-ı haremin.

Adam hamile,

Kadın bakire,

Nikah şekeri yerine krem deterjan verilmeli bu kire...

Göbek taşında yıkatsın.

Bir yastıkta kocatsın.

Amin...Amin...

               Cahit Etikan

                  1975', 'Günahı imamın, Nikahı damadın boynuna. Gelin kendinden emin. Mum söndüde,kim kimin girdiyse koynuna. Kerametine helal,haram-ı haremin. Adam ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Etikan']::text[], 8.5, '{"poet":"Cahit Etikan","poet_slug":"cahit-etikan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/imam-nikahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf-safına ve mert', 'saf-safina-ve-mert-kemal-guzel-83cnu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'daha çatal tutmasını bile beceremiyor

ne yapsın parmaklarıyla yemesini öğrenmiş

cam masalarda değil; 

yer sofrasında doyar ancak.', 'daha çatal tutmasını bile beceremiyor ne yapsın parmaklarıyla yemesini öğrenmiş cam masalarda değil;  yer sofrasında doyar ancak....', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saf-safina-ve-mert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düelo', 'duelo-kemal-guzel-3opsy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanlık bir gecede 

soğuk bir rüzgar eser

kahrınızı çeken kemal 

sizi MAHŞERDE bekler', 'karanlık bir gecede  soğuk bir rüzgar eser kahrınızı çeken kemal  sizi MAHŞERDE bekler...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duelo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci şans', 'i-kinci-sans-kemal-guzel-p7ibu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir daha gönderin beni 

birkez daha göreyim onu...', 'bir daha gönderin beni  birkez daha göreyim onu......', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ikinci-sans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan sesler', 'uzaktan-sesler-kemal-guzel-rcgia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayal kurmak çok uzak

düşsel bir denge değil,

çırılçıplak ve gerçek.

Hergünün ardında bir zorluk saklı.

Her çiçek bin yılların yorgunluğuyla açar.

Taze durdukça

bütün bu gelmeler,herbiri bir gitmenin çağrısı,

ve sonra çökmeye başlar kanlı hüzün,

 ve acılar herbiri bir yerden vurur.

Sonra sezar gibi bir yılma,

bir yenilgi,

kazanç yok! 

Kaçmak yok,saklanmak nafile.

Al eline kalemi o zaman,

yazmaya 

              BAŞLA...

Eğer mürekep bütün bunları yazmaya yeterse...

Yetmez ise,

akıllılığı bırak çal o zaman bir roman havası.', 'Hayal kurmak çok uzak düşsel bir denge değil, çırılçıplak ve gerçek. Hergünün ardında bir zorluk saklı. Her çiçek bin yılların yorgunluğuyla...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uzaktan-sesler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki, Ve, Hep', 'ki-ve-hep-metin-yalti-gq8f3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ki,

Demişti bana

“İnsan bir ormandır.”

Ve

Ne zaman çıksa

Kendi derinliklerine doğru

Bir yolculuğa

Anlatacağı yeni şeyler 

Dağarcığında 

Hep

Geriye döndüğünde…

08,01,06', 'Ki, Demişti bana “İnsan bir ormandır.” Ve Ne zaman çıksa Kendi derinliklerine doğru Bir yolculuğa Anlatacağı yeni şeyler  Dağarcığında  Hep ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ki-ve-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 20', 'd-siir-ve-sarki-sozleri-20-huseyin-avdic-ttftj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen Aşktan Ne Anlarsın

Sen hiç aşık oldun mu? 

Sevgiliyle doldun mu? 

Mecnûn gibi çöllerde,

Çaresizce koştun mu? 

*   *   *

Sen aşktan ne anlarsın! 

Anlamsızca yaşarsın.

Aşıklara gülersin.

Aşktan korkar kaçarsın.

*   *   *

Sevda nedir sordun mu? 

Leylâ gibi soldun mu? 

Sonsuz bir aşk arayıp,

Gerçek aşkı buldun mu? 

*   *   *

Sen aşktan ne anlarsın! 

Anlamsızca yaşarsın.

Aşıklara gülersin.

Aşktan korkar kacarsın.

Not: TSM olarak bestelendi.

Berlin, Aralık 2005.', 'Sen Aşktan Ne Anlarsın Sen hiç aşık oldun mu?  Sevgiliyle doldun mu?  Mecnûn gibi çöllerde, Çaresizce koştun mu?  *   *   * Sen aşktan ne an...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-24 Sırtımdaki yaralar', 'yb-24-sirtimdaki-yaralar-mehmet-coban-2lrd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanık ağıtlar dinledim

Yürekleri burkan

İnsanlar gördüm

Kendilerine zincir vuran

Kolları yorgun düşmüş

Oraları buraları şişmiş

Sırtları kan revan içinde

Gözlerinde inanç dolu

Yüzlerinde mutluluk dolu

Hava bir başkaydı bu gün

Gökyüzü yeni gibiydi

Eskilerine benzemez

İnsanlar grup, grup olmuşlar

Yanık ilahi musikilerle

Yanık sesleriyle 

Ortalığı inletiyorlar

Atmosfer öyleydi ki

Soramadım bile olanları

Zordu etkilenmemek

Zordu seyretmemek

Aklımda düşünceler

Nasıl olur, acı mutluluk verir? 

Nasıl olur, insan kendine acı verir? 

Nasıl olur, acı gözlerde inanç olur? 

Nasıl olur? Nasıl olur? 

Bu ne? Bu ne? Bu ne? 

Dedim etrafındakilere

Kerbela, kerbela, kerbela! ...

Dediler! .....

Anmaktı o gün olanları

Anıyorlardı o gün olanları

Sözle değil, 

Şiirle değil

Ağıtla değil, 

Acıları hissederek

Acıları yaşayarak

Gördüğüm tablo

İnsan inancının

İnsan sevgisinin

Sevgi duyduğu

Saygı duyduğu

İnanç duyduğu

Şeyleri, nasıl yaşadığını gösteriyordu! …

Ertesi gündü, 

Ortalık sakindi

Kendime bir arkadaş buldum

Dün olanları tek, tek sordum

Dedi, 

“Peygamberin torunu 

Peygamberin gelinleri

Zalimler tarafından

Her türlü eziyetle

Şehit edildi Kerbela’da

Dün onu andık

Dün onu yaşadık

Şahadeti andık

Şahadeti yaşadık”

Peki dedim, 

Dün gördüklerim 

Çok etkiliydi

Ancak bu gün düşündüğümde

Aklım almıyor böyle anmayı

Çünkü insanın kendine eziyeti

Yasaktır tanrının dininde

Başkalarından gelen eziyeti

Karşılamaktır sabırla dinde

Dün ise insanlar

Sırtlarına zincir vurdular

Her taraflarını yaraladılar

Doğru mu? 

Dinde var mı bu? 

Hışımla döndü bana, 

Kaldırdı gömleğini

Açtı gösterdi sırtını bana

“Sırtımdaki yaralar

İnancım için ne yapabileceğimi

Sevdiklerim için ne yapabileceğimi

Atalarım için ne yapabileceğimi

Gösteriyor, 

Sen inancın, sevdiklerin için

Ne yapabilir sin ki? ” Dedi

Bu inanç karşısında 

Ne diyebileceğimi bilemedim

Ama sorular vardı kafamda

Din bunları yasakladı diyemedim

Tarihine bu kadar bağımlı olanın

Atalar dinini terk edebileceğini düşünemedim

Tanrı her ayetinde altını çizse de

İnsan kendine atalar dini üretiyor diyemedim! ..

Döndüm arkama doğru

Uzaklaştım oralardan

Düşündüm kendi kendime

Defalarca tanrının sözlerinde

Atalar dininden niçin söz ediyor? Diye,

Anladım ki, tanrının sözlerini

Ancak  gölgelemiş, örtmüş atalar dini

Bu günde, geçmişte de, her devirde de! ..

Bilimcimle tanrıma yöneldim

Senin için her türlü zorluğa katlanırım

Ama asla bana verdiğin nefse zulüm edemem

Asla, yolunu kendi duygularımla gölgeleyemem

Diyerek, bilimcimi tazeledim, 

Aklımı, muhakememi, inancımı tazeledim.

Çizdirmeden yürüyeceğim bu yolda

Eğip bükmeden yaşacağım inancımda

Gelse de başıma her türlü bela

Yapsalar da hayatımı hep Kerbela

Sabırla, inançla, yürüyeceğim bu yolda

Bana destek verecek olan vücudumla

Elimle, kolumla, ayağımla, sırtımla

Bunlar benim arkadaşlarım inandığım yolda

Asla onlara eziyet edemem bu uğurda! ..

Onlar olmasa ben ne yapabilirim ki bu yolda? 

Ben onlarla varım, onlarla yaşarım inancımı

Ancak cahil insan çektirir onlara lüzumsuz acıları! ...

08.01.2006-İzmir', 'Yanık ağıtlar dinledim Yürekleri burkan İnsanlar gördüm Kendilerine zincir vuran Kolları yorgun düşmüş Oraları buraları şişmiş Sırtları kan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/yb-24-sirtimdaki-yaralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '17 Ağustos 1999 Depremi', '17-agustos-1999-depremi-recep-uslu-kkwc9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıkılır dedi dağları

Dümdüz olur ova gibi

Yıkıldı dağlar.

Yıkıldı kocaman binalar

Yıkıldı analar babalar.

Yaşlıdır kaçamaz demedi,

Çocuktur masum dinlemedi,

Göçtü üzerine dağlar,taşlar

Yardım bekleyerek vedalaştılar.

Allah insana akıl vermiş

İnsan aklıyla fay hattını bulmuş

İsyan etmiş Allah''a

Fay hattına fabrika kurmuş,ev kurmuş,şehir kurmuş

Ne idare edenin umurunda olmuş,

Ne yapanın,ne seyredenin.

Gün geldi...

Yıkıldı dağlar,

Patladı yarıldı faylar

Ne varsa üzerinde aldı altına

Kadın, erkek dinlemedi

Kurtarmaya gücümüz yetmedi.

Ağladı analar,ağladı babalar

Gözyaşı dinmedi,acı bitmedi.

Kurtar diyordu küçük bir kız

Babam enkazda dayı

Gözyaşları sel oldu,çığlığı yumak

Üç gün sonra varıldı yanına

Günlerden cuma,aylardan ağustos ayı

Ölmüştü adam ''Allah rahmet eylesin''

Bu dersler de bize yetsin.

Kapkara duman kapladı şehrin üstünü

TÜPRAŞ yanıyor patlayacak! 

Her yanı ölüm kaplayacak

Kaçtık dağlara,uzaklaştık tehlikeden

Enkazdakileri yarı canlı bırakıp

Umut içinde öldüler

Topluca gömüldüler.

Anılarım,dualarım onlarla

Eğer yararı varsa...

.......................

29.10.1999', 'Yıkılır dedi dağları Dümdüz olur ova gibi Yıkıldı dağlar. Yıkıldı kocaman binalar Yıkıldı analar babalar. Yaşlıdır kaçamaz demedi, Çocuktur ...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/17-agustos-1999-depremi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşsana', 'konussana-aytekin-orhan-onv7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne duruyorsun? 

zamanı şimdi vur silahınla

yarına kalmasın içindekiler

dökülsün...

yeni bir sayfa açılsın

geçmişe sünger çekilip

ne olacaksa bugün olsun

yarını kim bilir?', 'ne duruyorsun?  zamanı şimdi vur silahınla yarına kalmasın içindekiler dökülsün... yeni bir sayfa açılsın geçmişe sünger çekilip ne olacaksa...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/konussana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu kadar tatlı mıydı?', 'bu-kadar-tatli-miydi-aytekin-orhan-tb2bs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yorgun bakışların arasında geçti,

harabe şehre göç! 

ulaşıldığında, kayıp baykuş naraları...

son durak! inen var mı? soran olmadı.

...vızıltısıyla fırladım. 

geç kalınmış, adrese teslim anladım.

rüyada bile olsa acıydı.

ki gerçeğini de yaşamıştım.

yirmi saniyede yirmi yıl akmıştı gözlerimden

bu kadar tatlı mıydı?', 'yorgun bakışların arasında geçti, harabe şehre göç!  ulaşıldığında, kayıp baykuş naraları... son durak! inen var mı? soran olmadı. ...vızılt...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-kadar-tatli-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gibi Aklımdasın', 'dun-gibi-aklimdasin-i-brahim-dikmen-2-mdm9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutuldun sanma

hala

dün gibi aklımdasın

en sevdiğim özelliğindi

kömür karası gözlerin

şımarık

çocuk  gülüşlerin

aklımı

başımdan almaya yeterdi

kırmızı

şarap tadındaki dudakların

beni

sana tutsak eden

o''şuh bakışlarındı

bir türlü

hayır diyemediğim

senden vazgeçemediğim

zamansız

hoyrat sevişmelerindi

dudaklarımda yanan

arsız öpüşlerindi

okşamaya doyamadığım

bembeyaz

pürüzsüz bedenin

düzgün

uzun bacaklarındı

öpmeye bile kıyamadığım

başımı yaslayıp

kimi vakit ağladığım

kimi zaman

öpüp çocuklaştığım

ufacık göğüslerindi

hala

dün gibi aklımdasın işte

seni nasıl unutabilirim ki

sen

beni benden çalan

ilk ve tek kadındın

08/01/2006', 'Unutuldun sanma hala dün gibi aklımdasın en sevdiğim özelliğindi kömür karası gözlerin şımarık çocuk  gülüşlerin aklımı başımdan almaya yete...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dun-gibi-aklimdasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik kuş', 'minik-kus-aytekin-orhan-jtfgz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'usulca çöküverdi.

anlatmak istedi.

çıkmadı sesi,

yığılıverdi.

beraberinde götürdü.

özgürlüğü; 

bir avuç toprak,

üstüne örtüldü...

24/11/2005', 'usulca çöküverdi. anlatmak istedi. çıkmadı sesi, yığılıverdi. beraberinde götürdü. özgürlüğü;  bir avuç toprak, üstüne örtüldü... 24/11/2005...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/minik-kus-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaranın faydası', 'sigaranin-faydasi-mazlum-unlu-37b6k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde kalem

Ve bomboş bir kağıt

Tek düşündüğüm sen

Konu sen 

Hep sen

Şu sigara da olmasa

Napardım

Sigara nasıldır bilir misin? 

Nasıl içilir bilir misin? 

Önce derin bir nefes çekeceksin

Aklına sevdiğin gelecek

Tekrar derin bir nefes daha

-Bende yaktım şimdi-

Uzun uzun 

Yavaş yavaş 

Üfleyeceksin

Sanki derdini atarmış gibi

Sigara sağlığa zararlıymış

Boş laf

Bana yarıyor işte

Ömrüm mü azalıyor

Kime ne! 

O yok zaten

Uzun hayatı kim ister 

Anılar da olmasa

Gene sen 

Her zaman sen', 'Elimde kalem Ve bomboş bir kağıt Tek düşündüğüm sen Konu sen  Hep sen Şu sigara da olmasa Napardım Sigara nasıldır bilir misin?  Nasıl içili...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sigaranin-faydasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlığım geceyi yırtardı', 'cigligim-geceyi-yirtardi-aytekin-orhan-zh0bb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece çökerdi.

Çığlığım geceyi yırtardı,

El ayak çekildiğinde...

Bin bir hüznün, veda partisiydi

Yaşanmışlığın verdiği...

Bir umut ki düşün! 

Tazelenen.

Bir gönül ki düşün! 

Sönüp giden...

Bilmem kaçıncıdır bu? 

Kaçıncı isyanım,

Ruhumun devrimlerinde...

Serpilir bulutlar,

Yüreğimin ılık esen meltemlerinde...

Bir rüzgar isterim

Savursun beni benden ötelere,

Bilinmezlere...

Bir rüzgar isterim

Dağıtsın benliğimi hazan mevsiminde.

Alışıla gelmiş düşünceler bana göre değil

Bana göre değil bu dünya.

Başka olmalı, başkaları olmalı...

Sıkıca saran okşayan gözyaşları mı

Alıp götürmeli efkarımı, kanatlanıp gökyüzüne

Götürmeli...

Her daim bir çocuk gülmeli gözlerimde

Geçmişimle beraber.

Beni boğmadan yaralamadan gülmeli

Anlamalı; 

Birisi olmalı,

Gözlerinde kaybolmalıyım.

İçim titremeli yanındayken,

Dokunmadan sarmalı, gönül gözünden,

Okşamalı yıpranan bedenimi,

Unutmalıyım kendimi tüm benliğimi...

Yıl geçmeli,mevsim bahar olmalı,

Hasret solup sevda açmalı,

Ruhumun derinliğine,

Ilık ılık nefesi dolmalı

Birisi olmalı...

Mart/2004', 'Gece çökerdi. Çığlığım geceyi yırtardı, El ayak çekildiğinde... Bin bir hüznün, veda partisiydi Yaşanmışlığın verdiği... Bir umut ki düşün! ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cigligim-geceyi-yirtardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamam Gitmene', 'alisamam-gitmene-seyfettin-bilal-ozluk-0gi5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin batışı gibi olsun isterim her gidişleri

Karanlıkta kaybolmaya alışkınım çünki

Kanayan içimi bir ben bilirim gerisi yalan bilir

Uzanmak istedikçe batan güneşin ardından

Yaşlı gözlerle baka kalırım

Alıştım nasıl olsa gitmelere

Dönüşlerinde ben, ben olmuyorum olamıyorum.

Gidenlerin ardından üzülmedim

Gidene kal demek zaten işe yaramaz

Kaybettim bilmeden birine üzülemiyorum

Diğerini bilerek ben kaybedeceğim etmeliyim

Dönüşlerim olmadı asla kararlarımdan

Alışırım senin gitmene gözümden yaş gelmesede

Gelişlerinde ben, ben yokum yok olacağım.

Isıtmıyor artık kışın kızıl güneşi

Buz tutmuş bedenim kıpırdamıyor

Tutulmuş dilim gitmelerin ardından

Kopmak istemesemde gideceklerden

Yol verdim ve vermeliyim

Alıştım nasıl olsa gitmelere

Gidişlerinde ben, ben olarak kalamayacağım.

Şimdi iki gidenin ardından bakıyorum

Bir gitmeye daha hazır değilim susarım 

Sakın gitme zamansız ölürüm

Anlatamıyorum ki varlığını kimselere susmam bundan

Nasıl olsa alışmışsın diye sakın gitme

Alışamam senin gitmene

Gidersen ben, ben olamam biterim..', 'Güneşin batışı gibi olsun isterim her gidişleri Karanlıkta kaybolmaya alışkınım çünki Kanayan içimi bir ben bilirim gerisi yalan bilir Uzanm...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/alisamam-gitmene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tatile çıkacağım Bıçak Sırı Blues''larda...', 'bir-tatile-cikacagim-bicak-siri-blues-larda-akin-akca-pdg0o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tatile çıkacağım Harrison Ford’da

Blade Runner -Lou Reed ve Angelo Badalamenti’den

Ennio Morricone`vari bir patlatmaca

Clint, Clint eastwood Bond oo7 ve 

Damon Albarn Georilla

Ki lost Hiway’den Robocop 

Arquette Ros€anne

Bir J. Malkoviç D. Lynch’de.. …

- Rachael ile…

O her şeyin bir huzra erişinde

Gideceğim bir tatile

Kırlarda yemyeşil

Uçabilen bir araba 

Tekerlekleriyle ilerliyor yerde:

İçinde Harrison,

Öğrenebilen Robot Rachel’le.

Rutger Hauer, insancıl; 

“Blush Response” sessizliğinde; 

(kompleksin içine sızarak, ışıklı yapı’nın,

yapımcısı baş robotik uzmanını öldürdü,

daha sonra kendini -

bot avcısı Harrison önünde,

zorla seyrettiren 

bir robot infaz törenini,

hayatın amacını anlatmak 

birilerine istiyor gibiydi:

insan inşaatçısını ölrüderen

bir robot katil midir? 

çözmeli bulmacayı) 

Rachel neden inadetmemeyi tecrübe edebildi? 

Kırlara çıkacağının bilinci, önceden

Geçirilen olumsuzlukları silip atmış olmalı.

“Main titles” ile “end Titles” arası..

“Rachel’s Song”, “One More Kiss Dear”; 

Oh, “Memories o’Green”s o2.

“Tale’s of the Future”s a “Damask Rose”:

“Wait for(m)  me”, it’s a “Love Theme”.

Çift tırnaklar alıntı

Blade Runner filmine de atfen.

Ridley Scott, Harrison ford ve rutger Hauer’e, A. Badalamenti ile Clint, Lynch  ve Eniio’ya saygılar.

Orda bir Sabestian adlı adam da vardı robot yapan. Oda iyi oynamışt :)', 'Bir tatile çıkacağım Harrison Ford’da Blade Runner -Lou Reed ve Angelo Badalamenti’den Ennio Morricone`vari bir patlatmaca Clint, Clint east...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-tatile-cikacagim-bicak-siri-blues-larda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-seyfettin-bilal-ozluk-uvk9h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen başka kollardasın istesende istemesende

Ben ise boş odalarda yalnızım

Sarıldıkça sen o kollara umarsızca içinden gelmesede

Hasretinle ısıtıyorum kendimi kandırıyorum uyuyana kadar.

Tutunacak dalın var düşmelerinde

Koşmak istemesende, koşacak beklemesende

Tutarmı saçlarını okşarmı bilmiyorum bilmek istemiyorum içim acıyor

Ben olmayacağın ve olmadığın yastığımda seni arıyorum.

Titreyip üşüdüğümde senden uzaklarda

Olmadım başka kollarda olmam gerekmedikçe gerekmedi de

Yaşadığım lanet ihaneti asla sana yaşatmam görmesende bilmesende

Bir ömür yalnız kalacağımı bilsemde umurumda değil.

Gözlerin bakmasada gözlerime

Tutamayacağın ellerim boş sana uzansada

Bırakıp gidemem heves uğruna dolu yataklara

İçimde seni büyüttüğüm ve varolduğun sürece.

Ağlasa gözlerim kalbimle birlikte

Senin başka kollarda olduğunu unutmayacağım

Ruhumu satmadım şeytana satmayacağım

Kollarımla seni saracağım günü hep bekleyeceğim gelmesende

Masaldasın uyan deselerde biliyorum uyuyacağım

Gözlerimle seni başka yollarda arayacağım

Yolun sonu çıkmaz sokak nasıl olsa

Bir ucunda ben bekliyor olacağım çünki çıkmaz sokak.', 'Sen başka kollardasın istesende istemesende Ben ise boş odalarda yalnızım Sarıldıkça sen o kollara umarsızca içinden gelmesede Hasretinle ıs...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cikmaz-sokak-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C. Arf', 'c-arf-akin-akca-0mwy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“ Matematik tümevarımsal bir bilimdir ve bu tümevarımsal bilim sonsuz kümeler için geçerli. Bu sonsuzlukları tümevarımsal bir şekilde kavrıyoruz ve kavradığımız zaman da o sonsuzluğu hissediyoruz, sınırsızlığı.

Ve bu bize mutluluk veriyor, çünkü ölümü unutuyoruz... Herkes ölümsüz olduğunu hissettiği alanda çalışmak ister. Ben de matematikte kendimi ölümsüz hissettim...” CAHİT ARF (İSTANBUL, 26.12.1997) 

i.

Bir ayakkabı boyacısı umudedebiliyor sonsuzluk algısı; 

Yıl 191o 2o.yy’da, sonsuzluktan sonsuzluğun talebi doğdu.

Dolu bu derece de vefa, bu denli de ulvi, kadirşinas –

Anlaması için hayaletmesi bir gerçeği, ona katılanlar.

Kuğulu Park’ta çayımı yudumlarken düşünüyorum,

Nasıl olur da bazı insanlar bunca çaba hayata yormuşlar; 

Kafasına kurukafa dememiş olacak, su dolusu bir tas …

Dokurdıyor* ince kıvrımlar, fokurduyor; pınarlar tutkusu; 

Böylece şekil veriyor pabuçlara o boyacı küçük çocuk.

Parayı sürükleyendir merak, görmüştük Tesla’da bunu:

Vücudundan geçerken, saçları, her yeri dikilmiş, elektrik.

Hata olduğunu söylemişti William Blake’den kehanetsel

masumiyet çağrıları, tutkunun insanı sarmalamasının:

Tutku insanın içinde olmadıkça, bir metal yığınısındır.**

Yoksa tüy kadar ama hafifsindir, şiirsel matematik dilinde.

İnsana insan deme, matematiğin fiziği kapsayışı yönüne.

Çünkü matematik bir dil, edebiyat gibi bir il, bir vatan:

Nasıl ki dünya kapsar ülkeleri, vatanları –, barış güvercine; 

İşte öyle yokuş bir hariciye, ulaşan tümevarıma al nikbin.

Lisanlar bütünü, sanat fizikse ki öyle matematik şiirdir; 

Yeryüzü barışı da izafi ya, böyle gelecektir elbet bir gün.

Duygular ilerletmiyorken öçleri; ihanet, akıl oyunuyken:

İnsan öğrenecek barışı, duygulara zekasını uyarlayacak.

Büyük yaşam; yakın çağ bir efsane, Cahit ağabey oldu:

Çiviyi çivi sökende, ak pak balıklar kavakta kar yağdığınca; 

Bilimi arzulayan hayalperest Jules, Ay’a Yolculuk gerçekti.

İnsana insan deme, matematiğin fiziği kapsayışı yönüne; 

Lisanıdır çünkü, vatanıdır fiziğin matematik; şiir, sanat’ın.

O bileşkeler ki bu alt kümeler, hiçbir öngörüde bulunmazlar -

Buna da uğraşmazlar- en küçücük bir çıkar hesabı nevi.

Ter dökerler, faydacılık uğruna; ancak öğreticilik amaç değil:

Eğitim o kadar da çok önemlidir, ne var ki her şey değildir; 

Duyguların sen, beynin değil senin, sen olmadıkça öğretim.

ii.

Sentetik geometri kullanarak çözmek kamaşık matematiği; 

Elastiki, asal trigonometrisiz, asal analitik geometri’siz:

Amale gibi çabaladı, çünkü ardında en güvenli çözüm.

ARF, Paul Erdos’a biraz benzer; amfetamin haplarıyla

2o saat formülsel tümcelemeler, Divan şiirine mi yoksa benzer? 

Tesla da aynı böyle çalışıyordu, yol yordam aynı.

Yaşlılık zamanlarında böyleydi Arf, 8o’inde coşan Picasso.

Matematikte, karakteristiği 2’den fazla olan kuadratik formlar 

ya da invaryantlar (değişmezler) , de bir şekil, tanımlanmalı.

Alman matematikçi Witt bunu yaptı -E Katerina Witt 

4’lü solyut takla buz danslı attı- Karakteristiği 2 olan cisimler 

üzerindeki kuadratik formları ise sınıflandırmayı sen başardın.

Olayı bir adım daha ileri götürdün. Zordu olay, karakteristik 2 iken,

Erdal İnönü bunu sezmiş olacak ki, elbet cenaze törenindeydi.

Yine öyle gülümsemiştir devamlı kesin, ama olanca üzgün.

Göttingen’de Helmut Hasse, Özel Haller’i çözdün onun önerisiyle:

“Lokal cisimlerde dallanma teorisi” ki çok özel bir yeri 

bunun vardır “sayılar teorisi”nde; buna da katkıda bulundun 

ve dünya math literatürüne geçtin “Hasse-Arf Teoremi” olarak.

Düzlem bir eğri’nin herhangi bir kolunda, çok kat noktaları 

Hesaplanabiliyordu teoride; yıllardan saat 1945’i gösterdiğinde.

Karakterleri bulmak ise zor olanıydı, senin keşfedeceğin; 

Bir eğrinin düzlemleri verildiğinde, bilinmeyen de işte buydu.

Düzlem eğriler için bilinen cevapları, “yüksek boyutlu uzaylar’da 

Bulunan tekil eğriler” e yonttun, ne de güzel yaptın sen.

“Tek boyutlu cebirsel kolların sınıflandırılması” problemini tek

Celsede kapadın kendi aklınla, fikrinle doğrularınla, inancınla.

Önemli senin gördüğün halkalara problemin çözüm aşamasında; 

Yıl 1945, “Arf Halkaları” dendi.”Hasse-Arf teoremi”nde de

Mührünü basmıştın; Invaryantlar’a, o değişmezler’e de …

Zorlanıyorum yaptıklarını algılamakta, Ankara’da olsam da.

Halbuki Tübitak dediğin nedir ki, şuracık ya, belki inerim yarın.

Birkaç kitap bakarım, seyrederim ve sonra satın alacağım.

Kör olası elin kiri(ş) ini yararlı bir iş bilim yarınlara kılacağım …

Bir kitap alabilirim DNA’dan, Francis Crick basım menşeili; 

Küçücük bir kitap ya da kocamanından alırım, ah alacağım –

aşktan kalsın vakit, yeter ki; sevenler asla üzemesin bildiğini.

Einstein’in emeği vardır Avrupa Birliği’ne; senin, Tübitak’a.

Newton olmasa olmazdı o ve Galileo olmasa Isaac olmazdı

Ve böyle gider de gider zaman geriye, merak dünyaya indiğince.

İnsanlar başardıklarıyla ölçülür, en güzelle kal hep sağlıcakta! 

“Yirmi dokuz tane ortaokul açıldI” der misin, dersin, demişsin; 

Sülo Baba, 29 dene üni şeridini kestiğinde muhterem açılışa.

Demirel de sevimli, zararsız adamdır ama sen de haklısın.

Kalifiye elemanlar için, sayıda bolluk anlamsızdır, bunu seçin.

Neden ki böyle, ''En büyük denge bozulması ölüM'' lafı; 

(ikibine doğru, 26 nisan 1992)  pek sen düşünmezdin

Bunu diyeceğini veyahut da ben, bana –incelemeye hak etti.

Ölüm nedir ki, bir enerji olarak ölçülebilir mi, hayat nedir? 

Enerji yaşamdır ki en güzel tolerans dillisin, ayıp etmissin.

Bak, ölüm denge bozulması demişsin, yaşamı buna 

Bence sen yormamışsın, bilirsin denge bozulması o kalmalı.

Yaşayanlara ya da Tanrı’ya yaraşmaz, Azrail’e yakışır.

Birden bakıyorum, yine damardan mı niyetlenmişsin:

''Guzellik,insanda sonsuzluk duygusunu uyandirandiR''

Bunları yaşayarak yaşadığın, olaylara görerek baktığın

Onları, eşyanın tabiatını bilirken göçenlere saygı duyduğun,

Boşevermeden boşvermeyi geçen zamana yıkmadığın belli.

Şaşmayasın(!)  o enerji lafından sonra hayli şaşırttın beni.

Evet sonsuzluk güzelliktir, ve hep güzelliktir sonsuzluk; 

Ve/ fakat hep bir katışıksızlık; sana matematik, ressama

Onun resmi, şaire şiirdeki sevdiceği bla ve bunun gibi …

Işık, korunmayın, boncuk boncuk, sonundaki huzme koru’nun.

İsmet Berkan sormuş ''Cahit Arf neden manşet olmadI? ''

Olmadı da ondan yahu! Aman fazla Şekspirvari oldu bu :) 

Tü tüh, bir deşimdi bir şekispiyerimsi der miyiz, deriz deriz,

Nerde bizim cipsimiz –işte mi bir de T.S. Eliot’ladık (!) …

Of, off, tabi ki manşet olmaz, gündem bilmez, güncel; 

Karadelik koridorlarında tekillik kuyuları, bilmez-sormaz.

Yanar-döner sormaz, bundan da gocunmaz, ve ulaşır ama.

Öldüğünde bile de mi? Vah vah, kim alır, evde kaldı (!) 

Hasan Pulur da aksatmamış, tez cümle olaya vakfen:

(Hafız-felsefeci ki ezberlemiş baştan sona Kuran’ı,

Ama dışa açık beyni kardeşliğe, bunda sevmeyen 

asla ezberi, az Münir Özkul benzeri, dedem gibi,

dedem Hasan Pulur’un köşesinde gezinmeyi severdi) 

''Cumhurbaşkanı Arf''ın cenazesine gitmeliydİ'' di mi? 

Vallaha ne demeli bunun üstüne, pişpirik oynamalı, pışş …

Yahdi uykuya ninniler gelsin devlet makamındakilere! 

Haydi, haydi yehuda, Mehuda, sizler bizler bizli sizli

Sorumluları kim ki? ? ? Amanın artık söz bulamıyorum! ! 

Görüyorum birini, ama neyse, yok hayır neyse:

Birini görüyorum Nikola Tesla gibi, paylaşıyor aynı kaderi.

Ancak sorarsanız bana, valla böyle kalması daha iyii.

Popüler olmasın, kuytuda kalsın, ağzların suyunu akstın.

O kör testiler, BİLİRİZ! Biliriz, ne mendeburdurlar.

CAHİT ARF der ki, ‘zekadan önce sabır niçin gelir ki? ’

Ama o gene ekler ki, ‘evet böyledir, ve bu güzeldir’.

''Dağlara gidelim dağlara, üşüyelim. ben bu yoğunluktan bıktıM'' 

''Matematik de resim, heykel, muzik gibi bir sanattiR''

''En büyük denge bozulması ölüM''. (ikibine doğru, 26 nisan 1992) 

''Guzellik,insanda sonsuzluk duygusunu uyandirandiR''

''Bilimadamı törenlerden hoşlanmaz, 

çünkü törenlerde çok büyük sahtekarlıklar vardıR''

''Bilimadamı törenlerden hoşlanmaz, 

çünkü törenlerde çok büyük sahtekarlıklar vardıR'':

N’demiş emmiş hanimiş(!)  e has etmiş, değil kuru sıkı; 

Sıkıver balkondaki ip cambazı bir çarşafı, yeni yıkandı:

Çıkan sular aşağı dökülsün, kel fodul sepetçi bakkalı ıslatsın.

Bir nem kapan, çıksın sokağa da çırçıplak fırlasın

Arşimet gibi, Hipokrat yemini gibi, Arşidüklük gibi …

Pehh, zamanında köleliği savunmadı mı, savunmadı mı? 

O devirde yaşasa acaba Cahit babamız ne olurdu? 

Düşünmek bile saçmadır bunu, üşenmeye bile! 

Bir Atatürk vardır ki, o yoldan gidenler olur onun gibi! ! 

1943’lük yılı prof’luk senesi, 955’se ordinaryusluk yılı; 

II. Cihan Harbi bittiğinde geldi Cahit Arf’ın keşifler altın çağı.

194o’ta, fakruzaruret yıllarında değil; savaş biterken.

Neden bunu söyledim, öyle de ondan yahu çünkü :) 

Bu ılıman değil, ya da aşar 12 güneşini yazınen azından.

Zorlama hiç değil, ya herru merru, çıkar içinden öyle …

Çiviyle çivi söken, mutlulukla mutluluk kapan, casir! ! ! ***

Cahit Arf der ki, “Okulda diğer çocuklarla oyun 

oynayamadım çünkü utangaçtım..” kılı kırk yardım …

Balkan Savaşı patlak vermişti, ortam böyle bir zamandı; 

İstanbul’a taşınan ailesi Selanik’ten, onu da sürükledi.

Muzdarip olacaktı, çok zorlu bir yaşam geçirecekti.

Bunu biliyor muydu, bilse çok mu sanki fark ederdi? 	

Hem bunu fark edemedi, hem de “hiçbir şey fark etmezdi”.

Dolu geldi, dolu gitti, varolduğu yerde baki kaldı.

Çok kişi fark etmez göğe yükselen soyut heykel büstleri! 

“non mors sed imago mortis anima aeterna”, latince; 

Yokolan çehreyse, sonsuza dek yanımızda ruh kalır! 

“ölur ise ten ölür canlar ölesi degil “ haykırır ve ekler

 her dem yeniden doğarız, bizden kim usanası? '' -

halktan Karac’oğlanı Dedeler Korkut- Yunus Emre de! 

----

*doku(ların)  fıkırdamasal fokurdayışı (rastlantısal türetme) 

Casir: bakir cesaret (türetme) 

PLAN:

İlk bölüm, akılda kalan kaynakçadan derlediklerimle ve tamamen ilhamsal başlanan ki şiirin gelişimi buradan oldu (ikinci bölüme göre, konuya daha temsili genel bi giriş) 

İkinci bölüm, Arf’ın sözleri üzerinde daha çok düşünüp açıklamaya çalışarak..

Üçüncü bölüm, onun hayatıyla alakalıca VE HAYATIYLA İLGİLİ KENDİ LAFLARI. Ayrc. çalışmaları kesitleri.

Dördüncü bölüm, geleceğe dair, ne kadar elimden geldiyse, onun ağzındanvari bazı talepsel öngörüler ve v.s.

SONUÇTA 2 BÖLÜM ÇIKTI ŞİİR. Bİ ÇIRPIDA GELİŞTİ.

İlk bölüm önceden yazdığımdı. 2 bölüm Arf’ın deyişlerini, hayatını v.s. kapsıyor

Çift tırnaklar çoğunlukla onun lafları, iki tanesi ise Hasan Pulur mesela biri…

Ana kaynakçalar diğer sayfada dostlar

Kaynakçaları ekleyeceğim. İlk şekil.

Kısa bir araştırmadan ortaya çıkan..

Nur içinde yat Cahit Arf', '“ Matematik tümevarımsal bir bilimdir ve bu tümevarımsal bilim sonsuz kümeler için geçerli. Bu sonsuzlukları tümevarımsal bir şekilde kavrıy...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":178,"source_url":"https://www.antoloji.com/c-arf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak', 'hak-selim-gul-dw0yu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur bir kere bak gözlerime

Gönlümün gözlerinde

Bir nazar hakkı vardır

Dudak bükme ne olur

Kulak ver sözlerime

İdamlıkların bile

Son bir söz hakkı vardır

Ankara', 'Ne olur bir kere bak gözlerime Gönlümün gözlerinde Bir nazar hakkı vardır Dudak bükme ne olur Kulak ver sözlerime İdamlıkların bile Son bir ...', ARRAY['Türk Edebiyatı','Şiir','Selim Gül']::text[], 8.5, '{"poet":"Selim Gül","poet_slug":"selim-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sıkımlık Hayatımıza', 'bir-sikimlik-hayatimiza-gultekin-mustafa-jmzde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir akşam olur

bir sabah

bir yağmur yağar

bir ayaz

çok kullanılmaktan yorgun düşmemiştir 

bu sokak-ı hayat

yirmi ikinci yaşımda bir aralık sonu

zaten tek bir aralığa sahip yirmi ikinci yaşım

ve zaten bir tek herhangi bir ana sahip

kimin suratında sivilcedir belirsiz

tek sıkımlık hayatım

ve ı’lar aslında noktalı…

akşamlar ve gece

sokak lambaları ve cadde

başka nerede var okşayan bu telaşe

bir zehir kaç zemberek eder

yorgun işçilerin evinde

milyonlar yitiyor her gün

milyonlar yitiriyor her gün

sarı dişleriyle gülüyorlar

giyile giyile eskimiş 

kabirlik kazakları giyiyorlar

sonbahar-kışları ilkbahar ve yazları

yetiştirmek telaşı olmuşsa bu hayat

bazı saatlerde bazı salak esprilere gülüyorsak

ve her akşam televizyon izleyecek kadar salaksak

bir gerekliliği yok ki lan nefes almanın

nedir ulanlar’la sorgulamalıyım ben hayatı

her akşam iyi akşamlar

her sabah aynı lavabo

sabahın kuralı erken kalkmak

ve bir yanlı kural olmadan geldiysek biz dünyaya

gerek duyulan hiçbir yanlı kural 

bizden değildir', 'bir akşam olur bir sabah bir yağmur yağar bir ayaz çok kullanılmaktan yorgun düşmemiştir  bu sokak-ı hayat yirmi ikinci yaşımda bir aralık s...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-sikimlik-hayatimiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-mazlum-unlu-qwyt1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana inandım

Sana güvendim

Biran olsun unutmadım

Ama gel gör ki

Her şey bitti

Akılda ne yaşanılan anılar

Ne de verilen sözler kaldı

Sadece ihanet var

Sadece ben kaldım

Döneceğini bilsem

Düzeleceğini bilsem

Beklerim bir ömür

Usanmadan

Sadece senin için

Ama ne sende gelecek yüz var

Ne de bende sana inanacak güç var 	

Gelme

Arama 

Sorma beni

Düşünme beni', 'Sana inandım Sana güvendim Biran olsun unutmadım Ama gel gör ki Her şey bitti Akılda ne yaşanılan anılar Ne de verilen sözler kaldı Sadece i...', ARRAY['Türk Edebiyatı','Şiir','Mazlum Ünlü']::text[], 8.5, '{"poet":"Mazlum Ünlü","poet_slug":"mazlum-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelme-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündüz tapiri', 'gunduz-tapiri-akin-akca-nqvrb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Gündüz tapirli kış garibinde''ki helal vergi''li hükumet hutbe veda''larında, kuş nezlesi''nde asimetrinin kutsanışı Ve ''yarım Tül Kapı''

Virane bir binaa götürdüler tapiri,

yalanladı kış garibini.

toprağı eşeledi

zindanda, attıkları...

hapishanenin çatısı delindi

bir anda

ve kuş pislendi bir tomruk

hücre gardiyanlarının, 

dışarıda, güzelce:

yani demir

parmaklıkların dışı,

yoksa dört duvarlar-içi,

onların da yerleri yurtları.

Derken kiremitler iyiden

iyiye döküldü

sapır sapır..

tüm bir sarmalayan kubbe,

delindi...

yalapşap ozon deliği; 

seslerde, gacır gucur.

gökyüzü çöktü o virane

yer üzerine birin dördü.

Tahmin bunu edemediler.

Kasıldı, ve açıldı yer yuvar; 

bunu yapmakla

eciş bücüşlere zaman kazandırdı.

edi ile büdü topraktan fırladı

ve bir ece,

yine o voltacılar menşeili kalibrede,

bir hücre içi yaşamaktaydı gene,

kayalıklar üstü patinaj

tarlasından uyanmak üzerli

bir ayıcık, Ankara hayvanat bahçesi.

Tüm mahkumları suya hortumile

tazzikli tutmaya başlayan gardiyanlar; 

bir süre sonra, 

bunla durdurulamayacağını

kanatlıların anladılar -

her kim ''kanatlı..'' dedi...

''bağını sormadı''...

''kubura attı, canlı gömdü'',

''diri diri yaktı''

çukurdan fırlayan tekinin

altından hala ateş gelmekteydi.

bu haliyle,

prematüre bir kuluçka dönemi 

onun geçirdiği düşünülebilirdi.

Bilirdik ama

Kars''taki soğuk hava koşullarında

virüsler pek kolay ölmezmiş.

Üç aya kadar tavuklar,

''HBK DHÇ''* düzenlediler.

Zorunluyken bu artık onlar için.

Kendilerini havaya atıp oynayıp

sevinen çocukları

ve onları eğiten 

babalarını sevdiler.

Ama onları yolup yolup

ve canlı yakanları unutmadılar.

Bir ev babasına; 

bir tavuk, aynen şahit olundu -

Kars''tan bir 

ev babası şöyle diyordu

- ''Evet,

burası cehennem gibi..''

anlamınca bir şeyler...

ama sonra tüm çocukları salmış,

hepsi tavukları mıncıklamaktaydı.

Bahçede havaya atıp tutuyor

çocuklar bilmeden,

neşe içinde.

Diğer bir şehirdeyse,

canlı canlı çıplak ellerli,

yoluyorlar.

Bir ikilem.

Böyle bir toplumsal dizanteri

için bu anı mı beklediniz -

cehaleti sunacak, ortaya...

Sonra tabi ölenler olur,

olan ölen çocuklara olur,

tavuklar bile buna üzülür.

(Nasıl bir yerdeyiz 

anlamadım,

ispanyol günü''ne benzetilebilir; 

boğalar ve matadorlar,

dışarı koru yolunda ölümüne 

koşturan halk''a boğalarla benzer)

Ben Sultanahmete çıkıp

o güvercinel kargaşa 

arasında kol çırpacağım; 

(uçabilirsem şanslıyım,

pek de farklı sanırım değilim)

açık alanda güzel,

sıhhi olur:

evde yer küçük.

muhabbet kuşlarımı alıp

oraya salacağım; 

ama böyle bir vaka 

ortaya çıktı diye

edip paket onları yumrulayıp

piliç şekline koyup

dürüm yemiyorum -

kesip koyunları; 

kuzucukları 

Adile naşit''in kuzucukları

şişe geçirip...

- Aksine dışarı atıp

kurtulmaya da bakmıyorum.

Çarğışan arabalar ve lunapark; 

çırpışıyorlar gaga, kanat; 

ben de oturup izleyeceğim.

Ama astronot eldivenlerini

bu kez gözlerime takacağım,

görmeyeceğim o ateşe atılan

canlı-bilinçli yamyamlığı.

Kafese sığsak ve

/ya da kış garibi olmasak,

ben de belki küçülüp

Alice Harikalar Diyarı gibi

o kafesin içinde

onlara katılabilirdim.

Gündüz tapiri 

yampiri vanpiri,

ağaçtan ağaca sallanışlı

örümcek maymunu.

Büyüyen dişleri ölçüsünce; 

onun azımsanabilir,

mefhumlara, güruhlara

kan isteyiş döngüsü

Koşar, koşar,

dişleri dağ kadar olur:

hiç boğa ölmez,

hiç tavuk ölmez; 

meğer hiç de insan 

ölmemiş, bakarsın, görürsün.

-

*Hayvan birliği komitesi Dünya hayvancılık çiftliği', '''Gündüz tapirli kış garibinde''ki helal vergi''li hükumet hutbe veda''larında, kuş nezlesi''nde asimetrinin kutsanışı Ve ''yarım Tül Kapı'' Virane...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":138,"source_url":"https://www.antoloji.com/gunduz-tapiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Aynası', 'dilek-aynasi-bahri-yildirim-jfzcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

En çok çocukluğumu özlüyorum

Hani körebe oynarken

Hep seni yakalardım ya ilkönce

 Başkalarını görmezdi ya gözüm

Yüreğim sarılırdı ya ellerine

Saklanırdık ya hep aynı köşelere

Birbirimizi bekler gibi

Sen beni bulurdun saklambaçta ilk önce

Ben de seni.

-

Öyle özledim ki çocukluğumu

Özledim,seni çocuklar gibi sevmeyi

Çocukça beklemeyi

Çocukça gülümsemeyi

Çocukça riyasız sevmeyi..

-

Şimdi iki yüzlüler sardı çevremizi

Sensiz tadı yok sevmelerin

Boynu bükük,sensiz  gülümsemelerin 

Tadı kalmamış hiç bir şeyin

Seninile gitmiş tüm tatlar sanki

Bırakıp  gidince,darda beni.

-

Şimdi; sadece köşekapmaca oynanıyor

Sen dolu sokaklarda.

Biliyor musun? 

Oyunlar bile değişmiş sen gibi

Her tarafta ekmek kavgası

Köşe başlarında korkular cirit atıyor

Yollarda korku,sokakta korku,

Yüreğimde korku

Kaybedecek  hiç bir şeyim kalmamış

Senden başka,

Sensizlikten ötesi,çıkmaz sokakmış hayatın

Anladım ki sensizlikten öteye yol yok

Sokakların  ıssız oluşu bundan

-

Bu korkudan olsa gerek

Seni  bırakıp

Sokağa bile çıkamıyorum sensiz

-

Şİmdi kötü zamana kalmışız

Şimdi zifiri karanlık her yanımız

Sensiz zindan bir yanı, o eski sokakların

Ben de   sana sığınıp vazgeçtim

Artık körebe bile oynamıyorum

Saklambacı yasakladım yüreğime

-

Sadece; 

Misket vurgunu yüreğimden vazgeçmedim

Sensin diye sahibi,kimselere vermedim

İşte bu yüzden,sadece seni sevdiğim için

Çocuk olabilmeyi çok özlüyorum,biliyor musun? 

Ama elimden de bir şey gelmiyor ya hani

Aslında,sensiz büyümek,haram olmalıydı

Büyüdük işte,elimizde olmadan

Ama ben halâ,o günkü çocukluğumla

Geçiyorum o eski sokaklardan

Seni, çocukluğum gibi seviyorum

Yaşımız dayandı 45''e

Oyun bitti,biliyorum.

Ama,seni hala seviyorum', 'Biliyor musun?  En çok çocukluğumu özlüyorum Hani körebe oynarken Hep seni yakalardım ya ilkönce  Başkalarını görmezdi ya gözüm Yüreğim sarı...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/dilek-aynasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Af', 'af-selim-gul-fs3q9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili kardeşim usta şair Celaleddin Dinç''le olan atışmamdır

Celaleddin:

Müstehak sandım kendimi

İstirham ettim affını

Bilmezdim

Allah''ın senden aldığını

Affetme vasfını

Selim:

Af şahı Allah''a mahsus

Müstesna bir güzeldir

Abd-i acizin affı

Sadece bir gazeldir', 'Sevgili kardeşim usta şair Celaleddin Dinç''le olan atışmamdır Celaleddin: Müstehak sandım kendimi İstirham ettim affını Bilmezdim Allah''ın s...', ARRAY['Türk Edebiyatı','Şiir','Selim Gül']::text[], 8.5, '{"poet":"Selim Gül","poet_slug":"selim-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/af-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut elimden gidelim', 'tut-elimden-gidelim-ozer-akdemir-dwm8o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tut elimden gidelim

Upuzun yollara dönelim yüzümüzü

Yürüyelim... yürüyelim...

Mevsim bahar üstelik

Mevsim göç mevsimi iki gözüm

Mevsim dönme vakti sılaya

Tut elimden gidelim

Bir başkadır bizim oralar şimdi

Gece toprak kokuyodur

Gece süt gibi beyaz

Gizli sevda gibi gece

Tut elimden gidelim

Bu zindan 

Kalsın nemli duvarlarıyla

Bu ayrılık, 

           bu yalnızlık, 

                   bu özlem

Tut elimden gidelim

Ko ma bir başıma beni

Ben ki

Sütten kesilmemiş bebek gibi

Muhtacım gülüşüne

ulucanlar/1994', 'Tut elimden gidelim Upuzun yollara dönelim yüzümüzü Yürüyelim... yürüyelim... Mevsim bahar üstelik Mevsim göç mevsimi iki gözüm Mevsim dönme...', ARRAY['Türk Edebiyatı','Şiir','Özer Akdemir']::text[], 8.5, '{"poet":"Özer Akdemir","poet_slug":"ozer-akdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tut-elimden-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Anaya Ağıt', 'gurbetten-anaya-agit-latif-oz-iklxu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bayram da bekleme 

Gelemem garip anam

Akan gözyaşlarını

Silemem garip anam

Aklımı sana taktım

Sıla yoluna baktım

Hayat yükünden bıktım

Ölemem garip anam

Umudumu bağladım

Yaralarım dağladım

Gurbette hep ağladım

Gülemem garip anam

Yüzündeki aklığı

Duygundaki paklığı

Kimsede sıcaklığı

Bulamam garip anam

Geçen günler hep kıştır

Sıla bana bir düştür

Şu gurbetlik ne iştir

Bilemem garip anam

Zayıf düştüm tel gibi

Uçup giden tül gibi

Gurbet elde gül gibi

Solamam garip anam

Geçti gençlik yaşlarım

Çatık çatık kaşlarım

Bak ağarmış saçlarım

Yolamam garip anam

Ben bilirim hasreti

Çeke çeke mihneti

Kimselere gurbeti

Dilemem garip anam

Latif bülbül dili mi

Esen hazan yeli mi

Bağda solan gülümü

Sulamam garip anam', 'Bu bayram da bekleme  Gelemem garip anam Akan gözyaşlarını Silemem garip anam Aklımı sana taktım Sıla yoluna baktım Hayat yükünden bıktım Öl...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gurbetten-anaya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serenat', 'serenat-mehmet-atalay-32vvh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SERENAT

Gözlerinden başlayan,aşkın ayak sesleri

Bir ılık bûse gibi,iner dudaklarından

Bir Ekim akşamında,tanırken gözlerini

Bağlandım sözlerine,girdin şakaklarımdan

Gözlerinden başlayan,aşkın ayak sesleri

Bir ılık bûse gibi,iner dudaklarından

Üveyik kanadından,saçına bir tüy düştü

Sonra titredin birden,içinden koptu bir yan

Sanki kara kediler,rüyamızı bölüştü

Sımsıcak damlalarla,öylece kaldık giryân

Üveyik kanadından,saçına bir tüy düştü

Sonra titredin birden,içinden koptu bir yan

Lâcivert hayallere,uzanırken el ele

Efsâne anlatırdık,Kafdağı’nın ardından

Efsûnlu bir gergefe,işlenen beyaz güle

Ejderhâ nakşederdik,ağzından alev saçan

Lâcivert hayallere,uzanırken el ele

Efsâne anlatırdık,Kafdağı’nın ardından

Ellerimiz uzanır,titreyen yapraklara

Neşelenir gülerdik,geçerken sokaklardan

Nergis çiçeklerinden,taç yapar çocuklara

Nasıl olur bilmezdik,koşup arkalarından

Ellerimiz uzanır,titreyen yapraklara

Neşelenir gülerdik,geçerken sokaklardan

Rengârenk bir hülyâda,buluşurken arzumuz

İplik iplik uçardı,düşte ipeksi kardan

İlhâm alır rüzgârdan,coşkunlaşan ruhumuz

İnfirâk duyguları,uzaklaşırdı yardan

Rengârenk bir hülyada,buluşurken arzumuz

İplik iplik uçardı,düşte ipeksi kardan

Kaderimiz yürürken,mutluluk menzîline

Sâkîler aşk sunardı,kadehleri billûrdan

Seneler senle geçer,ayrılıklar yerine

Sevimli akislerle,donanırdık bir nûrdan

Kaderimiz yürürken,mutluluk menzîline

Sâkîler aşk sunardı,kadehleri billûrdan

Itırlı saçlarının,telleriyle as beni

Ellerimden tutarak,geçir aşk denen kordan

Ezelî hançerlerle,çıkar ruhumdan teni

Ebedî âlemlere,sonra al beni buradan

Itırlı saçlarının,telleriyle as beni

Ellerimden tutarak,geçir aşk denen kordan

Leylâ ol bu mecnûna,büyük insanlığına

Vakti yaklaşıyor,duy! Sesler var uzaklardan

Vâhanla can ver bana,doğayım varlığınla

Vâsıl ol artık cânâ,bıktım ayrılıklardan

Leylâ ol bu mecnûna büyük insanlığınla

Vakti yaklaşıyor,duy! Sesler var uzaklardan

Istırap çiçekleri kuşattı,her yanımı

İçimi dolduruyor,bir alev alçaklardan

İçiyor yarasalar,damla damla kanımı

İştahla didikliyor,büyüttüğüm aşklardan

Istırap çiçekleri.kuşattı her yanımı

İçimi dolduruyor,bir alev alçaklardan

Çıkarmadım hiçbir an,gözümden gözlerini

Yâsemen çiçekleri,yetirdim bir bahârdan

Ye’sin ufuklarında,kaçırdım son treni

Yâdigar olsun sana,yâkutin yaşlarımdan

Çıkarmadım hiçbir an,gözümden gözlerini

Yâsemen çiçekleri,yetirdim bir bahârdan

Elmas bakışlarınla,yeniden gir dünyama

Okyanus diplerinden,o masmavi sulardan

Oynaşan mercanlardan,bir inci getir bana

Olmazsa olmazımsın,kutsanmış yağmurlardan

Elmas bakışlarınla,yeniden gir dünyama

Okyanus diplerinden,o masmavi sulardan

Rüzgârlar koparmadan,sevdamı yaprak yaprak

Rikkatli sözcüklerle,kurtar uçurumlardan

Rehgüzâr ol,rehber ol; çıkar karanlıklardan

Revâ değil bu aşka,bir avuç kara toprak

Rüzgârlar koparmadan,sevdamı yaprak yaprak

Rikkatli sözcüklerle,kurtar uçurumlardan

İşit feryatlarını,yetiş imdatlarına

Uçan turnalar bile,söylüyor yedi kattan

Uzleti bitir artık,arşın seyyadlarına

Uçar mı hiç bülbüller,vurulunca kanattan

İşit feryatlarını,yetiş imdatlarına

Uçan turnalar bile,söylüyor yedi kattan

Muhabbetin zamanı,bak geldi ve geçiyor

Mâşukum ol,cânım ol; bakma öyle uzaktan

Mâtemle açan güller,ruhumdan kan içiyor

Mağrûrluğu at artık,kurtul o zor tuzaktan

Muhabbetin zamanı,bak geldi ve geçiyor

Mâşukum ol,cânım ol; bakma öyle uzaktan

                   MEHMET ATALAY

    GAZİANTEP ÜNİVERSİTESİ T.D.E

                    4.SINIF', 'SERENAT Gözlerinden başlayan,aşkın ayak sesleri Bir ılık bûse gibi,iner dudaklarından Bir Ekim akşamında,tanırken gözlerini Bağlandım sözler...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Atalay']::text[], 8.5, '{"poet":"Mehmet Atalay","poet_slug":"mehmet-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/serenat-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha ne olsun!', 'daha-ne-olsun-mustafa-murat-aydogdu-fn06k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her kışın baharı var deme bana

Mevsim hep kış olsun,çiçekler solsun

Daha kötüsü var diyorsun ama

Ben seni yitirdim; Daha ne olsun!', 'Her kışın baharı var deme bana Mevsim hep kış olsun,çiçekler solsun Daha kötüsü var diyorsun ama Ben seni yitirdim; Daha ne olsun!...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/daha-ne-olsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karga İle Eş İnsan', 'karga-i-le-es-i-nsan-seyfet-bozcali-wir81', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevlam bana altmış yıl ömür vermiş,

Kargayada bu kadar layık görmüş,

Akıl servetini hesaba katmaz,

Kargayla ölçülür bu aptal insan...

Karga çöplüklerden karnın doyurur,

Dünya nimetleri hep senin olur,

Vahşi aslan bile bir kedi olur,

Onun terbiyesini verirse insan...

Kargayı eş gören, karga zihinli,

Kalbi katılaşmış çürük beyinli,

Hakkı Hakikati görmezden gelir,

Kör, sağır yaşarsa zavallı insan...

Mevlam seni melekten üstün kıldı,

Hakikatı görmen için göz verdi,

Akıl verdi, beyin verdi, el verdi,

Bunu nasıl inkar eder o insan...

Yaşamın kargadan farklımı senin,

Leşler gibi kokar meyhane yerin,

Çöplük kokar ağzın, uyuşmuş beynin,

Toplumun gözünde necis o insan...

Ne yapıp yap Rabbin''e hiç eş koşma,

Gel tövbe et, hakkın yolundan şaşma,

Karga gibi çöplükleri dolaşma,

Sonu çöplük olur be aptal insan...

Karga misali ile haklıyım sanma,

Onun kadar bilen mevlayı anma,

Bunca yaratığı başı boş sanma,

Her şey ona döner bil zalim insan...

Karga beyinliye bu kadar yeter,

Çok yüklenme sıkışır gaga atar,

Seyfet der düşünen insana yeter,

Akıl yoksa beyni ne yapsın insan...', 'Mevlam bana altmış yıl ömür vermiş, Kargayada bu kadar layık görmüş, Akıl servetini hesaba katmaz, Kargayla ölçülür bu aptal insan... Karga ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karga-ile-es-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Azerbeycan', 'can-azerbeycan-seyfet-bozcali-am32u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özgürlük uğruna çok canlar verdin,

Yetmiş yılın heba can Azerbeycan,

Soğunda bağımsız bir devlet oldun,

Geçmişine inan kan Azerbeycan...

Ayrılma sevincin uzun sürmedi,

Ermeni baskısı fırsat vermedi,

Çoluğun çocuğun bir gün görmedi,

Sokakların ceset, kan Azerbeycan...

Karabağ''dan insanların kovuldu,

Horlandı, dövüldü, yolda soyuldu,

Dağlar, bataklıklar meskenin oldu,

Pilan Rüsya''nın dır bil Azerbeycan...

Dostlarını dost bil, düşmandan çekin,

Zulümün sonu yok kurtuluş yakın,

Kuvvet birliktedir, aldanma sakın,

Aman parçalanma gel Azerbeycan...

Dünya savaşında nasıl direndik,

Özgürlük uğruna hep birlik olduk,

Düşmandan bu yurdu nasıl kurtardık,

Türkiye yi örnek al Azerbeycan...

Toplu katliyamlar bağrında acı,

Sizler için ağlar ana ve bacı,

Ermeni vahşeti içinde sancı,

Geleceğe sahip ol  Azerbeycan...

Seyfet der andıkça kanım kaynıyor,

Dost akraba birbirini tanıyor,

Rusya geri döneceğin sanıyor,

Özgürlük yolunda kal Azerbeycan...', 'Özgürlük uğruna çok canlar verdin, Yetmiş yılın heba can Azerbeycan, Soğunda bağımsız bir devlet oldun, Geçmişine inan kan Azerbeycan... Ayr...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/can-azerbeycan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiR ASKER AĞLIYOR', 'bir-asker-agliyor-ahmet-eroglu-0e3r5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava yağmurlu tüfek omzunda 

Her yanı ıslanmış nöbet başında 

Seni düşünüyor hayalin karşında 

Bir asker ağlıyor nöbet başında 

Parke üstünde bere başında 

Ne sırlar gizliyor her göz yaşında 

Belli ki çok üşüyor sabahın soğuğunda 

Bir asker ağlıyor nöbet başında 

Yaşı ilerlemiş aklı başında 

Fakat çilesi bitmemiş asker ocağında 

Neler çektiği anlaşılıyor her hıçkırığında 

Bir asker ağlıyor nöbet başında

*İlk Şiirim olması nedeniyle bende özeldir.', 'Hava yağmurlu tüfek omzunda  Her yanı ıslanmış nöbet başında  Seni düşünüyor hayalin karşında  Bir asker ağlıyor nöbet başında  Parke üstünd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Eroğlu']::text[], 8.5, '{"poet":"Ahmet Eroğlu","poet_slug":"ahmet-eroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-asker-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Var Ki', 'i-nsan-var-ki-seyfet-bozcali-h5cw6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan var ki haline şükür eder,

İnsan var ki inanır inkar eder,

İnsan varki her daim zikir eder,

İnsan varki gönlümüzde kalkandır...

İnsan varki Dünya''yı baki bilir,

İnsan varki servetiyle övünür,

İnsan varki Hak yolunda can verir,

İnsan varki tüm aleme örnektir...

İnsan varki isyanı gurur bilir,

İnsan varki riyasıyla tanınır,

İnsan varki Şeytan ı rehber bilir,

İnsan varki sultanlara sultandır...

İnsan varki fitne, fesat çıkarır,

İnsan varki her an Rabbe yakarır,

İnsan varki şükrünü kalkan bilir,

İnsan varki tüm aleme önderdir....

İnsan varki Kuran-ı rehber bilir,

İnsan varki Resul-ü örnek alır,

İnsan varki nefsiyle dost olur,

İnsan varki Şeytan dan da Şeytandır...

İnsan varki gönlü arş-ı Rahman''dır,

İnsan varki dilsiz lakin şeytandır,

İnsan varki gönüllere sultandır,

İnsan varki hayvandan da hayvandır...', 'İnsan var ki haline şükür eder, İnsan var ki inanır inkar eder, İnsan varki her daim zikir eder, İnsan varki gönlümüzde kalkandır... İnsan v...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insan-var-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-seyfet-bozcali-gqg2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alçak gönüllü ol, hor bakma bana,

Doğru yolda yürü, yanarsın nara,

Güvenme servete, güvenme mala,

İşsiz, dostsuz bırakır seni gurur...

Hep yüksekten uçar, alayla bakar,

Yoksulun, yetimin kalbini yıkar,

Yaşamı boyunca zalimlik eder,

Merhamet bırakmaz insanda gurur...

Gururlu olanı sevmez yaratan,

Odur tüm canlıyı yoktan var eden,

İman ihlas ile ibadet eden,

Allah''ın yolunda saptırır gurur...

Yoksului, mazlumu gel hakir görme,

Dünya malı için kafanı yorma,

Kendine ideal kişiyim deme,

Yarı yolda koyar batırır gurur...

Gurur sanki bir insanda güçtür,

Gururla yaşayan insan bir hiçtir,

Aleme gülenin kendi gülünçtür,

Kişiti toplumdan soğutur gurur...

Öğretmen Seyfet der sevmem gururu,

Sevip, sayılmakta buldum ömürü,

Zayıf insanlara verdirir emiri,

Bitmez bir hastalık gibidir gurur...', 'Alçak gönüllü ol, hor bakma bana, Doğru yolda yürü, yanarsın nara, Güvenme servete, güvenme mala, İşsiz, dostsuz bırakır seni gurur... Hep y...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurur-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Dilek Tut Ben Sana Her Gün Yeni Bir Aşk Sunacağım', 'mutlulugu-dilek-tut-ben-sana-her-gun-yeni-bir-ask-sunacagim-kamil-aydemir-r0z3l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu ilk değil

geceleri gökyüzünden yıldız düşürüşüm

cimri hayatın göbeğine inadına koşuşum

memleketim gibi berbat halime gülüşüm

sessiz çığlık susuşum

ama bu ilk

çorak yüreğimde aşk büyütüşüm

ne zaman ayağım ilişse bir hüzüne

yüzünde gelinlik gibi duran

eşsiz gülüşlerine tutunacağım

ve ben her sabah sana yeni bir aşk sunacağım

böylece aşkımızı eskimekten kurtaracağım

dilek mutluluğu tut

verdiğim gülleri koynunda kurut

ay kadar yalnızım sensiz

göçebe hayatlarda yormuşum

çok kahırımı çeken şu yüreğimi

söyle suçlumuyum kalbimin çiçeği

gönlüne ektiysem sevgimi

şimdi büyümesini bekliyorum

her yeni gün yeni bir umut

ne olursun ben(i)   sol(dur)  madan 

sevgimi büyüt

istersen kalbimi sök al yerinden

içimdeki yangının külleridir

günlerin gözlerinden dökülen

hayat aç kedi

ben sensiz

o kedinin dişlerinde kanayan serçeyim

yarınlarımı sensiz bırakman daha berbat ölümden

aşkça bilmen gerek

anlaman için dilimden

sevmeyi de öğreneceksin sevgimden

hep acılara randevulu olsa da hayat

acıların gönlünü hoş etmek zorunda değil ki aşkta

mutluluk çiçeği açmaz ki

gözlerden akan yaşta

kıydıkça bana

içimdeki türküleri boğuyorsun

hüzünlü bir aşkın öyküsünü mü yazıyorsun

yurtsuzların yurdu alnıma

 acımıyorsan bana kendinede mi acımıyorsun

yarınlarına da kıyıyorsun

belkide doğum sancılarıdır

ç e k t i (r d i)   ğ i n

çünkü sevdamda yeniden doğuyorsun

sen ki

acılara hanlık

hüzünlere hamallık etmişsin bunca yıl

mutluluğu dilek tut

ben sana her gün yeni bir aşk sunacağım

ve mutluluğumu mutluluğunda bulacağım', 'bu ilk değil geceleri gökyüzünden yıldız düşürüşüm cimri hayatın göbeğine inadına koşuşum memleketim gibi berbat halime gülüşüm sessiz çığlı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/mutlulugu-dilek-tut-ben-sana-her-gun-yeni-bir-ask-sunacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama göz bebeğim', 'aglama-goz-bebegim-mine-yirmili-dhrc8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ağlama göz bebeğim,

Kıyamaz Anacığın sana... 

Şimdi mail - ini okudum da; 

Değil sana bir şiir,

Bu can feda... 

Kızarmasıyla bile içimin acıdığı; 

Gözlerininin akıttığı yaşa; 

Dayanır mı bu yürek...bu Ana... 

Bir daha... bir daha...

Duyarsam ağladığını,

Yok,sana...yok, sana; 

Şiir miir,yok,sana! ..

Söz verirsen bana; 

Bak ne şiirler gelir sana... 

Bir ay''ı bitirdin ya, 

Kaldı ondört ay, 

Hadi al gel tezkereyi; 

Alem görsün kız istemeyi...

Füsun''u ve seni bilmem ama, 

Sabrım kalmadı benim daha... 

Yapalım artık düğününüzü, 

2007 '' nin baharına 

21 ARALIK 2005 sa:01:55', 'Sen ağlama göz bebeğim, Kıyamaz Anacığın sana...  Şimdi mail - ini okudum da;  Değil sana bir şiir, Bu can feda...  Kızarmasıyla bile içimin...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aglama-goz-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosna - Hersek Yanıyor', 'bosna-hersek-yaniyor-seyfet-bozcali-6255l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yirmi iki ay süren, top altında bir yaşam,

Pazar yerinde vahşet, pazar yeri doldu kan,

Sokaklar doldu ceset, ana, baba, kız, oğlan,

Cani Sırp zulmü ile Bosna-Hersek yanıyor...

Allah''a iman eden, bu vahşete dayanmaz,

Bunlar çok kalın kafa tarihten hiç ders almaz,

Türk özgürlük simgesi, ölürde esir olmaz,

İçerim kan ağlarken, Bosna-Hersek yanıyor...

Yanmakla toprak bitmez, tamir edilir vatan,

İkiyüzbin can verdi dahada verilir can,

Vatan''a feda olsun genç, ihtiyar, kız, kızan,

Avrupa''nın bağrında Bosna-Hersek yanıyor...

Her şeyini kaybetmiş anaların feryadı,

Kırılmış kol, kanadı yok dizinde takatı,

Sırp Hırvattan yedi tokatı birde dünya tokatı,

Çığlıklar arşa çıktı Bosna-Hersek yanıyor...

Aç ve perişan halde, kamplarda can verdiler,

Hedef diye vurulup fırında yakıldılar,

Anne karnında bile süngülerle öldüler,

Bosnalı can verirken Bosna-Hersek yanıyor...

Kalpleri hüzün dolu sofrasında göz yaşı,

Yastık yaş, yorganı kar, silahtır arkadaşı,

Yokluğa yenik düşmez, daima diktir başı,

Soydaşım ayaktadır Bosna-Hersek yanıyor...

Koparmak istiyorlar tarihten geçmişinden,

Kuşlar korkup uçmuyor Bosna''nın üstünden,

Kulaklar dile geldi Sırp topunun sesinden,

Dünya seyir ederken, Bosna-Hersek yanıyor...

Gösterdi bir çok kanal Sırp zulmünü,

Davaya sahip çıktı, açtı yardım elini,

Ekranlarda gösterdi cani Sırpın yüzünü,

Evlerde iş yerlerinde Bosna-Hersek yanıyor...

Aklımda fikrimesin gönlümüzdesin herzaman,

Tüm yokluklar içinde savaşan ey kahraman,

Sizde bu inanç varken sırpların sonu hüsran,

Gönüller kan ağlarken Bosna-Hersek yanıyor...

Bir ağaç gövdesiyiz biz ayıramazlar bizi,

Hangi dal hasar görse bilki ordadır sızı,

Öğretmen Seyfet yazdı işte vahşetin yüzü,

Kalemimin ucunda Bosna-Hersek yanıyor...', 'Yirmi iki ay süren, top altında bir yaşam, Pazar yerinde vahşet, pazar yeri doldu kan, Sokaklar doldu ceset, ana, baba, kız, oğlan, Cani Sır...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bosna-hersek-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Askerine', 'turk-askerine-seyfet-bozcali-62sop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Atasından miras kutsal vatanı,

Yurdunu koruyan Türk askeridir,

Hayinler giremez aziz toprağa,

Bir sel gibidir taşan Türk askeridir...

Geçmişinden almış gücün özünü,

Tarihinden almış akan hızını,

Düşmandan ayırmaz her an gözünü,

Radar gibi gören türk askeridir...

Tek bir yürek olur, kaderde yasta,

Saldırı duyarsa doğrulur hasta,

İzmir, Erzurum''da, Kars''ta, Sivas''ta 

Sınırlarda çoşar Türk askeri...

Bilen gafil girmez onun yurduna,

Girmek isteyende düşer ağına,

Canın verir bir tek taşına,

Aslan gibi olan Türk askeridir...

Mehmetçik pusuda her an her yerde,

Dalgalanır bayrak burçta, gönderde,

Ülkesi uğrunda, toprak uğrunda,

Şehit düşen, ölen Türk askeridir.

Düşmanını hep bırakmış gölgede,

Adını andırır pek çok ülkede,

Yurdun dört yanında Çanakkale''de,

Destanları yazan Türk askeridir...

Kulak verin Bozçalı''nın sözüne,

Dört elle sarılın Hakkın özüne,

Vatanına göz koyanın gözüne,

Bir ok gibi batan Türk askeridir...', 'Atasından miras kutsal vatanı, Yurdunu koruyan Türk askeridir, Hayinler giremez aziz toprağa, Bir sel gibidir taşan Türk askeridir... Geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/turk-askerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Olursa', 'sevgi-olursa-seyfet-bozcali-bn0r5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi dediğimiz görülmez güçtür,

Eğer birde karşılıklı olursa,

Sevgisiz yaşanan yaşantı hiçtir,

Sevilmeden seven sevgi olursa...

Sevgi bir çiçektir, bilgiyle açan,

Bir ışık gibidir etrafa saçan,

Özgür bir kuş gibi göklere uçan,

Aydınlatan gerçek sevgi olursa...

Sonsuza uzanan bir el gibidir,

Yatağından taşan bir sel gibidir,

Tenleri okşayan bir yel gibidir,

Sarıp, okşar gerçek sevgi olursa...

Bülbül öter gül üstünde sevgiyle,

İnsan yaşar, ten içinde sevgiyle,

Çiçek açar, kuşlar uçar sevgiyle,

Bakıp okşar gerçek sevgi olursa...

Gerçek sevgi mutlu eder insanı,

Yaklaştırır o insana insanı,

Hiç arayıp sormaz dini, lisanı,

Karşılıklı seven sevgi olursa...', 'Sevgi dediğimiz görülmez güçtür, Eğer birde karşılıklı olursa, Sevgisiz yaşanan yaşantı hiçtir, Sevilmeden seven sevgi olursa... Sevgi bir ç...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgi-olursa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin..', 'sen-benimsin-nurdane-diken-o00hb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benimsin, herşeyimsin.

Her gün doğan güneşimsin.

Islandığım, yağmurumsun.

İçimde kor bir ateşsin..

Sen olmazsan, hayat olmaz.

Bahçemdeki güller açmaz.

Kurt kuzuyla barışamaz.

Sevgi yolu aşka çıkmaz..

Hayatımın neşesisin.

Aşkımın bir feryadısın.

Dostluğun hep merkezisin.

Sen bir tane sevgilimsin...', 'Sen benimsin, herşeyimsin. Her gün doğan güneşimsin. Islandığım, yağmurumsun. İçimde kor bir ateşsin.. Sen olmazsan, hayat olmaz. Bahçemdeki...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-benimsin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-ayse-hazal-beytas-sc7e3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bitiyor gün, 

Yine sensiz bitiyor saatler

Ve sensiz 

Ben bitiyorum....', 'Yine sensiz bitiyor gün,  Yine sensiz bitiyor saatler Ve sensiz  Ben bitiyorum.......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumun bayramları', 'cocuklugumun-bayramlari-mine-yirmili-275ue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdiki bayramlar, 

Hiç benzemiyorlar, 

Çocukluğumdaki bayramlara. 

Ne komşu teyzelerin ellerini öpmeler, 

Nede köşeleri çiçekli, 

Kar beyazı mendiller. 

Harçlık beklemezdim ben, 

Sadece hayallerimdi,beklentim, 

Kolleksiyonuma ekleyeceğim, 

Bir önceki yıldan farklı, 

Köşeleri işlenmiş,çiçekli, 

Kar beyazı mendiller...

Söylesem inanırmısınız? 

Hala saklıyorum o günlerin hayallerini...

Köşeleri çiçekli,kar beyazı mendilleri.

Şimdi ben oldum,komşu teyze, 

Hazırlıyorum mendilleri, 

Bekliyorum, gelecekler diye, 

Geliyorlarda, nitekim, 

Öpüyorlarda,ellerimi. 

Ama hiç zannetmiyorum. 

Hayalleri ve beklentileri, 

Değil asla benim, 

Çocukluğumdaki gibi...

Mine YİRMİLİ        KASIM 2005 

Ramazan  bayramı arefesi', 'Şimdiki bayramlar,  Hiç benzemiyorlar,  Çocukluğumdaki bayramlara.  Ne komşu teyzelerin ellerini öpmeler,  Nede köşeleri çiçekli,  Kar beyaz...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cocuklugumun-bayramlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram bahane', 'bayram-bahane-orhan-kutlu-l0slh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum ardımdasın

Gölgelerin içinden süzmektesin beni.

Bir gözlerimde kaldı yüzün

Dün anakart yanmış makinede

Tüm yazdıklarını ve almış gitmiş

Bende ki tüm resmini.

Senin tabirinle stv

Bir sır kapısı değilmi küçüğüm.

Yarın bayram arifesi,

Şİmdiden başladı herkeste

Bir bayram telaşı.

Kimi kurbanlık almada

Kimileri bayramlık elbise

Ayakkabı  çocuklarına.

Beni sorma

Gittikçe çoğalmakta içimde

Ayrılığın ateşi.

Bir kaç gündür

Güneşliydi İstanbulda havalar

Ama bayramda kar yağacak

Diyor hava tahminlerinde.

Ne de olsa ocak ayındayız

İkibinaltının 

Beklenmeli artık etkisi karakışın

Binlerce karakış koydu gönlüme

Anlamsız gidişin.

Biiyorum küçüğüm

Bilemediğim sebeplerin var

Nedenlerin nasılların gizli

Anlatamadığın.

Öyle bir zincirle bağlıki ayaklarım

Çok isteyipte peşinden koşmayı

Bırak koşmayı

Öyle bir durum ki

Bir adım bile atamadığın.

Bilmiyorum şu anda ne yapıyorsun

Nerdeyse gün ortası

Az sonra alışverişe çıkacaksın belki

Her zaman yaptığın gibi.

Şarkılar dinleyecek

Sevdiğin programları izleyeceksin biliyorum.

Biliyorum

Bu aşk bitti

Öyle imkansız bir aşktıki ağlayamıyorum bile

Ağlamak gözlerden yaş düşürmek ise.

Yüreğimin sızısı

Her vuruşunda göğsümü parçalayan isyanı

Ne demekse artık.

Sana dediğim gibi küçüğüm

Seni hep sevdim

hala da seviyorum.

Son bir kez bahane edip bayramı

Bayramını kutlarken

Özlemle, aşkla

Küçüğüm

Her yerinden öpüyorum.', 'Biliyorum ardımdasın Gölgelerin içinden süzmektesin beni. Bir gözlerimde kaldı yüzün Dün anakart yanmış makinede Tüm yazdıklarını ve almış g...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bayram-bahane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Ya', 'varsin-ya-ayse-hazal-beytas-dxdg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok uzak memeleketlerin birinde de olsan, 

Varsın en azından.

Yüreğim, yüreğinden teğet geçiyor

Sevdalara ilişmeden.

Ellerini tutamazsam,

Gözlerine bakamazsam ne çıkar

Varsın ya..

Aramızda okyanuslar dalgalansa da

Aynı yerküredeyiz en azından.

Sen dünyanın bir ucunda, 

Ben diğer ucunda....

Buda yeter varsın ya', 'Çok uzak memeleketlerin birinde de olsan,  Varsın en azından. Yüreğim, yüreğinden teğet geçiyor Sevdalara ilişmeden. Ellerini tutamazsam, Gö...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varsin-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver', 'bos-ver-tacettin-karagoz-n910d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimler mi şaşkın

Ben mi şaşırdım.

Ne ekin zamanım belli,

Ne de hasat zamanım,

Sevdam ekin oldu

Ürkek yüreğimse Orak

En acımasız patozlarda

Öğüttüm onu

Boş verin toplayamazsınız.

O çoktan samana karıştı,

Çoktan

Ne yapsanız nafile....', 'Mevsimler mi şaşkın Ben mi şaşırdım. Ne ekin zamanım belli, Ne de hasat zamanım, Sevdam ekin oldu Ürkek yüreğimse Orak En acımasız patozlard...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Karagöz']::text[], 8.5, '{"poet":"Tacettin Karagöz","poet_slug":"tacettin-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bos-ver-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihayet O Gözler Del''etti Beni', 'nihayet-o-gozler-del-etti-beni-zek-i-budak-iu0zj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nihayet o gözler del''etti beni

Yaşadığım dünya gayri dar bana

Seviyor sanmıştım aldattı beni

İçerim yanıyor n''eder kar bana

Kim nasıl bilirse beni söylesin

Gönül uslan gayri neden böylesin

Kalpteki yaraya tabip n''eylesin

Yaralarım için ilâç yâr bana

Bütün dünya gülse de ben gülemem

Bunu böyle eden kimdir bilemem

İnim inim inlesem de ölemem

Daha çekilecek çile var bana

Neyim beğenmedi başı boş muyum

Başlar yaran bir zalimce taş mıyım

Kör müyüm topal mı ya da keş miyim

Yârimi kaçırdım elden ar bana

Zekâi''yim bir güzele kul oldum

Sevdirmedi kendisini del''oldum

Bu dünyada yandım yandım kül oldum

Ahirette daha n''eyler nâr bana

(Edirne - 1973)', 'Nihayet o gözler del''etti beni Yaşadığım dünya gayri dar bana Seviyor sanmıştım aldattı beni İçerim yanıyor n''eder kar bana Kim nasıl bilirs...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nihayet-o-gozler-del-etti-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'merhametİ...', 'merhameti-akin-akca-9mix7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'merhameti kötüye çıkarmanın günahını

ödeyebilecek şey nedir...

O gün bankaya bilhassa gitmedim,

sanırım bundandır

canım kahve çekebilir,

güzel giyinmişleri görünce.

bu anlaşılmazları kavramak 

için su bile yeter -sınamak:

Ölüme sunmayan bir koza bu,

ihraç olandır da buna nefesimiz.

Kendi olmak, doğmak değil; 

bir olay karşısında tavır sergilemektir.

Yeterince cesur edilmek,

direnmektir yiğitliğin aslına.

doğmak bakidir asıl böyle,

bulabilirsen aksini bana söyle,

faydalanırım da her gidişte.', 'merhameti kötüye çıkarmanın günahını ödeyebilecek şey nedir... O gün bankaya bilhassa gitmedim, sanırım bundandır canım kahve çekebilir, güz...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/merhameti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Sevmek', 'yar-sevmek-ayse-hazal-beytas-nugmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Yar sevmek, yiğit işi

Ne bilsin her divane''

Yiğitlik, yiğit işi

Yiğitlikten sana ne.', '''Yar sevmek, yiğit işi Ne bilsin her divane'' Yiğitlik, yiğit işi Yiğitlikten sana ne....', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yar-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bayramlar...Suçlu Kim...', 'eski-bayramlar-suclu-kim-ugur-kilic-esgm7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zor uyuduğum bayram arefelerinde,

Uyanı verirdim sabahın altısında,

Tutardım babamın elinden,

Giderdik bayram namazına.

Çocukluk telaşı veye heyecanı,

Çabuk bitsin isterdim namaz.....

Daha bayramlıklarımı giyecektim,

Büyüklerin ellrini öpecektim,

Topladığım harçlıklarla,

Lunaparka gidecektim.

Ev ev dolaşırdık,

Önce tanışlara uğrardık,

Topladığım şekerleri

Kardeşimle paylaşırdık.

Kına yakılırdı kurbanlara,

Etler dağıtılırdı komşulara,

Kapıdan kimse çevrilmezdi,

Adetti şeker vermek çocuklara,

Bayramın ilk günü çocuklarındı,

İkinci gün başlardı akraba ziyaretleri,

Üçüncü gün komşulara gidilir,

Kısaca bayramın her günü ayrı zevkti.

Bir bayram havası var sokaklarda,

Bu söz şimdi anılarda,

Unuttuk adeleri,

Hata birim çoğumuzda.

Karşı komşunu tanırmısın? 

Tanısanda uğrarmısın? 

Bir merhabadan kaçmak için! ! 

Evindemi saklanırsın? 

Yarın bayram çocuklar erken kalkalım mı? 

Gerçi erken kalkacak çoşkunuz varmı? 

Haklıdır çocuklar hesap sorsa,

Onları götürecek eşin dostunuz kaldımı? 

Hata sende, bende, hepimizde,

Taşıyamadık adetleri geleceğe,

Soruyorum şimdi ne oldu bizim,

Örf, adet ve millet sevgimize? 

Atalardan emanetti bunlar bize,

Kalksalar topraktan acırlar halimize,

Dostlar gelin sahip çıkalım

Yoksa çocuklarımızda gelmez elimizi öpmeye...', 'Zor uyuduğum bayram arefelerinde, Uyanı verirdim sabahın altısında, Tutardım babamın elinden, Giderdik bayram namazına. Çocukluk telaşı veye...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/eski-bayramlar-suclu-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakup', 'yakup-tugba-simsek-8aade', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakup umdun, tek sevdigim canimdin benim

Askindan divaneye donup kacmistim sana

Kara toprak olup gittin, biraktin beni bana

Unutacagimi sakin ha dusunme! Ben seninim...

Para pul birakmasaydin da yanimda olsaydin benim

30.01.2005

(cok degerli, rahmetli dayicigm icin...)', 'Yakup umdun, tek sevdigim canimdin benim Askindan divaneye donup kacmistim sana Kara toprak olup gittin, biraktin beni bana Unutacagimi saki...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yakup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçtir Artık Çok geç', 'gectir-artik-cok-gec-tacettin-karagoz-sx2gv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyor musun dostum

Öyle bir an olur ki

Hiçbir limanı görünmeyen okyanusun

Ortasındaki gemi gibi hissedersin kendini,

En ufak bir karartı dahi sana 

Kara parçası sığınacak liman gibi gelir

Başını dayayacak bir diz 

Saçını okşayacak bir el

Ve bakan anlamlı bir çift göz

Aramaya başlarsın

Ömrünün en derin uykusu

Tüm hayat boyu gördüğün 

En dehşetli rüyadır bu

Birilerinin seni 

Tokatlamasını beklersin

Ki uyanasın bu uykudan

Olmaz ne seni tokatlayan

Ne de rüyanı yorumlayan

Hayatın ta kendisidir yaşadığın

Ama bir türlü inanmak istemezsin

Çaresizliğin seni çağırdığında 

Çoktan çözülmüştür dizlerinin bağı

Dikemez hiçbir terzi

Anlamaya başlarsın

Ağlamak sızlamak boşuna

Bunu anladığında

Hafif bir sis 

Çoktan çökmüştür her iki gözüne

Berrak olan her şey buğuludur artık

Ne yapsan ne etsen

 Geçtir vakit 

Artık çok geç....', 'Biliyor musun dostum Öyle bir an olur ki Hiçbir limanı görünmeyen okyanusun Ortasındaki gemi gibi hissedersin kendini, En ufak bir karartı d...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Karagöz']::text[], 8.5, '{"poet":"Tacettin Karagöz","poet_slug":"tacettin-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gectir-artik-cok-gec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-soner-guvendir-ljq66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslanın ağzından,

Ekmeğimi almak için,

Yüreğimin yarısını,

Şehrin ışıklarında bırakıp,

Dağlar aştım,

Yollar geçtim.

Yağmurda ıslandım

Çamur oldu hırslandım,

Caddelerde dolaştım

Çocuklarla konuşturm

Yalnızlığımı küçültsün diye,

İnsanlar arasına karıştım.

Öfkelendim kendime kızdım.

Gelgör ki ne yaptığı bilinmez biriyim.

Yinede gülüm,

Güneşli bir şehir sabahında

Bir sonbahar türküsünde

Hasretimi ardıma bırakıp

Koşarak geleceğim.

(2005)', 'Aslanın ağzından, Ekmeğimi almak için, Yüreğimin yarısını, Şehrin ışıklarında bırakıp, Dağlar aştım, Yollar geçtim. Yağmurda ıslandım Çamur ...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-323-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Zelal', 'ah-zelal-tacettin-karagoz-95hsn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah ZELAL

Denizin ahenkli sesi, 

Dalgaları sahile kavuşturmak ister.

Rüzgârın ısrarlı sesi,

Yaprakları toprağa kavuşturmak ister.

Yapraklar yazdan kalan ne varsa,

Örtmek ister.

Ah ZELAL

Kar taneleri zoruma gider

Hatıralarımı beyaz kefene sarmak ister.

Ya gönlüm

Gönlümse; bunların hiç biri olmasın ister', 'Ah ZELAL Denizin ahenkli sesi,  Dalgaları sahile kavuşturmak ister. Rüzgârın ısrarlı sesi, Yaprakları toprağa kavuşturmak ister. Yapraklar y...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Karagöz']::text[], 8.5, '{"poet":"Tacettin Karagöz","poet_slug":"tacettin-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-zelal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Aleme Yay''vermişsin Sihrini', 'tum-aleme-yay-vermissin-sihrini-zek-i-budak-tf3i4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm aleme yay''vermişsin sihrini

Nere kaçsam nere gitsem şaşırdım

Aşık gönlüm lûtuf sayar kahrını

Dert mi desem zevk mi desem şaşırdım 

Yıkılacak bir gün dünya direği

Sanma yoktur sözlerimin gereği

Dar göğüsüm içindeki yüreği

Tam bir ömür bu aşk ile pişirdim

Taştım ama aşamadım bendimi

İnan tuttum ikrarımı ahdimi

O gül yüzün aşkı için kendimi

Yüce dağdan enginlerden aşırdım

Bir vuslata değer mi bin kelâmın

Kokusu burnumda tüter sılamın

Ayda yılda bir alırım selâmın

Gül cemalin hayâlime düşürdüm

Zekâi''yim dolaştım tüm alemi

Göremedim böyle engin ilimi

Kalbe yazdım kullanmadım kalemi

Aşk güneşi olmayaydı üşürdüm

(Edirne - 1973)', 'Tüm aleme yay''vermişsin sihrini Nere kaçsam nere gitsem şaşırdım Aşık gönlüm lûtuf sayar kahrını Dert mi desem zevk mi desem şaşırdım  Yıkıl...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tum-aleme-yay-vermissin-sihrini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlerin Ardından', 'gidenlerin-ardindan-soner-guvendir-t364j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birer birer yitirdik

Çınar ağacımızın yapraklarını

Kimi dibine düştü,

Kimini uzaklarda biryerlere,

Rüzgar aldı götürdü.

(2005)', 'Birer birer yitirdik Çınar ağacımızın yapraklarını Kimi dibine düştü, Kimini uzaklarda biryerlere, Rüzgar aldı götürdü. (2005)...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gidenlerin-ardindan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-soner-guvendir-yzx11', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sizler uyurken geceleyin

Usulca öptüm yanaklarınızdan

Sizler uyurken geceleyin

Saçınızı okşadım,kokladım

Ey nazlım

Yavru ceylanım,Hazalım

Çocuk düşünü bozmamak için

Saramadım seni kucağıma

Ey nazlım

Çocukluğunu sığdırdın,

Beton duvarlara

Sizler uyurken geceleyin

Geride üç damla yaş bıraktım.

Biri aya

Biri güneşe,

Biri de sana.

(1999)', 'Sizler uyurken geceleyin Usulca öptüm yanaklarınızdan Sizler uyurken geceleyin Saçınızı okşadım,kokladım Ey nazlım Yavru ceylanım,Hazalım Ço...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/giderken-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba''ma', 'baba-ma-soner-guvendir-vd6bb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mezar taşını öptümde

Bir baba diyemedim.

Akıttım içime,

Gözyaşımı silemedim.', 'Mezar taşını öptümde Bir baba diyemedim. Akıttım içime, Gözyaşımı silemedim....', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baba-ma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçının Teli', 'sacinin-teli-soner-guvendir-eg7z2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçının telini buldum

Bugün kazağımda

Yarısı sarı

Siyah diğer yarısı

Kokladım koydum

Cüzdanımın arası', 'Saçının telini buldum Bugün kazağımda Yarısı sarı Siyah diğer yarısı Kokladım koydum Cüzdanımın arası...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sacinin-teli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Çocuklar', 'bizim-cocuklar-soner-guvendir-yjl58', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yalınayak

Karlar üstünde yürüyen

Sırtında bir kazağı olmayan çocuk

Ve yüreğinin sıcaklığıyla

Eritirken karı ayakların

Güneş seninle doğacak

Sen elinde kuru ekmeğiyle

Suyu katık eden çocuk

Ve gözlerindeki umutla

Bakarken gökyüzüne

Yağmur seninle yağacak

Ve sizler hepiniz çocuk

Tutunca ellerinizi beraber

Bu yoksulluğa

Bu zulme

Özgürlük sizinle gelecek

(1997)', 'Sen yalınayak Karlar üstünde yürüyen Sırtında bir kazağı olmayan çocuk Ve yüreğinin sıcaklığıyla Eritirken karı ayakların Güneş seninle doğa...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bizim-cocuklar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-soner-guvendir-avs1u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün seni onsekizinde düşündüm

Bayram havasında

Seni tanıdığım günü

Parklarda caddelerde

Seni beklediğim

Ay gibi parlayan gülüşünü

Sanki yanacakmış gibi

Elini tutuşumu

Ve yavru ceylan gibi ürkek

İlk öpüşümü

Dün seni onsekizinde düşündüm

Gidişini

Nasıl bir ayrılık bu

Ay buluta girmiş

Zifiri karanlık

Dün seni onsekizinde düşündüm

Mektuplarını

Telefonda

Beni okşar gibi seven sesini

Yedi tepeli şehirde

Bekleyişini

Gülen gözlerini

Denizi yararcasına

Beyaz köpükler içinde

Martı sesinde

Vapurda

Elini tutuşunu düşündüm

Dün seni onsekizinde düşündüm

Yağmur kar olsa da

Üşüse de ellerim ayazda

Otobüsü binip

Bitmeyecekmiş gibi gelen

Yolları aşıp

Yanına koşuşumu düşündüm

Yıldız parkında,Çamlıcada

Çingene falcılar arasında

Yanımda oluşunu

Sevginin o masum güzelliğiyle

Sıcaklığını duyuşumu düşündüm

Dün seni

Beyaz gelinlik içinde

Ömrümün en mutlu gününde düşündüm

Ayrılık yok artık

Yan yana yanımda

Bir elim omuzunda

Yaslarken başını göğsüme

Sıcaklığını düşündüm

Dün seni

Yavrumuzu dünyaya getirirken

Anne kokuşunu düşündüm

Dün seni

Cefakarlığında düşündüm

Geçirdiğim kazayı

Hastanede,dışarıda

Ağlamaklı sesini duyunca

Hıçkıra hıçkıra

Ağlamak istediğimi düşündüm

Bir çocuk gibi beni yıkamanı

Gömleğimi giydirmeni

Moral vermeni

Sevecenliğini düşündüm

Dün seni

Yıkıntılar arasından çıkarken düşündüm

Yanında olamadım

Sana birşey olsaydı

Neyapacağımı bilemeden

Çıldırasıya

Eve koşuşumu düşündüm

Dün seni

Çocuklarla yalnız başına

Yapayalnız bırakışımı düşündüm

Dün seni

Otobüste

Boğazım tıkanarak

Dokunsalar ağlayacak

Doya doya sarılamadan

Bırakıp geride

Bu ayrılığa gelişimi düşündüm

Dün seni

Gecenin güneşi

Ferhatın Şirini düşündüğü gibi

Yağmur altında ıslanarak

Gözlerimde

Gözyaşımla düşündüm', 'Dün seni onsekizinde düşündüm Bayram havasında Seni tanıdığım günü Parklarda caddelerde Seni beklediğim Ay gibi parlayan gülüşünü Sanki yana...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/seni-dusundum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutun ki', 'tutun-ki-soner-guvendir-8pudu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızları tutun gökyüzünde

Tutun ki sabaha kaybolmasınlar

Güneşi tutun ışınlarından

Tutun ki aya gerek kalmasın

Çiçek verin insanların eline

Verin k i silaha gerek kalmasın

Sevgi büyüt ellerinde

Büyütki zulme gerek kalmasın

(1990)', 'Yıldızları tutun gökyüzünde Tutun ki sabaha kaybolmasınlar Güneşi tutun ışınlarından Tutun ki aya gerek kalmasın Çiçek verin insanların elin...', ARRAY['Türk Edebiyatı','Şiir','Soner Güvendir']::text[], 8.5, '{"poet":"Soner Güvendir","poet_slug":"soner-guvendir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tutun-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durun Dayılar Ağalar', 'durun-dayilar-agalar-zek-i-budak-72ag5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durun dayılar ağalar

Üzerime varman n''olur

Bir güzeli sevdim ise

Suç değildir vurman n''olur

Bir dinleyin hele durun

Suçum yoktur emin olun

Yalan sözüm var mı sorun

Deyiversin zaman n''olur

Severim candan ziyade

Bilin mana yok riyada

Üç günlük fâni dünyada

Kalp incitmen aman n''olur

Ne arkamdan yerin beni

Ne yüz karşı övün beni

Hak ettimse dövün beni

Ama yârsız koman n''olur

İşte Zekâi böyle der

Yok mu halimden bilenler

Garipliğimi görenler

Gözünüzü yumman n''olur

(Edirne - 1973)', 'Durun dayılar ağalar Üzerime varman n''olur Bir güzeli sevdim ise Suç değildir vurman n''olur Bir dinleyin hele durun Suçum yoktur emin olun Y...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/durun-dayilar-agalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarın Ne', 'umarin-ne-zek-i-budak-vd356', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koyup koyup gitmelerin

Tüketecek sabrımı bil

Alay yüklü gülüşlerin

Gözlerime çekilen mil

Yak ta sevda ateşini

Hak''ka yönelt her işini

Öldürmekle kardeşini

Ne kazandı sanki Kabil

(Yok Dönmene İhtimal - 2003)', 'Koyup koyup gitmelerin Tüketecek sabrımı bil Alay yüklü gülüşlerin Gözlerime çekilen mil Yak ta sevda ateşini Hak''ka yönelt her işini Öldürm...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umarin-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Itırlı gülüşü / sevdikçe senleşmek...', 'itirli-gulusu-sevdikce-senlesmek-zafer-zengin-etnika-h1c18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

kez

kaç el uzansa

kırılır kez

- tekerrürden ibarettir doğmalar -

sesi ağlaması

kez dolu çırpsın dalları

vurgun zaman

ıtır ıtır elleri

yağmur sonrası

zordur anlatması

- nefesi çeken susar -

bilinler kemirmez

ne endişesi efendim

süzülen su değil

içine karışmış toprağı

- sevdikçe senleşir -

dur dökülsün kımıltıları

yüzümde ayın bir yanı

çirkinim

dünya değişse

değişmez elleri

ıtırlı gülüşü

bu kez gülmez…

12 12 2005

.', '. kez kaç el uzansa kırılır kez - tekerrürden ibarettir doğmalar - sesi ağlaması kez dolu çırpsın dalları vurgun zaman ıtır ıtır elleri yağm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/itirli-gulusu-sevdikce-senlesmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulaşamadıklarınızdır Kovaladığınız', 'ulasamadiklarinizdir-kovaladiginiz-tacettin-karagoz-c67qx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçin tüm hızınızla 

Puslu sokakları

Kovaladığınız,ulaşamadıklarınızdır

Tüm hayat boyu

Ne yazık ki farkında değil

Hiç biriniz', 'Geçin tüm hızınızla  Puslu sokakları Kovaladığınız,ulaşamadıklarınızdır Tüm hayat boyu Ne yazık ki farkında değil Hiç biriniz...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Karagöz']::text[], 8.5, '{"poet":"Tacettin Karagöz","poet_slug":"tacettin-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ulasamadiklarinizdir-kovaladiginiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kıtalık Hayat', 'bir-kitalik-hayat-mustafa-caliskan-manisa-5aeyc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tahterevallinin şu iki kolu 

Hayatımız iniş ve çıkış dolu 

Bazen renklidir,  bazen gri tonlu 

Ve istikametimiz mezar yolu', 'Tahterevallinin şu iki kolu  Hayatımız iniş ve çıkış dolu  Bazen renklidir,  bazen gri tonlu  Ve istikametimiz mezar yolu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-kitalik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Döndüm', 'geri-dondum-yunus-isikoglu-slxif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geri döndüm şiirlerim

Geri döndüm size

Giderken size dargın değildim

Ama gene de başka dostlar da aradım

Bulduklarım

Sizin kadar vefalı çıkmadı

Sizin kadar anlamadılar beni

Siz benim

Sırdaşım

Dert ortağım

Neşem

Kederim

Yani siz benim yaşamımı tatlandıran

Hayata bağlayan

Lastikli ipimsiniz

Biz kopamayız

Bakın gene sizinleyim', 'Geri döndüm şiirlerim Geri döndüm size Giderken size dargın değildim Ama gene de başka dostlar da aradım Bulduklarım Sizin kadar vefalı çıkm...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geri-dondum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-sinan-bilici-yjy3x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün göçüp giderse şu beden 

Kendimle birlikte aşkını

Yanıma alıp çok uzaklara...

Unutulmuşsa yüzün,bedenin

Korkma sevdan var yanımda 

Eğer  bir gün gelirde ağlarsam arkandan

Bil ki bu seni çok özlediğimdendir.', 'Bir gün göçüp giderse şu beden  Kendimle birlikte aşkını Yanıma alıp çok uzaklara... Unutulmuşsa yüzün,bedenin Korkma sevdan var yanımda  Eğ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-gun-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmalanmış hayat', 'yagmalanmis-hayat-aysenur-yazici-osn3i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gel arkadaş gel..! 

yağmalanan yaşamlarda

kafesi devrilen kuşların,

korkunç özgürlüğe ürkek kaçışlarına geeel...

Birbirimize ödünç verdiğimiz kederlere

ganimetin sahipsiz tadına,

emanet bırakılan sevgilere

toz duman arasında yalnızlığa tevacüzlere geel....

Geeel kaçırma geel...

İşportaya atılan kontes aşklarına,

ikinci el hüzünlere,

üçüncü el yıkımlara,

dördüncü el intiharlara geeel...

yağmalanmış bir ömrün

parçalanmış bir kurbanın

pirzola kısmını bilâ ücret kapmaya geeel

...ucuz, herşey ucuz 

yaşam ucuz,sevgi ucuz, his ucuz...

kaç para? 

Bu yara? 

            08.01.2006

            Kızkulesi

            (13:50)', 'gel arkadaş gel..!  yağmalanan yaşamlarda kafesi devrilen kuşların, korkunç özgürlüğe ürkek kaçışlarına geeel... Birbirimize ödünç verdiğimi...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yagmalanmis-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden saklarsın gözlerindeki', 'neden-saklarsin-gozlerindeki-i-smail-pekinoglu-q0o4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden saklarsın gözlerindeki 

ateşi bilinmez,

halbuki gün sana muhtaç

gece sana aç.

kaç..

nereye kaçarsan kaç.

yangınlar sana koşacak

ve ateşinle yanacak..

                       mart 2004', 'Neden saklarsın gözlerindeki  ateşi bilinmez, halbuki gün sana muhtaç gece sana aç. kaç.. nereye kaçarsan kaç. yangınlar sana koşacak ve ate...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neden-saklarsin-gozlerindeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin kahır, bin zulüm..', 'bin-kahir-bin-zulum-i-smail-pekinoglu-fwc1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bin kahır, bin zulüm..

Ne gidilecek bir yer var

ne de düşülecek peşine bir yar

ver elini şimdi

	dağlar,

ver elini

	yalnızlıklar..

		Mart 2004', 'Bin kahır, bin zulüm.. Ne gidilecek bir yer var ne de düşülecek peşine bir yar ver elini şimdi 	dağlar, ver elini 	yalnızlıklar.. 		Mart 200...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bin-kahir-bin-zulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-i-smail-pekinoglu-srqcy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fırtına delirmicesine

çarpıyor kapıları,

Burda olsan

	korkardın,

sana dokunamazdım

	korkardım.

Dışarısı buz,

dışarısı kuduz.

Sen olsan

şimdi dışarda olmazdım..

		Nisan 04', 'Fırtına delirmicesine çarpıyor kapıları, Burda olsan 	korkardın, sana dokunamazdım 	korkardım. Dışarısı buz, dışarısı kuduz. Sen olsan şimdi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/firtina-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramınız kutlu olsun.', 'bayraminiz-kutlu-olsun-mikdat-bal-hl83j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün bayram barışalım

Buluşalım görüşelim 

Affetmekte yarışalım

Bayramınız kutlu olsun

Bayram böyle kutlu olur

Barışanlar mutlu olur

Yarınlar umutlu olur

Bayramınız kutlu olsun

Kurban olsun bütün hisler

Atılsın bütün kaprisler 

Bayramı muhabbet süsler 

Bayramınız kutlu olsun 

Kerhen değil seve seve 

Uğrayalım her bir eve 

Herkes başlasın göreve

Bayramınız kutlu olsun', 'Bu gün bayram barışalım Buluşalım görüşelim  Affetmekte yarışalım Bayramınız kutlu olsun Bayram böyle kutlu olur Barışanlar mutlu olur Yarın...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bayraminiz-kutlu-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son kadeh, son gece, son name..', 'son-kadeh-son-gece-son-name-i-smail-pekinoglu-5abhw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son kadeh, son gece, son name..

Ateşler taşırım avuçlarımda,

yangınlar küle döner

		narımdan.

Düşlerim soğuk

	düşlerim ayaz.

Buz kesmiş kahırlarda

	yanar,

		tutuşur ömrüm..

Son kadeh; 

Mey avutmaz gönlüm deli,

yalnızlıklar böler uykularımı,

yarı derin,

yarı netameli.

gece sarhoş

	gündüz sarhoş..

Son gece; 

	ağır,

sancısı yürekte kahır.

Bağırsam duymaz kulaklar,

karanlıklar sağır..

Sarı bir yıldız akar,

gece sabahlara kadar ağlar..

Son name; 

Hıçkırıklarım sana akıyor,

sende kaldı yüreğimin yarısı.

Bu son akışı yüreğimin

	sana delice,

Bu son

	gözlerinden öpüşüm.

Kaybolup gidiyorum şimdi

		yakamozlarında..

			Ekim 05', 'Son kadeh, son gece, son name.. Ateşler taşırım avuçlarımda, yangınlar küle döner 		narımdan. Düşlerim soğuk 	düşlerim ayaz. Buz kesmiş kahı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Pekinoğlu']::text[], 8.5, '{"poet":"İsmail Pekinoğlu","poet_slug":"i-smail-pekinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/son-kadeh-son-gece-son-name-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen nerdesin.2', 'sen-nerdesin-2-yilmaz-ozturk-rgev4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalgalar sahile kavuştular

Sen nerdesin ömür töpüleniyor

Akşam saat 11de gözlerimden Nil akıyor

Nerdesin ellerim senden imdat bekliyor

Senden uzaktayken saniyeler sanki bir asır

Yastığım taş toprak yatağım yorganım hasır

Yoruldum düştüm yere ayaklarım da nasır

Dudaklar çaktladı sensiz yüreğim kanıyor

Herşeyde seni arıyorum sen yoksun

Ben sensiz yaşamıyorum seni gören gözde nursun

Yalvarıyorum mahrum etme gözlerim nura kavuşsun

Eğerki bana nurun çoksa çek mili gözlerim kör olsun', 'Dalgalar sahile kavuştular Sen nerdesin ömür töpüleniyor Akşam saat 11de gözlerimden Nil akıyor Nerdesin ellerim senden imdat bekliyor Sende...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-nerdesin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havale', 'havale-aysenur-yazici-c9sz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'katrana batırdılar

zifirim az,

teleklerim yolundu

dünya ayaz...

yağlı bir kağıdım,

mürekkep de tutmaz...

sesim dağ gibi,

 duyana sivrisinek saz....

.................postaya verildim,

...............pulum yok...

            08.01.2006

            Kavaklar

            (15.05)', 'katrana batırdılar zifirim az, teleklerim yolundu dünya ayaz... yağlı bir kağıdım, mürekkep de tutmaz... sesim dağ gibi,  duyana sivrisinek ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/havale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olgusu', 'ask-olgusu-baki-sulopasa-qkozg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk; kapılmak, sürüklenmek,

ve kendinle tanışmaktır.

Bir kişi hariç,

Herkesi ve herşeyi...

Sıfıra indirgemedir.

O, hariç kişiyi de; 

Kendine saklamaktır.

Çünkü aşk; gençlik,

o da en asil sarhoşluktur.

Ömründe iki sille yersin.

Biri:Feleğin sillesi,

Diğeri:Aşkın sillesi.

Hangisi acı dersin.', 'Aşk; kapılmak, sürüklenmek, ve kendinle tanışmaktır. Bir kişi hariç, Herkesi ve herşeyi... Sıfıra indirgemedir. O, hariç kişiyi de;  Kendine...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-olgusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AşK La(L) Söyleşi', 'ask-la-l-soylesi-arjin-murad-zj0cd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AşK La(L)  söyleşi

Yaz sanırdım bütün bir ömrü sen yanımdayken,,,

yazardım...

yaza benzetmeye çalışırdım elimin değdiği her şeyi,

dilimin değdiği her yer sevgi kokardı..

ömrümü çalardın sen aslında-farkına bile varmazdım-

ne çok kayıp vermişim....

ne çok yalan dolmuş talan ömrüm...

                          

                                      2

işte yin karanlık var kapımın önünde,

dışarda KARanlık yağıyor...

ve uzun zamandır bayat bir küfür tadı veriyor

yüreğimin çarptığı duwarlar...

ne çok duvar varmış be....

ne çok küfür kusmuş yüreğim....

                                       3

bazen kendimi -bır-Akıyorum hayatın kollarına,

bazende KApatıyorum sana vaRAn tüm yollarımı....

  ''''bir istisnayım artık kuralı bozuyorum''''

yağtığı her şeyi eline yüreğine bulaştıran bir çocuk...

başladığı her yeni paylaşımı korkularıyla aldatan bir aşığım belkide...

yada sen isim ver bana bilmiyorum...

                                          4

aşktan geriye ikişer-üçer sayıyorum kendimi,

acıdan ileriye dörder-beşer...

sonra birbirini kapsayan -bizim ayrık bildiğimiz-bu iki kümede ortak bir sonuç buluyorum...

korku.......................korkularım................

isteyerek kaçmalarım....

hem isteyip hem kaçtıklarım....

birde hiç bir zaman sonuna sahiplik  eki koyamadığım sen....

                                          5

gökyüzüyle benzeştirirdim kendimi...

  -yada gökten yağan yağmurla-

en çok çaresizliğime benzerdi ıslatan damlaları göğün...

çünkü ne zaman çaresiz kalsam sırılsıklam olurdum...

-sırılsıklam ağlardım-

şimdi ömürden saymıyorum yağmurun bana benzediği günleri...

ağlasam ağladığım günlere...

yarın bugüne ağlayacağım biliyorum...

                                             6

acemi bir seyyahtım -hatırlarsın-

ortak olmuştum insanların ortak bir yalanına -insanlığımdan-

oysa sen kimsin? -bilmezdi kimse-

ulaşılmazlıktın belki,belki bu yüzden caziptin...

anlaşılmazlık olmalısın ki:herkes kendinden birşey buluyordu sende...

yoksun d(İYE) miyorum sana ey aşk...

ama ben seni aramıyorum....

parçalanacağın günü bekliyorum  sadece...

sonra belki bir parçanın bana çarpmasını..

-bir parçanın beni çarpmasını-

                                                                      Arjin_

                                                                  08-01-2006

                                                                     Siwerek', 'AşK La(L)  söyleşi Yaz sanırdım bütün bir ömrü sen yanımdayken,,, yazardım... yaza benzetmeye çalışırdım elimin değdiği her şeyi, dilimin de...', ARRAY['Türk Edebiyatı','Şiir','Arjin Murad']::text[], 8.5, '{"poet":"Arjin Murad","poet_slug":"arjin-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ask-la-l-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Süpürgesi', 'sokak-supurgesi-baki-sulopasa-q1apo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yetmiş''ime yakın bir yerimde saklı,

Bir sokak süpürgesi! 

Dadanmış karanlık zindan kapılarına,

Aydınlıktan kaçıyor gibi.

Hiç yokmuş gibi orada,

Pırıltılı sabahlar,

Sarı beyaz çiçekler,

Ve kuşların cıvıltısı.

Bir yetmiş''ime yakın yerimde saklı,

Bir sokak süpürgesi.

Çalıp durma ikide bir; 

Sıktın artık; ezintiymiş, yıkıntıymış...

Çek bir çizgi üzerlerine; 

İyi ki unutmak var! 

Güneş kapılarını çal, yine çal.

Sokak süpürgesi ne olacak!', 'Bir yetmiş''ime yakın bir yerimde saklı, Bir sokak süpürgesi!  Dadanmış karanlık zindan kapılarına, Aydınlıktan kaçıyor gibi. Hiç yokmuş gibi...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sokak-supurgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-i-lyas-genc-lb4pa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '--------------------

Birgün düşeceğiz pencerelerden

Sen çiçek bahcesine, ben çamur batak içine 

Seni annen yıkayıp parklayacak

Beni yine tinerci cocuklar kovalayacak..

Sen her okul cıkışında annenı bulacaksın karşında

Ben se arıyacağım her daim gözyaşımda

Sen her gece annenin kucağında yatacaksın

Bense yıldızlarda annemı arayacağım...

Sen her yağmurda sokağa cıkıp oynayacaksın

Ben annemin gözyaşlarını tek tek ayıklayacağım...

Senin annen pazara gitti bekle birazdan gelecek

Benim annem mezara gitti hiç gelmeyecek……

yasak.tutku', '-------------------- Birgün düşeceğiz pencerelerden Sen çiçek bahcesine, ben çamur batak içine  Seni annen yıkayıp parklayacak Beni yine tin...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/annem-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-akin-akca-g1t72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir şiirken

bir kaç değildir.

ancak nicelik sığmaz

ve öldürür.

sonra kaldırır

öldüren ve sağaltır

ama bu başkadır,

çünkü hepsidir.

doğabilmek,

olmaktır.', 'bir şiirken bir kaç değildir. ancak nicelik sığmaz ve öldürür. sonra kaldırır öldüren ve sağaltır ama bu başkadır, çünkü hepsidir. doğabilme...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-249-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Yeri..', 'bayram-yeri-mucahit-gulbas-4f39c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zehir zıkkım kahve için bekleriz sizi...

İzdüşümlerimizde kaybolurda..

Yeniden buluruz belki geçmişimizi

Eh! gerisi yetişir artık yüreğimize..

İstersen sek sek,istersen bez bebek  taşı ruhuna

bir anlam bulduktan sonra varoluşuna.

Burası atlı karıncalar,burası bayram yeri,

Gerisi laf-ı güzaf çocuk...

Gerisi bayram şekeri.

07.07.2006/izmir', 'Bir zehir zıkkım kahve için bekleriz sizi... İzdüşümlerimizde kaybolurda.. Yeniden buluruz belki geçmişimizi Eh! gerisi yetişir artık yüreği...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bayram-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manyetik kutbun buzları', 'manyetik-kutbun-buzlari-baki-sulopasa-7my7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dönüp dönüp,

O an''a takılır; 

Acı belleğim eşelendikçe.

Aslında, bir tek sözcüktü,

Yanardağ öfkesinde; 

Dudaklarımdan dökülen.

Manyetik kutbun buzları,

Sokuldu aramıza, parça parça.

Küslüğü kopuşa varmasın diye...

Yeniden tavlamak vardı hesapta; 

Genç aşığı oynıyarak,

Öyle kolay mı? eski rolleri oynamak.

Zorlu bir kale gibi direndi; 

Nuh dedi, peygamber demedi! 

Bütün çiçek isimlerini sıraladım; 

Adının önüne, sıfat diye.

Yabancılaşma duygusu,buz gibi; 

Ellerim,  titreyerek uzandı saçlarına. 

Uzaklaşmaktan hızla uzaklaşmalıydık.

Ortada bir şey yok ki! 

Yeniden sarılmalı, koklaşmalıydık.

Bizler eski aşıklar değilmiydik? 

Birbirimizin vazgeçilmezi değilmiydik? 

Haydi! odamız, yatağımız, anılar, resimler,

Saksıdaki çiçekler,sevinecekler barışmamıza.', 'Dönüp dönüp, O an''a takılır;  Acı belleğim eşelendikçe. Aslında, bir tek sözcüktü, Yanardağ öfkesinde;  Dudaklarımdan dökülen. Manyetik kutb...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/manyetik-kutbun-buzlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsalar Ağlayacağım', 'dokunsalar-aglayacagim-nurten-koroglu-0snnq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılığın ok misali saplı yüreğimde

Gelmiyorsun, 

Ben hep böyle çaresiz yollarına mı bakacağım

Bu gün yine isyanım çığlarca

Dokunsalar ağlayacağım

Ardına bakarak gidişin hala sızı içimde

Bir gelsen doyasıya sarılacağım

Bu kaçıncı gece,kaçıncı sabahtır ki sayamıyorum

Dokunsalar ağlayacağım

Bensiz olacak yarınlarına

Sana dolu dolu sevgimi bırakacağım

Bu gün bari gel kederdeyim,benimle ol bırakma

Dokunsalar ağlayacağım

Hep haram oluyor bana sensiz aşım,sensiz gülüşüm

Daha ne kadar benim olman için Tanrıya yalvaracağım

Duyulmuyor sesim,duyulmuyor çığlıklarım

Dokunsalar ağlayacağım', 'Ayrılığın ok misali saplı yüreğimde Gelmiyorsun,  Ben hep böyle çaresiz yollarına mı bakacağım Bu gün yine isyanım çığlarca Dokunsalar ağlay...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dokunsalar-aglayacagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-nurten-koroglu-b9fub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bilsem yandığı kimdir,sevdiği kimdir o gözlerin

Öyle mahzun,öyle sevdalı,öylesi vurgun

Bir dokunsam baharlar dökülüverecek sanki

Baktıkça uzayıp gider,bilinmeyen diyarlar yorgun

Sineye dert olur,götürür eleminde

O gözler ki, yara açtı içimde silinmeyen

Sanki öylesi alıp başını gitmiş

Bir yol ki,bir daha geri dönülmeyen

Ruhumda yaktığı ateşte,sönmez durur izleri

Bir sevda olur öylesi dingin,öylesi durgun

Bir an gelir bir ümit,bir çare bırakacakmış gibi

Bir an gelir öylesi sessiz,öylesi suskun', 'Bir bilsem yandığı kimdir,sevdiği kimdir o gözlerin Öyle mahzun,öyle sevdalı,öylesi vurgun Bir dokunsam baharlar dökülüverecek sanki Baktıkç...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozler-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlara Küskünüm', 'bayramlara-kuskunum-mehmet-demir-atmali-yuiyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğumun, sevincimin hecesi,

Özlenen bayramlara, dünden küskünüm...

Rasul-ü Ekrem, ninemin bilmecesi; 

Gözlenen bayramlara, dünden küskünüm...

ÇAPARımın toprağa düştüğü güne,

ÇETİNERin göremediği düğüne,

İMAMOĞLUnun aç kaldığı öğüne,

Yozlanan bayramlara, dünden küskünüm...

Ülkü Erleri, vatan için ölenler,

Bu vatana kastedenlerle, bölenler.

Aynı kefeye koyan koydu, bilenler(!)

İzlenen bayramlara, dünden küskünüm...

Medrese-i Yusufi denen zindana,

Mamak''ta işkence yapan Gardiyana,

Babasını göremeden doğan Handan''a,

Gizlenen bayramlara, dünden küskünüm...

Mehmet''i gerici ilan eden kafa,

Zalimden mazluma istenen her af''a,

Yüz sürmek için varamadığım saf''a; 

Nazlanan bayramlara, dünden küskünüm...

9.10.1987

Not: 1980 öncesi Gaziantep''te Şehit düşen

Av.Mehmet Çapar ve Ali Çetiner''e ve üç gün 

aç kaldıktan sonra, cebinde 35 kuruş çıkan

İlk şehitlerden Yusuf İmamoğluna yazdım.', 'Çocukluğumun, sevincimin hecesi, Özlenen bayramlara, dünden küskünüm... Rasul-ü Ekrem, ninemin bilmecesi;  Gözlenen bayramlara, dünden küskü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bayramlara-kuskunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Bir Gözyaşı', 'kirik-bir-gozyasi-suheyla-kurnaz-sp0za', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susuyorsun...

Suçlusun biliyorsun,

Konuşmak istiyorsun, utanıyorsun öyle değil mi? 

Aşkın silahında kurşun sözlerinle 

Akıttın yüreğime, içten içe sızan kanımı.

Şimdi…

Sar sarabiliyorsan ruhumda kanayan yaramı...

Utanıyorsun...

Dehşete kapılıp, yüzüme bakamıyorsun

Şah damarın tıkanıyor öyle değil mi? 

Yanakların kırmızı güle bezenirken,

Kaçırma hicran mavisi gözlerini,

Şimdi…

Bak bakabiliyorsan, gözlerimin içine

Ağlıyorsun...

Hıçkırıkların düğümleniyor boğazında

Pişmanlığın yakıyor bedenini  değil mi? 

Bozguna uğrattın sevdamı, kıymetini bilemedin,

Feryadın, ağıtın nafile

Sevdalı gözlerim sana kapandı artık.

Şimdi…

Sev seve biliyorsan kelepçeli yüreğimi

Yanıyorsun...

Gecenin ayazında sokaklardasın

Kaldırım köşelerinde hoyratça, ser sefilsin öyle değil mi? 

Efkarın yüzünde mağrur gölge

Kırık gözyaşımla soruyorum sana hesabını

Mihrabımda  umarsız sevdan bitti artık

Şimdi…

Yak yakabiliyorsan yüreğimdeki küllerini

Gidiyorsun...

Son nefesinde şehâdet getirirken

Son sözün, ''''Affet Allah''ım'''' olsun

Daha ne bekliyorsun ki? 

Hadi git! 

Suskunu, nârını  ağıtlarını da al git

Gönlümü zincirledim ben aşklara

Yüreğimin kapısı  mezar taşım

Şimdi…

Aç açabiliyorsan sevda kapımı...

25.12.2005

SuheylaKurnaz.com - Kişisel Web Sitem

SuheylaKurnaz.com - Kişisel blog Sayfam

Yorum: Ömer Aykan (Radyo Davet / Mavi Gece Şiir Programı_BURSA)', 'Susuyorsun... Suçlusun biliyorsun, Konuşmak istiyorsun, utanıyorsun öyle değil mi?  Aşkın silahında kurşun sözlerinle  Akıttın yüreğime, içt...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kirik-bir-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Verecek', 'kim-verecek-saadet-ekinci-lgtts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömür kısa gelip geçiyor

yaşanmamış günlerin

set vurulmuş  emellerin

hesabını kim verecek

insanız  eşitiz derken

biri biftek diğeri

kuru ekmek yerken

hesabını kim verecek 

dünya nimetlerinin 

çoğunu görmeden 

tatmadan göçüp gidenlerin

hesabını kim verecek? 

(08.01.2006 ist.)', 'Ömür kısa gelip geçiyor yaşanmamış günlerin set vurulmuş  emellerin hesabını kim verecek insanız  eşitiz derken biri biftek diğeri kuru ekme...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ekinci']::text[], 8.5, '{"poet":"Saadet Ekinci","poet_slug":"saadet-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-verecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmak Kişi', 'ahmak-kisi-timur-i-likan-zqxzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahmak kişi sadece koşar dünyâ peşinde

Zerre kadar bile bir hayır olmaz işinde

Yalana yalan katar her söz söyleyişinde

Zerre kadar bile bir hayır olmaz işinde

Kendini buluverir cehennem ateşinde

Geçirir hep ömrünü boş işlerle beyhûde

Miskin miskin oturur kahve köşelerinde

İskâmbil kâğıtları onun hep ellerinde

Zerre kadar bile bir hayır olmaz işinde

Kendini buluverir cehennem ateşinde

Nerde bir günah varsa hep oraya dadanır

Kötü dostlarına da hemencecik aldanır

Meyhâneden ayrılmaz içip içip sallanır

Zerre kadar bile bir hayır olmaz işinde

Kendini buluverir cehennem ateşinde

Hiç düşünmez yarını, harcar boşa varını

Havaya ateş açar,  sıkar kurşunlarını

Yoldan çıkar durur da bulamaz kulvarını

Zerre kadar bile bir hayır olmaz işinde

Kendini buluverir cehennem ateşinde

Böylesi de pek çoktur şu üç günlük dünyâda

Geçer gider günleri gafletli bir rüyâda

Aklı başına gelir ancak öte dünyâda

Zerre kadar bile bir hayır olmaz işinde

Kendini buluverir cehennem ateşinde

(8 Ocak 2006/ İstanbul)', 'Ahmak kişi sadece koşar dünyâ peşinde Zerre kadar bile bir hayır olmaz işinde Yalana yalan katar her söz söyleyişinde Zerre kadar bile bir h...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ahmak-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Elimden Gökyüzü', 'tut-elimden-gokyuzu-mehmet-kindap-beyb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tut elimden gökyüzü

Götür beni uzaklara

Bahar yağmurlarının yağdığı yere

Azgın akan ak köpüklü

Mavi yeşil sulara

Tut elimden gökyüzü

Götür beni uzaklara

Mor sümbüllü dumanlı dağlara

Papatyalara gelinciklere

Peygamber çiçeklerine kırlara

Tut elimden gökyüzü

Götür beni uzaklara

(2006 Ankara)', 'Tut elimden gökyüzü Götür beni uzaklara Bahar yağmurlarının yağdığı yere Azgın akan ak köpüklü Mavi yeşil sulara Tut elimden gökyüzü Götür b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tut-elimden-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpücüklere Boğ Beni', 'opucuklere-bog-beni-vedat-koparan-tstk9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(kopart gecenin ipini soyunsun gerdanından,savrulsun rüzgarımızda yoksunlar, akayım sana öpücüklerden kale olsun 

çağla bana,gecenin mavisinde kopart yüreğimden yüreğimi al kat yüreğine, iki yürek bir olsun 

kardelenler nasıl üşür Munzur’da,har gül nicedir yarda, güneşi bekler açsın diye gün şafaklarında. 

o koca dağdan düşer kör karanlıklar, ben beni vurur, it gibi titrer sokakta kalan garipler,bir üşüme ağlar kuytu kıyılarda 

bırak derim bu üşümeleri,yangın yalnızlıkların türküsünü 

dayanamam,ah be kardelenim,har gülüm gel güneşe gidelim.)  

ne kaldı ise yaşanacak acele edişimizde zamansızlığımızdı 

yol vermez dar geçitlerde sıkışıp kalışımız amansızlığımızdı 

yıllar geçti bizi bizden alıp yorgunluklar dermansızlığımızdı 

sevdalara baş koyduk hep terk edildik ahde vefasızlığımızdı 

Vedat Koparan 08.01.2006 

Bazen Topal Bir Sevda Oldu Yüreğimizde Vurgunlar Yedik. 

Düştük,Tökezledik,Kalktık, Yeri Geldi Yenik Düştük Zamana. 

Yer Yer Esiri Olduk Anlamlı -Anlamsız Koşuşturmalarda... 

Adını Bilincimize Yazdığımız Anılara Kazıdığımız Dostlarımızı; Hiç Unutmadık... 

“Bizim Nehirlerimiz Var Ak Köpüklerinde,Hayallerimiz Var Yüzdürdüğümüz, 

Dostlarımız Var, Bayramlar Var Ayrı Geçirdiğimizde Üzüldüğümüz” 

Bütün Yaşamımız Bayram Olması Umuduyla. 

“Bir Ağacın Gölgesindeki Huzur Sudaki Saflık, Topraktaki Bereket Ve Aldığımız Nefesteki Anlam Kadar ''Güzel Olsun Her An, Nice Yaşanası.. Aydınlıklarla, Mutluluklar. Çocuk Gözlerini Giydir Gözlerine 

...gerçek bayramlarımız adına geleneksel  günü kutlar insanlığın en adaletli en özgür zamanlarına ulaşması  ''kurbansız bayramlara'' dileklerimi iletirim. İyi Bayramlar...Saygı Sevgiler.', '(kopart gecenin ipini soyunsun gerdanından,savrulsun rüzgarımızda yoksunlar, akayım sana öpücüklerden kale olsun  çağla bana,gecenin mavisin...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/opucuklere-bog-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ev', 'bos-ev-baki-sulopasa-yzc4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Işıkları çoktan, söndürülmüş evin.

gözlerim arıyor, dantel perdeleri,

Yüzüne bakmıyor, gelip geçenlerin.

Çocuklar basıyor, çalmayan zilleri.

Karanlık odalar, kara böceklerin; 

Yıkılmış bacalar, unutmuş tütmeyi.

Duyulmaz yıllardır sesi bebeklerin,

Kırılmış camları,  yalnızlık günleri.

Saksıları vardı, pembe çiçeklerin; 

Nerede? sulayan, incecik elleri.

Boşalmış odalar, uçuk gölgelerin; 

Baykuşların sesi, kaplar geceleri.', 'Işıkları çoktan, söndürülmüş evin. gözlerim arıyor, dantel perdeleri, Yüzüne bakmıyor, gelip geçenlerin. Çocuklar basıyor, çalmayan zilleri....', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bos-ev-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim Hayriye Bozçalı''ya', 'esim-hayriye-bozcali-ya-seyfet-bozcali-veyhc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğim tek kadın,ve ilk göz ağrım,

Mevlamın lütfudur böyle bir hanım.

Özü,sözü doğru,canım cananım,

İlk gün gibi hiç aklımdan çıkmadın...

Senin sevdan ile sevdakar oldum,

Gerçek temiz aşkı sayende buldum.

Sonunda evlendik bahtiyar kıldın,

Bir an olsun hiç aklımdan çıkmadın...

Yirmi yedi yıldır sırrım satmadın,

Yüzüm kızartacak birşey yapmadın,

Derdime kahrıma çokça katlandın,

Yıllar oldu,hiç aklımdan çıkmadın...

Yolsuz,susuz köylerde çile çektin,

Kader birliğine hep boyun büktün,

İki oğul verdin bahtiyar ettin,

Yıllar oldu hiç akımdan çıkmadın...

Dağ oldun yasladım sırtımı sana,

Güven verdin,destek oldun hep bana,

Minnattar bıraktın beni hep sana,

Yıllar oldu hiç aklımdan çıkmadın...

Seyfet der sevgisiz söyler mi insan,

İnsanı sevgiyle yaşatır insan,

Kalbimde köşk kuran sevdiğim Sultan,

Yıllar oldu hiç aklımdan çıkmadın...

        ''Dünya nimeterinin en hayırlısı Saliha bir hanımdır.''

                                                                  Hadis', 'Sevdiğim tek kadın,ve ilk göz ağrım, Mevlamın lütfudur böyle bir hanım. Özü,sözü doğru,canım cananım, İlk gün gibi hiç aklımdan çıkmadın... ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/esim-hayriye-bozcali-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüdüğüm Topraklarda Hıyanet var', 'yurudugum-topraklarda-hiyanet-var-eyup-selahattin-dalkiran-bnpze', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tut elimden gökyüzü

çek kendine

yürüdüğüm topraklarda

Kırıkı kırık akan gözyaşı var

Hıyanet var.

Bir dokunsalar hepsi

Ağlayacaklar gibiler.

Tut elimden gökyüzü

çek kendine

Yürüdüğüm topraklarda

Her yer acı bir bayram hüznü gibi

Her gördüğümde 

bir dudak ucu kül ve ateş var.

Tut elimden gökyüzü

çek kendine

yürüdüğüm topraklarda

Yağmalanmış,yağmalanmakta 

olan yürekler var.

Tut elimden gökyüzü

çek kendine

yürüdüğüm topraklarda

Cehennem zebanileri koro

halinde şarkılar söylemekte.

Tut elimden gökyüzü

çek kendine

yürüdüğüm topraklarda

Yüzlere acımazsıca kapanan

kapılar var.

Durun beyler,ağalar

Tüm alemin ellerine

bir sıkımlık hayatlara

Kırlangıç hüzünleri bağlamışsınız sanki.

tut elimden gökyüzü

çek kendine

yürüdüğüm topraklarda

bir sıkımlık koşmalarla,konuşmalarla

kefenlerini giymiş insanlar var

yarı bellerine kadar

sizleri koklamaya hazır vaziyette.', 'Tut elimden gökyüzü çek kendine yürüdüğüm topraklarda Kırıkı kırık akan gözyaşı var Hıyanet var. Bir dokunsalar hepsi Ağlayacaklar gibiler. ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yurudugum-topraklarda-hiyanet-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-seyfet-bozcali-bry79', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir özenti ile başladım sana,

Ömrüme musallat oldun sıgara,

Aldın akciğerden oksijenimi,

Siyah zehirini saldın sıgara...

Çok küçük yaşlarda sana aliştım,

Para bulmak için azmı çalıştım.

Ekmek param ile sana kavuştum,

Köle yaptın beni sana sıgara...

Paramı yakıpta uçtun havaya,

Nifak soktun o sıcacık yuvaya,

Asi ettin beni ana,babaya,

Hayatımı alt üst ettin sıgara...

Alıştım içmeden duramıyorum,

O kara sevdana doyamıyorum,

Senden özgesini aramıyorum,

Aşık ettin beni sana sgara...

Ben vazgeçtim bırakmadın peşimi,

Bir ara bıraktım döktün dişimi,

Zehir ettin ekmeğimi aşımı,

İrademi alt üst ettin sıgara...

İnsanı düşmana muhtaç edersin,

Girdiğin mekanı duman edersin,

Zehirini saçip,çekip gidersin,

Çok yuvalar viran ettin sıgara...

Tıkadın damarım gitti bacağım,

Bu sakat halimle ne yapacağım,

Nefes almaz oldu akciğerlerim,

Dünyamı kararttın,yıktın sıgara...

Öğretmen Seyfet der sana kanmadım,

O karanlık oyununa gelmedim,

Nefret ettim yakınıma koymadım,

Hayatımda sana yer yok sıgara...

                             ''Pişman Olmak tövbedir.''', 'Bir özenti ile başladım sana, Ömrüme musallat oldun sıgara, Aldın akciğerden oksijenimi, Siyah zehirini saldın sıgara... Çok küçük yaşlarda ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sigara-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haftaym Beyler', 'haftaym-beyler-baki-sulopasa-tdtl0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaldırım mühendisleri; arkadaşım,

Orda burda içki içtim, hava attım.

Piyasada cirit attım, at oynattım; 

Ayaklarımın altında, koca şehir.

İğne atsan yere düşmez, meyhanede,

''Haftaym beyler''  moda olmuş, karhanede.

Bir yaz aşkım sona erdi,Gülhane''de,

Ressamları, ozanları, yutan şehir.

Düşlemişim İmkansızı, bak gözlerim; 

El değmemiş duru güzel, tut ellerim.

Geri gelsin yaban zaman, ah güzelim; 

Gözü dönmüş yıkımların, azmış şehir.', 'Kaldırım mühendisleri; arkadaşım, Orda burda içki içtim, hava attım. Piyasada cirit attım, at oynattım;  Ayaklarımın altında, koca şehir. İğ...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haftaym-beyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Diyelim Yeter Artık', 'dur-diyelim-yeter-artik-seyfet-bozcali-7l147', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu anlamsız savaşlara,

Göstermelik barışlara,

İnsanlara kıyanlara,

Dur diyelim yeter artık.

Mesken tutulmuş dağlara,

Bağrı yanık analara,

Nefret dolu bakışlara,

Dur diğelim yeter artık.

Kinle dolan yüreklere,

Kan kusan o alçaklara,

Ölüm saçan silahlara,

Dur diyelim yeter artık.

Gençlerime kıyanlara,

Devletini soyanlara,

Kara para yiyenlere,

Dur diyelim yeter artık.

Mehmetçiğe kıyanlara,

Toprağa göz koyanlara,

Halk sırtından doyanlara,

Dur diyelim yeter artık.

Karanlık günler çatmadan,

Nifak tohumu bitmeden,

Ülke gemisi batmadan,

Dur diyelim yeter artık.

Sorumsuzca yaşanmaya,

Ekranlarda boşanmaya,

Şampanyayla yıkanmaya,

Dur diyelim yeter artık.

Nam peşinde koşanlara,

Sahte hacı,falcılara,

Diplomasız Doktorlara,

Dur diyelim yeter artık.

Düşünce zıtlaşmasına,

Mezhepler çatışmasına,

Kültürler yozlaşmasına,

Dur diyelim yeter artık.

Bize bizden başka dost yok,

Dostumuz az düşmanlar çok,

İçten,dıştan yıkanlar çok,

Dur diyelim yeter artık.

Seyfet der kucaklaşarak,

Fikirlerle barışarak,

Hep birlikte çalışarak,

Dur diyelim yeter artık...', 'Bu anlamsız savaşlara, Göstermelik barışlara, İnsanlara kıyanlara, Dur diyelim yeter artık. Mesken tutulmuş dağlara, Bağrı yanık analara, Ne...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dur-diyelim-yeter-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 45 (''biz'' ve ''tanrı'')', 'lirik-45-biz-ve-tanri-fevzi-cebe-sax8m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eğilip bükülen

sesler gibisin demek isterdim

ama değilsin

eğilip bükülen

sesler gibisi yoktur

eğilip bükülen –seslerle-

dolduruyorum kıvrımlarımı

seninle değil

sen mi demelisin

ne yazık 

ben mi

oyunlarımız olmadı

gerçeklerimiz ise acıydı

gözlerimden düşmeyen

yaşların sorumlusu sen misin

kader mi

görmeyen gözlerim çığlık atıyor

nefesim kendine şarkı söylüyor

içimde

gerçeklik buysa, reddedemem

kabulde

eşzamanlı olmadı çoğu şey

bir kılıcım var

o bir ölüm 

öldüreceğim...ama kimi

iki kere iki dört

sıfır çarpı sıfır sıfır

bir çarpı bir bir

üç kere bir üç

biz bunlardan hangisiyiz

sıfır artı bir bir

sıfır bölü sıfır tanımsız

2 kere sıfır sıfır

sıfır eksi bir eksi bir

bir artı eksi bir sıfır

biz bunlardan hangisiyiz

belki de hiçbiriyiz

bizim işlemimiz tanımsız çıktı

ben bir bölü iki artı bir bölü ikiye razıydım

“bir”

belki gücü yetmedi tanrının bu işleme

cebri

belki biz bu düzende yeralamadık

yaralandık

ne tanrı tanrı olabildi

ne biz “biz”

ne tanrı tanrı kalabildi

ne de biz biz

hata ne matematikte ne tanrıda

ne de bizde

hepimizin kaderi buydu belki 

oyunun bu sahnesinde

ne tanrı tanrı olabildi

ne matematik varlığını ispatlayabildi

ne de biz

tanrımı asmadım kalbimde

matematiğe küsmedim

seni silmedim kalbimden

kim bilir belki tanrı benim! 

ne senin ne kendimin

hiçbirşeyin tanrısı

bana bunları söyleten ne

bana bu hayatı yaşatan ne

adımızın sadece ilk harfleri büyük

gerisi...

tüm harflerimi sildim, alfabemden

tüm harflerini sildim, alfabemden

şekillerle yontulacaksa aklım

şekillerle kavrayacaksa bundan sonra da

varsın kavramasın

kavrayamadığı boşluğu, doluluğu

14.02.2005 – gece yarısı.', 'eğilip bükülen sesler gibisin demek isterdim ama değilsin eğilip bükülen sesler gibisi yoktur eğilip bükülen –seslerle- dolduruyorum kıvrıml...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/lirik-45-biz-ve-tanri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murakabe', 'murakabe-i-brahim-sagir-qxn0e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beynimin içinde binlerce akrep, 

Zehirliyor sanki öz düşüncemi...

Zamanı parçalar yelkovan-akrep,

Saniye didikler durur gecemi...

Menfide müsbeti aradı aklım,

Güzellikler Kafdağı’nın ardında...

Geçmişimi geleceğe bağladım,

Yıllardır yürüdüm bıçak sırtında...

Hâyâlden ötede gerçeği sezdim,

Bütün sahtelikler eridi bir bir...

Çile bahçesinde merdâne gezdim,

Kılavuzum oldu en ince fikir...

“Nereden gelmişim, yolum nereye? ”

Sualinde saklı elbet bütün sır...

Sıkışmış kalmışım bir cendereye,

Kaldım bu yollarda aciz ve kısır...

Aklımı fikrimin okuyla vurdum,

Ruhumun aynası gösterdi “BİR”i...

Nasılı, niçini nisyâna sardım,

Bildim ki, O bâki, yalnız O diri...', 'Beynimin içinde binlerce akrep,  Zehirliyor sanki öz düşüncemi... Zamanı parçalar yelkovan-akrep, Saniye didikler durur gecemi... Menfide mü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/murakabe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zıtların girdabında', 'zitlarin-girdabinda-i-brahim-sagir-st52d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde esmektedir, tayfunlar, fırtınalar,

Fikrimin girdabında boğuluyor vicdânım.

Beşerin ellerinde mazlumların kanı var,

Suskunluk dehlizinde mahkûm sanki isyanım.

Dar geldi yaşlı dünya, yıldızlara göz diktim,

Havsalamda çarpıştı binlerce zıt iç içe.

Kağıttan gemilere çelikten yelken diktim,

Fezânın sırlarına kement attım delice.

Yürüdüm gölgelerin arkasında nice yıl,

Hep gerçeği aradım yalan sahralarında.

Eşyaya şekil verdi haddini bilmez akıl.

Takıldı kaldı gönül ruhumun esrârında.

Nefsim eline aldı vesvese fenerini,

Aklım tuğyana kalktı, fikrim galeyan etti.

Vicdanımın aynası gösterdi hünerini,

Tâ ebet diyârının yolunu ayan etti.', 'İçimde esmektedir, tayfunlar, fırtınalar, Fikrimin girdabında boğuluyor vicdânım. Beşerin ellerinde mazlumların kanı var, Suskunluk dehlizin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zitlarin-girdabinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kapıdan bir kapıya', 'bir-kapidan-bir-kapiya-i-brahim-sagir-rrsc5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmişime bir göz attım bu gece,

Ömrümün çoğunu nisyanda gördüm.

En sonunda ölüm amma netice,

Yine de nefsimi isyanda gördüm.

Bir kapıdan bir kapıya yürüdüm,

Fâni tende bâki can’ı sürüdüm,

Hayat denen merdivende çürüdüm,

İnsanoğlunu hep hüsranda gördüm.

Ham hâyâlin dert pişirir aşını,

Yel ufalar kıraç dağın taşını,

Olgun başak yere eğer başını,

Dâneyi, samanı harmanda gördüm.

Mahlûkâtı muti kıldı Emr-i Hakk,

Tevâzu timsali şu kara toprak,

Açar varlıklara sevgiyle kucak,

Hayrı da, şerri de insanda gördüm.

Hayret sardı Tûr Dağında Mûsa’yı,

Göğe çekti sağken Rabbim İsa’yı,

Muhammed-ül Emin şakk etti Ay’ı,

Zamanı eğiren kirmanda gördüm,

Hazret-i Âdem’den bu güne gelen,

İnsanlık ufkunda insana gülen,

Çağlar arasında en son yükselen,

Asr-ı saâdeti bir yanda gördüm.

Gönüller Allah’ın nazargâhıdır,

Kur’an hakikatin tek dergâhıdır,

Hatem-ül Enbiya şahlar şahıdır,

Dünyada huzuru imanda gördüm.

Sağır’ım dünyaya eyleme meyil,

Bu dünya hayatı ebedi değil,

Rabbin huzurunda edeble eğil,

Sonsuz saâdeti Cinânda gördüm.', 'Geçmişime bir göz attım bu gece, Ömrümün çoğunu nisyanda gördüm. En sonunda ölüm amma netice, Yine de nefsimi isyanda gördüm. Bir kapıdan bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-kapidan-bir-kapiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-i-brahim-sagir-nyzs6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nesilden nesile emânet irfan,

İrfanı hür ise hür olur insan,

Mâziden aldığın haysiyete kan,

Vermesini bileceksin.

Geçmişine bağlı tüm mefahirin, 

Hizmetkârı olma nefs-i hakirin,

Güçsüzün, yetimin, bîkes fakirin,

Gözyaşını sileceksin.

Hür ise bayrağın, hür ise vatan,

Millet sevgisiyse kalbinde yatan,

Herkes bahtiyarsa, işte o zaman,

Huzur ile güleceksin.

Sevgi doğar, kollar kolu sarışta,

Hedefine adım adım varışta,

Milletler arası fende, yarışta,

Fezaları deleceksin.

Uğratma semtine bir dem uykuyu,

İlim nurlu sema, cehalet kuyu,

Mânâ hızarıyla havayı, suyu,

Eşit eşit böleceksin.

Bencillik putunu parça parça kır,

Putları kırmanın hünerinde sır,

Muzdarip insanlar asrı bu asır,

Çaresini bulacaksın. 

Esir olma nefsin kör inadına,

Getir ecdadını her dem yadına, 

Yükünü çektiğin dava adına,

Öl denende öleceksin.', 'Nesilden nesile emânet irfan, İrfanı hür ise hür olur insan, Mâziden aldığın haysiyete kan, Vermesini bileceksin. Geçmişine bağlı tüm mefahi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nasihat-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gergef', 'gergef-i-brahim-sagir-rloe0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömür iki nefes arası kadar,                                       

Yoklukla varlığın arasındayım.                                  

Şimdiki yoklar var olacaklar,                                      

Ben ise yokluğun sırasındayım.

Ezelden ebede akar bu ırmak,                                 

İsyânın nâfile, boştur haykırmak,                             

Elimde değil ki çemberi kırmak,                                 

Kaderin aşılmaz ver âsındayım.                                

Ruhum tüketiyor mesafeleri,                                     

Bilmem bu kalıbın nerede yeri,                                  

İmkansız çevirmek zamanı geri,                               

Acaba şu ömrün neresindeyim.                                

Gelişim, gidişim sırdan bir düğüm,                           

İkisi de ayrı mekânda doğum,                                  

Bir gerçek ve mutlak benim gördüğüm,                   

Allah’ın bir küçük karasındayım.', 'Ömür iki nefes arası kadar,                                        Yoklukla varlığın arasındayım.                                   Şimdiki ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gergef-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahırlanır', 'kahirlanir-i-brahim-sagir-a75ei', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülistânı mekan tutsa baykuşlar,

Bülbül kahırlanır, gül kahırlanır. 

Kapasa yolları uçtan uca kar,

Hancı kahırlanır, yol kahırlanır.

Gurbetçinin elem yağar üstüne,                  

Canavarlar girer kuzu postuna,

Sitem etse dostun biri dostuna,

Dudak kahırlanır, dil kahırlanır.  

Elden bir şey gelmez, kader küsünce, 

Bahçeleri yaban, ayrık basınca,

Hazan rüzgârları deli esince,      

Yaprak kahırlanır, dal kahırlanır.

Sevgisiz, sevgiye olunmaz nail,

Gönül ummanında sevgidir sahil,

Yazı yazsa ak kağıda bir cahil,

Parmak kahırlanır, el kahırlanır.

Dostun dosta sevgisinden ün gelir, 

Kem söz etme, sana döner, gün gelir,

Gönlünden nedamet ahı yükselir, 

Kucak kahırlanır, kol kahırlanır.

Sağır’ım, nadanda olmaz merhamet,  

Dünyanın törpüsü her türlü zahmet,  

Zahmet çeke çeke bükülür kamet,  

Ayak kahırlanır, bel kahırlanır.', 'Gülistânı mekan tutsa baykuşlar, Bülbül kahırlanır, gül kahırlanır.  Kapasa yolları uçtan uca kar, Hancı kahırlanır, yol kahırlanır. Gurbetç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kahirlanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koygun duygular', 'koygun-duygular-i-brahim-sagir-2p55b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaygılar ömrümün çıkmaz sokağı,	

Her sabah bir yeni teselli  arar,

Saplanır beynime fikrin hançeri,

Ruhuma bu alem dar geliyor dar.

Yakamozlar yansır mavi sularda,

Coşar içimdeki gizli duygular.

Yaşamak adına hüzün ve sevinç,

Yepyeni muştular taşır her bahar.

	

Ansızın yetişti kaderin hükmü,

Esiyor yöremde bir deli rüzgâr.

Seneler sinsice çekti hesaba,

Bahçelerim bir bir oldu tarumar.

Genç iken hayatı anlamamışım,

Her yaşın bir başka güzelliği var.

Hülyalı vakitler geride kaldı,

Dağıldı başımdan büyülü efkâr.

Amansız girdaplar çeker içine,

Uykulara perde gerer cadılar.

Kabuslu düşlerin anaforunda,

Sorgular ruhumu yomsuz cadılar.

Hüzün yağmurları düşer başıma,

İçimde bir boran, bir tipi, bir kar.		

Sarhoş hâyâllerim bozar kuralı,

Şüpheyi şüphenin peşine takar.

Gecelerim artık sükûna muhtaç,

Tedirgin bedenim yorgun, bîkarar.

Koygun duyguların okyanusunda,

Asude limandır eski anılar.

Yarınlara bilenirken umudum,

Bitmek bilmez gönüldeki arzular,

Ömrün ipi varsın inceledursun,

Bu hayatın arkasında hayat var.', 'Kaygılar ömrümün çıkmaz sokağı,	 Her sabah bir yeni teselli  arar, Saplanır beynime fikrin hançeri, Ruhuma bu alem dar geliyor dar. Yakamozl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/koygun-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilen var', 'bilen-var-i-brahim-sagir-4lnbf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldi geçti deli dolu çağlarım,

Gam deminde uykuları bölen var.

Hazan vurdu, harab oldu bağlarım,

Gülistanda bir hüzünlü şölen var.

Kavak yeli esmez oldu başımda,

Tat kalmadı ekmeğimde, aşımda,

Umman gizli her damla göz yaşımda,

Beni benden yavaş yavaş alan var.

	

 Kayıp ettim şu hayatın cengini,

Yıllar aldı saçlarımın rengini,

Son sefere sardı gönül dengini,

Ciğerimi delik delik delen var.

Düşün biraz varsa eğer iz’ânın,

Sığmaz senelere bazen bir ânın,

Can derdinde yatan ağır hastanın,

Baş ucunda bekler iken ölen var.

Baş eğmedim çıkar için nâmerde,

Göğüs gerdim nice amansız derde,

Gayri nerde eski güç kudret nerde,

Hâllerime sinsi sinsi gülen var.

			

Sebep var mı düşmen için yeise,

Yaşanacak kaderdeki ne ise,

Varsın kursun düşmanların desise,

Seni senden daha iyi bilen var.', 'Geldi geçti deli dolu çağlarım, Gam deminde uykuları bölen var. Hazan vurdu, harab oldu bağlarım, Gülistanda bir hüzünlü şölen var. Kavak ye...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilen-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün', 'birgun-arafat-arik-r61bm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürek sofrasını sererler birgün,

Hasatsız gönlünü dererler birgün,

Seninde sırrına ererler birgün,

Kalp kalbi bulunca o erler birgün.

Gelecek şafağa dilek tutulup,

Çürümüş ruhlara bin can katılıp,

Kalan sağlar için fire atılıp

Özgenin hakkını verirler birgün,

Güle giran olan acı dikeni,

Umut toprağına ateş ekeni,

Teslim olan candan canlar sökeni,

Kadim çarmıhlara gererler birgün

Ey kalbim sana da mihrican uğrar,

Tatmadığın hüsran, perişân uğrar,

Bir amansız sızı,su-i zan uğrar,

Mansur niyetine yererler birgün,

03-Ocak-2006', 'Yürek sofrasını sererler birgün, Hasatsız gönlünü dererler birgün, Seninde sırrına ererler birgün, Kalp kalbi bulunca o erler birgün. Gelece...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birgun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Ona Yaz Okusun Dedi', 'yuregim-ona-yaz-okusun-dedi-umut-gungor-09b8d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim ona yaz okusun dedi,

Sevgini kalbine dokusun dedi,

Defalarca seni okusun dedi,

Yürek dedi yazdım seni şiire.

Irmaklar gül aksa sana ulaşsa,

Bülbüller seninle gezip dolaşsa,

Selamım onlarla sana ulaşsa,

Yürek dedi seni yazdım şiire.

Çiçekler saçına taç olup konsa,

Sana nazar eden o anda donsa,

Farzetki bu yazdığım şiir sonsa,

Yürek dedi seni yazdım şiire.

Dışarda yağıyor kar beyaz beyaz,

Çıkarsan dışarı ayazmı ayaz,

Rabbime eyledim dua ve niyaz,

Yürek dedi seni yazdım şiire.', 'Yüreğim ona yaz okusun dedi, Sevgini kalbine dokusun dedi, Defalarca seni okusun dedi, Yürek dedi yazdım seni şiire. Irmaklar gül aksa sana ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregim-ona-yaz-okusun-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleme', 'gozleme-seyfet-bozcali-zv5gd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çorum Osmancıkta çıktın karşıma,

İsmin çok hoş geldi,uydum nefsime.

Bilmem nerden yedim pisi,pisine,

Midemizi alt üst ettin gözleme...

Otobüste acı sancı çekerken,

Sıkıntıdan ecel teri dökerken,

Arabanın durmasını beklerken,

On dakika bir yıl oldu gözleme...

Arabadan indim tutmaz dizlerim,

Yolcuları görmez oldu gözlerim,

O gün wc''leri çokça özledim,

Barsakları viran ettin gözleme...

Kuytu bir yer bulmak için yarıştık,

Yükseklerden atlamaya çalıştık,

Bir daha mı yememeğe ant içtik,

Bizi sana düşman ettin gözleme...

Öğretmen Seyfet der olanı sezdim,

Bozçalı kardeşler anlattı yazdım,

Bende Osmancık''ı yerinde gezdim,

İbret dolu gözle baktım gözleme', 'Çorum Osmancıkta çıktın karşıma, İsmin çok hoş geldi,uydum nefsime. Bilmem nerden yedim pisi,pisine, Midemizi alt üst ettin gözleme... Otobü...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozleme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Peygamber''e', 'son-peygamber-e-suleyman-yavas-h1eeb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bir gayesisin fani dünyanın

Güzellik bahçesi senin her yanın

Ayı çatlatıyor nur yüzün paspak

Güneşe bile senden gelir bu ak

Sendendir öğrendiğim edep haya 

Seni bilmez iken kalbim taş kaya

Güzel nurunla aydınlanır her yan

Bil ki melekler bile sana hayran

Bu zaman ihtiyaç sana ihtiyaç

Ey sevgili sensiz bu gönüller aç

Hep derim yoluna kurban olayım

Sen iste ana babasız kalayım

Anarım güzel ismini sözümde

İnan bir sen varsın benim özümde

Süleyman''ın sevdası her gün eser

Aşk hep sanadır ey Yüce Peygamber', 'Sen bir gayesisin fani dünyanın Güzellik bahçesi senin her yanın Ayı çatlatıyor nur yüzün paspak Güneşe bile senden gelir bu ak Sendendir öğ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-peygamber-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımazsız Sonbahar Gecelerinde Sen Elinden Geleni Yap', 'acimazsiz-sonbahar-gecelerinde-sen-elinden-geleni-yap-eyup-selahattin-dalkiran-22dr8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ölüm 

Dar yollar gibi

Öteler beni

Gözlerinin o Yeşil sıcaklığına

Uzaktan uzağa

Tek perdelik oyun gibi.

Önceleri ve sonralar ki

Hesap ortada

Gönül içine bırakılan

anılara sığınmış 

bir mektup

dolaşır olmuş

öpmeyi unuttuğumuz

yıllar gibi,

geriye kalan

ben oldum

yağmur yağarken

yalnız kaldırımlarda

dövünüp yıkılan 

yüreğim ile.

Söyleyemedin

maviye çalan gecelerde

aşkımın tarifini

şiirler içinde.

Biliyorum

sen beni katmalıydın 

Ben seni o ufak ufak

anlılarımızın peri kanatlarına.

Acımazsız sonbahar gecelerinde

Sen elinden geleni yap ne olur

açık olmalısın

Elma kabuklarında bulunan parlaklık ile

hayatın resmini çizmelisin kendine

Haydi hayatın çok uzaklardaydı bilirsin

kendini suçlama

Yoksa

susar kırlangıç kuşları

tepemizden geçerken.

Ben varken sende vardın

parmaklar uzanırken yarın ki hayatlarımıza

yok oluşumuza varacak

yok oluştaki çaresizlik gibi

yüreğimizi kapılarda bırakarak.', 'ölüm  Dar yollar gibi Öteler beni Gözlerinin o Yeşil sıcaklığına Uzaktan uzağa Tek perdelik oyun gibi. Önceleri ve sonralar ki Hesap ortada ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/acimazsiz-sonbahar-gecelerinde-sen-elinden-geleni-yap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Elini', 'ver-elini-emre-saricicek-c3ls5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ver elini gidelim sonsuzluğa.

Bizi bekleyen sessiz karanlığa.

Aşalım engelleri tüm gücümüzle,

Pes etmek yok böyle sevince.

Hadi ver elini, gidelim diyorum.

Geride kalanları düşünmüyorum.

Hey aşkım, sana söylüyorum.

Gelmeyeceksin biliyorum...', 'Ver elini gidelim sonsuzluğa. Bizi bekleyen sessiz karanlığa. Aşalım engelleri tüm gücümüzle, Pes etmek yok böyle sevince. Hadi ver elini, g...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ver-elini-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Yakarış', 'geceye-yakaris-ayse-hazal-beytas-tnlc8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürek paramparça yine bu akşam

Bu akşam içimde bin bir sızı var

Bitmiyor saatler, geçmiyor zaman 

Dakika dakika bitiyorum yar.

Sevgili, yokluğun ateşten kement

Sardıkça sarıyor tüm bedenimi

Ayrılık, sen bari biraz insaf et! 

Vuslat ateşine bırak yerini

Ey gece, bir defa merhamet bana! 

Bu sefer sorguya çekme karanlık! 

Yalnızlık, bu sefer dolma odama! 

Ey kabus sana da bir mola artık.', 'Yürek paramparça yine bu akşam Bu akşam içimde bin bir sızı var Bitmiyor saatler, geçmiyor zaman  Dakika dakika bitiyorum yar. Sevgili, yokl...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceye-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-cemal-simsek-tzmar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ilkbahar sabahında,

Seninle ilk buluşmamızda

Aşkımızın ilk tanığı,

O havuzun başında,

Suskunken dillerimiz,

Çarpıyorken yüreğimiz,

Tek bir aşk''la,

Sadece gözlerimizle,

Bakışlarımızla konuştuğumuzda

Bizim olmasada,kirada olsa,

İki odalı bir yuva

Yetecekti aşk''ımıza.

Sen,ben,çocuklarımız

Beraber yürüyecektik 

Hayat yolunda...

Bitmeyecekti sevdamız,

Ömür boyunca.

Beraber çıktık hayat yoluna

Umutlarımız gerçekleşti zamanla.

Beklentiler,beklentileri doğurdu

Gücümüz kalmadı sonunda.

Mutlu aile yuvamız

Hazan  rüzgarlarıyla sarsıldı

En mutlu olacağımız çağda.

Bunca emek bunca mücadele,

Bırakılırmı yarı yolda

Ömrümüzün son zamanlarında

Daha çok muhtacız,

Aşkımıza,sevdamıza.

Kıralım kin''i gururu,

Bitsin bu sessiz savaş

Bırakalım sen,ben kavgasını

Kalsın yüreğimizde aşk.

Dön bir arkana bak,

O ilkbahar sabahına

Yaptıklarımız teminattır,

Yapacaklarımıza

O Azimle,

O sevdayla,

O Aşk''la......', 'Bir ilkbahar sabahında, Seninle ilk buluşmamızda Aşkımızın ilk tanığı, O havuzun başında, Suskunken dillerimiz, Çarpıyorken yüreğimiz, Tek b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/davet-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babanın Çocuğuna Öğüdü', 'babanin-cocuguna-ogudu-seyfet-bozcali-xvzg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yavrum sen anandan yeni doğmuşken,

Söylenen tekbiri duy yavaş yavaş,

Zamanla gelişip,aklın erince,

Seni yaratanı an yavaş yavaş...

Anneni,babanı sakın incitme,

Onlara hizmette hiç kusur etme,

Haksız olsalarda aksine gitme,

İlerde anlarsın sen yavaş yavaş...

Her zaman haklının yanında savaş,

İçkiden,kumardan daim uzaklaş,

Alış verişinde her an helalleş,

Haram lokma yeme sen yavaş yavaş...

Her zaman hak ile doğrudan söz et,

Garibin yetimin hakkını gözet,

Bu sözlerim sana büyük nasihat,

Hakkın ateşiyle yan yavaş yavaş...

Dünyanın bin türlü haline alış,

Hep alın teriğle kazanca çalış.

Unutma sonunda hakkadır varış,

Ta baştan söyledim ben yavaş yavaş...

Alçak gönüllü ol gururdan sakın,

Şeytandan uzaklaş,ol Hakka yakın,

Haramdan,zinadan kendini sakın,

Sonsuz kurtuluşa var yavaş,yavaş...

Saygınla,sevginle hoş görülü ol,

Özünle,sözünle doğru kişi ol,

Elime asa ol,derde derman ol,

Hkkın rahmetini gör yavaş yavaş...

Seyfet der şiirim tüm evlatlara,

Yumuşak yaklaşın ana,babaya,

Hak yolunda mazhar olun duaya,

Rabbinin sevgisin al yavaş yavaş...', 'Yavrum sen anandan yeni doğmuşken, Söylenen tekbiri duy yavaş yavaş, Zamanla gelişip,aklın erince, Seni yaratanı an yavaş yavaş... Anneni,ba...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/babanin-cocuguna-ogudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Liman', 'son-liman-sultan-duran-tneo1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzün kokuları yayılıyor bu limandan

Giden mi var, gelen mi bilinmez

Bu son hüsrandır 

Yürek dağlayan acıların sonudur belki

Belki de başlangıcı, kimbilir...

Bu feryadların, çırpınışların

Göz yaşlarında saklanmış hayatların

Umudu mu, umutsuzluğu mu bilinmez

Göz yaşı seline kapılmış 

Sürüklenen sevdaların

Kıyıya vuran kalıntıları belki

Son ya da başlangıç...

Ne farkeder ki? ...

Diyar, diyar aşan göçebe kuşların

Kanadına konmuş yelpaze umutların

Semalar da süzülen düşlerin

Belki sonu

Belki başlangıcıdır kimbilir...', 'Hüzün kokuları yayılıyor bu limandan Giden mi var, gelen mi bilinmez Bu son hüsrandır  Yürek dağlayan acıların sonudur belki Belki de başlan...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-liman-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhunu Kaptırmış Yele Vermişsin', 'ruhunu-kaptirmis-yele-vermissin-umut-gungor-945ny', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhunu kaptırmış yele vermişsin,

Benliğini alıp ele vermişsin,

Rüyanı düşünü sele vermişsin,

Bundan sonra benden selam bekleme.

Kendine kötülük eder durursun,

Hasedinden çatlar, erir kurursun,

Elbet sende layığını bulursun,

Bundan sonra benden selam bekleme.', 'Ruhunu kaptırmış yele vermişsin, Benliğini alıp ele vermişsin, Rüyanı düşünü sele vermişsin, Bundan sonra benden selam bekleme. Kendine kötü...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruhunu-kaptirmis-yele-vermissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-akin-akca-8o22o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'evli nişanlımla kanla duvaktayım,

kimse beni geri çeviremez; 

öpmek için geri arzudayım,

kimse beni geri döndüremez

seçmek için onu seçtim,

kimse bunun için suçlayamaz; 

sevmek için onu sevdim,

kimse bundan takınamaz! 

durmak için seven arınamaz,

kördöğümde bunu biçtim.

ses dinleyen bakir arsızlanamaz; 

horoz dedimse ama tavuk.

Neden ürkek, benim her şeyim; 

sen susmayasın, sen dünsün,

sen bugünsün, sen varsın; 

sen susma, beni sen çok üzüyorsun.

nolur benim sen her şeyimsin; 

kötülüğünde kör mezarımsın.', 'evli nişanlımla kanla duvaktayım, kimse beni geri çeviremez;  öpmek için geri arzudayım, kimse beni geri döndüremez seçmek için onu seçtim, ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-513-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorlu Olur', 'zorlu-olur-seyfet-bozcali-w2xtb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakın dağlar kadar yüceyim deme,

Çoğu zaman başları karlı olur.

Aman bir mazlumun kalbini kırma,

Hesabını vermek çok zorlu olur...

Aman dikkatli ol nefse aldanma,

Şatafatlı dünya haline kanma,

Servetine,kudretine güvenme,

Hesabını vermek azaplı olur...

Yalanla dolanla işini kurma,

Halkın ekmeğinin patronu olma,

Mazlumu,yoksulu kaz gibi yolma,

Hesabını vermek şiddetli olur...

Gününü geçirme faydasız şeyle,

Geçen her zamanın ziyandır böyle,

Dilin döndüğünce hep hakkı söyle,

Hesabını vermek pek karlı olur...

Alimin Arifin yolunda yürü,

Hakka kulluğunda kalma ha geri,

Doğru konuş,daim doğruya yürü,

Hesabını vermek güvenli olur...

Seyfet der birazcık öğüdüm dinle,

Boş yere konuşup,boşuna gülme,

Harama helaldır,deyip te yeme,

Bedenin hesabı şiddetli olur...', 'Sakın dağlar kadar yüceyim deme, Çoğu zaman başları karlı olur. Aman bir mazlumun kalbini kırma, Hesabını vermek çok zorlu olur... Aman dikk...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zorlu-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A…..Aşklar…', 'a-asklar-suna-aras-ezzu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendime gizli bir yürekle taşındım hep

Bir

Gülüşü ay süzmesi

İki

Zılgıtlarla acıları anılan

A…..Aşklar…

Teli kendinden kopuk

Tükenmiş bir ampulün az ışığıydı onlar

Sığamadım koynuna

Hiç oldu

Aşk gibi başlayan.

Şimdi…

Bir zamana kaldırdım ki yörüngesi olmayan

Nedendir gün görmedi güneşe serdi sevdam

Tut ki çürüyen çaput

Üflesem yırtılacak.

Hey gurbeti yakını belleyen sen, az bekle

Koşup çocukluğumu alıp geleyim

Biraz ondan aşkı dinle.

En uzun ayrılıklar adınla başlar senin

En hızlı unutmanın şeklini bulan sensin

Ecel teri, soğu artık alnımdan

Sevgilim çocuk hoş geldin

Birden bire gelmedi deprem hızıyla biten.', 'Kendime gizli bir yürekle taşındım hep Bir Gülüşü ay süzmesi İki Zılgıtlarla acıları anılan A…..Aşklar… Teli kendinden kopuk Tükenmiş bir am...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/a-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz boyatan yalan beyanlar batsın', 'goz-boyatan-yalan-beyanlar-batsin-mikdat-bal-okitr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şımardı keneler boş vere vere

Akrepler yılanlar çıyanlar batsın

Pişkinliğe verip göz göre göre

Halkı çalıp çırpıp soyanlar batsın

Tepeye çıktılar hep çalıp çalıp

Çünkü hepsi aynı aynıdır kalıp

Kanunla kendini sağlama alıp

Milleti enayi sayanlar batsın

Hakkını yiyerek yetimin dulun

Başına vurarak gariban kulun

Dönüşü olmayan gidilen yolun

Yolun çıkmazında soyanlar batsın

Nifak tohumunu yurda yayarak

Milli kaynakları hurda sayarak

Fakir fukarayı darda koyarak

Mazluma zalimce kıyanlar batsın

Simit çaldı diye ceza verenin

Küçücük çocuğa eza verenin

Devleti soyana rıza verenin

Fakiri mahpusa koyanlar batsın

Kirli elleriyle nazır olanlar

Fakir fukaraya muzır olanlar

Dıştan iyi içten hınzır olanlar

Söz verip de sonra cayanlar batsın

Mikdat der lop diye hak yutanların

Vaadin aksine yol tutanların

Pişkinliğe verip laf atanların

Göz boyatan yalan beyanlar batsın', 'Şımardı keneler boş vere vere Akrepler yılanlar çıyanlar batsın Pişkinliğe verip göz göre göre Halkı çalıp çırpıp soyanlar batsın Tepeye çık...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/goz-boyatan-yalan-beyanlar-batsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kübra Bebeğe', 'kubra-bebege-ayse-hazal-beytas-1onr1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerimden yüreğime akıyor

Gözlerin öyle tatlı öyle masum bakıyor

Yıldız kayan gecede tutulan dilek misin

Kuş musun, kelebek mi, bebek mi, melek misin

Dokunmaya, bakmaya, öpmeye kıyamıyorum.

Dokunsam da, Sevsem de, öpsem de doyamıyorum,

Şanı büyük Rahman’ın en büyük lütfü  bebek

Sen demek tükenmeyen sevgi pınarı demek.

Kokun, rengin, ahengin bir başka ilklim gibi

Gönle bahar dolduran beşinci mevsim gibi

Bahtın hep açık olsun ve kısmetin olsun bol

Ben gidiyorum bebek, Allah’a emanet ol', 'Gözlerin gözlerimden yüreğime akıyor Gözlerin öyle tatlı öyle masum bakıyor Yıldız kayan gecede tutulan dilek misin Kuş musun, kelebek mi, b...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kubra-bebege-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşimiz tulum-bacılık! ...', 'i-simiz-tulum-bacilik-mehmet-halil-lc7ty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşimiz tulumculuk…

Devlet insan için kuruldu

Şimdi insan devlet için oldu.

Üretim insan içindi

Şimdi insan üretim için.

Para değişim içindi

Şimdi değişim para için

Sınırlar uluslar içindi

Şimdi uluslar sınır için.

Silahlar korunmak içindi

Şimdi silahlar vurulmak için.

Edebiyat geliştirmek içindi

Şimdi uyuşturmak için

‘’Yaşamak için yemek vardı

Şimdi yemek için yaşamak’’

uyuyanları uyarmak için değil, 

şimdi taşlama, 

Uyanıkları, korkutmak için.

bizim için,

Kurbanlar ne kadar önemli 

hepimiz hayvan sever olduk

Hitler’den beri…

İnsanları kurban ediyoruz…

Tulum çıkardık her şeyi.', 'İşimiz tulumculuk… Devlet insan için kuruldu Şimdi insan devlet için oldu. Üretim insan içindi Şimdi insan üretim için. Para değişim içindi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/isimiz-tulum-bacilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur''an-ı Kerim''e Sorda Söylesin', 'kur-an-i-kerim-e-sorda-soylesin-seyfet-bozcali-hl80d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaratılış gayen nedir be şaşkın? 

Kur''an-ı Kerim''e sorda söylesin.

Nasıl korunulur tüm kötülükten,

Kur''an-ı Kerim''e sorda söylesin...

Niçin huzursuzsun,neden küskünsün? 

Neden gelecekten hep ümitsizsin,

İçkikumar haramdır bilmez misin? 

Kur''an-ı Kerim''e sorda söylesin...

Giyim,kuşamında olmuşsun rezil,

Yaşantına bir bak haline üzül,

Nasılmış giyinmek,nasıl tesettür,

Kur''an-ı Kerim''e sorda söylesin...

İnsanın yaşamı nasıl olmalı,

Bu dünyada nasıl huzur bulmalı,

Hakkın huzuruna nasıl varmalı,

Kur''an-ı Kerim''e sorda söylesin...

Helalı,haramı,farzı sünneti,

Nmazı,orucu tüm ibadeti,

Kıssalarla Peygamberler hayat,

Kur''an-ı Kerim''e sorda söylesin...

Seyfet der bu Kur''an Rehberdir bize,

Allah sevgisini kor kalbimize,

Neler anlatıyor ayetler size,

Kur''an-ı Kerim''e sorda söylesin...', 'Yaratılış gayen nedir be şaşkın?  Kur''an-ı Kerim''e sorda söylesin. Nasıl korunulur tüm kötülükten, Kur''an-ı Kerim''e sorda söylesin... Niçin ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kur-an-i-kerim-e-sorda-soylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sevgi İle Kim Derdi Çiçek', 'sana-sevgi-i-le-kim-derdi-cicek-umut-gungor-20hf4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana sevgi ile kim dedi çiçek,

Saçını tarayıp kim dedi bebek,

Çok beklersin sana bahar gelecek,

Baharı beklerken yazı kaybettin.

Yolunu hasretle bekleyen varmı,

Etrafında engel yolları karmı,

Bahsettiğin kişi vefalı yarmı,

Baharı beklerken yazı kaybettin.

Tertemiz sevgimi terkettiğinden,

Doğruluk yolundan çarkettiğinden,

Hatanı çok geç farkettiğinden,

Baharı beklerken yazı kaybettin.', 'Sana sevgi ile kim dedi çiçek, Saçını tarayıp kim dedi bebek, Çok beklersin sana bahar gelecek, Baharı beklerken yazı kaybettin. Yolunu hasr...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-sevgi-ile-kim-derdi-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Kadar', 'sonsuza-kadar-ali-kalafat-tnlmv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir resmin var mıdır 

Yoksa hayalden mi ibaretsin 

Soluk mudur yüzündeki renkler 

Yoksa renkten mahrum musun

Kim çizer bahtsız yüzündeki tebessümleri 

Yoksa onuda emanet mi aldın dertlerinden 

Bir gecelik diyorsun o da mahsun

Ellerin var mıdır

Gökyüzüne ulaşan

Aşkın bedenini tanıyan

Sevgiyi senden önce kucaklayan

Ellerin var mıdır söylsene

Yoksa onlar da tutmaz mı

Sezsizce giden ağır sevdana 

Uzun uzadıya sallanmaz mı 

Kalbim var mıdır 

İçinde senden başka bir kalbi taşıyacak

Daglar kadar olmasa 

Bir yüregin var mıdır

Seni senden daha cok sevecek kadar

Sevmeyeceksen

Katlin var mıdır

Hükme uygun adli hesap sorulmayacak

Varsa da kıyacagım 

ÇÜNKÜ SEVDİM SENİ

BENİMSİN SONSUZA KADAR', 'Bir resmin var mıdır  Yoksa hayalden mi ibaretsin  Soluk mudur yüzündeki renkler  Yoksa renkten mahrum musun Kim çizer bahtsız yüzündeki teb...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sonsuza-kadar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semanın Gözyaşları', 'semanin-gozyaslari-mustafa-caliskan-manisa-smlcg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'titrek sokak lambası

yavaşça soyunan ağaçlar

üşüyorlar

yaprak yağıyor

kırmızı sarı kahve 

yaprak yağıyor

üşüyor ağaçlar

ıslanıyor 

ıslanıyor

ıslanıyor

semanın gözyaşlarıyla

ağlıyor sema

hazana

karanlığa

sokak lambasının

.................   titrek ışığıyla 

.........................aydınlanamayan sokaklara

semanın gözyaşları

her biri bir melek

rahmet oluyor inanki 

semadan toprağa düşerek

kaldır ellerini semaya

ellerine vursun gözyaşları 

her biri bir damla gözyaşı

her damlası bir melek

kalbine aksın parmaklarından

derin bir uykuya alsın seni

semada süzülerek

ve uyandığında bir başka

...........................hazan sabahı', 'titrek sokak lambası yavaşça soyunan ağaçlar üşüyorlar yaprak yağıyor kırmızı sarı kahve  yaprak yağıyor üşüyor ağaçlar ıslanıyor  ıslanıyor...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/semanin-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Nasıl Utanır?', 'i-nsan-nasil-utanir-seyfet-bozcali-t11ic', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'El alır göz utanır,

Ağız yer dil utanır,

Bunlar nasırlanmışsa,

O yüz nasıl utanır.

Nefsini kollamazsa,

Helal,haram bilmezse,

Hak yolunda olmazsa,

O  kalp nasıl utanır.

Doğru yolu bulmazsa,

Namazını kılmazsa,

Hakka aşık olmazsa,

O kul nasıl utanır.

Hep rüşfet yese insan,

Günah söylese lisan,

Defalarca tükürsen,

O yüz nasıl utanır

Seyfet bu kadar yeter,

Anlayan alır satar,

Kalmamışsa namus ar,

O zat nasıl utanır.', 'El alır göz utanır, Ağız yer dil utanır, Bunlar nasırlanmışsa, O yüz nasıl utanır. Nefsini kollamazsa, Helal,haram bilmezse, Hak yolunda olm...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insan-nasil-utanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül köprüleri', 'gonul-kopruleri-zeynep-aydinlioglu-bm82e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-- 

Gönülden ğönüle..akan sevgiler 

Güç yetmez,koparamaz ellerimiz 

Sevgilerin cağl cağıl aktığı nehirler 

Sevgi olmadan bu suda yüzemezsiniz 

Gönül köprüleri kurulur yürek duvarına 

Gönül gözüyle dostu gördüm sayarsınız 

Aynı anda bakarsınız nehrin sularına 

Gönül köprüleri kurulur, unutamazsınız 

Gönül sesiyle, olur dostumuz 

Gönülden gönüle sel olan sevgilere 

Dilerim sevgiyle pekişir dostluğumuz 

Yıkılmaz hiç bir zaman gönül köprüleri', '--  Gönülden ğönüle..akan sevgiler  Güç yetmez,koparamaz ellerimiz  Sevgilerin cağl cağıl aktığı nehirler  Sevgi olmadan bu suda yüzemezsini...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-kopruleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller bitti.', 'hayaller-bitti-vedat-okkar-14puu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri ağlar oldum gözyaşım dinmedi, 

Gözlerime günlerce uyku bile girmedi, 

Koca bir sene geldi geçti, 

Sana olan öfkem geçmedi. 

Yar diye sineme sarmışken seni, 

Sen ise aldattın en yakın arkadaşımla beni, 

Arkadaşlık kavramı değişmiş belli, 

Kendimi kaybettim dünyanın düzeni neydi. 

Oysaki durumuna acımıştım ben, 

ALLAH! a inancına bayılmıştım ben, 

Kapalı bir kutuymuşsun meher, 

Açıldın saçıldın herkeze birden. 

Ne kadar safmışım sana kanmışım, 

Gerçekleri duymasan çoktan yanmıştım, 

Belkide hayallere dalmıştım, 

Hayaller bitti uyandın şimdi ben.', 'Geceleri ağlar oldum gözyaşım dinmedi,  Gözlerime günlerce uyku bile girmedi,  Koca bir sene geldi geçti,  Sana olan öfkem geçmedi.  Yar diy...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayaller-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abrassas'' tı / kadın', 'abrassas-ti-kadin-guler-atas-n0jw4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadın abrassas’tı bir rivayete göre 

Konacağı çiçeği arayan (hovarda) 

O yüzden iyi bilirdi ipek yolunu

Sevdalınızdı yemen çöllerinde

Bir güle hasret hücrelerinizde

Yardan haber demekti

Kadın abrassas’tı 

Orta çağ büyücüsü yani

Gözlerinde çiçekler

Elleri eflatun mavi

Şiir gibi yaşardı ahir ömrünü

Bilirdi bir günün hikayesini 

O yüzden sevmezdi heredot’u

Bir satırlık tarihi vardı

En fazla bir gün okunurdu

                                8/01/2006', 'Kadın abrassas’tı bir rivayete göre  Konacağı çiçeği arayan (hovarda)  O yüzden iyi bilirdi ipek yolunu Sevdalınızdı yemen çöllerinde Bir gü...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/abrassas-ti-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acısız sevdalara hasrettir yüreği', 'acisiz-sevdalara-hasrettir-yuregi-vedat-okkar-dtpjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan bu dayanır herşeye, 

Acılarını yüreğinde saklar senlerce, 

Bir gün acılarıda gelip geçer, 

Hergün doğup batan güneş misali. 

Kanar yürek acılardan, 

Kanarda kimse bilemez sahibinden başka, 

Biten sevdaların ardından, 

Unutulan sevdalar üzerine söz veririz kendimize, 

Bir daha asla diye. 

Ne kadar asla desekte, 

İnsanız acıya mahkumuz, 

Ne acısız dururuz nede sevdasız, 

Çektiği acılarda bulur kendini, 

Hiç pes etmez yeni sevdalarda bulur dertlerini. 

Bir daha hüsran yaşar sevdasında, 

Yine içinde acısıyla kalır, 

Asla pes etmez, hep arar 

Taki aradığını bulduğu zaman, 

Herşeyi değişir, 

Çünkü insandır, 

Çünkü hayattır, 

Acısız sevdalara hasrettir yüreği...', 'İnsan bu dayanır herşeye,  Acılarını yüreğinde saklar senlerce,  Bir gün acılarıda gelip geçer,  Hergün doğup batan güneş misali.  Kanar yür...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/acisiz-sevdalara-hasrettir-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacakaranlık bir gece', 'alacakaranlik-bir-gece-vedat-okkar-uw9vn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alacakaranlık bir gece, 

Kelimeler bağzımda kaldı hece hece, 

Söylemek istedim gecelerce, 

Söylemedim sabrettim senelerce. 

Şimdi sölemediğim sözlerin huzurunu yaşıyorum, 

Hayata neşe ile mutluk ile bakıyorum, 

Nedensiz aldatışların üstüne beton atıyorum, 

Gönlüme gelmesin bir daha üstüne basıyorum. 

Hayattın anlamı nedir bilmeli, 

Sevdiğin çiçekse dalında bitmeli, 

Uzaklardan okşamak bile sana yetmeli, 

Kokusu her zaman burnunda tütmeli. 

Çiçekler dalında güzeldir derler, 

Su''yu olmassa söyle ne ederler, 

Çiçeklere güzelliği verenler, 

Asıl sevgiyi hakaderler. 

Sende benim için çiçek gibiydin, 

Gül için dalından oluverdin, 

Gülün dikenini farketmedin, 

Soldun gül dibi sönüverdin. 

Susuz kaldın şimdi çırpınacaksın, 

Sevdiğin gül gibi yalvaracaksın, 

Beton attım üstünüze kalkamassın, 

Çünkü siz benim için zavallısınız.', 'Alacakaranlık bir gece,  Kelimeler bağzımda kaldı hece hece,  Söylemek istedim gecelerce,  Söylemedim sabrettim senelerce.  Şimdi sölemediği...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/alacakaranlik-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır yaralı', 'agir-yarali-vedat-okkar-a7qwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki kişiyi iyi bilirdim, 

Biri arkadaşım bildiğim, 

Ötekini arkadaşıma kurban verdiğim. 

Biri dostluğuyla hançerleyip yüreğimi 

Tanıdığım bir yabancı oldu şimdi, 

Öbürü umutlarının kulesinin altında ezdi beni 

Daha ilk duruşmada kalemi kıran hâkim gibi 

Dünyayı başıma yıkmışcasına, 

Bağrıma kurşunlar sıkmışcasına, 

Sanki bir savaştan çıkmışcasına, 

Bütün anılarım ağır yaralı.', 'İki kişiyi iyi bilirdim,  Biri arkadaşım bildiğim,  Ötekini arkadaşıma kurban verdiğim.  Biri dostluğuyla hançerleyip yüreğimi  Tanıdığım bi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/agir-yarali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık denizi', 'yalnizlik-denizi-vedat-okkar-e5tme', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendini çok güvende hissetsende, 

Bir gün sende düşersin yalNızlık denizine, 

Denizin içinde sağlam bir gemi olsanda, 

O dalgalar sert bir kaya gibi çarpar yüğreğine, 

Hele birde fırtınalar eserse içinde, 

Yelkenlerin fayda etmez yakın geleceğe. 

Kapılırsın sende kuzey rüzgarlarına, 

Avare dolanırsın yılların ardından, 

Her limana demir atarsın yokluktan, 

Nereye sığınacağını şaşırırsın korkudan. 

Yıldızlar artık sana görünmez geceleri, 

Tozpembe hayallerin tozu kalır aklında, 

Kabusa dönüşür hayatın biranda, 

Acıdan kıvransanda çıkmaz olur sesin, 

Mutsuzluklar taht kurar bedeninde, 

Düşenin dostu olmaz ya dizginler vururlar sırtına, 

Bedelini ödersin birgün yalnızlık denizinde.', 'Kendini çok güvende hissetsende,  Bir gün sende düşersin yalNızlık denizine,  Denizin içinde sağlam bir gemi olsanda,  O dalgalar sert bir k...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-denizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın şerefine', 'ayriligin-serefine-vedat-okkar-ll4mw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla sevginin bile değerinin bilinmediği, 

Gündüzün karanlığı çökmüş bu dünyaya, 

Oysaki canımı verdim ben sana hediye, 

Benim bir damla sevgim canımdır diye, 

İçin başka, dışın başka, 

Başkalaşım yaşıyorsun bu dünyada, 

Başkalarıyla... 

Bana bir tek seni sevdim diyordun, 

Başka bir aşk bana haram diyordun, 

Ne oldu şimdi neden değiştin, 

Senin gibi yalancı dünyayı seçtin, 

Benim için belkide tektin, 

Sense ihanet ettin, 

Af edilmeyensin. 

Tatlı dilinde ki numaralarla, 

Alemi kendine hayran edersin, 

Yalanın anlaşılır, 

Bir gün sende kem gözlere gidersin, 

Bir anlam değil, 

Sadece ezbersin. 

Aşksız aşkları bilirmisin sen, 

Orada sevmenin tadı hep acıdır, 

Bırakacak gibide değil ki meret, 

İçtikçe içilesi gelir 

Şişenin dibine ihanet düşünce, 

Sarhoşluktan uyanırsın, 

Yinede içiyorum, 

Ama bu sefer ayrılığın şerefine.', 'Bir damla sevginin bile değerinin bilinmediği,  Gündüzün karanlığı çökmüş bu dünyaya,  Oysaki canımı verdim ben sana hediye,  Benim bir daml...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayriligin-serefine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 06:55', 'saat-06-55-vedat-okkar-sxvms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '06:55 

Bu sabah yeniden rastladım sana, 

Yediye beş kala taksim otobüsünde, 

Sen oturdun sanki sana ait olan yerine, 

Bense sadece hayaller içinde, 

Senin gözlerinde, 

Düşlerinde. 

Bakışların ne kadar gizemli, 

Başka dünyalara götürüyor beni, 

Sonsuz bir uçurumdan düşer gibi, 

Ama mutluluk verici, 

Belkide geçici. 

Yarın sabah yine bekliyeceğim seni, 

Yediye beş kala aynı yerimde, 

Karşılıklı başka dünyalara gidercesine, 

Gözlerimizde ki anlamlı ifadelerle, 

Gözlerimizi kırpmadan, 

Nefessiz kalırmışçasına, 

Taksim otobüsünde.', '06:55  Bu sabah yeniden rastladım sana,  Yediye beş kala taksim otobüsünde,  Sen oturdun sanki sana ait olan yerine,  Bense sadece hayaller ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saat-06-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-vedat-okkar-cn7x7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki dakikada geçen hayat, 

Çok bayat, 

Oyun oynamak kolay, 

Yenilmemektir olay. 

Hisler herşeydir bazen, 

Hislerede rest çekerler, 

Bazen pat kalırsın oyunda, 

Bazende pat diye ortalarda. 

Şah ayakta kalırsa kazanırsın oyunu, 

Şah''ın da çoğu zaman üzgün durumu, 

Ayakta dır oyunda, 

Neye yararki, 

Kalesini fethettikten sonra, 

Atın''da bir ayağı çukurda, 

Fil kalmış ortalarda, 

Piyonları önden yolladık kale uruna, 

Vezirinin yok oluşu yıkar Şah''ı', 'İki dakikada geçen hayat,  Çok bayat,  Oyun oynamak kolay,  Yenilmemektir olay.  Hisler herşeydir bazen,  Hislerede rest çekerler,  Bazen pa...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyun-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özler Arzularım', 'seni-ozler-arzularim-huseyin-ozan-ozturk-lix2q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başımyastığa değince,

Seni özler.arzularım.

Uzun hayaller boyunca,

Seni özler arzularım.

Aşk dediğin,azgın bir sel.

Tanımıyor hiçbir engel.

N''olur bari rüyama gel.

Seni özler,arzularım...

Lale, sümbül,çiğdem,ıtır..

Renk renk seni hatırlatır.

Mektüp mektüp,satır satır; 

Seni özler arzularım...

Gözlerim yaşlı,bağrım hun,

Mecnun gibi sana tutkun,

Öyle garip,melul,mahzun; 

Seni özler arzularım.

Arzularım çağlar gibi,

Öksüz öksüz ağlar gibi.

Yıkılası dağlar gibi,

Seni özler arzularım.

Bülbül gibi gonca güle,

Tutulmuşum bile bile,

Kara toprak olsam bile,

Seni özler arzularım..', 'Başımyastığa değince, Seni özler.arzularım. Uzun hayaller boyunca, Seni özler arzularım. Aşk dediğin,azgın bir sel. Tanımıyor hiçbir engel. ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-ozler-arzularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / BULUNSUN', 'bir-dortluk-de-sen-yaz-bulunsun-siir-perisi-grubu-fituz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/BULURSUN'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

Umudun hiç bitmesin dalgalansın ruhunda 

Adını sonsuza dek ÖVENLERİN bulunsun 

Varlığın sen yok iken algılansın ruhunda 

Öldüğünde ardında SEVENLERİN bulunsun...................(Ayak dörtlüğü)    Mehmet TEKECİ 

1. 

Hayat denen sahnede oynadığın oyunu 

Şerefinle bitir git yad etsinler soyunu 

Hayran olsun melekler gördüğünde huyunu 

Öldüğünde dizini DÖVENLERİN bulunsun.....................Mehmet TEKECİ 

2. 

Öyle güzel ülke ki yaşadığın bu yerler 

Değerini bilmezsen elbet göz diker eller 

Övün çalış güven ki düşmanlar çekinsinler 

Canlandır umutları SEVENLERİN bulunsun...................Metin Yaltı 

3. 

Sev! ... Sevil! ... Güler yüzle, çevrene mutluluk saç! 

İçten ve yüreklice, dostluğa uykunu aç! 

Kardeşlik, birlik için, çekinmeden serden geç! 

Gecenden kâbusları KOVANLARIN bulunsun...................Turan Orak 

4. 

Kim içten, kim değildir? Sorgulama inatla. 

Dostun çekip gitse de, barışık ol hayatla. 

Dürüstlük ve sevgide ısrar et ki sebatla, 

Ardından düşmanına SÖVENLERİN bulunsun...................Feride Özmat 

5. 

Başkalaşıp değişme, mukayyet ol rengine, 

Davul bile çalıyor, her dem dengi dengine. 

Adam gibi olanı yaren eyle kendine, 

Sana gelen belayı, SAVANLARIN bulunsun...................Mustafa Erkenekli 

6. 

Derlerse bu tepeye neyle, nasıl çıkılsın? 

Basamak olma sakın, bıkılırsa bıkılsın 

İşe yaramaz olma, umut ile bakılsın 

Ne kadar çorak olsan GEVENLERİN bulunsun.................Zülfikar Yapar Kaleli 

7. 

''Ne bir yaprak ne bir kuş, gülmeyi de unutmuş. 

Karamsarlık altında, zehir ettin ömrün kış. 

Neden yüreğin sızlar, neden gönüller susmuş? 

Uzak dur sitemlerden, SEVENLERİN bulunsun................Suna Doğanay 

8. 

Gözlerinden ışık saç, gece korksun gözünden 

Namert yürek titresin, mert dilinden sözünden 

Pusatlan sevda ile, yansın namlu közünden 

Kurşun at karanlığa, KOVANLARIN bulunsun.................İmdat Özcan 

9. 

Bir kuşun kanadında, güneşe benze ruhum 

Semaları kat be kat, çevreleyip sar bu gün 

Hüzün silinsin gayrı, isyanını perdele, 

Her ihtiyaç anında, MUTLULUĞUN bulunsun..................İlknur Sezgin 

10. 

Can içre canım deyip yoluna can koyanlar, 

Göklerde görüp seni benimsin ya diyenler, 

Sensiz olur mu deyip yoluna can verenler, 

Ay yıldıza sarılıp GÜLÜMSEYEN bulunsun...................SERAP HOCA 

11. 

Düşmanın her kimse o da senin gibi insan, 

Uzak dur şer mahalden her zaman eyle ihsan, 

Akmasın gözyaşları kötülüğe verme meydan, 

Sendeki bu cevheri ÖVENLERİN bulunsun....................İsmail Doğan 

12. 

Kırılsın baş örtüme uzanan alçak eller, 

Kaç vakittir hep böyle, zalim esti bu yeller. 

Ahlak düştü çukura, iffet bu yüzden terler, 

Bu derdin hesabını, SORANLARIN bulunsun..................Ali Hışıroğlu 

13. 

Kendin ol kendin görün, sev gönlünce gülşeni 

Etrafına neşe saç, al payına düşeni 

Bu gün var yarın yokuz, eşeleme eşeni 

Savur neşelerini SEVENLERİN bulunsun.....................Sevim E.Tezel 

14. 

Bil ki el uzatmadı örtüne kimse senin 

Siyasetine bayrak ettiğin güne değin. 

Ay yıldızlı al şalım tek örtün olsun senin 

Sahip çık ki üstüne ÖRTENLERİN bulunsun..................Metin Yaltı 

15 

Ver yetimin rızkını, yitik umutlarından 

Der gülleri gönlüne, arşa çıkmış beyazdan 

Vakti zaman gelince,gül dua olur nurundan 

Öldüğünde ardında, YADEDENLER bulunsun...................Özlem Gökdem 

16. 

Şair olup bulunsun adın yıllar sonraya 

metanetin bulunsun göğsün sanki bir kaya 

Şiirlerin bilerek heceyi saya saya 

Birkaç asır sonraya DİVANLARIN bulunsun..................Samet Mehmet Bora 

17. 

Yaratandan ötürü sevmek gerek insanı 

Hayatta huzur için hoş tutmalı her canı 

Öfke dolu olsan da bırakma ki izanı 

Halini, hatırını SORANLARIN bulunsun.....................İbrahim Usta 

18. 

Bayrak olmadan asla, alnım gelmez secdeye 

Hürriyet alemimdir, Vatanım dan Mekke’ye 

Nice kanlar döküldü, sor/sana acep niye? 

Sırtını Şehitlerden, OVANLARIN bulunsun...................ORKUN IŞIK 

19. 

Soysuz kahpeye inat, övün,yücelt soyunu 

Rum veya Gürcü olan bilmez senin boyunu 

Gel sen de tut elimden,bozalım bu oyunu 

Milletini çok sevdi,DİYENLERİN bulunsun...................Saim Bastık 

20. 

sorulmaz sorularda bir gün derde girersen 

onulmaz cefalarda bir gün zora gelirsen 

çalınmaz kapılarda bir gün dara düşersen 

gözlerindeki yaşı SİLENLERİN bulunsun..................... Ali Işık 

21. 

Diriliş tonu gökler mavisi bizi bekler 

Vatan ağlar sessizce üstümüze hep titrer 

Eller ruhsuz bedensiz eller bağrında işler 

Desen desen ağları SÖKENLER hep bulunsun! ...........K.Çağlar Aksu 

22. 

Hazanın yaprakları dökülürken yerlere 

Yağmurun serinliği vurur iken günlere 

Hasretinin yaşları dolar iken gözlere 

Beklediğin yoldan GELENLERİN bulunsun........... Serpil Doğan 

23. 

Hoşgörüsüz nazarda hırçın vahşilik başlar. 

Sevgi erir de sabit fikir beynini haşlar. 

Bir söz et ki çıkmasın torbadan arsız taşlar. 

Adamlık aleminde ÖVENLERİN bulunsun..............Necmi ÜNSAL', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/BULURSUN'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun Şİ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-bulunsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağım', 'topragim-mihrican-karaca-y6pjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlıktırki yaşıyorum

                          Bu kadar kalabalıkta.

Kimseye çarpmadan

                          Dolaşıyorum.

Ben böyle değildim

                          Eskiden

Ben böyle değildim

                          Seninleyken.

Saatler yalnızlığı vurduğunda

En acı zehirleri,içer oldum.

Yana yana

Yandığım

Zehirlerin acısı değil,

                             Sensizliğin

                             Ayrılığın

                                 Ve

                             İhanetinin

                             Acısıydı

                             Toprağım...', 'Bir yalnızlıktırki yaşıyorum                           Bu kadar kalabalıkta. Kimseye çarpmadan                           Dolaşıyorum. Ben bö...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/topragim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yiğit aranıyor..!', 'bir-yigit-araniyor-i-lhami-arslantas-nv8he', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ankara’da haklarımız çalınır,

Fukaralar kaz misali yolunur,

Acep buna nasıl sessiz kalınır,

Yok mu buna dur diyecek bir yiğit? 

Göç eyledi fakir kalan bölgeler,

Başımızda duran bizi gölgeler,

Bu milletten gizleniyor bilgiler,

Yok mu buna ver diyecek bir yiğit? 

İstesek de dönemeyiz köylere,

Umutları kurban ettik beylere,

Çerez olduk meze olduk meylere,

Yok mu buna şer diyecek bir yiğit.

Halk aynaydı kırıp döküp attılar,

Haklarının üzerine yattılar,

Sendikalar işçisini sattılar,

Yok mu buna kör diyecek bir yiğit? 

 Der İlhami dirlik düzen bozuldu,

Gözlerimden kanlı yaşlar süzüldü,

Mezarımız gurbet ele kazıldı,

Yok mu buna ar  diyecek bir yiğit?', 'Ankara’da haklarımız çalınır, Fukaralar kaz misali yolunur, Acep buna nasıl sessiz kalınır, Yok mu buna dur diyecek bir yiğit?  Göç eyledi f...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-yigit-araniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmalısın', 'alismalisin-mihrican-karaca-r7sop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben cansam,sende canan

İkimizde yandık,tüttü duman.

Beni yaraladın,kalmadı güman

Sen bensiz yaşamaya alışmalısın.

Bilmem eller bize ne söyler,

Söylerde hemde hasını,ama kimler.

Ben gibi birgün onlarda dize gelirler

Oğulsuz,karısız yaşamaya alışmalısın.

Suç bende değil hep,birazda sende

Karını bırakıpta,ne gezersin ellerle.

Ömrümü ne hayallerle süslemiştim ben,

Ansızın çıkıp karşıma,altüst ettin sen.

Birde rahat durmayı denesen,

Bu yaştan sonra doğruluğu öğretemem.

Sen üzülme,ben gidip karını getirem

hemen sevinme,yol parası senden.

Yalnız gelmiyor kaynananda hediyen,

Bundan sonrada

Sen bensiz yaşamaya alışmalısın.', 'Ben cansam,sende canan İkimizde yandık,tüttü duman. Beni yaraladın,kalmadı güman Sen bensiz yaşamaya alışmalısın. Bilmem eller bize ne söyle...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alismalisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-mihrican-karaca-idyjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahane edip aşkı

Beni ip üstünde oynattın.

Ne yalanlarla dolanlarla,

Gönlümü ayarttın.

Aslında ben doğruya değil,

Yalanlara inanmışım.

Kendini bana, pamuk ipliğiyle bağlamıştın

vedasız gidişinle

Bir kuş misali yaralamıştın.

Değermiydi sence kanamalara,

Değerdi bence

Çünki onun adı AŞKTI.

Şimdi bende bir tutku yarattın

Adını koyamadığım bir tutku.

Düşünmeden,konuşmadan

Sevmeden değilde; 

Seni yaşamadanda

Yaşıyorum...', 'Bahane edip aşkı Beni ip üstünde oynattın. Ne yalanlarla dolanlarla, Gönlümü ayarttın. Aslında ben doğruya değil, Yalanlara inanmışım. Kendi...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tutku-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım', 'umutlarim-huseyin-ozan-ozturk-y5fh8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Renk renk umutlarım kelebek gibi,

Ha açtı açacak bir çiçek gibi.

Özlemle gözlerim mor ufukları; 

Mutluluk perisi gelecek gibi', 'Renk renk umutlarım kelebek gibi, Ha açtı açacak bir çiçek gibi. Özlemle gözlerim mor ufukları;  Mutluluk perisi gelecek gibi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umutlarim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Severim....', 'seni-cok-severim-muzaffer-alcinkaya-qubmn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni çok severim 

Ama anlamazsın beni

Seni o kadar çok severim ki

Dağları, cihanı ayağının altına sererim

Bilirsin artık benim seni ne kadar sevdiğimi.....

(08.01.2006 / Mert Külçür)

10 yaşındaki yeğenimden bana........', 'Seni çok severim  Ama anlamazsın beni Seni o kadar çok severim ki Dağları, cihanı ayağının altına sererim Bilirsin artık benim seni ne kadar...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Alçınkaya']::text[], 8.5, '{"poet":"Muzaffer Alçınkaya","poet_slug":"muzaffer-alcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-cok-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedduam Oldun', 'bedduam-oldun-mihrican-karaca-rv0x2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen değilmiydin en çok seven,

Sen değilmiydin,daha çok isteyen.

Tam girmişken herşey yoluna,

Barikatlar kurdun yollarıma.

Ulaşılmazdım,ulaşamadında

yaklaşmıştın,bir adı kala.

En büyük bedduam oldun,

Sonunda layığını buldun.

Sanmamki mutlu oldun...

Dilerim hayatında,asla gülme

Benden baskasınıda yarin bilme.

sakın bunlara kader deme,

Sen kaderini kendin çizdin,

benide düşman bilme.

Belki gün olur,konuşuruz sadece

hesabını sorarım,

Tabi

Verecek hala cevabın varsa.', 'Sen değilmiydin en çok seven, Sen değilmiydin,daha çok isteyen. Tam girmişken herşey yoluna, Barikatlar kurdun yollarıma. Ulaşılmazdım,ulaşa...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bedduam-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahvı viranım', 'mahvi-viranim-ali-riza-unal-6jpc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açılsın sineye yüzünün mahı,

Yetmezmi can bedel aşığın ahı,

Sevenin sevene çölmüdür vahı,

Lâl oldu dilim mahvı viranım,

Saçılsın dideye zülfü siyahın,

Ellere perde bana ayan nihanın,

Ehline ne günah cürmü haramın,

Zâl oldu halim mahvı viranım.', 'Açılsın sineye yüzünün mahı, Yetmezmi can bedel aşığın ahı, Sevenin sevene çölmüdür vahı, Lâl oldu dilim mahvı viranım, Saçılsın dideye zülf...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mahvi-viranim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Ettin', 'zehir-ettin-mihrican-karaca-mb0sh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saklıyor ıssız geceler acılarımı,

Tan ağartısıyla,yoksa yansır mı? 

Kalbim mutluluğu birgün bulacak mı

Gün olup dostlarım halimi soracak mı? 

Sızlamakta içimdeki bu yürek,

Beklenmekte ölümüm,hazır kazma kürek.

Birtek ismimi,mezar taşım zikredecek,

Beni sen bile anlamadın,kimsede anlamayacak.

Seni sevmekte,hata yaptım galiba,

Giderken sormadın,şimdi hiç arama.

Birileri vardı deyip adımı,sakın anma

Acaba gelirmi diye,yollarıma bakma.

Sevilmeye değmezmişsin oysa,

Sensiz ömek mi,olamazdı asla

Bak yine hayatı,zehir ettin bana.', 'Saklıyor ıssız geceler acılarımı, Tan ağartısıyla,yoksa yansır mı?  Kalbim mutluluğu birgün bulacak mı Gün olup dostlarım halimi soracak mı?...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zehir-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz''im Benim Sevdam Sana', 'karadeniz-im-benim-sevdam-sana-umut-gungor-zblje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyısında Şamil''imi büyüten,

Dalgasında Osmanları yürüten,

Öfkesiyle düşmanları kürüten,

Karadeniz''im benim sevdam sana.

Bir kızdımı bulutları karartan,

Kötülerin şafağını sarartan,

Korku ile yüzlerini morartan,

Karadeniz''im benim sevdam sana.', 'Kıyısında Şamil''imi büyüten, Dalgasında Osmanları yürüten, Öfkesiyle düşmanları kürüten, Karadeniz''im benim sevdam sana. Bir kızdımı bulutla...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karadeniz-im-benim-sevdam-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Oldum', 'kor-oldum-ramazan-ates-owboj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Kayseri’li Ama Ozan Ömer Kadan’a)

Kör oldum ben, kör oldum,

Acılardan kör oldum.

Mutluluğu tatmadan,

Çilelerden kör oldum.

Gençtim geldim gurbete,

Güvendim ben herkese,

Onlar attı ateşe,

Hilelerden kör oldum.

Kimse dostum olmadı,

Ondan yüzüm gülmedi,

Doktor fayda vermedi,

Ağlamaktan kör oldum.

Doğru bildim yaşadım,

Eğrilere şaşardım.

Saz çalmayı başardım,

Çala çala kör oldum.

Ozan dediler bana,

Kul oldum Yaradan’a,

İsyanım yoktur haşa,

Kaderimdir kör oldum.

O istedi kör oldum.

Ramazan Ateş/Enschede-23.05.1999', '(Kayseri’li Ama Ozan Ömer Kadan’a) Kör oldum ben, kör oldum, Acılardan kör oldum. Mutluluğu tatmadan, Çilelerden kör oldum. Gençtim geldim g...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kor-oldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Veya Sen', 'olum-veya-sen-muhammet-umut-dilek-215b6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ölüm bir kahpe hançer

bekler düşlerimi

ama ben yine korkmam ondan

yok edemez gülüşlerimi

...

dünyam bir özge candır

bana hesabı hatırlatan

düşlerimi yıkayan akmayan kandır

bana terkedenlerin alayıyla bakan

hasret bir yıldırımdır böler bedenimi

yarım kalan sevgiler kaplar düşlerimi

sensiz olmuyor ah sevgili

sensizlik sarınıyor kefenimi

yaşayamam bilirim yaşayamam sensiz

bak kalakalmışım kimsesiz

nefes alan bir nölüyüm tenimde kar beyazlığı

gel gel ne 0lur gel

bitirmeliyim bu mezar yalnızlığını...

muhammet umut dilek', 'ölüm bir kahpe hançer bekler düşlerimi ama ben yine korkmam ondan yok edemez gülüşlerimi ... dünyam bir özge candır bana hesabı hatırlatan d...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olum-veya-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde', 'nerde-serhat-caliskan-7pp07', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşuna,yaşamışım yirmibeş yılı

Çalıp çırpmak lazımmış bilmedim işi

Asalet,dürüstlük,mertlik birkaçı

Uğruna aç kaldığım değerler nerde

Lakap taktılar gariban diye

Aşklarda bile geçti önüme

Boyun eğmedim,hiçbir zalime

Yolbirliği ettiğim garipler nerde

Elbet bizede uğrar dediğim

Kul sıkışmayınca gelmez dediğim

Zevk,sefa,lüks değil,em istediğim

Aleyhsselamı-hızırlar nerde', 'Boşuna,yaşamışım yirmibeş yılı Çalıp çırpmak lazımmış bilmedim işi Asalet,dürüstlük,mertlik birkaçı Uğruna aç kaldığım değerler nerde Lakap ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerde-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Yapraklım', 'yesil-yapraklim-onur-bayrakceken-wpc5p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Etrafında koşuştururken,

Sanki bize gülümsüyordun.

Yeşil yapraklarınla

Bize sevgi dağıtıyordun…

Her zil çalışında,

Gelirdik senin yanında,

Ah benim yeşil yapraklım…

Bir gün okula gelince,

Seni yerinde göremedik.

Meğer kesmişler seni,

Ah benim yeşil yapraklım…', 'Etrafında koşuştururken, Sanki bize gülümsüyordun. Yeşil yapraklarınla Bize sevgi dağıtıyordun… Her zil çalışında, Gelirdik senin yanında, A...', ARRAY['Türk Edebiyatı','Şiir','Onur Bayrakçeken']::text[], 8.5, '{"poet":"Onur Bayrakçeken","poet_slug":"onur-bayrakceken","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yesil-yapraklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Yakınken Gez Memleketi', 'yol-yakinken-gez-memleketi-onur-bayrakceken-fv8vc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne güzeldir memleketim,

İstanbul’dan Artvin’e,

Edirne’den Kars’a,

Tekirdağ’dan Van’a…

Sedir Adası ve Gökova’yı

Gezmeden olur mu hiç? 

İncecik ve pırıl pırıl kumuyla,

Ne güzel Sedir Adası…

Yol yakınken gez memleketi,

Gör Anadolu’yu,

Gör Efes’i

Gör! 

Gör binlerce yiğidin kan döktüğü Çanakkale’yi!', 'Ne güzeldir memleketim, İstanbul’dan Artvin’e, Edirne’den Kars’a, Tekirdağ’dan Van’a… Sedir Adası ve Gökova’yı Gezmeden olur mu hiç?  İnceci...', ARRAY['Türk Edebiyatı','Şiir','Onur Bayrakçeken']::text[], 8.5, '{"poet":"Onur Bayrakçeken","poet_slug":"onur-bayrakceken","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yol-yakinken-gez-memleketi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Conk Bayırı''nda', 'conk-bayiri-nda-onur-bayrakceken-p18ge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Conk Bayırı’nda bir sessizlik; 

Yaklşatı Mustafa Kemal Paşa düşmana,

Kaldırdı kampçısını havaya,

O anda yükseldi Conk Bayırı’nda; 

“Allah! Allah! ” sesleri.

Parladı süngüler

Kurşunun bittiği yerde! 

Mehmetçik düşürdü düşmanı derde…', 'Conk Bayırı’nda bir sessizlik;  Yaklşatı Mustafa Kemal Paşa düşmana, Kaldırdı kampçısını havaya, O anda yükseldi Conk Bayırı’nda;  “Allah! A...', ARRAY['Türk Edebiyatı','Şiir','Onur Bayrakçeken']::text[], 8.5, '{"poet":"Onur Bayrakçeken","poet_slug":"onur-bayrakceken","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/conk-bayiri-nda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-38 (M.S.) 07/01/2006', 'mektuplar-38-m-s-07-01-2006-mahzun-doga-mkn6q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni nasıl özlesem.

Nasılını hatırlasam senin.

Ki nasıl doğrasam sabrımı.

Bölüşsem ellerine.

Bakışlarına yapıştırsam.

Bir parça tenine eklesem.

Bölebilsem sabrımı her yerine.

Seni.

Nasıl.

Özlesem.

Bilsem.

Bilmiyorum.

Ya da bilmek diye bişeyi yok bunun.

''Seni sevmek...Seni sevmek işte! ''

Seni özlemek... Seni özlemek işte! 

Başka bir anlattığım yok ey anladığım.

Başka bir anlayanım yok ey anlatanım.

Bazen öyle basit.

Bazen ulaşılmaz ve güç.

Kimi de yabancı bir anlatıcısı oluyorum bu özlemin.

Ve ne kadar yitirsem yalnızlığı, 

o kadar yapayalnızlık oluyorum.

Yani ne kadar karışsan bana,

onca da tek kalıyorum.

Tek oluyoruz.

Ama uzak.

Çok uzak.

Uzansa da bazen ömrümüz,

yetişemiyoruz.

Yani şimdi ve öyle basit değil.

Seni.

Nasıl.

Özlesem.

Anlamsız kıldığımız anlamsızlıkları anlamlı kılıyor özlem denen bu illet.

Yapışıyor canımın her bir noktasına.

Kaç gülüşün olsa da zulamda,

yapışıyor yüzüme bu korkunç rezalet.

Ve kızıyorsundur bana.

Oysa ben o kadar çok kızmışım ki kendime.

Faydası en faydasız faydasız.

Yabancısı olmasak da bu yabanın.

En az tanıdığı oluyoruz kimi zaman.

Ne çok bilsek de inancın gücünü.

En güçsüzü oluyoruz bazen.

Ve ne sen anlayabiliyorsun bunu.

Ne de ben.

Sadece ikimiz biliyoruz.

Sen yine de ki bana:

''Seni sevmek...Seni sevmek işte! ''

Ben de diyeyim ki:

Seni özlemek... Seni özlemek işte!', 'Seni nasıl özlesem. Nasılını hatırlasam senin. Ki nasıl doğrasam sabrımı. Bölüşsem ellerine. Bakışlarına yapıştırsam. Bir parça tenine ekles...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/mektuplar-38-m-s-07-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafayı Yiyeceğim', 'kafayi-yiyecegim-ramazan-ates-oqlhk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalemi kırsam diyom,

Düzeni kursam diyom.

Usandım bu hayattan,

Çabuk kurtulsam diyom.

Ağlasam fayda vermez,

Çağırsam benle gelmez,

Bu düzen bana uymaz

Çabuk kurtulsam diyom.

Ölümde çare belki,

Başka kurtuluş yokki,

Dizimde derman bitti,

Hemen kurtulsam diyom.

Dost yok ki tutunayım,

Paylaşıp kurtulayım.

Yalnızım, yalnız kaldım,

Kaçıp kurtulsam diyom.

Kafayı yiyeceğim,

Ak gömlek giyeceğim,

Başka ne diyeceğim,

Ölüp kurtulsam diyom.

Ramazan Ateş/Enschede-1995', 'Kalemi kırsam diyom, Düzeni kursam diyom. Usandım bu hayattan, Çabuk kurtulsam diyom. Ağlasam fayda vermez, Çağırsam benle gelmez, Bu düzen ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kafayi-yiyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-39 (M.S.) 08/01/2006', 'mektuplar-39-m-s-08-01-2006-mahzun-doga-m7yf8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günler saklanarak geçiyor önümüzden.

Utanmaktan ne anlar şu berbat saatler.

Nerden akıl etsin aramızı boşaltmayı şu aptal yollar.

Ne halt ediyor bu yaşamak.

Bu iğrenç şiir ne anlatıyor.

Bu zavallı kelimeler.

Noktalar.

Satırlar.

Kim yazdırıyor bu felaketi.

Bu masum aklığa yazılan ne.

Neden! 

Kızılmayacak kaç anımız var ki.

Hangisi haketmiyor parçalanmayı.

Yaşamak hangisinin hakkı! 

Bütün öfkemiz adil.

Ve bütün yaptığı rezil şu zamanın.

Ne anlatıyor bu adi gerçekler.

Senin aslını istiyorum artık.

Ne saçmalıyor hayaller.

Aslının aslını istiyorum artık.

Biz sustukça, 

sapıtıyor bu sabır.

Şımarmasın artık hiçbir dilek.

Nazlanan bütün umutların canı cehenneme.

Umrumda değil artık hiçbir iyi niyet.

Zaman bozulmuş, durmuş.

Hatta geriye götürüyor bizi birbirimizden.

Değiştirmek gerek bütün dakikaları.

Ve sana koşmalılar durmadan.

Değiştirmeli günü güneşi.

İkisi de yaşlanmış.

Ölüp yeniden diriltmeli yaratan.

Seni sakin sevmeli.

Ve hırçın özlemeli.

Sende sakin durmalı.

Ve beklemeden beklemeli.

Seni Sakin yaşamalı.

ve durmadan ölmeli.

Yalan söylüyor bütün evren.

Oyalıyorlar bizi.

Çıldırmak gerek.

Durmadan koşmak gerek.

Kandırıyor bizi bütün insanlar.

Anlamamak gerek onları.

Bu biletleri kim çıkardıysa asmalı.

Lime lime doğrayıp sermeli yollara.

Yolculuklara ibret olmalı.

Yıkıp geçmek gerek bütün sınırlarını.

Bozuk çalıyor bütün şarkılar.

Atlar mavi koşamıyor.

Kuşlar ötemiyor.

Yeşil yeşeremiyor artık.

Herşey yıkılmalı. 

Şu özürlü satırları da yıkmak gerek.

Bu aptal şiiri yakmak.

Yakmak.

Yak.', 'Günler saklanarak geçiyor önümüzden. Utanmaktan ne anlar şu berbat saatler. Nerden akıl etsin aramızı boşaltmayı şu aptal yollar. Ne halt ed...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/mektuplar-39-m-s-08-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanardağdan Beter', 'yanardagdan-beter-osman-erdogmus-24dow', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tugay’a)

hava güneşliydi 

ve de sıcaktı 

nasılsın diye dokunsam 

belki de ağlayacaktı. 

Sevgi ile yoğrulmuş yüreği 

Damarlarına pompaladığı aşktı 

Kader örmüştü ağını 

Girdi bir güzelin gönlüne 

Sevinci ayaklarına vurmuştu 

Yürümüyordu sanki 

Neredeyse uçacaktı. 

Umutlar geleyana gelmişti 

Heyecanlar dorukta 

Ve düğün vardı ufukta 

Hayalin sınırı yok ki 

Gönül sarayını kurmuş 

Prensesini de oturtmuş tahta 

Ve hatta 

Çocuklarına isim bile bulmuştu 

Kız olursa Şirin 

Erkek olursa Ferhat koyacaktı. 

Nereden bilecekti ki 

Prensesini doğuranın 

Ve anne demeğe hazırlandığı kadının 

Kalbi kararmış 

Bahtı kararmış 

Her şeyiyle karalara bürünmüş 

Kara basan gibi 

Karşısına çıkacaktı. 

Musibetti bu 

Bir belaydı 

Ya kahırdan dağlara çıkacaktı 

Yada içine ata ata 

Sıkıntıdan genişleyen kalbi 

Yanardağdan beter 

Patlayacaktı. 

Ölüm mukadder elbet 

Bir gün herkesi bulacaktı 

Belki de kimisi için ölüm 

Izdırap ve sıkıntılardan kurtuluş 

Dertlerin bitişi 

Hasretin ve ayrılıkların 

Sona erdiği bir başlangıç olacaktı. 

Ey Rahmeti gazabını geçen Rabb’im 

Senin için zorluk yok 

Kalplere de hükmeden sensin 

İstediğine 

İstemeden de verirsin 

Kalpleri karalara 

Yürekleri katılara 

Sevgi ırmaklarından bir nebze olsun akıt 

Dile gelsin zalimler 

Coşsun sevenler,sevilenler 

Tutuşsunlar el ele 

Versinler gönül gönüle 

Hicret etsinler güneşe. 

Osman Erdoğmuş 

Aşk İklimi 

kitabından alınmıştır', 'Tugay’a) hava güneşliydi  ve de sıcaktı  nasılsın diye dokunsam  belki de ağlayacaktı.  Sevgi ile yoğrulmuş yüreği  Damarlarına pompaladığı ...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yanardagdan-beter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbetti Vesselam', 'sohbetti-vesselam-eyup-gok-lnv72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selam ey penceresinden baktığım

Herşeyiyle yaban hayat

Öylece kal, ne sen beni

Ne de ben seni kollayayım

Bu süreç böyle gelmiş

Bırak gitsin öyle

İkimizde mana bulamadık

Fakirdi bu sevgi

Lakin zararımız ne ola ki

İlk ve son arzum olsun

Ne olur tebessüm et

Bu son olsun', 'Selam ey penceresinden baktığım Herşeyiyle yaban hayat Öylece kal, ne sen beni Ne de ben seni kollayayım Bu süreç böyle gelmiş Bırak gitsin ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sohbetti-vesselam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşçi Tarık', 'i-sci-tarik-gultekin-mustafa-hv0yg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'omzunda ağır levent işçi tarık’ın

aklında yirmi beş kuruş

gözünde çocukluk

bileğinde plastik saat

yürüyor makinelerin arasında

omzunda ağır levent 

aklında yirmi beş kuruş

bir karısı, iki çocuğu, bir muhabbet kuşu

çok komşusu, çok çamuru, çok borcu var

bir kendine, bir geceye, bir gündüze

bir de bankalara bıkkın

kirden grileşmiş de olsa

eski bir kaşkolu var

omzundaki ağırlık işçiliğinden; 

hem işçi hem baba olmanın

üzerinde delik hırkası,

dişlerinde efkarın tortusu var

yürüyor ağır, işçi tarık, 

omzunda ağır levent

aklında yirmi beş kuruş var', 'omzunda ağır levent işçi tarık’ın aklında yirmi beş kuruş gözünde çocukluk bileğinde plastik saat yürüyor makinelerin arasında omzunda ağır ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isci-tarik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayan Yuregim', 'dayan-yuregim-sair-babaxyorgun-vkhqn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birgün geldim taa uzaklardan

Yorgunmu desem üzgünmü yoksa

Usandım ben bu duygularımdan

Aşkmı desem nefretmi desem', 'Birgün geldim taa uzaklardan Yorgunmu desem üzgünmü yoksa Usandım ben bu duygularımdan Aşkmı desem nefretmi desem...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dayan-yuregim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim 1', 'efendim-1-sair-babaxyorgun-t2dlz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'EFENDİM1

o©º°¨¨°º©o©º°¨¨°º©o

içimdeki sızı hasret sızısı

Yıllarım gurbette geçti efendim

Silinmez alnımın kara yazısı

Yandı korlu yürek pişti efendim

o©º°¨¨°º©o©º°¨¨°º©o

Söyle doktor nerde hemşire hanım

Getir sedyeyi ezik her yanım

Gönderin silama çıkmadan canım

Derdimin çaresi geçti efendim

o©º°¨¨°º©o©º°¨¨°º©o

Yokmudur sizlerde dostluk yarenlik

Gönül saraylarım oldu örenlik

Dizlerim dermansız yollar karanlık

Güneşim erkenden aştı efendim

o©º°¨¨°º©o©º°¨¨°º©o

Garibim kimsem yok kapım çalacak

Yavrularım nerden haber alacak

Yoksa naaşım gurebettemi kalacak

İçime bir acı düştü efendim

o©º°¨¨°º©o©º°¨¨°º©o

Dertliyim doğuştan yüreğim yanık

Kederli hüzünlü yüzüm utanık

Aziz misafirim ezrail konuk

Titrer elim avcum şaştı efendim

o©º°¨¨°º©o©º°¨¨°º©o', 'EFENDİM1 o©º°¨¨°º©o©º°¨¨°º©o içimdeki sızı hasret sızısı Yıllarım gurbette geçti efendim Silinmez alnımın kara yazısı Yandı korlu yürek pişt...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/efendim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amir Efendi', 'amir-efendi-ali-dilki-el28c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Burda çok rahatım amir efendi

Gak derim su gelir, guk derim ekmek

İnsanlığım kalbim her şeyi yendi

Gak derim su gelir, guk derim ekmek

Kimse hakkımızı çalmıyor inan

Alınterim rafta kalmıyor inan

Bir dediğim iki olmuyor inan

Gak derim su gelir, guk derim ekmek

Seviniyormuşsun sürüldü diye

Sayemde defteri dürüldü diye

Başka bir kuruma verildi diye

Gak derim su gelir, guk derim ekmek

Sanmaki burda çok sıkılıyorum

Hep kafama göre takılıyorum

El bebek gül bebek bakılıyorum

Gak derim su gelir, guk derim ekmek

ALİ der; şaşırdın belki de buna

Yalakanla haber gönderdim sana

Tüm herkes çok iyi davranır bana

Gak derim su gelir, guk derim ekmek.', 'Burda çok rahatım amir efendi Gak derim su gelir, guk derim ekmek İnsanlığım kalbim her şeyi yendi Gak derim su gelir, guk derim ekmek Kimse...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/amir-efendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölduruyorsun', 'olduruyorsun-sair-babaxyorgun-orceb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÖLDÜRÜYORSUN

o©º°¨¨°º©o©º°¨¨°º©o

Dudakların silah sözlerin kurşun

Sözlerinle beni oldürüyorsun

Kaşların yay gibi saçın bir arşın

Gözlerinle beni öldürüyorsun

o©º°¨¨°º©o©º°¨¨°º©o

Hak özel yaratmış eşsizdir yapın

Gönül sarayında açıktır kapın

Cennet bahçesinden geliyor kokun

Nazlarınla beni öldürüyorsun

o©º°¨¨°º©o©º°¨¨°º©o

Güzelliğin sırrı çözülmez sende

Sevdanla hal mecal koymadın bende

Uçarsın göklerde melekten önce

Hazlarınla beni öldürüyorsun

o©º°¨¨°º©o©º°¨¨°º©o', 'ÖLDÜRÜYORSUN o©º°¨¨°º©o©º°¨¨°º©o Dudakların silah sözlerin kurşun Sözlerinle beni oldürüyorsun Kaşların yay gibi saçın bir arşın Gözlerinle ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olduruyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-sair-babaxyorgun-vgclz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DOSTLUK

o©º°¨¨°º©o©º°¨¨°º©o

ÖLENECE DEVAM ETMİYEN DOSTLUK

HER İKİ TARAFI CANDAN BEZDİRİR

KILAVUZU BOZUK OLAN BİR MUSLUK

DAMLA DAMLA YAŞLARINI SIZDIRI

o©º°¨¨°º©o©º°¨¨°º©o

DİLERİMKİ DOSTLAR DÜŞMAN OLMASIN

ARA BOZANLARIN YÜZÜ GÜLMESİN

YUMUŞ KARA GÖZÜN EĞMİŞ SÜRMESİN

İNSANLIĞI HAYALİNDE GEZDİRİR

o©º°¨¨°º©o©º°¨¨°º©o

İNSANDIR İNSAN CANINA KIYAN

ÖRNEK ERMENİSTAN YANI BAHÇIVAN

KIRAÇ YERE BOSTAN EKEN BAHÇIVAN

GÜZ GELMEDEN BAHÇELERİ BOZDURUR

o©º°¨¨°º©o©º°¨¨°º©o

YAZIK SARAY BOSNAM SIRPLAR EZERKEN

CENAZELER KAN GÖLÜNDE YÜZERKEN

TARİHE BİR KARA LEKE YAZARKEN

DERTLİ DERTLİ DESTANLARI DÜZDÜRÜR

o©º°¨¨°º©o©º°¨¨°º©o

HALİLİM DER NERDE İNSAN HAKLARI

ÖLEN  nahçıvan  ÇOCUK ÇOKLARI

ŞAD OLSUN O ŞEHİTLERİN RUHLARI

KAFİR SİZE TOPLU MEZAR KAZDIRIR

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'DOSTLUK o©º°¨¨°º©o©º°¨¨°º©o ÖLENECE DEVAM ETMİYEN DOSTLUK HER İKİ TARAFI CANDAN BEZDİRİR KILAVUZU BOZUK OLAN BİR MUSLUK DAMLA DAMLA YAŞLARIN...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dostluk-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-sair-babaxyorgun-9xbbq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

GÖNÜLLER ŞEHRİNE DOLANIP GİDEN

YOLUNDA ÇETİNİ VARDIR EFENDİM

MUHABBET EDERKEN İNSAN MESDEDEN 

DİLİNDE ÇETİNİ VARDIR EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

HEP KONUŞMAK İSTER SÖZLERİN BİLMEZ

TOPLUMA GİRMEMİŞ NİZAMA GİRMEZ

ŞERRE SOYUNANDAN BİR HAYIR GELMEZ

ELİNDE ÇETİNİ VARDIR EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

VARDIR BİR MANASI SINIR TAŞININ

AÇMA CIRCIRINI YARA DÖŞÜMÜN

BUZLARI ERİRSE GÖNÜL KIŞININ

SELİNDE ÇETİNİ VARDIR EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

ELİN AK YÜZÜNE KARALAR ÇALMA

SÖZLERİM NASİHAT KUSURA KALMA

DİBİ GÖRÜNMEYEN GÖLERE DALMA,

GÖLÜNDE ÇETİNİ VARDIR EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

KİMDİR HALİLİME NAME YAZDIRAN

MANASIZ SÖZLERLE YARAM AZDIRAN

MECNUNLARI SİNESİNDE GEZDİREN

            ÇÖLÜNDE ÇETİNİ VARDIR EFENDİM

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'EFENDİM o©º°¨¨°º©o©º°¨¨°º©o GÖNÜLLER ŞEHRİNE DOLANIP GİDEN YOLUNDA ÇETİNİ VARDIR EFENDİM MUHABBET EDERKEN İNSAN MESDEDEN  DİLİNDE ÇETİNİ VAR...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/efendim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Bahçeleri', 'umut-bahceleri-eyup-gok-1k09d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayata dair bütün anıların

Gelip de geçecek usul usul

Zahmetsiz süren tüm zamanların

Pişmanlığıydı aslında bu okul

Yada bahçesinde çiçekler koklanmamış

Ama bakımlı ve de sulanmış

Bir çiçek bir umut ise

Gerçekleşmeyen hayaller her neyse

Yaşanmışlar asıl yansıtır gerçeği

Değişmeyen ise umut bahçeleri

Oysa hayalimdeki gül yediveren

Yırtık bir resim değil an ve an

Yolun sonunda asa tek yoldaş

Ne gardaş ne de arkadaş

Umut ettiğimi geçmiş zaman

Yaşatmadı, yaşamayacak olan

Hülyalarda dolaşan

Bahçede ki adam ben.', 'Hayata dair bütün anıların Gelip de geçecek usul usul Zahmetsiz süren tüm zamanların Pişmanlığıydı aslında bu okul Yada bahçesinde çiçekler ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-bahceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gulum Odasi', 'gulum-odasi-sair-babaxyorgun-t6nfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÜLÜM ODASI

Daglar ruhhh der bagirir

Dostlar dostlari çagirir

Burdan herkes ses duyurur

Sesin baska Gulum odasi

Ablasi abisi yengesiyle

Apocani zekisiyle

Halobini sibeliyle

Bitanesin Gulum odasi

Odalarin zirvesidir

Sessizlerin sesidir

Sorun hele gelenlere

Kimin neyin nesidir

Daglar geldi hos geldi

Kar boran kis geldi

Mikrofon alip eline

Tüm Dostlara Selam verdi

Burdan herkes ses duyurur

Sesin baska Gulum odasi

Birtanesin Gulum odasi

Dostlarin Yuvasi Gulum Odasi

               o©º°¨¨°º©o©º°¨¨°º©o:               

                 BABAXYORGUN         

               o©º°¨¨°º©o©º°¨¨°º©o:', 'GÜLÜM ODASI Daglar ruhhh der bagirir Dostlar dostlari çagirir Burdan herkes ses duyurur Sesin baska Gulum odasi Ablasi abisi yengesiyle Apoc...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulum-odasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakar Bir Hayatın Yanılgılarının Bileşkesinde Yaşananlar', 'sakar-bir-hayatin-yanilgilarinin-bileskesinde-yasananlar-atilla-guler-7l1li', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cepkenimin cebinden sarkan köstekli saatin kösteğine tutunup yaka paça savurdu dostluğu sahte sözcüklerde saklanan gecelerin arsız karanlığına bulanmış safiyetine sığınarak/tango ritminde sevda atışlarını sıkıntı saatlerine çaldı tutsaklığım/gözü dönmüş yaşamın tuvalinden fırlamış/bir katran kırmızı çaldım göklere/hayat kanıyor/zaman şaşkın/uykuda kollarımda

kutsanmış bakire güneş/sızdırdı karanlığı içeri/şeytan ayrıntıya gizlendi...güneşe söyledim/yarın çıkmayacağım dışarı/kimse kandıramaz beni/tüm randevularımı iptal ettim/bulutta beklemesin artık/…/kendimle sevişmelerdeyim

gecelere boşalttım yıldızları/pırıl pırıl aşk yansıyor yüzümde/bir elimden tuttu sevgi/sonsuza yolculukta bir adım daha! hayat ayaklarıma serilmiş kırmızı bir halı! 

hüzün süzüldü gözlerinden tanrının/hüzne bulanmış bir şarkı geçti /şiir titredi! /içimi sensizlik kapladı/…/sensizlik/yalnızlığıma vurulan kara bir büyü/.../

kader...seni sunağımda yıkadım/arınmadın! / hüznüm bitmek bilmedi cebimde...her gelen bir tutam bıraktı gitti... 

düşler/takıp kanatlarını konuverdiler omzuma...melekler gibi/çağladım suskun… sustukça daha da serseri oldu hayat/…/oyun/…/kukla insanlar bulaştı oyuna/konuş(a) madım…

bu gece son/yarına bir saniye/günışığı selam ediyor karşı kaldırımda/aşk! 

“Merhaba! ”

şimdi bu kaçıncı bahar?', 'cepkenimin cebinden sarkan köstekli saatin kösteğine tutunup yaka paça savurdu dostluğu sahte sözcüklerde saklanan gecelerin arsız karanlığı...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sakar-bir-hayatin-yanilgilarinin-bileskesinde-yasananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Olan Gözler Kapanacak', 'acik-olan-gozler-kapanacak-semra-geven-zqe5y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat hep yaşadıklarımdan  ibaret 

Geri dönüp baktığımda hep bir film şeridi canlanır gözümde

İçerisinde anılarım göz yaşlarım haykırışlarım sessizliğim

Korkularım ve en önemlisi de ben varım 

Düşünüyorum da bunca zaman hep hayat için yaşamışım

Ona yetişeyim derken hep bir yanımı eksik bırakmışım

Ertelemişim kendimi en sona koymuşum 

Umutlarımı pamuk ipliğine bağlı bırakıp

Sevgimi bir kenara fırlatmışım 

Özgürlüğümü bir kuşun kanadına bile bağlayamamışım

Ama korkularımı göklere kadar çıkarmışım

Hayattan sevmekten özgür olmaktan 

Umutlarımı mavilere bırakmaktan hep korkmuşum

Kendimi çok cesur ve güçlü sanardım hep

Oysa hiç de güçlü değilmişim 

Kandırmışım bunca zaman boyunca kendi kendimi

Hayata yaklaşamamışım bile 

Oysa hayat nedir ki; 

Gözümü açtığımda bile devam eden bir rüya

Adı üstünde bu bir rüya ve elbette bir gün son bulacak

Açık olan gözlerim kapanacak', 'Hayat hep yaşadıklarımdan  ibaret  Geri dönüp baktığımda hep bir film şeridi canlanır gözümde İçerisinde anılarım göz yaşlarım haykırışlarım...', ARRAY['Türk Edebiyatı','Şiir','Semra Geven']::text[], 8.5, '{"poet":"Semra Geven","poet_slug":"semra-geven","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/acik-olan-gozler-kapanacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsem de', 'gitsem-de-birsen-ates-jddq1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir yağmur damlasıydım

düştüm yüreğine

sıcaklığında

yanıp kavrulmaya

gri boğucu şehirde

bir rüya gördük seninle

kısacık ama mutlu

ama bitti rüyamız 

çöktü aşkın kabusu 

içimiz acısa da

biliyor musun

gitsem de 

sendeyim hala

08.01.06', 'bir yağmur damlasıydım düştüm yüreğine sıcaklığında yanıp kavrulmaya gri boğucu şehirde bir rüya gördük seninle kısacık ama mutlu ama bitti ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gitsem-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Hüzün', 'bir-garip-huzun-ufuk-ozgen-ohzrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk mıdır kader

Aşktır mukadder

Gidenler gider

O sana yeter.

İster hayal de

Gitme kal de

Varsa gönülde 

Aşka da bir yer

O sana yeter.

Yetmez mi dersin

Çeker gidersin

Yüreğimdesin

O bana yeter.

Yetmez de desen

Gönlün hep esen

Olsun ve de sen

Yüreğinde her

Zaman aşka yer 

Ver derim, hep ver

O sana yeter.

Olur da bir gün

Bir garip hüzün

İle gördüğün

Olursam eğer

O bana yeter.

(Lüleburgaz - Ağustos 2003)', 'Aşk mıdır kader Aşktır mukadder Gidenler gider O sana yeter. İster hayal de Gitme kal de Varsa gönülde  Aşka da bir yer O sana yeter. Yetmez...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Özgen']::text[], 8.5, '{"poet":"Ufuk Özgen","poet_slug":"ufuk-ozgen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-garip-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Gideli', 'gittin-gideli-erdal-ercin-hkm46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülmeyi unuttum 

Gittin gideli

Duruldu duygunun o coşkun seli

Çok oldu ben senden umut keseli

Gel gör ki yakamdan düşmüyor sevdan

Adına diktiğim güller boşuna

Baktırıp baktığım fallar boşuna

Bilirim döktüğüm diller boşuna

Gel gör ki yakamdan düşmüyor sevdan

Bir seni tanıdım

Sana vuruldum

Eşimi dostumu kırdım

Kırıldım

Her şeyden vazgeçtim

Artık yoruldum

Gel gör ki yakamdan düşmüyor sevdan', 'Gülmeyi unuttum  Gittin gideli Duruldu duygunun o coşkun seli Çok oldu ben senden umut keseli Gel gör ki yakamdan düşmüyor sevdan Adına dikt...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ercin']::text[], 8.5, '{"poet":"Erdal Ercin","poet_slug":"erdal-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittin-gideli-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen-1', 'herseye-ragmen-1-eyup-gok-lhb8t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu cümleler bulacağım

Söylenmiş, bütün o sözlere rağmen

Tefekküre şevkat, mana olacağım

Kinlenmiş, bütün o gözlere rağmen', 'Sevgi dolu cümleler bulacağım Söylenmiş, bütün o sözlere rağmen Tefekküre şevkat, mana olacağım Kinlenmiş, bütün o gözlere rağmen...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/herseye-ragmen-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla (2)', 'leyla-2-erdal-ercin-xmdk9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni gezdim diyar diyar

Oldum sefil seyyah Leyla

Rüzgâr gibi geçti yıllar

Yazık ettin

Günah Leyla

Ben peşinde sen bir kaçak

Bunun sonu ne olacak

Adın göğsümde bir bıçak

Beynimde bir silah Leyla

Değil mi bu son ümitti

Benim için her şey bitti

Gitti gençlik elden gitti

Gitti gençlik

Eyvah Leyla', 'Seni gezdim diyar diyar Oldum sefil seyyah Leyla Rüzgâr gibi geçti yıllar Yazık ettin Günah Leyla Ben peşinde sen bir kaçak Bunun sonu ne ol...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ercin']::text[], 8.5, '{"poet":"Erdal Ercin","poet_slug":"erdal-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/leyla-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fay Hattı Gibi Yüreğim', 'fay-hatti-gibi-yuregim-hatice-bediroglu-kd65o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Donuveriyor sevinç içimde 

Buz kesiyor elim ayağım 

İplik iplik hüzünler 

Dönüyor hızla etrafımda

Birbiri ardı sıra 

Kopup geliyor gözyaşlarım 

Susuyor zaman 

Yükseliyor sesi dalgaların 

Parçalıyor kendini bir kayık 

Saklanıyorum 

Koynuna korkunun

Acı taarruzda 

Acı çıldırmış 

Acı fışkırıyor yüreğimden 

Kanıyor toprağın damarları

Bu gece... Bu gece...

Ne gökyüzü duruyor 

Ne de duygularım 

Öyle bir yara almışım ki! 

Fay hattı gibi yüreğim 

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Donuveriyor sevinç içimde  Buz kesiyor elim ayağım  İplik iplik hüzünler  Dönüyor hızla etrafımda Birbiri ardı sıra  Kopup geliyor gözyaşlar...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fay-hatti-gibi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla (3)', 'leyla-3-erdal-ercin-a12km', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demek aşkta gözü yoktu

Varı yoğu birdi Leyla 

Bunu kim kafana soktu

Bu aklı kim verdi Leyla

O akardı yorulmazdı

Köpürürdü

Durulmazdı

Bilse sana vurulmazdı

Nereden bilirdi Leyla

Bu zehri önce kim tattı

Kim canını kime kattı

Aşkı kim kime uzattı

Kim geri çevirdi Leyla

Ben sana dayan dedimdi

Söyle ne olacak şimdi

Canının çektiği kimdi

Koynuna kim girdi Leyla

Gözlerinden çıkan oktan

Çoktan yaralandı çoktan

Adı mecnun oldu yoktan

Kays niye delirdi Leyla', 'Demek aşkta gözü yoktu Varı yoğu birdi Leyla  Bunu kim kafana soktu Bu aklı kim verdi Leyla O akardı yorulmazdı Köpürürdü Durulmazdı Bilse s...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ercin']::text[], 8.5, '{"poet":"Erdal Ercin","poet_slug":"erdal-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/leyla-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsız', 'kararsiz-erdal-ercin-9a51j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim aklım fikrim sende

Vazgeçtim

Boyun verdim bir kemende

Vazgeçtim

Ağırla beni hanende

Vazgeçtim

Götür beni

Dış kapında kul eyle

Saç bağı yap saçlarının teline

Türkü olam dola beni diline

Kemer olam bağla beni beline

Bu bana çok

Ayağına yol eyle

Elmas olam hazinene kat beni

Çift kilitli kasalarda tut beni

Kadir kıymet bilmeyene sat beni

Ne tutarsam çar çur eyle

Pul eyle

Önce gönül ambarına dök beni

Sonra sevgi tarlasına ek beni

İlkbaharda kurumadan sök beni

Bulunduğum her ortamı çöl eyle

Yar bağrımı 

Gör karayı akı da 

Bak kendine

Her damarda dokuda

Yüreğimin mektubunu oku da

Beğenmezsen dök benzini

Kül eyle', 'Benim aklım fikrim sende Vazgeçtim Boyun verdim bir kemende Vazgeçtim Ağırla beni hanende Vazgeçtim Götür beni Dış kapında kul eyle Saç bağı...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ercin']::text[], 8.5, '{"poet":"Erdal Ercin","poet_slug":"erdal-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kararsiz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Robot Resim', 'robot-resim-melih-coskun-4n25t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün 

Yüzünde sebepsiz gülümseyişiyle 

Şarkılar mırıldanarak yürüyen

Erken büyümüş bir çocuk görürsen karşında 

Bil ki o benim…

2005', 'Bir gün  Yüzünde sebepsiz gülümseyişiyle  Şarkılar mırıldanarak yürüyen Erken büyümüş bir çocuk görürsen karşında  Bil ki o benim… 2005...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/robot-resim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap Rakı Çin Kirpiklerimden Damlıyor 1', 'sarap-raki-cin-kirpiklerimden-damliyor-1-eyup-selahattin-dalkiran-wfqde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçiyorum işte

Kalb hastası olsam ne yazar

İçiyorum işte

Şarap,rakı,çin

kirpiklerimden damlıyor.

İçim bir telaş yuvası pir telaş olmuş

Çırpınıyor ellerim

,çarpışıyor makinalı tüfekle

Uzak ruhlar ile.

Artık içiyorum

kalb hastası olsam ne yazar

İçiyorum işte

Gözlerin agzımdan düşüyor

Çırpınıyor ellerim,tutmaya

çalışıyor gözlerim gözlerini

içiyorum işte

kalb hastası olsam ne yazar

içiyorum işte

siğaranın hasını

dumanlar hırstan soluyor

Mavi mavi delişmen atlar gibi

Meyhaneci zokaya gelmiş yakalanmış 

balık gibi

Çırpınır durur ordan oraya

Ayaklarına dolaşmış bağcıkları

ağ gibi

İçiyorum işte

İstanbulun havasını ve seni 

Ne yazar sosyalist  olsam  halk için.

Diyeceğim olmuyor

Çünkü karşımda duruyorlar

Avını bekleyen kuduz köpekler gibi

Faşistler.', 'İçiyorum işte Kalb hastası olsam ne yazar İçiyorum işte Şarap,rakı,çin kirpiklerimden damlıyor. İçim bir telaş yuvası pir telaş olmuş Çırpın...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sarap-raki-cin-kirpiklerimden-damliyor-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarındayım', 'avuclarindayim-i-lknur-er-1hr5j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Avuçlarındayım

Gördüklerim, göreceklerim senden ibaret

Tam ortası gecenin ve karanlığın dipsiz kuyusunda

Ellerinden kaymanın korkaklığıyla

Sıkıca siniyorum kırışıklarına

Sakın ellerini açma', 'Avuçlarındayım Gördüklerim, göreceklerim senden ibaret Tam ortası gecenin ve karanlığın dipsiz kuyusunda Ellerinden kaymanın korkaklığıyla S...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/avuclarindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Sende Kalayım', 'birak-sende-kalayim-i-lknur-er-2essv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut umutsuzluğa takılmış bugün

Belkiler kalkmış sözcük dağarcığımdan

Hiç bilmediğim bir bakış yerleşmiş gözlerime

Sen hiç sana ben gibi baktınmı? 

Gözlerinde çaresizliği gördüğümden beri

Çare yim sendeki kanlı yaraya

Bir bıraksam tuttuğum parçalarını

Toparlanamazsın belki bir daha

Gölgen yorganım olur gecelerimde

Nefesin sıcağım olur her an yanımda

Gözlerin mühürlü bir ok kalbimde

Bırak sende kalayım sakın git deme', 'Umut umutsuzluğa takılmış bugün Belkiler kalkmış sözcük dağarcığımdan Hiç bilmediğim bir bakış yerleşmiş gözlerime Sen hiç sana ben gibi bak...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birak-sende-kalayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Deme', 'umut-deme-i-lknur-er-f8943', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yerleştiğin tavan arasından çık artık

Karış bendeki karanlıklara

Çıkmazları gör hayatımdaki

Sonra yine çekil kenara

Umut deme, belki deme

Ne dersen de yarınlarıma

Açık kapıları sıkıca kapa

Gidiyorsan git dönme bir daha

Yüreğim gümrük kapısı değil

Girişler, çıkışlar olmaz parayla', 'Yerleştiğin tavan arasından çık artık Karış bendeki karanlıklara Çıkmazları gör hayatımdaki Sonra yine çekil kenara Umut deme, belki deme Ne...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umut-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklar Devler Gibi Sevişiyordu', 'yapraklar-devler-gibi-sevisiyordu-tuna-ozturk-tf74e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yapraklar devler gibi sevişiyordu

Hepsi sararmıştı  tahminen mevsimden

Sevişmesi biten  kırılıyordu

Etraf kırık yapraklar…

Dün gece saçlarını madam  tousso  da  gördüm

Senden ödünç aldı biliyorum

Gözlüklerini  kimlere  takmadılar ki

Yakışmıyordu kimseye 

Gözlerini  kimsede görmedim dün gece

Çünkü yoktu  o gözleri  bir saatlik de olsa  taşıyacak

Yürekli  biri..

Yapraklar devler gibi sevişiyordu

Çocuklar gibi  kırılıyordu

Ellerimi ellerine dolamama

Kahretsin ki  engeldi 

Beni  bilmiyor oluşun

Ellerim  koşuyordu

Asla tutamıyorum

Bana tokat atacaksın biliyorum 

Değerse  ellerim

Ellerine..

Yapraklar her sene  bu zamanlar

Sevişiyorlar aslında

Ve her sene de güçsüzler kırılıyorlar

Ama ilk olan  bir şey  var

Mozart ı düşün güneşi ilk  görüşünü

Bu ilk,  son olur  umarım

Yoksa bir daha  ellerimi  zaptedemem

Ben rezil olurum

Çocuklar  gibi  temiz düşünürken…

Yapraklar devler  gibi sevişiyordu

Senin fikrin bitmiyordu

Gözlerinin  bittiği yerde saçların başlıyordu

Saçlarını  bir  görüşüm

Gözlerimi   şair yapıyordu..

Sanmasınlar ki  bunları ben yazdım

Yaprakların seviştiği bir  akşamüstü

Saçların tuttu  ellerimden

Gözlüklerin kalem oldu

İlham da sende

Aşk da sende

Güzellik de sende

İlk  kez  bu gün anladım seni görünce

Bir hiç olduğumu

Bir hiç olduğumu…', 'Yapraklar devler gibi sevişiyordu Hepsi sararmıştı  tahminen mevsimden Sevişmesi biten  kırılıyordu Etraf kırık yapraklar… Dün gece saçların...', ARRAY['Türk Edebiyatı','Şiir','Tuna Öztürk']::text[], 8.5, '{"poet":"Tuna Öztürk","poet_slug":"tuna-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yapraklar-devler-gibi-sevisiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Bela Gözlerin', 'gunese-bela-gozlerin-tuna-ozturk-d1nka', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşe bela gözlerin,güneşe

Güneşe

        Güneşer

                   Gün eşermek

Günü  tırnaklarımızla eşermedik mi gömüldüğü dipsiz karanlıktan

Çıkarmadık mı,gecenin suratına tokat gibi yapıştırmadık mı günü

Güneş gündüzleri olur

                    Gözlerin güneş

                              Gözlerin güneş her zaman gözlerin

                                                      Güneşe bela gözlerin.

Bülbüle ceza sözlerin bülbüle

Bir duyan seni,gitmiyordu

Akşamlar şimşek gibi çakıyordu

Ve sen bana gelince  film izlemeye,film bitince bir de

Bülbüller uyuyamıyordu….', 'Güneşe bela gözlerin,güneşe Güneşe         Güneşer                    Gün eşermek Günü  tırnaklarımızla eşermedik mi gömüldüğü dipsiz karanl...', ARRAY['Türk Edebiyatı','Şiir','Tuna Öztürk']::text[], 8.5, '{"poet":"Tuna Öztürk","poet_slug":"tuna-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunese-bela-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tepecik Serserisi', 'tepecik-serserisi-tuna-ozturk-zwwqk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TEPECİK SERSERİSİ

Üç kişi   vurdular bana; kürt Ekrem,tepecik ve ben

Gecenin bir saati çaldım kapısını kendimin

Evde yokum rezil bir haldeyim belki sarhoşum

Tövbeler olsun ağzıma sürmedim ama sarhoşum kahretsin

Yıkıl kürt Ekrem, kelebek çekmeden  dövsene sıkıysa

Gelsene yanına almadan tepeciği ve beni

Ayıkken ben gelsene.

Üç kişi  vurdular bana kürt Ekrem,tepecik ve ben

Cevap versem cevabım cılız kalıyordu

Siyah parizyenli orospular bile yoktu dışarıda/bu nasıl tepecik  böyle

Önce  sol ayağım yıkıldı  biraz sonra sağ

Ellerim pansumanda karnımdan akan suya.

Üç kişi vurdular bana  dört de olabilir

Ne bileyim sarhoştum  gidin başımdan belki de bir

Kürt de değildi belki türkoğlu türktü

Sağ memesiydi belki tepecik sol memesi  kürt Ekrem

Sureti bendim belki de ne bileyim

Gidin başımdan.

Üç kişi vurdular bana

Kel komiser kimse yoktu oğlum diyor

Bunamışsın sen komiser,kürt Ekrem tepecik ve ben

Bir kavgaya karıştık ben tektim

Kanım Kızılırmak oldu tükenecek emin olun

Aktı yeşildereye.

Üç kişi vurdular bana,konuşabilsem  senin  adını söyleyecektim polislere..', 'TEPECİK SERSERİSİ Üç kişi   vurdular bana; kürt Ekrem,tepecik ve ben Gecenin bir saati çaldım kapısını kendimin Evde yokum rezil bir haldeyi...', ARRAY['Türk Edebiyatı','Şiir','Tuna Öztürk']::text[], 8.5, '{"poet":"Tuna Öztürk","poet_slug":"tuna-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tepecik-serserisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şimdi kalbime ne derim', 'ben-simdi-kalbime-ne-derim-ramazan-kayak-s22fi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden bu kadar geciktin 

Bunca zaman yalnız bıraktın 

İçimdeki sevda çiçekleri soluyor bak 

Nerelerdeydin 

Beklendiğin çağda gelmeyen sevgili 

Neden şimdi zamansız geldin

Yorgun ve yoksul gönlüme 

Yüreğim aşkla dolup taştığında 

Sevda yelleri başımda estiği zamanda 

Neredeydin 

Umutlarım yıllara takıldı gitti

Yağmurlara kapıldı gençliğim 

Sel, sel oldu gitti benden

Sevdayı gurbet kervanlarına yükledim 

Hangi çöllerden geçer hangi kuyulardalar 

Hayatın hangi kıyısındalar 

Sormuyorum hesabını geçen yılların

Geldin şimdi ansızın dünyama 

Bahar yeşilli gözlerinle 

Buram, buram karanfillerinle 

Fırtınalar kopardın yüreğimde 

Neredeydin ey geç gelen sevgili 

Sevdalarım tükendi gözyaşlarım kurudu 

Kırılgan kalbimde çiçekler soldu

Sen bedenim de ateşler yakıyorsun 

Sen beni çöllere yoluyorsun yeniden 

Sevda kervanlarının peşinden 

Hiç acımaz mısın bana 

Bunca zamandan sonra 

Sorgusuz sual sız giriyorsun dünyama 

Ben şimdi kalbime ne derim

Ne derim söyle zamansız gelen sevgili 

                           Ocak.2006  Balcalı hastanesi Adana', 'Neden bu kadar geciktin  Bunca zaman yalnız bıraktın  İçimdeki sevda çiçekleri soluyor bak  Nerelerdeydin  Beklendiğin çağda gelmeyen sevgil...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ben-simdi-kalbime-ne-derim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezberimden', 'ezberimden-cagdas-yildiz-b5hok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yolun yarısında unutmayayım diye,

avuçlarıma tutturulmuş buruşuk bir kağıtla,

çıkageldim karşına...

hep unuturdum sanıyordum,

ama bunu,

ezberden okuyorum; 

seni çok seviyorum...', 'yolun yarısında unutmayayım diye, avuçlarıma tutturulmuş buruşuk bir kağıtla, çıkageldim karşına... hep unuturdum sanıyordum, ama bunu, ezbe...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ezberimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemleme', 'ozlemleme-cagdas-yildiz-u1bth', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hanginiz özleyebildi

özlenmediğini bildiğini...

ya da

hanginiz 

özleyebilirsiniz; 

özlemenin ta kendini...

siz hiç gerçekten 

özlemini bile özleyeceğiniz 

birisini sevdiniz mi?', 'hanginiz özleyebildi özlenmediğini bildiğini... ya da hanginiz  özleyebilirsiniz;  özlemenin ta kendini... siz hiç gerçekten  özlemini bile ...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlemleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzen Kurulmuş Dönme Üstüne…', 'duzen-kurulmus-donme-ustune-metin-soydeveli-c7yeg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uskur döner, şaft  döner

Teker döner, mil döner 

Pervane döner, çark döner…

Hepsi götürmeye programlı sanki

Günler, aylar, mevsimler, yıl döner…

Dünya döner, Güneş döner, Ay döner

At döner, dolap döner

Belki bir gün baht döner! 

Sonu yok bu dönüşlerin

Bütün dönüşlere sen istisna.

Sen de dön 

Taş yüreklim

Beni öksüz bırakma

Analar taş doğurur da…

Taş taşı doğurmaz

Durup durma yaban elinde

Taş bile taş gibi duramaz yerinde.

Sen de dön

Taş yüreklim

Beni öksüz bırakma

Ne kıyısı kalır, ne köşesi…

Kapılırsa dalgasına hasretin.

Oyuncağı olur elinde 

Yuvarlana yuvarlana 

Ufalanır gider, kuma döner

Sen de dön

Taş yüreklim

Beni öksüz bırakma

Bir sen kaldın bir de bahtım 

Dönüşlere müstesna

Kutup yıldızı gibi çakıldın kaldın

Gittiğin yaban ellerde

Bittim, tükendim artık 

Aşkın çağı çoktan geçti bende

Köreldi tüm duygularım 

Biri istisna! 

Fark etmeyecek artık 

Dönsen de dönmesen de.', 'Uskur döner, şaft  döner Teker döner, mil döner  Pervane döner, çark döner… Hepsi götürmeye programlı sanki Günler, aylar, mevsimler, yıl dö...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/duzen-kurulmus-donme-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suna Su', 'suna-su-fevzi-gunenc-zbix4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu top Suna

bu da ip

Oyna, atla...

İmreniyorum bakarak şuna buna

babam bal alamıyor

Sen bana su ver Suna!', 'Bu top Suna bu da ip Oyna, atla... İmreniyorum bakarak şuna buna babam bal alamıyor Sen bana su ver Suna!...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/suna-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götürürler', 'gotururler-yusuf-ter-35fkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Urfa önünde yatar

üstü acık her gece

puştun alemliğinde

ay göğün göğsünde

mayına düşer esirce

kurtlar,çakalar 

sırtlanlar, uluşur 

hainliğin kapısında

puştlu bir gece vakti

alırlar götürüler senide...

BİLMEDİĞİN İZBELERE…

Yusuf Ter 8.01.2006

Saat 21:12: İsviçre 

Not Sevgili Umut kardeşimizin 

Özelime  yazıp gönderdiği şiir

Beni o kadar çok duygulandırdı

Okurken bunlar döküldü kalemimden

Kendisine teşekkür ediyorum

Güzel şiirini benle paylaştığı için... 

Şiiri

Puşt Gece-Umut Kıylık', 'Urfa önünde yatar üstü acık her gece puştun alemliğinde ay göğün göğsünde mayına düşer esirce kurtlar,çakalar  sırtlanlar, uluşur  hainliğin...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gotururler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekli Ölüm', 'cicekli-olum-serhat-caliskan-z9mi9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bu akşam ölüyorum

Önce yavaş yavaş,kan çekiliyor damarlarımdan

Şöyle bir sendeleyip koltuğa düşüyorum

Aynada sararmış yüzme sonkez bakıyor gözlerim

Şu duyduğum son hırıltım olmalı

Başım hafiften sola yatıyor

Parmaklarım çözüldü,işte ben  öldüm

Yarın sabahı görür gibiyim 

Ağlayanlar,sızlayanlar hayıflananlar

Babam ellerini yüzüne kapatmış ağlıyor,

Abilerim,kardeşlerim hepsi bana yanıyor

Borcum olanlar daha bir üzgün

Herkesten gizli sevdiğm yorgun

Boşver,aldırma gönül maralım

Bir zaman sonra alışacaklarını bilmiyorlarki

Yakıştırırlar sanada çok geçmeden başka bir ben

O musalla taşına birkez daha yatmştım anam öldüğünde

İlkkez sabun gözlerimi yakmayacak ve sevmediğim o selayı duymayacağım şükür

Son elbisem bu benim,

Keşke biraz bol alsaydın,seneyede giyerdin diyen olmayacak

Öylesine idealki,ne eskir ne çeker,nede çıplak brakır

Dirilene kadar giy

Yalz şu kutu biraz darca,hani bir misafir gelse kapıda kalır

Eee alışğız nede olsa üç oda bir salona

İşte mahalle imamının sesi,hakkınızı helal ediyormusunuz

Ediyoruz! 

Bendende size helal olsun canlarım

Küçükken maviyle,kırmızıya bayılırdım,

En gerçek renkler beyaz ve siyahmış meğer

Beyaz kefen,kara toprak bir ömre değer

Oh be kiradan kurtuluyorum

Almanyadan oğlum gelecek,çık evimden diyemezlerya burdada

Yahu bir sigara,bir çay içseydim bari

Ölüye bir zararı yokmuş o meretin

Az sonra,çamlıkklar arasındaki mezarlığa gidiyoruz

Hep omuzlara alınmayı hayal ederdim

Bir sporcu,bir bakan,bir yazar,bir asker olarak

Kahramanca gururla

İşte omuzlardayım,yorum sizin

Aman yavaş bırakın

Sol tarafım ağrıyor,doymamışlıkmı desem,korkumu desem

Yoksa yeni evimi sevemedimmi

Ev alma komşu al derdik yaşarken

Yandaki şehit hoşgeldine gelecekmiş

Ne ikram etsem

Aaa gidiyormusunuz,ne güzel laflıyorduk

Neyse bunu saymam,fatihayada beklerim', 'Ben bu akşam ölüyorum Önce yavaş yavaş,kan çekiliyor damarlarımdan Şöyle bir sendeleyip koltuğa düşüyorum Aynada sararmış yüzme sonkez bakıy...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cicekli-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım-ız', 'yalnizligim-iz-cagdas-yildiz-xhq38', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gün gelecek,

yalnızlığından gizleyemediğin ellerin,

yeniden üşüyecek...

o gün gelince,

yalnızlığın 

yalnızlığımız olup,

ellerin ellerime

yeniden değecek..', 'bir gün gelecek, yalnızlığından gizleyemediğin ellerin, yeniden üşüyecek... o gün gelince, yalnızlığın  yalnızlığımız olup, ellerin ellerime...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizligim-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Ağlıyor', 'sensizlik-agliyor-birsen-ates-i95d3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kolay mıydı 

bilmediğim bir okyanusta 

korkularımla yüzleşmek 

sana gelmeye çalıştıkça 

senden uzakta kalmak

karşı kıyılar da,

düşlerde 

artık çok u z a k l a r d a 

a n l a m ı y o r s u n 

peki,

öyle olsun 

anlardın 

gözlerime baksaydın 

sensizlik ağlıyordu gözlerim de 

09.01.06', 'kolay mıydı  bilmediğim bir okyanusta  korkularımla yüzleşmek  sana gelmeye çalıştıkça  senden uzakta kalmak karşı kıyılar da, düşlerde  art...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizlik-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır... ağır', 'agir-agir-hakan-ak-v8gwt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ölüm kadar sessizdin

sevda denizlere düşmüş

ben gözlerinde çırpınmışım

kurşun kurşun göz yaşı

yıldızlar boğulmuş geceden 

ölüm kadar sessizsin

istanbula kızarken eylüller

yapraktan sarıdan sonbahardan 

kızıldan siyahtan gidenlerden..

ölüm kadar sessizim

kelimeleri kandırdılar beni kandırdılar 

bu gece aya kursun sıktılar

gece saydın uykulardaydın', 'ölüm kadar sessizdin sevda denizlere düşmüş ben gözlerinde çırpınmışım kurşun kurşun göz yaşı yıldızlar boğulmuş geceden  ölüm kadar sessizs...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agir-agir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Şehir', 'sarhos-sehir-cihan-basak-0knu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sarhoş şehirdi beni sana unutturan.

Adım adım tüm kaldırımları bir dost kılan.

Bu sarhoş şehirdi seni benden gizli çalan.

Sokak sokak beni yapayalnız dolaştıran.

1998 Gazimagosa', 'Bu sarhoş şehirdi beni sana unutturan. Adım adım tüm kaldırımları bir dost kılan. Bu sarhoş şehirdi seni benden gizli çalan. Sokak sokak ben...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sarhos-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götür Benide', 'gotur-benide-guzin-osmancik-e0iuf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takıldım gidiyorum

Bir kuşun kanadına

Kuş enginlere,

Kuş bulutlara,

Kuş bilinmeze uçuyor.

Kanadına tutundum 

Gidiyorum

Kuş hızlı,

Kuş kararlı,

Uçuyor senelere....

Kendi istediği ülkeye

Kaderimmisin sen benim kuş

Yoksa sen.KADERMİSİN

Elim senin kanadında

Kanadın kime bağlanmış

Götür beni de

Bağlandığın

Sahibine', 'Takıldım gidiyorum Bir kuşun kanadına Kuş enginlere, Kuş bulutlara, Kuş bilinmeze uçuyor. Kanadına tutundum  Gidiyorum Kuş hızlı, Kuş kararl...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gotur-benide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidermisiniz?', 'gidermisiniz-esat-erbil-fzuh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözün ceylan 

Dudak kaytan 

Kaşın fettan

Birsin payım... Edermisiniz? 

Yanağın ah

Saçın siyah

Yüzünde mah

Birin bize...  Seçermisiniz? 

Boyun çinar 

Ağzın pınar

Beni yakar 

İksin bana... Verermisiniz? 

Benim bardüş

Aşkın ateş

Yaklaş yevaş

Beni behoş... Birakırmısınız? 

Adın Peyman

Canın kurban

Gafil oyan

Söyle bensiz... Gidermisiniz?', 'Gözün ceylan  Dudak kaytan  Kaşın fettan Birsin payım... Edermisiniz?  Yanağın ah Saçın siyah Yüzünde mah Birin bize...  Seçermisiniz?  Boyu...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidermisiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem - Gazel', 'i-stemem-gazel-esat-erbil-achaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç defa rüşvet diye atıldı üst masama,

Merdane törelmişim ar safasın istemem.

Meyli cananım vardır ararım istediğim,

Cananılar çoktur ama be vefasın istemem.

Şan şöhret varlık değil çoklar para hastası,

Özgürlük elde olmazsa gizli sesin istemem.

Kimi kendini satmış üç günlük yaşamaya,

Alçakça böyle yaşam bir cefasın istemem.

Yıksalar dünyamı da zerrece düşünme rem,

Kişisel bencilliğim tek kafasın istemem.

(Esat)  bağlar sahibi doğru çiçek tanırım,

Bağ isterim altından yad kafesin istemem.', 'Kaç defa rüşvet diye atıldı üst masama, Merdane törelmişim ar safasın istemem. Meyli cananım vardır ararım istediğim, Cananılar çoktur ama b...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istemem-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-cihan-basak-7klvh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yapraklar solar 

Mevsim mevsim

Çok şey soldu

İçimde bahar 

Bu mevsim

Bu bahar

Yaprak kopartan bahar

Ne zaman 

Yeşillenir bilmem 

İçimdeki yığınlar.

15 Ekim 2000 Diyarbakır', 'Yapraklar solar  Mevsim mevsim Çok şey soldu İçimde bahar  Bu mevsim Bu bahar Yaprak kopartan bahar Ne zaman  Yeşillenir bilmem  İçimdeki yı...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bahar-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterince yaşamak', 'yeterince-yasamak-cetin-hacifettahoglu-pypqg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sokaktan her akşam üzeri geçerdi

Elleri diken gözleri panzer gibi,bir sağa bir sola düşerdi

İşte ben o akşam gördüm gelmediğini

Kıyametin alameti belkide bu idi

Ben gördüm görmediği kırık kaldırım taşını

Ben tükürdüm mazgala

Ve ben taradım gözlerimle duvardaki kirli yazıları

Her akşamdan başka bu akşam

Mendeburdu belki ama doldururdu akşamın o sisli boşluğunu

Yeterince yaşamalı dedi

Yeterince çekmeli bu yükü

Dedi,dedi,dedi...

Ve bir daha asla dİyemeden çekti gitti.', 'Bu sokaktan her akşam üzeri geçerdi Elleri diken gözleri panzer gibi,bir sağa bir sola düşerdi İşte ben o akşam gördüm gelmediğini Kıyametin...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeterince-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen Yoksada Ölüm', 'ya-sen-yoksada-olum-esat-erbil-xg33x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimden gelirse bir köşk yaparım,

Acı yalnızlığa üç eş taparım,

Gelirsen yoluna güller serperim,

     Kız gönül arzumdur seninle gülüm,

     Ya, sen nasıbımsın yoksa da ölüm ,

İlk aşkım seninle başladı inanan,

Sevdim sevildim de olmadım pişman,

Benim olmak için can veririm can,

     Kız gönül arzumdur seninle gülüm,

     Ya, sen nasıbımsın yoksa da ölüm

Yazıktır sevgilim emeğim itsin,

Canan kavuşalım yalnızlık bitsin,

Çile üzüntüler başımdan gitsin,

     Kız gönül arzumdur seninle gülüm,

     Ya, sen nasıbımsın yoksa da ölüm', 'Elimden gelirse bir köşk yaparım, Acı yalnızlığa üç eş taparım, Gelirsen yoluna güller serperim,      Kız gönül arzumdur seninle gülüm,     ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ya-sen-yoksada-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şenlik Başlarken', 'senlik-baslarken-esat-erbil-xjez9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardeş bacılar haleye kalkın,

Toy düğün oldu ele ele takın,

Gelin getirdik boyuna bakın,

       Şenlik başlarken küreken mutlu,

       Gelen günlere gelin umutlu,

Gelecek güne umut bağlandı,

Yeni bir hayat bize sağlandı,

Dostlar sevindi düşman dağlandı,

        Şenlik başlarken küreken mutlu,

        Gelen günlere gelin umutlu,

Kaç yıl bekledik bugünü bizler,

Acılar çektik bir gülsün yüzler,

Çalındı davul söylendi sözler,

       Şenlik başlarken küreken mutlu,

       Gelen günlere gelin umutlu,', 'Kardeş bacılar haleye kalkın, Toy düğün oldu ele ele takın, Gelin getirdik boyuna bakın,        Şenlik başlarken küreken mutlu,        Gelen...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senlik-baslarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ocağımız', 'ocagimiz-esat-erbil-hg28c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşasın Ocağımız,

Milletin okuludur,

Yaşasın Ocağımız,

Yolumuz hak yoludur.

Düzlükte teki yoktur,

Kinli düşmanı çoktur,

                       Ocağın adamları  ,

Gözlerine kör okutur .

Doğumun kutlu olsun,

Sevenin mutlu olsun,

Gelecek daha parlak,

Gençler umutlu olsun,

Türkçülüğe yol açan,

Kardeşliğe kol açan,

Türkmen’ i saklar bekler,

Dalsızlara dal açan,

Erbil ‘in Ocağında,

Ot yanar bucağında,

Öksüzleri hep besler,

O, Geniş kucağında,

Uyandırdı milleti,

Yok eyledi illeti,

Mücadele yolu ile,

Kahır edecek zilleti', 'Yaşasın Ocağımız, Milletin okuludur, Yaşasın Ocağımız, Yolumuz hak yoludur. Düzlükte teki yoktur, Kinli düşmanı çoktur,                     ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ocagimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Yükü', 'zamanin-yuku-esat-erbil-ko42w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıktı belden yükünü,

Konak geliptir zaman,

Çelik olsa bükünü,

Bize dalıptır zaman.

Güldür bülbül saynadan,

Ateş suyu kaynatan,

Bizi ele oynatan, 

Yazık oluptur zaman.

Bize güldü çok ağyar,

Yeter dost yaralar sar, 

Yüzlerce vefalı yar,

Bizden alıptır zaman.

Yürekte yara kaldı,

Hep dostlar buna daldı,

Gönlümüz keyfin aldı,

Gama salıptır zaman.

Bekleriz bizi salsın,

Yad ellerine dalsın,

Erkekler sana kalsın,

Kaldık kalıptır zaman.

Çok el çaldık dizlere,

Bak gülen şen yüzlere,

Vefalı dost bizlere,

Hala kalıptı zaman.', 'Yıktı belden yükünü, Konak geliptir zaman, Çelik olsa bükünü, Bize dalıptır zaman. Güldür bülbül saynadan, Ateş suyu kaynatan, Bizi ele oyna...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zamanin-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Işıklar', 'mor-isiklar-cihan-basak-cn1ca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mor ışıklar altında

Kan kırmızı asil güller.

Yüksek topuklar üstünde 

Sallanan bedenler.

Dirseğine kadar çıplak

Havada bembeyaz eller.

Mor ışıklar altında,

Baldırına kadar çıplak

Gölgeden abideler.

26 Nisan 2000', 'Mor ışıklar altında Kan kırmızı asil güller. Yüksek topuklar üstünde  Sallanan bedenler. Dirseğine kadar çıplak Havada bembeyaz eller. Mor ı...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mor-isiklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalğın Peşinde', 'yalgin-pesinde-esat-erbil-843qd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yurdumdan ayrılamam işte ona delliyim

Yabancılar tanımaz dostlarında belliyim

Seven beni bir görer yada birkaç elliyim

Çok yazıklar millete birbirimizle kırılak

Yad cesaret etmeden dost eliyle vurulak.

Hakıkatın yüzüyüz terse boyun eğmeyiz

Nazuk olan kimsenin bir gölüne değmeriz

Millet yolunda yalan hiçkimseyi öğmeriz

Kuşları kondurdular yaprak dökülen

Son durakta milleti getirdiler ne hala.

Sesimiz cihan duysun hakkımıza susmarız

Mille hayınlarına göz yüm ayak basmarız

Mücadele dostumuz ü. Ağaca asmarız

Tanıyan bize tanık ateştende ürkmeriz

Soran varsa kim bunlar biz gayretli Türkmeniz.

Kolayca yenilmeriz yağılık yapan bilsin

Yakınmayı çözeriz kini gönülden silin

Kurnaz olan ayınsın hayına ölüm kılsın

Bizlerin uğraşması toplamak bir araya

Gönlümüz amacı çara bulmak yaraya.

Mert adam saygısı var eğilip elle öpmez

Öz ekmeğinden fazla başka  ellerden  kapmaz

İyimserlik içinde büyüyen kötü yapmaz

Çalışmada bulunun millet alanı geniş

Başarı kayt etmeyen yerleri alçak iniş

Yağmacılar, yerginler çevremizi alıptı

Yırtıcı bencilikler kendi işin salıptı

Milliyetçiye yer yok tavcılarsa kalıptı

Alanı dört eliyle bırakmazlar tutmuşlar

Yazıklar bu milletin öz hakkını yutmuşlar

Adet mı millette güç verilsin hayına? 

Yanıt bizden almayın bakın halkın vayına

Güçlü güçsüzü yiyor benziyorlar hayvana

Şanımız nerede kaldı düri nefis yaşıyız

Her gelen bir oynadır aynı setrenç taşiyiz

Beklenirdi ileri ulğun ulğun adımlar

Yoksul değiliz belki yoksunlara yardımları

Dem vurdular millete ne zalimce zalimler

Hakiket yalan oldu her şey döndü yalgına

Milletin liderliği verildi  dört çılgına', 'Yurdumdan ayrılamam işte ona delliyim Yabancılar tanımaz dostlarında belliyim Seven beni bir görer yada birkaç elliyim Çok yazıklar millete ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yalgin-pesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırılsıklam hayaller', 'sirilsiklam-hayaller-cetin-hacifettahoglu-gasqr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsim dışı bir zaman

Sana yaz bana sonbahar

Ellerinde hayalleriyle küçük bir kız

Yitik bir parçası besbelli

Belki bir sokak kaldırımda düşürmüş

Ha bulmuş ha bulacak derken

Yeni bir gerçek olmuş adımları

Sürüklene sürükleye

İffetiyle bir kenar mahalleye kadar 

Çıkmaz sokakta sıkıştırmış onu hayalleri', 'Mevsim dışı bir zaman Sana yaz bana sonbahar Ellerinde hayalleriyle küçük bir kız Yitik bir parçası besbelli Belki bir sokak kaldırımda düşü...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sirilsiklam-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-cihan-basak-5d8sy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masum ve titrek bir melodi

Bir böcek olmalı şarkı söyleyen...

Yaz gelmiş.

Hasat mevsimi yakın.

Yakacak yine güneş tarlada çalışanları,

Kumsalı denizi bilmeyen zavallıları.

İstemesede çekecek mehtap,

Yıldızlarla kavga eden

Sahte aşıkları.

Yaz gelmiş.

Şimdi bir deniz kasabasında gece...

Kayan bir yıldızı izleyen gözlerim...

Yaz gelmiş.

Bir serserinin yaz aşkı

Ve karıncaların aş telaşı derken,

Kurak memleketimin bir köşesinde

Çatlak toprağı sulayan 

Bir kadının göz yaşları...

Yaz gelmiş.

Bazen çekilmez olsada 

Şu meltemin kaprisi.

Yaz gelmiş.

Bitmek bilmez bir kurbağa senfonisi...

31 Mayıs 1998 Gazimagosa/Kıbrıs', 'Masum ve titrek bir melodi Bir böcek olmalı şarkı söyleyen... Yaz gelmiş. Hasat mevsimi yakın. Yakacak yine güneş tarlada çalışanları, Kumsa...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut Anı', 'bir-umut-ani-gul-aycan-fppu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kelimeler bir bir dizilir boğazına,

Dilinin ucuna gelir söyleyemezsin.

İçinde içinden çıkılmaz karmaşa...

Yolun hangi başlangıca varır bilmezsin.

Gözlerinde bir boşluk, bir manasız bakış...

Yanağına düşer kirpiklerindeki yaş.

Ne zaman biter bu bitmek bilmeyen kaçış? 

Ne zaman başlarsın yeniden bir hayata? 

Yürü ve git, adımların saklasın seni.

Hiçbir göz görmesin kimsesizliğini.

Kendine de güvenme, gör gerçekliğini,

Umudun hayatın kendisi olduğunu.

Haziran 2004', 'Kelimeler bir bir dizilir boğazına, Dilinin ucuna gelir söyleyemezsin. İçinde içinden çıkılmaz karmaşa... Yolun hangi başlangıca varır bilme...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-umut-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'cahit', 'cahit-cetin-hacifettahoglu-ecdh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessiz bir gemi gezerdi bu limanda

Okyanustu hayalleri

Hep fenerden döndü iskelesine

Bazen kayıklarla dertleşirdi

Bazende balıklara ses verirdi

Okyanustan haber getirirdi kılıç balıkları

Dinler dinler dertlenirdi 

Cahit adında küçük bir gemi

Elleri güvertesinde kenetli

Limanında battı en sonunda 

Cahite şahit kalmadı iskeleye vurdu sessizce güvertesi', 'Sessiz bir gemi gezerdi bu limanda Okyanustu hayalleri Hep fenerden döndü iskelesine Bazen kayıklarla dertleşirdi Bazende balıklara ses veri...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak bir balon gibi', 'yasamak-bir-balon-gibi-cetin-hacifettahoglu-i5wnc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölümmü bize öğretir yok olmayı

Yaşama sımsıkı bağlıyken kopan bir yay misali iki ayrı gelgit

Sonu olan yaşamaksa eğer

Tüm balonları patlatmalıyız

Boşa yer kaplamasınlar diye

Bizim içimizede hava basılmış değilmi sanki...', 'Ölümmü bize öğretir yok olmayı Yaşama sımsıkı bağlıyken kopan bir yay misali iki ayrı gelgit Sonu olan yaşamaksa eğer Tüm balonları patlatma...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamak-bir-balon-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne, çok acıyor..', 'anne-cok-aciyor-aysenur-yazici-v8bj3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarama üfle anne...

çok acıyor.! 

Üfle kalbime anne

çok,çok sancıyor....

  

09.01.2006

(Tophane) 

(01:30)', 'Yarama üfle anne... çok acıyor.!  Üfle kalbime anne çok,çok sancıyor....    09.01.2006 (Tophane)  (01:30)...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anne-cok-aciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kervanlik Var', 'kervanlik-var-sair-babaxyorgun-mdfgo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KERVANLIK VAR

o©º°¨¨°º©o©º°¨¨°º©o

AŞTI GÖNLÜMDE GÜNEŞİM

RUHUMDA BİR KARANLIK VAR

EL OLDU HEP YAREN EŞİM

DERTLERİM BİR KERVANLIK VAR

o©º°¨¨°º©o©º°¨¨°º©o

KİLO KİLO TARTTIM HER GÜN

ÖLÇEK ÖLÇEK ÖLÇTÜM HERGÜN

DOLA DOLA TAŞTIM BEN

DERTLERİM BİR KERVANLIK VAR

o©º°¨¨°º©o©º°¨¨°º©o

SORMA DERDİM GARİP YOLCU

HERGÜN FALA BAKAR FALCI

HESAP ETSE ARZUHALCI

DERTLERİM BİR KERVANLIK VAR

o©º°¨¨°º©o©º°¨¨°º©o

FELEK AVCI BEN BİR TURNA

UÇTUM GÖLLERİMDEN SORMA

YARAM DERİN TABİP SORMA

             DERTLERİM BİR KERVANLIK VAR

o©º°¨¨°º©o©º°¨¨°º©o', 'KERVANLIK VAR o©º°¨¨°º©o©º°¨¨°º©o AŞTI GÖNLÜMDE GÜNEŞİM RUHUMDA BİR KARANLIK VAR EL OLDU HEP YAREN EŞİM DERTLERİM BİR KERVANLIK VAR o©º°¨¨°º...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kervanlik-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalimin', 'zalimin-sair-babaxyorgun-akvuc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ZALIMIN

o©º°¨¨°º©o©º°¨¨°º©o

LAFINDA ZEHİR VAR DİLİNDE DİKEN

SÖZLERİ ACILI BATAR ZALIMIN

ODUR BOŞ YERE GÖZ YAŞI DÖKEN

TABANCASI SERİ ATAR ZALIMIN

o©º°¨¨°º©o©º°¨¨°º©o

YAKAR YÜREKLERİ KOR OYMAK OYMAK

YESEN BOĞAZINDAN GEÇMEZ BAL KAYMAK

AZGIN EJDARHASI BİLMEZKİ DOYMAK

DEVLERİ NİCE CAN YUTAR ZALIMIN

o©º°¨¨°º©o©º°¨¨°º©o

AĞRIMAYAN BAŞI DERTLERE SALAR

BAĞLAR ELİN KOLUM SIKICA DOLAR

DEVE ÜSTÜNDETKEN KUDUZDA DALAR

TİMLERİ ISIRGAN SATAR ZALIMIN

o©º°¨¨°º©o©º°¨¨°º©o

HALİL BİRGÜN DEDİKLERİM ÇIKARSA

FELEK BOĞAZIMA FERMAN TAKARSA

YAVRULARIM BOYNU BÜKÜK BAKARSA

KİMLERİ KARA YAS TUTAR ZALIMIN

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'ZALIMIN o©º°¨¨°º©o©º°¨¨°º©o LAFINDA ZEHİR VAR DİLİNDE DİKEN SÖZLERİ ACILI BATAR ZALIMIN ODUR BOŞ YERE GÖZ YAŞI DÖKEN TABANCASI SERİ ATAR ZAL...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zalimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-sair-babaxyorgun-0xso5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ANAM

o©º°¨¨°º©o©º°¨¨°º©o

ANADOLU ANALARIN DİYARI

ANAM ANAM ANAM CAN CİĞER ANAM

BABA CENNETTENMİ ALDIN BU YARİ

ANAM ANAM ANAM CAN CİĞER ANAM

o©º°¨¨°º©o©º°¨¨°º©o

KAZDIN TEPELERİ HÖLLÜK ELEDİN

BENİ SICAK KUNDAKLARA BELEDİN

OĞLUN KIZIN İÇİN NELER DİLEDİN

ANAM ANAM ANAM CAN CİĞER ANAM

o©º°¨¨°º©o©º°¨¨°º©o

SALLARSIN BEŞİKTE KOÇLUK KUZUYU

ATARSIN İÇİNE İNCE SIZIYI

YARAP YAZMA DERSİN KARA YAZIYI

ANAM ANAM ANAM CAN CİĞER ANAM

o©º°¨¨°º©o©º°¨¨°º©o

SERVETİN ADAPTIR SERMAYEN HAYA

ESALETİN ÜSTÜN TEMİZDİR MAYA

YAŞMAKLI AK YÜZÜN BENZİYOR AYA

ANAM ANAM ANAM CAN CİĞER ANAM

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'ANAM o©º°¨¨°º©o©º°¨¨°º©o ANADOLU ANALARIN DİYARI ANAM ANAM ANAM CAN CİĞER ANAM BABA CENNETTENMİ ALDIN BU YARİ ANAM ANAM ANAM CAN CİĞER ANAM ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anam-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir', 'gelir-sair-babaxyorgun-g5dgu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GELİR

o©º°¨¨°º©o©º°¨¨°º©o

ACIMASIZ DÜNYAM ATEŞ KAYNAĞIM

BUHRANLI GÜNLERDE DOĞUŞTAN GELİR

DÖŞTE OYLUM OYLUM YANAR OYMAĞIM

GÖK DUMANLAR GARİP BOĞUŞTAN GELİR

o©º°¨¨°º©o©º°¨¨°º©o

AÇIL SUSAM DERİM AÇILMAZ BAHTIM

HARABE YAŞAMDAN KURTULUŞ AHTIM

ŞANTİYE SARAYIM RANZALAR TAHTIM

BENDENİZİN SESİ KOĞUŞTAN GELİR

o©º°¨¨°º©o©º°¨¨°º©o

ZEVK SEFA SÜRMEDİM SAZ İLE BARDA

MANSURİ MİSALİ KALMIŞIM DARDA

HİÇ İNSAF YOK İMİŞ VEFASIZ YARDA

BİR SİTEMDE GÖZÜ MAVİŞTEN GELİR

o©º°¨¨°º©o©º°¨¨°º©o

YİĞİDİM GÖNLÜMDE GÜNEŞİM AŞAR

DERDİMİ DEMEYE DİLLERİM ŞAŞAR

SIĞMAZ YATAĞINA SELLERİM COŞAR

AKAN SELLER DOLU YAĞIŞTAN GELİR

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'GELİR o©º°¨¨°º©o©º°¨¨°º©o ACIMASIZ DÜNYAM ATEŞ KAYNAĞIM BUHRANLI GÜNLERDE DOĞUŞTAN GELİR DÖŞTE OYLUM OYLUM YANAR OYMAĞIM GÖK DUMANLAR GARİP ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gelir-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceremden', 'penceremden-cihan-basak-oh89w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Penceremden sokaklara

Köşesinden tutunduğum kızıllığa

Salıverdiğim dileğe

Şarkılar söylerim içimden...

Umurumda olmaz bu kent

Ne de bölük bölük yığınlar.

Rüzgarlar doldurur odamı

Asılı zerreye 

Havalanan toza bakarım.

Bulutları biriktiririm içimde

Yüksek katlı binalardan düşerim

Burnum kanar...

Günün en mahrem saatinde

Devşirme bir kinden 

Uzak bir vatana uğrarım...

Ne sen umurumda olursun 

Ne de Diyarbakır.

Perdeleri örter

Işıkları kaparım.

Sen asılı dururken dudaklarımda

Hiç umursamadan 

Ben durmadan ağlarım

22 Haziran 2002 Diyarbakır', 'Penceremden sokaklara Köşesinden tutunduğum kızıllığa Salıverdiğim dileğe Şarkılar söylerim içimden... Umurumda olmaz bu kent Ne de bölük bö...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/penceremden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parelerimi', 'parelerimi-sair-babaxyorgun-xd232', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'PARELERİMİ

NASIL İZAH EDEM TABİBİM SANA

GÖZLE GÖRÜLMEYEN YARALARIMI

BOŞUNA EL SÜRME NE OLURSUN BANA

LOKMANDA BULAMAZ ÇARELERİMİ

o©º°¨¨°º©o©º°¨¨°º©o

DİLLE TABİR OLMAZ GÖRÜLMEZ ŞEYLER

NE MERHEM EYLERSE YARADAN EYLER

ELİN GİYİNDİĞİ AL BANA NEYLER

BEN GİYDİKTEN SONRA KARALARIMI

o©º°¨¨°º©o©º°¨¨°º©o

BİR GÜZEL GÜL GİBİ DE YATAR

KOKLAMAK İSTESEM DİKENİ BATAR

SEVDA HER PARÇAMI BİR YERE ATAR

ZEMBİLDE BULAMAZ PARELERİMİ

o©º°¨¨°º©o©º°¨¨°º©o

YİĞİDİN ÖRENİ OLMUŞ BİR ÇÖPLÜK

EŞİNİR ÇÖPLÜKTE KINALI KEKLİK

FELEK BİR ÇERÇİCİ BEN OLDUM İPLİK

BEŞ KURUŞA SATAR TURALARIMI

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'PARELERİMİ NASIL İZAH EDEM TABİBİM SANA GÖZLE GÖRÜLMEYEN YARALARIMI BOŞUNA EL SÜRME NE OLURSUN BANA LOKMANDA BULAMAZ ÇARELERİMİ o©º°¨¨°º©o©º...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/parelerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Olsun', 'selam-olsun-sair-babaxyorgun-ftxdp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selam Olsun

o©º°¨¨°º©o©º°¨¨°º©o

Bu yamyamın kıymetini

Bilenlere selam olsun

Merhabayla selamını 

Alanlara selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

Sevgi güler yüz muhabbet

Dayan yüreğim sabret

İçinde var bu feraset

Bilenlere selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

Yamyam Erdal bidenesin

Nartanesin gültanesin

Sen hep dillerdesin

Ananlara selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

Burada toplanır merkezi

İçine alır tüm herkesi

Dünyayadır bu gür sesi

Duyanlara selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

Saygı kıymet içindedir

İlahi güç kalbindedir

Dierleri sor nerdedir

Gidenlere selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

Babayorgun yeter artık

Biz bu yola sizle çıktık

Ardımıza bi dönüp baktık

Düşenlere selam olsun

o©º°¨¨°º©o©º°¨¨°º©o

BABAXYORGUN', 'Selam Olsun o©º°¨¨°º©o©º°¨¨°º©o Bu yamyamın kıymetini Bilenlere selam olsun Merhabayla selamını  Alanlara selam olsun o©º°¨¨°º©o©º°¨¨°º©o Se...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/selam-olsun-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baska', 'baska-sair-babaxyorgun-v0i0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BASKA

SELAM SANA DOSTLUK YUVASI

ELİMİZDEKİ GÜLÜ VERİŞİMİZ BASKA

GÜLER YÜZLE DURAN HECOSU

BİZE MERHABA DEMESİ BASKA

o©º°¨¨°º©o©º°¨¨°º©o

MELİS KURT TİRYAKİ HALOBİNİ

NASIL UNUTURUM ATAKANLA GÜNEYİNİ

SİBELİNİ DAĞLARI EMELİNİ

COŞKUYLA GÖRMEK BASKA

o©º°¨¨°º©o©º°¨¨°º©o

ZEKİCANIMI DESEM APOCANIMI

NASIL ANLATSAM BURASINI

ESKİLER VARDI NERDELER HANİ

SİTELER İÇİNDE DURUŞU BASKA

o©º°¨¨°º©o©º°¨¨°º©o

SEVGİ SAYGI SENİN ÖZÜNDE

ŞEKER KAYMAK BAL VAR SÖZÜNDE

BİR BALIK VAR SENİN SESİNDE

ŞİRİ TÜRKÜYÜ ÇALIŞIN BASKA

o©º°¨¨°º©o©º°¨¨°º©o

TAHSİNİM SENİ UNUTMADIM

İŞTE BAK BEN HEP BURDAYIM

SEVGİ DOSTLUKTAN YANAYIM

TADIYLE BURAYI PAYLAŞMAK BASKA

o©º°¨¨°º©o©º°¨¨°º©o

BABAYORGUN SÖYLEDİ BUNLARI

TEKRAR SELAM YAMYAM DOSTLARI

ALLAHTAN GÖRÜN NİCE YILLARI

GULUMDE GULUŞUMUZ BİLE BİR BASKA

o©º°¨¨°º©o©º°¨¨°º©o

BabaxYorgun', 'BASKA SELAM SANA DOSTLUK YUVASI ELİMİZDEKİ GÜLÜ VERİŞİMİZ BASKA GÜLER YÜZLE DURAN HECOSU BİZE MERHABA DEMESİ BASKA o©º°¨¨°º©o©º°¨¨°º©o MELİS...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/baska-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Olsaydın', 'kurban-olsaydin-suheyl-turkoglu-x3hb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boğazını  bıçakla kesseler,

Akan kanına

Dua etseler,

Ölümüne

Bayram deseler.

Kurban ettik diye

Sevinseler,

İnsanları Affedermiydin?', 'Boğazını  bıçakla kesseler, Akan kanına Dua etseler, Ölümüne Bayram deseler. Kurban ettik diye Sevinseler, İnsanları Affedermiydin?...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kurban-olsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavas yavas', 'yavas-yavas-sair-babaxyorgun-i8la9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YAVAŞ YAVAŞ

Bir sancı başlar karanlık basınca

İçimde erir yavaş yavaş

Ruhum daralır isyan edince

Oflarım çoğalır yavaş yavaş

Dertler adressiz mektup olmuş

Gittiği yerlerde kaybolmuş

Rüzgar önünde savrulmuş

Gider hep yavaş yavaş

Kaderle hesap gününde

Elbet soracağım var benimde

Bir suçlu gibi hakim önünde

Paylaşırız yavaş yavaş

Ben kaçtıkca sen geldin

Gittiğim yerdede buldun

Hep başıma bela oldun

Süründürdün yavaş yavaş

Yalvardım ayrılsın yolum

Kırdın kanadım kolum

Ne olucak benim sonum

Üzüyorsun yavaş yavaş

Arkadaşın oldu yıllar

Çiçek açmaz oldu dallar

Engelledi dağlar yollar

Yuşuyla yavaş yavaş

Sen bana olmadın gardaş

Dertlerle oldun arkadaş

Gel artık limana yanaş

Boşalt dert yükünü yavaş yavaş

Sana elveda diyebilsem keşke

Ne zaman yelken açsam aşka

Hep sürdün beni yuşa

Yordun beni yavaş yavaş

Babayorgundan sitemdir bunlar

Gitti gidenler bunlar kalanlar

Elbet beni birgün anlarlar

Toprak sardığında yavaş yavaş

o©º°¨¨°º©o©º°¨¨°º©o

BabaxYorgun', 'YAVAŞ YAVAŞ Bir sancı başlar karanlık basınca İçimde erir yavaş yavaş Ruhum daralır isyan edince Oflarım çoğalır yavaş yavaş Dertler adressi...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yavas-yavas-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yanı başımda sensiz yaşamak', 'seni-yani-basimda-sensiz-yasamak-candeniz-azger-i65s6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutmak istedim seni

Unutmak istedim…

O simsiyah saçlarını

O kara gözlerini

O inceden çizilmiş kaşlarını

Çok özledim seni

Çok özledim…

O parktaki bakışlarını

O banktaki konuşmalarımızı

O karşılıklı atışmalarımızı

O kafelerde birbirimize yaslanmamızı

O seni barındıran, saran, sarmalayan şehri

Unutuyordum nerdeyse seni

Unutuyordum nerdeyse…

Ama

O çıktı karşıma

O tıpkı sen

O simsiyah saçlarıyla

O kara gözleriyle

O ince çizilmiş kaşlarıyla

O işte tıpkı sen

Bende ölen seni tekrar diriltti

Acımı çekiyorum! 

Hayır! Aksine seni onda görüyorum

Ve avutuyorum kendimi bir rüya ile

Bir rüya işte bu

Bir rüya işte…

Uyandın mı biten 

Bittiğini görünce üzen

Üzüldükçe alevlenen

Alevi yüreğimi yakan 

Bir rüya işte bu

Tıpkı sen olan o

Tıpkı senin gibi olamadı

Sen korkmazdın hiç

Konuşmadan

Tartışmadan

Yazışmadan

Dedim ya sana 

Tıpkı senin gibi olan o

Tıpkı senin gibi olamadı

Ben şimdi buna ne ad vereyim

Kader mi? 

Rastlantı mı? 

Türk filmi mi? 

Yoksa ilahi bir cezamı

Dönüp bir baktım yaptıklarıma

Acaba ne yaptım yaratana

Tek yaptığım seni sevmek

Sana bağlanmak ve sana tapmak

Bana vereceği tek ceza

Seni bana göstermek

Eski günleri hatırlatmak

Acımı çekiyorum! 

Hayır! Aksine mutluyum

Çünkü bende ölen sen tekrar canlandı

Şimdi sen olmasan da karşımda

Yine

O saçlar

O gözler

O kaşlar

Ve

O

O işte

Tıpkı sen olan ama senin gibi olamayan o

Uğraşıyorum seni öldürmeye

Taş değil bu yürek

Her onu gördüğümde sızlıyor bu yürek

Her onu gördüğümde ağlıyor bu yürek

Her onu gördüğümde unut diyorum unut! 

Ama unutmuyor bu yürek

Şimdi tek yapabileceğim

Senin gibi olamayan onu

Sevmek karşılık beklemeden

Ama dedim ya sana

O olamadı senin gibi

Yok yok suç onda değil suç bende

Cezam kesilmiş

Seni yanı başımda sensiz yaşamak

Sen olmayan onla 

Hep karşılaşmak

Bazen konuşmak

Bazen de korkarak gözlerinin içine bakmak

Dedim ya sana benim cezam

Seni yanı başımda sensiz yaşamak

Şimdi ben seni düşünüyorsam

Düşünmediğim asır gibi günlerden sonra

Biliyorum işte 

Sende beni düşünüyorsun

Zaten tek yapabildiğimiz

Birbirimizi düşünmek

Tek suçumuz

Birbirimizi sevmek

Ve benim payıma düşen ceza

Seni yanı başımda sensiz yaşamak', 'Unutmak istedim seni Unutmak istedim… O simsiyah saçlarını O kara gözlerini O inceden çizilmiş kaşlarını Çok özledim seni Çok özledim… O par...', ARRAY['Türk Edebiyatı','Şiir','Candeniz Azger']::text[], 8.5, '{"poet":"Candeniz Azger","poet_slug":"candeniz-azger","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/seni-yani-basimda-sensiz-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadığıma', 'unutamadigima-suleyman-yavuz-6ghfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum neden ama

Elimde değil olmuyor

Beceremiyorum unuttum diyorum 

Unutamıyorum 

Sen ne kadar sevmesen de 

Ben seni çok seviyorum

Nerdesin söyle nerde 

Benim canım nerede söyle

Kim bilir neredesin belki çok uzaksın

Bense buradayım bıraktığın yerde 

Uzaksın belki çok uzak ama

İnan sevdiceğim

Hasret acı olsa da 

Sevgim hep yanımda birde 

Kulağımda kalan sesin var bende

Şimdi arıyorum seni

Soruyorum herkese

Söyleyin sevdiğim

O güzel nerede', 'Bilmiyorum neden ama Elimde değil olmuyor Beceremiyorum unuttum diyorum  Unutamıyorum  Sen ne kadar sevmesen de  Ben seni çok seviyorum Nerd...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unutamadigima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-cihan-basak-rx308', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşamüstü uyanışlarım olmasa

Seni nasıl düşünürüm bilmem.

O kadar sinmişsinki içime

Seni unutabilirmiyim bilmem.

8 Nisan 2005', 'Akşamüstü uyanışlarım olmasa Seni nasıl düşünürüm bilmem. O kadar sinmişsinki içime Seni unutabilirmiyim bilmem. 8 Nisan 2005...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bilmem-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avut Bizi', 'avut-bizi-gokhan-oflazoglu-bqd7b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufukta kaybolan kuş sürüleri,

süzülür yokluğun derinliklerine.

Çırpınan belirsizlik güç bulur,

yekparedir artık kanat sesleriyle.

Öğüt dinlemeyen eylemimiz,

böyle yapın diyen yapıtları çizer,

hiç işitmemişcesine.

Her yeni gün bir itiraz, kalın

duvarlarda yankılanır.

Biz çürürüz bu zindanda, umut biraz..

Gene de dokun bin ah işitsen de.

Aykırı nameler yatıştırsın korkumuzu,

böyle bırakma bizi, alıp gitsek başımızı.

Kucak açta kayan yer yutmasın,

kollarında tut bu ürkünç yerde.

Ne kadar sızlansam duyulmaz sesim,

arada bir sorsan susardım belki.

Ne kadar sevinsem solar bir bir,

bir kere olsun tam güldür bizi.

Sürüp gitsin kahkahamın izi.

Burası ürkünç, avut bizi.

09/01/2006', 'Ufukta kaybolan kuş sürüleri, süzülür yokluğun derinliklerine. Çırpınan belirsizlik güç bulur, yekparedir artık kanat sesleriyle. Öğüt dinle...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/avut-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşkeler Olmasaydı', 'keskeler-olmasaydi-suleyman-yavuz-s4gfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke bir daha duysaydım sesini

Dokunsaydım ellerine

Baksaydım gözlerine

Ve çıksaydı hayatımdan ayrılık

Bıraksaydı yakamı hasret

Sadece sen kalsaydın bir tek geride 

Bir sen birde ben

Ve olsaydık biz ikimiz

Keşke diyorum keşke

Sen olsaydın ben olsaydım biz olsaydık

Ama bir türlü keşkeleri ve hataları

Hayatımdan silip atamıyorum

Çünkü biliyorum

Sen artık yoksun

Yoksun canım benim', 'Keşke bir daha duysaydım sesini Dokunsaydım ellerine Baksaydım gözlerine Ve çıksaydı hayatımdan ayrılık Bıraksaydı yakamı hasret Sadece sen ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/keskeler-olmasaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elleri güz / güz yabanlığı', 'elleri-guz-guz-yabanligi-zafer-zengin-etnika-w9nwi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

döndü

can içi

can göçü

nasıl ışık

güneş anlamaz

tarih yazamaz

ve harman yanar

yüreğimin 

bir köşesinde

.

gel

elleri güz

bebem

acıdan geldin

umut geldin

sevdim yalan yok

büyür şurası

dağ

yaban

çiçekleri

dost

naraları 

çalar

gözlerimden

rüzgarı…

06 07 2005

.', '. döndü can içi can göçü nasıl ışık güneş anlamaz tarih yazamaz ve harman yanar yüreğimin  bir köşesinde . gel elleri güz bebem acıdan geldi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/elleri-guz-guz-yabanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konya''dan Meltem''e', 'konya-dan-meltem-e-umit-isikdag-0a7bx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğruyu eğriyi bilemez oldum

Neden intikam var bu dünyada

Sesim kısılıdı duyulmaz oldum

Anlaşılmak çok mu zor bu dünyada..

Adını bilmem sanını bilmem

Meltem tanışır ben onu bilmem

İçime bir acı doldurur gider

Tatlıyı ne zaman görürüm bilmem

Diyorsun ki sen kandırdın beni

Beş dakika latife''ye,bu kul öle mi? 

Gerçeği söyledim ben hemen ama..

Sen kitledin kalbini o andan beri..

İlmi anlatmak çok mu zor oldu

Elsiz oldum dilsiz oldum az mı oldu 

Gönlümden kaldırdım öfkeyi ama

Ben anlayan bir toz mu oldu

O güzel Mevlana diyarındansın

O güzel gönlünü kim kırdı bilmem

Seni benden evvel üzmüşler ama..

Onlar ben değilim ki Meltem..

İnsan üzmek, ne kadar sevaptır bilmem

Gönül derviş oldu,keyf nedir bilmem

Gönlümden öfkeyi kaldırmışım ben

O yüzden sana da kızamam Meltem...', 'Doğruyu eğriyi bilemez oldum Neden intikam var bu dünyada Sesim kısılıdı duyulmaz oldum Anlaşılmak çok mu zor bu dünyada.. Adını bilmem sanı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/konya-dan-meltem-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemiş miydim?', 'soylemis-miydim-birsen-ates-s76uk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben şimdi 

kuş olup gelsem 

seni öpsem,

sende beni öper misin 

düşüme gelip..

aşk 

gözlerine henüz takılmışken 

kırıldım acıtan sözlerine.

gözyaşlarım avuçlarım da 

yüreğindeydim küçük bir serçenin

sanırım gitmeliyim.

beklediğim bir avuç maviydi 

gözlerime sürdüğün  griydi 

söylemiş miydim 

alışık olmadığım kadar 

sendeydeydim..

şimdi 

gece sağılırken güne 

içimde yolunu şaşırmış acımla 

sesimi sesinde bırakıp 

gülümseyerek 

gidiyorum..

sanırım

sende hiç kalmamışım 

ben şimdi kuş olup gelsem 

seni....................................... 

boş 

ver 

unut 

gitsin 

09.01.06', 'ben şimdi  kuş olup gelsem  seni öpsem, sende beni öper misin  düşüme gelip.. aşk  gözlerine henüz takılmışken  kırıldım acıtan sözlerine. g...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/soylemis-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Çiçek.', 'sari-cicek-i-shak-ozlu-w7s3b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eriten o gözlerin zühal yıldızı,

Bakamam yüzüne dolunayın kızı.

Çoban yıldızında asılı bir sızı,

Düştü gönül sarayıma sarı çiçek.

Yangınlar sardı gönlümü kimse bilmez,

Aşk oku yüreğimde acısı dinmez.

Beklerim sabah akşam ne çare gelmez,

Yağmur damlası ilacım sarı çiçek.', 'Eriten o gözlerin zühal yıldızı, Bakamam yüzüne dolunayın kızı. Çoban yıldızında asılı bir sızı, Düştü gönül sarayıma sarı çiçek. Yangınlar ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sari-cicek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecnebi Gibi', 'ecnebi-gibi-cihan-basak-4k7un', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok insan gibi,

Aşağılık buldum kendimi.

Düşüncelerim kabuk bağlamış,

Alnımda imza gibi.

Aklım asi.

Ruhum kendi yurdunda ecnebi gibi.

19 Ocak 2001 Diyarbakır', 'Çok insan gibi, Aşağılık buldum kendimi. Düşüncelerim kabuk bağlamış, Alnımda imza gibi. Aklım asi. Ruhum kendi yurdunda ecnebi gibi. 19 Oca...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ecnebi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledik İşte', 'bekledik-i-ste-cihan-basak-3cyxs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soluduğun hava bastığın toprak

Kokmuyor buralarda.

Kaldığın sokak,yüzüne inen sağanak

Çok uzaklarda.

Anlamsız başıboş yürüdüğüm sokak,

Soluduğum hava bastığım toprak.

Özlem hala içimde aynı korkak.

''''Bekledik işte seni be hain! 

Sensizlik zaten koca durak.

Bekledik işte seni be zalim! 

Tren garına döndü her şafak.''''

17 Mart 2001 Diyarbakır', 'Soluduğun hava bastığın toprak Kokmuyor buralarda. Kaldığın sokak,yüzüne inen sağanak Çok uzaklarda. Anlamsız başıboş yürüdüğüm sokak, Solud...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekledik-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gidiş', 'o-gidis-alper-kuruk-h6kn1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İştahım yok

Ne aş isterim ne iş

İştahtan kesti bağladı düşünceye

Beni o gidiş.

Gemiler geçtikçe Boğaz''dan

Dizim dizim diziliyor lokma

Geçmiyor boğazımdan.

Seni düşünüyorum

Yemek-içmekten kesildim hep

Bir deri,bir kemik kaldım artık.

İştahım yok

Ne aş ister gönlüm ne iş

Yok mu o gidiş,yok mu o gidiş...

Bir hasretin acısını gömdü

Acılar mezarlığı gönlüme,

Gittin o gidişte bensiz

Bensiz dalmışındır suların derinliğine

Yalnızlık ve aşkımızdan ürpermiştir

Belki için tiril tiril.

Bir vapur götürdü seni

Bir vapur düdüğünde acı düşünceler

Öldürdü beni,öldürdü beni.

Düştü gönlüm düştü yine 

Anılar serinliğine...', 'İştahım yok Ne aş isterim ne iş İştahtan kesti bağladı düşünceye Beni o gidiş. Gemiler geçtikçe Boğaz''dan Dizim dizim diziliyor lokma Geçmiy...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-alper-kuruk-ohe8i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutlarla donattığım gök

Dertlerle yitiklere karıştı

Ağlasam doldururum boşlukları

Yarı beline dek ıslak karanlıklarla.

Bir ağaç olmak isterdim

Karanlıktan aydınlığa boy atan,

Bir ömür isterdim

Önce yeşil,sonra sarı yaprak yaprak,

Bir gök isterdim

Kâlpte dualar gibi çaklı

Isı ve ışık

Ve bir rüzgâr isterdim

Başımda ılık.

İstediklerimin hepsi de var

Bulmak mı istemiyorum nedir? 

Oysaki istediklerime paydaş olmuş insanlar

Bir başımı kaldırıverip

Şöyle bakıversem

Aradığımı bulurum gökçe gözlerde

Hem de kendimi...

Öyleyse yitiğim

Işıl ışıl göğüm değil

Gökçe gözlüm.

Bir murat diye çırpınan gönlüm

Şimdi yeşil gözlerde

Şimdi yeşil gözlerde...', 'Umutlarla donattığım gök Dertlerle yitiklere karıştı Ağlasam doldururum boşlukları Yarı beline dek ıslak karanlıklarla. Bir ağaç olmak ister...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yitik-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belliyidi', 'belliyidi-mehmet-ali-kepez-pxabh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ettin artık edeceğin

                   Ben nolurum  nideceğin

                   Birgün böye  gideceğin

                   Gelişinede  belliyidi

                   Yandim bitti  yakacağın

                   Düşünce yan bakacağın

                   Bu  yuvayı  yıkacağın

                   Gülüşünde belliyidi

                   Ne tat  kaldı nede  huzur

                   İtirazın hemen  hazır

                   Her ne etsem binbir kusur

                   Buluşunda  belliyidi

                   Kepez kalasın umutlu

                   El yumağı  oldu  tatlı

                   Ben acı çekerken  sen mutlu

                   Oluşunda  belliyidi', 'Ettin artık edeceğin                    Ben nolurum  nideceğin                    Birgün böye  gideceğin                    Gelişinede  bell...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belliyidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severdim Seni Tanrı''m', 'severdim-seni-tanri-m-alper-kuruk-9tvyy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can verdi gönül şu batan akşam güneşinde

Bugün de akşam oldu.

Bir garip, medet umdu karanlıklardan

Elllerin tüm neş''esi benim bir tasam oldu.

Hani benim önceki neş''elerim? 

Hani iç ürpertici umutlarım? 

Ne oldu onlara Tanrı''m ne oldu? 

Güzelden yok kısmetimiz,neyse...

Bir çirkini bile reva görmez eller

Ben mi değiştim

Dünya mı değişti Tanrı''m

Bu insanlara böyle ne oldu? 

Bir değişme olsa ömrümde köklü

Yalnız,ölüm olmaksızın...

Sevmesem sevgiye değer her şeyi

Tüm güzellikler ki sevgi yüklü.

Yine de sevmemezlik edemezdim seni Tanrı''m

Sevgi nedir tatmamış bir adam olsam bile

Yine de sevgiden anlarım...', 'Can verdi gönül şu batan akşam güneşinde Bugün de akşam oldu. Bir garip, medet umdu karanlıklardan Elllerin tüm neş''esi benim bir tasam oldu...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/severdim-seni-tanri-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtar beni', 'kurtar-beni-mehmet-ali-kepez-5i80i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdanda olmuŞum  deli

Bak  halime  gel gÖr beni

Sana kavusamam  belli

Gel kalbimde cek  vur  beni

Kurallara  takılmışım

Kule döndüm yakilmışım

Sararıpta dökülmüşüm

Sonbahar da bir  sor  beni

Yaktın  sen asiret kızı 

Töreler ayırdi bizi

İçerimdeki  bu sızı

Kör zindanda hep kor beni

Ruyamdayım  uyanmıyom

Ateşe  düştüm yanıyom

Bu hasrete  dayanmiyom

Bir karar ver kurtar  beni', 'Sevdanda olmuŞum  deli Bak  halime  gel gÖr beni Sana kavusamam  belli Gel kalbimde cek  vur  beni Kurallara  takılmışım Kule döndüm yakilmı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kurtar-beni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlığında Üşür Dilim', 'acliginda-usur-dilim-salih-erdem-wai4k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynı göğün altındayız inan ki 

fikrime sarılmış acı bir hasret 

ne yana dönersen dön 

uykuna rahat yok 

hani derler ya 

........ gönül yorgun 

yokluğunda ne çok söz birikti 

......................sana harcanan 

ve daha kullanamadan eskittiğin 

olsun 

hatıraya sahip çıkan bir ben miyim bu şehirde

benden payına düşen ne varsa ziyan olmasın 

yamalı bir hırka gibi 

.................her sabah benliğime giyerim 

inan ki ikimiz de aynı göğe bakıyoruz

sen gözlerine özlemi giydirip 

…………………telaşları derinden çekersin sinene

sonra düşünden sıçrarsın bulutlara

bense unuttum gözlerimden yaş almayı 

ve öğrendim artık yokluğuna susmayı

biliyor musun

yokluğunda kendime yeni işler edindim

artık gök mavisinde 

………ömür eskitiyorum milim milim 

daha ne olsun ki vehmim 

tek zorum 

..............açlığında üşüyen dilim

kabından çıkar artık duygularını

dokunduğu yer huzur bulacak

kuytularında 

………hâlâ bana saklıyorsun değil mi

………………………………………..şifa sularını 

ben sayamadığım günahlarımın yüküyle

unutma her sabah 

……………bu son çıkışımmış gibi yeni güne

içime çekiyorum yoğa fakir nefesimle seni

sonra peşi sıra koşturuyorum

ve ben seninle aynı göğün altında

……………..günde bilmem kaç vakit 

sabahtan akşama

…………kendime hesap veriyorum

ve sen 

güzel aklını yormaya devam et

……….sonra benim için  dua et

18.11.2005', 'aynı göğün altındayız inan ki  fikrime sarılmış acı bir hasret  ne yana dönersen dön  uykuna rahat yok  hani derler ya  ........ gönül yorgu...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/acliginda-usur-dilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Sen', 'hersey-sen-derin-oger-xz6a6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilirmisin niye hep kalbimde yeşil kaldığını

gül''e bulanmış ellerin var yanağımı okşar

doluşur hatıralar,herşey sen olursun. 

ne zaman gam içinde bir gölge düşse gözlerime

gökte yıldız sen yanarsın,tutulurum yanışına

vurulur ışıltına,gece sen olursun.

durup durup severim seni kocaman özlemlerle

içimin mavi akışında yaşam gibi gerçeksin

karelerce çoğalıp herşey sen olursun......', 'bilirmisin niye hep kalbimde yeşil kaldığını gül''e bulanmış ellerin var yanağımı okşar doluşur hatıralar,herşey sen olursun.  ne zaman gam i...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hersey-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zayıf Kâlpli Aşık', 'zayif-k-lpli-asik-alper-kuruk-f9ehd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün sancıdı kâlbim yine

Ayak-üstü uğrayıverdim doktora

Bir iyi muayene ediverdi dost işi

Sağ olsun.

Kâlbim zayıfmış tümden

Doktor da biliverdi güzele dayanamadığımı.

Üzülmeyeceksin dedi

''Aldırış etmeyeceksin,

Gözü sen olma ağlayanların,

Boş vereceksin bazı bazı...

Ve acımayacaksın...''

Bırak dedim doktor bırak! 

İnsanım ne de olsa

Üzülme...aldırma...ağlama...acıma...

Kabil mi dediklerini tutmak

Bir insan için.

Dedim yok mu iğnen,ilacın? 

Bırak tavsiyeyi bırak! 

Kâlbimi zayıflatan kız

İşte son defa geldim kapına

Kâlbime erk ver,yalvarışlarıma umut

Ya da sert kâlbini ver bana

Tutayım doktorun dediklerini.

Ver de tutabileyim...

Başa gelen çekilirmiş diyeyim...', 'Dün sancıdı kâlbim yine Ayak-üstü uğrayıverdim doktora Bir iyi muayene ediverdi dost işi Sağ olsun. Kâlbim zayıfmış tümden Doktor da biliver...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zayif-kalpli-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Şair', 'buyuk-sair-cemal-simsek-91rkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekmek elden,su gölden

Alışmışsın yaşamaya

Oh....ne rahat hayat

Kazanan getiren var nasılsa.

Yetmiyor bütün bunlar,

Sabah kalktığında

Kahven hazır olacak.

Çocuklar yakacak sobayı

Oturacaksın sıcak sıcak,

Bilgisayarın başına

Şiirler yazacaksın,

Mısralarında

Aşk''lar,sevdalar,duygular.

Masanda boş fincanlar,

Dolu sigara tablaları,

Odan darmadağınık

Bulaşıklar yığınla mutfakta.

Müzik sonuna kadar açık,

Hüzzam makamında şarkılar.

Şiirlerini okuyanlar

Ne büyük şair diyorlar

Anlıyor Aşk''tan,sevda''dan.

Akşam eve geldiğimde

Bağırıyorsun çocuklara,

Babanız geldi,

Makarna suyu koyun  ocağa

Akşam sofrasında

Tok oluyorsun mutlaka

Biz kaşık sallarken  makarnaya,

Övgü dolu mail’lerini okuyorsun

Bilgisayarda.

Daha sofra toplanmadan

Başlıyor evde tantana.

Emirler veriyorsun boyuna,

Ne bu evin hali

Bulaşıklar kalmayacak sabaha.

Sonra bana dönüyorsun

Bir şey söyle çocuklarına

Sinir krizi geçiriyorum

Akşama kadar.

Hiç biri laf dinlemiyor

Başına buyruk olmuşlar.

Benden ses çıkmayınca

Söyleniyorsun kendi kendine

Bunlardan ne köy olur,ne kasaba.

Oğlun oturmuş bir köşeye,

Canı burnunda

Kızın bir başka odada

Gözünden yağmur gibi

Yaşlar akmakta.

Sen bilgisayarın başında

Bayram mesaj''ı geçiyorsun

Dostlarına,hayranlarına,okurlarına

Basıyorsun tek tek tuşlara

BU MÜBAREK BAYRAMDA

YÜREĞİNİZDEN SEVĞİ

YÜZÜNÜZDEN GÜLÜCÜKLER

EKSİK OLMASIN ASLA

SAĞLIKLA,  ESENLİKLE

AŞK''LA   SEVĞİYLE

NİCE NİCE BAYRAMLARA

.................................Bize ne kalıyor ki

.................................Amin demekten başka.

..........09. 01. 2006 SÖKE ....Cemal Şimşek', 'Ekmek elden,su gölden Alışmışsın yaşamaya Oh....ne rahat hayat Kazanan getiren var nasılsa. Yetmiyor bütün bunlar, Sabah kalktığında Kahven ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/buyuk-sair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamsinde Kediler', 'hamsinde-kediler-alper-kuruk-iu84p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekâr evinin penceresi önüne 

Kedilerle geldi Hamsin,

Bekâr kıskançlığı attı içinden

Bırak dedi kendi kendine

Bırak varsın

Yeni doğmuş çocuk gibi ağlasın.

Sen de bir zamanlar böyleydin oğlum...

Az mı inim inim inletti aşk seni de? 

Küskünlüğün unutturduğu bekârlığını

Hatırla şimdi kedi sesinde.

Bırak,sevişsinler bildikleri gibi

Sen de bildiğin gibi sevişmek istemez miydin? 

Hem yılda bir kere gelir Hamsin

Senin her günün aşkla geçerdi önceleri.

Sonu gelmediyse yalnız aşka küs.

Aşk,sahilsiz denizlerin tek gemisidir

Dalgalarla çalkalanır coşan gönüllerde...

Kovma kedileri pencerenden

Yum,aşk serüvenli rüyalara gözlerini.', 'Bekâr evinin penceresi önüne  Kedilerle geldi Hamsin, Bekâr kıskançlığı attı içinden Bırak dedi kendi kendine Bırak varsın Yeni doğmuş çocuk...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hamsinde-kediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-alper-kuruk-bijfg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum arkamda

Cama yapışmış burunlar kaldı.

Gidiyorum

Yarın yatacağım toprağı çiğneyerek

Belki isteyerek

Belki istemeyerek.

Gidiyorum

Dönüş ne zaman bilmem,

Cebim dolu mendilim var

Sallarım eşe-dosta

Ağlasam gözümü silmem.

Rüyalarımda hep geliyordum

Senin için uzun yollardan.

Çoktan geçiyordu yorgunluğum

Sabah olmadan.

Rüyalar tersine döndü

Şimdi hep gidiyorum,

Senden bir adımlık ayrılığın yorgunluğu

Gğnahkâr ruhlara döndürdü beni.

Bu kadar acı duymazdım inan

Boyum sıra felçlensem.

Gidiyorum senden uzaklara

Ya mektup satırlarında göreceğim seni

Ya da yine rüyalarımda...', 'Gidiyorum arkamda Cama yapışmış burunlar kaldı. Gidiyorum Yarın yatacağım toprağı çiğneyerek Belki isteyerek Belki istemeyerek. Gidiyorum Dö...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiyorum-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksürük', 'oksuruk-alper-kuruk-atzkk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkımızın bölünmesine 

Bir kem öksürük sebep oldu.

Hatırla bir güz sonu

Mehtaplı bir gecede dönüşümüzü...

Ben unutamadım bir türlü 

Dün gibi hatırlıyorum:

Bir rüzgâr vardı hafiften

Ğığış gığış ayaklarımızın altında

Bizi bir başka âleme sessizce

Aktaran yapraklar...

İçin ürperdi ansızın

Seni daha fazla kollarımda sıktım ısınasın diye

Boğazın gıcıklandı

Ve arkasından başladın tatlı tatlı öksürmeye

Öksürüklerden ördüğün acı bir besteyi...

Aşkımıza ve bana ithaf ettin...

Nöbetçin oldum günlerce yatağının başında

Senin her öksürüşüne

Ben bir sessiz hıçkırık kattım

Ayakta olduğuma bakma benim

Seninle birlikte ben de hastalanıp yattım...', 'Aşkımızın bölünmesine  Bir kem öksürük sebep oldu. Hatırla bir güz sonu Mehtaplı bir gecede dönüşümüzü... Ben unutamadım bir türlü  Dün gibi...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oksuruk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâl Külü', 'hay-l-kulu-alper-kuruk-kz472', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kafam hayâl mangalı

İçi dolu külle

Duydum bir tatlı sıcaklık

Dokununca elle.

Sıcaklık doldurdu ruhumu

Kaldırdım kolumu

Kavradım gerçeği bir maşa gibi

Mangalı eşip deştim

Üstüne geldi küllerin dibi.

Bir kor parladı kül içinden

Sarstı bütün varlığımı

Koştum binlerce emel peşinden

Renk aldı hayâllerim

Kimi kordan,kimi külden.

Gömdüm mangalın içine

Küllenmesin diye birkaç

Cehennem koru,gönülden...', 'Kafam hayâl mangalı İçi dolu külle Duydum bir tatlı sıcaklık Dokununca elle. Sıcaklık doldurdu ruhumu Kaldırdım kolumu Kavradım gerçeği bir ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayal-kulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Gideyim Ona', 'birakin-gideyim-ona-alper-kuruk-rfe9b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelere bakmışsın belli 

Ondan gözlerin böyle kara,

Bir parlaklık gözlerinde ışıl ışıl

Yıldızlardan huy kapmış.

Tarlalarda geçmiş ömrün

Yastık yapıp uyumuşsun buğday demetlerini

Saçların sararmış.

Dert yüzü görmüş olacaksın

Ki benzin de sararmış.

Bir yıldız görüyorum gecelerde

Sen de görüyorsundur elbet

Bakışlarımız birleşsin onda

Işıkcasına görelim birbirimizi

Gönüllerimizde doğsun

Başlanmadık bir aşka niyet.

Saçların gündüzler gibi uzun

Göğüslerin aşk yolunda çift tepe,

Dönüşü yok zıt yolculuğumuzun

Haykırmak istiyorum sessizliğe:

Ulak ulak olun yolar

Alıp gideyim başımı,

Yoluma durmayın dağlar

Çiğner giderim sizi.

Bir sevgili gözetlermiş yolumu

Belki güler,belki ağlar...', 'Gecelere bakmışsın belli  Ondan gözlerin böyle kara, Bir parlaklık gözlerinde ışıl ışıl Yıldızlardan huy kapmış. Tarlalarda geçmiş ömrün Yas...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birakin-gideyim-ona-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-sadettin-deren-p6rzu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz  iki aşığız,

İki serseri,

El-ele çıkar dolaşırız

Geceleri.

Vururuz elimizdekileri yere,

Çıkarız gündüzleri tepelere.

Kara dut toplar dallardan,

Kirletiriz üstümüzü,

Şarap içer naralar atar,

Tozu dumana katarız.

Karışmayın yediğimize içtiğimize

Vakit olursa belki uğrarız size,

Denizde yelken açar,uçarız,

Dostlarla tarhanaya ekmek doğrarız.', 'Biz  iki aşığız, İki serseri, El-ele çıkar dolaşırız Geceleri. Vururuz elimizdekileri yere, Çıkarız gündüzleri tepelere. Kara dut toplar dal...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biz-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-afiq-agdamli-hkjjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her lokmayı bir bölürdük,

Bir ağlayip, bir gülürdük.

Ölende de bir ölürdük,

Neden bana küstün dostum? 

Bu dostluğu kutsal sandık,

Her ateşte biz bir yandık.

Bir yürektik, parçalandık,

Neden bana küstün dostum? 

Benimleyken hayat zor mu? 

Fakirliyim sana ar mı? 

Söyle, vefan bu kadar mı? 

Neden bana küstün dostum? 

Kalbim yanıp küle döndü,

Gözyaşlarım sele döndü.

En yakınım ele döndü,

Neden bana küstün dostum?', 'Her lokmayı bir bölürdük, Bir ağlayip, bir gülürdük. Ölende de bir ölürdük, Neden bana küstün dostum?  Bu dostluğu kutsal sandık, Her ateşte...', ARRAY['Türk Edebiyatı','Şiir','Afiq Agdamlı']::text[], 8.5, '{"poet":"Afiq Agdamlı","poet_slug":"afiq-agdamli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dostum-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...ben...hiç kimse...', 'sen-ben-hic-kimse-hasan-esat-heptunali-cq1r2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadınım...

alkol halinde hallerim...

bi ben bilirim...

bi de...

hiç kimse...

nasıl da çekilmezim...

bi sen bilirsin...

bi de...

hiç kimse...', 'kadınım... alkol halinde hallerim... bi ben bilirim... bi de... hiç kimse... nasıl da çekilmezim... bi sen bilirsin... bi de... hiç kimse......', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-ben-hic-kimse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Çocuk Kalbinde Yolculuğu', 'siirin-cocuk-kalbinde-yolculugu-aynur-uluc-k2e3v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ocak ayı Cemal Süreya anma törenleri bakımından zengindi. Ben de evimde bir anma töreni organize etmeyi düşündüm. Bir Cemal Süreya seveni daha oluşturmak için elimde kitapla yanına gidip, şiirden pek de hoşlanmayan oğluma dedim ki; “Sana şiir okuyacağım.” 

''Öfff anne'' diyerek girdi söze. ''Ama'' dedim '' Ben sana gerçekten “şiir” okuyacağım Okuduğumda değil öflemek, yalvaracaksın bir tane daha oku'' diye. ''İşte sana öyle şiirler okuyacağım.'' 

Başladım ''Üçgenler”den,

“Nerde öklidin üçgenleri, bu nerde” diye bahsederken Ali’nin üçgeninden “Bir kenarı yamuk çizilmiş, Sühayla’nınki” diye diye  devam ettim usulca.

“Elma” şiiri ikinci planımdı sıradaki.

“Şimdi sen çırılçıplak elma yiyorsun / elma da elma ha Allahlık / bir yarısı kırmızı bir yarısı yine kırmızı”

C.Süreya bir çocuğun kalbine gidecek kanalı açtı bile, tahmin ettiğim gibi bu iki şiiriyle. 

''Ben ömrümde aşk nedir bilmedim, Süheyla’yı saymazsak ha ha ha” ile devam ederken tören, gülme efektlerini de birebir canlandırarak ''yumuşak g vitamini'' ni girdiriverdim devreye.

 ''Bütün mimarlar yüksek, mühendisler de, bir sen mi kaldın alçak mimar ey Sinan usta...” 

Tamamdı artık. Türkiye’nin ata halleri, Güzin’le Süleyman’ın hamam hikayesi derken “Bir tane daha yok mu sabırsızlığı” başladı bile. 

''Sizin hiç babanız öldü mü? '' dedim birden. 

''Benim öldü''

 ''Siz hiç sabunluyken ağladınız mı? ” 

Sonrası…

Sonrası, şiir şiir üstüne işte...

”Beni çocuklar anlar, ama okullarda beni okutmazlar ki” demiş ya kendisi de. Gözlerimle gördüm.ki; çok doğru. 

Başucu kitabıma ortak çıkmıştı.

Evet, kesinlikle kahvaltının mutlulukla, Cemal Süreya''nın şiiri sevmekle bir ilgisi olmalıydı.

Aynur Uluç 

Berfin Bahar / 2007 - Sayı 107', 'Ocak ayı Cemal Süreya anma törenleri bakımından zengindi. Ben de evimde bir anma töreni organize etmeyi düşündüm. Bir Cemal Süreya seveni da...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siirin-cocuk-kalbinde-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Gönlüm', 'saf-gonlum-seyfettin-bilal-ozluk-0ed65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimseyi sevmeye inanmaya gücüm yoktu

Sevemiyordum yalancı gönülleri

Üç kuruşa satılıp alınan geçimişimi bile

Bu kadar inanmazken

Sen çıktın karşıma saf gönlüme girdin...

Yüzümden düşen bin parça hayatı yaşarken

Tarifi yapılmamış küstahlıkları yaşadım

Yanlış tercih yanlış kararlar peşindeydim

Yalanı doğu doğruyu yalan bilmeye başladığımda

Sen çıktın karşıma saf gönlüme girdin...

Kurşun sıkılsa kan akmazdı senden önce

Çünki hayatın anlamı yok yaşamak boştu

Mahkumum artık yanlış karar almış olsamda

Geri dönemem yaptıklarımı unutmaya çalışıyorken

Sen çıktın karşıma ve saf gönlüme girdin...

Gelecek takvimlerimde sen varsın

Dünü kopardım ve önümde daha çok günler var

Belki yarın belki bugün yanındayım

İçimde varsın günleri saymıyorum artık

Girdiğin saf gönlümden çıkma ne olur...', 'Kimseyi sevmeye inanmaya gücüm yoktu Sevemiyordum yalancı gönülleri Üç kuruşa satılıp alınan geçimişimi bile Bu kadar inanmazken Sen çıktın ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saf-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuşsun....', 'olmussun-emin-nadir-dj1ri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Selam verdik almadın.

Selamdan kaçar olmuşsun.

Ağzın mühür,dilin kantar.

Sözünü satar olmuşsun.

Okkası kaça,dirhemi ne? 

Bir nasılsın bedeli ne? 

Fazla mı değiştin gideli ne? 

Yedi kat elden beter olmuşsun.

Zorba zoruyla hatır sorulmaz.

Aşığın sözüne nokta konulmaz.

Bundan gayri ismin okunmaz.

Hatırdan gönülden gider olmuşsun.', 'Selam verdik almadın. Selamdan kaçar olmuşsun. Ağzın mühür,dilin kantar. Sözünü satar olmuşsun. Okkası kaça,dirhemi ne?  Bir nasılsın bedeli...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankar', 'i-syankar-saadet-un-pd4ap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sanki isyankâr mı doğduk anamızdan

isyankâr mı oynadık sokaklarda

isyankâr mı sevdik delicesine

gün geçtikçe kabarıp taştı

içimizdeki volkan

gün geçtikçe unuttuk gülmeyi

acılar içinde ağladık sabahlara dek

kalmadı seven kalmadı bir dost

kalmadı güldüren kalmadı bir arkadaş

biz battıkça çamura bir tekmede onlar vurdu

biz için için ağladıkça onlar gülüyordu

çığlık çığlığa bağırdık! 

bize de bir hayat dedik

sustuk...

ne diyecekler acaba diye

dünyaya deliler dolmuş dediler

sanki isyankâr mı doğduk anamızdan

isyankâr mı oynadık sokaklarda

isyankâr mı sevdik delicesine

ne yapalım

isyankâr ettiler bizi

isyankâr!', 'sanki isyankâr mı doğduk anamızdan isyankâr mı oynadık sokaklarda isyankâr mı sevdik delicesine gün geçtikçe kabarıp taştı içimizdeki volkan...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/isyankar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konya''dan Meltem''e 2', 'konya-dan-meltem-e-2-umit-isikdag-x9g0z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sen kendini bilmeyen insan

Ben benim de söyle sen kimsin

İnsanı üzmeyi zevk sayan insan

Allah sana da iyilikler versin

İki kitap ile adam olunsa

Ben çoktan olurdum adam

Üç günde insan kendini bulsa

Önce ben kendimi bulurdum adam! 

Yaradanım aynı kızamıyorum...

Seni bir türlü çözemiyorum..

Sana da rastlamak varmış hayatta

Öfkeme gem vurdum kızamıyorum...

Ben senin gibi üzemiyorum..

Senin kadar kolay çözemiyorum

Dünya zor bir denklem Meltem

Yine de sana kızamıyorum..', 'Ey sen kendini bilmeyen insan Ben benim de söyle sen kimsin İnsanı üzmeyi zevk sayan insan Allah sana da iyilikler versin İki kitap ile adam...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/konya-dan-meltem-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekle', 'ekle-ertugrul-sakar-y1wwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu bayramda

Hüzün ekle yüreğine

Gözlerini ıslat camlarda

Dönmeyecek bir kuşun gidişini

Gelmeyecek bir ısının bitişini

Avuçlarındaki son sıcaklığı sık

Gönül zindanında volta at

Bir ah, bir of kısık

Kar beyazı bir güneştir  uçan

Hasrettir yaralar açan', 'Bu bayramda Hüzün ekle yüreğine Gözlerini ıslat camlarda Dönmeyecek bir kuşun gidişini Gelmeyecek bir ısının bitişini Avuçlarındaki son sıca...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-murat-polat-2-4rmgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüme meydan okumam

Yaradana isyan değil.

Tam tersi her an hazır olmak gibi

Yani demirlemek değil bu dünyaya

Bu dünyanın nimetlerine..

Ölüme meydan okumam

Beğenmediğimden değil asla.

Belki sıradakine yer açmak.

Belkide bir an önce kavuşmak

Sonsuz aşka...

Beğenmemek değil asla verilenleri...

Ölüme meydan okumam

Belkide korkumu bastırmak

Sanki hiç korkmuyormuşçasına.

Şundan rahatım, yok canım bence

Tüm yaşantımız onun elinde

Belki o yüzden...

Rahatlığım ve bencilliğim...', 'Ölüme meydan okumam Yaradana isyan değil. Tam tersi her an hazır olmak gibi Yani demirlemek değil bu dünyaya Bu dünyanın nimetlerine.. Ölüme...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/belki-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylüle İsyan', 'eylule-i-syan-ali-gencay-tn7id', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I-

Neden diyorum, neden

Dünler naftalin kokar burnuma

Yitirilmiş eskiler mi yakar genzimi

Yoksa unutulan neşeler mi düşer kursağıma

Mazimde terkedilmiş sandallar 

Kaburgasında çatırdayan sabırsızlık

Yorulmadı dalgalara dövülmekten

Gövdesinde ‘sevdam’ yazar

Bilirim bu beklemeler haksızlık

II-

Eylül mü bu

Beni benden alan

Hazan mı bana

Kaç var doğum sancına

Doğar mı sarı saçlı kız

İçimde isyan/arsız/sabırsız

Sen doğur güneşi gelsin bahar

Bana bakma sen, aldırma

Bir, bir tüketmişim yeminleri

Durumum rüsva/rezil

Sökülmüş kaburgamdan sanki kalbim

Heyecanım dağıtılmış, sebil

Sende gidersen eylül gibi

Ben öldüm, bil

III-

Karınca yüreğim, kararınca

Ölümüne vurulmuş dağlar sırtıma

Ya aşk neyler adama, neyler bana

Ayrılık bu, bakmak çok uzaklara

İnat değimli, ölmemeliyim

Kırparsam gözlerimi, sakın bağışlama', 'I- Neden diyorum, neden Dünler naftalin kokar burnuma Yitirilmiş eskiler mi yakar genzimi Yoksa unutulan neşeler mi düşer kursağıma Mazimde ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/eylule-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın Aşk', 'yasasin-ask-bekir-mutlu-gokcesu-whuxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelip geçer sıcaklığı ellerimin

Gün olur söner feri yüreğimin

Lakin aşk yaşasın

Işıklarınca gecelerin

Ve sonsuzluğunda dizelerin...

Tozu kadar yitimsiz bir çiçeğin

Yükünce özlem ve umut 

Kanatlarında bir kelebeğin

Bir bakış kadar ebedi ve derin

Yaşasın aşk, yaşasın su gibi...', 'Gelip geçer sıcaklığı ellerimin Gün olur söner feri yüreğimin Lakin aşk yaşasın Işıklarınca gecelerin Ve sonsuzluğunda dizelerin... Tozu kad...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasasin-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sohbeti', 'dost-sohbeti-nurten-altinok-cpnmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                                 



Sıradan dilekler dilenir, dökülür sayfalara

Amaç bayramı kutlamaksa

Gerek var mı bu kadar süslü laflara

Yapmayacağım hiç birini

Bilirsiniz siz benim içimi, dışımı

Doğrumu, yanlışımı



Susarım dilime dolaşınca mısralarım

En acemi yönümdür susmalarım



Sarılıyorum hepinize tek tek, yürek yürek

Kimsiniz, nerdesiniz, ne yaparsınız, hiç önemli değil

Şu an benimlesiniz

Bendesiniz

Elleriniz gözümdeki yaşa uzanmış, hissediyorum

Yürekleriniz sarmış sarmalamış yalnızlığımı

Siz hep buradaydınız 

Hep buradasınız

Biliyorum

Bayramınızı kutluyorum

Sarılıyorum hepinize 

Kokluyorum 



Tenin sesini dinle

Sunam, çok uzaklardan, Amerika''dan

Kara İbo''m Ankara’dan

Feride''m Üsküdar''dan

İsveç’e yolcudur bugün Handan’ım

Gurbet bayram dinlemiyor be canım



Susarım dilime dolaşınca mısralarım

En acıtan yanımdır susmalarım

Gelincikler gelir aklıma Nesrin’im

Düşerler yola Antalya’dan

Betül’üm gelir Düzce’den, Zafer’im

Ellerinde yenigelin çiçekleri

Ve de birilerinin İnci tanesi üşür yüzümde

Aha şuramda, yanıbaşımda Avcılar’da

Bırakmaz dost elleri ellerimi



Susarım dilime düşünce mısralarım

En acıyan yanımdır yalnızlığım

Bayramınız bayramımız olsun

Sarılırım tül titremesi yüreklerinize

Sığınırım avuç içi sıcaklığınıza

Tenin sesini dinle





Nurten Altınok

09/01/2006', 'Hoşgeldiniz                                    Sıradan dilekler dilenir, dökülür sayfalara Amaç bayramı kutlamaksa Gerek var mı bu kadar süs...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dost-sohbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-selcen-boyar-4cb0e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamak çare olsaydı seni unutmama /

Derya olur taşardı göz pınarlarım; 

/lakin seni unutamadım

Kelimeler dile gelmeseydi /

sağır olurdum/ dilsiz olurdum /

Ama yinede unuturdum.

Lakin kelimeler hiç susmadı /

Şu kalbime  seni unutturamadı', 'Ağlamak çare olsaydı seni unutmama / Derya olur taşardı göz pınarlarım;  /lakin seni unutamadım Kelimeler dile gelmeseydi / sağır olurdum/ d...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutamadim-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-selcen-boyar-bvt4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çaresizliğin verdiği acıyla kıvranmaktayım.

İçim acıyor. / Yüreğim acıyor /

Çok hem de çok...

Yılların verdiği o birikmiş acıların/ 

Hepsi çöreklendi yüreğime /

Dayanabilmek ne çare.

Hareket edip yürüyememek/

Uzanıp sana / ellerini tutamamak,

Koklayamamak doyasıya /

Miski amber kokulu vücudunu

Ne acı bebeğim.

Hele o arkamdan bakakalan çaresiz bakışlara /

Umut verememek ne acı /

Benim öpmeye kıyamadığım /

O kara gözlerinden akan /

O her tanesi inci-mercan gözyaşlarına /

Mani olamamak ne acı....

Minicik yüreğinde atan o gitme korkusuna

Uykunu bölen kabus olan o sabahlara/

“annecim hemen gel” diyen o ballı yakarışlara

Umarsız kalmak ne kadar acı', 'Çaresizliğin verdiği acıyla kıvranmaktayım. İçim acıyor. / Yüreğim acıyor / Çok hem de çok... Yılların verdiği o birikmiş acıların/  Hepsi ç...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aci-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev', 'sev-selcen-boyar-6c06r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni öyle sev

Öyle sevki,,,,,,,

Her hücremde seni hissedeyim

Dokularım seni zikretsin

Öyle sevki beni

Sensiz iken ben öleyim….', 'Beni öyle sev Öyle sevki,,,,,,, Her hücremde seni hissedeyim Dokularım seni zikretsin Öyle sevki beni Sensiz iken ben öleyim…....', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sev-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-selcen-boyar-0100c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığın acısı yüreğime düşünce 

Bir sızı saplandı içime gizlice

Sancır durur zaman zaman delice

Ayrılık sözü aklıma geldikçe

Hep korkar dururum ha geldi ha gelecek

Bir gün beni yarimden edecek

Bu ayrılık beni bir gün değil

Her gün biraz biraz öldürecek', 'Ayrılığın acısı yüreğime düşünce  Bir sızı saplandı içime gizlice Sancır durur zaman zaman delice Ayrılık sözü aklıma geldikçe Hep korkar du...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-324-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar bayram olsun', 'bayramlar-bayram-olsun-durmus-karakus-3vrab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinleyin ahali dinleyin beni,

Heryanımı sardı keder ile gam,

Ev sahibim ile konuştuk yeni,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.

Dur be abi dedim insafın yokmu,

Suratını astı dedi ki çokmu,

Düşünmedi bile açmısın tokmu,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.

Asgari ücrete sabır diyordum,

Güngelir ekmeği yavan yiyordum,

İnan böyle birşey beklemiyordum,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.

İster gelir ister gelmez işine,

Paramı ver dedi ayın beşine,

Eşim bana baktı ben de eşime,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.

Gözüm de yaşlarım sel oldu akar,

Kapısından döndüm ben yalvar yakar,

Ev sahibi beyim bizi kim takar,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.

Karakuş: almadım üst başa giyim,

Böyle yaşamaya alıştık beyim,

Şeytan''ından bulsun başka ne deyim,

Evin kirasına yüzde elli zam,

Zehir oldu yine bize bu Bayram.', 'Dinleyin ahali dinleyin beni, Heryanımı sardı keder ile gam, Ev sahibim ile konuştuk yeni, Evin kirasına yüzde elli zam, Zehir oldu yine biz...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bayramlar-bayram-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemiyorum', 'olemiyorum-selcen-boyar-g6p7m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu kalbimi bir görsen

Dayanabilir misin ızdırabına bilmem

Öyle çok acıyor öyle çok acıyorkiii

O acıya dokunabilir misin bilmem

Ağlayamıyorum

Gülemiyorum

Anlamsız bişey oldum

Kendimi çözemiyorum

Bakıyorum göremiyorum

Duyuyorum  anlam veremiyorum

Nefes alıyor bu vucut 

Her tik takta

Ama yaşayamıyorum

Her nefes alışımda

Her sefer bitiyor hayat

Ama

Ama ölemiyorum', 'Şu kalbimi bir görsen Dayanabilir misin ızdırabına bilmem Öyle çok acıyor öyle çok acıyorkiii O acıya dokunabilir misin bilmem Ağlayamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olemiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasılsın, İyi misin?', 'nasilsin-i-yi-misin-bekir-mutlu-gokcesu-eoiu5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yıldız gözler beni

Yüzümü, ellerimi

Bir yıldız saatlerdir

Bekler onu fark etmemi...

Sonu gelmez ışıkların

Bitiremem geceyi

Birleştiremem iki heceyi...

Nice sonra göz göze geliriz

Orada bir yıldız, yapayalnız

Sorar halimi...', 'Bir yıldız gözler beni Yüzümü, ellerimi Bir yıldız saatlerdir Bekler onu fark etmemi... Sonu gelmez ışıkların Bitiremem geceyi Birleştiremem...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nasilsin-iyi-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anayurt', 'anayurt-mikdat-bal-p3em9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oku okut veya dinle üçten ol 

Ne arkada, ne ortada uçtan ol 

Cehaleti yok edecek güçten ol 

Anayurdu baş uçundan ayırma 

Kullanmaya kullanmaya Türkçeyi 

kekeleriz çıkarırken heceyi 

Ay yıldızsız kim neylesin geceyi 

Anayurdu baş uçundan ayırma 

Her gün izle hafızanı tazele 

Unutmazsın göz atarsan güzele 

Şimşek çaksa hoplatsa da zelzele 

Ana yurdu baş uçundan ayırma 

Anayurttan bir pencere açıldı 

Kolay değil bin engelden geçildi 

Hediyenin en güzeli seçildi 

Anayurdu baş uçundan ayırma 

''Anayurttur'' görün ne güzel adı 

Orada işlenir Türk`ün sanatı 

Ali Gündüz Şair, şiir üstadı 

Anayurdu baş uçundan ayırma 

Mikdat Bal`ım selam sevgi herkese 

Çifte selam hele bir de Türk ise 

Gurbet demek Anayurdu Terk ise 

Anayurdu baş uçundan ayırma', 'Oku okut veya dinle üçten ol  Ne arkada, ne ortada uçtan ol  Cehaleti yok edecek güçten ol  Anayurdu baş uçundan ayırma  Kullanmaya kullanma...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anayurt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe Yüreği', 'serce-yuregi-serdar-erdemir-nujwg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dışarıdan bakınca; yumruk kadar/

alabildiğine dar...

üstüne üstlük parmaklık var,

içerden cam, çerçeve

hani şu bildik; 

karanlık deve ışık sunan/

tek gözlü, kör pencere

bir saksısı eksik, bir de gül

ne perde takılı ne de tül..

kapkara bir gölge gibi; 

gökyüzüne yükselen minareden/

masmavi bir musiki

uykusu kaçmış bir serçe

belki yorgunluktan; 

belki de meraktan. 

geçerken kondu; hasta çınara

göz ucuyla bakar; 

koğuşun sağdan üçüncü/

sol penceresine....

gören teselliye gelmiş der.

bir de mahareti var kendince

eşlik eder; minareden yükselen musikiye

kafa sallar, çırpınır durur.! 

tez canlı; fermanı dilinde

dışarıda lapa, lapa kar

kırık camdan içeri/

toprak kokulu, rüzgâr uğuldar

zahir bundandır kahrı

kurşun olsa ağzında; 

ancak bu kadar vurur

küçücük yüreğinde ne ahkâm, ne gurur

buz kesmiş pencereye; tüm cesaretiyle

hohlar durur…

kendi özgürlüğünü yaşamaz

bilmem ne buldu bende

derdime ortak olur.

takvimi belli her gün doğumunda/

gelir kör penceremde huzur bulur…', 'dışarıdan bakınca; yumruk kadar/ alabildiğine dar... üstüne üstlük parmaklık var, içerden cam, çerçeve hani şu bildik;  karanlık deve ışık s...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/serce-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünbaz Geceler', 'huzunbaz-geceler-h-hikmet-esen-ouw00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdaların 

Gönüllü vurgun yediği saatler. 

Güneş saklanmış

Sabahın özlemiyle

Zeytinlerin ardına.

Mevsimler 

Gün be gün

Dökülürken 

Takvim yapraklarına.

Zaman

Dört dönüyor

Yalnızlığın

O ürkek akşamlarında.

Miadı dolmuş hüzünler

Akıp giderken

Sulusepken.

Onulmaz özlemlerim

Nihavent''e geçiyor

Mahur bestelerin 

Esaretinden.

Bilirim

Alıkonmuş zamanlarda saklıdır anılar.

Ama bunaldıkça

Ya, deniz çeker 

Yüreğini insanın

Ya başına

Duvak takınan dağlar.

Yarınlar çiçeklenirken

Gözbebeklerimde.

Tomurcuklarından 

Çiğ tanecikleri dökülür

Satırlarına yaşamın.

Umutlarım

Islansın ıslanmasına

Dert değil de; 

Hüzünbaz kesilir

Geceler

Durup dururken

Dokunur yüreğime...

H Hikmet Esen', 'Sevdaların  Gönüllü vurgun yediği saatler.  Güneş saklanmış Sabahın özlemiyle Zeytinlerin ardına. Mevsimler  Gün be gün Dökülürken  Takvim y...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/huzunbaz-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
