INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet', 'sikayet-zahide-handan-erengil-evb7h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir can büyütmek,

Büyük eziyet emek,

En büyük cehalet ise,

Bunu bilmemek, hissetmemek.

Kimyasal,nükleer silah dendi,

İnsanların hakkı,hukuku yendi.

Irak ta kadın, çocuk demeden,

Katliam yapıldı niçin,neden? 

Şimdi için buldu mu huzuru? 

Nerede insanların,haysiyeti onuru? 

Tutturmuşlar bir gece yarısı ekspresi,

Ermeni meselesi,

Bunların,ırak ta,Filistin de,

Yaptıkları neyin nesi? 

Bunlara kim cevap verecek? 

İnsan hakları ne zaman iade edilecek? 

Şimdi sıra kime geldi belli mi? 

Dökülen kanların hesabı verildi mi? 

Ne zaman bu kanlar dinecek? 

Dünyaya ne zaman gerçek barış gelecek? 

Siz diyorsunuz ki çocuklar değil önemli,

Biz diyoruz ki çocuklar hep gülmeli.

En büyük örnek 23 nisan çocuk bayramı,

Hayret,tutumunuz çıldırtıyor insanı.

Bıkmadınız mı kan ve barut kokusundan? 

Kadınlar,çocuklar kaçıyor can korkusundan.

Yapmayın,etmeyin bu kadar zulüm,

Mutlak hepinizin de sonu olacak ölüm.

Yazıktır kıymayın masumlara,

Açmayın her gönülde bir yara.

Bir gün sen de çıkarsın o büyük huzura,

O zaman sen de verirsin hesabını,

Yalvarırsın da kimseler duymaz ahüzarını,

Şikayetim insan hakları mahkemesinedir,

Elbet bu insanların hakkı ödenecektir.', 'Bir can büyütmek, Büyük eziyet emek, En büyük cehalet ise, Bunu bilmemek, hissetmemek. Kimyasal,nükleer silah dendi, İnsanların hakkı,hukuku...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sikayet-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedim', 'i-stedim-aysel-al-y4azz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerimde kaybolurken

Avuçlarının arasından fışkırıp kaymak

Gökyüzüne uçmak

Bütün mutlulukları toplayıp

Sonra,

Avuçlarına sunmak istedim

Yaşama sevinciyle yağmur yağar gibi

Mutluluk göz yaşlarıyla

Yüreklerimiz yıkansın istedim

Neredesin?', 'Gözlerin gözlerimde kaybolurken Avuçlarının arasından fışkırıp kaymak Gökyüzüne uçmak Bütün mutlulukları toplayıp Sonra, Avuçlarına sunmak i...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istedim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrencinin Yakarışı', 'ogrencinin-yakarisi-seyfet-bozcali-77rk8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mesleğine özenirdim küçükken,

Adını öğrendim kalem tutmazken,

İlk beni sen diktin, taze fideyken,

Büyüt meyvesini gör öğretmenim...

Eğitmek öğretmek senin görevin,

İyi bak ki açıversin güllerim,

Işık saçki aydınlansın yollarım,

Karanlıkta koymayın öğretmenim...

Değerini bilde koru mesleğin,

Daim senin kıymetini bileyim,

Cahil kalsam dünya malı neyleyim,

Eğiterek yön verin öğretmenim...

Bilgi damarımda kan öğretmenim,

Sen öğretmezsen kime giderim,

Boş kafayla bu alemde  nederim,

Cehalet içinden al öğretmenim...

Doğru yolda yürü izin süreyim,

Şefkati,sevgiyi sizde bulayım,

Anne, baba gibi yakın göreyim,

Kucakla bağrına sar öğretmenim...', 'Mesleğine özenirdim küçükken, Adını öğrendim kalem tutmazken, İlk beni sen diktin, taze fideyken, Büyüt meyvesini gör öğretmenim... Eğitmek ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogrencinin-yakarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrailim Sensen Eğer!', 'azrailim-sensen-eger-tunay-karaca-5nmsn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eskiden buse çiçekleri açardı suratım da, en güzeli de dudaklarım da açardı! bakışımı sevdiğini söylerdin; gülerdim, gülüşümü de severdin..... 

artık kalmadı hiç biri, senin ardından bakışım da gülüşüm de gitti, o gün mıh gibi aklımda şimdi... 

kendi ellerimle götürmüştüm seni, daha önce de gidişlerin olmuştu, ne bakışlarımı ne de gülüşlerimi almıştın yanına, yanına ufak bir çanta alıp veda etmeden giderdin, çok geçmeden geri; dönerdin. o gün veda etmiştin! 

o gün bavullarını hazırlarken, ben ölmeye çalışmıştım, ölmedim ama bavullarını taşıdım tren garına. sen de iki bavul dolusu eşya, ben de bir tren dolusu hüzün almıştım yanıma.... 

tren garı hep mezarlık gibi gelir bana, tren gelir herkez orada, tren gider çesetler kalır ortada. hepsinin hikayesi farklıdır ama ayrılık var orta da; koyuyor insana.. 

o gün son bakışında şamar otları bitmeye başladı suratımda. zaten o eski gülüşüm de bakışım da yok artık. giderken yanına kalbimi de almışsın yeni farkına vardım. öldürmekse amacın başaramazsın... 

azrailim sensen, sana vermem bu canı, çırpına çırpına yaşarım bu hayatı sana inat.. 

kaç kere alnımın ortasına sıktın gittiğinden beri, kaç kez kalbimi söküp aldın, kaç kez bu bedenden başımı ayırdın; ölmedim! 

azrailim sensen, sana vermem bu canı, çırpına çırpına yaşarım bu hayatı sana inat!', 'eskiden buse çiçekleri açardı suratım da, en güzeli de dudaklarım da açardı! bakışımı sevdiğini söylerdin; gülerdim, gülüşümü de severdin......', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/azrailim-sensen-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Kadar', 'sevgi-kadar-seyfet-bozcali-c2mvk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi kadar güzel şey var mı? 

Sizlere soruyorum çocuklar.

Sevgiği,şefkati güzelliği,

Yaşınız küçük ama bilirsiniz siz...

Sevgi kadar güzel şey var mı? 

Size soruyorum dostlar,

Tecrübeler ve yaşantınızdan,

Sevgiyi insanlığı anlarsınız siz...

Sevgi kadar güzel şey var mı? 

size soruyorum kitaplarım.

Her sayfanızda ayrı bilgiler,

İğiliği,doğruluğu anlatırsınız siz...

Sevgi kadar güzel şey var mı? 

Size soruyorum tüm insanlar.

Din,dil,ırk ayrımı yapmadan,

Sevgi ile yaşarsınız siz...', 'Sevgi kadar güzel şey var mı?  Sizlere soruyorum çocuklar. Sevgiği,şefkati güzelliği, Yaşınız küçük ama bilirsiniz siz... Sevgi kadar güzel ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Dili Olsa', 'ozlemin-dili-olsa-aysel-al-08w5a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni özlediğimi söylüyorum

Bu nasıl bir şey

Ah keşke! 

Özlem denilen duygunun

Dili olsa da anlatsa kendisini

Anlatamıyorum

Yüreğimdeki o coşkuyu

Haykıramıyorum

Senin  yanında olsam da yine

Seni özlüyorum

İsimlendiremiyorum

Özlem denilen duygu

Anlatsa

Küçük küçük mutlulukların

Yaşama sebebi olduğunu

Söylesene bir tanem

Anlatabilen var mı sence

Aşklar, arkadaşlıklar, bütün duygular

Mutluluklar, mutsuzluklar

Diye söylüyor bilenler

Fakat bir tanem

Özlem

İki dudağının arasından dökülen

Seni seviyorum demekte...', 'Seni özlediğimi söylüyorum Bu nasıl bir şey Ah keşke!  Özlem denilen duygunun Dili olsa da anlatsa kendisini Anlatamıyorum Yüreğimdeki o coş...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ozlemin-dili-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Gelen Vuslatımsın Benim', 'gec-gelen-vuslatimsin-benim-zeliha-bicer-6amt6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaç dalındaki çiy damlası

Sabahlarımdaki mavim

Şiirlerimin hüznü,

Sevinci,mutluğu

Sen benim hasretimsin.

Bestekarın ilhamı gibi,

Kemanında ki notası,

Sesinin tınısındaki,

Sevgim gibisin.

Yazılmamış mektuplarım,

Edilmemiş dualarım,

Söylenmemiş şarkılarım,

Geç gelen vuslatımsın benim...', 'Ağaç dalındaki çiy damlası Sabahlarımdaki mavim Şiirlerimin hüznü, Sevinci,mutluğu Sen benim hasretimsin. Bestekarın ilhamı gibi, Kemanında ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gec-gelen-vuslatimsin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Depremlerim', 'senli-depremlerim-zeliha-bicer-mvwiu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçi oyulmuş ağaç kovuğu gibiyim

İçtiğim ne çayın tadı var

Ne de sigaramın dumanında sen

Rüyalarıma kilit vurdum

Giderken,eve sinen kokunda

Tepeden tırnağa

Ruhumun derinlikliklerinde

Senli depremlerim vardı..', 'İçi oyulmuş ağaç kovuğu gibiyim İçtiğim ne çayın tadı var Ne de sigaramın dumanında sen Rüyalarıma kilit vurdum Giderken,eve sinen kokunda T...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senli-depremlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Açılan Cennetimsin Benim', 'yuregime-acilan-cennetimsin-benim-zeliha-bicer-4bbtc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahçeye girmiş gibi gönlüm

Öyle renkli,öyle güzel öyle saf ki çiceğim

Seninle açılan pencerelerimin

Mutluluğu, huzuru, sevgisi var

Şükrettim Tanrı''ya defalarca

Ömrümün bu sonbaharında

Kapı çalıp geldiğin için

Dostluğunu,arkadaşlığını sevdim

Seninle güldüm,ağladım,sevindim

Bana yaşam yoldaşım dedin

Yüreğime açılan cennettimsin benim.', 'Bir bahçeye girmiş gibi gönlüm Öyle renkli,öyle güzel öyle saf ki çiceğim Seninle açılan pencerelerimin Mutluluğu, huzuru, sevgisi var Şükre...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuregime-acilan-cennetimsin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazsın..', 'unutamazsin-durdane-demirkoparan-a41rq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutamazsın beni

İstesen de

Savaşsan da yüreğinle

Silemezsin hatıralarımızı

Unutsan bilirdim

Ben unutamam

Sende unutamazsın

Biz iki can bir beden olduk 

Ruhumuz birleşti

Seni ayrı görmedim benden

Sende göremezsin

Yüreğin kaçamaz sen kaçsanda

Gün gelir

Sende haklıymışsın dersin

Geç olur belki

Ama unutamazsın

Senin canın yansa benim yanar

Sen unutsan bende unuturdum

Ben unutmamışsam seni

Ben silememişsem yüreğimden

Atamamışsam en kötü resmini bile

Ve yanıyorsa içim hala

Unutamazsın...', 'Unutamazsın beni İstesen de Savaşsan da yüreğinle Silemezsin hatıralarımızı Unutsan bilirdim Ben unutamam Sende unutamazsın Biz iki can bir ...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutamazsin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamam ki,', 'dayanamam-ki-ramazan-ates-u3kez', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözünden bir damlacık yaşın aksa,

Kahrımdan ölürüm, bir tanem benim.

İçin burulsa da, kaşın çatılsa, 

Kahrımdan ölürüm, bir tanem benim.

Her zaman mutlu ol, gülsün yüzlerin.

Daima sevinç saçsın gözlerin.

Bir an bile üzgün olsa sözlerin,

Kahrımdan ölürüm, bir tanem benim.

Arzuların gerçekleşsin hep senin.

Düşlerinde bile, mutlu olup gülesin.

Elem, keder, asla sana gelmesin,

Kahrımdan ölürüm, bir tanem benim.

Seninle her şeye varım, bilirsin.

Sen, benim bir tanem, sevdiceğimsin.

Sensiz olmaktan sa, hayatım bitsin,

Kahrımdan ölürüm, bir tanem benim.

Ramazan Ateş/Enschede-9.1.2006', 'Gözünden bir damlacık yaşın aksa, Kahrımdan ölürüm, bir tanem benim. İçin burulsa da, kaşın çatılsa,  Kahrımdan ölürüm, bir tanem benim. Her...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dayanamam-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Olsaydı Ahhh..', 'elimde-olsaydi-ahhh-ramazan-ates-81tk6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilseydim sen gibi güzel doğacak,

Belki de gelmezdim, erken dünya’ya.

Bilseydim bunca yıl sensiz kalacak,

Belki de gelmezdim, erken dünya’ya.

Erken geldim sanki, neyim değişti? 

İçime hep acı, ateşler düştü.

Seni buldum ama, iş işten geçti,

Bilseydim gelmezdim, erken dünya’ya.

Sonbaharda açan çiçek gibisin,

İçimde saklayım, söyle ne dersin? 

Bilseydim seni ben böyle seveyim,

Belkide gelmezdim, erken dünya’ya.

Alın yazımızı yazan kalemi,

Silmeye bir silgi var mı elinde? 

Erken gelmek sanki benim elimde,

Bilseydim gelmezdim, erken dünyaya.

Bilseydim, gelmezdim sensiz dünyaya.

Ramazan Ateş/Enschede-9.1.2006', 'Bilseydim sen gibi güzel doğacak, Belki de gelmezdim, erken dünya’ya. Bilseydim bunca yıl sensiz kalacak, Belki de gelmezdim, erken dünya’ya...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/elimde-olsaydi-ahhh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Bayram', 'huzunlu-bayram-abdullah-gencay-4d9no', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soy ağacımın ana dalları

Kırılıp düşüyor toprağa birer birer

Küçük dalların,  boynu bükük

Hüzün girdi yine bayrama

Yüreğim buruk darmadağın

Haziranda sel girmiş tarla sanki

Giden benim canım, kanım

Hüzün girdi yine bayrama

Emanet bedeni bıraktı toprağa

Hesap günü açılmak üzere

Onlarca torun bıraktı, soy ağacına

Hüzün girdi yine bayrama

Hacı dayım, ağam benim

Sinirli, ters görünen ama mangal yüreklim

Son kez ellerini öperim

Rabbine kavuştun, bayramın mübarek olsun

Bizde ise hüzün bıraktın, Allah rahmet etsin.', 'Soy ağacımın ana dalları Kırılıp düşüyor toprağa birer birer Küçük dalların,  boynu bükük Hüzün girdi yine bayrama Yüreğim buruk darmadağın ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzunlu-bayram-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapattım', 'kapattim-i-brahim-karaca-zn3hp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel bir sevda çektim

Acı bir sevgi tattım

Bana gülü anlatmayın

Ben gülü kokladım

Acı cekmek istemem

Hislerimi körrerttim

Teselliyi çok görmem

Artık gönlümü kapattım

Bakmayın artık gözlerime

Kimseyi göremezsiniz

Kapatım gönlümü

Kimseyi bulamazsınız

1984

             İbrahim Karaca

                       Bafra', 'Güzel bir sevda çektim Acı bir sevgi tattım Bana gülü anlatmayın Ben gülü kokladım Acı cekmek istemem Hislerimi körrerttim Teselliyi çok gör...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karaca']::text[], 8.5, '{"poet":"İbrahim Karaca","poet_slug":"i-brahim-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kapattim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Doğan Çocuk', 'aciya-dogan-cocuk-ceren-gurakar-0bzrp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak gibi olmak...

Her mevsim, başka umutlara gebe kalmak.

Benim toprağım mutsuz...umutsuz...

nasıl bir damla yağmur değmemiş,

Yeşermesin... saramasın yaralrını diye,

Nasıl büyütememiş, hiç bir çocuğu gönlünde

Benim toprağım nasıl naçar ise

Gönlümde öyle...

Bizim oralarda her çocuk 

Umuda yenik doğmuş.

Ayağı yalın...

Güçsüz gama, kedere

Gözleri toprak kadar kara

Sevgiye hasret...

Sevdaya yenik

Onca zaman geçmiş

Değişmemiş yazıları

Her doğan bebeğin yüzünde...

Koca bir adam

Acıya doğan 

Acıya ölen', 'Toprak gibi olmak... Her mevsim, başka umutlara gebe kalmak. Benim toprağım mutsuz...umutsuz... nasıl bir damla yağmur değmemiş, Yeşermesin....', ARRAY['Türk Edebiyatı','Şiir','Ceren Gürakar']::text[], 8.5, '{"poet":"Ceren Gürakar","poet_slug":"ceren-gurakar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aciya-dogan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrıyı Kaybeden İnsan', 'tanriyi-kaybeden-i-nsan-tunc-tasbas-1-ivkf8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlara git, cehennem orada,

Sen kim oluyorsun da kendini yalnızlığa layık görüyorsun,

Yalnızlık ödüldür, senden önce buraya gelenler yalnızlığı sadece bana yakıştırmadılar mı? 

Sen yalnızlığı hakedecek ne yaptın? 

İnsanlara git, 

Özgürlüğünü ver onlara,

Bağlan, 

Tat Havva''nın elmasından,

Bu ceza yeter mi sana,

Ateşimi çalmaya çalıştın,

Seni büyük kayalara bağladım,

Yalnızlığımı çalmaya çalışıyorsun,

Seni hicran denizine atıyorum,

İnsanlara git,

Bu senin cezan.

2004 İzmir', 'İnsanlara git, cehennem orada, Sen kim oluyorsun da kendini yalnızlığa layık görüyorsun, Yalnızlık ödüldür, senden önce buraya gelenler yaln...', ARRAY['Türk Edebiyatı','Şiir','Tunç Taşbaş 1']::text[], 8.5, '{"poet":"Tunç Taşbaş 1","poet_slug":"tunc-tasbas-1","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanriyi-kaybeden-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yattılar kalktılar AB dediler', 'yattilar-kalktilar-ab-dediler-mikdat-bal-4wf6t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yattılar kalktılar AB dediler

Büyük bir hayale dalıverdik biz

Satacağız diye hibe dediler

Ancak birbirini yoluverdik biz

Milli gelir dondu ihracat sıfır

Yabancılar artık değil misafir

Bize emir verrir yabancı sefir

Tüketen bir toplum oluverdik biz

Açıktan pazarlık Kıbrıs verildi

Savunanlar hain dendi, yerildi

Çok şey kayıp ettik, çok şey kırıldı

Parmak istediler kolu verdik biz

Bu hikaye Türk’ün gerçek kıssası

Dediler adalet mülkün esası

Uydurdular bir şey “uyum yasası” 

Çalanı, katili salıverdik biz

Bunlar Avrupaya döndü yönünü

Faize bağladı ayın sonunu

IMF emretti aldık kanunu

Eski hasır aldık halı verdik biz

Mikdat der hal böyle bilsin bu millet

Uyansın hizaya gelsin bu millet

Gereken tedbiri alsın bu millet

Ne kadar da geri kalıverdik biz', 'Yattılar kalktılar AB dediler Büyük bir hayale dalıverdik biz Satacağız diye hibe dediler Ancak birbirini yoluverdik biz Milli gelir dondu i...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yattilar-kalktilar-ab-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-aysel-al-rrf85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara basan gibisin

İçimi karartan

Nukleer bomba gibisin

Duygularımı sarsan

Alev gibisin

İçimi ısıtan

Söyle bana sevgili

Nasıl bir gönül erisin? 

Bazen fırtına olup esiyorsun

Sııcacık ateş olup ısıtıyorsun

Sevgiyle cıhanı kucaklıyorsun

Söyle bana sevgili 

Nasıl bir gönül erisin?', 'Kara basan gibisin İçimi karartan Nukleer bomba gibisin Duygularımı sarsan Alev gibisin İçimi ısıtan Söyle bana sevgili Nasıl bir gönül eris...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-guzin-osmancik-72x6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyaz  giyinirken 

Bedenime

Düğüne gider gibimi

Gideceğim

Belki ağlayan çıkacak ardımdan

Bilmeyecekler ki

Güle oynaya giden benim

Yoksa beyaz olurmuydu

Gelinliğim

Zaten aşinayım

Bu yolun yolcusuna

Elim kolum bağlı

Dilim suskun

Kalbim..... hazırmı? 

Hazır.

Belki baktığımda geriye

Ah keşke, keşke 

Demeseydim 

Hiç

     sonram', 'Beyaz  giyinirken  Bedenime Düğüne gider gibimi Gideceğim Belki ağlayan çıkacak ardımdan Bilmeyecekler ki Güle oynaya giden benim Yoksa beya...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beyaz-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Point Break', 'point-break-cagla-toygan-zjqnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'However you’re far away from my wings

I can’t live without feelin your breath

Nights never end like the dark side of life

Sun never rises like you light my way

Feels like we were lovers in another life

I follow the signs you left behind 

Dream the beginning of this chaos

And wait for the point break baby

Oh baby..no lies..i’m dyin for you…

I’ll be alone there without you just in fume

I’ll think about this two weeks of all my life

However you’ll never belong to me

I’ll live for you,just for you man..

Just because of you,i wanna feel this love till the end comes..

You see it never finishes like the endless cavity

Now you know it was the only dream we waited for so long

You feel it gets closer by a lunatic northeast wind

The point break of all your life and all your expectations…

(11/01/2006)', 'However you’re far away from my wings I can’t live without feelin your breath Nights never end like the dark side of life Sun never rises li...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/point-break-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlık', 'bayramlik-alper-yildiz-oafk9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün müthiş halim,

Yerin altında bir kıyamet gibi,

Bugün ölü gibiyim,

Görünen yalnız denizin dibi.

Sıladan ayrı bir bayram daha,

Bütün kanlar kanım olsun aksın,

Ateşler tutuşsun,koca bir vaha,

Yansın bedenim ateşler yaksın,

Her yanış bende bir baha...

İbrahim yanımla baktım kendime,

İsmailliğimi yere yatırdım,

Bıçağı almadan elime,

Kan olup,akıp,yeri göğü batırdım.

Zaman akar bayram suretinde,

Gözlerim kapalı daldığım rüya,

Kurban olayım yıldızlar üzerinde,

Hak ve hakikat bu degilmiş güya! 

İlahi bir öfkeyim semada,

Dinmem defalarca sönsemde,

Bir avuç kan olurum deryada,

Bütün suları kırmızı görsemde.

Bu bayram kan rengine büründüm,

Beni kurban ettiler sanki.

Bıçaktan bıçağa sürüldüm,

Hangi acım daha yalan ki...

Kurban olup yaralarımı saram,

Beklerim gelecek benimde sıram,

Boynumda bir halka yaram,

Neden kendimde kalam ki....', 'Bugün müthiş halim, Yerin altında bir kıyamet gibi, Bugün ölü gibiyim, Görünen yalnız denizin dibi. Sıladan ayrı bir bayram daha, Bütün kanl...', ARRAY['Türk Edebiyatı','Şiir','Alper Yıldız']::text[], 8.5, '{"poet":"Alper Yıldız","poet_slug":"alper-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bayramlik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ağlarım', 'ben-aglarim-sair-yaman-4wabz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir çiğ damlası yalnızlığında

akıyor inan gözyaşlarım

sanki hüzünler filizlendi bağrımda

ağır geliyor kelimeler kaldıramıyor dudaklarım...

burası yalnız bir kentin en sote yeri

gönlümdeki düğümle gezdim dolaştım kavları

yalancıymış meyler, gözyaşımı durdurmadı

ulaşmadı yerine, sanki geri dönüyor ahlarım...

hasretinle erittim dakikaları bir bir

yokluğun ileri, saatler hep geridir

ruhum seninle gitti, beden benim gibidir

ölüm bir yana ben bu ayrılığı kaldıramadım...

bir damla gözyaşı aksa bir sevda uğruna

inan çıplak sokaklar değil, ben ıslanırım

deseler ki bir kalp esir olmuş ayrılığa

gamları, kederleri toplar ben kanarım

ağlamasın yürekler, ağlamasın sevdalar

hepsinin yerine ben ağlarım, ben ağlarım...', 'bir çiğ damlası yalnızlığında akıyor inan gözyaşlarım sanki hüzünler filizlendi bağrımda ağır geliyor kelimeler kaldıramıyor dudaklarım... b...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-aglarim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırladığım şeyler', 'hatirladigim-seyler-guzin-osmancik-t6dsm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırladığım şeyler var

Soba borulu

İs kokan sokaklarda

Paytonların nal sesleri

Arnavut kaldırımlarında 

Balıkesir geceleri

Çocuk düşlerim

Bez bebeğim

Peri masallarım

Ahşap evlerde yaşanan

Sanki bir mevsim süren 

Ramazanlar

Mangalda kahveleri

Alaturka tuvaletleri 

Ve o her sokaktan gelen 

Lokma kokuları ile 

Balıkesir çocukluğum', 'Hatırladığım şeyler var Soba borulu İs kokan sokaklarda Paytonların nal sesleri Arnavut kaldırımlarında  Balıkesir geceleri Çocuk düşlerim B...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatirladigim-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarlar', 'mezarlar-abdullah-gencay-pl8o2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mezarlar; 

Bedenin son yatağı

Ana kucağı gibi sarar bedenleri

Memleketimde, 

Ağaç altlarındadır yerleri

Mezar taşları; 

Mezarların bekçileri

Önce, tahtadandır

İnsan duruşu misali

Beden yatar,

Onun gölgesi düşer üzerine

Sonra başka bir sanatkarın 

Eli değer taşlara, hazırdır 

Doğum tarihi, Ölüm tarihi

Ve Ruhuna  fatiha 

Taşlar dizilir mezar kenarına

Su dökülür toprak otursun diye

Mahlukat eşelemesin

Bedene ilişmesin diye

Her yaşta her insanı alır içine

Gururla, kabara kabara toprak

Seçmez ne iyiyi nede kötüyü

Ne fakiri nede zengini

Çünkü; topraktandır insanın temeli

Analar, babalar,çocuklar, en yakınlar

Bir elinde su, bir elinde çiçeklerle

Gelirler son yatağı süslemeye

Temizleyip son şeklini vermeye

İnsanın doğumunda da süslenir 

Memleketimde ilk yattığı, beşik

Farkı; ilk yatak bezden ve küçüktür beden

Son yatak topraktan ve büyüktür beden

Beşikte büyür beden, mezarda çürür beden', 'Mezarlar;  Bedenin son yatağı Ana kucağı gibi sarar bedenleri Memleketimde,  Ağaç altlarındadır yerleri Mezar taşları;  Mezarların bekçileri...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mezarlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Bir Baharsın', 'ne-guzel-bir-baharsin-aysel-al-qfz43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerine dokunmasa da 

Seni göreyim

Seni göremesem de

Sesini duyayım

Sesini duyamasam da

Ne fark eder

Konuşayım şiir şiir

Şiirlerle konuşamasam da

Rüyamda göreyim

Rüyamda göremesem de

Oh ne güzel! 

Yine de varsın, biliyorum...

Sensizlik içinde sen, sadece sen varsın...

Ne güzel bir baharsın', 'Ellerim ellerine dokunmasa da  Seni göreyim Seni göremesem de Sesini duyayım Sesini duyamasam da Ne fark eder Konuşayım şiir şiir Şiirlerle ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-guzel-bir-baharsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-aysel-al-nd5va', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmiyor günler saymaktan yoruldum

Sabah olmuyor

Bitmiyor zaman

Yokluğun öylesine sarsıyor ki beni

Bilmem nerede ne kadar kaldı zaman

Gece olsun, uykuya dalayım diyorum

Sabah olur da bir gün daha geçer diye

Ama olmuyor canım, olmuyor işte...

Zaman akıp gitsin istiyorum

Mıh gibi duruyor, taş kesiliyor yerinde

Ne istiyor  benden akreple yelkovan? 

Anlamıyorum... 

Oysa; 

Sadece yokluğunun ateşi var içimde...

Ah gelsen boynuna bir sarılsam

Sonra işte o anda

Geçmese zaman

Bir tanem

Sarılıp, sarılıp ağlasam...

Öylesine özledim ki seni

Gel artık! 

İçimde özlem dolu

Bir sancı var,

Kurtar beni...', 'Geçmiyor günler saymaktan yoruldum Sabah olmuyor Bitmiyor zaman Yokluğun öylesine sarsıyor ki beni Bilmem nerede ne kadar kaldı zaman Gece o...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-tanem-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir göç mevsimi', 'bir-goc-mevsimi-sair-yaman-wkecq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir göç mevsimi daha geldi

aşk şarkıları söylediğimiz anlardan sonra

hasrete alışık değildim, bahtıma ayrılık düştü

buralarda sevda çiçekleri açar mı daha..? 

vazgeçtim deme bilirim geçilmez

göç mevsimi bu, sevdaya ölçü biçilmez

sonsuza açılan kapıdır, açıldı mı örtülmez

buralarda unutma beni, selam yolla ara sıra...

gidiyorsun işte turnaların uçtuğu yere

kanat açma vakti geldi artık yalnızlığa

söylenen aşk şarkılarının anısına

yalnız bir beste tuttururum dilime

sen merak etme sevdiğim sen merak etme...', 'bir göç mevsimi daha geldi aşk şarkıları söylediğimiz anlardan sonra hasrete alışık değildim, bahtıma ayrılık düştü buralarda sevda çiçekler...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-goc-mevsimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Babam...', 'benim-babam-ali-orhan-gunaydin-fl4h1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim Babam,

Bir deli adam.

Yüreği hep deli doludur da,ondan,

Benim Babam,

Bir deli adam.

Haksızlığa gelemez,o hiç bir zaman,

Göğüs gerer,gözünü dahi kırpmadan.

Benim Babam,

Bir deli adam.

Verdiği sözde durur,dönmez hiç bir zaman,

Söz namustur onun için her an.

Benim Babam,

Kaybolmaya yüz tutmuş,

Büyük Kahraman...

           10/01/2006', 'Benim Babam, Bir deli adam. Yüreği hep deli doludur da,ondan, Benim Babam, Bir deli adam. Haksızlığa gelemez,o hiç bir zaman, Göğüs gerer,gö...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-babam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Kendi Yoluna be', 'herkes-kendi-yoluna-be-yusuf-ter-yhns2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arzu hayal yasak mi ki

Herkes kendi yoluna be

İsim benzer size nedir

Herkes kendi yoluna be

Şehvetlerde gözüm yoktur

El sallasam inan çoktur

Benim karnım size toktur

Herkes kendi yoluna be

Muhatabım insan için

Bu temâşa söylen niçin

Bu söylemden artık geçin

Herkes kendi yoluna be

Yusuf''umu kızdırmayın

Bir kayaya yazdırmayın

Gönlünüzü gezdirmeyin 

Herkes kendi yoluna be...

Yusuf Ter 11.01.06

Saat 00:11 İsviçre', 'Arzu hayal yasak mi ki Herkes kendi yoluna be İsim benzer size nedir Herkes kendi yoluna be Şehvetlerde gözüm yoktur El sallasam inan çoktur...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/herkes-kendi-yoluna-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-aysel-al-82jst', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine görüş günü geldi

Sayıyorum günleri

Ara sıra

Duyuyorum sesini

İçimde ılık bir sıcaklık esiyor

Ayaklarım yerden kesiliyor

Hani idama mahkum edilen

Bir insanın son arzusu sorulurcasına

Çırpınıyor yüreğim

Koşuyorum sana

Yine görüş günü geldi

Bilmem bir saat mi yoksa bir kaç saat mi

Sevgiye ayıracak zamanın var

Yüreğimin coşkusunu anlatamadan

Zaman akıp geçti

Unuttum söylemeyi bilmem

Belki de zaman kalmadı

Yine geçti bir saat

Gidiyorsun

Arkandan bakıyorum sana

Haykırıyorum

Yüreğimdeki sevinç ve burukluğa

Nedir benim hissettiklerim bilmiyorum

Sevda  mı kara sevda mı

İsim veremiyoru

Yeni bir görüş gününe kadar 

Seni umutla bekliyorum', 'Yine görüş günü geldi Sayıyorum günleri Ara sıra Duyuyorum sesini İçimde ılık bir sıcaklık esiyor Ayaklarım yerden kesiliyor Hani idama mahk...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sitem-219-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S e n i n i m Diyemedim', 's-e-n-i-n-i-m-diyemedim-birsen-ates-jh0tk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kendimi 

ıslak geceye vurduğum 

hüzünlerimden asıyorum

söylemedim 

seninle nasıl da mutluydum 

tuttuğunda ellerimi 

öleceğimi sanardım heyecandan

ne zaman yüzüme baksan

sanırdım hep bahar kalacak mevsimler..

oysa sana

seninim diye hiç diyemedim

kendi kendime kurdum 

darağacını 

henüz ipini çekemediğim

sensizliğe küfrediyorum

duyulmuyor

soğuk bir gecenin kollarına

tek başına atıyorum kendimi

gücüm yok

tutup kaldıramıyorum

çırpınıyor çaresizliğim 

yolunu şaşırmış acılarım

bir başına

kıyılarına demir atmış

yürek gemim 

şimdi

pişmanlığı var içimde

suskunluğumun 

söyleyemediklerimle yaşıyorum

sensizliğimin aynalarında 

ağlaya ağlaya...', 'kendimi  ıslak geceye vurduğum  hüzünlerimden asıyorum söylemedim  seninle nasıl da mutluydum  tuttuğunda ellerimi  öleceğimi sanardım heyec...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/s-e-n-i-n-i-m-diyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-aysel-al-pfgqd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin tam ortasında

Yıkarsın saçlarını serin sularda

Yakamoz, yakamoz…

Kahkahanı, duyarım

Evlerin çatılarında, duvarlarında

Seni, sesini ancak ben duyarım

Başkası duyamaz

Ah yaramaz! ...

Milyon yıldız peşindedir

Sana bağlı sana sevdalı hepsi

Bir de beni düşünsen ne olur/! 

Vay ki vay! Vay …Vay! ...

Bir de beni sevsen, gece mi biter? 

Yaramaz ay! ...

Gecenin tam ortasında,

Tutsan ellerimden, efendim olsan

Ruhuma, beynime dolsan

Kursan ışığımla  içimde bir saray

Bir kerecik benim olsan ne olur! ? 

Yaramaz ay! ...', 'Gecenin tam ortasında Yıkarsın saçlarını serin sularda Yakamoz, yakamoz… Kahkahanı, duyarım Evlerin çatılarında, duvarlarında Seni, sesini a...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-aysel-al-9rwww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya bom boş gözümde

Tadı yok ne baharın ne kışın

İçimde kaskocaman bir yalnızlık

Kendimi kendime anlatamıyorum

Hayal mi gerçek mi? 

Soruyorum anıları

Bir fırtına başlıyor yüreğimde

Sensiz bu şehirde yapamıyorum

Kendimi kendime anlatamıyorum

İçimde sen varsın

Gözlerimde yüreğimde

Yalnızlığın sancısı geldiğinde

İçimdeki savaş alanından çıkamıyorum

Kendimi kendime anlatamıyorum

Sevgisiz bir dünya mı? 

Olmaz

Aşksız yaşamak mı? 

Kahrolası yalnızlık boğuyor beni

Çıkacak yol bulamıyorum

Yüreğim sancıyor

Sensiz olamıyorum', 'Dünya bom boş gözümde Tadı yok ne baharın ne kışın İçimde kaskocaman bir yalnızlık Kendimi kendime anlatamıyorum Hayal mi gerçek mi?  Soruyo...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlatamiyorum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-ebru-rabia-berkul-2xcd5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karınca kümelerini

Anımsatan

İnsan topluluğu

İçerisinde

Gurbette gibiyim.

Bir başıma

Yalnızlığımla 

Sohbetteyim

Tanıdık,

Bildik bir dost eli

Arar gibi

Uzaklara

Dalar gibiyim

Ve gün

Gözyaşlarını dökerken

Limana

Demir atıyorum...', 'Karınca kümelerini Anımsatan İnsan topluluğu İçerisinde Gurbette gibiyim. Bir başıma Yalnızlığımla  Sohbetteyim Tanıdık, Bildik bir dost eli...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/liman-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığım', 'ay-isigim-aysel-al-zr4gk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay ışığım,

Biricik sevgilim, 

Seni seven kalbimi,

Terk edip,

Nasıl gidersin. 

Hiç mi özlemezsin, 

Hiç mi sormazsın beni,

Ay ışığım, 

Biricik sevgilim.

Söyle Ay ışığım, söyle? 

Şimdi hangi uzak yerlerdesin? 

Söyle bana,

Rüyalarıma neden girmezsin.

Söyle Ay ışığım, söyle, 

Gökte misin yerde misin? 

Şu an nasıl bir hal içindesin? 

Sana yine gönül kapımı açsam

Ve gel desem 

Uzatsam elimi 

Gelir misin? 

Söyle Ay ışığım, söyle? 

Şimdi neredesin, nerelerdesin? 

Benden uzak, 

Hangi yerdesin, hangi yerlerdesin? 

Ay ışığım, 

İçimde beni ben yapan varlığın, 

Kalbimde çınlayan ses senin sesin,

Gel yüreğime nefes ver,

Senin için çarpan kalbime, 

Neşe ver, huzur ver. 

Hayallerimde beslediğim, 

Sürekli gözlediğim, 

Mutluluklarımızın içine, 

Ay ışığın dolsun

Varlığın bana, 

Eş olsun 

Ay ışığım,

İçimdeki ses, neredesin? 

Hangi uzak yerdesin, yerlerdesin.', 'Ay ışığım, Biricik sevgilim,  Seni seven kalbimi, Terk edip, Nasıl gidersin.  Hiç mi özlemezsin,  Hiç mi sormazsın beni, Ay ışığım,  Biricik...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ay-isigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-aysel-al-v997d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim açık seni bekler, 

Eee, hadi bekletme, 

Ne duruyorsun,

‘Koş mu’ demeliyim, 

‘Bana sarıl mı’ demeliyim, 

Gör ne kadar sırılsıklam, 

Aşık olduğumu, 

Seninle en kutsal sevgiyi, 

Teneffüs ederek içimde bulduğumu. 

‘Fazla naz aşık usandırır’ derler, 

Eee, hadi bekletme,

Yüreğim açık seni gözler, 

Gel sevgilim gel, 

Zaman bize hainlik yapacak. 

Gel sevgilim,

Duygularımız aşkta buluşsun,

Atalım umutsuzlukları, 

Gönül gözüyle bir dünya kuralım, 

Ne dersin? 

Bırakalım umutsuz bakışları, 

Yalnızlığımıza sevgimizi ortak edelim.

Şu açık yüreğime, 

 Sana ‘gel’ diyen haykırışıma, 

Kulak ver sevdiğim. 

Yoksa senin için,

Yanan bu yüreğimin yerini,

Karanlık geceler teslim alacak! 

Sana son kez bir şey söylüyorum, 

Gel sevgilim gel…. 

Yüreğime gel,

Zaman bize hainlik yapacak, biliyorum.

Yine sabahın parlayan güneşi yüzüme vururken,

Senden bir haber, bir ses bekledim.

Sana uzanan bu sıcacık yüreği, 

Aşkın o güzel hislerinden umutlar derip,

Mutlu etmeyi düşündüm. 

Aşkın kanununu yazan çılgın yürekler, 

Bu kadar sert ve acımasız mı olmalı? 

Sana beslediğim, bu güzel hislerin yüceliğini,

Anlayamadın, göremedin. 

Yanılmışım, yanılmışım. 

Sen hala yoksun

Halâ uzağımdasın, uzaklardasın.

Gözlerim seni seçemedi, 

Senden aldığım cevap; 

‘Ayrılıkmış’ anladım, anladım. 

Yine akşam oldu, 

Hüzün başladı, 

Saatlerin 00.24’ e vurduğu vakitlerde, 

Bileceğim ki, 

Yarın sabah, yıkıldığım gün olacak, 

Artık sana ne ‘gel’ diyeceğim.

Nede ‘kal’ diyeceğim. 

Bundan sonra, 

Ne seni bekleyen sıcak bir kalp, 

Nede seni bir ömür boyu saracak,

Sevgi kalmış olacak bende.

Zaman bize hainlik yapmadı,

Hainlik ve yanlışlık yapan sendin,

Karşılıksız sevdiğim insan, 

Seni dünyamdan atıyor,

Seni mazime gömüyor, gömüyorum…', 'Yüreğim açık seni bekler,  Eee, hadi bekletme,  Ne duruyorsun, ‘Koş mu’ demeliyim,  ‘Bana sarıl mı’ demeliyim,  Gör ne kadar sırılsıklam,  A...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/gel-248-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sen Olduğun İçin Sevdim', 'ben-seni-sen-oldugun-i-cin-sevdim-burhanettin-akdag-39xvu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni, 

Sen beni sevesin diye sevmedim ki! 

Görür görmez vurulduğum, 

Mahur ve mahzun gözlerinin 

Eşsiz gizemine takılıp düşerken peşine 

Avaresi olduğum aşk denilen iksirin 

Efsunlu büyüsüyle sevdim. 

Sevmesen de beni, 

Hiç getirmesen de aklına 

Bakmasan da yüzüme 

Korkaklık sayacağım vazgeçmeyi 

Bin kez de olsa, ısrarla seveceğim. 

Ben seni, 

Seninle sevinmek için sevdim 

Göğsünde ağlayıp, 

Kalp atışlarında can bulurken 

Sevda yağmurlarında sırılsıklam olmak için sevdim. 

Hiç değer vermeyip sevdama 

Gülmesen de yüreğime 

Hiç ümit olmasa da yarınlardan 

Sana inat seveceğim seni 

Yokluğunda, 

Sıcaklığınla teselli edeceğim kalbimi. 

Ben seni, 

İliklerime kadar titremek için 

Aşkınla soluklanıp, gözbebeklerinde yanarken 

Gönül saraylarını, 

Aşkımla taçlandırmak için sevdim. 

Yaklaştırmasan da sevda bahçelerine 

Kızıl gülleri inatla seveceğim 

Mavi ufuklarla donatırken gülşeni 

Koklayacağım teker teker, senin niyetine. 

Ben seni, 

Sensiz günahlarımı yıkarsın diye

Bıkmadan bekledim nisan yağmurlarında 

Umarsızca tutunduğum gecelerde kahkahanı ararken 

Bir gün dönersin diyerek sevdim. 

Beyaz sayfa açacağım yeniden 

Önce adını yazacağım başına 

Yeniden yazacağım ezberlercesine 

Mahzun gönlüm hasretinden çağlarken 

Ümidimi her gün tazeleyerek bekleyeceğim. 

Ben seni, 

Sende gülmek,

Sevdanla yeniden doğarken 

Kalbinde tutuklu kalmak için 

Yani ben seni, 

Sen olduğun için sevdim. 

Sen beni, 

Hiç sevmemiş olsan da! 

(11.01.2006)', 'Ben seni,  Sen beni sevesin diye sevmedim ki!  Görür görmez vurulduğum,  Mahur ve mahzun gözlerinin  Eşsiz gizemine takılıp düşerken peşine ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ben-seni-sen-oldugun-icin-sevdim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örnek Şiir-Her İnsan ve Ben- (GÜLCE-Buluşma)', 'ornek-siir-her-i-nsan-ve-ben-gulce-bulusma-mustafa-ceylan-kl139', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her insan, her insan birazcık deli

Ben sana deliyim, hem de zırdeli.

Hep seni görürüm ne yana baksam

Hep seni ararım gittin gideli...

Gittin gideli ne haldeyim,

Sorsan bir, arasan bir; ne olur...? 

..............Hasret dağlarının Ferhatıyım 

...........................Tek sana, tek sana sevdalıyım...

Her insan, her insan birazcık aşık

Ben sevdanı saran çılgın sarmaşık.

Yıktım duvarları, bahçeyi, çiti

Bu sebep yüzünden başım dolaşık...

Işık...

......Işık...

..........Işık... 

...........Sonsuzluk türküm, bitmeyen ışık....

Yoksun işte, yoksun yanımda, canevimde

Özledim nefesini, sesini

....................Dava açtım mevsimlere

.......................Kışların kapısındayım

....................................Firardayım....

Her insan, her insan düşkün paraya

Ben sana düşkünüm, bak şu yaraya

Olmazsa derdime derman gözlerin

Döner deli gönlüm yıkık saraya...

Varlık sen, yokluk yine sen

Ötesi sadece boşluk, 

.................Yosun gözlerinle bir bak istersen... 

.....................Acılarımla başbaşayım; 

...........................Işık* hızıyla sana koşayım

..................................................''Gel! '' dersen...

Her insan doğduysa, mutlak ölecek

Ölsem sevdan ile kim ne bilecek..? 

Kırıp aynaları, durgun suya bak

Gözlerin benimle orda gülecek...

Gülüm, 

..........Gülüm... 

...................Gülüm...

..............Ve sana kavuşmaksa ölüm

......................Dünden razıyım her şeye, hazırım inan..! 

.............................Gece yarısında suya indiğinde bir ceylan

.................................Mor menekşe buselerle avuçlarına

....................................Avuçlarına düşeyim; mutlu olurum o an...

.............................................Bitsin bu zulüm,

................................................................Gülüm, 

....................................................................Gülüm... 

...........................................................................Gülüm...

10 / 11. Ocak. 2006

******************************************************************

(*)                        Not. (Buluşma)                  adını verdik bu nazım türüne işte dostlar.

Hece şiiri ile serbest şiirin buluşması... 

Burada; 

Hece Vezinli mısralarımız 65=11 hece ile dokunmuş olup; 

kafiye düzeni de (a / a /-/ a)                  (b / b /-/ b)                  (c / c / - / c)                  (d / d /-/ d)                 şeklinde olup; BULUŞMA'' da rahatlığı temin maksadıyla ''mani'' türünü özellikle seçtik. Buluşma noktalarını da ses tonlamalarıyla renklendirmeye çalıştık. Serbest mısralarımızı alabildiğine serbest bırakırken de ses ve iç ahenk''i gözden kaçırmamaya gayret ettik. Tekerrür sanatından istifade ettik. 

Böylece hece-serbest kavgasını bu bayramda sona erdirmiş olduk biz...

E hadi, ne duruyorsunuz? İşte örnek dostlar.... 

Denemeye ne dersiniz? 

(*)             Işık- kelimesi Ahmet Erdem kardeşimin armağanıdır. (Atom hızı)              demiştik. Duygu İmparatorumuz şair Ahmet Erdem''in görüşleriyle (Işık)              yaptık dostlar...

(**)             Yakında yeni NAZIM şekilleri ve türleri'' ni sunmaya çalışacağım. BULUŞMA adını verdiğimiz bu nazım şeklini, başta şair Harun YİĞİT kardeşim ''İstanbul'' şiirinde ve bir çok şair kimi şiirlerinde denemiştir. Ama bizim yaptığımız bunu sistematize edip bundan sonra sunacağımız NAZIM ŞEKİLLERİ ile yeni bir AÇILIM sağlamaktır. Zira, maksadımız Türk Şiirine yeni nefes alanları açmaktır dostlar. Yıllardan beri üzerinde çalıştığımız hususlardır bunlar. Saygılarımla...', 'Her insan, her insan birazcık deli Ben sana deliyim, hem de zırdeli. Hep seni görürüm ne yana baksam Hep seni ararım gittin gideli... Gittin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ornek-siir-her-insan-ve-ben-gulce-bulusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Gribi', 'kus-gribi-ertan-tasli-glxq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben nasıl doğdum diye

Sorarlar çocuklar annelerine

Aldıkları yanıt, onları leyleklerin 

Getirdiğidir çoğu zaman

İnanır çocuklar kendilerini

Kuşların getirdiğine

Büyüyünceye kadar.

Şimdi de inanmak zorundalarmı? 

Kuşların götürdüğüne', 'Ben nasıl doğdum diye Sorarlar çocuklar annelerine Aldıkları yanıt, onları leyleklerin  Getirdiğidir çoğu zaman İnanır çocuklar kendilerini ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Taşlı']::text[], 8.5, '{"poet":"Ertan Taşlı","poet_slug":"ertan-tasli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kus-gribi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yangını', 'kar-yangini-birsen-ates-e2ffy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karlı bir akşam da

bıraktım bakışlarımı

son kez ağladım giderken

dönüp yaşlı gözlerimle

son kezde olsa

cesaret edip

gidişine  bakamadım 

meğer sensizliğeymiş 

yolculuğum

bilemedim

canım yanıyordu

acaba senin 

şimdi

kim bilir 

hangi şarkılardasın

bizi anlatan

bende ki seni alıp

gittiğin

karlı  akşam da

bir bilsen

kar yangınlarında

ne halde  birsen

11.01.06', 'karlı bir akşam da bıraktım bakışlarımı son kez ağladım giderken dönüp yaşlı gözlerimle son kezde olsa cesaret edip gidişine  bakamadım  meğ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kar-yangini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunlar Bizmiyiz', 'bunlar-bizmiyiz-kamil-at-fpjp6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biryerden geldik mi başka bir yere

Canımızla uysaydık keşke bir yere

Biz özgürce dolanırız öyle her yere

Sınırlar kontrol da bunlar bizmiyiz.

Sınırlar kalkar birgün bir felaketle

Yönlendirme hayattır memleketle

Kim kimlerin elinde bilinmez niyetle

Daha sıkı olsun daha da azmıyız.

Kimi aslında dünyada bilinmez

Var sayar kendini onunla ölünmez

Devlet oyununa bağlı kalınmaz

Çoban modası sürüyor yozmuyuz.

Kamil At dünya son bulur belkide

Yüzyıllar sonra kurtulur belkide

İnsanlık umudum, insan olur belkide

Kötüye bakan karanlık gözmüyüz.', 'Biryerden geldik mi başka bir yere Canımızla uysaydık keşke bir yere Biz özgürce dolanırız öyle her yere Sınırlar kontrol da bunlar bizmiyiz...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bunlar-bizmiyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Bir gün son bulacak ıstırâbın', 'bir-gun-son-bulacak-istir-bin-sair-ahrazi-tyqvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine yalnız,yine tek başınasın ey gönlüm! 

Rahat ol! Kimse görmeyecek ağladığını; 

Nasıl birden kapatırsa bir kapıyı ölüm

Öyle çarpacaksın nemli göz kapaklarını. 

Hiç korkma sakın! Yavaşça dal bu son hayâle

Üzülme! İlk defâ gülecek,sevineceksin; 

Uykun üstüne bir gölgeyi çok görse bile

Üşürsün diye aşkını örtecektir aksin.

Sükûna erecek o ân,endîşen ve sızın

Daha bir şâd öleceksin Yûnus’tan,Nâbî’den.

Bilmeyecek seni asrın.Sonra,ansızın

Senin de yapılacak dünyâda bir âbiden.

Sevenler az çok görecek:sükûn içindesin

Tekrar okuyacak yazdığın her mısrâı dil

Niçin sustuğunu söyleyecek içli sesin 

Duydukça yanacak,yanacak,yanacak kandil.

Yalnız caddeni görmek için her köşesinden

Bir çok selâm gönderecek sana memleketin

Ağırlıyacak toprağın.Bahsederken senden

Bir ben kaldım diyecek üç düğmeli ceketin.

Güller konacak etrâfına,dizilecekler; 

Gün be gün artacak belki ziyâretçilerin

Belki azalacak kabrinde açan çiçekler

Olmayacak belki de hiçbirinden haberin.

Ellerin değecek gâipten bir tül perdeye

Bakacaksın:tâ ki,son gezdiğin yere kadar

Soracaksın:benden kim kaldı yâdigâr diye

Kabrini gösterecek bıraktığın vedâlar; 

En yüksek tepede,yüzün batıya çevrilmiş

Bekleyecek,bekleyecek,bekleyeceksin ki,

Sen olmak istiyorsun dünyâda ilk dirilmiş

İlk gören sen olmak istiyorsun Hakkı sanki.

Yine yalnız,yine bir başınasın ey gönlüm! 

Rahat ol! Kimse duymayacak ağladığını; 

Nasıl birden kapatırsa bir kapıyı ölüm

Öyle çarpacaksın nemli göz kapaklarını. 

* * *', 'Yine yalnız,yine tek başınasın ey gönlüm!  Rahat ol! Kimse görmeyecek ağladığını;  Nasıl birden kapatırsa bir kapıyı ölüm Öyle çarpacaksın n...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-gun-son-bulacak-istirabin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolculuk', 'bir-yolculuk-gul-aycan-xjly2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yol uzanır geçmişten geleceğe.

Bilir, yol budur, o da gidecek elbet...

Islanır yanağı bakarken geriye.

Yağmur yağdığında ıslanacak elbet...

Atılan her adım yeni bir hece,

Gider hep ileri, öteye doğru...

Yürür hiç durmadan yol alan yolcu,

Gider bilmediği yerlere doğru.

Derken bir son gelir, kurcalar zihnini; 

Lakin ne zaman gelir bilinmez vakti.

Kimi zaman çok yakın sanırken onu,

Bazen de sanırsın hiç gelmeyeceğini.

Bir gün bir şey olur, değişir her şey.

Gider yol boyunca yolalan yolcu.

Her şey aynı kalır, değişir tek şey:

Yeni bir yol başlar, değişir sahne.

6 Temmuz 2004', 'Bir yol uzanır geçmişten geleceğe. Bilir, yol budur, o da gidecek elbet... Islanır yanağı bakarken geriye. Yağmur yağdığında ıslanacak elbet...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-yolculuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantıklı Şiir', 'mantikli-siir-gul-aycan-f28d2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki mantıksızlığın arasında

Bir mantık arayacak kadar

Mantıksız olacak değilim.

Bazen en mantıksız cevap

Olur en mantıklı cevap.

6Temmuz 2004', 'İki mantıksızlığın arasında Bir mantık arayacak kadar Mantıksız olacak değilim. Bazen en mantıksız cevap Olur en mantıklı cevap. 6Temmuz 200...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mantikli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-gul-aycan-6aflw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin gittiğin yer hep benden uzak,

Simsiyah gözlerin bana tek tuzak; 

Uzak olsan da bana, benden çok uzak,

Kaçıp kurtulamam bu sevgi tuzak...

Seni göremem ya görsem de yasak,

Vakitsiz vuslata ermek yok yasak...

Gün hiç kararmadan sabaha varsak,

Vakit geçse de biz beraber kalsak...

Seninle uzak bir diyara gitsek,

Aradığımız neyse orda bulsak...

Hayat eskise de hiç yorulmasak,

Ömrümüz bitse de her an yaşasak...

26 Ekim 2004', 'Senin gittiğin yer hep benden uzak, Simsiyah gözlerin bana tek tuzak;  Uzak olsan da bana, benden çok uzak, Kaçıp kurtulamam bu sevgi tuzak....', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-gul-aycan-y60wa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevdaya tutunup yaşamak bir hayatı,

Uyanmak kimsesizliğe yaşamı görmeden...

Bir sevdada arayıp hayatın anlamını,

Kaybetmek yaşanmışı yeniden ve yeniden...

Ekim 2004', 'Bir sevdaya tutunup yaşamak bir hayatı, Uyanmak kimsesizliğe yaşamı görmeden... Bir sevdada arayıp hayatın anlamını, Kaybetmek yaşanmışı yen...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yeniden-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstat', 'ustat-sultan-duran-1fqv7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu güzel vatan da hainler ne çok

Birliği, beraberliği de sunanlar çok

Okumalı, yazmalı seni pek çok

Üstat sen ne güzel yazmışsın? 

Lale''yi, sümbül''ü, gül''ü, bülbül''ü

Dalında duran şu gonca gül''ü

Özünü, sözünü, bilgeliğini

Ah üstat sen ne güzel yazmışsın? 

Sevgiyi, dostluğu, aşkı yazarsın

Umutsuzlukta bile umut ararsın

Dost dergahında nice dostlar toplarsın

Üstat sen ne güzel yazmışsın? 

Bunların üzerine yazamam gayri

Senden feyiz alıp giderim gayri

Yolunu yol bilip gelirim gayri

Üstat sen ne güzel yazmışsın?', 'Bu güzel vatan da hainler ne çok Birliği, beraberliği de sunanlar çok Okumalı, yazmalı seni pek çok Üstat sen ne güzel yazmışsın?  Lale''yi, ...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ustat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Kal', 'gitme-kal-aysel-al-lzad4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana sevgi dedim

Sev dedin

Sana aşk dedim

Bul dedin

Sana ben dedim

Sor dedin

Şimdi

Sev, bul, sor diye diye

Zamanı bitirdin ve sonra

Gitme kal dedin.', 'Sana sevgi dedim Sev dedin Sana aşk dedim Bul dedin Sana ben dedim Sor dedin Şimdi Sev, bul, sor diye diye Zamanı bitirdin ve sonra Gitme ka...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gitme-kal-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Git', 'oyle-git-sultan-duran-3qhea', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evin bir oda bir aralıksa

Soban da bir atımlık kömürün yoksa

Gönlün hoş bahtın açıksa

Bir tabak çorbayla ısın öyle git

Ayağın yalın, alnın açıksa

Dürüstlük şanın, dostluk katığınsa

Dimdik durmak yiğitliğin şanıysa

Bir lokma ekmeği paylaş öyle git

Gönül kırgınlığını yıkıp gittiysen

Düşmanı şefkatinle ezebildiysen

Bir avuç sevdayı paylaşabildiysen

Yüreğinin sesini dinle öyle git', 'Evin bir oda bir aralıksa Soban da bir atımlık kömürün yoksa Gönlün hoş bahtın açıksa Bir tabak çorbayla ısın öyle git Ayağın yalın, alnın a...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oyle-git-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Gel', 'kendine-gel-nilcan-altay-tqjba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Naz yapma kendine gelmeye

Kullan kendini

İçindeki dışındaki her şeyi

Ve öğren iğrençliklerini

Gör güzelliklerini

Kabullen

İstersen temizlen

İstersen kirlen

		

İyiyi de kötüyü de

Sen al kendine

Naz yapma artık

Kendine gelmeye', 'Naz yapma kendine gelmeye Kullan kendini İçindeki dışındaki her şeyi Ve öğren iğrençliklerini Gör güzelliklerini Kabullen İstersen temizlen ...', ARRAY['Türk Edebiyatı','Şiir','Nilcan Altay']::text[], 8.5, '{"poet":"Nilcan Altay","poet_slug":"nilcan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-gel-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hep Sendeyim', 'ben-hep-sendeyim-gul-aycan-wpboc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sensiz kalsan da ben hep sendeyim.

Bir bunu bil yeter, kederlerdeyim.

Bir senin sevdiğim hasretindeyim.

Sen kendinden uzak nereye gitsen,

Sen sensiz kalsan da ben hep sendeyim.

Ömrümde tek an, seni sevdiğim an...

Dur durak bilmez su misali zaman,

Geçip gider hiç ardına bakmadan.

Vakitler gelip de sıralanırken

Ömrümde tek an, seni sevdiğim an...

Ellerin, gözlerin bu benim sevgim...

Sen gelirsen eğer, biter özlemim.

Son bulur endişem, tasam, kederim.

Ne ellerini al ne gözlerini,

Ellerin, gözlerin bu benim sevgim...

Bir garip duygu bu ruhumu saran:

Uçmak için çırpınan ve kanatlanan; 

Bir küçük kanarya göklerde uçan,

İçimde yaşayan ve hayat bulan,

Bir garip duygu bu ruhumu saran...

Uzat saçlarını, sal sevdiceğim.

Bilmem sana daha ne diyeceğim.

Sen gülmezsen bana, gülmeyeceğim.

Olmazsa ahtım, işte vasiyetim:

Uzat saçlarını, sal sevdiceğim.

26 Ekim 2004', 'Sen sensiz kalsan da ben hep sendeyim. Bir bunu bil yeter, kederlerdeyim. Bir senin sevdiğim hasretindeyim. Sen kendinden uzak nereye gitsen...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-hep-sendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Arkadaşım', 'yol-arkadasim-gul-aycan-xl141', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi yola başlasam,

Sonu ardından gelir.

Ne gidecek yol kaldı

Ne de varacak menzil.

Nereye gidersem boş,

Gölgem ardımdan gelir.

Benim tek gerçek dostum,

Aynadaki aksimdir.

26 Ekim 2004', 'Hangi yola başlasam, Sonu ardından gelir. Ne gidecek yol kaldı Ne de varacak menzil. Nereye gidersem boş, Gölgem ardımdan gelir. Benim tek g...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yol-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişme Vakti', 'sevisme-vakti-birsen-ates-g22e2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimdi

yağmur mevsimi 

tam sevişme vakti

ıslak yağmura karışmış

dudakların da ıslanır gibi

gözlerim 

gözlerinde kenetli

sus olmuş dilim

sendeyim

hadi gel artık

geç olmadan

sevişme vaktinde

değerken tenimize

yağmurun ateşi

koparıp alıyorsun tüm düşlerimi

ben artık acı çekemem

bu mevsim

bu son yağmur sanki

11.01.06', 'şimdi yağmur mevsimi  tam sevişme vakti ıslak yağmura karışmış dudakların da ıslanır gibi gözlerim  gözlerinde kenetli sus olmuş dilim sende...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevisme-vakti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürdenin Sesi II', 'murdenin-sesi-ii-gul-aycan-y1s6n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Edebiyat öğretmenimin anısına)  

Mazide kaldı yaşanmış ne varsa.

Ellerimde bir avuç toprak varsa,

Tahammül gerek artık karanlığa; 

İnce bir hüzün yüzümü sarmışsa,

Neden, diye sorma, bu veda sana...

Aldımsa ahını söyle toprağa.

Rica yok bu demde, bu sitem sana...

Perişan gazeller vurdu rüzgara.

Al çehremde renkler döndü beyaza.

Cemren yanağından düştü alnıma.

Işığım karardı, hasretim sana.

Kara baht, doldu dem, döndüm toprağa.

Aralık 2004', '(Edebiyat öğretmenimin anısına)   Mazide kaldı yaşanmış ne varsa. Ellerimde bir avuç toprak varsa, Tahammül gerek artık karanlığa;  İnce bir...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/murdenin-sesi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürdenin Sesi', 'murdenin-sesi-gul-aycan-xgk27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Edebiyat öğretmenimin anısına) 

Mahmur bir akşamdı içimde her dem.

Ellerim soğuktu, gözlerimde nem...

Tahammül gerekti gelince sitem.

İrkildim, uyandım; neden bilemem.

Ne burdayım, derim; ne de diyemem.

Aldım, elimde belirdi bir kalem.

Renginde var sanki başka bir alem.

Pervane uçuyor durmadan her dem.

Aldandım, yürüdüm, kırıldı kalem.

Cânândan ayrıldım, cânı göremem.

Islandı mendilim, yoktu acelem.

Kaldım karanlıkta, artık gidemem.

Kasım 2004', '(Edebiyat öğretmenimin anısına)  Mahmur bir akşamdı içimde her dem. Ellerim soğuktu, gözlerimde nem... Tahammül gerekti gelince sitem. İrkil...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/murdenin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış kış gerçeğinde radikal ide (Boğa ve Kuşş)', 'kis-kis-gerceginde-radikal-ide-boga-ve-kuss-akin-akca-r5k5w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Helal gıda(k ibaresini kaldıranın paso cüzdanından,

Aklından zoru olmalı -bunun ardına sığınanın.

Bir süre beklemek lazım, kısa ya da uzun; 

Millet tamamen özgürleşene, para kazanana kadar:

Belki yıllar geçer birkaç, belki yıl bir on.

Ekonomik özgürlüğünü kazanıp tatmin olduğunda

Ve hala orta ortamdan kurban kaldırılmamış ise,

O zaman da işte, silinmek üzerli kaldırılmayacak

O ibare, küflü geçmiş dokudaki şanlı, bilhassa:

Orda bırakmak gerekmez en iyisi, o vakit,

Sahte bir düzmeceyi, beklerken de vakittir nakt.

İnsanlar var eder gider, doğduğu bir kendi dinini.

Kaldırmak hata, bırakmaya, değerlendirme''''de -

Basitliktir kaldırmak, kedi girer melek gelende

- Orda kalır, öğünür durur da kan vahşetiyle.

-

bunu yazmayacaktım ama fikiri olunması gerektiğini düşündüm.

gereği varsa ki bir kere olduysa..bla blah', 'Helal gıda(k ibaresini kaldıranın paso cüzdanından, Aklından zoru olmalı -bunun ardına sığınanın. Bir süre beklemek lazım, kısa ya da uzun; ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kis-kis-gerceginde-radikal-ide-boga-ve-kuss-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk, Sevgi''dir', 'ask-sevgi-dir-akin-akca-tcoyl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okyanus tabanına doğru savrulan,

Savrulan ve yutulan

Sevgindir de senin canım benim; 

Bermuda şeytan (k) (h) açı üçgenlerinden…

El olabilen ellerin senin, hasır mı

kolaja dönmeyen plajlarda yazın? 

Sonra el gene el oluyor

Ki görünmez, ama isteri-uzanıyor

Doğaçlama

-

İkincişekil

Aşk sevgidir

Okyanus tabanına doğru savrulan,

Savrulan ve yutulan

Sevgindir de senin canım benim; 

Bermuda şeytan açı üçgenlerinden...

El olabilen ellerin senin, hasır mı

Sanki; kolaja dönmeyen plajlarda yazın? 

Sonra el gene el oluyor

Ki görünmez, ama isteri uzanıyor

--

Ki aynı

 :)) (', 'Okyanus tabanına doğru savrulan, Savrulan ve yutulan Sevgindir de senin canım benim;  Bermuda şeytan (k) (h) açı üçgenlerinden… El olabilen ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-sevgi-dir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek-2', 'sevmek-2-akin-akca-87caj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baş kaldırmaktırtanrıya suçlarından ötürü,

Suçlarından ötürü suçlamamak ama asla.

Suç taşımış olan bağış kolay edemezdi de; 

Sevgiye savaş, Sezar ile fetihler götürü.

Bir yer işgal ettiysen, kararlıca düşünmeli; 

Kimdir toprağının onun altında yatanları.

Niyetlendiysen vahşi batıda nalbantlığa; 

Seç gece görür tavuğu, kör boğa''ndan önce.

Çünkü insanın bile yetmiyor ekonomisi

Politikasına yetmeye yeryüzünde kanter; 

Aman Allah, ne biz yahu sürt edeceğiz

Çekilip bari köşeye güzelce oturmalıyız

Aşk Prusya ise, sevmek Ada Avrupa olmalı

Ve seven biri de Anadolu’da, sevilen nerde? 

Doğanlar değil, en uçta olanlar ululanmalı; 

Aşk ve sevgi değil, yadedenler bunu yaşamalı.

Öyle bir doğaçlama', 'Baş kaldırmaktırtanrıya suçlarından ötürü, Suçlarından ötürü suçlamamak ama asla. Suç taşımış olan bağış kolay edemezdi de;  Sevgiye savaş, ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm-2', 'olum-2-akin-akca-oiacb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat oksa,

ölüm yoktur.', 'Hayat oksa, ölüm yoktur....', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/olum-2-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey İçin', 'her-sey-i-cin-savas-dincbas-og12e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşamımın kıyısından

bir merhabayla geçen

bir süre de olsa

ziyaret edip giden

ve yaşamıma girip

orada kalan herkese

bana kattıkları

her şey için

benden götürdükleri

her şey için

ve her şey için

sonsuz teşekkürler...', 'yaşamımın kıyısından bir merhabayla geçen bir süre de olsa ziyaret edip giden ve yaşamıma girip orada kalan herkese bana kattıkları her şey ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-sey-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her nedense', 'her-nedense-ulya-erkman-ysmr7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden insanlar cekemezler 

Birbirlerini

Haset ve kiskanclikla yerler 

Kendilerini

Bir insan gostermisse kendini 

Bir yolda

Haset kiskanclik degil iftihar

Etmeliyiz onunla

Her insan kendi becerisiyle 

Iftihar etse

Baskasini kendinden ustun veya asagi

gormese

Dostluklar daha baska olurdu

 Bence 

Yapamiyoruz ne yazik 

Her nedense', 'Neden insanlar cekemezler  Birbirlerini Haset ve kiskanclikla yerler  Kendilerini Bir insan gostermisse kendini  Bir yolda Haset kiskanclik ...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-nedense-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Olur', 'hazan-olur-mehmet-sait-akkus-sia8g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hazan olur gidişlerin

Elimde gülün kururken

Öyle veda edişlerin

Beni kalbimden vururken

Yar kadrim buymuş meğer

Kendimi ancak bulurum

Geriye dönmessen eğer

İnankendimi vururum', 'Hazan olur gidişlerin Elimde gülün kururken Öyle veda edişlerin Beni kalbimden vururken Yar kadrim buymuş meğer Kendimi ancak bulurum Geriye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hazan-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmesem Olmuyor', 'dusunmesem-olmuyor-mehmet-sait-akkus-0x74z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bendeki derin yaralar

Kapanacak gibi değil

Kaybolup giden yarınlar

Bulunacak gibi değil

Sana olan bu sevgimi

Bilmem nasıl anlatayım

Sana versem yüreğimi

Bilirmisin ne haldayım

Düşünmeden olmuyorki

Seni içime hapsettim

Git desemde gitmiyorki

İnan her şeyi hakkettim', 'Bendeki derin yaralar Kapanacak gibi değil Kaybolup giden yarınlar Bulunacak gibi değil Sana olan bu sevgimi Bilmem nasıl anlatayım Sana ver...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusunmesem-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devir', 'devir-mehmet-sait-akkus-f1wgn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devir güzelim

Devir

Yaşadığımız aşkları devir

Yılları devir

Ayları devir

Günleri devir güzelim

Çevir güzelim

Çevir

Aşk sayfalarını çevir

Satırları çevir

Notaları çevir

Şiirlerimi çevir

Götür güzelim

Götür

Bendeki aşkı götür

Canımı götür

Bneliğimi götür

Öldür güzelim

Öldür

Bnedeki beni öldür

Bendeki aşkı öldür

Bendeki hasreti öldür

Beni öldür güzelim

Öldürki

Yeniden doğup

Seni yeniden baştan seveyim', 'Devir güzelim Devir Yaşadığımız aşkları devir Yılları devir Ayları devir Günleri devir güzelim Çevir güzelim Çevir Aşk sayfalarını çevir Sat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/devir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Annem', 'benim-annem-ramazan-kurt-yvlfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutup adım adım yürüten Annem.

		Sallayıp beşiği büyüten Annem.

		Sevgiyi saygıyı öğreten Annem.

		Bayramda öptüğüm ellere kurban.		

		Nemliydi gözleri tatlıydı dili.

		Bazen güneş olur bazen sam yeli.

		Gönül bahçesinin goncası gülü.

		Gözlerinden akan sellere kurban.

		Üstüme eğilip kol kanat geren,

		Bağrına basıp ta gülümü deren,

		Bebeğim diyerek bana süt veren,

		Saçlarından düşen tellere kurban.		

		Nur çiçeğim solmuş Çiçekdağında.

		Kurumuş kör kuyu gönül bağında.

		Uzanmış yatıyor yer yatağında.

		Yanağında açan güllere kurban.

		

		Kara haber ile teller çekildi.

		Saçlarıma Anam beyaz ekildi.

		İki baş ucuna taşlar dikildi.

		Kokun ile gelen yellere kurban.	

		Ölmesin Anneler solmasın güller.

		Gurur verir bana öptüğüm eller.

		Ramazana Melek bütün Anneler.

		Ruhunla savrulan küllere kurban

				(Rahmetli anneme ağıt) 

						Ağustos-1989', 'Tutup adım adım yürüten Annem. 		Sallayıp beşiği büyüten Annem. 		Sevgiyi saygıyı öğreten Annem. 		Bayramda öptüğüm ellere kurban.		 		Nemli...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt']::text[], 8.5, '{"poet":"Ramazan Kurt","poet_slug":"ramazan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/benim-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühür Gözlüm', 'muhur-gozlum-ramazan-kurt-i4a8v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalinle deli gönlüm eylerim,

				Uçan kuşa senin ismin söylerim,

				Sensiz bu dünyayı zindan eylerim

				Hüzünlendi yine hal mühür gözlüm.

				

				Leyla’m olup bir gün beni gezersen,

				Mecnununu ıssız çölde sezersen,

				Efkarlanıp seven gönlün üzersen,

				Aşkın deryasına dal mühür gözlüm.

				Uyku tutmaz eski yaran azarsa,

				Dilin söyler elin mektup yazarsa,

				Aşkın pınarından sevdam sızarsa,

				Gönül kapısını çal mühür gözlüm.

				Baba ocağına sığmazsa başın,

				Eğilmesin yere kirpiğin kaşın,

				Yakar yüreğimi tek damla yaşın,

				Senindir bu gönlüm al mühür gözlüm.

				Ramazanım zaman geldi geçiyor.

				Gönlüm bu dünyada seni seçiyor.

				Emsallerin yuva yaptı göçüyor.

				Ağzı şeker,dudak bal mühür gözlüm.

 							Temmuz-1972', 'Hayalinle deli gönlüm eylerim, 				Uçan kuşa senin ismin söylerim, 				Sensiz bu dünyayı zindan eylerim 				Hüzünlendi yine hal mühür gözlüm...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt']::text[], 8.5, '{"poet":"Ramazan Kurt","poet_slug":"ramazan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/muhur-gozlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek Seni', 'beklemek-seni-unal-karabulut-peyps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklemek seni...

Çatlayan bir toprağın 

Beklediği gibi yağmuru

Doğum sancısı çeken bir kadının

Beklediği gibi bebeğini

Esir düşmüş bir askerin

Beklediği gibi özgürlüğü

Hayatın yarın için bi güvence vermemesi

Ne kadar ilginç dimi

Neden zordur beklemek 

Vaktin sınırlı olması mı

Yoksa seni kaybetme korkusumu

Belkide hiç kazanmadığım seni 

Gelirsin diye umuşlar olmasa....

Çekilir gibi değil bu BEKLEMEK

10/01/2006', 'Beklemek seni... Çatlayan bir toprağın  Beklediği gibi yağmuru Doğum sancısı çeken bir kadının Beklediği gibi bebeğini Esir düşmüş bir asker...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklemek-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkna', 'i-kna-unal-karabulut-78ar3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Konuşmalıyız, anlatmalısın bana

Tartışmalıyız hatta

Bilmediğim yolda yürüyemem ben

İki dağın arasındayım sanki

Hangisinde olduğum değil önemli olan

Arada uzun süre kalamam ben

Hadi ikna et beni

Büyükse büyük, küçükse küçüğe çıkayım

Renklerden griyim sanki

Oysa hiç sevmedim griyi

Siyah yada beyaz olmalıyım ben

Hadi ikna et beni

siyahsa siyah, beyazsa beyaz olayım ben

Hadi ikna et beni sevdiğine 

Ve senden daha çok seveyim seni ben

Hadi ikna et beni 

Ve senden daha sadık olayım senin davana', 'Konuşmalıyız, anlatmalısın bana Tartışmalıyız hatta Bilmediğim yolda yürüyemem ben İki dağın arasındayım sanki Hangisinde olduğum değil önem...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poker', 'poker-unal-karabulut-fsqkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şeyini alabilirim senin

Sen bilmiyorsun bu oyunu

Hiç saklamaya çalışma elini

Gözlerin söylüyor elindekini

Boşuna blöf yapma

Rest çekmenin hiç sırası değil

Kaybedeceğin çok şey varken 

Kalk git istersen', 'Her şeyini alabilirim senin Sen bilmiyorsun bu oyunu Hiç saklamaya çalışma elini Gözlerin söylüyor elindekini Boşuna blöf yapma Rest çekmeni...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/poker-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-asude-gediz-58yhh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu Bayramın

          kin, 

          nefret, 

          öfke, 

          şiddet

kurbanları.

kırgınlığım ise

kınalı

ne yazık! ! ! ... bırakmıyor yakamı

Tüm Antoloji  ailesinin  kurban bayramı kutlarım', 'Bu Bayramın           kin,            nefret,            öfke,            şiddet kurbanları. kırgınlığım ise kınalı ne yazık! ! ! ... bırakm...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kurban-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Ne Zaman Katliam Olur?', 'kurban-ne-zaman-katliam-olur-huseyin-avdic-an3it', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurban Ne Zaman Katliam Olur? 

Ibadettir, eger kesersen hayvani Allah icin.

Katliamdir, kesilmezse kurbanliklar lillah icin.

-----------------------------

Lillah: Allah icin, Allah yoluna, Allah a$kina.

Berlin, Ocak 2006.', 'Kurban Ne Zaman Katliam Olur?  Ibadettir, eger kesersen hayvani Allah icin. Katliamdir, kesilmezse kurbanliklar lillah icin. ---------------...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kurban-ne-zaman-katliam-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu dünyaya', 'ne-oldu-dunyaya-mikdat-bal-wa5bu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne oldu dünyaya çürütü koktu

Maddesi tamam da cevheri gitti

Sayısız neler var eskiden yoktu

Mevsimler tamam da zemheri gitti

Konforu çok artık kimse yorulmaz

Akraba yabancı oldu sorulmaz

Kimseyle ebedi dostluk kurulmaz

Komşu unutuldu hemşeri gitti

Güzelliğe kanma her şey kaplama

Adam edememiş nice diploma

Bilinenler sağdan soldan toplama

Bin kitap okuyan serseri gitti

Her şeye mutlaka  fesat  karışır

İnsanlık  ne  uyar, ne de barışır

İlaç çok, hastalık durmaz yarışır

Kuş gribi korkuttu, kanseri gitti

Mikdat der şaşırmam artık olana

Haram halal kalktı çalan çalana

Tekmeyi vururlar altta kalana

Devlet orkestrası, konseri gitti', 'Ne oldu dünyaya çürütü koktu Maddesi tamam da cevheri gitti Sayısız neler var eskiden yoktu Mevsimler tamam da zemheri gitti Konforu çok art...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-oldu-dunyaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O ki', 'o-ki-yasemin-sezer-tulgar-hwwq1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürürdü pembe düşler patikasında

Çakıl taşları ışıldarken davetkar

Çıkınında üç öğün tebessüm

Aksatmadan doldur boşalt

Sundu telaşlı sevgisini bonkörce

Sevildi içinin güleçliğiyle

Geçti dudakların kıyı şeritlerinden

Çıplak deniz danslarından

Cemalin kokusunda salındı ki arza

O ki,

Yol kenarlarında yasemin’di oysa …

01.01.06', 'Yürürdü pembe düşler patikasında Çakıl taşları ışıldarken davetkar Çıkınında üç öğün tebessüm Aksatmadan doldur boşalt Sundu telaşlı sevgisi...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-ki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Ser', 'tek-ser-yasemin-sezer-tulgar-9pchf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Salsam suretimi mahşerimden

Kalbur tümsek tepelerinden

Oynatabilir misin

Yarınlarımı yerinden? 

Düşüyor topallığım

Kuytuya 

Us denilen

Sakat de

Hasta de

Ne istersen…

Apansız rüyalarında gecemin

Yürüyemiyorum

Uzaktır karşı kaldırım

Çok uzak

Mazgallar

Kalbur tuzak

Sakınıyorum

Göğsümden

Mavinin tuzunu

Usumun közünü 

Adı’mı’nı

Düşüremem

Dokunamam

Sa’bahı’na

Kıyamam

Ağlamalarım

Yağızdan da beter

Bitsin 

Bozulmasıdır

Yarım rakının 

Seyrinde kalan

Elleri bağlı alkoliğin

Yiten tadıdır

Damağında inleyen

Uzun zaman

Şimdi

Çek sularını

Toplan açıklara

Sahilimden

Köpüren sularımdan

Bırak 

Bozulayım

İki ayak

İki göz

Tek ser

17.09.2005', 'Salsam suretimi mahşerimden Kalbur tümsek tepelerinden Oynatabilir misin Yarınlarımı yerinden?  Düşüyor topallığım Kuytuya  Us denilen Sakat...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/tek-ser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni ve Mutlu Sen’e', 'yeni-ve-mutlu-sen-e-yasemin-sezer-tulgar-d2k5p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırpmak istiyorum tümlenmemiş ömrün yanlarını

Yüce kabulleniş sözleri etmeyeceğim bugün

Kabulüm tek kaygıya ki dolamayan yalın boşluğuma

Yığılmak üzere biriktirilmiş karmaşaların yıllık yükü

Faturası fişi yok bunun ödenesi iade

Serpiştirmek kar tanelerini tipi nefesiyle

Örtmek açmamak üzere kirin sancısını

Adına yeni denen her şeye sarılırcasına neşeyle

Temennim; 

Yeni ve Mutlu Ol Sen(e)  …

31.12.05', 'Kırpmak istiyorum tümlenmemiş ömrün yanlarını Yüce kabulleniş sözleri etmeyeceğim bugün Kabulüm tek kaygıya ki dolamayan yalın boşluğuma Yığ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeni-ve-mutlu-sen-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum', 'dusunuyorum-elazigli-mustafa-kaya-4t06x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aydınlığı bile

başı döndüren gözlerini

düşünüyorum.

yıldızların bile duyduğu

bir gece korkunu

düşünüyorum.

uyumuş kalmışsın

dizimde,

dizimi hiç kıpırdatmadığımı

düşünüyorum.

yanaklarından süzülen

sıcak ıslaklığı,

o ulvi sevgini

düşünüyorum...

mustafa kaya

11.01.2006 / ankara

www.mustafakaya.net', 'aydınlığı bile başı döndüren gözlerini düşünüyorum. yıldızların bile duyduğu bir gece korkunu düşünüyorum. uyumuş kalmışsın dizimde, dizimi ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusunuyorum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi iradeye teslim', 'i-lahi-iradeye-teslim-elazigli-mustafa-kaya-dkdm3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insanın,

yakın durmasıdır

ilahi söze.

huzuruna çıkmasıdır

rabb''ının.

kurban olmak,

kurban demek,

kurban kesmektir,

boynunu vermektir.

itaattir kurban.

teslimiyettir.

dünyayı

en sevdiklerimizi

ölümlü olan her şeyi

ölümsüzlük için

gerektiğinde

ilahi olana

feda etmektir...

mustafa kaya

10.01.2006 / ankara

www.mustafakaya.net', 'insanın, yakın durmasıdır ilahi söze. huzuruna çıkmasıdır rabb''ının. kurban olmak, kurban demek, kurban kesmektir, boynunu vermektir. itaatt...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilahi-iradeye-teslim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlak iradeye teslimiyet', 'mutlak-iradeye-teslimiyet-elazigli-mustafa-kaya-so040', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'daha çizgisiz

daha temiz

ilahi iradenin emrinde olmak.

yaratılış ve

dirilişi red eden 

materyalist olmaktansa.

kabuğu emip

ruhu tüküren...

mustafa kaya

21.07.1994 / ankara

www.mustafakaya.net', 'daha çizgisiz daha temiz ilahi iradenin emrinde olmak. yaratılış ve dirilişi red eden  materyalist olmaktansa. kabuğu emip ruhu tüküren... m...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutlak-iradeye-teslimiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...,', 'ben-avni-aydin-2716n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilemedim...

kimdik biz? ...

nelerdi yaşananlar? 

konuşmazdık ki çok...

ya da anlaşamazdık ne kadar konuşsak da...

ne kadar zaman geçti aradan? 

belki az... belki de çok

farkedemiyorum...

nasıl olacak

ya da nasıl gidecek 

hiç bulamadım...

ve ben...

seni hala unutamadım...', 'bilemedim... kimdik biz? ... nelerdi yaşananlar?  konuşmazdık ki çok... ya da anlaşamazdık ne kadar konuşsak da... ne kadar zaman geçti arad...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-236-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim hikayem', 'benim-hikayem-elazigli-mustafa-kaya-0zp44', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yıkık çeşme 

anlatır beni. 

bir asma kaldırır 

hikayemi. 

bin bir ninni

öper

kundaktan patiğe 

geçişimi. 

taş örtülü

kuyulardan çıktım 

derin ve 

saklı bir dert

raflara dizilmiş 

kıvrımları beynimin

yere düşmüş

evi yanan bir insan gibiyim 

dam altlarında gezmiş.. 

mustafa kaya

10.01.2006  / ankara

www.mustafakaya.net', 'bir yıkık çeşme  anlatır beni.  bir asma kaldırır  hikayemi.  bin bir ninni öper kundaktan patiğe  geçişimi.  taş örtülü kuyulardan çıktım  ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-hikayem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yükü', 'sevda-yuku-bahri-yildirim-xrsz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağırdır sevmelerin yükü   ,biliyorum 

Her yürek taşıyamaz,seziyorum 

Büyüktür umutlar,her yere sığmaz 

Görüyorum... 

Ben yanarım bu gece de aşk ile 

Sevenler anlar, ancak bunu 

Sevmeyen duymaz ,ben duyuyorum 

Seveceksen benim kadar,hazırım 

Seni çok seviyorum...', 'Ağırdır sevmelerin yükü   ,biliyorum  Her yürek taşıyamaz,seziyorum  Büyüktür umutlar,her yere sığmaz  Görüyorum...  Ben yanarım bu gece de ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevda-yuku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare/Siz', 'care-siz-bahri-yildirim-9bifd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlama...! 

Bağırma.....! 

Konuşma....! 

Sakın  bir şey söyleme 

Sussss!  dediler sadece 

Hep bunu söylediler bana 

İyi ama bu doğruysa 

Nasıl anlatacağım, sevdamı sana? 

Ağlasam da, 

Bağırsam da, 

Konuşsam da, 

Kolay değil, 

Bu sevdayı hemen anlatmak sana.

Bir sen duyarsın,duysan duysan 

Çünkü:

Birşeyler var  aramızda  söylenemeyen

Senin,yüreğine oturmuş

Benim dilimin ucunda', 'Ağlama...!  Bağırma.....!  Konuşma....!  Sakın  bir şey söyleme  Sussss!  dediler sadece  Hep bunu söylediler bana  İyi ama bu doğruysa  Nas...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/care-siz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Geçirme Ömrün', 'bosa-gecirme-omrun-seyfet-bozcali-2bbzj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sel gibi akar gider kynaktan,

Boş yaşamla zevk alınmaz hayattan,

Doğru yolda harcanan her zamandan,

Gel sen de al,boşa geçirme ömrün...

Uyuklama kumar masalarında,

Ümit bulma para keselerinde,

Tselliği bulma pis içkilerde,

Gel insan ol boşa geçirme ömrün...

Sorumluluk taşı,uyma şeytana,

Doğrularla yürü,küsme cihana,

Hiç ister mi böyle,yaratan Mevla,

Gel mümin ol boşa geçirme ömrün...

Mevlam kulluk için bizi yarattı,

Tüm nimeti bizler için var etti,

Farz kılarak ilk namazı emretti,

Gel secde et boşa geçirme ömrün...

İhlassız bir vucut olamaz mesut,

Hakça yaşa haklının yolunu tut.

O zaman alırsın yaşamından tat,

Gel kulluk et boşa geçirme ömrün...

Yetime,yoksula yardım elin aç,

Zamanı gelince başlayacak göç,

Seyfet der ellerin Yaratana aç,

Gel dua et,boşa geçirme ömrün...', 'Bir sel gibi akar gider kynaktan, Boş yaşamla zevk alınmaz hayattan, Doğru yolda harcanan her zamandan, Gel sen de al,boşa geçirme ömrün... ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bosa-gecirme-omrun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gelip Geçtin', 'son-gelip-gectin-ayse-hazal-beytas-3gxih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkese kapadım gönül kapımı

Oradan bir defa sen gelip geçtin.

İstesen de artık yazmam adını 

Gönül defterimden son gelip geçtin.

Unuttum sesini yırttım resmini

Çalmıyorum eski aşk bestesini

Bir daha anmadım artık ismini

Aklımdan son defa dün gelip geçtin.', 'Herkese kapadım gönül kapımı Oradan bir defa sen gelip geçtin. İstesen de artık yazmam adını  Gönül defterimden son gelip geçtin. Unuttum se...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-gelip-gectin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde?', 'nerde-seyfet-bozcali-zvt2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak rastlantı haline bugün,

Haramlar yeniyor,hergün,her öğün,

Ahlaksız olana bunlar toy düğün,

Allah''tan korkmanın utancı nerde? 

İhale etmede hep gizli işler,

Bir çoğu haramı hayelde düşler,

Elbette tökezler böyle gidişler,

Gerçeği görenin gözleri nerde? 

Aldığı malları yüzde yüz satan,

Fahiş karla servete,servet katan,

Çok kısa zamanda yükünü tutan,

Büyük şirketlerin doğrusu nerde? 

Enflosyonun hızı artmış büyümüş,

Fakir,fakir kalmış zengin yürümüş,

Kazma kürek ile ömrü çürümüş,

Yokulu soyanın vicdanı nerde? 

Seyfet der boş lafla gemi yürümez,

Hırsızın,hainin nesli türemez,

Doğrunun dürüstün işiş çürümez,

Yazdığım şiirin ibreti nerde? 

              24.10.1985', 'Yaşamak rastlantı haline bugün, Haramlar yeniyor,hergün,her öğün, Ahlaksız olana bunlar toy düğün, Allah''tan korkmanın utancı nerde?  İhale ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerde-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocaman Bir Çocuğa', 'kocaman-bir-cocuga-ayse-hazal-beytas-fh7ie', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çocuk  hayatı zindana çevirir

Pembe  umutlarla yaptığın bütün resimleri boyar siyaha 

Renkler ağlaşır…

Bir çocuk hayatı zindana çevirir.

Söndürür bütün ışıkları

Karanlığa sarılırsın

İndirir bütün perdeleri gökyüzünü göremezsin

“Dur çocuk

Yapma çocuk

Etme çocuk”  diyemezsin

Bir çocuk hayatı zindana çevirir

Karalar açtığın en beyaz sayfaları

Elinde kırık hayallerinden başka 

            bir şey bırakmaz sana

Alır götürür umutlarını

Kalıverirsin öylece

Ve kırar bütün aynaları bir çocuk

Aynada yüzün olmaz.

Üzülüp kahrolursun 

Çocukta hüzün olmaz.

Bilse çok incittiğini böyle yapmaz bilirim

Ama çocuk bu 

                   Bilemez! 

Bir çocuk hayatı zindana çevirir

Çocuk dedim ya! 

Ne halden anlar 

Ne hal anlatır

Gelip dikilir karşıma hiçbir şey olmamış gibi

Bakar buruk buruk

Bütün sitemlerini içine gömersin 

Darılamasın da ona

“afettim” dersin 

Ama

Ama ben seni sevmiştim çocuk

Af edersin', 'Bir çocuk  hayatı zindana çevirir Pembe  umutlarla yaptığın bütün resimleri boyar siyaha  Renkler ağlaşır… Bir çocuk hayatı zindana çevirir....', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kocaman-bir-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-seyfet-bozcali-vvxj9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanma şu Dünya''nın şatafatına,

Gelen göçtü hiç kimseye kalmadı.

Nerede Karun''lar ve Fravun''lar,

Dünya dostu zalimlere kalmadı...

Hani üç kıtayı fetih edenler? 

Nerde Kanuni''ler? Nerde Yavuz''lar? 

Nerde yeni çağı açan Fatih''ler? 

Padişaha,Sultanlara kalmadı...

Anıldıkça kalbe huzur verenler,

Hani Mevlana''lar? Nerde Tebriz''ler? 

Yunus Emre gibi Hakka aşıklar,

Allah dostu olanlara kalmadı...

Nerede ilk Atan,nerede deden? 

Nerde ilk Peygamber Hazreti Adem? 

Mahluka hükmeden Sultan Süleyman,

Dünya''ya ilk gelenlere kalmadı...

Nerde o kutsal Kabeyi yapanlar? 

Nerde islam güneşini yayanlar? 

Ebubekir,Ömer,Osman,Ali''ler,

En büyük dört halifeye kalmadı...

Cehalet devrinde Dünya''ya gelen,

Güzel ahlakıyla,şerefler veren,

Vefatından önce Cenneti gören,

Ol Muhammed Mustafaya kalmadı...', 'Kanma şu Dünya''nın şatafatına, Gelen göçtü hiç kimseye kalmadı. Nerede Karun''lar ve Fravun''lar, Dünya dostu zalimlere kalmadı... Hani üç kıt...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kalmadi-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Cananım', 'affet-cananim-multe-ci-han-lbals', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygularım paramparça

Düşüncelerim flu

İsyanim karanlık bir ordu

Kulaklarım duymuyor sanki

Gözlerim görmüyor

Hissedemiyorum kalbimi

Ayılamıyorum

Yürüyorum etrafıma çarpa çarpa

Kırılıyor her tarafım

Bir cam gibi

Ellerim kanayan yaralarımda

Kayan bir yıldız yansıyor

Kırılmış kadehlerime

Ben yapamıyorum

Gözlerimin önünden kayarken yıldızım

Bir dilek bile tutamıyorum korkumdan

Beni affet cananım

Bir damla yaş yanağımda

Kayboluyorum gök yüzünde

Islanıyor vücudum

Beni affet cananım

Ben

Ben artık yolcuyum', 'Duygularım paramparça Düşüncelerim flu İsyanim karanlık bir ordu Kulaklarım duymuyor sanki Gözlerim görmüyor Hissedemiyorum kalbimi Ayılamıy...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/affet-cananim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Her Gece', 'yalnizim-her-gece-multe-ci-han-xh7k0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farkediyorum

Rüzgarlar arttı son zamanlarda

hayatımda

Görüyorum ki tek kalan yaprak da düşüyor

ağacımdan

Umutlarım son nefesinde

Bir yaz yağmuru hayatım

Hayatım son deminde

Şarap şişeleri benim aşkım

Yıllandıkça daha da değerli...

Savruluyorum ağaçtan dökülen yaprak gibi

Bir sonraki durağım belli değil

Seninle kestirmiyorum biletimi

Nerede hayat bulurum bilmiyorum

Yerde günden güne daha da kuruyorum

Bu 

bir elveda vaktidir belki

ya da yeni bir macera

Her ne olursa olsun geleceğimde

sensiz her yer soğuk 

elimde son şarjörümle

Her ne olursa olsun geleceğimde

sen yoksan eğer

YALNIZIM HER GECE', 'Farkediyorum Rüzgarlar arttı son zamanlarda hayatımda Görüyorum ki tek kalan yaprak da düşüyor ağacımdan Umutlarım son nefesinde Bir yaz yağ...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizim-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-saadet-un-fxd2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu gece

sinsi aynada alaycılık

inadına

mimiklerim gülümsüyor

anılarımı soğuklaştırmış

duvarlar

buz gibi

yüreğim yorgun çarpıyor

bu gece

hasret yıkmamış dağları

sevgi

kaf dağından el sallıyor

parmaklarım uyuşmuş

can yitik canım

üşüyorum

bu gece

sırdır

sırdaşımdır

takvim yaprakları

sessizlik 

daha bir suskun

avuçlarımda iki damla gözyaşımla

başım dik

yıkılıyorum', 'bu gece sinsi aynada alaycılık inadına mimiklerim gülümsüyor anılarımı soğuklaştırmış duvarlar buz gibi yüreğim yorgun çarpıyor bu gece hasr...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-gece-180-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temenni', 'temenni-gul-aycan-jmtfe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazı şeyler vardır ki unutulmaz,

Silinmez hatıra defterlerinden.

Yok etmek istersin, ellerin gitmez.

Silsen de hayat başlamaz yeniden.

Yürü ve git, ardına bakma sakın; 

Hatıralar gözünde canlanmasın.

Yeni bir hayat beklerken seni,

Mendilin avucunda ıslanmasın.

Bazı şeyler vardır ki,sonu gelmez.

Bitti dediğin yerde başlar yeniden.

Mutlu hatıralar çok uzun sürmez,

Yok olur, gider; silinir gözünden.

Aralık 2004', 'Bazı şeyler vardır ki unutulmaz, Silinmez hatıra defterlerinden. Yok etmek istersin, ellerin gitmez. Silsen de hayat başlamaz yeniden. Yürü ...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/temenni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanlı Bayrağım', 'sanli-bayragim-suleyman-yavas-5ylsu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şehidin kanı kokuyor senin al renginde

Gece gündüz göğü süsleyen şanlı bayrağım

Üstümüze gölgesin yurdun her zemininde

Gece gündüz göğü süsleyen şanlı bayrağım

Senin ay yıldızın benim gönlümün ilacı

Senin olmadığın yerde çekiyorum acı

Şu göklere giydiriyorsun en güzel tacı

Gece gündüz göğü süsleyen şanlı bayrağım

Sen hep dalgalan canıma bağlanmış bayrağım', 'Şehidin kanı kokuyor senin al renginde Gece gündüz göğü süsleyen şanlı bayrağım Üstümüze gölgesin yurdun her zemininde Gece gündüz göğü süsl...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanli-bayragim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Çığlık', 'son-ciglik-gul-aycan-qrlhc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece gündüzü kovalar dururken

Sabah arkasından koşar gecenin.

Perdeler kapanır oyun biterken,

Sahneler değişir durmadan her dem.

Bir şeyler değişir, olur ve biter.

Hayat gam yoludur, ölümle biter.

Ölüm gelmeden uzayan geceler,

Kapıyı çalınca son bulur, biter.

Hayat sahnesinde yaşayan ömrü,

Her vakit ''başındayım'' der ''yolumun''.

Ne kadar yaşasa kısadır ömrü,

Getirmez aklına gideceğini.

Bir çığlık belirir dudaklarında.

Söylesen bir türlüdür, sussan bir türlü.

Kelimeler şekillenir dudaklarında.

Görmez olur gözün ne gördüğünü.

Bir haykırış gelir, kopar içinden.

Sessizliğin sesi susturur seni.

İçinden geçeni söyleyemezsin.

Bilmezsin, nereye götürür seni.

25 Aralık 2004', 'Gece gündüzü kovalar dururken Sabah arkasından koşar gecenin. Perdeler kapanır oyun biterken, Sahneler değişir durmadan her dem. Bir şeyler ...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-ciglik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..ÇiĞDeM ÇiÇeĞiM...', 'cigdem-cicegim-murat-dogan-jap1o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat göründüğü kadar basit değildir be ÇiğdeM çiçeğim.

Yağmuru sevdiğin kadar çamurunuda seveceksin.

Gülmeyi bildiğin kadar ağlamayıda öğreneceksin.

Çok acılar çekecek,çok şeyler göreceksin.

Ve bir gün gelecek ''eehh artık yaş kemale erdi'' diyeceksin.

Yüzündeki kırışıklıklara ve gözlerindeki yorgunluğa aynada bakarken

Kendi kendine gülümseyip,

Hayat göründüğü kadar basit değildi ÇiğdeM çiçek diyeceksin..

......çiçi''ye hitaben; sevgilerimle benim küçük çiğdem çiçeğim..', 'Hayat göründüğü kadar basit değildir be ÇiğdeM çiçeğim. Yağmuru sevdiğin kadar çamurunuda seveceksin. Gülmeyi bildiğin kadar ağlamayıda öğre...', ARRAY['Türk Edebiyatı','Şiir','Murat Doğan']::text[], 8.5, '{"poet":"Murat Doğan","poet_slug":"murat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cigdem-cicegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap Rakı Çin Kirpiklerimden Damlıyor (2)', 'sarap-raki-cin-kirpiklerimden-damliyor-2-eyup-selahattin-dalkiran-fz3s3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapat gözlerini kapat

Gözlerini gözlerim görmesin

Yoksa dayananam

Öperim rujlu dudaklarından

Kapat gözlerini kapat

Gözlerim gözlerini görmesin

yoksa duramam

içerim gözlerindeki aşkı

Yudumluya yudumluya

Kapat omuzlarını şalınla

dayanaman öperim omuz başlarından

Hadi dokundur parmak uçlarını

parmak uçlarıma,yakarcasına

hadi sevinçlerimize,sevişmelerimize

öyle usul usul varalım

kimse farkına varmadan.

Haydi kalk gidelim

içtik içtiğimiz kadar

Neredeyse gözlerimden seninde

omuzlarından akacak şampanya

haydi kalk gidelim.

Yoksa içeceğim omuzlarından akacak 

şampanyayı hasretler içinde sen diye.

Hadi kalk gidelim

Ayak parmaklarımızdan akan

aşk ateşinde yanalım 

Haydi kalk gidelim

Gidecemiz yer yakın hadi.

Ama dikkatli olalım Faşistler karşıda

Durmakta Pisi pisine ölmek istemem

Senin kollarında.', 'Kapat gözlerini kapat Gözlerini gözlerim görmesin Yoksa dayananam Öperim rujlu dudaklarından Kapat gözlerini kapat Gözlerim gözlerini görmes...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sarap-raki-cin-kirpiklerimden-damliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümden Ömrüne', 'omrumden-omrune-suleyman-yavas-3a06a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrümden ömrüne

Bir ömür versem

Zatına bağlanıp

Önünde eğilsem

Leblerinden 

En dolu sevgimle öpsem

Ebedi bir aşkı getirip

Önüne sersem

Mağrur bir şey

Yapmış olmam güzelliğine', 'Ömrümden ömrüne Bir ömür versem Zatına bağlanıp Önünde eğilsem Leblerinden  En dolu sevgimle öpsem Ebedi bir aşkı getirip Önüne sersem Mağru...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/omrumden-omrune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B e n D o ğ d u m', 'b-e-n-d-o-g-d-u-m-koksal-akar-xoc1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben doğdum maviyi vurdu avcılar,

Kapladı yönümü siyah bir duman.

Bir başka ruhuma sindi sancılar,

Yıldızları yerde gördüğüm zaman.

Dirildi karanlık, ışıklar söndü; 

Yıkıldı yıkılmaz dediğim duvar (!)

Renklerin dünyası tersine döndü,

Uzadı mevsimler, asırlar kadar.

Her seher ömrümden ıradı umut; 

Elimden aldılar oyuncağımı.

Anne(!)    sen al beni koynunda uyut

Saçların yap n''olur, salıncağımı...', 'Ben doğdum maviyi vurdu avcılar, Kapladı yönümü siyah bir duman. Bir başka ruhuma sindi sancılar, Yıldızları yerde gördüğüm zaman. Dirildi k...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/b-e-n-d-o-g-d-u-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün II', 'bir-gun-ii-gul-aycan-kfk39', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün bugün gibi bir gündü, o gündü.

Gelmeyen yarından evvelki gündü.

Öteden bir suret geldi, göründü:

Bir hayal, bir rüya. bir düş misali...

Vakit ne vakitti, geçmek bilmedi.

Sen gelmeden evvel yüzüm gülmedi.

Sen geldiğindeyse artık çok geçti.

Yüzümden gülüşüm silindi gitti.

Ne zaman buradan geçecek olsak,

Ya sen kayıp oldun ya da ben yoktum.

Yıllar sonra karşılaştık burada,

Ne sen beni bildin ne de ben seni...

Aralık 2004', 'Gün bugün gibi bir gündü, o gündü. Gelmeyen yarından evvelki gündü. Öteden bir suret geldi, göründü: Bir hayal, bir rüya. bir düş misali... ...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük', 'buyuk-suleyman-yavas-2fsm0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki şu dilin büyük demek ister

O vakit sen söyle Allahuekber', 'Belki şu dilin büyük demek ister O vakit sen söyle Allahuekber...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavaş']::text[], 8.5, '{"poet":"Süleyman Yavaş","poet_slug":"suleyman-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/buyuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'U y u Y a v r u m', 'u-y-u-y-a-v-r-u-m-koksal-akar-h9daf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elbet bir gün yanacaksın,

Dünyayı hoş sanacaksın.

Ne var ki uyanacaksın,

Uyu yavrum uyu uyu…

Yaşamak mı, söyle; nasıl? 

Bir uyan görürüsün asıl.

Dünya bir garip velhasıl,

Uyu yavrum uyu uyu…

Kıymet bilen kimmiş, nerde? 

Dayanırsın hangi derde? 

Gel sesime kulak ver de,

Uyu yavrum uyu uyu…

Var dolaşma dere, tepe...

Körpeciksin henüz, körpe.

Uzanıver sere serpe,

Uyu yavrum uyu uyu…

Uykuları süzsün gözün,

Umutları ezsin gözün,

Rüyalarda gezsin gözün,

Uyu yavrum uyu uyu.

Zannetme ki hoştur dünya,

İnan bana boştur dünya.

Koştur, koştur, koştur dünya...

Uyu yavrum uyu uyu…

Dertler sinene dayanır,

Saçların aka boyanır,

Uyanma sular uyanır,

Uyu yavrum uyu uyu…

Yavrum cana yeter minnet,

Ölümden de beter minnet.

Sana vaat edildi cennet,

Uyu yavrum uyu uyu…', 'Elbet bir gün yanacaksın, Dünyayı hoş sanacaksın. Ne var ki uyanacaksın, Uyu yavrum uyu uyu… Yaşamak mı, söyle; nasıl?  Bir uyan görürüsün a...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/u-y-u-y-a-v-r-u-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk! Bir Kez Daha', 'ask-bir-kez-daha-atilla-guler-2bkgf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün ortası bir şarkıda buluştu şiir

kızıllığına doyamadım

ürkek adımları akşamı denk düşürdü gözlerine

elasında savurdu yalanın yalanını

rengini bulamadı sevginin kollarında

ayazına düştü sıcağı

sabahları içti kana kana

sırtını çevirip gecenin gizemine

epriyen yüreğinde bir sızı

gerçek sevgi kimin yüreğinde

Leyla öldürdü Mecnun''u

Romeo kimin kurbanı

güneş tutuşturdu saçlarını suçluluğun

haykırışları takılı kaldı bulutlara

üzgün kelimeler silindi gökyüzünden

bir yangına yazıldı adı fırtınanın

lavanta kokusu sindi koynuna

havada bir delilik var

ekmeğine sürdü yeni sevgisini

katığı aşk bir kez daha

“Hey! ”

rakılar benden bu akşam hayata', 'gün ortası bir şarkıda buluştu şiir kızıllığına doyamadım ürkek adımları akşamı denk düşürdü gözlerine elasında savurdu yalanın yalanını ren...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-bir-kez-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamlama', 'tamlama-fulya-celikbilek-h49at', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biraz  sende  olandım  ben

Biraz  bende/ndim  sen olduğun.



09.01.2006', 'Biraz  sende  olandım  ben Biraz  bende/ndim  sen olduğun. 09.01.2006...', ARRAY['Türk Edebiyatı','Şiir','Fulya Çelikbilek']::text[], 8.5, '{"poet":"Fulya Çelikbilek","poet_slug":"fulya-celikbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tamlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Karıştı Akşama', 'ay-karisti-aksama-muharrem-kemal-gunduz-pftz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün daha biterken yokluğunda

Ay karıştı akşama

Sevdam gönül çıkmazında yiterken

Sensizliğinde ay karıştı akşama..

Dağlarda yeşerip açtı gelincikler

Yanan yüreğimi nerden bilecekler

Unutulan sevinç zoraki gülücükler

Yokluğunda ay karıştı akşama..

Bu baharda bekle geleceğim

Uzun ayrılık sonu seni göreceğim

Ölüm ayıramaz seni seveceğim

Sensizliğinde ay karıştı akşama..

İhanet edersen çıksın ölün

Burulsun boynun, solsun gülün 

Yıllardır bekledim ve bugün

Yokluğunda ay karıştı akşama

          27-29/Nisan/1984', 'Birgün daha biterken yokluğunda Ay karıştı akşama Sevdam gönül çıkmazında yiterken Sensizliğinde ay karıştı akşama.. Dağlarda yeşerip açtı g...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ay-karisti-aksama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mona Lisa', 'mona-lisa-utku-demir-t0tju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıradan bir bakış değil bu

Cadıkazanından çıkma 

Büyüleci bir duruş

Zerafetiyle yutar içine düşeni

Hızla arşınlatır sınırları

Kaybolduğun mutluluk vaatli ormanı

Perdelerini indirir

Demir attın diziye

Yanında platonik yenikler 

Karşında ölümsüz Mona Lisa

Peşinden münzevi sözcükler 

Her an salınır umut kapısına

Soğurulur katıksız gülümsemesi 

Tüm dünya görünmez,anaç kuyruğunda

Çekiniktir çaresiz kleptomanisine

Virtüözlerin titreyen telleri

Mona Lisa''nın soluk yıllarında

Ah Leonardo 

Bu nasıl bir ebediyettir

Mahçup denizi kabartan izin simgesi', 'Sıradan bir bakış değil bu Cadıkazanından çıkma  Büyüleci bir duruş Zerafetiyle yutar içine düşeni Hızla arşınlatır sınırları Kaybolduğun mu...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mona-lisa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerime, gecelerime hüzün çöktü', 'gunlerime-gecelerime-huzun-coktu-i-sa-tekin-pk2nu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yokken yanımda

Sevgi yapraklarım kurudu

Günlerime, gecelerime hüzün çöktü

Mevsimlerin rengi değişti

Tırpana vurdum umutlarımı

Yalnız gecelerimin

Karanlık gecelerimin

Renkli arkadaşıydı umutlarım

Acılarla dolu sevdamı

Gömerken yüreğime

Bire bin veren sevgi başağı

Henüz fide iken bağrımda

Koparıp aldın ansızın bir gece

Kalp atışlarım değişti

Damarlarım koptu inceden inceye

Yüreğimin derinliklerinde

Pişmanlıklar vurur yüreğimi

Söküp atmak isterim derinden

Acılar vurur yüreğimi

Elimde değil, 

Sevgim toprağa düşmüş

Sevdam ile birlikte

Sökümü zordur damardan

Sensiz zaman geçmiyor

Özlemler, ayrılıklar üstüme üstüme

Acılı yüreğim, yeniden kanıyor 

Vurulurum her gece düşlerimde

Kan revan içinde uyanırım 

Dicle''den bir tas su derman olur yüreğime

Ben Sur''lara bakarım 

Sur''lar Dicle''ye

Bazen kudurur dalga olur,

Kayadan kayaya çarpar özlemler

Ve umutlar akar peşi sıra gider

Bazen dalgalı bazen hüzün ile derinde

Oysa ben geriye giderim

Senin ile olan günlerimize

Güzel gözlerin hapseder yüreğimi

Yüreğim bir başka atar o an

İlk günkü gibi heyecanlanırım

Dilim kurur konuşamam

Düşündüklerim yüreğimde kalır

Anlatamam bu sevdayı

Gösteremem bu sevgiyi

Sevdamda alkışa, tezavrata yer yoktur

Dil lal olur

Gözler konuşur 

Benim sevdam çatal yürektedir

Sol göğsümün orta yerinde

Sen olmayınca incirim derinden

Dicle''ye bakarım

Karacadağ''dan esen rüzgar

Alıp götürsün acılarımı özlemlerimi

Çünkü bu yürek acıyı kaldıramaz sensiz

N'' olur seher vaktinde 

Güneş doğmadan gel 

Kollarını, yüreğini açta öyle gel

Bu sevdayı büyütelim seninle', 'Sen yokken yanımda Sevgi yapraklarım kurudu Günlerime, gecelerime hüzün çöktü Mevsimlerin rengi değişti Tırpana vurdum umutlarımı Yalnız gec...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/gunlerime-gecelerime-huzun-coktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
