INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Ey hayat men seni Neylerem..', 'ey-hayat-men-seni-neylerem-murat-dogan-mzle6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Menim cağnım candan getmiş ey hayat..

Şimdi men senin gözelliklerini neylerem? 

Bilirem  feryadım yakarışım faydasız,

Sana gitme desem sesimi duyura bilmirem,

Menim canım getme men sensiz neylerem..', 'Menim cağnım candan getmiş ey hayat.. Şimdi men senin gözelliklerini neylerem?  Bilirem  feryadım yakarışım faydasız, Sana gitme desem sesim...', ARRAY['Türk Edebiyatı','Şiir','Murat Doğan']::text[], 8.5, '{"poet":"Murat Doğan","poet_slug":"murat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ey-hayat-men-seni-neylerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücün Yeterse', 'gucun-yeterse-cengiz-suslu-zwraa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonumuz meçhul bizim,ak demek yanlış olur.

Kırık duygularımı,düzelt gücün yeterse.

Sana mutluyum dersem,bilki palavra olur.

Bitirdiğin şu ömrü yaşat gücün yeterse.

Ne sokakta sarhoşum,ne sarayda paşayım,

Ne sarhoşa şarabım,ne paşaya asayım.

İstedim ki bir kerede yere sağlam basayım,

Vurup tuş ettin beni; kaldır gücün yeterse.

Hey hat! 

Yıkarım dağları derdim,bende eski zamanda,

Şöyle bir dikildim mi kar yağardı baharda.

Her geçen gün gururla bağlı iken hayatla,

Bütün ipleri kestin,bağla gücün yeterse.

Artık gücüm kalmadı,ince yerinden kopsun.

Eskittiğin gönlümde ha varsın hada yoksun.

Kokladığım tüm güller masana meze olsun,.

Kalbimde kurumuşsun yeşert gücün yeterse

1990', 'Sonumuz meçhul bizim,ak demek yanlış olur. Kırık duygularımı,düzelt gücün yeterse. Sana mutluyum dersem,bilki palavra olur. Bitirdiğin şu öm...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gucun-yeterse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Yeniden', 'her-gun-yeniden-cem-veysel-gul-iuj1s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim demis ki; 

Ben yasiyorum

Senin nerde oldugunu bilmeden

Ben icten ice kendimce

Her gün yeniden 

Ölür ha ölürüm.

Kim demis ki; 

Ben asik olamam

Sen gökte yildiz

Ben yerde Atesböcegi gibi

Sana karsi

Yanar ha yanarim.

Kim demis ki; 

Ben sevemem

Sen denizde su

Ben sana ulasmya calisan

Bir irmak gibi her an

Icimden sana dogru

Akar akar ha akarim

Inanki...

cem Veysel Gül

08/01/2006-04:30

schw.gmünd/almanya', 'Kim demis ki;  Ben yasiyorum Senin nerde oldugunu bilmeden Ben icten ice kendimce Her gün yeniden  Ölür ha ölürüm. Kim demis ki;  Ben asik o...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-gun-yeniden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renksiz / siz bilenmeleri...', 'renksiz-siz-bilenmeleri-zafer-zengin-etnika-fw4h3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

açık gömlek yakalarının arasından

içeri süzülen rüzgara ve dağlanan yerleri soğutmasına dair; 

elbette''nin nesi olursa

tutuşan belki kendiyle

isimsizde çokça

kralları bile ister

ve bir boyacı

bir asker belki

köşede unutulmuş film

bir keman sesi belki

“gezginlere biçiyorum

öyle koşmalı

sakince adımlamalı işte “

bana ne

demokrasinizden

sosyalizmden

faşizminizden

bahsetmeden anlatın 

uçsuz bucaksın mekanı

içinde kaldığım dünyayı

güzel mi özgürlükten

öyle büyük ki

gözlerimle çiziyorum 

giriyorum içine yüreğimle

ben varım elimde

size yalnızlık bıraktım

biraz sayın

yorulmayın

gelirse özgürlük

gelecek deyin oyalayın

yalnızsın deyip ağlatmayın …

06 07 2005

.', '. açık gömlek yakalarının arasından içeri süzülen rüzgara ve dağlanan yerleri soğutmasına dair;  elbette''nin nesi olursa tutuşan belki kendi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/renksiz-siz-bilenmeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmeyen Ask', 'olmeyen-ask-huseyin-saim-gurer-q8p6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne cabuk gecti yillar,

Elimde kalem,masamda kagit,

Harfler yaziyorum,ismin cikiyor sonunda

kokun burnumda,gozlerin hayalimde

Bilirdim seni her zaman sevecegimi,

Deliler gibi ozleyecegimi,

Kapi,kapi dolasirim,

Sen cikarsin karsima her yeni yuzde.

Her yeni sarkida ozlemin calar,

Kalbim isminle carpar,

Onsekiz sene ayrilik birsey degilki,

Gonlum seni arar,hergun anar.

Olmeyen askimi seneler ispat etti,

Koprulerin altindan ne sular gecti,

Sen hala benlesin

Kokun burnumda,gozlerin hayalimde.

Kah Cinarin altinda,kah deniz kenarinda,

kah bebekte,kah bostancida,

Bazen raki kadehinde,bazen calan sarkilarda,

Lunaparkta carpisan arabalarda

Hep varsin hep benlesin kah gozyasimda,

Gercek aski anlatamaz ne siir ne romanda,

Ben seni  cok sevdim takildim kaldim zamanda,

Bitmesin bu siir nede askin beyazgul sokakta', 'Ne cabuk gecti yillar, Elimde kalem,masamda kagit, Harfler yaziyorum,ismin cikiyor sonunda kokun burnumda,gozlerin hayalimde Bilirdim seni h...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Saim Gürer']::text[], 8.5, '{"poet":"Hüseyin Saim Gürer","poet_slug":"huseyin-saim-gurer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmeyen-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Üşüyor mu Ellerin?', 'usuyor-mu-ellerin-umut-gul-a8liw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğuluydu gözlerin 

Giderken... 

Ardımdan gel diyordu titreyen sesin 

Gözlerinde yalvaran bakışlarınla 

El sallıyordun bana… 

Gidişine isyan eden ayakların 

Takılıyordu kaldırımlara 

Gidiyordun... 

Yüreğin kalıyordu bende 

Bir de o gülen gözlerin... 

Hala anımsıyorum, 

Dönmek üzere gidişini… 

Yanıyordun, 

Sen de benim gibi 

Dışarda zemheri ayaz 

İçimizde hasret ateşi 

Henüz bırakmamıştık ellerimizi… 

Sımsıcaktı bıraktığımda 

Söyle, 

Şimdi üşüyor mu ellerin... 

(Bilirim en çok ellerin üşür senin...)', 'Buğuluydu gözlerin  Giderken...  Ardımdan gel diyordu titreyen sesin  Gözlerinde yalvaran bakışlarınla  El sallıyordun bana…  Gidişine isyan...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/usuyor-mu-ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zile''ye Çeken', 'zile-ye-ceken-mehmet-ayhan-gunaydin-vjco6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ZİLE’YE ÇEKEN

Bir şey var bu yerde,

Bir şey var bu şehirde,

Bir şey var Zile’de,

Beni kendine çeken.

Baba ocağı oluşudur belki,

Geçmişimdir belki,

Eskiye özlemdir belki,

Ya da, topraktır belki,

Belki de beni çeken.

Ne zaman gitsem Zile’ye,

Önce kaleye çıkıyorum.

Sonra eski sokakları,

Bir bir dolaşıyorum.

Mutlak Ulu Camide

Bir sabah namaz kılıyorum.

Sabah namazı sonrası,

Fırınlara gidiyorum.

Sıcak ekmek kokusunu,

Şöyle doya doya,

İçime bir çekiyorum.

Ne yapayım bu kokuyu,

Ben çok seviyorum. 

Tanıdık tanımadık,

Herkesle selamlaşıyorum.

Sonra girip bir dükkana,

Çay içip, sohbet kuruyorum.

Tanımayan garipsiyordur belki,

Bu da kim ki diyordur.

Kınamayın,

Senede bir ya da iki,

Anca gelebiliyorum.

Gelince de özlediğim ne varsa,

Bir araya sıkıştırıyorum.

Dışarıda olmak zor, özlemse fazla,

Ben bu şehri çok seviyorum.

M. Ayhan Günaydın.

    29 Aralık 2005 

          Ankara', 'ZİLE’YE ÇEKEN Bir şey var bu yerde, Bir şey var bu şehirde, Bir şey var Zile’de, Beni kendine çeken. Baba ocağı oluşudur belki, Geçmişimdir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/zile-ye-ceken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim der zavallı', 'sairim-der-zavalli-mikdat-bal-g3sgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair diye ortalıkta dolaşır

Aşar gider şairim der zavallı

Çukur herif her pisliğe bulaşır

Yaşar gider, şairim der zavallı

Sağ gösterir solu vurur gözüne 

Saldırarak insanların özüne 

Hakareti katar her bir sözüne 

Coşar gider şairim der zavallı

Medeniyim der de fular bağlamaz 

Her gittiği yerde uyum sağlamaz 

Kovulursa ona kimse ağlamaz 

Şaşar gider, şairim der zavallı

Açıktan açığa isme saldırır 

Kıyafete, boya cisme saldırır 

Tanımadan bakar resme saldırır 

Koşar gider şairim der zavallı

Kart horozdur ötüşünde düzen yok

Sanır kendi benden iyi yazan yok

Yanlışlarda ondan fazla yüzen yok

Şişer gider, şairim der zavallı

Mikdatî der özü sözü bir olmaz

İçi pislik belki yüzü kir olmaz

Toplasan da bunun yüz’ü bir olmaz

Taşar gider şairim der zavallı', 'Şair diye ortalıkta dolaşır Aşar gider şairim der zavallı Çukur herif her pisliğe bulaşır Yaşar gider, şairim der zavallı Sağ gösterir solu ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sairim-der-zavalli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamın Biri 2', 'adamin-biri-2-bolat-unsal-pf74l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyi yolunda kurudur tuzu

Mihnet nedir bilmez gerilmez yüzü

Bar pavyon gazino kesilmez hızı

Gezdikçe geziyor adamın biri

Elinde purosu ipek yuları

Kapatır her gece disko barları

Cüzdanından çekip yuro doları

Bozdukça bozuyor adamın biri

Coştukça viskiye atıyor perdah

Şarkılar türküler oluyor sabah

Dudak defterine sayısız kadeh

Yazdıkça yazıyor adamın biri

Oldukça kalındır ense derisi

Çekilmez kahırı bitmez kaprisi

Etrafına garson konsamatrisi

Dizdikçe diziyor adamın biri

Kafayı bulunca attıkça atar

Başı sıkışınca adamı satar

Gerer ortamı bir birine katar

Azdıkça azıyor adamın biri', 'Her şeyi yolunda kurudur tuzu Mihnet nedir bilmez gerilmez yüzü Bar pavyon gazino kesilmez hızı Gezdikçe geziyor adamın biri Elinde purosu i...', ARRAY['Türk Edebiyatı','Şiir','Bolat Ünsal']::text[], 8.5, '{"poet":"Bolat Ünsal","poet_slug":"bolat-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adamin-biri-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel', 'ecel-cansu-sevda-ozbey-eufnx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ecel gelip çalsın rüzgâr yerine, kapımızı

Buzdan soğuk ellerini bekliyor, bekliyorum…

Bir canım var zaten, başka neyim var ki? 

İstiyorum ki uğrunda feda olsun! 

Aşkın güneşmiş, at beni tam ortasına

Senin için yanmaya razıyım! 

Hasretinle yanmaktansa, 

Aşkında kavrulayım! ...

Sen de biliyorsun

Her şey senle başlar, senle biter bende

Ölüm bile gözümde hiçtir! 

Şayet bir gün vereceksem son nefesimi bir tanem? 

Ecelim senin elinden olsun,

O bana sevinçtir! ...', 'Ecel gelip çalsın rüzgâr yerine, kapımızı Buzdan soğuk ellerini bekliyor, bekliyorum… Bir canım var zaten, başka neyim var ki?  İstiyorum ki...', ARRAY['Türk Edebiyatı','Şiir','Cansu Sevda Özbey']::text[], 8.5, '{"poet":"Cansu Sevda Özbey","poet_slug":"cansu-sevda-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ecel-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-cansu-sevda-ozbey-xd8oi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamlar olmadan

Saçlar ağarmadan

Güllerim solmadan

Gel, durma, haydi gel! 

Bitmeden umudum

Susmadan ud’ um

Çıkmadan tabutum

Gel, durma, haydi gel! 

Şafaklar atmadan

Baharım bitmeden

Gençliğim gitmeden

Gel, durma, haydi gel! 

Geçmeden bu mevsim

