INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-cihan-basak-w6qia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzü karanlığın üstüne ağlıyor

Istırabın dinmedigi bu yolda tek arkadaşım rüzgar.

Yağmurla karanlık üstüme siniyor

Rüzgar deli gibi üstüme geliyor...

Bozuk kaldırım taşları üzerinde ıslanan üstüm başım...

Bugece bir başkayım.

Yürüdüğüm yol hiç bitmeyecekmiş gibi

Ömrümün yarısını burada bırakacakmışım gibi...

Su birikintilerine girip çıkan ayaklarım...

Gecenin rengiyle beynime çarpan

Birkaç devrik cümlenin intikamı...

Ve gurursuzlaşan gururumun yanıbaşına düşen 

bir kaç silik isim...

Tüm hırçınlıklarıyla sallanan ağaç dallarında 

Asılı kalmış bir kaç bezgin yaprak...

Gençliğimi andıran bir hüzün.

Sarhoş olmuş ruhum ümidime saldırıyor

Bastığım kaldırım taşları inliyor sanki.

Ve gökgürültüsüyle coşan yağmurun sesi...

Üstüme çullanan bir yığın kelime...

Ümidimin dip notları.

Ne kimsem var bu yolda ne de bir dost var yanımda.

Beni kızdıran tek şey gece.

Gölgemi bile benden gizleyen gecenin nankörlüğüydü beni kızdıran...

Hıçkırıklara boğulan gökyüzünde

Karanlığın acımasızlığını yumusatan

Yağmur tanecikleri...

Uzayan yol ve bitmek bilmeyen  gece...

29 Mayıs 1998 Gazimagosa', 'Gökyüzü karanlığın üstüne ağlıyor Istırabın dinmedigi bu yolda tek arkadaşım rüzgar. Yağmurla karanlık üstüme siniyor Rüzgar deli gibi üstüm...', ARRAY['Türk Edebiyatı','Şiir','Cihan Başak']::text[], 8.5, '{"poet":"Cihan Başak","poet_slug":"cihan-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yol-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın Canı', 'canimin-cani-birsen-ates-7l4vl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünüp durdum delice 

gittiğimde bıraktığım seni.

o derin dalan gözlerin

gitmiyor hafızamdan 

öyle özledim ki inan

bana canımsın demeni 

canımın canı 

ben seninim hala 

bıraktığın yerdeyim 

aşka dair ne varsa 

biriktirdim yüreğimde 

seninleyim 

her solukta aldığın 

gecendeyim hayallere daldığın 

yatağındayım bensiz uyandığın 

14.01.06', 'düşünüp durdum delice  gittiğimde bıraktığım seni. o derin dalan gözlerin gitmiyor hafızamdan  öyle özledim ki inan bana canımsın demeni  ca...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canimin-cani-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ve Sen.', 'ben-ve-sen-suheyl-turkoglu-zkkpa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ben vardım,

Bir de sen,

Saçını başını

Yolarken  aşk,

Bir ben vardım,

Bir de sen.

Sevgiye dokunurken,

Gözlerine

Destan yazarken

Teninde

Hayat bulurken,

Bir ben vardım

Bir de sen.

Ayrılığı sularken

Göz yaşlarım,

Kururken hayat ağacım,

Gönlüme sordum

Sevdayı gördüm,

Bir ben vardım,

Bir de sen.

Tutku oldu

Tutundum.

Çiçekler döşedim 

Yollarına

Baharlarda

Bir ben vardım

Bir de sen.', 'Bir ben vardım, Bir de sen, Saçını başını Yolarken  aşk, Bir ben vardım, Bir de sen. Sevgiye dokunurken, Gözlerine Destan yazarken Teninde H...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-ve-sen-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim Oğlum', 'seni-ozledim-oglum-orhan-eren-uncu-iyi03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilirmisin? 

Bir umuttur özlem

Beklediğine sarılmak için

Zamanı durdurmak

Akreple yelkovana rest çekmektir özlem

Bir umuttur özlem

Uzak yürekleri

Bir birine tutturmak

Sıkı sıkı sarılmak

Kopmadan kalbe yapışmak

Bir umuttur anlık zamanda

Sevdiğini elini tutmaya çalışmaktır özlem

Özlem yürekten üşümüş

Dudakların çarpışması

Özlem, terminal hatlarında 

Kaybolan duyguları bağlamktır yürekten

Uzatıp elini yüreğine

Bırakmaksızın sarılmak

Yıkılmadan kopmadan

Trenin raylara sarılması gibi

Benim seni yüreğime 

Hapsetmemdir özlem

Özlem hiç kopmaksızın

Benim yanımda olmandır

Tükenmeden ayaz gecelerde

Senin geleceğini bilerek

Beklemektir sabahı

Gün doğana kadar

Ve seni yanımda olduğunu görmektir özlem

Ve seni içime çekmektiğim andır özlem

Sevgili oğlum..

Özlem sensindir... 

14/01/2006

02:24', 'Bilirmisin?  Bir umuttur özlem Beklediğine sarılmak için Zamanı durdurmak Akreple yelkovana rest çekmektir özlem Bir umuttur özlem Uzak yüre...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-ozledim-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızımı Alamadım', 'hizimi-alamadim-naciye-bildim-g90py', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu dünyada bir kez olsun

Gözümü açamadım.

Her nereye bakacak olsam,

Gözümde hep sen vardın.

Bir tek arzum bir tek emelimdin

Ama benim olmadın.

Neler yaptım nelerde,

Ey kader

Dur daha hızımı alamadım...', 'Şu dünyada bir kez olsun Gözümü açamadım. Her nereye bakacak olsam, Gözümde hep sen vardın. Bir tek arzum bir tek emelimdin Ama benim olmadı...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hizimi-alamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
