INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teneke ile Yağmur', 'teneke-ile-yagmur-ahmet-zekai-yildiz-rb6xi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çatı tenekesinde fakir tıpırtı.

Duvar dibinde ıslak kedi kaygılı.

Penceresinden duygu aktı şairin.

Damlalar düşünce oldu bu gece.

Ne eski kaldı yaşanan.

Ne de yeni yaşanacak zaman.

Sabah oldu olmasına da,

Akşam nasıl olur sormayın..', 'Çatı tenekesinde fakir tıpırtı. Duvar dibinde ıslak kedi kaygılı. Penceresinden duygu aktı şairin. Damlalar düşünce oldu bu gece. Ne eski ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/teneke-ile-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Fatma Öldü! ! !', 've-fatma-oldu-bahri-yildirim-3cw5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onu da kuşlar getirmişti belkide

Ya da leylekler 

Adı da yoktu,kimliği de

Yaşını bile söyleyemezdi,sıkıntıda

Yokluklar içinde bir neferdi,o

Cehaletin göz bebeğinde bir kurban

Ölüm kapısını çaldı aniden

Hiç yaşanmadan bitti herşey

Ve.. Fatma öldü.

Bir kaç damla gözyaşı,ıslar mı toprağını? 

 Bilemem...

Kim okuyacak duasını? ! 

Anlayamam...

Kuşlar mıymış en büyük katil? 

Hadi canım sen de? ! ! ! 

Baksanıza; Cehalet yağıyor gökyüzünden..

17.01.2006   Tv  Haberler. Fatma:.....   Kuş gribinden öldü....', 'Onu da kuşlar getirmişti belkide Ya da leylekler  Adı da yoktu,kimliği de Yaşını bile söyleyemezdi,sıkıntıda Yokluklar içinde bir neferdi,o ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ve-fatma-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biyolojik Şiir.! !', 'biyolojik-siir-h-hikmet-esen-psjm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genetik bilgi aktarımına

Gebe geceler..

Molekül sancılarında,

Kıvranırken hücreler; 

Çekirdek çeperlerinde RNA''lar

De oksileşirler,

Aksileştikçe...

Ve mitoz bölünmelerle

Çoğaldıkça; 

İnfazlar, hüküm yazar

Hücre duvarlarına..

Nasıl sığamıyorsa,

Tohuma kaçmış fesleğenler; 

Bir avuç toprağa

Boğulan kökleriyle,

Saksılarına; 

İsyanlar,

Hücre zarlarına,

Yalnızca,

Varoluş adına...

07/01/1998', 'Genetik bilgi aktarımına Gebe geceler.. Molekül sancılarında, Kıvranırken hücreler;  Çekirdek çeperlerinde RNA''lar De oksileşirler, Aksileşt...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/biyolojik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sarhoşun Elinde Kırılmış Şarap Şişesi Gibiyim', 'bir-sarhosun-elinde-kirilmis-sarap-sisesi-gibiyim-multe-ci-han-0f1jb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah erken kalktım yatağımdan

Cep telefonumda en sevdiğim melodiyle

Güzel bir uyku çekmiş olarak uyandım

Sıyrıldım kabuslarımdan,

Bana işkence gibi gelen yalnızlıktan.

Bir umut var içimde

Kim bilir belki yeniden gelirsin

Seni hala seven bu kalbe...

Güneşin doğuşunu izliyorum balkondan

Şarap şişeleri içinde,

Kırılmış kadehlerin arasından

Yine tutamıyorum kendimi

Hüzünleniyorum sabah sabah

Göz yaşlarım akıyor bir çeşme gibi; 

Ağır yaralar açıyor yüzümde,

Senim kalbimde açtıklarının benzeri...

Hala kurtulamadım senden

Senin hayalinden

Hala kurtulamadım

Geceleri yatağıma yattığımda

Hayalimde seninle yaptığım sohbetlerden

Hala kurtulamadım

Rüyalarımda seni görmekten

O güzel gözlerinle bana yine bakmandan

Ve herşeye yeniden başlamamızdan...

Ne olurdu hala iki yabancı olsak

Ne olurdu birbirimizi hiç tanımasak

Ne olurdu kader bana böyle bir oyun oymamasa

Ne olurdu sorarım sana ve Yüce Yaradana! ! ! 

Güneş ufuktan sıyrıldı giderek yükselmekte

Umutlarım tekrar bitiş çizgisini görmekte

Ufukta umutların doğmuş olduğu yerde

Kalbi yaralı bir çocuk gidiyor derinliklere...

Yine yenik düşüyorum nefsime

Yine düşünüyorum kalbimdeki yarayı açan sevgiliyi

Yine düşünüyorum geçmişi.

Bırakıyorum kılıcımı 

Teslim oluyorum kadere

Güneş doğmuş kimin umrunda! ? ! 

Bu bir umut değil gerçeklerin yüzüme vuruşu

Ve unutmak sağımı solumu! ...', 'Bu sabah erken kalktım yatağımdan Cep telefonumda en sevdiğim melodiyle Güzel bir uyku çekmiş olarak uyandım Sıyrıldım kabuslarımdan, Bana i...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-sarhosun-elinde-kirilmis-sarap-sisesi-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni yıl kedi ve mart', 'yeni-yil-kedi-ve-mart-kemal-eyupoglu-kyj45', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yaramaz kedi yavrusuydu,yeni yıl

			Ve bir yumaktı onun için

			Bir önceki  yıl.

			Oynarken,çözüp tüketirken

			Ve etrafa dağıtırken günleri

			Haftaları,ayları

			Aslında kendiside bilmiyordu

			Bir yıl daha yaşlandığını.

			Kim bilir

			Belki de onun istediği

			Kışları sert

			Her günü dert olsa da 

			Gelmesiydi bir an önce

			Mart ayının.', 'Bir yaramaz kedi yavrusuydu,yeni yıl 			Ve bir yumaktı onun için 			Bir önceki  yıl. 			Oynarken,çözüp tüketirken 			Ve etrafa dağıtırken gü...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeni-yil-kedi-ve-mart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarda', 'yollarda-aziz-akgun-iehfz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yapayalnız yürümek de var

Bu esrarlı yollarda

-Dikenlere bata bata ayaklarımız-

Belli belirsiz ışıklar yanıp söner

Çok uzaklarda,

Yönelir ışığa bir garip umutla

Hızlanır karanlıklarda adımlarımız

……………….

Sonsuzluk gibidir karanlığın yolları

Ne yürümekle biter

Ne ışıklar bir adım yaklaşır sana

Açılmış karanlıkta yokluğun kolları

Sabırla seni bekler

Yolun sonu budur anlasana…', 'Yapayalnız yürümek de var Bu esrarlı yollarda -Dikenlere bata bata ayaklarımız- Belli belirsiz ışıklar yanıp söner Çok uzaklarda, Yönelir ış...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yollarda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-volkan-i-ncel-gc3pb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'üzerime çöktü 

yeni bir yaşın gerginliği

sustum ondan

hangi yaşı yaşıyordum

bilge olmanın yaşınımı

yoksa yaşamış olmanın yaşınımı

utanıyorum kendimden

yoksa

korkuyormuyum yaşlanmaktan

boşver diyorum

geldiysem dünyaya

yaşamalıyım

hadi diyorum gönül

yaşa da bitsin

bari sancı olmasın gönlüme', 'üzerime çöktü  yeni bir yaşın gerginliği sustum ondan hangi yaşı yaşıyordum bilge olmanın yaşınımı yoksa yaşamış olmanın yaşınımı utanıyorum...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sustum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz', 'sahipsiz-kemal-eyupoglu-kjjdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çomak soktun gönlümdeki  kovana

 			Arı gitti,balı kaldı sahipsiz

			Kurudu kökleri, devrildi çınar

			Gövde gitti, dalı kaldı sahipsiz.

			Değiştirdin yatağını derenin

			Kumu gitti,çakıl kaldı sahipsiz

			Bir zamanlar her şeyim yerindeydi

			Kafa gitti,akıl kaldı sahipsiz.

			Süpürdün rüzgarla doruklarımı

			Karı gitti,buzu kaldı sahipsiz

			Kaynaya kaynaya,yok oldu aşım

			Tadı gitti,tuzu kaldı sahipsiz.

			Yolumu kapladın bin bir engelle

			Yolcu bitti,yollar kaldı sahipsiz

			Sevmesini bilen,gönül tükendi

			Sevda gitti,kollar kaldı sahipsiz.

			Eski sevgileri tüketti zaman

			Mecnun gitti,çölü kaldı sahipsiz

			Bir sevdayı hapsetmişler kafese

			Bülbül gitti,gülü kaldı sahipsiz.

			Gözünü kuruttun soğuk pınarın

			Suyu gitti,gözü kaldı sahipsiz

			Eskiden yaşayan bir şair vardı

			Kendi gitti,sözü kaldı sahipsiz.', 'Çomak soktun gönlümdeki  kovana  			Arı gitti,balı kaldı sahipsiz 			Kurudu kökleri, devrildi çınar 			Gövde gitti, dalı kaldı sahipsiz. 			...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sahipsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zat-ı muhterem', 'zat-i-muhterem-kemal-eyupoglu-k1rm3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karda yürür izini belli etmezdi

				Zat-ı Muhterem

				Yetmiş yıllık hayatının sonunda

				Bir dönüp baktığında geriye

				Hiçbir iz bırakmadığını görmüştü

				Yürüdüğü yollarda! ..', 'Karda yürür izini belli etmezdi 				Zat-ı Muhterem 				Yetmiş yıllık hayatının sonunda 				Bir dönüp baktığında geriye 				Hiçbir iz bırakma...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zat-i-muhterem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar beyazım', 'kar-beyazim-kemal-eyupoglu-kweew', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umut dediğimiz nedir ki? 

			Kar beyazım,

			Kar beyazı  olmalı umutların.

			Leke olmamalı ve kızıllıkta olmamalı

			Ve sararmamalı umutların.

			Umut dünyası olsa da  yaşadığımız hayat

			Umutlara düşmemeli

			Tükenmez hüzünlerin gölgesi.

			Hüzün,göçmen kuş olmamalı

			Ve gidip gidip

			Geri dönmemeli yuvasına.

			Hüzün,harem kurmamalı içimizde

			Ve yavrulayıp çoğalmamalı hüzün.

			Hüzün,ara sıra misafir olmalı

			Kabul edersek gelmeli

			Kovarsak, başını eğmeli ve gitmeli.

			İnsanlar sevse de birbirlerini

			Herkes kendi yoluna gitmeli

			Ve sende kendi yolunda yürümelisin kar beyazım.

			Hasretin gözü yollarda,

			Hüznün gözü bende,

			Hüzünsüz yürüsem de yolumda

			Başım omuz üstünde

			Aklım,ayak parmaklarımın ucunda

			Ve sende.', 'Umut dediğimiz nedir ki?  			Kar beyazım, 			Kar beyazı  olmalı umutların. 			Leke olmamalı ve kızıllıkta olmamalı 			Ve sararmamalı umutlar...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kar-beyazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Umut', 'bitmeyen-umut-saadet-ekinci-ic97f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne umutla başlamıştım,

Yıllar,yollar yıpratamadı

Umutlarımı.

Kimseler caydıramadı

Hayalimden,bekleyişimden.

Öylesine bekledim...bekledim.

Bekleyiş boşa değildi,

Verilmiş bir söz

Sunulmuş bir umut tomurcuğu vardı.

Mutlaka bir gün gelecek,

Gelecekti.

Yıllar geçti.

Sanki günlerin herbiri bir yıldı.

Ama  ben ilk günkü gibi,

Umutla bekledim.

Haklıydım,bir gün o gündü...

Geldi.

Oldu olacak diye beklerken

Olmadan bitti niye? 

Çok büyütmüşüm gözümde,

Süslemişim hayalimde.

Gelen oydu ama,

Beklediğim o değildi....

(17.01.2006)    İstanbul  Saadet Ekinci', 'Ne umutla başlamıştım, Yıllar,yollar yıpratamadı Umutlarımı. Kimseler caydıramadı Hayalimden,bekleyişimden. Öylesine bekledim...bekledim. Be...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ekinci']::text[], 8.5, '{"poet":"Saadet Ekinci","poet_slug":"saadet-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bitmeyen-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erat Geldiğinde Anladım', 'erat-geldiginde-anladim-multe-ci-han-9yx9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek zordu; 

kelepçe vurulan bu kalbe.

Neydi önemli olan bilmiyordum

Seni hissetmeden önce

Sonbaharda dökülen yapraktı hayatım

-önemsiz ve kuru-

Rüzgarlardı yönümü belirleyen

Son durağımdı, bir şubat dolusu...

Güneş neydi? ...

Havada asılı duran o nesne miydi

Yoksa ellerin mi

Bu aklıma düştüğünde anladım seni sevdiğimi.

İlk defa kavramıştım mehtabın parlaklığını

İlk defa kavramıştım yağmurun güzelliğini

-fırtınanın özelliğini-

Kalbim bilmediğim bir sıcaklığa kavuşmuştu

Her gördüğümde seni daha da artıyor

Sensiz soğuyordu.

Anlamıyordum bu neydi

 değer vermiyordum daha o zamanlarda

 değer vermiyordum hayatıma

Şimdi anlıyorum

Herşey sana benziyor gittiğinden beri

O kalbimdeki aşktı değil mi? ...

Şimdi anlıyorum

Bir gün geliyor erat

götürüyor seni

bağlıyor ellerimi

Bir gün geliyor erat

Alıp götürüyor kalbimi

Sanki ''''tek suçum sevmekmiş'''' gibi', 'Sevmek zordu;  kelepçe vurulan bu kalbe. Neydi önemli olan bilmiyordum Seni hissetmeden önce Sonbaharda dökülen yapraktı hayatım -önemsiz ve...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/erat-geldiginde-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir senden başka', 'bir-senden-baska-kemal-eyupoglu-hq8dg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nadasa bırakılan,bir çatlamış topraktı

Filizlendiğim mekan

Ve başımı kaldırdığımda gök yüzüne

Etrafımda kimseyi göremediğimde

Korktuğumu,tir tir titrediğimi

Bir dost ses,bir deli sevda aradığımı

Kimseler fark etmemişti

Kimseler fark etmemişti yalnızlığımı

Bir senden başka.

Gündüzler örtünürken gecelerimi

Kimseler farkına varamamıştı çıplaklığımın

Boşluktan çekip çıkardığım ellerim

Örtmeye çalışırken avdet yerlerimi

Ve ben yaşarken utanmışlığımı

Yumarak gözlerimi

Saklamaya çalışırken yüzümün kızarıklığını

Kimseler fark etmemişti beni

Bir senden başka.

Yeryüzü ile ufkun kesiştiği noktada

Bulut bulut göklere uzandığımı

Cisil cisil ağladığımı sen fark ettin

Gökkuşağından kurduğum köprüler üzerinde

Umuda yürüdüğümü sen fark ettin

Bu günden vazgeçtiğimi

Yarınlarımı ise

Hazan rüzgarlarına emanet ettiğimi

Yine sen fark ettin.

Lakin

Seninde beyhude oldu fark edişlerin

Ne örtebildin çıplaklığımı

Ne giderebildin utanmışlığımı

Ne de çare bulabildin sipariş veremediğim yarınlarıma

Kimseler fark etmedi

Fark edişlerinin beyhude olduğunu

Bir benden başka.', 'Nadasa bırakılan,bir çatlamış topraktı Filizlendiğim mekan Ve başımı kaldırdığımda gök yüzüne Etrafımda kimseyi göremediğimde Korktuğumu,tir...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-senden-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanacak Bu Millet', 'uyanacak-bu-millet-mehmet-ayhan-gunaydin-2anpg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UYANACAK BU MİLLET

Uyanacak bu millet,

Uyanıp, gerçeği görecek.

Uyanınca bu millet,

Diriliş de gerçekleşecek.

Dirilecek bu Millet,

Mutlak yeniden dirilecek.

Dirilince bu Millet,

İnsanlık da gülecek.

Tarihte hep böyleydi,

Ne zaman ki  kararmıştı.

Atalarımdı ışık, 

Onlar aydınlatmıştı.

Ne zaman dünya,

Düştüyse nara.

Onlardı koşan,

Yetişen imdada.

Ve, Dünya düşünce dara,

Yetişmişti Milletim.

Çıkıp, dik durup karşısına, 

Elinden, kurtarmıştı zalimin.

Dünya ki…

Biz hükmederken,

Huzurlu idi.

Adildi,

Güzeldi.

Dünya karardı yine,

Yine narda, yine darda.

Sıra bizdedir yeni nesil,

Yetişelim imdada.

M. Ayhan Günaydın.

     4 Ocak 2005 

         Ankara', 'UYANACAK BU MİLLET Uyanacak bu millet, Uyanıp, gerçeği görecek. Uyanınca bu millet, Diriliş de gerçekleşecek. Dirilecek bu Millet, Mutlak ye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/uyanacak-bu-millet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil Bilmez Sevda', 'dil-bilmez-sevda-atilla-guler-70q5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'doruklardan

kopup geldi

çığ bozması karanlık

ve soğuk

gerisi koca bir kandırmaca

ikilemlerle kol kola

sen yoksun 

sahildeki ayak izlerinde

okyanusun lacivert dalgalarında yitirilen sözler

aç martıların gagalarında

çığlık çığlığa

beyazdı köpükleri dalgaların

kumsala vurdukça

bir şarkı vardı içinde

dinmeyen

eşlik ederdi mavi

masum mırıltılarla

lal olmuş şarkıcılarda dinle artık kayıp notaları

masanın altında nankör bir kara kedi

eski bir sırnaşıklık kopup gelir anılardan

zarları atan kim ki gelen hep yek

benden yana

…ya işime yararsa

salya sümük ağlamakta gecelerin yıldızları

ellerine düşen her damlada

rengarenk

ıslak sevda

vişne çürüğü dudaklardan süzülür sessizlik

bir sığıntı yalnızlık 

direnişe geçen yürekte 

dile gelir aşk

…büyüler

anlaşılmasa da

vurur…hiç yaşanmamış gibi

bir daha

bir daha

dil bilmez sevda

kendi dilinden başka', 'doruklardan kopup geldi çığ bozması karanlık ve soğuk gerisi koca bir kandırmaca ikilemlerle kol kola sen yoksun  sahildeki ayak izlerinde o...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dil-bilmez-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lazım', 'lazim-i-brahim-halil-demir-u9guh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Halimden,ehvalimden anlayabilmek için,

Yaşadıklarımı senin de yaşaman lazım.

Kimin dost kimin düşman olduğunu bilmek için,

Çok sıkıntılı geceleri uykusuz geçirmen lazım.

Sıcak yaz gecelerinde,yıldızları saymadan uyumak için,

Gün boyunca güneşin altında, çok kabala çalışman lazım.

Bir sevda uğruna yadellere muhacir olmak için,

Sevda sürmesini çekmiş gözlerle çok bakışman lazım.

Yar kokan gül bahçelerinde,acıklı bir türkü bestelemek için,

Aşkı,sevdayı,sevmeyi,sevilmeyi doyasıya yaşaman lazım.

Sevda hastalığından,şifa bulup iyileşmek için,

Ferhat,Kerem,Tahir gibilerle tanışıp dost olman lazım.

Cehennem ateşinden korkmuyorum diyebilmek için,

Bu fani dünyada sevilmeden sevmenin ateşiyle yanman lazım.

Ahirette cenneti kazanabilmek için,

Dünya nimetlerinin çoğunu elinin tersiyle itmen lazım.

Zifiri karanlıklardan zevk almak için,

Bir vefasızın yolunu beklemekten gözlerinin ferini kaybetmen lazım.

Tam anlamıyla yürekten gülebilmek için,

Aşkın hançeriyle sinsice arkadan vurulmaman lazım.

Geçmek bilmeyen zamanın sıkıntısını anlamak için,

Akrebi,yelkovanı durmuş sevda saatini koluna takman lazım.

Yedi nüfuslu bir ailenin geçim sıkıntısını idrak etmek için,

Çok helal çalışıp,çok alın teri dökmen lazım.

16/01/2006

.', 'Halimden,ehvalimden anlayabilmek için, Yaşadıklarımı senin de yaşaman lazım. Kimin dost kimin düşman olduğunu bilmek için, Çok sıkıntılı gec...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/lazim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köprü ve Su', 'kopru-ve-su-ahmet-zekai-yildiz-vos2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zülfikar dilli yılana benziyor,

Dönüp duran şu dağ yolları.

Ne zaman yola çıksam,

Yürekli ellerimle direşen

Hayta ayaklarımın it dalaşıydı zaman.

Kapalı gözlerimde her an,

Mezar kaçkını bir heyula.

İsrafil düdüğüne kilitli kulaklarım.

Gök kubbe altında ve onca insan içinde..

Bir başıma hiçliğe haykıran,

Kadın çığlığı korkularım.

Ve her köprü başında,

Deli Dumrul edasıyla dikilecekse karşıma,

Eli kılıçlı Azrail..

Ozaman

O köprüler altından akan sular gibi,

Özgür ve çılgın aksın hayatım..', 'Zülfikar dilli yılana benziyor, Dönüp duran şu dağ yolları. Ne zaman yola çıksam, Yürekli ellerimle direşen Hayta ayaklarımın it dalaşıydı z...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kopru-ve-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan, Ben ve Hücrem', 'gardiyan-ben-ve-hucrem-multe-ci-han-b6awj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anılarım tekrar canlanıyor

-hayalimde-

Kulağımda en sevdiğim şarkı

Her sözüyle beni anlatan.

Elimde kalemim

Mısralarıma aşkımı akıtan

Bu hücre artık banim değil

Senin siluetinle süslü

Ben ne kadar yalansam burada

Sen de o kadar benimlesin 

rüyalarımda

Bekliyorum; 

Sürpriz af kararını

Bekliyorum; 

Gardiyanın ''''seni bıraktım'''' diye bağırmasını

prangalarımı çıkarmasını

Gözlerimden dökülen son damla yaş

Mısralarımı süslüyor

Mürekkebim dağılıyor üzerinde

_kalbim gibi_

Yeni yollar açıyor kendine

Bitiriyor elindeki son kadehi

İsyan ediyor bilinçsizce

Bana değil, kağıda değil aslında isyanı

İsyanı gittiğin o geceye

İsyanı giderken bıraktığın ayak izlerine

İsyanı hiç gelmeyecek af kararını beklemesine

- ümitsizce ve sessizce -', 'Anılarım tekrar canlanıyor -hayalimde- Kulağımda en sevdiğim şarkı Her sözüyle beni anlatan. Elimde kalemim Mısralarıma aşkımı akıtan Bu hüc...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gardiyan-ben-ve-hucrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum&Bilmiyorum', 'biliyorum-bilmiyorum-ahmet-zekai-yildiz-d0ov3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum.

Gelmeyeceksin.

Yalvarsam da,

Seviyorum,

Seni çok özledim desem de boşuna.

Hı!  ıh! 

Gelmeyeceksin.

Gittiğin nasıl bir yer ki? 

Giden çok,

Gelen yok.

Madem öyle; 

Ben gelsem diyorum.

Bulabilir miyim seni? 

Hı...? 

Bilmiyorum..', 'Biliyorum. Gelmeyeceksin. Yalvarsam da, Seviyorum, Seni çok özledim desem de boşuna. Hı!  ıh!  Gelmeyeceksin. Gittiğin nasıl bir yer ki?  Gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biliyorum-bilmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik', 'eksik-ahmet-zekai-yildiz-f05ou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevenlerim yok şimdi.

Sevdiklerim çok uzakta.

Öyle uzak ki dünya! .

Soğuk ışıklı mavi ben oldum.

Umudun bittiği yerde,

Dama düşen mahpusun,

Sabahsız ilk gecesiyim.. 

.

Yarısı tamam, anladım..

Diğer yarısı olmayan

Bir kırık leblebiydi, bitti.

Yarım kaldı hayatım..', 'Sevenlerim yok şimdi. Sevdiklerim çok uzakta. Öyle uzak ki dünya! . Soğuk ışıklı mavi ben oldum. Umudun bittiği yerde, Dama düşen mahpusun, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eksik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mustafa-oz-go2ue', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alem-i ervahta,aşkla yoğruldum

Şahadet alemi,ayna dediler

Aşkla vücut buldum.aşkla doğruldum

Elem-i aşk ile,kayna dediler

Alemler içinde.çok sırlar gizli

Her insan bir alem,bir sır dediler

Sırların içinde,asırlar gizli

Aşk ile örtülür,kusur dediler

Alem-i lahüt''da zaman yok olur

Kâinat aşk ile,döner dediler

Aşk ile tabut''da mekan yok olur

Cehennem aşk ile,söner dediler', 'Alem-i ervahta,aşkla yoğruldum Şahadet alemi,ayna dediler Aşkla vücut buldum.aşkla doğruldum Elem-i aşk ile,kayna dediler Alemler içinde.çok...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Öz']::text[], 8.5, '{"poet":"Mustafa Öz","poet_slug":"mustafa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-517-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamak', 'kacamak-ahmet-zekai-yildiz-scpwd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit ellili yaşların bir yaz akşamı.

Yer aynı yer,

Köyümüzün harmanı..

Ve biz,

Saklambaç oynayan çocuklar olmalıyız.

Toz, pasak terimizle

Helva karmalı..

Koşuşturmalardan kızaran yüzümüzde.

Rastlantı bu ya:

Yine sen gelmelisin yanıma.

Saklandığımız yerde,

Ebelenme korkusuyla beklerken; 

Eskisi gibi uyuyakalmamalıyız ama..

Ve gün ağarmadan kaçmalıyız.

Tüm anılarımızdan.

Ait olduğumuz yerlere..', 'Vakit ellili yaşların bir yaz akşamı. Yer aynı yer, Köyümüzün harmanı.. Ve biz, Saklambaç oynayan çocuklar olmalıyız. Toz, pasak terimizle H...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kacamak-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Çay Bahçesinde', 'sahilde-cay-bahcesinde-mehmet-akif-tiryaki-331t9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birbirimizi seven iki sevgiliyiz biz,

Tek aşkta birleşti yanan kalplerimiz,

Sahilde çay bahçesinde oturduk el ele,

Ben senin yanında sen Kaf Dağı''nın tepesinde.

Oturduk el ele,

Sahilde çay bahçesinde,

Islak yakamoz sakladım ceplerime,

Sana vermek için.

Arta kalan neydi geçen günlerden,

Hayat bir masaldı, sen se Kaf Dağı''nın tepesinde

Yudum yudum içtim seni,

Sahilde çay bahçesinde.

Alma gözlerini gözlerimden,

Bırak onları sensiz,

Bir aşkın hecesinde, sisli bir akşam esintisinde,

Kaf Dağı''nın tepesinde.', 'Birbirimizi seven iki sevgiliyiz biz, Tek aşkta birleşti yanan kalplerimiz, Sahilde çay bahçesinde oturduk el ele, Ben senin yanında sen Kaf...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahilde-cay-bahcesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı', 'olmadi-kemal-eyupoglu-lptuo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yolum yol oldu,dağ başlarında

		Ne kendimi buldum,gözyaşlarında

		Sessiz şehirlerin varoşlarında

		Beni benden başka,bilen olmadı.

		Ne elim el oldu,gurbet elinde

		Ne dilim dil oldu seher yelinde

		Dünya dedikleri, yalan belinde

		Beni benden başka seven olmadı.

		Güç,kuvvet kalmadı,tutmaz bileğim

		Sanki kan çanağı,oldu yüreğim

		Menzile varmadı hiçbir dileğim

		Beni benden başka bilen olmadı

		

		Ne seni alacak,benden bu ölüm

		Ne derde çileye yetecek gönlüm

		Has bahçeden uzak,bir gonca gülüm

		Beni benden başka deren olmadı.

		Bir garip şairim,bilinmez adım

		Kendimi tükettim seni akladım

		Ağladım döktüğüm yaşı sakladım

		Beni benden başka duyan olmadı.', 'Ne yolum yol oldu,dağ başlarında 		Ne kendimi buldum,gözyaşlarında 		Sessiz şehirlerin varoşlarında 		Beni benden başka,bilen olmadı. 		Ne e...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmadi-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor Yüreğim.', 'agliyor-yuregim-i-shak-ozlu-v2sw1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzeller gördüm kimi leyla kimi aslı bakar,

Yıldız gözleri sınır tanımaz gönüle akar.

Her bir bakış gizemince ruhumda ateş yakar,

Ama hiç biride SEN gibi yürekten bakmıyor.

Gün oldu hafta bir lokma ekmeğe muhtaç kaldım,

Evsiz kaldım,dosta hasret kor ateşlerde yandım.

Umut bitti bitecek utanmadım umut çaldım,

Piştim acılarla özlemin gibi can yakmıyor.

Her yeni şafak sevdamın onuru ile yüce,

Sürer gün boyu adın dilimde sonsuz bir hece.

Döner semalara yükselir aşkımız her gece,

Ağlıyor yüreğim sanma ki göz yaşım akmıyor.', 'Güzeller gördüm kimi leyla kimi aslı bakar, Yıldız gözleri sınır tanımaz gönüle akar. Her bir bakış gizemince ruhumda ateş yakar, Ama hiç bi...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agliyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen-2', 'herseye-ragmen-2-eyup-gok-tb5iv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçeği örselemeden, soldurmadan getireceğim

Küf kokan, bütün o düşüncelere rağmen

Doğasından ayırmadan, dalında sunacağım

Herzaman bana yoldaş gecelere rağmen', 'Çiçeği örselemeden, soldurmadan getireceğim Küf kokan, bütün o düşüncelere rağmen Doğasından ayırmadan, dalında sunacağım Herzaman bana yold...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/herseye-ragmen-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-afsin-ersoy-27d77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN…

	

Bir bakışın yeter,hayatın  hayatlanmasına

Bir tebessümün yeter,dünyanın tüm güzelliklerine

Bir sen yetersin,senin gayrının hepsine 

Bir tek sen değersin, görmek için ölmeğe…

Sen olmayınca hayaller nursuz, akıllar bitap 

sensizlikten sızlayan  gönüller paslı,

Sen olmayınca akıl,hayal,gönül bir hiç…

Sensiz yaşamak, yalnızca… aldanmak….', 'SEN… 	 Bir bakışın yeter,hayatın  hayatlanmasına Bir tebessümün yeter,dünyanın tüm güzelliklerine Bir sen yetersin,senin gayrının hepsine  B...', ARRAY['Türk Edebiyatı','Şiir','Afşin Ersoy']::text[], 8.5, '{"poet":"Afşin Ersoy","poet_slug":"afsin-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-737-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Gece', 'guzel-bir-gece-multe-ci-han-x98pv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor pencereme

Dışarı çıkıyorum yağmurda ıslanmak için

Her zaman sevmişimdir yağmurda ıslanmayı

Belki bu yağmurun saflığındandır

Belki de seni bana hatırlattığından

Yürüyorum ağaçlarla kaplı dar sokaklarda

Yürüyorum ayın belli belirsiz aydınlattığı bu ıslak patikada

Yürüyorum ıslana ıslana

Yürüdükçe atıyorun fani dünyanın gereksiz düşüncelerini

Yürüdükçe daha belirgin hale getiriyorum hayalini

Sensiz yürünmüyor bu dar sokaklarda

Sensiz olmuyor sahile vuran dalga

Sensiz yaşamıyor yeni filizlenen papatya

Yanımdasın artık etinle kemiğinle

Bana bakıyorsun o güzel gözlerinle

Ve yine yürüyoruz bu sessiz patikada 

EL ELE

Yine heyecanlanıyorum

Elini tutmak her zaman heyecanlandırdı beni

Vücudunun ısısını hissetmek

İçimde rüzgarlar estirdi her zaman

Ama sıcaktı o rüzgarlar

Senin sevginle hayat buldular

Senin sevginle hayatta kalmayı başardılar

Kalbim senin sevginle, senin aşkınla doluyor

Kelimeler zor dökülüyor artık ağzımdan

Düşünemiyorum heyecandan

İstiyorum ki anla gözlerimden

Sensiz günlerimin geçmediğini

Sensiz ben olamayacağını

Ve seni ''''sonsuza'''' dek seveceğimi', 'Yağmur yağıyor pencereme Dışarı çıkıyorum yağmurda ıslanmak için Her zaman sevmişimdir yağmurda ıslanmayı Belki bu yağmurun saflığındandır B...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/guzel-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-multe-ci-han-i7p7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer görmek istemediklerimi de görseydim

Seni bu kadar sevemezdim

Gözlerini göremezsem 

Kalbinin sesini duyamam

Kalbim kalemim kadar güçlü olsaydı

Hayalin hala yanımda olmazdı', 'Eğer görmek istemediklerimi de görseydim Seni bu kadar sevemezdim Gözlerini göremezsem  Kalbinin sesini duyamam Kalbim kalemim kadar güçlü o...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgiliye-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaşam Edası', 'bir-yasam-edasi-eyup-gok-bhq40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamak istiyorum artık dünyayı

Ancak, sormak istediğim soruları

Hala söyleyemiyorsam sonrayı

Gördüğümdendir Heyhat! umutsuz sonları

Bunlar varmıydı zaten, yaşanmış dünyada

Pişmanlık, zalimlik, kölelik ve hürriyet

Yasaklar varsa eğer yaşanacaklarda

Ey tarih; yeniden ve yine tekerrür et.', 'Anlamak istiyorum artık dünyayı Ancak, sormak istediğim soruları Hala söyleyemiyorsam sonrayı Gördüğümdendir Heyhat! umutsuz sonları Bunlar ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-yasam-edasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurallarımız', 'kurallarimiz-mehmet-akif-tiryaki-hycbw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık hayatın labirentlerinde maden işçisiyiz,

Her birimizin yolları farklı, platform aynı

Havasız tünellerde ışık yok,

Uzayan koridorlar karanlık, siyah,

Kulaklarımda adım sesleri, tempolu.

Gündüzler karanlık, burası tozlu

Kurulmuş robotlar aşağı yukarı gider gelir,

Çıkış kapılarında bir müddet dinlenilir.

Çalışmalar tekrar edilir durur,

Karanlık kimi zaman da içe vurur.

Karanlık hayatın labirentlerinde maden işçisiyiz,

Desek de yarin gerdanında inci tanesiyiz,

Havasız tünellerde gider geliriz.

Toz duman kısıldı çıkmaz sesimiz,

Nefesler soğuk, insanlar isimsiz,

Kurallar kesin, emirleri verenler erdemsiz.

Soru sorulmaz burada, ihtiyaç bildirilmez,

Kurallara uyulur, asla eleştirilmez.', 'Karanlık hayatın labirentlerinde maden işçisiyiz, Her birimizin yolları farklı, platform aynı Havasız tünellerde ışık yok, Uzayan koridorlar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kurallarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bana Kalan', 'senden-bana-kalan-ali-gencay-q7un8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düştü rahminden birkaç damla kan

Ölen can değildi, aşktı sızıp kanayan

Üşüdü elleri, soğuktu ölümü çağıran

Bakmadı gözlerime gitti, sanki yalan

Değersiz gecelerde zevkmiş yaşanan

Tenimde ateşti, içimde kordu yanan

Uzaklaştı sıcak mevsim, şimdi hazan

Bir avuç kupkuru yaprak aşka kalan

Ne varsa sen, beni adam eden sevdan

Ayaklar altına aldığım gurur, kavgan', 'Düştü rahminden birkaç damla kan Ölen can değildi, aşktı sızıp kanayan Üşüdü elleri, soğuktu ölümü çağıran Bakmadı gözlerime gitti, sanki ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senden-bana-kalan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Tavuk-Çilli Horoz', 'sari-tavuk-cilli-horoz-muharrem-cetinkaya-nx2bv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düğün değil bayram değil

bir yaban kaz_ı öptü bizim sarı tavuğu

kustu ağzına zehiri

o da bilmez ya öpüşmeyi

yuttu…….

hastalanıverdi bir akşam üstü

aman dedi 

bulaşmasın bu meret 

benim çilli horozuma

akşam yatmadı yanına

çilli horoz ne bilsin

yaban kaz_ı_nın öpücüğünü

o sarı tavuğa küstü…

 ve ötmeye başladığında gün ışırken

bi-de ne görsün

sarı tavuk yüz-üstü……! 

anlamadı çilli

nerden anlasın

nerden belli …..? ? ? ?', 'düğün değil bayram değil bir yaban kaz_ı öptü bizim sarı tavuğu kustu ağzına zehiri o da bilmez ya öpüşmeyi yuttu……. hastalanıverdi bir akşa...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sari-tavuk-cilli-horoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DoğalGaz ık (!)', 'dogalgaz-ik-muharrem-cetinkaya-gw14g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'doğaldır bu bize verilen gaz

çook yol alırız

biz bu gazla

aman oğlum fazla basma

yazık

araba bizim amma

yanan doğal-gaz_ık! ! !', 'doğaldır bu bize verilen gaz çook yol alırız biz bu gazla aman oğlum fazla basma yazık araba bizim amma yanan doğal-gaz_ık! ! !...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dogalgaz-ik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Nasıl Bekle Derim', 'sana-nasil-bekle-derim-i-brahim-dikmen-2-ku6xm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayağım da prangalar

Ellerimde kelepçeler

Sarılamam yar boynuna

İzin vermez zaptiyeler

Mahkumun gece örtüsü

Gündüzler ömür törpüsü

Duyulmaz bir ezan sesi

Sana nasıl bekle derim

Dilimde hasret türküsü

Unutulmaz aşk öyküsü

Aklıma düşse gözlerin

Sana nasıl bekle derim

Mapusta geçmez günler

Kuşatır dikenli teller

Yaslanamam yar omzuna

Geçit vermez zaptiyeler

17/01/2006', 'Ayağım da prangalar Ellerimde kelepçeler Sarılamam yar boynuna İzin vermez zaptiyeler Mahkumun gece örtüsü Gündüzler ömür törpüsü Duyulmaz b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aklima-dustu-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dünyam', 'benim-dunyam-muharrem-cetinkaya-1cvae', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yağmurlar yağdırırım kurak gönlüme

sağnak sağnak

ıslanırım

mavi gecelerde

kimsesiz bir sahilde

ne gören olur

ne duyan…! 

.

ve ne yangınlar söndürürüm

okyanuslarımda

denizlerim kabarır

alev mi dayanır  bu med-cezire

sevda mı

kalırsa geriye

sönmeyen 

sadece bir kor ateş kalır

yüreğimin ta derinlerinde

.

ormanlarımı büyütürüm

çeşit çeşit ağaçlar

fikirlerim gibi filizlenir

kardeşçe yaşatırım

tüm çelişkilerimi

kurtlarım dolanır özgürce

ceylanlar koşuşur 

bilirim çekemezler beni

bir gölge gibi izler aslanlarım

hain çakalları…! 

.

hayaller kurarım anılarımdan

sevda evlerinde

en sultan köşelerine oturturum

tüm sevdiklerimi

bir eli yağda bir eli balda

ve

oturur soğan-ekmek yerim

gözlerim yaşararak….! 

.

gün gelir kral ben olurum

hükmederim

tüm dünyama

asarım-keserim

taş üstünde taş bırakmam

baş üstünde baş

ama bir şeye kıyamam

yetmez gücüm

sensizliğe…! 

.

gün olur mahkum olurum

gönül gardiyanlarına

ellerimde kelepçe-ayaklarımda zircir

bir fındık kabuğunda gizlenir

ve bir sincabın elinden firar ederim

özgürlüğe…! 

.

İşte yaşam budur

Bir gün kral

Bir gün köle

damarda kan gibi can verir yaşatırım

yaşam gibi

can verir kanatırım

samanlığa saklarım bir iğnenin içinde

tüm gizlerimi

ve aratırım

gözü bağlı gönlüme …!', 'yağmurlar yağdırırım kurak gönlüme sağnak sağnak ıslanırım mavi gecelerde kimsesiz bir sahilde ne gören olur ne duyan…!  . ve ne yangınlar s...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/benim-dunyam-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-muharrem-cetinkaya-hn3aw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benim sanırdım gökyüzünü

özgürce uçarım

sınırsız

gökler benim! 

ne bilirdim ki

gökyüzünün bir serçenin

bir kanadını bile taşıyamadığını

.

şimdi kanadı kırık bir uçurtmayım

uçmak 

havalanmak bir yana

mahzende bir duvarda asılı kaldı gençliğim

gün_yüzü bile görmez

yorgun tenim

ve bir yüzüğün taşına  sakladım

al sevdiceğim

koynunda  sakla

bu benim göklere bile sığmayan özgürlüğüm…!', 'benim sanırdım gökyüzünü özgürce uçarım sınırsız gökler benim!  ne bilirdim ki gökyüzünün bir serçenin bir kanadını bile taşıyamadığını . şi...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mahkum-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Bunu Bilseydin', 'keske-bunu-bilseydin-yusuf-onder-bahceci-c4tq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklım kaldı gözlerinde,

Seni sevdim sözlerinde,

Benim sevgim yüreğimde,

Keşke bunu bilseydin....', 'Aklım kaldı gözlerinde, Seni sevdim sözlerinde, Benim sevgim yüreğimde, Keşke bunu bilseydin.......', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/keske-bunu-bilseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretin Gölgesi', 'cesaretin-golgesi-eyup-gok-dduf0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden haram olsun sana

Bu yürekle yaşamak

Bak parlıyor serhad

Güneşin habercisi, sabahın

Bir tek doğru var ki

Anlatır sana tüm vaktiyle

İlk değilsin ki sen

Heyhat! sonda olmayacaksın

Lakin hayatın manasını

Bulacaksın dinle mutlaka

Dudakların nasıl su isterse

Alev alev yanan yüreklerde

Birzaman ola ki

Sen varsın dünyada

Ve cesaretin gölgesi

Bir de huzurun sesi

Sabahın ezanıyla uyanırsın

Tüm cihan uyanır 

Asıl uyumak haram olur

Lakin iki dünya varsa 

Cesur ol, doğru ol

Kendine hakim, adil ol

Gözyaşların kurumadıysa eğer

Önce insan 

Sonra baba ol.', 'Neden haram olsun sana Bu yürekle yaşamak Bak parlıyor serhad Güneşin habercisi, sabahın Bir tek doğru var ki Anlatır sana tüm vaktiyle İlk ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cesaretin-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti Dedi', 'bitti-dedi-onur-balci-d10mu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O benim aşkımdı, sadece benim 

Ondan başka kimseyi sevmedim

Dünyaya bir daha gelsem yine onu severdim

Ama kavuşamadık BİTTİ DEDİ

Kalpler bir oluncada aşk bitiyormuş 

Benim gibi oda beni seviyormuş

Mantık duyguların önünde geliyormuş

İmkansız zannetti; sadece BİTTİ DEDİ

Bu kadar kolaymıydı bir aşkın bitmesi

Yazık değilmiydi kalbe devamlı acı çekmesi

Ben istiyordum bu aşkın bir ömür boyu sürmesi

Ve o aşk benimle ölecek, ama o BiTTİ DEDİ', 'O benim aşkımdı, sadece benim  Ondan başka kimseyi sevmedim Dünyaya bir daha gelsem yine onu severdim Ama kavuşamadık BİTTİ DEDİ Kalpler bir...', ARRAY['Türk Edebiyatı','Şiir','Onur Balcı']::text[], 8.5, '{"poet":"Onur Balcı","poet_slug":"onur-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitti-dedi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
